INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-1', '系安全带，前排后排都系', '为什么系安全带，前排后排都系？', '坐前排系上安全带，出车祸时被撞死的概率大约降一半。坐轻型卡车前排的降六成。美国 2022 年死在车里的人，能查到系没系带的，有一半没系。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-2', '骑摩托车、电动自行车戴头盔并扣好', '为什么骑摩托车、电动自行车戴头盔并扣好？', '戴头盔并且把扣带扣好，摩托车骑手出事时死亡的概率低约四成。头部受伤低约七成。扣带要系紧，松松垮垮挂在头上不算戴。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-3', '装烟雾报警器；冬天在室内烧煤、用燃气取暖的再装一氧化碳报警器', '为什么装烟雾报警器；冬天在室内烧煤、用燃气取暖的再装一氧化碳报警器？', '一个能正常工作的烟雾报警器，能把住宅火灾里死亡的概率降约六成。起火时有四成人在睡觉，光靠鼻子是醒不过来的。冬天在屋里烧煤或用燃气的，再加一个一氧化碳报警器。中国 2018 年有 1.15 万人死于一氧化碳中毒，冬天那三个月七成死在家里。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-4', '燃气软管和灶具到期就换，不自己改管道，燃气公司上门推销可以直接拒绝', '为什么燃气软管和灶具到期就换，不自己改管道，燃气公司上门推销可以直接拒绝？', '一根合规软管几十块。到期就换，这是《城镇燃气管理条例》写明的用户义务。自己改管道、拆燃气表是条例明令禁止的。同一部条例还写了，燃气公司不能要求你买它指定的产品和服务。上门说「必须换」的推销，可以直接拒绝。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","C 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-5', '不采、不买、不吃野生蘑菇，任何「土办法鉴别」都不成立', '为什么不采、不买、不吃野生蘑菇，任何「土办法鉴别」都不成立？', '光 2025 年一年，全国就有 828 起蘑菇中毒，2165 人中招，13 人死。那一年还新认出 34 种以前没记录过会毒人的蘑菇。银针试毒、虫子吃过就没毒、颜色鲜艳才有毒，这些说法全都不成立。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-6', '电动自行车不推进楼道、不进电梯、不在家里充电', '为什么电动自行车不推进楼道、不进电梯、不在家里充电？', '把电动车推进楼道、推进电梯，或者在家里充电，应急管理部的《高层民用建筑消防安全管理规定》明令禁止。不改正的，个人罚 500 到 1000 元，做生意的罚 2000 到 10000 元。罚款还是小事，要紧的是这种火正好烧在你唯一的逃生通道上。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-7', '量血压，高了就吃药降到达标', '为什么量血压，高了就吃药降到达标？', '血压每降 10 mmHg，出大的心血管毛病的概率降两成，中风降 27%，心衰降 28%，死亡概率降 13%。中国 35 到 75 岁的人里，44.7% 有高血压，真正控制住的只有 7.2%。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-8', '35 岁以后只要超重，就去查一次空腹血糖，正常也每三年再查', '为什么35 岁以后只要超重，就去查一次空腹血糖，正常也每三年再查？', '花几十块抽一管血，就能在一点症状都没有的时候查出糖尿病前期。美国官方的筛查建议是：35 到 70 岁、超重或肥胖的人去查。查出来正常的，每三年再查一次。美国按体重指数 25 算超重，对亚裔放宽到 23；中国标准是 24 就算超重。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-9', '开车不超速、不酒驾', '为什么开车不超速、不酒驾？', '平均车速每高 1%，撞死人的概率高约 4%。酒精没有「喝一点没事」的安全线。血里的酒精浓度还很低的时候，风险就已经开始往上走了。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-10', '给 4 岁以下儿童用安全座椅，不要抱在怀里', '为什么给 4 岁以下儿童用安全座椅，不要抱在怀里？', '一岁以下的婴儿坐安全座椅，车祸里受致命伤的概率低约七成。1 到 4 岁的孩子低约一半。抱在怀里没有这个效果，急刹车时你也抱不住。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-11', '家里有小孩就给窗户和阳台装限位器，纱窗不算防护', '为什么家里有小孩就给窗户和阳台装限位器，纱窗不算防护？', '一副限位器几十块钱。纽约市给高风险住户免费装窗户护栏、又上门讲解，一个区上报的儿童坠落数三年里降了一半。后来纽约干脆立法，要求房东给住着小孩的房子装护栏。纱窗一推就开，不算防护。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-12', '儿童近水不离视线，划船、野泳穿救生衣', '为什么儿童近水不离视线，划船、野泳穿救生衣？', '落水的时候穿着救生衣，淹死的概率大约只有不穿的一半。溺水至今是中国 1 到 14 岁孩子的头号死因。农村的溺水死亡率大约是城市的两倍。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-13', '60 岁以上练平衡和腿部力量，改造家里的浴室和楼梯', '为什么60 岁以上练平衡和腿部力量，改造家里的浴室和楼梯？', '每周练两三次平衡，比如太极，老人跌倒的次数降约两成三，摔过的人数降 15%。家里做防滑、装扶手，再降约两成。跌倒是中国 65 岁以上老人因伤害死亡的头号原因，而且一多半就摔在自己家里。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-14', '查乙肝两对半，没有抗体就打疫苗', '为什么查乙肝两对半，没有抗体就打疫苗？', '查一次几十块。启东那项跟踪了 30 年的试验里，一出生就打了乙肝疫苗的人，后来得原发性肝癌的概率低 84%，身上带着乙肝病毒的比例低 72%。成人查出没抗体的补三针，半年打完，一两百块。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-15', '被铁钉、木刺扎到或者伤口沾了泥土，当天去处理，顺便问破伤风要不要打', '为什么被铁钉、木刺扎到或者伤口沾了泥土，当天去处理，顺便问破伤风要不要打？', '破伤风一旦发病，大约每 10 个人里死 1 个。深的伤口、沾了泥土的伤口风险最高。伤口脏、离上一针满 5 年的，要加强 1 针。当天去处理花不了几十块，别拖到伤口肿起来再说。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-16', '女性接种 HPV 疫苗，越早越好', '为什么女性接种 HPV 疫苗，越早越好？', '瑞典 167 万女性的数据里，17 岁以前打过 HPV 疫苗的人，后来得浸润性宫颈癌的概率只有没打的约八分之一。17 到 30 岁才打的，也只有一半左右。所以越早打越值。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-17', '女性 40 岁起做乳腺癌筛查，每两年一次钼靶', '为什么女性 40 岁起做乳腺癌筛查，每两年一次钼靶？', '40 到 74 岁的女性每两年拍一次钼靶，这是美国官方筛查建议里明确推荐的。75 岁以上，以及给致密乳腺加做超声和磁共振，官方的结论是证据还不够。体检套餐拿这些加钱的时候，可以不买。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-18', '30 岁以上女性做宫颈癌筛查，优先 HPV 检测', '为什么30 岁以上女性做宫颈癌筛查，优先 HPV 检测？', '印度农村那项试验里，一辈子只做过一次 HPV 检测的女性，死于宫颈癌的概率低约一半，查出晚期宫颈癌的概率低约五成。一次一两百块，结果阴性能管 5 年。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-19', '45 到 50 岁起做结直肠癌筛查，做查大便隐血的粪便免疫化学检测或者肠镜', '为什么45 到 50 岁起做结直肠癌筛查，做查大便隐血的粪便免疫化学检测或者肠镜？', '每一两年做一次几十块的粪便隐血检查，死于结直肠癌的概率低约 16%，至少查过一轮的人低 25%。被叫去做一次肠镜的人，往后十年得结直肠癌的概率从 1.20% 降到 0.98%。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-20', '有心血管病的人和老年人每年打流感疫苗', '为什么有心血管病的人和老年人每年打流感疫苗？', '心梗之后打流感疫苗的那项试验里，一年内死亡的比例从 4.9% 降到 2.9%。有心血管病的人和老人，每年秋天补一针，50 到 150 元。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-21', '50 岁以后打带状疱疹疫苗', '为什么50 岁以后打带状疱疹疫苗？', '三期试验里，这支疫苗把带状疱疹挡掉了 97%，各个年龄段都差不多。缺点是两针三四千元全自费。这笔钱买回来的，是九成七的发病率降幅。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 多","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-22', '65 岁以上打肺炎球菌疫苗', '为什么65 岁以上打肺炎球菌疫苗？', '8.45 万老人的试验里，13 价肺炎球菌疫苗把疫苗管得住的那几型肺炎挡掉约 46%，把最凶险的侵袭性感染挡掉 75%。但对「所有原因的肺炎」没看出效果，别指望它管住全部肺炎。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-23', '查幽门螺杆菌，阳性就根除', '为什么查幽门螺杆菌，阳性就根除？', '山东临朐那项跟踪了 22 年的试验里，把幽门螺杆菌根除掉的人，后来得胃癌的概率低约一半，死于胃癌的概率低约四成。查一次一两百块，根除要吃两周药。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-24', '重度吸烟者每年做一次低剂量胸部 CT', '为什么重度吸烟者每年做一次低剂量胸部 CT？', '符合条件的重度吸烟者每年做一次低剂量 CT，死于肺癌的概率比只拍胸片低 20%，总的死亡概率低 6.7%。代价是查出可疑结果后的复查，和那一段时间的提心吊胆。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-25', '抑郁或有自杀念头时打 12356，家里不囤安眠药和农药', '为什么抑郁或有自杀念头时打 12356，家里不囤安眠药和农药？', '把能要命的东西从手边拿走，这类做法的证据一直在变强：管住镇痛药以后，相关自杀降 43%；常有人跳楼的地方装上防护，降 86%。所以家里不囤安眠药和农药。想不开的时候先打 12356，全国通用，每天至少开 18 小时。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-26', '备齐灭火器、灭火毯、逃生呼吸面罩和急救包，每年检查一次', '为什么备齐灭火器、灭火毯、逃生呼吸面罩和急救包，每年检查一次？', '灭火器、灭火毯、逃生面罩、急救包，都在应急管理部那份 11 样的家庭应急清单里。一套几百元，买一次就行。上门做过家庭安全指导的那些研究里，伤害发生率低约四分之一。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-27', '尿里出现肉眼看得见的血，哪怕不疼、哪怕第二天就干净了，也要去查一次', '为什么尿里出现肉眼看得见的血，哪怕不疼、哪怕第二天就干净了，也要去查一次？', '60 岁以上的人出现一次肉眼看得见的血尿，最后查出膀胱癌的概率约 2.8%，40 到 59 岁约 1.2%。这个数不算高，但也高到必须去查一次。哪怕第二天不出血了也要去查。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-28', '勃起功能出了问题，先去查心血管，别当成单纯的「那方面的事」', '为什么勃起功能出了问题，先去查心血管，别当成单纯的「那方面的事」？', '有勃起功能障碍的男性，后来得心血管病的比别人多约四成，心梗多约六成。越年轻的人差得越多。这个毛病常常比胸痛先出现。所以先去查血压、血糖、血脂，别自己买药压过去。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-29', '减重、戒烟、把血压血糖控住，勃起功能能跟着好转', '为什么减重、戒烟、把血压血糖控住，勃起功能能跟着好转？', '把心血管的危险因素管起来，勃起功能本身会好转。用一份问卷打分，平均能多 2 到 3 分。这份问卷总分 25 分，22 分以上算正常。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-30', '性行为全程用安全套，不和别人共用针具', '为什么性行为全程用安全套，不和别人共用针具？', '每一次都全程戴，异性之间传染艾滋病的概率大约降七成以上。「大部分时候戴」的效果，和不戴差不了多少。梅毒、淋病这些也一并挡住。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-31', '有过高危行为就去查一次艾滋病，疾控中心免费、结果保密', '为什么有过高危行为就去查一次艾滋病，疾控中心免费、结果保密？', '去疾控查艾滋病不花钱。没有你本人同意，任何单位和个人都不得公开你的姓名、住址、工作单位和病史。查出来也不是判死刑：坚持吃药把病毒压到测不出来的人，不会再传给性伴侣。那项研究跟了七百多对伴侣、七万多次无套性行为，伴侣间传染是零。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-32', '自杀念头一冒出来先告诉身边的一个人，把这几十分钟交出去', '为什么自杀念头一冒出来先告诉身边的一个人，把这几十分钟交出去？', '自杀未遂的人里将近一半说，从念头冒出来到动手不超过 10 分钟，所以要熬过去的往往就是这几十分钟。四分之三的人那段时间和身边人有过接触，只是没开口。因自伤进过医院的人，1 年后约 2% 死于自杀，9 年以上约 7%，绝大多数人后来没有死于自杀。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-33', '别把「救回来」当成兜底：喝农药、吸煤气之后急诊能保住的是命，保不住肺和脑子', '为什么别把「救回来」当成兜底：喝农药、吸煤气之后急诊能保住的是命，保不住肺和脑子？', '百草枯没有解药，喝下去的人四成多救不回来。它会让肺发炎、慢慢变硬，肾和肝也跟着受伤。煤气中毒被救回来的人，六周后将近一半脑子不如从前，做了高压氧的也还有四分之一。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-34', '别拿「躺几天就好」赌高处坠落：进了创伤 ICU 的人多数活下来，代价按年算', '为什么别拿「躺几天就好」赌高处坠落：进了创伤 ICU 的人多数活下来，代价按年算？', '从高处摔下来进了创伤 ICU 的人，死亡的只有 5.5%，但伤得重、治得久。将近一半同时伤到三个以上部位，三分之一多上了呼吸机，最长的在 ICU 住了 132 天。一半人摔下来的高度不超过 3 米。伤得重的人，后来能回去上班的不到六成。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-35', '别拿「少一个肾没什么」换钱：剩下那个要替两个干活，卖过肾的人事后 86% 说身体变差', '为什么别拿「少一个肾没什么」换钱：剩下那个要替两个干活，卖过肾的人事后 86% 说身体变差？', '捐肾前层层筛查、捐后有人复查的正规捐献者，15 年后走到尿毒症的是每万人 31 人，同样健康但没捐的人是每万人 4 人。卖肾的人没有筛查也没有复查，6 年后 86% 说身体变差，四分之三还欠着债。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-36', '不捡、不拆、不卖来路不明的金属件，带三叶草警示标志的离远点', '为什么不捡、不拆、不卖来路不明的金属件，带三叶草警示标志的离远点？', '辐射没有气味、颜色和温度，多数放射源就是一截普通金属，所以「看着没事」不能当判断。普通人撞上的概率极低，每年每万枚放射源出事不到 1 起。可一旦撞上就无法挽回，1987 年巴西有人把废弃诊所的放疗机当废铁拆开，最后 4 人死亡。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-37', '赌到借钱还赌、心情一直低落时，先打 12356，再把银行卡和支付密码交给家人管', '为什么赌到借钱还赌、心情一直低落时，先打 12356，再把银行卡和支付密码交给家人管？', '去医院看过赌博问题的人，自杀死亡是同龄人的 15 倍，总死亡是 1.8 倍。能预先看出谁会自杀的信号是抑郁。所以赌到借钱还赌、情绪一直低落，先打 12356。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-38', '有高危性行为的男男性行为者，去艾滋病定点医院问暴露前预防药，按时吃能少感染七成以上', '为什么有高危性行为的男男性行为者，去艾滋病定点医院问暴露前预防药，按时吃能少感染七成以上？', '还没感染的人提前吃一种抗病毒药，叫暴露前预防。按时吃的人，感染风险能少七成以上。吃吃停停的人，基本没效果。它是处方药，要先在医院查过身体再开，之后定期复查。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-39', '65 岁以上的女性去做一次双能 X 线骨密度检查，绝经后有骨质疏松危险因素的不用等到 65 岁', '为什么65 岁以上的女性去做一次双能 X 线骨密度检查，绝经后有骨质疏松危险因素的不用等到 65 岁？', '65 岁以上的女性，以及绝经后有骨质疏松危险因素的女性，该去查一次骨密度。先查风险、再给高风险的人用药，髋部骨折能少约 17%。折算下来，每 1000 个去查的人里，约少 5 人髋部骨折。总死亡率没有看出变化。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-40', '查出骨质疏松，或者轻轻一摔就骨折过，就请医生开抗骨质疏松药并坚持用，别拿补钙代替', '为什么查出骨质疏松，或者轻轻一摔就骨折过，就请医生开抗骨质疏松药并坚持用，别拿补钙代替？', '已经确诊骨质疏松、或者轻轻一摔就骨折过的人，按医生的方案用药，髋部骨折能少约一半，脊柱骨折也少一半多。髋部骨折做完手术就开始每年输一次药的老人，两年里再骨折的少约三成五。单靠补钙代替不了这些药。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-41', '上野外冰面前先打孔量厚度，不到 15 厘米别上，河上的冰和冰钓洞边别去', '为什么上野外冰面前先打孔量厚度，不到 15 厘米别上，河上的冰和冰钓洞边别去？', '国内官方的说法是，冰厚到 15 厘米，成年人才能上去滑冰。美国和加拿大的底线是 10 厘米，而且只算新结的透明冰。发白的冰结实程度只有一半，厚度要翻倍。同一片冰，这里一尺厚，几步外可能只有一两寸，所以要边走边量。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s1-42', '装好护罩、戴上护目镜加面屏再用角磨机，双手握稳，别装木工锯片切木头', '为什么装好护罩、戴上护目镜加面屏再用角磨机，双手握稳，别装木工锯片切木头？', '角磨机转得极快，片子碎了会飞出来伤人，装上木工锯片还会突然反弹。国内两起事故都是装了锯片、没装护罩，一人割断大腿动脉，一人割破颈动脉，都没救回来。护罩、护目镜加面屏、双手握稳，这几样花不了几个钱。', 'safety', '1. 不要早死', 'published', 1, 'reference_book', 95, '{"1. 不要早死","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-1', '戒烟，越早越好', '为什么戒烟，越早越好？', '吸烟的人平均比不吸烟的人少活十年以上。40 岁前戒掉，能把接着吸烟带来的死亡风险抹掉九成左右。戒得越早，捡回来的越多。骨折以后接着抽，骨头长不上的几率约是不抽的 2.3 倍，所以骨头没长好之前别抽。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-2', '别在家里和车里抽烟，也别让客人在家里抽', '为什么别在家里和车里抽烟，也别让客人在家里抽？', '全球每年约 60 万人死于吸别人的烟，其中近三成是孩子。长期吸二手烟的人，高血压、心脏病、卒中的风险都高三成上下。在家里吸到的，比在外面吸到的更伤人。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-3', '戒烟别光靠忍，先去拿药：成功率能翻一倍多', '为什么戒烟别光靠忍，先去拿药：成功率能翻一倍多？', '光靠忍，多数人戒不掉。吃伐尼克兰的人戒成的比例，是吃安慰剂的两倍多。用尼古丁贴片、咀嚼胶这类替代品的，比不用药的高五成左右。贴片和咀嚼胶一起用，还能再高两成多。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-4', '定一个戒烟日，到那天一次停掉，别先慢慢减', '为什么定一个戒烟日，到那天一次停掉，别先慢慢减？', '很多人打算先每天少抽几根，慢慢减到零。可到了第六个月，定好日子一次停掉的人里 22% 没再抽，慢慢减的只有 15.5%。所以定一个日子，到那天一次停掉。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-5', '去戒烟门诊，或者打 12320 问当地有没有戒烟服务', '为什么去戒烟门诊，或者打 12320 问当地有没有戒烟服务？', '药和「有人定期问你」是两件事，合起来最管用。一边吃药一边有专人跟进的人，戒成的比例接近只听一句简短建议的人的两倍。电话也算：主动打回来的戒烟热线，能把成功率再提高两三成。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-6', '已经戒不掉再考虑电子烟，本来不吸烟的人别碰', '为什么已经戒不掉再考虑电子烟，本来不吸烟的人别碰？', '把烟换成含尼古丁的电子烟，戒成的人比用尼古丁贴片多约六成，这个结论很可靠。但它不是无害的，长期吸的安全数据还没有。本来不吸烟的人吸它没有任何好处。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-7', '不喝含糖饮料，换成无糖的也不算解决', '为什么不喝含糖饮料，换成无糖的也不算解决？', '每天喝两瓶以上甜饮料的人，同期死亡的概率比几乎不喝的人高约两成。每天一到两瓶的，也高一成多。换成无糖的也没见着好处：每天喝两杯以上代糖饮料的人，反而高约四分之一。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-8', '不嚼槟榔', '为什么不嚼槟榔？', '嚼槟榔的人，同期死亡的概率比不嚼的人高约两成。糖尿病和代谢综合征的风险高近五成。口腔癌和食管癌的风险还要另算。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-9', '把家里的食盐换成低钠盐（钾盐）', '为什么把家里的食盐换成低钠盐（钾盐）？', '得过中风或 60 岁以上有高血压的人，把家里的盐换成低钠盐，五年内死亡的概率低约 12%，中风低约 14%。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-10', '认真刷牙，每天清一次牙缝，缺牙及时补', '为什么认真刷牙，每天清一次牙缝，缺牙及时补？', '每天用牙线或牙缝刷的人，同期死亡的概率低约一成。牙掉光的老人，死亡的概率高约九成。剩不到 20 颗牙的，高约一倍。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-11', '每天走到 7000–8000 步，或者每周累计快走 150–300 分钟', '为什么每天走到 7000–8000 步，或者每周累计快走 150–300 分钟？', '每天走 7800 步左右的人，同期死亡的概率比只走 3500 步的人低约四成半。按时间算也一样，每周快走 150–300 分钟，比不运动低约三成。多到一定量就不再往下降了，60 岁以上走到 6000–8000 步就够。两种数法达标一个就行。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-12', '有高血压、高血脂就按医嘱规律吃药，别自行停', '为什么有高血压、高血脂就按医嘱规律吃药，别自行停？', '血压每降 10 mmHg，死亡的概率降约 13%，中风降约 27%。他汀把低密度胆固醇降 1 个单位，死亡的概率降约一成。按时吃药的人比经常漏吃的人，死亡的概率低三成到四成半。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-13', '每晚睡 7 小时左右，作息固定', '为什么每晚睡 7 小时左右，作息固定？', '长期睡不到 7 小时的人，同期死亡的概率高约一成。作息越乱，风险越高。睡得最规律的人比最不规律的人低两成到近五成。也就是说，作息规不规律比睡多久更能看出死亡风险。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-14', '每周打三次球拍类运动，每次 45 分钟', '为什么每周打三次球拍类运动，每次 45 分钟？', '常打网球、羽毛球、乒乓球的人，同期死亡的概率比不打的人低约一半，心血管死亡低约 56%。游泳的人低约 28%。跑步和足球在这份数据里没看出差别。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-15', '把爬楼梯、快走赶路这类零碎的用力活动攒到每天四五分钟', '为什么把爬楼梯、快走赶路这类零碎的用力活动攒到每天四五分钟？', '平时完全不锻炼的人，只要每天有三次一两分钟的用力活动，同期死亡的概率就比一点没有的人低约四成，心血管死亡低近一半。用力活动指爬楼梯、快步赶路这类。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-16', '每周做 30–60 分钟力量训练', '为什么每周做 30–60 分钟力量训练？', '每周练 30–60 分钟力量的人，同期死亡的概率比不练的人低一到两成。再多练不会更好。力量和有氧一起做效果最好。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-17', '别连着坐太久，隔一阵起身动一动', '为什么别连着坐太久，隔一阵起身动一动？', '坐得最久的人，同期死亡的概率是坐得最少的人的 2.6 倍。一次连着坐很久，还要另算一笔风险。但只要每天有 60–75 分钟中等强度活动，久坐多出来的风险基本就被抵消了。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-18', '少吃加工肉（火腿、培根、香肠、午餐肉）', '为什么少吃加工肉（火腿、培根、香肠、午餐肉）？', '火腿、培根、香肠吃得最多的人，同期死亡的概率比吃得最少的人高约两成。每天多吃一份加工肉，概率也高两成。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-19', '少喝或不喝酒', '为什么少喝或不喝酒？', '每周喝过 100 g 纯酒精以后，喝得越多死得越早。100 g 纯酒精大约是 2.5 L 啤酒。40 岁时每周喝 100–200 g 的人，少活半年左右；喝 200–350 g 的少一两年；超过 350 g 的少四五年。按整体健康算，最划算的量是不喝。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-20', '每天都喝酒、一停就手抖心慌的人，别自己硬戒', '为什么每天都喝酒、一停就手抖心慌的人，别自己硬戒？', '天天大量喝酒的人突然停，会出戒断反应。轻的手抖、出汗、心慌、睡不着，重的会抽搐或者出现震颤谵妄，那是会死人的急症。挪威跟踪了三万多人，得过震颤谵妄的那批，往后每年有 8% 的人死亡。想戒就先去医院，说清你每天喝多少。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-21', '想少喝酒，先把一周喝了多少数出来，再找医生聊几分钟', '为什么想少喝酒，先把一周喝了多少数出来，再找医生聊几分钟？', '医生花几分钟看你的饮酒量、说清风险、帮你定个目标，一年后平均每周少喝 20 克纯酒精，大约半升啤酒。谈更久并没有更多好处。已经停不下来的，国外有两种药被证明管用，大约每治 12 个人能多 1 个人不再回到一喝就喝多。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-22', '每天吃一小把坚果', '为什么每天吃一小把坚果？', '常吃坚果的人，同期死亡的概率比不吃的人低约两成。一周吃一次就能看出差别，低约一成。吃到每天一把，差别最明显。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-23', '把一部分红肉换成鱼和禽肉', '为什么把一部分红肉换成鱼和禽肉？', '每周多吃两份加工肉或者红肉，同期死亡的概率高约 3%。换成同样份数的鱼或者禽肉，就看不出升高。这条的效应在本节里偏小，属于顺手就换、不必较劲的事。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-24', '把一部分精米白面换成全谷物', '为什么把一部分精米白面换成全谷物？', '每天多吃 90 g 全谷物的人，同期死亡的概率低约 17%。90 g 大约是三份。吃到每天 200 g 左右，还在继续往下降。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-25', '每周喝三次以上茶', '为什么每周喝三次以上茶？', '有喝茶习惯的人，同期死亡的概率低约 15%。从 50 岁算起，平均多活 1.26 年，多出 1.41 年不得心血管病的时间。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-26', '每天喝三到四杯咖啡，不加糖不加奶盖', '为什么每天喝三到四杯咖啡，不加糖不加奶盖？', '每天喝三到四杯咖啡的人，同期死亡的概率比不喝的人低约 17%。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-27', '每天吃够 5 份（约 400 g）水果蔬菜', '为什么每天吃够 5 份（约 400 g）水果蔬菜？', '每天多吃 200 g 蔬菜水果，同期死亡的概率低约一成。每天吃够 5 份的人，比只吃 2 份的人低约 13%。再往上吃，不会更低。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-28', '少吃超加工食品（薯片、方便面、糕点、速食）', '为什么少吃超加工食品（薯片、方便面、糕点、速食）？', '超加工食品吃得最多的人，同期死亡的概率比吃得最少的人高约两成，心血管死亡高五成。不过这类证据被评为不太确定，数字要往回打折看。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-29', '做饭、取暖不烧煤和柴，换成电或燃气', '为什么做饭、取暖不烧煤和柴，换成电或燃气？', '做饭烧煤或烧柴的人，同期死亡的概率高约一成；取暖烧煤柴的高约 14%。已经改用电或燃气的人，比还在烧煤柴的人死亡概率低 13%–33%。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-30', '热的东西放一放再喝，不喝滚烫的茶、汤和咖啡', '为什么热的东西放一放再喝，不喝滚烫的茶、汤和咖啡？', '喝很烫的茶，得食管癌的概率是喝温茶的 8 倍。就算只是「热」，也有 2 倍。倒出来不到两分钟就喝，风险是等四分钟以上再喝的 5 倍。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-31', '白天出门晒晒太阳，别整天不见光', '为什么白天出门晒晒太阳，别整天不见光？', '刻意躲太阳的女性，预期寿命比晒得最多的人少 0.6 到 2.1 年。不吸烟但躲太阳的人，寿命和晒得最多的吸烟者差不多。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-32', '把 BMI 控制在 20–25，超重就减', '为什么把 BMI 控制在 20–25，超重就减？', '死亡的概率在 BMI 20–25 这一段最低。BMI 到 27.5–30 高约两成，30–35 高约四成半，35–40 接近翻倍。东亚人对超重更敏感，BMI 每高 5，风险高约四成。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-33', '每周吃四次以上辣椒', '为什么每周吃四次以上辣椒？', '每周吃四次以上辣椒的人，同期死亡的概率比很少吃的人低约 23%，心血管死亡低约三分之一。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-34', '每天喝一两份奶或酸奶', '为什么每天喝一两份奶或酸奶？', '每天喝两份以上奶或者酸奶的人，同期死亡的概率比不喝的人低约 17%。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-35', '鸡蛋不用戒，但别每天三四个', '为什么鸡蛋不用戒，但别每天三四个？', '每天多吃半个全蛋，同期死亡的概率高约 7%。把这半个换成蛋清、鱼、禽肉或者坚果，各项死亡风险反而都更低。不用戒鸡蛋，只是别每天吃三四个。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-36', '有条件就泡澡，别只冲淋浴', '为什么有条件就泡澡，别只冲淋浴？', '几乎每天泡澡的人，心血管事件的风险比每周泡不到两次的人低约 28%，脑出血低约 46%。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-37', '把午睡控制在半小时内，别超过一小时，非得睡一两小时才撑得住就去查原因', '为什么把午睡控制在半小时内，别超过一小时，非得睡一两小时才撑得住就去查原因？', '午睡不超过一小时的人，死亡和慢性病的风险没有升高，脑子还更清醒一些。睡过一小时的人，冠心病风险高约三成，糖尿病和肥胖高约两成。所以定个闹钟，半小时叫醒自己。要是每天非得睡一两小时才撑得住，那是该去查身体的信号。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-38', '熬夜之后第二天晚上就补觉，别攒到周末', '为什么熬夜之后第二天晚上就补觉，别攒到周末？', '少睡之后第二天晚上没补上的人，死亡风险比作息规律的人高约 15%，少得厉害又不补的高约 42%。补上了的人看不出风险升高。所以熬了夜，第二天晚上就早点上床。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-39', '上夜班干得越久心血管风险越高，能转岗就趁早转', '为什么上夜班干得越久心血管风险越高，能转岗就趁早转？', '上夜班的人，心血管病比不上夜班的人多约 13%，心血管死亡多约 27%。而且干得越久越多：每多上 5 年夜班，心血管病再多约 7%。所以这笔账按年数算，能转岗就趁早。至于夜班致癌，证据比流传的说法软得多。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-40', '买预包装、有 SC 编号的食用油，不买小作坊散装自榨花生油', '为什么买预包装、有 SC 编号的食用油，不买小作坊散装自榨花生油？', '花生受潮发霉会长黄曲霉毒素，它是明确的致癌物，主要伤肝。广州管住小作坊之后，常吃自榨油的居民肝功能异常少了约三成半。广西的孕妇吃自榨花生油，孩子出生体重偏低的风险高约九成，早产高约八成。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-41', '做饭用植物油代替猪油和黄油，不必为了健康换着买油，也别指望亚麻籽油护心', '为什么做饭用植物油代替猪油和黄油，不必为了健康换着买油，也别指望亚麻籽油护心？', '少吃猪油黄油这类饱和脂肪、换成植物油，心脏病和中风这类事少约一成七，但总的死亡风险没看出变化。大豆油、玉米油、菜籽油之间换来换去，没有证据说有什么区别。亚麻籽油吃多了，心脏病风险也没看出下降。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-42', '炒菜、煎炸时打开抽油烟机，从开火一直开到做完', '为什么炒菜、煎炸时打开抽油烟机，从开火一直开到做完？', '不吸烟的中国女性，炒菜时不开或很少开抽油烟机，得肺癌的风险约是常开的两倍。住过厨房通风差的房子，风险也高约五成，烧煤的人家最明显。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s2-43', '绝经前后潮热盗汗影响到生活，就去妇科评估激素治疗，别硬扛也别自己买药，更别拿它防心脏病', '为什么绝经前后潮热盗汗影响到生活，就去妇科评估激素治疗，别硬扛也别自己买药，更别拿它防心脏病？', '绝经前后潮热、盗汗，用激素治疗，潮热次数比吃安慰剂少约 75%。代价是乳腺癌、血栓、中风会多一点，每年每 1 万名女性里各多出约 8 个人。50 到 59 岁开始用的人，总死亡率没有升高。它不能用来防心脏病和老年痴呆。', 'health', '2. 不要慢慢死', 'published', 1, 'reference_book', 95, '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-1', '关掉非必要通知，工作时把手机放到视线之外', '为什么关掉非必要通知，工作时把手机放到视线之外？', '手机响一下，哪怕你没看、没碰，注意力任务的成绩也会掉。掉的幅度和你真去接电话、发短信差不多。还有一种情况：手机就搁在桌上，你忍住不看，脑子能用的余量一样会变少。越离不开手机的人，掉得越多。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-2', '固定起床时间，周末也一样', '为什么固定起床时间，周末也一样？', '作息最乱的那五分之一人，生物钟比最规律的那五分之一晚了约 2.5 小时。等于长期活在时差里。作息越规律的学生，成绩也越好。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-3', '每晚睡够 7 到 8 小时，别把 6 小时当作够用', '为什么每晚睡够 7 到 8 小时，别把 6 小时当作够用？', '连着两周每晚只睡 6 小时，脑子的表现会掉到相当于两天两夜没合眼的水平。麻烦的是自己感觉不到。自己打分的困倦头几天涨完就不再涨，睡 6 小时的人和睡 4 小时的人打分一样困。所以「我睡 6 小时够用」这句话本身就是缺觉的症状。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","A 级","性价比 一般","口径 时间","钱 0","时间 多","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-4', '下午两点以后不碰咖啡因', '为什么下午两点以后不碰咖啡因？', '睡前 6 小时喝一大杯咖啡（400 mg），当晚用仪器测出来少睡 1 小时以上。可自己写的睡眠日记根本看不出差别。一杯普通咖啡（107 mg）要在睡前 8.8 小时以上喝完，才不影响睡眠。十一点睡的人，下午两点就是界线。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-5', '把邮件和消息改成每天固定几次批量处理', '为什么把邮件和消息改成每天固定几次批量处理？', '同一批人对比了两周。把邮件限制成每天只查 3 次的那一周，日常压力明显更低，而收发的邮件数量一样多。不加限制的时候，人平均每天要查 15.5 次。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-6', '做需要连续思考的工作时，把哪怕几秒钟的打断也挡在外面', '为什么做需要连续思考的工作时，把哪怕几秒钟的打断也挡在外面？', '一次平均 2.8 秒的打断，就让接下来的操作出错概率翻倍。4.4 秒的打断翻三倍。现场跟踪还发现，被打断的那件事平均要 25 分钟才回得来，中间还插进两件别的事。被打断的人干得更快，但压力、挫败感和费劲程度全都更高。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 极高","口径 时间","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-7', '一次只做一件事，不要边开会边回消息', '为什么一次只做一件事，不要边开会边回消息？', '任务一切换，反应就更慢，也更容易出错。经常同时开好几个屏的人，并没有练出同时做几件事的本事，反而在任务切换测试上表现更差。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-8', '睡前一小时不看发光屏幕，要看就看纸书或墨水屏', '为什么睡前一小时不看发光屏幕，要看就看纸书或墨水屏？', '睡前读发光屏幕，比读纸书晚约 10 分钟才睡着。褪黑素被压低 55%。第二天生物钟往后推 1.5 小时以上，早上更困，要更久才清醒。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-9', '到点就睡，不为游戏、短视频、色情内容熬夜', '为什么到点就睡，不为游戏、短视频、色情内容熬夜？', '2025 年中国人夜里平均睡 6.97 小时，平均 0:10 才入睡。睡前用手机、平板的人，睡不够的概率是两倍多，白天犯困的概率是 2.7 倍。设备只是放在卧室里不用，数字也差不多。所以最省事的办法是手机不进卧室。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-10', '深夜不做重大决定、不发要紧的消息', '为什么深夜不做重大决定、不发要紧的消息？', '人睡饱的时候，很快就能学会躲开高风险的选项。连着两晚没睡之后，反而一次次挑高风险的，年纪越大越明显。少睡几小时有多大影响没人测过，但要紧的决定还是推到睡醒以后。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-11', '下午困了就睡 10 分钟，不要睡半小时', '为什么下午困了就睡 10 分钟，不要睡半小时？', '10 分钟的小睡当场就能提神，效果能撑两个半小时。睡 5 分钟基本没用。睡 20 分钟要等半小时以后才见效。睡 30 分钟，醒来先有一段发懵，那阵子表现比不睡还差。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-12', '在开放式办公室工作时用耳塞或找安静房间做需要记忆的活', '为什么在开放式办公室工作时用耳塞或找安静房间做需要记忆的活？', '背景噪音从 39 分贝涨到 51 分贝，能记住的词就变少，人更累，也更不想干活。休息的时候看带声音的自然风光片，比接着听办公室噪音更能把精力找回来。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-13', '每周工作时间不要超过 49 小时', '为什么每周工作时间不要超过 49 小时？', '一战时英国军工厂的记录显示，每周干 49 小时以内，干多久就出多少活。超过 49 小时，多干一小时多出的活越来越少。一周干 70 小时和干 56 小时出的活几乎一样，多干的那 14 小时是白干。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-14', '发现自己在反复回想同一件糟心事时，换个需要动手的活', '为什么发现自己在反复回想同一件糟心事时，换个需要动手的活？', '反复回想同一件糟心事，不会想出答案。它只会加重抑郁，把负面念头钉得更牢，让人更解决不了问题，也更难真动手，还会把身边愿意听你说的人耗光。察觉到自己在原地绕，就去干点要动手的活。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-15', '把「事情肯定会更糟」这类念头当症状看，不当事实看', '为什么把「事情肯定会更糟」这类念头当症状看，不当事实看？', '一项跟踪了 20 年的双生子研究里，悲观程度每高一个档，同期死亡的概率高约 13%，死于心血管病的概率高约 20%。反过来，乐观得分高并没有带来相应的好处。所以要处理的是悲观，不是「不够正能量」。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-16', '减少让你消耗的人际关系，学会拒绝不想接的请求', '为什么减少让你消耗的人际关系，学会拒绝不想接的请求？', '一个消耗你的人造成的损失，比一个支持你的人带来的好处更大，也更一致。所以先做减法，再做加法。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","C 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-17', '生气时先离场，把对方当天气而不是当敌人', '为什么生气时先离场，把对方当天气而不是当敌人？', '换个角度解释刚发生的事，或者站到对方立场想一下，都能实打实把情绪降下来，后一种更管用。硬压着不表现出来没有效果。另外，惩罚了冒犯者的人，事后反而更久地反复想这件事；不报复的人翻篇更快。报复带来的痛快，人们事先高估了。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-18', '情绪低落时先做性价比最高的几件事：动起来、晒太阳、按时睡、找人说、打 12356', '为什么情绪低落时先做性价比最高的几件事：动起来、晒太阳、按时睡、找人说、打 12356？', '对抑郁来说，快走和慢跑效果最好，强度越大越有效，细节见第 22 节第 6 条（心情差就去走或者跑）。晒光照对季节性抑郁效果很强，对不分季节的抑郁也有效。网上的自助认知行为课程管用，症状偏重时有人带着做更好。想不开先打 12356。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","A 级","性价比 高","口径 时间","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-19', '把警察、医生、柜员当成按规则上班的人，别当成角色：能推动事情的是文书和期限，不是情绪', '为什么把警察、医生、柜员当成按规则上班的人，别当成角色：能推动事情的是文书和期限，不是情绪？', '警察、医生、柜员都是按岗位规则上班的人，被文书、期限和监督管着。对方态度好不好，和你的事办不办、几天办完基本无关。所以要拿回执、记期限、按渠道申诉，别想着把道理讲到对方认同。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","C 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-20', '别把「别人过得怎么样」当每日必读：给刷同龄人动态的应用设限或关掉', '为什么别把「别人过得怎么样」当每日必读：给刷同龄人动态的应用设限或关掉？', '习惯在网上跟过得更好的人比的人，往往情绪更差、自尊更低。把 Facebook 停用四周的人，幸福感小幅提高，但对时事的了解也掉了一截。把三个社交平台各限到每天 10 分钟的人，三周后孤独和抑郁都降了下来。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-21', '觉得「所有人都看见我出丑了」的时候，把这个估计除以二', '为什么觉得「所有人都看见我出丑了」的时候，把这个估计除以二？', '穿一件尴尬的 T 恤走进有人的房间，穿的人以为将近一半人认得出衣服上印的是谁，实际不到四分之一。穿自己觉得体面的 T 恤，估计的人数是实际的六倍。人聊完天，也普遍低估对方有多喜欢自己。所以觉得「所有人都记住我出丑了」时，砍一半仍然偏高。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-22', '把「别人要求我做到完美」当症状看，不当事实看', '为什么把「别人要求我做到完美」当症状看，不当事实看？', '总觉得「周围的人要求我完美，做不到就会被否定」的人，更容易有自杀念头。「我自己要求自己完美」和自杀念头的关系弱得多，只有前一种的三分之一左右。把原本就有的念头扣掉，前一种感觉仍和后来念头变多有关，只是幅度不大。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-23', '生气时别靠砸东西、打沙袋、跑一圈来发泄，先让身体慢下来', '为什么生气时别靠砸东西、打沙袋、跑一圈来发泄，先让身体慢下来？', '打沙袋、摔东西、去跑一圈，这类让身体更兴奋的发泄办法，整体上消不了气。慢呼吸、正念、冥想这类让身体静下来的办法，能明显压下怒气和想动手的劲。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-24', '心里压着一件事，可以连着几天把想法和感受写下来，但别指望它治病', '为什么心里压着一件事，可以连着几天把想法和感受写下来，但别指望它治病？', '把糟心事写下来，平均有一点好处，但很小。汇总的结论也不一致，有两项汇总算下来没有效果。它几乎不花钱，可以试。情绪问题重了，别拿它代替看医生。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s3-25', '痛经就吃布洛芬这类止痛药，别硬扛；痛到耽误上班上学、吃三个月药也压不住，就去妇科查', '为什么痛经就吃布洛芬这类止痛药，别硬扛；痛到耽误上班上学、吃三个月药也压不住，就去妇科查？', '痛经吃布洛芬这类药，痛明显减轻的人从不到两成升到约一半，比对乙酰氨基酚管用，副作用多一点。痛到耽误上班上学、同房时深处痛，或者吃三个月药还压不住，就去妇科查子宫内膜异位症。这个病平均拖 6.7 年才确诊。', 'psychology', '3. 不要浪费精力', 'published', 1, 'reference_book', 95, '{"3. 不要浪费精力","A 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-1', '把「打算做」写成「几点、在哪、遇到什么就做什么」', '为什么把「打算做」写成「几点、在哪、遇到什么就做什么」？', '把「我要做这件事」改写成「周二早 8 点坐到书桌前就先写引言」。94 项检验合起来算，这么写的人把目标做成的比例明显更高，属于中到大的效果。改的只是一句话的写法，不花钱，也不费力气。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","A 级","性价比 极高","口径 时间","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-2', '开工前写下退出条件', '为什么开工前写下退出条件？', '开工前先写好一句话：到某月某日还没达到某个指标就停。多项研究合起来算，这种写法确实能帮人从注定做不成的事上撤下来。省下的是你本来还要接着往里砸的全部时间。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-3', '决定是否继续时，只看未来投入和未来回报，不看已投入多少', '为什么决定是否继续时，只看未来投入和未来回报，不看已投入多少？', '已经投进去的钱和时间，会让人更想接着干下去。98 组数据合起来算，这个倾向稳定存在。所以判断要不要继续，只算往后还要投多少、还能拿回多少。已经花掉的那些，不要算进去。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-4', '估工期时按过去同类任务的实际耗时估，不按计划推', '为什么估工期时按过去同类任务的实际耗时估，不按计划推？', '学生估自己 33.9 天写完论文，实际用了 55.5 天，只有 29.7% 的人按自己估的时间做完。另一组被要求先回想上次同类的事花了多久再估，按时完成的比例从 29.3% 升到 60.0%。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 极高","口径 时间","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-5', '会前发议程，没议程的会不开；能站着开就站着开', '为什么会前发议程，没议程的会不开；能站着开就站着开？', '会前发了议程的会，参会者更容易觉得这个会有用。实验里，坐着开的会比站着开的长 34%，而两种开法做出的决定，好坏没有差别。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-6', '砍会议数量，能用文字异步解决的不开会', '为什么砍会议数量，能用文字异步解决的不开会？', '当天开的会越多，人越累，自己感觉手上的活也越多。砍掉一个会，省下的时间就是那个会本身的长度，一分不打折。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-7', '把大任务拆成子任务再估时、再开工', '为什么把大任务拆成子任务再估时、再开工？', '人估工期的时候，不会自动把任务拆开一件件算。先把子任务列出来再估，就能少估短一截。拆开之后，每一小步都能马上动手，也就不那么容易拖。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-8', '给没有外部截止的事自己定一个日期', '为什么给没有外部截止的事自己定一个日期？', '有别人定的截止日期时，80.6% 的学生能在那之前做完。按自己预计的时间做完的，只有 38.7%。什么时候做完，几乎由截止日期决定，和自己估的关系不大。所以没有截止日期的事，自己给它定一个，并且认账。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-9', '把拖延当成在躲开难受，不要当成不够努力', '为什么把拖延当成在躲开难受，不要当成不够努力？', '拖延和懒、和性格关系不大。最能看出一个人拖不拖的，是这件事本身让他多难受、他觉不觉得自己做得成、他有多容易被眼前的东西带走。所以有用的是把任务改得没那么难受、把第一步改小，不是骂自己一顿再硬上。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-10', '把要用的东西摆到手边，把不想碰的挪远，别指望当场忍住', '为什么把要用的东西摆到手边，把不想碰的挪远，别指望当场忍住？', '东西离得远一点，人就少拿一点。把同样的零食放远，吃下去的量明显下降，属于中等大小的效果。少摆几个选项，拿的人也明显变少。这类办法不用你当场忍，几分钟就能布置好。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-11', '想让自己做到就把钱押上，但先问自己肯不肯押', '为什么想让自己做到就把钱押上，但先问自己肯不肯押？', '想逼自己做到，可以做到了就领奖金，也可以先交押金、做到才退还再加奖。两种都肯参加的人里，交押金的做到的多出 13 个百分点。但肯交押金的只有 13.7%，肯拿奖金的有 90%，所以押金只对肯押的人有用。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","A 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-12', '新习惯按月算，不要按「21 天」算', '为什么新习惯按月算，不要按「21 天」算？', '「21 天养成一个习惯」没有依据。一项跟踪 12 周的研究算下来，一个动作变得不用想就做，快的 18 天，慢的要 254 天。两三周还没变轻松是正常的。中间漏掉一天，也不会把进度清零。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-13', '拖延已经影响生活的，用有随机试验支持的自助材料，不用非找治疗师', '为什么拖延已经影响生活的，用有随机试验支持的自助材料，不用非找治疗师？', '拖延严重到让人痛苦，是能治的。照着认知行为自助材料练十周，有人带着做和完全自己做，都明显比什么都不做好。有人带和没人带看不出差别，所以自己照着做也有效。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-14', '用自己的时薪决定哪些家务外包', '为什么用自己的时薪决定哪些家务外包？', '中国人平均每天花 1 小时 17 分做家务。当天真动手做的那部分人，花 1 小时 59 分。花钱买时间的人，生活满意度更高。同样一笔钱，花在买时间上比买东西，当下更让人开心。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-15', '给短视频和无目的刷屏设硬上限', '为什么给短视频和无目的刷屏设硬上限？', '中国人平均每天上网 5 小时 37 分。当天真上了网的人，是 6 小时 3 分。2018 年按同样算法还只有 2 小时 42 分。这是本节里数字最大的一项。每天砍掉一小时，一年就多出 365 小时。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","C 级","性价比 高","口径 时间","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-16', '不看电视和滚动新闻，需要的信息定时集中看', '为什么不看电视和滚动新闻，需要的信息定时集中看？', '美国 15 岁以上的人每天看 2.6 小时电视，占掉全部闲暇时间的一半。中国人平均每天看 1 小时 40 分，75 到 84 岁的老人看 3 小时 16 分。把要看的信息改成定时集中看，省下的就是这一整块。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","C 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-17', '花一次时间学常用软件的键盘快捷键和自动化', '为什么花一次时间学常用软件的键盘快捷键和自动化？', '多数用了很多年 Word 的人，还是在点工具栏图标。分组对比的实验里，快捷键比菜单和图标都快。学这一次是一次性花费，之后每天每次操作都在回本。做同一类工作越久，赚回来越多。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s4-18', '选住处时把通勤时长放在前面，缩短单程通勤', '为什么选住处时把通勤时长放在前面，缩短单程通勤？', '通勤越长的人，自己觉得过得越不好。这笔损失并没有在工资或者住房上被补回来。单程少 30 分钟，一周就省出 5 小时。', 'efficiency', '4. 不要浪费时间', 'published', 1, 'reference_book', 95, '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 多","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-1', '关掉所有自动续费，改为到期手动续', '为什么关掉所有自动续费，改为到期手动续？', '省下来的，是那些你早就不用、每月还在扣钱的订阅。翻一遍支付宝、微信、苹果和安卓的自动扣款列表，用不了 20 分钟。按规定，商家扣款前要明显提醒你，还必须给你一个随时能取消的入口，而且要好找好点。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-2', '每年三月到六月做一次个税汇算，专项附加扣除该填的填', '为什么每年三月到六月做一次个税汇算，专项附加扣除该填的填？', '这几种人办下来通常能退到钱：全年只干了几个月，年中换过工作，或者子女教育、房贷、房租、赡养老人这些扣除没填。在手机上十几分钟就能办。如果你一年综合所得不到 12 万元，或者该补的税不到 400 元，可以不办。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-3', '公积金不只用来买房：租房、装修、物业费都能提，2026 年 9 月 20 日起按新条例办', '为什么公积金不只用来买房：租房、装修、物业费都能提，2026 年 9 月 20 日起按新条例办？', '公积金不是只有买房才能动。新条例把能提取的情况列了九项，租房、装修自己住的房子、交物业费都算在里面。你交了申请，公积金中心要在 3 天内答复你准不准提。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-4', '每年重算一次手机和宽带套餐，用不上的降档，运营商不给转就投诉', '为什么每年重算一次手机和宽带套餐，用不上的降档，运营商不给转就投诉？', '你用的老套餐，往往比现在新卖的贵几十块钱。一个月几十，一年就是几百块白扔。按规定，运营商没有正当理由，不能拒绝你转网，也不能拖着不给你办，更不能专门给转网的人单独设一套资费。它卡着不放，你就投诉。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-5', '不买彩票', '为什么不买彩票？', '按规定，乐透数字型彩票拿出来当奖金的钱，最少是销售额的 50%，双色球是 51%。也就是你每投 1 元，长期平均只能拿回 0.51 元，稳定亏掉 49%。2024 年全国卖了 6234.86 亿元彩票，其中 1610.31 亿元直接进了公益金，这部分不在奖金里。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-6', '看到「高收益」「保本」「稳赚」直接走开', '为什么看到「高收益」「保本」「稳赚」直接走开？', '监管部门自己的说法是：收益率超过 6% 就要打问号，超过 8% 很危险，10% 以上就要准备赔光本金。正规理财已经不许承诺保本保收益了。参加非法集资亏掉的钱，按规定由你自己承担，出事没人替你兜底。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-7', '不用信用卡最低还款，不为消费开分期或消费贷；非借不可，先把利息换成年化利率再比', '为什么不用信用卡最低还款，不为消费开分期或消费贷；非借不可，先把利息换成年化利率再比？', '最低还款是按天算利息的贷款，折合一年 18% 上下，用了免息期就作废。分期写「每月手续费 0.6%」，按年算约 13.8%，不是 7.2%。因为本金每月在还，手续费却一直按最初的数收。比哪笔贷款贵，只看年化利率，别看日息和月费率。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-8', '不给主播打赏、不给游戏充值、不冲动下单', '为什么不给主播打赏、不给游戏充值、不冲动下单？', '国内玩游戏的人，平均每人一年在游戏上花约 480 元，花出去基本追不回来。法律只让未成年人没经家长同意花的钱退回来，成年人没有这一条。最省力的办法是提前设防：关掉免密支付，设单笔和每日限额，把支付方式解绑。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-9', '孩子用手机充值打赏，八岁以上的大额支出未经家长追认可以主张退', '为什么孩子用手机充值打赏，八岁以上的大额支出未经家长追认可以主张退？', '八岁以上的孩子花的钱，只要金额和他的年龄、智力明显不相称，家长既不同意也不认这笔账，这笔交易就是无效的，可以要求退。不满八岁的孩子，本来就不能自己做主花钱。家长一直不表态，法律上就算作不认这笔账。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-10', '教孩子记一句话：任何人让你拿家长的手机去操作、去报验证码，都是骗子', '为什么教孩子记一句话：任何人让你拿家长的手机去操作、去报验证码，都是骗子？', '这六类骗局的套路各不相同，但最后一步永远是同一个动作：让孩子拿家长的手机去转账，或者念验证码。所以教会一句就够用了：谁让你动家长的手机、报验证码，谁就是骗子。再加一句「被骗了先跟我说，我不骂你」。孩子敢当天说，钱才有可能追回来。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-11', '拒绝电子产品的延长保修（延保）', '为什么拒绝电子产品的延长保修（延保）？', '延保一般卖到原价的 10% 到 50%，卖延保的赚头是普通商品的十几倍，这个差价就是你多付的钱。洗衣机、冰箱的电机这类主要部件，国家本来就规定保修 3 年。碰上很便宜的延保，拿延保价除以修一次的钱，得数就是这几年里至少坏一次的可能要多大才回本。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-12', '优先选通过一致性评价的仿制药和集采中选药', '为什么优先选通过一致性评价的仿制药和集采中选药？', '集采第二批药平均降价 53%，降得最多的降了 93%。到 2026 年 4 月，已经做了 11 批，覆盖 490 种药。开药买药时多问一句「有没有集采的、通用名的」，成分一样，钱能少花一大截。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-13', '在医保 App 上办一次家庭共济绑定，职工医保个人账户的钱就能给配偶、父母、子女看病买药', '为什么在医保 App 上办一次家庭共济绑定，职工医保个人账户的钱就能给配偶、父母、子女看病买药？', '办一次绑定，你职工医保个人账户里的钱，就能给配偶、父母、孩子看病买药用。不办，这笔钱就只能你自己用，一直躺在账户里。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-14', '喝烧开的自来水，不常年买瓶装水', '为什么喝烧开的自来水，不常年买瓶装水？', '北京第一阶梯的水价，折合 0.005 元一升。瓶装水按 1 元 500 毫升算，是 2 元一升。两者差 400 倍。自来水执行的是强制性的国家标准，平时烧开了喝就行。真碰上水源出事、水发臭发浑，那不是多煮几分钟能解决的，要停下来别喝，并且向外反映。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-15', '不频繁交易股票，行情暴涨暴跌的时候更要少动手', '为什么不频繁交易股票，行情暴涨暴跌的时候更要少动手？', '买卖最频繁的美国家庭，每年只赚 11.4%，同期整个市场是 17.9%，差距几乎全是手续费。国内 2014 到 2015 年那轮暴涨暴跌里，账户最小的 85% 家庭买卖太勤。他们比一直拿着不动少赚 2500 亿元，约是本金的三成。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-16', '不借钱投资、不加杠杆、不买自己看不懂的', '为什么不借钱投资、不加杠杆、不买自己看不懂的？', '借钱买股票，一旦跌破线，你又补不上钱，就会被强制卖掉。账面上的亏损当场变成真亏，连「等它涨回来」的机会都没有。监管规定，开户不满半年、最近 20 个交易日日均资产不到 50 万元的人，不能开融资账户。这个门槛本身就说明，它不是给普通人用的。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-17', '用宽基指数基金替代主动管理基金作为长期底仓（长期拿着不动的那部分钱）', '为什么用宽基指数基金替代主动管理基金作为长期底仓（长期拿着不动的那部分钱）？', '主动基金合起来买的那堆股票，已经很接近整个市场了。但它们多收的那笔管理费，是实打实从你到手的收益里扣掉的。把基金的业绩当成运气反复重算来比，能靠多赚的那部分把自己收的费挣回来的基金，很少。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-18', '同类基金优先选费率低的', '为什么同类基金优先选费率低的？', '一年的费率每高 1 个百分点，20 年后到手的钱少约 18%，30 年后少约 26%。在同一类基金里挑费率低的，是这件事上唯一一个你能提前确定的东西。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-19', '别把钱押在一只股票、一个平台、一套房上', '为什么别把钱押在一只股票、一个平台、一套房上？', '几样东西只要不是完全一起涨、一起跌，把钱分开放，平均能赚到的不变，账户的起伏却会小一些。反过来，钱全押在一只股票、一个平台、一套房上，它一出事，就等于你全部出事。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-20', '交个税且税率到 10% 及以上的人开个人养老金账户，每年最多 12000 元能在税前扣掉；不交个税或税率只有 3% 的人开了不划算', '为什么交个税且税率到 10% 及以上的人开个人养老金账户，每年最多 12000 元能在税前扣掉；不交个税或税率只有 3% 的人开了不划算？', '你每存进去一元，省下的税是「你那一档税率减 3%」。一年存满 12000 元，税率 10% 的人省 840 元，20% 的省 2040 元，30% 的省 3240 元。税率只有 3% 的人，省下的税领钱时又交回去，白锁到退休。不交个税的人领钱时还要交 3%，是净亏。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-21', '健身房按次付费或短周期付费，除非有一年以上的稳定记录', '为什么健身房按次付费或短周期付费，除非有一年以上的稳定记录？', '美国那份三年的数据里，选月费 70 美元以上合同的会员，平均每月只去 4.3 次，折合每次超过 17 美元。而按次买 10 次卡，每次只要 10 美元。这些人在会籍期间平均多付了 600 美元。除非你已经有一年以上稳定去的记录，否则按次买或者买短期的更划算。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-22', '交预付款要签书面合同；商家出风险要停收，跑路前你有权要回未消费的余额', '为什么交预付款要签书面合同；商家出风险要停收，跑路前你有权要回未消费的余额？', '商家收你的预付款，必须和你签书面合同，写清楚怎么退。商家经营出了大问题，就该停止收钱，要停业或搬走也得提前告诉你。这时你可以要它接着提供服务，或者把没花完的余额退给你。商家违反这些规定会被罚款。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-23', '大额非必需购买设 24 小时冷静期，网购善用七日无理由退货', '为什么大额非必需购买设 24 小时冷静期，网购善用七日无理由退货？', '省下来的，是那些你第二天就不想要的东西。网购的东西，从你收到货那天算起，七天之内可以无理由退。有几类不能退：按你的要求定做的，生鲜和容易坏的，已经拆封的数字商品，还有报刊。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-24', '不为「划线价」和大促囤货', '为什么不为「划线价」和大促囤货？', '人判断一样东西贵不贵，靠的是最先看到的那个数字，之后再怎么调整都调不够。所以「原价 999 现价 499」会让你系统性地高估它有多便宜。而按规定，打折要拿来当基准的，只是这家店促销前七天里的最低成交价。那个划掉的价格，不一定真卖过。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-25', '保险优先买消费型，把「返还」「分红」当作不保证的部分', '为什么保险优先买消费型，把「返还」「分红」当作不保证的部分？', '分红和返还的那部分钱，保险公司不保证给你。说明书上必须用加粗字写明「未来的保单红利为非保证利益」。你为返还多交的保费，等于交给保险公司替你存着，收益不保证，想取出来也不容易。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-26', '三者险买够：交强险限额全国统一且不高，超出的部分从你自己家里出', '为什么三者险买够：交强险限额全国统一且不高，超出的部分从你自己家里出？', '你有责任时，交强险最多赔三项：死亡伤残 18 万元，医疗费用 1.8 万元，财产损失 2000 元。三项分开算，不能互相挪用。撞伤人的赔偿很容易超过这些限额，超出的钱要你自己家掏，所以商业三者险要买够。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-27', '先存出 3 到 6 个月生活费的应急金，放在随时能取的地方', '为什么先存出 3 到 6 个月生活费的应急金，放在随时能取的地方？', '把 3 到 6 个月的生活费放在随时能取出来的地方。这样失业或者生病的时候，你就不用去借那种一年要付 18% 利息的钱，也不用亏着把手里的投资卖掉。存在银行里的钱有存款保险，同一家银行最高赔 50 万元。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-28', '提前还房贷之前先做一道比较题，不要凭感觉', '为什么提前还房贷之前先做一道比较题，不要凭感觉？', '提前还房贷，等于稳稳赚到你的房贷利率。所以只问一件事：你能长期稳定拿到的税后收益，比房贷利率高吗？高就别急着还，不高或说不准就还。等额本息前几年利息占得多，越早还省得越多。银行 App 的「提前还款试算」能直接算出数字。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-29', '网购认平台规则和法条，不认主播和「好评」', '为什么网购认平台规则和法条，不认主播和「好评」？', '商家骗你，按你付的价款三倍赔，不到 500 元的按 500 元算。平台明知卖家侵权还不管，要跟着一起赔。定金最多收合同金额的 20%，你违约定金不退，卖家违约要双倍退你。直播间刷单、刷好评要担责，大数据杀熟是明文禁止的。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-30', '直播间买的东西出了问题，先向平台要卖家和带货人的信息，平台必须给', '为什么直播间买的东西出了问题，先向平台要卖家和带货人的信息，平台必须给？', '直播间买东西出了问题，最常见的死结是你找不到该告谁。这时候你可以直接要求平台，提供直播间运营者和带货人的信息，以及相关的经营记录。平台必须给。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-31', '买到不安全的食品，除了退钱还能要十倍价款，增加赔偿不足一千元的按一千元算', '为什么买到不安全的食品，除了退钱还能要十倍价款，增加赔偿不足一千元的按一千元算？', '买到过期、变质的食品，东西本身、包装和小票就是你的证据，别急着扔。你可以要价款十倍或损失三倍的赔偿，不到一千元的按一千元算。找卖家还是找厂家由你挑，被你找上的那一方必须先赔，不许推给另一方。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-32', '买大件前先查国家抽检通报、3C 认证和能效标识', '为什么买大件前先查国家抽检通报、3C 认证和能效标识？', '2024 年国家抽检了 25250 批次产品，14.3% 不合格。电商渠道更差：抽了 7297 批次，23.5% 不合格；实体店是 15.1%。买大件之前花几分钟，查一下抽检通报，再查一下 3C 证书是不是真的。该贴能效标识的，不能缺。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-33', '手串、玉石、名表、潮玩按「花掉的钱」算账，不按「存下的钱」算', '为什么手串、玉石、名表、潮玩按「花掉的钱」算账，不按「存下的钱」算？', '这类东西的价钱里先含了一截消费税：每只 1 万元及以上的手表是 20%，金银铂金首饰和钻石是 5%，其他珠宝玉石是 10%，增值税另算。这笔税转手卖掉时拿不回来。真喜欢就当消费买，别算成理财。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-34', '珠宝玉石只认带 CMA 标志的检测报告，并到发证部门官网核一下这家机构', '为什么珠宝玉石只认带 CMA 标志的检测报告，并到发证部门官网核一下这家机构？', '证书能伪造，所以要查的是出证书的那家机构。检测机构对外出报告必须有资质，报告上要印 CMA 标志。发证部门会在官网公布机构名单，你自己就能查这家在不在上面。官方查处的案子里，随货的「国检证书」有自己找人做的。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-35', '盲盒、抽卡这类随机销售，按「这笔钱不会回来」算', '为什么盲盒、抽卡这类随机销售，按「这笔钱不会回来」算？', '商家必须把抽取规则、抽取概率、限量款数量摆在显眼处，不许后台操纵结果，不许设空盒。保底和花钱、抽取次数的上限，文件只是鼓励商家做。网上买的盲盒，商家讲清楚、你也确认过的，拆封后就不能七日无理由退货。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-36', '在意食品里加了什么，就买预包装的：散装柜台法律上不要求标配料表', '为什么在意食品里加了什么，就买预包装的：散装柜台法律上不要求标配料表？', '法律只要求预包装食品标配料表，散装的不要求。散装柜台只要标名称、生产日期、保质期和谁生产的。所以「没写添加剂」不等于「没加」，只等于法律没要求写。在意就买预包装的那一版，配料表和添加剂名称都印在上面。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-37', '亏了的股票也要按事先定好的规则卖掉，不靠往下补仓摊平成本翻身', '为什么亏了的股票也要按事先定好的规则卖掉，不靠往下补仓摊平成本翻身？', '人的本能是赚了就卖、亏了死扛。一万个美国账户七年的记录里，涨了的股票被卖掉的可能比跌了的高五成以上。同一批人还更爱给亏着的股票加仓。可他们留下的亏损股，后面一年平均还比卖掉的那些差 3.4 个百分点。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-38', '想买美股这类海外资产，走 QDII 基金或港股通，别去境外券商开户，也别拿每年的换汇额度去买', '为什么想买美股这类海外资产，走 QDII 基金或港股通，别去境外券商开户，也别拿每年的换汇额度去买？', '老虎、富途、长桥这类境外券商，2026 年 5 月起不许再给境内的人开户。已经开了的，两年内只能卖出、把钱转出来，不能再买。换汇额度也不许拿去买境外股票，违规的当年和之后 2 年都不能再用这个额度。想买海外资产，走 QDII 基金或港股通。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-39', '只给自己扛不住的损失买保险，扛得住的损失用应急金兜着', '为什么只给自己扛不住的损失买保险，扛得住的损失用应急金兜着？', '你交的保费不会全部赔回来，有一部分要付保险公司的费用和利润。所以值得买的，是很少发生、一旦发生家里掏不出来的损失，比如大病、开车撞伤人、家里挣钱的人走了。存款扛得住的小损失，交给应急金。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-40', '家里有人靠你的收入过日子，先给挣钱的人买定期寿险，别先给孩子买', '为什么家里有人靠你的收入过日子，先给挣钱的人买定期寿险，别先给孩子买？', '定期寿险只保固定的年数，这些年里人走了，家里拿到一笔钱。它是给靠你收入过日子的家人留的，比如房贷没还完、孩子还小。没人靠你养，就用不着。孩子不挣钱，给孩子买的死亡保险，法律还限了能赔多少。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-41', '签了一年以上的人身险又后悔，在犹豫期内退掉，保费基本全退', '为什么签了一年以上的人身险又后悔，在犹豫期内退掉，保费基本全退？', '一年以上的人身险都有犹豫期。在银行买的，是收到保单后 15 天，这期间退保最多扣 10 元工本费。过了犹豫期再退，只能拿回保单里能退的那部分钱，往往比交的少。保险公司打回访电话问你清不清楚，没弄懂就别说清楚。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-42', '在银行柜台签字前，先看清手里的是存款还是保险', '为什么在银行柜台签字前，先看清手里的是存款还是保险？', '银行能代卖保险，但不许说成存款。保险合同的封面要用大字印「保险合同」和保险公司的名字，不许出现「存款」「储蓄」字样。封面上是保险公司，这钱就不是存款，过了犹豫期再退会亏。65 岁以上的人在银行买，原则上只能买收益确定的。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-43', '想退保就自己找保险公司办，别找「代理退保」，觉得被误导了打 12378 投诉', '为什么想退保就自己找保险公司办，别找「代理退保」，觉得被误导了打 12378 投诉？', '网上喊「全额退保、不成功不收费」的，多半是非法代理退保。他们要拿走退回来的钱的三到五成，还要你的身份证、银行卡和验证码。退了保，保障也就没了。觉得被误导了，先找保险公司客服，谈不拢打 12378，全程免费。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-44', '保单上把受益人写成具体的人，出了事记得去领钱：寿险 5 年、其他保险 2 年内要主张', '为什么保单上把受益人写成具体的人，出了事记得去领钱：寿险 5 年、其他保险 2 年内要主张？', '没写受益人，或者受益人先走了，保险金就算遗产，要先拿去还去世的人欠的债。受益人写了「妻子某某」，后来离婚了，出事时算没写。家里人要知道有这张保单：寿险从知道出事起 5 年内要去主张，其他保险是 2 年。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-45', '别拿钱买比特币、泰达币这类虚拟货币，别人拉你一起投也不跟：交易不受法律保护，亏了打官司也要不回来', '为什么别拿钱买比特币、泰达币这类虚拟货币，别人拉你一起投也不跟：交易不受法律保护，亏了打官司也要不回来？', '国内不承认虚拟货币是钱，个人买币的交易可以被判无效，亏了算自己的。有人跟人买泰达币，付了约 44.8 万元，后来平台提不了现，起诉要钱被法院驳回。被人偷走的是另一回事，偷的人照样按盗窃罪判。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s5-46', '没单位的人自己交职工养老保险，按最低档交、先把年限交够最划算；别当成一交就赚，按最低档也要领约 10 年才回本', '为什么没单位的人自己交职工养老保险，按最低档交、先把年限交够最划算；别当成一交就赚，按最低档也要领约 10 年才回本？', '没单位的人自己交职工养老，按最低档交、把年限交够最划算。领的钱大头跟着退休那年当地的平均工资走。按那时的工资水平折算，最低档交 15 年、60 岁开始领，约领 10 年回本，往高档多交的部分要领约 17 年。值得交，但不是一交就赚。', 'finance', '5. 不要浪费钱', 'published', 1, 'reference_book', 95, '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-1', '不要为了长寿或防心血管病吃复合维生素', '为什么不要为了长寿或防心血管病吃复合维生素？', '1.4 万名男医生吃了十一年复合维生素。心脏和血管出大事的人、死掉的人，和不吃的一样多。把 9 项试验、5 万多人放一起看，对死亡也看不出影响。不买能省下一年两百到七百块。查出来确实缺某种营养的人、孕妇补叶酸，不在这条里面。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-2', '不要为了预防心血管病吃普通鱼油', '为什么不要为了预防心血管病吃普通鱼油？', '两项大试验分别找了 2.6 万人和 1.5 万名糖尿病患者。每天吃 1 克鱼油的人，心脏血管出大事的、死掉的，都和不吃的一样多。「吃鱼有好处」不等于「吃鱼油胶囊有好处」。不买能省下一年四百到一千块。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-3', '不要为了长寿给不缺维生素 D 的人补维生素 D', '为什么不要为了长寿给不缺维生素 D 的人补维生素 D？', '本来就不缺维 D 的人补上 5 年，得癌症、得心血管病和死亡的人数，都和不补的人一样。查出来确实缺的人、有骨质疏松的人、长期晒不到太阳的人不在这条里面，他们按医生说的补。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-4', '不要为了防癌吃抗氧化补剂（β 胡萝卜素、维生素 E、维生素 A）', '为什么不要为了防癌吃抗氧化补剂（β 胡萝卜素、维生素 E、维生素 A）？', '这一条不只是没用。78 项试验、近 30 万人合起来算，吃抗氧化补剂的人死亡率反而略高一点。两项专门找吸烟者做的大试验里，β 胡萝卜素让得肺癌的比例高了 18% 到 28%，死亡高了 8% 到 17%。吸烟的人、接触过石棉的人尤其别吃。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-5', '不要指望氨糖（葡萄糖胺）/软骨素治膝关节炎', '为什么不要指望氨糖（葡萄糖胺）/软骨素治膝关节炎？', '膝盖有骨关节炎的人吃 24 周假药，也有六成说没那么疼了。吃氨糖或软骨素的人只比这多出四五个百分点，小到可能只是碰巧。一年花七百到一千八，买到的基本就是那六成的心理作用。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-6', '不要靠维生素 C 预防感冒', '为什么不要靠维生素 C 预防感冒？', '天天吃维 C 基本不会让你少得感冒，感冒了才开始吃，效果也时有时无。天天吃能把一次感冒缩短约 8%，也就是少难受半天，值不值一年三五百自己算。马拉松选手和在寒冷地区行军的士兵是例外，他们吃了得感冒的人能少一半。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-7', '不要给没有症状的自己做「全身 PET-CT」或「肿瘤标志物套餐」', '为什么不要给没有症状的自己做「全身 PET-CT」或「肿瘤标志物套餐」？', '没症状的人去查，查出来最多的是虚惊一场。做全身 CT 的人八成多至少查出一处「异常」，将近四成被叫回去复查，可大多数是良性的。女性查卵巢癌标志物，死于卵巢癌的反而略多一点，还有人因为虚惊一场白做了一次手术。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-8', '不要指望手环/手表的运动量化帮你减重', '为什么不要指望手环/手表的运动量化帮你减重？', '超重的人做同样的饮食和运动安排，戴运动手环的人两年减了 3.5 公斤，不戴的人反而减了 5.9 公斤。想减重，花钱买设备帮不上忙，真正管用的是运动本身。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-9', '不要为了「更健康」花溢价买有机食品', '为什么不要为了「更健康」花溢价买有机食品？', '没有有力的证据说有机食品更有营养。真正看了人吃完以后健康怎么样的研究只有 3 项，都没看出差别。有机农产品被检出农药残留的比例确实低 30 个百分点，但检出不等于超标。多吃蔬菜水果本身有用，是不是有机的不影响这一点。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-10', '不要花大钱买保健品、膏方、滋补品来「调理身体」', '为什么不要花大钱买保健品、膏方、滋补品来「调理身体」？', '多维、鱼油、维 D 这些常见成分，本节前六条已经一样样查过，都没看出管用。包装上那句「保健食品不是药物，不能代替药物治疗疾病」，是管保健食品的部门规定必须印的。这笔钱多半是买给父母、提着上门的，那份心意没有问题，只是东西选错了。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-11', '不要在没有肠道问题时长期吃益生菌', '为什么不要在没有肠道问题时长期吃益生菌？', '45 项在健康成年人身上做的试验合起来看，吃益生菌不能让肠道里的菌长期变个样，停了就回到原样，血脂也没有改善。吃抗生素吃出腹泻这类特定情况另有证据，不在这条里面。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-12', '不要为了「增强免疫力」逼自己洗冷水澡', '为什么不要为了「增强免疫力」逼自己洗冷水澡？', '3018 人的试验里，洗冷水澡的人请病假的次数少了 29%，但请假的总天数和别人一样，所以谈不上少生病。2025 年把 11 项试验合起来看，冲完冷水之后，身体发炎的指标反而短暂升高，免疫的指标没变化。爱洗随便洗，只是别把它当成一笔健康投资。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-13', '不要买排毒、清肠、酵素、碱性水这类产品', '为什么不要买排毒、清肠、酵素、碱性水这类产品？', '排毒这个产业做得很大，可支持它的临床证据非常少，也没人拿市面上卖的排毒饮食认真做过试验。有人去查饮食酸碱、碱性水和癌症有没有关系，够格的研究只找到 1 篇，也没看出关联。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-14', '不要为了凑够「每天 8 杯水」强迫自己喝水', '为什么不要为了凑够「每天 8 杯水」强迫自己喝水？', '有人专门去追「每天 8 杯水」的出处，一项支持它的研究都没找到。食物和别的饮料里本来就带着大量水分，所以用不着喝那么多。渴了就喝，看看尿的颜色就够了。天热干活、剧烈运动、得过肾结石的人，还有不太觉得渴的老人，要另外主动喝。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-15', '不要花钱算命、看塔罗、看星座来做决定', '为什么不要花钱算命、看塔罗、看星座来做决定？', '有个经典的课堂实验：学生拿到的「个人性格分析」其实人手一份、一模一样，大家却普遍觉得很准。算命显得准，道理就在这里。占星师挑对的次数和瞎猜差不多。代价不只几十块：河南息县那个算命团伙，收香火钱和最高 3888 元的「供养套餐」，主犯判了十一年。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-16', '不要买防蓝光眼镜来「保护视力」，也不要相信「对着屏幕干几个月眼睛就废了」，但眼睛胀痛发红要当急症', '为什么不要买防蓝光眼镜来「保护视力」，也不要相信「对着屏幕干几个月眼睛就废了」，但眼睛胀痛发红要当急症？', '防蓝光镜片没用，不买能省下几百到上千的加价。和普通镜片比，戴它的人眼睛累不累、能看多清都没差别，也没找到它护眼底的证据。看屏幕看得眼酸眼干能缓过来，真正会把眼睛伤坏的是电焊弧光、紫外线、激光，还有青光眼急性发作。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-17', '不要把献血当保健：「排毒、降血脂、防心梗」没有随机试验支持，频繁献倒是真会缺铁', '为什么不要把献血当保健：「排毒、降血脂、防心梗」没有随机试验支持，频繁献倒是真会缺铁？', '说献血能排毒、降血脂、防心梗，靠不住。能一直去献血的人，本来身体就更好，把这层扣掉，每年多献一次血的死亡率降幅从近两成缩到 7.5%。真正把人分开对比的试验里，死亡人数没有差别。反过来，献得太勤确实会让人没力气、怕冷，原因是缺铁。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-18', '不要靠通用体检套餐防病，按年龄性别做那几项有证据的筛查', '为什么不要靠通用体检套餐防病，按年龄性别做那几项有证据的筛查？', '定期做通用健康检查的人，和不做的人死亡率一样，死于心血管病、癌症的也一样多。按年龄性别做那几项有证据的筛查就够了。35 岁以上每年能免费量一次血压，65 岁以上每年有一次免费体检。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-19', '不要因为体检查出尿酸高、但从没痛过，就开始吃降尿酸药', '为什么不要因为体检查出尿酸高、但从没痛过，就开始吃降尿酸药？', '尿酸超标、但从没发作过痛风也没长痛风石的人，美国风湿病学会建议先不吃降尿酸药。24 个人吃满 3 年，才拦得住一次痛风发作。想靠它护肾也落空了，吃药的人肾功能照样往下掉，和吃假药的一样快。真发作过了再治。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-20', '不要因为体检查出胆囊结石、但从没疼过，就去预防性切胆囊', '为什么不要因为体检查出胆囊结石、但从没疼过，就去预防性切胆囊？', '胆囊里有石头、但从没疼过的人，近九年里约八成一直没出症状。不动它，每年出胆囊炎、胰腺炎这类急症的约千分之一到千分之三。切胆囊也不是零风险，约 1.5% 的人胆管会被伤到。所以欧洲和英国的指南都说，没症状先不切。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-21', '不要为了防肾结石把钙戒掉', '为什么不要为了防肾结石把钙戒掉？', '长过草酸钙结石的人常被劝少吃钙，试验的结果正好反过来。反复长结石的男性正常吃钙、同时少吃动物蛋白和盐，五年里复发的人只有吃低钙饮食的一半。英国的指南也写明不要限制钙。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-22', '不要为了「转运」「招财」「养人」买水晶、手串、貔貅这类物件', '为什么不要为了「转运」「招财」「养人」买水晶、手串、貔貅这类物件？', '说戴了能改运、能招财、能养人，没有可以核查的证据。它和算命显得准是一个道理，话说得足够笼统，你会自己往身上套。商家把话说到治病的功效上就是虚假宣传，2026 年有直播间因此被查处。当装饰品买没问题。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-23', '不要指望买东西改善心情或身份感', '为什么不要指望买东西改善心情或身份感？', '把钱和物质看得越重的人，自己觉得越不幸福，但关联很弱，也分不出谁导致谁。还有研究发现，花钱买一段经历比买东西更让人快乐。所以心情差的时候，把钱花在一次出门、一顿和人吃的饭上，比塞满购物车更可能有用。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-24', '不要为了「在周围人里往上挪一档」多花钱换房、换车、换圈子', '为什么不要为了「在周围人里往上挪一档」多花钱换房、换车、换圈子？', '拿收入一样的人来比，邻居挣得越多，这个人报告的幸福感越低。这只发生在学历和自己相同、又常来往的邻居之间。所以为了搬进一个人人都比你宽裕的地方而多花的钱，买到的是把自己往下挪一档。但收入一起涨的时候，人还是觉得更好过，绝对水平仍然算数。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-25', '不要相信「意志力像肌肉，用一会儿就没了」', '为什么不要相信「意志力像肌肉，用一会儿就没了」？', '流行的说法是：先做一件费自控的事，接下来就更容易破功，所以要省着用意志力。23 个实验室、2141 人按同一套方案重做了这个实验，结果几乎是零。别再用「今天意志力用完了」解释自己，也别为此花钱买教你攒意志力的课。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-26', '不要指望吃早餐或 16:8 轻断食帮你控制体重，吃饭时间挑你能长期坚持的', '为什么不要指望吃早餐或 16:8 轻断食帮你控制体重，吃饭时间挑你能长期坚持的？', '流行说法是不吃早餐会让人午饭晚饭暴食，一天总量反而更多。试验里不是这样：不吃早餐的人一天少吃了两百多千卡，体重还略轻一点。16:8 和单纯少吃比，一年下来体重也没差别。长期不吃早餐的人心血管病确实多约一成七，总死亡率则看不出差别。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-27', '不要相信「手淫伤身」「戒色才能变好」，真正要看的是有没有耽误睡觉、工作和关系', '为什么不要相信「手淫伤身」「戒色才能变好」，真正要看的是有没有耽误睡觉、工作和关系？', '没有研究说手淫伤身。美国一项大研究反而看到，射精次数多的男性，前列腺癌少约两成。英国一项研究看到二三十岁时次数多的人风险偏高，所以两边都不能当成锻炼身体的理由。很多人觉得自己「看色情上瘾」，更多是因为这事和自己的道德观打架。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-28', '不要花钱做「性取向矫正」「同性恋治疗」，也不要把家里人送去', '为什么不要花钱做「性取向矫正」「同性恋治疗」，也不要把家里人送去？', '美国心理学会的专家组看完研究后说，这类矫正改不了性取向，还可能伤人。美国一项调查里，做过矫正的人有过自杀念头的多了近九成。国内有精神病院以「性偏好障碍」为名强制收治一名男子，被法院判侵权、赔 5000 元。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-29', '不要指望学会「正确搬运姿势」、上搬运培训就能防腰痛，要减的是搬的重量和次数，平时多锻炼', '为什么不要指望学会「正确搬运姿势」、上搬运培训就能防腰痛，要减的是搬的重量和次数，平时多锻炼？', '上过搬运姿势培训的工人，后来腰痛的并不比没上过的少。搬东西时腰弯得多的人，也没看出更容易腰痛。和腰痛有关的是搬得重、搬得多，每次多搬 10 公斤或每天多搬 10 次，风险高约一成。平时规律锻炼的人，腰痛发作少三成多到四成多。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s6-30', '不要指望骨折之后猛补钙、喝骨头汤能让骨头长得更快', '为什么不要指望骨折之后猛补钙、喝骨头汤能让骨头长得更快？', '骨折后补维生素 D 的试验，没有一项看出骨头长得更好。钙和维 D 一起补的研究很少，说不清有没有用。一大碗骨头汤里的钙，只有每天该吃的几十分之一。本来就缺维 D、有骨质疏松的人另说。', 'consumer', '6. 反面清单', 'published', 1, 'reference_book', 95, '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-1', '失业了先在线申领失业保险金', '为什么失业了先在线申领失业保险金？', '单位和你自己交满 1 年、又不是你主动提的辞职，办完失业登记就能领钱。交满 1 年不到 5 年，最多领 12 个月。满 5 年不到 10 年，最多 18 个月。10 年以上，最多 24 个月。领钱这段时间，职工医保有失业保险替你交。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-2', '被欠薪先投诉劳动监察，再申请劳动仲裁，两条路都不收费，多数案子几个月内有结果', '为什么被欠薪先投诉劳动监察，再申请劳动仲裁，两条路都不收费，多数案子几个月内有结果？', '两条路都不收钱。先打 12333 或者去人社局劳动监察投诉，立案后 60 个工作日内查完，能责令公司限期付钱，逾期不付还要多赔 50% 到 100%。再不行就申请劳动仲裁，45 天内结案。但「结案」不等于「到账」：公司没财产、老板跑了，赢了也可能拿不到钱。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-3', '打不起官司就申请法律援助，讨薪、赡养费、工伤这类案子本来就在范围内', '为什么打不起官司就申请法律援助，讨薪、赡养费、工伤这类案子本来就在范围内？', '讨薪、要赡养费、要社保或低保待遇、见义勇为受了损失，都能申请免费法律援助。打 12348，或者去当地的法律援助中心。现在不用回原籍开经济困难证明，本人如实说明就行。可能判死刑的，还有盲、聋、哑和未成年的被告人，一律指派律师。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-4', '走投无路时去救助站，管吃住和返乡车票', '为什么走投无路时去救助站，管吃住和返乡车票？', '救助站管吃、管住，生病了送医院，还帮你联系家里人。没钱回家的发车票。一般住不超过 10 天。自愿来、自愿走，不是收容，也不发现金。车票按户籍地或者住所地开，去之前先想清楚要回哪儿。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-5', '找活先用免费的公共就业服务和零工市场，不找收费中介', '为什么找活先用免费的公共就业服务和零工市场，不找收费中介？', '就业服务中心、人力资源市场这些公家机构，介绍工作、职业指导、政策咨询、办就业和失业登记，全都不收钱。法律还明文不许它们拿这些服务去赚钱。零工市场的登记和发布信息也免费。顺手把失业登记办掉，领失业金和认定就业困难人员都要用它。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-6', '突发变故先申请临时救助', '为什么突发变故先申请临时救助？', '家里突然出事，比如火灾、车祸、家人突发重病，把基本生活一时压垮了，就可以向乡镇政府或者街道办申请临时救助。不要求你已经是低保户。多是一次性发一笔，金额各地差别很大。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","B 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-7', '收入低于当地低保线就申请低保', '为什么收入低于当地低保线就申请低保？', '全家收入除以人数，低于当地低保线，家里财产也符合规定的，就可以申请。2024 年末，全国城市低保线平均每人每月 798.1 元，农村 593.9 元。批下来发的是低保线减去家里每人每月收入的差额。有房有车有存款，或者子女能赡养你，可能批不下来。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-8', '持残疾人证的去申请残疾人两项补贴', '为什么持残疾人证的去申请残疾人两项补贴？', '低保家庭里的残疾人，可以领生活补贴。残疾等级是一级、二级，又需要长期照护的，可以领护理补贴。两项能同时领。标准各省自己定，差别很大，具体问街道。带上第二代残疾人证，去街道或者乡镇办一次。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-9', '居民医保每年 400 元不要断，困难户可减免', '为什么居民医保每年 400 元不要断，困难户可减免？', '个人一年交 400 元起，财政再按人头补 700 元上下。特困人员全额资助，低保对象定额资助。断缴是有代价的：没在集中期参保、或者没连着交的，交完之后有 3 个月看病不给报，每多断 1 年原则上再多加 1 个月。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-10', '得了重病先走医保、大病保险、医疗救助和异地备案，不碰网贷', '为什么得了重病先走医保、大病保险、医疗救助和异地备案，不碰网贷？', '顺序是固定的。跨省住院前先在「国家医保局」公众号里备案，出院直接结算，不用先垫全款。报销完自己还掏不起的，向乡镇或者街道申请医疗救助。在职的按工龄有 3 到 24 个月医疗期，这期间公司不能辞你。网贷和民间高息借款不要碰。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-11', '身份证丢了立刻补办，急用先领临时身份证', '为什么身份证丢了立刻补办，急用先领临时身份证？', '补办的，从交表那天算起 60 天内发证。急用的，当场再申请一张临时身份证，3 天内发，有效期 3 个月。没有身份证，找工作、住宿、开户、领补贴全都办不成，它是所有手续的前提。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-12', '办失业登记后争取就业困难人员认定，拿社保补贴或公益性岗位', '为什么办失业登记后争取就业困难人员认定，拿社保补贴或公益性岗位？', '认定下来之后，自己交社保能拿补贴，原则上不超过你实际交的三分之二，最长 3 年。被单位招用、或者安排到公益性岗位的，单位那部分社保也有补贴。公益性岗位的工资参照当地最低工资。这类岗位钱不多，但带社保，适合过渡。社保补贴多是先交后补，得先垫钱。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-13', '失业期间去领职业培训补贴、就业见习补贴和社保补贴，别自费上培训班', '为什么失业期间去领职业培训补贴、就业见习补贴和社保补贴，别自费上培训班？', '培训不用自己掏钱。参加培训并拿到规定的证书，就有职业培训补贴，同一个人最多领 3 次。毕业两年内没找到工作的高校毕业生、16 到 24 岁的失业青年，可以参加就业见习，见习期间领基本生活费。先去当地人社局官网查「职业培训补贴目录」，别自费报班。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-14', '求职别只投简历，用系统方法：学技巧、定目标、找人帮', '为什么求职别只投简历，用系统方法：学技巧、定目标、找人帮？', '参加过求职辅导的人，找到工作的几率是没参加的人的 2.67 倍。管用的是这几样：学具体的求职技巧，把自己讲清楚，定明确目标，主动出击，开口找人帮忙。找人帮忙落到实处，就是托熟人内推。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-15', '不交押金、不押证件、不签「培训贷」、不进传销、不借高利贷', '为什么不交押金、不押证件、不签「培训贷」、不进传销、不借高利贷？', '用人单位不能扣你的身份证，不能收押金，也不能换个名目收钱。中介没给你介绍成工作，必须退中介费。先交培训费再上岗的培训贷、靠拉人头算钱的传销，都是官方点名的骗局。借钱的利息超过一年期 LPR 四倍的部分，法院不支持，但本金照还。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-16', '住房困难先排公租房', '为什么住房困难先排公租房？', '要同时占上三条：在本地没房，或者住房面积低于标准；收入和财产低于标准；外来务工的还要在本地稳定就业满规定年限。轮候期由当地公布。这是远水，解不了近渴，但排队不花钱，早报名早轮到。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-17', '把住和吃压到最低：合租月租代替日租，自炊和助餐食堂代替外卖', '为什么把住和吃压到最低：合租月租代替日租，自炊和助餐食堂代替外卖？', '2025 年全国人均消费里，吃占 29.3%，住占 21.7%，两项加起来过半，所以压这两项最有效。按作者的经验，日租房、钟点房折算到一个月，比合租贵；自己做饭比点外卖便宜。找工作时问清包不包吃住，包的岗位等于把这两大项抹掉。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-18', '社保断缴不要慌：养老按累计算，医保按规则补', '为什么社保断缴不要慌：养老按累计算，医保按规则补？', '养老金按累计年限算，不按连续年限算，断了不清零，到退休年龄累计满 15 年就能按月领。职工医保交够年限的，退休后不用再交，各地的年限不一样，打 12393 问参保地。真正受影响的是买房、落户、积分这些要求连续缴费的资格。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-19', '坐过牢、破过产、上过失信名单，法律上都有重来的路，先把手续走完', '为什么坐过牢、破过产、上过失信名单，法律上都有重来的路，先把手续走完？', '刑满释放的人，在就业、就学、社保上不得被歧视，生活困难的由政府帮助安置。犯罪时不满 18 岁、判 5 年以下的，记录封存，当兵找工作不必报告。失信名单的期限是 2 年，钱还清了法院应在 3 个工作日内删名。成年人的前科不封存，当兵、就业时要如实报告。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-20', '大病之前，基本医保之外配一份一年期医疗险或重疾险，看清「保证续保」四个字', '为什么大病之前，基本医保之外配一份一年期医疗险或重疾险，看清「保证续保」四个字？', '这类保险补的是医保报完之后你自己要掏的那部分，还有停工的损失。买之前认准「保证续保」四个字：没有这四个字的，明年可能停售或者涨价。健康状况要如实告知，瞒了会被拒赔。先把基本医保交上，再考虑这条。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-21', '实在没地方睡，24 小时营业场所只能应急一晚，优先去救助站', '为什么实在没地方睡，24 小时营业场所只能应急一晚，优先去救助站？', '机场、火车站的候车区能撑一夜，有厕所也有电源。但没有任何官方数据说这样安全。财物贴身放好，不接陌生人递的吃喝，别去偏僻角落。桥洞、河边、工地夜里不能睡。救助站免费管吃住，优先去那儿。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","C 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s7-22', '被欠了工钱，先分清雇你的是谁：没执照的作坊和包工头照样找劳动监察，给家庭或个人干私活才去法院', '为什么被欠了工钱，先分清雇你的是谁：没执照的作坊和包工头照样找劳动监察，给家庭或个人干私活才去法院？', '没办执照的作坊、店铺，欠了工资照样能投诉劳动监察、申请劳动仲裁，老板本人也能被追。包工头转包工地上的活欠了钱，由总包或建设单位来付。只有给家庭或个人干私活，比如当保姆，才不算劳动争议，要去法院起诉。', 'living', '7. 没钱的时候怎么活', 'published', 1, 'reference_book', 95, '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-1', '出了交通事故先停车、救人、报警，不要跑', '为什么出了交通事故先停车、救人、报警，不要跑？', '跑了，这起事故就默认算你全责。驾照吊销，这辈子都不能再考。还有更现实的一层：车损险和三者险对逃逸一律不赔，几十万的赔偿全要自己掏。留在现场救人、报警，最多耗掉一两个小时。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-2', '发现被骗，立刻打 110 或 96110 要求止付，别先自己查', '为什么发现被骗，立刻打 110 或 96110 要求止付，别先自己查？', '钱刚转出去的那一小段时间，是唯一的窗口。这段时间警方可以紧急止付、快速冻结，银行必须配合。等钱被层层转走、分散开，就基本追不回来了。所以先打 110 或者 96110，别自己先去查、先去问。96110 打进来的是警察在劝阻你，要接。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-3', '记住反诈硬规则：来电不轻信、信息不透露、链接不点击、转账多核实，七种最常见的骗局都是这个形状', '为什么记住反诈硬规则：来电不轻信、信息不透露、链接不点击、转账多核实，七种最常见的骗局都是这个形状？', '凡是让你转账、共享屏幕、下载陌生 App、点链接、报验证码的，先挂断，再用官方号码打回去核实。刷单返利、虚假投资理财、网络贷款、冒充客服、冒充公检法、杀猪盘、色诱刷单这七类最常见，都是要你先转钱。事前认出来，比事后追钱便宜得多。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-4', '视频里看见脸、电话里听见声音都不算核实，涉及转账先挂断，用自己通讯录里的旧号码打回去', '为什么视频里看见脸、电话里听见声音都不算核实，涉及转账先挂断，用自己通讯录里的旧号码打回去？', '看见脸、听见声音，都不算核实。只要涉及转账就先挂断，再用自己通讯录里存的旧号码打回去，或者找共同认识的人问一句。对方说「信号不好」「在开会」，不肯当面视频，直接当骗局处理。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-5', '被指控或被传唤，先请律师，不私了、不删记录', '为什么被指控或被传唤，先请律师，不私了、不删记录？', '被叫去问话的第一次，你就可以请律师了。律师要求见你，看守所最迟 48 小时内安排，谈话不会被听。跟这个案子无关的问题，你可以不答。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-6', '出了事主动去说清楚：自首最多能减四成刑，「躲过追诉期」这条路是堵死的', '为什么出了事主动去说清楚：自首最多能减四成刑，「躲过追诉期」这条路是堵死的？', '自首最多能把刑期减掉四成，情节较轻的可以直接不罚。被找上门之后才如实交代，最多也能减两成。跑掉、拒不承认，这些都换不来。指望躲几年让案子过期也不成立：已经立案的，你躲着的这段时间不算进追诉期限。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-7', '喝了酒就不碰方向盘，包括电动车和「挪一下车」', '为什么喝了酒就不碰方向盘，包括电动车和「挪一下车」？', '酒后开车，扣证 6 个月，罚一两千。再犯就拘留加吊销。醉驾直接吊销，5 年内不能重考，还要按危险驾驶罪追刑责，留下案底，影响政审和一部分职业。保险也不管：喝了酒开车，车险一律不赔。「就挪一下车」也算驾驶。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-8', '不把银行卡、手机卡、支付账号借给任何人，「跑分」不是兼职', '为什么不把银行卡、手机卡、支付账号借给任何人，「跑分」不是兼职？', '把银行卡、手机卡、支付账号租给、借给、卖给别人，这件事本身就违法。罚违法所得的 1 到 10 倍，没有所得的最高罚 20 万元，情节严重的拘留 15 日，还会被记入信用记录、限制账户功能。要是明知对方拿去犯罪还帮着收钱转钱，就是帮信罪，判 3 年以下。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-9', '每年免费查两次自己的征信报告，看有没有不是自己办的贷款和卡', '为什么每年免费查两次自己的征信报告，看有没有不是自己办的贷款和卡？', '你每年可以在网上免费查两次自己的信用报告，十分钟就能查完。用人民银行征信中心官网或者手机银行查，别用第三方的「查征信」App，那类 App 在收集你的信息。不良记录从这件事结束那天起留 5 年，过了就该删。有异议可以提，20 天内必须书面答复你。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-10', '起了冲突先报警不动手，先动手的那个几乎一定吃亏', '为什么起了冲突先报警不动手，先动手的那个几乎一定吃亏？', '打人，拘留 5 到 10 日，罚五百到一千。结伙打、打老人孕妇孩子残疾人、多次打人，拘留 10 到 15 日，罚一两千。打成轻伤就是刑事案件，判 3 年以下，重伤判 3 到 10 年。两个人对着打不算正当防卫，先动手的那个几乎一定吃亏。退到人多的地方报警，比还手管用。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-11', '躲不掉的侵害可以还手，但只打正在动手的那个人，他停你就停', '为什么躲不掉的侵害可以还手，但只打正在动手的那个人，他停你就停？', '对方正在侵害你或者别人的时候，你动手制止、把他打伤，不负刑事责任。对方正在行凶、杀人、抢劫、强奸、绑架，打伤打死也不算过当。但只能打正在动手的那个人，他停你就停。最后认定站你这边，你也可能先被立案、先被关上几天。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-12', '跟谁结了怨——被欠薪、被开除、被坑了钱——走投诉、仲裁、起诉，别去找人算账', '为什么跟谁结了怨——被欠薪、被开除、被坑了钱——走投诉、仲裁、起诉，别去找人算账？', '走法定路径，最坏的结果是钱要不回来。去报复，结果是钱照样要不回来，还要自己抵命。无锡那起案子：徐某金没拿到毕业证、又不满实习报酬，持刀行凶致 8 死 17 伤，判死刑并已执行。欠薪走投诉和仲裁，2024 年全国靠这条给 65.4 万人追回了 86.5 亿元。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-13', '再恨也别对不相干的人下手：驾车冲撞人群、在公共场所行凶按以危险方法危害公共安全定罪，起刑三年，死了人就是死刑', '为什么再恨也别对不相干的人下手：驾车冲撞人群、在公共场所行凶按以危险方法危害公共安全定罪，起刑三年，死了人就是死刑？', '驾车冲撞人群、在公共场所行凶，按以危险方法危害公共安全定罪。一个人都没伤着，也是三年起。死了人就是十年以上、无期或者死刑。珠海那起：樊维秋不满离婚财产分割，开车冲进体育中心正在锻炼的人群，致 35 死 43 伤，判死刑并已执行。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-14', '冒出「拉个垫背的」「同归于尽」这种念头，当急症处理：离开现场，把车钥匙和刀交给别人，打 12356', '为什么冒出「拉个垫背的」「同归于尽」这种念头，当急症处理：离开现场，把车钥匙和刀交给别人，打 12356？', '这类念头从冒出来到动手，窗口很短。82 个自杀未遂的人里，47.6% 说从第一次起念到动手不超过 10 分钟。所以要做的不是「想通」，而是先把方向盘、刀、燃气阀、绳子和自己隔开一步，把这十分钟熬过去。然后打 12356。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-15', '身边人说出「谁也别想好过」「带着孩子一起走」，别当气话：近亲属可以直接送诊，公安接到报警也必须管', '为什么身边人说出「谁也别想好过」「带着孩子一起走」，别当气话：近亲属可以直接送诊，公安接到报警也必须管？', '家里人说出「谁也别想好过」「带着孩子一起走」，近亲属可以直接把他送去医院，医院不得拒绝诊断。已经动过手、或者眼看要出事的，住院不需要本人同意。分不清是气话还是真的，先打 12356 问，或者报 110 让警察到场。替他瞒着不算帮他。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-16', '网上不骂人、不造谣、不转发没核实的事；被网暴先留证再报警', '为什么网上不骂人、不造谣、不转发没核实的事；被网暴先留证再报警？', '公开骂人或者造谣诽谤，拘留 5 日以下，或者罚 1000 元以下，情节较重的拘留 5 到 10 日。情节严重就构成侮辱罪、诽谤罪，判 3 年以下。转发不免责。反过来，你被网暴时，侮辱诽谤原则上要你自己去法院告，所以截图、录屏、存链接只能靠你自己。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-17', '签字前把纸看完，不替人签字，不在空白纸上签', '为什么签字前把纸看完，不替人签字，不在空白纸上签？', '签了就算数，按手印和签名一样算数。「没看清」「以为是别的」在法庭上基本站不住。所以多花几分钟从头读到尾，看不懂的当场问，拍照留底。不替别人签，不在空白纸上签，身份证复印件写清用途。电子签和刷脸确认，同样算签字。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-18', '借钱写清借条，替人担保前先想清楚自己愿不愿意替他还', '为什么借钱写清借条，替人担保前先想清楚自己愿不愿意替他还？', '借条要写全：出借人、借款人、金额、利率、期限、还款方式，双方签名。钱走转账，不给现金，写全了才好起诉。替人担保时看清有没有「连带」两个字。一般保证是等债权人先告了借款人、执行不到钱，才轮到你。写了连带责任保证，债权人可以直接找你要。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-19', '维权有期限：民事诉讼时效 3 年，劳动仲裁 1 年，过了对方一句「超过时效」就够', '为什么维权有期限：民事诉讼时效 3 年，劳动仲裁 1 年，过了对方一句「超过时效」就够？', '民事诉讼时效 3 年，从你知道权利受损那天算起。过了期，法院不会主动管，可对方在法庭上说一句「超过时效」就够了，钱还在，只是要不回来。而一条留了痕迹的催款消息，就能让这 3 年从头重算。劳动争议是另一套，仲裁时效 1 年。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-20', '被起诉、被执行了，如实报财产、能还多少还多少，别把房和钱转给亲友或公司', '为什么被起诉、被执行了，如实报财产、能还多少还多少，别把房和钱转给亲友或公司？', '把房子挂到公司名下、把钱转给亲友，正是拒执罪写明的情形，判 3 年以下，情节特别严重的判 3 到 7 年。帮着藏钱过户的亲友和公司按同伙算，钱照样追回。拒绝报告或者虚报财产，个人可罚 10 万元以下、拘留 15 日。真没钱不构成这个罪。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-21', '被限制消费或者被列入失信名单，先查清是按哪一条纳入的，能纠正的申请纠正', '为什么被限制消费或者被列入失信名单，先查清是按哪一条纳入的，能纠正的申请纠正？', '先弄清自己是被限制消费，还是进了失信名单，这是两件事。失信名单只有六种情形能纳入，期限 2 年。已经履行完毕等七种情形，法院应当 3 个工作日内删除。限高禁九类消费，坐 G 字头高铁也算。生活或者经营必需的，可以一次一申请。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-22', '网购、二手交易被骗，先平台投诉，再报警，再算值不值得起诉', '为什么网购、二手交易被骗，先平台投诉，再报警，再算值不值得起诉？', '先找平台。平台有保证金和处罚规则，处理最快。再报警：被骗 3000 元以上就够诈骗罪的立案线，不够刑事标准的按治安处罚，拘留 5 到 10 日。要打官司的，网购纠纷可以在收货地法院起诉，金额小的走小额诉讼，2 个月内审结，网上就能立案。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-23', '恋爱和婚内的大额赠与，交付之前想清楚，交付之后原则上要不回', '为什么恋爱和婚内的大额赠与，交付之前想清楚，交付之后原则上要不回？', '钱一交出去，原则上就要不回来了。送出去的东西，只有在过到对方名下之前才能随便撤销。过户完成之后，只有对方严重侵害你或者你的近亲属、该扶养你却不扶养、不履行约定义务这三种情形才撤得掉。所以大额转账之前先想清楚，这是借还是送。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-24', '彩礼走转账并备注，聊天记录留好；借婚姻要钱可以要回', '为什么彩礼走转账并备注，聊天记录留好；借婚姻要钱可以要回？', '借婚姻索取财物是法律禁止的，法院支持返还。没登记的、登记了但确实没共同生活的、婚前给了彩礼导致给钱一方生活困难的，可以要求返还。已登记又共同生活的一般不返还。所以彩礼、三金、改口费都走转账并备注用途，谁给的钱谁留证据，男女一样。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-25', '婚前财产不用怕，房子加名和父母出资先写清楚', '为什么婚前财产不用怕，房子加名和父母出资先写清楚？', '婚前的财产是你个人的，不会因为结婚年头长就变成共同财产。夫妻可以书面约定婚前婚后的财产各归各的。要留意一点：说好把房子加上对方的名，在变更登记之前还能反悔，登记完就是对方的了。离婚时藏钱、转移、挥霍或者伪造债务的一方，可以少分或者不分。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-26', '结婚前核对对方婚姻状况，以结婚为幌子骗钱的按诈骗罪追究', '为什么结婚前核对对方婚姻状况，以结婚为幌子骗钱的按诈骗罪追究？', '重婚的婚姻无效。有配偶还去结婚，或者明知对方有配偶还跟他结婚的，判 2 年以下。以结婚为幌子骗钱的，按诈骗罪追究：数额较大判 3 年以下，巨大判 3 到 10 年，特别巨大判 10 年以上或者无期。登记前看一眼对方身份证和户口簿上的婚姻状况。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-27', '上门维修、验车、装修，先问价再动手，全程在旁边看着', '为什么上门维修、验车、装修，先问价再动手，全程在旁边看着？', '家电维修必须明示收费标准，给维修凭证和发票，不得虚报故障，不得故意换掉性能正常的零件，情节严重的罚 3 万元以下。所有经营者都必须明码标价，不得在标价之外加价。所以动手前问清价钱和要换的件，修完要凭证和发票，旧件留下。被多收了先打 12315。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-28', '别当「挂名法人」，别把身份证借给人注册公司', '为什么别当「挂名法人」，别把身份证借给人注册公司？', '法律预设法定代表人就是那个管事的人，「我只是挂个名、什么都不知道」不是免责的理由。法定代表人执行职务给别人造成损害，公司先赔，赔完可以回头找有过错的你追偿。已经挂了名的，公司法允许你辞掉，公司要在 30 日内定出新的法定代表人。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-29', '出入境不帮陌生人带东西，不代收来路不明的包裹', '为什么出入境不帮陌生人带东西，不代收来路不明的包裹？', '外交部领事司给出国公民的建议是：不要替别人携带行李物品，特别是违禁品，或者你并不了解的东西。行李里真查出毒品或者走私品，「我不知道里面装的什么」要你自己举证。国内代收快递也一样，尤其是让你先垫钱、事后退款的。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-30', '养狗必须牵绳：不牵绳出了事是无过错责任（你有没有错都要赔），赔到底', '为什么养狗必须牵绳：不牵绳出了事是无过错责任（你有没有错都要赔），赔到底？', '狗伤了人，原则上不管你有没有错都要赔。只有能证明是对方故意或者有重大过失，才可能少赔或者不赔。而如果你违反规定没牵绳，就只剩「被侵权人故意」这一条能减轻，不牵绳等于把唯一的退路也堵死。禁养的烈性犬伤了人，没有任何免责的理由。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-31', '对方喝到意识不清、睡着，或者可能不满 14 岁，就不要发生关系', '为什么对方喝到意识不清、睡着，或者可能不满 14 岁，就不要发生关系？', '对方喝到意识不清或者睡着，就没有能力表示同意，这时发生关系法律上也算强奸，基本刑是 3 到 10 年。事后你几乎无法证明对方当时同意。唯一可靠的做法是不发生关系，酒局散场把人交给对方自己的朋友或者家人。年龄的认定见第 9 节第 18 条（不满 14 岁）。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-32', '发生关系、裸聊之后对方拿报警、发照片、告诉你单位来要钱，一分钱不给，一条记录不删，直接报警', '为什么发生关系、裸聊之后对方拿报警、发照片、告诉你单位来要钱，一分钱不给，一条记录不删，直接报警？', '拿「我去报警」「把照片发给你单位」要挟你给钱，是敲诈勒索。一分钱不给，一条记录不删，当场报警，给了第一笔就会有第二笔。对方真把照片发出去，是他多一条罪。敲诈 2000 到 5000 元以上就判 3 年以下，3 万到 10 万以上判 3 到 10 年。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-33', '被人捏造事实举报，可以要求追究：够治安处罚的拘留 5 日起，够罪的判 3 年以下', '为什么被人捏造事实举报，可以要求追究：够治安处罚的拘留 5 日起，够罪的判 3 年以下？', '捏造事实诬告陷害别人，想让他被追究刑责或者被治安处罚，本身就是违法。这种要拘留 5 日以下，或者罚 1000 元以下。情节较重的，拘留 5 到 10 日。够得上犯罪的是诬告陷害罪，判 3 年以下。但记错了、告错了不算，要追究对方，你得证明他是有意诬陷。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-34', '证据不足本来就应当判无罪，逼出来的口供应当排除；判了还有申诉和再审', '为什么证据不足本来就应当判无罪，逼出来的口供应当排除；判了还有申诉和再审？', '定罪的门槛写在刑事诉讼法里：定案的证据要经过法定程序查证属实，还要综合全案证据排除合理怀疑。做不到，就应当判无罪。刑讯逼供得来的口供、暴力威胁得来的证言，都应当排除，不能作为判决的依据。判决生效之后，你和你的法定代理人、近亲属还可以申诉。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-35', '被羁押后撤案、不起诉或者判无罪的，去申请国家赔偿，按天算钱', '为什么被羁押后撤案、不起诉或者判无罪的，去申请国家赔偿，按天算钱？', '被拘留、逮捕后又撤案、不起诉或判无罪的，能申请国家赔偿。被关的日子按天赔，2026 年 5 月 18 日起每天 495.94 元，一年约 18 万元。后果严重的另给精神损害抚慰金。犯了事只因情节轻微不起诉的，不赔。过了追诉期、没到年龄、自己作假口供的也不赔。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-36', '自己是受害人去索赔，走 12315、起诉或者律师，别单独赴对方的约，别把「给钱」和「我不曝光」绑成一句话', '为什么自己是受害人去索赔，走 12315、起诉或者律师，别单独赴对方的约，别把「给钱」和「我不曝光」绑成一句话？', '自己是受害人，向侵权方索赔，本身有法律依据，不会因为「要价高」就自动变成敲诈勒索。但代价可能很大：郭利先被以敲诈勒索罪判了五年，后来才再审宣告无罪。所以走留痕的渠道，别单独去对方指定的地方谈，别把「给钱」和「我就不曝光」绑成一个条件说出口。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-37', '被网暴了：先开防护、先固证，再在平台、禁令、报警三条路里挑', '为什么被网暴了：先开防护、先固证，再在平台、禁令、报警三条路里挑？', '当场先做三件事：打开平台的防护设置，用快捷取证把内容存下来，再从快捷入口举报。之后可以向法院申请禁令，让他先停手。也可以自己去法院告，取证难可以请公安协助。后果特别严重、影响又恶劣的，由检察院起诉，不用你自己举证。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-38', '「先给人买保险再动手」这条路法律上从头堵死：钱一分拿不到，罪按故意杀人加保险诈骗数罪并罚', '为什么「先给人买保险再动手」这条路法律上从头堵死：钱一分拿不到，罪按故意杀人加保险诈骗数罪并罚？', '四道门都是关着的。背着家人给他买以死亡为条件的保险，合同无效。投保人故意造成被保险人死亡的，保险公司不赔。故意杀害被继承人的，丧失继承权。刑法还把这种骗保单列一项，和故意杀人罪数罪并罚，最高死刑。钱一分拿不到。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-39', '报警当场要受案回执，不立案要书面通知：7 日内可申请复议，再 7 日可申请复核，检察院能通知公安立案', '为什么报警当场要受案回执，不立案要书面通知：7 日内可申请复议，再 7 日可申请复核，检察院能通知公安立案？', '报了警要当场拿到受案回执，这是你报过案的唯一凭据。公安决定不立案，应当给你书面的不予立案通知书。不服可以 7 日内申请复议，还不服再 7 日内申请复核。你也可以找检察院，请它监督公安立案。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-40', '别给办案、执法的人送钱送卡：行贿自己也判，对监察、执法、司法人员行贿还要从重', '为什么别给办案、执法的人送钱送卡：行贿自己也判，对监察、执法、司法人员行贿还要从重？', '「花点钱把事摆平」在刑法里是独立的罪，被抓的不只是收钱那个人。行贿判 3 年以下。情节严重的判 3 到 10 年，特别严重的判 10 年以上或者无期。对监察、行政执法、司法人员行贿，还是明文从重的那一档。被勒索给了钱、又没拿到不正当利益的，不算行贿。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-41', '可能翻脸的电话和面谈，直接开录音：自己参加的谈话，不用先征得对方同意', '为什么可能翻脸的电话和面谈，直接开录音：自己参加的谈话，不用先征得对方同意？', '借钱、欠款、赔偿、退款、劳动纠纷，电话里说清楚了却没留下东西，几个月后双方就可能各说一套。你自己参加的谈话可以录下来，没提前告诉对方，不会单凭这一点就不能当证据。不能干的是窃听、偷窥别人隐私、闯进别人家里偷录，或者威胁对方说话。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-42', '现场出了事，先拍全景，再拍位置关系，最后拍损坏和伤情，原图原视频别删', '为什么现场出了事，先拍全景，再拍位置关系，最后拍损坏和伤情，原图原视频别删？', '只对着车上一道划痕或者地上一件东西拍特写，过几天没人知道它原来在哪。先拍一段全景，把路口、门牌、车、人和周围都收进去，再拍相互位置，最后拍细节。要挪动东西或者车，能先拍就先拍。原图原视频留在手机里，别只存一份聊天软件里转过的。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-43', '被家暴了：先报警留下出警记录，再去法院申请人身安全保护令，不用先离婚，也不收费', '为什么被家暴了：先报警留下出警记录，再去法院申请人身安全保护令，不用先离婚，也不收费？', '在全世界被杀害的女性里，三分之一以上是伴侣下的手，往往是长期家暴的结局。同样挨打的女性里，被掐过脖子的，后来被杀的几率是没被掐过的 7 倍多。所以挨了打就报警，再去法院申请保护令。法院一般 72 小时内就要给答复。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-44', '家里人赌博欠了债，别急着替他还：赌债法律不保护，为赌借的钱也不算夫妻共同债务', '为什么家里人赌博欠了债，别急着替他还：赌债法律不保护，为赌借的钱也不算夫妻共同债务？', '在赌桌上欠的钱，法院不保护。债主明知他借钱去赌还借给他，这笔钱法院也不保护。一方为了赌博借的钱，不能算成两口子一起还的债。没经过审判，法院不能让没借钱的一方替他担责任。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-45', '熟人让你「帮忙刷个脸、做个见证」去办贷款，或者要你念验证码，别答应：这叫 AB 贷，借款人是你，不是担保人', '为什么熟人让你「帮忙刷个脸、做个见证」去办贷款，或者要你念验证码，别答应：这叫 AB 贷，借款人是你，不是担保人？', '所谓「帮忙刷个脸、做个见证」，其实是用你的名字向银行借钱。借款人是你，不是担保人，钱转给熟人以后，银行照样找你还。中介骗了你，但只要银行不知情，这份借款合同你就撤不掉。熟人写给你的「我来还」承诺书，也管不到银行。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s8-46', '给门窗装好锁、门外装一盏感应灯，出门真的锁上：防入室盗窃靠这几样，单装一个报警器看不出用', '为什么给门窗装好锁、门外装一盏感应灯，出门真的锁上：防入室盗窃靠这几样，单装一个报警器看不出用？', '英国的数据显示，门锁加窗锁的人家，被人进屋偷东西的几率只有什么都没装的十二分之一。再加一盏门外感应灯，降到三十多分之一。只装一个报警器、别的都不装，看不出能防盗。这管的是盗窃，不管有人在家的抢劫。', 'legal', '8. 别把自己搭进去：法律与财产安全', 'published', 1, 'reference_book', 95, '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-1', '群里不转发不知真假的灾情、疫情、警情消息，不 P 图、不用 AI 造现场图', '为什么群里不转发不知真假的灾情、疫情、警情消息，不 P 图、不用 AI 造现场图？', '一条灾情、疫情、警情的消息，你明知是假的还转出去，罚得和自己编一样重。不是你编的也一样：拘留 5 到 10 日，还要罚 1000 元。把社会秩序搅乱了判 3 年以下，造成严重后果判 3 到 7 年。P 图、AI 做的假现场图，都算自己编。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-2', '不发、不转侮辱英烈的图片、表情包和评论，不拿国旗国歌开玩笑', '为什么不发、不转侮辱英烈的图片、表情包和评论，不拿国旗国歌开玩笑？', '拿英烈、国旗、国歌开玩笑，轻的拘留 5 到 10 日，或者罚 1000 到 3000 元。重一些的拘留 10 到 15 日。构成犯罪的判 3 年以下。有人在 499 人的村民微信群里发了 2 条诋毁袁隆平的话，判管制 6 个月，人没关进去，但行动受限制。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-3', '境外网站上的东西看完就关，不截图、不转发、不搬进群里，也不在评论区跟着说', '为什么境外网站上的东西看完就关，不截图、不转发、不搬进群里，也不在评论区跟着说？', '这些法条罚的是往外传，不罚看。你转发、搬进群、在评论区跟着说，办案时都算传播。传到煽动颠覆、煽动分裂这一档，判 5 年以下，带头的 5 年以上。恐怖主义、极端主义的书和音视频是例外，明知还存在手里，情节严重的就判 3 年以下。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-4', '黄色视频自己看归自己，别往群里发、别卖「资源」、别建群', '为什么黄色视频自己看归自己，别往群里发、别卖「资源」、别建群？', '自己看不在处罚条款里。往群里发一次就算向全群传播，拘留 10 到 15 日，再罚 5000 元以下，情节严重的判 2 年以下。卖「资源」挣钱的判 3 年以下，最重到无期。建 30 人以上的传播群，建群的、当管理员的、主要往里发的，都按犯罪算。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-5', '「兼职」要你用自己的卡收钱、取现、转账，不管给多少好处费都不做', '为什么「兼职」要你用自己的卡收钱、取现、转账，不管给多少好处费都不做？', '这类兼职挣的是几百块，代价是留一份案底。有人带着身份证和 1 张银行卡去指定地点，配合转账取款，挣了 500 多元。检察院没起诉他，公安还是拘留 10 日、罚 1000 元。另一人把自己和别人的银行卡、手机卡交给团伙收款取现，判 2 年 3 个月，罚 2.2 万元。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-6', '有人拉你去「包装材料」贷款、按贷款额分你好处费，一个都不做', '为什么有人拉你去「包装材料」贷款、按贷款额分你好处费，一个都不做？', '帮人「包装材料」去贷款、拿分成，按诈骗办。有个 126 人的团伙，把没工作的人包装成「优质客户」，在 80 多家银行骗贷 3000 多万元。出面签字的按贷款额拿三成好处费，已判的 80 人里 76 人判了 1 年 4 个月到 6 年 6 个月。钱贷在谁名下，债就是谁的。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-7', '捡到银行卡不取钱，捡到手机、钱包联系失主或交给警察，不揣走', '为什么捡到银行卡不取钱，捡到手机、钱包联系失主或交给警察，不揣走？', '捡到东西留着自己用，金额到了「数额较大」又不肯交出来，判 2 年以下，数额巨大的判 2 到 5 年。拿捡来的银行卡去 ATM 取钱更重，算冒用别人的信用卡，数额较大就判 5 年以下，还要罚 2 万到 20 万元。取钱这一种警察直接立案，不用失主自己去告。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-8', '优惠用自己的真实身份领，不买虚拟号批量注册小号，不靠漏洞重复领', '为什么优惠用自己的真实身份领，不买虚拟号批量注册小号，不靠漏洞重复领？', '用自己的真实身份、一个号领一次券，不在处罚范围里。批量注册假用户、自己下单自己接单去多领，按诈骗办，骗到 3000 元就能判 3 年以下，3 万元起判 3 到 10 年。有骑手用 0.1 元一个的虚拟号刷券，套现 9 万余元，同案 12 人都被判了刑。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-9', '阳台、窗户不往外扔任何东西，烟头、垃圾袋、酒瓶都算', '为什么阳台、窗户不往外扔任何东西，烟头、垃圾袋、酒瓶都算？', '往楼下扔东西，没砸到人也能拘留 5 日、罚 1000 元，情节严重的拘留 10 到 15 日。砸到人就换罪名了：有人在 21 楼酒后把空酒瓶、玻璃杯扔到楼下操场，砸中 13 岁学生致重伤，判 10 年。还有人从 32 楼扔 8 块砖头砸死 1 人，2024 年被核准死刑。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-10', '不网购仿真枪、钢珠枪、气枪，不买来路不明的「玩具枪」', '为什么不网购仿真枪、钢珠枪、气枪，不买来路不明的「玩具枪」？', '网上买的钢珠枪、气枪，枪口比动能到了 1.8 焦耳/平方厘米，就按枪支认定。没有许可拿在手里，判 3 年以下，情节严重的判 3 到 7 年。有对夫妇卖「玩具枪」，43 支里有 18 支被鉴定为枪，只因证明不了他们知情才没被起诉。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-11', '买了无人机先实名登记，机场、军事区和城市管制空域不飞，不破解限高', '为什么买了无人机先实名登记，机场、军事区和城市管制空域不飞，不破解限高？', '没实名登记就飞，罚 200 元以下，情节严重的罚 2000 到 2 万元。没批准在管制空域飞，罚 500 元以下，情节严重的没收无人机，再罚 1000 到 1 万元。情节较重的还能拘留 5 到 10 日。有人花钱破解限高，飞到近 3000 米拍云层发到网上，被拘留 5 日。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-12', '不偷拍别人，不在出租屋、民宿、酒店房间装摄像头', '为什么不偷拍别人，不在出租屋、民宿、酒店房间装摄像头？', '偷拍、偷窥、散布别人的隐私，拘留 5 日以下或者罚 1000 元以下，情节较重的拘留 5 到 10 日。用专门的偷拍设备、造成严重后果的，判 2 年以下。有两人在三家酒店的房间装器材远程偷拍，分别判了 1 年 3 个月和 1 年。家里装监控不算，装在别人住的房间就算。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-13', '麻将、扑克可以打，不抽头、不当庄、不组局收钱，不玩网络赌博', '为什么麻将、扑克可以打，不抽头、不当庄、不组局收钱，不玩网络赌博？', '亲友之间小额打牌，法律不管。从局里抽头、当庄、组局收钱，性质就变了：参与赌博、赌资较大的，拘留 5 日以下或者罚 1000 元以下。聚众赌博、靠赌博过日子的判 3 年以下，开赌场的判 5 年以下。多少算「赌资较大」，各地自己定，没有全国统一数字。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-14', '不吃野味，不买卖、不养保护动物当宠物', '为什么不吃野味，不买卖、不养保护动物当宠物？', '吃国家重点保护动物，东西没收，再按价值罚 2 到 20 倍。收购、运输、出售珍贵濒危动物，判 5 年以下，情节严重的判 5 到 10 年。人工繁育、当宠物买卖的一般不算犯罪，有人卖了 40 多只人工繁育的鹦鹉，没被起诉。野外抓的、来路不明的不在此列。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-15', '要债不扣人、不关人、不跟到家里赖着不让走', '为什么要债不扣人、不关人、不跟到家里赖着不让走？', '钱是真欠你的，也不能扣人、关人。法条专门写了：为了讨债扣人、关人，照样按非法拘禁办。轻的拘留 10 到 15 日，并罚 1000 到 2000 元。构成非法拘禁罪的判 3 年以下，把人弄成重伤的判 3 到 10 年，弄死人的判 10 年以上。要债去法院起诉。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-16', '身份证不借人，不用别人的身份证，也不拿别人的证件登记、开卡、买票', '为什么身份证不借人，不用别人的身份证，也不拿别人的证件登记、开卡、买票？', '把身份证借给、租给、转给别人，警告并罚 200 元以下。冒用别人的身份证，或者用骗领来的，罚 200 到 1000 元，或者拘留 10 日以内。买火车票、住店这类必须实名的场合用假证件或者别人的证件，情节严重的判拘役或者管制。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-17', '被警察拦下或带走时配合，不推、不打、不抢执法记录仪，喝了酒更要忍', '为什么被警察拦下或带走时配合，不推、不打、不抢执法记录仪，喝了酒更要忍？', '现场阻碍执法，警告或者罚 500 元以下，情节严重的拘留 5 到 10 日。对警察动手是另一档：撕咬、掌掴、踢打、抱摔、扔东西，造成轻微伤以上就算暴力袭警，判 3 年以下。用枪支、管制刀具或者开车撞的，判 3 到 7 年。甩手、挣脱这类一般的抗拒不算。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-18', '对方不满 14 岁就不能发生关系，「她同意」不是理由', '为什么对方不满 14 岁就不能发生关系，「她同意」不是理由？', '对方不满 14 岁，不管她同不同意，都按强奸罪从重处理，基本刑期是 3 到 10 年。对方不满 12 岁的，一律认定你「应当知道」。12 到 14 岁的，从发育、举止、穿着能看出可能是幼女，你还下手，就认定你「明知」。说自己确实不知道，法院把关很严。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-19', '动手打人前算清这笔账：拘留、赔钱、判刑', '为什么动手打人前算清这笔账：拘留、赔钱、判刑？', '动手一次的账：拘留 5 到 10 日，加罚 500 到 1000 元。打成轻伤就是刑事案件，判 3 年以下，打成重伤判 3 到 10 年。钱另算：有人打断对方三根肋骨，赔了 11.3 万元和解，才没被起诉。另一人打断对方桡骨，没赔，判了 10 个月。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-20', '孩子生下来养不了，只有民政登记这一条合法出路：收钱把孩子给人可能按拐卖罪判，扔下不管是遗弃罪', '为什么孩子生下来养不了，只有民政登记这一条合法出路：收钱把孩子给人可能按拐卖罪判，扔下不管是遗弃罪？', '养不了有出路，但合法的只有一条：到民政部门办收养登记，收养关系从登记那天才成立。私下把孩子给人，尤其是收了钱，可能从「送养」变成拐卖儿童罪，起刑就是 5 年以上。把孩子扔下不管、拒不抚养，情节恶劣的是遗弃罪，判 5 年以下。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-21', '别伪造事故、别夸大损失骗理赔：这是保险诈骗罪，帮你作证、帮你修车、帮你鉴定的人一起算', '为什么别伪造事故、别夸大损失骗理赔：这是保险诈骗罪，帮你作证、帮你修车、帮你鉴定的人一起算？', '编造事故、夸大损失去骗理赔，是保险诈骗罪，数额较大的判 5 年以下，再罚 1 万到 10 万元。帮你作证、鉴定、评估财产的人故意出假证明，和你一起按共犯定罪。安徽宣城一起案子里，8 个人被判 2 到 4 年，各罚 1 万元。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-22', '不卖自己的器官，也别帮人找供体：肾到手 2 万多，同一枚转手卖 20 万，钱要被没收还要按交易额罚 10 到 20 倍', '为什么不卖自己的器官，也别帮人找供体：肾到手 2 万多，同一枚转手卖 20 万，钱要被没收还要按交易额罚 10 到 20 倍？', '活体器官只能捐给配偶、直系血亲或者三代以内的旁系血亲，买卖都违法。北京一起案子里，卖肾的人只拿到 2 万多，同一枚肾卖给病人要 18 万到 22 万。卖得的钱会被没收，再按交易额罚 10 到 20 倍。摘肾后身体的代价见第 1 节第 35 条（剩下那个肾替两个干活）。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-23', '别嫖娼：默认档是拘留 10 到 15 日，不是罚点钱了事', '为什么别嫖娼：默认档是拘留 10 到 15 日，不是罚点钱了事？', '被抓到不是罚点钱了事。法条写的默认档是拘留 10 到 15 天，还可以再罚 5000 元以下。只有情节较轻的，才是 5 天以下拘留或者 1000 元以下罚款。另外，明知自己有梅毒、淋病还去嫖，是犯罪，判 5 年以下。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-24', '汉化漫画、搬运影视剧、分享网盘资源和盗版电子书，不收钱也是侵权；挂广告、收会员费就可能判刑', '为什么汉化漫画、搬运影视剧、分享网盘资源和盗版电子书，不收钱也是侵权；挂广告、收会员费就可能判刑？', '别人的作品没经许可翻译了贴出来，或者传到网上，不收钱也是侵权，要删、要赔钱。一挂广告、收会员费，就算为了挣钱。挣到 3 万元、传到 500 部或者会员到 1000 人，就够判刑，最重判 10 年。人人影视字幕组的老板判了 3 年 6 个月。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-25', '写同人、做二创拿去出版或卖钱，先取得原作许可，或者把借来的人物名字和关系换成自己的', '为什么写同人、做二创拿去出版或卖钱，先取得原作许可，或者把借来的人物名字和关系换成自己的？', '同人哪怕只借了人物名字、性格和关系，拿去出版也可能被判侵权。江南的《此间的少年》借了金庸 60 多个人物，二审判他赔 168 万元，外加 20 万元开支。官司打了 9 年，最后调解，他答应不再原样再版。免费写着玩的同人怎么算，法院说要具体分析。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s9-26', '别为了防身买甩棍、电击器、匕首、辣椒水带在身上，放在车里也算携带', '为什么别为了防身买甩棍、电击器、匕首、辣椒水带在身上，放在车里也算携带？', '匕首、弹簧刀、警棍、电击器这类东西，带出门被查到，可以拘留 5 日以下。带进车站、商场、公交车，拘留 5 到 10 日。真拿出来用也容易吃亏：有人被空手打了一拳，就拿事先藏好的刀捅人，按防卫过当判了 4 年。', 'legal', '9. 普通人容易踩的法律红线', 'published', 1, 'reference_book', 95, '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-1', '认识更多人，而不是死磕一个：两个人合不合得来，见面之前预测不出来', '为什么认识更多人，而不是死磕一个：两个人合不合得来，见面之前预测不出来？', '两场闪电约会研究让人在见面前填了 100 多项择偶问卷。问卷只能算出谁普遍容易喜欢别人、谁普遍受欢迎，算不出这两个人之间来不来电。合不合得来只有见了面才知道。所以多认识几个人，比押在一个人身上划算。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-2', '对方明确拒绝之后就停下，继续纠缠是治安违法，不是「诚意」', '为什么对方明确拒绝之后就停下，继续纠缠是治安违法，不是「诚意」？', '对方明确说了拒绝，你还发消息、还去等人，2026 年 1 月起就是治安违法。可以拘留 5 日以下，或者罚 1000 元以下。情节较重的拘留 5 到 10 日。公安还可以下令禁止你接触对方，违反了再拘留 5 到 10 日。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-3', '判断对方有没有兴趣，看行为不看「信号」：谁主动、谁安排、谁跟进', '为什么判断对方有没有兴趣，看行为不看「信号」：谁主动、谁安排、谁跟进？', '让 52 对陌生男女聊十来分钟，再互相判断对方有没有在调情。结果是「对方没在调情」判得比较准，「对方在调情」反而看不出来。换成 261 个人看视频判断，结论一样。所以别猜表情和语气，看行为：谁主动发起，谁安排下一次，你不推进时对方跟不跟进。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-4', '关系好不好，主要看你自己在这段关系里的感受，不是看对方条件', '为什么关系好不好，主要看你自己在这段关系里的感受，不是看对方条件？', '最能说明关系好不好的，是你自己的感受，不是对方的条件。比如你觉得对方认不认真、欣不欣赏你，你们吵得多不多。你自己的感受比伴侣的说法管用二到四倍。但这段关系往后变好还是变坏，任何问卷都基本算不出来。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-5', '想拉近距离就轮流回答一组由浅入深的问题，别学话术', '为什么想拉近距离就轮流回答一组由浅入深的问题，别学话术？', '两个陌生人轮流回答 36 道由浅入深的问题，45 分钟后，比光闲聊同样久的人亲近得多。起作用的是轮流说真话、一层层往深里说，不靠话术。这只说明当时更亲近，不代表能发展成长期关系。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-6', '异地不比同城差，真正的坎是搬到一起之后的头三个月', '为什么异地不比同城差，真正的坎是搬到一起之后的头三个月？', '异地在分开期间反而更稳，因为见得少，容易把对方想得比实际好。真正的坎在搬到一起之后。追踪数据里约一半异地伴侣走到了同城这一步，另一半在分开期间就结束了。重聚的这一半里，三分之一在 3 个月内分手。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 时间","钱 多","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-7', '先看登记数据再听长辈：结婚率、离婚率各是什么口径', '为什么先看登记数据再听长辈：结婚率、离婚率各是什么口径？', '2024 年全国结婚登记 610.6 万对，比上一年少了两成，离婚 351.3 万对。网上说离婚率过半，是拿这两个数一除，约 57.5%。可离婚的和结婚的不是同一批人，不能读成一半婚姻会离。公报里的结婚率 4.3‰、离婚率 2.5‰，是除以全国人口算的。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-8', '把健康收益算进去，但按观察性数据打折', '为什么把健康收益算进去，但按观察性数据打折？', '已婚的人同期死亡的概率比非婚的人低约 12%，从未结过婚的人比已婚的人高约 24%。但这只是两件事同时出现，不是结婚起的作用。本来健康、收入高、社交多的人，既更容易结婚，也更容易活得久。这些数字基本来自欧美，对国内只能当量级参考。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-9', '时间账按「无酬劳动」算，谈清分工再领证', '为什么时间账按「无酬劳动」算，谈清分工再领证？', '全国时间利用调查里，家务和陪伴照料家人这类没报酬的活，男性每天平均 1 小时 52 分，女性 3 小时 29 分。调查没按结没结婚分组，所以「结了婚家务会多多少」没有官方数字，这个性别差距只能当上限参考。分工可以在领证前谈成另一个样子。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 时间","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-10', '钱账先看法律默认规则，再决定要不要书面约定', '为什么钱账先看法律默认规则，再决定要不要书面约定？', '不签书面约定的话，法律默认婚后挣的工资奖金、经营和投资收益、继承或受赠的财产都归两人共有。婚前财产、遗嘱或赠与合同写明只给一方的，才是个人的。两个人可以书面约定各归各，签了就有约束力。因带孩子、照料老人多付出的一方，离婚时可以要求补偿。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-11', '父母出资买房，在转账的时候就把是借是送写清楚', '为什么父母出资买房，在转账的时候就把是借是送写清楚？', '婚前父母出钱买房，默认只给自己孩子。婚后出的钱没约定，按夫妻共同财产算。2025 年 2 月起，婚后一方父母全额出资、又没写明只给自己孩子的，离婚时法院可以把房判给出资方的孩子，再定补不补偿另一方。要算借款，就当天写清楚、双方签字。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-12', '配偶一方大额借的钱，你没签字也没追认，不自动变成你的债', '为什么配偶一方大额借的钱，你没签字也没追认，不自动变成你的债？', '配偶背着你借的钱，只要明显超出家里日常开销，你又没签字、没事后认账，就不自动变成你的债。要债的人得自己证明这钱用在了共同生活或共同经营上。但买房这种钱如果确实变成了你们一起住或共有的房子，对方往往证得到这一层。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-13', '领证只要身份证加一份签字声明，不用户口簿，不收钱，当场发证', '为什么领证只要身份证加一份签字声明，不用户口簿，不收钱，当场发证？', '2025 年 5 月起领证只要两样东西：本人身份证，加一份签字声明。声明里写明本人没有配偶，和对方没有直系血亲、三代以内旁系血亲关系。户口簿不用带，也不用回一方户口所在地办。登记一分钱不收，符合条件当场发证。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-14', '婚前做一次婚检，有重大疾病必须在登记前如实告诉对方', '为什么婚前做一次婚检，有重大疾病必须在登记前如实告诉对方？', '有重大疾病，没在登记前如实告诉对方，对方可以去法院请求撤销这段婚姻。要在知道之日起一年内提出。婚检本身从 2003 年起就不是领证的前置条件，去不去自愿。费用看本地政策，花半天。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-15', '算退出成本：协议离婚有 30 天冷静期，诉讼离婚有法定条件', '为什么算退出成本：协议离婚有 30 天冷静期，诉讼离婚有法定条件？', '协议离婚不是签完就完。交了申请后 30 天内，任何一方都能撤回。期满还要在 30 天内两人亲自去领离婚证，不去就当撤回。对方不同意，只能起诉。法院先调解，要有家暴、重婚、分居满两年这些情形，调解不成才判离。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-16', '给「为长辈结婚」单独记一笔账，别和自己的账混在一起', '为什么给「为长辈结婚」单独记一笔账，别和自己的账混在一起？', '长辈那份收益，也就是安心、面子、不再催，是真的。但它不会自动变成你的健康收益或关系质量。而时间账、钱账和退出成本这三笔，全部由你自己承担。在纸上分两栏，把哪些收益归自己、哪些归长辈写开，这笔账划不划算自己一眼就能看出来。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","C 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-17', '把关系好坏当成一笔健康账：吵架对事不对人，别骂人、别挖苦', '为什么把关系好坏当成一笔健康账：吵架对事不对人，别骂人、别挖苦？', '夫妻关系好的，身体好一些，死亡风险也低一些。这个关联不大，和饮食对健康的关联差不多大。一项实验里，吵架时一直带着敌意的夫妻，实验做出的小伤口愈合速度只有平和夫妻的六成。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-18', '同性伴侣趁两个人都清醒，办好授权委托、意定监护和遗嘱：法律上你们不是近亲属，不办就没有签字权和继承权', '为什么同性伴侣趁两个人都清醒，办好授权委托、意定监护和遗嘱：法律上你们不是近亲属，不办就没有签字权和继承权？', '法律上的近亲属是配偶、父母、子女、兄弟姐妹这些人，伴侣不算。不提前办文件，一方病重时，另一方替他做不了主。一方去世时，另一方一分遗产也继承不到。三份文件各管一段：活着时靠授权委托，失去判断能力后靠意定监护，身后靠遗嘱。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-19', '别靠隐瞒性取向结婚，也别把形婚当成省事的办法：法律上它就是一段真婚姻，想退出只能走离婚', '为什么别靠隐瞒性取向结婚，也别把形婚当成省事的办法：法律上它就是一段真婚姻，想退出只能走离婚？', '隐瞒性取向结婚，法律上不算无效，也不能撤销，想退出只能离婚。形婚也是真婚姻，婚后挣的钱、欠的债都按夫妻算。被瞒的一方离婚时，可以要求多分财产、赔精神损失，但法院支不支持还没有定论。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s10-20', '关系卡在反复吵架和冷战里，两个人一起去做伴侣治疗：干等着基本不会自己好', '为什么关系卡在反复吵架和冷战里，两个人一起去做伴侣治疗：干等着基本不会自己好？', '关系卡住的伴侣一起做完伴侣治疗，对这段关系明显满意多了，大约七成有好转。光排队干等的伴侣，基本没变化。但效果会变淡：跟到第 5 年，约一半还明显好着，约四分之一已经分居或离婚。', 'relationship', '10. 恋爱和结婚划不划算', 'published', 1, 'reference_book', 95, '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 多","时间 中","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-1', '动手前先问三句：损害了谁的利益、对方多有能力追究、我留了多少证据；被追究后马上找刑事律师', '为什么动手前先问三句：损害了谁的利益、对方多有能力追究、我留了多少证据；被追究后马上找刑事律师？', '动手之前先问一句：厂商、平台、公司会不会去报案。服务器日志、支付记录、群聊记录，办案时都调得出来。真被刑事拘留了，最长 37 天内决定抓不抓你。从第一次问话起你就能请律师，这 37 天是找刑事律师最管用的时候。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","C 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-2', '不做、不卖游戏外挂和辅助，包括「只读屏幕不碰内存」的 AI 辅助，也不卖给微信这类软件加功能的改版', '为什么不做、不卖游戏外挂和辅助，包括「只读屏幕不碰内存」的 AI 辅助，也不卖给微信这类软件加功能的改版？', '外挂卖出 20 人次，或者挣到 5000 元，就够判 3 年以下，特别严重的判 3 到 7 年。有人做透视、自瞄外挂，3 个月卖了 8 万多，判 1 年缓 1 年、罚 5000 元。有人拿服务端程序开私服，收了 2000 多万充值，最重判 4 年，罚金最高 1000 万元。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-3', '不写、不卖抢票、秒杀、刷单、薅羊毛脚本，哪怕只是「自动化点按钮」', '为什么不写、不卖抢票、秒杀、刷单、薅羊毛脚本，哪怕只是「自动化点按钮」？', '脚本不改内存、不破解，只是发请求比人快，一样会被定罪，挣到 5000 元或让对方损失 1 万元就够。有人用买来的 12306 账号代抢 200 多张票、挣了 2 万多，判 1 年 6 个月缓 1 年 6 个月、罚 5000 元。在网店卖抢票软件的，按不正当竞争赔了 2 万元。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-4', '爬虫只爬无需登录的公开页面，不绕反爬、不碰个人信息，爬到的数据不卖', '为什么爬虫只爬无需登录的公开页面，不绕反爬、不碰个人信息，爬到的数据不卖？', '要登录、要 token、要破解签名才拿得到的数据，属于绕过防护，判 3 年以下，严重的判 3 到 7 年。爬到个人信息更麻烦。行踪、通信、征信、财产类 50 条，就算情节严重。住宿、健康、交易类 500 条，其他类 5000 条，或者挣到 5000 元，也一样。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-5', '不接赌博、诈骗、色情 App 的开发单，不替「客户」搭支付通道、解封账号', '为什么不接赌博、诈骗、色情 App 的开发单，不替「客户」搭支付通道、解封账号？', '这类报价高、需求含糊的单子，接了就算赌博团伙的共犯。按开设赌场罪判 5 年以下，严重的 5 到 10 年，比单纯帮忙最多判 3 年重。有个电竞竞猜 App，写代码的 28 人判了 1 年到 3 年 6 个月。替诈骗团伙解封 QQ 号的，判 1 年 6 个月、罚 2 万元。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-6', '离职时交清账号权限，不删库、不留后门、不改密码锁系统，哪怕公司欠你钱', '为什么离职时交清账号权限，不删库、不留后门、不改密码锁系统，哪怕公司欠你钱？', '账号密码是公司给的，不等于离职后还能用，登进去就算非法控制，判 3 年以下。删数据让系统跑不起来的，判 5 年以下，后果特别严重的判 5 年以上。有个被辞退的高级工程师，用原管理员账号登录公司服务器删数据和日志，损失 12 万多元，判 3 年缓 5 年、罚 3 万元。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-7', '离职不带走源码、客户名单和技术文档，不上传个人网盘，不在下家复用', '为什么离职不带走源码、客户名单和技术文档，不上传个人网盘，不在下家复用？', '自己写的代码著作权也归公司，客户名单也算商业秘密，带走就是拿公司的东西。有离职员工带着安检系统源码去新公司，本人判 5 年、罚 50 万元，新公司罚 400 万元。有人钻系统漏洞下载 3.3 万多个设计文件，判 1 年 10 个月。公司还可以另外找你索赔。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-8', '不在别人的电脑、服务器、摄像头上跑自己的程序，公司机器不拿来挖矿', '为什么不在别人的电脑、服务器、摄像头上跑自己的程序，公司机器不拿来挖矿？', '没经允许控制别人的电脑、服务器、摄像头，到 20 台就判 3 年以下，特别严重的判 3 到 7 年。够不上犯罪的，也要拘留 5 日以下，还可能罚 5 万到 50 万元。受过刑事处罚的人，终身不能干网络安全管理和网络运营的关键岗位。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-9', '没有书面授权不测别人的系统，「出于好意」和「事后上报」都不是出罪理由', '为什么没有书面授权不测别人的系统，「出于好意」和「事后上报」都不是出罪理由？', '定不定罪看有没有授权、拿到了多少，不看你本意。拿到 500 组普通账号密码，或者挣到 5000 元、让对方损失 1 万元，就够判 3 年以下。为了证明漏洞顺手导一张用户表，常常一次就过了 500 组。手里有账号密码，用在授权范围以外也算侵入。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-10', '漏洞按规定报送，修补前不公开细节、不发利用工具、不交给境外', '为什么漏洞按规定报送，修补前不公开细节、不发利用工具、不交给境外？', '个人也归《网络产品安全漏洞管理规定》管。厂商拿出修补办法之前，你不能公开漏洞，也不能公开正在用的系统的漏洞细节。不能发专门利用漏洞的程序和工具，公开时要同时说清怎么修。没公开的漏洞，不能交给厂商以外的境外组织和个人。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-11', '不卖翻墙工具、VPN 账号，不替人搭这类节点', '为什么不卖翻墙工具、VPN 账号，不替人搭这类节点？', '自己搭线路出境，或者用国家公用信道以外的国际信道，公安可以责令停止联网、给予警告，罚 1.5 万元以下并没收违法所得。靠这个做生意的，办案机关可以按非法经营罪办，情节严重的判 5 年以下。这条讲的是卖和搭节点。个人自己用的，处罚以警告加罚款为上限。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","B 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-12', '签了竞业协议，离职后公司不按月给补偿就书面催告，满 3 个月没给可以解除；没接触过商业秘密的岗位可请求确认条款不生效', '为什么签了竞业协议，离职后公司不按月给补偿就书面催告，满 3 个月没给可以解除；没接触过商业秘密的岗位可请求确认条款不生效？', '竞业限制就是离职后一段时间不许去同行干活，最长 2 年，公司要按月给补偿。没约定数额的，按离职前 12 个月平均工资的 30% 给，不低于当地最低工资。公司的原因 3 个月没给，你可以请求解除。2025 年起，没接触过商业秘密的岗位，可以请求确认条款不生效。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-13', '上班时间、用公司资源写的代码归公司，自己的开源项目用自己的时间和设备做，不混公司代码', '为什么上班时间、用公司资源写的代码归公司，自己的开源项目用自己的时间和设备做，不混公司代码？', '主要靠公司的设备、内网或业务数据写出来、由公司担责的软件，著作权归公司，你只保留署名权，合同这么约定的也一样。下班写的，只要用了公司电脑或业务数据，同样可能算公司的。用公司资源做出的发明，专利也归公司。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-14', '用 GPL 等开源代码做产品，按许可证要求开源或换许可证，不当「没人管」', '为什么用 GPL 等开源代码做产品，按许可证要求开源或换许可证，不当「没人管」？', '侵犯著作权，按对方的损失或你挣到的钱赔，故意且情节严重的，能判到 1 到 5 倍。有家公司招了对手的前员工，做出实质相似的软件，辩称对方软件用了 GPLv2、本该开源。最高法认为对方开不开源不影响它的著作权，照样判停止侵害、赔 50 万元。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-15', '做 App 只收业务必需的个人信息，14 岁以下要监护人同意，隐私政策写清楚', '为什么做 App 只收业务必需的个人信息，14 岁以下要监护人同意，隐私政策写清楚？', '只收业务必需的信息，不满 14 岁的要监护人同意。违规的先责令改正，App 可能被停掉。拒不改正罚 100 万元以下，负责人罚 1 万到 10 万元。严重的罚 5000 万元以下或上年营业额的 5%，负责人罚 10 万到 100 万元，写代码和做产品的也可能算负责人。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","B 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-16', '网站、App 上线前先做 ICP 备案，按等级保护要求留 6 个月以上日志', '为什么网站、App 上线前先做 ICP 备案，按等级保护要求留 6 个月以上日志？', '备案不要钱，走云厂商流程大概几周，境内服务器不备案会被关站。备案说不收费、实际在收钱的，罚 10 万到 100 万元。日志要留满 6 个月，拒不改正或出了后果的罚 1 万到 10 万元。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-17', '对公众提供生成式 AI 服务前先按规定做安全评估和算法备案，生成内容加标识', '为什么对公众提供生成式 AI 服务前先按规定做安全评估和算法备案，生成内容加标识？', '面向公众、能影响舆论或动员人的生成式 AI 服务，上线前要做安全评估、办算法备案，改了或停了还要办变更、注销。生成的图片和视频要加标识。自己用、不对公众开放的小工具不用管这些。违反了按网络安全法等法律处罚。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","B 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-18', '不做、不发自动跳过或屏蔽别家 App 广告的工具，免费、不联网也可能被判不正当竞争', '为什么不做、不发自动跳过或屏蔽别家 App 广告的工具，免费、不联网也可能被判不正当竞争？', '做软件替用户跳过、屏蔽别家 App 的广告，会被对方告不正当竞争。不收钱也可能算，法律管的经营者包括提供服务的个人。有浏览器默认屏蔽芒果TV 的片头广告，赔了 80 万元。有 App 让人直接跳过芒果TV 的开屏广告，赔了 8 万元损失。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s11-19', '不搭「AI 中转站」低价转卖境外大模型接口：上海已有站长被刑事拘留', '为什么不搭「AI 中转站」低价转卖境外大模型接口：上海已有站长被刑事拘留？', 'AI 中转站就是低价转卖境外大模型接口的网站。上海有个站长因此被刑事拘留 37 天，取保后他自己说肯定会被判刑，已经退赔退赃。国家安全部也发过提示，说不少中转站没有运营资质，还私自把用户数据传到境外。', 'living', '11. 程序员和技术人容易踩的红线', 'published', 1, 'reference_book', 95, '{"11. 程序员和技术人容易踩的红线","C 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-1', '只拿亏得起的钱创业，不动家底、不借钱开张', '为什么只拿亏得起的钱创业，不动家底、不借钱开张？', '个体户欠的钱，要拿你自己名下的钱和东西还。分不清是不是全家一起做的，就拿全家的财产还。开公司也不保险：公司还不上债的时候，你当初答应出、还没到期的那笔出资，会被要求提前掏出来。所以投多少，按「全亏光也照样还房贷、看病」来定。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-2', '不给公司贷款签个人担保，配偶更不要跟着签', '为什么不给公司贷款签个人担保，配偶更不要跟着签？', '签的是「连带责任保证」，公司还不上钱，债主可以绕开公司直接找你要。写「一般保证」才是先告公司，卖完公司财产还差多少才轮到你。配偶跟着签字，两个人的家产一起搭进去，有限公司的「有限」对你个人就不算数了。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-3', '开张前选对主体：个体户和合伙人赔到底，有限公司才「有限」', '为什么开张前选对主体：个体户和合伙人赔到底，有限公司才「有限」？', '个体户和普通合伙人要赔到底，欠多少还多少。有限公司的股东只赔自己注册时答应出的那个数。但答应了多少，5 年内就要真拿出多少：填 100 万，就是可能欠着 100 万。公司账和自家账混着用，「有限」也会失效。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-4', '不当挂名股东，不替人代持股权', '为什么不当挂名股东，不替人代持股权？', '名字登记在册，你在法律上就是股东。注册时答应出的钱要按期交齐，交不上除了补交还要赔公司的损失。公司开办时别的股东没真把钱交进来，缺多少你也跟着还多少。生意是别人做的，债记在你名下。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-5', '加盟前先查商务部备案，拿到书面披露，把「冷静期」写进合同', '为什么加盟前先查商务部备案，拿到书面披露，把「冷静期」写进合同？', '按规定，品牌方自己得先开 2 个直营店、经营满 1 年，签约后 15 日内还要去商务部门备案。签约前，它必须把加盟费、保证金怎么退、现有门店赚不赚钱等 12 项写成书面材料给你。查不到备案、不肯给材料、要先交钱才让看合同的，直接走人。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-6', '注册前把名称、经营场所、经营范围和注册资本定下来，材料齐了当场就能领执照', '为什么注册前把名称、经营场所、经营范围和注册资本定下来，材料齐了当场就能领执照？', '登记本身不花钱，注册费 2015 年起就停征了。要交的材料只有五项：申请书、身份或资格证明、经营场所文件、章程或合伙协议（个体户不用交），加上法规另外点名要的。材料齐了当场发执照，当场发不了的 3 个工作日内办完。被收的那笔钱多半是代办跑腿费。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-7', '要许可证的行当，证没下来不开张', '为什么要许可证的行当，证没下来不开张？', '没证就开张，轻的是勒令停业、把挣到的钱收走，再罚 1 万元以下。要是做的是专营专卖的东西，或者证券、期货、保险、资金支付结算这几类，情节严重就构成非法经营罪，判 5 年以下起步。先装修后办证、证下来之前先试营业，是最常踩的一脚。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-8', '做食品先看自己落在哪一档：生产和做餐饮要许可，只卖预包装的改备案，卖生鲜肉菜不用证', '为什么做食品先看自己落在哪一档：生产和做餐饮要许可，只卖预包装的改备案，卖生鲜肉菜不用证？', '自己做东西去卖，像小吃店、卤味、烘焙、自制酱菜，都要办许可。只卖别人做好的整包装食品不用许可，到县级以上市场监管部门备案就行。卖生鲜肉、蔬菜这类不用证。没证就干，最低也罚 5 万到 10 万，比多数小本生意的本钱还高。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-9', '装袋卖就是预包装食品：标签上生产日期、保质期、配料表一样都不能少', '为什么装袋卖就是预包装食品：标签上生产日期、保质期、配料表一样都不能少？', '食品装进包装再卖，法律上就叫预包装食品，包装上必须有标签，而且有九项必须标，生产日期和保质期都在里面。散装食品也要标名称、日期和卖家的名称地址。该标的没标，货值不到一万罚 5000 到 5 万，够一万按货值罚 5 到 10 倍。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-10', '普通食品不许说能治病：标签、说明书、广告和直播话术都算', '为什么普通食品不许说能治病：标签、说明书、广告和直播话术都算？', '普通食品的标签、说明书和广告里，都不能说自己能防病治病。除了医疗、药品、医疗器械这三类广告，别的广告都不许说能治病，也不许用听着像药的词。罚的是广告费的 1 到 3 倍。算不出广告费的，罚 10 万到 20 万。情节严重的还能吊销营业执照。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-11', '食品这一行有刑事线：卖病死肉、超标货就够罪，掺了有毒有害的不看金额、起刑五年', '为什么食品这一行有刑事线：卖病死肉、超标货就够罪，掺了有毒有害的不看金额、起刑五年？', '前面几条罚的是钱，这条抓的是人。卖病死肉、检验不合格的肉，或者农残兽残重金属严重超标的东西，只要「足以」让人吃出严重中毒就够罪，不用真有人吃坏，判 3 年以下。往食品里掺有毒有害的非食品原料，起步就是 5 年以下，不看你卖了多少钱。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-12', '领了执照就开始有申报义务，没有收入也要按期零申报（照报一张全是零的表）', '为什么领了执照就开始有申报义务，没有收入也要按期零申报（照报一张全是零的表）？', '领了执照就要按期报税。一分钱没赚也要报，只是表上数字全填零。不报先罚 2000 元以下，情节严重的罚 2000 到 1 万。连着三个月所有税种都不报，系统会自动把你列为非正常户，发票就开不了了。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-13', '发票只按真实交易开，小规模纳税人用足免税额', '为什么发票只按真实交易开，小规模纳税人用足免税额？', '你要是按简易办法交税的小规模纳税人，一个月卖不到 10 万、一个季度卖不到 30 万，增值税就免了。本来按 3% 交的，同期也减到按 1% 交。反过来，「找人开票抵成本」就是虚开，起步判 3 年以下，还要罚 2 万到 20 万。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-14', '自称税务局催你交钱报税的都是骗子，办税只走电子税务局和 12366', '为什么自称税务局催你交钱报税的都是骗子，办税只走电子税务局和 12366？', '税务部门不会打电话要你的银行卡密码、支付密码或者短信验证码，也不会给你一个账号让你把税打过去。真上门查账的，要出示检查通知书和检查证。接到这类电话先挂断，再打 12366 核实。已经转了钱，立刻打 110 或者 96110 止付。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-15', '收钱写「定金」不写「订金」，违约金写明数，账期当放贷来审', '为什么收钱写「定金」不写「订金」，违约金写明数，账期当放贷来审？', '写「定金」这两个字才有双倍规则：你毁约，这笔钱要不回来；对方毁约，要退你双倍。超过合同金额 20% 的那部分不算。写成「订金」，法律上没有这套规则。给账期等于把自己的钱白借给对方，对方倒了就是坏账。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-16', '用人第一个月内签书面合同，30 日内办社保登记', '为什么用人第一个月内签书面合同，30 日内办社保登记？', '人来上班满一个月还没签书面合同，从第二个月起，每个月要按双倍发工资，一直算到满一年。社保要在用工 30 天内登记，不办的罚该交社保费的 1 到 3 倍。法律上没有「员工自愿放弃社保」这一项。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-17', '工资按合同和法律给，加薪、借款、奖金都走书面', '为什么工资按合同和法律给，加薪、借款、奖金都走书面？', '工资要按合同和法律按时足额发。欠了，员工可以直接找法院开支付令。加薪、奖金、垫付只是口头说说，真吵起来，拿不出证据的一方吃亏。自己掏钱借给员工，要写书面借条，写清数额、利息和什么时候还。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-18', '先卖再造：用预售和小订单验证有人买，再投钱生产', '为什么先卖再造：用预售和小订单验证有人买，再投钱生产？', '有人跟踪了 116 家意大利新公司大约一年：先立一个假设、再拿市场反馈去验的创业者，生意做得更好，也更愿意及时换方向，而且并没有更早放弃。所以，没人肯预付、没人肯下小单，就别信「做出来自然有人买」。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-19', '样品做出来先过一遍量产清单，再谈开工', '为什么样品做出来先过一遍量产清单，再谈开工？', '一件样品和一千件的差别，在于钱压在哪里。良率决定真实成本。起订量和账期决定你要先垫多少钱。库存决定钱什么时候能回来。产品要是在强制性认证目录里，没认证、没标认证标志就不能出厂和销售。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","C 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-20', '进货一批留一批票据和上家信息，进货价明显低于市场价的不进：员工进的假货，老板是被判的那个', '为什么进货一批留一批票据和上家信息，进货价明显低于市场价的不进：员工进的假货，老板是被判的那个？', '卖假货，挣到 3 万，或者卖到 5 万，就够判刑，判 3 年以下。货压在仓库没卖出去也算。「我不知道是假的」不由你说了算：进货价明显低于市场价又说不出理由，就会被认定你知情。留住采购合同、发票、付款记录和上家信息，才有免赔那条路。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-21', '商品、包装、吊牌和宣传图上的图案要么自己做要么买授权，改个颜色、加个图标不算「改过了」', '为什么商品、包装、吊牌和宣传图上的图案要么自己做要么买授权，改个颜色、加个图标不算「改过了」？', '在别人的图上改个颜色、换个底色、加个自己的图标，还是没经许可用别人的作品。为赚钱复制别人的美术作品，挣到 3 万、做到 5 万，或者印够 500 张，就构成侵犯著作权罪，判 3 年以下。商标那边，「像到容易混淆」本身就算侵权。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 自由","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-22', '在岗位上按规程办事，规程之外的好意先想清楚责任归谁', '为什么在岗位上按规程办事，规程之外的好意先想清楚责任归谁？', '以护士为例：条例写明，发现病人病情危急，要立即通知医师；发现医嘱违反规定，要向开医嘱的医师提出。别的岗位也一样，先看清自己这份规程把「必须上报」划在哪儿。法律也没让人见死不救：自愿出手紧急救助，把人弄伤了，不用赔钱。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-23', '亏了就按程序退场：能简易注销就注销，资不抵债走破产，别放着不管', '为什么亏了就按程序退场：能简易注销就注销，资不抵债走破产，别放着不管？', '没欠债、不欠工资税款社保的，全体投资人写份承诺，公示 20 天没人提异议就能简易注销。个体户不用公示，10 天没异议直接注销。还不上债就申请破产。放着不管、2 年不报年报又联系不上的，吊销执照，负有责任的法定代表人 3 年内不能再当法定代表人。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s12-24', '花钱请人代运营网店、上开店培训、做「无货源」之前，先问清后面还要不要加钱、销量从哪来', '为什么花钱请人代运营网店、上开店培训、做「无货源」之前，先问清后面还要不要加钱、销量从哪来？', '这类骗局先收一笔小钱，再拿「升级套餐」、垫付货款、解冻金让你一次次加钱。后台的订单和收益可能是做出来的，想提现时就提不出来。靠刷单冲销量本身就违法，被查到的代运营要挨罚。', 'living', '12. 创业与做生意：别把家底赔进去', 'published', 1, 'reference_book', 95, '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-1', '有人倒地没呼吸，立刻用力按压胸口，让旁人打 120 并找 AED', '为什么有人倒地没呼吸，立刻用力按压胸口，让旁人打 120 并找 AED？', '你最可能按的是自家人：心脏骤停有 79.2% 发生在家里。有人按压，活着出院的比例从 3.9% 升到 16.1%。叫不应、没呼吸，就直接按。位置在两乳头连线的中点，双手叠起来用力压，每秒 2 次，不停。让第二个人打 120、拿 AED，你的手别停。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-2', '老人摔倒、有人倒地，先蹲下喊他、打 120，别急着把人扶起来；陌生人这档走开也合法，停下来就别上手搬', '为什么老人摔倒、有人倒地，先蹲下喊他、打 120，别急着把人扶起来；陌生人这档走开也合法，停下来就别上手搬？', '这条的主线是自家老人和身边熟人。先看有没有呼吸，没有就按第 1 条（用力按压胸口）压胸。有呼吸也别抱起来：人可能是先中风、先晕厥才摔的，硬扶会加重。蹲下叫他，问他记不记得自己怎么倒的。腰背疼、像骨折的一律不搬，原地打 120。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-3', '突然嘴歪、一侧胳膊没劲、说话说不清，立刻打 120，不要等、不要自己开车去', '为什么突然嘴歪、一侧胳膊没劲、说话说不清，立刻打 120，不要等、不要自己开车去？', '嘴歪、一侧胳膊抬不起、说话说不清，立刻打 120。发病 3 小时内打药通开血管，恢复到生活基本能自理的可能性大约是不打药的 1.75 倍。拖到 3 到 4.5 小时只剩 1.26 倍。超过 4.5 小时就看不出差别了。记下症状开始的准确时间。别喂水喂药，别自己开车。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-4', '突然天旋地转站不稳、看东西成双、一只眼发黑，或者手指点不到自己鼻尖，也按卒中打 120', '为什么突然天旋地转站不稳、看东西成双、一只眼发黑，或者手指点不到自己鼻尖，也按卒中打 120？', '只看「脸歪、抬手、说话」三条，一成多的卒中会被漏掉，因为有的卒中一开始既不歪嘴也不瘫手。把站不稳、看东西重影或缺一块也算进去，漏掉的降到 4.4%。突然天旋地转站不住、看东西成双、手指点不到自己鼻尖，一样打 120，一样记下时间。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-5', '一只眼睛突然像拉下窗帘一样黑掉，哪怕几分钟就自己好了，也当天按卒中去急诊', '为什么一只眼睛突然像拉下窗帘一样黑掉，哪怕几分钟就自己好了，也当天按卒中去急诊？', '一只眼突然像拉下窗帘一样黑掉，是眼底血管堵了，堵得越久，能救回的视网膜越少。它也是脑缺血的一种，接下来几天容易中风。当天评估、当天开始治的人，90 天内再中风的比例从 10.3% 降到 2.1%。当天去有卒中中心的急诊，别等第二天挂眼科。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-6', '一只眼又胀又痛、发红，看灯有一圈彩虹，还头痛恶心想吐，当天去眼科急诊', '为什么一只眼又胀又痛、发红，看灯有一圈彩虹，还头痛恶心想吐，当天去眼科急诊？', '这是青光眼急性发作。眼睛里的水排不出去，眼压一下子顶上去。拖得越久，视神经压坏得越多，坏了就回不来。武汉封控期间的病人平均拖了 241 小时才治上，失明的占 21.87%。第二年同期没封控，平均拖 121 小时，失明的占 7.84%。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-7', '胸口压着疼、闷、发紧超过 15 分钟不缓解，打 120，不要自己扛也不要自己开车', '为什么胸口压着疼、闷、发紧超过 15 分钟不缓解，打 120，不要自己扛也不要自己开车？', '胸口压着疼、闷、发紧，超过 15 分钟不缓解，打 120。到医院后 55 分钟内把血管撑开的，30 天内死亡 2.8%。超过 55 分钟的 9.7%。耽误的每一段，都在多坏死一块心肌。别自己开车，路上失去意识就是第二场事故。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-8', '突然像被撕开一样的剧痛，从胸口往后背、往腰一路挪，打 120 并说清「疼在移动」', '为什么突然像被撕开一样的剧痛，从胸口往后背、往腰一路挪，打 120 并说清「疼在移动」？', '撕裂一样的剧痛从胸口往后背、往腰一路挪，打 120 时直接说「像撕开一样，疼在往下走」。这病不手术、光吃药的死亡率 58%。它的处理和心梗正相反：医生想到它，才会去做增强 CT，而不是给你抗凝溶栓。两条胳膊血压差很多、一侧摸不到脉，也一起说出来。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-9', '突然一记「这辈子最疼的头痛」，一小时内就到最疼，立刻去急诊做头颅 CT', '为什么突然一记「这辈子最疼的头痛」，一小时内就到最疼，立刻去急诊做头颅 CT？', '要看的是多快疼到最厉害。一小时内疼到顶的剧烈头痛，约 6% 是脑表面的血管破了。40 岁以上、脖子痛或发硬、有人看到你晕过去、活动中起病、瞬间炸开、脖子往前低不下去，中一条就去急诊做头颅 CT。去查的人大多没事，但漏一次再出血就是死亡。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-10', '老人磕过头之后两三周到几个月变得走路不稳、迟钝、嗜睡或者一侧没劲，去做头颅 CT', '为什么老人磕过头之后两三周到几个月变得走路不稳、迟钝、嗜睡或者一侧没劲，去做头颅 CT？', '老人磕头之后，血通常到第三周才积起来。撞的当时可以完全没事，人自己都想不起磕过。这病开刀之后复发率能到 33%，病死率能到 32%。发现老人突然糊涂、走路发飘、总想睡、一只手没劲，先倒回去问这两三个月摔没摔过头，再去做 CT。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-11', '一条腿突然肿起来、发紧、按着疼，尽快就医；再加上突然喘不上气或者胸痛，立刻打 120', '为什么一条腿突然肿起来、发紧、按着疼，尽快就医；再加上突然喘不上气或者胸痛，立刻打 120？', '一条腿突然肿起来、比另一条粗一圈、按着疼，尽快去做腿部静脉超声。再出现突然喘不上气、深吸气时胸痛、心跳快、发晕，血块可能已经跑到肺里，直接打 120。确诊肺栓塞的人 3 个月内死亡 17.4%。久坐超过 4 小时风险大约翻倍，但摊到一个人头上仍然很低。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-12', '大出血先用手死死压住伤口，四肢压不住就上止血带，同时打 120', '为什么大出血先用手死死压住伤口，四肢压不住就上止血带，同时打 120？', '先用手或衣物死死压住，四肢压不住就上止血带，再打 120，上了就不松开。战地伤员里，休克前上止血带的活了九成，休克后才上的只活一成，该上没上的 5 个人全死了。扎在伤口上方，拧到血停，记下时间。别拿鞋带绳子代替。脖子和躯干只能压，不能扎。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-13', '被狗、猫咬伤或抓破皮，先用肥皂水和流水交替冲 15 分钟，当天去打疫苗', '为什么被狗、猫咬伤或抓破皮，先用肥皂水和流水交替冲 15 分钟，当天去打疫苗？', '狂犬病一旦发病，病死率几乎 100%，冲洗加疫苗是唯一的路。先用肥皂水和流动清水交替冲 15 分钟，当天去打疫苗。咬穿了、破皮的地方被舔，属于三级暴露，还要加打被动免疫制剂。「家养的、打过针的」不改变处置，级别按伤口定，不按狗的来历定。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-14', '烫伤后立刻用凉的流动水冲 20 分钟，别抹牙膏酱油', '为什么烫伤后立刻用凉的流动水冲 20 分钟，别抹牙膏酱油？', '受伤 3 小时内用凉的流动水冲够 20 分钟，后来需要植皮的可能性大约只有没冲的六成。是凉水不是冰水，冰敷会加重损伤。衣服粘在伤口上别硬撕，冲完拿干净布盖住去医院。牙膏、酱油、香油、面粉都不要抹。隔了一会儿才想起来，三小时内补冲仍然有用。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-15', '突然全身起疹、喘不上气或者发晕，按过敏性休克处理，立刻叫 120 并说清楚', '为什么突然全身起疹、喘不上气或者发晕，按过敏性休克处理，立刻叫 120 并说清楚？', '突然全身起疹，再加上喘不上气或者发晕，就按过敏性休克办。立刻打 120，直接说「怀疑过敏性休克」，让急救带着肾上腺素来。抗过敏药和激素起效慢，替不了肾上腺素。有过一次的人找医生开自动注射笔，打大腿中外侧，隔着裤子也能打。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-16', '有人抽搐倒地，清开周围、让他侧躺、看表计时，什么都别往嘴里塞', '为什么有人抽搐倒地，清开周围、让他侧躺、看表计时，什么都别往嘴里塞？', '把周围的硬东西挪开，让他侧躺、嘴朝下，看表记时间。别按住他，别掰嘴，别往嘴里塞东西，那只会弄伤牙齿和下颌。超过 5 分钟不停、停了很快又发作、发作后叫不醒或者呼吸困难、在水里发作、这是头一次发作，都要叫救护车。等人完全清醒再给水。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-17', '糖尿病人突然发抖、出冷汗、说话不清，先给 15 克糖，15 分钟后复测', '为什么糖尿病人突然发抖、出冷汗、说话不清，先给 15 克糖，15 分钟后复测？', '先吃 15 克糖，方糖、一小盒果汁都行。15 分钟后再测一次，还低就再来一次。血糖低于 3.0 mmol/L 就是医学上要当回事的低血糖。到了要别人帮忙才能处理的程度，可以致命。意识不清的人一口都别喂，会呛进气管，直接打 120。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-18', '有人触电，先断电，再用干燥的木棍之类挑开电源，不要直接上手拉', '为什么有人触电，先断电，再用干燥的木棍之类挑开电源，不要直接上手拉？', '先断电，或者用干燥的木棍之类把电源挑开，再碰人。直接上手拉，一个伤者就变成两个。脱离电源后没有呼吸的，立刻按第 1 条（用力按压胸口）按压，别因为是电伤就不敢碰。高压线落地、变电设备附近不自己处置，退远等电力部门断电。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-19', '一氧化碳报警器响了，或者一屋子人同时头痛恶心，先出门再打电话', '为什么一氧化碳报警器响了，或者一屋子人同时头痛恶心，先出门再打电话？', '报警器响了，或者一屋子人同时头痛、恶心、发晕，先把人都带到室外，再打电话。别留在屋里找原因，也别回去关阀门。症状像感冒，「出门就好转」是最强的提示。中国 2018 年报告了 11523 人死于一氧化碳中毒，冬天最多，大多死在家里。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-20', '误服清洁剂、农药、药物先别催吐，带上瓶子立刻就医；溅到眼睛或皮肤用大量清水至少冲 15 分钟', '为什么误服清洁剂、农药、药物先别催吐，带上瓶子立刻就医；溅到眼睛或皮肤用大量清水至少冲 15 分钟？', '误服清洁剂、农药、药物不要催吐，腐蚀性液体吐出来会把食管再烧一遍。先喝适量牛奶或者蛋清，带上瓶子和说明书立刻去医院。溅到皮肤或者眼睛，用大量清水至少冲 15 分钟，眼睛要撑开眼皮冲、不要揉。消毒液和洁厕剂混着用会产生氯气。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-21', '酸碱等化学品溅到身上，立刻脱掉污染的衣服、用大量流动清水冲，眼睛要掰开眼皮冲，冲够时间再走', '为什么酸碱等化学品溅到身上，立刻脱掉污染的衣服、用大量流动清水冲，眼睛要掰开眼皮冲，冲够时间再走？', '三步。第一步，立刻脱掉沾上的衣服鞋袜，衣服兜住的地方伤得最重。第二步，用大量流动清水冲，皮肤和眼睛都至少 15 分钟，湖南省应急管理厅给到 20 到 30 分钟，按长的那个来。第三步，眼睛撑开眼皮冲，冲完直接去眼科。用常温水，不用热水。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-22', '高温下头晕、恶心、不出汗或意识不清，立刻挪到阴凉处脱衣泼水降温，意识不清的不喂水、打 120', '为什么高温下头晕、恶心、不出汗或意识不清，立刻挪到阴凉处脱衣泼水降温，意识不清的不喂水、打 120？', '皮肤烫红、说话含糊、意识混乱是热射病。从头晕到昏迷可以只有几十分钟，病死率极高。立刻挪到阴凉通风处、脱掉衣服、用凉水和湿毛巾降温，同时打 120。意识不清的一口水都不要喂，会呛。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-23', '中暑的人只要清醒，就少量多次喝凉的淡盐水或运动饮料，别猛灌、别喝酒和高糖饮料', '为什么中暑的人只要清醒，就少量多次喝凉的淡盐水或运动饮料，别猛灌、别喝酒和高糖饮料？', '只有清醒的人才喝。凉的淡盐水或运动饮料少量多次喝，一小时 500 到 1000 毫升。别猛灌，吐出来呛进气管更要命。不喝酒和高糖饮料，它们会让人丢更多水。先用凉水擦身、冰袋敷脖子腋下大腿根降温，再补水。意识不清、说话含糊的，一口都不喂。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-24', '火灾时贴地爬、摸门再开门、门烫就别开，走楼梯不坐电梯，出去了别回头', '为什么火灾时贴地爬、摸门再开门、门烫就别开，走楼梯不坐电梯，出去了别回头？', '趴到地上，从烟底下爬向出口。开门前先摸门把和门板，烫、或者门缝在冒烟，就别开这扇门，换第二条路。开门要慢，一冒浓烟立刻关上。走楼梯不坐电梯，一断电就困在里面。出去了不为拿东西回头。衣服着火就停下、倒地、打滚，用手护住脸。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-25', '看到有人溺水，先叫人和打 110/120，伸竿、抛漂浮物，自己不下水', '为什么看到有人溺水，先叫人和打 110/120，伸竿、抛漂浮物，自己不下水？', '溺水的人会本能地把施救者往水下按，下水的人自己也可能淹死。顺序是：大喊叫人 → 打 110/120 → 递长杆、绳子 → 抛救生圈、空桶、矿泉水瓶 → 人上岸没呼吸就立刻按压。不结手拉手的链子下水。全球每年约 30 万人溺亡，这是 1 到 4 岁孩子的第四位死因。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-26', '有人噎住说不出话，站到背后做 5 次拍背加 5 次腹部冲击，倒下就做心肺复苏', '为什么有人噎住说不出话，站到背后做 5 次拍背加 5 次腹部冲击，倒下就做心肺复苏？', '先问「你噎住了吗，能说话吗」。还能用力咳、能出声的不要动手，让他咳。说不出话就站到背后，5 次拍背接 5 次腹部冲击，反复做到东西出来或者人倒下。倒下就做心肺复苏，同时叫人打急救电话。孕妇和很胖的人改冲胸口。别伸手去嘴里掏看不见的东西。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-27', '在戈壁、沙漠、无人区迷路或车坏了，留在原地或车旁，先报位置，再遮阳保温，省水，不乱走', '为什么在戈壁、沙漠、无人区迷路或车坏了，留在原地或车旁，先报位置，再遮阳保温，省水，不乱走？', '留在原地或者车旁，车是最大的遮阳物。顺序是：有信号先发位置再打电话 → 遮阳保暖 → 省水，白天不动、夜里凉了再动 → 不乱走 → 用反光镜、烟、三堆火发信号。进去之前把路线、目的地、返回日期和车型车牌告诉别人。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","C 级","性价比 一般","口径 死亡率","钱 多","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-28', '发抖、说话含糊、走路打晃是失温，换掉湿衣、包起来，先暖躯干，喝热甜饮不喝酒', '为什么发抖、说话含糊、走路打晃是失温，换掉湿衣、包起来，先暖躯干，喝热甜饮不喝酒？', '体温降到 35℃ 以下就是失温，人会发抖、说话含糊、走路打晃、想不清楚事。换掉湿衣服，用保温毯或者干衣裹起来，先暖躯干、不先暖手脚。给热的甜饮料，不给酒，酒会压住寒战。不抖了不是好转，是加重。没有意识就做心肺复苏。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-29', '被蛇咬，坐下别动、摘掉戒指手表、尽快送医院打抗蛇毒血清，不切、不吸、不绑死', '为什么被蛇咬，坐下别动、摘掉戒指手表、尽快送医院打抗蛇毒血清，不切、不吸、不绑死？', '坐下别动，把被咬的肢体固定住。先摘掉戒指手表，接下来会肿。尽快送到有抗蛇毒血清的医院，血清是唯一能逆转大部分毒性作用的东西。不切开，不用嘴吸，不冰敷，不用绳子勒到发紫。别喝酒，别跑动。能远远拍张蛇的照片就拍，别去抓。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-30', '地震时先看自己在什么房子里：符合抗震设防的楼里就地躲，会垮的老房子门在几步外就出去', '为什么地震时先看自己在什么房子里：符合抗震设防的楼里就地躲，会垮的老房子门在几步外就出去？', '先看自己在什么房子里。2001 年以后按规范建的楼，要下楼梯、穿门厅才能出去的，就地躲：护住头颈钻到结实桌子下面，抓牢桌腿。平房、老砖房、没抗震设防的自建房，门就在几步外，出去。任何情况都不跳楼、不坐电梯、不在摇晃中下楼梯。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-31', '遇到熊、野猪、成群野狗，别跑、别尖叫、别对视，侧身慢慢退开', '为什么遇到熊、野猪、成群野狗，别跑、别尖叫、别对视，侧身慢慢退开？', '别跑，熊上下坡都跑得像赛马。也别爬树，黑熊棕熊都会爬。站住，低声一直跟它说话，等它不动了再侧身慢慢退开。棕熊扑上来就趴下装死，双手扣在颈后、两腿分开。黑熊扑上来不装死，往车里或屋里跑，跑不掉就拿手边东西反击。被狗抓咬按第 13 条冲洗打针。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-32', '野外遇上雷雨，钻进有硬顶的车或建筑，避开山脊、孤树、水面和金属', '为什么野外遇上雷雨，钻进有硬顶的车或建筑，避开山脊、孤树、水面和金属？', '雷暴范围内的户外没有安全的地方。钻进硬顶的车或者建筑，敞篷车、摩托、帐篷、凉亭、树下、突出的岩石下面都不算。避开开阔地、山脊山顶、孤立的大树、水面和铁栏杆。一群人走不了就散开站。听见雷就撤，最后一声雷过去 30 分钟才算安全。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-33', '上高原按睡眠海拔（当晚睡在多高）慢慢升，症状加重就下撤，不要硬扛', '为什么上高原按睡眠海拔（当晚睡在多高）慢慢升，症状加重就下撤，不要硬扛？', '算的是睡在多高，不是白天到过多高。睡在 2450 米以上就有高原病风险。过了 3000 米之后，每晚睡觉的高度只往上加 500 米，每升 1000 米多留一天适应。头痛加恶心、走路打晃、意识变化，或者不动也喘不上气，就往下走。下撤排在吸氧和吃药前面。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-34', '被蜱虫叮住，用尖头镊子贴着皮肤稳稳拉出来，别涂油别用火烧', '为什么被蜱虫叮住，用尖头镊子贴着皮肤稳稳拉出来，别涂油别用火烧？', '用尖头镊子贴着皮肤夹住蜱的头部，稳稳地朝外拉出来。别涂油，别用火烧，别扭着拽，那会刺激它把带病原体的体液挤进皮肤，还容易把口器留在肉里。拔完记下日期。之后几周里发烧、起疹、乏力，看病时主动说被蜱咬过。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-35', '野外的水一律烧开再喝，滚开一分钟就够，不用因为海拔高多煮', '为什么野外的水一律烧开再喝，滚开一分钟就够，不用因为海拔高多煮？', '所有能靠喝水致病的微生物，在沸点温度下几秒就死了。再滚一分钟，只是给「看走眼」留的余量，不用因为海拔高就多煮。烧不了就用过滤器或者消毒片，这两样各有覆盖不到的病原体，能烧还是烧。看着清澈的溪水、雪水一样可能有寄生虫。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-36', '荒郊野外被陌生人索财，钱给他，不动手，记特征，脱身后报警', '为什么荒郊野外被陌生人索财，钱给他，不动手，记特征，脱身后报警？', '钱给他，不动手，不还嘴。对方为几百块冒的是抢劫罪：三年以上十年以下起步，入户、持枪、致人重伤死亡的十年以上，直到死刑。他拿了钱转身走，你追上去打就不再算正当防卫。脱身后立刻记下体貌、口音、车牌和逃跑方向，打 110。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-37', '撞见一群人打架，退开走人，别上去拉架、别围观、别捡地上的家伙；要报警就退到安全距离打 110', '为什么撞见一群人打架，退开走人，别上去拉架、别围观、别捡地上的家伙；要报警就退到安全距离打 110？', '你一动手，劝架就成了参加打架。参加聚众斗殴判 3 年以下，人多、在马路上、拿了家伙的判 3 到 10 年。围观也容易被误伤。该做的是退开走人。愿意报警就退到安全距离打 110，说清地点、几个人、有没有拿刀棍、有没有人躺下不动。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-38', '可能被 HIV 暴露了，72 小时内去拿阻断药，越早越好', '为什么可能被 HIV 暴露了，72 小时内去拿阻断药，越早越好？', '怀疑自己被传染上艾滋病，72 小时是硬线，最好 2 小时内就吃上药。药要连吃 28 天。超过 72 小时这条路就没了，所以别等到第二天再决定。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 死亡率","钱 多","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-39', '救人受了伤、搭进了钱，先找加害人和医保，再去申报见义勇为确认', '为什么救人受了伤、搭进了钱，先找加害人和医保，再去申报见义勇为确认？', '救人把自己搭进去，不用自认倒霉。见义勇为负伤的先救治、后收费。医疗费由加害人出，人跑了或者赔不起的走基本医保。没有加害人的，被你救下的人依法应当给适当补偿。同时去申报见义勇为确认，受了伤的按工伤保险待遇落实。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-40', '刀、钢筋、玻璃扎进身体，压住异物周围止血，不要把它拔出来', '为什么刀、钢筋、玻璃扎进身体，压住异物周围止血，不要把它拔出来？', '拔出来可能造成大出血，也会让医生更难判断伤了多深。做法是：打 120，用手或者敷料压住异物周围止血，把异物垫稳别让它晃。肚子上的伤口有内脏露出来，不要往回塞，盖一块干净的湿敷料。胸口的伤口在冒泡的，别用塑料布封死，封死可能把肺压瘪。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-41', '怀疑骨折就别再动那个部位，托着不动、冷敷 20 分钟以内，别自己掰正', '为什么怀疑骨折就别再动那个部位，托着不动、冷敷 20 分钟以内，别自己掰正？', '手脚受了伤先当骨折处理，能站能动也排除不了。伤处保持不动，用手托住或用硬板在原位撑住，冷敷一次不超过 20 分钟。别自己掰正，骨头戳出皮肤的先止血，别按回去。X 光可能漏看骨折。片子正常但医生仍怀疑骨折或者韧带伤的，按医生说的复查或做核磁。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-42', '被性侵之后，先到安全的地方打 110；验伤之前别洗澡、别洗衣服、别收拾房间，72 小时内去医院', '为什么被性侵之后，先到安全的地方打 110；验伤之前别洗澡、别洗衣服、别收拾房间，72 小时内去医院？', '身上、衣服上和屋里留下的痕迹，是指认对方最要紧的证据。所以验伤前尽量别洗澡，也别洗衣服、收拾房间，尽早打 110。紧急避孕药药店就有，越早吃越有效。72 小时内去医院，让医生判断要不要吃阻断药。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-43', '不满 1 岁的婴儿噎住哭不出声，趴着拍背 5 下、翻过来按胸口 5 下，轮着做，别按肚子', '为什么不满 1 岁的婴儿噎住哭不出声，趴着拍背 5 下、翻过来按胸口 5 下，轮着做，别按肚子？', '孩子还能咳、能哭出声，就让他自己咳，你在旁边盯着。哭不出声、脸发紫，就让人打 120，你把孩子脸朝下趴在前臂上，用掌根在两块肩胛骨中间拍 5 下。没出来就翻过来，在胸口正中快速按 5 下，两样轮着做，别按肚子。孩子没反应了就改做心肺复苏。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s13-44', '不满 1 岁的婴儿没反应、没正常呼吸，开免提打 120，做婴儿心肺复苏：按 30 下吹 2 口气', '为什么不满 1 岁的婴儿没反应、没正常呼吸，开免提打 120，做婴儿心肺复苏：按 30 下吹 2 口气？', '拍脚底没反应、没正常呼吸，就开免提打 120，手不停。双手环抱胸口用两个拇指按，抱不住就用一只手的掌根，按下去约 4 厘米，每秒约 2 下。每按 30 下，嘴包住孩子口鼻吹 2 口气。婴儿心跳停多半是喘不上气引起的，做了带吹气的心肺复苏，活下来的更多。', 'living', '13. 紧急情况：先做什么', 'published', 1, 'reference_book', 95, '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-1', '邮箱、支付、社交账号都开二次验证，优先用手机弹窗确认，其次才是短信验证码', '为什么邮箱、支付、社交账号都开二次验证，优先用手机弹窗确认，其次才是短信验证码？', '二次验证是指登录时除了密码，还要再确认一次是不是本人。用手机上弹个窗、你点一下确认的办法，九成以上的钓鱼盗号都被拦住了。靠回答「上次在哪登的」「备用邮箱是什么」这种老办法，钓鱼盗号只能拦下一成左右。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-2', '邮箱密码单独一个，不和任何网站重复', '为什么邮箱密码单独一个，不和任何网站重复？', '别的网站被偷走的密码，会被人拿来直接登你的邮箱。邮箱一旦被人登进去，凡是能用邮箱找回密码的账号，都跟着一起丢。所以邮箱的密码要单独一个，别的地方一律不用。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-3', '手机设锁屏密码，SIM 卡设 PIN 码', '为什么手机设锁屏密码，SIM 卡设 PIN 码？', 'SIM 卡就是手机里那张小卡片，短信验证码靠它来收。手机丢了，捡到的人会把这张卡拔下来，插进别的手机收验证码，再挨个重置你的账号。给卡设一个 PIN 码，卡换到别的手机上，一开机就要先输这个码，这条路就断了。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-4', '手机丢了按这个顺序做：挂失 SIM 卡、远程锁定、改密码、报警、冻结银行卡', '为什么手机丢了按这个顺序做：挂失 SIM 卡、远程锁定、改密码、报警、冻结银行卡？', '顺序比手快更重要。第一步挂失 SIM 卡，验证码这条命脉就断了。接着远程锁住手机，再用电脑改邮箱和支付密码，然后报警拿回执，最后看情况冻结银行卡。手机不在身上，借别人的手机打运营商客服也能挂失。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-5', '卡被盗刷先挂失冻结再报警，然后要求银行赔：证明「是你自己刷的」是银行的责任', '为什么卡被盗刷先挂失冻结再报警，然后要求银行赔：证明「是你自己刷的」是银行的责任？', '卡被人盗刷，不用你去证明「这不是我刷的」。反过来，是银行要拿出证据证明这笔是你本人刷的，拿不出就得赔你。前提是你一发现就挂失冻结。拖着不挂失，后面多出来的损失要自己承担。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-6', '每隔一段时间看一次账号的登录设备和已授权应用，不用的清掉', '为什么每隔一段时间看一次账号的登录设备和已授权应用，不用的清掉？', '「登录设备」是指现在还能用你账号的那些手机和电脑。盗号的人常常先潜伏一阵再动手。列表里冒出你不认识的设备，或者早就不用的软件还连着你的账号，看到就退出全部登录，再改密码。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-7', '别为了用 App 点「全部同意」：不是必需的信息，你不同意也不能拒绝给你服务', '为什么别为了用 App 点「全部同意」：不是必需的信息，你不同意也不能拒绝给你服务？', 'App 要你的信息，如果不是提供这项服务必须用的，你不同意给，它不能因此不让你用。它能收的，也只限于用得着的那些。地图要你的位置是必须的，手电筒要你的通讯录就不是。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-8', '你有权查看、复制、更正和删除自己的个人信息，被拒绝可以起诉', '为什么你有权查看、复制、更正和删除自己的个人信息，被拒绝可以起诉？', '你有权要求企业让你查看、复制、更正和删除自己的信息。服务停了、保存期限到了、你撤回同意的，企业本来就该自己删掉。它拒绝你，必须说明理由；不办，你可以直接去法院告它。注销账号和删除信息是两件事，注销之后还要另外提删除。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-9', '刷脸不是必须答应的：有别的办法就不能只让你刷脸，你不同意得给你其他方式', '为什么刷脸不是必须答应的：有别的办法就不能只让你刷脸，你不同意得给你其他方式？', '只要还有别的办法能办成同一件事，对方就不能只让你刷脸。你不同意刷脸，它得给你刷卡、密码或者身份证这类别的办法，也不许拿「那就办不了业务」来逼你。宾馆客房、公共浴室、更衣室、卫生间这些地方，谁都不许装人脸识别设备。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s14-10', '别把代码、密钥和隐私资料交给来路不明的「AI 中转站」，让 AI 自动执行命令时尤其如此', '为什么别把代码、密钥和隐私资料交给来路不明的「AI 中转站」，让 AI 自动执行命令时尤其如此？', '中转站夹在你和模型厂商中间，你发出去的内容和收回来的回答，它都看得见、改得了。有研究测了 400 多个中转站，9 个往回答里塞恶意代码，17 个动了研究者故意放进去的云服务密钥。让 AI 自动执行命令的，一条被改过的命令就够让电脑被人控制。', 'living', '14. 账号与信息安全', 'published', 1, 'reference_book', 95, '{"14. 账号与信息安全","B 级","性价比 一般","口径 自由","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-1', '押金的数额、退还时间和扣减情形，必须写进合同', '为什么押金的数额、退还时间和扣减情形，必须写进合同？', '押金多少、什么时候退、什么情况下能扣，签字前就要写进合同。合同里没写的扣款理由，房东退租时不能拿来扣你的押金。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-2', '被断水断电、换锁、上门威胁赶人，先报警留证：法规禁止用这些方式逼你腾房', '为什么被断水断电、换锁、上门威胁赶人，先报警留证：法规禁止用这些方式逼你腾房？', '房东不能靠断水断电、换锁、上门威胁逼你解约或者搬走，法规明令禁止。遇上了先报警。出警记录是你以后要求赔损失的证据。不要自己动手和对方对抗。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-3', '中介不得代收代付租金和押金，钱直接给房东', '为什么中介不得代收代付租金和押金，钱直接给房东？', '按规定，房租和押金不能由中介代收代付，钱直接付给房东。钱在中介手里过一道，就多一次它卷款跑路的机会。真跑了，你租金白交，还会被房东赶走。付款前核对收款人是不是产权证上的名字。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-4', '租长租公寓先查它的资金监管账户，别图便宜一次性付一年', '为什么租长租公寓先查它的资金监管账户，别图便宜一次性付一年？', '一次性付一年，拿到的折扣就那么点。公司一旦倒了，你的押金和剩下十几个月的房租一起没。绑了租金贷更糟：公寓跑了，贷款还是你按月还完。签约前先查它有没有公示资金监管账户。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-5', '房子租期内被卖掉，租约继续有效，不用搬', '为什么房子租期内被卖掉，租约继续有效，不用搬？', '租期内房子被卖掉，你的租约照样有效。新房东要按原来的合同让你住到期满。不用搬，也不用重新谈价钱。前提是你已经合法住在里面，合同、转账记录、入住时间的证据都留好。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-6', '签约前核对产权证和抵押情况，所有款项走转账并备注用途', '为什么签约前核对产权证和抵押情况，所有款项走转账并备注用途？', '最常见的两种血本无归，一是租金付给了不是产权人的人，二是房子早就抵押给银行、后来被查封。签约前去不动产登记中心查一次产权和抵押。所有钱走转账，备注写「某某房屋某月租金」，出了纠纷这就是直接证据。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-7', '二手房让中介代收房款的，必须走中介在银行开的交易资金专用存款账户', '为什么二手房让中介代收房款的，必须走中介在银行开的交易资金专用存款账户？', '房款是几十万到几百万，是这本书里单笔金额最大的一件事。中介代收房款的，按规定必须走它在银行开的专用账户，不能微信转给经纪人个人。另外，两家中介合做一单只能收一份佣金，代办贷款、代办过户要单独签合同、事先说清收费。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-8', '别租隔断房：最小出租单位是原设计的房间，厨房、卫生间、阳台不得住人', '为什么别租隔断房：最小出租单位是原设计的房间，厨房、卫生间、阳台不得住人？', '按规定，最小的出租单位是原来设计好的那间房。厨房、卫生间、阳台和地下储藏室不能住人。这种房被查处之后，你可能要搬走。另外，租期内房东也不能自己说涨租就涨租。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s15-9', '城镇户口想搬去乡下住，只租农房，别买宅基地和宅基地上的房子', '为什么城镇户口想搬去乡下住，只租农房，别买宅基地和宅基地上的房子？', '城镇户口的人不能到农村买宅基地、农民的房子或者「小产权房」，国家文件明令禁止。村里人说「写个合同就行」也不行，钱付出去，房子也成不了你的。想在乡下长住，就签租赁合同，一次最长签 20 年，到期再续。', 'living', '15. 租房与买房', 'published', 1, 'reference_book', 95, '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-1', '药按医嘱吃满，别感觉好了就停', '为什么药按医嘱吃满，别感觉好了就停？', '按医生说的把药吃满的人，同期死亡的可能性大约只有断断续续吃药的人的一半。这个数要打折看。连假药都吃满的人死亡率也低，说明有一部分好处来自「能坚持吃药的人本来就更注意健康」。但停药的害处是确定的，降压药、抗凝药、抗排异药尤其如此。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-2', '先办门诊慢特病认定再办异地备案，高血压、糖尿病、放化疗、透析、抗排异就能异地直接结算', '为什么先办门诊慢特病认定再办异地备案，高血压、糖尿病、放化疗、透析、抗排异就能异地直接结算？', '高血压、糖尿病、恶性肿瘤门诊放化疗、尿毒症透析、器官移植后抗排异，这五种在外地看门诊也能直接刷医保。不用先自己垫钱，再回参保地报销。但要先在参保地办门诊慢特病认定，再办异地就医备案。两件事都办了才管用。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-3', '复查按医生给的间隔做，把每次的指标记在同一个本子上', '为什么复查按医生给的间隔做，把每次的指标记在同一个本子上？', '慢性病看的是一段时间里的变化，不是某一次的数值。把日期、指标、当时吃的药和剂量记在同一个本子上。换医院的时候拿出来，不用把检查重做一遍、重花一遍钱。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-4', '别为了试偏方、保健品停掉正规治疗', '为什么别为了试偏方、保健品停掉正规治疗？', '停药的坏处是确定的，偏方和保健品的好处是不确定的。这等于拿确定的损失去换不确定的好处。想试补充剂就先告诉主治医生。有些补充剂会影响抗凝药、抗排异药在血里的浓度。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-5', '病情稳定的慢性病，在社区医院一次可以开到 12 周的药', '为什么病情稳定的慢性病，在社区医院一次可以开到 12 周的药？', '病情稳定、吃的药也没换的人，在社区卫生服务中心一次能开够 12 周的药。省掉每月往返大医院排队挂号的半天。在同一个参保地里，住基层医院的报销比例通常还比上一级医院高十个百分点左右。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-6', '在社区签家庭医生之前，问清楚哪些进医保、哪些自费', '为什么在社区签家庭医生之前，问清楚哪些进医保、哪些自费？', '签约的基本服务包按规定走医保。个性化服务包的钱要全部自己出。有人推销「升级包」的时候，先问清楚这是基本包还是个性化包、备没备案、一年多少钱。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-7', '确诊糖尿病就去查一次眼底，之后按医生给的间隔查；每年查一次脚', '为什么确诊糖尿病就去查一次眼底，之后按医生给的间隔查；每年查一次脚？', '糖尿病伤到眼底、伤到脚，在坏到看不见、烂起来之前几乎没有感觉。早查出来还有得治。2 型糖尿病确诊当时就查一次散瞳眼底，1 型在发病 5 年后开始查。查过一两次没事、血糖也达标的，可以放宽到一两年一次。脚每年查一次。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-8', '得过肾结石就把水喝到每天 2.5–3 升，盐降到 6 克以内', '为什么得过肾结石就把水喝到每天 2.5–3 升，盐降到 6 克以内？', '第一次长了钙结石的人，什么都不做的话，五年里约四分之一会再长。每天把水喝够的人，五年里复发的只有一成多，少了一半多。英国指南给的量是每天喝 2.5 到 3 升水，盐不超过 6 克。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s16-9', '确诊痛风就长期吃降尿酸药，把血尿酸压到 360 µmol/L 以下并一直维持', '为什么确诊痛风就长期吃降尿酸药，把血尿酸压到 360 µmol/L 以下并一直维持？', '痛风要长期吃降尿酸药，把尿酸压到 360 µmol/L 以下，不能只在疼的时候吃止痛药。由护士按化验结果帮着调药量的病人，两年后 95% 达标，照常看病的只有 30%。达标之后也不能停药。靠忌口降不到这条线，戒酒也只低 1.6 mg/dL。', 'living', '16. 得了慢性病之后怎么活', 'published', 1, 'reference_book', 95, '{"16. 得了慢性病之后怎么活","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-1', '趁老人清醒，书面指定将来的监护人', '为什么趁老人清醒，书面指定将来的监护人？', '趁老人头脑还清楚，花几百元去公证处办一份书面文件，写明将来谁当他的监护人。没有这份文件，等老人不能自己做决定了，谁替他签字、谁替他管钱，要由法院来指定。家里人意见不一致，还会拖得更久。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-2', '把遗嘱立了，记住后立的推翻先立的，公证遗嘱不再优先', '为什么把遗嘱立了，记住后立的推翻先立的，公证遗嘱不再优先？', '法律认六种遗嘱，但形式写错了整份作废，这是最常见的翻车点。自己手写的那种，要本人从头到尾手写，签上名，写清年月日。立了好几份、内容互相打架的，按最后立的那份算。2021 年起，公证过的那份也不再自动排在前面。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-3', '老人的钱单独放一个账户，大额支出定一个双人确认的规矩', '为什么老人的钱单独放一个账户，大额支出定一个双人确认的规矩？', '骗老人买保健品、买收藏品、买理财的，套路都一样：先花几个月和他处熟，再一次性收割。事先约好一条规矩，超过多少钱的支出要先跟某个人说一声。这等于把掏钱那一刻往后拖，拖过最冲动的那一阵。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-4', '给老人备好一句随时能说出口的推辞：「我要回去和家里人商量」', '为什么给老人备好一句随时能说出口的推辞：「我要回去和家里人商量」？', '推销和诈骗靠的是现场压力，让人当场不好意思拒绝。事先和老人商量好一句话：「我要回去和家里人商量。」他随时能说出口，当场有台阶下。这比事后再跟他讲道理管用。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-5', '凡是让老人先交钱的「投资养老」都别碰：办卡、买床位、买养老公寓、旅居养老、买老年产品是同一套非法集资', '为什么凡是让老人先交钱的「投资养老」都别碰：办卡、买床位、买养老公寓、旅居养老、买老年产品是同一套非法集资？', '让老人先交钱、又许诺回报的养老名目，都是同一套骗局：办卡、买床位、买养老公寓、旅居养老、开会卖老年产品。按规定，这种钱亏了只能自己认。有人借预定养老公寓床位收走 1.36 亿元，坑了 2100 多人。能拦住的只有掏钱那一步。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-6', '除了保险公司的住房反向抵押养老保险，其他「以房养老」都别碰，绝不抵押房子去买理财', '为什么除了保险公司的住房反向抵押养老保险，其他「以房养老」都别碰，绝不抵押房子去买理财？', '正规的以房养老只有一种，就是保险公司的住房反向抵押养老保险，还在试点。上门推销的那种和它毫无关系，是骗老人抵押房子，再拿借来的钱买它推荐的理财。有人连房子被抵押了都不知道，最后房子没了，还背着贷款。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-7', '家里老人长期卧床或重度失能，去参保地医保部门申请长期护理保险；它不是只发给老人', '为什么家里老人长期卧床或重度失能，去参保地医保部门申请长期护理保险；它不是只发给老人？', '长期护理保险帮你出请人照护的钱。家里有人重度失能、持续半年以上，就去参保地医保部门申请。护理费不用先自己垫，职工参保的报七成左右，城乡居民参保的报五成左右，床位费、伙食费不报。它没有年龄门槛，年轻人重度失能也能申请。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-8', '家里有人长期卧床，把压疮当头号敌人：上电动气垫床、定时翻身、每天看一遍骨头突出的地方', '为什么家里有人长期卧床，把压疮当头号敌人：上电动气垫床、定时翻身、每天看一遍骨头突出的地方？', '髋部骨折开刀前就有压疮的老人，30 天内去世的可能性高约两成。换电动气垫床，新长压疮的少约六成。按时翻身真正做到位，少约七成。别让人长时间趴着。每天看一遍骶尾、足跟、髋部、肩背，发现压了不褪的红，当天找护士或医生。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","B 级","性价比 一般","口径 死亡率","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s17-9', '老人的白内障已经影响看路，就去眼科评估做手术；两只眼都有的，第二只别拖太久', '为什么老人的白内障已经影响看路，就去眼科评估做手术；两只眼都有的，第二只别拖太久？', '70 岁以上的女性尽快做第一只眼的白内障手术，一年里跌倒的次数少约三成四，骨折的人也少了。但摔过跤的人数没有少。第二只眼做不做，跌倒上没看出明显差别。做了手术的老人，一年内髋部骨折低约一成六。', 'living', '17. 家里有老人', 'published', 1, 'reference_book', 95, '{"17. 家里有老人","B 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s18-1', '先把能领的算进来：国家育儿补贴每孩每年 3600 元，发到 3 岁', '为什么先把能领的算进来：国家育儿补贴每孩每年 3600 元，发到 3 岁？', '孩子在 2025 年 1 月 1 日以后出生、还不满 3 周岁，就能领这笔钱。父母中的一个人去孩子户口所在地申请。每个孩子每年 3600 元，一直领到 3 岁。这笔钱不用交个人所得税。申请低保这类救助时，也不算进你家的收入。', 'living', '18. 养孩子划不划算', 'published', 1, 'reference_book', 95, '{"18. 养孩子划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s18-2', '产假 98 天，生育津贴由生育保险基金按单位上年度职工月平均工资发', '为什么产假 98 天，生育津贴由生育保险基金按单位上年度职工月平均工资发？', '生孩子至少能休 98 天产假，其中产前可以先休 15 天。难产再加 15 天。每多生一个孩子，也再加 15 天。这段时间发的钱叫生育津贴，由生育保险基金出。单位没给你上生育保险的，就由单位自己发。', 'living', '18. 养孩子划不划算', 'published', 1, 'reference_book', 95, '{"18. 养孩子划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s18-3', '知道这条：不得因怀孕、生育、哺乳降工资或者辞退', '为什么知道这条：不得因怀孕、生育、哺乳降工资或者辞退？', '怀孕、生孩子、喂奶这几段时间里，单位给你降工资或者把你辞了，都是违法的，要按每人 1000 到 5000 元罚款。孩子不满一周岁的，你每天有 1 小时喂奶时间，单位也不能安排你加班和上夜班。索赔怎么走见第 19 节。', 'living', '18. 养孩子划不划算', 'published', 1, 'reference_book', 95, '{"18. 养孩子划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s18-4', '时间账按「谁的时间被占掉」算，不按「辛不辛苦」算', '为什么时间账按「谁的时间被占掉」算，不按「辛不辛苦」算？', '把每天看孩子的小时数、夜里被吵醒的次数，都折算成时间。再乘上干这些活的那个人的时薪。算出来的数，一般远远大于奶粉尿布钱。所以分工最好在生之前就谈好。', 'living', '18. 养孩子划不划算', 'published', 1, 'reference_book', 95, '{"18. 养孩子划不划算","C 级","性价比 一般","口径 时间","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s18-5', '钱账分三段算：0 到 3 岁、义务教育、义务教育之后', '为什么钱账分三段算：0 到 3 岁、义务教育、义务教育之后？', '0 到 3 岁的钱，主要花在怎么带上：自己带、老人带，还是请人带。小学到初中这段，主要花在住房和课外。再往后，主要花在升学这条路上。三段的花法完全不同，混在一起只会算出一个吓人的总数。', 'living', '18. 养孩子划不划算', 'published', 1, 'reference_book', 95, '{"18. 养孩子划不划算","C 级","性价比 一般","口径 金钱","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s18-6', '为长辈生、为婚姻生、为养老生，各记一笔账', '为什么为长辈生、为婚姻生、为养老生，各记一笔账？', '别人希望你生，这可以算你的一个考虑因素。但时间和钱是记在你自己账上的。「养儿防老」要单独算一笔，因为它赌的是二十年后另一个人的经济能力和意愿。把不生的后果也写下来，两边对照。', 'living', '18. 养孩子划不划算', 'published', 1, 'reference_book', 95, '{"18. 养孩子划不划算","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-1', '加班费按 1.5 倍、2 倍、3 倍三档算，不给就投诉劳动监察，逾期不付还要加付 50% 到 100%', '为什么加班费按 1.5 倍、2 倍、3 倍三档算，不给就投诉劳动监察，逾期不付还要加付 50% 到 100%？', '平时加班按工资的 1.5 倍给钱。休息日加班又没让你补休，按 2 倍。元旦、春节、劳动节、国庆这类法定假日上班按 3 倍，而且不能拿补休顶掉。公司不给，就去劳动监察投诉。被责令限期付款以后还不给的，单位还要另加付欠款的一半到一倍。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-2', '年休假按累计工龄算 5、10、15 天，没休成的按日工资 300% 折钱', '为什么年休假按累计工龄算 5、10、15 天，没休成的按日工资 300% 折钱？', '在所有单位的工龄加起来满 1 年不满 10 年，每年 5 天年休假。满 10 年是 10 天，满 20 年是 15 天。换过工作也照样往上累计。单位安排不了、你又同意不休的，那几天按日工资的 3 倍给钱。「自愿放弃年休假」的表一签，就只剩正常工资了。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-3', '试用期有法定上限、工资不得低于 80%，而且只能约定一次', '为什么试用期有法定上限、工资不得低于 80%，而且只能约定一次？', '合同签 1 年以内的，试用期最多 1 个月。签 1 到 3 年的最多 2 个月。签 3 年以上的最多 6 个月。同一家公司只能试用你一次，转正后调个岗再来一次是违法的。试用期工资不能低于同岗位最低档或者合同约定工资的 80%，也不能低于当地最低工资。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-4', '被裁先算清 N：每满一年一个月工资，不满六个月按半个月', '为什么被裁先算清 N：每满一年一个月工资，不满六个月按半个月？', '被裁时公司要给的经济补偿这样算：干满一年给一个月工资，满半年不满一年按一年算，不满半年给半个月。这里的月工资是走人前 12 个月的平均数，奖金、津贴、补贴都要算进去。工资高过当地上年度月平均工资 3 倍的按 3 倍封顶，年限最多算 12 年。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-5', '公司辞退你没提前 30 天通知，还要多付一个月工资', '为什么公司辞退你没提前 30 天通知，还要多付一个月工资？', '公司因为你病后干不了、干不了工作或者情况大变而辞退你，没有提前 30 天书面通知，要在 N 之外再多给一个月工资，这就是常说的 N+1。谈的时候把这一个月单独列出来，别让公司把它算进 N 里面。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-6', '公司违法解除的，赔偿金是经济补偿标准的二倍', '为什么公司违法解除的，赔偿金是经济补偿标准的二倍？', '公司属于违法解除的，赔偿金按经济补偿的标准翻倍，也就是常说的 2N。是不是违法解除要看具体情形。先找法律援助或者律师问清楚，再决定是跟公司谈，还是去仲裁。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-7', '不要签「个人原因主动辞职」，那一签就没有 N 了', '为什么不要签「个人原因主动辞职」，那一签就没有 N 了？', '签字承认「个人原因主动辞职」，经济补偿和失业保险金通常一起落空。自己提出离职，本来就不在给补偿的那几种情形里，公司欠薪、不缴社保这类过错除外。不必当天签，冷静一晚再说。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-8', '离职前把工资条、考勤、劳动合同、社保记录和聊天记录先存下来', '为什么离职前把工资条、考勤、劳动合同、社保记录和聊天记录先存下来？', '电脑和账号一交回去，工资条、考勤、合同、社保记录和聊天记录就再也拿不到了。仲裁时工资多少、有没有加班，还是要靠你自己手上的材料。存的是自己的劳动关系材料，公司的源码和客户名单不要带走。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-9', '进有粉尘、噪声、化学品的岗位之前，先看合同里写没写危害；三次职业健康检查由单位安排并掏钱', '为什么进有粉尘、噪声、化学品的岗位之前，先看合同里写没写危害；三次职业健康检查由单位安排并掏钱？', '签合同时，单位必须把岗位有什么职业病危害、怎么防护、有什么待遇如实写进合同。瞒了你，你可以拒绝干这个活，单位不能因此辞退你。上岗前、在岗时、离岗时三次职业健康检查，由单位安排并掏钱。没做离岗体检，单位不能和你解除合同。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-10', '粉尘、噪声、化学毒物造成的损伤不可逆：防护用品单位必须给，没有防护措施的作业可以拒绝', '为什么粉尘、噪声、化学毒物造成的损伤不可逆：防护用品单位必须给，没有防护措施的作业可以拒绝？', '尘肺、噪声聋、化学性眼灼伤都是法定职业病，肺和听力坏了就治不回来。你有权知道岗位有什么危害，有权要单位给防护设施和防护用品。没有防护的活你可以不干。单位因此给你降薪或辞退你，都不算数。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-11', '上班受伤、上下班路上被撞，第一件事是做工伤认定，单位不报你自己报', '为什么上班受伤、上下班路上被撞，第一件事是做工伤认定，单位不报你自己报？', '上班受伤算工伤。上下班路上被撞、主要责任不在你的，也算工伤。但不做工伤认定，医药费、养伤期间照发的工资、伤残补助金就全部落空。单位应当在 30 天内申报。单位不报的，你或者家属、工会可以在一年内自己去社保行政部门报。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-12', '别信「撑到工位就算工伤」：突发不适先打 120，不是先赶去打卡', '为什么别信「撑到工位就算工伤」：突发不适先打 120，不是先赶去打卡？', '突发不适往公司赶，不会让你多拿一笔钱。视同工伤要求人在工作时间、又在工作岗位上发病，路上发病没到岗的本来就不算。抢救超过 48 小时的反而也不算。为了凑条件耽误的那几十分钟，换掉的是自己的存活率。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-13', '单位没给你交工伤保险，工伤待遇一样有，由单位按同样的标准全额出', '为什么单位没给你交工伤保险，工伤待遇一样有，由单位按同样的标准全额出？', '单位没给你交工伤保险，工伤待遇一样有。只是改成由单位按同样的项目和标准全额付，一分不少。没参保是对单位加罚：责令补缴、按日加收万分之五滞纳金，逾期还要罚欠缴额的 1 到 3 倍。「公司没买工伤险所以赔不了」是假话。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-14', '伤情稳定后去做劳动能力鉴定，伤残等级直接换算成钱', '为什么伤情稳定后去做劳动能力鉴定，伤残等级直接换算成钱？', '伤情稳定之后去做劳动能力鉴定，等级直接换算成钱。一次性伤残补助金按本人工资算：五级 18 个月、六级 16 个月、七级 13 个月、八级 11 个月、九级 9 个月、十级 7 个月。鉴定结果出来之前，不要签「一次性了结」的协议。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-15', '工亡的三笔钱要分清：丧葬补助金、供养亲属抚恤金、一次性工亡补助金', '为什么工亡的三笔钱要分清：丧葬补助金、供养亲属抚恤金、一次性工亡补助金？', '因工死亡是三笔钱，别只谈其中一笔。丧葬补助金是当地上年度职工月平均工资的 6 个月。供养亲属抚恤金按死者本人工资按月发，配偶每月 40%，其他亲属每人每月 30%。一次性工亡补助金是上一年度全国城镇居民人均可支配收入的 20 倍，全国就这一个数。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-16', '在单位长期被欺负、辱骂、刁难，别硬扛：先记下来留证据，再按性质走投诉、报警或者仲裁', '为什么在单位长期被欺负、辱骂、刁难，别硬扛：先记下来留证据，再按性质走投诉、报警或者仲裁？', '在单位被欺负的人，后来得心脏病、中风的风险高约六成，被欺负得越多风险越高。被欺负的人几年后冒出自杀念头的几率约是别人的两倍。挨骂受气不是忍一忍就过去的小事。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","B 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-17', '离职时找单位要一份离职证明，写明合同期限、离职日期、岗位和工作年限', '为什么离职时找单位要一份离职证明，写明合同期限、离职日期、岗位和工作年限？', '不管是被辞退、合同到期还是自己辞职，单位都要在你离职时给一份离职证明，并在 15 天内转走档案和社保。证明上要写合同期限、离职日期、岗位和在这家干了几年。办失业登记要用它。单位不给，劳动部门会责令改正，害你受了损失还要赔。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-18', '拿到离职补偿先看个税：当地上年职工平均工资 3 倍以内免税，超出的部分单独算，不并进当年工资', '为什么拿到离职补偿先看个税：当地上年职工平均工资 3 倍以内免税，超出的部分单独算，不并进当年工资？', '因为解除劳动合同拿到的一次性补偿，在当地上年职工平均工资 3 倍以内的部分不交个税。超出的部分单独算税，不和当年工资加在一起。单位要是把整笔并进当月工资扣了税，先找单位问清楚，再打 12366 问税务局。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s19-19', '换城市工作时，把养老和医保关系转到新参保地，缴费年限接着累计，别办退保', '为什么换城市工作时，把养老和医保关系转到新参保地，缴费年限接着累计，别办退保？', '换城市工作，养老和医保关系都能跟着你走，以前交的年限接着往上加。没到领养老金的年龄，不能办退保把钱取出来。医保断交超过 3 个月，到新地方可能要等最多 6 个月才能报销，所以中间别空太久。', 'living', '19. 在职、离职和工伤', 'published', 1, 'reference_book', 95, '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-1', '让孩子仰着睡，睡硬的平面，同房不同床，床上不放任何软东西', '为什么让孩子仰着睡，睡硬的平面，同房不同床，床上不放任何软东西？', '让孩子脸朝上躺着睡，睡在硬的平面上。大人和孩子睡同一间房，但不睡同一张床。床上不放枕头、被子、床围、毛绒玩具和定型枕。斜着的摇篮和婴儿椅只能坐，不能当床睡。光美国每年就有约 3500 个婴儿死在睡眠里。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-2', '出生后 24 小时内打上乙肝疫苗第一针', '为什么出生后 24 小时内打上乙肝疫苗第一针？', '孩子出生后 24 小时之内要打上第一针乙肝疫苗。在婴儿期和幼儿期感染乙肝的人里，约有 95% 会转成慢性肝炎。成年以后才感染的，绝大多数能自己好。所以这一针越早打越有用。妈妈乙肝表面抗原是阳性的，孩子还要同时打乙肝免疫球蛋白。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-3', '按国家免疫规划把该打的疫苗打齐，全程免费，错过了只补没打完的剂次', '为什么按国家免疫规划把该打的疫苗打齐，全程免费，错过了只补没打完的剂次？', '国家免疫规划里的疫苗全程免费，接种单位不能收钱。孩子入托、入学都要查预防接种证，漏打的会被查出来补上。错过了只补没打完的那几剂，不用从头再打，换了厂家也能接着打。湿疹、荨麻疹、过敏性鼻炎、哮喘只要病情稳定，新生儿黄疸也一样，都能正常打。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-4', '前 6 个月只喂母乳，连水都不用喂，6 个月起加辅食并继续母乳', '为什么前 6 个月只喂母乳，连水都不用喂，6 个月起加辅食并继续母乳？', '孩子出生后第一个小时里就开始喂奶。前 6 个月只喂母乳，连水都不用喂。满 6 个月起加辅食，每天要有含铁多的动物性食物，母乳接着喂到 2 岁或更久。母乳不够或者不能喂，就用配方奶，不用自责。喂什么对孩子安危的影响，远没有睡姿大。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-5', '冲奶粉用 70 ℃ 以上的水，冲好放凉再喂，喝剩的倒掉', '为什么冲奶粉用 70 ℃ 以上的水，冲好放凉再喂，喝剩的倒掉？', '奶粉不是无菌的，可能带一种叫阪崎克罗诺杆菌的细菌。新生儿一旦感染，报告的病死率在四成到八成之间。冲的时候先把热水倒进奶瓶，等水温降到约 73.8 ℃ 再放奶粉。这时奶液还在 70 ℃ 以上，能把这种菌杀到原来的十万分之一以下。冲好放凉再喂，喝剩的倒掉。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-6', '不满 1 岁不喂蜂蜜', '为什么不满 1 岁不喂蜂蜜？', '孩子不满 1 岁，不要喂蜂蜜。蜂蜜水、拌进辅食里的蜂蜜、含蜂蜜的糕点，都算。蜂蜜里可能带有引起肉毒中毒的细菌。大人肚子里的菌群能压住它，婴儿压不住。自家做的腌菜和发酵食品，也是同样的道理。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-7', '出生时的维生素 K 针一定要打', '为什么出生时的维生素 K 针一定要打？', '新生儿身体里存的维生素 K 很少，不补可能出血，晚出现的那种常常是脑子里出血。在没普遍打这一针的地方，每 10 万个新生儿有 478 个出这种血。打了这一针，估计能少掉七成八以上。国内正规医院会常规打，在家生或在不正规机构生的，要主动问一句打了没有。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-8', '不满 3 个月的婴儿体温到 38 ℃ 就直接去医院，不在家观察', '为什么不满 3 个月的婴儿体温到 38 ℃ 就直接去医院，不在家观察？', '孩子不满 3 个月，体温到 38 ℃ 就直接去医院。不要在家观察，也不要先喂退烧药再等等看。这个月龄的孩子就算得的是严重细菌感染，也可能只表现为发热。所以「看着精神还行」不能当成在家等的理由。出生不满 8 天的孩子，连指南都没覆盖，更要马上去。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-9', '无论多累多气都不要摇晃婴儿', '为什么无论多累多气都不要摇晃婴儿？', '婴儿的头大，脖子没力气。用力摇晃会让他脑子里、眼睛里出血，可能要了他的命，也可能留下一辈子的残疾。哄睡时轻轻晃不算，危险的是控制不住的猛晃。快压不住火时，把孩子放回婴儿床，人走开几分钟，让他哭一会儿比抱着晃安全。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-10', '尿布不看牌子看三件事：合不合身、换得勤不勤、有没有被抽检通报过', '为什么尿布不看牌子看三件事：合不合身、换得勤不勤、有没有被抽检通报过？', '没有哪个官方机构排过「哪个牌子最好」。能查的只有两样：市场监管总局的产品质量抽检通报，和监管部门对具体事件的调查。贵的不等于安全，进口的不等于合格。先买小包装试一周，看孩子有没有红屁股和勒痕，合适再囤。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","C 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-11', '大件按「借、买二手、买新」的顺序考虑，别一次性配齐', '为什么大件按「借、买二手、买新」的顺序考虑，别一次性配齐？', '婴儿车、婴儿床、抱被、玩具用的时间都短，二手货很多。先问人借，借不到买二手，再不行才买新的，通常能省下上千元。安全座椅和床垫别买二手，座椅撞过以后的损伤眼睛看不出来。月子会所、早教课这类大钱，先冷静 24 小时再定。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","C 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-12', '孩子有严重湿疹或鸡蛋过敏，别躲着花生，按医生指导早点加上，但绝不能喂整粒', '为什么孩子有严重湿疹或鸡蛋过敏，别躲着花生，按医生指导早点加上，但绝不能喂整粒？', '有重度湿疹或鸡蛋过敏的婴儿，从 4 到 11 个月起定期吃花生，到 5 岁时花生过敏的只有 1.9%，完全躲开的是 13.7%。皮试已经有点反应的孩子，吃的是 10.6%，躲的是 35.3%。加之前先带孩子看医生。绝不能喂整粒花生，会噎住气管。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s20-13', '盯住新生儿黄疸的几个信号：出生 24 小时内就黄、越来越黄、叫不醒不吃奶、大便发白，就当天去医院', '为什么盯住新生儿黄疸的几个信号：出生 24 小时内就黄、越来越黄、叫不醒不吃奶、大便发白，就当天去医院？', '八成以上的新生儿会有点黄，多数自己会退。出生不满 24 小时就黄，或者越来越黄、比平时嗜睡叫不醒、不吃奶、身子发软或发硬，要当天去医院。大便颜色发白，可能是胆道闭锁，也要尽快去查。胆红素太高会伤到脑子，留下一辈子的残疾。', 'living', '20. 刚出生的孩子怎么带', 'published', 1, 'reference_book', 95, '{"20. 刚出生的孩子怎么带","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-1', '出发前查一次外交部安全提醒，标了「暂勿前往」的地方就别去', '为什么出发前查一次外交部安全提醒，标了「暂勿前往」的地方就别去？', '外交部把国外的安全风险分成四档，最高的一档叫「暂勿前往」。2026 年 9 月 15 日起，避开高风险的国家和地区写进了行政法规。办证件和出境过关的时候，工作人员还会提醒你，必要时会劝你别去。出发前翻一遍那一页，几分钟的事。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-2', '把 12308 和当地使领馆的领保电话存进手机，再抄一份放钱包，别等出事再找', '为什么把 12308 和当地使领馆的领保电话存进手机，再抄一份放钱包，别等出事再找？', '出事时的求助电话就一个。人在国内打 12308，人在国外打 +86-10-12308。这条热线开通以来接了 300 多万通电话。同一时期，外交部和驻外机构办了 50 多万起领事保护案件。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-3', '知道领事保护能做什么、不能做什么：能探视，不能捞人，费用还得自己付', '为什么知道领事保护能做什么、不能做什么：能探视，不能捞人，费用还得自己付？', '你在国外被抓，使领馆能做的是：向当地核实情况、要求依法公正处理、去看你、开庭时旁听。它不能替你改判，也不能把人领走。别人先垫的食宿、交通、医疗费，最后还是你自己付。所以出国前把钱和保险备好，别把「出事了国家会兜底」当成计划。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-4', '买一份含境外医疗和医疗转运的保险，别只买航班延误险', '为什么买一份含境外医疗和医疗转运的保险，别只买航班延误险？', '在国外看病的钱要自己掏。国内医保基本不报，使领馆也不垫。真正能拖垮一个家的不是门诊费，是重伤以后的住院，还有把人运回国，那得靠专机或者医疗护送。买旅行险主要看两个额度：境外医疗费用，紧急医疗转运与送返。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","C 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-5', '「境外高薪招聘」一律当诈骗看，被骗去做电诈回来还要被限制出境', '为什么「境外高薪招聘」一律当诈骗看，被骗去做电诈回来还要被限制出境？', '月薪高得离谱、不问学历经验、不签正规合同、让你先到边境城市集合、还替你保管护照。这种活去了，人和护照都不在自己手上。出境时材料造假，边检会把你拦下不放行。在境外参与了违法犯罪，回国之后还可能 6 个月到 3 年不准出境。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-6', '境外取现一年不能超过 10 万元人民币，是本人名下所有卡合起来算的', '为什么境外取现一年不能超过 10 万元人民币，是本人名下所有卡合起来算的？', '境外取现的额度不是一张卡一个，是你名下所有银行卡（附属卡也算）合起来算，每个自然年 10 万元人民币。取满了，当年剩下的时间和第二年都不能再在境外取现。停的只是取现，刷卡消费不受影响，也不占你每年 5 万美元的购汇额度。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-7', '护照、签证、身份证都拍照存一份在云端，丢了先报警再补旅行证', '为什么护照、签证、身份证都拍照存一份在云端，丢了先报警再补旅行证？', '护照丢了，使领馆能给你补一张回国用的旅行证件。前提是你能证明自己是谁。手里有资料页、签证页的照片和出入境记录，补办就快得多。你还得先在当地报警拿到回执，出境检查和保险理赔都认这张纸。手机常和护照一起丢，照片别只存在手机里。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-8', '境外自驾先确认当地认不认中国驾照，网上卖的「国际驾照」多数是废纸', '为什么境外自驾先确认当地认不认中国驾照，网上卖的「国际驾照」多数是废纸？', '网上代办的「国际驾照」在中国内地不成立。那本证是 1949 年日内瓦公约缔约方之间互认的翻译件，103 个缔约方里没有中国内地。所以国内不管谁给你办，都没有法律效力。能不能用中国驾照开车，看目的地自己的规定，没确认清楚就别开。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-9', '找中介办签证、留学、移民，先问它有没有在移民管理机构备案', '为什么找中介办签证、留学、移民，先问它有没有在移民管理机构备案？', '2026 年 9 月 15 日起，办签证、留学、移民的中介要向移民管理机构备案。「包过」「保签」「材料我们帮你做」这些话，本身就在明令禁止之列。自己填表填错，顶多这次被拒签。用了假材料被认定弄虚作假，污点会留在你往后的出入境记录里。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-10', '别替陌生人出具邀请函，也别让人借你的名义办出入境手续', '为什么别替陌生人出具邀请函，也别让人借你的名义办出入境手续？', '替别人出邀请函或者申请材料，内容不实，罚的是出具人。个人罚 5000 元到 1 万元，有违法所得一并没收。单位罚 1 万到 5 万，经手的人另外罚 5000 到 1 万。一次人情，换来的是自己掏这笔钱。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s21-11', '出境前把行程、住处和同行人发给一位家人，约好多久联系一次', '为什么出境前把行程、住处和同行人发给一位家人，约好多久联系一次？', '人在境外失联，家里人可以找使领馆求助，使领馆会告诉家属当地怎么报警，立案后还会催办。前提是国内有人知道你该在哪、该什么时候联系。把航班号、住址、同行人电话和约好多久联系一次，发给一个家人就够。', 'living', '21. 出国、旅行与境外安全', 'published', 1, 'reference_book', 95, '{"21. 出国、旅行与境外安全","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-1', '进 KTV、酒吧、密室之前先看一眼安全出口在哪，被锁被堵就换一家', '为什么进 KTV、酒吧、密室之前先看一眼安全出口在哪，被锁被堵就换一家？', '按规定，娱乐场所营业时，疏散通道和安全出口必须畅通。不许封堵，不许上锁，不许摆东西挡路，也不许遮住指示标志。网吧同样不许封门锁窗。做不到就是违法，你可以举报。包厢在地下、只有一个出口、走道堆满杂物的，换一家。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-2', '点单前要价目表，娱乐场所必须明码标价，不接受「先玩后算」', '为什么点单前要价目表，娱乐场所必须明码标价，不接受「先玩后算」？', '按规定，娱乐场所卖服务、卖东西都必须明码标价，还要主动把价目表拿给你看。所谓「天价酒水」，几乎都出在没看过价目表、事后按口头报价结账的场合。进包厢先要单子拍照。点完再要一份确认清单。结账有争议就当场打 12315。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-3', '场子里有人递「东西」就立刻走，容留和提供都不是「帮朋友」', '为什么场子里有人递「东西」就立刻走，容留和提供都不是「帮朋友」？', '娱乐场所不许贩毒、不许提供毒品，也不许留人在里面吸，违反的要停业整顿 3 到 6 个月，重的吊销许可证。你自己吸要受治安处罚。在你订的包厢或住处让人「用一下」，就是容留他人吸毒，属于刑事犯罪。有人掏出不明粉末、片剂、烟弹请你试，当场走。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-4', '不吃陌生人给的糖和零食，不喝离开过视线的饮料，不接别人递的烟弹', '为什么不吃陌生人给的糖和零食，不喝离开过视线的饮料，不接别人递的烟弹？', '现在的毒品不长毒品的样子。掺了合成大麻素的「上头」电子烟，看着和普通电子烟差不多，有人专在酒吧、KTV、宾馆里递给人试。骗人吸的拘留 10 到 15 日、罚 1000 到 5000 元，被骗吸了的人也要拘留 10 到 15 日。饮料离开过视线就换一杯。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-5', '剧本杀、密室别去开在居民楼里或者地下二层以下的', '为什么剧本杀、密室别去开在居民楼里或者地下二层以下的？', '五部门 2022 年的通知写明，剧本娱乐场所不得开在居民楼内，也不得开在地下一层以下。这类场地黑、隔断多、道具易燃，门还常常要解谜才打得开。一旦起火，比普通商铺难跑得多。订之前在点评页看一眼地址和楼层，不合规的换一家。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-6', '心情差就去走或者跑，抗抑郁的效应量（效果大小）跟强度成正比', '为什么心情差就去走或者跑，抗抑郁的效应量（效果大小）跟强度成正比？', '心情差的时候，快走或慢跑改善最明显。其次是瑜伽、力量训练、太极气功，几种差距不大。强度开得越高效果越好，力量训练和瑜伽最容易坚持。这方面的证据质量偏低，能确定的是动比不动好，挑自己坚持得下来的那种。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-7', '焦虑到影响生活时，正念减压课的效果不劣于常用的抗焦虑药', '为什么焦虑到影响生活时，正念减压课的效果不劣于常用的抗焦虑药？', '确诊焦虑障碍的人上 8 周正念减压课，症状改善和吃抗焦虑药艾司西酞普兰几乎一样。吃药的人近八成出过不良反应，有人因此退出。上课的人约一成半出过，没人退出。课得是标准化的 8 周课程，随便一个冥想 App 不算。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-8', '当场想缓过来，用 5 分钟「循环叹息」：吸气两段，呼气拉长', '为什么当场想缓过来，用 5 分钟「循环叹息」：吸气两段，呼气拉长？', '每天做 5 分钟呼吸练习、坚持一个月，情绪改善和呼吸放慢都比同样时长的正念冥想好。几种呼吸法里，把呼气拉长的「循环叹息」最好。做法是用鼻子吸一口，再补吸一小口把肺撑满，然后用嘴慢慢吐尽。这只是一项试验，好坏靠本人自己报，但不花钱。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-9', '把「定期和人见面」当成健康支出，别只在心情差时才找人', '为什么把「定期和人见面」当成健康支出，别只在心情差时才找人？', '平时很少和人来往的人，同期死亡的概率高约三成。感到孤独的人高约四分之一，独居的人高约三成，65 岁以下的人更明显。这些都是跟踪观察出来的，也可能是身体本来就差的人更容易独居。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s22-10', '住得离绿地近就多用它，散步、遛弯、坐着都算', '为什么住得离绿地近就多用它，散步、遛弯、坐着都算？', '住处周边 500 米内的绿化越好，同期死亡的概率越低，按植被指数每提高 0.1 算，低约 4%。量的是住处周边的绿化，不是你去公园的次数。绿化好的地段，住的人往往更有钱、空气也更好。所以别当成去公园就能延寿，选住处时把周边绿地算进去就行。', 'relaxation', '22. 怎么放松：娱乐场所和减压', 'published', 1, 'reference_book', 95, '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-1', '不满 16 周岁没有「去打工」这个选项：招你的单位每月被罚 5000 元，肯招的都是黑工', '为什么不满 16 周岁没有「去打工」这个选项：招你的单位每月被罚 5000 元，肯招的都是黑工？', '初中毕业一般 15 到 16 岁，正好卡在这条线上。不满 16 岁，单位招你就是违法，每用一名童工每月罚 5000 元。所以肯要你的，都是明知违法还敢用的单位。真出了事，医药费和赔偿只能找这家单位要，它赖账或者跑了，就没人替它兜底。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-2', '把「读书有没有用」也放进死亡率账里：每多受一年教育，成人死亡风险降约 1.9%', '为什么把「读书有没有用」也放进死亡率账里：每多受一年教育，成人死亡风险降约 1.9%？', '每多读一年书，成年后的死亡风险平均低约 1.9%。18 到 49 岁的人最明显，每多一年低约 2.9%，70 岁以上只低 0.8%。能一直读下去的人往往本来条件就好，这里面有多少是读书本身的作用，分不清。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-3', '判断「学历是不是贬值了」之前，先看全国的学历结构：每 10 万人里只有 15467 人有大学文化程度（2020 年普查，2025 年抽样推算约 19%）', '为什么判断「学历是不是贬值了」之前，先看全国的学历结构：每 10 万人里只有 15467 人有大学文化程度（2020 年普查，2025 年抽样推算约 19%）？', '2020 年人口普查时，全国念到大专及以上的约占 15%。2025 年的抽样调查推算约 19%，五年里多了几个百分点。两次都是初中学历的人最多。15 岁以上的人平均只读了 9.91 年书，刚过初中毕业。所以初中学历在中国不是「够用」，是最普通的那一档。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-4', '「读不起」先按政策算一遍：中职学费大多已免，助学金 2300 元，助学贷款每年最高 2 万', '为什么「读不起」先按政策算一遍：中职学费大多已免，助学金 2300 元，助学贷款每年最高 2 万？', '公办中职里，农村学生、城市涉农专业学生和家庭困难学生已经免学费。中职和普通高中的助学金，2025 年春季起每年 2300 元。上了大学，助学金每年 3700 元，助学贷款每年最多能借 2 万。钱不够可以推迟、可以换个办法，很少到必须现在退学去打工的地步。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-5', '没考上普高不等于路断了：中职有贯通招生和单独考试，技能岗位招聘还可以降学历要求', '为什么没考上普高不等于路断了：中职有贯通招生和单独考试，技能岗位招聘还可以降学历要求？', '2022 年的职业教育法写明：职业教育和普通教育地位同等重要。中职可以和高职贯通招生，高职还必须留出招生计划或者单独考试，专门招中职毕业生。用人单位也不得因为你是职业学校毕业就设门槛卡你。分数不够上普高，是换一条路，不是停在初中学历。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-6', '把「读书还是打工」算成一道题：早挣的三年工资，对上往后几十年的年收入差', '为什么把「读书还是打工」算成一道题：早挣的三年工资，对上往后几十年的年收入差？', '把两种选择摊在纸上比。早工作挣到的是三年低门槛岗位的工资，只有这一次。继续读，换回的是往后每年多挣的那一截，还要乘以剩下的三四十年。中国城镇多读一年书，收入平均高 4.0%（1988 年）到 10.2%（2001 年）。数据老，只能看个大概。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-7', '先记住基准线：多受一年教育，全球平均的私人回报（落到自己收入上的那部分）约为每年 9%', '为什么先记住基准线：多受一年教育，全球平均的私人回报（落到自己收入上的那部分）约为每年 9%？', '按全世界平均算，多读一年书，个人收入每年高约 9%，女性的回报一直高于男性。这个数说的是正规上学，报一个班不能直接套。拿它当尺子：一个课程要你花 3 万元和半年，就问它带来的收入变化抵不抵多读一年书。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-8', '花钱考证之前，先查这张证在不在国家职业资格目录或人社部备案的评价机构名单里', '为什么花钱考证之前，先查这张证在不在国家职业资格目录或人社部备案的评价机构名单里？', '有些机构打着新职业、技能等级的名义乱办班、乱收费、滥发证，还有假冒权威机构的，人社部专门治理过。报名前按三步查：这个职业在不在国家职业资格目录、发证机构是不是人社部门备案的评价机构、证书编号能不能在官方平台查到。查不到的，报名费就是白花。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-9', '培训优先走政府补贴渠道，别一上来就自费报商业班', '为什么培训优先走政府补贴渠道，别一上来就自费报商业班？', '2025 年到 2027 年底，国家计划办 3000 万人次以上的补贴培训。钱从就业补助资金、失业保险基金、企业职工教育经费等多个口子出。哪个工种越缺人、培训成本越高，补贴就越高。在职的先问单位，其余人先翻当地人社局的补贴目录，再决定学什么。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-10', '挑技能时优先看「要不要动手、要不要现场判断」，这类最难被自动化顶掉', '为什么挑技能时优先看「要不要动手、要不要现场判断」，这类最难被自动化顶掉？', '按美国的估算，约 47% 的岗位有较高风险被计算机接手，后来按具体任务估的比例低得多。机器难过的坎有三样：手上的灵巧劲、想出新东西、跟人打交道。所以要到现场、环境不标准、得临场判断的活更难被顶掉，流程固定、主要处理信息的岗位风险最高。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","B 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-11', '学之前先确认这个技能有没有等级评价，等级能不能换成钱', '为什么学之前先确认这个技能有没有等级评价，等级能不能换成钱？', '国家在推「新八级工」，要求企业把岗位工资和技能等级挂钩，表现突出的职工还能不看工龄资历直接认定等级。这是政策方向，各地各企业差别很大。有国家职业标准和等级通道的技能，往后才谈得上按等级涨薪，学之前先查一下有没有。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-12', '别把「网上说工资高」当成缺人，去查当地的紧缺职业目录和补贴目录', '为什么别把「网上说工资高」当成缺人，去查当地的紧缺职业目录和补贴目录？', '各地给哪个工种的培训补贴多，是按急需紧缺程度和培训成本定的，所以补贴额度能看出当地缺不缺人。网上说的「某工种月入多少」，多半是招聘平台的挂牌价或个人自述。你看到的多是挣到钱的人，也没算工时、通勤、职业病和淡旺季。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-13', '同样的钱和时间，优先选能直接上岗的短周期项目', '为什么同样的钱和时间，优先选能直接上岗的短周期项目？', '政策鼓励的是能短期就业的「短平快」培训，还有职业院校的微专业。挑项目只看一条：学完有没有一个具体岗位能投简历。学一年半载、结业还要「再积累经验」的，实际花掉的时间远超标价。开工前就写好退出条件：学到什么程度还没找到活就停。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","C 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-14', '学完先合上书自己考一遍，别回头重读', '为什么学完先合上书自己考一遍，别回头重读？', '读完再读一遍感觉很熟，其实记不牢。合上书考自己一遍，效果明显更好，课堂上加了小测验，成绩提高属于中等幅度。给十种常用学法排名时，自测排在最高一档。读完一节先默写要点，再翻回去对。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-15', '把同样的时间摊到几天，别一次学完', '为什么把同样的时间摊到几天，别一次学完？', '同样的时间，分几天学比一次学完记得牢。317 个实验都在测这件事，结论一致。还有一条实用规律：你要记到多久以后，复习间隔就该拉多长。明天考就当天复习，一个月后考就隔几天过一遍。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-16', '别把划重点、反复读、写摘要当成主要学法', '为什么别把划重点、反复读、写摘要当成主要学法？', '学生最常用的是划重点和反复读，可在十种常用学法的排名里，这两样都在最低一档。写摘要、关键词记忆法、给课文配图想象也在最低一档。它们不是完全没用，只是起作用的条件太窄，同样的时间换成自测更划算。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-17', '几种题型混着练，别一种连做二十道', '为什么几种题型混着练，别一种连做二十道？', '同一类题连做一大串，当场做得很顺，过后不一定分得清该用哪个方法。把几类题打乱着练，长期效果更好，属于中等幅度。但这招挑材料：练图像、练分类最有效，数学题小一些，背单词反而不如分块练。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-18', '别按「我是视觉型、他是听觉型」挑学法', '为什么别按「我是视觉型、他是听觉型」挑学法？', '很多人相信每个人有自己的学习风格，比如视觉型、听觉型，按风格教才学得好。认真检验这件事的研究很少，几乎没有一项支持它，有几项的结果还正好相反。人确实各有偏好，但没有证据说按偏好上课就学得更好，不用花钱做风格测评。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-19', '要背的内容按将来的用法出题考自己，别原样背一遍就算完', '为什么要背的内容按将来的用法出题考自己，别原样背一遍就算完？', '合上书考自己，好处不只停在背过的那几个字上。192 项对比、一万多人合起来算，它对换了题型的题、对应用题和推理题也管用，幅度中等偏小。但有两种情况几乎没用：把问法和答案对调，以及只在书上见过、从来没被考过的内容。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-20', '评职称先弄清自己在哪个系列、哪一级，再按单位性质找申报渠道', '为什么评职称先弄清自己在哪个系列、哪一级，再按单位性质找申报渠道？', '职称全国分 27 个系列，每个系列分初级、中级、高级。一般要一级一级往上报。在单位上班的，由单位审核、公示后往上报。在民营企业的，可以去职称申报受理服务点，或者找人才中介服务机构、行业协会申报。自由职业者报当地人社部门组织的评审。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-21', '会计这类初级、中级职称靠全国统考拿，先对照学历和工作年限去报名', '为什么会计这类初级、中级职称靠全国统考拿，先对照学历和工作年限去报名？', '有些系列的初级、中级职称是考出来的，考过就算，不再另外评审。会计就是这样：助理会计师要高中以上学历，会计师要本科干满 4 年会计、大专满 5 年。已经拿到某些职业资格的，也可能直接算作有相应职称。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 少","时间 中","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-22', '别找中介代评、别买论文代写、别在材料上造假：查实就撤销职称，记诚信档案 3 年', '为什么别找中介代评、别买论文代写、别在材料上造假：查实就撤销职称，记诚信档案 3 年？', '用假材料、代写论文、剽窃成果拿到的职称，查实就撤销。失信记录要记 3 年，还进全国信用平台。申报时签的承诺书不实，3 年内不能再申报。人社部门还专门查处中介的虚假宣传、假冒评审和假证。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s23-23', '拿到职称不等于涨工资：先问清单位是按岗位比例评聘，还是评了不一定聘', '为什么拿到职称不等于涨工资：先问清单位是按岗位比例评聘，还是评了不一定聘？', '职称是聘用、考核、晋升的依据，但评上和聘上是两回事。事业单位一般在岗位比例内评，评上多半能聘。不实行岗位管理的单位可以评聘分开，评上了单位不一定给对应的岗位和工资。换单位、换地方后，职称可能要重新评或者确认。', 'living', '23. 学什么技能划算', 'published', 1, 'reference_book', 95, '{"23. 学什么技能划算","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-1', '常见病先在社区看，经基层逐级转诊上去，住院起付线接着算', '为什么常见病先在社区看，经基层逐级转诊上去，住院起付线接着算？', '先去社区，再由社区转到大医院住院，自己先掏的那一段钱只算一次。自己直接跑去三级医院住院、之后再转回社区康复，这段钱可能要掏两回。由大医院转回社区接着住的，同一个病这段时间里也不再重算一次。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-2', '同一个统筹地区（医保参保地）里，级别越低报销比例越高，差距约 10 个百分点', '为什么同一个统筹地区（医保参保地）里，级别越低报销比例越高，差距约 10 个百分点？', '同一笔住院费，医院级别越低，报销报得越多。各地要把档次拉开，每往上一级差十个百分点左右。比如 1 万元住院费，报销从八成降到七成，自己掏的就从 2000 元变成 3000 元。新增的医保基金也往基层倾斜。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-3', '要去大医院，走基层转诊或者医院的转诊中心，别找号贩子', '为什么要去大医院，走基层转诊或者医院的转诊中心，别找号贩子？', '大医院要留出一部分号和床位，专门给从基层转来的人。医院还要设转诊中心，或者指定一个固定部门专管转诊，2027 年全覆盖。挂不到号不等于没有路。号贩子的号除了贵，还可能把你送进不对口的科室。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-4', '跨省异地就医之前先在本地问一句，必要性原则上要副主任医师以上评估', '为什么跨省异地就医之前先在本地问一句，必要性原则上要副主任医师以上评估？', '要不要去外地看病，原则上由二、三级医院副主任医师以上的医生评估。临时外出就医报销多少，和在参保地同级别医院会有差别，具体看本地规定。出发前在本地问一句，比人到了外地才发现报不了强。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-5', '每次看完病，把病历、检查报告和影像自己存一份', '为什么每次看完病，把病历、检查报告和影像自己存一份？', '查阅和复制自己的病历，是法律给你的权利。门诊病历、住院志、化验单、影像、手术和麻醉记录、病理资料、费用清单都能复制。医院有专门窗口受理，只能收工本费。换医院、找别的医生再看一遍、报商业保险、真起了纠纷，凭的都是这一摞材料。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-6', '对诊疗有疑问就当场要求封存病历，双方在场、开清单、各执一份', '为什么对诊疗有疑问就当场要求封存病历，双方在场、开清单、各执一份？', '对治疗有疑问，可以要求把病历封存起来。封存要医患双方都在场，开清单、签字盖章、各拿一份。病历还没写完的，先封已经写完的那部分。怀疑是输液、输血、打针、用药出的问题，那袋液体、那支药和输液器要一起封存。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-7', '急重的伤病直奔急诊预检分诊台，别去挂号窗口排队', '为什么急重的伤病直奔急诊预检分诊台，别去挂号窗口排队？', '急诊不按先来后到，按病情轻重分四级排。定级的地方是急诊入口的预检分诊台，不是挂号窗口。不去分诊，你在系统里就没有级别，伤得再重也只能跟着队伍慢慢挪。到了先报最危险的那一条：大出血、喘不上气、意识不清、身上扎着东西、胸口压着疼。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-8', '没带钱、没带证件、说不清自己是谁，急诊也必须先救', '为什么没带钱、没带证件、说不清自己是谁，急诊也必须先救？', '国家有一笔疾病应急救助基金，专付两种人的急救费：身份查不出来的，和掏不出钱的。医院不能拒绝或拖延抢救，急救中心也不能因为钱的问题不出车。所以别因为没钱在家硬扛，也别怕欠费不叫救护车。这笔钱只管急救，后面住院还是走医保和医疗救助。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-9', '伤残鉴定要等治疗终结之后再做，做早了等级会评低', '为什么伤残鉴定要等治疗终结之后再做，做早了等级会评低？', '赔多少钱主要看评几级，评几级看的是治完之后还剩多少功能障碍。标准写明要在治疗终结、或者临床治疗效果稳定之后再做。骨头还没长好、钢板还没取就跑去评，评的是当时那个样子，等于自己把等级压低。长好了不影响功能的普通骨折，评不上。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-10', '治完之后确实留下功能障碍，去户籍地县级残联申请残疾人证', '为什么治完之后确实留下功能障碍，去户籍地县级残联申请残疾人证？', '残疾人证是领残疾人待遇的门槛，不是伤情证明。分视力、听力、言语、肢体、智力、精神和多重七类，每类一到四级。流程是申请、受理、到指定机构评定、公示、审核批准、发证，有效期十年、到期免费换。评不上就是评不上，这不是找熟人能办下来的东西。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-11', '谢救过你的医生，走感谢信、锦旗和满意度评价，别走红包：准则禁的是财物，不是谢意', '为什么谢救过你的医生，走感谢信、锦旗和满意度评价，别走红包：准则禁的是财物，不是谢意？', '事先塞钱买不到优先，号源、床位、紧缺药品和手术安排都禁止拿来换好处。事后想谢救你命的医生，可以谢，但别送烟酒红包，他收了就是违规。能真正落到他身上的谢法有三种：认真填一次满意度评价，写一封点名的感谢信或送面锦旗，按医嘱复查。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s24-12', '种牙之前先问清包干价含哪些项目，优先找承诺参与价格治理的机构，别信低价广告', '为什么种牙之前先问清包干价含哪些项目，优先找承诺参与价格治理的机构，别信低价广告？', '种植牙 2023 年集中降价以后，一颗常规种植牙的整体费用从平均 1.5 万元降到 6000 到 7000 元。三级公立医院单颗的服务费原则上不超过 4500 元，种植体和牙冠另算。种牙、镶牙、正畸医保不报，补牙、拔牙这类治疗各地普遍能报。', 'living', '24. 看病：怎么少花钱少走弯路', 'published', 1, 'reference_book', 95, '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-1', '人在家里或外面没了，先分清正常死亡还是非正常死亡：意外、死因不明、独居才发现的，立刻报警，遗体和现场不要动', '为什么人在家里或外面没了，先分清正常死亡还是非正常死亡：意外、死因不明、独居才发现的，立刻报警，遗体和现场不要动？', '意外走的、不知道怎么走的、独居很久才被发现的，死亡证明只有公安能开。现场被动过，事情说不清，证也不好开。这张纸拿不到，后面火化、销户、保险理赔全都卡住。分不清是哪一种，就先打 110。警察到场查完，照样给你开证。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-2', '死亡证明是后面所有事的钥匙：谁救治谁开，家中正常死亡找社区卫生服务机构，一日内签发', '为什么死亡证明是后面所有事的钥匙：谁救治谁开，家中正常死亡找社区卫生服务机构，一日内签发？', '在医院走的，找管救治的那一家开死亡证明。在家里正常走的，找住处这一片的社区卫生服务机构、乡镇卫生院开。死因清楚的，一天内就签发。销户、火化、取公积金、领社保待遇、理赔、办继承，每一件都要用它。拿到先多复印几份。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-3', '遗体接运、存放、火化只能走殡仪馆，医院太平间不办殡仪，存放一般不超过 3 日', '为什么遗体接运、存放、火化只能走殡仪馆，医院太平间不办殡仪，存放一般不超过 3 日？', '接运、存放、防腐、整容、火化，只能由殡仪馆来做。医院太平间不办丧事，最多让遗体临时放一放。殡仪馆存放一般不超过 3 日，要多放几天得去办延期。火化要凭死亡证明和火化确认书。火化后给的那张火化证明，办继承、理赔还要用。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-4', '对死因有异议，48 小时内提出尸检，同时封存病历', '为什么对死因有异议，48 小时内提出尸检，同时封存病历？', '对死因有疑问，要在人去世后 48 小时内提出尸检。医院有冻存条件的，可以延到 7 日。尸检还要近亲属签字同意。不签字，或者一直拖过了时间，死因查不清的责任就算在拖的那一方。提尸检的同时，要求把病历封存起来。遗体一火化，就再也做不了尸检。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-5', '注销户口有法定时限：城市在安葬前，农村在一个月以内', '为什么注销户口有法定时限：城市在安葬前，农村在一个月以内？', '城市要在安葬前销户，农村要在一个月以内。带死亡证明和户口簿去派出所办。拖着不办，继承过户、领待遇、退保都会卡在户籍状态上。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-6', '殡葬服务分基础项目和非基础项目，基础项目有清单、收费依法制定', '为什么殡葬服务分基础项目和非基础项目，基础项目有清单、收费依法制定？', '遗体接运、存放、告别、火化、骨灰寄存、生态安葬，都在国家的基础项目清单里。公办机构提供的骨灰格位安葬也在里面。这些项目的价钱按规定来定。清单之外，不许另立项目收钱。出发前先问清楚哪几项算基础项目、当地标准是多少，再谈别的。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-7', '遇到强制搭售、标价外加价、把一项拆成几项收费，记下来投诉', '为什么遇到强制搭售、标价外加价、把一项拆成几项收费，记下来投诉？', '这几样都是条例点名的价格违法行为：不挂价目表、在标价之外加钱、捆绑着强卖丧葬用品、逼你接受别家的收费服务。把一项拆成几项收费，也算变相涨价。当场先要价目表，留好收费凭据和聊天记录。事后再投诉也来得及。查价格找市场监管，管殡葬服务找民政。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-8', '殡葬代理、用品代购、策划主持这类中介，要在县级民政备案', '为什么殡葬代理、用品代购、策划主持这类中介，要在县级民政备案？', '殡葬代理、用品代购、策划主持、信息咨询这类中介，要在县级民政部门备案。没备案的，不进民政部门那套殡葬服务信息系统。能不能自己查各地不一样，最稳的是打电话问县级民政部门。用骗术乱收费、倒卖逝者信息的，会被依法处置。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-9', '分散在各处的钱要逐个去取：公积金余额、社保待遇、工伤待遇', '为什么分散在各处的钱要逐个去取：公积金余额、社保待遇、工伤待遇？', '公积金余额继承人可以提取，它不在银行账户里，最容易漏。养老保险个人账户里剩的钱也能继承。因病去世的，家属另领丧葬补助金和 3 到 24 个月的抚恤金。因工死亡的，另有工伤那三笔钱。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s25-10', '死者的账号和个人信息，近亲属可以要求查阅、复制、更正、删除', '为什么死者的账号和个人信息，近亲属可以要求查阅、复制、更正、删除？', '人走以后，近亲属为了自己的合法正当利益，可以要求平台查阅、复制、更正、删除死者的个人信息。平台要是拒绝，得说明理由。你也可以去法院起诉。有一个例外：他生前另有安排的，比如设过账号继承人、留下过明确意愿，按他的安排来。', 'living', '25. 人走了以后要办什么', 'published', 1, 'reference_book', 95, '{"25. 人走了以后要办什么","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-1', '平台不要自己收钱再转给卖家，让钱走持牌支付机构直接结算', '为什么平台不要自己收钱再转给卖家，让钱走持牌支付机构直接结算？', '买家的钱先进你的账户，你再转给卖家，这就是在做支付业务。做这门生意要中国人民银行批准，还要真拿出一亿元本钱。没批准就干，会被关停，挣的钱收走，还要罚款，老板和经办人另外罚。严重的还要判刑。稳妥做法只有一条：钱不进你的账户。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-2', '收费的网站多数要许可证，自己卖货不让别人入驻的不用，撮合交易的是另一类许可，免费的只要备案', '为什么收费的网站多数要许可证，自己卖货不让别人入驻的不用，撮合交易的是另一类许可，免费的只要备案？', '向用户收钱的网站，多数要先办增值电信业务经营许可证，这张证个人办不了。只在自己网站或 App 上卖货、不让别人入驻开店的，不用办。只开微信、支付宝小程序或网店的也不用。该办没办就收钱开站，会被没收收入再罚款，严重的关站。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 多","时间 多","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-3', '做直播要网络文化经营许可证，做视听节目的那张证民营基本拿不到', '为什么做直播要网络文化经营许可证，做视听节目的那张证民营基本拿不到？', '做直播、做游戏解说，要省级文化部门发的网络文化经营许可证。证上的经营范围里得写明网络表演。受理后 20 日内出结果，证管 3 年。播过的视频自己要留满 60 天。没办证就开张，会被叫停、警告，再罚 3 万元以下，不停就上黑名单。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 多","时间 多","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-4', '服务器放境内就要备案，接入商必须自己持有增值电信许可', '为什么服务器放境内就要备案，接入商必须自己持有增值电信许可？', '服务器放在境内，开站前就要备案。备案不花钱，跟着服务器在服务商那里提交，一般几天到几周。没备案会被责令限期改正，再罚 1 万元，不改就关站。主页上不挂备案号，另外罚 5000 元到 5 万元。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-5', '让用户上来卖东西，平台就要核验登记、报送信息、留存三年', '为什么让用户上来卖东西，平台就要核验登记、报送信息、留存三年？', '让别人上你的平台卖东西，你就要先核卖家的身份、地址、联系方式和许可证，再登记建档。建完档，至少每六个月回头再核一次。卖家是谁要报给市场监管，纳税的情况每季度报给税务。商品和交易记录留三年。漏做一项，先责令改正，不改罚 2 万到 10 万元。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 多","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-6', '用户发的内容你要管：审核机制、举报入口、发现违法立即停传并报告', '为什么用户发的内容你要管：审核机制、举报入口、发现违法立即停传并报告？', '用户发的东西，出了事由平台负责。你要把这套制度建起来：注册、发帖审核、评论审核、每天巡查、出事怎么处置。页面显眼的地方放举报入口。看到违法信息，马上停止传播、留好记录、报给主管部门。不做的，罚 5 万到 50 万元，严重的更多。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-7', '提供信息发布、即时通讯服务，必须要求用户提供真实身份信息', '为什么提供信息发布、即时通讯服务，必须要求用户提供真实身份信息？', '你的网站能发帖，或者能聊天，就要在用户开通服务时要他的真实身份信息。不给的，不能让他用。做法是后台存真名，页面上显示什么昵称由他自己定，核验用手机号就行。不做实名的，先责令改正。不改的罚 5 万到 50 万元，还可能关站。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-8', '不给未满 16 周岁的人开直播，打赏按年龄分档处理', '为什么不给未满 16 周岁的人开直播，打赏按年龄分档处理？', '不满 16 周岁的人，不能在你这里注册开播账号。满 16 周岁的要核验身份，还要父母或其他监护人同意。打赏分三档：不满 8 岁不能打赏，8 到 16 岁要监护人同意，16 岁以上要监护人同意或核验收入证明。孩子背着监护人打赏的钱，监护人来要，法院会判退还。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-9', '接到侵权通知要及时处理，转送声明后 15 日没有下文就恢复', '为什么接到侵权通知要及时处理，转送声明后 15 日没有下文就恢复？', '有人发来侵权通知，还附了初步证据，你要及时把东西删掉、屏蔽或者断开链接，同时把通知转给卖家。拖着不办，多出来的那部分损失你要和卖家一起赔。卖家申辩了，你把申辩转给对方，等 15 天。对方既没投诉也没起诉，就把东西恢复回去。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-10', '用户信息不要随手放到境外，出境有法定条件和人数门槛', '为什么用户信息不要随手放到境外，出境有法定条件和人数门槛？', '把境内用户的信息传到境外的机器上，这就叫出境。服务器放在境外，不等于数据没出境。要出境得走四条路之一：网信部门的安全评估、专业机构的认证、按标准合同签约，或者法律另有规定。还要告诉用户境外收信息的是谁、拿去做什么，并专门就这件事问他一次。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s26-11', '选服务器先看停机能不能忍，再看有没有人运维，最后才比价', '为什么选服务器先看停机能不能忍，再看有没有人运维，最后才比价？', '三档的差别不在价格，在出事那天你手上有什么。大厂有备案通道，资质公开，坏了有公告、有赔偿条款，能找到人。小服务商便宜一半，可它超售、跑路、被上游封掉的时候，你连找谁都不知道。没有用户数据的静态站，几十元的 VPS 就够用。', 'living', '26. 做一个网站或平台：资质、备案和服务器', 'published', 1, 'reference_book', 95, '{"26. 做一个网站或平台：资质、备案和服务器","C 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-1', '准备怀孕就开始每天补 0.4 毫克叶酸，一直吃到孕早期满 3 个月', '为什么准备怀孕就开始每天补 0.4 毫克叶酸，一直吃到孕早期满 3 个月？', '怀孕前后每天吃一粒叶酸，孩子出现神经管缺陷的概率大约能降七成。神经管缺陷就是无脑儿、脊柱裂这一类的出生缺陷。已经生过一个这样的孩子的人，再生一个还出问题的概率，大约降到原来的三分之一。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-2', '孕 13 周前去社区卫生服务中心建《母子健康手册》，把免费产检额度用掉', '为什么孕 13 周前去社区卫生服务中心建《母子健康手册》，把免费产检额度用掉？', '孕期至少五次产检，加上产后上门访视和产后 42 天检查，这些钱国家出。领的办法是怀孕 13 周以前去社区建一本《母子健康手册》。不去建，这几次免费的就白白错过。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-3', '第一次产检就把艾滋病、梅毒、乙肝三项查掉，查出来也有免费的阻断', '为什么第一次产检就把艾滋病、梅毒、乙肝三项查掉，查出来也有免费的阻断？', '第一次产检就把艾滋病、梅毒、乙肝这三样查掉，检测不用自己掏钱。真查出来也不是绝路。国家免费给药、给方案，挡住病从母亲传给孩子的那条路，这叫母婴阻断。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-4', '整个孕期一支烟一口酒都不要，家里人也别在屋里抽', '为什么整个孕期一支烟一口酒都不要，家里人也别在屋里抽？', '孕期抽烟，孩子早产、生下来太小、唇腭裂的概率都往上走。孕期和生产时异常出血的风险直接翻一倍。婴儿猝死的风险也更高。家里人在屋里抽，一样算。什么时候戒都还来得及。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-5', '有子痫前期高危因素的，孕 12 周后开始每天一片小剂量阿司匹林', '为什么有子痫前期高危因素的，孕 12 周后开始每天一片小剂量阿司匹林？', '子痫前期是孕期的一种高血压病。上一胎得过、怀多胎、有慢性高血压、孕前有糖尿病、有肾病或自身免疫病的人算高危。高危的人从孕 12 周起每天一片小剂量阿司匹林，子痫前期低约一成半，早产和孩子在生产前后死亡都低约两成。其他人别自己吃。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-6', '孕 24 周及以后做一次妊娠期糖尿病筛查，别嫌喝糖水麻烦', '为什么孕 24 周及以后做一次妊娠期糖尿病筛查，别嫌喝糖水麻烦？', '妊娠期糖尿病就是怀孕之后才出现的血糖高。孕 24 周以后花半个上午，喝一次糖水、抽几次血，就能查出来。不查也不管，胎儿长得过大、难产、挨一刀、子痫前期和新生儿低血糖的风险都会往上走。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-7', '背下这张「立刻去医院」的清单，孕期和产后一年内都算数', '为什么背下这张「立刻去医院」的清单，孕期和产后一年内都算数？', '任何一条出现，当天就去医院，别在家等一晚。头痛不好或越来越重、看东西变样、发烧到 38 ℃。手或脸肿得厉害、喘不上气、胸痛或心跳快。肚子剧痛不缓解、胎动停了或明显变少、阴道出血或流液。一条胳膊或腿又肿又痛、想伤害自己或孩子。产后一年内也算。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-8', '破水了就地平躺、垫高臀部、打 120，不要走动也不要洗澡', '为什么破水了就地平躺、垫高臀部、打 120，不要走动也不要洗澡？', '破水了不是慢慢收拾东西再出发。正确做法是就地躺下、把屁股垫高、打 120。站着走动，羊水流得更快，脐带可能跟着被冲下来。那是能要孩子命的急症。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-9', '想要无痛分娩就直接说，它不增加剖宫产的风险', '为什么想要无痛分娩就直接说，它不增加剖宫产的风险？', '无痛分娩就是在腰上打一针麻药，把生孩子的疼压下去。它比别的止疼办法更管用，也不会让你更可能挨一刀。「打了无痛腰疼一辈子」同样没有依据。现在它有了单独的收费项目，医院也更愿意做。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-10', '没有医学指征就别主动要求剖宫产，也别为了挑日子开刀', '为什么没有医学指征就别主动要求剖宫产，也别为了挑日子开刀？', '世界卫生组织的说法是，一个地方的剖宫产比例超过 10% 以后，母亲和新生儿的死亡就不再继续下降。该剖的一定要剖。为了挑日子、怕疼去剖，只是白挨一次腹部大手术。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-11', '怀孕前就确认生育保险的参保状态，未就业的配偶也能报生育医疗费用', '为什么怀孕前就确认生育保险的参保状态，未就业的配偶也能报生育医疗费用？', '单位交了生育保险，生孩子的医疗费和产假期间的津贴都从这笔基金里出。配偶没工作的，医疗费这一块也能报。参保月数够不够、在外地生要不要先备案，都得提前问，事后补不了。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-12', '出院前把《出生医学证明》办掉，名字提前想好、别写错字', '为什么出院前把《出生医学证明》办掉，名字提前想好、别写错字？', '这张证是上户口、参保、上学的前置件，而且只有接生的那家机构能第一次开。出了院再回头补，要另走一套流程、多交材料。名字里的字，先确认户籍系统打得出来。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-13', '新生儿足跟血筛查和听力筛查都别拒绝', '为什么新生儿足跟血筛查和听力筛查都别拒绝？', '扎一次足跟血、做一次听力测试，能在孩子看起来完全正常的时候，查出甲减、苯丙酮尿症和听力障碍。等症状显出来，智力上的损害已经补不回来了。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-14', '拿到出生医学证明就给孩子办居民医保，别等落完户', '为什么拿到出生医学证明就给孩子办居民医保，别等落完户？', '拿到出生证就能在网上给孩子参保，不用等落户。参上了，出院时的住院费当场就能报。新生儿的住院费不低，参保和没参保差别很大。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-15', '孩子出生后一个月以内去派出所申报出生登记', '为什么孩子出生后一个月以内去派出所申报出生登记？', '法律给的是一个月，不是「有空再说」。落户卡着后面的打疫苗、入园、入学和办身份证。越往后拖，要补的材料越多。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s27-16', '产后 42 天那次复查别跳过，它同时是产后抑郁的筛查', '为什么产后 42 天那次复查别跳过，它同时是产后抑郁的筛查？', '这次复查不花钱，含血常规、白带常规，还包含一次产后抑郁筛查。产后一年内都可能出大问题，别觉得出了月子就安全了。', 'living', '27. 怀孕和生产：从发现怀孕到出院办证', 'published', 1, 'reference_book', 95, '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-1', '不要用极端节食、断食或催吐来控制体重，要减就从运动那一侧减', '为什么不要用极端节食、断食或催吐来控制体重，要减就从运动那一侧减？', '神经性厌食的人，死亡概率大约是同龄人的 5.9 倍。每 1000 个人跟一年，死 5.1 个。死的人里每五个有一个是自杀。而它的入口就是节食：跟踪 44 所中学的学生三年，严重节食的女生出现进食障碍的概率是不节食的 18 倍。想控制体重就多运动，别少吃到饿。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-2', '打针、埋线、开刀之前查两样：机构许可证上有没有「医疗美容」，动手的人是不是主诊医师', '为什么打针、埋线、开刀之前查两样：机构许可证上有没有「医疗美容」，动手的人是不是主诊医师？', '动针、动刀、用医疗器械，会破皮或进到身体里的，就算看病。只能在许可证上写了「医疗美容」的机构做，动手的必须是注册过的执业医师。在美容院、工作室、酒店房间里做属于非法行医。动手的人情节严重判 3 年以下，伤了人判 3 到 10 年，致人死亡判 10 年以上。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-3', '面部填充避开鼻背、眉间、额头这几个部位，更别为省钱找非正规注射', '为什么面部填充避开鼻背、眉间、额头这几个部位，更别为省钱找非正规注射？', '打填充针后失明的人里，一半多打的是鼻部，其次是眉间、额头和法令纹，八成多用的是玻尿酸。失明的人只有两成视力完全恢复，一成多部分恢复，将近两成还伤到了脑。目前没有一种抢救办法稳定管用，只能事先避开这些部位。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-4', '不要买承诺「快速瘦」的减肥药、减肥咖啡、瘦身糖果和酵素梅', '为什么不要买承诺「快速瘦」的减肥药、减肥咖啡、瘦身糖果和酵素梅？', '这类产品里最常查出偷加的是西布曲明，它原来是减肥药，2010 年在中国被停掉了。有心脏病或糖尿病的超重的人吃了三年多，没致命的心梗高约三成，中风高约三成六。体重只多减了 1.7 公斤。抽检查出来的时候，你已经吃下去了。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-5', '不要用合成代谢类固醇（「增肌针」「口服药」）来长肌肉', '为什么不要用合成代谢类固醇（「增肌针」「口服药」）来长肌肉？', '健身房兴奋剂检测阳性的男性，死亡风险是同龄人的 3 倍，每年跑医院的次数多一倍多。痤疮、男性乳房发育、勃起功能障碍，每十个用药的人里至少一个中招。这类药在中国是处方药，能卖给你的渠道本身就在违法。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-6', '要吃减肥药就去医院拿处方，别在不用处方就发货的网店买', '为什么要吃减肥药就去医院拿处方，别在不用处方就发货的网店买？', '处方药必须凭处方卖，网上卖也必须有真实处方并且实名。不问诊、不要处方、下单就发货的，要么卖的不是它说的药，要么这家店在违规。出了事，没人替你的剂量和禁忌负责。挂一次号几十块钱，就有医生替你把这一关。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-7', '性激素类药只在医生开方并定期复查的前提下用，不要网购、不要自己加量', '为什么性激素类药只在医生开方并定期复查的前提下用，不要网购、不要自己加量？', '这条不讨论该不该用，只讨论怎么用。用雌激素的跨性别女性，血管里长血块的比同龄人明显多，每一千人两年多出约 4 个，八年多出约 17 个。这类风险得靠定期复查盯着，网购药、自己调量就没人替你查。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-8', '如果「觉得自己丑」已经到反复照镜子、反复想改的程度，先做一次体像评估再谈手术', '为什么如果「觉得自己丑」已经到反复照镜子、反复想改的程度，先做一次体像评估再谈手术？', '去做整形手术的人里约 15% 有躯体变形障碍，就是把别人基本看不出的缺陷放大到影响生活。去皮肤科求美的人里约 13%，两边都是七成多为女性。这种人做完一处又会盯上下一处，手术解决不了。先挂一次号看看自己是不是这种情况，再决定动不动手术。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s28-9', '矫正牙齿要找有正畸资质的医生当面检查、按时复诊，别网购牙套自己在家戴', '为什么矫正牙齿要找有正畸资质的医生当面检查、按时复诊，别网购牙套自己在家戴？', '透明牙套在国内是二类医疗器械，说明书要求在有正畸资质的医生指导下戴、定期复诊。美国药监部门说没批准过不经牙医开方就直接卖给个人的牙套。没人当面检查，可能咬合变歪、牙齿移错位置、疼痛，甚至掉牙。', 'living', '28. 别为了外形把身体搞坏', 'published', 1, 'reference_book', 95, '{"28. 别为了外形把身体搞坏","C 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-1', '亲人刚走的那几天别一个人待着，有心脏病、高血压、糖尿病的照常吃药，胸口压着疼就叫 120', '为什么亲人刚走的那几天别一个人待着，有心脏病、高血压、糖尿病的照常吃药，胸口压着疼就叫 120？', '亲人去世后头一天，心梗发作的概率是平时的 21.1 倍，之后一天比一天低。60 到 89 岁的人在伴侣去世后 30 天内，心梗或中风的比例大约翻倍，一个月后回落。本来就有心血管病的人，这几天别停药。胸口压着疼、喘不上气、一侧手脚没力，立刻打 120。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-2', '被告知重病诊断的那一周，别一个人去拿报告，治疗以外的决定往后放', '为什么被告知重病诊断的那一周，别一个人去拿报告，治疗以外的决定往后放？', '拿到癌症诊断的第一周，自杀的概率是没确诊的人的 12.6 倍，死于心血管病的概率是 5.6 倍。到第一年，自杀风险降到 3.1 倍，越难治的癌越明显。所以拿报告那天带个人去，回家别一个人待着。辞职、卖房这类事，留到下次门诊再说。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-3', '失业之后先把作息、医保和找工作的节奏固定下来，别整天待在家里', '为什么失业之后先把作息、医保和找工作的节奏固定下来，别整天待在家里？', '失业的人之后死亡的概率比在职的人高约六成，男性和年纪不大的人更明显，头十年最高。把抽烟喝酒的影响扣掉，升幅少了约四分之一，这部分自己能管住。先去办失业登记、领失业保险金，领的期间医保由失业保险代缴。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-4', '亲人死于自杀、意外或凶案的，别指望硬扛，主动去找专业帮助', '为什么亲人死于自杀、意外或凶案的，别指望硬扛，主动去找专业帮助？', '配偶死于自杀的人，五年内被查出精神障碍的概率比一般人高约八成（男性）、七成（女性）。和配偶死于其他原因的人比，也高七成到一倍。这类丧亲的人更容易觉得被人疏远、觉得羞耻。这正是要主动去找人的理由，别等自己好起来。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-5', '丧偶后的头半年，把三餐、睡觉、慢性病的药和复查交给一个固定的人盯着', '为什么丧偶后的头半年，把三餐、睡觉、慢性病的药和复查交给一个固定的人盯着？', '丧偶后不到半年，同期死亡的概率比没丧偶的人高约四成。半年以后降到高约一成半。男性高约两成三，女性那一档小到可能只是巧合。这个差不是靠想开点能扛过去的。该做的是把药、饭和复查落到一个具体的人身上，别指望自己记得住。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-6', '没有亲人也没有朋友的，把「盯着你的那个人」换成三样东西：能进你家门的邻居、社区的探访名单、手机里的紧急联络', '为什么没有亲人也没有朋友的，把「盯着你的那个人」换成三样东西：能进你家门的邻居、社区的探访名单、手机里的紧急联络？', '没有亲人也没有朋友时，要顾的是两件事：出了事有人发现你，平时按时吃药吃饭。吃药吃饭靠自己，写成清单、上闹钟，别靠记性。有人发现靠三样：给邻居留一把备用钥匙，去居委会问能不能上探访关爱名单，手机设好紧急联络人、别关机。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-7', '家长去世后，如实告诉孩子、让他参加告别、别送去别处「换个环境」', '为什么家长去世后，如实告诉孩子、让他参加告别、别送去别处「换个环境」？', '18 岁前失去父亲或母亲的孩子，到成年早期死亡的概率比没经历过的孩子高约五成。父母死于意外、自杀的高约八成，死于疾病的高约三成。家里能做的是如实告诉他，让他参加告别，别中断上学，别送去亲戚家换环境。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-8', '哀伤过了半年还在原地、日子过不下去，去精神科或临床心理科挂号', '为什么哀伤过了半年还在原地、日子过不下去，去精神科或临床心理科挂号？', '大约每十个丧亲的成年人里有一个会卡住：半年以上还在持续想念到吃不下饭、上不了班、带不了孩子，人麻木，觉得生活没有意义。这不是不够坚强，它有诊断标准，也有专门的治疗。针对性治疗的有效率 51%，普通心理治疗是 28%，起效也更快。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-9', '别一上来就花钱做哀伤咨询，先看自己的哀伤是不是真的卡住了（第 8 条那几条症状）', '为什么别一上来就花钱做哀伤咨询，先看自己的哀伤是不是真的卡住了（第 8 条那几条症状）？', '给所有丧亲的人都安排心理咨询，好处很小，过一阵就看不出来了，因为多数人本来会自己缓过来。但对已经明显适应不了的人，治疗和治别的心理问题一样有效。所以先对照第 8 条（哀伤卡住了去精神科），对上了再花这笔钱。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-10', '分居离婚之后别断医保、别用酒顶着', '为什么分居离婚之后别断医保、别用酒顶着？', '分居或离婚的人早死的概率明显高于还在婚的人，男性和年纪较轻的人升得更多。这不一定是离婚造成的，离婚的人在健康、收入上本来就可能不一样。能自己管住的有两样：别让医保、体检断掉，别靠烟酒顶着。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-11', '要人陪着说话打 12356，未成年人和青少年打 12355，要看医生挂心理门诊', '为什么要人陪着说话打 12356，未成年人和青少年打 12355，要看医生挂心理门诊？', '想找个人说话，打 12356，这是全国心理援助热线，免费。未成年人和青少年另有 12355 青少年综合服务平台。要看医生，就挂精神科、心理科或临床心理科的心理门诊。遇到家庭变故、失业、失学，社区网格员和社工本来就该主动发现。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-12', '变故后的头三个月，凡是不可逆的大决定一律往后推', '为什么变故后的头三个月，凡是不可逆的大决定一律往后推？', '这段时间你对各种「机会」的判断力最差。说能联系逝者的、说能帮你把钱翻回来的、劝你辞职去外地重新开始的、拉你合伙的，都会找上来。金额超过一个月收入、或者反悔代价很大的事，一律推后三个月。先讲给一个跟这件事没利益关系的人听，别当天拍板。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s29-13', '别拿死当还债的办法：两年内的寿险不赔，工伤不认，债照样先从遗产里扣', '为什么别拿死当还债的办法：两年内的寿险不赔，工伤不认，债照样先从遗产里扣？', '寿险合同两年内自杀的不赔，只退保单里能退的那点钱。工伤也不认，工亡的三笔钱一分没有。欠的债先从你留下的遗产里扣，家里人只拿剩下的。他们还要承受本节第 4 条（因自杀或暴力死亡丧亲）说的那份健康代价。', 'living', '29. 遭遇重大打击之后', 'published', 1, 'reference_book', 95, '{"29. 遭遇重大打击之后","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-1', '孩子说突然剧痛、而且越来越重，立刻去医院，不要让他忍到放学', '为什么孩子说突然剧痛、而且越来越重，立刻去医院，不要让他忍到放学？', '有些病是按小时算的。男孩突然一侧阴囊剧痛，是睾丸扭转，也就是睾丸连着的那根血管拧住了，血供断了。6 小时内处理，睾丸保住的比例 97.2%。拖到 19 至 24 小时，只剩 42.5%。这种痛等不到放学，也等不到考完。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-2', '该做的治疗别为了「等考完」往后拖，有些窗口跟着骨龄走，不跟着考试安排走', '为什么该做的治疗别为了「等考完」往后拖，有些窗口跟着骨龄走，不跟着考试安排走？', '脊柱侧弯是脊柱往侧面弯。支具是一件硬壳背心，穿在身上把脊柱撑住。骨头还在长的时候戴，75% 的孩子没弯到要开刀的程度，只观察不戴的只有 42%。能戴的时间跟着骨头长完走，不跟着中考高考走，等考完往往只能开刀。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-3', '孩子被欺凌，当天就报到学校并要求书面处理，涉及打人、抢钱、传谣的直接报警', '为什么孩子被欺凌，当天就报到学校并要求书面处理，涉及打人、抢钱、传谣的直接报警？', '被同伴欺凌的孩子，冒出自杀念头的可能约是没被欺凌的 2.2 倍，有过自杀行为的约 2.6 倍。学校接到报告要立即调查，认定是欺凌就要处分，严重的不许瞒，必须报公安。所以当天就报，要求走认定程序，留下书面记录。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-4', '让孩子每天在户外待够 2 小时，这是目前唯一有随机试验支持的防近视办法', '为什么让孩子每天在户外待够 2 小时，这是目前唯一有随机试验支持的防近视办法？', '小学一年级每天多上 40 分钟户外课，三年后新近视的孩子从约四成降到约三成。卫健委给的量是每天白天在户外不少于 2 小时，或者一周加起来 14 小时。阴天也算数，课间到室外站着也算数。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-5', '0 到 3 岁不给屏幕，3 到 6 岁尽量不给，中小学生非学习用途每天不超过 1 小时', '为什么0 到 3 岁不给屏幕，3 到 6 岁尽量不给，中小学生非学习用途每天不超过 1 小时？', '国家卫健委要求 0 到 3 岁不给屏幕，3 到 6 岁尽量别碰，中小学生不为学习用的，一次不超过 15 分钟、一天不超过 1 小时。理由是长时间近距离用眼会让近视来得早。屏幕和近视的证据没这么硬，真正试出效果的是每天户外 2 小时。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-6', '把近视当成会留下的损伤：度数越深，将来视网膜脱离、黄斑病变、青光眼越多', '为什么把近视当成会留下的损伤：度数越深，将来视网膜脱离、黄斑病变、青光眼越多？', '近视不会自己好，度数也降不回去。它也不只是「戴个眼镜」的事。和不近视的人比，得近视性黄斑病变的可能，轻度近视高十几倍，600 度以上高几百倍。视网膜脱离，轻度高约 3 倍，600 度以上高约 13 倍。所以孩子近视得越早、涨得越快，将来要担的风险越大。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-7', '每年那次学生体检的报告单要自己看一遍，异常项当年带去医院查', '为什么每年那次学生体检的报告单要自己看一遍，异常项当年带去医院查？', '中小学校每年组织一次学生体检。报告单上的重点是超重、肥胖、营养不良、脊柱弯曲异常、视力不良、龋齿，这几样最容易被拖过去。别只看一眼身高体重就收起单子。这几项有异常，当年就带孩子去专科查清楚。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-8', '12 到 18 岁的孩子做一次抑郁筛查，别拿学校的心理测评当诊断', '为什么12 到 18 岁的孩子做一次抑郁筛查，别拿学校的心理测评当诊断？', '美国的预防指南建议给 12 到 18 岁的孩子筛查重度抑郁，11 岁及以下证据不够。自杀是 10 到 19 岁孩子的第二位死因。学校每年的心理测评只是普查，不能当诊断。孩子说难受，或者吃、睡、兴趣、成绩突然变样，直接挂精神科或临床心理科。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-9', '不买号称能「治愈近视」「降低度数」的产品和服务', '为什么不买号称能「治愈近视」「降低度数」的产品和服务？', '市场监管总局明说「在目前医疗技术条件下，近视不能治愈」。宣传「恢复」「降低度数」「近视治愈」「度数修复」这类说法的，要从严查处。看到这类词直接排除，不用再比价。护眼仪算医疗器械，电商平台有责任查卖家够不够格卖。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-10', '睡眠、作业、体育和排名都有明文规定，学校做不到可以提', '为什么睡眠、作业、体育和排名都有明文规定，学校做不到可以提？', '文件写明，小学生每天睡 10 小时，初中 9 小时，高中 8 小时。小学上午上课一般不早于 8:20，中学不早于 8:00。2025 年又规定每天体育活动不少于 2 小时，不得按考试成绩排名。孩子长期睡不够，先拿这几条去对，别先怪孩子磨蹭。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-11', '孩子撑不住了可以休学，学籍学校必须给他留着，最长 1 年', '为什么孩子撑不住了可以休学，学籍学校必须给他留着，最长 1 年？', '休学有正式制度。父母或其他监护人提出申请，学校确认后报上级核准。一次最长 1 年，期满还要休就重新申请。休学期间学校要给孩子保留学籍，复学时回来接着上。具体办法各省定，问学校教务处或当地教育局。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-12', '查出视力不良，去医院做散瞳验光，之后按医生给的间隔复查', '为什么查出视力不良，去医院做散瞳验光，之后按医生给的间隔复查？', '散瞳验光是先滴一种眼药水，让眼睛里负责调焦的肌肉松下来，再验度数。这是在医院做的，诊断近视最准。卫健委写明这种药水对健康的眼睛不会造成损伤，停药后恢复正常。别拿眼镜店的一次电脑验光当诊断，也别因为「怕度数涨」不给孩子配镜。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-13', '恒磨牙长出来以后做窝沟封闭', '为什么恒磨牙长出来以后做窝沟封闭？', '窝沟封闭是把大牙咬东西那一面的沟槽用树脂封住，食物残渣就塞不进去。做完两年，长蛀牙的机会约为不封的八分之一。不封时有 16% 的牙面会蛀，封了只有约 5%。四年后仍然有效。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-14', '孩子爱打游戏，先看睡觉、作业和出门活动有没有被挤掉，别光盯着玩了多久', '为什么孩子爱打游戏，先看睡觉、作业和出门活动有没有被挤掉，别光盯着玩了多久？', '真正够得上「游戏障碍」的，大约每百人里两三个。问卷门槛定得低、专挑青少年查，比例就会虚高。拿游戏公司的真实记录看，玩多玩少和心情好坏几乎没关系。未成年人按规定只能在周五、周六、周日和节假日晚上 8 点到 9 点玩。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-15', '孩子说自己喜欢同性，别骂、别赶出家门、别送去「矫正」：家里的态度和他会不会自杀有关', '为什么孩子说自己喜欢同性，别骂、别赶出家门、别送去「矫正」：家里的态度和他会不会自杀有关？', '国内中学生里，喜欢同性或者两性都喜欢的孩子，一年里试过自杀的约是别人的 3 到 5.5 倍。国外研究看到，青春期被家里强烈排斥的孩子，后来试过自杀的多得多。被父母送去「矫正」的，试过自杀的最多。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-16', '管孩子别动手打，也别吼骂、骂他笨：常挨打挨骂的孩子，行为和情绪问题都更多', '为什么管孩子别动手打，也别吼骂、骂他笨：常挨打挨骂的孩子，行为和情绪问题都更多？', '常挨打的孩子，攻击性和心理问题都更多，和父母也更疏远，挨更重的打也更多。打能不能让孩子当场听话，证据说不清。13 岁时常被吼、被骂笨的孩子，之后闯祸和抑郁都更多，父母平时再亲热也抵不掉。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-17', '孩子难管、自己总忍不住打骂，去上一期教具体做法的家长课', '为什么孩子难管、自己总忍不住打骂，去上一期教具体做法的家长课？', '教家长具体管法的课，在抽签分配的试验里，孩子打人、不守规矩的问题少了，家长的情绪也好了。家长打骂孩子也少了，刚上完课时最明显，一两年后还在，但小了很多。上海也试过这类课，有效。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s30-18', '别把孩子送进封闭管理的「戒网瘾学校」「特训营」：法律禁止用伤害身心的办法戒网瘾，已经有孩子被关死', '为什么别把孩子送进封闭管理的「戒网瘾学校」「特训营」：法律禁止用伤害身心的办法戒网瘾，已经有孩子被关死？', '法律明文禁止用伤害孩子身心的办法戒网瘾。合肥一所特训学校把刚送去的男孩铐在禁闭室里，约 44 个小时后人就死了。南昌豫章书院把学生关禁闭，几个负责人被判了刑，家长要求赔学费，法院没支持。', 'living', '30. 上学以后的孩子', 'published', 1, 'reference_book', 95, '{"30. 上学以后的孩子","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-1', '先把门槛对一遍：十二条路的年龄和学历要求都是明文写死的', '为什么先把门槛对一遍：十二条路的年龄和学历要求都是明文写死的？', '这十二条路的年龄和学历门槛，都明文写在文件里。打工要满 16 周岁。当兵是男性满 18 周岁，本科毕业生可以放宽到 24 周岁。考公务员要 18 到 35 周岁、大专以上学历。自考和办个体户这两条，既不看学历，也不看年龄。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-2', '十八岁那年 10 月 31 日前要做兵役登记；义务兵服现役就是两年', '为什么十八岁那年 10 月 31 日前要做兵役登记；义务兵服现役就是两年？', '兵役登记是法定义务，不是报名参军，登记了也不等于要去。当年满 18 周岁的男性，要在 10 月 31 日前上网登记完。不登记的，县里会责令你限期改正，还不改就强制你履行兵役义务并罚款。真去当兵，义务兵服现役就是两年。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 时间","钱 0","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-3', '应征之后拒服兵役，两年内不准出境或升学复学，还进不了公务员和国企', '为什么应征之后拒服兵役，两年内不准出境或升学复学，还进不了公务员和国企？', '报了名又拒绝去当兵，后果是一串。公务员不能录用你，国有企业和事业单位也不能招你。两年内不准出境，不准升学，不准回学校复学。还会被列进履行国防义务严重失信主体名单。所以「先报上再说，不行就退回来」是个很贵的想法。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-4', '大学生当兵最实的两块：学费每年补最高 20000 元，学籍保留两年、考研有专项计划', '为什么大学生当兵最实的两块：学费每年补最高 20000 元，学籍保留两年、考研有专项计划？', '在校生、应届毕业生和新生去当兵，国家替你出读书那几年的学费，按实际交的补，本专科生每年最高 20000 元，研究生最高 25000 元。学费本来就低的，只补到实际交的那么多。学籍给你留两年。考研另有一条只招退役大学生士兵的专项计划。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-5', '退役后只有六种情况由政府安排工作；自主就业的 30 日内必须报到', '为什么退役后只有六种情况由政府安排工作；自主就业的 30 日内必须报到？', '「当兵包分配」早就不是普遍情况。现在只有六种情况由政府安排工作，义务兵服两年退役，绝大多数不在这六种里面。不由政府安排工作的那一档叫自主就业，它有个硬期限：退出现役之后 30 日内必须去报到。没有正当理由超过 30 日，就算你放弃安置待遇。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-6', '退役后的三笔账：一次性退役金、军龄算工龄、自己干每年扣减 20000 元税', '为什么退役后的三笔账：一次性退役金、军龄算工龄、自己干每年扣减 20000 元税？', '退役之后有三笔账。第一笔是自主就业的一次性退役金，按服现役年限发，立过功的还增发。第二笔是当兵这几年不算社保空白，军龄算工龄，缴费年限跟入伍前和退役后合着算。第三笔是税：自己开店做生意的，3 年内每年最多能少交 20000 元的税。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-7', '想进体制内不止考公一条：基层服务项目干满两年，能报每年 10% 的定向考录计划', '为什么想进体制内不止考公一条：基层服务项目干满两年，能报每年 10% 的定向考录计划？', '想进体制内，不是只有考公一条路。「三支一扶」这类基层服务项目干满两年、考核合格，就能报只面向这些人的定向考录计划。各省每年要拿出公务员考录计划的 10% 左右招这些人。三年内考研，初试总分还加 10 分。代价是这两年拿的是财政补助。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-8', '特岗教师三年服务期满、考核合格又愿意留下的，应当及时入编', '为什么特岗教师三年服务期满、考核合格又愿意留下的，应当及时入编？', '特岗计划是少数几条写明「期满入编」的路。条件是本科及以上学历、以师范类专业为主，年龄不超过 30 周岁，还要有相应的教师资格证。服务期三年，这三年的工资待遇跟当地公办学校的在编教师一样。三年期满考核合格、又愿意留下的，文件要求及时入编。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-9', '消防员和军队文职是另外两个公开招录的口子，门槛比考公低', '为什么消防员和军队文职是另外两个公开招录的口子，门槛比考公低？', '这两条路都不卡「大专以上」这道门槛。消防员招 18 到 22 周岁、高中以上文化程度的人，大专以上学历的人和退役士兵可以放宽到 24 周岁。军队文职只要求年满 18 周岁，入门层级的岗位首次招录最高 35 周岁。共同的代价是政治考核和体检刷人。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-10', '学历不是一锤子买卖：自考不限年龄和已受教育程度，成人高考和开放大学都能补', '为什么学历不是一锤子买卖：自考不限年龄和已受教育程度，成人高考和开放大学都能补？', '十八岁那年没读成书，后面还有三条正规通道：自考、成人高考、开放大学。自考不限年龄，也不看你原来读到哪一级，但全日制在校生不能报。成人高考要先有高中或者专科的毕业证。三条路都慢，但都不看你十八岁那年考成什么样。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 少","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-11', '不进单位就是灵活就业：养老和医疗要自己在就业地参保，户籍限制已经放开', '为什么不进单位就是灵活就业：养老和医疗要自己在就业地参保，户籍限制已经放开？', '不进单位，不等于没有社保这回事，只是没人替你交那一半。文件要求各地放开灵活就业人员在就业地参保的户籍限制，个别超大城市可以逐步放开。所以别把「自由」理解成不用管社保。断着不交，退休金和医保报销都要按断缴的规则算。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-12', '送外卖、跑网约车、拉同城货运，平台按单给你交职业伤害保障费，自己不缴', '为什么送外卖、跑网约车、拉同城货运，平台按单给你交职业伤害保障费，自己不缴？', '送外卖、跑网约车、拉同城货运的人，平台要按单替你缴职业伤害保障费，你自己一分钱不出，每接一单就保一单。这还是试点，接单前先查自己所在的省份和平台在不在范围里。已经和平台建立劳动关系的，走工伤保险，不走这套。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-13', '高考填志愿那天就能锁定编制的两条路：公费师范生和定向医学生，代价是 6 年履约', '为什么高考填志愿那天就能锁定编制的两条路：公费师范生和定向医学生，代价是 6 年履约？', '这两条路都是国家先替你出钱，你毕业后按协议去指定的地方干 6 年。公费师范生只在六所教育部直属师范大学招，提前批录取。定向医学生在拿到入学通知书前就要签三方协议。违约要退钱、交违约金，还进信用记录。想清楚这 6 年能不能接受，再填志愿。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-14', '想出国打工，先查这家公司有没有对外劳务合作经营资格：它不得向你收押金', '为什么想出国打工，先查这家公司有没有对外劳务合作经营资格：它不得向你收押金？', '出国打工这件事，法律管的不是你，是组织你出去的那家公司。只有拿到对外劳务合作经营资格证书、又办了登记的企业才能干这个。听到「先办旅游签过去再转工签」，这句话本身就说明对方在违法。公司也不得以任何名目向你收押金，或者要你拿财产做担保。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-15', '在家给境外公司远程干活，这笔钱在税法上算境内所得：个税自己报，收汇走「职工报酬」', '为什么在家给境外公司远程干活，这笔钱在税法上算境内所得：个税自己报，收汇走「职工报酬」？', '这笔钱算境内还是境外，看的是你在哪儿干活，不是钱从哪儿打进来。人在国内远程给境外公司干活，算境内所得，要在境内交个税。境外公司在中国没有机构，没人替你代扣，这笔税得你自己去报。钱汇进来走「职工报酬」这条路。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s31-16', '不进单位自己干，起步钱先看创业担保贷款：个人最高 30 万、财政贴一半利息', '为什么不进单位自己干，起步钱先看创业担保贷款：个人最高 30 万、财政贴一半利息？', '如果一定要借钱起步，先看这笔有财政贴息的。个人最高能借 30 万元，最长 3 年，利息由财政替你出一半。有个硬条件常被忽略：申请时你和配偶名下不能有别的贷款，只有助学贷款、脱贫人口小额信贷、房贷、车贷和 5 万元以下的小额消费贷不算在内。', 'living', '31. 十八岁之后有哪几条路', 'published', 1, 'reference_book', 95, '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-1', '交学费之前先查学校在不在留服中心的认证院校名单里', '为什么交学费之前先查学校在不在留服中心的认证院校名单里？', '回国以后，这张文凭要用来考公、进国企、落户、评职称，就得先过一道认证。认证由教育部留学服务中心做。学校不在能认证的名单里，学费和时间就白花了，文凭在国内用不上。查名单不花钱，查完再交学费。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-2', '盯住美国 F-1 新规的官司：「最长四年、读完 30 天内走」原定 2026 年 9 月 15 日生效，前一天被法院暂停，眼下仍是「读完为止」', '为什么盯住美国 F-1 新规的官司：「最长四年、读完 30 天内走」原定 2026 年 9 月 15 日生效，前一天被法院暂停，眼下仍是「读完为止」？', '美国原本要把 F-1 改成最长四年、读完 30 天内走。生效前一天，联邦法院把它暂停了。所以眼下还是老规矩：读多久算多久，读完有 60 天准备走人。暂停不是废除，政府还能上诉，规矩随时可能再变。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-3', '打工时数是美加英澳四国都写死的红线，超一小时就是违反签证条件', '为什么打工时数是美加英澳四国都写死的红线，超一小时就是违反签证条件？', '四个国家都给学生签证的打工时间定了上限。超了就是违反签证条件，可能被取消签证、被遣返，以后再申请也会被追问。上限是：美国每周 20 小时，英国读学位每周 20 小时、学位以下 10 小时，加拿大每周 24 小时，澳大利亚每两周 48 小时。打两份工要合起来算。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-4', '身份的根是「全日制在读」：休学、退学、转学空档期一律不能打工', '为什么身份的根是「全日制在读」：休学、退学、转学空档期一律不能打工？', '能不能打工，看你是不是正在全日制上学。一旦休学、退学、被开除，或者转学期间没在上课，打工资格当场就没了。这时候接着干，就是非法打工。很多人以为签证没到期就没事，其实身份早断了。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-5', '美国：搬家后 10 天内必须报新地址', '为什么美国：搬家后 10 天内必须报新地址？', '在美国换了住的地方，法律要求 10 天之内通知移民局。不报不是小事。一来它本身违法，二来移民局寄给你的信会寄丢。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-6', '出发前和在读期间，看一眼教育部的留学预警', '为什么出发前和在读期间，看一眼教育部的留学预警？', '教育部会对某个国家或者地区专门发预警，说那里近期的治安或者政策对中国留学生不利。这是官方公开发布的风险提示，白纸黑字能查到，比中介的说法可靠。看一眼不花钱。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-7', '澳大利亚：OSHC 必须覆盖全程且中间不能断，落地拿不出保险可能被拒绝入境', '为什么澳大利亚：OSHC 必须覆盖全程且中间不能断，落地拿不出保险可能被拒绝入境？', '澳大利亚把留学生医疗保险写进了签证条件，不是可买可不买。保险要盖住整个停留期。续签换保单的时候，中间不能有空档。入境时拿不出保险证明，可能当场被拒绝入境。家里人来陪读，每个人都要单独买一份。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-8', '英国：签证费之外还有一笔按年收的医疗附加费，学生每年 776 英镑，申请时一次付清', '为什么英国：签证费之外还有一笔按年收的医疗附加费，学生每年 776 英镑，申请时一次付清？', '去英国要交的钱不止签证费。还要按签证年数预交医疗附加费，交了才能用英国的国民医疗服务。两年的签证就是一次交 1552 英镑。再加上签证费，出发前这一笔要一次交清，做预算别漏了。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-9', '回国前留出认证时间：留服认证要 10 到 20 个工作日', '为什么回国前留出认证时间：留服认证要 10 到 20 个工作日？', '国外的学历回国要用，得先做学历学位认证。光是审核就要 10 到 20 个工作日。赶上求职季，或者材料被退回来，还要更久。秋招、考公报名、落户都有截止日期，别等到要用了才开始办。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 一般","口径 时间","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s32-10', '认证被「加强审查」的学校每年都在加，花钱买文凭这条路已经走不通', '为什么认证被「加强审查」的学校每年都在加，花钱买文凭这条路已经走不通？', '留服中心会点名一批国外院校，对它们的学历认证单独加强审查，也会暂停受理个别学校的认证申请。被点名的往往就是宣传里「免语言、免出境、几个月拿硕士」的那种。报名前搜一次学校名，比事后申诉省事得多。', 'living', '32. 出国留学：身份、打工、保险和回国认证', 'published', 1, 'reference_book', 95, '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-1', '脊髓损伤之后突然剧烈头痛、出汗，先扶坐直、松开衣物，同时叫 120', '为什么脊髓损伤之后突然剧烈头痛、出汗，先扶坐直、松开衣物，同时叫 120？', '脊髓损伤的人，身体的报警线路断了一截。膀胱憋着、衣服勒着，本人可能没感觉，血压却会猛往上冲。信号是突然剧烈头痛和出汗。这时先把人扶坐直、松开勒紧的衣物、看是不是憋着尿，同时叫 120。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-2', '致残之后的头十年是自杀的高风险期，别当成「想开点」就行的事', '为什么致残之后的头十年是自杀的高风险期，别当成「想开点」就行的事？', '刚残疾那几年，自己或者家人情绪垮掉，是常见的，不是意志力的问题。英国两家脊髓损伤中心的长期随访发现，这群人的自杀率是普通人的五倍。九成以上的自杀发生在受伤后的头十年。受伤原因本身就是自杀的人，风险还要高出一截。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-3', '精神障碍住院以自愿为原则，只有两种情形可以不经本人同意', '为什么精神障碍住院以自愿为原则，只有两种情形可以不经本人同意？', '家属或单位一句话，不能把一个人留在精神病院住院。法律只认两种情况：已经伤害自己或有这个危险，已经危害别人或有这个危险。第一种要监护人同意才能收。对诊断有异议的，三天内可以要求再次诊断，之后还能自己委托鉴定。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-4', '长期照护家里残疾人的那个人，自己的身体要有人盯着', '为什么长期照护家里残疾人的那个人，自己的身体要有人盯着？', '照护者累垮不是矫情。一项美国研究跟踪了八百多位老人四年。一边照护失能的配偶、一边报告自己精神吃力的那批人，死亡风险比不照护的人高约六成。照护但不觉得吃力的人，没有出现这种升高。所以要盯的不是照护本身，是那份长期紧绷。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-5', '长期坐轮椅的，坐垫换成减压型，每天看一遍坐骨和尾骨', '为什么长期坐轮椅的，坐垫换成减压型，每天看一遍坐骨和尾骨？', '普通海绵坐垫压久了会把皮肤压破，破了愈合很慢，容易感染。养老院里用减压坐垫的老人，坐骨那里的压疮明显更少，但把尾骨一起算就没看出差别。轮椅本身也要按人的尺寸配，别买个通用款就算了。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-6', '别买「能治好瘫痪、失明、耳聋」的疗法和器械', '为什么别买「能治好瘫痪、失明、耳聋」的疗法和器械？', '广告法把话说死了。医疗、药品、医疗器械的广告，不许保证疗效，不许说治愈率和有效率，不许找人现身说法。所以「三个疗程站起来」「多少人已经康复」这类话本身就是违法广告，不用再研究它讲的原理。不是医疗器械的东西，连提治病都不允许。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-7', '残疾人证办下来之后，去县级残联把能申请的东西一次问全', '为什么残疾人证办下来之后，去县级残联把能申请的东西一次问全？', '残疾人证本身不发钱，它是一把钥匙。接在它后面的是好几笔各自独立的待遇，每一笔都要自己去申请，不会自动上门。第一次去残联，就把清单上的项目一项项问过来，比来回跑几趟省事。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-8', '孩子不满 7 岁又有残疾或者孤独症的，去县级残联申请康复救助', '为什么孩子不满 7 岁又有残疾或者孤独症的，去县级残联申请康复救助？', '国家给 0 到 6 岁的残疾儿童和孤独症儿童建了一套康复救助制度，管手术、辅助器具和康复训练。救助对象先保困难家庭，地方财力允许的可以放宽年龄和家庭经济条件。这一段是康复效果最好的窗口，别拖到该上学了再说。机构要从残联的定点名单里挑。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-9', '家里的坡道、扶手和浴室改造，可以向县级以上政府申请补贴', '为什么家里的坡道、扶手和浴室改造，可以向县级以上政府申请补贴？', '《无障碍环境建设法》写了一条：县级以上政府应当支持、指导家庭无障碍设施改造，对符合条件的残疾人、老年人家庭应当给予适当补贴。这类项目一般由残联牵头，按年度名额做，所以要早点去登记。补多少、改哪几项由各地定。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","B 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-10', '找工作时主动说明自己持证，企业招你能抵掉一笔钱', '为什么找工作时主动说明自己持证，企业招你能抵掉一笔钱？', '单位安排残疾人就业的比例不得低于在职职工总数的 1.5%，具体比例由省里定。达不到就要按差额人数交残疾人就业保障金，一个人头按本单位上年职工年平均工资算。所以招你不只是照顾，是实打实省钱。面试时把持证这件事说清楚，对方自己算得过来这笔账。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-11', '残疾人的个人所得税可以减征，减多少打电话问省税务局', '为什么残疾人的个人所得税可以减征，减多少打电话问省税务局？', '个人所得税法写着，残疾人的所得可以减征个税。但是减多少、减多久，法律交给了省级政府定，所以各省不一样。有的省按年度定一个减免限额，有的按比例减。办法是打 12366 问当地税务局，或者在个人所得税 App 里找减免事项。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-12', '导盲犬可以带进公共场所和公共交通，盲人免费坐市内公交', '为什么导盲犬可以带进公共场所和公共交通，盲人免费坐市内公交？', '法律写明，公共场所和公共交通要为带导盲犬、导听犬、辅助犬的残疾人提供便利。盲人凭有效证件免费坐市内公交、地铁和渡船，残疾人可以免费带随身必备的辅助器具。被拦下来时把这两条说出来，不行就投诉。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-13', '残疾人参加高考可以申请合理便利，用盲文卷的考试时间加一半', '为什么残疾人参加高考可以申请合理便利，用盲文卷的考试时间加一半？', '残疾考生参加高考，可以申请盲文卷、大字卷、免外语听力、单独考场、带助听器和轮椅进场，考试时间也能延长。这些不会自动给，要按省里规定的时间交书面申请，附第二代以上的残疾人证。对结果不服，可以找省教育厅申请复核。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-14', '残疾孩子申请入学，学校不得拒收；到不了校的由教育局安排送教上门', '为什么残疾孩子申请入学，学校不得拒收；到不了校的由教育局安排送教上门？', '幼儿园和各类学校，对符合条件的残疾孩子申请入学不得拒收，普通职业学校也一样。孩子需要专人护理、到不了学校的，由县教育局安排送教上门或远程上课，照样有学籍。入学和转学由教育局请专家委员会评估后决定，不由学校自己说了算。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-15', '右下肢或者双下肢没了也能考驾照，准驾车型叫 C5', '为什么右下肢或者双下肢没了也能考驾照，准驾车型叫 C5？', '右下肢或双下肢没了、动不了，但能自己坐稳、上肢条件够的人，可以考残疾人专用的自动挡小车驾照，代号 C5。一只手掌缺失的也能申请。单眼视力障碍、听力障碍的人各有能考的车型。体检要去省里认定的专门医院做。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 自由","钱 多","时间 多","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-16', '康复在有康复医学科的正规机构做，强度听治疗师的，不是越猛越好', '为什么康复在有康复医学科的正规机构做，强度听治疗师的，不是越猛越好？', '把人接回家躺着等自然恢复，是最常见的错。中风后由多学科团队有组织地照护，一年后还活着、还能住在家里的人更多。但也别自己加码，中风后 24 小时内练得更早、更勤、更多，三个月后的结果反而更差。练多少、什么时候练，听康复科和治疗师的。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 死亡率","钱 多","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-17', '听力下降就去配助听器，配它的理由是听得见，不是防痴呆', '为什么听力下降就去配助听器，配它的理由是听得见，不是防痴呆？', '「戴助听器能防痴呆」这个说法目前没有立住。一项近千人的三年试验，总体上没有做出差别。只有在本来认知下降风险就偏高的那部分人里看到了差别。所以配助听器的理由是当下听得见、能和人说话、过马路能听见车，不是为了几十年以后的脑子。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-18', '说一个成年人「管不了自己的事」，要向法院申请认定，家属说了不算', '为什么说一个成年人「管不了自己的事」，要向法院申请认定，家属说了不算？', '一个成年人是不是「无民事行为能力」或者「限制民事行为能力」，只有法院能认定。家属、单位、居委会都不能自己说了算。要由利害关系人或者有关组织向法院申请。反过来，智力或者精神健康恢复了，也可以申请认定他恢复行为能力。这道程序既是限制，也是保护。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-19', '成年人的监护人按法定顺序定；被监护人伤了别人，由监护人赔', '为什么成年人的监护人按法定顺序定；被监护人伤了别人，由监护人赔？', '成年人失去行为能力后，监护人按顺序来：配偶，父母和子女，其他近亲属，最后是愿意担任的其他人或组织。争起来了由居委会、村委会或民政部门指定，不服可以找法院。人还清醒时可以书面指定将来的监护人。被监护人伤了别人，由监护人赔。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s33-20', '因为残疾被拒招、不转正、少发钱，可以告，但先把过程成本算清', '为什么因为残疾被拒招、不转正、少发钱，可以告，但先把过程成本算清？', '法律禁止在招用、转正、晋级、评职称、报酬、社保上歧视残疾人。你可以向主管部门投诉，也可以去法院告。但打赢了官司，对方也不替你出律师费。所以先投诉，同时申请法律援助，再考虑打官司。', 'living', '33. 残疾之后怎么活', 'published', 1, 'reference_book', 95, '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 多","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-1', '同时吃两种感冒药或止痛药之前，先看成分表，对乙酰氨基酚只能占一种', '为什么同时吃两种感冒药或止痛药之前，先看成分表，对乙酰氨基酚只能占一种？', '很多感冒药里都掺了对乙酰氨基酚，两盒一起吃就是吃了双份，过量会伤肝。在美国，它造成的急性肝衰竭病人里，近三成没等到换肝就死了。国内说明书建议一天最多吃 2 克，吃药期间也别喝酒。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-2', '孩子发烧不用阿司匹林、尼美舒利和安乃近，含安乃近的感冒药也不给未成年人吃', '为什么孩子发烧不用阿司匹林、尼美舒利和安乃近，含安乃近的感冒药也不给未成年人吃？', '孩子退烧，这三种药都别用。阿司匹林和瑞氏综合征有关，这种病伤脑伤肝，美国统计里约三成病孩死亡，警告发出后病例少了九成多。尼美舒利 12 岁以下禁用，安乃近 18 岁以下禁用。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-3', '60 岁以上、胃出过血、在吃抗凝药或激素的人，吃布洛芬这类止痛药之前先问医生', '为什么60 岁以上、胃出过血、在吃抗凝药或激素的人，吃布洛芬这类止痛药之前先问医生？', '布洛芬、萘普生、阿司匹林这类止痛药会伤胃。在大剂量的试验里，吃布洛芬的人胃出血、穿孔的风险是不吃的约 4 倍。年纪大、胃出过血、同时吃抗凝药或激素、每天喝酒的人，风险更高。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-4', '2 岁以下的孩子感冒，别自己喂复方感冒药和止咳药', '为什么2 岁以下的孩子感冒，别自己喂复方感冒药和止咳药？', '国家药监局要求 14 种儿童复方感冒药加上警示：不建议家长自己给 2 岁以下孩子用，要在医生或药师指导下用。在孩子身上做的试验里，止咳药、抗过敏药效果都不比安慰剂好。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-5', '怀孕 20 周以后，别自己吃布洛芬这类止痛药', '为什么怀孕 20 周以后，别自己吃布洛芬这类止痛药？', '怀孕 20 周以后，羊水大部分是胎儿的肾做出来的。这时吃布洛芬这类药，可能伤到胎儿的肾、让羊水变少。美国收到的这类报告里，有新生儿死亡的病例。医生开的小剂量阿司匹林不在此列。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-6', '反酸烧心自己买奥美拉唑，最多吃 7 天；吞咽困难、呕血、黑便就直接去医院', '为什么反酸烧心自己买奥美拉唑，最多吃 7 天；吞咽困难、呕血、黑便就直接去医院？', '奥美拉唑肠溶片从 2022 年起不用处方就能买，但说明书写明自己吃不超过 7 天，两个月内别再吃。吞咽困难或疼痛、呕血、便血或黑便时不要自己吃，这些可能是严重情况的信号。这药还可能盖住胃癌的症状，耽误诊断。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-7', '普通感冒别找医生要抗生素', '为什么普通感冒别找医生要抗生素？', '感冒吃抗生素，好得不比不吃快。成年人吃了，副作用的风险是不吃的两倍多。流脓鼻涕不到 10 天的，吃抗生素也没有确定的好处。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-8', '拉肚子先喝口服补液盐补水，5 岁以下的孩子不给止泻药', '为什么拉肚子先喝口服补液盐补水，5 岁以下的孩子不给止泻药？', '拉肚子最要紧的是补水，不是止泻。按说明书兑水喝口服补液盐，别拿果汁饮料代替，太甜反而让人更缺水。5 岁以下的孩子不给洛哌丁胺这类止泻药，严重的会肠梗阻，可能致命。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-9', '止痛药一个月别吃超过 15 天，复方止痛药别超过 10 天，不然头痛可能就是药吃出来的', '为什么止痛药一个月别吃超过 15 天，复方止痛药别超过 10 天，不然头痛可能就是药吃出来的？', '头痛老犯、就天天吃止痛药，可能越吃越痛。国际头痛分类把这叫药物过度使用性头痛。普通止痛药一个月吃 15 天以上，复方止痛药 10 天以上，连着超过 3 个月，就够得上。多数人停掉吃多的药以后会好转。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-10', '过期药和用不上的剩药定期清出来，连包装投进有害垃圾桶，别留在家里', '为什么过期药和用不上的剩药定期清出来，连包装投进有害垃圾桶，别留在家里？', '小孩背着大人误吃的药，近一半是处方药片。误吃的处方药里，约三成是爷爷奶奶的。用不上的药清出来，就少一样能被孩子翻到的东西。清出来的药连包装投进有害垃圾桶，或者交给收旧药的药店。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_archive_s34-11', '用头孢、甲硝唑这类抗菌药期间和停药后 7 天内不喝酒，藿香正气水、止咳糖浆这类含酒精的药也不碰', '为什么用头孢、甲硝唑这类抗菌药期间和停药后 7 天内不喝酒，藿香正气水、止咳糖浆这类含酒精的药也不碰？', '部分头孢、甲硝唑这类药碰上酒精，会让人脸红、心慌、胸闷、呕吐，重的血压往下掉。不光是白酒啤酒，藿香正气水、止咳糖浆这类含酒精的药也会引起。吃药期间到停药后 7 天都别碰。', 'living', '34. 家里的常备药别吃出事', 'published', 1, 'reference_book', 95, '{"34. 家里的常备药别吃出事","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB001', '罐头为什么能放很久？', '罐头为什么能放很久？', '热处理 + 密封是商业罐藏长期保存的核心机制之一。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","食品","罐头","食品保存"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB002', '未开封罐头为什么通常不用放冰箱？', '未开封罐头为什么通常不用放冰箱？', '符合商业罐藏工艺的未开封罐头可在常温保存。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","罐头","冷藏","食品保存"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB003', '罐头开封后为什么要冷藏？', '罐头开封后为什么要冷藏？', '开封破坏了原来的密封保护，微生物就重新获得了进入和生长的机会。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","罐头","开封","冷藏"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB004', '“保质期长”不等于“加了很多防腐剂”', '为什么“保质期长”不等于“加了很多防腐剂”？', '食品能久放，可能来自热处理、低水分、低温、酸度、密封等多种机制。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","防腐剂","食品科技","添加剂"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB005', '食品包装上的“最佳食用期”不等于“当天过期就有毒”', '为什么食品包装上的“最佳食用期”不等于“当天过期就有毒”？', '日期标签可能涉及品质而不一定等同于瞬间变成不安全。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","保质期","日期标签"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB006', '冰箱不会“杀死所有细菌”', '为什么冰箱不会“杀死所有细菌”？', '冰箱主要是降低温度、减慢许多微生物的生长，而不是把食品灭菌。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","冰箱","微生物","保鲜"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB007', '冷冻不等于消毒', '为什么冷冻不等于消毒？', '冷冻主要抑制生长，不能把所有病原微生物都可靠杀死。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","冷冻","食品安全"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB008', '冷冻烧（freezer burn）主要是品质问题', '为什么冷冻烧（freezer burn）主要是品质问题？', '冷冻烧更多是水分升华和氧化造成的干燥、变色、风味下降。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","冷冻","食品品质"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB009', '剩菜真正重要的是时间和温度，不是“隔夜”两个字', '为什么剩菜真正重要的是时间和温度，不是“隔夜”两个字？', '食品安全风险和它放了多久、处于什么温度、是否快速冷却更相关。', 'food', 'food', 'published', 1, 'imported', 92, '{"生活盲区","food","剩菜","隔夜菜","食品安全"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
