INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB169', '为什么湿衣服晾起来会干？水分子在不断离开液面', '为什么湿衣服晾起来会干？水分子在不断离开液面', '蒸发是液体表面分子获得足够能量后进入气相的过程。', 'science', 'science', 'published', 1, 'imported', 92, '{"生活盲区","science","蒸发","湿衣服"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_blindspot_LB170', '冰为什么会让饮料变冷？因为它融化时吸收热量', '冰为什么会让饮料变冷？因为它融化时吸收热量', '冰从固态融化为液态需要吸收潜热，因此可以从饮料带走大量热量。', 'science', 'science', 'published', 1, 'imported', 92, '{"生活盲区","science","冰","融化","潜热"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0001', '为什么棉织物容易吸汗，却不一定干得快', '为什么棉织物容易吸汗，却不一定干得快？', '棉纤维亲水，能吸收水分；吸进去的水还需要蒸发，干燥速度也受织物厚度、织法、温度和气流影响。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0002', '羊毛为什么常被用作保暖材料', '羊毛为什么常被用作保暖材料？', '羊毛纤维的卷曲形态有助于形成纤维间的空气层，空气层会减慢热量传递。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0003', '亚麻衣服为什么容易起皱', '亚麻衣服为什么容易起皱？', '亚麻纤维刚挺、弹性回复能力有限，折叠或坐压后不容易完全恢复原状。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0004', '丝绸为什么摸起来顺滑，却需要谨慎护理', '丝绸为什么摸起来顺滑，却需要谨慎护理？', '蚕丝纤维表面和细长结构会带来平滑触感，但不同染整工艺和织法会影响耐摩擦、耐光与耐洗表现。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0005', '聚酯纤维为什么常用于运动服', '聚酯纤维为什么常用于运动服？', '聚酯纤维强度和尺寸稳定性较好，较容易做成轻量、快干的运动面料。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0006', '弹性纤维为什么能让衣服拉伸后回弹', '弹性纤维为什么能让衣服拉伸后回弹？', '氨纶等弹性纤维能在拉伸后产生较强回复力，常与其他纤维混纺以兼顾贴合和舒适。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
