INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0009', '衣服的克重是什么意思', '衣服的克重是什么意思？', '克重通常表示单位面积织物的质量，可辅助判断面料厚薄和用料，但不能单独决定保暖或质量。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0010', '衣服为什么会起球', '衣服为什么会起球？', '短纤维和表面纤维在摩擦中缠结形成小球，纤维长度、纱线结构和摩擦程度都会影响起球。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
