INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0017', '衣物护理标签为什么值得看', '衣物护理标签为什么值得看？', '护理标签把生产商验证过的洗涤、漂白、烘干、熨烫或专业护理限制传递给使用者。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
