INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0020', '衣物的紫外线防护为什么不能只看颜色', '衣物的紫外线防护为什么不能只看颜色？', '紫外线透过量受纤维、织法、厚度、伸展、潮湿和整理工艺共同影响。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0021', '肉类煎出棕色表层，为什么不只是“烤焦”', '肉类煎出棕色表层，为什么不只是“烤焦”？', '高温下氨基酸与还原糖等物质可发生美拉德反应，形成棕色和复杂香气；它与单纯烧焦不是同一过程。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0022', '糖为什么会焦糖化', '糖为什么会焦糖化？', '糖在足够高的温度下会发生分解和重组，形成颜色与焦糖风味；具体温度范围随糖种和条件而变。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0023', '蛋白为什么加热后会凝固', '蛋白为什么加热后会凝固？', '热会改变蛋白质的空间结构，使其展开并彼此结合，形成新的网络结构。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0024', '蛋清为什么能打发成泡沫', '蛋清为什么能打发成泡沫？', '搅打把空气分散成气泡，蛋白质在气泡界面形成膜，帮助泡沫暂时稳定。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0025', '蛋黄为什么能帮助蛋黄酱乳化', '蛋黄为什么能帮助蛋黄酱乳化？', '蛋黄中的卵磷脂等成分可帮助油滴分散在水相中，让混合物较稳定。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0026', '面粉中的面筋是什么', '面粉中的面筋是什么？', '小麦面粉的部分蛋白质遇水并经过揉混后形成有弹性的网络，能帮助面团 удерж удерж住气体。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0027', '酵母为什么能让面团膨胀', '酵母为什么能让面团膨胀？', '酵母代谢可产生二氧化碳，气体被面团网络部分 удерж住后使其膨胀。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0028', '泡打粉和小苏打有什么区别', '泡打粉和小苏打有什么区别？', '小苏打需要酸等条件产生二氧化碳；泡打粉通常把碱性成分与酸性成分配在一起，并可能受潮湿和加热触发。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0029', '为什么烤箱预热会影响烘焙', '为什么烤箱预热会影响烘焙？', '烘焙依赖稳定的热环境；把冷面团放进未达到目标温度的烤箱可能改变膨胀和定型时序。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0030', '为什么高海拔烘焙可能需要调整配方', '为什么高海拔烘焙可能需要调整配方？', '气压降低会改变水的沸点与气体膨胀行为，从而影响烘焙中的膨胀、干燥和定型。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0031', '盐为什么不仅用于调咸味', '盐为什么不仅用于调咸味？', '盐会影响蛋白质、淀粉和水分的行为，也能改变味觉对其他味道的感知。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0032', '糖为什么会影响面包的口感', '糖为什么会影响面包的口感？', '糖可提供甜味，也会影响发酵、褐变、水分保持和面包组织；作用取决于配方比例。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0033', '淀粉为什么能让酱汁变稠', '淀粉为什么能让酱汁变稠？', '加热和水分会使淀粉颗粒吸水膨胀并释放部分分子，增加液体黏度。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0034', '明胶为什么能让甜品凝固', '明胶为什么能让甜品凝固？', '明胶冷却后可形成可逆的三维网络，把水分包在结构中，产生凝胶口感。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0035', '果胶为什么能让果酱成胶', '果胶为什么能让果酱成胶？', '果胶是植物细胞壁中的多糖，某些条件下可形成网络并让果酱变稠或凝固。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0036', '味精为什么能增加鲜味', '味精为什么能增加鲜味？', '谷氨酸盐能激活鲜味相关味觉受体，使食物的鲜味更明显。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0037', '辣椒为什么会让人觉得“辣得痛”', '辣椒为什么会让人觉得“辣得痛”？', '辣椒素会激活与热刺激相关的感觉受体，引发灼热感，但辣味不等于食物真的处于高温。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0038', '洋葱切开为什么容易刺激眼睛', '洋葱切开为什么容易刺激眼睛？', '切割破坏细胞后，含硫前体与酶发生反应，生成挥发性刺激物并到达眼表。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0039', '蘑菇为什么受热后容易出水', '蘑菇为什么受热后容易出水？', '蘑菇含水量较高，加热会破坏组织结构并促使水分释放。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0040', '咖啡萃取为什么不是“泡得越久越好”', '咖啡萃取为什么不是“泡得越久越好”？', '水温、研磨粒径、时间、搅动和水粉比例共同影响溶出物，过度萃取可能带来不理想的苦涩与口感。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0041', '淋巴系统为什么不只是“免疫系统的一部分”', '淋巴系统为什么不只是“免疫系统的一部分”？', '淋巴系统回收组织间液、运输部分脂肪，并参与免疫细胞的循环与监测。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0042', '红细胞为什么呈双凹圆盘形', '红细胞为什么呈双凹圆盘形？', '双凹形状增加表面积与体积比，并帮助红细胞在细小血管中变形通过。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0043', '白细胞为什么有不同类型', '白细胞为什么有不同类型？', '免疫系统需要不同细胞承担识别、吞噬、抗体产生和协调反应等任务。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0044', '血小板为什么会帮助止血', '血小板为什么会帮助止血？', '血管受损时，血小板可黏附、聚集并参与凝血过程，形成初步止血塞。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0045', '骨骼为什么会不断更新', '骨骼为什么会不断更新？', '骨组织会持续经历形成和吸收，受机械负荷、激素、营养与年龄等因素影响。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0046', '软骨为什么比骨头更难修复', '软骨为什么比骨头更难修复？', '许多软骨组织血液供应有限，修复细胞和营养到达方式不同，损伤后恢复往往较慢。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0047', '韧带和肌腱有什么区别', '韧带和肌腱有什么区别？', '韧带主要连接骨与骨并稳定关节；肌腱主要把肌肉产生的力量传到骨骼。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0048', '肌肉为什么能产生力量', '肌肉为什么能产生力量？', '肌肉细胞内的蛋白丝在神经信号和能量供应下相互滑动，产生收缩。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0049', '肌肉为什么会疲劳', '肌肉为什么会疲劳？', '运动时能量供给、代谢物变化、神经驱动、热调节和肌肉局部过程都会参与疲劳。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0050', '肌腱为什么通常不像肌肉那样灵活', '肌腱为什么通常不像肌肉那样灵活？', '肌腱主要由排列紧密的胶原纤维构成，适合传递拉力但弹性和血供特征不同于肌肉。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0051', '肝脏为什么会参与消化，却不是消化道管道的一段', '肝脏为什么会参与消化，却不是消化道管道的一段？', '肝脏制造胆汁并参与营养物质处理、代谢与储存，但食物本身通常并不直接通过肝脏。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0052', '胆囊为什么会储存胆汁', '胆囊为什么会储存胆汁？', '肝脏持续产生胆汁，胆囊可在两餐之间储存并浓缩它，进食后再将胆汁释放到小肠。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0053', '胰腺为什么同时和消化、血糖有关', '胰腺为什么同时和消化、血糖有关？', '胰腺外分泌部分释放消化酶，内分泌部分释放胰岛素、胰高血糖素等激素。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0054', '肾脏为什么不只是“制造尿液”', '肾脏为什么不只是“制造尿液”？', '肾脏过滤血液并调节水、电解质、酸碱平衡，还参与血压调节和红细胞生成相关信号。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0055', '甲状腺激素为什么会影响许多身体功能', '甲状腺激素为什么会影响许多身体功能？', '甲状腺激素参与调节代谢速度、体温生成、心率与生长发育等过程。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0056', '垂体为什么常被称为“内分泌中枢”之一', '垂体为什么常被称为“内分泌中枢”之一？', '垂体释放多种激素，参与调节甲状腺、肾上腺、生殖腺和生长等功能；它本身也受下丘脑调控。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0057', '大脑为什么需要髓鞘', '大脑为什么需要髓鞘？', '髓鞘包裹许多神经纤维，帮助电信号更快速、更有效地沿轴突传播。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0058', '反射为什么有时比有意识反应更快', '反射为什么有时比有意识反应更快？', '部分反射回路可通过脊髓或脑干较短路径完成，不必等待复杂的有意识处理。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0059', '瞳孔为什么会随光线改变大小', '瞳孔为什么会随光线改变大小？', '虹膜中的肌肉根据光照和神经信号改变瞳孔直径，帮助调节进入眼睛的光量。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0060', '耳朵为什么能帮助维持平衡', '耳朵为什么能帮助维持平衡？', '内耳前庭系统检测头部旋转与线性加速度，并与视觉和本体感觉共同参与平衡。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0061', '化验单上的参考区间为什么不是“健康与生病的绝对分界线”', '化验单上的参考区间为什么不是“健康与生病的绝对分界线”？', '参考区间通常基于特定人群和统计方法建立，单个结果需要结合症状、病史、采样条件和其他检查解释。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0062', '筛查和诊断检查有什么区别', '筛查和诊断检查有什么区别？', '筛查通常用于无明显症状的人群寻找风险信号；诊断检查用于评估具体症状或确认某种疾病。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0063', '假阳性为什么会发生', '假阳性为什么会发生？', '即使检测准确度较高，当被检测疾病在人群中很少见时，阳性结果中也可能有相当比例来自没有该病的人。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
