INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0098', '皮肤为什么会起鸡皮疙瘩', '皮肤为什么会起鸡皮疙瘩？', '立毛肌收缩会让毛囊周围皮肤隆起，是自主神经反应的一种表现。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0099', '触觉为什么会对某些区域特别敏感', '触觉为什么会对某些区域特别敏感？', '皮肤不同部位的感受器密度、感受野大小和大脑表征不同，造成触觉分辨率差异。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0100', '为什么疼痛与组织损伤程度不总是一一对应', '为什么疼痛与组织损伤程度不总是一一对应？', '疼痛是感受输入、神经处理、情绪、注意和经验共同产生的体验，不能简单当作损伤量表。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0101', '水泥、混凝土和砂浆为什么不是同一种东西', '水泥、混凝土和砂浆为什么不是同一种东西？', '水泥是胶凝材料，混凝土通常由胶凝材料、骨料和水等组成，砂浆一般用于砌筑、抹面或粘结，骨料粒径和用途不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0102', '钢筋为什么要放在混凝土里', '钢筋为什么要放在混凝土里？', '混凝土抗压性能较好而抗拉性能相对弱，钢筋可帮助结构承受拉力并共同工作。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0103', '墙体为什么不都能随便拆', '墙体为什么不都能随便拆？', '部分墙体承担楼板、屋顶或侧向荷载，另一些是隔墙；仅凭外观很难确认结构作用。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0104', '隔音和吸音有什么区别', '隔音和吸音有什么区别？', '吸音减少室内声能反射，隔音则降低声音从一侧传到另一侧；两者通常需要不同设计。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0105', '热桥为什么会让某些墙角更容易结露', '热桥为什么会让某些墙角更容易结露？', '热桥是热量较容易通过的局部部位，表面温度可能低于周围区域，水汽因此更容易凝结。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0106', '双层玻璃为什么有助于隔热', '双层玻璃为什么有助于隔热？', '两层玻璃之间的密封空间可减缓热传递，气体填充、间距和低辐射涂层会进一步影响性能。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0107', '窗户上的低辐射涂层有什么用', '窗户上的低辐射涂层有什么用？', '低辐射涂层可改变玻璃表面的热辐射传递特性，在合适设计中降低部分热量交换。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0108', '窗框材料为什么会影响室内热损失', '窗框材料为什么会影响室内热损失？', '不同材料的导热能力不同，窗框截面和隔热断桥设计也会改变热量通过路径。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0109', '建筑伸缩缝为什么不是施工瑕疵', '建筑伸缩缝为什么不是施工瑕疵？', '温度变化、湿度和结构运动会引起材料尺寸变化，接缝为预期位移提供空间。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0110', '瓷砖缝为什么需要合适的填缝材料', '瓷砖缝为什么需要合适的填缝材料？', '填缝料帮助封闭接缝并承担部分表面使用条件，但不同位置的位移、湿度和化学暴露不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0111', '防水层为什么通常藏在饰面下面', '防水层为什么通常藏在饰面下面？', '瓷砖、石材等饰面本身和接缝不一定构成完整防水系统，防水层负责阻止水进入结构层。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0112', '屋顶泛水板为什么重要', '屋顶泛水板为什么重要？', '泛水板把水从墙体、烟囱、天窗等交界处引导离开，降低水进入建筑缝隙的机会。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0113', '檐沟和落水管的作用是什么', '檐沟和落水管的作用是什么？', '它们把屋顶雨水集中导离墙体和基础，减少冲刷、积水与部分渗水风险。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0114', '门窗密封条为什么会老化', '门窗密封条为什么会老化？', '橡胶或聚合物长期受紫外线、温度、压缩和污染物影响，弹性与密封能力可能下降。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0115', '墙面底漆为什么不是多余的一层', '墙面底漆为什么不是多余的一层？', '底漆可改善基层吸收一致性、附着力或覆盖效果，具体功能取决于产品配方。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0116', '木材为什么会随湿度涨缩', '木材为什么会随湿度涨缩？', '木材会与周围空气交换水分，含水率变化导致尺寸变化，而且不同方向的变化幅度不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0117', '胶合板、刨花板和中密度纤维板有什么区别', '胶合板、刨花板和中密度纤维板有什么区别？', '它们使用木片、颗粒或纤维以不同方式结合，结构和制造过程影响强度、表面质量、重量与耐湿性。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0118', '天然石材为什么也可能被酸性液体损伤', '天然石材为什么也可能被酸性液体损伤？', '某些石材含有易与酸反应的矿物，酸液会造成腐蚀或失去光泽。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0119', '玻璃为什么会因边缘缺口而更容易破裂', '玻璃为什么会因边缘缺口而更容易破裂？', '玻璃受拉应力时，边缘微裂纹可能成为应力集中的起点。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0120', '砖墙为什么会使用砂浆缝', '砖墙为什么会使用砂浆缝？', '砂浆帮助定位砌块、传递部分压力并填充不规则空隙；配比和养护影响强度与耐久。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0121', '缝纫机为什么能把线锁成连续针迹', '缝纫机为什么能把线锁成连续针迹？', '常见锁式线迹由针线与底线在布料中交织形成；机针、旋梭和送布机构需要同步工作。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0122', '激光打印机为什么先让粉末附着再转到纸上', '激光打印机为什么先让粉末附着再转到纸上？', '激光打印机通常用静电图像吸引碳粉，再通过转印与加热定影把图像固定在纸面。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0123', '喷墨打印机的墨水为什么可能堵头', '喷墨打印机的墨水为什么可能堵头？', '喷嘴孔径很小，墨水干结、颗粒或长时间不使用可能影响喷射。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0124', '热敏打印机为什么通常不用传统墨盒', '热敏打印机为什么通常不用传统墨盒？', '直接热敏纸会在受热处改变颜色；热转印则用加热将色带材料转移到介质上。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0125', '条形码为什么能被快速识读', '条形码为什么能被快速识读？', '条纹或图案按标准编码信息，扫描器读取反射差异并把图形转换成数字数据。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0126', '光纤为什么能传输大量数据', '光纤为什么能传输大量数据？', '光信号在特定条件下沿纤芯传播，光纤具有高带宽、低损耗和抗电磁干扰等优点。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0127', '触控屏为什么能感知手指', '触控屏为什么能感知手指？', '常见电容屏检测手指对电场或电容分布的影响；其他技术也可能利用压力或光学变化。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0128', '相机光圈数字为什么越小，开口反而通常越大', '相机光圈数字为什么越小，开口反而通常越大？', 'f值是焦距与有效光圈直径的比值，因此在相同焦距下，较小f值对应较大的开口。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0129', '快门速度为什么影响运动模糊', '快门速度为什么影响运动模糊？', '曝光期间物体或相机相对移动会在传感器上形成位移，曝光时间越长通常越容易留下运动轨迹。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0130', '自动对焦为什么在低光或低对比场景更难', '自动对焦为什么在低光或低对比场景更难？', '对焦系统需要从图像或传感信号找到可用于判断清晰度的特征，低光和低对比会减少可靠线索。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0131', '双筒望远镜上的数字通常代表什么', '双筒望远镜上的数字通常代表什么？', '例如“8×42”通常表示8倍放大和42毫米物镜口径。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0132', '折射望远镜和反射望远镜有什么区别', '折射望远镜和反射望远镜有什么区别？', '折射式主要用透镜聚焦，反射式主要用镜面聚焦，设计会影响体积、色差、维护和成本。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0133', '显微镜为什么需要分辨率而不只是放大倍率', '显微镜为什么需要分辨率而不只是放大倍率？', '分辨率指能区分两个相近细节的能力；单纯放大模糊图像并不会增加真实细节。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0134', '激光测距仪为什么能测距离', '激光测距仪为什么能测距离？', '设备通过测量光脉冲往返时间或相位差估计到目标的距离。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0135', '棘轮扳手为什么可以连续转动螺母', '棘轮扳手为什么可以连续转动螺母？', '棘轮机构允许手柄在一个方向带动齿轮、另一个方向空回，减少反复换位需要。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0136', '扭矩为什么不是单纯“手劲大小”', '扭矩为什么不是单纯“手劲大小”？', '扭矩是力与力臂等因素共同决定的转动效应，施力点越远，产生同样扭矩所需的力可能越小。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0137', '液压千斤顶为什么能用较小的力抬起重物', '液压千斤顶为什么能用较小的力抬起重物？', '液压系统利用封闭液体传递压力，不同面积的活塞能产生不同的力，但位移和输入功也相应变化。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0138', '滚动轴承为什么能减少摩擦', '滚动轴承为什么能减少摩擦？', '滚动体把主要相对运动从滑动转为滚动，通常能降低某些工况下的摩擦损失。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0139', '铅笔芯为什么不是铅做的', '铅笔芯为什么不是铅做的？', '现代铅笔芯通常主要由石墨和黏土等材料混合制成，颜色来自石墨而不是金属铅。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0140', '橡皮为什么可以擦掉铅笔字', '橡皮为什么可以擦掉铅笔字？', '橡皮通过黏附和摩擦把纸面上的石墨颗粒带离或重新分散。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0141', '飞机机翼为什么能产生升力', '飞机机翼为什么能产生升力？', '机翼周围的气流与压力分布、偏转气流和迎角共同参与升力形成，不能只用一个过度简化的口诀解释。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0142', '客机巡航时为什么要加压客舱', '客机巡航时为什么要加压客舱？', '高空外界气压很低，客舱加压把舱内压力维持在适合乘客与设备的范围。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0143', '飞机的黑匣子为什么常是橙色', '飞机的黑匣子为什么常是橙色？', '飞行数据记录器和驾驶舱语音记录器常采用醒目的橙色外壳，以便事故后更容易寻找。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0144', '跑道编号为什么与方向有关', '跑道编号为什么与方向有关？', '跑道编号通常以磁航向按近似十度取整表示，同一条跑道从相反方向使用时编号差约180度。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0145', '飞机遇到乱流为什么天空晴朗也可能发生', '飞机遇到乱流为什么天空晴朗也可能发生？', '湍流可由高空急流、山脉地形、温度锋面或晴空大气运动造成，未必能从窗外提前看见。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0146', '飞机机舱为什么通常有圆角窗', '飞机机舱为什么通常有圆角窗？', '圆角能减少角部应力集中，帮助压力循环下的结构承受疲劳负荷。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0147', '飞机为什么常沿航路而不是直线飞到目的地', '飞机为什么常沿航路而不是直线飞到目的地？', '航路要考虑空域组织、天气、地形、交通流、燃油效率和空管安排。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0148', '地铁车轮为什么采用特殊轮廓', '地铁车轮为什么采用特殊轮廓？', '车轮踏面和轮缘几何有助于引导车辆在轨道上行驶，并影响曲线通过与稳定性。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0149', '轨道电气化为什么能改变铁路的运营方式', '轨道电气化为什么能改变铁路的运营方式？', '电气化铁路通过架空接触网或第三轨向牵引系统供电，减少对车载燃料的依赖。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0150', '铁路轨距为什么会影响跨境运输', '铁路轨距为什么会影响跨境运输？', '轨距是两条钢轨内侧间的距离，不同轨距可能需要换轨、换转向架或换装货物。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0151', '集装箱为什么改变了全球物流', '集装箱为什么改变了全球物流？', '标准化集装箱可在船、铁路和卡车之间转运，减少重复装卸和货损，并推动港口机械化。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0152', '港口吊机为什么能搬动重型集装箱', '港口吊机为什么能搬动重型集装箱？', '起重机使用机械结构、钢索、滑轮和驱动系统把负载安全地提升、横移和定位。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0153', '船为什么能浮在水上', '船为什么能浮在水上？', '当船体排开水的重量足以平衡船与货物的重量时，浮力可支撑船只。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0154', '压舱水为什么可能带来生态问题', '压舱水为什么可能带来生态问题？', '船舶为稳定和操纵会取入、排出压舱水，其中可能携带异地生物或病原体。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0155', '自行车变速为什么不是让脚“自动更有力”', '自行车变速为什么不是让脚“自动更有力”？', '齿比改变每次踩踏对应的车轮转动量，骑行者可在速度、坡度和腿部发力之间做取舍。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0156', '自行车链条为什么需要清洁与润滑', '自行车链条为什么需要清洁与润滑？', '链条滚子、销轴与齿片持续承载并相互接触，污染物会增加磨耗，适当润滑可减少摩擦与腐蚀。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0157', '自行车碟刹为什么通过摩擦减速', '自行车碟刹为什么通过摩擦减速？', '刹车片夹紧转子，把运动能量主要转换为热量。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0158', '汽车后视镜为什么会有视野盲区', '汽车后视镜为什么会有视野盲区？', '镜面曲率与驾驶员位置限制可见区域，车辆结构也会遮挡部分视线。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0159', '道路标线为什么夜间会显得更亮', '道路标线为什么夜间会显得更亮？', '部分标线使用玻璃微珠等反光材料，把车灯光线反射回驾驶者方向，增强可见性。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0160', '交通环岛为什么能改变冲突点分布', '交通环岛为什么能改变冲突点分布？', '环岛通过车辆绕行和让行规则，把一些直角交叉冲突转化为较低速度的交织与并入冲突。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0161', '债券价格为什么通常会与市场利率反向变动', '债券价格为什么通常会与市场利率反向变动？', '已有固定票息债券的现金流不变时，市场新债收益率上升会使旧债价格调整，才能与新收益水平竞争。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0162', '票面利率与到期收益率有什么区别', '票面利率与到期收益率有什么区别？', '票面利率按债券面值计算定期利息；到期收益率考虑购买价格、未来现金流和到期偿还金额。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0163', '股票市值是什么意思', '股票市值是什么意思？', '公司市值通常按股价乘以流通或发行在外股份数估算，是市场对股权价值的度量。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0164', '股票拆分为什么不自动让投资者变富', '股票拆分为什么不自动让投资者变富？', '拆分会增加持股股数并相应调整每股价格，在其他条件不变时总持仓价值不会仅因拆分而改变。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0165', '首次公开募股（IPO）是什么', '首次公开募股（IPO）是什么？', 'IPO通常是公司首次向公众发行股票并进入公开市场交易的过程，具体结构和规则因市场而异。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0166', '股息为什么不是“额外免费收益”', '股息为什么不是“额外免费收益”？', '公司支付股息是向股东分配现金或资产，除息后股价可能相应调整，企业可用资金也会减少。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0167', '指数为什么不能代表整个经济的全部状态', '指数为什么不能代表整个经济的全部状态？', '股票指数按其成分、权重和编制规则反映特定市场或一组证券，而不是所有企业、家庭和劳动者的状况。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0168', '共同基金和ETF为什么能帮助分散持仓', '共同基金和ETF为什么能帮助分散持仓？', '它们把许多投资者的资金集中起来持有一篮子资产，但实际分散程度取决于基金持仓与策略。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0169', '基金费用为什么值得认真看', '基金费用为什么值得认真看？', '管理费、交易成本和其他费用会减少可归属于投资者的净回报。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0170', '流动性是什么意思', '流动性是什么意思？', '流动性指资产能在多大程度上及时转换为现金，且不必承担过大折价或交易成本。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0171', '汇率报价为什么有买入价和卖出价', '汇率报价为什么有买入价和卖出价？', '金融机构在兑换货币时会提供不同的买入与卖出价格，价差是交易成本和市场条件的一部分。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0172', '名义收益与实际收益有什么区别', '名义收益与实际收益有什么区别？', '名义收益没有扣除价格水平变化；实际收益试图衡量购买力变化，通常需要考虑通胀。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0173', '消费者价格指数为什么不等于每个人的生活成本变化', '消费者价格指数为什么不等于每个人的生活成本变化？', 'CPI按特定篮子、权重和统计方法跟踪价格变化，个人消费结构与居住地区可能不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0174', '国内生产总值（GDP）衡量什么', '国内生产总值（GDP）衡量什么？', 'GDP通常衡量一段时期内一国或地区境内最终商品和服务的市场价值，是经济活动指标之一。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0175', '政府预算赤字和政府债务有何不同', '政府预算赤字和政府债务有何不同？', '赤字是一定时期支出超过收入的流量；债务是累积的未偿还义务存量。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0176', '边际税率与平均税率为什么不同', '边际税率与平均税率为什么不同？', '边际税率作用于额外一单位应税收入所处的税率区间；平均税率是总税额占收入的比例。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0177', '工资单上的税前工资与到手工资为什么不一样', '工资单上的税前工资与到手工资为什么不一样？', '税前工资可能还需扣除税费、社保、退休计划或其他授权项目，实际到手金额因此不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0178', '按揭月供为什么通常包含不止本金和利息', '按揭月供为什么通常包含不止本金和利息？', '房贷月供可能只包括本金与利息，也可能由贷款机构代收税款、保险或其他费用；结构视产品和地区而定。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0179', '首付比例为什么会影响贷款风险和借款成本', '首付比例为什么会影响贷款风险和借款成本？', '更高首付通常减少借款本金和贷款价值比，但也占用更多现金；具体利率和保险规则视地区与贷款产品而定。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0180', '债务的名义利率和实际成本为什么可能不同', '债务的名义利率和实际成本为什么可能不同？', '名义利率是合同或市场报价的一部分，实际借款成本还受费用、计息频率、通胀和还款结构影响。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0181', '民事纠纷和刑事案件有什么核心区别', '民事纠纷和刑事案件有什么核心区别？', '民事程序通常处理个人或组织之间的权利义务争议；刑事程序处理被认为违反刑法的行为与国家追诉。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0182', '“举证责任”是什么意思', '“举证责任”是什么意思？', '举证责任指诉讼中哪一方需要提出足以支持某项主张的证据；不同案件和争点的分配规则不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0183', '无罪推定的含义是什么', '无罪推定的含义是什么？', '在适用该原则的刑事司法体系中，被告在依法认定有罪前应被视为无罪。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0184', '调解和仲裁有什么区别', '调解和仲裁有什么区别？', '调解通常由中立第三方帮助当事人协商解决；仲裁通常由仲裁员按约定或法律作出具有一定拘束力的裁决。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0185', '公证和“文件盖章”为什么不一定是一回事', '公证和“文件盖章”为什么不一定是一回事？', '公证通常由依法授权的人员或机构按程序确认特定事实、签名或文件；普通盖章的法律效果视情境而定。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0186', '授权委托书能做什么', '授权委托书能做什么？', '授权文件可让指定的人在限定范围内代表授权人处理某些事务，权限和生效条件取决于法律与文件内容。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0187', '遗嘱和信托为什么不是同一种安排', '遗嘱和信托为什么不是同一种安排？', '遗嘱通常在立遗嘱人死亡后按法律程序处理遗产；信托涉及将财产置于特定管理安排中，结构可不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0188', '知识产权为什么包含不同权利类型', '知识产权为什么包含不同权利类型？', '著作权、商标权和专利权保护对象与条件不同，分别关注表达、商业标识和符合条件的发明等。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0189', '商标和公司名称有什么区别', '商标和公司名称有什么区别？', '商标用于区分商品或服务来源；公司登记名称是企业登记中的身份信息，两者的法律功能和保护范围不完全相同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0190', '专利为什么有期限和地域限制', '专利为什么有期限和地域限制？', '专利权通常是有限期限、按司法辖区授予的排他性权利，需满足法定条件并遵守维护要求。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0191', '公共领域作品意味着什么', '公共领域作品意味着什么？', '公共领域通常指不受相关著作权限制或保护期已届满的作品，但判断可能涉及地域、版本、其他权利和来源。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0192', '开放源代码许可证为什么有不同类型', '开放源代码许可证为什么有不同类型？', '不同许可证规定使用、修改、分发、署名和再发布时的义务，宽松型与互惠型许可要求可能不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0193', '隐私政策为什么不是“用户完全放弃隐私”的同义词', '隐私政策为什么不是“用户完全放弃隐私”的同义词？', '隐私政策通常说明服务如何收集、使用、共享和保留数据，但权利与义务仍受法律和实际做法约束。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0194', '服务条款为什么可能影响日常使用', '服务条款为什么可能影响日常使用？', '服务条款可能约定账户使用、内容许可、费用、争议处理和暂停服务等条件。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0195', '诉讼时效是什么意思', '诉讼时效是什么意思？', '诉讼时效等规则可能限制某些请求在经过一定时间后是否仍可通过法院主张，但规则和起算点因法域及请求类型而异。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0196', '上诉为什么不是简单地“把原案从头再审一次”', '上诉为什么不是简单地“把原案从头再审一次”？', '上诉程序通常审查下级裁判在法律适用、程序或特定事实认定方面是否存在可纠正问题，范围依制度而异。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
