INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0232', '飓风、台风和气旋为什么是同类系统的不同地区名称', '飓风、台风和气旋为什么是同类系统的不同地区名称？', '这些名称通常指热带气旋在不同海域的叫法，分类阈值和区域机构的命名规则可能不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0233', '龙卷风和热带气旋为什么不是一回事', '龙卷风和热带气旋为什么不是一回事？', '龙卷风是强烈旋转的局地气流柱；热带气旋是大尺度、持续时间更长的暖核低压系统。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0234', '露点为什么常比相对湿度更能说明空气含水情况', '露点为什么常比相对湿度更能说明空气含水情况？', '露点反映空气水汽含量与饱和条件的关系；相对湿度还依赖当前温度。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0235', '雾和低云为什么在物理上相似', '雾和低云为什么在物理上相似？', '两者都涉及近地空气中的微小液滴或冰晶；主要区别在于云层与地表的相对位置和观测定义。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0236', '冰雹为什么会在暖季出现', '冰雹为什么会在暖季出现？', '强对流云中的上升气流能把冰粒带到较冷区域反复增长，达到一定重量后落下。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0237', '气候和天气的时间尺度为什么不同', '气候和天气的时间尺度为什么不同？', '天气描述短期大气状态，气候指更长时期的统计特征与变化。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0238', '城市热岛效应是什么', '城市热岛效应是什么？', '城市建筑、道路和人为热源改变地表储热、通风与蒸发条件，使部分城区比周边农村更暖。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0239', '厄尔尼诺和拉尼娜为什么会影响远方天气', '厄尔尼诺和拉尼娜为什么会影响远方天气？', '热带太平洋海温与大气环流耦合变化可改变全球部分环流型态和降水概率。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0240', '地磁北极和地理北极为什么不是同一个点', '地磁北极和地理北极为什么不是同一个点？', '地理北极由地球自转轴定义，磁极与地球磁场方向相关，位置会随时间变化。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0241', 'DNS在浏览网页时做什么', 'DNS在浏览网页时做什么？', 'DNS把域名解析为设备或服务可用的网络地址，帮助用户用易记名称访问网络服务。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0242', 'IP地址为什么不一定能准确指出个人身份', 'IP地址为什么不一定能准确指出个人身份？', 'IP地址主要用于网络路由和连接标识，可能对应家庭网络、公司出口、共享网络或动态分配。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0243', '浏览器缓存为什么能加快网页加载', '浏览器缓存为什么能加快网页加载？', '缓存会暂存部分图片、脚本或资源，减少重复下载；但过期或损坏的缓存有时也会引发显示问题。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0244', 'Cookie和浏览器缓存有什么区别', 'Cookie和浏览器缓存有什么区别？', 'Cookie通常保存由网站读取的小段状态或标识信息；缓存主要保存资源副本以提升加载效率。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0245', '元数据为什么也可能透露隐私', '元数据为什么也可能透露隐私？', '照片时间、设备信息、文件作者、位置或修改记录等元数据可能揭示内容之外的信息。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0246', '数字签名和电子图片签名有什么区别', '数字签名和电子图片签名有什么区别？', '密码学数字签名可用于验证内容完整性和密钥持有者身份；粘贴的签名图片本身不自动具备同样机制。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0247', '哈希值和加密有什么区别', '哈希值和加密有什么区别？', '哈希函数把输入映射为固定长度摘要，通常不可逆；加密则通过密钥将信息变换为可在有密钥时还原的形式。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0248', '端到端加密意味着什么', '端到端加密意味着什么？', '在正确实现的系统中，消息内容主要只由通信端点解密，中间传递服务难以直接读取明文。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0249', '开源软件为什么不一定“没有商业公司参与”', '开源软件为什么不一定“没有商业公司参与”？', '开源描述源代码的许可与可使用方式，项目仍可由企业、基金会或个人维护并提供付费服务。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0250', '软件版本号为什么不能总用一个数字比较', '软件版本号为什么不能总用一个数字比较？', '版本编号遵循不同项目约定，语义化版本、日期版本和厂商内部版本的含义并不一致。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0251', '文件扩展名为什么不总能保证真实文件格式', '文件扩展名为什么不总能保证真实文件格式？', '扩展名是文件名的一部分，常用于提示类型，但可以被改名，实际格式通常还需看文件内容和签名。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0252', '有损压缩和无损压缩有什么区别', '有损压缩和无损压缩有什么区别？', '无损压缩可在解压后恢复原数据；有损压缩会丢弃部分信息，以换取更小文件。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0253', '数字图像分辨率与打印尺寸有什么关系', '数字图像分辨率与打印尺寸有什么关系？', '同样像素数量在不同打印尺寸下对应不同像素密度，影响近距离观看时细节表现。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0254', 'OCR为什么会把表格或复杂版面读错', 'OCR为什么会把表格或复杂版面读错？', 'OCR要识别字符并推断阅读顺序，低分辨率、倾斜、字体、栏位和手写体都会增加难度。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0255', '语音识别为什么会听错人名和专业词', '语音识别为什么会听错人名和专业词？', '识别系统基于声学信号与语言模型推测词语，口音、噪声、上下文和训练数据会影响结果。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0256', '人脸识别为什么会有误报和漏报', '人脸识别为什么会有误报和漏报？', '识别系统比较图像特征并按阈值判断是否匹配，图像质量、年龄变化、角度和模型训练都影响结果。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0257', '算法推荐为什么不一定显示“最客观的信息”', '算法推荐为什么不一定显示“最客观的信息”？', '推荐系统通常优化点击、观看、相关性或其他目标，目标函数和数据会影响排序结果。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0258', '人工智能生成的答案为什么可能听起来合理却是错的', '人工智能生成的答案为什么可能听起来合理却是错的？', '生成模型根据训练和上下文预测文本，不等于每次都通过数据库验证事实；复杂或冷门细节尤其需要核实。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0259', '推荐算法为什么会放大某些极端观点', '推荐算法为什么会放大某些极端观点？', '若系统把高互动内容当作成功信号，愤怒、争议或极端表达有时会被更多传播。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0260', '深度伪造为什么不只是“视频剪辑得很假”', '深度伪造为什么不只是“视频剪辑得很假”？', '生成模型可合成逼真的脸部、声音或视频片段，使传统的视觉直觉不足以可靠鉴别。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0261', '确认偏误是什么', '确认偏误是什么？', '人们可能更容易注意、相信或记住支持已有看法的信息，而忽略反例。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0262', '锚定效应为什么会影响议价', '锚定效应为什么会影响议价？', '人们判断数量或价值时，可能受到最先出现的数字影响，即使该数字与真实价值关系不大。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
