INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0326', '氮和磷为什么既是农业必需养分，也可能造成水体问题', '氮和磷为什么既是农业必需养分，也可能造成水体问题？', '植物需要氮磷生长，但过量养分流入湖泊和海岸水域可能导致藻类增殖和缺氧。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0327', '豆科植物为什么能帮助土壤获取氮', '豆科植物为什么能帮助土壤获取氮？', '许多豆科植物与根瘤菌共生，微生物可把大气氮转化为植物可利用形式。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
