INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0329', '授粉为什么对许多作物重要', '授粉为什么对许多作物重要？', '授粉把花粉送到合适部位，使植物能够受精并形成种子或果实；不同作物依赖的传粉方式不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
