INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0331', '真菌为什么是生态系统的重要分解者', '真菌为什么是生态系统的重要分解者？', '许多真菌能分解复杂有机物并参与养分循环，有些与植物根系形成互利共生。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0332', '授粉昆虫减少为什么可能影响食物供应', '授粉昆虫减少为什么可能影响食物供应？', '部分果实、坚果和种子作物依赖动物传粉，传粉者减少可能影响产量、稳定性和作物多样性。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0333', '外来物种为什么不一定就是入侵物种', '外来物种为什么不一定就是入侵物种？', '外来物种指被带到原分布范围之外的物种；入侵通常还涉及扩散与生态、经济或健康危害。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0334', '生物多样性为什么不只是物种数量', '生物多样性为什么不只是物种数量？', '多样性还包括遗传差异、生态系统类型、丰度、功能和相互作用等层面。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0335', '碳足迹为什么要说明边界', '碳足迹为什么要说明边界？', '碳足迹计算需要定义生命周期阶段、排放气体、时间范围和系统边界，否则数字难以比较。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0336', '甲烷和二氧化碳为什么不能只按分子数量比较气候影响', '甲烷和二氧化碳为什么不能只按分子数量比较气候影响？', '两者在大气寿命、辐射效应和时间尺度上不同，常用指标会在指定时间范围内比较其增温影响。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0337', '太阳能光伏和太阳能热利用有什么区别', '太阳能光伏和太阳能热利用有什么区别？', '光伏把光转换成电能；太阳能热系统主要收集太阳能加热流体或空间。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0338', '风力发电机为什么不是简单“被风吹动的风扇”', '风力发电机为什么不是简单“被风吹动的风扇”？', '叶片把气流动能转成转子旋转，再由发电机转成电能；叶片形状和控制系统影响效率与负载。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0339', '电网为什么需要频率保持稳定', '电网为什么需要频率保持稳定？', '交流电网中的发电与负载必须保持实时平衡，频率变化可反映系统供需偏差。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0340', '能源效率和能源节约为什么不完全相同', '能源效率和能源节约为什么不完全相同？', '效率描述完成某项服务所需的能量比例；节约还包括减少不必要使用、改变行为和系统需求。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0341', '不锈钢为什么也会生锈', '不锈钢为什么也会生锈？', '不锈钢依靠表面形成富铬钝化膜抵抗腐蚀，但氯盐、酸、划伤和不当清洁仍可能破坏保护条件。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0342', '铸铁锅的“养锅”层是什么', '铸铁锅的“养锅”层是什么？', '经过适当加热的油脂会形成聚合后的薄层，帮助减少粘附并保护表面；它不是神秘的永久涂层。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0343', '不粘涂层为什么需要遵守温度和工具说明', '不粘涂层为什么需要遵守温度和工具说明？', '不同涂层与基材的耐温、耐磨和维护要求不同，过热或金属工具可能损伤表面。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0344', '树脂识别码为什么不等于回收保证', '树脂识别码为什么不等于回收保证？', '塑料上的数字通常用于区分树脂类型，并不直接代表当地回收系统接收该产品。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0345', 'IP防护等级为什么要看两个数字', 'IP防护等级为什么要看两个数字？', '许多IP代码中的首位数字涉及固体异物防护，第二位涉及进水防护，具体等级对应标准测试条件。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0346', '流明和瓦特为什么不是同一种亮度指标', '流明和瓦特为什么不是同一种亮度指标？', '瓦特描述耗用功率，流明描述可见光通量；灯具的光效决定同样功率能产生多少光。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0347', '色温为什么不是灯泡的实际温度', '色温为什么不是灯泡的实际温度？', '色温用开尔文描述光色外观，低色温常偏暖黄，高色温常偏冷白。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0348', '显色指数为什么会影响衣服颜色看起来是否真实', '显色指数为什么会影响衣服颜色看起来是否真实？', '显色性能描述光源呈现物体颜色与参考光源相比的程度，但单一指数不能完整描述所有颜色。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0349', '分贝为什么不能按普通数字直接相加', '分贝为什么不能按普通数字直接相加？', '分贝是对数尺度，声能或声压的比较需要按相应物理量计算。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0350', '家具贴皮、木皮和层压板有什么区别', '家具贴皮、木皮和层压板有什么区别？', '这些术语通常指不同的表面材料或结构：木皮是薄天然木层，层压表面则可能是印刷纸、树脂或其他复合材料。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0351', '墙面锚栓为什么要和墙体类型匹配', '墙面锚栓为什么要和墙体类型匹配？', '锚栓依靠不同机制在石膏板、砖、混凝土或空心墙体中固定，承载能力差异很大。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0352', '胶水为什么有不同的固化机制', '胶水为什么有不同的固化机制？', '有的胶黏剂靠溶剂挥发，有的通过化学反应、湿气、紫外线或冷却形成粘结。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0353', '螺钉和钉子为什么各有适用场景', '螺钉和钉子为什么各有适用场景？', '螺钉的螺纹通过旋入提供拔出阻力，钉子通常依靠摩擦和材料变形固定，安装速度与受力特点不同。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0354', '陶瓷为什么硬却可能脆', '陶瓷为什么硬却可能脆？', '许多陶瓷材料具有较高硬度和耐热性，但裂纹尖端的应力集中可能使其在冲击下突然断裂。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0355', '玻璃杯为什么不能随意冷热冲击', '玻璃杯为什么不能随意冷热冲击？', '不同部位温度变化不一致会产生热应力，超过材料或形状可承受范围时可能开裂。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0356', '胶带为什么有些靠压敏胶，有些需要固化', '胶带为什么有些靠压敏胶，有些需要固化？', '压敏胶通过施压与表面接触形成粘结；其他胶带或胶黏剂可能需要水分、加热或化学反应。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0357', '床垫软硬为什么不是单一的“越硬越护腰”', '床垫软硬为什么不是单一的“越硬越护腰”？', '体重、睡姿、材料、支撑分区和个人疼痛情况都会影响床垫与身体的匹配。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0358', '枕头高度为什么会影响颈部姿势', '枕头高度为什么会影响颈部姿势？', '枕头支撑会改变头颈与躯干的相对角度，合适高度与睡姿、肩宽和床垫有关。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0359', '商品的“认证标志”为什么要核查编号与适用范围', '商品的“认证标志”为什么要核查编号与适用范围？', '标志的含义取决于认证机构、标准、产品类别和市场要求，图案本身可能被仿用。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0360', '产品召回为什么值得持续关注', '产品召回为什么值得持续关注？', '召回可能针对发现的设计缺陷、制造错误或安全风险，已购买的产品也可能受影响。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0361', '月经周期为什么不一定每个月完全一样', '月经周期为什么不一定每个月完全一样？', '排卵与激素变化受生理状态、压力、疾病、药物和年龄等因素影响，周期可能存在一定波动。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0362', '排卵期为什么不是每个人固定在周期第14天', '排卵期为什么不是每个人固定在周期第14天？', '排卵时间会随周期长度和个体差异变化，第14天只是对部分典型周期的简化描述。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0363', '避孕方法的“典型使用”和“完美使用”有什么区别', '避孕方法的“典型使用”和“完美使用”有什么区别？', '完美使用假设每次都按说明正确使用；典型使用还考虑现实中的遗漏、错误和不一致。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0364', '安全套为什么能降低而不是消除所有性传播感染风险', '安全套为什么能降低而不是消除所有性传播感染风险？', '安全套可减少与覆盖区域相关的体液和黏膜接触，但某些感染也可能通过未覆盖皮肤传播。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
