INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0498', '产品规格中的公差是什么意思', '产品规格中的公差是什么意思？', '公差描述某个尺寸或性能允许偏离目标值的范围，具体含义由图纸、标准和测量方法定义。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0499', '商品条码为什么主要用于识别而不是证明真伪', '商品条码为什么主要用于识别而不是证明真伪？', '条码通常编码商品或物流识别信息，读码系统需连接数据库或业务记录才能获取相关资料。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, name, canonical_question, canonical_summary, domain, topic, status, difficulty, origin, quality_score, tags, created_at, updated_at) VALUES ('concept_b1000_NEWC0500', '商标和商品通用名称为什么不是一回事', '商标和商品通用名称为什么不是一回事？', '商标用于区分特定经营者的商品或服务，通用名称则指向一类产品；法律认定因地区、使用方式和证据而异。', 'living', NULL, 'published', 1, 'imported', 90, '{"生活盲区"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
