INSERT INTO sources (id, organization, title, url, source_type, retrieved_at, status, citation) VALUES ('src_archive_s17-7', '国家医保局等八部门', '国家医保局等八部门 (2026). 关于印发《加快建立长期护理保险制度实施方案》的通知. https://www.gov.cn/zhengce/zhengceku/202603/content_7063915…：保障对象为「按规定参保缴费且失能状态长期持续（一般为6个月以上），经申请通过评估认定的失能人员」，「制度起步阶段保障重度失能人员」；「待遇享受不设起付标准。符合规定的长期护理服务费用，按未', 'https://www.gov.cn/zhengce/zhengceku/202603/content_7063915…：保障对象为「按规定参保缴费且失能状态长期持续（一般为6个月以上），经申请通过评估认定的失能人员」，「制度起步阶段保障重度失能人员」；「待遇享受不设起付标准。符合规定的长期护理服务费用，按未就业城乡居民参保政策参保的，基金支付比例为50%左右；按单位职工参保政策参保的，基金支付比例为70%左右，退休人员享受单位职工参保待遇」；「参保人员基金年度最高支付限额不超过统筹地区上年度城乡居民人均可支配收入的50%」；「待遇享受固定等待期原则上按照6个月设置」；另见中共中央办公厅、国务院办公厅《关于加快建立长期护理保险制度的意见》.', 'guideline', '2026-10-08', 'active', '国家医保局等八部门 (2026). 关于印发《加快建立长期护理保险制度实施方案》的通知. https://www.gov.cn/zhengce/zhengceku/202603/content_7063915…：保障对象为「按规定参保缴费且失能状态长期持续（一般为6个月以上），经申请通过评估认定的失能人员」，「制度起步阶段保障重度失能人员」；「待遇享受不设起付标准。符合规定的长期护理服务费用，按未就业城乡居民参保政策参保的，基金支付比例为50%左右；按单位职工参保政策参保的，基金支付比例为70%左右，退休人员享受单位职工参保待遇」；「参保人员基金年度最高支付限额不超过统筹地区上年度城乡居民人均可支配收入的50%」；「待遇享受固定等待期原则上按照6个月设置」；另见中共中央办公厅、国务院办公厅《关于加快建立长期护理保险制度的意见》. https://www.gov.cn/gongbao/2026/issue_12666/202604/content_…') ON CONFLICT (id) DO NOTHING;
INSERT INTO sources (id, organization, title, url, source_type, retrieved_at, status, citation) VALUES ('src_archive_s17-8', 'Porter SB, Pla R, Chow JH, et al.', 'Porter SB, Pla R, Chow JH, et al. (2022). Preoperative Pressure Ulcers, Mortality, and Complications in Older Hip Fracture Surgery Patients. JAAOS Global Research &amp; Reviews, 6(11). https://doi.org', 'https://doi.org/10.5435/JAAOSGlobal-D-22-00117；Ottaviani', 'guideline', '2026-10-08', 'active', 'Porter SB, Pla R, Chow JH, et al. (2022). Preoperative Pressure Ulcers, Mortality, and Complications in Older Hip Fracture Surgery Patients. JAAOS Global Research &amp; Reviews, 6(11). https://doi.org/10.5435/JAAOSGlobal-D-22-00117；Ottaviani S, Rondanina E, Longo E, 等 (2026). Impact of pressure ulcers and frailty on long-term mortality: a prospective cohort study of hospitalized older adults. European Geriatric Medicine, 17(2), 665-672. https://doi.org/10.1007/s41999-025-01331-8；Shi C, Dumville JC, Cullum N (2018). Support surfaces for pressure ulcer prevention: A network meta-analysis. PLoS ONE, 13(2), e0192707. https://doi.org/10.1371/journal.pone.0192707；Latimer SL, Chaboyer WP, Probst S, 等 (2026). Repositioning for pressure injury prevention in adults. Cochrane Database of Systematic Reviews, 6, CD009958. https://doi.org/10.1002/14651858.CD009958.pub4') ON CONFLICT (id) DO NOTHING;
