INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-1', 'concept_archive_s1-1', 'recommendation', '美国交通安全主管部门（NHTSA）估计，系安全带能让轿车前排乘员受致命伤的风险下降 45%。轻型卡车前排下降 60%。2022 年美国死在乘用车（载人的小汽车）里的人当中，能查到系没系带的，有 50% 没系。世界卫生组织（WHO）的口径是，安全带让车内人员的死亡风险最多降低 50%。WHO 估计中国 2021 年死于道路交通事故的有 248,099 人，相当于每 10 万人里死 17.4 人', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-2', 'concept_archive_s1-2', 'recommendation', 'Cochrane 把多项研究合起来一起算。摩托车骑行者戴头盔，死亡风险下降 42%。原值 OR 0.58，可信范围 95% CI 0.50 到 0.68。头部损伤下降 69%（OR 0.31，95% CI 0.25 到 0.38）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-3', 'concept_archive_s1-3', 'recommendation', '美国北卡罗来纳州研究了一批住宅火灾，回头比对出事和没出事的家庭。家里有一个能正常工作的烟雾报警器，死亡风险下降约六成。原值 OR 0.39，可信范围 95% CI 0.18 到 0.83。美国 2018 到 2020 年，有人住的住宅里发生的致死火灾，24% 家里没有烟雾报警器，41% 起火时人在睡觉。中国 2018 年报告一氧化碳中毒死亡 11,523 例。这些死亡里，12 月有 72.59%、1 月有 67.42%、2 月有 66.48% 发生在家中', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-4', 'concept_archive_s1-4', 'recommendation', '条例把「及时更换国家明令淘汰或者使用年限已届满的燃气燃烧器具、连接管」写成了用户的义务：灶具和软管到了年限或者被国家淘汰了，你就要换。条例还把「擅自安装、改装、拆除户内燃气设施和燃气计量装置」列为禁止行为，自己动手改管道、拆燃气表都在里面。条例同时明确，燃气经营者不得要求用户购买它指定的产品，也不得要求用户接受它提供的服务', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-5', 'concept_archive_s1-5', 'recommendation', '中国疾控中心 2025 年调查了 828 起蘑菇中毒事件，涉及 2165 人，死亡 13 人。病死率 0.6%，指中毒的人里有 0.6% 死亡。2019 到 2024 年每年 276 到 676 起，病死率在 0.87% 到 2.86% 之间。光 2025 年就鉴定出 138 种有毒蘑菇，其中 34 种是国内第一次记录到会引起中毒', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-6', 'concept_archive_s1-6', 'recommendation', '应急管理部的规章明文禁止：「禁止在高层民用建筑公共门厅、疏散走道、楼梯间、安全出口停放电动自行车或者为电动自行车充电」。楼门厅、走道、楼梯间、安全出口这几处，既不能停车也不能充电。拒不改正的，不做生意的单位和个人罚 500 至 1000 元，做生意的罚 2000 至 10000 元', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-7', 'concept_archive_s1-7', 'recommendation', '把 123 项试验、61 万余人合起来一起算。收缩压每降 10 mmHg，主要心血管事件低约两成。原值 RR 0.80，可信范围 95% CI 0.77 到 0.83。收缩压就是血压两个数里高的那个。卒中（中风）低约 27%（RR 0.73）。心力衰竭低约 28%（RR 0.72）。总死亡率下降 13%（RR 0.87，95% CI 0.84 到 0.91）。中国给 35 到 75 岁的 170 万人做过筛查：44.7% 有高血压。这些人里，知道自己有的占 44.7%，在治疗的占 30.1%，控制住的只有 7.2%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-8', 'concept_archive_s1-8', 'recommendation', '美国预防服务工作组是美国官方给筛查建议的机构。它现在的建议是：对 35 到 70 岁、超重或肥胖的成年人筛查糖尿病前期和 2 型糖尿病，哪怕一点症状都没有。超重指体重指数 ≥25，肥胖指 ≥30。对亚裔美国人，它建议把界线降到体重指数 ≥23，因为同样的体重指数下，亚裔的糖尿病风险更高。中国的行业标准是：体重指数 24.0 到 28.0 之间算超重，≥28.0 算肥胖。这条建议的推荐等级是 B。它还写明：「对血糖正常的成年人，每 3 年筛查一次是合理的做法」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-9', 'concept_archive_s1-9', 'recommendation', '世界卫生组织（WHO）的说法：平均车速每升高 1%，出人命的事故风险升高 4%。酒驾的风险，从很低的血液酒精浓度起就开始上升', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-10', 'concept_archive_s1-10', 'recommendation', '美国交通安全主管部门（NHTSA）估计，用安全座椅能让轿车里 1 岁以下婴儿受致命伤的风险下降 71%。1 到 4 岁的幼儿下降 54%。世界卫生组织（WHO）的口径是婴儿死亡下降 71%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-11', 'concept_archive_s1-11', 'recommendation', '纽约市从 1972 年起办了一个叫「孩子不会飞」的项目，在高风险城区免费发窗户护栏，还上门讲解。布朗克斯区上报的坠落数，1973 到 1975 年下降 50%。此后纽约市修改卫生法典，强制房东为住有 10 岁及以下儿童的公寓安装窗户护栏', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-12', 'concept_archive_s1-12', 'recommendation', '用美国海岸警卫队的数据做的研究，把条件相近的人配成对来比。坐休闲船只落水的人，穿着救生衣的溺亡风险低约一半。原值是校正后 RR 0.51，可信范围 95% CI 0.35 到 0.74。中国 20 岁以下的溺水死亡率，从 2013 年的每 10 万人 6.60 人降到 2021 年的每 10 万人 3.28 人。农村约为城市的 2 倍。溺水仍然是 1 到 14 岁儿童的头号死因。2021 年 0 到 19 岁的伤害死亡里，溺水占 31.1%，道路交通占 27.9%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-13', 'concept_archive_s1-13', 'recommendation', 'Cochrane 把 108 项试验、23,407 人合起来一起算。运动让老年人跌倒的次数下降 23%。原值是跌倒率之比 RaR 0.77，可信范围 95% CI 0.71 到 0.83。摔过的人数下降 15%（RR 0.85）。请人到家里做安全评估和改造，跌倒率下降约两成（RR 0.81，95% CI 0.68 到 0.97）。练太极，跌倒风险低约 29%（RR 0.71）。在中国，跌倒是 65 岁以上老人因伤害死亡的头号原因。2018 年监测到的老年人跌倒，55.97% 发生在家中', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-14', 'concept_archive_s1-14', 'recommendation', '启东那项试验按群体随机分组，不是按个人分组，跟踪了 30 年。新生儿接种乙肝疫苗，原发性肝癌下降 84%。可信范围是 95% CI 23% 到 97%。乙肝表面抗原 HBsAg 阳性率下降 72%（95% CI 68% 到 75%），这个阳性率就是查出身上带着病毒的人所占的比例。中国全人群的 HBsAg 阳性比例，1992 到 2014 年下降 52%，5 岁以下下降 97%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-15', 'concept_archive_s1-15', 'recommendation', '美国的破伤风病例里，大约每 10 例死 1 例。深的伤口、被泥土污染的伤口，风险更高。中国 2024 年的诊疗规范把伤口分成两档。6 小时内处理、没沾泥土粪便和动物口水的浅伤口，算低风险。超过 6 小时才处理、沾了这些东西，或者是扎伤、撕脱伤、挤压伤、烧烫伤、冻伤、伤口里留着异物的，算高风险。打过 3 针以上、最后一针不到 5 年的，什么都不用打。5 到 10 年的，高风险伤口加强 1 针。满 10 年的，不管哪档都加强 1 针。没打全 3 针或者记不清的，要把疫苗补全，高风险伤口还要同时打被动免疫制剂（免疫球蛋白或抗毒素这类直接给抗体的针）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-16', 'concept_archive_s1-16', 'recommendation', '瑞典跟踪了 167 万名女性做统计：打过疫苗的人，浸润性宫颈癌的发病率比没打的低。17 岁以前接种的低约 88%（IRR 0.12，95% CI 0.00 到 0.34，括号里是原值和它的可信范围）。17 到 30 岁接种的低约 53%（IRR 0.47，95% CI 0.27 到 0.75）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-17', 'concept_archive_s1-17', 'recommendation', '美国预防服务工作组是美国官方给筛查建议的机构。它现在的建议是：「建议 40 至 74 岁女性每两年做一次筛查性乳腺 X 线摄影」。乳腺 X 线摄影就是平时说的钼靶。这条建议的推荐等级是 B。对 75 岁及以上的女性，以及给致密型乳腺补做超声、磁共振，它都判定为「现有证据不足」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-18', 'concept_archive_s1-18', 'recommendation', '印度农村那项试验按群体随机分组，不是按个人分组。对象是 30 到 59 岁的女性。只做一次 HPV 检测筛查，死于宫颈癌的风险就低约 48%。原值 HR 0.52，可信范围 95% CI 0.33 到 0.83。查出晚期宫颈癌的风险低约 53%（HR 0.47，95% CI 0.32 到 0.69）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-19', 'concept_archive_s1-19', 'recommendation', 'Cochrane 把多项研究合起来一起算。做粪便隐血筛查的人，死于结直肠癌的风险低约 16%。原值 RR 0.84，可信范围 95% CI 0.78 到 0.90。至少参加过一轮的人低约 25%（RR 0.75）。再看 NordICC 那项随机试验。被邀请去做肠镜的人，10 年里结直肠癌的发病从 1.20% 降到 0.98%。原值 RR 0.82，可信范围 95% CI 0.70 到 0.93', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-20', 'concept_archive_s1-20', 'recommendation', '一项试验在心肌梗死之后做，2571 人随机分组。医生和病人都不知道打的是哪一针。打流感疫苗的人，12 个月里的总死亡率是 2.9%。打安慰剂的是 4.9%。原值 HR 0.59，可信范围 95% CI 0.39 到 0.89。安慰剂就是不含有效成分的对照针。心血管死亡的 HR 是 0.59。另一项研究把多项研究合起来一起算。打流感疫苗的人主要心血管事件为 3.6%，对照为 5.4%。原值 RR 0.66，可信范围 95% CI 0.53 到 0.83。心血管死亡 RR 0.74（95% CI 0.42 到 1.30，这点差别还在误差范围内，算不上有统计学意义）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-21', 'concept_archive_s1-21', 'recommendation', '一项三期试验跨 18 个国家，有 1.54 万人。试验把人随机分成两组，一组打疫苗，一组打对照针，平均跟踪 3.2 年。结果疫苗组 6 例、安慰剂组 210 例发生带状疱疹。换算成每千人年是 0.3 对 9.1，每千人年的意思是 1000 个人观察一年里出现的例数。原文写「疫苗对带状疱疹的总体效力为 97.2%（95% CI 93.7–99.0，P&lt;0.001）」。各年龄组的效力在 96.6% 到 97.9% 之间', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-22', 'concept_archive_s1-22', 'recommendation', '荷兰把 8.45 万名 65 岁以上老人随机分成两组来比。用的是 13 价肺炎球菌结合疫苗。它对疫苗覆盖型肺炎的效力是 45.6%。可信范围是 95.2% CI 21.8–62.5。疫苗覆盖型就是这支疫苗管得住的那几个菌型。对侵袭性肺炎球菌病的效力是 75.0%（95% CI 41.4–90.8），这是最凶险的那一类感染。对全部原因加在一起的肺炎，它没有效果', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-23', 'concept_archive_s1-23', 'recommendation', '山东临朐那项随机分组的试验跟踪了 22 年。做过幽门螺杆菌根除治疗的人，得胃癌的风险低约一半。原值 OR 0.48，可信范围 95% CI 0.32 到 0.71。死于胃癌的风险低约 38%（HR 0.62，95% CI 0.39 到 0.99）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-24', 'concept_archive_s1-24', 'recommendation', '美国 NLST 随机试验收了 53,454 人，都是 55 到 74 岁、吸烟史 30 包年以上、戒烟不超过 15 年的人。包年是算烟量的单位，每天一包抽一年算一包年。结果是这样。做低剂量 CT 的人比只拍胸片的人，肺癌死亡相对下降 20.0%。可信范围 95% CI 6.8 到 26.7。总死亡率相对下降 6.7%，可信范围 95% CI 1.2 到 13.6', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-25', 'concept_archive_s1-25', 'recommendation', '一篇把近 10 年的研究系统梳理了一遍的综述：限制人拿到致死手段，这方面的证据一直在增强。管控镇痛药以后，和镇痛药有关的自杀下降 43%。常有人跳楼的地点加了防护之后，下降 86%（79% 到 91%，括号里是这个数的可信范围）。学校里开展的认知类项目，让自杀未遂低约 55%（OR 0.45，95% CI 0.24 到 0.85）。治抑郁的药物和心理治疗，是预防自杀的重要一环。中国从 2025 年 5 月 1 日起，全国拨 12356 都能接通心理援助热线，每天开通不少于 18 小时', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-26', 'concept_archive_s1-26', 'recommendation', '应急管理部的《全国基础版家庭应急物资储备建议清单》一共 11 样。其中「灭火器和灭火毯」用于「初起火灾的扑救」，清单还写明「灭火毯可披覆在身上逃生」。「呼吸面罩」指的是「消防过滤式自救呼吸器，用于火灾逃生使用」。「外用药品」是「止血粉、止血贴、纱布绷带等，用于处理伤口」。Cochrane 把 98 项研究、2,605,044 人合起来一起算。家庭安全干预让伤害发生率降到 IRR 0.89。可信范围是 95% CI 0.78 到 1.01。其中上门开展的干预，伤害发生率低约 25%（IRR 0.75，95% CI 0.62 到 0.91）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-27', 'concept_archive_s1-27', 'recommendation', '英国拿社区全科门诊（初级医疗）的电子病历做了一项研究，4915 例膀胱癌对 21718 例对照。出现肉眼血尿的人里，最后真查出膀胱癌的比例是这样。60 岁以上是 2.8%，可信范围 95% CI 2.5 到 3.1。40 到 59 岁是 1.2%，可信范围 0.6 到 2.3。这个比例的学名叫阳性预测值。只有在显微镜下才看得见的血尿，同样有意义。比值比 20，可信范围 95% CI 12 到 33。60 岁以上这个比例为 1.6%，可信范围 1.2 到 2.1', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-27"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-28', 'concept_archive_s1-28', 'recommendation', '一篇荟萃分析把 14 项跟踪研究合起来算，共 92,757 名男性，平均跟踪 6.1 年。和没有勃起功能障碍的人相比，有这个问题的人后来的风险是这样。总的心血管事件高约 44%（RR 1.44，95% CI 1.27 到 1.63，这是可信范围）。心梗高约 62%（RR 1.62，1.34 到 1.96）。脑血管事件高约 39%（RR 1.39，1.23 到 1.57）。全因死亡高约 25%（RR 1.25，1.12 到 1.39）。心血管死亡那一项没有拉开差距（RR 1.19，0.97 到 1.46）。年龄越轻，倍数越高。本来心血管风险属于中等的那批人，倍数比高风险和低风险的人都高。用问卷判定的研究，算出来的倍数是 1.61（1.38 到 1.86）。只问一句话的研究是 1.27（1.18 到 1.37）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-28"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-29', 'concept_archive_s1-29', 'recommendation', '一篇荟萃分析把 6 项随机对照试验、740 名男性合起来算。干预是改生活方式，或者用药控制心血管危险因素，随访至少 6 周。结果：勃起功能问卷（IIEF-5）的评分平均提高 2.66 分（95% CI 1.86 到 3.47，这是可信范围）。把其中用他汀的 2 项试验（143 人）去掉，剩下 4 项纯靠改生活方式的（597 人）仍然提高 2.40 分（1.19 到 3.61）。IIEF-5 是一份 5 个问题的问卷，总分 5 到 25 分。原文按得分分成五档，22 到 25 分算没有障碍，5 到 7 分算重度', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-29"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-30', 'concept_archive_s1-30', 'recommendation', '一项研究把 25 项研究、10676 对异性伴侣合起来一起算。这些伴侣都是一方感染 HIV、一方没感染，学名叫血清不一致。和从来不用的人相比，坚持每次都用安全套的人，HIV 传播风险低约 71%。原值 RR 0.29，可信范围 95% CI 0.20 至 0.43。和用得断断续续的人相比，低约 77%（RR 0.23，95% CI 0.13 至 0.40）。作者的结论是，安全套虽然不完美，但「坚持使用可使 HIV 传播降低 70% 以上」。同一层保护还覆盖梅毒、淋病、衣原体等其他性传播感染', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-30"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-31', 'concept_archive_s1-31', 'recommendation', '《艾滋病防治条例》第二十三条写明。县级以上地方人民政府卫生主管部门会指定一些医疗卫生机构。这些机构「应当为自愿接受艾滋病咨询、检测的人员免费提供咨询和初筛检测」。查得早有实际用处：现在的抗病毒治疗能把病毒压到检测不到。世界卫生组织的口径是「接受抗病毒治疗且病毒载量检测不到的感染者不会把 HIV 传染给性伴侣」。PARTNER 研究跟踪了 782 对同性伴侣，每对都是一方感染、一方没感染，学名叫血清不一致。合计 1593 对年（每对跟踪年数相加）。期间共 76088 次无套性行为，出现 15 例新感染。比对病毒基因做系统发育分析之后，这 15 例全部不来自伴侣，伴侣间传播为零。《艾滋病防治条例》第三十九条规定：「未经本人或者其监护人同意，任何单位或者个人不得公开艾滋病病毒感染者、艾滋病病人及其家属的姓名、住址、工作单位、肖像、病史资料以及其他可能推断出其具体身份的信息。」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-31"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-32', 'concept_archive_s1-32', 'recommendation', '82 名自杀未遂者在入院 3 天内接受访谈：47.6%（39 人）说，从这一次第一次冒出自杀念头到真的动手，不超过 10 分钟。这个过程拖得长一些的人，自杀意图评分明显更高。冲动性量表的得分和过程长短没有关系。76.8%（63 人）说，在这段时间里和伴侣、家人或者朋友有过某种接触。作者的结论是：能干预的时间窗通常很短，专业人员在这个阶段能介入的余地有限，所以要把识别信号和干预办法普及到普通人。另有一篇系统综述汇总了 90 项随访研究。因自伤就诊的人，1 年后再次自伤但没死的比例取中间值为 16%。1 年后死于自杀的为 2%。随访 9 年以上的，约 7% 死于自杀', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-32"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-33', 'concept_archive_s1-33', 'recommendation', '一篇百草枯中毒的系统综述：病死率极高，原因是它本身毒性强，又缺乏有效治疗。它被逆着浓度差主动搬进肺组织，学名叫逆浓度梯度主动摄取，结果是肺炎和肺纤维化，同时还造成肾损伤和肝损伤。综述写明：不应进行洗胃。血液透析和血液灌流不大可能改变临床病程。激素与免疫抑制剂的疗效证据很弱。综述还写了一句：「所有中心的病死率都很高，尽管治疗差异很大」。孟加拉 10 家三级医院 2013 至 2024 年收了 1420 例，其中可分析的 257 例：病死率 43.2%。常见表现是急性肾衰引起的下肢肿胀 71.2%、呕吐 65.8%、腹痛 58.0%。急性一氧化碳中毒的试验是双盲随机分组，两组各 76 人。医生和病人都不知道进的是哪一组。六周时留下认知后遗症的，高压氧组 19/76（25.0%）。常压氧组 35/76（46.1%），P=0.007。把其他因素校正之后 OR 0.45（95% CI 0.22 至 0.92，括号里是这个数的可信范围）。另一项研究连续观察了 73 例：30% 有认知后遗症，12% 出现脑白质高信号。中国自 2014 年 7 月 1 日起撤销百草枯水剂的登记和生产许可，并停止生产。2016 年 7 月 1 日起，水剂在国内停止销售和使用。2020 年 9 月 26 日起，禁止可溶胶剂在境内销售、使用。文件写明，「致使服用百草枯自杀事件时有发生」是加强监管的直接原因', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-33"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-34', 'concept_archive_s1-34', 'recommendation', '新疆南部一家创伤 ICU（重症监护病房）做过统计。从 2020 年 4 月到 2024 年 7 月，这里共收了 289 例高处坠落。这批人平均年龄 40.3 岁。坠落高度中位数 3 米，26.6% 从 5 米以上坠落，11.4% 从 10 米以上坠落。伤情评分 ISS 中位数 24，这套评分越高伤得越重，63.3% 的人 ISS 大于 20。47.1% 伤及 3 个以上部位，18.3% 伤及 4 个以上。36% 需要上呼吸机（机械通气），上机时长中位 103.5 小时。在 ICU 住院中位 8 天，最短 1 天，最长 132 天。院内或 30 天死亡率 5.5%（16/289）。德国一家创伤中心收了 84 例 ISS ≥ 25 的多发伤病人，多发伤就是同时伤到多个部位。随访期内重返工作的比例为 58%。年龄、ICU 治疗时长和自评健康是预测因素。2024 年全国医院次均住院费用（平均每次住院花的钱）9870.0 元，按当年价格比上年下降 4.3%。同年全国卫生总费用 90895.5 亿元，其中个人卫生支出 25007.5 亿元，占 27.5%', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-34"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-35', 'concept_archive_s1-35', 'recommendation', '美国把 96,217 名活体捐肾者和 20,024 名条件相当的健康未捐者作了比较。后者来自美国全国健康与营养调查（NHANES III）。再看捐后 15 年走到尿毒症的估计风险。捐献者为每万人 30.8 人，可信范围 95% CI 24.3–38.5。健康未捐者为每万人 3.9 人，可信范围 95% CI 0.8–8.9，P&lt;0.001。尿毒症的学名是终末期肾病 ESRD，到了这一步得靠透析或移植维持。估计一辈子走到 ESRD 的风险：捐献者每万人 90 人，未经筛查的一般人群每万人 326 人，健康未捐者每万人 14 人。挪威也做过一次比较。一边是 1901 名捐肾者，中位随访 15.1 年。另一边是 32,621 名符合捐献条件的对照，中位随访 24.9 年。捐肾者的全因死亡高约三成（HR 1.30，95% CI 1.11–1.52）。心血管死亡高约四成（HR 1.40，1.03–1.91）。走到 ESRD 高十倍上下（HR 11.38，4.37–29.6）。这批捐献者的 ESRD 总发生率为每百万人 302 例。美国另有 3698 名捐肾者，其中 11 人发生 ESRD，相当于每百万人观察一年里 180 例，同期一般人群是 268 例。这批人里有 255 人在捐后平均 12.2±9.2 年回来复查。其中 85.5% 的肾滤过功能 GFR ≥ 60 ml/min/1.73 m²。60 是临床正常下限。32.1% 有高血压。12.7% 有蛋白尿（尿里漏出蛋白）。印度金奈调查了 305 名卖肾者，平均在卖肾 6 年后接受调查：96% 为还债而卖，平均拿到 1070 美元。切肾后家庭平均收入下降三分之一（P&lt;0.001），生活在贫困线以下的人数增加，四分之三在调查时仍负债。86% 报告健康状况较切肾前变差，79% 不建议他人卖肾', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-35"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-36', 'concept_archive_s1-36', 'recommendation', '截至 2025 年，全国约有 17.8 万枚在用放射源和 35.5 万台（套）射线装置。放射源辐射事故的年发生率稳定在每万枚 1 起以下。分级是这样的。Ⅰ类、Ⅱ类放射源丢失、被盗、失控，就构成重大辐射事故。Ⅲ类为较大辐射事故。Ⅳ类、Ⅴ类丢失被盗，或者导致人员受到超过年剂量限值的照射，为一般辐射事故。官方案例：2020 年 6 月，宁夏钢铁集团炼铁厂在高炉管道改造项目上做 γ 射线探伤作业。一枚 Ⅱ 类铱-192 放射源使三名作业人员受到照射。陈某某左手急性放射性皮肤损伤 Ⅲ 度。刘某某左手拇指、食指 Ⅳ 度，中指、无名指、小指 Ⅲ 度。樊某某左手 Ⅰ-Ⅱ 度。三人受照剂量均严重超过国家标准规定的剂量限值，两家责任单位被吊销辐射安全许可证并罚款 7 万元。国际案例：1987 年巴西戈亚尼亚，废弃诊所的远距离治疗机被拆解，取出了里面 50.8 TBq 的铯-137 放射源，还弄破了装源的密封囊。约 112,000 人接受监测。其中 249 人受到体内或体外污染。这 249 人里，129 人为中度至重度污染，50 人需密切医学监护。最后 4 人死亡（全国 / 国际）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-36"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-37', 'concept_archive_s1-37', 'recommendation', '瑞典一项全国登记研究，找出 2005 到 2016 年在专科被诊断为赌博障碍的 2099 人。赌博障碍就是控制不住地赌、赌到影响生活。和同龄的瑞典人比，20 到 74 岁这些人的总死亡率是 1.8 倍，自杀死亡率是 15 倍（这两个数是标准化死亡比 SMR）。随访期间 67 人死亡，其中 21 人死于自杀。能预测自杀死亡的是抑郁。作者 2023 年发了更正：男性自杀是 12.1 倍，女性是 16.1 倍。中国从 2025 年 5 月 1 日起，全国拨 12356 能接通心理援助热线，每天开通不少于 18 小时（瑞典 / 全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-37"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-38', 'concept_archive_s1-38', 'recommendation', '这种药是恩曲他滨加替诺福韦的复方片。iPrEx 试验让 2499 名男男性行为者和跨性别女性每天吃药或者吃安慰剂。吃药组感染少了 44%（95% CI 15–63）。血里测得到药的人，保护效果强得多。英国的 PROUD 试验有 544 名男男性行为者。立刻吃药的一组比推迟一年的一组感染少 86%（90% CI 64–96，90% 可信范围）。法国的 IPERGAY 试验在性行为前后按需吃药，感染少 86%（95% CI 40–98）。世界卫生组织用的一篇荟萃分析把各项试验合起来。总体 RR 0.49（0.33–0.73，低约 51%）。吃药率超过七成的试验，RR 0.30（0.21–0.45，低约 70%）。吃药率不到四成的，RR 0.95，基本无效。国家药监局 2020 年 8 月批准这个药用于暴露前预防。成人和体重至少 35 公斤的青少年可以用（多国 / 中国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-38"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-39', 'concept_archive_s1-39', 'recommendation', '美国预防服务工作组 2025 年发的推荐是：65 岁及以上的女性做骨质疏松筛查（B 级推荐）。绝经后、不到 65 岁、但按风险评估骨折风险高的女性，也推荐筛查（B 级）。男性证据不足，没有表态。给这份推荐做的证据综述合并了 3 项随机试验、42009 名欧洲老年女性。筛查的做法是先评估骨折风险，风险高的再查骨密度，查出高风险就用药。筛查组髋部骨折低约 17%。原值 RR 0.83，可信范围 95% CI 0.73 到 0.93。折成绝对数，每 1000 人筛查少 5 例髋部骨折。其中英国 SCOOP 试验找了 12483 名 70 到 85 岁的女性，筛查组髋部骨折低约 28%（HR 0.72，95% CI 0.59 到 0.89），死亡率没有看出差别。中华医学会 2017 年版诊疗指南建议：女性 65 岁以上、男性 70 岁以上做骨密度检查。不到这个年龄、但有一个或多个骨质疏松危险因素的，也建议查。2017 到 2018 年的全国调查里，40 岁以上女性骨质疏松的患病率是 20.6%，男性是 5.0%（中国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-39"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-40', 'concept_archive_s1-40', 'recommendation', '脆性骨折，是受到轻微外伤或日常活动中就发生的骨折。中华医学会 2017 年版指南认定的用药对象有三类。一是脊柱或髋部发生过脆性骨折的人。二是骨密度 T 值在 -2.5 及以下的人，不管有没有骨折过。三是骨量偏低、又在手腕、上臂或骨盆有过脆性骨折，或者算出来骨折风险高的人。指南还写明「目前尚无充分证据表明单纯补钙可以替代其他抗骨质疏松药物治疗」。Cochrane 2025 年更新了阿仑膦酸钠的综述。在已有骨质疏松或骨折的绝经后女性里，用药组髋部骨折低约 51%。原值 RR 0.49，可信范围 95% CI 0.25 到 0.96。有症状的脊柱骨折低约 55%（RR 0.45，95% CI 0.28 到 0.73）。HORIZON 试验找了 2127 名髋部骨折做过手术的人，平均 74.5 岁。手术后 90 天内开始每年输一次唑来膦酸，跟踪的中位数是 1.9 年。新的骨折从 13.9% 降到 8.6%，少了约 35%。死亡从 13.3% 降到 9.6%，少了约 28%。指南写到，髋部骨折后一年内约 20% 的人死于各种并发症。2017 到 2018 年的全国调查里，确诊骨质疏松或骨折过的女性只有 1.4% 在用药，男性只有 0.3%（中国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s1-40"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-41', 'concept_archive_s1-41', 'recommendation', '中国气象局的科普说，冰层厚度达到 15 厘米，成年人可以上去滑冰。露天冰场的冰层也要达到 15 厘米才能开放。北京市水务局说，正规天然冰场要冰厚 15 厘米，之后一周气温保持在 -8℃ 到 1℃、没有大风，才能开放。野冰上常有钓鱼的人凿的冰洞，凿开后很难再冻结实。美国明尼苏达州自然资源部的指南只针对新结的透明冰：不到 4 英寸（约 10 厘米）别上，4 英寸可以步行和冰钓。积雪化了又冻上的白冰，结实程度只有透明冰的一半左右，厚度要按两倍算。同一片水面，冰可能这里一英尺厚，几英尺外只有一两英寸。流水上的冰通常危险，溪流、桥和涵洞附近尤其如此。岸边的冰也可能比远处薄。美国国家气象局给的步行、冰钓、滑冰门槛也是 4 英寸。加拿大职业健康与安全中心转述加拿大红十字会的建议：几个人一起滑冰、步行要 15 厘米，人多的滑冰聚会要 20 厘米。这些都是安全指南，没有研究算过照着做能少死多少人（全国 / 美国、加拿大）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-41"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s1-42', 'concept_archive_s1-42', 'recommendation', '加拿大职业健康与安全中心和澳大利亚昆士兰州的安全机构列的做法如下。开机前检查护罩和片子，有裂纹、缺口、变形的不用。片子上标的最高转速，不能低于机器上标的转速。片子的直径和中间的孔要和机器配套。换片前断开电源。要磨要切的东西先固定住。戴防护眼镜或护目镜，外面再加面屏。双手握住两个手柄，脚下站稳。切割片不能拿来打磨，那样片子更容易碎。片子完全停转之前不把机器放下。火花和碎屑朝向没人的地方，周围不放易燃的东西。昆士兰的通报说，切割片边缘的设计速度约为每秒 70 米。把 356 毫米的大片装到 230 毫米的机器上，边缘速度至少到每秒 120 米，片子容易碎。2016 年 2 月，当地一名工人用 230 毫米的角磨机时被碎片击中胸部，内伤死亡。国内有两份事故调查报告。2019 年哈尔滨一名工人把切割片换成带齿锯片，没装护罩就去切木板。锯片卷住裤子，割断大腿动脉，失血死亡。2024 年深圳福田一名工人用装着木工锯片、没装护罩和辅助手柄的角磨机切木门框。机器反弹，割破颈动脉死亡。报告引用的国家标准写着「不要附装上锯链、木雕刀片或带齿锯片」。韩国 2011 到 2018 年的急诊伤害监测里，被高速旋转的切割工具弄伤的有 8697 人次，其中 4603 人次在用砂轮机这一类工具。他们伤在手上的占 46.4%，伤在头部的占 23.0%。和其他同类工具比，砂轮机伤成重伤的可能高约一倍（OR 2.07，95% CI 1.88–2.29）。四川绵阳一家医院两年收治 36 名角磨机伤眼的住院病人。手术后戴上眼镜的最好视力仍低于 0.05 的有 10 人。土耳其一家医院一年的 742 例手和前臂急性外伤里，角磨机造成 82 例。除 8 例外都不是上班时伤的，44% 是退休的人。日本一家创伤中心 2017 到 2018 年的 15 名角磨机伤者里，9 人是装上锯片切木头这类错用。其中 2 人整根手指断掉，1 人断了一截（加拿大、澳大利亚 / 中国 / 韩国、土耳其、日本）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s1-42"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-1', 'concept_archive_s2-1', 'recommendation', '美国一项跟踪一群人的研究（只记录、不分组）发现：现在还吸烟的人，比从不吸烟的人预期寿命短 10 年以上。40 岁前戒掉，可以消除继续吸烟所带来死亡风险的约 90%。25–34 岁戒烟约多活 10 年，35–44 岁约多活 9 年，45–54 岁约多活 6 年（原文以寿命年报告）。中国的同类研究：2010 年代，城市男性吸烟者的死亡风险是不吸烟者的 1.65 倍（RR 1.65），农村男性是 1.22 倍。主动戒烟满 10 年后，吸烟带来的这部分风险接近消失。骨折之后也一样。19 项只记录、不分组的研究合起来算，吸烟的人骨折不愈合（骨头长不上）的几率约是不吸烟者的 2.3 倍（OR 2.32，95% CI 1.76–3.06，已扣除其他因素）。小腿胫骨骨折和开放性骨折里同样偏高。瑞典一项随机试验里，骨折急诊手术后参加 6 周戒烟项目的 50 人，20% 出现至少一种术后并发症。没参加的 55 人是 38%。提前约好的手术，可以在术前 4 到 8 周开始戒烟，每周有人辅导，配尼古丁替代品。这样做术后并发症低约 58%（RR 0.42，95% CI 0.27–0.65，2 项试验、210 人）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-2', 'concept_archive_s2-2', 'recommendation', '2004 年全球有 603,000 人死于二手烟，约占全球死亡的 1.0%，其中 28% 是儿童。把 57 项研究合起来算：吸到二手烟的人得高血压的机会，约为没吸到的人的 1.28 倍（比值比）。心脏病是 1.39 倍，心肌梗死是 1.50 倍，卒中是 1.36 倍。在家里吸到二手烟的风险，高于在家外吸到的', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-3', 'concept_archive_s2-3', 'recommendation', '41 项随机试验、17395 人合起来算，伐尼克兰组的戒烟成功率是安慰剂组的 2.32 倍（RR 2.32，95% CI 2.15–2.51，这是可信范围；高确定性证据）。伐尼克兰也高于安非他酮（RR 1.36，高约 36%）和单用一种尼古丁替代品（RR 1.25，高约 25%）。尼古丁替代品和不用药比：133 项试验、64640 人，成功率高约 55%（RR 1.55，95% CI 1.49–1.61）。贴片再加一种见效快的剂型（咀嚼胶、含片），比只用一种高约 27%（RR 1.27，95% CI 1.17–1.37，16 项试验、12169 人，高确定性证据）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-4', 'concept_archive_s2-4', 'recommendation', '英国 697 名吸烟者随机分成两组。一组在戒烟日当天一次停掉，一组在戒烟日前两周先把烟量减掉 75%。两组都有护士的行为支持，戒烟日前后都用尼古丁替代品。第 4 周时，一次停那组 49.0%（95% CI 43.8–54.2，这是可信范围）没复吸，慢慢减那组 39.2%（34.0–44.4），相对风险比 0.80（0.66–0.93）。到第 6 个月，一次停那组 22.0%（18.0–26.6），慢慢减那组 15.5%（12.0–19.7），相对风险比 0.71（0.46–0.91）。原本就偏好慢慢减的人，第 4 周的成功率也低于偏好一次停的人（38.3% 对 52.2%）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-5', 'concept_archive_s2-5', 'recommendation', '52 项试验、19488 人合起来算，药物加行为支持组的戒烟成功率是常规照护或简短建议组的 1.83 倍（RR 1.83，95% CI 1.68–1.98，这是可信范围；高质量证据）。在医疗机构招募的那 43 项试验里是 1.97 倍（1.79–2.18）。电话咨询单独算：在自己打过戒烟热线的人里，接受多次主动回访的比只拿到材料或只谈一次的高约 38%（RR 1.38，95% CI 1.19–1.61，14 项试验、32484 人）；没主动打过热线、由研究方提供电话咨询的，高约 25%（RR 1.25，95% CI 1.15–1.35，65 项试验、41233 人）。两项都是中等确定性证据。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-6', 'concept_archive_s2-6', 'recommendation', '一份持续更新的综述纳入 80 项随机试验、29861 人。含尼古丁的电子烟和尼古丁替代疗法比，戒烟成功率高约 61%（RR 1.61，95% CI 1.23–2.12，这是可信范围；高确定性证据，11 项试验、4114 人）。换成绝对数，大约是每 100 人里多 4 人戒成（多 1 到 7 人）。严重不良事件的发生比例两组大致相当（风险差 0.01，95% CI −0.01 到 0.02，中等确定性证据）。和只有行为支持或没有支持比，高约 75%（RR 1.75，95% CI 1.39–2.20，低确定性证据）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-7', 'concept_archive_s2-7', 'recommendation', '美国有两项跟踪一群人的大型研究。这两项只记录、不分组，约 11.8 万人、3.6 万例死亡。每天喝 2 份以上的人，死亡风险比每月不到 1 份的人高约 21%（HR 1.21）。每天喝 1–2 份的，高约 14%（HR 1.14）。欧洲 EPIC 跟踪研究只记录、不分组，有 45 万人、10 个国家。每天喝 2 杯以上的人和每月不到 1 杯的人比：含糖软饮这项高约 8%（HR 1.08，95% CI 1.01–1.16）。人工甜味剂饮料（无糖版）高约 26%（HR 1.26，1.16–1.35）。所有软饮合起来算，高约 17%（HR 1.17，1.11–1.22）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-8', 'concept_archive_s2-8', 'recommendation', '把 17 项亚洲研究、38.8 万人合起来算。嚼槟榔的人死亡风险比不嚼的人高约 21%（相对风险 1.21，P=0.02）。死亡这一项算的是其中的 17.96 万人。得糖尿病的风险高约 47%（1.47）。得代谢综合征的风险高约 51%（1.51）。槟榔本身也是口腔癌和食管癌的已知危险因素', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-9', 'concept_archive_s2-9', 'recommendation', '一项把人随机分成两组的试验，在中国农村做的，20995 人，都是得过卒中的人或者 60 岁以上的高血压病人，跟踪了 4.74 年。结果：用低钠盐的那组比用普通盐的那组，死亡风险低约 12%（RR 0.88）。卒中低约 14%（RR 0.86）。主要心血管事件低约 13%（RR 0.87）。血钾过高的事件，两组没看出统计上的差别。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-10', 'concept_archive_s2-10', 'recommendation', '日本有一项研究，9676 人，跟踪 6 年。用牙缝清洁工具的人，死亡风险低约 11%（风险比 0.89）。用舌苔清洁工具的人，低约 23%（0.77）。另外把多项研究合起来算，对象是住在社区的老人。一颗牙都没有的人，死亡的机会约为 1.87 倍（比值比，95% CI 1.35–2.59，这是可信范围）。牙齿少于 20 颗的，约为 2.04 倍（1.67–2.49）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-11', 'concept_archive_s2-11', 'recommendation', '把 15 项跟踪一群人的研究合起来算，只记录、不分组。这 15 项共 47471 人、3013 例死亡。按每天步数把人分成四档，最低那档中位是 3553 步/天。另外三档的中位是 5801、7842、10901 步/天。这三档的死亡风险比最低档分别低约 40%、45%、53%（HR 0.60、0.55、0.47）。60 岁以上的人走到 6000–8000 步以后，再多走收益就趋平了。60 岁以下的人是在 8000–10000 步以后趋平。另有一项分析把多项研究合起来算：从约 3867 步/天开始有效。之后每多走 1000 步/天，死亡风险降约 15%。按运动时间算：把多项跟踪研究汇总到一起算（只记录、不分组），运动量达到指南下限 1–2 倍的人，死亡风险比不运动的人低约 31%（HR 0.69）。这个量是 7.5–15 MET·h/周，大约合快走 150–300 分钟/周。没达到下限的人也低约 20%（HR 0.80）。达到下限 3–5 倍的人低约 39%（HR 0.61），这是降幅的顶点。再往上加不会更低，但也没害处（10 倍以上是 HR 0.69）。另一项用加速度计测量的汇总研究：中高强度活动最多的那四分之一人，比最少的那四分之一死亡风险低约 48%（HR 0.52）。加速度计是戴在身上实测活动量的仪器。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-12', 'concept_archive_s2-12', 'recommendation', '把多项随机分组试验合起来算：收缩压每降 10 mmHg，死亡风险低约 13%（RR 0.87）。收缩压就是血压里的高压。主要心血管事件低约 20%（RR 0.80）。卒中低约 27%（RR 0.73）。心衰低约 28%（RR 0.72）。吃他汀让低密度脂蛋白胆固醇（LDL）往下降。LDL 每降 1.0 mmol/L，死亡风险低约 10%（RR 0.90）。同样这一降，主要血管事件低约 22%（RR 0.78）。另外把多项跟踪研究合起来算，只记录、不分组。按医嘱吃到 ≥80% 的人，死亡风险比经常漏吃的人低。他汀这一项低约 45%（RR 0.55）。降压药这一项低约 29%（RR 0.71）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-13', 'concept_archive_s2-13', 'recommendation', '把 16 项跟踪研究合起来算，只记录、不分组，138 万人、11.3 万例死亡。睡得短的人死亡风险高约 12%（RR 1.12）。睡得长的人高约 30%（RR 1.30）。另一项汇总按睡眠时长分档：7 小时那档风险最低。少于 7 小时的，每少 1 小时高约 6%（RR 1.06）。多于 7 小时的，每多 1 小时高约 13%（RR 1.13）。英国生物银行有约 6.1 万人的腕表记录，只记录、不分组。把人按作息规律程度分成五档。较规律的那四档比最不规律的那档，死亡风险低 20%–48%。作息规不规律，比睡多久更能预测死亡。另有一项英国生物银行的研究，用腕表测了 51,562 人的睡眠时刻，其间 3,853 人新发心血管病。社会时差指工作日和周末的睡眠中点差多少。社会时差达到 2 小时以上的人，心血管病风险高约 30%（HR 1.30，95% CI 1.11–1.54）。这个关联在睡眠时长正常的人里同样存在。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-14', 'concept_archive_s2-14', 'recommendation', '英国一项 8.03 万人的跟踪研究，比的是做某项运动的人和不做这项运动的人。打球拍类运动的人，死亡风险低约 47%（风险比 0.53，95% CI 0.40–0.69，可信范围）。心血管死亡低约 56%（0.44，0.24–0.83）。球拍类指网球、羽毛球、乒乓球。游泳的人这两个数分别是 0.72 和 0.59，有氧操是 0.73 和 0.64，骑车是 0.85。跑步和足球没看出统计上的差别', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-15', 'concept_archive_s2-15', 'recommendation', '英国生物银行有一项研究，对象是 2.52 万名平时不专门锻炼的人。平均跟踪 6.9 年，其中 852 人去世。有的人每天有 3 次、每次 1–2 分钟的零碎剧烈活动。和完全没有的人比，他们的死亡风险和癌症死亡风险降低 38%–40%。心血管死亡风险降低 48%–49%。每天这类活动累计 4.4 分钟的人，死亡风险和癌症死亡风险降低 26%–30%。心血管死亡风险降低 32%–34%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-16', 'concept_archive_s2-16', 'recommendation', '把多项跟踪研究合起来算（只记录、不分组）：做力量训练的人比不做的人，死亡风险低 10%–17%。不是练得越多越好，每周约 30–60 分钟时降幅最大，约 10%–20%，再多练不会多出好处。力量和有氧都做的人，比两样都不做的人死亡风险更低。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-17', 'concept_archive_s2-17', 'recommendation', '美国有一项跟踪研究，只记录、不分组，用加速度计实测。把人按每天久坐总时长分成四份。久坐最多的那份人，死亡风险是最少那份的 2.63 倍（HR 2.63）。再按一次连着坐多久分成四份：连坐最久的那份人，是连坐最短那份的 1.96 倍（HR 1.96）。所以坐的总量和一次连坐多久，各自单独相关。另一项汇总把上百万人的研究合起来算，只记录、不分组。每天坐 8 小时以上、又几乎不运动的人，死亡风险是另一类人的 1.59 倍（HR 1.59）。另一类人是每天坐不到 4 小时、又最活跃的。每天约 60–75 分钟中等强度活动，可以抵消久坐多出来的风险。最活跃那组即使每天坐 8 小时以上，HR 也只有 1.04，没看出统计上的差别。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-18', 'concept_archive_s2-18', 'recommendation', '把多项跟踪研究合起来算（只记录、不分组）：加工肉吃得最多的那组，比吃得最少的那组死亡风险高约 23%（RR 1.23）。红肉合计高约 29%（RR 1.29）。没加工的红肉高约 10%（RR 1.10），但这一项没看出统计上的差别。另一项汇总是按每天吃的量算的。加工肉每天多吃 1 份，死亡风险高约 23%（RR 1.23）。红肉每天多吃 1 份，高约 10%（RR 1.10）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-19', 'concept_archive_s2-19', 'recommendation', '把 83 项往后跟踪的研究合起来算，只记录、不分组，60 万名在喝酒的人。死亡风险的最低点，在每周不超过 100 g 纯酒精。这个量大约是 5% 的啤酒 2.5 L，或者 40 度白酒 300 mL。40 岁时每周喝 100–200 g 的人，预期寿命少约 6 个月。每周喝 200–350 g 的少 1–2 年。超过 350 g 的少 4–5 年。以上三项原文以寿命年报告。全球疾病负担研究 GBD 2016 把各类健康损失合起来算，风险最低的饮酒量是 0 杯/周。还有一项汇总把研究设计上的偏差校正过了。每天喝 1.3–24 g 的人和一辈子不喝的人比，死亡风险低约 7%（RR 0.93）。但这一项没看出统计上的差别。每天喝 45–64 g 的高约 19%（RR 1.19）。每天 65 g 以上的高约 35%（RR 1.35）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-20', 'concept_archive_s2-20', 'recommendation', '一篇 2026 年的临床综述写明：长期大量饮酒的人在突然停酒或者大幅减量之后会出现戒断综合征，表现包括震颤、自主神经兴奋、焦虑、失眠、感知异常、癫痫发作和震颤谵妄，在普通内科诊疗中「常见且可能危及生命」。挪威的全国登记队列纳入 2009 到 2015 年诊断为酒精依赖、酒精戒断状态或震颤谵妄的 36287 人：震颤谵妄组的年死亡率 8.0%，戒断状态组 5.0%，酒精依赖组 3.6%。震颤谵妄组的标准化死亡比 9.8（95% CI 8.9–10.7，这是可信范围），意思是死亡风险约为同龄一般人群的 9.8 倍。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-21', 'concept_archive_s2-21', 'recommendation', '34 项随机试验、15197 人合起来算，接受简短干预的人在一年后比只接受最少干预或不干预的人每周少喝 20 克纯酒精（95% CI 少 12 到 28 克，这是可信范围；中等质量证据）。这些研究里受试者的基线饮酒量平均是每周 244 克。简短干预指的是不超过 5 次、总时长不到 60 分钟的建议或生活方式咨询；谈得更久并没有多出好处。药物方面：122 项随机试验、22803 人合起来算，阿坎酸每治疗 12 人（95% CI 8 到 26）可多让 1 人不再回到任何饮酒；口服纳曲酮每天 50 毫克，每治疗 12 人（8 到 26）可多让 1 人不再回到重度饮酒。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-22', 'concept_archive_s2-22', 'recommendation', '两项美国跟踪研究，11.9 万人，300 多万人年。人年就是人数乘以各自跟踪的年数。和不吃坚果的人比：每周吃不到 1 次的人死亡风险低约 7%（风险比 0.93，95% CI 0.90–0.96，这是可信范围）。每周吃 1 次的低约 11%（0.89，0.86–0.93）。每周 2–4 次的低约 13%（0.87，0.83–0.90）。每周 5–6 次的低约 15%（0.85，0.79–0.91）。每周 7 次以上的低约 20%（0.80，0.73–0.86）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-23', 'concept_archive_s2-23', 'recommendation', '把美国 6 项跟踪研究、近 3 万人合起来算。每周多吃两份加工肉，死亡风险高约 3%（风险比 1.03，95% CI 1.02–1.05，可信范围）。每周多吃两份没加工的红肉，也高约 3%（1.03，1.01–1.05）。同样的吃法换成禽肉，是 0.99（0.97–1.02）；换成鱼，是 0.99（0.97–1.01）。这两项都没看出统计上的差别', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-24', 'concept_archive_s2-24', 'recommendation', '把多项跟踪研究合起来算（只记录、不分组）：全谷物每天多吃 90 g，死亡风险低约 17%（RR 0.83）。90 g 大约是 3 份。这份好处一直持续到每天 210–225 g。另一项汇总里，每天多吃 1 份低约 8%（RR 0.92）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-25', 'concept_archive_s2-25', 'recommendation', '中国一项 10.09 万人的研究（China-PAR），其中一半人跟踪满了 7.3 年。有喝茶习惯的人，死亡风险低约 15%（风险比 0.85，95% CI 0.79–0.90，这是可信范围）。以 50 岁为起点算：有喝茶习惯的人，没得动脉粥样硬化性心血管病的年数多 1.41 年，预期寿命多 1.26 年', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-26', 'concept_archive_s2-26', 'recommendation', '一篇综述把 201 项汇总研究的结果又合到一起算，这些汇总底下的原始研究都只记录、不分组。结果：每天喝 3–4 杯咖啡的人和不喝的人比，死亡风险低 17%（相对风险 0.83，95% CI 0.79–0.88，这是可信范围）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-27', 'concept_archive_s2-27', 'recommendation', '把多项跟踪研究合起来算（只记录、不分组）：每天多吃 200 g 果蔬，死亡风险低约 10%（RR 0.90）。这份好处一直持续到每天 800 g。美国两项大型跟踪研究加上 26 项研究的汇总：每天吃够 5 份的人，比只吃 2 份的人死亡风险低约 13%（HR 0.87）。最好的搭配是 2 份水果加 3 份蔬菜，再多不再降。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-27"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-28', 'concept_archive_s2-28', 'recommendation', '一篇综述把多项汇总研究又合到一起算，这些汇总底下的原始研究都只记录、不分组。结果：超加工食品吃得多的人比吃得少的人，死亡风险高约 21%（RR 1.21），心血管病死亡高约 50%（RR 1.50）。这两项的证据分级分别是「高度提示」和「令人信服」。但按通行的证据打分法（GRADE）评，确定性是低或极低。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-28"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-29', 'concept_archive_s2-29', 'recommendation', '中国有一项慢性病往后跟踪的研究，只记录、不分组，27.1 万名没有心血管病的成人。做饭用煤柴这类固体燃料的人，死亡风险比用电或燃气的人高约 11%（HR 1.11）。取暖用固体燃料的人高约 14%（HR 1.14）。已经从固体燃料换成清洁燃料的人，和还在烧的人比，做饭这项低约 13%（HR 0.87）。取暖这项低约 33%（HR 0.67）。室外的 PM2.5 另有一笔账。把 104 项跟踪研究合起来算，长期吸到的浓度每高 10 µg/m³，自然原因死亡风险高约 8%（RR 1.08）。自然原因就是非意外的病死。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-29"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-30', 'concept_archive_s2-30', 'recommendation', '在伊朗北部的食管癌高发区，拿 300 名患者和 571 名没得病的人对比。下面都和喝温茶的人比。喝「热」茶的人，得食管鳞癌的机会约为 2.07 倍（比值比，95% CI 1.28–3.35，可信范围）。喝「很热」的约为 8.16 倍（3.93–16.9）。倒出后不到 2 分钟就喝的人，约为等 4 分钟以上再喝的人的 5.41 倍（2.63–11.1）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-30"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-31', 'concept_archive_s2-31', 'recommendation', '瑞典一项研究，2.95 万名女性，跟踪 20 年。和晒太阳最多的那组比，刻意回避晒太阳的人预期寿命少 0.6 到 2.1 年。作者写道「不吸烟但回避晒太阳的人，预期寿命与晒太阳最多组里的吸烟者相当」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-31"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-32', 'concept_archive_s2-32', 'recommendation', '把 239 项往后跟踪的研究的个人数据合起来算（只记录、不分组）。这份分析只留了三类人：从不吸烟的、入组时没有慢性病的、入组后又活过 5 年的。结果：死亡风险在 BMI 20–25 最低。BMI 25–27.5 高约 7%（HR 1.07）。27.5–30 高约 20%（HR 1.20）。30–35 高约 45%（HR 1.45）。35–40 高约 94%（HR 1.94）。40–60 是 2.76 倍（HR 2.76）。BMI 25 以上的人每高 5 kg/m²，东亚人群的风险高约 39%（HR 1.39）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-32"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-33', 'concept_archive_s2-33', 'recommendation', '意大利一项 2.28 万人的研究，其中一半人跟踪满了 8.2 年，共 1236 人去世。每周吃辣椒 4 次以上的人，死亡风险比很少吃的人低约 23%（风险比 0.77，95% CI 0.66–0.90，可信范围）。心血管死亡低约 34%（0.66，0.50–0.86）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-33"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-34', 'concept_archive_s2-34', 'recommendation', 'PURE 跟踪研究覆盖 21 个国家、13.6 万人，平均跟踪 9.1 年，共 6796 人去世。每天吃两份以上奶制品的人，死亡风险比不吃的人低约 17%（风险比 0.83，95% CI 0.72–0.96，可信范围），趋势 P=0.0052', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-34"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-35', 'concept_archive_s2-35', 'recommendation', '美国一项 52.1 万人的跟踪研究，共 12.9 万人去世。每天多吃半个全蛋，死亡风险高约 7%（风险比 1.07，95% CI 1.06–1.08，这是可信范围）。把这半个全蛋换成等量的蛋清、禽肉、鱼、奶制品或者坚果豆类，死亡风险会更低，心血管、癌症、呼吸系统这三项的死亡风险也都更低', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-35"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-36', 'concept_archive_s2-36', 'recommendation', '日本一项 3.0 万人的研究，跟踪 19 年，共 2097 例心血管事件。几乎每天泡澡的人，比每周泡不超过两次的人心血管事件风险低约 28%（风险比 0.72，95% CI 0.62–0.84，这是可信范围）。冠心病低约 35%（0.65，0.45–0.94）。脑卒中低约 26%（0.74，0.62–0.87）。脑出血低约 46%（0.54，0.40–0.73）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-36"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-37', 'concept_archive_s2-37', 'recommendation', '一篇伞形综述汇总了 16 篇荟萃分析、244 个健康结局。伞形综述就是把已有的汇总研究再汇总一遍。结论是：午睡少于 60 分钟的人，总死亡率和慢性病风险都没有升高，脑力改善也最明显（SMD 0.69，95% CI 0.37–1.00，这是可信范围）。20 到 30 分钟的短午睡对运动表现的改善最大（SMD 0.99，0.67–1.31）。午睡超过 60 分钟的人，冠心病风险高约 30%，糖尿病和肥胖风险高约 20%。另一项研究让 1338 名 56 岁以上的老人戴腕表实测午睡，不靠自己填问卷。跟踪最长 19 年，期间 926 人去世。午睡每多 1 小时，死亡风险高约 13%（HR 1.13，95% CI 1.04–1.23）。每天多睡一次，高约 7%（HR 1.07，1.02–1.13）。在上午睡的人，比在下午早些时候睡的人高约 30%（HR 1.30，1.03–1.64）。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-37"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-38', 'concept_archive_s2-38', 'recommendation', '英国生物银行 85,618 人，平均年龄 61.8 岁，戴腕表记录逐日睡眠，中位随访 8 年。研究先按每个人自己的睡眠需求算出「少睡的夜」，指比自己需要的少睡 2.5 小时以上。少睡那段之后的第一晚算「补觉夜」，这一晚比自己需要的多睡就算补上了。按这个分成五种模式。和作息规律的人相比，少睡又不补的全因死亡风险高约 15%（HR 1.15，95% CI 1.01–1.31，这是可信范围）。累计少睡超过 3.5 小时又不补的高约 42%（HR 1.42，1.24–1.63）。补上了的两组都没有显著关联，其中少睡后补是 HR 1.12（0.98–1.28）。本来就睡得短的人里，少睡不补高约 19%（1.19，1.01–1.40），严重少睡不补高约 38%（1.38，1.17–1.63）。这个结果在另一批 4,586 人的美国健康调查里也重复出来了。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-38"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-39', 'concept_archive_s2-39', 'recommendation', '把 23 项跟踪研究合起来算，只记录、不分组。上夜班的人心血管事件风险高约 13%（RR 1.13，95% CI 1.10–1.16，这是可信范围）。心血管死亡高约 27%（RR 1.27，1.18–1.36）。按年数看：每多上 5 年夜班，心血管病发生率再高约 7%（RR 1.07，1.04–1.09），心血管死亡再高约 5%（RR 1.05，1.03–1.06）。分病看，冠心病发生高约 22%（1.22，1.16–1.28），冠心病死亡高约 22%（1.22，1.10–1.36），缺血性心脏病死亡高约 39%（1.39，1.06–1.84），卒中死亡高约 49%（1.49，1.04–2.12）。卒中的发生率那一项不显著（1.06，0.95–1.18）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-39"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-40', 'concept_archive_s2-40', 'recommendation', '黄曲霉毒素是国际癌症研究机构定的 1 类致癌物（确定能让人得癌），主要是肝癌。广州一项研究测了 2010 到 2022 年小作坊自榨花生油里的黄曲霉毒素 B1。中位数 1.29 μg/kg，中间一半样品在 0.12 到 6.58 之间。当地出台小作坊管理条例后，油里的毒素马上降了 2.865 μg/kg，之后每年再降 2.593。常吃自榨油那片居民的肝功能异常比例随之下降（PR 0.650，95% CI 0.469–0.902，可信范围），低约 35%。广西一项跟踪 1611 名孕妇的研究里，81.7% 吃自榨花生油。吃的人孩子低出生体重的风险高约九成（aOR 1.9，1.1–3.2），早产高约八成（aOR 1.8，1.1–3.0）。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-40"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-41', 'concept_archive_s2-41', 'recommendation', 'Cochrane 汇总了 15 项随机试验、56,675 人，每项至少做两年。少吃饱和脂肪，心血管事件合计低约 17%（RR 0.83，0.70–0.98）。总死亡率几乎不变（RR 0.96，0.90–1.03），心血管死亡也不变（RR 0.95，0.80–1.12）。换成多不饱和脂肪（大豆油、玉米油的主要成分）和换成碳水，效果没看出差别。换成单不饱和脂肪（菜籽油、橄榄油的主要成分）的数据太少，说不清。另一篇 Cochrane 汇总 19 项随机试验、6461 人，多吃 omega-6（亚油酸）对总死亡率 RR 1.00（0.88–1.12），对心血管事件 RR 0.97（0.81–1.15），看不出好处也看不出害处。第三篇汇总 86 项随机试验、162,796 人，多吃植物来源的 omega-3（亚麻籽油、紫苏油的主要成分），总死亡率 RR 1.01（0.84–1.20），冠心病事件 RR 1.00（0.82–1.22），基本没有作用。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-41"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-42', 'concept_archive_s2-42', 'recommendation', '把 10 项病例对照研究合起来算，对象都是不吸烟的中国女性。病例对照是拿肺癌病人和没病的人比，回头问过去的习惯。接触做饭油烟的人，得肺癌的机会约为 1.74 倍（比值比，95% CI 1.57–1.94，可信范围）。其中 4 项比的是接触油烟又不用抽油烟机的人，约为 2.11 倍（1.54–2.89）。台湾一项研究拿 1302 名不吸烟的女性肺癌病人，和 1302 名没病的人对比。只看做饭十年以上的人。三分之二以上的年头都开抽油烟机的，和三分之一以下的比，风险低约一半（比值比 0.49，0.32–0.76）。上海有一项往后跟踪的研究，7.1 万名不吸烟的女性，从 1996 年跟到 2009 年，查出 429 例肺癌。自己说住过厨房通风差的房子的，得肺癌的风险高约 49%（HR 1.49，1.15–1.95）。烧煤又通风差 20 年以上的，约为 2.03 倍（HR 2.03，1.35–3.05）。单看烧没烧过煤，没看出差别（HR 1.03，0.84–1.26）。炒菜用哪种油，也没看出差别。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s2-42"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s2-43', 'concept_archive_s2-43', 'recommendation', 'Cochrane 汇总了 24 项随机试验、3329 人，比的是口服激素和安慰剂。用激素的人，每周潮热次数比安慰剂少约 75%（95% CI 64.3–82.3，可信范围）。潮热的严重程度也明显减轻（OR 0.13，0.07–0.23）。吃安慰剂的人潮热也少了约 57.7%，所以说能治潮热的东西，都要和安慰剂比过才算数。风险看美国 WHI 随机试验。16608 名有子宫的 50 到 79 岁女性，用雌激素加孕激素，平均跟了 5.2 年。冠心病高约 29%（HR 1.29，1.02–1.63）。浸润性乳腺癌高约 26%（HR 1.26，1.00–1.59）。中风高约 41%（HR 1.41，1.07–1.85）。肺栓塞约为 2.13 倍（HR 2.13，1.39–3.25）。折成绝对数，每 1 万名女性每年多 7 例冠心病、8 例中风、8 例肺栓塞、8 例浸润性乳腺癌。同时少 6 例结直肠癌、5 例髋部骨折。切除了子宫、只用雌激素的女性，累计跟踪 13 年，乳腺癌反而低约 21%（HR 0.79，0.65–0.97）。两项试验合起来跟踪 18 年，总死亡率没有变化（HR 0.99，0.94–1.03）。按开始用药的年龄分，50 到 59 岁那组在用药那几年总死亡率低约 31%（HR 0.69，0.51–0.94）。60 到 69 岁是 1.04（0.87–1.25），70 到 79 岁是 1.13（0.94–1.36），都不显著。跟到 18 年，50 到 59 岁那组是 0.89（0.79–1.01），也不显著了。Cochrane 2017 年的综述单看 50 到 59 岁的女性，唯一明显升高的是雌孕激素联用时的血栓，绝对风险不到 1/500。65 岁以上用雌孕激素联用的女性，4 年里痴呆从每千人 9 例升到 11 到 30 例。美国预防服务工作组 2022 年反对用激素预防慢性病（D 级推荐），结论是没有净好处。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s2-43"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-1', 'concept_archive_s3-1', 'recommendation', '只是收到一条通知，不看也不碰，注意力任务的成绩就明显变差。变差的幅度和真的接打电话、发短信相当。这是实验室里做的，受试者是大学生。另有两项实验显示：即便成功克制住不去看手机，自己的手机搁在旁边，也会让脑子能用的余量变少。手机依赖强的人下降最多。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-2', 'concept_archive_s3-2', 'recommendation', '61 名大学生记录了 30 天。作息最不规律的五分之一，生物钟（昼夜节律）比最规律的五分之一晚约 2.5 小时。具体是褪黑素开始分泌的时刻 00:08 对 21:32。最困、最想睡的时段也晚约 1.8 小时。作息越规律，学业成绩越好（相关系数 r = 0.37）。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-3', 'concept_archive_s3-3', 'recommendation', '48 名 21 到 38 岁的健康成人，连续 14 天每晚只睡 6 小时。他们的脑力表现累计下降，掉到相当于连续 2 晚完全不睡的水平。而自己打分的困倦程度只在头几天上升，之后几乎不再增加。6 小时组和 4 小时组的自评困倦没有差别。这是把人随机分成两组做的对照试验（RCT）。另外，短时间不睡（急性睡眠剥夺，不超过 48 小时）对简单注意力走神的效果大小 g = -0.776，对推理准确率 g = -0.125。这部分是把 70 项研究合起来算的。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s3-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-4', 'concept_archive_s3-4', 'recommendation', '睡前 6 小时喝 400 mg 咖啡因，仪器测到的总睡眠时间比喝安慰剂少 1.1 到 1.2 小时。安慰剂就是不含咖啡因的对照饮料。可是受试者自己写的睡眠日记没有报出差别，自己察觉不到。把多项研究合起来算（荟萃分析）：咖啡因平均让总睡眠时间减少 45 分钟。躺在床上真正睡着的比例（睡眠效率）下降 7%。一杯咖啡（107 mg）要在睡前 8.8 小时以上喝完，才不影响睡眠。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s3-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-5', 'concept_archive_s3-5', 'recommendation', '124 名成年人，两周里同一批人前后对比（自身对照）。限制为每天查 3 次邮件的那周，日常压力明显低于不限次数那周（效果大小 Cohen''s d = 0.37）。两周收到和回复的邮件数量并没有差别。一开始不加限制时，人们平均每天查邮件 15.5 次。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-6', 'concept_archive_s3-6', 'recommendation', '平均 2.8 秒的打断，会让按顺序一步步做的任务（序列任务）步骤出错率翻倍。4.4 秒的打断让它翻三倍。这是实验室里做的。另一项是对 24 名办公室白领（信息工作者）的现场观察。他们平均每 11 分钟切换一次工作主题。57% 的工作主题被打断。当天回到被打断的那件事上，平均要 25 分 26 秒。中间还插了 2.26 件别的事。还有一项 48 人的实验：被打断的人做得更快，但报告的压力、挫败感、时间压力和费劲程度都更高。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-7', 'concept_archive_s3-7', 'recommendation', '任务切换以后，反应明显更慢，也更容易出错。这部分来自多项研究的综述。另一项实验室研究的受试者是大学生。经常同时用好几种媒体的人（重度媒体多任务者）更容易被不相干的东西和不相干的记忆带跑。他们在任务切换测试上反而表现更差。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-8', 'concept_archive_s3-8', 'recommendation', '实验室里让同一批人两种条件轮着做（交叉试验）。睡前读发光的电子书，比读纸书入睡慢约 10 分钟（25.7 分钟对 15.8 分钟）。晚间褪黑素被压低 55%。第二天的生物钟（昼夜节律）推迟超过 1.5 小时，褪黑素开始分泌的时刻是 22:31 对 21:01。第二天早上更困，要更长时间才完全清醒。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-9', 'concept_archive_s3-9', 'recommendation', '2025 年我国居民夜间平均睡眠 6.97 小时，平均入睡时间 0:10（中国睡眠研究会）。睡前用便携设备的人，睡不够的可能性约为 2.17 倍（OR 2.17）。睡眠质量差约 1.46 倍（OR 1.46）。白天犯困约 2.72 倍（OR 2.72）。设备只是放在卧室里、并不使用，数字也差不多，约 1.79、1.53、2.27 倍（OR 1.79/1.53/2.27）。这部分是把 20 项同一时间点的调查、125198 名儿童青少年合起来算的。另一项同一时间点的调查：844 名 18 到 94 岁成人中，关灯后仍用手机的人入睡更慢，躺在床上真正睡着的比例更低，白天更疲劳。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-10', 'concept_archive_s3-10', 'recommendation', '34 名健康人在 49.5 小时不睡之后，做爱荷华赌博任务。这是一种衡量风险决策的实验。休息充足时，他们能很快学会避开高风险选项。缺觉之后，反而更多地选高风险选项。年纪大的人受影响更大。这是一项实验，只有这一项研究。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-11', 'concept_archive_s3-11', 'recommendation', '在前一晚没睡够之后，10 分钟的小睡能立刻改善困倦、疲劳、精力和脑力表现，一部分好处维持到 155 分钟以后。睡 5 分钟几乎没有好处。睡 20 分钟的好处要等 35 分钟以后才出现。睡 30 分钟以后先有一段睡眠惰性：刚醒那阵表现反而更差，之后才改善。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-12', 'concept_archive_s3-12', 'recommendation', '让学生在模拟的开放式办公室里工作。背景噪音从 39 分贝升到 51 分贝（dB，LAeq）时，他们记住的词更少，自己评分更疲劳，也更不想干活。休息时看带声音的自然影片，比只听河流声或者办公室噪音，更能把精力评分拉回来。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-13', 'concept_archive_s3-13', 'recommendation', '一战时期英国军工厂工人的产出记录：每周 49 小时以内，产出与工时成正比。超过 49 小时，产出的增速开始变慢。大约 63 小时达到最大。干 70 小时的产出与干 56 小时几乎没有差别，多干的 14 小时等于白干。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-14', 'concept_archive_s3-14', 'recommendation', '多项研究的综述说，反复回想同一件糟心事（反刍思维）会加重抑郁。它还会强化负面思考，削弱解决问题的能力。它会妨碍实际行动，还会把身边愿意听你说的人耗光。它与焦虑、暴食、酗酒、自伤相关。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-15', 'concept_archive_s3-15', 'recommendation', '澳大利亚 2978 名 50 岁以上的双生子，平均跟踪 20 年，其间有 1068 人死亡。悲观量表每高 1 个标准差，同期死亡的风险高约 13%（风险比 1.134）。这个数字的可信范围是 95% CI 1.065–1.207，P=8.85×10⁻⁵。心血管死亡高约 20%（1.196，1.045–1.368，P=0.0093）。与癌症死亡无关。乐观得分与死亡率也没有明显关联。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-16', 'concept_archive_s3-16', 'recommendation', '对 120 名 60 到 89 岁丧偶女性的调查：让人难受的来往和心理幸福感的关联，比让人舒服的来往更一致、也更强。按这个结果，一个消耗你的人造成的损失，大于一个支持你的人带来的好处。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-17', 'concept_archive_s3-17', 'recommendation', '把 306 组实验比较合起来算（荟萃分析）：换个角度解释发生的事（认知重评）对情绪的效果大小 d = 0.36。站到对方立场看 d = 0.45。转移注意 d = 0.27。硬压住感受无效（d = -0.04）。另有三项实验显示：惩罚冒犯者的人，事后反而更久地反复想对方；不惩罚的人更快「翻篇」。人们事先高估了报复带来的痛快。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-18', 'concept_archive_s3-18', 'recommendation', '把 218 项随机分组的对照试验、14170 人合起来算（网络荟萃分析）。对照组是同样在做别的活动的人。和他们相比，步行或慢跑对抑郁的效果大小 g = -0.62（95% 可信区间 -0.80 到 -0.45）。瑜伽 -0.55，力量训练 -0.49。强度越大效果越好。把多项光照治疗研究合起来算：季节性抑郁效果大小 0.84（0.60 到 1.08），非季节性抑郁 0.53（0.18 到 0.89）。还有一项分析，把各项研究逐个病人的数据合起来算。它看的是互联网认知行为疗法（网上自助课程）。有人指导和无人指导，都比对照组好。中重度（PHQ-9 大于 9 分）的时候，有人指导的更好。12356 是全国心理援助热线，每日开通不少于 18 小时。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s3-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-19', 'concept_archive_s3-19', 'recommendation', '把和机构打交道的动作换一换：从「求人、生气、反复复述委屈」，换成「拿文书、记期限、按渠道申诉」。省下的是重复沟通和反复回想的时间。这属于一次性的观念调整，不是每天都省时间。能拿来核对的是这些期限本身，它们都写在文件里。治安案件从受理那天算起，办案期限不超过 30 日；案情重大复杂的，经上一级公安机关批准可以延长 30 日。有控告人的案件决定不予立案的，不予立案通知书要在 3 日以内送达。控告人 7 日以内可以申请复议，公安机关 30 日以内作出决定。不服的，再 7 日以内向上一级申请复核。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-20', 'concept_archive_s3-20', 'recommendation', '把多项研究合起来算（荟萃分析）：54 个独立样本、94 个效应量、N = 36,583，用的是三层随机效应模型。网上向上社会比较与心理适应不良的平均相关 r = 0.330（95% CI 0.289–0.370，可信范围）。按具体结果分开看。怕被人看轻这类社会评价性的负面情绪 0.438，焦虑 0.382。抑郁 0.306，幸福感偏低 0.268，自尊偏低 0.263。年龄、文化背景、数据采集年份都不影响这个关联的强弱。长期跟踪的研究得出的结果，也不比同一时间点的调查更强。另有一项随机分组的对照试验，受试者是 2,743 名美国 Facebook 用户。其中 61% 的人愿意以低于 102 美元接受停用。这些人被随机分为停用四周组与对照组。停用为普通受试者每天空出 60 分钟。主观幸福感指数提高 0.09 个标准差。分项是生活满意度 0.12、焦虑 0.10、抑郁 0.09、快乐 0.08。把多次比较碰巧的成分扣掉后，这些仍然算数。作者给了一个参照，是让人变积极的心理干预。这类干预对主观幸福感约 +0.34 个标准差，对抑郁约 -0.23 个标准差。所以这个效应约为常规心理干预的 25% 到 40%。同期的代价是：时事知识指数下降 0.19 个标准差，政治立场对立程度下降 0.16 个标准差。实验结束后，停用组的 Facebook 使用仍比对照低 12 分钟/天（0.31 个标准差，降幅 23%）。还有一项随机分组的对照试验，受试者是 143 名本科生，被随机分成两组。一组把 Facebook、Instagram、Snapchat 每个平台每天限 10 分钟，另一组照常使用。三周后，限时组的孤独与抑郁明显下降。两组的焦虑与错失恐惧都比一开始低。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s3-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-21', 'concept_archive_s3-21', 'recommendation', '实验一：让参与者穿上印有 Barry Manilow 头像的 T 恤，走进有其他参与者的房间。穿的人平均估计 46% 的旁观者能正确指出衣服上的人是谁。旁观者实际正确率 23%，估计值恰为实际值的两倍。逐场把估计值减去实际值，平均高估 23 个百分点（95% CI 9–38，可信范围）。剔除只有两名和三名旁观者的那两场之后，为 27 个百分点（11–43）。实验二：改穿参与者自选的、自认为正面的 T 恤。平均估计 48%，旁观者实际正确率 8%，为六倍。另一系列研究有三种场景：陌生人配对交谈、大学新生室友、成人工作坊。结果是人们系统性低估交谈对象对自己的喜欢程度，也低估对方对这次交谈的享受程度。作者称之为「喜欢差」。不同长度的交谈中都存在，在新生室友之间持续数月。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-22', 'concept_archive_s3-22', 'recommendation', '把多项研究合起来算（荟萃分析）：45 项研究、N = 11,747，人群为本科生、医学生、社区成人与精神科患者，用的是随机效应模型。下面是与自杀念头的加权平均相关。完美主义担忧 r = .28（95% CI .24–.32，可信范围；42 项研究、7,936 人）。完美主义担忧是一个合集，包括社会规定型完美主义、在意犯错、对行动的怀疑、现实与标准的落差等。其中社会规定型完美主义单独算，也是 r = .28（.25–.32，30 项研究、3,640 人）。完美主义追求 r = .10（.07–.13，31 项研究、4,588 人），它是自我导向的完美主义与个人标准的合集。父母批评 r = .20（.11–.29）。再看与自杀未遂的关系。完美主义担忧 r = .12（.07–.17，15 项研究、5,275 人）。社会规定型完美主义 r = .19（.08–.29，8 项研究、689 人）。跟踪一段时间的那部分：把一开始就有的自杀念头扣除后，社会规定型完美主义仍与后来随访时的自杀念头同向变化，幅度不大。自我导向与他人导向的完美主义都看不出关联。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-23', 'concept_archive_s3-23', 'recommendation', '把 154 项研究合起来算（荟萃分析），共 184 组样本、10,189 人。让身体平静下来的办法，比如深呼吸、正念、冥想，能降低怒气和攻击性。效果大小 g = -0.63，95% CI -0.82 到 -0.43（可信范围）。这个结果在不同性别、种族、年龄和文化的人里都稳定。让身体更兴奋的办法，比如打沙袋、慢跑、骑车，整体无效。它的效果大小 g = -0.02，95% CI -0.13 到 0.09。作者的结论是：发泄怒气、去跑一圈，都不是管用的消气办法。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s3-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-24', 'concept_archive_s3-24', 'recommendation', '一项分析汇总了 146 项随机分组的研究（荟萃分析）。研究里的人把对自己重要的事写下来或者说出来。平均效果是正的，也显著，但很小，效果大小 r = .075。另一项汇总只收随机对照试验，30 项试验合起来算，身体健康和心理健康两方面都没有显著效果。针对癌症病人和康复者的 16 项随机试验合起来算，心理、身体、生活质量三方面都不显著。其中心理方面 g = 0.04，95% CI -0.06 到 0.14（可信范围）。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s3-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s3-25', 'concept_archive_s3-25', 'recommendation', '一篇 Cochrane 系统综述汇总了 80 项随机对照试验、5820 名原发性痛经的女性。原发性痛经指查不出别的病的痛经。和安慰剂比，非甾体抗炎药止痛更有效（OR 4.37，95% CI 3.76–5.09，可信范围）。换算过来，吃安慰剂的人有 18% 得到中等以上的缓解，吃这类药的人是 45% 到 53%。代价是副作用多一些（OR 1.29，1.11–1.51）。吃安慰剂的人有 10% 出副作用，吃这类药的是 11% 到 14%。多出来的主要是肠胃不适（OR 1.58）和神经系统反应（OR 2.74）。和对乙酰氨基酚比，这类药止痛也更有效（OR 1.89，1.05–3.43），不过只有 3 项试验。哪一种这类药最好，没比出差别。英国 NICE 指南（2024 年更新）列出要怀疑子宫内膜异位症的几种情况。它们是长期盆腔痛，痛经影响日常活动和生活质量，同房时或同房后深处痛。还有经期排便痛，经期尿血或尿痛，以及伴有这些症状的不孕。17 岁及以下的女孩也算在内。指南建议先试用对乙酰氨基酚或这类药，比如 3 个月。止痛不够，就转去做进一步检查。妇科检查和 B 超都正常，也不能排除这个病。一项研究在 10 个国家的 16 家医院调查了 1418 名做腹腔镜的女性。从出现症状到手术确诊子宫内膜异位症，平均拖了 6.7 年，主要耽误在基层看病那一段。确诊的女性平均每周少干 10.8 小时的活，多数是人在岗上、效率下降。荷兰一项网上调查问了 32748 名 15 到 45 岁的女性。13.8% 因为月经请过假，平均每年 1.3 天。80.7% 来月经时人在岗上但效率下降，折合每年少干 8.9 天。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s3-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-1', 'concept_archive_s4-1', 'recommendation', '把 94 项独立检验合起来算，先把打算写成「如果……就……」的人，目标达成率更高。这种写法在心理学里叫实施意图。效果大小 d = 0.65，算中到大。管用的环节有三个：开始动手、被打扰的时候顶住、从注定做不成的事上撤出来。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s4-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-2', 'concept_archive_s4-2', 'recommendation', '把多项实施意图研究合起来算，结果是：事先定好的「如果……就……」，同样能帮人从注定做不成的事上撤出来。原文的说法是 disengagement from failing courses of action。省下的时间，就是你本来还会继续投进去的那些。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-3', 'concept_archive_s4-3', 'recommendation', '已经投入的钱、精力和时间，会让人更想继续做下去。这在心理学里叫沉没成本效应。把 98 组数据合起来算，分析确认这种倾向稳定存在。避开这种倾向，就不会为了「不想浪费」继续往里投时间。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-4', 'concept_archive_s4-4', 'recommendation', '学生预计 33.9 天完成论文，实际用了 55.5 天。只有 29.7% 的人按自己的估计按时完成。研究者要求另一组人先把过去的经历和眼下这件事挂上钩，再去估。这一组按时完成的比例，从对照组的 29.3% 升到 60.0%。把工期往少了估的那种乐观，在这一组身上不再出现。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-5', 'concept_archive_s4-5', 'recommendation', '两项调查分别有 958 人和 292 人。结果是：会前发了议程的会，参会者更容易觉得这个会有效果，这个关系在统计上站得住。另一项实验里 55 组坐着开会，56 组站着开会，坐着开的时长多 34%。两种开法做出的决定，质量没有差别。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-6', 'concept_archive_s4-6', 'recommendation', '两项调查找的是每周工作 35 小时以上的员工，分别有 676 人和 304 人。开会占掉多少时间，对工作态度和幸福感的影响不是固定的，要看两件事：会开得好不好，这个岗位干活有多依赖别人。另一项研究让人连记一周日记，结果是当天开会次数越多，疲劳和自己感觉到的工作量越高。省下的时间，等于你砍掉的会议时长本身。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-7', 'concept_archive_s4-7', 'recommendation', '人们估工期时，不会自己把一件有好几头的任务拆成几块。比如写文献综述、写讨论、整理参考文献，这本来就是几件事。先把子任务列出来再估，能少犯把工期估短的毛病，这个毛病叫规划谬误。拆开之后，每一小步都成了一个可以立刻开始的动作，拖延也跟着变少。研究里最能预示拖延的因素，包括对这件事的厌恶感，以及任务本身被往后推。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-8', 'concept_archive_s4-8', 'recommendation', '有外部截止日期的学生，80.6% 在截止前完成。而在自己预计的时间内完成的，只有 38.7%。什么时候做完，几乎跟着截止日期走，相关系数 r = 0.82，这个数越接近 1 说明跟得越紧。和自己的预计只有很弱的关系。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-9', 'concept_archive_s4-9', 'recommendation', '一份汇总了 691 个相关系数的荟萃分析发现，和拖延关系强而稳定的有几样：任务让人厌恶的程度、离截止还有多远、自我效能感（觉得自己做得成）、冲动性，以及尽责性和它下面的自控、易分心、条理性、成就动机。而神经质、叛逆、寻求刺激和拖延只有很弱的关联。作者用时间动机理论来解释这组结果：一件事现在的吸引力，随着回报变远而快速变小。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s4-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-10', 'concept_archive_s4-10', 'recommendation', '一份纳入 24 项随机试验的 Cochrane 综述。把食物放得更远，吃掉的量下降，标准化均数差 −0.60（95% CI −0.84 到 −0.36，这是可信范围；12 项研究、1098 人，低确定性证据），属于中等效应。把可选项减少，选择该食物的下降更明显，标准化均数差 −1.13（95% CI −1.90 到 −0.37，3 项研究、154 人，低确定性证据）。回归分析显示：放得越远、可选项越单一，效果越强。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-11', 'concept_archive_s4-11', 'recommendation', '美国一项 2538 人的随机试验，把员工和他们的亲友随机分到四种激励方案或常规照护。奖励型（做到给约 800 美元）的接受率 90.0%，押金型（先交 150 美元，另加 650 美元奖励）13.7%。六个月的持续戒烟率：四种激励方案在 9.4% 到 16.0% 之间，常规照护 6.0%。奖励型 15.7%，押金型 10.2%。但在只算「两种都肯参加」的那 13.7% 的人里，押金型的六个月戒烟率比奖励型高 13.2 个百分点（95% CI 3.1 到 22.8，这是可信范围）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s4-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-12', 'concept_archive_s4-12', 'recommendation', '96 名志愿者各挑一个吃、喝或者活动方面的动作，在固定场景下（比如「早饭后」）每天做，持续 12 周，每天给自己的自动化程度打分。82 人的数据够用来分析，模型在 62 人身上拟合成功。达到各自自动化上限 95% 所需的天数，范围是 18 天到 254 天。研究还发现，漏掉一次执行机会对习惯养成过程没有实质影响。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-13', 'concept_archive_s4-13', 'recommendation', '150 人随机分成三组：有治疗师指导的自助、无指导的自助、等待名单对照。十周后，纯拖延量表上的组间效应量，有指导组 d = 0.70（95% CI 0.29–1.10，这是可信范围），无指导组 d = 0.50（0.10–0.90）；非理性拖延量表上分别是 0.81（0.40–1.22）和 0.69（0.29–1.09）。达到临床意义改善的比例：有指导组 31.3% 到 40.0%，无指导组 24.0% 到 36.0%。两组在任何一项结果上都没有显著差别。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s4-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-14', 'concept_archive_s4-14', 'recommendation', '中国居民做家务每天平均 1 小时 17 分钟。只算做了家务的人，平均 1 小时 59 分钟。这是 2024 年的调查，覆盖 3.85 万户、10.7 万人。另一项研究取了四个国家 6271 人的样本，花钱买时间的人生活满意度更高。研究者还在真实生活里做了实验：同一笔钱，花在买时间上比买实物带来更高的当下幸福感。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-15', 'concept_archive_s4-15', 'recommendation', '中国居民上网每天平均 5 小时 37 分钟。只算当天真上了网的人，平均 6 小时 3 分钟。当天用过网的人占 92.9%。这些是 2024 年的数字。2018 年按同样算法只有 2 小时 42 分钟。这是本节里数字最大的一项。每天砍掉其中一小时，等于每年多出 365 小时。另据中国互联网络信息中心，到 2025 年 6 月，网民平均每周上网 30.6 小时，比半年前多 1.9 小时。短视频用户有 10.68 亿人，占网民的 95.1%。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-16', 'concept_archive_s4-16', 'recommendation', '美国 15 岁以上的人每天看电视 2.6 小时。他们全部休闲时间是 5.2 小时，看电视占掉一半。这是 2025 年的数字。中国居民看电视每天平均 1 小时 40 分钟，75 到 84 岁的人 3 小时 16 分钟。这是 2018 年的数字。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-17', 'concept_archive_s4-17', 'recommendation', '研究看了 251 名有经验的 Word 用户，多数人很少用更快的快捷键，还是以点图标工具栏为主。分组对比的实验确认，菜单、图标、快捷键这三种方式里，快捷键最快。省回的时间随每天操作次数一点点累积。长期做同一类工作的人，收益最大。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s4-18', 'concept_archive_s4-18', 'recommendation', '中国居民每天花在交通上平均 50 分钟。只算当天有出行的人，是 1 小时 2 分钟。这是 2024 年的数字。德国长期跟踪同一批人的数据显示，通勤越长的人主观幸福感（自己觉得过得好不好）稳定地更低。而且这笔损失没有在收入或住房上得到补偿。把多项研究梳理到一起的综述也确认，通勤时间越长，人对通勤越不满意，这一点和用什么交通方式无关。单程少 30 分钟，每周约省 5 小时。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s4-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-1', 'concept_archive_s5-1', 'recommendation', '省下的钱，等于你已经不用、却还在扣费的那些订阅加起来的钱。每个人不一样，没有统一数字。监管要求商家在续费前明显提醒你，还要给你一个「简便的随时取消」的选项，取消不用另外花钱（中国，2021 年起施行）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-2', 'concept_archive_s5-2', 'recommendation', '把工资薪金、劳务报酬、稿酬、特许权使用费这四项合起来算一次总账。多交的退给你，少交的要补上。有两种情况可以不办：你一年的综合所得收入不超过 12 万元，或者要补的税不超过 400 元。这两条是国家税务总局 2023 年公告定的，管到 2027 年 12 月 31 日。反过来，下面这几种人办下来通常能退到钱：全年只有几个月有收入的，年中换过工作的，有子女教育、房贷、房租、赡养老人等扣除没填的', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-3', 'concept_archive_s5-3', 'recommendation', '修改后的条例把可以提取的情况列到九项。其中包括：支付房租，装修自己住的房子，支付自己住的房子的物业费。公积金管理中心要从受理你申请那天算起，3 日内作出准予提取或者不准提取的决定', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-4', 'concept_archive_s5-4', 'recommendation', '工信部的规章写明，运营商不得「无正当理由拒绝、阻止、拖延向用户提供携号转网服务」。也不得「采取拦截、限制等技术手段影响携号转网用户的通信服务质量」。还不得「为携号转网用户设置专项资费方案和营销方案」。老套餐往往比现在在售的套餐贵几十元。一直不换，就是每年白扔几百元', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-5', 'concept_archive_s5-5', 'recommendation', '财政部规定了奖金占销售额的最低比例：乐透型和数字型彩票 50%，即开型 65%，竞猜型 73%。双色球按销售额的 51% 提奖金，每卖 100 元只拿出 51 元当奖金。换算到你身上，每投入 1 元，长期平均只能拿回 0.51 元，亏掉 49%。2024 年全国彩票卖了 6234.86 亿元，其中 1610.31 亿元进了公益金，没有回到买彩票的人手里（中国，2024 年）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-6', 'concept_archive_s5-6', 'recommendation', '原银保监会主席 2018 年在陆家嘴论坛上说过一句话。原话是：「收益率超过 6% 的就要打问号，超过 8% 的就很危险，10% 以上就要准备损失全部本金」。资管新规要求金融机构「不得承诺保本保收益」，还要求「出现兑付困难时，金融机构不得以任何形式垫资兑付」。所以正规理财已经没有保本这一说。参与非法集资的损失「由集资参与人自行承担」，出事以后没有人替你赔（中国，2018、2021 年）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-7', 'concept_archive_s5-7', 'recommendation', '信用卡透支利率在 2020 年以前有上下限：上限是「日利率万分之五」，下限是上限的 0.7 倍。万分之五折合成一年是 18.25%，这是单利：按一年 18.25% 算，利息不再滚进本金里。2021 年起改成由发卡机构和持卡人自己商量定价。用了最低还款以后，没还的那部分本金每天全额算利息，免息期同时作废。央行已经要求发卡机构用明显的方式展示年化利率（按整年折算的利率），「不得仅展示日利率、日还款额」。2021 年起，所有放贷的机构做广告、签合同，都要明显写出年化利率。日利率、月利率可以一起写，但不能比年化利率更显眼。年化利率要把利息和跟贷款直接有关的各种费用都算进去。分期还本的，按每期还完后剩下的本金算你实际用了多少钱。人民银行给过一个算例：借 10 万元，分 12 个月还，每月交最初本金的 0.5% 作分期费。借款当时还要交 1000 元服务费。按单利算，年化约 12.80%。按复利算（内部收益率法），年化约 13.58%。光看费率，会以为一年只花 0.5% × 12 + 1% = 7%。实际差不多是它的两倍，因为本金每月在减少，分期费却一直按 10 万元收。照同样的算法，信用卡分 12 期、每期手续费 0.6%、没有别的费用，名义上是一年 7.2%。按复利算，年化约 13.8%，是名义数字的 1.9 倍左右。分 6 到 36 期，都在 1.8 到 2 倍之间。借给你钱的是个人或普通公司，就是民间借贷。约定的利率超过签合同时一年期 LPR 4 倍，法院不支持超出的部分。2026 年 8 月 20 日的一年期 LPR 是 3.0%，4 倍就是 12%。先从借款里扣掉的利息，法院按实际到手的钱算本金。这条线管不到银行、消费金融公司这些持牌金融机构。小额贷款公司、典当行、融资租赁公司等七类地方金融组织也不适用。所以不能拿 12% 去套它们的贷款，要看合同上写的年化利率（中国，2020、2021 年）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-8', 'concept_archive_s5-8', 'recommendation', '这是一笔很大的支出。2024 年国内游戏市场实际销售收入 3257.83 亿元，用户 6.74 亿人，人均约 480 元（这是拿前面两个数相除算出来的）。花出去的钱基本追不回来。只有一种情况例外：限制民事行为能力人（这里指未成年人）没经过监护人同意的打赏和充值，监护人要求退钱时「人民法院应予支持」。成年人自己的打赏和充值，没有这样的规定。另外，未成年人玩网络游戏本来就只能在周五、周六、周日和法定节假日玩，每天 20 时至 21 时这 1 小时（中国，2020、2021 年）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-9', 'concept_archive_s5-9', 'recommendation', '八周岁以上的未成年人是限制民事行为能力人，意思是他只能自己做和年龄、智力相称的事。和他年龄、智力不相称的民事法律行为，要经过法定代理人同意或者追认才有效：家长要事先点头，或者事后认账。不满八周岁的孩子是无民事行为能力人，自己做不了主，他的事由法定代理人代他办。法定代理人没有表示的，视为拒绝追认：家长一直不吭声，就算作不认这笔账', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-10', 'concept_archive_s5-10', 'recommendation', '泉州市反诈骗中心联合泉州市教育局，拆了六类专门骗青少年的骗局。它们套路各不相同，但最后一步是同一个动作：让孩子拿家长的手机转账。第一类，游戏账号和装备低价私下交易。小王私下转了 260 元，对方说「未成年人转账违规，账号要冻结」，他用爸爸的手机点了「核查链接」，账户里 3 万多元被转走。第二类，「解除防沉迷」。对方威胁「不转账取消，你家长要坐牢」，孩子用妈妈的手机转了 7000 元。原文写明防沉迷是官方设定的，「根本没有『私下解锁』渠道」。第三类，打赏退款。骗子冒充「官方客服」，说未成年人打赏可以退，要求「用家长支付宝给指定直播间刷礼物才能退款」，妈妈账户里 7.3 万元被打赏出去，人被拉黑。原文说「有人加你让你『刷礼物退款』，100% 是诈骗」。第四类，冒充同学或者老师。骗子盗了号，发语音报出名字来借钱。开学季还混进班级群冒充老师，发「交学杂费 500 元」，头像和昵称都和真老师一样，还安排「托」在群里说「已交」。第五类，追星。骗子把孩子拉进「明星粉丝群，领 888 元红包」。先让孩子转 48.88 元「验证」。再吓唬说「未成年人参与违规，平台要冻结 8 万，家长要坐牢」。一共骗走 1.6 万元。原文说「真警察、律师绝不会在网上联系未成年人调查，更不会要家长手机操作」。第六类，二手平台上用低价商品把人引出平台，私下转账。同一份材料还列了三条孩子自己别踩的红线。一是银行卡和电话卡不借、不卖、不租，卡被用去转移赃款，可能构成帮助信息网络犯罪活动罪，留下案底会影响考研和考公。二是「手机口」兼职是违法犯罪。三是境外的「高薪招聘」，人可能一到境外就被控制住（全国，2025 年 10 月）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-11', 'concept_archive_s5-11', 'recommendation', '延保的定价通常是商品原价的 10% 到 50%。研究里引用的行业估计说，延保的平均毛利率是 50% 到 60%：卖出去 100 元，有 50 到 60 元是赚的。这大约是普通商品毛利率的 18 倍。2003 年，延保只占百思买营收的 3% 到 4%，却贡献了超过 50% 的利润（美国，2000 年代零售数据）。碰上价格远低于这个区间的延保，可以自己算一笔：延保价 ÷ 修一次要花的钱 = 回本需要的故障概率。你估计延保那几年里至少坏一次的可能比这个数大，才值得买。比如 25 元的延保，假设修一次 300 元，至少坏一次的可能要超过约 8% 才回本。这里的 300 元只是举例，不是统计数字。算之前先扣掉国家规定已经保了的部分。国家规定的三包期从开发票那天算：洗衣机和电冰箱整机 1 年，主要部件 3 年。洗衣机的主要部件是电机、定时器、程控器和电容器，电冰箱是压缩机、温控器等。延保和三包重叠的那段，等于花钱买了本来就有的东西（全国，1995 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-12', 'concept_archive_s5-12', 'recommendation', '国家组织的药品集采，第二批平均降价 53%，最高降 93%。截至 2026 年 4 月，已经开展了 11 批，覆盖 490 种药品。通过或者视同通过一致性评价的药品达到 1695 个。这大约占临床常用化学药的 2/3（中国，2020 到 2026 年官方数据）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-13', 'concept_archive_s5-13', 'recommendation', '个人账户里的钱，可以用来支付你本人和你的配偶、父母、子女在定点医疗机构看病时自己要掏的那部分医疗费。也可以用来支付在定点零售药店买药品、医疗器械、医用耗材时自己要掏的那部分钱。文件还提出，要探索把个人账户用于给家人交城乡居民医保的个人缴费', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-14', 'concept_archive_s5-14', 'recommendation', '北京居民第一阶梯水价是 5 元一立方米，折合 0.005 元一升。瓶装水如果按 1 元 500 毫升算，就是每升 2 元，是自来水的 400 倍。生活饮用水执行的是强制性国家标准 GB 5749-2022。这个标准 2022 年 3 月 15 日发布，2023 年 4 月 1 日起施行。主管部门是国家疾控局（中国，2015 年水价与 2022 年标准）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-15', 'concept_archive_s5-15', 'recommendation', '这项研究看的是 66,465 个美国折扣券商的家庭账户，时间是 1991 到 1996 年。交易最频繁的那一组，年化收益 11.4%，也就是平均每年赚 11.4%。同期整个市场是 17.9%，平均一个家庭是 16.4%。平均一个家庭一年的换手率是 75%，一年里把手上的股票换掉了四分之三。频繁交易的那组和不频繁的那组，毛收益（扣手续费前赚的钱）差别很小，所以差距主要来自买卖时付掉的交易成本（美国，1991 到 1996 年）。国内的数据：研究用的是上海证券交易所的逐日账户数据，覆盖全部约 4000 万个账户。样本期是 2014 年 7 月到 2015 年 12 月，共 18 个月。这 18 个月里上证综指先涨了 150% 以上。它在 2015 年 6 月 12 日见顶 5166.35 点，到 12 月底又跌了 40%。家庭账户按期初市值分成四档。最小的一档占全部家庭账户的 85%，最大的一档占 0.5%。两档期初的股票总市值差不多，分别是 8800 亿元和 8080 亿元。结果是最小的那 85% 因为主动交易损失 2500 亿元，最大的那 0.5% 赚到 2540 亿元。这里的「损失」是和同一段行情里一直持有不动、什么都不做相比。两个数各约相当于本组期初股票市值的三成，前者 28%，后者 31%。作为对照，2014 年 6 月之前的两年半市场较平静。那段时间任取 18 个月，同类差额只有期初市值的 1% 到 3%。这轮行情里，家庭账户平均约三周就把手上的股票换一遍，一年近 18 次（中国上海，2014 到 2015 年；对照期 2012 到 2014 年）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-16', 'concept_archive_s5-16', 'recommendation', '杠杆就是借钱来买，它会把亏损放大。你用融资买入以后，抵押物的市值可能跌到维持担保比例线以下。这条线是券商划的，管的是你抵押在它那里的东西。跌破了这条线，你又没能追加担保把它补回来，就会被强制平仓，由券商直接替你卖掉。账面上的亏损当场变成真亏，没有「等它涨回来」的机会。监管规定，「从事证券交易时间不足半年、缺乏风险承担能力、最近 20 个交易日日均证券类资产低于 50 万元」的客户，不得开立信用账户。这个门槛本身就说明，它不是给普通人用的工具（中国，2015 年）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-17', 'concept_archive_s5-17', 'recommendation', '美国主动股票型基金的整体组合接近市场组合：这些基金合起来持有的股票，和整个市场差不多。但主动管理的高成本原封不动地变成了投资者更低的净回报（扣完费用后到手的收益）。研究用了自助法模拟，把业绩反复随机重排，看单凭运气能做到什么程度。结果显示，很少有基金能产生足以覆盖成本的超额收益：基金比市场多赚的那部分，够不上它收的那笔费（美国，2010 年发表）。标普道琼斯指数公司每年统计一次：2024 年，美国主动管理的大盘股票基金有 65% 跑输标普 500。它统计了 24 年，平均每年有 64% 跑输。截至 2024 年底的 15 年里，所有类别中都没有哪一类是多数主动基金跑赢的', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-18', 'concept_archive_s5-18', 'recommendation', '费率的差别会按复利一点点吃掉本金，意思是每年被扣掉的那一点会年年叠加。一年的费率高 1 个百分点，20 年后的终值少 0.99^20 ≈ 18.2%，终值就是到那时候账户里剩下的钱；30 年后少约 26%。中国从 2023 年起推行公募基金费率改革，下调了主动权益类基金（主要买股票、由基金经理挑股的那种）的费率上限。从 2023 年 7 月 7 日起，新注册的这类基金管理费率不超过 1.2%，托管费率不超过 0.2%。136 家基金公司把旗下老产品的这两项也降到了这条线以下', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-19', 'concept_archive_s5-19', 'recommendation', '只要几项资产不是完全同涨同跌，把钱分开放，预期收益（平均能赚到的）不变，波动（账户上下起伏）却更小。这是 Markowitz 1952 年提出的组合选择基本结论，此后几十年一直沿用。反过来说，钱全押在一只股票或者一个平台上，它的方差就是你全部的方差，它涨跌多少你就跟着涨跌多少。出事的时候没有任何对冲，也就没有别的资产能帮你补回来', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-20', 'concept_archive_s5-20', 'recommendation', '交进去的钱，每年最多 12000 元，可以从综合所得或者经营所得里如实扣掉：你存进去多少，就能从要交税的收入里减掉多少。这笔钱在账户里投资赚到的收益，暂时不收个人所得税。将来领出来的时候不并进综合所得，单独按 3% 计税。所以你省下的是「你的边际税率减去 3%」乘以你实际交进去的钱。边际税率就是你每多赚一元要按的那一档税率。算下来：边际税率 10% 的人每年最多省 840 元，20% 的省 2040 元，30% 的省 3240 元。本来就不用交个税的人（年综合所得扣完各项后没到起征点），交钱的时候一分没省，领的时候反而要按 3% 交，是净亏。边际税率只有 3% 的人也不划算。全年综合所得扣完各项后不超过 36000 元，就落在这一档。这些人交钱时省 3%，领钱时再交 3%，正好抵消，钱却白白锁到退休。每月工资被扣了个税，不等于你就在 10% 那一档，要看全年扣完各项后的数。每年的缴费额度按自然年度累计，第二年重新算，当年没交满的不能结转到下一年。这项政策从 2024 年 12 月 15 日起在全国实施（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-21', 'concept_archive_s5-21', 'recommendation', '这项研究看的是美国 3 家健身俱乐部 7,752 名会员 3 年的数据。选月费超过 70 美元合同的会员，平均每月只去 4.3 次，折合每次超过 17 美元。而 10 次卡只要每次 10 美元。这些人在会籍期间平均多付了 600 美元。另外，月付会员超过一年还没退卡的比例，比年付会员高 17%（美国，三年面板数据）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-22', 'concept_archive_s5-22', 'recommendation', '条例规定，商家收预付款必须订立书面合同，并且在合同里约定退款方式。商家出现重大经营风险的，应当停止收取预付款。商家决定停业或者搬迁的，应当提前告知消费者。消费者有权要求它继续履行，或者退还没消费完的余额。违反的，可以处违法所得 1 到 10 倍的罚款；没有违法所得的，处 50 万元以下罚款', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-23', 'concept_archive_s5-23', 'recommendation', '省下来的是冲动买的东西里「第二天就不想要了」的那部分。这部分占多少，给不出统一的比例。网上买的商品，从收到那天算起七日内可以无理由退货。有四类除外：定做的、鲜活易腐的、已经拆封的数字商品、报刊（中国，2017 年起施行）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-24', 'concept_archive_s5-24', 'recommendation', '人的判断会被最先看到的数字定住，之后再调整通常调不够。所以「原价 999 现价 499」会系统性地抬高你对「便宜了多少」的估计。监管规定，折价的基准应当是促销前七日内同一家店的最低成交价，打几折要拿这家店促销前七天里实际卖出去的最低价当参照。划掉的那个价格，不一定真的卖过（中国，2020 年起施行）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-25', 'concept_archive_s5-25', 'recommendation', '监管规则要求，分红型产品的说明书要用加粗字体提示「未来的保单红利为非保证利益，其红利分配是不确定的」。红利演示就是保险公司给你看的那张分红测算表，它的利差上限是 4.5% 减去产品预定利率。预定利率就是合同里定死的那一档收益率。返还型和分红型多交的那部分保费，相当于交给保险公司代管的储蓄。它收益不保证，流动性也差，想取出来不容易（中国，2023 年起施行）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-26', 'concept_archive_s5-26', 'recommendation', '交强险在全国范围内实行统一的责任限额。限额分成四项分别计算：死亡伤残、医疗费用、财产损失，以及你没有责任时的赔偿。2020 年车险综合改革以后，现行的总责任限额是 20 万元。这 20 万元里，死亡伤残 18 万元、医疗费用 1.8 万元、财产损失 0.2 万元。你没有责任的时候，死亡伤残 1.8 万元、医疗费用 1800 元、财产损失 100 元。超出限额的部分由侵权人自己承担，撞了人的一方要自己掏钱。没投交强险的，车辆会被扣留，还要罚应缴保险费的 2 倍', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-27', 'concept_archive_s5-27', 'recommendation', '有了应急金，失业或者生病的时候你就不用去借钱，也不用亏着把投资卖掉。消费贷和信用卡最低还款按年算的利率，见本节第 7 条（不用信用卡最低还款）。存在银行里的钱受存款保险保护，同一家银行最高偿付 50 万元（中国，2015 年）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-27"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-28', 'concept_archive_s5-28', 'recommendation', '算法是这样。先设房贷年利率为 r，按你的合同来。2026 年 8 月 20 日 5 年期以上 LPR 为 3.5%，实际执行的利率是在 LPR 上加点或者减点。再设 g 为你可选的另一种投资扣完税后的年化收益：这笔钱换个地方投，平均每年能赚到的比例。提前还款的确定收益率就是 r，每还掉一笔，就等于稳稳赚到了 r。如果 g 稳定大于 r，钱留在投资里更划算。如果 g 小于 r，或者 g 根本说不准，那提前还款就等于锁定一笔无风险的 r。等额本息前几年你还进去的钱里，利息占得多，所以越早还省下的利息越多。这一点用银行 App 的「提前还款试算」直接看数字（中国，2026 年利率）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-28"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-29', 'concept_archive_s5-29', 'recommendation', '经营者有欺诈行为的，按价款的三倍赔偿，不足 500 元的按 500 元算。平台明知道或者应该知道卖家侵权却不处理的，要承担连带责任，这笔赔偿你可以直接找平台要。直播间和主播不得虚构交易、关注、浏览、点赞这些流量，也不得发布虚假信息，造成损害的要承担民事责任。组织虚假交易、虚假评价帮人刷宣传的，罚 100 万元以下；情节严重的罚 100 万到 200 万元，还可以吊销执照。定金不得超过合同标的额的 20%。你不履行合同，定金不退；卖家不履行，要双倍返还给你。用个人信息做自动化决策的，不得在交易价格等条件上搞不合理的差别待遇，这就是俗称的大数据杀熟（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-29"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-30', 'concept_archive_s5-30', 'recommendation', '发生消费争议的时候，直播营销平台的经营者应当按照消费者的要求，提供直播间运营者、直播营销人员的相关信息，以及相关的经营活动记录。直播维权最常见的难处是找不到该告谁，拿到这些信息就知道该告谁了', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-30"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-31', 'concept_archive_s5-31', 'recommendation', '因为不符合食品安全标准的食品受到损害的，你可以向经营者要求赔偿损失，也可以向生产者要求。接到你赔偿要求的那一方实行首负责任制，要先行赔付、不得推诿。意思是你找的是谁，谁就得先把钱赔了，不能把你推给另一方。除了要求赔偿损失，你还可以要求对方支付价款十倍或者损失三倍的赔偿金，而且「增加赔偿的金额不足一千元的，为一千元」。但有一处例外：「食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外」。司法解释还定了几条。第一，要同时满足三个条件。购买者是因为个人或者家庭生活消费需要买的。食品不符合食品安全标准。又没有证据证明他买的时候就知道。满足了就「以其实际支付价款为基数计算价款十倍的惩罚性赔偿金」。第二，明知不符合标准还是买、然后索赔的，人民法院只「在合理生活消费需要范围内」支持。连续购买、反复起诉的，按多次购买的总数放在同一个范围内认定。第三，有几种瑕疵法院不支持惩罚性赔偿，前提是它不会让消费者对食品安全产生误解。这几种瑕疵是：文字字号不规范，有错别字、多字漏字。还有净含量与规格的标示方式不规范。还有对没有特殊贮存条件要求的食品没有标示贮存条件（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-31"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-32', 'concept_archive_s5-32', 'recommendation', '2024 年国家监督抽查了 25250 批次产品，不合格率 14.3%。其中电商渠道抽了 7297 批次，不合格率 23.5%，比上一年升了 1.8 个百分点。实体店抽了 8055 批次，不合格率 15.1%。强制性产品认证（3C）的证书，可以在认监委官网的「认证结果」栏里查真伪。能效标识按产品目录强制管理，标识上必须有能效等级、能效指标和能效信息码。伪造、冒用能效标识，或者该标不标的，按节约能源法处罚（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-32"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-33', 'concept_archive_s5-33', 'recommendation', '先看买入这一头。《消费税税目税率表》定的税率是这样的。「高档手表」20%。「贵重首饰及珠宝玉石」里，金银首饰、铂金首饰、钻石及钻石饰品 5%。其他贵重首饰和珠宝玉石 10%。「高档手表」的口径是「销售价格（不含增值税）每只在 10000 元（含）以上的各类手表」。再看变现这一头，依据是《典当管理办法》。第三十六条：典当期限最长不得超过 6 个月。第三十七条讲的是当金利率，指典当行借给你那笔钱的利息。这个利息按中国人民银行公布的 6 个月期法定贷款利率和典当期限折算。利息不得预扣，不能从给你的钱里先扣走。第三十八条：动产质押典当（押手表玉石这类东西）的月综合费率，不得超过当金的 42‰，每月另收的综合费用不超过借款额的 4.2%。房地产抵押是 27‰，财产权利质押是 24‰。第四十条：期限到了以后 5 日内既不赎当也不续当，就算绝当，东西不再等你来赎。第四十三条：估价金额 3 万元以上的绝当物，可以委托拍卖。拍卖收入要先扣掉拍卖费用和当金本息。剩下的退还给当户，不够的部分还要向当户追索（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-33"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-34', 'concept_archive_s5-34', 'recommendation', '先看规则，依据是《检验检测机构资质认定管理办法》。第二条：资质认定，是对「向社会出具具有证明作用的数据、结果」的检验检测机构做的评价许可：先审查它，再发给它出证书的资格。第十五条：资质认定标志由 CMA 图案和资质认定证书编号两部分组成。第二十一条：机构对外出具有证明作用的数据、结果的，应当在检验检测报告上标注资质认定标志。第二十二条：资质认定部门应当在官方网站上公布取得资质认定的机构信息，并注明证书状态。第三十四条：没有依法取得资质认定就擅自对外出具有证明作用的数据、结果的，处 3 万元罚款。第三十七条：伪造、变造、冒用资质认定证书或者标志的，处 3 万元以下罚款。再看官方案例，出自市场监管总局 2026 年 6 月 4 日公布的传统工艺市场「打假清源」典型案例。一，江苏东海一个直播间宣称，卖的是「天然的、无酸洗、无优化、缅甸的 A 货」。直播间还配了「国检证书」。送检结果却是石英岩玉（染色）、翡翠（处理）、玻璃和塑料。那张证书是当事人自己联系人做出来的。二，同一个县还有一案，扣押了 469 件疑似假冒的天然水晶制品，检出 210 件是天然水晶、259 件是合成水晶。三，河南镇平一家店铺私自做了一块展板，用于直播。展板上写的是「GIA CMA 中玉珠宝玉石鉴定中心认证合作单位」。这家店还从网上买了 181 只「国家珠宝玉石质量监督检验中心」的合格证标识。这些标识配着手镯一起卖（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-34"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-35', 'concept_archive_s5-35', 'recommendation', '依据是《盲盒经营行为规范指引（试行）》。第九条列了一串关键信息，应当以显著方式对外公示，保证消费者买之前就知道。这些信息是：商品名称、种类、样式、抽取规则、商品分布、限量商品投放数量、抽取概率、商品价值范围。同一条还规定了三件不许做的事。一是不得通过后台操纵改变抽取结果、随意调整抽取概率等方式变相诱导消费。二是不得用折现、回购、换购等方式拒绝或者故意拖延发放盲盒。三是不得设置空盒。第十一条只是「鼓励」经营者建立保底机制，通过设定抽取时间、抽取金额上限和次数上限等方式引导理性消费。第十七条管的是以互联网形式卖的盲盒商品。经营者充分告知提示了，消费者也在单次购买时确认了，这种盲盒拆封后可以不适用七日无理由退货。经营者不得用默认勾选的方式替代消费者的确认环节。第二十一条：不得以盲盒的名义从事或者变相从事赌博活动。第二十三条：不得向未满 8 周岁的未成年人销售盲盒；向 8 周岁及以上的未成年人销售，应当依法确认已经取得相关监护人的同意（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-35"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-36', 'concept_archive_s5-36', 'recommendation', '食品安全法第六十七条规定，预包装食品的包装上应当有标签。标签必须标明九项内容。其中第二项是「成分或者配料表」，第七项是「所使用的食品添加剂在国家标准中的通用名称」。第六十八条对散装食品的要求少得多。原文是：食品经营者销售散装食品，应当在散装食品的容器、外包装上标明「食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容」。这一条没有提配料表，也没有提添加剂。冷冻水产品是这个差别最明显的地方。GB 2760—2024 允许在冷冻水产品里用磷酸及磷酸盐做水分保持剂，俗称保水剂。最大使用量是 5.0 g/kg，以磷酸根计。在这个量以内用是合法的。出问题的是超量用和包冰增重。2025 年央视 3·15 晚会曝光虾仁「违规超量添加保水剂（复合磷酸盐）及包冰增重」之后，市场监管部门要求企业「产品标签应明确标注保水剂（如磷酸盐）成分、净含量（扣除冰衣重量）、配料表」（全国，食品安全法 2025 年第三次修正，2025 年 12 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-36"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-37', 'concept_archive_s5-37', 'recommendation', '这项研究看的是美国一家折扣券商 10,000 个账户 1987 到 1993 年的全部交易记录。盈利股被卖出的比例（PGR）是 0.148。亏损股被卖出的比例（PLR）是 0.098。两者相差 0.050，t 值超过 35。按天算，涨了的股票被卖掉的可能性比跌了的高 50% 以上。同一批账户给亏损股加仓也更积极。亏损股被再买一次的比例是 0.135，盈利股是 0.094，t 值 19。研究还检验了「留着的会涨回来」这个想法。结果是反的：卖掉的盈利股在此后一年的超额收益，平均比留着没卖的亏损股高 3.4 个百分点。超额收益指的是比市场指数多出来的那一部分。作者还按平均值算过一个例子。同样卖掉 1000 美元的股票，卖亏损的那只比卖盈利的那只，此后一年回报高约 4.4%。这 4.4% 里含了卖亏损股提前抵税省下的钱。抵税是按美国的税制算的（美国，1987 到 1993 年）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-37"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-38', 'concept_archive_s5-38', 'recommendation', '2026 年 5 月 22 日，证监会、工业和信息化部、公安部、中国人民银行、市场监管总局、金融监管总局、国家网信办、国家外汇局八个部门印发《综合整治非法跨境证券期货基金经营活动实施方案》。总体要求是「经过2年集中整治，全面取缔境外证券期货基金经营机构非法跨境经营活动」。境外机构不得在境内开展营销招揽，不得「提供相关开户、处理交易指令、资金划转等交易服务」。对已经开了户的人，方案写的是「禁止境外机构为存量投资者在境内非法提供买入交易、转入资金等服务，只允许单向卖出交易并转出资金」。两年期满后，「全面关停境内网站、交易软件及配套服务器」。同一天证监会通报，拟没收老虎、富途、长桥境内外相关主体全部违法所得，并依法严厉处罚。配套的答记者问写明，要「引导境内投资者通过港股通、合格境内机构投资者（QDII）及跨境理财通等合法渠道开展境外投资」。换汇这头，国家外汇局的《个人购汇申请书》写明，个人购汇「不得用于境外买房、证券投资、购买人寿保险和投资性返还分红类保险等尚未开放的资本项目」。违规的人列入「关注名单」，「当年及之后连续 2 年不享有个人便利化额度」，还会被行政处罚、移送反洗钱调查，信息纳入个人征信记录（全国，2026 年 5 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-38"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-39', 'concept_archive_s5-39', 'recommendation', '保险公司收上来的保费，只有一部分会作为赔款付出去。剩下的要付销售和运营的费用，还有公司的利润。监管要求卖个人短期健康险的公司，每半年在官网公布一次「综合赔付率」。它大致是赔出去的钱占保费的比例，想知道一家公司赔出去多少，可以去它官网查。所以对一件损失来说，买保险长期平均是亏一点钱。换来的是把一次能压垮家里的大额支出，摊成每年一笔小钱。损失越小、你越掏得起，这笔交换越不划算。按这个标准，书里已经写过的几样是值得买的。一年期医疗险见第 7 节第 20 条（一年期医疗险）。有车的人见本节第 26 条（三者险）。出国的人见第 21 节第 4 条（境外医疗）。家里有人靠你的收入过日子的，见本节第 40 条（定期寿险）（全国，2021 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-39"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-40', 'concept_archive_s5-40', 'recommendation', '监管对寿险的定义是：以人的寿命为保险标的的人身保险，分定期寿险、终身寿险、两全保险等。定期寿险以被保险人死亡为给付保险金的条件，保险期间是固定的年数。终身寿险保到终身。意外伤害保险只在意外事故导致身故、残疾时才赔，生病去世不赔，代替不了寿险。以死亡为给付条件的合同，要经被保险人本人同意并认可保额，否则合同无效。父母给未成年子女投保死亡保险不受这条限制，但因孩子死亡给付的保险金总和，不得超过监管机构规定的限额。寿险保额通常在数十万元级，收益因此定为大。保额买多少没有官方口径。作者的算法是：没还完的房贷，加上孩子长到成年前的开销，再加几年的家用（全国，2015 年修正）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-40"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-41', 'concept_archive_s5-41', 'recommendation', '保险期间超过一年的人身险，监管要求写明犹豫期从哪天算、有几天。投保人在犹豫期里有什么权利，也要写明。长期健康险的犹豫期不得少于 15 天。在银行买的、保险期间超过一年的保险，合同里一律约定 15 日犹豫期。它从你收到保单并书面签收那天算起，按自然日算。这类保单的封面上要印这句提示：「您在收到保险合同后15日内有全额退保（扣除不超过10元的工本费）的权利。超过15日退保有损失。」过了犹豫期，你仍然可以随时解除合同。保险公司要在 30 日内，按合同约定退还保单的现金价值（保单里能退的那部分钱）。金融监管部门的风险提示说，长期人身险犹豫期后退保，现金价值往往低于已交的总保费。一年以上的人身险新单，保险公司要在犹豫期内回访你。回访要确认你知不知道退保的损失和犹豫期的权利（全国，2010、2019 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-41"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-42', 'concept_archive_s5-42', 'recommendation', '规定写明，银行不得把保险和储蓄存款、基金、银行理财混在一起卖。不得把保险的收益和存款简单类比，不得把不确定的收益说成保证收益。保险单证和宣传材料不许用银行的名称和标识，不许出现「存款」「储蓄」「与银行共同推出」这类字样。保险单封面要用不小于 72 号的字印「保险合同」，用不小于二号的字印保险公司名称。有三种人买保险，原则上只能卖保单利益确定的产品：投保人超过 65 周岁的；买期缴产品、投保人超过 60 周岁的；填的年收入低于当地居民人均可支配收入的。这三种人的保单还要转给保险公司人工核保，不许在网点自动出单。保险公司的人不许在银行网点里卖保险。银行卖的一年以上保险，有 15 日犹豫期，过了犹豫期退保就有损失（全国，2019 年 10 月起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-42"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-43', 'concept_archive_s5-43', 'recommendation', '2026 年 2 月，金融监管总局、中央网信办、公安部、中国人民银行、中国证监会联合发了风险提示。它说「全额退保」这类说法属于不实信息，和保险法等法律法规不符。「代理维权」的人会收高额服务费，你中途想退出，还可能因为「违约」吃官司。他们还会收集你的手机卡、银行卡、保单、家庭住址、孩子的学校这些信息。这些信息被倒卖，你可能碰上电信诈骗和盗刷。宁夏金融监管局 2026 年 6 月的提示写得更细。这类中介约定退保成功后，收退保金额 30% 到 50% 的代理费，中途不干了要交高额违约金。他们教人编造销售误导、代签名这类理由去投诉。照做的人可能违反治安管理处罚法，严重的可能涉嫌诬告陷害或敲诈勒索的共同犯罪。退保后保险责任马上终止。以后再买同类保险，可能因为年纪大了、身体查出问题，而涨价或者被拒保。真被误导了，先找保险公司官方客服投诉协商，谈不拢打 12378 银行保险消费者投诉维权热线，全程免费。只是一时交不起保费，可以先问保险公司能不能办减额交清、保单贷款这类服务。减额交清就是以后不再交钱，保额按比例降下来（全国，2026 年）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s5-43"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-44', 'concept_archive_s5-44', 'recommendation', '保险法规定，受益人由被保险人或者投保人指定。投保人指定的，要经被保险人同意。有三种情况，保险金算被保险人的遗产，按继承的规矩给。一是没指定受益人，或者指定得不清楚。二是受益人死在被保险人前面，又没有别的受益人。三是受益人依法丧失或者放弃受益权，又没有别的受益人。受益人和被保险人在同一件事里去世、分不清先后的，推定受益人先死。算作遗产的钱，要先清偿去世的人欠的税和债，剩下的才分。最高法的解释写明：受益人写成「姓名加身份关系」，出事时身份关系变了，算没指定受益人。改受益人没通知保险公司的，对保险公司不生效。领钱的诉讼时效，人寿保险是 5 年，其他保险是 2 年，都从知道或者应当知道出事那天算起。寿险保额通常在数十万元级，收益因此定为大（全国，2015 年修正、2021 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-44"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-45', 'concept_archive_s5-45', 'recommendation', '2026 年 2 月，人民银行等八个部门发了银发〔2026〕42 号通知。通知写明，比特币、以太币、泰达币这类虚拟货币「不具有法偿性，不应且不能作为货币在市场上流通使用」。人民币换币、币换币、发币融资，都属于非法金融活动，「一律严格禁止」。境外机构也不许给境内的人提供这类服务。个人投资这一头，通知原话是：「任何单位和个人投资虚拟货币、现实世界资产代币及相关金融产品，违背公序良俗的，相关民事法律行为无效，由此引发的损失由其自行承担」。2021 年的银发〔2021〕237 号通知同时废止，这句话在新通知里保留了。法院案例：汤某 2018 年 2 月到 2019 年 7 月，向两个自称平台商户的人买泰达币，付了约 44.8 万元（精确值 448000 元）。后来平台提不了现，也登不上。他起诉要回这笔钱。法院认为用人民币换虚拟货币，这个投资行为无效，损失由他自己承担，驳回了起诉，二审维持（江苏宜兴，2025 年 3 月发布）。被偷是另一回事：有人账户里价值 400 余万元的虚拟币被「黑客」盗走，其中一名盗窃者被以盗窃罪判 7 年，罚 2 万元（河南郑州）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-45"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s5-46', 'concept_archive_s5-46', 'recommendation', '怎么交、怎么领，国务院 2005 年的决定写明了。没单位、自己交的人（正式说法是灵活就业人员）按缴费基数的 20% 交，其中 8% 记进个人账户。2019 年起，缴费基数可以自己选。范围是本省全口径城镇单位就业人员平均工资的 60% 到 300%。退休后的养老金分两块。第一块叫基础养老金。把当地上年度在岗职工月平均工资，和你自己的平均缴费工资加起来除以 2，每交满 1 年发 1%。第二块叫个人账户养老金，是账户里的钱除以计发月数。60 岁退休的计发月数是 139，55 岁是 170，退休越晚，月数越少。下面是按公式自己算的例子，不是官方数字。假设退休那年当地月平均工资 8000 元，两种平均工资按同一个数算。下面的金额都按退休那年的工资水平折算，个人账户的利息按刚好跟上工资上涨算。按最低档 60% 交，缴费基数是 4800 元，每月交 960 元。交 15 年共交约 17.3 万元（精确值 172800 元）。60 岁起每月领约 1457 元：基础养老金 960 元，个人账户养老金约 497 元。一年约 1.75 万元（精确值约 17487 元），要领约 9.9 年才回本，也就是领到 70 岁上下。按 100% 档交，15 年共交约 28.8 万元（精确值 288000 元），每月领约 2029 元。比最低档多交的约 11.5 万元（精确值 115200 元），每月只多领约 572 元，要领约 16.8 年才回本。原因是基础养老金有一半按当地平均工资算，和你交多少无关，交得少的人占便宜。按最低档每多交一年，回本年限还是约 9.9 年，比提高档次划算。按最低档交，基础养老金占了领到的钱的大头。这个回本年限和当地工资高低无关。工资高的地方，交的和领的按同一个比例变高，回本年限不变。早年交的钱面额小，退休时却按当时的平均工资发。所以只看交钱和领钱的面额，回本比 9.9 年早。法律规定：退休时累计交满 15 年，才能按月领。不满的，可以接着交满。2030 年 1 月 1 日起，这个最低年限每年提高 6 个月，逐步提高到 20 年。人去世了，个人账户里剩的钱可以继承。国家会根据职工平均工资增长和物价上涨，适时调高养老金。养老保险基金不够发的时候，由政府补贴（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s5-46"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-1', 'concept_archive_s6-1', 'recommendation', 'PHS II 试验找了 14,641 名男医生，跟踪了 11.2 年（这是中位数，一半人比它长、一半人比它短）。吃的人和不吃的人，心脏血管出大事的比例一样。主要心血管事件 HR 1.01（HR 是风险比，1 就是两边一个样）。95% CI 0.91–1.10 是这个数的可信范围。死亡也一样，全因死亡 HR 0.94（0.88–1.02）。美国给预防措施打分的机构 USPSTF，2022 年把 9 项随机分组的对照试验、51,550 人合起来算，结果是多维片和总死亡没有关联。评级 I，意思是证据不够、说不清。它看起来划算，是因为「一片补齐所有营养」听着顺，而且一天只要几毛钱', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-2', 'concept_archive_s6-2', 'recommendation', 'VITAL 试验找了 25,871 人，每天吃 1 克鱼油，跟踪了 5.3 年（中位数）。心脏血管出大事和死亡，两边都没看出差别。主要心血管事件 HR 0.92（HR 是风险比，1 就是两边一个样）。95% CI 0.80–1.06 是这个数的可信范围。它跨过了 1，说明看不出差别。全因死亡 HR 1.02（0.90–1.15）。ASCEND 试验找了 15,480 名糖尿病患者，也是每天 1 克，平均跟踪 7.4 年，同样没看出差别。严重血管事件 RR 0.97（0.87–1.08）。全因死亡 RR 0.95（0.86–1.05）。它看起来划算，是因为很多人把「吃鱼有好处」直接当成了「吃鱼油胶囊有好处」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-3', 'concept_archive_s6-3', 'recommendation', 'VITAL 试验找了 25,871 人，每天吃 2000 IU，跟踪了 5.3 年（中位数）。癌症、心脏血管的毛病和死亡都没看出差别。会扩散的那类癌 HR 0.96（HR 是风险比，1 就是两边一个样；95% CI 0.88–1.06 是可信范围）。主要心血管事件 HR 0.97（0.85–1.12）。全因死亡 HR 0.99（0.87–1.12）。D-Health 试验找了 21,315 名 60 岁以上的澳大利亚人。他们每月吃 60,000 IU，跟踪 5 年。这一项也没看出差别，全因死亡 HR 1.04（0.93–1.18）。死亡的比例是 5.3% 对 5.1%。它看起来划算，是因为有些研究只跟踪记录、不做任何干预，发现维 D 水平低的人死得多，这被误读成了「补上就管用」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-4', 'concept_archive_s6-4', 'recommendation', 'Cochrane 把 78 项随机分组的对照试验、296,707 人合起来算。吃抗氧化补剂的人，总死亡 RR 1.02（RR 是风险比，1 就是两边一个样；95% CI 0.98–1.05 是可信范围）。只看设计更严谨、不容易跑偏的那批试验，RR 1.04（1.01–1.07），略高一点。单看 β 胡萝卜素 RR 1.05（1.01–1.09），单看维生素 E RR 1.03（1.00–1.05）。ATBC 试验找了 29,133 名男性吸烟者，每天吃 20 mg，得肺癌的比例高 18%（3%–36%），总死亡高 8%（1%–16%）。CARET 试验找了 18,314 名吸烟者或者接触过石棉的人。他们得肺癌的风险高约 28%（RR 1.28，1.04–1.57）。死亡风险高约 17%（全因死亡 RR 1.17，1.03–1.33）。它看起来划算，是因为「抗氧化就是抗衰老，抗衰老就能防癌」这条推理链，每一步听上去都像常识', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-5', 'concept_archive_s6-5', 'recommendation', 'GAIT 试验找了 1,583 名膝骨关节炎患者，吃 24 周。吃安慰剂（假药）的人里，也有 60.1% 说疼痛缓解了。氨糖只比它高 3.9 个百分点（P=0.30）。软骨素高 5.3 个百分点（P=0.17）。两样一起吃高 6.5 个百分点（P=0.09）。这几个差距都太小，不能排除只是碰巧。同一个试验里用来做对照的真药塞来昔布，高 10.0 个百分点（P=0.008）。它看起来划算，是因为「补软骨的原料」听起来正好对症，而且光吃假药就有六成人说有效', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-6', 'concept_archive_s6-6', 'recommendation', 'Cochrane 把 29 项对照试验、11,306 人合起来算。普通人天天吃维 C，基本不减少得感冒的次数。得感冒的比例 RR 0.97（RR 是风险比，1 就是两边一个样）。95% CI 0.94–1.00 是可信范围。感冒之后才开始吃的那些试验，原文说「未见一致效应」：有的试验有效，有的没有。同一篇综述里，长期天天吃能把感冒难受的时间缩短约 8%（成人，95% CI 3%–12%），儿童缩短 14%（7%–21%）。马拉松运动员、滑雪的人和在寒冷地区行军的士兵是例外。5 项试验、598 人里，得感冒的人少约一半。发生率 RR 0.48（95% CI 0.35–0.64）。它看起来划算，是因为便宜、酸甜好喝，而且「维 C 防感冒」这个说法已经传了半个世纪', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-7', 'concept_archive_s6-7', 'recommendation', '美国那个给预防措施打分的机构 USPSTF，对没有症状的女性用 CA-125 和超声筛查卵巢癌给了 D 级，意思是建议不做。依据是 PLCO 试验。因卵巢癌死亡的比例，筛查组 0.34%、常规组 0.29%。RR 1.18（95% CI 0.82–1.71）。查了没有好处。因为查错了（假阳性）而白挨一刀的比例，各试验里是 0.2%–3.25%，这些人里最多 15% 出现严重的手术并发症。另一项研究给 1,192 名没有症状的人做全身 CT 筛查。其中 86% 至少查出一处「异常」，37% 被建议进一步检查。原文说「大多数发现按描述是良性的」。它看起来划算，是因为「一次查全身、早发现早治疗」太符合直觉', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-8', 'concept_archive_s6-8', 'recommendation', 'IDEA 试验找了 471 名超重或肥胖的成年人，跟了 24 个月。大家做的饮食和运动安排是一样的，区别只在戴不戴可穿戴设备。戴的那组减重 3.5 公斤（95% CI 2.6–4.5，这是可信范围）。不戴的那组减了 5.9 公斤（5.0–6.8），反而更多。两组差 2.4 公斤（1.0–3.7，P=0.002）。它看起来划算，是因为「量化才能管理」这句话听着有道理，而且设备买一次就完事', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-9', 'concept_archive_s6-9', 'recommendation', '有一篇系统综述，把 17 项在人身上做的研究和 223 项测食品成分的研究合起来看。结论是「缺乏有力证据表明有机食品比常规食品显著更有营养」。这里面只有 3 项研究看的是人吃了以后健康怎么样（看的是过敏和有症状的感染），两边没看出差别。有机农产品被检出农药残留的比例低 30 个百分点，但检出不等于超标。它看起来划算，是因为「没农药就更安全，更安全就更健康」，每一步听上去都像常识', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-10', 'concept_archive_s6-10', 'recommendation', '换回的是省下的这笔钱。理由在本节前 6 条：保健品里最常见的几种成分，多维、鱼油、维 D、抗氧化剂、氨糖、维 C，在随机分组对照试验里都没看出预期的好处，各自的数字在那 6 条的收益栏里。监管规定只说明它能宣称什么，不能当成它没用的证据。国家市场监管总局规定，保健食品包装的正面必须用不小于 20% 的面积标上一句话：「保健食品不是药物，不能代替药物治疗疾病」。同一份规定还把保健食品的用途框死在「补充膳食营养物质、维持改善机体健康状态或者降低疾病发生风险因素」这个范围里。它看起来划算，是因为「不治病，只调理」这句话怎么说都不算错，谁也没办法证明它是假的。而且送礼时掏这笔钱，靠的是人情，不是证据', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-11', 'concept_archive_s6-11', 'recommendation', '一篇综述把 45 项在健康成年人身上做的试验合起来看，结论是「未能支持益生菌能引起肠道菌群的持久改变，也未能改善健康成人的血脂」。肠道里的菌确实会变，但只是暂时的，停了就回去。它看起来划算，是因为「肠道健康」这个说法足够宽、怎么套都不算错，而且每天一瓶单价很低', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-12', 'concept_archive_s6-12', 'recommendation', '荷兰做过一项随机分组对照试验，3,018 人，洗完热水澡之后再冲 30 秒、60 秒或 90 秒冷水。这些人请病假的次数少了 29%（IRR 0.71，这是次数之比）。但原文写明「病假天数没有显著组间差异」：总共病了多少天，两边一样。生活质量、工作效率、焦虑也都没看出有意义的差别。2025 年一篇系统综述把 11 项随机分组试验、3,177 人合起来算。泡完冷水的当下和 1 小时后，身体发炎的指标反而升高。免疫指标没变化。压力只在 12 小时那个时间点降低。作者自己说证据「受限于 RCT 少、样本小」，意思是这类随机分组试验数量太少、每项人也不多。它看起来划算，是因为不花钱，而且「吃苦就有效」这个直觉太顺', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-13', 'concept_archive_s6-13', 'recommendation', '那篇综述的结论是「尽管排毒产业蓬勃发展，支持这些饮食的临床证据非常少」，而且「没有针对商业排毒饮食的随机对照试验」。另一篇系统综述专门查饮食的酸碱、碱性水和癌症有没有关系：翻了 8,278 篇文献，只有 1 篇够格收进来，结果也没看出关联。作者写的是「向公众推广碱性饮食和碱性水用于癌症预防或治疗是不合理的」。它看起来划算，是因为「身体里有毒素要排出来」「体质发酸会致癌」这两个前提听上去很像生理学', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-14', 'concept_archive_s6-14', 'recommendation', '有一篇文献回顾专门查「8×8」这个说法，指的是每天 8 杯、每杯 8 盎司水。它的结论是「未找到任何支持 8×8 的科学研究」。它还写道，「对数千名成年人的食物与液体摄入调查强烈提示不需要如此大量」，因为食物和其他饮品已经提供了大量水分。这个说法看起来划算，是因为水不要钱、8 这个数字又整齐，而且「多喝水」这话在任何场合说出来都显得没坏处', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-15', 'concept_archive_s6-15', 'recommendation', '经典课堂实验：学生做完性格测验后拿到的「个人分析」其实人人都一样，却普遍认为很准。作者的结论是「被本人或分析者接受，不能证明解释正确」。39 个学生按 0 到 5 分给这份分析打准确度分，34 人打了 4 分或 5 分，按表里的分布算平均约 4.26 分。这就解释了算命为什么总显得准，这个现象叫巴纳姆效应。占星术也做过双盲检验，结果发表在 Nature 上。占星师要从三份性格测验结果里挑出和星盘对得上的那一份。116 份里挑中 40 份，纯靠瞎猜也能挑中 38.5 份，占星师事先自己预计能挑中 58.5 份。官方案例：河南息县检察院通报过一个网络算命诈骗团伙，先用免费看手相把人引进来，再收「香火钱」和最高 3888 元的「供养套餐」。被害人 50 余人，追回赃款 200 余万元，主犯判有期徒刑十一年，并处罚金 10 万元', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-16', 'concept_archive_s6-16', 'recommendation', 'Cochrane 2023 年的系统综述收了 17 项随机分组的对照试验，每项 5 到 156 人，跟踪时间从不到 1 天到 5 周不等。因为数据太少、各项试验招的人差别大、跟踪时间又不一致，作者没有把它们合起来算一个总数。下面的结果都是和不带蓝光过滤的镜片相比。跟踪不到一周时，自己报告的眼疲劳程度「可能没有差别」，证据确定性低。其中一项 120 人的试验，两组相差 9.76 个单位。这个差值的可信范围是 95% CI −33.95 到 53.47。范围横跨正负，说明看不出差别。临界闪烁融合频率是一项衡量眼睛疲劳的客观指标，两组「可能几乎没有差别」，确定性低。配上眼镜矫正之后能看到的最好视力「大概没有影响」。两组相差 0.00 logMAR（95% CI −0.02 到 0.02）。这一项只有 1 项研究、156 人，确定性中等。对白天清醒程度有没有影响说不清（2 项试验、42 人，确定性极低）。这篇综述也没有找到支持它保护眼底黄斑的证据', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-17', 'concept_archive_s6-17', 'recommendation', '芬兰 Kuopio 研究跟踪了 2862 名 42 至 60 岁的男性，平均将近 9 年。开始统计之前的 24 个月里献过血的有 153 人，其中 1 人（0.7%）发生了急性心梗。没献过的 2529 人里有 316 人（12.5%）发生（两个比例的差异 P&lt;0.0001）。把年龄和其他冠心病危险因素的影响扣掉之后，献过血的人心梗风险低约 88%。相对风险 0.12（95% CI 0.02–0.86，P=0.035）。但这只是跟踪记录出来的，没有分组对照。北欧 SCANDAT 数据库里有 1,182,495 名献血者，累计跟踪 9,526,627 人年，其中 15,401 人死亡。只扣掉年龄性别这类特征时，每年多献一次血，死亡率低 18.6%（95% CI 16.8%–20.4%）。再把「一直健康才一直被允许献血」这一层也扣掉，降幅只剩 7.5%（5.7%–9.4%）。作者的结论是「不能解释为有益健康的确凿证据」。FeAST 随机分组对照试验找了 1277 名有症状的下肢动脉疾病患者，随机分成两组，一组每 6 个月定期放血减铁，一组做对照。主要看的是全因死亡，125/636（20%）对 148/641（23%）。HR 0.85（HR 是风险比，1 就是两边一个样）。95% CI 0.67–1.08，P=0.17。死亡加上没死的心梗与卒中合起来算，是 180（28%）对 205（32%），HR 0.88（0.72–1.07，P=0.20）。两项都没看出差别。INTERVAL 随机分组试验找了 45,263 名献全血的人。这些人分成三种献血间隔。男性是 12 周、10 周、8 周，女性是 16 周、14 周、12 周。间隔缩短之后，两年内采到的血明显更多（男性 8 周组比 12 周组多 1.69 单位，95% CI 1.59–1.80）。生活质量、体力活动、认知功能各组都没看出差别。但献血带来的不适更多，包括乏力、气短、眩晕、头晕和不宁腿（夜里腿难受得躺不住）。同时血红蛋白与铁蛋白的平均值更低，因为血红蛋白低而被推迟献血的次数也更多（各项 P&lt;0.0001）。缺铁会影响身体产热：10 名缺铁性贫血的女性、8 名铁储备已经耗光但还没贫血的人、12 名对照女性，在 28 ℃ 的水里泡 100 分钟。贫血那组直肠温度 36.0±0.2 ℃，对照组 36.2±0.1 ℃（P=0.001）。耗氧量 5.28±0.26 对 5.99±0.29 mL·min⁻¹·kg⁻¹（P=0.04）。甲状腺素和三碘甲状腺原氨酸这两种甲状腺激素也更低（P&lt;0.002）。这个说法看起来成立，是因为献血的人本来就是被反复筛查过的健康人，而「把铁放掉就能护心」这个假说在随机试验里没验出来', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-18', 'concept_archive_s6-18', 'recommendation', 'Cochrane 系统综述 2019 年更新版收了 17 项随机分组的对照试验。算总死亡率时，合并了其中 11 项试验、233,298 名参与者、21,535 例死亡。做通用健康检查的那组和对照组一样，RR 1.00。RR 是风险比，1 就是两边一个样。95% CI 0.97–1.03 是可信范围。算因心血管病死亡时，合并 9 项试验、170,227 人、6,237 例死亡，RR 1.05（95% CI 0.94–1.16）。算因癌症死亡时，合并 8 项试验、139,290 人、3,663 例死亡，RR 1.01（95% CI 0.92–1.12）。这两项也都没看出差别。作者的结论是「通用健康检查不大可能有益」。国家基本公共卫生服务项目给 35 岁及以上的常住居民每年免费测量一次血压，给 65 岁及以上的老年人每年免费提供一次健康体检。这次免费体检包含体格检查、血常规、尿常规、空腹血糖和心电图。肝功能查谷草转氨酶、谷丙转氨酶、总胆红素。肾功能查血清肌酐、血尿素。血脂查总胆固醇、甘油三酯、低密度脂蛋白胆固醇、高密度脂蛋白胆固醇。最后还有肝胆胰脾的腹部 B 超（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-19', 'concept_archive_s6-19', 'recommendation', '美国风湿病学会 2020 年的痛风指南讲到无症状高尿酸血症。它指的是血尿酸 &gt;6.8 mg/dL，而且以前没发作过痛风、皮下也没长痛风石。指南有条件地建议这些人不要开始吃任何降尿酸药。药包括别嘌醇、非布司他、丙磺舒。证据确定性评为「高」。表下面的脚注写明「按归因风险计算，需治疗 24 名患者 3 年才能预防一次痛风发作」。CKD-FIX 随机分组对照试验找了 363 人。他们是 3 期或 4 期慢性肾病，没有痛风史但有恶化风险。一组每天吃 100–300 mg 别嘌醇，一组吃安慰剂。试验做了 104 周。eGFR 是反映肾功能的指标，单位是 mL/min/1.73 m²。一组每年变化 -3.33（95% CI -4.11 到 -2.55）。另一组每年变化 -3.23（-3.98 到 -2.47）。两组相差 -0.10（-1.18 到 0.97），P=0.85，肾功能下降的速度一样快。严重不良事件 46% 对 44%。PERL 随机分组对照试验找了 530 名 1 型糖尿病合并早中期糖尿病肾病的人，吃 3 年别嘌醇，再停药 2 个月把药效洗掉。别嘌醇确实把血尿酸从 6.1 降到了 3.9 mg/dL。但停药之后，两组的肾功能指标 GFR 只差 0.001 mL/min/1.73 m²。这个差值的可信范围是 95% CI -1.9 到 1.9，P=0.99。尿里漏出的白蛋白，在吃别嘌醇那组反而高 40%（0 到 80）。它看起来划算，是因为「指标超标就该吃药压下去」这个直觉太顺', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-20', 'concept_archive_s6-20', 'recommendation', '意大利 MICOL 人群普查给 11,229 名 29 至 69 岁的人做了超声。查出 856 人有胆结石，其中 580 人没有症状，平均跟踪 8.7 年。这 580 人里，453 人（78.1%）一直没症状，61 人（10.5%）出现轻症状，66 人（11.4%）出现重症状。跟踪期内一共做了 189 例胆囊切除，其中 41.3% 做在没有症状的人身上。作者的结论是「期待治疗对多数患者仍是有效的处理方式」，期待治疗的意思是先观察、不动手术。美国一家 HMO 做过跟踪统计，HMO 是一种管理式医疗机构，691 名确诊胆结石的人，平均跟踪 78±61.6 个月。其中 135 名没有症状的人跟踪了 58±50.2 个月（中位数 46.3 个月），只有 10% 出现了胆结石的症状，7% 接受了手术。全组 50 例死亡里只有 2 例和胆道有关，而且都在有症状的那一组。作者的结论是「有无声结石的患者不需要在出现症状前手术」，无声结石就是不吭声、不发作的石头。英国 NICE 指南 CG188 第 1.2.1 条是这么写的。「对胆囊和胆道均正常、偶然发现无症状胆囊结石的人，应告知其在出现症状前不需要治疗」。欧洲肝病学会 2016 年的胆结石指南把两边的风险放在一起写。没症状的人每年约 0.7% 到 2.5% 出现症状。每年出急性胆囊炎、急性胰腺炎、梗阻性黄疸（胆道堵住、人发黄）或胆管炎的，是 0.1% 到 0.3%。第一次绞痛之后，并发症才升到每年 1% 到 3%，所以多数人出大事前会先疼一次。手术这边，瑞典全国登记的 51041 例胆囊切除里，1.5% 伤到了胆管。其中约五分之一（0.3%）是胆管部分或完全断开。伤到胆管的人一年内死亡率 3.9%，没伤到的是 1.1%。指南还写，切完以后有 10% 到 40% 的病人仍有不适，或者好了一阵又回来。指南的结论是：没症状的人做手术，不管开腹还是腹腔镜，都不延长寿命，因为手术本身的死亡和并发症风险超过了不切的风险。等出了症状再处理，总花费也更低。1983 年的一项测算给过具体数：30 岁男性预防性切除，比先观察平均少活 4 天，50 岁少活 18 天。切和不切，至今没有一项随机分组的试验比较过。预防性切除看起来划算，是因为「早晚要疼，不如趁年轻一次切了」这个直觉', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-21', 'concept_archive_s6-21', 'recommendation', '有一项做了 5 年的随机分组对照试验，找了 120 名反复长草酸钙结石、同时尿里钙又偏高（叫特发性高钙尿）的男性。他们被随机分成两组。一组正常吃钙，每天 30 mmol。这一组同时少吃动物蛋白（每天 52 g）、少吃盐（每天 50 mmol 氯化钠）。另一组吃传统的低钙饮食，每天 10 mmol。5 年里复发的是 12/60 对 23/60。没做校正的相对风险 0.49（95% CI 0.24–0.98，这是可信范围），P=0.04，正常吃钙那组的复发风险只有一半。跟踪期间，两组尿里的钙都降了大约每天 170 mg。但尿里排出的草酸不一样。低钙组平均每天升高 5.4 mg，正常钙组平均每天下降 7.2 mg。英国 NICE 指南 NG118 第 1.8.1 条写明，不要限制每天吃进去的钙。成年人保持每天 700 到 1,200 mg。儿童青少年按年龄每天 350 到 1,000 mg。戒钙看起来划算，是因为「结石是钙做的，那就少吃钙」这个直觉', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-22', 'concept_archive_s6-22', 'recommendation', '经典课堂实验显示，人人拿到的都是同一份笼统的「个人分析」，却普遍认为很准，这个现象叫巴纳姆效应。它解释了「戴上之后确实顺了」这种体验是从哪来的。那位作者的结论是「被本人接受不能证明解释正确」。官方案例：市场监管总局 2026 年 6 月 4 日公布了一批传统工艺市场「打假清源」典型案例。其中广东四会有一家珠宝店，在直播间里编造商品材质。它还假称商品有「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」等功效。这家店靠编剧本演戏来误导、欺骗消费者。这违反了反不正当竞争法第九条第一款（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-23', 'concept_archive_s6-23', 'recommendation', '一项荟萃分析（把很多项研究合起来算）共 259 项独立样本、753 个效应量。结果是：越看重物质的人，自己报告的幸福感越低。在最常用的那种多维量表上，相关系数 r = -0.19（校正后 ρ = -0.24）。只测「重视金钱」这一个方面的量表上，关联更弱，r = -0.08 到 -0.11。按看的是哪种结果分开看，强弱不一样。和冒险的健康与消费行为、对自己的负面评价关联最强，r = -0.28 到 -0.44。和生活满意度、负面情绪关联最弱，r = -0.13 到 -0.15。作者还做了中介分析（查中间通过什么传过去），结果提示这种负向关联可能是因为心理上的需要没有得到满足。另一项研究：两次面向不同人群的调查中，受访者都说为获得一段生活经历而花的钱比买东西更让自己快乐。随后的实验室实验里，回想一次为经历花钱之后的好心情，也高于回想一次买东西（全国口径不适用，这两项用的都是国外样本）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-24', 'concept_archive_s6-24', 'recommendation', '美国全国家庭与住户调查（NSFH）两轮回访了同一批人。作者把这份数据和本地平均收入对上。本地平均收入（PUMA）是按 1990 年人口普查 5% 抽样推算出来的。把本人收入和一系列个人特征都扣掉之后，结果是：邻居收入越高，自己报告的幸福感越低。这个效应大，换一种算法也稳，而且高度显著。作者的表述是，「邻居收入上升」和「本人收入下降同样幅度」带来的幸福感下降处于同一数量级。改成同一个人前后自己跟自己比之后（这叫加个体固定效应），系数方向不变、大小也相近，只是显著性降到了 10% 的水平。再限定在同一个州、同一轮调查之间比（这叫加州和调查轮次的固定效应），结果基本不变。这说明它不是「爱搬去穷地方的人本来就更快乐」造成的，也不是州一级某些没测到的因素造成的。效应在常和邻居来往的人身上更强，在只和社区外朋友来往的人身上不显著。租房的人和自己有房的人没有差异，这一点不支持「贵地方房价高，所以实际可花的钱少」这种解释。幸福感只随学历相同的邻居的收入而下降，对学历不同的邻居的收入几乎没有反应。而且它主要是通过「对自己物质处境的满意度」传过去的，不是通过对家庭生活等其他方面的满意度。最后，如果本人和邻居的收入按同样比例一起上升，幸福感仍然上升', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-25', 'concept_archive_s6-25', 'recommendation', '一项多实验室预注册重复研究，23 个实验室、共 2141 名受试者，按 Sripada 等人的标准化方案重做了序贯任务范式：先做一件消耗自控的任务，再做第二件需要自控的任务。汇总结果显示自我损耗效应很小，而且 95% 可信区间包含 0（d = 0.04，95% CI −0.07 到 0.15）。作者据此讨论了「自控是有限资源」这一模型还成不成立。另一次同样事先登记方案的重做，36 个实验室、3531 人，效果大小 d = 0.06，同样小到不能算数。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-26', 'concept_archive_s6-26', 'recommendation', '先看「不吃早餐会让人后面吃更多」这个说法。一篇荟萃分析把 13 项随机试验合起来算。被分到吃早餐那组的人，每天摄入比不吃早餐那组多 259.79 kcal（95% CI 78.87–440.71，这是可信范围）。体重高 0.44 kg（0.07–0.82）。不吃早餐的人并没有在午饭晚饭补回来。这些试验跟踪时间都很短，看体重的平均 7 周，看摄入的平均 2 周。再看 16:8 这类只在固定几小时内吃饭的做法。一项让 116 名超重成人做 12 周。只在中午 12 点到晚上 8 点吃饭的那组，和每天规律吃三顿的那组，体重差 −0.26 kg（−1.30 到 0.78），不显著。另一项在广州做，139 名肥胖患者，跟踪 12 个月。限时进食加控制热量，比单纯控制热量多减 1.8 kg（−4.0 到 0.4），也不显著。最后看长期不吃早餐有没有害。238 万人的汇总里，不吃早餐的人心血管病风险高约 17%（OR 1.17，1.09–1.26），心血管死亡高约 49%（OR 1.49，1.20–1.84）。但这些是只记录、不分组的研究。跟踪 17 到 23 年的那项原始研究里，全因死亡的风险比是 1.19，可信范围 0.99 到 1.42，跨过了 1，算不上有差别。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-27', 'concept_archive_s6-27', 'recommendation', '先看身体。美国一项研究跟踪了 31925 名男性，到 2010 年。每个人自己报告每月射精几次，再按次数分组。和每月 4 到 7 次的人比，每月 21 次以上的人前列腺癌 HR 0.81（95% CI 0.72–0.92，低约 19%），这是按 20 到 29 岁时的次数算的。按 40 到 49 岁时的次数算，HR 0.78（0.69–0.89，低约 22%）。少掉的主要是低危的前列腺癌。反方是英国一项病例对照研究，比了 431 名 60 岁前确诊的患者和 409 名对照。二三十岁时手淫频繁的人风险偏高，五十多岁时频繁的人风险偏低。再看色情内容。一篇系统综述加荟萃分析认为，很多人觉得自己「上瘾了」，更多是行为和自己信的道理对不上，不只是看得多（美国 / 英国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-27"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-28', 'concept_archive_s6-28', 'recommendation', '美国心理学会 2009 年的工作组报告说，改变性取向的努力「不太可能成功，并且有一定的伤害风险」。对把未成年人送进强制或住院式的矫正项目，报告建议父母和孩子都不要考虑。美国一项全国代表性调查访问了 1518 名性少数成年人，约 7% 做过矫正，其中八成来自宗教人士。扣除年龄、童年不幸经历等因素后，做过矫正的人一生中有过自杀念头的 OR 1.92（95% CI 1.01–3.64，高约九成）。计划过自杀的 OR 1.75（1.01–3.06）。没受伤或受轻伤的自杀尝试 OR 1.88（1.01–3.50）。另一项研究访问了 245 名 21 到 25 岁的年轻人。青春期没被矫正过的，22.0% 试过自杀。父母自己试图改变孩子性取向的，是 48.1%。父母还把孩子送去找治疗师或宗教人士的，是 62.8%。世界卫生组织的疾病分类 ICD-10 写明：「性取向本身不被视为一种障碍」。2017 年河南驻马店驿城区法院审了一个案子：精神病院以「性偏好障碍」为名强制收治一名男子。法院认为他「病情一般，也无自杀、伤人、毁物等行为或危险，不符合应当强制治疗的条件」。法院判医院公开道歉，赔精神抚慰金 5000 元（美国 / 中国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-28"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-29', 'concept_archive_s6-29', 'recommendation', '先看培训。Cochrane 系统综述 2011 年版汇总了 9 项随机分组的试验，共 20101 名员工。其中 7 项试验、19317 人的结果是：上过搬运培训的人和什么都没做的人，后来报告的腰痛差不多（OR 1.17，95% CI 0.68–2.02，可信范围跨过 1）。和只看了一段视频的人比，RR 0.93（0.69–1.25），也差不多。证据质量是中等。作者的结论是，搬运建议和培训不管配不配搬运工具，都防不住腰痛和腰痛造成的失能。再看弯腰。2020 年一篇系统综述汇总了搬东西时腰弯多少的研究，证据质量低。唯一一项跟踪研究里，后来腰痛和没腰痛的人，搬东西时腰最多弯的角度只差 1.5 度（−0.7 到 3.7），不显著。11 项研究里有 9 项没看到两组有差别。另有 7 项研究换了一种量法，腰痛的人搬东西时腰反而少弯 6.0 度（−11.2 到 −0.9）。作者的结论是，没有证据说腰弯得多会招来腰痛。最后看该怎么做。一篇荟萃汇总了 8 项跟踪研究：每次搬的东西每重 10 公斤，腰痛风险 OR 1.11（1.05–1.18，高约 11%）。每天每多搬 10 次，OR 1.09（1.03–1.15，高约 9%）。另一篇汇总了 21 项随机试验、30850 人。锻炼加讲解让腰痛发作的风险 RR 0.55（0.41–0.74，低约 45%），证据质量中等。单靠锻炼 RR 0.65（0.50–0.86，低约 35%），证据质量低到很低。单靠讲解 RR 1.03（0.83–1.27），护腰带 RR 1.01（0.71–1.44），都看不出效果。英国健康与安全执行局（HSE）的官方指南也写明：单靠培训保证不了搬运安全，好的搬运手法也替代不了配搬运工具、改进任务和货物。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s6-29"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s6-30', 'concept_archive_s6-30', 'recommendation', '先看维生素 D。2023 年一篇系统综述收了 14 项研究、2734 名骨折病人。作者的结论是，单补维生素 D 对骨头愈合、长没长上和恢复后的功能影响很小。看出好处的几项研究，质量普遍偏低。作者写明，只算随机分组的试验，没有一项看出补了有好处。其中一项找了 100 名维 D 偏低的长骨骨折病人。一半人伤后两周内一次吃 10 万 IU，一半人吃安慰剂（假药）。两边各有 2 人骨头没长上，合起来是 4%。另一项找了 102 名 18 到 50 岁的大腿骨或小腿骨骨折病人，分四组吃不同剂量或安慰剂。3 个月和 12 个月时，愈合评分都没看出差别。还有一项找了 32 名手腕骨折的绝经后女性。和不补的人比，每天折合 1800 IU 的大剂量组，骨头的抗压硬度反而更低。再看钙。2014 年一篇系统综述说，维 D 不足或补维 D 对骨折愈合影响的临床研究很少，结论说不清。它找到的两项研究是钙和维 D 一起补，看到的是骨折处骨密度或骨痂（新长出来的骨头）多了，没看愈合快慢。最后看骨头汤。台湾高雄一项测定买了三种骨头汤面食，一份汤 450 到 550 克。每份汤里的钙平均 14 到 39 毫克，占每天 1000 毫克推荐量的 1.4% 到 3.9%。作者的结论是，一份汤的钙不到每天推荐量的 5%。中国的推荐量是 18 到 49 岁每天 800 毫克，50 岁以上 1000 毫克，每天上限 2000 毫克。这份标准写明，长期吃过量的钙会增加得肾结石的风险。美国一项试验找了 36282 名绝经后女性，每天吃 1000 毫克钙加 400 IU 维 D，平均跟踪 7 年。肾结石风险高约 17%（HR 1.17，95% CI 1.02–1.34，可信范围）。髋部骨折低约 12%，但不显著（HR 0.88，0.72–1.08）。它看起来划算，是因为「骨头是钙做的，多吃钙就长得快」这个直觉', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s6-30"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-1', 'concept_archive_s7-1', 'recommendation', '要同时满足三个条件。一是单位和你本人交失业保险累计满 1 年。二是不是你自己主动提的辞职（法律叫「非因本人意愿中断就业」）。三是已经办了失业登记，并且有找工作的意愿。能领多久按缴费年限算。累计满 1 年不足 5 年，最长领 12 个月。满 5 年不足 10 年，最长 18 个月。10 年以上，最长 24 个月。每月发多少由省级政府定，各省不一样。金额低于当地最低工资，高于城市低保。国家的目标是逐步提到最低工资标准的 90%。领失业保险金这段时间，你照样参加职工基本医疗保险、享受基本医疗保险待遇。该交的那笔基本医疗保险费从失业保险基金里出，你个人不交（全国，条例 1999 年起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-2', 'concept_archive_s7-2', 'recommendation', '第一步是投诉。拨 12333，或者去当地人社局的劳动监察投诉。法律规定立案后 60 个工作日内查完，案情复杂的可以再延 30 个工作日。查实了，能责令公司限期把钱付掉。过了期限还不付的，要按该付金额的 50% 到 100% 再加付一笔赔偿金。2024 年全国监察机构查处 13.7 万件，为 65.4 万人追回工资 86.5 亿元。手上有欠条或者工资表、欠薪事实清楚的，还可以直接向基层法院申请支付令。支付令就是法院给公司下的付款命令，法院受理后 15 日内发出。第二步是申请仲裁。法律规定受理后 45 日内结案，可以再延 15 日。讨工资的可以申请先予执行：不等案子全部审完，先执行一部分。欠的钱不超过当地月最低工资 12 倍的，属于一裁终局：仲裁裁完就算定了，公司不能再起诉。2024 年全国办理 425.7 万件，办结 415.6 万件。结案金额 934.7 亿元。调解成功率 79.6%，仲裁结案率 98.2%，仲裁终结率 73.7%。有人说这事要拖「半年一年」，说的是仲裁之后又打到法院去的那部分案子：一审 6 个月（走简易程序的 3 个月），再加二审 3 个月。2024 年法院审结追索劳动报酬案 8.8 万件、追回 285.4 亿元，998 人因拒不支付劳动报酬罪获刑（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-3', 'concept_archive_s7-3', 'recommendation', '国务院的条例里写明了民事法律援助管哪六类事。条例的原话是：「依法请求国家赔偿的；请求给予社会保险待遇或者最低生活保障待遇的；请求发给抚恤金、救济金的；请求给付赡养费、抚养费、扶养费的；请求支付劳动报酬的；主张因见义勇为行为产生的民事权益的」。说白了就是：要国家赔偿，要社保或低保待遇，要抚恤金救济金，要赡养费抚养费，讨工资，见义勇为受了损失。刑事案件这边，可能判处死刑的被告人，以及盲、聋、哑和未成年的被告人，不看经济状况一律指派律师', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-4', 'concept_archive_s7-4', 'recommendation', '救助站提供符合卫生要求的食物和住处。在站里突发急病的，送医院治。还会帮你联系亲属和单位。没钱买票回户籍地或者住所地的，发乘车（船）凭证，就是车票船票。户籍地就是老家，住所地就是现在常住的地方。救助期限一般不超过 10 天。等家人来接、等治疗、等安置的，可以延长。公安和其他行政机关的人执行职务时碰上流浪乞讨人员，应当告诉他可以去求助。对残疾人、未成年人、老年人和行动不便的人，要引导护送过去（全国，2003 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-5', 'concept_archive_s7-5', 'recommendation', '法律规定下面这几样一律免费：就业政策咨询；哪里在招人、哪里缺人的信息；职业指导和职业介绍；办就业登记和失业登记；对就业困难人员的就业援助。这些机构不得从事经营性活动，不许靠这些服务赚钱。零工的求职招聘信息，登记和发布也免费向社会提供，已经纳入公共就业信息服务的范围。对待工时间长的人（就是长期接不到活的）、低收入家庭等困难零工人员，还要加强帮扶（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-6', 'concept_archive_s7-6', 'recommendation', '两类家庭可以拿临时救助。一类是因为意外事件、家庭成员突发重大疾病这些原因，连吃住看病这些最基本的开销都一时撑不住的家庭。另一类是非花不可的开销突然增加、超出自己承受能力的低保家庭。救哪些事、给多少钱，由县级以上地方政府自己定并公布（全国制度，金额地方定，2014 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s7-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-7', 'concept_archive_s7-7', 'recommendation', '全家收入除以人数，低于当地低保标准，家里财产也在规定范围内的，可以拿低保。2024 年末，全国城市低保平均标准是 798.1 元/人·月，农村是 593.9 元/人·月。城市低保保障 625.0 万人，农村保障 3361.5 万人。低保金按差额按月发：当地低保标准减去家庭人均收入。比如当地标准 798.1 元，家里每人每月收入 500 元，每人每月领的是 298.1 元，不是 798.1 元。低保标准这么定：拿当地上年度居民人均消费支出，乘以一个量化比例，隔一段时间再调一次。说白了就是拿当地上一年平均每人花掉多少钱，打个折算出来（全国平均，各地不同）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-8', 'concept_archive_s7-8', 'recommendation', '国务院定下了两项补贴。第一项是困难残疾人生活补贴，文件写的对象是「低保家庭中的残疾人，有条件的地方可逐步扩大到低收入残疾人及其他困难残疾人」。意思是先保低保家庭里的残疾人，地方财力允许的可以往外扩。第二项是重度残疾人护理补贴，文件写的对象是「残疾等级被评定为一级、二级且需要长期照护的重度残疾人」。这两项可以同时领', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-9', 'concept_archive_s7-9', 'recommendation', '除了自己交的那部分，财政再按人头补一笔。2024 年不低于 670 元，2025 年比上年提高 30 元，不低于 700 元，个人缴费仍是不低于 400 元（医保发〔2025〕22 号，按省级文件转述）。2026 年的政府工作报告里说再提高 24 元。低保对象和特困人员，符合规定的医疗费，医保报完之后剩下的部分，还能按不低于 70% 的比例走医疗救助再报一次。断缴的代价是等待期。没在集中缴费期参保、或者没连着交的，交完之后有 3 个月固定待遇等待期，这段时间看病不给报。每多断 1 年，原则上再加 1 个月（2025 年起，全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-10', 'concept_archive_s7-10', 'recommendation', '国家把基本医保、大病保险、医疗救助合起来叫「三重制度」，一层一层往下兜。低保对象和特困人员，符合规定的医疗费用按不低于 70% 救助。本来不穷、看病看穷了的重病患者，可以自己提出申请再救助。跨省住院前备了案，就能出院直接结算，不必先垫全款再回参保地报。生病停工有 3 到 24 个月的医疗期，具体多久按工龄长短定。这段时间里，公司不得解除劳动合同，病假工资不得低于当地最低工资的 80%。工伤职工有停工留薪期，就是养伤不上班的那段时间，原来的工资福利照发，由单位按月发，一般不超过 12 个月。信用卡欠款超出还款能力、本人又愿意还的，可以和银行协商个性化分期，把欠款重新排一个还款计划，最长 5 年，签了协议银行就必须停止催收。网上替本人筹钱的个人求助平台，必须经国务院民政部门指定。平台要核验求助信息是不是真的。捐来的钱只能打给求助人本人，或者他提供的账户（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-11', 'concept_archive_s7-11', 'recommendation', '从你交上《居民身份证申领登记表》那天算起，公安机关要在 60 日内发证。新办、换证、补办的这段时间里，如果急着用证，可以申请一张临时居民身份证。公安机关收到申请后 3 日内发放，有效期 3 个月（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-12', 'concept_archive_s7-12', 'recommendation', '认定下来之后，没有单位、自己交社保的（这叫灵活就业）可以拿社保补贴。补贴标准原则上不超过你实际交的 2/3，最长拿 3 年。被单位招用、或者被安排到公益性岗位的，单位按实际缴纳的养老、医疗、失业保险费拿补贴。公益性岗位就是政府出钱开发的岗位，它的补贴参照当地最低工资。政府开发的公益性岗位，优先安排就业困难人员。另外还有一次性求职补贴，发给高校毕业生。范围是低保家庭、零就业家庭、特困人员里的毕业生。残疾的、拿过国家助学贷款的毕业生也算。这笔钱在毕业那一学年领（全国框架，认定条件与金额地方定）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s7-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-13', 'concept_archive_s7-13', 'recommendation', '财政部、人社部的规章里列了一批就业补助资金项目，就是财政专门拿来补贴就业的那笔钱。参加培训并拿到符合规定的证书，给职业培训补贴，同一个人最多领 3 次。就业困难人员自己交社保（灵活就业）的补贴最长 3 年；离法定退休年龄不到 5 年的，可以延到退休。高校毕业生自己交社保的补贴最长 2 年，被企业招走的最长 1 年。毕业 2 年内没找到工作的高校毕业生，还有 16 至 24 岁的失业青年，可以参加就业见习，见习期间领基本生活费', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-14', 'concept_archive_s7-14', 'recommendation', '把 47 项做过对照的求职辅导研究合并起来算。这些研究是实验或者准实验设计，都分了组做比较。结果是：参加辅导的那组，找到工作的几率是没参加那组的 2.67 倍（OR 2.67，即几率之比）。辅导里管用的成分有这几样。一是教求职技巧。二是改善自我呈现（把自己讲清楚）。三是提升自我效能（相信自己做得到）。四是鼓励主动出击。五是设定目标。六是争取社会支持（开口找人帮忙）。既教技能、又能提起劲头的辅导，效果最大', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-15', 'concept_archive_s7-15', 'recommendation', '公司不得扣押你的身份证等证件，不得要你找人担保，也不得换个名目收你的钱和物。违反的责令退还，并按每人 500 元以上 2000 元以下罚款。职业中介同样不得扣证件、收押金，工作没介绍成，必须把中介费退给你。打着招聘的名义，诱导你先交培训费或者先贷款，这是人社部等五部门点名提示的「招转培」「培训贷」骗局。靠拉人头算提成、交了钱才能加入的，属于传销，参加的人可罚 2000 元以下。民间借贷的利息，超过签合同时一年期 LPR 4 倍的那部分，法院不支持。这条新规矩取代了原来按 24%、36% 两条线划三段的老办法（全国，2020 年 8 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-16', 'concept_archive_s7-16', 'recommendation', '三项条件都占上就能申请。一是在本地没有住房，或者住房面积低于规定标准。二是收入和财产低于规定标准。三是外来务工人员要在本地稳定就业满规定年限。具体条件由直辖市和市、县的住房保障部门定了公布。登记上排队名单的人叫轮候对象，住房保障部门应当在轮候期内给他安排房源（全国框架，门槛和租金地方定，2012 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s7-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-17', 'concept_archive_s7-17', 'recommendation', '2025 年，全国居民平均每人一年花掉 29476 元（这叫人均消费支出）。其中食品烟酒 8631 元，占 29.3%。居住 6397 元，占 21.7%。两项加起来过半，所以压这两项最有效。老年助餐服务面向全体老年人开展，形式有老年食堂、老年餐桌、助餐点，困难老人另有差异化补贴。作个参照：截至 2026 年 1 月 1 日，各省第一档月最低工资最低是青海 2080 元，最高是上海 2740 元（全国，2025 至 2026 年）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s7-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-18', 'concept_archive_s7-18', 'recommendation', '基本养老保险按累计缴费年限算，中间断过也不清零。到法定退休年龄，累计满 15 年就能按月领养老金。不够的，可以接着缴到满 15 年。换个地方就业的（正式说法是跨统筹地区），养老关系跟着人走，缴费年限接着往上累计。职工医保累计缴费达到国家规定年限的，退休后不用再交。居民医保断缴的代价是等待期：重新交上之后，有一段时间看病不给报（居民医保见第 9 条）（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-19', 'concept_archive_s7-19', 'recommendation', '刑满释放人员依法享有与其他公民平等的权利，在就业、就学和享受社会保障方面不受歧视。生活困难的，由户籍地或者居住地政府帮助安置、依法救助帮扶（监狱法 2026 年修订，11 月 1 日起施行）。中央 2010 年的文件要求对他们强化职业培训，符合条件的纳入低保，还要建立过渡性安置基地。犯罪时不满 18 岁、并且判刑 5 年以下的，犯罪记录封存，当兵、找工作时不必报告；本人申请无犯罪记录证明的，3 个工作日内出具。上失信名单的期限是 2 年。钱还清了，或者和对方达成和解等情形下，法院应在 3 个工作日内把名字删掉。深圳经济特区个人破产条例是目前唯一的个人破产法规，宣告破产后熬满 3 年考察期，没还完的债可以免掉。企业法人还不上到期的债、欠的又比有的多（这叫资不抵债），可以申请重整、和解或者破产清算，债随着这家企业一并了结（全国，个人破产仅深圳）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-20', 'concept_archive_s7-20', 'recommendation', '官方把这类产品分成两种。医疗保险按你实际花掉的医疗费报销。疾病保险是一确诊合同里约定的那些病，就按约定的数额直接赔一笔钱。两者补的都是医保报完之后自己要掏的那部分，以及停工的损失。保险期间在一年及以下、条款里又没写保证续保的，属于短期健康险。超过一年的，或者写了保证续保的，才是长期健康险。「保证续保」的意思是：到期续保时，公司必须按原来的条款和约定的费率接着保。保险公司不得诱导同一个人重复买保障功能相同或者类似的费用补偿型医疗险。买两份，同一笔钱也只能报一次。重疾险的疾病定义有行业统一规范，包括 28 种重度疾病和 3 种轻度疾病。恶性肿瘤、急性心肌梗死、脑中风后遗症是核心病种（全国，2019、2020 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s7-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-21', 'concept_archive_s7-21', 'recommendation', '能撑过一夜，有厕所，也能充电。没有官方数字', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s7-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s7-22', 'concept_archive_s7-22', 'recommendation', '劳动合同法第二条把用人单位限定为企业、个体经济组织、民办非企业单位等组织，自然人不在其中。最高法的劳动争议司法解释列了几种不属于劳动争议的纠纷。一是家庭或者个人与家政服务人员之间的纠纷。二是个体工匠与帮工、学徒之间的纠纷。三是农村承包经营户与受雇人之间的纠纷。这几种要去法院按普通民事纠纷起诉，诉讼时效 3 年。没有营业执照的用人单位不在这个例外里。劳动合同法第九十三条规定，不具备合法经营资格的用人单位，劳动者已经付出劳动的，该单位或者其出资人应当支付劳动报酬、经济补偿、赔偿金。该解释第二十九条规定，劳动者与未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位发生争议的，应当将用人单位或者其出资人列为当事人。劳动保障监察条例第三十三条规定，对无营业执照或者已被依法吊销营业执照、有劳动用工行为的，由劳动保障行政部门实施劳动保障监察。个人承包经营违法招用劳动者、给劳动者造成损害的，发包的组织和个人承包经营者承担连带赔偿责任（劳动合同法第九十四条）。建设单位或者施工总承包单位把工程发包、分包给个人或者不具备合法经营资格的单位，导致拖欠农民工工资的，由建设单位或者施工总承包单位清偿（保障农民工工资支付条例第三十六条）（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s7-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-1', 'concept_archive_s8-1', 'recommendation', '跑了的那一方，要承担这次事故的全部责任。只有你能证明对方也有错，责任才可能减轻一点。跑了还要吊销驾驶证，而且这辈子都不能再考。如果这起事故构成交通肇事罪，跑了判 3 到 7 年。如果因为跑了导致人死亡，判 7 年以上。保险也不管：商业车险里的车损险和三者险，遇上「交通肇事逃逸」「故意破坏、伪造现场、毁灭证据」一律不赔，几十万的赔偿要你自己全掏（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-2', 'concept_archive_s8-2', 'recommendation', '公安机关有权对涉案的资金做即时查询、紧急止付、快速冻结。银行和支付机构必须配合。冻结住的钱，按程序返还给被害人。钱一旦被转走、分散开，追回的概率大幅下降，所以止付越早越有效。96110 是全国统一的反诈预警热线，来电是警方在劝阻你，务必接（全国，2022 年 12 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-3', 'concept_archive_s8-3', 'recommendation', '法律要求政府和有关部门把各类电信网络诈骗的手法讲给大家。公安机关会同金融、电信、网信部门建立预警劝阻系统，发现可能要被骗的人就及时劝阻。96110 就是这条全国统一的预警劝阻热线，来电要接。公安部 2026 年 6 月通报，最高发的 10 类诈骗占了全部电诈案件的 85%。刷单返利发案最多，占 25%。虚假网络投资理财损失最大，约占全部损失的 40%。福建省公安厅逐类拆解的识别特征如下。刷单返利：「喊你一起赚钱的大概率是想赚你的钱」，任务单做不完就不退本金。虚假投资理财：群里「水军」晒收益，先给小额返利再让你加大投入，提现要「缴税」。网络贷款：「贷款并不需要交保证金、做银行流水账，一旦遇上了，一定是假的」。冒充客服：说你开了会员要自动扣费、影响征信，逼你转账取消。冒充公检法：「公检法机关不存在所谓的『安全账户』，凡是通过电话、QQ、微信、网络等办案、做笔录的『公检法机关』，都是诈骗」。杀猪盘：「对于从未见过面，只见到照片或者视频的『恋人』，不可轻信」，永远不视频不见面却常有急事要钱。色诱刷单：约见面先「做任务」，钱越交越多。事前认出来，比事后止付便宜得多。止付能追回多少，取决于报警时钱还在不在账上，止付怎么做见第 2 条（打 110 或 96110 要求止付）（全国，2022 年 12 月起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-4', 'concept_archive_s8-4', 'recommendation', '公安部网安局给了三条办法。第一条是动作验证：请对方做一个连贯的转头动作，或者用手掌完全遮住脸再快速移开。原文说「目前的 AI 技术在模拟这些复杂的面部遮挡和光影变化时，容易出现卡顿、模糊或扭曲」。第二条是听声音细节：「AI 生成的语音有时会缺乏自然的呼吸停顿、情感起伏，或者带有轻微的机械感、背景杂音异常」。第三条是多渠道核实。原文说这是「最核心的一招」：「挂断后直接拨打对方常用且你熟悉的电话号码（不要回拨可疑来电号码），或者通过你们共同认识的第三人进行侧面核实」。口诀是「视频语音莫轻信，动作验证多核实」。法律上，换脸换声早就被禁止用于诈骗。人脸生成、人脸替换、合成人声、仿声这几类服务，平台必须打上显著标识。任何组织和个人不得恶意删除、篡改、伪造、隐匿这个标识。但守规矩的是平台，骗子不会加，所以「没看到 AI 标识」不能反过来当成对方是真人的证据。公安部刑侦局公布过一起案件。14 人团伙被查获合成动态人脸视频 5 万多条，公民个人信息 50 多万条。警方还扣押了云服务器 60 台（全国，标识义务自 2025 年 9 月 1 日起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-5', 'concept_archive_s8-5', 'recommendation', '从第一次讯问起，或者从被采取强制措施（被限制人身自由）起，你就有权委托律师。案子还在公安手里侦查的这一段，只能委托律师，不能请律师以外的人当辩护人。律师提出会见，看守所最迟 48 小时内安排，会见不被监听。不得强迫任何人证实自己有罪。和本案无关的问题，你有权拒绝回答。传唤、拘传一次最长 12 小时，特别重大复杂的最长 24 小时。传唤是通知你去问话，拘传是强制把你带去问话。不得连着传唤，把人变相关住。捏造事实诬告别人、想让他被追究刑事责任的，判 3 年以下，造成严重后果的判 3 到 10 年。被拘留、逮捕之后又撤案、不起诉或者判无罪的，可以申请国家赔偿，每天按上一年度全国职工日平均工资计算（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-6', 'concept_archive_s8-6', 'recommendation', '刑法第六十七条：犯罪以后自动投案、如实供述自己罪行的，是自首。对自首的，可以从轻或者减轻处罚，其中犯罪较轻的可以免除处罚。没有投案但如实供述自己罪行的（坦白），可以从轻处罚；因如实供述避免特别严重后果发生的，可以减轻处罚。两高的量刑指导意见给了明码幅度。基准刑就是先按案情算出来的那个刑期，下面的百分比都在它之上往下减。自首可以减少基准刑的 40% 以下，犯罪较轻的可以减少 40% 以上或者依法免除处罚。坦白里，如实供述自己罪行的减少 20% 以下，如实供述司法机关尚未掌握的同种较重罪行的减少 10% 到 30%，因如实供述避免特别严重后果发生的减少 30% 到 50%。认罪认罚减少 30% 以下，同时有自首、重大坦白、退赃退赔、赔偿谅解等情节的减少 60% 以下，犯罪较轻的减少 60% 以上或者依法免除处罚。追诉期限按法定最高刑分四档：5 年、10 年、15 年、20 年（刑法第八十七条）。但刑法第八十八条写明，检察院、公安机关、国家安全机关立案侦查，或者法院受理案件以后，逃避侦查或者审判的，不受追诉期限的限制（全国，量刑幅度自 2021 年 7 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-7', 'concept_archive_s8-7', 'recommendation', '酒后驾车，暂扣驾驶证 6 个月，罚 1000 到 2000 元。再犯的，拘留 10 日以下并吊销驾驶证。醉驾直接吊销驾驶证，5 年内不得重考，并按危险驾驶罪追究刑事责任，判拘役并罚钱，拘役就是短期关押。开营运车的更重：酒驾拘留 15 日、罚 5000 元、5 年禁驾；醉驾 10 年禁驾，而且这辈子不能再开营运车。酒后或者醉驾造成重大事故、构成犯罪的，终生禁驾。商业车险对饮酒、吸毒后驾车一律不赔（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-8', 'concept_archive_s8-8', 'recommendation', '出租、出借、买卖电话卡、银行账户、支付账户、互联网账号，这件事本身就是违法。没收违法所得，再罚违法所得的 1 到 10 倍。没有违法所得的，最高罚 20 万元。情节严重的，拘留 15 日以下。还可能被记入信用记录、限制账户功能、停掉非柜面业务（只能去柜台办）。明知别人用网络实施犯罪，还给他提供支付结算这类帮助，情节严重的，构成帮助信息网络犯罪活动罪（简称帮信罪），判 3 年以下并处罚金（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-9', 'concept_archive_s8-9', 'recommendation', '行政法规写着「个人信息主体有权每年两次免费获取本人的信用报告」，你每年可以免费查自己两次。不良信息的保存期限是「自不良行为或者事件终止之日起为 5 年；超过 5 年的，应当予以删除」。对报告有异议的，你可以提出来，征信机构或者提供这条信息的机构应当在收到异议之日起 20 日内书面答复你', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-10', 'concept_archive_s8-10', 'recommendation', '殴打他人或者故意伤害的，拘留 5 到 10 日，并罚 500 到 1000 元。结伙打、打老人孕妇儿童残疾人、多次打人或者一次打多人的，拘留 10 到 15 日，并罚 1000 到 2000 元。结伙斗殴按寻衅滋事处理，最高拘留 15 日并罚 2000 元，寻衅滋事就是无事生非、起哄闹事。故意伤害他人身体、构成犯罪的，判 3 年以下；把人打成重伤的，判 3 到 10 年。两个人对着打，法律上叫相互斗殴，不算正当防卫。但如果对方先动手、手段又明显过激，或者你已经努力躲开、对方还接着打，你还击一般会被认定为防卫。还手过了头才叫防卫过当，要同时满足两条：明显超过必要限度，并且造成重大损害。就算真的过当，也应当减轻或者免除处罚（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-11', 'concept_archive_s8-11', 'recommendation', '刑法规定了什么算正当防卫。国家、公共利益、自己或者别人的人身、财产和其他权利，正在被不法侵害。这时候动手制止、把正在侵害的人打伤，属于正当防卫，不负刑事责任。同一条还写着：「正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚」。另有一款：「对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任」。两高一部的指导意见把边界说得更细。认定防卫过当，要同时具备「明显超过必要限度」和「造成重大损害」两条，缺一不可。「造成重大损害」是指把不法侵害人打成重伤或者打死，造成轻伤以及更轻的伤不算。只有不法侵害人确实已经失去侵害能力，或者确实已经放弃侵害，才算侵害结束。防卫必须针对不法侵害人本人。对显著轻微的不法侵害，在看得出来只是轻微侵害的情况下，直接用足以致人重伤或者死亡的方式制止的，不认定为防卫行为。过程成本有官方案例。检例第 47 号于海明案：2018 年 8 月 27 日当晚，公安以「故意伤害案」立案侦查。9 月 1 日，昆山市公安局依据刑法第二十条第三款认定为正当防卫，撤销了案件。检例第 45 号陈某案：一名学生被 9 人围殴，持刀反击致 3 人重伤。公安以涉嫌故意伤害立案侦查，把他刑事拘留。检察机关认定属于正当防卫，不批准逮捕，公安才把人放了。被拘留之后公安认为需要逮捕的，应当在 3 日内提请检察院审查批准（报检察院批不批捕）。特殊情况可以延长 1 至 4 日。流窜作案、多次作案、结伙作案的重大嫌疑分子，可以延长到 30 日。检察院再在 7 日内作出决定（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-12', 'concept_archive_s8-12', 'recommendation', '法定路径有官方数字。2024 年全国劳动监察查处 13.7 万件，为 65.4 万人追回工资 86.5 亿元。还有 998 人因为拒不支付劳动报酬罪获刑。欠薪怎么投诉劳动监察、怎么申请劳动仲裁，见第 7 节第 2 条。报复路径的价目写在刑法第二百三十二条：「故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑」。官方案例：徐某金考试不合格，没拿到毕业证书，又对实习报酬不满。2024 年 11 月 16 日，他回无锡工艺职业技术学院持刀行凶，致 8 人死亡、17 人受伤。一审以故意杀人罪判处死刑、剥夺政治权利终身，2025 年 1 月 20 日经最高人民法院核准执行。他不满的是学校和那笔报酬，受害的却是同学，那笔报酬他也一分没拿到（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-13', 'concept_archive_s8-13', 'recommendation', '刑法第一百一十四条：「放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑」。一个人都没伤着，也是三年起。第一百一十五条：致人重伤、死亡，或者使公私财产遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。官方案例：樊维秋因为婚姻破裂、生活失意，又不满离婚财产分割的结果，「决意通过驾车冲撞人群方式发泄私愤」。2024 年 11 月 11 日晚，他驾车冲入珠海市体育中心正在锻炼的人群，致 35 人死亡、43 人受伤。一审以以危险方法危害公共安全罪判处死刑、剥夺政治权利终身，2025 年 1 月 20 日经最高人民法院核准执行。被撞的是他不认识的跑步者（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-14', 'concept_archive_s8-14', 'recommendation', '这类念头到动手的窗口很短。对 82 名自杀未遂者在入院三天内做的访谈里，47.6% 的人说，从第一次冒出念头到实施不超过 10 分钟。一项 10 年系统综述（把十年间的研究合起来梳理一遍）认为，限制致死手段的证据在持续增强。镇痛药管控之后，与之相关的自杀下降 43%。跳楼热点加了防护之后，自杀下降 86%（79% 到 91%）。把方向盘、刀、燃气阀、绳子隔开一步，等的就是这十分钟过去。12356 是全国统一心理援助热线，每天接听不少于 18 小时（全国，2025 年 5 月 1 日起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-15', 'concept_archive_s8-15', 'recommendation', '精神卫生法第二十八条第二款写着：「疑似精神障碍患者发生伤害自身、危害他人安全的行为，或者有伤害自身、危害他人安全的危险的，其近亲属、所在单位、当地公安机关应当立即采取措施予以制止，并将其送往医疗机构进行精神障碍诊断」。同一条还规定：「医疗机构接到送诊的疑似精神障碍患者，不得拒绝为其作出诊断」。第二十九条要求医院把这类送来的人留在院里，立即指派精神科执业医师诊断，并及时出具结论。第三十条规定，住院治疗以自愿为原则。但有一种例外：诊断结论表明是严重精神障碍患者，而且「已经发生危害他人安全的行为，或者有危害他人安全的危险的」。这一类应当对他实施住院治疗，不以本人同意为前提。扬言伤人本身就可以直接报 110。写恐吓信，或者用其他办法威胁他人人身安全的，拘留 5 日以下或者罚 1000 元以下。扬言要实施放火、爆炸、投放危险物质等危害公共安全的犯罪行为，又把公共秩序搅乱了的，拘留 5 到 10 日，并可以罚 1000 元以下（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-16', 'concept_archive_s8-16', 'recommendation', '公然侮辱别人，或者捏造事实诽谤别人的，拘留 5 日以下，或者罚 1000 元以下；情节较重的，拘留 5 到 10 日。多次发送侮辱恐吓信息、滋扰纠缠跟踪、偷拍并散布别人隐私的，同样这么罚。故意散布谣言、把公共秩序搅乱了的，拘留 5 到 10 日。情节严重的，构成侮辱罪、诽谤罪，判 3 年以下。通过网络诽谤的，受害人取证有困难，可以请法院要求公安协助（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-17', 'concept_archive_s8-17', 'recommendation', '依法成立的合同受法律保护，对签字的双方都有约束力。签了就要按约定全面履行。民法典第四百九十条写着，用合同书订合同的，双方「签名、盖章或者按指印时合同成立」。按手印和签名、盖章是并列的三种办法，按了手印合同一样成立。「没看清」「以为是别的」在法庭上很难成立。不签，就不会背上不属于自己的债务和责任（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-18', 'concept_archive_s8-18', 'recommendation', '借款合同应当采用书面形式，内容一般包括借款的种类、币种、用途、数额、利率、期限和还款方式。写全了才好起诉。担保合同没写清按哪种方式保证，或者写得不清楚的，按一般保证算。一般保证的担保人可以先等着：要债的人得先去起诉或者仲裁，再申请强制执行借款人的财产，执行完还是还不上，才轮到你替他还。反过来，签了「连带责任保证」就没有这层保护，要债的人可以直接找你要（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-19', 'concept_archive_s8-19', 'recommendation', '民法典规定「向人民法院请求保护民事权利的诉讼时效期间为三年」。起算点是「权利人知道或者应当知道权利受到损害以及义务人之日起计算」，从你知道自己吃了亏、又知道该找谁的那天起算。最长不超过自权利受到损害之日起 20 年。期间届满的，「义务人可以提出不履行义务的抗辩」。法院不会自己去翻时效，但对方在法庭上一提就有效，钱还在，只是要不回来了。有四种事情会让时效中断，一中断就从头重新计算 3 年。一是你向欠你的人提出要他履行。二是对方答应履行。三是你去起诉或者申请仲裁。四是和这些效力相同的其他情形。约定分期还的，从最后一期到期那天起算。有四类要求不受时效限制：要求停止侵害、排除妨碍、消除危险；要回自己的不动产和已经登记的动产；抚养费、赡养费、扶养费；法律规定的其他情形。劳动争议是另一套：仲裁时效 1 年，从知道或者应当知道权利被侵害之日起算。但「劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-20', 'concept_archive_s8-20', 'recommendation', '转移财产本身就是入罪的情形。全国人大常委会对刑法第三百一十三条作过解释。解释把「被执行人隐藏、转移、故意毁损财产或者无偿转让财产、以明显不合理的低价转让财产，致使判决、裁定无法执行」直接列为「有能力执行而拒不执行，情节严重」。藏钱、转钱、故意砸了自己的东西、白送出去、贱卖出去，让判决没法执行，都算。两高（最高人民法院和最高人民检察院）2024 年的解释又补了十项。其中包括用假和解、假转让的方式处置自己的财产权益。也包括用明显不合理的高价买下别人的财产，替别人的债务做担保。这些都是故意把自己可以用来还债的财产掏空。拒执罪判 3 年以下。情节特别严重的，判 3 到 7 年并处罚金。特别严重指这几种情形：用虚假诉讼、虚假仲裁、虚假公证妨害执行。聚众冲击执行现场。围攻、扣押、殴打执行人员。因为拒不执行导致申请执行人自杀自残。不是案件当事人的外人，明知情况还和他串通、帮着藏钱过户的，按拒执罪的共犯（同伙）论处。被违法处置的财产应当依法追缴（追回）或者责令退赔。在被告收到应诉通知之后、判决生效之前就动手转移的，同样算。民事上，白送和明显不合理的低价转让，要债的人可以请法院把这笔转让撤销。拒绝报告或者虚假报告财产的，法院可以罚款，对个人 10 万元以下，也可以拘留 15 日以下（全国，两高解释 2024 年 12 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-21', 'concept_archive_s8-21', 'recommendation', '纳入失信名单只有六种情形。一是有履行能力而拒不履行。二是以伪造证据、暴力威胁妨碍抗拒执行。三是以虚假诉讼、虚假仲裁或者隐匿转移财产规避执行。四是违反财产报告制度。五是违反限制消费令。六是无正当理由拒不履行执行和解协议。提供了充分有效的担保，或者已经被查封扣押冻结的财产足够清偿的，法院不得按第一项（有履行能力而拒不履行）纳入。被执行人是未成年人的，不得纳入。纳入的期限是 2 年。以暴力威胁妨碍抗拒执行、情节严重的，或者有多项失信行为的，可以延长 1 到 3 年。已经履行完毕、和解协议已经履行完毕、法院裁定终结执行等七种情形，法院应当在 3 个工作日内删除。积极履行或者主动纠正失信行为的，还可以提前删除。被限制消费的自然人不得做九类高消费及非生活和工作必需的消费。一是坐飞机、列车软卧、轮船二等以上舱位。二是在星级以上宾馆、酒店、夜总会、高尔夫球场高消费。三是买不动产，或者新建、扩建、高档装修房屋。四是租高档写字楼、宾馆、公寓办公。五是买非经营必需的车辆。六是旅游、度假。七是子女就读高收费私立学校。八是花高额保费买保险理财产品。九是坐 G 字头动车组列车的任何座位，或者其他动车组列车一等以上座位。因为生活或者经营必需要做其中一项的，应当向法院申请，获得批准才能做。提供确实有效的担保，或者经申请执行人同意的，法院可以解除限高（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-22', 'concept_archive_s8-22', 'recommendation', '诈骗 3000 元至 1 万元以上，构成诈骗罪的「数额较大」，判 3 年以下，另外罚钱或者只罚钱，各省在这个幅度内定本地标准。不够刑事标准的，按治安管理处罚：拘留 5 到 10 日，或者罚 2000 元以下。情节较重的，拘留 10 到 15 日，并可以罚 3000 元以下。民事上，网购合同纠纷可以在收货地法院起诉，不必跑到卖家所在地。争的钱数在本省上年度就业人员年平均工资 50% 以下的，适用小额诉讼。小额诉讼一审终审（判完就生效、不能上诉）。立案后 2 个月内审结，简易程序 3 个月。民事诉讼可以在网上的平台进行，和线下同等效力（全国，民诉法 2024 年 1 月起，治安管理处罚法 2026 年 1 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-23', 'concept_archive_s8-23', 'recommendation', '送出去的东西，在过到对方名下之前可以撤销，法律把这个时点叫财产权利转移。一旦转账、过户完成，就只剩三种情形能撤销：收东西的一方严重侵害你或者你的近亲属；该扶养你却不扶养；不履行赠与合同里约定的义务。节日、生日这类有纪念意义的时点给的价值不大的礼物礼金，还有为了表达或者增进感情的日常消费支出，不属于彩礼，分手时不按彩礼返还（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-24', 'concept_archive_s8-24', 'recommendation', '法律禁止借婚姻索取财物。一方以彩礼为名借婚姻索取财物的，另一方要求返还，法院支持。有三种情形可以要求返还：没办结婚登记；办了登记但确实没有共同生活；婚前给了彩礼，给到出钱那一方生活困难。已经登记并且共同生活的，一般不返还。但共同生活的时间短、彩礼数额又过高的，法院会按钱实际怎么花的、有没有嫁妆、有没有孕育、双方有没有过错，来确定返还的比例。没登记但已经同居的，同样按比例处理（全国，2024 年 2 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-25', 'concept_archive_s8-25', 'recommendation', '婚前财产是个人财产，不会因为结婚年头长就变成共同财产。夫妻可以书面约定：婚前财产和婚后所得归各自、归共同，或者一部分共同，这个约定对双方都有约束力。婚前父母出资买房，视为给自己子女的赠与，除非明确表示是给两个人的。婚后父母出资的，按约定处理；没有约定的，按共同财产的原则处理。婚前或者婚内约定把一方的房产赠与另一方、或者变成两个人共有的，在变更登记之前，赠与的一方可以撤销，登记之后就是对方的了。离婚时隐藏、转移、变卖、挥霍共同财产，或者伪造债务的一方，可以少分或者不分（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-26', 'concept_archive_s8-26', 'recommendation', '重婚的婚姻无效。有配偶还去重婚的，或者明知对方有配偶仍然和他结婚的，判 2 年以下。诈骗公私财物数额较大的，判 3 年以下并处罚金。数额巨大的，判 3 到 10 年。数额特别巨大的，判 10 年以上或者无期，并处罚金或者没收财产（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-27', 'concept_archive_s8-27', 'recommendation', '家电维修经营者必须明示服务项目和配件的收费标准、质量规范、质保期限和投诉电话。必须给消费者维修服务凭证和收费发票，并如实填写维修的项目和详情。不得虚列、夸大、伪造维修项目，不得虚报故障部件，不得故意替换性能正常的部件。情节严重的，处 3 万元以下罚款。所有经营者都必须明码标价，不得在标价之外加价，不得收取任何没有标明的费用。低价诱骗、高价结算，以及虚假折价，属于价格欺诈。经营者必须用显著的方式标明服务的项目、内容、价格和计价方法，不得作虚假的或者引人误解的宣传（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-27"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-28', 'concept_archive_s8-28', 'recommendation', '法定代表人由实际执行公司事务的董事或者经理担任，法律预设你就是管事的那个人。法定代表人执行职务给别人造成损害的，公司先赔，赔完可以回头向有过错的法定代表人追偿（把这笔钱要回去）。董事、高管对公司负有忠实义务和勤勉义务（忠于公司、尽心办事）。执行职务给别人造成损害，本人又有故意或者重大过失的，自己也要掏钱赔。「不知情」在法律上不是能免掉责任的理由（全国，2024 年 7 月起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-28"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-29', 'concept_archive_s8-29', 'recommendation', '外交部领事司给出国公民的建议是「请务必避免为他人携带行李物品，特别是违禁物品或不了解的物品」。这么做是为了避免在不知情的情况下替别人携带违禁品，因而承担法律责任。行李里查出毒品或者走私品的时候，「不知道里面是什么」需要你自己举证', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-29"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-30', 'concept_archive_s8-30', 'recommendation', '自家养的动物伤了人，养的人或者当时管着它的人就要赔，法律叫承担侵权责任。只有能证明是被伤的人自己故意招惹，或者有重大过失，才可以不赔或者少赔。而违反管理规定、没采取安全措施的，比如该牵绳没牵，就只剩「被侵权人故意」这一条能减轻。禁止饲养的烈性犬伤了人，则没有任何能免责的理由', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-30"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-31', 'concept_archive_s8-31', 'recommendation', '《刑法》第二百三十六条：以暴力、胁迫或者其他手段强奸妇女的，处三年以上十年以下有期徒刑。「其他手段」不限于动手，对方意识不清、睡着时无法有效同意，就落在这四个字里。强奸妇女情节恶劣的，强奸妇女多人的等情形，处十年以上有期徒刑、无期徒刑或者死刑。同一条还规定，奸淫不满十四周岁的幼女的，以强奸论并从重处罚，幼女怎么认定见第 9 节第 18 条（不满 14 岁）。北京市西城区人民检察院的普法文章说，把妇女「麻醉、灌醉后实施性侵的，同样构成强奸罪」。关键在「是否违背了被害人内心真实意愿」，被害人当时有没有反抗「并非关键」。《刑法》第二百三十七条管强制猥亵：以暴力、胁迫或者其他方法强制猥亵他人的，处五年以下有期徒刑或者拘役（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-31"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-32', 'concept_archive_s8-32', 'recommendation', '《刑法》第二百七十四条：敲诈勒索公私财物，数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。拘役是短期关押，管制是不关押但限制自由，并处或者单处罚金就是另外罚钱或者只罚钱。数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金。数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。两高还有一份解释：《关于办理敲诈勒索刑事案件适用法律若干问题的解释》（法释〔2013〕10 号，2013 年 4 月 27 日起施行）。这份解释的第一条定了三档金额。敲诈勒索公私财物价值二千元至五千元以上的，认定为「数额较大」。三万元至十万元以上的，认定为「数额巨大」。三十万元至五十万元以上的，认定为「数额特别巨大」。第三条：二年内敲诈勒索三次以上的，应当认定为「多次敲诈勒索」（全国）。民法典第一千零三十二条：任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。第一千零三十三条禁止以电话、短信、即时通讯工具等方式侵扰私人生活安宁。所以对方真把照片发出去，是他多一条罪。福建省公安厅同类案件提示的原话是：「一定要保存好证据，及时拨打 110，切勿继续转账」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-32"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-33', 'concept_archive_s8-33', 'recommendation', '《治安管理处罚法》（2025 年 6 月 27 日修订，2026 年 1 月 1 日起施行）第五十条管的是诬告。捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的，要处罚。处五日以下拘留，或者一千元以下罚款。情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款。《刑法》第二百四十三条管的是诬告陷害罪。捏造事实诬告陷害他人，意图使他人受刑事追究，情节严重的，处三年以下有期徒刑、拘役或者管制。造成严重后果的，处三年以上十年以下有期徒刑。国家机关工作人员犯前款罪的，从重处罚，从重是指在同一档刑罚里往重里判。不是有意诬陷，而是错告，或者检举失实的，不适用前两款的规定。记错了、告错了，不按这两款追究（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-33"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-34', 'concept_archive_s8-34', 'recommendation', '《刑事诉讼法》第五十五条：证据确实、充分，要符合这些条件——定案的证据都经过法定程序查证属实，综合全案证据对认定的事实已经排除合理怀疑。排除合理怀疑，就是把全案证据合起来看，认定的事实不能还留着说得通的另一种可能。第五十六条：采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述，以及采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除。在侦查、审查起诉、审判时发现有应当排除的证据的，应当依法予以排除，不得作为起诉意见、起诉决定和判决的依据。第二百条第（三）项：证据不足，不能认定被告人有罪的，应当作出证据不足、指控的犯罪不能成立的无罪判决。第二百五十二条给了申诉的路。当事人及其法定代理人、近亲属，对已经发生法律效力的判决、裁定，可以向人民法院或者人民检察院提出申诉。但申诉不能停止判决、裁定的执行。第二百五十三条列举了人民法院应当重新审判的情形（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-34"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-35', 'concept_archive_s8-35', 'recommendation', '《国家赔偿法》第十七条列了几种情形，受害人有取得赔偿的权利。第一种是拘留：违反刑事诉讼法规定对公民采取拘留措施，或者依法拘留但超过法定时限。这之后决定撤销案件、不起诉，或者判决宣告无罪终止追究刑事责任的。第二种是逮捕：对公民采取逮捕措施后，决定撤销案件、不起诉，或者判决宣告无罪终止追究刑事责任的。第三种是再审：案子按审判监督程序再审改判无罪，原判刑罚已经执行的。审判监督程序就是把已经生效的判决重新拿出来审的程序。第三十三条：侵犯公民人身自由的，每日赔偿金按照国家上年度职工日平均工资计算。第三十五条：致人精神损害的，应当在侵权行为影响的范围内为受害人消除影响、恢复名誉、赔礼道歉，造成严重后果的应当支付相应的精神损害抚慰金。第十九条列了六种国家不赔的情形。一是自己故意作假口供，或者伪造其他有罪证据，因此被关或者被判刑。二是按刑法第十七条、第十八条不负刑事责任的人被关，比如没到负刑事责任的年龄，或者精神病人在不能辨认、不能控制自己行为的时候造成危害。三是按刑事诉讼法规定不追究刑事责任的人被关。这包括情节显著轻微、危害不大，不认为是犯罪的，过了追诉时效的，嫌疑人死亡的。也包括犯罪情节轻微、检察院决定不起诉的，就是常说的相对不起诉（也叫酌定不起诉）。未成年人附条件不起诉考验期满后不起诉的，和被害人达成和解后不起诉的，同样在内。四是办案人员和行使职权无关的个人行为。五是自己自伤、自残等故意行为造成的损害。六是法律规定的其他情形。两高 2015 年的刑事赔偿司法解释第七条再次确认：不负刑事责任的人和相对不起诉的人被羁押，国家不赔。但起诉后被法院错判拘役、有期徒刑、无期徒刑并已执行的，判决确定后继续关押的那段仍然要赔。该解释第八条：办案机关以「你自己作假口供」「你自己自伤自残」为理由不赔的，由办案机关举证。最高人民检察院 2026 年 5 月发了通知。国家统计局 2026 年 5 月 15 日公布，2025 年全国城镇非私营单位就业人员年平均工资约 12.9 万元（129441 元）。据此算出的日平均工资为 495.94 元。各级检察院自 2026 年 5 月 18 日起作出国家赔偿决定时，对侵犯公民人身自由的赔偿金按每日 495.94 元计算。上一个标准是每日 475.52 元，从 2025 年 5 月起用（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-35"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-36', 'concept_archive_s8-36', 'recommendation', '官方案例：2008 年有关部门公布部分批次「施恩」牌奶粉含三聚氰胺之后，郭利之女的检查结果为「双肾中央集合系统内可见数个点状强回声」。郭利多次向销售商和施恩公司索赔，并向媒体曝光。2009 年 6 月双方达成协议，施恩公司补偿 40 万元，郭利出具书面材料表示不再追诉并放弃赔偿要求。此后公司报案，郭利被潮安县人民法院以敲诈勒索罪判处有期徒刑五年。广东省人民检察院提出了再审建议。建议认为「现有证据不足以证实郭利主观上具有非法占有的目的」。郭利作为法定监护人，「有权利向奶粉的生产厂家索赔，其索赔行为有法律依据」。建议还写着，「消费者对损害其合法权益的行为，有权通过大众传播媒介予以揭露、批评」。2017 年 4 月 7 日，广东省高级人民法院再审宣告郭利无罪。理由是「原审认定郭利以非法占有为目的，使用威胁、要挟的方法，强行索取财物行为的事实不清，证据不足，郭利的行为性质未超出民事纠纷的范畴」。郭利自 2009 年 7 月 23 日至 2014 年 7 月 22 日被羁押 1826 天（广东，2017 年再审改判）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-36"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-37', 'concept_archive_s8-37', 'recommendation', '法发〔2023〕14 号第 15 条讲的是禁令。权利人有证据证明，行为人正在实施或者即将实施侵害其人格权的违法行为。不及时制止，将使其合法权益受到难以弥补的损害。权利人依据民法典第九百九十七条申请的，人民法院可以依法作出人格权侵害禁令。人格权侵害禁令就是一道责令对方先停手的法院命令。该解释第 11 条讲的是取证。自诉案件里，「被害人提供证据确有困难的，可以要求公安机关提供协助」。公安机关应当及时查明行为主体，收集传播扩散情况及影响等证据材料。网络服务提供者应当提供必要的技术支持。「经公安机关协助取证，达到自诉案件受理条件的，人民法院应当决定立案」。无法收集的，公安机关应当书面说明。自诉案件就是要受害人自己去法院起诉的案件。该解释第 12 条列了五种情形，应当认定为刑法第二百四十六条第二款说的「严重危害社会秩序」。一是造成被害人或者其近亲属精神失常、自杀等严重后果，且社会影响恶劣。二是随意以普通公众为侵害对象，信息大范围传播引发大量低俗恶意评论，且社会影响恶劣。三是侮辱诽谤多人或者多次散布，且社会影响恶劣。四是组织、指使人员在多个平台大量散布，且社会影响恶劣。五是其他。该解释第 4 条：组织「人肉搜索」，违法收集并向不特定多数人发布公民个人信息，情节严重的以侵犯公民个人信息罪定罪处罚。《网络暴力信息治理规定》第二十三条要求平台提供这些防护选项。可以屏蔽陌生用户或者特定用户。可以限制本人发布信息的可见范围。可以禁止转载或者评论。可以只接收好友私信，或者拒绝接收所有私信。第二十五条要求提供快捷取证功能。第二十六条要求在显著位置设快捷投诉举报入口。第十五条要求平台发现涉嫌违法犯罪的，及时向公安机关报案', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-37"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-38', 'concept_archive_s8-38', 'recommendation', '保险法第三十四条：以死亡为给付保险金条件的合同，未经被保险人同意并认可保险金额的，合同无效。被保险人就是被保的那个人。父母为未成年子女投保不受这个限制。第三十九条：投保人指定受益人时须经被保险人同意。投保人是掏钱买保险的人，受益人是出事后领钱的人。第四十三条管的是故意害人。投保人故意造成被保险人死亡、伤残或者疾病的，保险人不承担给付保险金的责任。投保人已交足二年以上保险费的，向其他权利人退还现金价值。受益人故意造成被保险人死亡、伤残、疾病的，或者故意杀害被保险人未遂的，该受益人丧失受益权。第二十七条第二款：投保人、被保险人故意制造保险事故的，保险人有权解除合同、不承担赔偿或者给付责任，除第四十三条规定外不退还保险费。民法典第一千一百二十五条：故意杀害被继承人的，丧失继承权。刑法第一百九十八条第一款第五项，把「投保人、受益人故意造成被保险人死亡、伤残或者疾病，骗取保险金」列为保险诈骗。数额较大的，处 5 年以下并处 1 万至 10 万元罚金。数额巨大的，处 5 至 10 年。特别巨大的，处 10 年以上。第二款：有该项行为同时构成其他犯罪的，依照数罪并罚的规定处罚，数罪并罚就是几个罪合在一起算刑。第二百三十二条：故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑。案例是安徽宣城的张某松案。2016 年 7 月 18 日凌晨，他驾车冲入池塘，妻子溺亡。事发前不到半个月，他为妻子投保 4 份，每份 100 万元。7 月 25 日他被抓获。法院以故意杀人罪、保险诈骗罪数罪并罚，判处死缓并处罚金 5 万元', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-38"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-39', 'concept_archive_s8-39', 'recommendation', '《公安机关办理刑事案件程序规定》（公安部令第 159 号修正后）第一百七十一条管的是受案回执。原文是：「公安机关接受案件时，应当制作受案登记表和受案回执，并将受案回执交扭送人、报案人、控告人、举报人」。第一百七十四条：「对接受的案件，或者发现的犯罪线索，公安机关应当迅速进行审查」。第一百七十八条管的是立不立案。接受案件后经审查，认为有犯罪事实需要追究刑事责任，又属于自己管辖的，经县级以上公安机关负责人批准予以立案。不立案也要给你一张纸：「对有控告人的案件，决定不予立案的，公安机关应当制作不予立案通知书，并在三日以内送达控告人」。第一百七十九条管的是不服怎么办。原文是：「控告人对不予立案决定不服的，可以在收到不予立案通知书后七日以内向作出决定的公安机关申请复议；公安机关应当在收到复议申请后三十日以内作出决定」。接着写：「控告人对不予立案的复议决定不服的，可以在收到复议决定书后七日以内向上一级公安机关申请复核；上一级公安机关应当在收到复核申请后三十日以内作出决定。对上级公安机关撤销不予立案决定的，下级公安机关应当执行」。案情重大、复杂的可以延长复议复核的时限，但「不得超过三十日，并书面告知申请人」。刑事诉讼法第一百一十二条：认为有犯罪事实需要追究刑事责任的应当立案；不予立案的，「将不立案的原因通知控告人。控告人如果不服，可以申请复议」。第一百一十三条：「被害人认为公安机关对应当立案侦查的案件而不立案侦查，向人民检察院提出的，人民检察院应当要求公安机关说明不立案的理由。人民检察院认为公安机关不立案理由不能成立的，应当通知公安机关立案，公安机关接到通知后应当立案」。《公安机关办理行政案件程序规定》第六十一条也有同样的要求。属于本单位管辖的案件，「应当立即调查处理，制作受案登记表和受案回执，并将受案回执交报案人、控告人、举报人、扭送人」。办理治安案件的期限「自受理之日起不得超过 30 日；案情重大、复杂的，经上一级公安机关批准，可以延长 30 日」，鉴定期间不计入办案期限。《公安机关督察条例》第九条管的是投诉警察。原文是：「督察机构对群众投诉的正在发生的公安机关及其人民警察违法违纪行为，应当及时出警，按照规定给予现场处置，并将处理结果及时反馈投诉人」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-39"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-40', 'concept_archive_s8-40', 'recommendation', '刑法第三百八十九条给行贿下了定义：「为谋取不正当利益，给予国家工作人员以财物的，是行贿罪」。同一条还写着：「在经济往来中，违反国家规定，给予国家工作人员以财物，数额较大的，或者违反国家规定，给予国家工作人员以各种名义的回扣、手续费的，以行贿论处」。也留了一种例外：「因被勒索给予国家工作人员以财物，没有获得不正当利益的，不是行贿」。量刑写在刑法第三百九十条（刑法修正案十二修改，2024 年 3 月 1 日起施行）。原文是：「对犯行贿罪的，处三年以下有期徒刑或者拘役，并处罚金；因行贿谋取不正当利益，情节严重的，或者使国家利益遭受重大损失的，处三年以上十年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产」。有七种要往重里判的从重情形：「（一）多次行贿或者向多人行贿的；（二）国家工作人员行贿的；（三）在国家重点工程、重大项目中行贿的；（四）为谋取职务、职级晋升、调整行贿的；（五）对监察、行政执法、司法工作人员行贿的；（六）在生态环境、财政金融、安全生产、食品药品、防灾救灾、社会保障、教育、医疗等领域行贿，实施违法犯罪活动的；（七）将违法所得用于行贿的」。末款留了主动交待可以减免的口子：「行贿人在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚。其中，犯罪较轻的，对调查突破、侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-40"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-41', 'concept_archive_s8-41', 'recommendation', '民事诉讼法第六十六条把视听资料、电子数据都列为证据。最高人民法院的民事诉讼法司法解释第一百零六条，只排除三种方法取得的证据：严重侵害他人合法权益的，违反法律禁止性规定的，严重违背公序良俗的。「没事先告诉对方」不在这三种里。最高人民法院的证据规定第十五条：拿录音录像当证据，要交存着它的原始载体，比如原来那部手机。第九十条：存有疑点的视听资料、电子数据，不能单独用来认定事实。最高人民法院官网转载的一篇法官文章也这样说：录音要合法取得、内容真实、不剪辑，还要和案子有关（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-41"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-42', 'concept_archive_s8-42', 'recommendation', '民事诉讼法第六十六条把物证、视听资料和电子数据都列为证据。最高人民法院的证据规定第十四条把图片、音频、视频列为电子数据。第十五条要求交电子数据的原件，拿录像当证据要交原始载体。照片和录像能把马上会变的现场状态留下来，再和报警记录、维修记录、病历、证人说法互相对上。「全景、位置、细节」这个顺序是经验做法，法律没有规定（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-42"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-43', 'concept_archive_s8-43', 'recommendation', '先说风险。66 个国家的数据合起来看（系统综述）。女性被杀的案子里，38.6% 是亲密伴侣干的，男性是 6.3%。作者说，这类命案往往是长期虐待的最后一步。另一项研究比较了 506 起命案和杀人未遂，还有 427 名挨过打但没出这种事的女性。以前被伴侣掐过脖子的，遭杀人未遂的几率是没被掐过的 6.70 倍（OR 6.70，95% CI 3.91–11.49）。被杀的几率是 7.48 倍（OR 7.48，95% CI 4.53–12.35）。再说法律。受害人和近亲属可以报警。公安机关要及时出警，制止家暴，调查取证，协助就医和验伤。情节较轻的，公安机关可以给对方出告诫书。遭受家暴或者面临家暴的现实危险，可以向法院申请人身安全保护令。法院受理后 72 小时内要作出裁定，情况紧急的 24 小时内。保护令可以禁止对方施暴，禁止对方骚扰、跟踪、接触你和你的近亲属，还可以让对方搬出你的住处。保护令最长管 6 个月，到期前可以申请延长。申请不以离婚为前提。法院认为家暴「存在较大可能性」就可以发。对方违反保护令，法院可以罚款 1000 元以下、拘留 15 日以下。构成犯罪的，按拒不执行判决、裁定罪处理。经常性的侮辱、威胁、跟踪、骚扰，还有挨冻挨饿，也算家暴。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s8-43"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-44', 'concept_archive_s8-44', 'recommendation', '最高人民法院 2017 年的通知写了四点。一方在赌博、吸毒这些违法犯罪活动里欠的债，不予法律保护。债主知道或者应当知道他借钱去赌博、吸毒，还借给他的，不予法律保护。一方用自己的名义借钱，拿去干违法犯罪的事，他要求按夫妻共同债务处理的，法院不支持。没经过审判程序，不能要求没借钱的那一方承担民事责任（全国，2017 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-44"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-45', 'concept_archive_s8-45', 'recommendation', '金融监管总局福建监管局 2022 年的风险提示讲了这个套路。客户 A 资质不够，贷不下来。中介说要加一个担保人，让 A 去找资质好的 B。实际办的时候，中介用 B 的身份信息申请贷款，钱给 A 用。原文说「借款人实质为B」，B「直至被银行催收才知本人是借款人而非担保人」。山东监管局 2024 年的提示说，中介会向 B 承诺「不用承担任何责任」。中介还会事先教 B 怎么应付银行的贷前调查，实际由 B 作为借款人申请贷款。上海普陀区法院 2024 年公布过一起案子。业务员拿着 B 的手机下载银行 App，直接用 B 的名义申请贷款。钱到了 B 的账户，B 转给了 A，A 又付了 8 万多元手续费。中介一伙 8 人以合同诈骗罪被判 10 个月到 4 年。中介判了刑，这笔贷款也不会因此变成别人的。民法典第一百四十九条写着，第三人欺诈的，对方「知道或者应当知道」，受骗的一方才能请求撤销。这里的对方是银行，银行不知情就撤不掉。能撤的，要在知道被骗之日起 1 年内向法院请求（第一百五十二条）。借款人要按约定的期限还钱（第六百七十五条）。合同只约束签合同的人（第四百六十五条）。把债转给别人，要经银行同意（第五百五十一条）。所以 A 写的承诺书管不到银行。钱只能自己起诉 A 去要。替人刷了脸、没看合同，法院也认。内江市市中区法院 2025 年审结过一个案子：蒋某向小贷公司借钱，自己一个人借不到。张某的儿子背着她，把她的身份信息给了蒋某，让她当共同借款人。借款流程里要她本人刷脸，她刷了，但没看合同。法院说她「应当预见人脸识别的重要性及法律后果」，判她和蒋某一起还剩下的本金 6 万多元。电子签名法写明，「可靠的电子签名与手写签名或者盖章具有同等的法律效力」。反电信网络诈骗法规定，任何人「不得提供实名核验帮助」，违反的要罚款，情节严重的拘留。普通程序一审 6 个月内审结，可以延长。律师费不在法定的诉讼费用里，要自己出（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-45"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s8-46', 'concept_archive_s8-46', 'recommendation', '英格兰和威尔士的犯罪调查，问了 2008 到 2012 年间 37416 户人家装了哪些防盗设施，再和被盗的人家比。什么都没装的只占全部人家的 4.9%，却占了被人进屋偷东西人家的 36.6%。作者算的是「保护倍数」：被盗几率是什么都没装人家的几分之一。门锁加窗锁是 12.54 倍，被盗几率降到约十二分之一。这里的门锁指双锁或者「死锁」（锁舌要用钥匙才能收回）。门锁、窗锁再加门外的感应灯或定时灯，是 34.41 倍。再加屋里的定时灯，是 49 倍。只装一样的，门外灯约 3 倍，门锁约 2.8 倍。单装窗锁看不出差别。装五样的，并不比装对了的三样强。只装报警器、别的都不装，被盗几率反而比什么都没装的高。挂假报警器盒子的，有人想闯进来没闯成的几率也更高。锁得真锁上才算数：1993 到 2006/07 年，撬锁、砸窗、拆门板进屋的盗窃从每千户 31 起降到 7 起，降了 77%。门窗没锁、直接走进去的那种，一直是每千户 7 起，没降（英格兰和威尔士）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s8-46"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-1', 'concept_archive_s9-1', 'recommendation', '故意散布谣言，谎报险情、疫情、灾情、警情，扰乱公共秩序的，拘留 5 到 10 日。还可以再罚 1000 元以下。情节较轻的那一档，是拘留 5 日以下，或者罚 1000 元以下。编造虚假的险情、疫情、灾情、警情，放到网上传播的，判 3 年以下。明知是假的还故意往外传，也是这一档。前提是把社会秩序搅乱得厉害，法条的说法是「严重扰乱社会秩序」。造成严重后果的，判 3 到 7 年（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-2', 'concept_archive_s9-2', 'recommendation', '用辱骂、编造事实这类方式，侵害英雄烈士的姓名、肖像、名誉、荣誉，损害了公共利益的，按下面这档罚。拘留 5 到 10 日，或者罚 1000 到 3000 元。亵渎、否定英烈的事迹和精神，制作传播美化侵略战争的言论、图片、音视频，扰乱公共秩序的，也是这一档。情节较重的那一档，是拘留 10 到 15 日，还可以再罚 5000 元以下。到「情节严重」这一档就构成犯罪，判 3 年以下。在公共场合侮辱国旗国徽，或者改国歌的词曲、用歪曲贬损的方式唱国歌，情节严重的也判 3 年以下。官方案例：肖某在 499 人的村民微信群发 2 条信息诋毁侮辱袁隆平，判管制 6 个月（管制是不关进监狱、但行动受限制的刑罚）。仇某用 250 余万粉丝的微博发 2 条歪曲卫国戍边官兵事迹的内容，判 8 个月，还要在全国性媒体公开道歉（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-3', 'concept_archive_s9-3', 'recommendation', '用造谣、诽谤或者别的方式，煽动别人颠覆国家政权、推翻社会主义制度的，判 5 年以下。带头的（法条叫「首要分子」）或者罪行重大的，判 5 年以上，有期徒刑最高 15 年。煽动分裂国家、破坏国家统一的，刑期和上面一样。和境外机构、组织、个人勾结着做这两件事的，从重处罚。境内外的机构、组织或者个人出钱资助别人做的，对直接负责的人判 5 年以下，情节严重的判 5 年以上。为境外的机构、组织、人员窃取、刺探、收买、非法提供国家秘密或者情报的，判 5 到 10 年。这一项里情节特别严重的判 10 年以上或者无期徒刑，情节较轻的判 5 年以下。危害国家安全的犯罪一律附加剥夺政治权利 1 到 5 年，这几年里选举权和当公职人员的资格都被取消。还可以并处没收财产，把个人财产收归国家。行政处罚上也有规定。任何个人和组织都不得利用网络，从事危害国家安全、荣誉和利益的活动。也不得煽动颠覆国家政权、推翻社会主义制度。不得煽动分裂国家、破坏国家统一。发布或者传输这类信息的，按有关法律、行政法规处罚（全国）。另有一类不用传播就成立。明知是宣扬恐怖主义、极端主义的东西，还非法拿在手里的，情节严重就够判。这里的东西包括图书、音频视频资料或者其他物品。刑期是 3 年以下有期徒刑、拘役（短期关押）或者管制（不关押但行动受限）。还要并处或者单处罚金，判刑的同时罚钱，也可能只罚钱。依据是刑法第一百二十条之六，由刑法修正案九新增。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-4', 'concept_archive_s9-4', 'recommendation', '在网上传播淫秽信息的，拘留 10 到 15 日，还可以再罚 5000 元以下。情节较轻的那一档，是拘留 5 日以下，或者罚 1000 到 3000 元。内容涉及未成年人的，从重处罚。传播淫秽物品到了「情节严重」这一档的，判 2 年以下。为了挣钱去卖、去传的，判 3 年以下并罚钱。这一项里情节严重的判 3 到 10 年，特别严重的判 10 年以上或者无期徒刑。建一个主要用来传播淫秽电子信息的群，成员到 30 人以上的，按犯罪办。造成严重后果的也一样。建群的人、当管理员的人和主要往里发的人，都按传播淫秽物品罪定罪（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-5', 'concept_archive_s9-5', 'recommendation', '明知是犯罪来的钱和物，还帮着转移、收购、卖掉，或者用别的办法帮着遮掩的，判 3 年以下，并处或者单处罚金（判刑的同时罚钱，也可能只罚钱）。官方案例：王某某按指示带上身份证和 1 张银行卡，到指定地点配合转账取款，赚了 500 余元。检察院没有起诉他，公安按反电信网络诈骗法拘留 10 日，并罚 1000 元。满某某把自己和别人的银行卡、手机卡交给团伙收款、转账、取现，判 2 年 3 个月，并罚 2.2 万元（全国）。换成虚拟币转走也一样：安某某等三人按电诈团伙的指示，用自己的银行卡收钱，在交易平台上买成虚拟货币，再转到对方指定的账户，按比例拿提成。查实其中有被害人被骗的钱 50 余万元。三人以掩饰、隐瞒犯罪所得罪分别判 2 年 8 个月到 3 年 3 个月，各罚 3 万到 4 万元（北京通州）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-6', 'concept_archive_s9-6', 'recommendation', '用骗的手段，从银行或者其他金融机构拿到贷款、票据承兑、信用证、保函等。给银行或者其他金融机构造成重大损失的，判 3 年以下。还要并处或者单处罚金，判刑的同时罚钱，也可能只罚钱。造成特别重大损失，或者有其他特别严重情节的，判 3 到 7 年并罚钱。警方立案追查的起点，是直接经济损失 50 万元以上。本来就没打算还，用编造的引进资金项目理由、假的经济合同、假的证明文件或者假的产权证明去骗贷款的，是贷款诈骗罪。这一项骗到 5 万元就立案，判 5 年以下并罚 2 万到 20 万元。数额巨大或者有其他严重情节的判 5 到 10 年，特别巨大的判 10 年以上直到无期徒刑。伪造、涂改、买卖国家机关的公文、证件、印章，判 3 年以下，情节严重的判 3 到 10 年。官方案例：一个 126 人的团伙，在 16 个省市把没工作的人包装成「优质客户」，在 80 多家银行网点骗贷 3000 余万元。出面贷款的「白户」按贷款金额的三成拿好处费。检察院追诉了 105 名「白户」。2026 年一审已判的 80 人里，76 人以贷款诈骗罪判 1 年 4 个月到 6 年 6 个月并罚钱。另有 4 人因为替团伙取现，被以贷款诈骗罪、洗钱罪数罪并罚（两个罪一起算刑期）。这 4 人判 2 年 4 个月到 7 年 6 个月（全国）。本条的骗取贷款罪，按刑法修正案（十一）2021 年 3 月起的文本。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-7', 'concept_archive_s9-7', 'recommendation', '捡到别人丢的东西，要还给失主，及时通知他来领，或者送交公安等部门。把别人落下的东西留着自己用，金额到了「数额较大」又不肯交出来的，构成侵占罪，判 2 年以下。数额巨大的判 2 到 5 年。捡到别人的信用卡拿到 ATM 上用，属于「冒用他人信用卡」。够得上犯罪的，按信用卡诈骗罪处理：数额较大的判 5 年以下，并罚 2 万到 20 万元。数额巨大或者有其他严重情节的，判 5 到 10 年，并罚 5 万到 50 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-8', 'concept_archive_s9-8', 'recommendation', '骗别人或者公家的财物，数额较大的判 3 年以下，并处或者单处罚金（判刑的同时罚钱，也可能只罚钱）。数额巨大，或者有其他严重情节的，判 3 到 10 年并罚钱。数额特别巨大，或者有其他特别严重情节的，判 10 年以上或者无期徒刑，并罚钱或者没收财产。数额较大、巨大、特别巨大这三档，各省在下面的幅度内定本地标准。较大是 3000 元至 1 万元以上。巨大是 3 万元至 10 万元以上，特别巨大是 50 万元以上。把方法教给别人、卖「教程」的，按传授犯罪方法罪判 5 年以下，情节严重的判 5 到 10 年，特别严重的判 10 年以上或者无期徒刑。买卖手机号、验证码的上下游，按侵犯公民个人信息罪判 3 年以下，特别严重的判 3 到 7 年。用批量账号、网络地址自动切换系统，以及批量接收短信验证的接码平台，本身就是反电信网络诈骗法第十四条明令禁止的。非法买卖、出租、出借电话卡和互联网账号、帮别人过实名核验，在第三十一条之列。违反第十四条的，赚到的钱全部没收，再按赚到的钱罚 1 到 10 倍。没赚到钱，或者赚的不到 5 万元的，罚 50 万元以下，情节严重的还要拘留 15 日以下。违反第三十一条的，罚款同样是 1 到 10 倍，没赚到钱或者赚的不到 2 万元的罚 20 万元以下，情节严重的也要拘留 15 日以下。参与电信网络诈骗、还不够判刑的，拘留 10 到 15 日。赚到的钱没收，再罚 1 到 10 倍。没赚到钱或者赚的不到 1 万元的，罚 10 万元以下。官方案例一：外卖骑手刘某某以 0.1 元一个买虚拟手机号，注册某平台新用户。他领满 29 减 15 的新人券下单，再把商品倒卖给小商铺套现。他还用虚拟号互相邀请，领 2 元至 20 元的奖励金。他和骑手谭某某分别骗得 9 万余元和 7 万余元。上海杨浦区检察院以诈骗罪起诉 12 人，法院判 3 年 6 个月至拘役 3 个月。官方案例二：王某利用网店退款与回收虚拟抽奖币的时间差。他退款 1156 笔，提走手办 224 件，金额 24.9 万余元。他还在二手平台变现，法院以诈骗罪判 3 年缓 4 年，并处罚金 3 万元。他在审理期间退赃并预缴罚金，共 33 万元。官方案例三：某网约车平台的新用户优惠券和司机补贴，被「自己打车自己接单」的虚假跑单骗取，涉及 19 省 70 余市，金额 200 余万元。辽宁朝阳龙城区检察院起诉 163 人，全部被判有罪。主犯黄某、蔡某以诈骗罪、侵犯公民个人信息罪、传授犯罪方法罪数罪并罚（几个罪一起算刑期），各判 3 年 6 个月。另有 34 名情节轻微的从犯，检察院决定不起诉，仍然移送公安作行政处罚（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-9', 'concept_archive_s9-9', 'recommendation', '从楼上或者其他高处往下扔东西，只要有伤到人、砸坏财物或者危及公共安全的危险，就可以拘留 5 日以下，或者罚 1000 元以下。情节严重的拘留 10 到 15 日，还可以再罚 1000 元以下。情节严重到构成高空抛物罪的，判 1 年以下，并处或者单处罚金（判刑的同时罚钱，也可能只罚钱）。砸伤砸死人的，按更重的罪名处理。官方案例：李某晨在 21 楼酒后把空酒瓶、玻璃杯扔到楼下操场，砸中 13 岁学生致重伤二级，以危险方法危害公共安全罪判 10 年。周某从 32 楼向人群投掷 8 块砖头砸死 1 人，2024 年最高法核准死刑（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-10', 'concept_archive_s9-10', 'recommendation', '没有许可就持有、私藏枪支的，判 3 年以下，情节严重的判 3 到 7 年。打不了制式子弹的非制式枪，只要枪口比动能大于等于 1.8 焦耳/平方厘米，一律认定为枪支。枪口比动能，指的是子弹出膛时每平方厘米带的能量。不少网上买的钢珠枪、气枪都超过这个数。2018 年起最高法、最高检要求，对比动能偏低的气枪，要综合外观、材质、价格、用途、本人是不是知情等等评估之后，再决定要不要定罪。官方案例：赵某某夫妇在集贸市场卖「玩具枪」，查获 43 支，其中 18 支经鉴定符合枪支标准。因为没有充分证据证明他们知道那是枪支，按证据存疑不起诉（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-11', 'concept_archive_s9-11', 'recommendation', '没做实名登记就飞的，责令改正，还可以罚 200 元以下，情节严重的罚 2000 到 2 万元。没批准就在管制空域飞微型、轻型、小型无人机的，责令停止飞行，还可以罚 500 元以下。这一项里情节严重的，没收无人机，并罚 1000 到 1 万元。违反空域管理规定飞行、情节较重的，拘留 5 到 10 日。官方案例：李某某付费破解限高，把无人机飞到近 3000 米拍云层并发布，拘留 5 日。张某某替人破解限高和禁飞区限制 20 余台次，赚了 1.5 万余元。他被以提供侵入、非法控制计算机信息系统程序、工具罪定罪。判 6 个月，缓刑 1 年，并处罚金（全国，2024 年 1 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-12', 'concept_archive_s9-12', 'recommendation', '偷窥、偷拍、窃听、散布别人隐私的，拘留 5 日以下，或者罚 1000 元以下。情节较重的拘留 5 到 10 日，还可以再罚 1000 元以下。非法使用窃听、窃照专用器材、造成严重后果的，判 2 年以下。窃听、窃照专用器材，指专门用来偷听、偷拍的设备。官方案例：颜某平、颜某建在网上买了窃照器材，装进三家酒店的多个房间远程偷拍，分别判 1 年 3 个月和 1 年（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-13', 'concept_archive_s9-13', 'recommendation', '为了挣钱给赌博提供便利条件，或者参与赌博、赌资较大的，拘留 5 日以下，或者罚 1000 元以下。情节严重的拘留 10 到 15 日，并罚 1000 到 5000 元。为了挣钱把人聚起来赌，或者靠赌博过日子的，判 3 年以下并罚钱。开赌场的判 5 年以下并罚钱，情节严重的判 5 到 10 年（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s9-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-14', 'concept_archive_s9-14', 'recommendation', '吃国家重点保护野生动物，或者为了吃去买的，东西没收，再按它的价值罚 2 到 20 倍的钱。没有许可证就繁育国家重点保护野生动物的，没收，并罚 1 到 10 倍。非法收购、运输、出售国家重点保护的珍贵、濒危野生动物和它们的制品，判 5 年以下并罚钱。这一项里情节严重的判 5 到 10 年，特别严重的判 10 年以上。为了吃而猎捕、收购、运输、出售其他陆生野生动物，情节严重的判 3 年以下。官方案例：养殖户王某等 3 人卖了 40 余只人工繁育的费氏牡丹鹦鹉（国家二级保护），总价不到 400 元，2021 年检察院决定不起诉。2022 年起最高法、最高检明确，人工繁育技术成熟、已经成规模、当宠物买卖运输的，一般不按犯罪处理（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-15', 'concept_archive_s9-15', 'recommendation', '非法限制别人的人身自由、擅自闯进别人家，或者非法搜别人的身，拘留 10 到 15 日，并罚 1000 到 2000 元。情节较轻的拘留 5 到 10 日，并罚 1000 元以下。非法拘禁判 3 年以下有期徒刑、拘役（短期关押）、管制（不关押但行动受限）或者剥夺政治权利。把人弄成重伤的判 3 到 10 年，弄死人的判 10 年以上。为了讨债扣人、关人的，照这同一套规定处罚，债是真的也一样（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-16', 'concept_archive_s9-16', 'recommendation', '把自己的居民身份证出租、出借、转让给别人的，警告并罚 200 元以下。冒用别人的身份证，或者使用骗领来的身份证，罚 200 到 1000 元，或者拘留 10 日以下。购买、出售、使用伪造变造的身份证的，也是这一档。有些场合按国家规定必须出示身份证明。在这些场合使用伪造、变造或者盗用别人的证件，情节严重的就要判刑。证件包括身份证、护照、社保卡、驾驶证等。刑罚是拘役（短期关押）或者管制（不关押但行动受限），还要并处或者单处罚金，判刑的同时罚钱，也可能只罚钱（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-17', 'concept_archive_s9-17', 'recommendation', '阻碍国家机关工作人员依法办公务的，警告或者罚 500 元以下。情节严重的拘留 5 到 10 日，还可以再罚 1000 元以下。阻碍的是人民警察，就从重处罚。暴力袭击正在依法执行职务的人民警察，判 3 年以下。用枪支、管制刀具或者开车撞等严重危及警察人身安全的，判 3 到 7 年。撕咬、掌掴、踢打、抱摔、投掷物品造成轻微伤以上的，才算「暴力袭击」。甩手、挣脱、蹬腿这类一般性抗拒不算（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-18', 'concept_archive_s9-18', 'recommendation', '和不满 14 周岁的幼女发生性关系的，按强奸罪处理并从重处罚，基础刑期 3 到 10 年。最高法的口径是这样：用暴力、胁迫等强制手段的，不管知不知道对方是幼女，都定强奸罪。没用强制手段的，对不满 12 周岁的一律认定「应当知道」。12 到 14 周岁的，从身体发育、言谈举止、衣着等能看出可能是幼女，还下手的，认定为「明知」。「确实不知道」这个例外把握得很严（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-19', 'concept_archive_s9-19', 'recommendation', '打人或者故意伤害的，拘留 5 到 10 日，并罚 500 到 1000 元。结伙打、打残疾人孕妇老人小孩、多次打或者一次打好几个人的，拘留 10 到 15 日，并罚 1000 到 2000 元。打成轻伤就是故意伤害罪，判 3 年以下有期徒刑、拘役（短期关押）或者管制（不关押但行动受限）。打成重伤的判 3 到 10 年。民事上还要赔医疗费、误工费（耽误上班少挣的钱）、护理费、交通费、住院伙食补助费、营养费。把人打残的，另外赔残疾赔偿金。残疾赔偿金的算法，是审案法院所在地上年度城镇居民人均可支配收入乘 20 年。伤者 60 岁以上的，每多一岁减一年，75 岁以上按 5 年算。2022 年全国检察机关受理轻伤害案件 7 万余件，多数是婚姻家庭邻里纠纷或者偶然事件引起的。最高检典型案例：卢某打断对方三根肋骨（轻伤二级），赔了 11.3 万元达成和解，才获不起诉。石某打断对方桡骨（轻伤二级），没有赔，判有期徒刑十个月（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-20', 'concept_archive_s9-20', 'recommendation', '刑法第二百四十条：「拐卖妇女、儿童的，处五年以上十年以下有期徒刑，并处罚金」。有加重情形的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。「情节特别严重的，处死刑，并处没收财产」。《关于依法惩治拐卖妇女儿童犯罪的意见》第 17 条，说的是怎么区分卖亲生孩子和民间送养。判断标准是「关键在于行为人是否具有非法获利的目的」。也就是看有没有想靠这件事挣钱。有三种情形可以认定为出卖亲生子女，按拐卖妇女、儿童罪定罪。第一种是「将生育作为非法获利手段，生育后即出卖子女的」。第二种是「明知对方不具有抚养目的，或者根本不考虑对方是否具有抚养目的，为收取钱财将子女『送』给他人的」。第三种是「为收取明显不属于『营养费』『感谢费』的巨额钱财将子女『送』给他人的」。反过来，不是为了挣钱、确实迫于生活困难私自送养、只收少量营养费感谢费的，属于民间送养，不按拐卖罪定罪。再看刑法第二百六十一条。「对于年老、年幼、患病或者其他没有独立生活能力的人，负有扶养义务而拒绝扶养，情节恶劣的，处五年以下有期徒刑、拘役或者管制」。民法典第一千零九十四条规定，能当送养人的只有三种：孤儿的监护人、儿童福利机构、有特殊困难无力抚养子女的生父母。第一千一百零五条：「收养应当向县级以上人民政府民政部门登记。收养关系自登记之日起成立」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-21', 'concept_archive_s9-21', 'recommendation', '刑法第一百九十八条列了五种情形。（一）投保人故意虚构保险标的，编一个根本不存在的投保对象。（二）投保人、被保险人或者受益人对发生的保险事故编造虚假的原因，或者夸大损失的程度。（三）编造未曾发生的保险事故。（四）投保人、被保险人故意造成财产损失的保险事故。（五）投保人、受益人故意造成被保险人死亡、伤残或者疾病。数额较大的，处 5 年以下有期徒刑或者拘役，并处 1 万元以上 10 万元以下罚金。数额巨大或者有其他严重情节的，处 5 至 10 年，并处 2 万至 20 万元罚金。数额特别巨大或者有其他特别严重情节的，处 10 年以上，并处 2 万至 20 万元罚金或者没收财产。这一条的末款管的是帮忙的人：保险事故的鉴定人、证明人、财产评估人。他们故意出具虚假的证明文件、给别人骗保创造条件的，按保险诈骗的共犯处理，和骗保的人一起定罪。保险法第二十七条：没出保险事故却谎称出了的，保险公司有权解除合同，并且不退保费。用伪造、变造的证明资料，或者编造虚假事故原因、夸大损失程度的，保险公司对多报的那部分不赔，已经赔出去的要退回来或者赔偿。案例：安徽宣城张某松案中，王某信等 8 人因保险诈骗罪被判处有期徒刑 4 年到 2 年不等，均并处罚金 1 万元。这案子牵出的一起虚假诉讼里，保险公司核定损失 2 万元，当事人靠伪造车辆转让协议取得起诉资格去打官司，法院判赔 7 万余元。这份已经生效的民事判决，于 2019 年 9 月 26 日经再审被撤销。《反保险欺诈工作办法》要求：卖保单和赔钱这两头（承保端和理赔端）都要核验风险信息。还要探索建立多险种的行业反欺诈信息平台、反欺诈情报中心。这些平台集中筛查欺诈可疑数据，线索交由行业协会、反欺诈组织和保险机构核查。涉嫌犯罪的及时向公安机关报案。金融监管总局和它的派出机构，要和公安机关、人民检察院、人民法院建立健全行政执法与刑事司法的衔接机制（全国，2024 年 7 月 31 日印发）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-22', 'concept_archive_s9-22', 'recommendation', '《人体器官捐献和移植条例》第五条：「任何组织或者个人不得以任何形式买卖人体器官，不得从事与买卖人体器官有关的活动」。第十条：「任何组织或者个人不得获取未满 18 周岁公民的活体器官用于移植」。第十一条：「活体器官的接受人限于活体器官捐献人的配偶、直系血亲或者三代以内旁系血亲」。第三十七条规定了买卖人体器官怎么罚。买卖人体器官或者从事与买卖人体器官有关活动的，由县级以上地方人民政府卫生健康部门查处。先没收违法所得，把这笔交易得来的钱全部收走。再按交易额罚 10 倍以上 20 倍以下的钱。医务人员参与的，吊销执业证书并终身禁止从事医疗卫生服务。构成犯罪的，依法追究刑事责任（全国，2024 年 5 月 1 日起施行，原《人体器官移植条例》同时废止）。刑法第二百三十四条之一：「组织他人出卖人体器官的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产」。还有三种情形，依照刑法第二百三十四条、第二百三十二条定罪处罚。一是未经本人同意摘取他的器官。二是摘取不满十八周岁的人的器官。三是强迫或者欺骗他人捐献器官。这几种按故意伤害、故意杀人处理。案例一：北京市第一中级人民法院 2014 年 8 月 20 日终审的郑伟等 15 人案，涉及 51 枚肾脏，涉案金额 1034 万余元。卖肾的人（供体）「换来的仅仅是 2 万到 2.5 万元不等的报酬」。等肾的病人一方（受体方）出的价码，「以前是一个肾 18 万或 19 万，后来是 21 万或 22 万」。摘肾点是每月 7500 元租的四层小楼，团伙护士长供述该处「脏乱不堪，连抢救设备都没有」。组织者郑伟以组织出卖人体器官罪判处有期徒刑 12 年，其余 14 人判 3 年半至 9 年。案例二：最高人民检察院公布的「少年卖肾买苹果手机」案。17 岁的王某 2011 年 4 月 28 日晚在郴州被切除右肾。动手术的场地，是一家没有移植资质的医院里由人承包的科室提供的。5 月 2 日出院时他拿到 2.2 万元，受体方付给中介的是 15 万元人民币和 1 万美元，主犯获利 5.6 万余元。王某术后肾功能不全，「伤情构成重伤、三级伤残」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-23', 'concept_archive_s9-23', 'recommendation', '《治安管理处罚法》第七十八条：卖淫、嫖娼的，处十日以上十五日以下拘留，可以并处五千元以下罚款。情节较轻的，处五日以下拘留或者一千元以下罚款。在公共场所拉客招嫖的，处五日以下拘留或者一千元以下罚款。第七十九条：引诱、容留、介绍他人卖淫的，处十日以上十五日以下拘留，可以并处五千元以下罚款。情节较轻的，处五日以下拘留或者一千元以上二千元以下罚款。第八十七条：旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处卖淫、嫖娼活动时为违法犯罪行为人通风报信的，或者以其他方式为上述活动提供条件的，处十日以上十五日以下拘留。《刑法》第三百六十条是传播性病罪：明知自己患有梅毒、淋病等严重性病卖淫、嫖娼的，处五年以下有期徒刑、拘役或者管制，并处罚金（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-24', 'concept_archive_s9-24', 'recommendation', '先说民事。著作权法给作者的权利里有翻译权，就是把作品从一种文字转成另一种文字的权利。还有信息网络传播权，就是把作品放到网上、让公众随时随地能看到的权利。没经许可翻译别人的作品，是侵权。没经许可把作品传到网上，也是侵权。侵权的要停止侵害、赔偿损失。只有为个人学习、研究或者欣赏，用别人已经发表的作品，才不用许可、不用付钱。赔多少，先按权利人的实际损失或者你挣到的钱算。都算不清的，由法院在 500 元到 500 万元之间定。故意侵权、情节严重的，可以判 1 到 5 倍。权利人为制止侵权花的合理开支，也要你一起赔。再说刑事。刑法第二百一十七条的前提是「以营利为目的」。为了挣钱，没经许可把别人的作品放到网上给公众看，够了门槛就是侵犯著作权罪。判 3 年以下，同时罚钱，或者只罚钱。数额巨大或者情节特别严重的，判 3 到 10 年并罚钱。什么算为了挣钱：除了卖，在网页上挂收费广告的算，用会员制收注册费或者其他费用的也算。收来的服务费、会员费、广告费，都算违法所得。够罪的门槛，下面到一条就够。违法所得 3 万元以上。非法经营数额 5 万元以上，人人影视案里算的是会员费、广告费和卖硬盘的总收入。在网上传播别人的作品合计 500 件（部）以上。被下载 1 万次以上，或者被点击 10 万次以上。用会员制传播，注册会员 1000 人以上。几项都没到，但有两项各到了一半以上，也算。到这些数的 10 倍，就进 3 到 10 年那一档。罚金一般是违法所得的 1 到 10 倍。官方案例一：梁永平等人从境外网站下载没授权的影视剧，组织人翻译、做字幕后上传。这些片子放在「人人影视字幕组」网站和客户端上，供人在线看和下载。网站里没授权的影视作品有 32824 部，会员 683 万余个。2018 年 1 月到 2021 年 1 月，收会员费 270 余万元，广告费 880 余万元。卖拷了影视剧的移动硬盘，又挣了 100 余万元。网站挂着「捐赠」二维码，捐了就能得到会员权益。检察机关认定，这就是换了个名目收会员费。2021 年 11 月 22 日，梁永平被判 3 年 6 个月，罚金 150 万元。另外 14 人判 1 年 6 个月到 3 年，都是缓刑，罚 4 万到 35 万元。官方案例二：柯某某用爬虫软件抓了 5 万余部影视剧的播放地址，放到自己的网站和 App 上让人免费看。他在开屏位置投广告，按展现量收钱，挣了 35 万余元。2023 年他被判 3 年、缓刑 4 年，罚金 40 万元。官方案例三：黄某在自己家里租服务器，搭了一个音乐下载论坛。他把 10 万余首歌传进 18 个网盘，在论坛发链接。会员要充值换论坛币，才能拿到链接和提取码。会员充值共 50 余万元。2023 年他被判 3 年、缓刑 4 年，罚金 55 万元（全国，司法解释 2025 年 4 月 26 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-25', 'concept_archive_s9-25', 'recommendation', '江南的小说《此间的少年》，用了郭靖、黄蓉、乔峰、令狐冲等金庸小说里的人物名字。书里讲的是这些人在大学校园里的故事。2002 年出版时，副标题是「射雕英雄的大学生涯」。到起诉时，这本书出了多个版本，发行上百万册。金庸 2016 年起诉江南和出版方，索赔 500 万元。一审认为不构成著作权侵权。理由是：离开了具体情节，光是人物名字、关系和性格，很难算受保护的具体表达。但一审认定，江南借原作名气吸引读者，构成不正当竞争。按历年版税 560 万元的 30%，判赔 168 万元，外加律师费 20 万元。二审由广州知识产权法院审理，改判构成著作权侵权。二审认为，两本书的故事情节不算实质性相似，也就是情节没有抄。但 60 多个人物合起来的「人物群像」，名字、性格、关系和背景都是金庸的选择和安排。这属于著作权法保护的表达，江南侵害了金庸四部小说的著作权。副标题故意和《射雕英雄传》挂钩，另外构成不正当竞争。二审判江南停止不正当竞争、登报消除影响，赔 168 万元和合理开支 20 万元。两家出版发行公司对其中 33 万元承担连带责任，也就是这部分要一起赔。二审没有判停止侵权，但要求以后再版，按再版版税收入的 30% 付给原作权利人。二审之后，双方都向广东省高级人民法院申请再审。2025 年 9 月 19 日，各方在广东高院主持下达成和解。和解里，各方同意不把这件事定性为「剽窃」。江南承认，他创作时缺乏著作权法律知识，没有事先取得金庸的改编许可，给金庸造成了损害。江南同意不再原样再版这本书。以后再版，不再用金庸作品里的独创人物名字和相关内容。各方确认，那个副标题构成不正当竞争。二审判的赔偿，江南已经付了。调解书签收后，原来的一审、二审判决都不再有法律效力。另一个案子的被告是《鬼吹灯》作者张牧野，笔名天下霸唱。2006 年，他把这套小说著作权里的财产权全部转让给了上海玄霆娱乐信息科技有限公司。后来他授权出版新书《摸金校尉》，书里用了《鬼吹灯》的人物名字、人物关系和盗墓规矩。新书封面用了《寻龙诀》的电影海报，这部电影是从《鬼吹灯》改编的。玄霆公司起诉，索赔 2000 万元。上海浦东法院认为，新书有自己独立的情节，不算侵犯著作权。但封面让读者误以为这本书和《寻龙诀》原著有关，构成虚假宣传。法院判两家出版发行公司赔 90 万元，出版社对其中 60 万元承担连带责任，二审维持。法条上，改编权是改变作品、创作出有独创性的新作品的权利。没经著作权人许可，用改编、翻译、注释等方式使用作品，要承担停止侵害、赔偿损失等民事责任（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s9-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s9-26', 'concept_archive_s9-26', 'recommendation', '先看治安管理处罚法第三十八条。非法携带弩、匕首等国家规定的管制器具的，拘留 5 日以下，可以再罚 1000 元以下。情节较轻的，警告或者罚 500 元以下。带进公共场所或者公共交通工具的，拘留 5 到 10 日，可以再罚 1000 元以下。刑法第一百三十条更重。非法携带管制刀具进入公共场所或者公共交通工具，危及公共安全、情节严重的，判 3 年以下。哪些刀算管制刀具，公安部 2007 年的认定标准列了五类。第一类是匕首：有刀柄、刀格和血槽，刀尖角度小于 60 度。第二类是三棱刮刀。第三类是带自锁装置的弹簧刀，俗称跳刀。第四类是刀尖角度小于 60 度、刀身超过 150 毫米的刀。第五类是刀尖角度大于 60 度、刀身超过 220 毫米的刀。没开刃、刀尖磨圆的武术和工艺礼品刀不算。警棍是警察的警械。人民警察法规定，警械只许警察持有和使用。别人持有的，没收，拘留 15 日以下或者警告，可以再按违法所得罚 5 倍以下。铁路的禁带目录把警棍、催泪器、电击器、防卫器都列为管制器具。坐火车时这些东西不许随身带，也不许托运。车里放着一样会被查：有人开车带着管制刀具过检查站，被民警查获，行政拘留。真用了的账，看正当防卫指导意见。它把「是否使用或者准备使用凶器」列为区分防卫和互殴的情节之一。官方案例：杨某和人吵架，对方扬言找人报复，他回家把两把刀藏在身上。对方回来空手打了他脸一拳，他拿刀捅对方胸腹，对方死亡。法院认定他有防卫性质，但对方只是空手打，他捅的是要害，属于防卫过当。他以故意伤害罪被判 4 年（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s9-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-1', 'concept_archive_s10-1', 'recommendation', '两场闪电约会研究里，参与者见面前先填了 100 多项与择偶有关的自陈量表（自己给自己打分的问卷）。研究者用随机森林模型（一种找规律的算法）来算。能算出「一个人整体上有多容易喜欢别人」，这些问卷能说明其中 4%–18% 的方差，方差就是人与人之间的差别，问卷只能说明其中一小部分。也能算出「一个人整体上有多受欢迎」，能说明 7%–27%。但「这两个具体的人之间来不来电」算不出来，会前的特质和偏好怎么组合都算不出来。同一批研究者更早还做过一项闪电约会实验。参与者会前自己报了理想型偏好，比如看重外貌还是看重经济前景。这个偏好预测不了他们在现场对具体某个人的兴趣', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-2', 'concept_archive_s10-2', 'recommendation', '2026 年 1 月 1 日起施行的治安管理处罚法，把纠缠、跟踪单列成一项。条文写的是「多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的」。这种行为处五日以下拘留，或者一千元以下罚款。情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款。这一项还多一层：经公安机关负责人批准，可以责令行为人在一定期限内禁止接触被侵害人。违反禁止接触规定的，再处五日以上十日以下拘留', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-3', 'concept_archive_s10-3', 'recommendation', '两项研究测了人识别调情的准确率。第一项让 52 对互不相识的异性两两交谈 10 到 12 分钟。谈完各自报告自己有没有在调情，也报告觉得对方有没有在调情。结果是「没有发生调情的互动被判断得更准，发生了调情的互动反而判断得更差」。第二项用 26 段一分钟的视频，给 261 名旁观者判断，结论一致。人能比较可靠地看出「对方没在调情」，却很难看出「对方在调情」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s10-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-4', 'concept_archive_s10-4', 'recommendation', '29 个实验室、43 份纵向配对数据的机器学习分析，纵向就是跟着同一批伴侣一路记录。最能预测关系质量的几项，全部来自当事人对这段关系的感受：感觉到对方的承诺、欣赏、性满意度、感觉到对方满意、冲突。跟个人有关的几项里最强的是生活满意度、负面情绪、抑郁、回避型依恋、焦虑型依恋。关于关系的这些项，在刚开始调查时最多能解释 45% 的方差。方差指伴侣与伴侣之间关系质量的差别，45% 是其中能用这些项说清的部分。到研究结束时最多解释 18%。而且「自己报告的那些项」的预测力，是「伴侣报告的那些项」的二到四倍。在自己报告的关系感受之外，再把个体差异和伴侣的报告加进来，没有多出任何预测力', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-5', 'concept_archive_s10-5', 'recommendation', '把互不相识的两人配对，让他们轮流回答三组逐步深入的问题，一共 36 题。问题从「你最想请谁吃饭」一直到「上一次当着别人的面哭是什么时候」。45 分钟后的亲近感，显著高于做同样时长闲聊的对照组。也高于该研究中大学生对自己现实中最亲密关系的平均评分', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s10-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-6', 'concept_archive_s10-6', 'recommendation', '两项研究的结论一致。异地恋在分开期间反而比同城恋更稳定。原因是异地关系里把对方想得比实际更好的程度明显更高，研究测的是理想化失真、浪漫爱、关系回忆、感知到的一致这几项。而且见面越少，想得越美。但这种稳定只在双方仍然分开时成立，一旦变成同城，异地伴侣更容易分手。追踪异地转同城的那项研究给出的比例是：约一半异地伴侣走到了搬到一起这一步，另一半在分开期间就结束了。在重聚的这一半里，三分之一在重聚后 3 个月内分手。分开期间见面间隔越长、理想化越强，重聚后越不稳', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s10-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-7', 'concept_archive_s10-7', 'recommendation', '2024 年全国依法办理结婚登记 610.6 万对，比上年下降 20.5%，结婚率 4.3‰。同年依法办理离婚手续 351.3 万对，其中民政部门登记离婚 262.2 万对，法院判决和调解离婚 89.1 万对，离婚率 2.5‰。公报注明，结（离）婚率 = 当年结（离）婚对数 / 当年平均总人口数 × 1000‰。这是「粗率」，分母是全体人口，不是已婚人口', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-8', 'concept_archive_s10-8', 'recommendation', '一项针对老年人的荟萃分析，把多项研究汇总重算，共 53 组比较、25 万余人。已婚相对非婚的全因死亡 RR 0.88，95% CI 0.85–0.91（RR 是风险比，CI 是可信范围），同期死亡的概率低约 12%。同一项里丧偶 1.11、离异或分居 1.16、未婚 1.11，分别高约 11%、16%、11%。男女无差异。最保守的估计是 RR 0.94，只低约 6%。另一项荟萃分析比的是未婚（从未结婚）相对已婚，用了 95 篇文献、5 亿余人。结果 HR 1.24（1.19–1.30），同期死亡的概率高约 24%。而且年纪越大，差距越小。还有一项按性别拆的荟萃分析，21 项研究、789 万余人：不论男女，非婚都与总死亡、癌症死亡、心血管死亡同时出现。男性这边的心血管死亡和总死亡差距更大。未婚男性相对未婚女性，卒中死亡多 31%，全因死亡多 9%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-9', 'concept_archive_s10-9', 'recommendation', '2024 年全国时间利用调查。无酬劳动就是家务、陪伴照料家人这些没有报酬的活。当天做了这类活的人，每日平均花 2 小时 45 分，其中男性 1 小时 52 分、女性 3 小时 29 分。一天里做过这类活的人占多大比例，男性是 67.5%、女性是 83.9%。居民家务劳动每日平均 1 小时 17 分，只算做了的人是 1 小时 59 分，比 2018 年少 28 分。陪伴照料家人每日平均 30 分，只算做了的人是 1 小时 46 分。2018 年的数字是：家务劳动男性 45 分、女性 2 小时 6 分，陪伴照料孩子男性 17 分、女性 53 分', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-10', 'concept_archive_s10-10', 'recommendation', '不另作约定时的默认规则是：婚后所得的工资奖金劳务报酬、生产经营投资收益、知识产权收益、继承或受赠财产，归夫妻共同所有（第一千零六十二条）。婚前财产、人身损害赔偿、遗嘱或赠与合同明确只归一方的财产、一方专用生活用品，是个人财产（第一千零六十三条）。双方可以书面约定婚前和婚后财产归各自所有、共同所有，或者部分各自所有部分共同所有，这个约定对双方有法律约束力（第一千零六十五条）。因抚育子女、照料老人、协助另一方工作而负担较多义务的一方，离婚时有权请求补偿（第一千零八十八条）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-11', 'concept_archive_s10-11', 'recommendation', '婚前父母为双方购房出资的，认定为对自己子女个人的赠与。父母明确表示赠与双方的除外。婚后出资的，有约定按约定。没有约定或者约定不明确的，按夫妻共同财产的原则处理。2025 年 2 月 1 日起还有一条。婚内由一方父母全额出资、赠与合同又没写明只赠与自己子女的，离婚分割时，法院可以判房屋归出资人子女一方所有。判归之后再综合几项情况，确定要不要给另一方补偿、补多少。这几项是共同生活和生育共同子女的情况、离婚过错、对家庭的贡献大小、离婚时房屋市场价格。一方父母部分出资，或者双方父母都出资的，以出资来源和比例为基础判归其中一方，并合理补偿（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-12', 'concept_archive_s10-12', 'recommendation', '下面几种情形借的钱属于夫妻共同债务。一是夫妻双方共同签名的。二是一方事后追认，就是事后认下这笔债，两个人都认账。三是一方在婚内以个人名义为家庭日常生活需要借的。一方以个人名义借的、明显超出家庭日常开销的钱，不属于夫妻共同债务。例外是债权人（要债的一方）能证明这笔钱用于夫妻共同生活、共同生产经营，或者是两个人都认的账。买房的钱明显超出家庭日常生活需要，举证责任在主张债权的一方，要债的人得自己拿出证据。但这笔钱如果确实变成了夫妻共同居住或共有的房子，债权人往往能证到「用于夫妻共同生活」这一层。所以更管用的是第 11 条（父母出资时写清是借是送）那一步（全国，2021 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-13', 'concept_archive_s10-13', 'recommendation', '2025 年 5 月 10 日起施行的新婚姻登记条例，改了内地居民结婚要交的材料。条文写的是只需出具两样东西：「（一）本人的居民身份证；（二）本人无配偶以及与对方当事人没有直系血亲和三代以内旁系血亲关系的签字声明」。户口簿不再是必需材料。登记机关是「县级人民政府民政部门或者省、自治区、直辖市人民政府按照便民原则确定的乡（镇）人民政府」。旧条例里「到一方当事人常住户口所在地」的限制已经取消。条例还写明「婚姻登记机关办理婚姻登记，不得收取费用」，以及「对当事人符合结婚条件的，应当当场予以登记，发给结婚证」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-14', 'concept_archive_s10-14', 'recommendation', '隐瞒的法律后果是明确的。新婚姻登记条例规定「一方当事人患有重大疾病的，应当在结婚登记前如实告知另一方当事人；不如实告知的，另一方当事人可以依据民法典第一千零五十三条的规定向人民法院请求撤销婚姻」。国家把婚检当作出生缺陷防治的第一道关口。现行目标是「婚前医学检查率、孕前优生健康检查目标人群覆盖率分别保持在 70% 和 80% 以上」。文件还要求「推进婚前医学检查机构与婚姻登记场所就近设置方便群众」，并推广「婚姻登记、婚前医学检查、生育指导『一站式』服务」。民法典规定，一方患有重大疾病的应当在结婚登记前如实告知，不如实告知的，另一方可以向人民法院请求撤销婚姻。请求撤销婚姻的，应当自知道或者应当知道撤销事由之日起一年内提出', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s10-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-15', 'concept_archive_s10-15', 'recommendation', '协议离婚要签书面离婚协议，并亲自到婚姻登记机关申请（第一千零七十六条）。自登记机关收到申请之日起 30 日内，任何一方可以撤回。期满后 30 日内，双方须亲自申领离婚证，不申领视为撤回（第一千零七十七条）。一方不同意时走诉讼，法院应先调解。有重婚或与他人同居、家庭暴力或虐待遗弃、赌博吸毒屡教不改、因感情不和分居满二年等情形的，调解无效应准予离婚。判不离后又分居满一年，再起诉应准予（第一千零七十九条）。2024 年全国离婚 351.3 万对，其中 89.1 万对走的是法院判决、调解', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-16', 'concept_archive_s10-16', 'recommendation', '长辈的收益是真实的。但它不会自动转成你的健康收益（第 8 条）或关系质量（第 4 条，关系好不好看自己的感受）。而时间账（第 9 条）、钱账（第 10 到 12 条）和退出成本（第 15 条），全部由当事人承担。分开记账以后，「做任务式结婚」的性价比是高是低，自己就能看出来', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s10-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-17', 'concept_archive_s10-17', 'recommendation', '把 126 篇研究、7.2 万多人合起来算（荟萃分析）。婚姻质量越高，身体越好，相关系数 r 在 .07 到 .21 之间。相关系数 0 是毫无关系，1 是完全同步。其中和死亡风险更低的相关是 r = .11。吵架时心血管反应更小，r = -.13。作者说，这些效应都小，和饮食这类健康习惯与健康的关联差不多大。另一项交叉实验里，42 对健康夫妻各住院两次，每次 24 小时。一次做互相支持的谈话，一次讨论一件有分歧的事。吵完之后，实验做出的水泡伤口愈合更慢。两次都表现出更多敌意的夫妻，伤口愈合速度只有低敌意夫妻的 60%。吵架第二天早上，他们血里的炎症指标（IL-6、肿瘤坏死因子）也升得更多。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s10-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-18', 'concept_archive_s10-18', 'recommendation', '民法典第一千零四十五条列的近亲属是配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女。第一千一百二十七条的法定继承人先是配偶、子女、父母，其次是兄弟姐妹、祖父母、外祖父母。伴侣两处都不在。第一千二百一十九条管的是手术、特殊检查、特殊治疗。不能或者不宜向患者说明的，医务人员要向患者的「近亲属」说明，并取得同意。有三条路可以补上。第一，第三十三条允许成年人和「其他愿意担任监护人的个人」事先书面约定监护人。本人丧失或者部分丧失民事行为能力后，这个人来当监护人，监护人就是法定代理人。第二，第一百六十五条规定，书面授权委托书要写明代理人的姓名、代理事项、权限和期限，由本人签名或者盖章。本人一去世，委托就终止。第三，第一千一百三十三条允许立遗嘱，把个人财产赠给法定继承人以外的个人。湖北省司法厅网站刊登的宜昌市司法局文章写明，同性伴侣可以办意定监护协议公证，指定对方当自己将来的监护人（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-19', 'concept_archive_s10-19', 'recommendation', '民法典第一千零五十一条规定，婚姻无效只有三种情形：重婚、有禁止结婚的亲属关系、未到法定婚龄。第一千零五十二、一千零五十三条规定，能撤销的只有两种：被胁迫结婚，婚前隐瞒重大疾病。婚姻家庭编解释（一）第十七条规定，拿这三种以外的理由请求确认婚姻无效，法院判决驳回。所以想退出只能离婚。形婚登记了也是合法婚姻。第一千零六十二条规定，婚后的工资、奖金、劳务报酬等是夫妻共同财产。第一千零六十四条规定，两人共同签字借的债、一方为家庭日常生活借的债，是夫妻共同债务。离婚损害赔偿看第一千零九十一条，限于重婚、与他人同居、家庭暴力、虐待遗弃家庭成员，以及「有其他重大过错」。解释（一）第二条把「与他人同居」限定为和「婚外异性」同居。所以同性关系只能按「其他重大过错」去争。赔偿包括精神损害赔偿，被瞒的一方起诉离婚时要一并提出，判不离就不支持。民法典施行后，没有查到法院公开的这类判决。旧法时期，江苏省高级人民法院网站 2013 年刊登的一篇文章，讨论了妻子因丈夫隐瞒同性恋起诉离婚的案子。文章列了两种看法。一种认为同性恋不在当时法定的过错里，多分财产和精神赔偿都不该支持。作者赞同另一种：把被瞒的一方当作「无过错方」，分财产时照顾她，还应赔精神抚慰金（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s10-20', 'concept_archive_s10-20', 'recommendation', '2020 年一项荟萃分析汇总了 58 项研究、2092 对伴侣。做完伴侣治疗，关系满意度的前后变化 g = 1.12（可信范围 0.92–1.31），作者说是大效应。g 是效应量，见 README 术语表。分到排队等候的伴侣，同一段时间 g = 0.12（−0.04 到 0.29），没有明显改善。开始时关系越差的，改善反而越多。2012 年一篇综述写的是，伴侣治疗让 70% 接受治疗的伴侣有好转。另一项随机试验找了 134 对长期、严重不和的夫妻，做了约 8 个月的两种行为伴侣治疗。做完时满意度变化 d = 0.90 和 0.71。到第 5 年，两种做法分别有 50.0% 和 45.9% 的夫妻仍有明显好转。这里的明显好转，作者叫「有临床意义的改善」。同时有 25.7% 和 27.9% 已经分居或离婚', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s10-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-1', 'concept_archive_s11-1', 'recommendation', '任何单位和个人发现犯罪事实，都有权去报案。办案机关认为有犯罪事实，就应当立案。被刑事拘留之后，公安要在 3 日内提请批捕（向检察院申请正式逮捕）。特殊情况可以延长 1 到 4 日。流窜作案（跨地方连续作案）这类情形可以延长到 30 日。检察院再用 7 日决定。加起来最长 37 天内决定捕不捕。从第一次讯问起，或者从被采取强制措施（被拘留、逮捕这一类）起，你就可以委托律师。案子还在公安手里查的阶段，只能委托律师。律师要求会见，看守所最迟 48 小时内安排。可能判管制、拘役这类比坐牢轻的刑罚，或者只判附加刑、不判主刑的，可以取保候审：交一笔保证金或者找个保证人，先回家等着办案。取保最长 12 个月（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s11-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-2', 'concept_archive_s11-2', 'recommendation', '提供专门用于侵入、非法控制计算机信息系统的程序、工具，情节严重的判 3 年以下，并处或单处罚金。并处是判刑的同时罚钱，单处是只罚钱。情节特别严重的判 3 到 7 年并处罚金。「情节严重」的门槛是提供工具 20 人次以上，或者违法所得 5000 元以上。违法所得就是靠这件事挣到的钱。故意绕开或者破坏权利人设的技术保护措施，还可能构成侵犯著作权罪，判 3 年以下，严重的判 3 到 10 年。官方案例：王某等人制售外挂，靠读取和修改游戏内存实现透视、自瞄。3 个月卖了 8 万余元，获利 3 万余元。判 1 年缓 1 年、罚 5000 元。缓 1 年就是判了 1 年但先不关，这一年里不再犯事就不用去坐牢。项某等人卖「TZ」系列外挂，销售额 20 余万元，项某判 3 年缓 3 年、罚 2 万元。刘某某等人拿到游戏服务端程序，改参数开私服，收了充值 2000 余万元。判 4 年到 2 年 6 个月，罚 1000 万到 130 万元。不只是游戏。上海一家公司做了刷机包，让手机里的微信多出自动转发、点赞、群发等几十种功能，当「营销手机」卖了 2381 台。2019 年上海徐汇法院按侵犯著作权罪判公司罚金 50 万元，负责人判 1 年 6 个月缓 1 年 6 个月（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-3', 'concept_archive_s11-3', 'recommendation', '侵入计算机信息系统，或者用其他技术手段拿到里面的数据，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。「情节严重」的门槛是违法所得 5000 元以上，或者造成损失 1 万元以上。官方案例：某人用外挂批量导入买来的 12306 账号，多线程密集提交购票请求。他代抢火车票 200 余张，获利 2 万余元。法院以非法获取计算机信息系统数据罪，判他 1 年 6 个月缓 1 年 6 个月、罚 5000 元。郑某在网店卖针对某售票 App 的抢票软件，被判构成不正当竞争，赔 2 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-4', 'concept_archive_s11-4', 'recommendation', '绕过防护拿系统里的数据，量刑和第 3 条（抢票秒杀刷单脚本）一样，判 3 年以下，或者 3 到 7 年。非法获取、出售或者提供公民个人信息，达到下面任何一条就算「情节严重」：行踪轨迹、通信内容、征信、财产信息 50 条以上；住宿、通信记录、健康、交易信息 500 条以上；其他个人信息 5000 条以上；违法所得 5000 元以上。情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。官方案例：软件开发人员李某把窃取手机相册的功能伪装成「颜值检测」软件，拿到人脸照片 1751 张，还倒卖社工库资料，判 3 年缓 3 年。社工库就是把各处泄露的个人信息汇总起来的数据库。某网络科技公司用爬虫拿外卖平台的店铺、订单数据，造成损失 4 万余元，被以非法获取计算机信息系统数据罪追诉（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-5', 'concept_archive_s11-5', 'recommendation', '明知别人在利用网络犯罪，还给他提供技术支持、支付结算这类帮助，情节严重的判 3 年以下，并处或单处罚金。同时还构成其他犯罪的，按更重的那个罪判。开设赌场判 5 年以下并处罚金，情节严重的判 5 到 10 年。官方案例：张盛集团研发赌博游戏后「包网外销」，收建站费、报表费。涉案近 70 亿元。张盛判 9 年 9 个月、罚 5000 万元。负责外包研发的王强等 79 人，判 6 个月到 9 年 9 个月不等。陈东等人开发运营电竞竞猜 App，技术团队在海南写代码，28 人以开设赌场罪判 3 年 6 个月到 1 年不等，并处罚金。张某某开工作室替诈骗团伙解封被封的 QQ 号，判 1 年 6 个月、罚 2 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-6', 'concept_archive_s11-6', 'recommendation', '非法控制计算机信息系统，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。删除、修改系统功能或者数据，造成系统不能正常运行，后果严重的判 5 年以下，特别严重的判 5 年以上。官方案例：IT 高级工程师吕某某被辞退后，用原管理员账号登录公司共享服务器。他改了密码，删了数据和日志，造成损失 12 万余元。判 3 年缓 5 年、罚 3 万元。软件公司员工白某某写升级程序时故意加进错误代码，导致客户系统无法登录，损失 4 万余元，以破坏计算机信息系统罪追诉（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-7', 'concept_archive_s11-7', 'recommendation', '违反保密义务，把商业秘密说出去或者自己拿来用，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 10 年并处罚金。反不正当竞争法还把两件事列为侵权：用「电子侵入」（技术手段侵入系统）拿商业秘密；教唆、帮助别人违反保密义务。官方案例：孙某明等离职员工带走安检系统源码和核心算法，用在新公司的产品上，孙某明判 5 年、罚 50 万元，新公司罚 400 万元。田某某利用系统漏洞下载 3.3 万余个设计文件，判 1 年 10 个月、罚 10 万元。工程师杨某某把 App 模块源码存进个人电脑和云端，跳槽后做同类 App，以侵犯商业秘密罪追诉（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-8', 'concept_archive_s11-8', 'recommendation', '对计算机信息系统实施非法控制，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。非法控制 20 台以上就算「情节严重」。还够不上犯罪的，公安没收违法所得，拘留 5 日以下，并可以罚 5 万到 50 万元。情节较重的拘留 5 到 15 日，并可以罚 10 万到 100 万元。受过治安处罚的 5 年内、受过刑事处罚的终身，不得从事网络安全管理和网络运营的关键岗位。官方案例：李某买来网络摄像头的 IP，用软件控制了 105 台摄像头窥探隐私，判 3 年缓 5 年、罚 2 万元。吴某等人把木马植入手机主板，控制 330 余万部手机回传验证码，判 2 年到 4 年 6 个月（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-9', 'concept_archive_s11-9', 'recommendation', '普通公司和个人的系统，属于国家事务、国防建设、尖端科学技术领域以外的计算机信息系统。侵入这类系统，或者采用其他技术手段，拿到里面存储、处理、传输的数据，情节严重的判 3 年以下有期徒刑或者拘役，并处或单处罚金。特别严重的判 3 到 7 年并处罚金。「情节严重」有几条标准：拿到支付结算、证券交易、期货交易等网络金融服务的身份认证信息（账号密码这类）10 组以上；拿到其他身份认证信息 500 组以上；非法控制计算机信息系统 20 台以上；违法所得 5000 元以上，或者造成经济损失 1 万元以上。上面这些数字的 5 倍以上，就是「情节特别严重」。官方案例：检例第 36 号确立了一句话，「超出授权范围使用账号、密码登录计算机信息系统，属于侵入计算机信息系统的行为」。意思是手里本来就有账号密码，但用在授权范围以外，这个行为本身就算侵入。该案三人用工作中掌握的账号、密码和令牌，异地登录公司内部系统，下载了不属于工作范围的数据，拿到网上出售，违法所得 37000 元。三人分别判 4 年、3 年 9 个月、4 年，各罚 4 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-10', 'concept_archive_s11-10', 'recommendation', '这份规定管三类对象：境内的网络产品提供者、网络运营者，以及从事漏洞发现、收集、发布等活动的组织或者个人。任何组织或者个人，不得利用漏洞从事危害网络安全的活动，不得非法收集、出售、发布漏洞信息。向社会发布漏洞信息要守五条。第一，不得在产品提供者提供修补措施之前发布。第二，不得发布网络运营者在用的网络、信息系统及其设备存在漏洞的细节情况。第三，不得刻意夸大危害和风险，不得利用漏洞信息实施恶意炒作或者诈骗。第四，不得发布或者提供专门用于利用漏洞从事危害网络安全活动的程序和工具。第五，发布时应当同步发布修补或者防范措施。另外，未公开的漏洞信息，不得提供给产品提供者之外的境外组织或者个人。规定鼓励把漏洞报给四个官方平台。一是工业和信息化部网络安全威胁和漏洞信息共享平台。二是国家网络与信息安全信息通报中心漏洞平台。三是国家计算机网络应急技术处理协调中心漏洞平台。四是中国信息安全测评中心漏洞库。违反规定收集、发布漏洞信息的，由工业和信息化部、公安部依据各自职责依法处理。构成网络安全法规定情形的，依该法处罚。向社会发布系统漏洞等网络安全信息，应当遵守国家有关规定。违反的，由有关主管部门责令改正、给予警告，可以处 1 万元以上 10 万元以下罚款。拒不改正或者情节严重的，处 10 万元以上 100 万元以下罚款。还可以责令暂停相关业务、停业整顿、关闭网站或者应用程序。也可以吊销相关业务许可证或者吊销营业执照。对直接负责的主管人员和其他直接责任人员，处 1 万元以上 10 万元以下罚款（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-11', 'concept_archive_s11-11', 'recommendation', '直接进行国际联网，必须使用国家公用电信网提供的国际出入口信道。任何单位和个人不得自行建立或者使用其他信道：既不能自己搭线路出境，也不能用别人搭的。违反的，由公安责令停止联网、给予警告，可以并处 1.5 万元以下罚款，没收违法所得。靠这个做生意的，办案机关可以按非法经营罪处理。情节严重的判 5 年以下，并处或单处违法所得 1 到 5 倍的罚金。特别严重的判 5 年以上（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s11-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-12', 'concept_archive_s11-12', 'recommendation', '竞业限制只能约束高管、高级技术人员，以及其他负有保密义务的人。期限最长 2 年。公司必须在这段期限内按月给经济补偿。没有约定补偿数额的，按离职前 12 个月平均工资的 30% 给，并且不低于当地最低工资。因为公司自己的原因 3 个月没付，劳动者可以请求解除这份竞业限制。公司主动解除的，要额外付 3 个月补偿。2025 年起，岗位上没知道、没接触过商业秘密的劳动者，可以请求确认条款不生效。约定范围超出他实际知道的那部分秘密的，超出的部分无效。官方案例：某医药公司起诉首席技术官郑某，索赔违约金 710 万元。法院认定他新东家的产品与原公司不具替代性，竞业范围应当限于他实际知悉的秘密，判决全部驳回（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-13', 'concept_archive_s11-13', 'recommendation', '为完成单位工作任务创作的作品是职务作品（上班干活做出来的东西）。一般情形下著作权归作者，单位有权在业务范围内优先使用，并且 2 年内作者不得许可第三人以相同方式使用。但有两类情况不一样。一类是主要利用单位物质技术条件创作、并由单位承担责任的工程设计、软件等作品。另一类是合同约定归单位的作品。这两类作者只保留署名权。单位物质技术条件指的是公司的设备、内网、业务数据这些。执行本单位任务，或者主要利用本单位物质技术条件完成的发明创造，是职务发明，申请专利的权利和拿到的专利权都归单位（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-14', 'concept_archive_s11-14', 'recommendation', '侵犯著作权，按权利人的实际损失赔，或者按侵权人挣到的钱赔。这两样都算不清的，参照正常买这份授权要付多少钱来定。故意侵权并且情节严重的，可以判 1 到 5 倍赔偿。损害公共利益的，还可以没收违法所得并处罚款。官方案例：（2021）最高法知民终 51 号。被告招聘了原告的前员工，开发出的网关软件与原告软件实质相似。被告抗辩说，原告软件基于 GPLv2、本来就该开源。最高法认定「开发者自身是否违反 GPLv2 协议和是否享有软件著作权是两个独立问题」，判停止侵害、赔偿 50 万元（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s11-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-15', 'concept_archive_s11-15', 'recommendation', '处理个人信息应当有明确合理的目的，与这个目的直接相关，并且采取对个人权益影响最小的方式。处理个人信息要取得个人同意，或者符合法定情形。不满 14 周岁的，必须取得父母或者监护人同意。违反的，由监管部门责令改正、给予警告、没收违法所得，对违法的 App 责令暂停或者终止提供服务。拒不改正的罚 100 万元以下，对直接负责的主管人员和其他直接责任人员罚 1 万到 10 万元。情节严重的罚 5000 万元以下，或者上一年度营业额 5% 以下。责任人员罚 10 万到 100 万元。这些人还可能被禁止在一定期限内担任相关企业的董事、监事、高管。出售或者提供个人信息构成犯罪的，见第 4 条（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s11-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-16', 'concept_archive_s11-16', 'recommendation', '经营性的互联网信息服务实行许可，非经营性的实行备案。没有取得许可、或者没有备案的，不得从事。未备案的，由电信管理机构责令改正，拒不改正的责令关闭网站。未经许可经营的，没收违法所得，并罚违法所得的 3 到 5 倍，或者罚 10 万到 100 万元。网站主页不标备案号，罚 5000 元到 5 万元。网络运营者要按等级保护制度（等保）制定安全管理制度、防范攻击、留存网络日志不少于 6 个月、对数据分类备份加密。不履行的，责令改正、给予警告。拒不改正或者造成后果的，罚 1 万到 10 万元，主管人员罚 5000 元到 5 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-17', 'concept_archive_s11-17', 'recommendation', '提供具有舆论属性或者社会动员能力的生成式人工智能服务，应当按国家规定开展安全评估，并按算法推荐管理规定办算法备案，以及后续的变更、注销手续。舆论属性或者社会动员能力，指的是能影响公众看法，或者能把人组织动员起来。提供者应当对图片、视频等生成内容进行标识。办法自 2023 年 8 月 15 日施行（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s11-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-18', 'concept_archive_s11-18', 'recommendation', '法律规定，经营者不得利用技术手段，妨碍、破坏其他经营者合法提供的网络产品或服务正常运行。这里的经营者，指提供商品或服务的自然人、法人和非法人组织。给对方造成损害的，按对方的实际损失赔，或者按你因此得到的好处赔，再加上对方为制止侵权花的合理开支。市场监管部门还可以罚 10 万到 100 万元，情节严重的罚 100 万到 500 万元。官方案例：720 浏览器的内置功能默认拦截芒果TV 网站的片头广告和暂停广告。一审驳回了芒果TV 的起诉。广州知识产权法院二审改判，认定构成不正当竞争，判赔经济损失和合理开支 80 万元。2021 年最高法把它列为典型案例。「拦精灵」App 让用户直接跳过芒果TV 的开屏广告。一审判它停止，赔经济损失 8 万元、合理开支 1 万元。2024 年 4 月，北京知识产权法院二审维持。二审认为它实际是把开屏广告屏蔽了，不只是替用户点「跳过」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s11-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s11-19', 'concept_archive_s11-19', 'recommendation', '国家安全部 2026 年 6 月发布风险提示。提示说，AI 中转站是夹在用户和模型厂商官方服务之间的代理层。部分中转站运营资质缺失。有的没取得数据出境的合规资质，也没走安全评估的法定流程，就把用户输入的数据传到境外服务器。有的还能让用户绕过网络访问、官方授权和跨境传输的限制。《中国新闻周刊》2026 年 6 月报道了一个案子。2026 年 5 月，一名上海的中转站站长在技术社区发了关停声明。他说自己因为非法获取大模型接口，被上海警方刑事拘留 37 天，现在取保候审。他说「将来肯定会被判刑」，已经退赔退赃，还要交罚金。报道说，这类中转站批量注册或购买境外大模型的订阅账号，在海外架服务器当跳板，再低价转卖给国内用户（全国 / 上海）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s11-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-1', 'concept_archive_s12-1', 'recommendation', '亏了不只是钱没了。个体工商户欠的债，如果生意是你一个人做的，要拿你自己名下的钱和东西还（以个人财产承担）。如果是全家一起做的，或者分不清是谁做的，要拿全家的钱和东西还（以家庭财产承担）。夫妻两人都签了字的债，算两个人一起还的共同债务。一方事后点了头的，也算。一方用自己名义借的钱，只要债主能证明这笔钱用在了两口子一起做的生意上，照样两个人一起还。公司这边也有一条：公司还不上到期的债时，股东当初在注册资本里答应出、还没到缴纳期限的那笔钱（认缴出资），债主可以要求他提前交出来（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s12-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-2', 'concept_archive_s12-2', 'recommendation', '担保书上的那句话，意思就是「欠钱的人不还，由你来还」。写成「连带责任保证」的，债主可以不去找公司，直接上门找你要。写成「一般保证」的，债主得先去告公司或者去仲裁，再请法院把公司的财产强制卖掉抵债。卖完还差多少，才轮到你补。夫妻两人都签了字的债，算两个人一起还的共同债务。一方事后点了头的，也算。配偶签了字，就是两个人的家产一起搭进去（全国，2021 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-3', 'concept_archive_s12-3', 'recommendation', '个体工商户欠的债，要拿个人的钱和东西还，或者拿全家的钱和东西还。普通合伙企业的合伙人，对合伙企业的债承担无限连带责任。意思是欠多少还多少，还不完不算完。债主还可以只揪住其中一个人，要他还全部。有限合伙不一样，里面的有限合伙人只赔到自己答应出的那笔钱（以认缴出资为限）为止。有限责任公司的股东也是只赔到自己答应出的那笔钱（以认缴出资额为限）。但「有限」会在三种情况下失效。一是答应出的钱要在公司成立起 5 年内真交齐，公司还不上到期的债时，债主可以要求提前交。二是已经投进去又抽走的钱（抽逃出资）要还回来。三是拿公司当壳子躲债。只有一个股东的公司，又证明不了公司的钱和自己的钱是分开的，也算在这第三种里。这两种做法之下，公司的债你个人要跟着一起还（承担连带责任）（全国，2024 年 7 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-4', 'concept_archive_s12-4', 'recommendation', '登记在册的股东，就是法律上的股东。你要按公司章程定的期限，把答应出的钱一分不少地交进去（足额缴纳认缴出资）。没按期交的，除了补交还要赔公司的损失。公司开办时有股东没把钱真交进来的，开办时的其他股东在这个缺口里跟着一起还（承担连带责任）。公司还不上到期的债时，债主可以要求还没到期限的那笔钱提前交。真正做生意的人不在登记上，债却记在你名下（全国，2024 年 7 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-5', 'concept_archive_s12-5', 'recommendation', '法规要求品牌方（法规里叫特许人）至少有 2 个自己开、自己经营的直营店，而且开满 1 年以上。从第一次签加盟合同那天算起，15 日内它要去商务主管部门备案。不备案的，罚 1 万到 5 万元。过了期限还不备案的，罚 5 万到 10 万元，并且对外公告。签约之前，它必须把该交代的事写成书面材料交给你，一共 12 项。里面包括加盟费收哪几种、各多少钱，保证金什么情况下退，现有多少家加盟店、生意做得怎么样。还有近 2 年查过账的审计报告摘要，近 5 年打过的官司和仲裁。合同里还必须写明，加盟商在签约后的一段时间内可以自己一方说退就退（单方解除）。品牌方瞒着不说，或者给的是假信息，加盟商可以解除合同（全国，2007 年 5 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-6', 'concept_archive_s12-6', 'recommendation', '条例把要交的材料写死为五项。「（一）申请书」。「（二）申请人资格文件、自然人身份证明」。「（三）住所或者主要经营场所相关文件」。「（四）公司、非公司企业法人、农民专业合作社（联合社）章程或者合伙企业合伙协议」。「（五）法律、行政法规和国务院市场监督管理部门规定提交的其他材料」。翻成大白话：一份申请书；一份证明你是谁、或者你有资格办这件事的材料；一份能证明店面或者办公地归你用的材料；公司章程或者合伙协议；再加上法规另外点名要的。公司还要交法定代表人、董事、监事和高管的任职文件和身份证明。个体户不用交章程。名字「由申请人依法自主申报」，自己起、自己报。注册资本「实行认缴登记制」，先写上答应出多少，不用当场掏出来。经营范围从登记机关公布的分类里挑。材料齐全、格式也对的，「予以确认并当场登记」。当场办不完的，「3 个工作日内」办完，情况复杂的再多给 3 个工作日。「营业执照签发日期为市场主体的成立日期」：执照上印的那天，就是公司或者店铺成立的日子（全国，2022 年 3 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-7', 'concept_archive_s12-7', 'recommendation', '没拿到许可就开门做生意的，由法律法规指定的那个部门来查处。没有执照就经营、法律又没写明怎么罚的，勒令停下来，把挣到的钱（违法所得）收走，再罚 1 万元以下。还有更重的一档。法律法规规定的专营、专卖或者限制买卖的物品，没经许可就去经营。证券、期货、保险、资金支付结算这几类生意，没经批准就去做。这两种情形，情节严重的构成非法经营罪。判 5 年以下有期徒刑或者拘役（短期关押），同时按挣到的钱的 1 到 5 倍罚钱。情节特别严重的判 5 年以上（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-8', 'concept_archive_s12-8', 'recommendation', '食品安全法：做食品生意要先拿许可。自己生产食品、卖食品、做餐饮，都要依法拿到许可。「但是，销售食用农产品和仅销售预包装食品的，不需要取得许可。仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案」。食用农产品就是生鲜肉、蔬菜这类没加工过的。预包装食品就是别人做好、连包装一起卖的。「食品生产加工小作坊和食品摊贩等的具体管理办法由省、自治区、直辖市制定」，这两类由各省自己出规矩。没拿到许可就做食品生意的，挣到的钱、食品以及工具设备原料全部没收。这批货按售价算的总金额（货值金额）不足一万元的，另罚 5 万元以上 10 万元以下。货值金额一万元以上的，按货值的 10 倍以上 20 倍以下罚。生猪屠宰管理条例：猪只能在国家指定的屠宰厂宰，由官方集中检疫。「除农村地区个人自宰自食的不实行定点屠宰外，任何单位和个人未经定点不得从事生猪屠宰活动」。「从事生猪产品销售、肉食品生产加工的单位和个人以及餐饮服务经营者、集中用餐单位生产经营的生猪产品，必须是生猪定点屠宰厂（场）经检疫和肉品品质检验合格的生猪产品」。所以你卖的、用的猪肉都得来自指定屠宰厂，检疫和肉品品质检验这两道都得过。没在指定屠宰厂私自宰猪的，勒令关停，猪、屠宰的工具设备和挣到的钱一起没收，罚多少和上面没证做食品那一档一样。动物防疫法：卖的和运的动物产品，要随货带着检疫证明和检疫标志。没带的勒令改正，再按同类合格货的货值金额罚一倍以下。司法解释：小作坊和食品摊贩做的、卖的食品不符合食品安全标准的，买家要求按十倍赔（惩罚性赔偿，就是退钱之外再多赔的那笔），法院应当支持（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-9', 'concept_archive_s12-9', 'recommendation', '食品安全法：预包装食品（装进包装再卖的食品）包装上必须有标签。标签要标明名称、规格、净含量、生产日期，成分或者配料表，生产者的名称、地址、联系方式，保质期。还有产品标准代号、贮存条件、所用食品添加剂在国家标准里的通用名称、生产许可证编号。法律法规或者食品安全标准另外要求标的，也要标。散装食品是不装袋、按需称的那种。卖散装食品，容器和外包装上也要标：食品的名称，生产日期或者生产批号，保质期，生产经营者的名称、地址、联系方式等内容。做的、卖的预包装食品没标签，或者标签、说明书不符合本法规定的，挣到的钱和食品一起没收。这批货按售价算的总金额（货值金额）不足一万元的，另罚 5000 元以上 5 万元以下。货值金额一万元以上的，按货值的 5 倍以上 10 倍以下罚。情节严重的勒令停产停业，直到把许可证收回。标签、说明书只是有小毛病（瑕疵），既不影响食品安全也不会让消费者误解的，先勒令改正，拒不改才罚 2000 元以下。新版《预包装食品标签通则》编号 GB 7718-2025，2025 年 3 月 16 日发布，2027 年 3 月 16 日起实施，中间有两年过渡期。它要求在包装上设置独立区域，同时展示生产日期和保质期到期日。日期要用高对比度、容易看清的字体和颜色，并且按年-月-日的顺序排列（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-10', 'concept_archive_s12-10', 'recommendation', '食品安全法：「食品和食品添加剂的标签、说明书，不得含有虚假内容，不得涉及疾病预防、治疗功能。生产经营者对其提供的标签、说明书的内容负责」。「食品广告的内容应当真实合法，不得含有虚假内容，不得涉及疾病预防、治疗功能。食品生产经营者对食品广告内容的真实性、合法性负责」。意思是包装、说明书和广告里都不能说自己能防病治病，写了什么由卖家自己担责。在广告里对食品吹牛、骗消费者的，按广告法罚。广告法也有一条禁令。「除医疗、药品、医疗器械广告外，禁止其他任何广告涉及疾病治疗功能，并不得使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语」。除了医疗、药品、医疗器械这三类广告，其他广告一律不许说能治病，也不许用听着像药、像医疗器械的词。违反这一条的，勒令停掉广告。还要让出广告的那一方（广告主）在发过的范围里公开澄清、消除影响。再按广告费用的 1 倍以上 3 倍以下罚钱。广告费用算不出来，或者报得明显偏低的，罚 10 万元以上 20 万元以下。情节严重的，按广告费用的 3 倍以上 5 倍以下罚，或者罚 20 万元以上 100 万元以下，还可以把营业执照吊销、生意直接做不成（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-11', 'concept_archive_s12-11', 'recommendation', '刑法第一百四十三条管的是这一档。你做的、卖的食品不符合食品安全标准。只要「足以造成严重食物中毒事故或者其他严重食源性疾病的」，就够罪。判 3 年以下有期徒刑或者拘役（短期关押），同时罚钱。把人的健康搞出严重损害，或者有其他严重情节的，判 3 年以上 7 年以下并罚钱。后果特别严重的，判 7 年以上有期徒刑直到无期，罚钱或者把名下财产全部没收。第一百四十四条：在做的、卖的食品里掺进有毒有害的非食品原料，或者明知掺了还卖的，判 5 年以下有期徒刑并罚钱。把人的健康搞出严重损害，或者有其他严重情节的，判 5 年以上 10 年以下并罚钱。把人吃死了，或者有其他特别严重情节的，按第一百四十一条处罚（10 年以上、无期或者死刑）。最高人民法院和最高人民检察院出过一份解释（两高解释）。它列明了哪几种情形算「足以造成严重食物中毒事故或者其他严重食源性疾病」。一是「含有严重超出标准限量的致病性微生物、农药残留、兽药残留、生物毒素、重金属等污染物质」。二是「属于病死、死因不明或者检验检疫不合格的畜、禽、兽、水产动物肉类及其制品的」。三是「属于国家为防控疾病等特殊需要明令禁止生产、销售的」。四是「特殊医学用途配方食品、专供婴幼儿的主辅食品营养成分严重不符合食品安全标准的」。添加剂用超量、用错地方，到了会造成上述后果的程度，同样按第一百四十三条定罪。什么算「有毒、有害的非食品原料」，不由你说了算。一类是法律法规禁止往食品里加的物质。另一类是国务院有关部门公告的名单上的物质，比如禁用农药、禁止用在食用动物身上的药。还有一种情形也算第一百四十四条里的「其他严重情节」。做了、卖了 10 万元以上不满 20 万元。地点在中小学校园、托幼机构、养老机构及周边。卖的对象是未成年人、老年人。不在指定屠宰厂、自己私设猪的屠宰场干屠宰和销售，情节严重的按非法经营罪判。做到 10 万元以上，或者挣到 5 万元以上，就算「情节严重」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-12', 'concept_archive_s12-12', 'recommendation', '「纳税人在纳税期内没有应纳税款的，也应当按照规定办理纳税申报」：这一期一分税都不用交，表照样要报。不按期报的，「由税务机关责令限期改正，可以处二千元以下的罚款；情节严重的，可以处二千元以上一万元以下的罚款」。不报又少缴了税的，税要追回来，还要把按天加收的滞纳金一起补上，另罚少缴那笔税的「百分之五十以上五倍以下的罚款」。滞纳金按每天万分之五加。「连续三个月所有税种均未进行纳税申报的，税收征管系统自动将其认定为非正常户，并停止其发票领用簿和发票的使用」。三个月什么都不报，系统就自己把你列为非正常户，发票领不了也开不了。补报并且接受处罚之后，自动解除。用了人的单位「应当自成立之日起三十日内……向当地社会保险经办机构申请办理社会保险登记」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-13', 'concept_archive_s12-13', 'recommendation', '规模小、按简易办法交税的那一档叫小规模纳税人。法律写的是「销售额未达到起征点的，免征增值税」。这条线叫起征点。从 2026 年 1 月 1 日到 2027 年 12 月 31 日，起征点是按月算 10 万元，按季度算 30 万元，按次或者按天算 1000 元，卖不到这条线就不用交。同一段时间里，本来按 3% 交的减到按 1% 交，卖房租房和转让土地使用权除外。反过来说，开了没有真实买卖的增值税专用发票，或者其他能拿去抵税的发票，判 3 年以下有期徒刑或者拘役，并罚 2 万到 20 万元。给别人开、给自己开、让别人给自己开、介绍别人开，都算。涉及税额较大的判 3 到 10 年。数额巨大的判 10 年以上或者无期（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-14', 'concept_archive_s12-14', 'recommendation', '税务总局的提示原文：「税务部门不会通过微信小程序、电话、短信等方式索要银行卡密码、支付密码、账户余额及与银行卡收付款项相关的短信验证码」。「一些不法分子冒充税务干部以提供『帮办纳税申报』『税收优惠代办』『政策辅导』等为名接触纳税人」。要核实就打「12366 纳税缴费服务热线或主管税务机关固定电话」。真上门查账（稽查）的，「必须出示检查通知书和检查证」。「税款只能通过电子税务局或者在办税大厅缴纳，税务部门不会提供指定账号」。替人办税的中介机构也有一条。「以税务机关和税务人员的名义敲诈纳税人、扣缴义务人的」，按情节轻重罚款。打着税务局和税务干部的旗号，敲诈交税的人和代扣代缴税款的单位，就是这种情形。冒充国家机关工作人员招摇撞骗的，拘留 10 日以上 15 日以下，还可以再罚 1000 元以下。既够诈骗罪又够招摇撞骗罪的，「依照处罚较重的规定定罪处罚」（哪条罚得重按哪条判）（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-15', 'concept_archive_s12-15', 'recommendation', '定金要等钱真交到对方手上才算数（自实际交付时成立）。付定金的一方毁约，这笔钱要不回来。收定金的一方毁约，要原数退回，再赔上同样一份（双倍返还）。超过合同总金额（主合同标的额）20% 的那部分，不按定金算。约定的违约金比实际损失高得离谱或者低得离谱的，法院可以按一方的请求往下调或者往上调。违约金和定金都写进了合同的，真出了违约只能挑一样要，不能两样都拿（全国，2021 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-16', 'concept_archive_s12-16', 'recommendation', '人来上班满一个月、不满一年还没签书面合同的，每个月要按双倍发工资。从人上班第一天算起，30 日内要给他办社保登记。不办的先勒令改正。过了期限的，按该交的社保费罚 1 到 3 倍，经办这件事的人另罚 500 到 3000 元。社保没按时交、没足额交的，从欠的那天起按每天万分之五加钱（滞纳金）。过了期限还不交的，再按欠款罚 1 到 3 倍。单位要自己申报，按时把钱交足。只有天灾这类没法抗的法定事由，才能晚交或者少交。没有「员工自愿放弃」这一项（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-17', 'concept_archive_s12-17', 'recommendation', '劳动合同里必须写明的内容，就包括工资怎么给、社保怎么交。单位要按合同和国家规定，及时、足额发工资。拖着不发的，员工可以直接向法院申请支付令（法院开出的催款文书）。老板拿自己的钱借给员工，这就是一份借款合同。除了两个自然人之间另有约定的，都要写成书面的，写清借了多少、利息怎么算、什么时候还、怎么还。口头答应的奖金没有白纸黑字，真吵起来，拿不出证据的一方吃亏（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s12-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-18', 'concept_archive_s12-18', 'recommendation', '一项随机对照试验，跟踪了 116 家意大利初创企业大约一年。随机对照试验就是把人随机分成两组，只给一组做培训，再比两组的结果。结果是：受过培训、按「先提假设、再用市场反馈严格检验」来做决定的创业者，业绩更好，也更可能及时掉头换别的方案，早期放弃的比例并不更高。作者的解释是，这种做法减少了往看着有戏、其实做不成的项目（假阳性项目）上继续砸钱的概率（意大利，2020 年发表）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s12-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-19', 'concept_archive_s12-19', 'recommendation', '一件样品和一千件的差别，在于钱压在哪里。良率决定真实成本，良率就是做出来的一批里有几成合格能卖。供应商一次最少要你订多少（起订量），发货之后多久才收得到钱（账期），这两项决定你要先垫多少钱。库存决定钱什么时候回来。列入强制性产品认证目录的产品，必须先通过认证，并且在产品上标出认证标志，才能出厂和销售。没认证就擅自出厂销售的，按认证认可条例处罚。做餐饮和卖食品要办食品经营许可（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s12-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-20', 'concept_archive_s12-20', 'recommendation', '明知是假冒注册商标的商品还卖，挣到的钱（违法所得）够 3 万元，或者卖出去的金额够 5 万元，就到了要判刑的门槛。判 3 年以下，同时罚钱，或者只罚钱。达到这个标准十倍的，判 3 到 10 年并罚钱。货还压在仓库没卖出去也算：货值到了销售金额标准三倍以上的，同样构成犯罪。「明知」不用你自己承认。最高人民法院和最高人民检察院 2025 年的司法解释，列了五种可以直接认定你知情的情形，你拿得出证据证明确实不知道的除外。一是知道商品上的注册商标被涂改、调换或者覆盖。二是伪造、涂改商标注册人授权文件，或者知道该文件被伪造、涂改。三是因销售假冒商品受过刑事或者行政处罚，又销售同一种的。四是无正当理由，以明显低于市场价格进货或者销售的。五是被行政执法机关、司法机关发现后，转移、销毁侵权商品和会计凭证等证据，或者提供虚假证明的。公司犯这一条的，「对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员」按同一条处罚。就是公司罚钱，拍板的负责人和经手的人按同一条判。所以货是员工进的，挨罚挨判的还是拍板的那个人。反过来，商标法留了一条出路：卖的时候确实不知道这货侵犯了别人的注册商标，「能证明该商品是自己合法取得并说明提供者的，不承担赔偿责任」。能不能免赔，全看有没有票据和上家信息，没留就用不上这一条（全国，司法解释 2025 年 4 月 26 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-21', 'concept_archive_s12-21', 'recommendation', '著作权法把「未经著作权人许可，以改编、翻译、注释等方式使用作品」和直接复制并列为侵权行为。所以在原图上改颜色、换底色、加个自己的图标，仍然是未经许可使用别人的作品。要判刑的门槛在这里：为了赚钱，没经作品的版权人（著作权人）许可，就把美术作品印出来卖（复制发行）。够上罪的是三个数。挣到的钱（违法所得）够 3 万元。或者这门买卖做到 5 万元（非法经营数额）。或者印出来的件数加起来够 500 份（张）。到了其中任何一个数，就构成侵犯著作权罪。判 3 年以下，同时罚钱，或者只罚钱。达到十倍标准的判 3 到 10 年。只是卖别人印的侵权货，挣到 5 万元以上，或者卖出去 10 万元以上，按销售侵权复制品罪判 5 年以下。商标也一样：在同一种商品上使用与注册商标近似的商标，或者在类似商品上使用相同或者近似的商标，「容易导致混淆的」本身就在侵权范围内。「近似」是法条明写的侵权情形，稍微改一改仍然算侵权（全国，司法解释 2025 年 4 月 26 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-22', 'concept_archive_s12-22', 'recommendation', '以护士为例，法规写明的职务边界是这样的。发现病情危急，立即通知医师。紧急情况下为抢救垂危患者，可以先行实施必要的紧急救护。发现医嘱违法违规，或者违反诊疗技术规范的，要向医师提出，必要时向科室负责人报告。民法典另有规定：自愿出手做紧急救助，结果把被救的人弄伤了的，救人的一方不用赔钱（不承担民事责任）（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s12-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-23', 'concept_archive_s12-23', 'recommendation', '欠别人的和别人欠你的都没有，或者都已经还清。不欠工资、不欠社保、不欠税。全体投资人写了书面承诺。满足这几条，挂出来公示 20 日没人提异议，就能走简易注销。个体户不用公示，有关部门 10 日内没有异议就直接注销。公司还不上到期的债、欠的又比手上有的多（资不抵债）的，可以向法院申请重整、和解或者破产清算。已经解散又没清算、欠的比有的多的，该负责清算的人应当去申请破产清算。放着不管的后果是这样的：不按期公示年报，会被列进经营异常名录。连续 2 年不报年报、被列进经营异常名录还不改，按登记的地址又联系不上的，吊销营业执照。担任被吊销执照企业的法定代表人、对此负有个人责任的，从吊销那天算起 3 年内不得再当公司的法定代表人和董事、监事、高管。已经列进经营异常名录的，连简易注销都走不了（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s12-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s12-24', 'concept_archive_s12-24', 'recommendation', '广东省高级人民法院判过一个代运营骗局。蒋某、徐某等 55 人在广州、南宁、杭州开了多家公司。法院认定他们「明知根本不具备电商代运营的能力和技术条件」。他们还是以给淘宝网店代运营为名，诱骗 7711 名被害人购买、升级「服务套餐」。一共骗走 5299.4 万余元。两名首犯按诈骗罪分别判了 14 年和 13 年 6 个月。法院说，骗局设计得「严丝合缝」，「多名被害人一再受骗」。江苏省公安厅 2025 年把「无货源」跨境电商骗局拆成四步。第一步，在社交平台发「零基础」「无需囤货」的信息。第二步，以「运营指导」的身份加你，让你下载指定的平台。第三步，你开店后很快有第一单。对方让你先付商品成本价，说买家的货款冻结在平台里，收货后解冻。随后后台造出大量订单，让你不断加钱。第四步，想提现时就说「账户异常」「系统维护」，要你再交解冻金、手续费。案例里的张女士陆续垫进去 90 余万元，3 天后网站就打不开了。刷单那一头：一家代运营商给商户组织虚假团购冲排名。市场监管部门罚了它 10 万元，平台扣了它 5 万元保证金，法院支持平台扣钱。最高人民法院 2026 年把它列为典型案例，原话是「虚假交易、刷单炒信本为法律明令禁止的行为」。市场监管总局 2025 年也公布过一个案子。一家公司卖「一键搬家」「一键代发」软件，把别的平台的商品信息爬过来上架，被罚 53 万元。总局提示经营者「不得实施『搬家盗店』『无货源经营』等」违法行为。出路在民法典里：被对方用欺诈手段骗着签的合同，你可以请法院或者仲裁机构撤销。要在知道被骗那天起 1 年内提出。撤销以后，对方因此拿到的钱应当返还（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s12-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-1', 'concept_archive_s13-1', 'recommendation', '79 项研究、142,740 人合起来算（荟萃分析）：心跳停在医院外面（院外心脏骤停）的人，活着出院的总共只有 7.6%。在场的人做了心肺复苏的，活着出院的比例从 3.9% 升到 16.1%。有人在旁边看见发作的占 53%，真得到在场者按压的只有 32%。中国 BASIC-OHCA 登记了 38,227 例急救接诊病例。其中 30,282 例（79.2%）的心脏骤停发生在家中。这批人里，在场者按压率 20.3%，活着出院的 1.2%。顺序是先按压，再让第二个人打电话和拿 AED。机器开机后照着它的语音做', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-2', 'concept_archive_s13-2', 'recommendation', '卫生部《老年人跌倒干预技术指南》写明两句话。一句是「跌倒是我国 65 岁以上老年人伤害死亡的首位原因」。另一句是「发现老年人跌倒，不要急于扶起，要分情况进行处理」。意识不清的，立即拨打急救电话。有呕吐的，把头偏向一侧并清理口鼻。呼吸心跳停止的，立即做胸外按压。「如需搬动，应保证平稳，尽量平卧」。意识清楚的，先问他对跌倒过程有没有记忆，「如不能记起，可能为晕厥或脑血管意外」。有剧烈头痛，或者口角歪斜、言语不利、手脚无力的，「立即扶起老年人可能加重脑出血或脑缺血，使病情加重」。有骨折迹象，或者腰背疼痛、大小便失禁的，「如无相关专业知识，不要随便搬动」。以上几种都应立即拨打急救电话。老人自己想站起来的，可以协助他缓慢起立，「坐、卧休息并观察，确认无碍后方可离开」。说到「怕被讹」，法律上是这样规定的。《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十条有两句。头一句是「当事人对自己提出的诉讼请求所依据的事实……应当提供证据加以证明」。第二句是「在作出判决前，当事人未能提供证据或者证据不足以证明其事实主张的，由负有举证证明责任的当事人承担不利的后果」。民法典第一千一百九十八条的原文是：「宾馆、商场、银行、车站、机场、体育场馆、娱乐场所等经营场所、公共场所的经营者、管理者或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担侵权责任。」民法典第一百八十四条：「因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任」。最高人民法院公布过一个典型案例。药店经营者给心脏骤停的人做心肺复苏，压断了对方的肋骨。受助人住院 18 天，索赔 9 千余元。法院判决救助人不承担民事责任', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-3', 'concept_archive_s13-3', 'recommendation', '把 16 项静脉溶栓随机试验、6756 名患者的个体数据合起来算（荟萃分析）。静脉溶栓就是打药把堵住的血管通开。发病 3 小时内用阿替普酶溶栓，恢复到生活基本能自理（改良 Rankin 评分 0–1）的比值比 1.75，95% CI 1.35–2.27（可信范围）。这个结果出现的可能性约为不溶栓的 1.75 倍。拖到 3 到 4.5 小时是 1.26（1.05–1.51）。超过 4.5 小时是 1.15（0.95–1.40），统计上已经看不出差别', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-4', 'concept_archive_s13-4', 'recommendation', '美国肯塔基大学卒中中心 2014 年回顾了 736 例急性缺血性卒中（血管堵住引起的中风）的病历。其中 14.1% 的病人发病时完全没有脸歪、胳膊无力、说话不清这三个症状（FAST）。把「走路不稳、腿没劲、视觉症状」也算进筛查，漏掉的比例从 14.1% 降到 4.4%', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-5', 'concept_archive_s13-5', 'recommendation', '美国心脏协会 2021 年关于视网膜中央动脉阻塞（眼底那根主血管被堵住）的科学声明写明：「急性视网膜中央动脉阻塞是急症」。救治体系应当把它按急诊来识别、按轻重缓急排顺序。断血时间越长，还能救回来的视网膜越少。牛津 EXPRESS 研究看的是两类病人：小卒中，和症状自己好转的脑缺血（医学上叫短暂性脑缺血发作）。这批病人改为当天评估、当天开始治疗之后，90 天内再发卒中的比例从 10.3%（32/310）降到 2.1%（6/281）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-6', 'concept_archive_s13-6', 'recommendation', '武汉一家眼科医院比了两段时间的急性原发性闭角型青光眼病人。2020 年封控的 76 天里有 54 人 64 眼，2021 年同期有 46 人 51 眼，两组的人口特征相近。从出现症状到接受治疗，封控那组是 241.84±211.95 小时，对照组是 121.53±96.12 小时（P=0.001）。就诊时的眼压是 52.63±12.45 mmHg 对 45.16±9.79 mmHg（P=0.001）。失明的比例是 21.87% 对 7.84%。查出青光眼性视神经病变的是 20/64 眼（31.25%）对 7/51 眼（13.73%）（P=0.03）。韩国一家医院回顾了 50 只发作过一次、后来摘了晶状体的眼睛。一年之后 25 只（50%）留下了不同程度的视野缺损。从症状出现到把眼压降下来的这段时间越长，留下缺损的可能越大（P=0.005）。另有一项前瞻研究，让 43 名前房浅的人在暗室里俯卧 1 小时。两只眼的眼压都明显升高（P&lt;0.01）。平时主要用的那只眼中位数升了 3.60 mmHg，另一只升了 2.70 mmHg（P&lt;0.05）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-7', 'concept_archive_s13-7', 'recommendation', '以色列做过一项全国急性冠脉综合征调查。分析的对象是 ST 段抬高心肌梗死患者，这是一类心梗。算的是从进医院到用球囊把堵住的血管撑开（球囊扩张）这一段间隔。间隔 ≤55 分钟的，30 天内死亡 5/178（2.8%）。间隔 &gt;55 分钟的，30 天内死亡 15/155（9.7%）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-8', 'concept_archive_s13-8', 'recommendation', '国际急性主动脉夹层登记（IRAD）收了 12 家中心的 464 例。主动脉夹层就是胸背撕裂样剧痛那种病。病人最先说出来的症状里，最常见的是突然发作的剧烈锐痛。住院期间总死亡率 27.4%。A 型夹层没做手术、只吃药的，死亡率 58%', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-9', 'concept_archive_s13-9', 'recommendation', '加拿大 10 家急诊对 2131 例「一小时内达到最痛的剧烈头痛」做了前瞻队列研究，事先定好标准，再一路跟踪记录。其中 132 例（6.2%）是蛛网膜下腔出血（脑表面的血管破了）。渥太华 SAH 规则有六条：40 岁及以上、脖子痛或者发硬、有人看到晕过去。另外三条是活动中发作、一下子炸开式发作、医生查体时脖子前屈受限。符合任一条就要查。这条规则把出血的人全都挑了出来，敏感性 100%，95% CI 97.2%–100.0%（可信范围）。代价是没出血的人里只有 15.3% 被它排除掉（特异性 15.3%）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-10', 'concept_archive_s13-10', 'recommendation', '中华医学会神经外科学分会等发布过《慢性硬膜下血肿药物治疗中国专家共识》。慢性硬膜下血肿，是脑膜之间慢慢积起来的一摊血。专业说法是蛛网膜与硬脑膜之间积血形成的慢性占位。它「通常在颅脑外伤后第三周形成」，多见于老年人。开刀之后复发率可达 33%，病死率可达 32%。90 岁以上的病人，总体上恢复得好的只有 24%。系统综述：全球每 10 万人每年新发 3.39 到 39.1 例，随年龄升高，80 岁以上可达三倍。最常见的起因是外伤和跌倒，其次是长期酗酒、用防止血液凝固的药（抗凝）和暴力伤害。老年医学综述：临床表现「典型包括意识模糊、认知下降、步态障碍或嗜睡，可能与其他老年综合征相似」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-11', 'concept_archive_s13-11', 'recommendation', '国际肺栓塞协作登记（ICOPER）收了 7 个国家 52 家医院的 2454 例确诊急性肺栓塞病人。肺栓塞就是血块堵住肺动脉。这批人 3 个月内不分原因的死亡率是 17.4%（426/2454）。世界卫生组织 WRIGHT 项目：连续 4 小时以上的旅行，让静脉里长血块、血块跑到肺里（静脉血栓栓塞）的风险「大约翻倍」。但摊到一个人头上的概率仍然很低，久坐不动超过 4 小时「约为六千分之一」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-12', 'concept_archive_s13-12', 'recommendation', '美国得州 11 家一级创伤中心 6 年里收了 1,026 例四肢血管伤，其中 181 例（17.6%）在到医院之前上了止血带。不做任何调整直接算，上了止血带的死亡 3.9%，没上的 5.2%。把其他条件拉平之后（多因素校正），上止血带仍然单独和活下来相关。校正 OR 5.86，可信范围是 95% CI 1.41 到 24.47。巴格达战地医院的 232 名伤员：休克出现前上止血带的存活 90%，休克后才上的只有 10%。需要止血带而没上的 5 人全部死亡，上了的存活 87%。顺序是：直接压迫，衣物、毛巾都行 → 压不住的四肢出血上止血带 → 打 120 → 不松开', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-13', 'concept_archive_s13-13', 'recommendation', '国家疾控局、国家卫健委 2023 年版规范原文：「狂犬病病死率几乎达 100%」。处置是「用肥皂水（或者其他弱碱性清洁剂）和一定压力的流动清水交替彻底冲洗所有咬伤和抓伤处约 15 分钟」。裸露皮肤被轻咬、无出血抓伤，是 II 级暴露，要打疫苗。贯穿性咬伤、破损皮肤被舔，是 III 级暴露，「应处置伤口并注射狂犬病被动免疫制剂和接种狂犬病疫苗」。WHO：全球每年约 5.9 万人死于狂犬病，99% 由狗传播', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-14', 'concept_archive_s13-14', 'recommendation', '澳大利亚跟踪了 2495 名烧烫伤儿童。受伤后 3 小时内用凉流动水冲 20 分钟的孩子，后来需要植皮的比值比是 0.6，95% CI 0.4–0.8（可信范围），大约只有没这么冲的六成。7 项研究合起来算的结果同样发现，「伤后三小时内 20 分钟凉流动水显著降低了需要植皮和手术处理创面的可能」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-15', 'concept_archive_s13-15', 'recommendation', '肾上腺素是二级及以上过敏性休克首选的药（一线药），指南把它列为强推荐。抗过敏药和激素起效慢，顶不了它的位置', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-16', 'concept_archive_s13-16', 'recommendation', '避免掰嘴、塞硬物造成的牙齿和下颌损伤。避免强行按住造成的骨折。超过 5 分钟不停，是必须叫救护车的红线', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-17', 'concept_archive_s13-17', 'recommendation', '血糖低于 3.0 mmol/L，属于临床上有意义的低血糖。出现意识或者行动改变、需要别人帮忙处理的，是重度低血糖，可以致命', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-18', 'concept_archive_s13-18', 'recommendation', '避免施救的人一起被电住，把一个伤者变成两个。脱离电源后没有呼吸的，按本节第 1 条（用力按压胸口）做心肺复苏。美国疾控中心的急救步骤是：先看，别碰，人可能还连着电。能断电先断电，断不了就用纸板、塑料或木头这类不导电的东西把电源拨开。脱离电源后，呼吸或脉搏停了的，立刻做心肺复苏。一篇综述说，触电后心跳骤停、被救回来的人，预后往往不错', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-19', 'concept_archive_s13-19', 'recommendation', '中国疾控的死因监测系统 2018 年报告了 11523 例一氧化碳中毒死亡。最多的是 1 月（2845 例）、2 月（2321 例）和 12 月（2010 例）。冬天这三个月，死在家里的占 66% 到 73%。这是系统里报上来的数，不是按全国人口推算的。美国每年 400 多人死于与火灾无关的意外一氧化碳中毒。10 万人以上进急诊，1.4 万人以上住院', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-20', 'concept_archive_s13-20', 'recommendation', '中国疾控中心职业卫生与中毒控制所给的处置口径分四种。吃进嘴里（消化道摄入）的，立即饮用适量的牛奶或蛋清，「切记，不要催吐」。尽快就医，同时携带包装或说明书，「以便于医生快速判断成分并制定救治方案」。吸进气里（呼吸道吸入）：立即转移至通风良好的区域，解开衣领保持呼吸通畅；出现剧烈咳嗽、气促或呼吸困难的，立即就医。皮肤接触：立即用大量清水冲洗接触部位至少 15 分钟，注意别让冲洗液溅到眼睛或者其他完好皮肤。眼睛接触的，立即用大量清水或生理盐水冲洗眼睛至少 15 分钟。冲洗时撑开眼睑，让水流充分接触眼球及眼睑内侧，「切勿揉搓眼睛」。冲洗后立即前往眼科。高危产品按酸碱度（pH）认。pH&lt;3 的是洁厕剂、除垢剂、地板清洁剂、不锈钢光亮剂。部分强力管道疏通剂还含稀硫酸。pH&gt;11 的是管道疏通剂、厨房强力除污剂、洗碗粉、爆炸盐、去污粉。还有一个当场出事的组合：消毒液和含盐酸的洁厕剂一起用会产生氯气，刺激呼吸道、引起剧烈咳嗽和气促，甚至危及生命', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-21', 'concept_archive_s13-21', 'recommendation', '现场三步。第一步，立即脱去受污染的衣物鞋袜：毒物会继续经皮肤吸收，衣服兜着的部分伤得最重。第二步，用大量流动清水冲洗。中国疾控中心职业卫生与中毒控制所给的下限，是皮肤和眼睛各「至少 15 分钟」。湖南省应急管理厅给的口径是创面冲洗 20 至 30 分钟，「强烈的化学品要更长」。两个口径里取长的那个。第三步，眼睛要「撑开眼睑，确保水流充分接触眼球及眼睑内侧」，「切勿揉搓眼睛」，冲完立即去眼科。用常温或微温水，禁用热水。新鲜创面上不要涂油膏、红药水或者任何东西，也不要用脏布包裹，涂了会影响医生判断深度。法律上，「化学性皮肤灼伤」和「化学性眼部灼伤」都在法定职业病目录里，工作中发生的按职业病和工伤走。发生急性职业病危害事故的，用人单位「应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担」（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-22', 'concept_archive_s13-22', 'recommendation', '美国国家气象局：热射病是「严重的医疗急症」。它的表现是体温高于 103°F（39.4°C）、意识混乱、说话含糊、皮肤发烫发红。处理是立刻叫急救、移到凉处、用凉水和湿布降温、「不要给液体」。热衰竭的表现是大汗、乏力、皮肤湿冷、脉快而弱，处理是移到凉处、松开衣服、小口喝水；呕吐、恶化或者超过 1 小时不缓解就就医。云南省疾控局提示：立即转移到阴凉通风处，用冷湿毛巾降温，意识清醒的补含盐饮料，症状严重的立即拨打急救电话；重症热射病「病死率极高」。中国疾控中心提示：先降温，后转运，在病人失去意识后的「黄金半小时」内降温。有条件的，无基础疾病的青壮年可以用冷水浸泡快速降温，老人和有基础病的往皮肤上喷水、靠蒸发降温。荒野医学会 2024 年更新的热病指南说，冷水浸泡是治重症中暑最重要的办法，降温最快。没有冰水就用手边最凉的水，泡不了就喷水加扇风，速度大约是浸泡的一半', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-23', 'concept_archive_s13-23', 'recommendation', '中国疾控中心发布过《公众高温中暑预防与紧急处理指南（2014 版）》。里面写着「至少每小时喝 2~4 杯凉水（500~1000ml），水温不宜过高，饮水应少量多次」。还写着「不要饮用含酒精或大量糖分的饮料。这些饮料会导致失去更多的体液。同时，还应避免饮用过凉的冰冻饮料」。对热射病则明确写「不要给病人喝水」。美国 NIOSH：热衰竭要「鼓励小口频繁地喝凉水」；热痉挛每 15 到 20 分钟补一次含糖和电解质的运动饮料，「不要用盐片」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-24', 'concept_archive_s13-24', 'recommendation', '美国 FEMA 逃生原文：「趴到地上，从烟下面爬向出口」。开门前先摸门把和门板，「如果是热的，或者门缝有烟，别开这扇门，用第二条路」。开门要慢，一有浓烟立刻关上。衣服着火就「停下、倒地、打滚」，用手护脸。出不去就关门，用布或者胶带堵住门缝和通风口，打电话报位置。应急管理部的火灾自救提示和这一致：逃生不要坐电梯，火不大时尽量往楼下跑，用湿毛巾或口罩蒙住口鼻，趴着或弯腰撤离', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-24"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-25', 'concept_archive_s13-25', 'recommendation', 'WHO：全球每年约 30 万人溺亡，92% 在中低收入国家。溺水是 1 到 4 岁儿童的第四位死因，5 到 14 岁的第三位死因。WHO 推荐的干预是「安全救援和复苏培训」，比如先学会不下水的救法。顺序是：大喊叫人 → 打电话 → 递长杆、绳子，抛救生圈、空桶、矿泉水瓶 → 人上岸后无呼吸立刻按压', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-25"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-26', 'concept_archive_s13-26', 'recommendation', '美国国立医学图书馆原文：先问「你噎住了吗，能说话吗」。「能用力咳嗽、能说话的不要动手」，咳嗽本身多能把异物咳出。说不出话就「反复做 5 次拍背接 5 次腹部冲击，直到异物出来或人失去意识」。「失去意识就开始心肺复苏」，同时叫人打急救电话。孕妇、肥胖者改做胸部冲击', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-26"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-27', 'concept_archive_s13-27', 'recommendation', '美国国家公园管理局的莫哈韦沙漠页面有三句原文。一句是「每人每天至少 1 加仑（约 3.8 升）水，徒步和骑行者每人每天 2 加仑」。一句是「告诉别人你的路线、目的地、返回日期、车型和车牌」。还有一句是「手机信号时有时无」。死亡谷原文：「热的时候不要在谷底和低海拔徒步」，荒野区域「几乎没有手机信号」，推荐带卫星电话。莫哈韦的沙漠驾驶页面原文：「出了紧急情况，待在车旁是你能做的最重要的事」。页面还说，这种事不常见，但确实有人在走回公路的路上，死于暴露在酷热或寒冷里。优先级分五步。第一步是报平安和坐标，有信号时先发位置再打电话。第二步是遮阳保暖，车是最大的遮蔽物。第三步是水，白天不动、夜里凉了再动。第四步是不乱走。第五步是信号。重庆市应急管理局的提示是：摆成三角形的三堆火是国际通行的求救信号。离得近就喊「三声短、三声长、再三声短」，隔 1 分钟重复。有太阳时用镜子、罐头盖这类亮东西反光。文化和旅游部提醒自驾游客谨慎前往无人区，尽量多车同行，必要时租卫星电话', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-27"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-28', 'concept_archive_s13-28', 'recommendation', '美国国家气象局原文：体温 95°F（35°C）以下就是失温，「觉得冷、迟钝、想不清楚，立刻看医生」。处理是「立即就医，把人移到有暖气的室内，先从身体中心开始复温」，给热饮。「酒精会减少寒战」，所以不喝。「失去意识做心肺复苏」。冻伤用温水或者体温回暖，「不要用热水或壁炉一类辐射热」。荒野医学会 2019 年失温指南是这个领域的执业指南', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-28"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-29', 'concept_archive_s13-29', 'recommendation', 'WHO 原文有三句。一句是「立即完全固定被咬的身体部位，并迅速送到最近的医疗机构就医」。一句是「避免使用止血带，并避免切割伤口」。还有一句是「用针对当地蛇种的适当抗蛇毒血清进行治疗」。「高质量抗蛇毒血清是防止或逆转蛇咬伤的大部分毒性作用的最有效治疗方法」。全球每年约 8.1 万到 13.8 万人死于蛇咬伤，截肢和永久残疾的人数约为死亡数的 3 倍。中国 2024 年的蛇伤救治指南估计，国内每年有 25 万到 28 万例毒蛇咬伤，被咬的多是 50 岁以上的人。长江流域和南方 11 个省的医院 2017 到 2021 年收治了 40817 名蛇伤病人，住院期间死亡 23 人（0.06%）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-29"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-30', 'concept_archive_s13-30', 'recommendation', '中国地震局科普片《地震来了，是躲还是跑？》的口诀是「震时就近躲避，震后迅速撤离」，并明确限定「这里指的是在符合抗震设防要求的建筑内」。理由是这类建筑「整体垮塌的可能性较小」。原文说「坠落的建筑构件及装饰物品」「才是对生命安全最大的威胁」。而「震时无保护措施的盲目乱跑」「反而容易被坠落的天花板、吊灯（扇）等物品砸伤」。躲的做法是「用手或者其他软物保护好头颈部」「并牢牢地抓住桌腿」；没有桌子就「迅速贴紧承重墙蹲伏」「避开外墙、窗户、阳台」。「如果在户外」则「应该第一时间疏散到空旷的地方避震」。反过来看，1988 年亚美尼亚地震是苏联式预制板楼成片垮塌。那次的病例对照研究写着，「第一下震动之后离开建筑是保护性行为」。待在室内的人受伤的可能性，是跑出去的 4.40 倍（比值比 4.40），95% CI 2.24–8.71（可信范围）。在建筑里受伤的可能性，是在室外的 12.20 倍（3.62–63.79）。在 5 层以上的楼里，是在更矮的楼里的 3.65 倍（2.12–6.33）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-30"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-31', 'concept_archive_s13-31', 'recommendation', '美国国家公园管理局关于熊的原文有六句。一句是「不要跑，熊上下坡都能跑得像赛马一样快」。一句是「保持冷静，大多数熊不想攻击你，只想被放着不管」。一句是「用低沉的声音持续跟熊说话」。一句是「熊不动时，侧着身慢慢退开，这样既能盯着熊又不会绊倒」。一句是「让自己显得尽量大」。还有一句是「不要爬树，灰熊和黑熊都会爬树」。被棕熊攻击时「装死，趴着双手扣在颈后、双腿分开」。被黑熊攻击时「不要装死，逃向车或房子，逃不了就用手边任何东西反击」。被狗咬伤按第 13 条处理', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-31"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-32', 'concept_archive_s13-32', 'recommendation', '雷暴范围内的户外没有安全的地方。最后一声雷响过 30 分钟，才算安全', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-32"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-33', 'concept_archive_s13-33', 'recommendation', '睡在 2450 米以上就有高原病风险。高原脑水肿和肺水肿（脑子和肺里积水），不及时往低处撤会死', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s13-33"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-34', 'concept_archive_s13-34', 'recommendation', '涂油、用火烧、扭着拽，会刺激蜱虫，把带病原体的体液挤进皮肤。这么做也容易把它扎在肉里的那部分嘴（口器）留在里面。蜱虫在中国传的发热伴血小板减少综合征，2024 年全国报告 6602 例、死亡 306 例，都是发现这种病以来最多的一年。2010 到 2024 年平均病死率 4.79%，年纪越大越高，85 岁以上是 9.15%', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-34"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-35', 'concept_archive_s13-35', 'recommendation', '所有能靠喝水致病的微生物，在水烧开的温度下几秒就被杀死（灭活）。「高海拔水烧不到位」是常见误解', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-35"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-36', 'concept_archive_s13-36', 'recommendation', '命比钱贵，对方为几百元冒的是重罪。刑法第二百六十三条规定，以暴力、胁迫或者其他方法抢劫公私财物的，处三年以上十年以下有期徒刑并处罚金。持枪、入户、致人重伤死亡等情形，判十年以上直至死刑。刑法第二十条的正当防卫只保护「制止正在进行的不法侵害」。对方拿了钱转身走，你追上去打就不再是防卫。脱身后立刻记下体貌、口音、车牌、逃跑方向，打 110', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-36"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-37', 'concept_archive_s13-37', 'recommendation', '刑法第二百九十二条：「聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制」。多次聚众斗殴的，人数多规模大社会影响恶劣的，在公共场所或者交通要道造成社会秩序严重混乱的，持械的，「处三年以上十年以下有期徒刑」。「聚众斗殴，致人重伤、死亡的」，按故意伤害罪、故意杀人罪定罪处罚。治安管理处罚法也有罚则。殴打他人，拘留 5 到 10 日并罚 500 到 1000 元。结伙斗殴按寻衅滋事处理，最高拘留 15 日并罚 2000 元。《关于依法适用正当防卫制度的指导意见》第 5 条：不法侵害「既包括针对本人的不法侵害，也包括危害国家、公共利益或者针对他人的不法侵害」。该意见第 9 条：一方先动手且手段明显过激，或者一方先动手、在对方努力避免冲突的情况下仍继续侵害的，还击一方一般应当认定为防卫行为', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-37"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-38', 'concept_archive_s13-38', 'recommendation', '北京市人民政府防艾科普栏目的口径是：接触之后的预防用药叫暴露后预防（英文缩写 PEP），应「尽可能在 2 小时内进行预防性用药，最好在 24 小时内、不超过 72 小时」。还要「连续服用 28 天」。超过 72 小时就不再建议启动，这是一条硬时限', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-38"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-39', 'concept_archive_s13-39', 'recommendation', '民法典第一百八十三条：「因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿」。国办发〔2012〕39 号讲了见义勇为负伤人员怎么办。医疗机构要建立绿色通道，「坚持『先救治、后收费』的原则」。医疗费这一块的原文是「因紧急救治发生的医疗费用，有加害人或责任人的，由加害人或责任人承担；无加害人或责任人以及加害人或责任人逃逸或者无力承担的，按规定通过基本医疗保障制度解决」。死亡的，「符合烈士评定条件的，依法评定为烈士」；「属于视同工伤情形的，享受一次性工亡补助金以及相当于本人 40 个月工资的遗属特别补助金」。伤残的，「符合享受工伤保险待遇条件的，依据《工伤保险条例》落实相应待遇；不符合的，由民政部门评定伤残等级并落实相应待遇」。就业上「优先纳入就业援助，予以重点支持」，公益性岗位「优先安排符合条件的见义勇为人员」。住房上「优先纳入住房保障体系，优先配租、配售保障性住房或发放住房租赁补贴」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-39"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-40', 'concept_archive_s13-40', 'recommendation', '国际红十字与红新月会联合会 2025 年国际急救指南：「急救的人应当压住扎进身体的异物（比如刀）周围，把异物稳住，不要把它拔出来」。「不要从腹部或胸部的伤口里拔出任何扎入的异物，拔出来可能造成大出血，也会让医生更难判断伤得有多重」。「扎在身体里的异物应当稳住；异物随脉搏跳动的，就让它跳，松松地稳住即可」。「急救的人不应把露出来的内脏塞回体内」。没有在往外涌血的开放性胸壁伤口「可以敞着、不加敷料，因为把伤口封死可能让空气积在胸腔里，使肺部分或完全塌陷（气胸）」。所有穿透性胸腹部伤口都应立即呼叫急救', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-40"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-41', 'concept_archive_s13-41', 'recommendation', '国际红十字与红新月会联合会发布了 2025 年国际急救指南。里面写着「手脚上的任何一处伤，都应当先按可能的骨折来处理」。还写着「确诊骨折唯一准确的办法是拍 X 光。拿不准就当骨折办」。固定的目的是「尽量减少活动和疼痛」。冷敷「一次最多连续 20 分钟，这样可以减轻疼痛；冷得比这更久可能损伤皮肤」。「伤到股骨这类长骨时，光是骨头本身出的血就可能致命」。疼痛或者肿胀明显、有休克表现、股骨（大腿骨）骨折或者肢体位置明显不对时，应呼叫急救。折弯成角的骨折，要两个条件同时成立，才考虑在现场掰回原位（复位）。一是「地处偏远（或者条件有限），而且成角处下方的肢体发凉、发白，或者急救的人没法固定好以便搬动」。二是施救者受过训练。开放性骨折（断骨戳破皮肤）的优先事项是止血和防感染。但第一次 X 光没看出来，不等于没骨折。英国国家卫生与临床优化研究所（NICE）的髋部骨折指南写：X 光正常但仍怀疑髋部骨折的，「做磁共振（核磁）」。24 小时内做不了，就考虑做 CT。它的骨折指南写：怀疑手腕舟骨骨折的，「经过仔细的体格检查后，考虑首先做磁共振」。舟骨是手腕里的一块小骨头。考克兰（Cochrane）的一篇文献汇总说：「最初的 X 光片不能排除骨折」。它收的研究里，X 光正常、医生仍怀疑舟骨骨折的人，真有骨折的比例中位数是 20%。美国放射学会有一份膝关节外伤的检查标准。它写：X 光没看到骨折，但仍怀疑有隐藏骨折或关节内部损伤的，下一步「通常适合」做磁共振。它还写，磁共振查隐藏骨折、半月板和韧带损伤都很准', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-41"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-42', 'concept_archive_s13-42', 'recommendation', '北京市人民检察院的检察官说：「无论是未成年人还是成年人，遇到侵害，都应当第一时间拨打110报警」。及时报警、就医，「便于侦查机关及时勘查现场、提取物证痕迹、固定证据」。贵州省民政厅转载的人民日报防性侵手册写：「一旦不幸遭遇性侵害，最重要的事情就是留存证据」。要保留「体液、毛发、皮屑、通信记录等证据」，「被侵害后，不要擅自洗澡、洗衣物、收拾房间、扔东西」。熟人作案的，保留通话、通信记录。对方事后威胁或者收买，也要留下证据。北京市西城区人民检察院写的是：「在接受身体检查之前尽量不要洗澡」。世界卫生组织说，紧急避孕可以用在「女性在未采取有效的避孕保护措施时遭受性侵犯」的时候。建议在 5 天内用，越早越有效。含左炔诺孕酮（一种孕激素）的紧急避孕药，用过的女性怀孕率是 1.2% 到 2.1%。国内药店卖的左炔诺孕酮片是非处方药。武汉市卫健委的说法是：在无防护性生活后「72小时以内，服药越早，预防妊娠效果越好」。艾滋病阻断药要尽可能 2 小时内吃上，最晚不超过 72 小时（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-42"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-43', 'concept_archive_s13-43', 'recommendation', '美国心脏协会和美国儿科学会出了 2025 年的儿童基础生命支持指南。指南写：窒息（比如异物堵住气道）「是婴儿和儿童的主要死因之一」。婴儿最常呛进去的是液体。还在咳、还能出声的是轻度，让孩子自己咳，同时盯着有没有变重。咳得很弱或者咳不出、哭不出、脸色发紫的是重度。重度要先叫急救，再「反复做 5 次拍背、接 5 次胸部冲击，直到异物出来或者婴儿失去反应」。指南不建议给婴儿做腹部冲击，因为可能伤到肚子里的脏器。胸部冲击现在推荐用一只手的掌根，因为它比原来的两指法按得更深。婴儿失去反应就开始心肺复苏，先按压，不摸脉搏。吹气前看得见的异物要取出来。指南明写「不要用手指盲目去掏」。国际红十字与红新月会联合会的 2025 年国际急救指南也是这一套。先在两肩胛骨之间用力拍最多 5 下，不行就把孩子翻过来按胸口最多 5 下，再不行马上叫急救。它按胸口用的是双手环抱、两个拇指按。福建省红十字应急救护培训中心说，1 岁以下婴儿要做「5 次背部拍击 + 5 次胸部冲击」。拍背时让婴儿俯卧在前臂上，头低于躯干', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-43"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s13-44', 'concept_archive_s13-44', 'recommendation', '美国心脏协会和美国儿科学会出了 2025 年的儿童基础生命支持指南。指南写：婴儿和儿童心跳骤停，主要原因仍是呼吸出了问题。在医院外心跳骤停的婴儿，活着出院的只有 6.6%。普通人遇到没反应、没正常呼吸、没有生命迹象的婴儿或儿童，「应当立即开始心肺复苏」，不要去摸脉搏。按压深度至少是胸廓前后径的三分之一，婴儿「约 1.5 英寸（4 厘米）」。频率每分钟 100 到 120 次。一个人做时，按 30 下吹 2 口气。两个人做时，按 15 下吹 2 口气。婴儿用一只手的掌根按，或者双手环抱、两个拇指按。环抱不住就用掌根。两根手指按的做法已经取消，因为按不够深。指南还写，院外心脏骤停的婴儿和儿童，按压之外再加吹气能提高存活。美国一个登记库统计了 3900 名 18 岁以下院外心脏骤停的孩子，59.4% 是婴儿。在场的人做了心肺复苏的，调整后活着出院的比例是 13.2%，没做的是 9.5%。调整后 OR 1.57（活下来的几率高约 57%），95% CI 1.25–1.96（可信范围）。在婴儿里，带吹气的心肺复苏和更高的存活有关，活下来的孩子脑子也恢复得更好。只按不吹的，结果和没人做差不多。国际红十字与红新月会联合会的 2025 年国际急救指南写：看婴儿有没有反应，要把孩子抱起来或者拍他的脚底。只有你一个人，就开免提自己打急救电话。手边没有能边按边打的电话，就先做 1 分钟心肺复苏再去打。首都儿科研究所有一篇科普，北京市卫健委转载了。它写：「如果只有1个人在场，先进行2分钟的心肺复苏后呼叫120救护车」。按压幅度「婴儿4cm」。1 岁以内吹气要「口对口鼻」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s13-44"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-1', 'concept_archive_s14-1', 'recommendation', '谷歌统计了 35 万次真实的盗号尝试（也叫账号劫持）。一类是靠设备来验证，比如手机上弹窗让你点确认，或者插一把安全密钥。这一类拦下了「超过 94% 源于钓鱼的劫持尝试和 100% 的自动化劫持尝试」。钓鱼是指骗你在假网站上输密码，自动化是指机器拿泄露的密码批量去试。另一类是靠回答问题来验证，比如问你上次在哪登录、备用邮箱是什么。这一类「只拦下了低至 10% 的钓鱼劫持和 73% 的自动化劫持」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s14-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-2', 'concept_archive_s14-2', 'recommendation', '把别处泄露的账号和密码挨个拿来试着登，这叫撞库，是最省事的攻击方式，你的邮箱也会被这样试。邮箱一旦被人登进去，所有用它找回密码的账号一起丢。美国网络安全和基础设施安全局的建议是：每个账号用一个不同的强密码，至少 16 位，交给密码管理器存', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s14-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-3', 'concept_archive_s14-3', 'recommendation', '手机丢了以后，捡到的人最快的一条路是把 SIM 卡插到别的手机上，收你的短信验证码。有了验证码，他就能一个个重置你的账号。SIM 卡设了 PIN 码，换到别的手机上开机就要先输密码，捡到的人就没法拿它收验证码', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s14-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-4', 'concept_archive_s14-4', 'recommendation', '顺序比速度更重要。第一步，挂失 SIM 卡，别人就收不到你的验证码了。第二步，远程锁定手机，并清空手机里的内容。第三步，从电脑上改邮箱和支付密码。第四步，报警，拿回执。最后按需要冻结银行卡。美国联邦通信委员会的提示也是：就算觉得只是弄丢了，也要远程锁住。被偷了马上报警，报上型号和 IMEI 串号（手机的身份编号），并马上告诉运营商', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s14-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-5', 'concept_archive_s14-5', 'recommendation', '最高法的规定把「谁来拿证据」分开了。你说这是伪卡盗刷或者网络盗刷，要先拿证据。伪卡盗刷就是卡被人复制了一张去刷。这些都能用来证明：已经生效的法律文书、银行卡交易时真卡在哪里、交易发生在哪里。还有账户交易明细、交易通知、报警记录、挂失记录等等。反过来，发卡银行、非银行支付机构（第三方支付）说这笔是持卡人本人刷的、或者是经他授权刷的，要由它们拿出证据。你告知银行之后，银行没及时核实，或者没及时提供、保存交易单据和监控录像，证据因此拿不到的，拿不出证据的后果由银行承担。认定成立以后：借记卡（储蓄卡）持卡人，可以要求发卡银行把被盗刷的存款本息付给你，并赔偿损失。信用卡持卡人，可以要求退回被扣走的透支款本息和违约金，并赔偿损失；银行反过来要你还这笔透支款的，法院不予支持。你还可以要求发卡银行及时撤销相应的不良征信记录（全国，2021 年 5 月 25 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s14-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-6', 'concept_archive_s14-6', 'recommendation', '被盗号往往不是当场就动手，对方会先潜伏一阵。账号里的登录设备列表，记着现在还能用这个账号的手机和电脑。已授权应用列表，记着你准许它用这个账号登录的别家软件。列表里的陌生设备，和早就不用的第三方软件，是最容易发现的痕迹', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s14-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-7', 'concept_archive_s14-7', 'recommendation', '法律明写了两条。一是不得以个人不同意、或者撤回同意为由，拒绝提供产品或者服务；处理这些信息属于提供服务所必需的除外。二是收集应当限于实现处理目的的最小范围，只能收用得着的那些', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s14-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-8', 'concept_archive_s14-8', 'recommendation', '有几种情形企业应当主动删除：服务停了、约定的保存期限到了、你撤回同意、当初收集的目的已经达到等等。它没删，你可以要求它删。它拒绝你行使这些权利的，必须说明理由。你可以直接向法院起诉', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s14-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-9', 'concept_archive_s14-9', 'recommendation', '人脸识别技术应用安全管理办法写明：「实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式。个人不同意通过人脸信息进行身份验证的，应当提供其他合理、便捷的方式。」办法还写明：「任何组织和个人不得以办理业务、提升服务质量等为由，误导、欺诈、胁迫个人接受人脸识别技术验证个人身份。」要是按你同意来处理人脸信息，得取得「在充分知情的前提下自愿、明确作出的单独同意」：单独就这一件事问你，你单独点头才算。你有权撤回同意，处理者要提供便捷的撤回方式。处理不满十四周岁未成年人的人脸信息，应当取得父母或者其他监护人的同意。公共场所安装人脸识别设备，「应当为维护公共安全所必需」，并设置显著提示标识。宾馆客房、公共浴室、公共更衣室、公共卫生间等公共场所中的私密空间内部，任何组织和个人不得安装。人脸信息应当存储于人脸识别设备内，不得通过互联网对外传输。两种情况例外：法律、行政法规另有规定，或者取得了单独同意（全国，2025 年 6 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s14-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s14-10', 'concept_archive_s14-10', 'recommendation', '国家安全部 2026 年 6 月发布风险提示。部分中转站会把用户提交的数据留在服务器上，有的私自截留，倒卖给别的大模型厂商做训练。有的暗藏后门，向用户设备植入恶意代码，窃取账号密钥和云端凭证，甚至装上远程控制程序。提示建议用官方直连、正规授权的平台，不用来源不明、没有运营资质、没有安全保障的平台。用的时候先给个人隐私和项目资料脱敏，管好密钥、定期更换。遇到异常扣费、无故封号、数据异常，立即停用、改密钥、查杀病毒、留存证据。加州大学圣塔芭芭拉分校等单位的研究者 2026 年做了一项测量。他们从淘宝、闲鱼和海外网店买了 28 个付费中转站，又从公开社区收集了 400 个免费中转站。结果 1 个付费的和 8 个免费的，会往返回的工具调用里注入恶意代码。工具调用就是 AI 让你的电脑去执行的命令，比如安装软件包。还有 2 个会挑时机下手，论文举的例子是只对全自动执行的会话下手。17 个动用过研究者故意放进去的亚马逊云服务密钥。1 个转走了研究者以太坊钱包里的钱，钱包里只放了很少的钱，损失不到 50 美元。论文演示的改法很隐蔽：把安装命令里的 requests 换成拼法相近的 reqeusts，一眼看不出来（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s14-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-1', 'concept_archive_s15-1', 'recommendation', '行政法规写得很明白：「出租人收取押金的，应当在住房租赁合同中约定押金的数额、返还时间以及扣减押金的情形等事项。除住房租赁合同约定的情形以外，出租人无正当理由不得扣减押金。」三件事要写进合同：押金收多少、什么时候退、什么情况下能扣。合同里没写的理由，房东不能拿来扣你的钱', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-2', 'concept_archive_s15-2', 'recommendation', '行政法规写得很明白：「出租人不得采取暴力、威胁或者其他非法方式迫使承租人解除住房租赁合同或者腾退租赁住房。」腾退就是让你搬走。遇到这类情况先报警，把证据留下。不要自己动手对抗', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-3', 'concept_archive_s15-3', 'recommendation', '行政法规把「代收、代付住房租金、押金」列为房地产经纪机构的禁止行为，中介不能替房东收你的房租和押金。钱在中介手里过一道，就多一次卷款跑路的机会', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-4', 'concept_archive_s15-4', 'recommendation', '行政法规要求转租经营的住房租赁企业「设立住房租赁资金监管账户并向社会公示」。转租经营就是企业从房东手里整租下来，再转租给你。一次性付一年拿到的那点折扣，抵不上企业跑路时押金和剩余租金一起没的风险。同时签了租金贷的，风险更大', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-5', 'concept_archive_s15-5', 'recommendation', '民法典里有一条叫「买卖不破租赁」。法条原话是：租赁物在租赁期限内发生所有权变动的，不影响租赁合同的效力。意思是租期里房子换了主人，已经签好的租约照样有效。新房东要按原合同让你住到期满', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-6', 'concept_archive_s15-6', 'recommendation', '最常见的两种血本无归，一是把租金付给了不是产权人的人，二是房子早就抵押给银行，后来被查封。转账时备注「某某房屋某月租金」，出了纠纷这就是直接证据', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s15-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-7', 'concept_archive_s15-7', 'recommendation', '规章写得很明白：约定由房地产经纪机构代收代付交易资金的，应当通过其在银行开设的客户交易结算资金专用存款账户划转。意思是房款进的是受监管的专用账户，不是中介自己的账户，也不是某个经纪人的私人账户', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-8', 'concept_archive_s15-8', 'recommendation', '规章写得很明白，最小的出租单位是原设计的房间，不能把一间房再隔成几间分开租。人均租住建筑面积不得低于当地规定的最低标准。厨房、卫生间、阳台和地下储藏室不得出租供人员居住。租期内出租人也不得单方面随意提高租金', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s15-9', 'concept_archive_s15-9', 'recommendation', '国务院办公厅的文件写得很明白：「城镇居民不得到农村购买宅基地、农民住宅或『小产权房』。」同一份文件还规定，农民卖掉或者租出住房以后，再申请宅基地不予批准。2019 年中央农办和农业农村部的文件又说了一遍：「严禁城镇居民到农村购买宅基地。」同一份文件给出了合法的路：城镇居民可以租农房居住或者经营，租赁合同的期限不得超过二十年，到期双方可以另行约定', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s15-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-1', 'concept_archive_s16-1', 'recommendation', '21 项研究、46847 人合起来算（荟萃分析）：和吃药断断续续的人相比，按医嘱吃满的人同期死亡的可能性约低 44%。原值是比值比 0.56，95% CI 0.50–0.63（可信范围）。只看确有疗效的治疗，约低 45%（0.55，0.49–0.62）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-2', 'concept_archive_s16-2', 'recommendation', '国家医保局的文件说已经做到了这一步。原话是「基本实现高血压、糖尿病、恶性肿瘤门诊放化疗、尿毒症透析、器官移植术后抗排异治疗等 5 种门诊慢特病费用跨省直接结算县域可及」。「县域可及」的意思是在县一级就能办到。文件还在这 5 种的基础上再新增 5 种', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-3', 'concept_archive_s16-3', 'recommendation', '慢性病要看的是数值一段时间里怎么变，只看某一次不够。记在同一处还有一个好处：换医院时不用重复检查，也不用重复花钱', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s16-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-4', 'concept_archive_s16-4', 'recommendation', '停药的害处是确定的，偏方的好处是不确定的。常见的无效品类，这本书第 6 节列了一批', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s16-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-5', 'concept_archive_s16-5', 'recommendation', '不用每月往返大医院排队开药。在同一个参保地（也叫统筹地区）里，住基层医院的报销比例原则上比上一级医院高约 10 个百分点', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-6', 'concept_archive_s16-6', 'recommendation', '基本服务包按规定由医保付。个性化服务包的钱全部自己出，这种包还要向县级卫生健康部门备案', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-7', 'concept_archive_s16-7', 'recommendation', '糖尿病伤到眼底叫视网膜病变，伤到脚叫糖尿病足。这两样在出问题之前几乎没有感觉。早查出来还有得治。等到看不见或者脚烂起来，就晚了', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-8', 'concept_archive_s16-8', 'recommendation', '一项为期 5 年、随机分成两组的对照试验，对象是 199 名第一次得钙结石、又查不出原因的患者（也叫特发性钙结石）。一组每天至少喝 2 升水，另一组不做任何干预。5 年里复发的，多喝水那组 12/99（12.1%），不干预那组 27/100（27.0%），P=0.008。P 值越小，越说明两组的差别不是碰巧。平均隔多久复发：38.7±13.2 个月对 25.1±16.4 个月，P=0.016。一开始测的 24 小时尿量，结石患者明显低于没结石的人：男性是 1,057±238 mL 对 1,401±562 mL（P&lt;0.0001），女性是 990±230 mL 对 1,239±440 mL（P&lt;0.001）。NICE 指南 NG118 第 1.8.1 条建议，成人每天喝 2.5 到 3 升水，儿童青少年按年龄喝 1 到 2 升。水里加点鲜柠檬汁，别喝碳酸饮料，成人每天盐不超过 6 克', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s16-9', 'concept_archive_s16-9', 'recommendation', '一项随机分成两组的对照试验，517 名过去 12 个月内发作过的成人。一组由护士主导，给患者讲清楚病是怎么回事，再按指标把尿酸调到达标。另一组照常找全科医生看。2 年时血尿酸降到 &lt;360 µmol/L（6 mg/dL）的比例，95% 对 30%。达标的可能性是常规组的 3.18 倍（RR 3.18，95% CI 2.42–4.18，这个区间是数字的可信范围），P&lt;0.0001。第 2 年的发作频率、痛风石、生活质量这几项次要指标，也都优于常规组。每多换来一年算上生活质量折算的寿命（质量调整生命年），花费 £5,066。同一试验还做了随访研究，438 人发了问卷，收回 82%。两组都自己报告了过去 12 个月的发作次数。达标组的中位数是 0 次（中间一半人落在 0–0 次）。常规组是 1 次（0–3），P&lt;0.001。括号里的这个范围叫四分位距。仍在吃降尿酸药的比例，达标组是常规组的 1.19 倍（校正后 RR 1.19，1.09–1.30）。美国风湿病学会 2020 年痛风指南强烈推荐三种人启动降尿酸治疗：皮下长了痛风石的、影像检查看到痛风把骨头啃出缺损的、每年发作 ≥2 次的。做法是持续监测血尿酸，照着结果调剂量直到达标，目标 &lt;6 mg/dL。首选别嘌醇，3 期及以上慢性肾病的人也是首选它，起始剂量 ≤100 mg/日。启动时同时给抗炎的预防用药，至少吃 3 到 6 个月。同一指南还引用了一组病例观察。这些患者长期控制良好之后停了药，停药后血尿酸仍保持 &lt;7 mg/dL。他们当中，5 年跟踪期内一次都没发作的只有 13%（27/211）。饮食方面，限酒或戒酒的人，血尿酸比不限的人低 1.6 mg/dL，一份啤酒使血尿酸升高 0.16 mg/dL。健康饮食、地中海饮食、DASH 饮食的效果更小。首选哪种降尿酸药有分歧。美国风湿病学会指南强烈推荐别嘌醇作为首选，理由是剂量用够时有效、耐受好、安全、便宜。它还有条件地建议：吃非布司他的人如果有心血管病史，或新出了心血管事件，有别的药可换就换掉。这条推荐和 FDA 给非布司他加的黑框警告一致。依据之一是 CARES 试验，6190 名合并心血管病的痛风病人随机吃非布司他或别嘌醇。非布司他组的全因死亡风险是别嘌醇组的 1.22 倍（HR 1.22，95% CI 1.01–1.47，高约 22%）。心血管死亡是 1.34 倍（1.03–1.73，高约 34%）。欧洲的 FAST 试验结论不同。它纳入 6128 名 60 岁以上、有心血管危险因素的病人，非布司他的主要心血管事件不比别嘌醇多（HR 0.85，0.70–1.03）。死亡人数是非布司他组 7.2%、别嘌醇组 8.6%。吃促进尿酸从肾排出的药的人，美国风湿病学会有条件地不建议碱化尿液，因为没有证据说明有效，证据确定性很低。它同时要求叮嘱这些人多喝水，已知有肾结石或 3 期及以上慢性肾病的人不该用这类药', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s16-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-1', 'concept_archive_s17-1', 'recommendation', '民法典规定，头脑清醒、能自己做主的成年人（法律叫「具有完全民事行为能力的成年人」），可以提前和人商量好将来谁当自己的监护人。商量的对象可以是近亲属，也可以是其他愿意当监护人的个人或者组织。商量好了要「以书面形式确定自己的监护人」。将来他不能做决定了，或者只能做一部分决定了（法律叫「丧失或者部分丧失民事行为能力」），就由写定的这个人来管。没有这份文件，将来谁替他签字、谁替他管钱，要走法院指定', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s17-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-2', 'concept_archive_s17-2', 'recommendation', '民法典认可六种遗嘱形式：自己手写的、请人代写的、打印的、录音录像的、口头的、公证的。每一种都有各自必须做到的手续要求（法律叫「形式要件」）。如果立了好几份，内容互相打架，以最后立的那份为准。2021 年起，公证的那份不再自动排在前面', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s17-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-3', 'concept_archive_s17-3', 'recommendation', '针对老人的保健品、收藏品、理财骗局，套路都是先用几个月把信任攒足，再一次性收割。事先约好「超过多少钱的支出要先和某个人说一声」。这等于把掏钱这个决定往后拖，拖过最冲动的那一阵', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s17-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-4', 'concept_archive_s17-4', 'recommendation', '推销和诈骗都靠现场施压。事先商量好一句「我要回去和家里人商量」，让老人有台阶可下。这比事后讲道理有效', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s17-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-5', 'concept_archive_s17-5', 'recommendation', '民政部列了五种表现形式，认名目比认人可靠。第一种，假借养老服务机构之名：没有实体，临时租个场地，宣称和养老机构签了合作协议来「碰瓷」。第二种，以提供「养老服务」为名：卖「贵宾卡」「会员卡」「预付卡」，让人预交「养老服务费用」，承诺的服务明显超过自己的床位供给能力。第三种，以投资「养老项目」为名。常见名目有入股养生养老基地、销售虚构的养老公寓。还有长期出租养老床位、「时间银行」互助养老。打的幌子是返本销售、售后返租、约定回购。第四种，以销售「老年产品」为名：商品回购、寄存代售、消费返利、免费体检、赠送礼品、会议营销、养生讲座、专家义诊。第五种，以享受「旅居养老」为名：低价或免费旅游、储值返利、积分养老。钱追不回来，条例里写明了。防范和处置非法集资条例第二十五条规定，「因参与非法集资受到的损失，由集资参与人自行承担」，亏掉的钱只能自己认。官方通报过的案子里，戴某平等人以预定养老公寓床位名义非法集资 1.36 亿元，被害人 2100 余人，戴某平以集资诈骗罪判 15 年，并处罚金 40 万元。曹某铭以投资养老产业为名集资诈骗 132.07 亿元，涉及 11 万余人，判无期徒刑、剥夺政治权利终身、没收个人全部财产。保健品会销走的是诈骗罪。倪某荣用免费宴请、赠送礼品、专车接送，把老年人拉去听课。讲师用「虚假人设、虚假案例、虚高砍价」编造防癌抗癌功效。老人被诱骗以成本价的数十倍买「二氢槲皮素」。销售金额 62 万余元。倪某荣判 10 年 3 个月，并处罚金 12 万元（全国，条例 2021 年 5 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s17-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-6', 'concept_archive_s17-6', 'recommendation', '银保监会消保局把真假两种说清楚了。正规的以房养老只有一种，叫「老年人住房反向抵押养老保险」。拥有房屋完全合法产权的老年人，把房产抵押给保险公司。房子照样归自己住、自己用、自己收租。要卖、要处置，得经抵押权人（保险公司）同意。老人按约定条件领取养老金，一直领到去世。这项业务目前仍处于试点阶段，做的人比较少。不法分子说的「以房养老」，与国家试行的住房反向抵押养老保险「完全无关」，是「假借国家政策、为非法集资活动造势宣传的手段」。它的操作是诱骗老人办房产抵押，再把借来的钱去买它推荐的理财产品，「往往是『以新还旧』的庞氏骗局」。后果原文写的是「有的参与人甚至都不知道自己的房产被抵押，最终失去了房子，还背负贷款」。提示里还给了一条看收益率的线。原话是「理财产品如果承诺收益率超过 6% 就要打问号，超过 8% 就很危险，10% 以上就要准备损失全部本金，『保本高收益』就是金融诈骗」。同一份提示还要求「慎重对待合同签署环节，不在空白合同签字」（全国，2021 年 6 月）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s17-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-7', 'concept_archive_s17-7', 'recommendation', '符合规定的长期护理服务费用不设起付线。起付线就是先自己垫够一个数才开始报，这里不用垫。按单位职工政策参保的，由基金报销约 70%。按未就业城乡居民政策参保的，约 50%。一年最多能报到的钱（年度最高支付限额），不超过本地统筹地区上年度城乡居民人均可支配收入的 50%', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s17-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-8', 'concept_archive_s17-8', 'recommendation', '19520 例髋部骨折手术患者（美国 NSQIP 2016 至 2019 年）。开刀前就有压疮的人，30 天内死亡的比例更高。把其他因素算进去之后，这个关联仍然成立（OR 1.2，几率增加 21%，P=0.004）。这些人还更容易出别的问题：深静脉血栓（OR 1.59）、肺炎（OR 1.39）、非计划再住院（OR 1.43），平均住院日也多 0.4 天。324 名住院老人（平均 86 岁）随访中位 18 个月。压疮能单独预测长期死亡（HR 1.500，95% CI 1.059 至 2.126，P=0.020）。单独预测的意思是，把别的因素排掉之后，它自己就能预测。65 项随机试验放在一起算（网络荟萃分析）。比的是电动主动气流支撑面和标准病床垫（标准病床支撑面）。电动主动气流支撑面就是电动气垫床这一类。用它的人压疮发生率更低（RR 0.42，95% CI 0.29 至 0.63，中等确定性）。电动混合气流支撑面是 RR 0.22（0.07 至 0.66）。11 项试验 4462 人的 Cochrane 综述（2026 年更新）。2 小时翻一次和 4 小时翻一次比，差别说不清（RR 1.05，95% CI 0.79 至 1.39，确定性极低）。其他翻身间隔之间的比较，同样极不确定。1226 名 ICU 患者的试验里，用可穿戴传感器实时提醒并给出视觉警示，把 2 小时翻一次真正落实下来。压疮发生率低于常规护理（RR 0.28，95% CI 0.10 至 0.75，中等确定性）。116 人的试验中，俯卧位（趴着）那组的压疮发生率高于仰卧位（平躺）那组（RR 4.55，95% CI 2.31 至 8.98）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s17-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s17-9', 'concept_archive_s17-9', 'recommendation', '一项随机试验找了 306 名 70 岁以上、有白内障的女性。一半在约 4 周内做第一只眼的手术，另一半按常规等 12 个月。一年里，尽快做手术的人跌倒次数少约 34%。原值是跌倒率之比 0.66，可信范围 95% CI 0.45 到 0.96。跌过至少一次的人，手术组 49%，等待组 45%，没有少。跌过两次以上的人，手术组 18%，等待组 25%。手术组 4 人骨折（3%），等待组 12 人（8%）。Cochrane 综述收了这项试验，结论是女性第一只眼的手术减少了跌倒次数，第二只眼的手术没有。第二只眼的随机试验找了 239 名 70 岁以上的女性。手术组跌倒率低 32%，但差别可能是碰巧（跌倒率之比 0.68，95% CI 0.39 到 1.19）。美国医保 5% 抽样里，有 1113640 名 65 岁以上的白内障病人（2002 到 2009 年）。这项研究只是跟踪记录，没有分组对照。做了手术的人，一年内髋部骨折的几率低约 16%（OR 0.84，95% CI 0.81 到 0.87）。绝对差是 0.20 个百分点，约每 1000 人少 2 例', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s17-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s18-1', 'concept_archive_s18-1', 'recommendation', '中共中央办公厅、国务院办公厅印发的方案规定：2025 年 1 月 1 日起出生、3 周岁以下的婴幼儿，按「每孩每年 3600 元」发放。由孩子的父母一方或者其他监护人去申领。这笔补贴「免征个人所得税」。认定低保这类救助的时候，它「不计入家庭或个人收入」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s18-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s18-2', 'concept_archive_s18-2', 'recommendation', '产假天数由国务院规定。「女职工生育享受 98 天产假，其中产前可以休假 15 天；难产的，增加产假 15 天；生育多胞胎的，每多生育 1 个婴儿，增加产假 15 天。」产假期间拿的钱叫生育津贴。已经参加生育保险的，「按照用人单位上年度职工月平均工资的标准由生育保险基金支付」。没参保的，由用人单位按你产假前的工资标准发给你', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s18-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s18-3', 'concept_archive_s18-3', 'recommendation', '国务院规定：「用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。」这三段时间里单位不能给你减钱，也不能把你辞退或者解约。哺乳未满 1 周岁婴儿的，每天有 1 小时哺乳时间。单位也不得安排你延长劳动时间，不得安排夜班。单位违反上面这些的，按每人 1000 元以上 5000 元以下罚款', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s18-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s18-4', 'concept_archive_s18-4', 'recommendation', '把每天照看孩子的时间、夜里被吵醒的次数，都折算成小时。再乘以干这些活的那个人的时薪。得到的数字通常远大于奶粉尿布钱。照看、做饭、夜里起夜这些活虽然没人付钱，也照这样记进成本。算法和第 10 节算家务的那套一样。先谈好分工，再决定生不生', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s18-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s18-5', 'concept_archive_s18-5', 'recommendation', '0 到 3 岁的大头是照料方式：自己带、老人带还是请人带。义务教育阶段（小学到初中）的大头是住房和课外支出。这之后的大头是升学路径。这三段钱花在哪完全不同，混在一起算，只会得到一个吓人的总数', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s18-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s18-6', 'concept_archive_s18-6', 'recommendation', '思路和第 10 节一样。别人的期待可以算你的一个考虑因素。但成本要记在你自己的账上，不记在他们账上。「养儿防老」尤其要单独算一笔，因为它假定的是二十年后另一个人的经济能力和意愿', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s18-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-1', 'concept_archive_s19-1', 'recommendation', '法律规定的正常上班时间是每天不超过 8 小时，平均每周不超过 44 小时。平时加班一般每天不得超过 1 小时。有特殊原因要多干的，每天不得超过 3 小时，而且一个月加起来不得超过 36 小时。加班费分三档。平时安排你延长工作时间的，按不低于工资的 150% 给。休息日安排你上班、又安排不了补休的，不低于 200%。法定休假日安排你上班的，不低于 300%。法定休假日这一档，法条里没有「拿补休顶掉」这个选项。单位安排了加班又不给加班费的，由劳动行政部门勒令它限期付清。过了期限还不付的，勒令它在欠款之外，再按应付金额的 50% 以上 100% 以下加付一笔赔偿金给劳动者（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-2', 'concept_archive_s19-2', 'recommendation', '连续工作满 12 个月就有年休假。天数按累计工作时间定，在所有单位干过的年头都加起来算。满 1 年不满 10 年 5 天，满 10 年不满 20 年 10 天，满 20 年 15 天。国家法定休假日和休息日不算进年休假的天数里。单位确实因为工作需要安排不了、又征得你本人同意不休的，该休没休的那几天「按照该职工日工资收入的 300% 支付年休假工资报酬」。这 300% 里已经含了正常上班那天本来就该给的一份，所以实际额外多拿到手的是 200%。日工资 = 本人月工资 ÷ 21.75。月工资按发这笔钱之前 12 个月的工资算，去掉加班费之后取月平均数。当年才进单位的，按在这家单位剩下的日历天数折算。离职时按当年已经干了多久折算并结清，已经多休的不倒扣回来。单位既不安排休、又不给钱的，勒令限期改正。过了期限还不改的，除了那笔年休假工资报酬，还要再按同样的数额加付一笔赔偿金（全国，2008 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-3', 'concept_archive_s19-3', 'recommendation', '合同签 3 个月以上不满 1 年的，试用期不得超过 1 个月。签 1 年以上不满 3 年的，不得超过 2 个月。签 3 年以上的，以及不写到期日的无固定期限合同，不得超过 6 个月。以干完一件活为期限的合同，或者总共不到 3 个月的合同，不许约定试用期。「同一用人单位与同一劳动者只能约定一次试用期」，同一家公司对同一个人只能试用一回。合同里只写了试用期的，这段试用期不成立，这个期限就是劳动合同期限。试用期工资「不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准」。试用期约得超过法定长度、人又实际干了的，单位要按你试用期满后的月工资标准，就超出去的那段时间另付一笔赔偿金。试用期内单位想解除合同，只能按法律列明的那几种情形，而且要向劳动者说明理由（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-4', 'concept_archive_s19-4', 'recommendation', '劳动合同法定的经济补偿，就是被裁时单位该给的那笔钱，大家常叫它 N。算法是：「每满一年支付一个月工资……六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资」。月工资高过当地上年度职工月平均工资三倍的，按三倍封顶算，而且工龄最多只算到十二年', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-5', 'concept_archive_s19-5', 'recommendation', '劳动合同法规定，用人单位按这一条解除劳动合同的，有两种做法。一种是「提前三十日以书面形式通知劳动者本人」。另一种是「额外支付劳动者一个月工资后，可以解除劳动合同」。想让你立刻走，就得多掏一个月工资。这多出来的一个月俗称代通知金，是 N 之外另算的一笔。这一个月按你上一个月的工资算，N 按离职前 12 个月的平均工资算，两笔的基数不一样', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-6', 'concept_archive_s19-6', 'recommendation', '劳动合同法规定，用人单位违反本法规定解除或者终止劳动合同的，「应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金」。算法是先按经济补偿那套标准算出一份，再翻一倍给你', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-7', 'concept_archive_s19-7', 'recommendation', '劳动合同法把该给经济补偿的情形限定在法律列明的那几类里。劳动者自己提出走人，不在里面，除非是因为公司欠薪、不缴社保这类法定过错。签了「主动辞职」，经济补偿和失业保险金通常一起落空', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s19-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-8', 'concept_archive_s19-8', 'recommendation', '一旦交回电脑和账号，这些材料就再也拿不到了。仲裁时谁来举证，虽然会朝单位那边偏一些，但工资多少、有没有加班这些事，还是要靠你自己手上的证据', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s19-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-9', 'concept_archive_s19-9', 'recommendation', '职业病防治法规定，签劳动合同的时候，单位要把四件事讲清楚：干这份活可能产生哪些职业病危害、会落下什么后果、怎么防护、有什么待遇。法条原文是「如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗」。合同签完之后又调你去干合同里没交代过的有害活儿的，要重新如实告知，并且跟你商量着改合同条款。单位没做到的，「劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同」。体检一共三次：上岗前、在岗期间、离岗时。「职业健康检查费用由用人单位承担」，钱由单位出，结果要书面告诉你本人。没做上岗前体检的人，单位不得安排去干接触职业病危害的活。身体条件本来就不适合这类活的人（有职业禁忌的），也不得安排去干这些禁忌作业。查出跟这份工作有关的健康损害的，要把人调离原岗位并妥善安置。「对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同」。离职时你「有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章」。这份职业健康监护档案，单位要照实复印一份免费给你，还要在复印件上盖章（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-10', 'concept_archive_s19-10', 'recommendation', '法定职业病自 2025 年 8 月 1 日起是 12 大类 135 种，其中含 4 项开放性条款。排在第一类的是职业性尘肺病。里面有矽肺、煤工尘肺、石墨尘肺、碳黑尘肺、石棉肺、滑石尘肺。还有水泥尘肺、云母尘肺、陶工尘肺、铝尘肺、电焊工尘肺、铸工尘肺，再加一项开放条款。职业性耳鼻喉口腔疾病里有噪声聋和爆震聋。职业性眼病里有化学性眼部灼伤和电光性眼炎。这些损伤都不可逆，没有哪种治疗能把肺和听力修回来。法律给了四条可以当场搬出来用的权利。一是知道这个工作场所里有哪些职业病危害、会造成什么后果、该采取哪些防护措施。二是要求单位提供合格的防护设施和个人防护用品、改善工作条件。三是对违反职业病防治法律法规的做法、以及会危及生命健康的做法提出批评、检举和控告。四是「拒绝违章指挥和强令进行没有职业病防护措施的作业」，不合规的指挥和没有防护的活，你可以不干。并且「因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效」。因为你用了这几条权利就给你降薪、降待遇或者辞退你，这些做法不算数（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-11', 'concept_archive_s19-11', 'recommendation', '没做工伤认定，医药费、养伤期间照发的工资（停工留薪期工资）、伤残补助金就全部落空。单位超过 30 日不申报的，这段时间里该给的工伤待遇费用由单位自己掏', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-12', 'concept_archive_s19-12', 'recommendation', '视同工伤要求人「在工作时间和工作岗位」上突发疾病死亡，或者在 48 小时之内经抢救无效死亡。为了凑齐这两个条件而耽误就医，赔的是自己活下来的机会，换来的赔偿也不一定拿得到', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-13', 'concept_archive_s19-13', 'recommendation', '条例明写：没给员工交工伤保险的单位，员工出了工伤，由这家单位按条例规定的项目和标准把钱付出来。该给哪几笔、每笔给多少，和交了保险的完全一样，只是改成单位自己掏', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-14', 'concept_archive_s19-14', 'recommendation', '一次性伤残补助金按伤残等级折算成几个月的工资，一次付清。五级 18 个月、六级 16 个月、七级 13 个月的本人工资。八级 11 个月、九级 9 个月、十级 7 个月的本人工资', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-15', 'concept_archive_s19-15', 'recommendation', '因工死亡的钱分三笔。第一笔是丧葬补助金，金额是参保所在地区（统筹地区）上年度职工月平均工资的 6 个月。第二笔是供养亲属抚恤金，按死者本人工资按月发，配偶每月 40%，其他亲属每人每月 30%。第三笔是一次性工亡补助金，金额是上一年度全国城镇居民人均可支配收入的 20 倍，全国只有这一个数，不分地区。2026 年因工死亡的，这一笔是约 113 万元（1130040 元）。算法是上一年度全国城镇居民人均可支配收入 56502 元乘以 20。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-16', 'concept_archive_s19-16', 'recommendation', '健康上，瑞典和丹麦三个队列合起来，共 79,201 名 18 到 65 岁的在职者。他们起初都没有心血管病，平均跟踪 12.4 年。9% 的人说过去一年在单位被欺负过。被欺负的人得心血管病（冠心病和脑血管病）的风险高约 59%（HR 1.59，95% CI 1.28–1.98）。在单位遭遇过暴力的，高约 25%（HR 1.25，1.12–1.40）。两种都是遭遇越多，风险越高。挪威一项全国随机抽样的跟踪调查，1846 名在职者，隔两到三年测一次，共测三次。被欺负的人后来出现自杀念头的几率约是别人的 2 倍（OR 2.05，95% CI 1.08–3.89）。反过来，先有自杀念头的人，后来并不更容易被欺负。法律上，我国没有专门管「职场霸凌」的法律，要按具体行为对号。单位侮辱、体罚、殴打、非法搜查或者拘禁劳动者的，要受行政处罚，造成损害要赔偿，构成犯罪的追究刑事责任。单位用暴力、威胁强迫你干活的，你可以立即解除合同，不用事先通知，还能拿经济补偿。单位要采取措施，预防和制止有人利用职权、上下级关系实施性骚扰。受害人可以要求骚扰的人承担民事责任。劳动仲裁从受理那天算起 45 日内结案，复杂的最多再延 15 日。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s19-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-17', 'concept_archive_s19-17', 'recommendation', '劳动合同法规定，单位要在解除或者终止劳动合同时出具证明。法条不分是谁提出的，合同到期不续、你自己辞职、被辞退都在内。单位还要在 15 日内为你办好档案和社会保险关系的转移手续。实施条例规定证明上要写四样：劳动合同期限、解除或者终止的日期、工作岗位、在本单位的工作年限。失业保险条例规定，职工失业后要拿着单位出具的这份证明，及时去社保经办机构办失业登记。失业保险金从办失业登记那天起算。单位不出书面证明的，由劳动行政部门责令改正。给你造成损害的，单位要赔。法律另外规定，新单位招了还没和原单位解除合同的人，给原单位造成损失的，要承担连带赔偿责任。离职证明就是你已经和原单位解除合同的书面凭据（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-18', 'concept_archive_s19-18', 'recommendation', '财政部和税务总局的文件规定，个人和用人单位解除劳动关系拿到的一次性补偿收入，包括经济补偿金、生活补助费和其他补助费。其中在当地上年职工平均工资 3 倍以内的部分，免征个人所得税。超过 3 倍的部分，不并入当年综合所得，单独按综合所得税率表算税。这张表全年 36000 元以内的部分税率 3%，36000 元到 144000 元的部分 10%，再往上分级加到 45%。举个例子，当地上年职工平均工资是 10 万元，3 倍就是 30 万元。拿到 36 万元补偿，只就超出的 6 万元算税，是 3480 元。同样 36 万元要是整笔都按这张表算，是 58080 元。这条从 2019 年 1 月 1 日起执行，没有写截止日期（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s19-19', 'concept_archive_s19-19', 'recommendation', '社会保险法规定，换个地方就业的（正式说法是跨统筹地区），养老关系随本人转移，缴费年限累计计算。职工医保也一样，关系跟着人走，年限累计计算。退休时养老金分段计算、统一支付。跨省转养老关系按国务院办公厅转发的转移接续办法办。没到领取待遇的年龄，不得终止养老关系、办理退保。社会保险法也写明个人账户不得提前支取。个人账户里的钱连本带息全部转走。单位交的那部分叫统筹基金，按你 1998 年以后各年实际缴费工资的 12% 转过去。领养老金时，按你各年的缴费工资、缴费年限和领取地各年的平均工资算。手续是在新地方参保缴费以后，由单位或你自己向新参保地书面申请。新参保地 15 个工作日内审核，原参保地接到同意接收函后 15 个工作日内办好转出。新参保地收到关系和资金后，再 15 个工作日内办结。按 2020 年的跨省通办清单，这件事要在当年底前实现跨省通办。你向转入地申请就行，不用再回转出地办。职工医保要原参保地先停保、新地方已经参保，才能申请转移。可以在国家医保服务平台网上申请，也可以去窗口。原参保地 10 个工作日内转出，新参保地 5 个工作日内转入，个人账户余额一起划过去。转之前断缴 3 个月以内的，按新地方规定补缴后不设等待期，缴费当月就能报销，中间那段也能追溯报。断缴超过 3 个月的，等待期按各地规定，原则上不超过 6 个月（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s19-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-1', 'concept_archive_s20-1', 'recommendation', '美国每年约 3500 名婴儿死于睡眠相关原因。这里面包括婴儿猝死综合征、死因不明和在床上意外憋住。美国儿科学会给的安全睡眠环境是「仰卧位；使用坚实、不倾斜的睡眠表面；同房不同床；避免柔软的寝具和过热」。还有几件事也能降低风险：母乳喂养、别让孩子接触尼古丁和酒精、按时接种疫苗、使用安抚奶嘴', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-2', 'concept_archive_s20-2', 'recommendation', '世界卫生组织的说法是：「所有婴儿都应在出生后尽早（24 小时内）接种乙肝疫苗。」原因是「婴儿期和幼儿期感染约有 95% 会发展为慢性肝炎」。成年后感染的绝大多数能自愈（不用治也会好）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-3', 'concept_archive_s20-3', 'recommendation', '孩子入托、入学的时候，托幼机构和学校要查验预防接种证。发现没按规定接种免疫规划疫苗的，要报告接种单位，并且配合督促监护人补种。所以漏打的疫苗拖不过去，入学时一定会被查出来。现在执行的是 2026 年版程序。人乳头瘤病毒（HPV）疫苗已经纳入国家免疫规划。百白破疫苗的起始接种年龄从 3 月龄改成 2 月龄，一共 5 剂，分别在 2 月龄、4 月龄、6 月龄、18 月龄和 6 周岁各打 1 剂。西藏、青海、新疆和新疆生产建设兵团的适龄儿童，2026 年 3 月起也常规接种乙脑疫苗。几种疫苗可以同一天打：现阶段国家免疫规划疫苗都可以按免疫程序或补种原则同时接种。两种及以上打针的疫苗要打在不同部位，「严禁将两种或多种疫苗混合吸入同一支注射器内接种」。没在同一天打的，两种及以上打针的减毒活疫苗之间要间隔不小于 28 天。灭活疫苗、口服的减毒活疫苗和其他疫苗之间的间隔不作限制。不满 18 周岁的补种原则是尽早补种，「只需补种未完成的剂次，无需重新开始全程接种」，同一种疫苗换厂家可以接着打（全国，2026 年版程序）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-4', 'concept_archive_s20-4', 'recommendation', '世界卫生组织的建议是「在出生后第一个小时内开始母乳喂养」。前 6 个月「纯母乳喂养，即不提供其他任何食物或液体，包括水」。然后「从 6 月龄起开始添加安全充足的辅食，同时继续母乳喂养到 2 岁或以上」。国家卫健委的服务指南也提倡 0 至 6 月龄纯母乳喂养。这份指南还要求满 6 月龄起「每天的辅食必须包含含铁丰富的动物性食物」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-5', 'concept_archive_s20-5', 'recommendation', '奶粉不是无菌的，可能带阪崎克罗诺杆菌。新生儿感染后的病死率，报告为 40% 到 80%。实验研究显示：先把热水倒进奶瓶，等水温降到约 73.8 ℃ 再加奶粉，绝大多数情况下奶液温度还在 70 ℃ 以上。这样可以让这种菌减少 5 个对数级以上，降到原来的十万分之一以下', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-6', 'concept_archive_s20-6', 'recommendation', '美国疾控中心的说法是「不要给 1 岁以下的儿童喂蜂蜜」，因为「蜂蜜可能含有引起肉毒中毒的细菌」。成年人的肠道菌群能压住这种芽孢（这种细菌的休眠状态），婴儿压不住', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-7', 'concept_archive_s20-7', 'recommendation', '新生儿体内存的维生素 K 很少。不补充可能出现维生素 K 缺乏性出血，晚出现的那一种常常表现为颅内出血（脑子里出血）。比利时的共识建议是「出生时肌肉注射 1 或 2 毫克维生素 K 一次」。在没有系统提供预防的地区，维生素 K 缺乏性出血的发生率是每 10 万人 478 例，这个数字来自塔什干的 4.2 万名新生儿。作者估计，做了预防可以使发生率下降「高于 78.5%」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s20-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-8', 'concept_archive_s20-8', 'recommendation', '美国儿科学会为 8 至 60 日龄、看上去状态还可以的足月婴儿制定了专门指南。这份指南把发热定义为「体温 ≥38.0 ℃」。它按 8 至 21 日龄、22 至 28 日龄、29 至 60 日龄分成三档，各给一条处理路径。不满 8 日龄的婴儿甚至不在这份指南的范围里，意思是这个阶段更要立即就医', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-9', 'concept_archive_s20-9', 'recommendation', '婴儿头部占比大，颈部肌肉弱。剧烈摇晃会造成颅内出血和视网膜出血（脑子里和眼睛里出血），可能致死，也可能留下终身残疾。哄睡时的轻柔摇动不算，危险的是失控的剧烈晃动。医学上把摇晃、撞击造成的这类伤叫「虐待性头部外伤」。它是 2 岁以下孩子头部外伤致死的首要原因。美国 1999 到 2014 年，它造成近 2250 名 5 岁以下孩子死亡', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s20-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-10', 'concept_archive_s20-10', 'recommendation', '没有任何官方机构发布过「哪个牌子最好」的排名，所以本书不给品牌推荐。能核查的信息只有两类。一类是国家市场监督管理总局的产品质量抽检通报。另一类是监管部门对具体事件的调查。2026 年 6 月「婴幼儿纸尿裤甲酰胺问题」引起关注之后，市场监管总局牵头成立了联合调查组去核查', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s20-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-11', 'concept_archive_s20-11', 'recommendation', '婴儿车、婴儿床、抱被、玩具的使用期都很短，二手市场上供给远大于需求。真正不能省、也不建议买二手的是两样：安全座椅和床垫。安全座椅撞过之后的结构损伤，肉眼看不出来', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s20-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-12', 'concept_archive_s20-12', 'recommendation', '英国 LEAP 随机试验。640 名婴儿入组，条件是有重度湿疹、鸡蛋过敏，或者两样都有。入组时 4 到 11 个月大。随机分成两组，一组定期吃花生制品，一组完全回避，到 60 个月大时看花生过敏率。入组时花生皮试阴性的 530 人里，回避组 13.7% 过敏，吃的组 1.9%（P&lt;0.001）。入组时皮试已经弱阳性的 98 人里，回避组 35.3%，吃的组 10.6%（P=0.004）。两组的严重不良事件没有差别。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s20-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s20-13', 'concept_archive_s20-13', 'recommendation', '美国儿科学会 2022 年的指南说，「超过 80% 的新生儿会有某种程度的黄疸」。胆红素太高，会引起急性胆红素脑病和核黄疸。指南说核黄疸是「永久的致残性神经系统疾病」。它的表现包括手脚不自主扭动的脑瘫、眼睛往上看不了、乳牙釉质发育不良和听力损害。指南把「出生后 24 小时内出现黄疸」列为会发展成重度黄疸的风险因素。英国国家医疗服务体系（NHS）给家长的说法分两档。第一档要打急救电话或直接去急诊。这一档是孩子有黄疸，同时比平时嗜睡或叫不醒、不吃奶、身子发软或发硬、有抽动。孩子出生还不满 24 小时就有黄疸的，也算这一档。第二档要尽快约医生。这一档是出生超过 24 小时，黄疸不见好或越来越重，尿深黄或褐色，或者大便是淡奶油色。全球估算，2010 年约 48 万名新生儿得了 Rh 溶血病（母子血型不合引起）或极重度的高胆红素血症。这些孩子里 24% 死亡，13% 发展成核黄疸。核黄疸活下来的孩子里，83% 以上留下一种或多种残损。大便发白可能是胆道闭锁，这种病要在 60 天内做葛西手术（Kasai 手术），预后才明显更好。台湾从 2004 年起，把大便比色卡印进每个新生儿的儿童健康手册。60 天内做上手术的比例，从 2004 年的 60% 升到 2005 年的 74.3%。另一项台湾全民研究里，推行比色卡之后，胆道闭锁孩子的死亡率从 26.2% 降到 15.9%。这是前后对比，不是分组试验', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s20-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-1', 'concept_archive_s21-1', 'recommendation', '外交部按风险高低公开发布国外安全提醒。从低到高大致是四档：「注意安全」「加强安全防范」「谨慎前往」「暂勿前往」。2026 年 9 月 15 日起施行的新规，把个人的义务也写进了行政法规。原文是：「中国公民应当关注国外安全提醒和旅游目的地安全风险提示，避免前往及驻留高风险国家或者地区」。新规同时要求移民管理机构（办出入境证件和管边检的部门），在办证和出境边检时提醒要去高风险地区的人。这一条的原文是：「对准备前往风险等级为最高级别或者严重危及人身安全案件突发高发的国家或者地区的中国公民，必要时应当劝阻其前往」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-2', 'concept_archive_s21-2', 'recommendation', '外交部有一条全球领事保护与服务应急热线，24 小时有人接。人在国内拨 12308。人在国外拨 +86-10-12308，或者 +86-10-65612308。这条热线从 2014 年开通到现在，累计接听 300 多万通来电。同一时期，外交部和驻外机构处置各类领事保护案件 50 多万起', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-3', 'concept_archive_s21-3', 'recommendation', '你被抓时，使领馆能做这么几件事。向所在国有关部门核实情况，要求依法公正处理。条例原文是「按照驻在国法律和我国与驻在国缔结或者共同参加的国际条约对其进行探视或者与其联络，了解其相关需求，要求驻在国有关部门给予该中国公民人道主义待遇和公正待遇」。说白了就是照当地法律和两国签的条约去看你、跟你联络、问你要什么，并要求当地按人道和公正的标准对待你。开庭时使领馆可以旁听，可以要求保障你的诉讼权利。你受了伤或者赶上灾，它能催当地紧急救助，能帮家属处理善后。但费用上条例写得同样清楚：「中国公民、法人、非法人组织在领事保护与协助过程中，得到第三方提供的食宿、交通、医疗等物资和服务的，应当支付应由其自身承担的费用」。别人先垫的食宿、交通、医疗，该你掏的还是你掏', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-4', 'concept_archive_s21-4', 'recommendation', '在境外看病的钱要自己出。国内医保在境外基本不报销。领事保护也不垫付这笔钱（见第 3 条，领事保护能做什么、不能做什么，依据是条例第二十六条）。真正会把一个家拖垮的不是门诊费，是重伤以后的住院和医疗转运。把人从境外医院转回国，要用专机或者医疗护送，属于自费项目里最贵的一类。美国疾控中心的说法是，把病人从偏远地方紧急转运到好医院，自己付的话可能要花 10 万美元以上。买保险时优先看两项额度。一是境外医疗费用额度。二是紧急医疗转运与送返额度，管的是出事后转院、把人送回国最多能赔多少', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s21-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-5', 'concept_archive_s21-5', 'recommendation', '官方对这类案件的定性很直接。近年出现「上当受骗出境或者虚构事由非法出境从事跨境赌博、电信网络诈骗等违法活动，严重危害人民群众生命和财产安全」。说的是被人骗出去，或者编个理由偷着出去，到那边干赌博和电信诈骗。新规针对这一点两头收紧。出境这头：「申请出境入境、停留居留的事由应当真实、合法」。交假材料或者说假话的，移民管理机构有权不给你发证件、不放你出境。回国这头：「中国公民在境外从事违法犯罪活动，危害国家安全和利益的，可以……决定自回国之日起 6 个月至 3 年以内不准其出境」。因为骗取证件、非法出境入境被行政拘留的，同样是 6 个月至 3 年不准出境', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-6', 'concept_archive_s21-6', 'recommendation', '依据是国家外汇管理局《关于规范银行卡境外大额提取现金交易的通知》（汇发〔2017〕29 号，2018 年 1 月 1 日起实施）。第一条：「个人持境内银行卡在境外提取现金，本人名下银行卡（含附属卡）合计每个自然年度不得超过等值 10 万元人民币。超过年度额度的，本年及次年将被暂停持境内银行卡在境外提取现金」。同条第二款：「个人不得通过借用他人银行卡或出借本人银行卡等方式规避或协助规避境外提取现金管理」。第二条：外汇局每天把暂停名单发给发卡银行，发卡银行应不晚于北京时间当日 17 时起，暂停名单里的人用本行银行卡在境外取现。第三条：被列入暂停名单的人，可以拿本人有效身份证件到外汇局分支局，查自己的境外取现明细。第四条：外币卡每卡每日的上限，由等值 1000 美元调整为等值 1 万元人民币；人民币卡维持每卡每日不得超过等值 1 万元人民币。第六条：发卡银行、境内人民币卡清算组织和个人违反本通知规定的，按《中华人民共和国外汇管理条例》有关规定处罚。外汇局答记者问还讲清了几点。《通知》不影响个人持卡在境外消费。出境旅游、商务、留学所涉的食、宿、行、购等经常项下交易，都可以刷银行卡支付。这些消费也不占用个人便利化年度 5 万美元购汇额度。年度额度由外汇局汇总各家发卡金融机构的数据算出来，因为实时控制会拖慢交易响应，「外汇局采用延时控制手段」（不当场拦截）。另据统计，2016 年 81% 的境内银行卡境外提取现金低于 3 万元人民币（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-7', 'concept_archive_s21-7', 'recommendation', '护照丢了，驻外使领馆能给你签发回国用的旅行证件，但需要你先证明自己的身份。手里有清晰的护照资料页照片、签证页照片和出入境记录，补办速度差别很大。同时你要先在当地报警，拿到报案回执。很多国家的出境检查和保险理赔都要这份材料。找使领馆的入口，就是第 2 条里存好的那两个领保电话', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s21-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-8', 'concept_archive_s21-8', 'recommendation', '所谓「国际驾照」（IDP），是 1949 年《道路交通公约》缔约国之间互相认可的翻译件。这份公约 1949 年 9 月 19 日在日内瓦订立，1952 年 3 月 26 日生效。目前有 103 个缔约方（签约的国家和地区）。中国内地不在这份名单里。所以中国不签发这种国际驾照。任何机构在国内「代办国际驾照」，都不产生法律效力。能不能用中国驾照开车，取决于目的地国家或地区自己的规定：有的承认中国驾照加公证翻译件，有的要求换领当地驾照，有的完全不认', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-9', 'concept_archive_s21-9', 'recommendation', '2018 年取消了因私出入境中介机构的准入许可（开中介不必先拿批文）。此后机构数量快速增长，也出现了「机构底数不清、部分机构违法违规办理业务、损害出境入境人员合法权益」的问题，官方连有多少家都数不清。2026 年 9 月 15 日起，这类中介改成备案管理。机构应当自设立之日起 15 日内，向所在地移民管理机构报备。此前已经在做的，要在施行之日起 90 日内补办。明令禁止的行为有这几类。一是「发布虚假信息，或者通过夸大宣传、误导性宣传等方式招徕服务对象」。二是「提供或者协助提供虚假材料，协助他人违规办理签证、停留居留证件、护照等出境入境证件或者手续」。三是「泄露、出售、非法提供……个人隐私或者个人信息」。四是「组织或者协助他人从事跨境违法犯罪活动」。境外企业、机构不得在中国境内提供这类中介服务', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-10', 'concept_archive_s21-10', 'recommendation', '出具邀请函的人，要对内容是不是真实负责。原文是：「个人为他人申请出境入境、停留居留出具虚假邀请函件或者其他申请材料的，由移民管理机构处 5000 元以上 1 万元以下罚款；有违法所得的，没收违法所得」。单位出具虚假材料的，罚 1 万元以上 5 万元以下。同时对直接负责的主管人员和其他直接责任人员（管事的领导和经手人），再处 5000 元以上 1 万元以下罚款', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s21-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s21-11', 'concept_archive_s21-11', 'recommendation', '中国公民在境外下落不明时，亲属可以向驻外外交机构求助。条例原文是「驻外外交机构应当提供当地报警方式及其他获取救助的信息」。当地警方立案以后，使领馆会催他们及时处理。这些求助能不能启动，取决于国内有没有人知道你本该在哪、本该什么时候联系', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s21-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-1', 'concept_archive_s22-1', 'recommendation', '这是经营者的法定义务。做不到就是违法，你可以举报。条例原文：「营业期间，娱乐场所应当保证疏散通道和安全出口畅通，不得封堵、锁闭疏散通道和安全出口，不得在疏散通道和安全出口设置栅栏等影响疏散的障碍物」。条例还要求，「应当在疏散通道和安全出口设置明显指示标志，不得遮挡、覆盖指示标志」。网吧也一样，被要求「营业期间禁止封堵或者锁闭门窗、安全疏散通道和安全出口」，并「禁止明火照明和吸烟」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-2', 'concept_archive_s22-2', 'recommendation', '条例原文：「娱乐场所提供娱乐服务项目和出售商品，应当明码标价，并向消费者出示价目表；不得强迫、欺骗消费者接受服务、购买商品。」违反价格法律法规的，由有关部门依法处罚。所谓「天价酒水」纠纷，绝大多数发生在这种场合：没有出示价目表，事后按口头报价结账', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-3', 'concept_archive_s22-3', 'recommendation', '条例明令禁止娱乐场所「贩卖、提供毒品，或者组织、强迫、教唆、引诱、欺骗、容留他人吸食、注射毒品」。从业人员也不得吸毒，不得为顾客做上面这些事提供条件。违反的，由公安部门没收违法所得和非法财物，责令停业整顿 3 至 6 个月。情节严重的吊销娱乐经营许可证。条例还要求场所在大厅、包厢、包间的显著位置悬挂禁毒、禁赌、禁止卖淫嫖娼的警示标志，并注明举报电话', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-4', 'concept_archive_s22-4', 'recommendation', '现在的毒品不长毒品的样子。合成大麻素类物质自 2021 年 7 月 1 日起被整类列管，这一大类整体按毒品管。有人把它掺进烟油，做成「上头」电子烟。最高检报道的案子里，办案人员的描述是：这种烟油「可以通过添加食用颜料变成各种颜色、各种口味」，「在外观上和普通电子烟基本一致」。卖家在酒吧、KTV、宾馆呼朋引伴推销，诱导他人吸食。报道里，当地当年办理的吸食案件中，未成年吸食者占比近四成。依托咪酯自 2023 年 10 月 1 日起列入第二类精神药品目录。骗人吸食本身就是一档违法：引诱、教唆、欺骗或者强迫他人吸食、注射毒品的，拘留 10 到 15 日并罚 1000 到 5000 元。构成犯罪的判 3 年以下，情节严重的判 3 到 7 年，强迫的判 3 到 10 年，对未成年人下手的从重。后果也落在被骗的人身上：吸食、注射毒品的，处 10 到 15 日拘留并可罚 3000 元以下。情节较轻的处 5 日以下拘留或者 1000 元以下罚款。还可能被同时责令 6 个月到 1 年内不得进入娱乐场所。成瘾的责令社区戒毒 3 年。拒绝社区戒毒、或者戒毒期间再吸的，强制隔离戒毒 2 年，最长可再延长 1 年（全国，治安管理处罚法 2026 年 1 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-5', 'concept_archive_s22-5', 'recommendation', '五部门 2022 年的专门通知写得很具体：「剧本娱乐经营场所不得设在居民楼内、建筑物地下一层以下（不含地下一层）等地」。通知还要求场所落实安全生产法和消防法的要求，「常态化开展火灾风险自知、自查、自改，提高紧急情况下的组织疏散逃生和初起火灾扑救能力」。同一份通知还要求剧本设置适龄提示。场景不适宜未成年人的，不得允许未成年人进入。除法定节假日、休息日及寒暑假外，不得向未成年人提供剧本娱乐活动', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-6', 'concept_archive_s22-6', 'recommendation', '这是把 218 项随机分成两组的对照试验合在一起算的结果。涉及 495 个组、14170 名符合重度抑郁临床标准的参与者。算法让各种运动互相比较（贝叶斯网状荟萃分析）。拿来对比的是常规照护和安慰剂片（主动对照）。效果大小用 Hedges'' g 表示，数越往负走，症状改善越多。快走或慢跑 −0.62（95% 可信区间 −0.80 至 −0.45，意思是真实值大致落在这一段里）。瑜伽 −0.55（−0.73 至 −0.36）。力量训练 −0.49（−0.69 至 −0.29）。混合有氧 −0.43（−0.61 至 −0.24）。太极或气功 −0.42（−0.65 至 −0.21）。原文说「运动的效果与所处方的强度成正比」：强度开得越高，效果越好。力量训练和瑜伽的可接受度最好，最容易坚持下来', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-7', 'concept_archive_s22-7', 'recommendation', '这是美国 3 家城市学术医疗中心做的试验，目的是看上课会不会比吃药差（非劣效随机对照试验）。276 名确诊焦虑障碍的成年人按 1:1 随机对半分组。一组上 8 周正念减压课程。一组吃艾司西酞普兰（10 至 20 mg 弹性剂量）。208 人做完全程。结束时按医生打的焦虑严重程度分（临床总体印象严重度量表）算，正念组下降 1.35，药物组下降 1.43。两组差 −0.07（95% CI −0.38 至 0.23，即真实差距大致落在这一段里；P=0.65，即这点差距和没差别看不出区别）。这一段的下限没有越过事先划好的「算不上更差」的线（非劣效界值 −0.495）。副作用差别很大：药物组 78.6% 至少出现一次和试验有关的不良反应，10 人因此退出。正念组 15.4%，无人因此退出', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-8', 'concept_archive_s22-8', 'recommendation', '这是一项在家做、随机分组的对照试验，比较三种每天 5 分钟的呼吸练习和同样时长的正念冥想，持续 1 个月。三种呼吸法是：循环叹息（强调延长呼气）、箱式呼吸（吸气、屏息、呼气等长）、带屏息的循环过度换气（吸气长、呼气短）。把各人各次的数据放在一起算（混合效应模型），呼吸练习都好过正念冥想，尤其是以呼气为主的循环叹息。它在情绪改善（P&lt;0.05，即这点差别不像是碰巧撞出来的）和呼吸频率下降（P&lt;0.05）上都更好', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s22-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-9', 'concept_archive_s22-9', 'recommendation', '这是把 70 项先记录情况再往后跟踪的研究合在一起算的结果（荟萃分析），共 340 万名参与者，平均跟踪 7 年。社会隔离、孤独感、独居都与死亡率升高相关。把年龄、身体状况这些干扰因素扣掉之后，加权平均比值比分别是：社会隔离 1.29、孤独 1.26、独居 1.32。换算过来，同期死亡的概率分别高约三成、约四分之一、约三成。三者的效果大小差不多，而且在 65 岁以下人群中比在老年人群中更大', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s22-10', 'concept_archive_s22-10', 'recommendation', '这是把 9 项跟踪人群多年的研究合在一起算的结果（队列研究的荟萃分析），涉及 7 个国家、832 万人。看的是住处 500 米以内的周边绿化程度，用归一化植被指数（NDVI，把地面绿化折算成的一个数）衡量。绿化程度每增加 0.1 个指数，总死亡率的合并风险比为 0.96（95% CI 0.94–0.97），同期死亡的概率低约 4%，真实值大致落在低 3% 到低 6% 这一段。9 项研究中有 7 项发现绿化越好死亡率越低，差别也不像碰巧。另外 2 项没看出关联', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s22-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-1', 'concept_archive_s23-1', 'recommendation', '《义务教育法》第十一条：「凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育」。第十四条：「禁止用人单位招用应当接受义务教育的适龄儿童、少年」。第五十八条：没有正当理由、不按本法规定送适龄儿童少年入学的，由当地乡镇人民政府或者县级人民政府教育行政部门「给予批评教育，责令限期改正」。《禁止使用童工规定》第二条：国家机关、社会团体、企业事业单位、民办非企业单位或者个体工商户「均不得招用不满16周岁的未成年人」。第六条：「按照每使用一名童工每月处5000元罚款的标准给予处罚」，逾期不改正的按每人每月 1 万元罚。第七条：介绍童工去就业的，「按照每介绍一人处5000元罚款」。第十条：童工患病或者受伤的，用人单位「应当负责送到医疗机构治疗，并负担治疗期间的全部医疗和生活费用」，伤残或死亡的还要一次性赔偿。第十三条只留了一个例外：文艺、体育单位经父母或者其他监护人同意，可以招用不满 16 周岁的专业文艺工作者、运动员（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-2', 'concept_archive_s23-2', 'recommendation', '把此前的研究找齐再合在一起算（系统综述与荟萃分析）。检索范围是 1980 年 1 月到 2023 年 5 月，最终纳入 603 项研究、59 个国家 70 个地点、10355 个观测。教育和成人死亡率（各种原因加起来的死亡）是剂量反应关系（读得越多降得越多）。每多受一年教育，死亡风险平均下降 1.9%（95% 不确定区间 1.8–2.0，真实值大致落在这一段里）。18 至 49 岁的人每多一年下降 2.9%（2.8–3.0）。70 岁以上的人下降 0.8%（0.6–1.0）。男女之间没看出差别。按国家发展水平（社会人口指数）分开看，也没看出差别', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-3', 'concept_archive_s23-3', 'recommendation', '第七次全国人口普查的标准时点是 2020 年 11 月 1 日。全国人口里，有大学（大专及以上）文化程度的 218360767 人。高中（含中专）213005258 人。初中 487163489 人。小学 349658828 人。和 2010 年第六次人口普查相比，每 10 万人中有大学文化程度的由 8930 人上升为 15467 人。高中由 14032 人上升为 15088 人。初中由 38788 人下降为 34507 人。小学由 26779 人下降为 24767 人。15 岁及以上人口的平均受教育年限由 9.08 年提高到 9.91 年。文盲率由 4.08% 下降为 2.67%。2025 年全国 1% 人口抽样调查的标准时点是 2025 年 11 月 1 日，样本 2052 万人。按样本推算全国人口 140545 万人。其中大学（大专及以上）27233 万人，高中（含中专）24272 万人，初中 45283 万人，小学 33122 万人。公报没有给每 10 万人的数。按总人口自己折算，大学约占 19.4%，初中约占 32.2%，仍是人数最多的一档', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-4', 'concept_archive_s23-4', 'recommendation', '中职免学费是 2012 年秋季学期起的政策。原文是「对公办中等职业学校全日制正式学籍一、二、三年级在校生中所有农村（含县镇）学生、城市涉农专业学生和家庭经济困难学生免除学费（艺术类相关表演专业学生除外）」。2024 年调整了学生资助政策。本专科生国家助学金由每生每年 3300 元提高到 3700 元。国家励志奖学金由 5000 元提高到 6000 元。这两项从 2024 年秋季学期起执行（励志奖学金自 2024 年起）。中等职业学校国家助学金、普通高中国家助学金都由每生每年 2000 元提高到 2300 元，从 2025 年春季学期起执行。国家助学贷款也调了，从 2024 年秋季学期起。本专科学生「每人每年申请贷款额度由不超过16000元提高至不超过20000元」。研究生「由不超过20000元提高至不超过25000元」。利率是同期同档次的贷款市场报价利率（LPR）减 70 个基点（再低 0.7 个百分点）（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-5', 'concept_archive_s23-5', 'recommendation', '《职业教育法》（2022 年 5 月 1 日起施行）第三条：「职业教育是与普通教育具有同等重要地位的教育类型」。第三十七条：中等职业学校「可以按照国家有关规定，在有关专业实行与高等职业学校教育的贯通招生和培养」。高等职业学校「可以按照国家有关规定，采取文化素质与职业技能相结合的考核方式招收学生」。省级以上教育行政部门要建立职业教育统一招生平台，汇总发布学校、专业设置和招生情况，并提供查询报考服务。第五十三条：「职业学校学生在升学、就业、职业发展等方面与同层次普通学校学生享有平等机会」。高等职业学校和实施职业教育的普通高等学校「应当在招生计划中确定相应比例或者采取单独考试办法，专门招收职业学校毕业生」。「用人单位不得设置妨碍职业学校毕业生平等就业、公平竞争的报考、录用、聘用条件」。事业单位公开招聘中有职业技能等级要求的岗位「可以适当降低学历要求」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-6', 'concept_archive_s23-6', 'recommendation', '这是对中国城镇 1988 至 2001 年的估计。多读一年书能让收入高出多少，这叫教育回报率。原文写的是「从 1988 年每受教育一年 4.0% 大幅上升到 2001 年的 10.2%」。涨幅主要发生在 1992 年之后。它反映的是念到大学的人比没念的多挣的那一截（高等教育工资溢价）在变大。这是把「多读一年」折成年收入差时可用的中国本土量级。全球平均值见本节第 7 条（多受一年教育的全球平均回报）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s23-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-7', 'concept_archive_s23-7', 'recommendation', '一项覆盖 1950 至 2014 年、139 个国家、1120 项估计的综述算出：「多受一年教育的全球平均私人回报率是每年 9%」。私人回报就是落到本人收入上的那一部分：多读一年书，收入平均高约 9%。高等教育的私人回报在上升。教育的社会回报（落到整个社会而不是本人身上的那部分）仍然很高。女性受教育的平均回报持续高于男性', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-8', 'concept_archive_s23-8', 'recommendation', '人社部专门为此开展过全国性治理。文件里点名的乱象是「一些机构和单位以新职业职业资格、职业技能等级等名义随意举办培训、评价、发证活动，乱收费、滥发证；一些机构和单位虚假或夸大宣传，甚至假冒权威机构名义组织培训、评价、颁发证书等」。治理措施包括联合网信、公安、市场监管等部门查处，「严厉打击假冒鉴定机构、人社部门备案评价机构的评价发证活动」。网站和新媒体上不合规的宣传，依法关停。文件同时要求「引导公众了解证书查询渠道和方式，判断证书合法合规性和含金量」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-9', 'concept_archive_s23-9', 'recommendation', '国家层面的规模是明确的：2025 年到 2027 年底，「聚焦高精尖产业与急需行业、就业重点群体等开展补贴性培训 3000 万人次以上」。资金来源被打通为一揽子：就业补助资金、失业保险基金、行业发展资金、东西部协作资金、企业职工教育经费等。补贴高低按职业（工种）的急需紧缺程度和培训成本来定，不同工种不一样。对企业还要求「按规定足额提取和使用职工教育经费，确保 60% 以上用于一线职工教育和培训」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-10', 'concept_archive_s23-10', 'recommendation', '给美国 702 个职业逐个估「这活多大概率能交给计算机做」（可计算化概率评估），结果是约 47% 的就业岗位处于高风险区间。模型里决定风险高低的，是三处机器目前迈不过去的坎，作者叫它「工程瓶颈」。一是感知与操作，包括手指灵巧度、手部灵巧度、在狭窄空间和别扭姿势下作业。二是创造性智能（想出新东西的能力）。三是社会智能（跟人打交道的能力）。所以环境非标准、需要手上功夫和临场判断的活，被替代的概率一贯更低，不是个别职业的偶然。流程固定、以信息处理为主的岗位风险最高', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s23-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-11', 'concept_archive_s23-11', 'recommendation', '国家正在推「新八级工」职业技能等级制度。文件明确要求把等级和薪酬挂钩，原话是「强化技能导向的薪酬分配制度……指导企业实行岗位薪酬与岗位价值、技能等级双挂钩的分配办法」。各地要「加大高级工以上评聘力度和批次」。符合条件的企业可以自己给职工做技能等级评价。对表现突出的职工，「可打破工作年限、等级、资历等条件，直接认定相应职业技能等级」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s23-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-12', 'concept_archive_s23-12', 'recommendation', '补贴额度本身就是官方对「哪些工种缺人」的定价。政策要求「健全根据职业（工种）急需紧缺程度、培训成本等情况确定的差异化补贴机制」，各地据此确定本地的补贴性职业技能培训项目范围。所以同一个工种在不同城市的补贴额度差多少，直接反映了当地的紧缺程度', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s23-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-13', 'concept_archive_s23-13', 'recommendation', '政策口径与此一致：支持「民办培训机构开展市场化的高质量职业技能培训项目和能短期实现就业的『短平快』式职业技能培训项目」。同时推动职业院校「聚焦就业市场急需知识和技能……开设微专业和职业能力培训课程」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s23-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-14', 'concept_archive_s23-14', 'recommendation', '222 项独立研究、48478 名学生的荟萃分析：课堂测验让学生的学业成绩提高，效应量属于中等（g = 0.499）。效果大小受几个条件影响：对照组用的是什么学法、测验形式和最终考试是否一致、材料是否匹配、有没有给纠正性反馈、测验重复了几次、在哪里什么时候测、干预持续多久、用的是什么实验设计。另一份逐一评估十种常用学习方法的综述，把「练习性测验」和「分散练习」评为最高一档（high utility），理由是它们对不同年龄、不同能力的学习者都有效，在多种考核形式和真实教育场景里都被验证过。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-15', 'concept_archive_s23-15', 'recommendation', '一份汇总了 184 篇文章、317 个实验、839 次分散练习效果评估的荟萃分析。它比较了两件事：连着学完和分开几次学（间隔效应），以及间隔短和间隔长（延迟效应）。结论是复习间隔和「要记到多久之后」共同决定最终测验的保持率：要保持的时间越长，能带来最佳保持率的复习间隔也越长。另一份逐一评估十种常用学习方法的综述，把分散练习评为最高一档（high utility）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-16', 'concept_archive_s23-16', 'recommendation', '一份评估十种常用学习方法的综述，按「效果能不能跨学习条件、跨学生特征、跨材料、跨考核形式推广」给评级。评为最高一档的是练习性测验和分散练习。评为中等一档的是精细提问、自我解释、交错练习。评为最低一档的五种是：写摘要、划重点（或者画线）、关键词记忆法、为课文配图想象、反复阅读。综述写明：多数学生都说自己在用反复阅读和划重点，但这两种并不能稳定提高成绩，应当换成别的方法，比如用练习性测验代替反复阅读。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-17', 'concept_archive_s23-17', 'recommendation', '一份纳入 59 项研究、238 个效应量、158 个样本的多层荟萃分析。交错练习相对于分块练习的总体效应属于中等（Hedges'' g = 0.42）。按材料分：绘画类最好（g = 0.67），其他视觉材料也较好；数学任务的效应较小（g = 0.34）；说明性文本和味觉材料的总体效应不显著；词汇类反而是分块练习更好（g = −0.39）。回归分析显示：类别之间越相似、同一类别内部越不相似、材料越复杂，交错的好处越大。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-18', 'concept_archive_s23-18', 'recommendation', '一份受托评估学习风格证据的综述指出：要证明「按学习风格施教」有效，必须先按风格给学生分组，再把每组学生随机分配到不同教法，最后用同一份测验考。有效的判据是出现一种特定的交互作用：对一种风格最有效的教法，对另一种风格不是最有效的。综述的结论是：几乎没有发现这种交互作用；关于学习风格的文献虽然很多，但用了合格实验设计的研究极少，其中几项的结果还直接和「匹配假说」相反。作者据此认为，现有证据不足以支持把学习风格测评用进教育实践。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-19', 'concept_archive_s23-19', 'recommendation', '一项荟萃分析汇总了 40 多年的研究，含 67 篇已发表和未发表的文章、122 个实验、192 个迁移效应量，总人数 10382 人。和「再看一遍但不考」的对照相比，练习性测验带来的学习确实能迁移到别的情境，效应量 d=0.40（95% CI 0.31 到 0.50）。迁移最强的几种情况是：换一种题型考、考应用题和推理题、医学诊断类的问题、考意思相近的线索词。迁移最弱的几种是：把刺激和反应对调、初学时见过但没被考过的材料、例题类问题。调节因素中，练时和考时的作答形式是否一致、有没有做过带详细反馈的提取练习、以及初次测验答对没有，都强烈影响会不会出现正向迁移。作者还用两种方法校正了发表偏倚，调节因素的效应量受影响很小，但截距估计被明显压低：上面这些条件一个都不具备时，常常看不到正向迁移', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-20', 'concept_archive_s23-20', 'recommendation', '全国共设 27 个职称系列，比如经济、工程、卫生、出版。职称分高级、中级、初级三层。人社部令第 40 号适用于企业、事业单位、社会团体、个体经济组织，也适用于自由职业者。申报人一般要逐级申报。你所在单位要审核材料，并在单位内公示，公示期不少于 5 个工作日。民营企业和自由职业者，可以由人事代理机构等替你审核、公示、推荐。各地要在科技园区、高新区等地设职称申报受理服务点，也可以通过人才中介服务机构、行业协会商会、学会受理申报。符合条件的自由职业者，按属地参加当地人社部门组织的评审。能在网上核验的材料，不得要求你另外开证明。材料不齐的，评审方要一次性告诉你缺哪些。民营企业的人一般在劳动关系所在地申报。被派到外地连续干满一年的，可以在派驻地申报。离退休人员不能申报。事业单位工作人员受记过以上处分的，处分期间不能申报（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-21', 'concept_archive_s23-21', 'recommendation', '2016 年的改革意见规定，初级、中级职称实行全国统一考试的专业，不再进行相应的评审或认定。在职称和职业资格密切相关的领域，取得职业资格就可以认定具备相应职称，还可以作为申报高一级的条件。以会计为例。助理会计师和会计师实行全国统一考试。高级会计师考试和评审结合，正高级一般只评审。报考条件如下。助理会计师：高中毕业以上学历，含中专、职高、技校。会计师：博士学位；或硕士学位、干会计满 1 年；或第二学士学位、研究生班毕业、干满 2 年；或本科、干满 4 年；或大专、干满 5 年。有会计硕士、会计博士专业学位的，考会计师可以免考《财务管理》（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-21"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-22', 'concept_archive_s23-22', 'recommendation', '人社部令第 40 号规定，提供虚假材料、剽窃他人作品和学术成果，或者用其他不正当手段取得职称的，撤销职称。同时记入职称评审诚信档案库，纳入全国信用信息共享平台，记录期限 3 年。2024 年的监管办法点名了申报人的几类违规：虚假承诺和伪造信息，论文造假代写，业绩造假，说情打招呼。申报时要签个人承诺书，承诺不实的，3 年内不得申报。人社部门会同公安、网信、市场监管查处中介的虚假网站、虚假宣传、合同陷阱、假冒评审和假证。情节严重涉嫌犯罪的，移送有关机关处理（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s23-22"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s23-23', 'concept_archive_s23-23', 'recommendation', '人社部令第 40 号第二条：职称评审结果是专业技术人才聘用、考核、晋升等的重要依据。2016 年的改革意见规定，全面实行岗位管理的事业单位，一般在岗位结构比例内开展职称评审。不实行岗位管理的单位，以及通用性强的系列和新兴职业，可以评聘分开。专业技术人才跨地区、跨单位流动时，职称按管理权限重新评审或者确认，国家另有规定的除外（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s23-23"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-1', 'concept_archive_s24-1', 'recommendation', '经基层逐级转诊的参保患者，在上级医院的住院起付线可以连续计算。起付线就是每次住院自己先掏、掏够了医保才开始报的那一段。连续计算的意思是前后两家医院合起来只算一次，不用重新掏一遍。由上级医院下转回基层的住院患者，同一疾病周期内不再另设起付线', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-2', 'concept_archive_s24-2', 'recommendation', '文件要求各地拉开不同等级医疗机构的住院报销水平，原则上逐级差 10 个百分点左右。按这个差距，同一笔住院费每往上跑一级医院，自己多掏的大约是这笔可报销费用的 10%。比如 1 万元可报销的住院费，报销比例从 80% 降到 70%，自己掏的从 2000 元变成 3000 元。多掏的 1000 元是总费用的一成，但比原来自己掏的多了一半。各地实际比例不同，起付线和封顶线也会让差额变化，这里只是按文件的 10 个百分点算的示意。年度新增医保基金也向基层倾斜', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-3', 'concept_archive_s24-3', 'recommendation', '紧密型医联体的牵头医院，要为基层预留一定比例的号源和床位，并及时接诊经基层转诊的患者。紧密型医联体就是几家医院和社区卫生机构绑在一起协作的一组机构。所以从社区转上去有单独的号和床，不和大厅里抢号的人挤在一起。医疗机构要设转诊中心或指定固定部门，到 2027 年实现全覆盖', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-4', 'concept_archive_s24-4', 'recommendation', '跨统筹地区、跨省异地就医的必要性，原则上由二、三级医院副主任医师及以上职称人员评估。跨统筹地区就是跨出自己的医保参保地。去不去外地看，要由够级别的医生说了算。跨省临时外出就医人员的报销水平，与参保地同级别机构保持合理差异。在外地看同样的病，报回来的钱会比在家少一截', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-5', 'concept_archive_s24-5', 'recommendation', '法规明确把查阅、复制病历列为患者的权利。范围覆盖门诊病历、住院志、化验单、医学影像、手术及麻醉记录、病理资料、医疗费用等全部资料。换医院、找第二个医生再看一遍、报商业保险、真起了纠纷，靠的都是这些', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-6', 'concept_archive_s24-6', 'recommendation', '条例规定「发生医疗纠纷需要封存、启封病历资料的，应当在医患双方在场的情况下进行」。封存的可以是原件，也可以是复制件，由医疗机构保管。病历尚未完成需要封存的，对已完成部分先行封存，后续完成后再封存。医疗机构应当对封存的病历开列封存清单，由医患双方签字或者盖章，各执一份。疑似输液、输血、注射、用药等引起不良后果的，医患双方应当共同对现场实物进行封存、启封。需要检验的，应当由双方共同委托有检验资格的机构。双方无法共同委托的，由医疗机构所在地县级人民政府卫生主管部门指定。疑似输血引起不良后果、需要封存血液的，医疗机构应当通知血站派员到场。另有一条硬约束：「任何单位和个人不得篡改、伪造、隐匿、毁灭或者抢夺病历资料。」封存后纠纷已解决，或者满 3 年未再提出解决要求的，医疗机构可以自行启封（全国，2018 年 10 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-7', 'concept_archive_s24-7', 'recommendation', '国家卫生健康委 2024 年版急诊医学质控指标规定，急诊预检分诊要「按病情危重程度将患者分为四级」。「I 级为急危患者，需要立即得到救治」。「II 级为急重患者，往往评估与救治同时进行」。「III 级为急症患者，需要短时间内得到诊治」。「IV 级为非急症患者或亚急症患者，在普通诊疗区顺序就诊」。预检分诊就是进急诊先由专人评一遍病情轻重，定下看病顺序。北京市的执行标准给出了各级的响应要求。1 级「立即进行评估和救治，安排患者进入复苏室或抢救室」。2 级「立即监护生命体征，10 分钟内得到救治，安排患者进入抢救室」。3 级「先于 4 级患者优先诊治，安排患者在普通诊疗区候诊；若候诊时间大于 30 分钟，需再次评估」。4 级「顺序就诊，除非病情变化，否则候诊时间较长；若候诊时间大于 4 小时，可再次评估」。分诊要「坚持急危重症优先就诊原则」，急诊科入口显著位置应设预检分诊区域（四级标准为全国口径，响应时间为北京市标准）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-8', 'concept_archive_s24-8', 'recommendation', '疾病应急救助制度的救助对象是「在中国境内发生急重危伤病、需要急救但身份不明确或无力支付相应费用的患者」。基金支付两类费用：「无法查明身份患者所发生的急救费用」，和「身份明确但无力缴费的患者所拖欠的急救费用」。文件还写明「各级各类医疗机构及其工作人员必须及时、有效地对急重危伤患者施救，不得以任何理由拒绝、推诿或拖延救治」。院前急救也有规定：全国院前医疗急救呼叫号码为「120」。急救中心（站）「不得因指挥调度原因拒绝、推诿或者延误院前医疗急救服务」，也「不得因费用问题拒绝或者延误院前医疗急救服务」。转运遵循「就近、就急、满足专业需要、兼顾患者意愿的原则」（全国，2013 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-9', 'concept_archive_s24-9', 'recommendation', '《人体损伤致残程度分级》规定鉴定时机「应在原发性损伤及其与之确有关联的并发症治疗终结或者临床治疗效果稳定后进行鉴定」。标准「将人体损伤致残程度划分为 10 个等级，从一级（人体致残率 100%）到十级（人体致残率 10%），每级致残率相差 10%」。判断依据是「人体组织器官结构破坏、功能障碍及其对医疗、护理的依赖程度，适当考虑由于残疾引起的社会交往和心理因素影响」。十级里与骨折有关的条款包括这么几条。一是「一椎体压缩性骨折（压缩程度达 1/3）或者粉碎性骨折」。二是「骨盆两处以上骨折或者粉碎性骨折，畸形愈合」。三是「四肢任一大关节（踝关节除外）功能丧失 25% 以上」。同一部位和性质的残疾不得重复计算。两处以上致残的，应分别写明等级（全国，2017 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-10', 'concept_archive_s24-10', 'recommendation', '残疾人证「是认定残疾人及其残疾类别、残疾等级的合法凭证，是残疾人依法享有国家和地方政府优惠政策的重要依据」。评定标准是国家标准《残疾人残疾分类和分级》（GB/T 26341-2010）。办证坚持申领自愿、属地管理。视力、听力、言语、肢体、智力、精神及多重七类残疾人均可申领，残疾等级为一至四级。县级残联负责申办受理与核发，依据省级指定的医院或专业机构作出的评定结论。评定结论符合标准的，在村（社区）公示五个工作日，县级残联「在十个工作日内审核完毕」。「办理残疾人证不收取工本费」。评定与照片费用「原则上由申请人个人自理；有条件的地方可由当地财政予以补贴，对特殊困难的申请人应协调有关部门予以减免」。证的有效期十年，期满免费换领。残疾类别或等级发生变化的，可申请重新评定。对评定结论有异议的，可在十个工作日内到地市级残联申请重新评定。仍有异议的，由省级残疾评定专家委员会作出最终结论（全国，2018 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-11', 'concept_archive_s24-11', 'recommendation', '《医疗机构工作人员廉洁从业九项准则》（国卫医发〔2021〕41 号）第七项：「维护诊疗秩序，不破坏就医公平。坚持平等原则，共建公平就医环境。严禁利用号源、床源、紧缺药品耗材等医疗资源或者检查、手术等诊疗安排收受好处、损公肥私」。第八项：「共建和谐关系，不收受患方『红包』。恪守医德、严格自律」。同一项还写明「严禁索取或者收受患者及其亲友的礼品、礼金、消费卡和有价证券、股权、其他金融产品等财物」。患方出钱的饭局和娱乐也一样：「严禁参加其安排、组织或者支付费用的宴请或者旅游、健身、娱乐等活动安排」。文件同时要求医疗机构落实主体责任、开展督查、「坚决查处违规行为」。满意度评价被写进了三级公立医院的绩效考核。依据是《国务院办公厅关于加强三级公立医院绩效考核工作的意见》（国办发〔2019〕4 号）。文件说：「三级公立医院绩效考核指标体系由医疗质量、运营效率、持续发展、满意度评价等 4 个方面的指标构成」。文件还写明：「医院满意度由患者满意度和医务人员满意度两部分组成……」。后面接着说，要「通过门诊患者、住院患者和医务人员满意度评价，衡量患者获得感及医务人员积极性」。这套评价还有全国统一的平台：「国家建立公立医院满意度管理制度……」。时间表是：「2019 年 3 月底前，全国三级公立医院全部纳入国家卫生健康委满意度调查平台。各地要应用国家卫生健康委满意度调查平台，将调查结果纳入三级公立医院绩效考核」。医院还必须管投诉。依据是《医疗机构投诉管理办法》（国家卫生健康委令第 3 号，2019 年施行）第二条。投诉管理是指患者就医疗服务行为、医疗管理、医疗质量安全等方面「提出意见、建议或者投诉请求」。医院要负责调查、处理和反馈。「二级以上医疗机构应当设置医患关系办公室或者指定部门（以下统称投诉管理部门）统一承担投诉管理工作」。投诉管理部门的职责包括「统一受理投诉，调查、核实投诉事项，提出处理意见，及时答复患者」。医疗机构「应当鼓励工作人员主动收集患者对医疗服务、医疗质量安全等方面的意见和建议」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s24-12', 'concept_archive_s24-12', 'recommendation', '国家医保局 2024 年 1 月的公告说，常规单颗牙种植费用由三部分构成。一是医疗服务费，采取包干的方式。包干范围包括「种植全过程的诊查费、生化检验和影像检查费、种植体植入费、牙冠置入费、扫描设计建模费，不包括拔牙、牙周洁治、根管治疗、植骨、软组织移植」。「各地三级公立医院单颗常规种植牙的医疗服务收费原则上不超过4500元」，经济发达地区按 2022 年的专项治理通知最多可以放宽 20%。二是种植体，2023 年 1 月全国集中采购，「中选价格区间为548元—1855元，均价900余元」。牵头的四川省医保局公布，进口的高价品牌从采购中位价 5000 元降到 1850 元左右，用量最大的几个品牌从 1500 元左右降到 770 元左右。三是牙冠，「价格区间为100元—656元，均价300余元」。国家医保局 2023 年下半年的新闻发布会说，各地治理措施在 4 月底 5 月初全部落地，「种植牙整体费用从平均1.5万元降至6000－7000元左右」。医保报不报：劳动保障部等部门 1999 年的文件把「义齿」（假牙）和「非功能性整容、矫形手术」列为基本医保不予支付。国家医保局 2019 年答复政协提案时说，「美容类（包括牙缺失修复、矫正等）的诊疗项目,不纳入医保基金支付范围。但是对于牙科治疗类的诊疗项目，国家层面没有排除，各地也普遍纳入了医保支付范围」（全国，截至 2026 年 10 月）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s24-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-1', 'concept_archive_s25-1', 'recommendation', '户口登记条例第八条第二款：「公民因意外事故致死或者死因不明，户主、发现人应当立即报告当地公安派出所或者乡、镇人民委员会」。意思是：出了意外，或者不知道人是怎么没的，户主和发现的人要马上报派出所或者乡镇政府。殡葬管理条例第二十三条：「自然人正常死亡的，医疗卫生机构应当及时出具死亡证明。涉及公安机关依法处置且未经医疗卫生机构救治的非正常死亡案（事）件的逝者，由公安机关出具死亡证明」。意思是：正常病故的，由给他看病的医疗机构开死亡证明。没经医院救治、又归公安处理的那种，由公安开。非正常死亡的死亡证明只有公安能开。现场被动过，就既说不清也不好开。后面火化、销户、保险理赔，全都卡在这一张纸上', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-2', 'concept_archive_s25-2', 'recommendation', '《人口死亡信息登记管理规范（试行）》说：在医疗卫生机构内死亡的，由「负责救治的医疗卫生机构签发」，在医院或者卫生院走的，找管救治的那一家开。在家中或其他场所正常死亡的，「由本辖区社区卫生服务机构或乡镇（街道）卫生院签发」，找住处这一片的社区卫生服务中心、乡镇或街道卫生院开。公安司法机构判断为非正常死亡的，由公安司法部门按现行规定及程序办理。2026 年五部门通知说：《死亡证明》「纸质版与电子证照具有同等法律效力」，电子的和纸质的一样管用。死因已明确的正常死亡，要在死亡发生后一日内签发。证明丢了，可以向原签发机构申请补发一次。基本信息有误的，可以凭材料申请重新签发一次', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-3', 'concept_archive_s25-3', 'recommendation', '殡葬管理条例第二十五条：「遗体接运、存放、防腐、整容、火化服务，由殡仪馆专门负责提供」。这几件事别家做不了。第二十四条：「医疗卫生机构的太平间不得外包，不得开展殡仪服务，可以为遗体暂时停放提供便利服务」。医院太平间只能临时放一放，不能承办丧事。第二十七条：「殡仪馆存放遗体一般不超过 3 日，需要延期存放的，丧属或者遗体移交方应当在殡仪馆办理延期存放手续」。要多放几天，就去殡仪馆办延期。第二十八条：「殡仪馆应当凭死亡证明和火化确认书火化遗体，并出具火化证明」。两样材料缺一不可，火化完会给你一张火化证明。第二十九条：「在实行火葬的地区，遗体应当就地、就近在殡仪馆火化」，要在人去世的地方就近找殡仪馆火化', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-4', 'concept_archive_s25-4', 'recommendation', '尸检的时限写在医疗纠纷预防和处理条例第二十六条。原文是：「患者死亡，医患双方对死因有异议的，应当在患者死亡后 48 小时内进行尸检；具备尸体冻存条件的，可以延长至 7 日」。所以想查清死因，要在人去世后 48 小时内做尸检，医院有冷冻条件的最多放宽到 7 天。同一条还写着：「尸检应当经死者近亲属同意并签字，拒绝签字的，视为死者近亲属不同意进行尸检」。家属不签字，就当作不同意。还写着：「不同意或者拖延尸检，超过规定时间，影响对死因判定的，由不同意或者拖延的一方承担责任」。谁不同意、谁拖过了时间，后面查不清死因的责任就算谁的。第二十四条：封存、启封病历资料「应当在医患双方在场的情况下进行」。病历装封和拆封，你和医院都得在场', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-5', 'concept_archive_s25-5', 'recommendation', '户口登记条例第八条第一款：「公民死亡，城市在葬前，农村在一个月以内，由户主、亲属、抚养人或者邻居向户口登记机关申报死亡登记，注销户口。公民如果在暂住地死亡，由暂住地户口登记机关通知常住地户口登记机关注销户口」。意思是：城里在下葬前办，农村在一个月内办。户主、亲属、抚养人或者邻居都可以去户口登记机关（派出所）报死亡、销户口。人是在外地暂住时走的，由暂住地派出所通知户籍所在地派出所销户', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-6', 'concept_archive_s25-6', 'recommendation', '遗体接运、遗体存放、遗体告别、遗体火化、骨灰寄存、生态安葬，都在国家的基础项目清单里。政府举办的殡葬服务机构提供的骨灰格位安葬，也在清单里。这些项目的收费标准依法制定，价钱按规定来定，不由殡仪馆自己说了算。非基础项目清单由设区的市级以上民政部门（地级市及以上的民政部门）确定', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-7', 'concept_archive_s25-7', 'recommendation', '条例列了五类价格违法行为，下面说其中四类。不挂价目表、收比标价更多的钱，属于不明码标价或者在标价之外加价。不买这个就不给办那个，属于捆绑或者附加不合理条件强制销售。硬塞给你另一家的收费服务，属于强制或者变相强制接受第三方有偿服务。换个名目多收钱，属于变相提高收费标准。另外还禁止「分解项目、扩大范围收费等形式变相提高收费标准」。把一项服务拆成好几项分别收费，或者把收费范围往外扩，都在禁止之列', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-8', 'concept_archive_s25-8', 'recommendation', '没备案的中介，不在民政部门管的殡葬服务信息系统里。以欺骗手段违规收费、诱导大操大办、强迫接受服务、倒卖逝者信息的，会被依法处置，还会在系统中标注、向社会公开，谁都能看到', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-9', 'concept_archive_s25-9', 'recommendation', '住房公积金账户余额（他公积金账户里还剩的钱），继承人、受遗赠人可以提取。受遗赠人是指写进遗嘱、要把东西留给他的那个人。因工死亡的，另有三笔钱：丧葬补助金、供养亲属抚恤金、一次性工亡补助金。养老保险个人账户里剩的钱，社会保险法写明可以继承。参加职工养老保险的人因病或者非因工死亡，家属还能领丧葬补助金和抚恤金，合称遗属待遇。企业职工的标准全国统一公式。丧葬补助金是本省上一年城镇居民月人均可支配收入的 2 倍。抚恤金以这个月收入为基数，按缴费年限发 3 到 24 个月：不满 5 年 3 个月，5 到 10 年 6 个月，10 到 15 年 9 个月，15 年以上每多 1 年加 1 个月，最多 24 个月。已经退休的，每领 1 年养老金减 1 个月，最少 9 个月', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s25-10', 'concept_archive_s25-10', 'recommendation', '法律明写：自然人死亡的，近亲属为了自身合法、正当利益，可以对死者的相关个人信息行使查阅、复制、更正、删除等权利。近亲属可以要求平台把他的信息拿出来看、复制一份、改错、删掉', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s25-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-1', 'concept_archive_s26-1', 'recommendation', '法规说的支付业务，是「根据收款人或者付款人提交的电子支付指令转移货币资金」。说白了就是按别人的指令替人转钱。要做这门生意，「应当经中国人民银行批准，取得支付业务许可」。注册资本最低 1 亿元，而且是实缴货币资本，这 1 亿元要真金白银打进公司账户。「未经依法批准，擅自设立非银行支付机构、从事或者变相从事支付业务的，由中国人民银行依法予以取缔，没收违法所得」。没批准就干这件事的，直接关停，挣的钱收走。违法所得 50 万元以上的，再罚违法所得的 1 到 5 倍。没有违法所得、或者不足 50 万元的，罚 50 万到 200 万元。法定代表人和直接负责的人另外罚 10 万到 50 万元。刑法还把「非法从事资金支付结算业务」算作非法经营。情节严重的判 5 年以下，特别严重的判 5 年以上。什么算「情节严重」，最高人民法院和最高人民检察院的解释里划了线。这条线是非法经营数额 500 万元以上，或者违法所得 10 万元以上（全国，2024 年 5 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-2', 'concept_archive_s26-2', 'recommendation', '法规原话是「国家对经营性互联网信息服务实行许可制度；对非经营性互联网信息服务实行备案制度。未取得许可或者未履行备案手续的，不得从事互联网信息服务」。收钱的要先拿许可证，不收钱的要先备案，两样都没有就不能开站。什么叫经营性？法规说是「通过互联网向上网用户有偿提供信息或者网页制作等服务活动」。简单说就是向用户收钱。撮合交易的那一类叫在线数据处理与交易处理业务，业内简称 EDI。法规给它的定义是「利用各种与公用通信网或互联网相连的数据与交易/事务处理应用平台，通过公用通信网或互联网为用户提供在线数据处理和交易/事务处理的业务」。它还「包括交易处理业务、电子数据交换业务和网络/电子设备数据处理业务」。说的就是网站替用户在线处理数据，或者替买卖双方撮合和处理交易。没办证就经营，或者超范围经营，都要没收违法所得，再罚违法所得的 3 到 5 倍。超范围经营就是办了证，干的事却超出证上写的范围。没有违法所得、或者违法所得不足 5 万元的，罚 10 万到 100 万元。情节严重的，责令关闭网站（全国）。收钱不等于一定要办证。广东省通信管理局 2025 年 10 月发的问答说，按工信部要求，下面三种不用办这张证。第一种，企业在自己的网站、App 上「以自营方式直接销售自身或其它企业的商品或服务」，而且没有别的单位或个人入驻开店。第二种，企业在自己的网站、App 上只发自己的信息，不给别人提供发布信息的平台。第三种，企业只靠微信、支付宝这些平台上的小程序、公众号、视频号、网店做生意，「且无其他独立运营平台」。反过来，只要让别人入驻开店、或者让用户在你这里发信息，就不在这三种里面', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-3', 'concept_archive_s26-3', 'recommendation', '做网络表演的单位要先办证。法规原话是「应当根据《互联网文化管理暂行规定》，向省级文化行政部门申请取得《网络文化经营许可证》，许可证的经营范围应当明确包括网络表演」。打游戏给人看、给人讲解的也按这一套管，法规原话是「参照本办法进行管理」。所有网络表演的视频资料，「保存时间不得少于60日」，播过的视频你要自己留满 60 天。没批准就做经营性互联网文化活动的，责令停止、给予警告，再罚 3 万元以下。叫了还不停的，列入文化市场黑名单。在网上放节目是另一张证，「应当取得《信息网络传播视听节目许可证》」。申请人要「具备法人资格，为国有独资或国有控股单位」，必须是国家全资或者国家控股的单位，民营公司基本拿不到。没这张证就做的，予以警告、责令改正，可以再罚 3 万元以下。情节严重的，按广播电视管理条例处罚（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-4', 'concept_archive_s26-4', 'recommendation', '法规原话是「未经备案，不得在中华人民共和国境内从事非经营性互联网信息服务」。不向用户收钱的网站，只要放在境内，也得先备案。没备案的，责令限期改正，再罚 1 万元。拒不改正的，关闭网站。帮你把服务器接上网的那家服务商也受管：它「不得为未经备案的组织或者个人从事非经营性互联网信息服务提供互联网接入服务」。替你收钱的服务商也一样。法规说这类服务商「不得为未依法取得经营许可证或者履行非经营性互联网信息服务备案手续的单位或者个人提供接入或者代收费等服务」。意思是没证也没备案的站，正规服务商不许接。再有，机房托管和云主机在法规里叫互联网数据中心业务，宽带接入叫互联网接入服务业务，这两样本身就要许可，服务商自己先得有证。网站主页上不标备案号的，责令改正，再罚 5000 元到 5 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-5', 'concept_archive_s26-5', 'recommendation', '法律对平台有一段要求。原话是「应当要求申请进入平台销售商品或者提供服务的经营者提交其身份、地址、联系方式、行政许可等真实信息，进行核验、登记，建立登记档案，并定期核验更新」。卖家进场前要交身份、地址、联系方式和他该办的许可证。你要核一遍，登记建档，之后隔一段时间还要回头再核一次。「定期」是多久？部门规章说得更细，「至少每六个月核验更新一次」。你还要向市场监管部门报送平台内经营者的身份信息。税务那边也要报，原话是「依照税收征收管理法律、行政法规的规定，向税务部门报送平台内经营者的身份信息和与纳税有关的信息」。所以卖家是谁要报给市场监管，卖家的身份和纳税情况要报给税务。商品和服务信息、交易信息「保存时间自交易完成之日起不少于三年」，从一笔交易做完那天算起，数据至少留三年。上面任何一项没做到的，责令限期改正。逾期不改的，罚 2 万到 10 万元。情节严重的，责令停业整顿，再罚 10 万到 50 万元。涉税信息要「于季度终了的次月内」报送，每个季度结束后的下一个月里就要报掉。没按期报的，罚则一样（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-6', 'concept_archive_s26-6', 'recommendation', '法规说平台「应当履行信息内容管理主体责任」，用户发的东西由平台自己负责管。具体要「健全用户注册、账号管理、信息发布审核、跟帖评论审核、版面页面生态管理、实时巡查、应急处置和网络谣言、黑色产业链信息处置等制度」。从注册、发帖、评论，到日常巡查和出事处置，每一环都要有写下来的规矩。还「应当在显著位置设置便捷的投诉举报入口」，举报按钮要放在用户一眼看得见、点得到的地方。发现违法信息的，「应当依法立即采取处置措施，保存有关记录，并向有关主管部门报告」。网络安全法说得更具体。原话是「发现法律、行政法规禁止发布或者传输的信息的，应当立即停止传输该信息，采取消除等处置措施，防止信息扩散，保存有关记录，并向有关主管部门报告」。没做到的，责令改正、给予警告、予以通报，可以再罚 5 万到 50 万元。拒不改正、或者情节严重的，罚 50 万到 200 万元，还可能被责令停业整顿、关闭网站或者应用程序、吊销许可证或者营业执照。直接负责的人另外罚 5 万到 20 万元（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-7', 'concept_archive_s26-7', 'recommendation', '法律原话是「网络运营者为用户办理网络接入、域名注册服务，办理固定电话、移动电话等入网手续，或者为用户提供信息发布、即时通讯等服务，在与用户签订协议或者确认提供服务时，应当要求用户提供真实身份信息。用户不提供真实身份信息的，网络运营者不得为其提供相关服务」。没要实名的，或者用户没给真实身份、你还照样让他用的，责令改正。拒不改正、或者情节严重的，罚 5 万到 50 万元，还可能被责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销许可证或者营业执照。直接负责的人另外罚 1 万到 10 万元。直播服务按「后台实名、前台自愿」的原则，做「基于移动电话号码等方式的真实身份信息认证」。意思是平台后台存着用户的真名，页面上显示什么昵称由用户自己定，核验靠手机号一类方式。直播带货要求更严，是「基于身份证件信息、统一社会信用代码等真实身份信息认证」。统一社会信用代码就是营业执照上那串号（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-8', 'concept_archive_s26-8', 'recommendation', '法律原话是「网络直播服务提供者不得为未满十六周岁的未成年人提供网络直播发布者账号注册服务；为年满十六周岁的未成年人提供网络直播发布者账号注册服务时，应当对其身份信息进行认证，并征得其父母或者其他监护人同意」。条例还要求「建立网络直播发布者真实身份信息动态核验机制」，开播的人的身份，你要能随时复核一遍。另外要「合理限制不同年龄阶段未成年人在使用其服务中的单次消费数额和单日累计消费数额」，按年龄给未成年人设单笔和单日的花钱上限。打赏现在分三档：「不得向八周岁以下的未成年人提供打赏服务。向八周岁至十六周岁的未成年人提供打赏服务，应征得其监护人同意。向十六周岁以上的未成年人提供打赏服务，应征得其监护人同意或核验其收入证明材料」。还有一条：限制民事行为能力人没经监护人同意就打赏的，监护人来要钱，法院应予支持，钱能要回去。限制民事行为能力人指法律上还不能完全自己做主的未成年人（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-9', 'concept_archive_s26-9', 'recommendation', '权利人「有权通知电子商务平台经营者采取删除、屏蔽、断开链接、终止交易和服务等必要措施。通知应当包括构成侵权的初步证据」。权利人就是商标、著作权、专利这些权利的主人。光发一句话不算，要附上初步证据。平台接到通知后，「应当及时采取必要措施，并将该通知转送平台内经营者；未及时采取必要措施的，对损害的扩大部分与平台内经营者承担连带责任」。你拖着不处理，多出来的那部分损失，你要和卖家一起赔。卖家申辩之后，平台「在转送声明到达知识产权权利人后十五日内，未收到权利人已经投诉或者起诉通知的，应当及时终止所采取的措施」。意思是把卖家的申辩转给权利人，等 15 天。对方既没投诉也没起诉，就把删掉、下架的恢复回去。平台知道或者应当知道有侵权却不处理的，与侵权人承担连带责任。知识产权部门还可以责令你限期改正，逾期不改的罚 5 万到 50 万元，情节严重的罚 50 万到 200 万元。反过来，「恶意发出错误通知，造成平台内经营者损失的，加倍承担赔偿责任」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-10', 'concept_archive_s26-10', 'recommendation', '把境内用户的信息交给境外的公司、或者存到境外的机器上，法律上叫向境外提供个人信息，「应当具备」四项条件之一。一是通过网信部门组织的安全评估。二是经专业机构做个人信息保护认证。三是按网信部门制定的标准合同和境外接收方签约。四是法律、行政法规规定的其他条件。同时你要告诉用户这几样：境外接收方的名称、联系方式、处理目的、处理方式、个人信息的种类，以及他怎么行使自己的权利。而且要「取得个人的单独同意」，专门就这件事问用户一次。具体门槛按累计人数分档。普通企业在法规里叫关键信息基础设施运营者以外的数据处理者。这类企业有一条免办的线，原话是「自当年1月1日起累计向境外提供不满10万人个人信息（不含敏感个人信息）的」。到不了这条线，申报评估、订立标准合同、做认证这三样都免了。10 万人以上不满 100 万人的，应当订立标准合同或者通过认证。100 万人以上的，或者敏感个人信息达到 1 万人以上的，应当申报安全评估（全国，2024 年 3 月起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s26-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s26-11', 'concept_archive_s26-11', 'recommendation', '三档的差别不在价格，在出事那天你手上有什么。主流云厂商有备案通道，资质是公开的，出故障有公告，合同里有赔偿条款，出了问题能找到人。小服务商价格能低一半，但它超售、跑路、被上游封掉的时候，你没有申诉对象，所以谈价之前先去工信部系统查它有没有增值电信业务经营许可。独立服务器托管只有在两个条件都成立时才合算：带宽或者硬件成本明显更便宜，并且你自己有人做运维。怎么选：没有用户数据的静态站，用最便宜的 VPS 就够。有用户注册和交易的，选能弹性扩容、能快照备份的云主机，备份至少放在两个地方', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s26-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-1', 'concept_archive_s27-1', 'recommendation', 'Cochrane 系统综述把 5 项试验、6708 例分娩合起来一起算，证据质量评为高。怀孕前后每天补叶酸，胎儿神经管缺陷的风险 RR 0.31（95% CI 0.17 至 0.58，可信范围），约降低七成。已经生过神经管缺陷孩子的人，再生一个又出问题的风险 RR 0.34（95% CI 0.18 至 0.64），降到原来的三分之一左右。按人群分组来看，0.4 毫克和更高的剂量效果没有差别。单独吃叶酸和吃复合维生素，效果也没有差别', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-2', 'concept_archive_s27-2', 'recommendation', '《国家基本公共卫生服务规范（第三版）》里有孕产妇健康管理服务。辖区内的常住孕产妇可以做这些。孕早期健康检查 1 次，孕中期 2 次，孕晚期 2 次，产后访视 1 次，产后 42 天健康检查 1 次。孕 13 周前要去建册，同时做第 1 次产前检查。孕中期那两次分别在孕 16 至 20 周、孕 21 至 24 周。孕晚期那两次分别在孕 28 至 36 周、孕 37 至 40 周。地方公开的服务清单里，还包含第一次的一整套化验和产后抑郁筛查', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-3', 'concept_archive_s27-3', 'recommendation', '母婴传播就是病从母亲传给孩子。《预防艾滋病、梅毒和乙肝母婴传播工作规范（2020 年版）》有要求。在孕早期或者第一次产前检查的时候，医院要告知相关信息，并「提供适宜、规范的免费检测」，这三项检测不用自己掏钱。再根据结果提供检测后咨询或者转诊。查出阳性也不是绝路。《艾滋病防治条例》第四十四条规定，向感染艾滋病病毒的孕产妇「免费提供预防艾滋病母婴传播的治疗和咨询」。第四十三条要求提供阻断（不让病传给孩子）、治疗、产后访视、婴儿随访和检测等服务。母亲乙肝表面抗原阳性的，新生儿出生时要同时打乙肝疫苗和乙肝免疫球蛋白（见第 20 节第 2 条）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-4', 'concept_archive_s27-4', 'recommendation', '美国疾病控制与预防中心的口径：孕期吸烟会让孩子「足月出生也可能过小」「可能早产」。它会「使孕期和分娩期异常出血的风险翻倍」。它会提高唇裂、腭裂等出生缺陷的风险。它还会「损害胎儿正在发育的肺和大脑，损害可持续到儿童期」。孕期吸烟的母亲生的婴儿，以及出生后接触烟雾的婴儿，婴儿猝死综合征的风险更高。官方建议是「最好在怀孕前就戒烟，但如果已经怀孕，戒了仍然有用」「什么时候戒都不晚」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-5', 'concept_archive_s27-5', 'recommendation', '美国预防服务工作组给的是 B 级推荐：对子痫前期高危的人，在孕 12 周之后开始吃小剂量阿司匹林（81 毫克/天）来预防。子痫前期是孕期的一种高血压疾病。把多项研究合起来算，结果如下，95% CI 是可信范围。子痫前期 RR 0.85（95% CI 0.75 至 0.95，16 项研究），低约 15%。早产 RR 0.80（95% CI 0.67 至 0.95，13 项研究），低约 20%。围产期死亡 RR 0.79（95% CI 0.66 至 0.96，11 项研究），低约 21%；围产期死亡就是生产前后这段时间里的死亡。小于胎龄儿／宫内生长受限 RR 0.82（95% CI 0.68 至 0.99，16 项研究），低约 18%；说的是胎儿长得比同孕周的偏小', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-6', 'concept_archive_s27-6', 'recommendation', '美国预防服务工作组的 B 级推荐：对没有症状（自己没觉出不舒服）的孕妇，在孕 24 周及以后筛查妊娠期糖尿病。妊娠期糖尿病就是怀孕之后才出现的血糖高。只做一次筛查的，这一次要放在孕 24 周及以后。孕 24 周之前就筛查好不好，工作组的结论是现有证据不足以判断好处和坏处（I 级）。妊娠期糖尿病不管，会推高这几样的风险：巨大儿（胎儿长得过大）、难产、剖宫产、子痫前期和新生儿低血糖', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-7', 'concept_archive_s27-7', 'recommendation', '美国疾病控制与预防中心列出的孕产期紧急预警信号有这些：头痛一直不好或者越来越重、头晕或者晕过去、看东西变样、体温达到 38 ℃ 或更高；手或者脸肿得厉害、有伤害自己或者伤害孩子的念头、呼吸困难、胸痛或者心跳过快；恶心呕吐很厉害、肚子剧烈疼痛一直不缓解、孕期胎动停止或者明显减少；孕期阴道出血或者流出液体、产后阴道出血或者分泌物不正常；一条胳膊或者一条腿严重肿胀、发红或者疼痛。这些问题在产后一年内都可能发生，不是「出了月子就没事」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-8', 'concept_archive_s27-8', 'recommendation', '北京市卫生健康委员会给的处置办法：发现破水后「马上找个地方平躺下来，防止羊水流出来」「不要随意走动」，并且「立即拨打 120 急救电话」。等车的时候通知家里人带东西到医院会合。医疗机构的科普进一步说明了为什么：人站着的时候羊水流失更快，胎儿的脐带可能跟着掉出来，这叫脐带脱垂，是危及胎儿的急症。所以要躺下，把臀部垫高，可以取左侧卧位', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s27-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-9', 'concept_archive_s27-9', 'recommendation', 'Cochrane 系统综述的结论是：硬膜外镇痛在减轻产痛、提高产妇对镇痛的满意度上，比不用硬膜外的办法更有效。无痛分娩用的就是硬膜外镇痛。同一篇还说，「硬膜外镇痛对剖宫产风险和长期腰痛没有影响」。器械助产（用器械把孩子接出来）增加的现象，在 2005 年以后的研究中已经看不到。2024 年起，国家医保局的产科类医疗服务价格项目立项指南，把「分娩镇痛」「导乐分娩」「亲情陪产」单独立了项。理由正是原先没有独立的价格项目，医院提供分娩镇痛的积极性被压低', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-10', 'concept_archive_s27-10', 'recommendation', '世界卫生组织 2015 年的声明：一个人群里的剖宫产率上升到约 10% 时，孕产妇和新生儿的死亡数会下降。超过 10% 之后，没有证据显示死亡率还能进一步改善。世界卫生组织同时强调，应当尽一切努力，为有需要的产妇提供剖宫产，而不是为了凑某个特定的比率', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-11', 'concept_archive_s27-11', 'recommendation', '《社会保险法》第五十四条：用人单位已经缴纳生育保险费的，其职工享受生育保险待遇。职工没有工作的配偶，按照国家规定享受生育医疗费用待遇，所需资金从生育保险基金中支付。说白了，单位交了生育保险，职工本人能享受待遇，职工那位没工作的配偶生孩子的医疗费，也能从这笔基金里出。生育保险待遇分两块：一块是生育医疗费用，就是生孩子这件事本身的医疗费；另一块是生育津贴，就是产假期间发给你的那笔钱。第五十六条列明了能领生育津贴的三种情形：女职工生育享受产假、享受计划生育手术休假、法律法规规定的其他情形。生育津贴「按照职工所在用人单位上年度职工月平均工资计发」，算的是你所在单位去年的职工月平均工资，不是你自己的工资', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-12', 'concept_archive_s27-12', 'recommendation', '《母婴保健法》第二十三条：医疗保健机构和从事家庭接生的人员，按照国务院卫生行政部门的规定，出具统一制发的新生儿出生医学证明。这张证是后面所有事的前置条件：上户口、参保、办医保卡、入园入学都要它。而且第一次签发只能由接生的机构办。出了院再回头补办，要走另一套流程，还需要额外的证明材料', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-13', 'concept_archive_s27-13', 'recommendation', '《新生儿疾病筛查管理办法》第三条：「全国新生儿疾病筛查病种包括先天性甲状腺功能减低症、苯丙酮尿症等新生儿遗传代谢病和听力障碍。」这两类病有个共同点：早期完全看不出异常，等到症状明显的时候，智力损害已经不可逆了。而早发现早干预效果很好，办法是补充甲状腺素、喝特殊配方奶、戴助听器或者装人工耳蜗。第十条规定，筛查结果是阳性的，机构应当及时通知监护人去确诊', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-14', 'concept_archive_s27-14', 'recommendation', '中国政府网 2024 年的口径：「新生儿凭出生医学证明就可以在线上参保」，不必先落户。「新生儿出院以后就能够直接报销医药费用」。以前的做法是落了户才能参保，住院费得先全额垫付，再回头报销。参保缴费的平均办理时长，也从年初的 28.7 个工作日压减到 6.4 个工作日', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-15', 'concept_archive_s27-15', 'recommendation', '《户口登记条例》第七条：「婴儿出生后一个月以内，由户主、亲属、抚养人或者邻居向婴儿常住地户口登记机关申报出生登记。」这是法律定的时限，不是建议。落户是后面这些事的前置条件：打疫苗、入园、入学、办身份证。越往后拖，需要补的材料越多', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s27-16', 'concept_archive_s27-16', 'recommendation', '《国家基本公共卫生服务规范（第三版）》的孕产妇健康管理里，产后有 1 次产后访视和 1 次产后 42 天健康检查。地方公开的服务清单里，这一次含化验（血常规、白带常规）和 1 次产后抑郁筛查。产后一年内都可能出现严重并发症。第 7 条那张「立刻去医院」的清单里，「有伤害自己或伤害孩子的念头」「产后阴道出血或异常分泌物」「一侧肢体严重肿痛」都属于产后', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s27-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-1', 'concept_archive_s28-1', 'recommendation', '36 项研究合起来算。神经性厌食这一批人累计被跟踪了 166,642 人年（每人被跟踪的年数加总）。他们的标准化死亡比是 5.86，即死亡概率约为同龄人的 5.9 倍。每 1000 人年死亡 5.1 例，就是 1000 个人跟一年死 5.1 个。死的人里约 1/5 死于自杀。贪食症的标准化死亡比是 1.93，其他进食障碍是 1.92，即各约为同龄人的 1.9 倍。另一项研究在澳大利亚维多利亚州的 44 所中学做，跟踪 14–15 岁学生 3 年、同一批学生三年里前后查了 6 波。女生新发进食障碍 21.8/1000 人年，即 1000 个女生跟一年新出 21.8 例。严重节食的女生发病风险是不节食者的 18 倍，中度节食者是 5 倍。再校正既往节食与精神症状，把「以前就节食过」和「本来就有精神症状」的影响扣掉。扣掉之后，BMI（体重除以身高平方算出的胖瘦指标）、运动量和性别都不再预测新发进食障碍。作者结论是「在青少年中用运动而非限食控制体重，发生进食障碍的风险似乎更低」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s28-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-2', 'concept_archive_s28-2', 'recommendation', '《医疗美容服务管理办法》第二条给医疗美容下了定义。原文是「运用手术、药物、医疗器械以及其他具有创伤性或者侵入性的医学技术方法对人的容貌和人体各部位形态进行的修复与再塑」。说白了，只要破皮、进针、进到身体里，就按看病算。第八条和第二十四条要求先取得《医疗机构执业许可证》，并经登记机关核准医疗美容诊疗科目，才能开展。许可证上没写「医疗美容」这一项，就不能做。第十一条要求主诊医师（动手的那位医生）具有执业医师资格并且注册过。做美容外科的还要有 6 年以上相关专业临床工作经历，美容牙科 5 年以上，美容中医科与美容皮肤科各 3 年以上。第二十条要求动手之前书面告知适应症、禁忌症（什么情况适合做、什么情况不能做）、医疗风险和注意事项，并取得签字同意。《刑法》第三百三十六条管的是非法行医。非法行医就是没有医生执业资格的人给人打针、动刀、看病。情节严重的，处 3 年以下有期徒刑、拘役或者管制，并处或者单处罚金。严重损害就诊人身体健康的，处 3 年以上 10 年以下有期徒刑并处罚金。造成就诊人死亡的，处 10 年以上有期徒刑并处罚金', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s28-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-3', 'concept_archive_s28-3', 'recommendation', '把全世界期刊报过的病例汇总起来算。2015 年 1 月到 2018 年 9 月新增 48 例注射填充后部分或完全视力丧失。出事最多的部位是鼻部，占 56.3%。接下来是眉间 27.1%、前额 18.8%、鼻唇沟（法令纹那道沟）14.6%。81.3% 的病例填充物为透明质酸，就是玻尿酸。43.8% 出现皮肤改变。18.8% 出现中枢神经系统并发症（脑出了问题）。10 例（20.8%）视力完全恢复，8 例（16.7%）部分恢复，剩下的没恢复。作者结论为各家的处理方式差得很远，没有一种治疗被证明能持续奏效', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s28-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-4', 'concept_archive_s28-4', 'recommendation', 'SCOUT 试验招了 9,804 人。他们都是 55 岁以上、超重或肥胖，并且有心血管病或 2 型糖尿病。这些人抽签分成吃药和不吃药两组，平均治疗 3.4 年。主要终点是事先定好要数的几件坏事：非致死性心梗、非致死性卒中（中风）、心脏骤停后被救回来、心血管死亡。这几件事的发生率是 11.4% vs 10.0%。HR 1.16（95% CI 1.03–1.31，P=0.02），吃药的人出事概率高约一成六。真实值大致落在高 3% 到高 31% 之间。非致死性心梗 4.1% vs 3.2%，HR 1.28（1.04–1.57），高约三成。非致死性卒中 2.6% vs 1.9%，HR 1.36（1.04–1.77），高约三成六。心血管死亡与全因死亡未增加，全因就是各种原因加起来。抽签之后，西布曲明组平均多减重 1.7 kg。原国家食品药品监督管理局根据安全性评估认为「减肥治疗的风险大于效益」，2010 年 10 月通知停止西布曲明制剂及原料药的生产、销售、使用。西布曲明与酚酞均禁止添加于食品，保健食品也算在内', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s28-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-5', 'concept_archive_s28-5', 'recommendation', '丹麦回头翻档案，给每个用药的人配同龄对照。用药的是 2006-01-03 至 2018-03-01 健身房兴奋剂检测雄激素类固醇阳性的 545 名男性，配了 5,450 名对照。另外又用 644 名拒绝受检者和 6,440 名对照复核了一遍。结果：使用者死亡率为对照的 3 倍，HR 3.0（95% CI 1.3–7.0），真实倍数大致在 1.3 到 7 之间。每年住院或就诊次数的中位数是 0.81 次 vs 0.36 次（P&lt;0.0001）。中位数就是一半人多于、一半人少于这个数。这个 P 值说明这个差别几乎不可能是碰巧。痤疮（长痘）、男性乳房发育、勃起功能障碍各影响超过 10% 的使用者，即每十个用药的人里至少一个中招，都明显高于对照（P&lt;0.0001）。复核的那一批结果一致。《反兴奋剂条例》第七条：国家对兴奋剂目录所列禁用物质实行严格管理，任何单位和个人不得非法生产、销售、进出口。同一条例规定蛋白同化制剂、肽类激素实行处方药管理，即只能凭医生处方买，蛋白同化制剂是法规里对这类药的叫法', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s28-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-6', 'concept_archive_s28-6', 'recommendation', '《药品经营和使用质量监督管理办法》规定，药品零售企业要遵守处方药与非处方药分类管理制度。这个制度就是把药分成两类，一类必须凭医生处方买，一类可以自己买。药店要按规定凭处方销售处方药，处方保留不少于五年。药师或者其他药学技术人员不在岗时应挂牌告知，没经过他们审核不得销售处方药。处方药不得开架销售，不能摆在货架上由顾客自己拿。《药品网络销售监督管理办法》第九条规定，通过网络向个人销售处方药的，应当确保处方来源真实、可靠并实行实名制。第十条要求在每个药品展示页面下突出显示风险警示信息。通过处方审核前，不得展示说明书，也不得提供购买服务，处方没审过，页面上连买的按钮都不该给。第八条规定，国家实行特殊管理的药品不得在网络上销售。这类药包括疫苗、血液制品、麻醉药品、精神药品、医疗用毒性药品、放射性药品、药品类易制毒化学品', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s28-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-7', 'concept_archive_s28-7', 'recommendation', '研究者从 Kaiser Permanente 这家医疗集团的电子病历里跟踪了一批人。其中 2,842 名跨性别女性、2,118 名跨性别男性。平均跟踪 4.0 年与 3.6 年。每个人都按出生年、种族、就诊点和入组时间配了约 10 倍的顺性别对照，一共 48,686 名顺性别男性与 48,775 名顺性别女性。跨性别女性的静脉血栓栓塞（血管里长血块堵住）比对照多。和顺性别男性比，2 年是每 1000 人 4.1 例（95% CI 1.6–6.7）。8 年是 16.7 例（6.4–27.5）。算下来，1000 个人里两年多出 4.1 例，八年多出 16.7 例。和顺性别女性比，这两个数是 3.4（1.1–5.6）与 13.7（4.1–22.7）。缺血性卒中（血管堵住那一类中风）与心肌梗死总体各组接近。但在跟踪期内才开始激素治疗的跨性别女性中，静脉血栓与缺血性卒中的差异更明显。跨性别男性的证据不够，下不了结论。作者结论为「这些结果可能提示需要长期警惕跨性别激素中雌激素的血管副作用」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s28-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-8', 'concept_archive_s28-8', 'recommendation', '按规矩把 33 项研究找齐再合起来算。整形外科就诊者中，躯体变形障碍（把别人基本看不出的缺陷放大到影响生活）患病率 15.04%，各项研究在 2.21%–56.67% 之间。换成人数，每 100 个去做整形的人里约 15 个符合，单看各项研究则从 2 个到 57 个不等。这批人平均年龄 34.54±12.41 岁，后一个数是上下浮动的幅度，74.38% 为女性。皮肤科就诊者是 12.65%，各项研究在 4.52%–35.16% 之间，平均年龄 27.79±9.03 岁，76.09% 为女性。作者建议整形外科医师与皮肤科医师主动评估、把高风险的人认出来，并安排几个科室一起管', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s28-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s28-9', 'concept_archive_s28-9', 'recommendation', '国家药监局医疗器械技术审评中心 2022 年的《无托槽矫治器注册审查指导原则》说，这种牙套「管理类别为Ⅱ类」。它要求说明书写明「治疗过程中需在具有口腔正畸专业资质医师的指导下进行佩戴」，还要写「进食、刷牙及定期复诊的要求」。产品名称「不建议含有“隐形”等虚无、假设的概念性名称」。美国食品药品监督管理局（FDA）的说法是：「The FDA has not authorized clear aligners that are sold directly to consumers without a prescription and supervision by a dentist or orthodontist」，意思是不经牙医开方和监督、直接卖给个人的透明牙套，它一个都没批准过。FDA 还说：「In-person examination by a dentist or orthodontist can help lower the risks of uneven bite, unintended tooth movement, pain, and tooth loss」，也就是牙医当面检查能降低咬合不齐、牙齿移位、疼痛和掉牙的风险。开始戴以后定期当面复诊，才能确认牙在按计划安全移动。这两份都是监管文件，没有给出出事的比例', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s28-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-1', 'concept_archive_s29-1', 'recommendation', '1985 名急性心梗患者，拿同一个人发病前后的不同时间段自己跟自己比。其中 270 人（13.6%）在发病前 6 个月内失去过重要的人，19 人是在心梗前 1 天内失去的。重要的人去世后 24 小时内，急性心梗发作率升高 21.1 倍（95% CI 13.1–34.1，真实倍数大致在 13 到 34 之间）。此后逐日下降。换成实际人数：十年心梗风险 5% 的人里，每 1394 个刚失去亲人的多出 1 例。风险 20% 的人里，每 320 个多出 1 例。英国另一项研究，比了 30447 名 60 至 89 岁丧偶者和 83588 名条件相当的对照。丧偶后 30 天内发生心梗或中风的，丧偶的一边 50 人（0.16%）。对照的一边 67 人（0.08%）。IRR 2.20（1.52–3.15），即出事的概率约为对照的 2.2 倍。其中心梗 2.14（1.20–3.81），约 2.1 倍。中风 2.40（1.22–4.71），约 2.4 倍。30 天以后减弱。90 天内还看了两类病。一类是非心梗急性冠脉综合征（心脏供血急性出问题、但还够不上心梗的那类），IRR 2.20（1.12–4.29）。一类是肺栓塞（血块堵在肺的血管里），IRR 2.37（1.18–4.75）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-2', 'concept_archive_s29-2', 'recommendation', '瑞典全国档案跟踪 607 万多人（6,073,240 人），时间是 1991 至 2006 年。和没确诊癌症的人相比，确诊后第一周自杀相对风险 12.6（95% CI 8.6–17.8），即约 12.6 倍。真实倍数大致在 8.6 到 17.8 之间。这一周的发病率是 2.50/1000 人年，也就是 1000 人跟一年出 2.5 例。到第一年降到 3.1（2.7–3.5，0.60/1000 人年），约 3.1 倍。心血管死亡第一周 5.6（5.2–5.9，116.80/1000 人年），约 5.6 倍。前 4 周 3.3（3.1–3.4，65.81/1000 人年）。风险升高在确诊后第一年内迅速回落。越是治起来难、活下来概率低的癌种，升得越明显。把同一批患者不同时间段自己跟自己比，结论一致', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-3', 'concept_archive_s29-3', 'recommendation', '42 项研究、235 个死亡风险估计、逾 2000 万人合起来算。把年龄等条件的影响扣平之后，失业者各种原因加起来的死亡风险平均 HR 为 1.63，比在职的人高约六成。男性高于女性。对处在职业生涯早期和中期的人影响明显，晚期较小。跟踪的头 10 年风险最高，之后下降。在把抽烟喝酒这类健康行为也算进去的那部分研究里，平均 HR 低 24%，即算出来的升幅少了约四分之一', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-4', 'concept_archive_s29-4', 'recommendation', '丹麦全国档案跟踪 670 万成年人，时间是 1980 至 2014 年，合计逾 1.36 亿人年（所有人被跟踪的年数加总）。因配偶自杀而丧偶的人，5 年内新查出精神障碍的风险和一般人比，IRR 男性 1.8（95% CI 1.6–2.0），即高约八成。女性 1.7（1.6–1.8），即高约七成。和因其他死因丧偶的人相比，IRR 男性 1.7（1.5–1.9）、女性 2.0（1.9–2.2），即高七成到一倍。这批人里，自杀行为、死亡率与需要市政救助的比例也更高。肝硬化、睡眠障碍等身体上的病，风险同样升高。另有 57 项研究逐项归纳，不合并算数。因自杀丧亲，和下面四件事相关。一是伴侣自杀风险升高。二是子女自杀后父母住进精神科的风险升高。三是成年子女自杀后母亲自杀风险升高。四是父母自杀后子女抑郁风险升高。和因其他暴力死亡丧亲的人相比，因自杀丧亲的人更常说自己被人疏远、觉得羞耻', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-5', 'concept_archive_s29-5', 'recommendation', '15 项先登记再往后跟踪的研究、2,263,888 人合起来算。丧偶不足 6 个月时死亡 RR 1.41（95% CI 1.26–1.57），即同期死亡概率比没丧偶的人高约四成。6 个月以后是 1.14（1.10–1.18），降到高约一成半。男性 RR 1.23（1.18–1.28），高约两成三。女性 1.04（1.00–1.08，无统计学意义，即这点差可能只是巧合）。小于 65 岁与 65 岁以上没看出明显差别。另一项分析合并了 123 篇文献、1377 个风险估计、逾 5 亿人。把条件差异扣平后 HR 1.23（1.19–1.28），即整体高约两成三。男性还高于女性。男性 1.27（1.19–1.35），高两成七。女性 1.15（1.08–1.22），高一成五', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-6', 'concept_archive_s29-6', 'recommendation', '44,573 名门诊病人，都有动脉粥样硬化血栓的风险或者病史（血管里长斑块、容易被血块堵住的那类毛病）。他们由多国医生登记进 REACH 这个国际项目跟踪，2003 年 12 月至 2004 年 12 月入组，跟踪 4 年。其中 8,594 人（19%）独居。独居的人 4 年里各种原因加起来的死亡为 14.1%，同住的是 11.1%。心血管死亡 8.6% 对 6.8%。两项 log-rank P&lt;0.01，差别不太可能是碰巧。不同年龄段的差距不一样（交互 P=0.03）。45 至 65 岁，独居对同住的死亡为 7.7% 对 5.7%。把别的条件扣平后 HR 1.24（95% CI 1.01–1.51），即高约两成四。66 至 80 岁是 13.2% 对 12.3%，HR 1.12（1.01–1.26），高约一成。80 岁以上是 24.6% 对 28.4%，HR 0.92（0.79–1.06），反而没见升高。民政部等十部门 2022 年意见规定，要开展探访关爱服务。对象是独居、空巢、留守、失能、重残、计划生育特殊家庭等老年人。服务方式为「定期上门入户、电话视频、远程监测」。由乡镇（街道）摸底排查、村（居）民委员会协助，掌握基本信息和「接受探访关爱服务的意愿」并纳入基层网格化管理，也就是按片区分给专人盯着。到 2025 年底「确保特殊困难老年人月探访率达到 100%」，「对失能的特殊困难老年人，每月探访关爱不少于一次」。文件还倡导家庭配置智能呼叫系统、智能电水表、健康监测产品、养老监护装置，「一旦监测异常，能够及时预警，并同步向紧急联系人发送提示信息」。服务人员发现紧急问题「应当第一时间协助拨打紧急求助电话」', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s29-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-7', 'concept_archive_s29-7', 'recommendation', '丹麦 1968 至 2008 年、瑞典 1973 至 2006 年出生的全部人口都算进来。再加上芬兰 1987 至 2007 年出生者里抽出的 89.3%。合计逾 730 万人。其中 189,094 人在 18 岁前失去父母。这批孩子各种原因加起来的死亡率，比没丧亲的人高 50%（死亡率比 1.50，95% CI 1.43–1.58，即约 1.5 倍）。父母死于意外、自杀这类非自然原因的是 1.84（1.71–2.00），高约八成。死于疾病等自然原因的是 1.33（1.24–1.41），高约三成。孩子的死因和父母的死因属同一类时最高', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s29-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-8', 'concept_archive_s29-8', 'recommendation', '14 项研究合起来算，对象是亲人不是死于暴力、本人也没在精神科就诊的成年人。延长哀伤障碍患病率 9.8%（95% CI 6.8–14.0），即每 100 个丧亲的成年人里约 10 个。年龄越大比例越高。另有一项研究检验这套诊断标准准不准，找了 291 名丧亲者，在丧亲后 0–6、6–12、12–24 个月分三次访谈。诊断的核心表现是对逝者的强烈想念。还要加上这九项里的至少五项。前五项是情感麻木、震惊、觉得生活没有意义、不信任他人、因这次失去而痛苦。后四项是难以接受、认不清自己该是谁、回避现实、无法继续生活。这些表现要每天都出现，或者严重到干不了事。而且在亲人去世至少 6 个月后仍然存在，还影响着日常生活。还有一项 95 人抽签分两组的试验，做 16 次治疗、平均 19 周。针对复杂哀伤的治疗有效率 51%。普通的人际心理治疗 28%（P=0.02，差别不太可能是碰巧）。前者起效也更快。需治疗人数 4.3，即平均每治 4.3 个人就多一个好转', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-9', 'concept_archive_s29-9', 'recommendation', '61 项对照研究合起来算。给丧亲的人普遍做心理干预，在治疗刚结束时好处很小，隔一段时间再看就看不出好处了。只招收「已经明显适应不了」的丧亲者的干预，效果和治疗其他心理问题的心理治疗一样好。事先不做筛查的研究结果不好，原因是没做干预的那一组本来也会随时间自己缓过来。另有 14 项抽签分组试验合起来算：对已经出问题的人做的治疗，在治疗后和之后回访时都明显好于对照，隔一段时间效果还在变大。对还没出问题的人普遍做的预防性干预无效。还有一项研究把 205 人从丧偶前一直跟到丧偶后 6、18 个月。这项研究分出五种走向。分别是普通哀伤、长期哀伤、长期抑郁、丧亲期间反而好转、韧性（扛得住）。其中韧性型最常见，普通哀伤型相对少见', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-10', 'concept_archive_s29-10', 'recommendation', '32 项先登记再往后跟踪的研究合起来算，覆盖逾 650 万人、16 万例死亡、逾 75.5 万例离婚、11 个国家。和还在婚的人相比，分居或离婚的成年人早死风险明显升高。男性和年纪较轻的人，升得比女性和年长者明显。作者讨论了四条可能的路径。一是社会选择，本来健康或条件就不一样的人更容易走到离婚。二是资源中断，收入和保障断掉。三是健康行为改变，烟酒作息变差。四是慢性心理压力（长期紧绷）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-11', 'concept_archive_s29-11', 'recommendation', '国家卫生健康委等 25 部门 2026 年方案要求完善 12356 心理援助热线工作制度。要保证稳定运行、提升接通率。要推动建立省级 12356 信息化平台。要加强与 110 等服务热线的联动机制建设。还要建强用好 12355 青少年综合服务平台，并与 12356 联动协作。到 2030 年的目标有三条。一是 80% 以上的行政村、城市社区设心理咨询室或社会工作室并提供心理服务。二是各级公立精神专科医院、各县（区）至少有 1 所医院提供心理门诊服务。三是各省建成省级 12356 心理援助平台。心理危机干预与心理援助队伍，由精神科医师、心理治疗技师、心理咨询人员、社会工作专业人员和志愿者组成。方案还要求三类人平时就留意、早点发现。这三类人是网格员（社区里按片区负责的工作人员）、社会工作专业人员和志愿者。他们要及时发现家庭变故、失业、失学等心理危机风险（全国，2026 年 3 月印发）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s29-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-12', 'concept_archive_s29-12', 'recommendation', '避免在刚受打击、判断力最差的那段时间，做出反悔不了的财产处置。这类事包括卖房、辞职、把抚恤金或赔偿款一次性投出去、仓促再婚、替人担保。这类决定的金额通常在数万元到一套房子这个量级，收益因此定为中。官方文件同样把「家庭变故、失业、失学」列为社区要主动排查的心理危机风险，这段时间的状态本来就被当成需要外人搭把手的状态', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s29-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s29-13', 'concept_archive_s29-13', 'recommendation', '保险法第四十四条管的是以被保险人死亡为给付保险金条件的合同。从合同成立或者合同效力恢复之日起算，二年内被保险人自杀的，保险人不承担给付保险金的责任。被保险人自杀时为无民事行为能力人的，也就是法律上不能为自己行为负责的人，不在此列。这种情况下保险公司应当按照合同约定退还保险单的现金价值，即只退保单里能退的那点钱，不赔保额。寿险保额通常在数十万元级，收益因此定为大。工伤保险条例第十六条第三项规定：自残或者自杀的，不得认定为工伤或者视同工伤。第三十九条那三笔工亡待遇随之全部落空。一是丧葬补助金，按当地上一年职工月平均工资发 6 个月。二是供养亲属抚恤金。三是一次性工亡补助金，为上一年度全国城镇居民人均可支配收入的 20 倍。民法典第一千一百五十九条规定：分割遗产应当清偿被继承人依法应当缴纳的税款和债务，即先拿遗产还税和债，剩下的才分。第一千一百六十一条规定：继承人以所得遗产实际价值为限清偿，也就是只用继承到的那部分还、不用自己再掏，放弃继承的可以不负清偿责任', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s29-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-1', 'concept_archive_s30-1', 'recommendation', '按规矩把 30 组病例报告、2116 例睾丸扭转患者找齐，合起来看。其中 1283 例是按 6 小时一档统计的。从开始痛算起，0 至 6 小时睾丸保住的比例 97.2%。7 至 12 小时 79.3%。13 至 18 小时 61.3%。19 至 24 小时 42.5%。25 至 48 小时 24.4%。超过 48 小时 7.4%。合并成大段看，12 小时内 90.4%，13 至 24 小时 54.0%，超过 24 小时 18.1%。作者的结论是，能保住的时间可以比通常说的 6 至 8 小时更长。所以就算已经痛了很久，也还是要去处理，不要因为「反正晚了」就不去', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-2', 'concept_archive_s30-2', 'recommendation', '多家医院一起做的试验，找了 242 例够条件戴支具的青少年特发性脊柱侧弯患者。其中 116 例抽签分组，126 例自己选戴不戴。成败事先定好怎么算：弯度长到 50 度以上算治疗失败，骨头长完时还没到这个度数算治疗成功。按最初分到哪一组来算，不管后来有没有真戴够。抽签戴支具组成功率 75%，抽签只观察组 42%（OR 4.11，95% CI 1.85–9.16），成功的机会约为只观察的 4 倍。把抽签的和自己选的两拨人合起来算，是 72% 对 48%（把两拨人本来的差别扣平后 OR 1.93，1.08–3.46，仍约 1.9 倍）。每天戴的小时数越多，成功率越高（P&lt;0.001，这个关系不太可能是碰巧）。试验因为支具确实有效，提前停掉了', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-3', 'concept_archive_s30-3', 'recommendation', '34 项研究、284,375 名儿童青少年合起来算。被同伴欺凌和冒出自杀念头相关，OR 2.23（95% CI 2.10–2.37），出现念头的机会约为没被欺凌的 2.2 倍。另有 9 项研究、70,102 人，被欺凌和自杀未遂相关，OR 2.55（1.95–3.34），约 2.6 倍。男女、年龄和研究本身质量不同，结果都一样。网络欺凌和自杀念头的关联比线下欺凌更强。《未成年人学校保护规定》第二十一条列出五类行为：殴打、脚踢、掌掴、抓咬、推撞、拉扯；辱骂、讥讽、起侮辱性绰号；抢夺、强拿硬要或故意毁坏财物；恶意排斥孤立；通过网络捏造事实诽谤或散布谣言。该条还规定，在年龄、身体或人数上占优势的一方蓄意或恶意做这些事，造成人身伤害、财产损失或精神损害的，可以认定为欺凌。第二十二条要求教职工发现学生情绪反常、身体损伤，应及时了解并报告。第二十三条要求学校接到报告立即调查，提交欺凌治理组织认定处置，并通知家长参与。认定构成欺凌的，要作出教育惩戒或纪律处分。对违反治安管理或涉嫌犯罪的严重欺凌行为不得隐瞒，应当及时向公安机关、教育行政部门报告（全国，2021 年 9 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-4', 'concept_archive_s30-4', 'recommendation', '广州 12 所小学的一年级学生，以学校为单位抽签分组（干预校 952 人，对照校 951 人，平均年龄 6.6 岁）。干预的做法是每个上学日增加 1 节 40 分钟户外活动课，并鼓励家长在课外多带孩子出去。3 年里新近视的比例，干预组 30.4%，是 853 名合格者中的 259 例；对照组 39.5%，是 726 名中的 287 例。两组差值 -9.1 个百分点（95% CI -14.1 至 -4.1，P&lt;0.001），真实差距大致在少 4 到少 14 个百分点之间。3 年里度数的加深量（等效球镜变化）是 -1.42 D 对 -1.59 D，差 0.17 D（P=0.04）。干预组加深得略少一点。D 是量度数的单位。眼轴（眼球前后的长度）的增长，两组看不出差别（P=0.07）。《防控儿童青少年近视核心知识十条》要求儿童青少年每天日间户外活动不少于 2 小时，或每周累计 14 小时。它注明即使阴天，户外活动也有防护效果，并要求避开午后高温强晒的时段', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-5', 'concept_archive_s30-5', 'recommendation', '《防控儿童青少年近视核心知识十条》第四条的原话是「0～3岁婴幼儿不使用手机、平板、电脑等视屏类电子产品；3～6岁幼儿尽量避免其接触和使用手机、平板、电脑等视屏类电子产品；中小学生非学习目的使用电子屏幕单次时长不宜超过15分钟，每天累计时长不宜超过1小时」。同一条写明「长时间近距离使用电子视屏类产品，易消耗儿童远视储备量，是儿童青少年近视早发、高发的重要原因」。教育部等八部门 2018 年的实施方案给家长的要求一致，还加了一句「年龄越小，连续使用电子产品的时间应越短」。研究证据要弱得多：一项系统综述收了 33 项研究，11 项进了合并计算，对象从 3 个月到 33 岁。只算手机和平板的，近视的比值比是 1.26（95% CI 1.00 到 1.60，I²=77%）。和电脑合起来算是 1.77（1.28 到 2.45，I²=87%）。作者的结论只写到「可能相关」，并写明 33 项研究没有一项有可靠的屏幕时间测量', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-6', 'concept_archive_s30-6', 'recommendation', '一项系统综述与荟萃分析汇总了 2019 年 6 月之前的研究，按度数分三档：轻度（−0.5 到 −3.00 D）、中度（−3.00 到 −6.00 D）、高度（≤−6.00 D，600 度以上）。和不近视的人相比，近视性黄斑变性的比值比依次是 13.57（95% CI 6.18 到 29.79）、72.74（33.18 到 159.48）、845.08（230.05 到 3104.34）。视网膜脱离依次是 3.15（1.92 到 5.17）、8.74（7.28 到 10.50）、12.62（6.65 到 23.94）。后囊下白内障依次是 1.56（1.32 到 1.84）、2.55（1.98 到 3.28）、4.55（2.66 到 7.75）。开角型青光眼，轻度是 1.59（1.33 到 1.91），中度和高度合起来是 2.92（1.89 到 4.52）。60 岁以上出现视力损害的比值比，三档依次是 1.71（1.07 到 2.74）、5.54（3.12 到 9.85）、87.63（34.50 到 222.58）。《防控儿童青少年近视核心知识十条》的说法一致：600 度以上为高度近视，这类人群里白内障、开角型青光眼、近视性黄斑病变、视网膜脱离、近视性视神经病变等致盲性眼病的发病率明显高于其他人群，而且「近视可防可控不可逆」', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-7', 'concept_archive_s30-7', 'recommendation', '《中小学生健康体检管理办法（2021 年版）》规定，中小学校每年组织 1 次在校学生健康体检。外科检查包括头部、颈部、胸部、脊柱、四肢、皮肤、淋巴结。眼科检查包括眼外观、远视力、屈光度（近视远视的度数）。发给个人的报告单应包括查出来的结果、总的评价和健康指导建议。其中超重、肥胖、营养不良、脊柱弯曲异常、视力不良、龋齿（蛀牙）须作为指导重点。教育行政部门应当对出现健康问题的学生建立档案并随访（记下来、之后再跟进）。义务教育阶段学生健康体检费用由学校公用经费开支，家长不另掏（全国，2021 年 9 月印发）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-8', 'concept_archive_s30-8', 'recommendation', '美国预防服务工作组 2022 年发了一份推荐声明。它建议对 12 至 18 岁青少年筛查重度抑郁障碍（B 类推荐）。B 类的意思是把握中等、算下来好处也中等，值得做。对 11 岁及以下儿童筛查重度抑郁，证据不足（I 声明，即证据不够，给不出建议）。对儿童青少年专门筛查自杀风险，好处和坏处的证据都不足（I 声明）。文件指出，自杀是 10 至 19 岁人群的第二位死因。文件还指出，儿童青少年的重度抑郁和后来的很多问题关系密切。这些问题包括成年后抑郁反复发作、别的精神障碍，以及自杀念头、自杀未遂、自杀死亡的风险升高。《进一步加强中小学生心理健康工作十条措施》要求构建班主任、专兼职心理健康教师、精神科医师三级服务体系。每名学生每学年接受心理测评，一般不超过 1 次。文件还要求推进精神疾病转介就医和愈后复学机制。它要求发挥 12355 青少年服务台和 12356 心理援助热线的作用（全国，2025 年 10 月印发）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-9', 'concept_archive_s30-9', 'recommendation', '市场监管总局办公厅 2021 年 11 月至 2022 年 3 月的专项整治行动通知明确：「在目前医疗技术条件下，近视不能治愈」。通知要求依法从严查处使用「康复」「恢复」「降低度数」「近视治愈」「近视克星」「度数修复」等误导性表述营销儿童青少年近视防控产品的行为。通知要求加大打击力度，管的是冒用中医药名义、或者假借中医药理论技术做营销宣传欺骗消费者的行为。通知还要求严厉打击两类虚假违法广告：使用患者名义或形象作诊疗前后效果对比的，以及对诊疗安全性、功效作保证性承诺的。通知要求电商平台严格落实护眼仪等医疗器械及有关特殊商品的经营资质审查责任（查清卖家够不够格卖）（全国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-10', 'concept_archive_s30-10', 'recommendation', '《关于进一步加强中小学生睡眠管理工作的通知》规定：小学生每天睡眠应达 10 小时，初中生 9 小时，高中生 8 小时。小学上午上课时间一般不早于 8:20，中学一般不早于 8:00。学校不得要求学生提前到校参加统一的教育教学活动。小学生就寝一般不晚于 21:20，初中生不晚于 22:00，高中生不晚于 23:00。校外培训机构培训结束时间不得晚于 20:30，线上直播类培训结束不得晚于 21:00。每日 22:00 到次日 8:00 不得为未成年人提供游戏服务（全国，2021 年 3 月印发）。《进一步加强中小学生心理健康工作十条措施》另有几条规定：全面推行中小学生每天综合体育活动时间不低于 2 小时，鼓励推行「课间 15 分钟」。它还规定不得以考试成绩对学生进行排名，严禁布置机械重复、惩罚性作业，鼓励每周设置一天「无作业日」（全国，2025 年 10 月印发）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-11', 'concept_archive_s30-11', 'recommendation', '《中小学生学籍管理办法》第十六条规定了休学怎么办。学生休学由父母或其他法定监护人提出申请。学校确认后报上级学籍管理部门核准。复学时学校应及时办理相关手续。一次申请休学的期限不超过 1 年，期满后确实还要接着休的，应重新申请办理。学生休学期间学校应为其保留学籍（学生身份和位置给留着）。休学复学的具体办法由省级教育行政部门制定（全国，2025 年 1 月印发）。《进一步加强中小学生心理健康工作十条措施》要求推进精神疾病转介就医和愈后复学机制建设，指导学校制定校园突发心理危机事件处理预案', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-12', 'concept_archive_s30-12', 'recommendation', '《防控儿童青少年近视核心知识十条》写明了散瞳验光是怎么回事。先用睫状肌麻痹剂，再验光。睫状肌麻痹剂是让眼睛里负责调焦的那块肌肉松下来的眼药水。散瞳验光是在医院做的医学验光，为诊断近视的「金标准」（最准的做法）。散瞳药物对健康的眼睛不会产生损伤，用药后可短期出现怕光、看近处不清楚，停药后可恢复正常。一旦确诊近视，应及时科学干预，通过配戴眼镜等矫正。配戴合适的眼镜可以有效矫正视物不清、延缓近视进展。戴镜视力正常者，学龄前儿童及小学生每 3 至 6 个月复查一次，初高中学生每 6 至 12 个月复查一次，根据具体情况决定是否更换眼镜。儿童在 1 至 3 岁、4 至 6 岁、7 岁之后应定期接受屈光筛查（查度数），监测远视储备量（全国，2023 年 7 月印发）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-13', 'concept_archive_s30-13', 'recommendation', '38 项试验、7924 名 5 至 16 岁儿童，由 Cochrane 按规矩找齐后合起来算。拿树脂类封闭剂和不封闭比。5 至 10 岁儿童的第一恒磨牙，做完 24 个月时长蛀牙 OR 0.12（95% CI 0.08–0.19），长蛀牙的机会约为不封闭的八分之一。这一项来自 7 项试验，1548 名抽签分组、1322 名最后受检，证据质量中等。若对照组 24 个月内 16% 的牙面长蛀牙，封闭后为 5.2%（3.13%–7.37%）。对照组 40% 时为 6.25%（3.84%–9.63%）。对照组 70% 时为 19%（12.3%–27.2%）。做完 48 至 54 个月时 OR 0.21（0.16–0.28），仍是不封闭的约五分之一。作者结论为树脂封闭剂在 24 个月时比不封闭少长 11% 至 51% 的蛀牙。4 项记录了不良反应的试验中，没出现不良反应。玻璃离子这类别的封闭材料之间谁更好，证据不足', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-14', 'concept_archive_s30-14', 'recommendation', '一篇荟萃分析汇总了 17 个国家的 53 项研究、226247 人。游戏障碍的患病率是 3.05%（95% CI 2.38–3.91，这是可信范围）。只算抽样更严格的研究，是 1.96%。各研究结果差得远，77% 的差别出在用的是哪份问卷上。样本是青少年、门槛分数低、样本小，都会让比例偏高。另一项研究拿到 7 家游戏公司的数据，把 38935 名玩家六周的真实游戏时长，和他们自己填的幸福感连起来看。几乎找不到玩的时长影响幸福感的证据。国家新闻出版署规定，游戏企业只能在周五、周六、周日和法定节假日每天 20 时到 21 时，给未成年人提供 1 小时服务（全国 / 国际，2021 年起）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-15', 'concept_archive_s30-15', 'recommendation', '国内一项调查覆盖 7 个省 506 所中学，共 150822 名初一到高三的学生。过去一年试过自杀的，男生里只喜欢异性的是 2.2%，只喜欢同性的是 6.9%，两性都喜欢的是 12.2%。女生对应是 3.1%、8.9%、10.9%。算下来约是只喜欢异性的同学的 3 到 5.5 倍。研究者扣除了年龄、学业压力、家庭经济、被欺凌这些因素。之后男生这两组的 OR 是 3.13（95% CI 2.28–4.28）和 3.83（2.85–5.14），高约两到三倍。一篇汇总 35 项研究的荟萃分析算出，性少数青少年试过自杀的 OR 3.50（2.98–4.12）。美国一项研究访问了 224 名 21 到 25 岁的同性恋和双性恋青年，请他们回忆青春期时家里的反应。和家里几乎不排斥的同龄人比，家里排斥程度高的试过自杀的 OR 是 8.4。另一项研究里，父母自己试图改变孩子性取向的，孩子试过自杀的 OR 3.08（1.39–6.83）。父母还把孩子送去找治疗师或宗教人士的，是 5.07（2.38–10.79）（中国 / 多国 / 美国）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-16', 'concept_archive_s30-16', 'recommendation', '先看打。一篇荟萃分析只算「张开手打屁股或打手脚」这一种。它汇总了 75 项研究、111 个效果值，共 160927 名孩子。17 项结果里有 13 项和挨打明显有关，方向全是坏的。d 是效果大小，0.2 算小，0.5 算中等。小时候的攻击性 d = 0.37（95% CI 0.13–0.61，可信范围）。外显问题 0.41，指打人、违反规矩这类。内化问题 0.24，指焦虑、抑郁这类。心理健康问题 0.53，和父母关系差 0.51，自尊低 0.15，认知能力差 0.17。被父母施加身体虐待 0.64。长大后的反社会行为 0.36，心理健康问题 0.24。111 个效果值合起来是 d = 0.33（0.29–0.38）。孩子当场听不听话，和挨不挨打关系不明显（d = 0.14，−0.19–0.47），这一项只有 5 个效果值。另一篇综述只看前后跟踪的研究，共 69 项。体罚稳定地预示孩子之后的行为问题变多，没看到它和任何长期的好结果有关。其中 7 项研究看了打的次数，5 项发现打得越多、问题越重。再看吼骂。美国一项研究跟踪了 976 个父母双全的家庭。孩子 13 岁时，父母常吼叫、骂脏话、骂孩子笨或懒，孩子 13 到 14 岁之间闯祸和抑郁症状都增加。父母平时亲不亲热，都抵消不了这个关联。反过来也成立：13 岁时闯祸多的孩子，之后挨骂也更多。法律上，父母不得对孩子实施家庭暴力。《反家庭暴力法》第二条列了家庭暴力的方式：殴打、捆绑、残害、限制人身自由，以及经常性谩骂、恐吓。该法第十二条要求监护人用文明的方式进行家庭教育。父母侵犯孩子权益的，居委会、村委会要劝诫、制止，情节严重的报公安。公安、检察院、法院发现了，应当训诫父母，并可以责令他们接受家庭教育指导（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-17', 'concept_archive_s30-17', 'recommendation', 'Cochrane 汇总了 13 项试验，其中 10 项是抽签分组的，共 1078 名家长。孩子 3 到 12 岁，都有行为问题。上过课的家长，孩子的行为问题少了。家长自己评是 SMD −0.53（95% CI −0.72 到 −0.34，可信范围），旁人独立评是 −0.44（−0.77 到 −0.11）。SMD 和 d 是同一把尺子，0.5 算中等。家长的心理健康变好，−0.36（−0.52 到 −0.20）。负面或严厉的管法变少，家长自己评 −0.77（−0.96 到 −0.59），旁人评 −0.42（−0.67 到 −0.16）。作者说这些是短期效果。另一篇荟萃筛出 346 项抽签分组的试验，其中 60 项量了打骂孩子这类行为，分布在 22 个国家。打骂在课刚上完时少了，d = −0.46（−0.59 到 −0.33）。1 到 6 个月后是 −0.24（−0.37 到 −0.11）。7 到 24 个月后是 −0.18（−0.34 到 −0.02），越往后越小。这些数据大多是家长自己报的。国内也有试验。上海 81 名家长抽签分组，一部分上 Triple P 小组课。上完课，孩子的适应问题、家长的管法和情绪，都比等着上课的家长好，6 个月后还在。农村一所幼儿园有 191 名带孩子的大人参加，一部分自学网课，再加两次小组讨论。上完两周，他们报告的虐待孩子行为比只发书读的少约 33%（IRR 0.67）。三个月后，孩子的行为问题也少了（d = −0.40）。《家庭教育促进法》要求父母自觉学习家庭教育知识。中小学校、幼儿园可以办家长学校，定期组织公益性的家庭教育指导。居委会、村委会可以办社区家长学校。省级以上政府要开公益性的网上家长学校和服务热线。家庭教育指导机构不得组织营利性培训（全国，2022 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s30-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s30-18', 'concept_archive_s30-18', 'recommendation', '《未成年人保护法》第六十八条规定，任何组织和个人不得用侵害未成年人身心健康的方式，干预未成年人沉迷网络。下面两起案子都有法院判决。第一起在安徽合肥。2017 年 8 月，一名 18 岁男孩的父母和一家特训学校签了协议，要送他戒网瘾。学校的人把他强行带走，关进禁闭室，把他的双手铐在窗户栅栏上。他们限制他吃饭、喝水和休息，还打了他。约 44 个小时后，男孩死亡。鉴定结论是高温、限制体位、缺少饮食和外伤，引起水电解质紊乱死亡。2018 年 10 月 31 日，合肥市中级法院一审判决。学校负责人犯故意伤害罪和非法拘禁罪，判 16 年。四名教官判 1 年到 8 年 6 个月。2018 年 12 月 28 日，安徽省高级法院二审维持原判。二审裁定写明，这所学校没有经过有关部门批准，几名被告人也都没有教师资质。第二起在江西南昌。豫章书院 2013 年开办，2017 年 11 月注销停办。办学期间，学校把部分学生带进「烦闷解脱室」关禁闭，派专人看守，每次关三到十天。2023 年 4 月 28 日，萍乡市安源区法院重审一审宣判，五名被告人构成非法拘禁罪。四人判二年十个月到十一个月，并在一定期限内禁止从事和教育有关的职业，一人免予刑事处罚。家长要求赔学费和往返交通费，法院不支持（全国 / 安徽 / 江西）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s30-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-1', 'concept_archive_s31-1', 'recommendation', '当兵看兵役法：「年满十八周岁的男性公民，应当被征集服现役；当年未被征集的，在二十二周岁以前仍可以被征集服现役。普通高等学校毕业生的征集年龄可以放宽至二十四周岁，研究生的征集年龄可以放宽至二十六周岁」。考公务员看《公务员录用规定》第十八条。报考条件含「年龄为十八周岁以上，三十五周岁以下」「具有大学专科以上文化程度」。这两项经省级以上公务员主管部门批准可适当调整。该规定第十九条列了五类不得报考的人。比如因犯罪受过刑事处罚的、被开除公职的、被列为失信联合惩戒对象的。消防员看《国家综合性消防救援队伍消防员招录办法》。第五条「年龄为 18 周岁以上、22 周岁以下」「具有高中以上文化程度」。第六条「大学专科以上学历人员、解放军和武警部队退役士兵……年龄可以放宽至 24 周岁」。军队文职看《中国人民解放军文职人员条例》第九条，基本条件含「年满 18 周岁」。该条例第十九条写明，较低职级岗位首次招录聘用最高年龄 35 周岁。较低职级岗位就是入门层级的岗位。事业单位看《事业单位人事管理条例》第八条「事业单位新聘用工作人员，应当面向社会公开招聘」。个体户看《促进个体工商户发展条例》「有经营能力的公民……依法登记为个体工商户的，适用本条例」。自考看《高等教育自学考试暂行条例》。第三条「中华人民共和国公民，不受性别、年龄、民族、种族和已受教育程度的限制，均可依照本条例的规定参加高等教育自学考试」。第二十条「各级各类全日制学校的在校生不得报考」。公费师范生看《教育部直属师范大学本研衔接师范生公费教育实施办法》第二条。它只在六所部属师范大学招。分别是北京师范大学、华东师范大学、东北师范大学、华中师范大学、陕西师范大学和西南大学。本科和研究生阶段一体设计、分段考核，本科读完接着读研究生。在校期间的学费和住宿费由中央财政承担，另外还给生活费补助。该办法第五条「招收公费师范生实行提前批次录取」，就是在普通批次之前先录。定向医学生看《关于做好农村订单定向免费培养医学生就业安置和履约管理工作的通知》。它写着：「在录取后、获得入学通知书前，须与培养学校和定向就业所在地的县级卫生健康行政部门……人力资源社会保障部门签署协议」。出国打工看《对外劳务合作管理条例》。第五条：从事对外劳务合作应当经商务主管部门批准取得经营资格。第七条第四款：「未依法取得对外劳务合作经营资格证书并办理登记，不得从事对外劳务合作」。没有这张资格证的公司组织人出国打工，本身就违法。第八条第二款：「任何单位和个人不得以商务、旅游、留学等名义组织劳务人员赴国外工作」。平台接单和灵活就业没有法定学历门槛，自己参保和职业伤害保障的依据见本节第 11、12 条。义务教育法「禁止用人单位招用应当接受义务教育的适龄儿童、少年」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-2', 'concept_archive_s31-2', 'recommendation', '登记看《兵役登记工作规定》。它写着：「县、自治县、不设区的市、市辖区人民政府兵役机关应当于每年 10 月 31 日前，组织本行政区域内当年 12 月 31 日以前年满 18 周岁的男性公民进行初次兵役登记」。同一份规定还写着：「初次兵役登记主要采取网络登记的方式进行，由公民通过兵役登记网络平台自主完成」。不登记会怎么样，看兵役法第五十七条第一款。这一款管的是「拒绝、逃避兵役登记的」。处罚是「由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款」。兵役法还写着「义务兵服现役的期限为二年」。「根据军队需要和本人自愿，可以征集年满十七周岁未满十八周岁的公民服现役」。军士「服现役满十二年或者符合国家规定的其他条件的，由安置地的县级以上地方人民政府安排工作」。军士「服现役满三十年或者年满五十五周岁或者符合国家规定的其他条件的，作退休安置」。安排工作就是由政府给一份工作，退休安置就是按退休办退下来。《征兵工作条例》写着「优先保证普通高等学校毕业生和对政治、身体条件或者专业技能有特别要求的兵员征集」。该条例还写着「应征公民为普通高等学校的全日制在校生、应届毕业生的，可以在入学前户籍所在地或者学校所在地应征」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-3', 'concept_archive_s31-3', 'recommendation', '兵役法第五十七条第一款第二项是「应征公民拒绝、逃避征集服现役的」。处罚同样是「由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款」。同一条第二款：「有前款第二项行为，拒不改正的，不得录用为公务员或者参照《中华人民共和国公务员法》管理的工作人员，不得招录、聘用为国有企业和事业单位工作人员，两年内不准出境或者升学复学，纳入履行国防义务严重失信主体名单实施联合惩戒。」联合惩戒就是多个部门照同一份名单，一起执行上面这些限制。第五十八条把同一套惩戒接到已经入伍的人身上。军人以逃避服兵役为目的，拒绝履行职责或者逃离部队，后果要看处理结果。被军队除名、开除军籍或者被依法追究刑事责任的，依照第五十七条第二款处罚。其中被除名的并处罚款（全国，2021 年 10 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-4', 'concept_archive_s31-4', 'recommendation', '财政部等四部门 2024 年通知说，去服兵役的高校学生有三样待遇：学费补偿、用于学费的国家助学贷款代偿、学费减免。代偿就是国家替你把这笔助学贷款还掉。这三样的标准「相应调整为本专科学生每人每年最高不超过 20000 元、研究生每人每年最高不超过 25000 元」。新标准自 2024 年秋季学期起执行。到底按多少补，看这一句：「按学生实际缴纳的学费或获得的国家助学贷款（包括本金及其全部偿还之前产生的利息）两者金额较高者执行」。后面还有一句是「超出标准部分不予补偿、代偿或减免」。所以每年拿到的，是「实际学费和助学贷款里较高的那个」与上限两者中较小的那个。学费每年 5000 元的就补 5000 元。补几年按读书的年数算，不按服役的年数算。2019 年的学生资助资金管理办法写着：「入伍前已完成规定的修业年限，即为学费补偿或国家助学贷款代偿的年限；退役复学后接续完成规定的剩余修业年限，即为学费减免的年限」。应届毕业生去当兵，补的是整个学制的学费。学籍看《退役军人保障法》。它写着：「现役军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习」。该法还写着：「高等学校根据国家统筹安排，可以通过单列计划、单独招生等方式招考退役军人」。考研看教育部办公厅 2026 年通知。这个计划叫「退役大学生士兵计划」。通知写着：「在全国硕士研究生招生计划总规模内单列下达、专项使用，不得调整为普通计划或其他专项计划。招生单位自主确定……初试成绩要求（一般不高于本单位相应学科专业普通计划考生初试成绩要求）……同等条件下服役时间长的考生优先录取」。单列、专项使用的意思是，这部分名额单独划出来，只能用来招退役大学生士兵。这个计划 2026 年由 532 所普通高等学校承担（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-5', 'concept_archive_s31-5', 'recommendation', '《退役军人安置条例》第二十五条列了六种情形，由安置地人民政府安排工作。原文是：「（一）军士服现役满 12 年的；（二）服现役期间个人获得勋章、荣誉称号的；（三）服现役期间个人荣获三等战功、二等功以上奖励的；（四）服现役期间个人获得一级表彰的；（五）因战致残被评定为 5 级至 8 级残疾等级的；（六）是烈士子女的」。该条例还写着：「安置地人民政府应当在接收退役军士和义务兵的 6 个月内完成安排退役军士和义务兵工作的任务」。用人单位「应当按照规定与其签订不少于 3 年的中长期聘用合同或者劳动合同。其中，企业接收军龄 10 年以上的退役军士的，应当与其签订无固定期限劳动合同」。无固定期限就是合同上不写到期日。待安排工作期间「按照当地月最低工资标准逐月发放生活补助」。不是因为你自己的原因没按规定安排上岗的，「按照不低于本单位同等条件人员平均工资 80% 的标准，逐月发放生活费直至上岗为止」。不得以安排工作方式安置的情形，包括被开除中国共产党党籍、受过刑事处罚。自主就业的期限看第五十一条：「自主就业的退役军士和义务兵，应当自被批准退出现役之日起 30 日内，到安置地人民政府退役军人工作主管部门报到。无正当理由不按照规定时间报到超过 30 日的，视为放弃安置待遇。」（全国，2024 年 9 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-6', 'concept_archive_s31-6', 'recommendation', '第一笔看《退役军人安置条例》。它写着：「对自主就业的退役军士和义务兵，根据其服现役年限发放一次性退役金」。钱由谁出：「由中央财政专项安排，具体标准由国务院退役军人工作主管部门、中央军事委员会政治工作部门会同国务院财政部门……确定，并适时调整」。增发比例分五档。获得勋章、荣誉称号增发 25%，一等战功或一级表彰 20%。二等战功、一等功或二级表彰 15%。三等战功或二等功 10%，四等战功或三等功 5%。该条例还写着：「退役军人未及时就业的，可以依法向户口所在地人力资源社会保障部门申领失业保险待遇，服现役年限视同参保缴费年限，但是以退休、供养方式安置的退役军人除外」。视同缴费年限的意思是，这几年你没交过钱，也按交过算。第二笔看《退役军人保障法》：「退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算」。工龄就是参加工作的年数，服役这几年和退役后的年数接着往上加。该法还写着，服现役年限与入伍前、退役后的养老、医疗、失业缴费年限「依法合并计算」，「退役的军士和义务兵服现役经历视为基层工作经历」。《军人保险法》：「军人服现役年限视同职工基本医疗保险缴费年限，与入伍前和退出现役后参加职工基本医疗保险的缴费年限合并计算」。第三笔看财政部、税务总局、退役军人事务部 2023 年第 14 号公告。公告写的是自主就业退役士兵从事个体经营的情形：「在 3 年（36 个月，下同）内按每户每年 20000 元为限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税。限额标准最高可上浮 20%」。扣减就是从当年该交的这几种税里按顺序往下减，减到限额为止，不是发给你的钱。企业招用的「定额标准为每人每年 6000 元，最高可上浮 50%」。执行期为 2023 年 1 月 1 日至 2027 年 12 月 31 日。到期未满 3 年的可继续享受至期满（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-7', 'concept_archive_s31-7', 'recommendation', '第四轮「三支一扶」计划通知写着「服务期为两年」。它还写着：「各省（区、市）每年应拿出公务员考录计划的 10％左右，面向『三支一扶』计划等服务基层项目人员定向考录。各省（区、市）县乡基层事业单位公开招聘时，应根据本地区实际拿出一定数量或比例的岗位，对『三支一扶』服务期满考核合格的人员进行专项招聘……聘用后可以不再约定试用期」。定向考录和专项招聘的意思是，这部分名额只在干过基层服务项目的人里面考，别人报不了。同一份通知还写着：「期满考核合格的『三支一扶』人员，三年内参加全国硕士研究生招生考试的，初试总分加 10 分，同等条件下优先录取……高职（高专）毕业生期满且考核合格的，可免试入读成人高等学历教育专科起点本科」。免试入读就是不用再考试，直接去读专升本。通知还写着：「参加『三支一扶』计划前无工作经历的人员期满且考核合格的，两年内在参加机关和企事业单位考录（招聘）、自主创业、落户、升学等方面可同等享受应届毕业生相关政策。『三支一扶』人员在基层服务年限计算为工龄，其参加工作时间按其到基层报到之日起算」。中央财政补助标准为西部地区每人每年 3 万元、中部地区 2.4 万元、东部地区 1.2 万元。中办国办的意见写着：「参加基层服务项目前无工作经历的人员服务期满且考核合格后 2 年内，在参加机关事业单位考录（招聘）、各类企业吸纳就业、自主创业、落户、升学等方面可同等享受应届高校毕业生的相关政策」。该意见还写着：「省级以上机关录用公务员，除特殊职位外，按照有关规定一律从具有 2 年以上基层工作经历的人员中考录」。另一条路是西部计划。它由「共青团中央、教育部、财政部、人力资源社会保障部共同组织实施」。它招募高校应届毕业生或在读研究生，「到西部基层从事为期 1—3 年」的志愿服务（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-8', 'concept_archive_s31-8', 'recommendation', '2024 年特岗计划通知写的招聘条件是：「要求本科及以上学历，以师范类专业为主，小学阶段可适当招聘师范高等专科学校毕业生」。「年龄不超过 30 周岁」。还须具有相应的教师资格证书。通知另写着：「参加过『大学生志愿服务西部计划』、有从教经历的志愿者和参加过半年以上实习支教的师范院校毕业生同等条件下优先录取」。「支持鼓励符合条件的退役军人到中小学任教，可综合考虑服役年限等因素对退役军人相应放宽年龄限制」。待遇和入编看这几句。「从 2024 年 1 月 1 日起，提高特岗教师工资性补助标准，中央财政……中部地区由年人均 3.52 万元提高到 3.88 万元，西部地区由 3.82 万元提高到 4.18 万元」。「同等条件下在薪酬待遇、职称评聘、评先评优、年度考核等方面享受与当地公办学校在编教师同等待遇」。「保证三年服务期满、考核合格且愿意留任的特岗教师及时入编并落实工作岗位，做好相关人事、工资关系等接转工作，连续计算工龄、教龄，不再实行试用期」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-9', 'concept_archive_s31-9', 'recommendation', '消防员看《国家综合性消防救援队伍消防员招录办法》。第五条基本条件含「年龄为 18 周岁以上、22 周岁以下」「具有高中以上文化程度」。第六条「大学专科以上学历人员、解放军和武警部队退役士兵、具有 2 年以上灭火救援实战经验的政府专职消防队员和政府专职林业扑火队员，年龄可以放宽至 24 周岁；对消防救援工作急需的特殊专业人才，经应急管理部批准年龄可以进一步放宽，原则上不超过 28 周岁」。第七条「消防员面向社会公开招录，主要从本省级行政区域常住人口中招录，根据需要也可以面向其他省份招录」。第九条写的招录程序是「宣传动员、组织报名、资格审查、体格检查、政治考核、体能测试和岗位适应性测试、心理测试和面试、公示、录用」。军队文职看《中国人民解放军文职人员条例》第十八条「军队实行公开招考、直接引进、专项招录相结合的文职人员招录聘用制度」。这是三条线：公开考试招人，直接引进现成的人才，面向特定人群专门招。该条例第九条基本条件含「年满 18 周岁」「符合军队招录聘用文职人员的政治条件」「符合岗位要求的文化程度、专业水平和工作能力」。第十九条写明，较低职级岗位首次招录聘用最高年龄 35 周岁。该条例还写明「文职人员岗位应当优先招录聘用符合条件的退役军人」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-10', 'concept_archive_s31-10', 'recommendation', '自考看《高等教育自学考试暂行条例》。第三条：「中华人民共和国公民，不受性别、年龄、民族、种族和已受教育程度的限制，均可依照本条例的规定参加高等教育自学考试」。第二十条：「各级各类全日制学校的在校生不得报考」。第二十五条写了拿毕业证的三个条件：考完全部课程并合格、完成毕业论文或实践任务、思想品德鉴定合格。都做到了就可取得毕业证书。这一条还写着「获得专科（基础科）或本科毕业证书者，国家承认其学历」。第三十二条写毕业证书获得者的工资待遇：「非在职人员录用后，与普通高等学校同类毕业生相同」。《高等教育法》第二十一条「国家实行高等教育自学考试制度，经考试合格的，发给相应的学历证书或者其他学业证书」。成人高考看《2025 年全国成人高校招生办法》。报名对象是「国家承认学历的各类高、中等学校在校生以外的从业人员和社会其他人员」。「报考高起本或高起专的考生应高级中等教育学校毕业或者具有同等学力。报考专升本的考生必须是已取得……专科毕业证书、本科结业证书或以上证书的人员」。「脱产最短学习时间为：高起本四年、高起专和专升本两年，非脱产最短学习时间为：高起本五年、高起专和专升本两年半」。脱产就是离开工作全天在校读，非脱产就是不离开工作、边干边读。开放大学看《教育部关于办好开放大学的意见》。它写着：「开放大学实行注册入学，学生修完课程并获得相应学分，即可获得课程证书，修满规定的学分并达到相关要求，即可获得相应的学历与非学历证书，符合学位授予条件的应授予相应学位」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-11', 'concept_archive_s31-11', 'recommendation', '参保看《关于维护新就业形态劳动者劳动保障权益的指导意见》。它写着：「各地要放开灵活就业人员在就业地参加基本养老、基本医疗保险的户籍限制，个别超大型城市难以一步实现的，要结合本地实际，积极创造条件逐步放开。组织未参加职工基本养老、职工基本医疗保险的灵活就业人员，按规定参加城乡居民基本养老、城乡居民基本医疗保险，做到应保尽保。督促企业依法参加社会保险。企业要引导和支持不完全符合确立劳动关系情形的新就业形态劳动者根据自身情况参加相应的社会保险」。同一份文件把用工分成三类：「符合确立劳动关系情形的，企业应当依法与劳动者订立劳动合同。不完全符合确立劳动关系情形但企业对劳动者进行劳动管理……指导企业与劳动者订立书面协议……个人依托平台自主开展经营活动、从事自由职业等，按照民事法律调整双方的权利义务」（全国，2021 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-12', 'concept_archive_s31-12', 'recommendation', '这项保障看《新就业形态人员职业伤害保障办法（试行）》。第二条写着：「平台企业应当依照本办法规定参加新就业形态人员职业伤害保障……为通过平台注册并接单，以平台企业名义提供出行、即时配送和同城货运等劳动并获得报酬或者收入的新就业形态人员缴纳职业伤害保障费，实现每单必保、每人必保。适用《工伤保险条例》规定的劳动者，企业应当依法为其参加工伤保险，不适用本办法」。第九条：「试行期间，出行行业按照每单 0.01 元执行；即时配送行业按照每单 0.07 元、0.25 元执行；同城货运行业按照每单 0.18 元执行」。试点怎么往外扩，看这一段：「2025 年 7 月 1 日起，在已先行试点 7 个省份和 7 个平台企业的基础上……增加天津、河北、辽宁、浙江、安徽、福建、山东、湖北、广西、宁夏等 10 个省份……2026 年，推动职业伤害保障试点在全国 31 个省份和新疆生产建设兵团实施；将出行、即时配送和同城货运三个行业的平台企业总体纳入职业伤害保障试点范围」（试点，逐年扩围）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-13', 'concept_archive_s31-13', 'recommendation', '公费师范生看《教育部直属师范大学本研衔接师范生公费教育实施办法》（2024 年，2018 年办法同时废止）。第二条：由中央财政承担学生在校期间学费、住宿费并给予生活费补助。第三条：重点为中西部地区省会城市之外的地（市、州、盟）及以下培养。它还写着「不得定向到直辖市、计划单列市或省会城市主城区任教（五个自治区、陆地边境省份、海南省、贵州省、青海省除外）」。第九条：毕业后一般回生源所在省份定向地（市、州、盟）中小学任教，「承诺从事中小学教育工作 6 年以上」。到城镇学校工作的，「应到农村义务教育学校任教服务至少 1 年」。第十三条：没履约或者履约期限不够的，按协议承担责任。后果之一是「违约行为纳入信用记录，并及时与全国信用信息共享平台共享，违约相关材料归入本人人事档案」。另一句是「履约任务完成前不得到定向地（市、州、盟）之外从教，不得被招录（聘用）为其他公务人员。完成履约任务后即修复相关信用」。协议约定的服务期没干满之前，别的公职岗位报不了；干满了，信用记录才恢复。第六条：录取后经考察不适合从教的，入学 1 年内退还已享受的公费教育费用，并调整到非师范专业。第十四条：没在规定学习年限内取得教育硕士学历学位证书和教师资格证书的，按违约处理，退费并缴纳违约金。第二十一条：各地在现有事业编制总量内，解决公费师范生到中小学任教所需编制。农村订单定向免费医学生看另一份通知。录取后、获得入学通知书前，须与培养学校和定向就业所在地县级卫生健康、人社部门签署协议。协议里要「承诺毕业后到定向农村基层医疗卫生机构服务 6 年」。履约就是按协议去指定的地方干满。履约报到就业后，须参加 3 年全科专业住院医师规范化培训，简称规培。规培就是毕业后在医院按统一标准接着练本事的阶段。培训期间原人事、工资关系不变。违约记录归入个人人事档案，并作为医疗卫生机构等行政事业单位公开招录（招聘）、住院医师规范化培训招收、研究生招生录取的诚信评价依据。恶意违约的人，通过「信用中国」网站全国公示，并实行失信联合惩戒。违约的培训年限不计入服务期。没按协议退还费用和违约金的，由县级卫生健康行政部门通过法律途径追缴（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-14', 'concept_archive_s31-14', 'recommendation', '《对外劳务合作管理条例》第五条：从事对外劳务合作应当经省级或者设区的市级商务主管部门批准取得经营资格。这个经营资格就是那张对外劳务合作经营资格证书，没有它就不能组织人出国干活。第七条：经营资格证书名单报国务院商务主管部门，并通报中国驻外使馆、领馆。这一条还写着「未依法取得对外劳务合作经营资格证书并办理登记，不得从事对外劳务合作」。第八条：「任何单位和个人不得以商务、旅游、留学等名义组织劳务人员赴国外工作」。第九条：企业应当自登记之日起 5 个工作日内在指定银行缴存「不低于 300 万元人民币的对外劳务合作风险处置备用金」，缴存名单向社会公布。第十条：备用金用于支付企业拒绝承担或者无力承担的应退服务费、劳动报酬和依法赔偿的损失。它还用于「因发生突发事件，劳务人员回国或者接受紧急救助所需费用」。第十一条：不得组织劳务人员赴国外从事与赌博、色情活动相关的工作。第十二条：没安排培训的不得组织出国。第十三条：应当为劳务人员购买在国外工作期间的人身意外伤害保险。第二十一、二十三条：须与国外雇主、与劳务人员分别订立书面合同，没订立的不得组织出国。第二十五条：「不得以任何名目向劳务人员收取押金或者要求劳务人员提供财产担保」。第二十六条：合同订立之日起 10 个工作日内报商务主管部门备案。第二十九条：劳务人员实际权益与合同不符的，企业应当协助索赔；没得到应有赔偿的，有权要求企业承担赔偿责任。第三十一条：有关国家或者地区安全状况难以保障人身安全的，企业不得组织劳务人员前往。第三十七条：商务主管部门建立不良信用记录和公告制度。罚则在后面几条。第三十九条：没资格从事对外劳务合作的，查处取缔，构成犯罪的追究刑事责任。第四十条：以商务、旅游、留学名义组织出国、出借资格、组织从事赌博色情相关工作的，吊销经营资格证书。第四十三条：没签合同、或者隐瞒信息、提供虚假信息组织出国的，罚 10 万元以上 20 万元以下。还要对主要负责人罚 2 万元以上 5 万元以下（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-15', 'concept_archive_s31-15', 'recommendation', '这笔钱算不算境内所得，看《个人所得税法实施条例》（国务院令第 707 号，2019 年 1 月 1 日起施行）第三条。它写着：「除国务院财政、税务主管部门另有规定外，下列所得，不论支付地点是否在中国境内，均为来源于中国境内的所得：（一）因任职、受雇、履约等在中国境内提供劳务取得的所得」。同一部条例第六条给两个税目下了定义。一个是工资薪金：「工资、薪金所得，是指个人因任职或者受雇取得的工资、薪金、奖金、年终加薪、劳动分红、津贴、补贴以及与任职或者受雇有关的其他所得」。另一个是劳务报酬：「劳务报酬所得，是指个人从事劳务取得的所得，包括从事设计、装潢、安装、制图、化验、测试、医疗、法律、会计、咨询、讲学、翻译、审稿、书画、雕刻、影视、录音、录像、演出、表演、广告、展览、技术服务、介绍服务、经纪服务、代办服务以及其他劳务取得的所得」。《个人所得税法》第六条写怎么算应纳税所得额：「居民个人的综合所得，以每一纳税年度的收入额减除费用六万元以及专项扣除、专项附加扣除和依法确定的其他扣除后的余额，为应纳税所得额」。同一条还写着「劳务报酬所得、稿酬所得、特许权使用费所得以收入减除百分之二十的费用后的余额为收入额」。减 20% 这一句只列了这三项，工资薪金不在其内。所以工资薪金按全额计入收入额，两个税目算出来的税不同。第九条：「个人所得税以所得人为纳税人，以支付所得的单位或者个人为扣缴义务人」。第十条：「有下列情形之一的，纳税人应当依法办理纳税申报：……（二）取得应税所得没有扣缴义务人；……（四）取得境外所得」。第十一条：「居民个人取得综合所得，按年计算个人所得税……需要办理汇算清缴的，应当在取得所得的次年三月一日至六月三十日内办理汇算清缴」。钱汇进来看《个人外汇管理办法》（中国人民银行令〔2006〕第 3 号，2007 年 2 月 1 日起施行）。第九条：「对个人结汇和境内个人购汇实行年度总额管理。年度总额内的，凭本人有效身份证件在银行办理；超过年度总额的，经常项目项下凭本人有效身份证件和有交易额的相关证明等材料在银行办理」。第七条：「银行和个人在办理个人外汇业务时，应当遵守本办法的相关规定，不得以分拆等方式逃避限额监管，也不得使用虚假商业单据或者凭证逃避真实性管理」。《个人外汇管理办法实施细则》（汇发〔2007〕1 号）第二条：「对个人结汇和境内个人购汇实行年度总额管理。年度总额分别为每人每年等值 5 万美元」。第十条：「境内个人经常项目项下非经营性结汇超过年度总额的，凭本人有效身份证件及以下证明材料在银行办理：……（七）职工报酬：雇佣合同及收入证明」（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s31-16', 'concept_archive_s31-16', 'recommendation', '个人申请条件写在《普惠金融发展专项资金管理办法》（财金〔2023〕75 号）第六条。第一个条件是要属于重点就业群体。文件列的是城镇登记失业人员、就业困难人员（含残疾人）、退役军人、刑满释放人员。还有高校毕业生（含大学生村官和留学回国学生）、化解过剩产能企业职工和失业人员。还有返乡创业农民工、网络商户、脱贫人口、农村自主创业农民等。第二个条件是名下不能有别的贷款：「除助学贷款、脱贫人口小额信贷、住房贷款、购车贷款、5 万元以下小额消费贷款（含信用卡消费）以外，申请人提交创业担保贷款申请时，本人及其配偶无其他贷款」。第九条：「对符合条件的创业担保贷款，财政部门给予贷款实际利率 50% 的财政贴息。对展期、逾期的创业担保贷款，财政部门原则上不予贴息」。贴息就是利息由财政替你出一半。展期是到期后再往后延，逾期是过期没还，这两种情况财政不再替你出。第十条：个人申请的 10 万元以下创业担保贷款原则上取消反担保，不必再另外找人、或者拿财产给担保机构做担保。第十一条：纳入奖补支持范围的个人创业担保贷款「额度不超过 30 万元，贷款期限不超过 3 年」。合伙创业可适当提高，最高不超过个人额度上限之和的 110%。奖补支持的贷款利率上限分三档：东部地区为 LPR+50BPs，中西部地区 LPR+150BPs，脱贫地区 LPR+250BPs。LPR 是银行贷款市场报价利率，BPs 是利率的计量单位，加得越多利息越高。「还款积极、带动就业能力强、创业项目好」的，到期后可继续申请，累计次数不超过 3 次。第八条：申请人先向当地人力资源社会保障部门申请资格审核，再向担保机构和经办银行提交申请。第十二条：经省级人民政府同意，各地可扩大支持范围、提高额度和贴息比例（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s31-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-1', 'concept_archive_s32-1', 'recommendation', '中国（教育部）留学服务中心有一个认证院校查询入口。你可以按国家查，也可以按学校名字查。查的是这所学校发的学历学位在不在认证范围里。另外，教育部教育涉外监管信息网还公布中外合作办学和境外办学的监管信息', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-2', 'concept_archive_s32-2', 'recommendation', '国土安全部 2026 年 7 月 17 日公布了一项规则，原定 2026 年 9 月 15 日生效。内容是 F-1 学生不再按「读完为止」入境，改成固定期限，最长四年，到期要另外申请延期。读完或者实习结束后，只留 30 天准备离境。2026 年 9 月 14 日，马萨诸塞州联邦地区法院的 Saylor 法官依《行政程序法》第 705 条，推迟了这项规则的生效。暂停管全国，管整份规则。法院没有撤销这项规则，撤销的请求被驳回，但允许以后再提。案子还在继续审。按法院这道命令，F、J、I 三类签证的人仍按「读完为止」入境，60 天离境宽限期照旧，也不需要另外申请延期', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-3', 'concept_archive_s32-3', 'recommendation', '美国的 F-1 学生，校内打工在学期中每周不得超过 20 小时。经批准的校外兼职同样是每周 20 小时。假期可以全职。依据是美国联邦移民法规 8 CFR 214.2(f)(9)。英国的学生签证，读学位及以上课程的，学期内每周 20 小时，学位以下的每周 10 小时。非全日制课程一律不得打工。还不得自雇（自己给自己干活），也不得做职业运动员或者演艺工作。依据是英国移民规则里管学生的那一部分，附录 Student ST26.1、ST26.5。加拿大符合条件的全日制学生，校外打工每周最多 24 小时，依据是加拿大移民法实施条例 IRPR 第 186(v) 条。澳大利亚的学生签证，课程进行期间每两周最多 48 小时。研究型硕士、博士和他们的家属不受这个限制', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-4', 'concept_archive_s32-4', 'recommendation', '加拿大明文规定，在获批的休学期间不得校外打工。转学期间没有在学习的，也不得校外打工。要等恢复学业以后，才能重新开始工作。美国的校内打工资格只给 SEVIS 里身份为 Active 的 F-1 学生。SEVIS 是美国的留学生身份档案系统，Active 是在读有效。这些学生还要维持全日制课业。英国的打工许可按课程类型给，非全日制课程不得打工', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-5', 'concept_archive_s32-5', 'recommendation', '美国联邦移民法规 8 CFR 265.1 规定，按法律要登记的外国人，地址变了以后 10 日内要报告。报给 USCIS（美国移民局），按它要求的办法报，既报地址变了这件事，也报新地址', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-6', 'concept_archive_s32-6', 'recommendation', '教育部通过教育涉外监管信息网发布留学预警。2025 年一共发了 4 号。第 1 号提示美国有关州通过的高等教育法案里含有涉华消极条款（2025-04-09）。第 2 号和第 3 号两次提示菲律宾针对中国公民的案件多发、留学环境不佳（2025-07-18、2025-08-30）。第 4 号提示日本治安形势和留学环境不佳，建议谨慎规划赴日留学（2025-11-16）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-7', 'concept_archive_s32-7', 'recommendation', '澳大利亚内政部规定，学生签证申请人和他的家属要买海外学生医疗保险（OSHC），而且在澳大利亚停留的全程都要有，不能断。保险要由澳大利亚认可的保险机构提供。符合可以免买的豁免情形的除外。新保险和前一个签证的保险之间不得有空档。入境时拿不出已经投保的证明，可能被拒绝入境。比课程开始时间更早入境的，保险起始日要写实际抵达澳大利亚的那一天', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-8', 'concept_archive_s32-8', 'recommendation', '英国学生签证的费用是 558 英镑。在英国境外申请、在境内延期或者转换，都是这个数。另外还有医疗附加费，交了才能用英国的国民医疗服务，按签证年数在申请时一次预交。学生本人和他的家属是每年 776 英镑，比如 2 年的签证就是 1552 英镑。其他类别的申请人是每年 1035 英镑。签证超过 6 个月、不足 1 年的，按整年收取', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-9', 'concept_archive_s32-9', 'recommendation', '国（境）外学历学位认证在中国（教育部）留学服务中心的网上服务大厅办。流程是四步：注册并实名认证，在线提交申请和材料，在线缴费，等评估和审核。公布的认证工作时限是 10 至 20 个工作日。工作日不含周末和节假日，这段是留服中心审核用的时间', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s32-10', 'concept_archive_s32-10', 'recommendation', '中国（教育部）留学服务中心一直在发公告，对部分国外院校的学历学位认证加强认证审查（对这些学校的文凭单独多查一道）。最新一份是第九号（2025-10-28）。留服中心还发过暂停受理个别境外院校认证申请的公告，也发过提示，说有人借国（境）外学历学位认证实施诈骗', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s32-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-1', 'concept_archive_s33-1', 'recommendation', '这种发作叫自主神经反射异常。一篇系统综述检索了 Medline、CINAHL、EMBASE 和 PsycINFO 四个数据库，纳入 31 项研究，其中 6 项是随机对照试验。综述写明，发作当时的非药物处理是三步：把患者摆成直立体位、松开紧身衣物、去除诱发刺激。这三步的依据是临床共识和生理学数据，属于第 5 级证据。血压持续升高时才用降压药，其中哌唑嗪有第 1 级证据，硝苯地平和前列腺素 E2 有第 2 级证据。综述还写明，预防发作的策略主要针对泌尿生殖系统和手术这两类常见诱因，多数只有第 4 级和第 5 级证据支撑', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s33-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-2', 'concept_archive_s33-2', 'recommendation', '研究跟踪了 1991 到 2010 年新入院、熬过伤后第一年、出院时有神经功能缺损的 2304 例外伤性脊髓损伤患者，随访到 2014 年底。其中 63 例（2.7%）的受伤原因本身就是自杀未遂。到随访结束共 533 人死亡，其中 4.2% 死于自杀，91% 的自杀发生在受伤后的头十年。按年龄标化的自杀死亡率是每年每 10 万人 62.5 例（95% CI 36.4–88.6，可信范围），是 2014 年英格兰和威尔士普通人群自杀率（每 10 万人 12.2 例）的五倍。因自杀未遂致伤的那部分人，和其他致伤原因相比，死亡的比值比是 4.32（P&lt;0.001），自杀的比值比是 9.46（P&lt;0.001）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-3', 'concept_archive_s33-3', 'recommendation', '《精神卫生法》第三十条写明「精神障碍的住院治疗实行自愿原则」。只有诊断结论和病情评估表明就诊者是严重精神障碍患者、并且有下列情形之一的，才应当实施住院治疗。一是「已经发生伤害自身的行为，或者有伤害自身的危险的」。二是「已经发生危害他人安全的行为，或者有危害他人安全的危险的」。第三十一条：属于第一种情形的，经监护人同意医疗机构才实施住院治疗，监护人不同意的不得实施。第三十二条：属于第二种情形而本人或者监护人有异议的，可以要求再次诊断，应当自收到诊断结论之日起三日内提出，由二名初次诊断医师以外的精神科执业医师作出；对再次诊断结论仍有异议的，可以自主委托依法取得执业资质的鉴定机构做精神障碍医学鉴定。第三十五条：再次诊断结论或者鉴定报告表明不能确定为严重精神障碍患者、或者患者不需要住院治疗的，医疗机构不得对其实施住院治疗。第七十八条：将非精神障碍患者故意作为精神障碍患者送入医疗机构治疗的，依法承担赔偿责任（全国，2013 年 5 月 1 日起施行，2018 年修正）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-4', 'concept_archive_s33-4', 'recommendation', '研究是前瞻性人群队列，1993 到 1998 年，平均随访 4.5 年，在美国四个社区做。392 名照护者和 427 名非照护者，年龄 66 到 96 岁，都与配偶同住。四年内 103 人（12.6%）死亡。调整社会人口学因素、已有疾病和亚临床心血管疾病之后，一边照护一边报告有精神或情绪紧张的人，死亡风险比非照护对照高 63%（RR 1.63，95% CI 1.00–2.65，可信范围）。照护但未报告紧张的人（RR 1.08，95% CI 0.61–1.90）和配偶失能但本人不照护的人（RR 1.37，95% CI 0.73–2.58），调整后的死亡率都没有升高', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-5', 'concept_archive_s33-5', 'recommendation', '这项随机临床试验在 12 家养老院做，2004 到 2008 年招募 232 名 65 岁以上、每天坐轮椅 6 小时以上、Braden 评分 18 分以下的住户。所有人先配了合身的轮椅，再随机分成两组。一组用皮肤保护型坐垫（空气、黏性流体加泡沫、或者凝胶加泡沫），一组用 7.6 厘米厚的分段式泡沫坐垫。随访 6 个月或者到发生压疮为止。坐骨结节部位的压疮，分段泡沫组 8 例（6.7%），皮肤保护型坐垫组 1 例（0.9%），P=0.04。把坐骨和骶尾部的压疮合起来算，分段泡沫组 21 例（17.6%），皮肤保护型坐垫组 12 例（10.6%），P=0.14，没有做出差别', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s33-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-6', 'concept_archive_s33-6', 'recommendation', '《广告法》第十六条规定，医疗、药品、医疗器械广告不得含有下列内容：「（一）表示功效、安全性的断言或者保证；（二）说明治愈率或者有效率；（三）与其他药品、医疗器械的功效和安全性或者其他医疗机构比较；（四）利用广告代言人作推荐、证明」。第十七条规定，除医疗、药品、医疗器械广告外，「禁止其他任何广告涉及疾病治疗功能，并不得使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语」。第四条规定，广告不得含有虚假或者引人误解的内容，不得欺骗、误导消费者，广告主应当对广告内容的真实性负责（全国，2021 年修正）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-7', 'concept_archive_s33-7', 'recommendation', '证接上的待遇至少六项，各有各的出处。一是困难残疾人生活补贴和重度残疾人护理补贴，见第 7 节第 8 条（两项补贴）。二是残疾儿童康复救助，见本节第 8 条（康复救助）。三是基本型辅助器具配置补贴，依据是《残疾预防和残疾人康复条例》第二十六条。四是家庭无障碍设施改造补贴，见本节第 9 条（坡道扶手和浴室改造）。五是按比例就业和就业服务，见本节第 10 条（主动说明持证）。六是个人所得税减征，见本节第 11 条（个税减征）。《残疾预防和残疾人康复条例》第二十六条还写明，国家通过实施重点康复项目为城乡贫困残疾人、重度残疾人提供基本康复服务，「按照国家有关规定对基本型辅助器具配置给予补贴」。第二十条规定，县级以上人民政府有关部门和残联应当利用社区资源，设立康复场所或者购买服务，开展康复指导、日常生活能力训练、康复护理、辅助器具配置、信息咨询和转介等社区康复工作（全国，2017 年 7 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-8', 'concept_archive_s33-8', 'recommendation', '《国务院关于建立残疾儿童康复救助制度的意见》写明，救助对象为符合条件的 0—6 岁视力、听力、言语、肢体、智力等残疾儿童和孤独症儿童。包括城乡最低生活保障家庭、建档立卡贫困户家庭的残疾儿童和儿童福利机构收留抚养的残疾儿童，残疾孤儿、纳入特困人员供养范围的残疾儿童，以及其他经济困难家庭的残疾儿童。其他经济困难家庭的具体认定办法由县级以上地方人民政府制定。文件还写明「有条件的地区，可扩大残疾儿童康复救助年龄范围，也可放宽对救助对象家庭经济条件的限制」。经费保障标准由县级以上地方人民政府依据本地财力状况、保障对象数量、残疾类别等分类确定，并建立动态调整机制。上位依据是《残疾预防和残疾人康复条例》第二十六条：国家建立残疾儿童康复救助制度，「逐步实现0—6岁视力、听力、言语、肢体、智力等残疾儿童和孤独症儿童免费得到手术、辅助器具配置和康复训练等服务」（全国，2018 年起）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-9', 'concept_archive_s33-9', 'recommendation', '《无障碍环境建设法》第十九条：「县级以上人民政府应当支持、指导家庭无障碍设施改造。对符合条件的残疾人、老年人家庭应当给予适当补贴。」第十八条规定，对既有的不符合无障碍设施工程建设标准的居住建筑、居住区、公共建筑、公共场所、交通运输设施、城乡道路等，县级以上人民政府应当根据实际情况制定有针对性的无障碍设施改造计划并组织实施。第六十二条规定，任何组织和个人有权向政府有关主管部门提出加强和改进无障碍环境建设的意见和建议，对违反本法规定的行为进行投诉、举报；主管部门接到投诉举报「应当及时处理并予以答复」。第六十三条规定，对违反本法规定损害社会公共利益的行为，人民检察院可以提出检察建议或者提起公益诉讼（全国，2023 年 9 月 1 日起施行）', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s33-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-10', 'concept_archive_s33-10', 'recommendation', '《残疾人就业条例》第八条：「用人单位安排残疾人就业的比例不得低于本单位在职职工总数的1.5%。具体比例由省、自治区、直辖市人民政府根据本地区的实际情况规定。」第九条：达不到所在地省级人民政府规定比例的，应当缴纳残疾人就业保障金。《残疾人就业保障金征收使用管理办法》第八条给了公式：「保障金年缴纳额=（上年用人单位在职职工人数×所在地省、自治区、直辖市人民政府规定的安排残疾人就业比例-上年用人单位实际安排的残疾人就业人数）×上年用人单位在职职工年平均工资」。第十六条：自工商登记注册之日起 3 年内，对安排残疾人就业未达到规定比例、在职职工总数 20 人以下（含 20 人）的小微企业，免征保障金。《残疾人保障法》第三十六条规定，国家对安排残疾人就业达到、超过规定比例或者集中安排残疾人就业的用人单位，依法给予税收优惠（全国，残疾人就业条例 2007 年 5 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-11', 'concept_archive_s33-11', 'recommendation', '《个人所得税法》第五条：「有下列情形之一的，可以减征个人所得税，具体幅度和期限，由省、自治区、直辖市人民政府规定，并报同级人民代表大会常务委员会备案：（一）残疾、孤老人员和烈属的所得；（二）因自然灾害遭受重大损失的。」《残疾人保障法》第三十六条另外规定，国家对从事个体经营的残疾人，依法给予税收优惠，并免除行政事业性收费（全国，个人所得税法 2019 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-12', 'concept_archive_s33-12', 'recommendation', '《无障碍环境建设法》第四十六条：「公共场所经营管理单位、交通运输设施和公共交通运输工具的运营单位应当为残疾人携带导盲犬、导听犬、辅助犬等服务犬提供便利。」第三十五条规定，政务服务便民热线和报警求助、消防应急、交通事故、医疗急救等紧急呼叫系统，应当逐步具备语音、大字、盲文、一键呼叫等无障碍功能。第六十二条规定，任何组织和个人有权对违反本法规定的行为投诉、举报，主管部门应当及时处理并予以答复。《残疾人保障法》第五十条：「盲人持有效证件免费乘坐市内公共汽车、电车、地铁、渡船等公共交通工具。盲人读物邮件免费寄递。」同条还规定，县级以上人民政府对残疾人搭乘公共交通工具应当给予便利和优惠，残疾人可以免费携带随身必备的辅助器具（全国，无障碍环境建设法 2023 年 9 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-12"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-13', 'concept_archive_s33-13', 'recommendation', '《残疾人参加普通高等学校招生全国统一考试管理规定》第五条列了十二项合理便利。包括为视力残疾考生提供现行盲文试卷、大字号试卷或者普通试卷；为听力残疾考生免除外语听力考试；允许视力残疾考生携带盲文笔、盲文手写板、无存储功能的盲文打字机、无存储功能的电子助视器、盲杖、光学放大镜等辅助器具；允许听力残疾考生携带助听器、人工耳蜗；允许行动不便的考生使用轮椅、助行器，有特殊需要的可以自带特殊桌椅。延长时间的幅度写在第五条第六项：「使用盲文试卷的视力残疾考生的考试时间，在该科目规定考试总时长的基础上延长50%；使用大字号试卷或普通试卷的视力残疾考生、因脑瘫或其他疾病引起的上肢无法正常书写或无上肢考生等书写特别困难考生的考试时间，在该科目规定考试总时长的基础上延长30%」。此外还有优先进入考点考场、单独标准化考场、配备引导辅助人员和手语翻译人员等。第七条规定申请程序：考生按省级教育考试机构规定的时间、地点、方式提出正式书面申请，并提供本人第二代及以上残疾人证；由专家组现场确认并综合评估，省级教育考试机构出具《告知书》。第八条规定，考生对《告知书》有异议，可以向省级教育行政部门提出书面复核申请。第九条规定，免除外语听力的，外语科成绩按「笔试成绩×外语科总分值/笔试部分总分值」计算。第十八条规定，残疾人参加其他国家教育考试需要合理便利的，可以参照本规定执行（全国，2017 年 4 月 7 日发布施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-13"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-14', 'concept_archive_s33-14', 'recommendation', '《残疾人教育条例》第七条：「学前教育机构、各级各类学校及其他教育机构应当依照本条例以及国家有关法律、法规的规定，实施残疾人教育；对符合法律、法规规定条件的残疾人申请入学，不得拒绝招收。」第二十九条：「普通职业学校不得拒绝招收符合国家规定的录取标准的残疾人入学，普通职业培训机构应当积极招收残疾人入学。」条例还规定，适龄残疾儿童、少年需要专人护理、不能到学校就读的，由县级人民政府教育行政部门统筹安排，通过提供送教上门或者远程教育等方式实施义务教育，并纳入学籍管理。第二十条规定，县级人民政府教育行政部门应当会同卫生行政部门、民政部门、残疾人联合会，建立由教育、心理、康复、社会工作等方面专家组成的残疾人教育专家委员会，由它评估身体状况、接受教育的能力和适应学校学习生活的能力并提出入学、转学建议；评估结果属于孩子的隐私，有关单位和工作人员负有保密义务。第二十三条规定，在普通学校随班就读的残疾学生，可以适用普通义务教育的课程设置方案、课程标准和教材，但是对其学习要求可以有适度弹性。第五十二条规定，残疾人参加国家教育考试需要必要支持条件和合理便利的，可以提出申请（全国，2017 年 5 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-14"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-15', 'concept_archive_s33-15', 'recommendation', '《机动车驾驶证申领和使用规定》附件 1 把身体条件写得很细。第 8 目：「右下肢、双下肢缺失或者丧失运动功能但能够自主坐立，且上肢符合本项第5目规定的，可以申请残疾人专用小型自动挡载客汽车准驾车型的机动车驾驶证。一只手掌缺失，另一只手拇指健全，其他手指有两指健全，上肢和手指运动功能正常，且下肢符合本项第6目规定的，可以申请残疾人专用小型自动挡载客汽车准驾车型的机动车驾驶证」。第 6 目：单独左下肢缺失或者丧失运动功能、但右下肢正常的，可以申请小型自动挡汽车准驾车型。视力一项：「单眼视力障碍，优眼裸视力或者矫正视力达到对数视力表5.0以上，且水平视野达到150度的」，可以申请小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车准驾车型。听力一项：有听力障碍但佩戴助听设备能够辨别声源方向的，可以申请小型汽车、小型自动挡汽车准驾车型，驾驶时应当佩戴助听设备。第八十五条规定，办理残疾人专用小型自动挡载客汽车驾驶证业务时提交的身体条件证明，应当由经省级卫生健康行政部门认定的专门医疗机构出具。持这一准驾车型的人应当每三年进行一次身体检查，在记分周期结束后三十日内提交身体条件证明。第七十八条规定，驾驶时应当按规定在车身设置残疾人机动车专用标志（全国，公安部令第 172 号修正，2025 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-15"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-16', 'concept_archive_s33-16', 'recommendation', 'Cochrane 系统综述纳入 29 项试验、5902 名参与者，比较有组织的住院卒中单元照护和其他照护方式。随访到末次（中位 1 年）时，不良结局（死亡、残障或者需要机构照护）的比值比是 0.77（95% CI 0.69–0.87，可信范围），死亡的比值比是 0.76（95% CI 0.66–0.88），死亡或者依赖他人的比值比是 0.75（95% CI 0.66–0.85），证据质量中等。换算成绝对数，每 100 人接受卒中单元照护，多 2 人存活、多 6 人住在家里、多 6 人生活自理。另一方面，AVERT 试验在 5 个国家的 56 个急性卒中单元随机分配 2104 名患者，比较「常规照护」和「常规照护加超早期高强度活动」。三个月时结局良好（改良 Rankin 量表 0—2 分）的，超早期组 480 人（46%），常规组 525 人（50%），调整后比值比 0.73（95% CI 0.59–0.90，P=0.004）。死亡是 88 人比 72 人，没有做出差别（比值比 1.34，95% CI 0.93–1.93，P=0.113）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-16"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-17', 'concept_archive_s33-17', 'recommendation', 'ACHIEVE 试验在美国 4 个社区做，纳入 977 名 70 到 84 岁、有未经治疗的听力损失、没有明显认知障碍的人。随机分成两组，一组接受听力干预（听力咨询和配助听器），一组接受健康教育对照，每 6 个月随访一次。主要终点是 3 年的整体认知评分变化。合并两个来源人群的主要分析里，两组没有显著差别：听力干预组 −0.200（95% CI −0.256 到 −0.144），对照组 −0.202（95% CI −0.258 到 −0.145），差值 0.002（95% CI −0.077 到 0.081），P=0.96。一项预设的敏感性分析显示，干预效果在两个来源人群之间存在差异（交互作用 P=0.010）。来自那项长期心血管健康观察研究的参与者年龄更大、认知下降的危险因素更多、基线认知分更低。研究者的结论是，听力干预可能在认知下降风险较高的人群里减少 3 年的认知变化，在风险较低的人群里则不能。试验没有报告归因于研究的严重不良事件', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-17"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-18', 'concept_archive_s33-18', 'recommendation', '《民法典》第二十一条：「不能辨认自己行为的成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。」第二十二条：「不能完全辨认自己行为的成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其智力、精神健康状况相适应的民事法律行为。」第二十四条：「不能辨认或者不能完全辨认自己行为的成年人，其利害关系人或者有关组织，可以向人民法院申请认定该成年人为无民事行为能力人或者限制民事行为能力人。」同条还规定，被认定之后，经本人、利害关系人或者有关组织申请，人民法院可以根据其智力、精神健康恢复的状况，认定其恢复为限制民事行为能力人或者完全民事行为能力人。有关组织包括：居民委员会、村民委员会、学校、医疗机构、妇女联合会、残疾人联合会、依法设立的老年人组织、民政部门等。第二十三条规定，无民事行为能力人、限制民事行为能力人的监护人是其法定代理人（全国，2021 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-18"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-19', 'concept_archive_s33-19', 'recommendation', '《民法典》第二十八条：无民事行为能力或者限制民事行为能力的成年人，由下列有监护能力的人按顺序担任监护人：「（一）配偶；（二）父母、子女；（三）其他近亲属；（四）其他愿意担任监护人的个人或者组织，但是须经被监护人住所地的居民委员会、村民委员会或者民政部门同意。」第三十一条：对监护人的确定有争议的，由被监护人住所地的居民委员会、村民委员会或者民政部门指定，对指定不服的可以向人民法院申请指定，也可以直接向人民法院申请。指定时「应当尊重被监护人的真实意愿，按照最有利于被监护人的原则」。指定之前权益处于无人保护状态的，由居民委员会、村民委员会、法律规定的有关组织或者民政部门担任临时监护人。第三十三条：「具有完全民事行为能力的成年人，可以与其近亲属、其他愿意担任监护人的个人或者组织事先协商，以书面形式确定自己的监护人」。第一千一百八十八条：「无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。」有财产的，从本人财产中支付赔偿费用，不足部分由监护人赔偿。第一千一百八十九条：监护人将监护职责委托给他人的，监护人仍应当承担侵权责任，受托人有过错的承担相应的责任（全国，2021 年 1 月 1 日起施行）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-19"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s33-20', 'concept_archive_s33-20', 'recommendation', '《残疾人保障法》第三条：「禁止基于残疾的歧视。禁止侮辱、侵害残疾人。」第三十八条：「在职工的招用、转正、晋级、职称评定、劳动报酬、生活福利、休息休假、社会保险等方面，不得歧视残疾人。」同条还规定，残疾职工所在单位应当根据残疾职工的特点提供适当的劳动条件和劳动保护，并根据实际需要对劳动场所、劳动设备和生活设施进行改造。第六十四条：「违反本法规定，在职工的招用等方面歧视残疾人的，由有关主管部门责令改正；残疾人劳动者可以依法向人民法院提起诉讼。」《残疾人就业条例》第四条：「禁止在就业中歧视残疾人。」第十三条：用人单位不得在晋职、晋级、评定职称、报酬、社会保险、生活福利等方面歧视残疾职工。《法律援助法》第四十二条规定，申请人有材料证明属于「无固定生活来源的未成年人、老年人、残疾人等特定群体」的，免予核查经济困难状况。第四十五条规定，法律援助机构为老年人、残疾人提供法律援助服务的，应当根据实际情况提供无障碍设施设备和服务（全国）', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s33-20"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-1', 'concept_archive_s34-1', 'recommendation', '美国 22 家医院用 6 年时间连续登记了 662 例急性肝衰竭。其中 275 例（42%）是对乙酰氨基酚造成的，吞下的剂量中位数是 24 克。这 275 人里，131 人（48%）是不小心吃多的，不是故意。不小心吃多的人里，38% 同时吃了两种以上含这个成分的药。这 275 人里，27% 没等到换肝就死了，8% 做了肝移植。国家药监局 2020 年要求非处方药说明书写明：过量使用会引起严重肝损伤，建议一日最大量不超过 2 克。说明书还要写明，尽量避免和含对乙酰氨基酚或其他解热镇痛药的药品合用。美国法规要求这类非处方药在警示第一条写明三种伤肝情形：超过一天最大量，和其他含对乙酰氨基酚的药同吃，用药期间每天喝 3 杯以上的酒。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-1"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-2', 'concept_archive_s34-2', 'recommendation', '瑞氏综合征会引起脑病和肝脏脂肪变性，通常出现在流感或水痘之后。美国 1981 到 1997 年的全国监测里，18 岁以下报告了 1207 例。82% 的病孩血里测得到水杨酸，这是阿司匹林这类药的成分。总病死率 31%。1980 年开始发布水杨酸类药的警告。那一年报告了 555 例，是高峰，1987 年起每年不超过 36 例。国家食药监局 2011 年规定，尼美舒利口服制剂禁止用于 12 岁以下儿童。国家药监局 2020 年规定安乃近片禁用于 18 岁以下青少年儿童。含安乃近的复方青蒿安乃近片、重感灵片和重感灵胶囊同样禁用于 18 岁以下。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-2"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-3', 'concept_archive_s34-3', 'recommendation', '这类药叫非甾体抗炎药，常见的有布洛芬、萘普生、双氯芬酸。一项荟萃分析汇总了 280 项这类药对安慰剂的随机试验，共 124513 人。和安慰剂比，上消化道穿孔、梗阻或出血的风险：布洛芬 RR 3.97（95% CI 2.22–7.10，约 4 倍），萘普生 4.22（2.71–6.56），双氯芬酸 1.89（1.16–3.09）。所有这类药都让心力衰竭的风险大约翻倍。美国法规要求这类非处方药写明胃出血警示。警示列出风险更高的六种人：60 岁以上，有过胃溃疡或出血，在吃抗凝药或激素，同时吃别的这类药，用药期间每天喝 3 杯以上的酒，吃得比说明书多或久。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s34-3"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-4', 'concept_archive_s34-4', 'recommendation', '国家药监局 2021 年第 57 号公告修订了 14 个品种的说明书，包括氨酚麻美口服溶液、小儿氨酚黄那敏颗粒、小儿氨酚烷胺颗粒等。新增警示语是「不建议家长或监护人自行给2岁以下婴幼儿使用本品，应在医师或药师的指导下使用」。注意事项加了「应严格按照药品说明书用法用量使用，避免用药过量」。还加了「应避免合并使用含有相同或相似活性成份的抗感冒药」。一篇 Cochrane 系统综述纳入 29 项随机对照试验，其中 10 项在儿童身上做。儿童试验里，这几类药都不比安慰剂好：止咳药，抗组胺药（抗过敏成分），抗组胺药加减充血剂（通鼻子的成分），止咳药加支气管扩张剂。21 项研究报告了不良反应，含抗组胺药和右美沙芬的制剂不良反应更多。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-4"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-5', 'concept_archive_s34-5', 'recommendation', '美国食品药品监督管理局（FDA）2020 年 10 月发布安全警示。怀孕约 20 周以后使用非甾体抗炎药，可能引起胎儿肾脏问题，导致羊水过少。警示同时管处方药和非处方药，包括阿司匹林、布洛芬、萘普生、双氯芬酸、塞来昔布。FDA 查了截至 2017 年 7 月的不良事件报告，找到 35 例羊水过少或新生儿肾功能不全，全是严重结局。其中 5 例新生儿死亡，都伴有新生儿肾衰竭。文献里，多数羊水过少在停药后 72 小时到 6 天内恢复。FDA 建议孕妇 20 周以后不要用这类药，除非医生明确这么建议。81 毫克的小剂量阿司匹林由医生开来治孕期特定问题的，不受这条限制。需要止痛退烧时，FDA 提到可以用对乙酰氨基酚等其他药，先问药师或医生。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-5"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-6', 'concept_archive_s34-6', 'recommendation', '国家药监局 2022 年第 68 号公告把奥美拉唑肠溶片从处方药转成非处方药，同时发布说明书范本。范本写的适应症是「胃酸过多引起的烧心和反酸症状的短期缓解」。注意事项写明：使用不得超过 7 天，症状没缓解要咨询医师或药师。两个月以内不得再次服用，症状反复要立即就医。吞咽困难或疼痛、呕血、便血或黑便时请勿使用，这些可能是严重情况的征兆。出现明显消瘦、反复呕吐、吞咽困难、呕血或黑便这类报警症状时，要先排除恶性肿瘤，因为治疗可能掩盖症状、延误诊断。55 岁以上出现新的症状或症状有变化，要咨询医生。在吃氯吡格雷的人要避免同时吃奥美拉唑。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-6"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-7', 'concept_archive_s34-7', 'recommendation', '一篇 Cochrane 系统综述汇总了 6 项随机试验、1147 人。感冒吃抗生素和吃安慰剂比，没好或症状持续的比例没有明显差别（RR 0.83，95% CI 0.60–1.14，差别不显著）。不良反应的风险是安慰剂组的 1.8 倍（95% CI 1.01–3.21）。其中成人 2.62 倍（1.32–5.18），儿童没有增加（0.91，0.51–1.63）。流脓鼻涕不到 10 天的急性脓性鼻炎，吃抗生素也没有明确好处（RR 0.73，0.47–1.13）。不良反应却多了（RR 1.46，1.10–1.94，高约 46%）。作者结论是：这两种情况都不推荐常规用抗生素。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s34-7"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-8', 'concept_archive_s34-8', 'recommendation', '世界卫生组织的腹泻治疗手册写明，「止泻」药和止吐药对儿童急性或迁延性腹泻没有实际益处。它们不能预防脱水，也不能改善营养。有些有危险的、有时致命的副作用，绝不能给 5 岁以下儿童用。洛哌丁胺这类减慢肠蠕动的药，可能引起严重的麻痹性肠梗阻，可以致命，还可能拖长感染。手册还写明，糖太多的饮料会把身体里的水吸进肠子，造成高钠性脱水，比如软饮料和市售果汁饮料。世卫手册推荐的是低渗配方，总渗透压 245 mOsm/L。和旧配方比，它让计划外的静脉输液少了 33%。一篇 Cochrane 综述汇总 8 项试验，结果相近（OR 0.59，95% CI 0.45–0.79，少约四成）。', true, 1.0, 'very_strong', 'supported', 1, '{"src_archive_s34-8"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-9', 'concept_archive_s34-9', 'recommendation', '国际头痛学会的《国际头痛疾病分类》第 3 版给了诊断标准。原本有头痛病的人，每月头痛 15 天以上，同时规律过量使用治头痛的药超过 3 个月。对乙酰氨基酚、阿司匹林、布洛芬这类非阿片止痛药，过量的门槛是每月 15 天及以上。复方止痛药的门槛是每月 10 天及以上。复方止痛药指两类以上有止痛作用的药合在一起，或者加了咖啡因这类辅助成分，比如对乙酰氨基酚加可待因。几种非阿片止痛药轮着吃，天数合起来算。分类说明写明，多个国家的流行病学证据显示，每月头痛 15 天以上的人里，超过一半属于这种头痛。多数病人停掉过量的药后会好转，预防头痛的治疗也更起作用。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-9"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-10', 'concept_archive_s34-10', 'recommendation', '美国急诊监测数据估计，2004 到 2013 年，不满 6 岁的孩子背着大人误吃药品，看了约 64 万次急诊（估计值 640161 次）。2013 年一年约 5.9 万次（59092 次）。2010 到 2013 年，最常见的是口服处方药片剂，占 45.9%。处方药里最常见的是阿片类止痛药（13.8%）和苯二氮䓬类安眠镇静药（12.7%）。美国 5 家中毒控制中心 2017 年问了打电话求助的家长。孩子误吃处方药的，30.7% 吃的是祖父母的药。一半以上（51.5%）的处方药，在孩子拿到之前已经被大人从原包装里取了出来。国内的《国家危险废物名录（2025 年版）》把家庭日常生活中产生的废药品及其包装物，列为生活垃圾中的危险废物。上海的分类投放指引把废药品归入有害垃圾，写明包括过期药物、药物胶囊、药片、药品内包装，「废弃药品宜连带包装一并投放」。上海还规定，药店收集的市民家庭过期废弃药品，由各区市场监管部门设临时中转点。美国 FDA 说，处理过期和用不上的药，最好的办法是交给回收点。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-10"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_archive_s34-11', 'concept_archive_s34-11', 'recommendation', '这叫双硫仑样反应。福建省药监局 2023 年的安全用药科普说，部分头孢类药物服药前后饮酒，可能引发这种反应，「会严重损害健康甚至导致生命危险」。症状有面部潮红、出汗、心悸，甚至呼吸困难、血压下降、过敏性休克。科普按《中华人民共和国药典临床用药须知》列出的药，有头孢唑林、头孢曲松、头孢哌酮、甲硝唑、替硝唑、呋喃唑酮等。科普写明「用药后 7 天内禁止饮酒和食用含酒精的药物、食物等」，例子有酒心巧克力和藿香正气水。理由是被药抑制的那种酶，常要 4 到 5 天才能恢复。广州一家医院整理了 2 年里的 82 例病例。由头孢类引起的 57 例（69.51%），硝基咪唑类（甲硝唑、替硝唑这类）10 例（12.20%）。酒精来自酒类饮料的 40 例（48.78%），来自含乙醇药物的 31 例（37.80%）。口服的有藿香正气水、止咳糖浆、益母草流浸膏等。82 例里轻度 68 例、中度 9 例、重度 5 例，1 到 3 小时内缓解，没有死亡。美国甲硝唑说明书要求，用药期间和停药后至少 3 天不喝酒，也不用含丙二醇的产品。', true, 1.0, 'strong', 'supported', 1, '{"src_archive_s34-11"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB001', 'concept_blindspot_LB001', 'fact', '适当热处理可降低微生物风险，密封则减少再次污染；不同产品的配方和工艺不同。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S005","src_b150_S006","src_b150_S008"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB002', 'concept_blindspot_LB002', 'fact', '商业罐藏食品的目标之一就是做成货架稳定产品；开封后再冷藏则是另一回事。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S008","src_b150_S006"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB003', 'concept_blindspot_LB003', 'fact', '开封后应按普通易腐食品处理，及时冷藏并尽快食用。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S008","src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB004', 'concept_blindspot_LB004', 'fact', '食品保存是一整套技术体系，防腐剂只是其中一种工具。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S005","src_b150_S006"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB005', 'concept_blindspot_LB005', 'fact', '不同国家和食品类别的日期制度不同；对货架稳定食品，日期往往与品质变化有关。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S005","src_b150_S006","src_b150_S008"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB006', 'concept_blindspot_LB006', 'fact', '冷藏能延缓腐败，但并不能让食品无限期安全。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S004","src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB007', 'concept_blindspot_LB007', 'fact', '解冻后仍需按食品安全规则处理和烹调。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S007","src_b150_S008"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB008', 'concept_blindspot_LB008', 'fact', '只要食品一直安全储存，冷冻烧通常影响的是质量而非自动意味着有毒。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S006","src_b150_S008"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB009', 'concept_blindspot_LB009', 'fact', '易腐食品不应在室温久放；美国 USDA 建议易腐食品室温不超过2小时，炎热环境不超过1小时。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB010', 'concept_blindspot_LB010', 'fact', '安全取决于原料、储存和加热全过程；某些耐热毒素或化学危害不是重新加热就能解决。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S006","src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB011', 'concept_blindspot_LB011', 'fact', '食品安全判断不能只靠鼻子和眼睛。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S005","src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB012', 'concept_blindspot_LB012', 'fact', '安全控制的重点是避免交叉污染和彻底烹调，而不是用水把鸡肉“洗干净”。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB013', 'concept_blindspot_LB013', 'fact', '不同食材和污染物需要不同处理；不要把普通冲洗理解为灭菌。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S005","src_b150_S007"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB014', 'concept_blindspot_LB014', 'fact', 'USDA 对面包、软水果、软奶酪等发霉食品建议丢弃。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S009"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB015', 'concept_blindspot_LB015', 'fact', '食品结构和含水量影响霉菌是否可能深入内部。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S009"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB016', 'concept_blindspot_LB016', 'fact', '在美国 FDA 语境中，“natural”有一定政策含义，但并不等于更健康，也不涵盖所有生产方法。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S010"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB017', 'concept_blindspot_LB017', 'fact', '美国有机标签由 USDA NOP 管理，和营养标签是两套规则。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S011"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB018', 'concept_blindspot_LB018', 'fact', '一包食品可能含多个 servings；吃完整包时要按总量重新计算。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S012"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB019', 'concept_blindspot_LB019', 'fact', '牛奶、水果等天然含糖食品即使不添加糖，也可能有 total sugars。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S013"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB020', 'concept_blindspot_LB020', 'fact', '标签是按法规阈值和规定的每份量计算的，不要把营销语言当成化学意义上的绝对零。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S013","src_b150_S012"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB021', 'concept_blindspot_LB021', 'fact', '完整水果和果汁的咀嚼、纤维结构、摄入速度不同。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S014","src_b150_S013"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB022', 'concept_blindspot_LB022', 'fact', '精制、细碎、糊化程度高的碳水食物仍可能有较高血糖反应。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S014","src_b150_S012"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB023', 'concept_blindspot_LB023', 'fact', '研究测得的不同粥类 GI 差异很大，不能把一个食物类别一刀切。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S014"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB024', 'concept_blindspot_LB024', 'fact', '参考指南和大型试验并没有把普通复合维生素证明成替代健康饮食的万能方案；有明确缺乏或特殊人群是另一回事。', true, 1.0, 'moderate', 'supported', 1, '{"src_b150_S001","src_b150_S019"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB025', 'concept_blindspot_LB025', 'fact', '没有统一的“体内毒素”需要某个饮料一次性清除。', true, 1.0, 'moderate', 'supported', 1, '{"src_b150_S001","src_b150_S019"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB026', 'concept_blindspot_LB026', 'fact', '长时间、高强度运动或大量出汗场景与普通坐办公室的补水需求不同。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S017","src_b150_S014"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB027', 'concept_blindspot_LB027', 'fact', '是否安全还要看原水质量、污染类型和储存过程；煮沸也不会去除所有化学污染物。', true, 1.0, 'strong', 'supported', 1, '{"src_b150_S005","src_b150_S006"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB028', 'concept_blindspot_LB028', 'fact', '历史文献并没有为“8×8”找到坚实的普遍性科学依据。', true, 1.0, 'moderate', 'supported', 1, '{"src_b150_S015"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_blindspot_LB029', 'concept_blindspot_LB029', 'fact', '人体获得的液体来源不只有白水；是否适合喝更多咖啡是另一个问题。', true, 1.0, 'moderate', 'supported', 1, '{"src_b150_S015","src_b150_S021"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
