INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0499', 'concept_b1000_NEWC0250', 'fact', '版本编号遵循不同项目约定，语义化版本、日期版本和厂商内部版本的含义并不一致。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0500', 'concept_b1000_NEWC0250', 'inference', '兼容性、更新渠道、功能变化与硬件要求也会影响适用性。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0501', 'concept_b1000_NEWC0251', 'fact', '扩展名是文件名的一部分，常用于提示类型，但可以被改名，实际格式通常还需看文件内容和签名。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0502', 'concept_b1000_NEWC0251', 'inference', '文件名可能伪装类型，来源和安全扫描同样重要。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0503', 'concept_b1000_NEWC0252', 'fact', '无损压缩可在解压后恢复原数据；有损压缩会丢弃部分信息，以换取更小文件。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0504', 'concept_b1000_NEWC0252', 'inference', '若每次都重新有损编码，压缩误差可能累积；具体程度取决于参数和工作流程。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0505', 'concept_b1000_NEWC0253', 'fact', '同样像素数量在不同打印尺寸下对应不同像素密度，影响近距离观看时细节表现。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0506', 'concept_b1000_NEWC0253', 'inference', '镜头、对焦、曝光、传感器噪声和处理算法同样重要。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0507', 'concept_b1000_NEWC0254', 'fact', 'OCR要识别字符并推断阅读顺序，低分辨率、倾斜、字体、栏位和手写体都会增加难度。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0508', 'concept_b1000_NEWC0254', 'inference', '表格结构、符号、数字和小数点可能出现错误，尤其重要数据要人工核对。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0509', 'concept_b1000_NEWC0255', 'fact', '识别系统基于声学信号与语言模型推测词语，口音、噪声、上下文和训练数据会影响结果。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0510', 'concept_b1000_NEWC0255', 'inference', '专有名词、否定词、数字和说话人转换都需要抽查。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0511', 'concept_b1000_NEWC0256', 'fact', '识别系统比较图像特征并按阈值判断是否匹配，图像质量、年龄变化、角度和模型训练都影响结果。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0512', 'concept_b1000_NEWC0256', 'inference', '阈值是工程决策，必须考虑误认成本和其他身份核验因素。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0513', 'concept_b1000_NEWC0257', 'fact', '推荐系统通常优化点击、观看、相关性或其他目标，目标函数和数据会影响排序结果。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0514', 'concept_b1000_NEWC0257', 'inference', '个人化排序会筛选展示内容，不能直接推断整体人群观点或事实重要性。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0515', 'concept_b1000_NEWC0258', 'fact', '生成模型根据训练和上下文预测文本，不等于每次都通过数据库验证事实；复杂或冷门细节尤其需要核实。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0516', 'concept_b1000_NEWC0258', 'inference', '引文可能不支持对应主张，链接可能失效或被误配，重要事实需要核对原始来源。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0517', 'concept_b1000_NEWC0259', 'fact', '若系统把高互动内容当作成功信号，愤怒、争议或极端表达有时会被更多传播。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0518', 'concept_b1000_NEWC0259', 'inference', '传播机制衡量的可能是注意力而不是准确性，仍需独立核查证据。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0519', 'concept_b1000_NEWC0260', 'fact', '生成模型可合成逼真的脸部、声音或视频片段，使传统的视觉直觉不足以可靠鉴别。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0520', 'concept_b1000_NEWC0260', 'inference', '来源链、上下文、独立证据和可信核验工具通常更有价值。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0521', 'concept_b1000_NEWC0261', 'fact', '人们可能更容易注意、相信或记住支持已有看法的信息，而忽略反例。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0522', 'concept_b1000_NEWC0261', 'inference', '检索策略会塑造接触到的证据；主动寻找最强反方论据有助于发现盲点。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0523', 'concept_b1000_NEWC0262', 'fact', '人们判断数量或价值时，可能受到最先出现的数字影响，即使该数字与真实价值关系不大。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0524', 'concept_b1000_NEWC0262', 'inference', '先独立估算范围、收集可比价格并了解替代方案，有助于减少锚定影响。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0525', 'concept_b1000_NEWC0263', 'fact', '容易想起或画面鲜明的事件，可能被高估为更常见或更可能发生。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0526', 'concept_b1000_NEWC0263', 'inference', '媒体曝光度、记忆鲜明程度和实际发生率并不相同，需要查看基准数据。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0527', 'concept_b1000_NEWC0264', 'fact', '只观察留下来或成功的案例，会忽略退出、失败或未被看见的样本。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0528', 'concept_b1000_NEWC0264', 'inference', '缺少失败对照和替代解释，无法判断必要条件、充分条件或因果关系。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0529', 'concept_b1000_NEWC0265', 'fact', '人们可能低估任务所需时间，即使过去做过类似任务也会发生。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0530', 'concept_b1000_NEWC0265', 'inference', '复杂任务受依赖、返工、等待和不确定性影响，历史实际耗时常比理想估计更有参考价值。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0531', 'concept_b1000_NEWC0266', 'fact', '在某些情境下，人们对损失的心理反应可能强于同等收益带来的满足感。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0532', 'concept_b1000_NEWC0266', 'inference', '决策时可先定义目标、风险限额与退出规则，避免只围绕已经付出的成本判断。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0533', 'concept_b1000_NEWC0267', 'fact', '已经无法收回的时间或金钱不应自动成为继续投入的理由，未来收益与成本才是关键。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0534', 'concept_b1000_NEWC0267', 'inference', '可比较从现在开始的替代方案，而不是把过去支出当作可回收资产。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0535', 'concept_b1000_NEWC0268', 'fact', '一个突出特征可能影响对其他特征的整体判断，例如外表、自信或名校背景影响能力评价。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0536', 'concept_b1000_NEWC0268', 'inference', '针对具体能力收集多种证据，比由单一印象推断全面素质更可靠。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0537', 'concept_b1000_NEWC0269', 'fact', '观察他人行为时，人们有时高估性格因素、低估当时环境和约束。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0538', 'concept_b1000_NEWC0269', 'inference', '交通、健康、照护和信息沟通都可能影响行为，判断前应了解情境。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0539', 'concept_b1000_NEWC0270', 'fact', '记忆在提取时会受到线索、期待、后续信息和重构过程影响，细节可能被改变。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0540', 'concept_b1000_NEWC0270', 'inference', '主观确信度与客观准确性并非总是一致，重要事件应尽早保留记录。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0541', 'concept_b1000_NEWC0271', 'fact', '注意力在任务间切换会带来重新定位目标、恢复上下文和抑制干扰的成本。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0542', 'concept_b1000_NEWC0271', 'inference', '对于需要连续推理的工作，批量处理相似任务和减少切换通常更有帮助。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0543', 'concept_b1000_NEWC0272', 'fact', '眼神、姿势和微表情受文化、焦虑、习惯与情境影响，单一线索难以准确判断撒谎。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
