INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0547', 'concept_b1000_NEWC0274', 'fact', '在某些紧急情境中，责任分散和对他人反应的观察可能降低个人行动概率，但效果受情境影响。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
