INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0801', 'concept_b1000_NEWC0401', 'fact', '常见水处理可能包括混凝、沉淀、过滤和消毒等阶段，用于去除不同类别的杂质或病原风险。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
