INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0838', 'concept_b1000_NEWC0419', 'inference', '过强眩光、光线不均和阴影可能影响视觉舒适与辨识，应关注照明质量而不仅是亮度。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
