INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0965', 'concept_b1000_NEWC0483', 'fact', '质量描述物体惯性与物质量相关属性；重量是重力作用产生的力，会随重力场变化。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0966', 'concept_b1000_NEWC0483', 'fact', '月球重力较小，因此重量下降；质量本身不会因为换地点而同样变化。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0967', 'concept_b1000_NEWC0484', 'fact', '体积描述空间大小，容量通常表示容器能容纳多少，质量描述物体质量；密度联系质量与体积。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0968', 'concept_b1000_NEWC0484', 'fact', '同体积材料因密度不同而质量不同。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0969', 'concept_b1000_NEWC0485', 'fact', '净重通常是内容物质量，毛重包含包装，皮重是包装或容器本身的质量，具体标签用法需看标准。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0970', 'concept_b1000_NEWC0485', 'inference', '计算方式不同会改变计价基准，需要核对合同、物流条款或商品说明。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0971', 'concept_b1000_NEWC0486', 'fact', '测量结果只应表达与仪器和方法精度相称的位数，过多小数可能给人虚假的精确感。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0972', 'concept_b1000_NEWC0486', 'inference', '输入值的误差和测量方法限制仍然存在。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0973', 'concept_b1000_NEWC0487', 'fact', '校准建立仪器读数与参考标准之间的关系；验证是判断设备或方法是否满足规定要求，实际流程依标准而定。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0974', 'concept_b1000_NEWC0487', 'inference', '传感器漂移、损坏或环境条件可能影响准确度，重要测量需按规定校准或核查。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0975', 'concept_b1000_NEWC0488', 'fact', '误差可来自测量不确定性、系统偏差或随机波动；人为错误则可能是操作或记录失误，处理方式不同。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0976', 'concept_b1000_NEWC0488', 'inference', '重复测量有助于估计随机变化，但系统偏差可能持续存在。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0977', 'concept_b1000_NEWC0489', 'fact', '同一字母组合可能被多个专业、组织或产品重复使用，语境决定含义。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0978', 'concept_b1000_NEWC0489', 'inference', '仅靠字母搜索可能得到错误领域的解释。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0979', 'concept_b1000_NEWC0490', 'fact', '词语会随着社会使用、借词、隐喻和语法变化而改变含义，现代用法未必等于最初来源。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0980', 'concept_b1000_NEWC0490', 'inference', '当代含义应参考实际用法、词典与语境，而非只靠历史起源。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0981', 'concept_b1000_NEWC0491', 'fact', '不同地区可能使用日/月/年或月/日/年等格式，纯数字日期会产生歧义。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
