INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0989', 'concept_b1000_NEWC0495', 'fact', '时间计量依赖精密物理标准，而时区边界与法定时间还由行政和社会选择决定。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0990', 'concept_b1000_NEWC0495', 'inference', '当地时间标签发生变化，物理经过时间仍需按实际时间间隔计算。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0991', 'concept_b1000_NEWC0496', 'fact', '现代计量标准逐步用可复现的物理常数定义单位，以提升稳定性和跨实验室一致性。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0992', 'concept_b1000_NEWC0496', 'inference', '更新通常是为了让单位基础更稳定，而实际量值会按连续性和转换规则处理。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0993', 'concept_b1000_NEWC0497', 'fact', '比例尺表达地图距离与实际距离的对应关系；地图缩放后，屏幕上的标尺或比例信息也可能变化。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0994', 'concept_b1000_NEWC0497', 'inference', '道路、水域、坡度、边界和交通网络会使直线距离与真实路线距离不同。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0995', 'concept_b1000_NEWC0498', 'fact', '公差描述某个尺寸或性能允许偏离目标值的范围，具体含义由图纸、标准和测量方法定义。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0996', 'concept_b1000_NEWC0498', 'fact', '更严格的公差可能要求更精密的加工、环境控制与测量设备，成本影响还取决于工艺和批量。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0997', 'concept_b1000_NEWC0499', 'fact', '条码通常编码商品或物流识别信息，读码系统需连接数据库或业务记录才能获取相关资料。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0998', 'concept_b1000_NEWC0499', 'inference', '条码可能被复制或错误使用，真伪还需核对包装、防伪体系、渠道和供应商信息。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL0999', 'concept_b1000_NEWC0500', 'fact', '商标用于区分特定经营者的商品或服务，通用名称则指向一类产品；法律认定因地区、使用方式和证据而异。', true, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, claim_type, claim_text, canonical, confidence, evidence_level, status, version, source_ids, created_at, updated_at) VALUES ('claim_b1000_NEWCL1000', 'concept_b1000_NEWC0500', 'inference', '注册范围、商品类别、使用证据和当地法律都会影响商标权利。', false, 1.0, 'uncertain', 'supported', 1, '{}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-1', 'concept_archive_s1-1', 'claim_archive_s1-1', 'action', 'life_archive', '系安全带，前排后排都系', '1. 不要早死', '坐前排系上安全带，出车祸时被撞死的概率大约降一半。坐轻型卡车前排的降六成。美国 2022 年死在车里的人，能查到系没系带的，有一半没系。', '后排也要系。同一份报告里，第二排被撞死的人有 60% 没系带。45%、60% 这两个数，是美国交通安全主管部门（NHTSA）拿事故数据库算出来的估计（引 Kahane 2015），不是随机分组的试验。WHO 那个中国死亡人数是推算出来的，比公安交管登记的数字高好几倍。两边统计的范围不一样，这里只用 WHO 的口径。', NULL, NULL, NULL, '不花钱。每次上车多花 2 秒。', '美国交通安全主管部门（NHTSA）估计，系安全带能让轿车前排乘员受致命伤的风险下降 45%。轻型卡车前排下降 60%。2022 年美国死在乘用车（载人的小汽车）里的人当中，能查到系没系带的，有 50% 没系。世界卫生组织（WHO）的口径是，安全带让车内人员的死亡风险最多降低 50%。WHO 估计中国 2021 年死于道路交通事故的有 248,099 人，相当于每 10 万人里死 17.4 人', '后排也要系。同一份报告里，第二排被撞死的人有 60% 没系带。45%、60% 这两个数，是美国交通安全主管部门（NHTSA）拿事故数据库算出来的估计（引 Kahane 2015），不是随机分组的试验。WHO 那个中国死亡人数是推算出来的，比公安交管登记的数字高好几倍。两边统计的范围不一样，这里只用 WHO 的口径。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-2', 'concept_archive_s1-2', 'claim_archive_s1-2', 'action', 'life_archive', '骑摩托车、电动自行车戴头盔并扣好', '1. 不要早死', '戴头盔并且把扣带扣好，摩托车骑手出事时死亡的概率低约四成。头部受伤低约七成。扣带要系紧，松松垮垮挂在头上不算戴。', '头盔要把扣带扣好，挂在车把上不算戴。上面的数据来自摩托车。电动自行车没有直接研究，是照着推过来的，因为撞上以后头部受伤的方式相同。', NULL, NULL, NULL, '买一顶 100 到 300 元。每次戴上花 5 秒。', 'Cochrane 把多项研究合起来一起算。摩托车骑行者戴头盔，死亡风险下降 42%。原值 OR 0.58，可信范围 95% CI 0.50 到 0.68。头部损伤下降 69%（OR 0.31，95% CI 0.25 到 0.38）', '头盔要把扣带扣好，挂在车把上不算戴。上面的数据来自摩托车。电动自行车没有直接研究，是照着推过来的，因为撞上以后头部受伤的方式相同。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-3', 'concept_archive_s1-3', 'claim_archive_s1-3', 'action', 'life_archive', '装烟雾报警器；冬天在室内烧煤、用燃气取暖的再装一氧化碳报警器', '1. 不要早死', '一个能正常工作的烟雾报警器，能把住宅火灾里死亡的概率降约六成。起火时有四成人在睡觉，光靠鼻子是醒不过来的。冬天在屋里烧煤或用燃气的，再加一个一氧化碳报警器。中国 2018 年有 1.15 万人死于一氧化碳中毒，冬天那三个月七成死在家里。', '给 B 的原因：烟雾报警器这边只有一项研究，做法是回头比对出事和没出事的家庭，不是随机分组的试验。一氧化碳报警器本身没有降低死亡率的研究。这里的收益是按「中毒死亡集中在冬季、集中在家中」推出来的。', NULL, NULL, NULL, '烟雾报警器一个 30 到 100 元。一氧化碳报警器一个 50 到 150 元。装好以后每年换一次电池。', '美国北卡罗来纳州研究了一批住宅火灾，回头比对出事和没出事的家庭。家里有一个能正常工作的烟雾报警器，死亡风险下降约六成。原值 OR 0.39，可信范围 95% CI 0.18 到 0.83。美国 2018 到 2020 年，有人住的住宅里发生的致死火灾，24% 家里没有烟雾报警器，41% 起火时人在睡觉。中国 2018 年报告一氧化碳中毒死亡 11,523 例。这些死亡里，12 月有 72.59%、1 月有 67.42%、2 月有 66.48% 发生在家中', '给 B 的原因：烟雾报警器这边只有一项研究，做法是回头比对出事和没出事的家庭，不是随机分组的试验。一氧化碳报警器本身没有降低死亡率的研究。这里的收益是按「中毒死亡集中在冬季、集中在家中」推出来的。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-4', 'concept_archive_s1-4', 'claim_archive_s1-4', 'action', 'life_archive', '燃气软管和灶具到期就换，不自己改管道，燃气公司上门推销可以直接拒绝', '1. 不要早死', '一根合规软管几十块。到期就换，这是《城镇燃气管理条例》写明的用户义务。自己改管道、拆燃气表是条例明令禁止的。同一部条例还写了，燃气公司不能要求你买它指定的产品和服务。上门说「必须换」的推销，可以直接拒绝。', '条例原文能逐字核对，但它只说明到期换管是你的义务，不说明换了能少出多少事故。按年限换管能把燃气事故降多少，没找到官方统计数字，所以只给 C 级。有人以「安检」名义上门，检查完就推销自闭阀和报警器。条例第二十条第六项不许燃气公司要求你买它指定的产品，你可以拒绝，也可以投诉。闻到燃气味，先关燃气总阀，瓶装气关钢瓶阀门。再开门开窗通风，别开排气扇。电灯、抽油烟机这些电器一律别开也别关，打火机也别碰。然后人撤出去，离开现场再打燃气公司的报警电话。一氧化碳中毒是另一件事，见第 13 节。', NULL, NULL, NULL, '一根合规的燃气软管几十元。灶具几年换一次。换的时候顺手看一眼有没有过期。', '条例把「及时更换国家明令淘汰或者使用年限已届满的燃气燃烧器具、连接管」写成了用户的义务：灶具和软管到了年限或者被国家淘汰了，你就要换。条例还把「擅自安装、改装、拆除户内燃气设施和燃气计量装置」列为禁止行为，自己动手改管道、拆燃气表都在里面。条例同时明确，燃气经营者不得要求用户购买它指定的产品，也不得要求用户接受它提供的服务', '条例原文能逐字核对，但它只说明到期换管是你的义务，不说明换了能少出多少事故。按年限换管能把燃气事故降多少，没找到官方统计数字，所以只给 C 级。有人以「安检」名义上门，检查完就推销自闭阀和报警器。条例第二十条第六项不许燃气公司要求你买它指定的产品，你可以拒绝，也可以投诉。闻到燃气味，先关燃气总阀，瓶装气关钢瓶阀门。再开门开窗通风，别开排气扇。电灯、抽油烟机这些电器一律别开也别关，打火机也别碰。然后人撤出去，离开现场再打燃气公司的报警电话。一氧化碳中毒是另一件事，见第 13 节。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","C 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-5', 'concept_archive_s1-5', 'claim_archive_s1-5', 'action', 'life_archive', '不采、不买、不吃野生蘑菇，任何「土办法鉴别」都不成立', '1. 不要早死', '光 2025 年一年，全国就有 828 起蘑菇中毒，2165 人中招，13 人死。那一年还新认出 34 种以前没记录过会毒人的蘑菇。银针试毒、虫子吃过就没毒、颜色鲜艳才有毒，这些说法全都不成立。', '吃错了就立刻催吐，然后带上剩下的蘑菇或者拍的照片去医院。毒蘑菇中毒分好几种类型，认出是哪一种蘑菇直接决定医生怎么治。每年都有新种类被记录到能毒人，所以「本地人认得清」这个前提本身站不住。银针验毒、和大蒜同煮、虫子吃过就没毒、颜色鲜艳才有毒，这些说法全都不成立。', NULL, NULL, NULL, '不花钱。难的地方是放弃一种季节性的野味。', '中国疾控中心 2025 年调查了 828 起蘑菇中毒事件，涉及 2165 人，死亡 13 人。病死率 0.6%，指中毒的人里有 0.6% 死亡。2019 到 2024 年每年 276 到 676 起，病死率在 0.87% 到 2.86% 之间。光 2025 年就鉴定出 138 种有毒蘑菇，其中 34 种是国内第一次记录到会引起中毒', '吃错了就立刻催吐，然后带上剩下的蘑菇或者拍的照片去医院。毒蘑菇中毒分好几种类型，认出是哪一种蘑菇直接决定医生怎么治。每年都有新种类被记录到能毒人，所以「本地人认得清」这个前提本身站不住。银针验毒、和大蒜同煮、虫子吃过就没毒、颜色鲜艳才有毒，这些说法全都不成立。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-6', 'concept_archive_s1-6', 'claim_archive_s1-6', 'action', 'life_archive', '电动自行车不推进楼道、不进电梯、不在家里充电', '1. 不要早死', '把电动车推进楼道、推进电梯，或者在家里充电，应急管理部的《高层民用建筑消防安全管理规定》明令禁止。不改正的，个人罚 500 到 1000 元，做生意的罚 2000 到 10000 元。罚款还是小事，要紧的是这种火正好烧在你唯一的逃生通道上。', '别买改装电池，别用杂牌充电器，别整夜充着不管。锂电池一旦起火，几十秒里就整片烧开，同时冒出剧毒的烟。车停在楼道里起火，烧的就是你唯一的逃生通道。应急管理部公布的数字是，2021 年全国电动自行车火灾 1.8 万起，死 65 人。其中烧在建筑物里的 3782 起，死了 60 人，死者几乎都在室内。2024 年整治之后，火灾起数比上年降了 42.2%，伤亡降了九成以上，那一年的绝对数没有公布。', NULL, NULL, NULL, '不花钱。难的地方是每次都停到楼下的集中充电点，多走几十米。', '应急管理部的规章明文禁止：「禁止在高层民用建筑公共门厅、疏散走道、楼梯间、安全出口停放电动自行车或者为电动自行车充电」。楼门厅、走道、楼梯间、安全出口这几处，既不能停车也不能充电。拒不改正的，不做生意的单位和个人罚 500 至 1000 元，做生意的罚 2000 至 10000 元', '别买改装电池，别用杂牌充电器，别整夜充着不管。锂电池一旦起火，几十秒里就整片烧开，同时冒出剧毒的烟。车停在楼道里起火，烧的就是你唯一的逃生通道。应急管理部公布的数字是，2021 年全国电动自行车火灾 1.8 万起，死 65 人。其中烧在建筑物里的 3782 起，死了 60 人，死者几乎都在室内。2024 年整治之后，火灾起数比上年降了 42.2%，伤亡降了九成以上，那一年的绝对数没有公布。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-7', 'concept_archive_s1-7', 'claim_archive_s1-7', 'action', 'life_archive', '量血压，高了就吃药降到达标', '1. 不要早死', '血压每降 10 mmHg，出大的心血管毛病的概率降两成，中风降 27%，心衰降 28%，死亡概率降 13%。中国 35 到 75 岁的人里，44.7% 有高血压，真正控制住的只有 7.2%。', '先去量一次血压。中国 10 个高血压的人里只有不到 1 个控制住了，所以量这一次是本书里性价比最高的动作之一。降到多少算达标（130 还是 140）还有讨论，但「知道自己高血压并把它降下来」这件事本身没有争议。', NULL, NULL, NULL, '电子血压计 100 到 200 元。量一次 1 分钟。降压药多数每月几元到几十元。难的地方是没症状也要接着吃。', '把 123 项试验、61 万余人合起来一起算。收缩压每降 10 mmHg，主要心血管事件低约两成。原值 RR 0.80，可信范围 95% CI 0.77 到 0.83。收缩压就是血压两个数里高的那个。卒中（中风）低约 27%（RR 0.73）。心力衰竭低约 28%（RR 0.72）。总死亡率下降 13%（RR 0.87，95% CI 0.84 到 0.91）。中国给 35 到 75 岁的 170 万人做过筛查：44.7% 有高血压。这些人里，知道自己有的占 44.7%，在治疗的占 30.1%，控制住的只有 7.2%', '先去量一次血压。中国 10 个高血压的人里只有不到 1 个控制住了，所以量这一次是本书里性价比最高的动作之一。降到多少算达标（130 还是 140）还有讨论，但「知道自己高血压并把它降下来」这件事本身没有争议。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-8', 'concept_archive_s1-8', 'claim_archive_s1-8', 'action', 'life_archive', '35 岁以后只要超重，就去查一次空腹血糖，正常也每三年再查', '1. 不要早死', '花几十块抽一管血，就能在一点症状都没有的时候查出糖尿病前期。美国官方的筛查建议是：35 到 70 岁、超重或肥胖的人去查。查出来正常的，每三年再查一次。美国按体重指数 25 算超重，对亚裔放宽到 23；中国标准是 24 就算超重。', '查出糖尿病前期不等于就要吃药。相当一部分人光靠改生活方式就能把它扭回去。中国成人里，知道自己有糖尿病的一直是少数，很多人是等到出了并发症才发现', NULL, NULL, NULL, '空腹血糖十几元。糖化血红蛋白几十元。去医院抽一次血就行。', '美国预防服务工作组是美国官方给筛查建议的机构。它现在的建议是：对 35 到 70 岁、超重或肥胖的成年人筛查糖尿病前期和 2 型糖尿病，哪怕一点症状都没有。超重指体重指数 ≥25，肥胖指 ≥30。对亚裔美国人，它建议把界线降到体重指数 ≥23，因为同样的体重指数下，亚裔的糖尿病风险更高。中国的行业标准是：体重指数 24.0 到 28.0 之间算超重，≥28.0 算肥胖。这条建议的推荐等级是 B。它还写明：「对血糖正常的成年人，每 3 年筛查一次是合理的做法」', '查出糖尿病前期不等于就要吃药。相当一部分人光靠改生活方式就能把它扭回去。中国成人里，知道自己有糖尿病的一直是少数，很多人是等到出了并发症才发现', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-9', 'concept_archive_s1-9', 'claim_archive_s1-9', 'action', 'life_archive', '开车不超速、不酒驾', '1. 不要早死', '平均车速每高 1%，撞死人的概率高约 4%。酒精没有「喝一点没事」的安全线。血里的酒精浓度还很低的时候，风险就已经开始往上走了。', '速度和死亡的那组 1%、4%，是按事故模型推算出来的，不是随机分组的试验。酒驾这边 WHO 只给了方向，没给数字。「喝多少、风险涨多少」这个问题，本节没有核实过原始文献。', NULL, NULL, NULL, '不花钱。开慢一点，一趟多花几分钟。难的地方是饭局上少喝。', '世界卫生组织（WHO）的说法：平均车速每升高 1%，出人命的事故风险升高 4%。酒驾的风险，从很低的血液酒精浓度起就开始上升', '速度和死亡的那组 1%、4%，是按事故模型推算出来的，不是随机分组的试验。酒驾这边 WHO 只给了方向，没给数字。「喝多少、风险涨多少」这个问题，本节没有核实过原始文献。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-10', 'concept_archive_s1-10', 'claim_archive_s1-10', 'action', 'life_archive', '给 4 岁以下儿童用安全座椅，不要抱在怀里', '1. 不要早死', '一岁以下的婴儿坐安全座椅，车祸里受致命伤的概率低约七成。1 到 4 岁的孩子低约一半。抱在怀里没有这个效果，急刹车时你也抱不住。', '按说明书把座椅固定好，装错等于没装。1 岁以下要反向安装，让孩子面朝车尾。上面的数字是美国官方拿事故数据估出来的。', NULL, NULL, NULL, '一个 300 到 2000 元，能用几年。每次上车多花 1 分钟把孩子绑好。', '美国交通安全主管部门（NHTSA）估计，用安全座椅能让轿车里 1 岁以下婴儿受致命伤的风险下降 71%。1 到 4 岁的幼儿下降 54%。世界卫生组织（WHO）的口径是婴儿死亡下降 71%', '按说明书把座椅固定好，装错等于没装。1 岁以下要反向安装，让孩子面朝车尾。上面的数字是美国官方拿事故数据估出来的。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-11', 'concept_archive_s1-11', 'claim_archive_s1-11', 'action', 'life_archive', '家里有小孩就给窗户和阳台装限位器，纱窗不算防护', '1. 不要早死', '一副限位器几十块钱。纽约市给高风险住户免费装窗户护栏、又上门讲解，一个区上报的儿童坠落数三年里降了一半。后来纽约干脆立法，要求房东给住着小孩的房子装护栏。纱窗一推就开，不算防护。', '窗边和阳台边不要放床、沙发、箱子这类小孩能爬上去的东西。纱窗只挡蚊子，一推就掉，别把它当护栏。也不是只有住高层才要装：美国那份数据里，多数坠落发生在二层或者更低。', NULL, NULL, NULL, '一副窗户限位器或者儿童安全锁几十元。装上去十分钟。', '纽约市从 1972 年起办了一个叫「孩子不会飞」的项目，在高风险城区免费发窗户护栏，还上门讲解。布朗克斯区上报的坠落数，1973 到 1975 年下降 50%。此后纽约市修改卫生法典，强制房东为住有 10 岁及以下儿童的公寓安装窗户护栏', '窗边和阳台边不要放床、沙发、箱子这类小孩能爬上去的东西。纱窗只挡蚊子，一推就掉，别把它当护栏。也不是只有住高层才要装：美国那份数据里，多数坠落发生在二层或者更低。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-12', 'concept_archive_s1-12', 'claim_archive_s1-12', 'action', 'life_archive', '儿童近水不离视线，划船、野泳穿救生衣', '1. 不要早死', '落水的时候穿着救生衣，淹死的概率大约只有不穿的一半。溺水至今是中国 1 到 14 岁孩子的头号死因。农村的溺水死亡率大约是城市的两倍。', 'A 级只对应救生衣这一半。「不离视线」是大家的共识，单算只有 C 级，没有随机试验，以后也不会有。中国的溺水死亡集中在农村、夏季，以及 15 到 19 岁的男性。冬天上冰面玩，见第 41 条（野外冰面先量厚度）。', NULL, NULL, NULL, '救生衣 50 到 200 元。另外要搭上看着孩子的那份注意力。', '用美国海岸警卫队的数据做的研究，把条件相近的人配成对来比。坐休闲船只落水的人，穿着救生衣的溺亡风险低约一半。原值是校正后 RR 0.51，可信范围 95% CI 0.35 到 0.74。中国 20 岁以下的溺水死亡率，从 2013 年的每 10 万人 6.60 人降到 2021 年的每 10 万人 3.28 人。农村约为城市的 2 倍。溺水仍然是 1 到 14 岁儿童的头号死因。2021 年 0 到 19 岁的伤害死亡里，溺水占 31.1%，道路交通占 27.9%', 'A 级只对应救生衣这一半。「不离视线」是大家的共识，单算只有 C 级，没有随机试验，以后也不会有。中国的溺水死亡集中在农村、夏季，以及 15 到 19 岁的男性。冬天上冰面玩，见第 41 条（野外冰面先量厚度）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-13', 'concept_archive_s1-13', 'claim_archive_s1-13', 'action', 'life_archive', '60 岁以上练平衡和腿部力量，改造家里的浴室和楼梯', '1. 不要早死', '每周练两三次平衡，比如太极，老人跌倒的次数降约两成三，摔过的人数降 15%。家里做防滑、装扶手，再降约两成。跌倒是中国 65 岁以上老人因伤害死亡的头号原因，而且一多半就摔在自己家里。', '这条适用于住在自己家里、不在养老院的 60 岁以上老人。上面的研究数的是跌倒次数，不是死亡人数。老人从跌倒到髋部骨折、再到死亡，这段路很短。看不清路也会多摔，白内障影响看路的见第 17 节第 9 条（白内障手术）。骨头经不经得起摔，见本节第 39 条（骨密度检查）。', NULL, NULL, NULL, '每周练 2 到 3 次，每次 30 分钟太极或者平衡训练。浴室防滑垫、扶手、夜灯几十到几百元。难的地方是要长期练下去。', 'Cochrane 把 108 项试验、23,407 人合起来一起算。运动让老年人跌倒的次数下降 23%。原值是跌倒率之比 RaR 0.77，可信范围 95% CI 0.71 到 0.83。摔过的人数下降 15%（RR 0.85）。请人到家里做安全评估和改造，跌倒率下降约两成（RR 0.81，95% CI 0.68 到 0.97）。练太极，跌倒风险低约 29%（RR 0.71）。在中国，跌倒是 65 岁以上老人因伤害死亡的头号原因。2018 年监测到的老年人跌倒，55.97% 发生在家中', '这条适用于住在自己家里、不在养老院的 60 岁以上老人。上面的研究数的是跌倒次数，不是死亡人数。老人从跌倒到髋部骨折、再到死亡，这段路很短。看不清路也会多摔，白内障影响看路的见第 17 节第 9 条（白内障手术）。骨头经不经得起摔，见本节第 39 条（骨密度检查）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-14', 'concept_archive_s1-14', 'claim_archive_s1-14', 'action', 'life_archive', '查乙肝两对半，没有抗体就打疫苗', '1. 不要早死', '查一次几十块。启东那项跟踪了 30 年的试验里，一出生就打了乙肝疫苗的人，后来得原发性肝癌的概率低 84%，身上带着乙肝病毒的比例低 72%。成人查出没抗体的补三针，半年打完，一两百块。', '这条适用于 1992 年前出生、没打过疫苗或者抗体已经消失的成人。肝癌下降 84% 那个数来自一出生就打的人。同一项试验里，到青少年才补打的，防住病毒携带的效力只有 21%。成人打主要图的是不再被感染，不能直接套那个 84%。已经感染的人打疫苗没用，要去肝病科定期复查。怎么算已经感染：化验单上乙肝表面抗原 HBsAg 那一项是阳性。', NULL, NULL, NULL, '查一次几十元。成人乙肝疫苗 3 针合起来 100 到 300 元。半年之内打完。', '启东那项试验按群体随机分组，不是按个人分组，跟踪了 30 年。新生儿接种乙肝疫苗，原发性肝癌下降 84%。可信范围是 95% CI 23% 到 97%。乙肝表面抗原 HBsAg 阳性率下降 72%（95% CI 68% 到 75%），这个阳性率就是查出身上带着病毒的人所占的比例。中国全人群的 HBsAg 阳性比例，1992 到 2014 年下降 52%，5 岁以下下降 97%', '这条适用于 1992 年前出生、没打过疫苗或者抗体已经消失的成人。肝癌下降 84% 那个数来自一出生就打的人。同一项试验里，到青少年才补打的，防住病毒携带的效力只有 21%。成人打主要图的是不再被感染，不能直接套那个 84%。已经感染的人打疫苗没用，要去肝病科定期复查。怎么算已经感染：化验单上乙肝表面抗原 HBsAg 那一项是阳性。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-15', 'concept_archive_s1-15', 'claim_archive_s1-15', 'action', 'life_archive', '被铁钉、木刺扎到或者伤口沾了泥土，当天去处理，顺便问破伤风要不要打', '1. 不要早死', '破伤风一旦发病，大约每 10 个人里死 1 个。深的伤口、沾了泥土的伤口风险最高。伤口脏、离上一针满 5 年的，要加强 1 针。当天去处理花不了几十块，别拖到伤口肿起来再说。', '到了医院让医生判断，别自己拿主意，也别嫌麻烦不问。不是所有伤口都要打。医生会看伤口属于哪一档，再问你上一次打针是什么时候，然后决定。「小时候打过就一辈子有效」是错的。伤口脏的话，离上一针满 5 年就要加强。所以去之前想一想自己最后一次打破伤风针是哪一年。', NULL, NULL, NULL, '挂号加处理伤口几十元。医生说要打的话，疫苗或者免疫球蛋白几十到几百元。', '美国的破伤风病例里，大约每 10 例死 1 例。深的伤口、被泥土污染的伤口，风险更高。中国 2024 年的诊疗规范把伤口分成两档。6 小时内处理、没沾泥土粪便和动物口水的浅伤口，算低风险。超过 6 小时才处理、沾了这些东西，或者是扎伤、撕脱伤、挤压伤、烧烫伤、冻伤、伤口里留着异物的，算高风险。打过 3 针以上、最后一针不到 5 年的，什么都不用打。5 到 10 年的，高风险伤口加强 1 针。满 10 年的，不管哪档都加强 1 针。没打全 3 针或者记不清的，要把疫苗补全，高风险伤口还要同时打被动免疫制剂（免疫球蛋白或抗毒素这类直接给抗体的针）', '到了医院让医生判断，别自己拿主意，也别嫌麻烦不问。不是所有伤口都要打。医生会看伤口属于哪一档，再问你上一次打针是什么时候，然后决定。「小时候打过就一辈子有效」是错的。伤口脏的话，离上一针满 5 年就要加强。所以去之前想一想自己最后一次打破伤风针是哪一年。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-16', 'concept_archive_s1-16', 'claim_archive_s1-16', 'action', 'life_archive', '女性接种 HPV 疫苗，越早越好', '1. 不要早死', '瑞典 167 万女性的数据里，17 岁以前打过 HPV 疫苗的人，后来得浸润性宫颈癌的概率只有没打的约八分之一。17 到 30 岁才打的，也只有一半左右。所以越早打越值。', '9 到 14 岁打收益最大。17 到 30 岁打，还有一半以上的下降。30 岁以后打，收益就一路变小。打过疫苗也还是要做宫颈癌筛查，疫苗替代不了筛查，见第 18 条（30 岁以上女性做宫颈癌筛查）。', NULL, NULL, NULL, '国产二价约 300 多元一针，进口九价约 1300 元一针。一共打 2 到 3 针。每次跑一趟，半天。', '瑞典跟踪了 167 万名女性做统计：打过疫苗的人，浸润性宫颈癌的发病率比没打的低。17 岁以前接种的低约 88%（IRR 0.12，95% CI 0.00 到 0.34，括号里是原值和它的可信范围）。17 到 30 岁接种的低约 53%（IRR 0.47，95% CI 0.27 到 0.75）', '9 到 14 岁打收益最大。17 到 30 岁打，还有一半以上的下降。30 岁以后打，收益就一路变小。打过疫苗也还是要做宫颈癌筛查，疫苗替代不了筛查，见第 18 条（30 岁以上女性做宫颈癌筛查）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-17', 'concept_archive_s1-17', 'claim_archive_s1-17', 'action', 'life_archive', '女性 40 岁起做乳腺癌筛查，每两年一次钼靶', '1. 不要早死', '40 到 74 岁的女性每两年拍一次钼靶，这是美国官方筛查建议里明确推荐的。75 岁以上，以及给致密乳腺加做超声和磁共振，官方的结论是证据还不够。体检套餐拿这些加钱的时候，可以不买。', '从几岁开始查，各国不一样，中国有些指南和地方项目是从 45 岁起。父母、子女或者亲兄弟姐妹得过乳腺癌的，以及带有 BRCA 突变的，属于高危，要单独找医生定方案，本条不适用', NULL, NULL, NULL, '钼靶每次两三百元。很多地区有免费筛查项目。每两年花半天。', '美国预防服务工作组是美国官方给筛查建议的机构。它现在的建议是：「建议 40 至 74 岁女性每两年做一次筛查性乳腺 X 线摄影」。乳腺 X 线摄影就是平时说的钼靶。这条建议的推荐等级是 B。对 75 岁及以上的女性，以及给致密型乳腺补做超声、磁共振，它都判定为「现有证据不足」', '从几岁开始查，各国不一样，中国有些指南和地方项目是从 45 岁起。父母、子女或者亲兄弟姐妹得过乳腺癌的，以及带有 BRCA 突变的，属于高危，要单独找医生定方案，本条不适用', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-18', 'concept_archive_s1-18', 'claim_archive_s1-18', 'action', 'life_archive', '30 岁以上女性做宫颈癌筛查，优先 HPV 检测', '1. 不要早死', '印度农村那项试验里，一辈子只做过一次 HPV 检测的女性，死于宫颈癌的概率低约一半，查出晚期宫颈癌的概率低约五成。一次一两百块，结果阴性能管 5 年。', '打过 HPV 疫苗的人也要筛查，因为疫苗盖不住全部的病毒型别。这项研究少见的地方是：它是随机分组的筛查试验，直接拿死亡人数当结果，而且只筛了一轮。', NULL, NULL, NULL, 'HPV 检测一次 100 到 300 元。结果阴性的，5 年查一次就行。取样几分钟。', '印度农村那项试验按群体随机分组，不是按个人分组。对象是 30 到 59 岁的女性。只做一次 HPV 检测筛查，死于宫颈癌的风险就低约 48%。原值 HR 0.52，可信范围 95% CI 0.33 到 0.83。查出晚期宫颈癌的风险低约 53%（HR 0.47，95% CI 0.32 到 0.69）', '打过 HPV 疫苗的人也要筛查，因为疫苗盖不住全部的病毒型别。这项研究少见的地方是：它是随机分组的筛查试验，直接拿死亡人数当结果，而且只筛了一轮。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-19', 'concept_archive_s1-19', 'claim_archive_s1-19', 'action', 'life_archive', '45 到 50 岁起做结直肠癌筛查，做查大便隐血的粪便免疫化学检测或者肠镜', '1. 不要早死', '每一两年做一次几十块的粪便隐血检查，死于结直肠癌的概率低约 16%，至少查过一轮的人低 25%。被叫去做一次肠镜的人，往后十年得结直肠癌的概率从 1.20% 降到 0.98%。', '争议。NordICC 是按「被邀请去做肠镜」的人来算的，结直肠癌死亡 0.28% 对 0.31%（RR 0.90，95% CI 0.64 到 1.16），差别还在误差范围内。这说明肠镜对死亡率的好处以前被高估过。粪便检测在死亡率上的证据反而更硬。从几岁开始查，各国指南在 45 到 50 岁之间。家里有人得过这个病的要更早开始。', NULL, NULL, NULL, '粪便检测几十元，每 1 到 2 年做一次。肠镜几百到一千多元，结果阴性的 10 年做一次就行。做肠镜前要留出一天清肠。', 'Cochrane 把多项研究合起来一起算。做粪便隐血筛查的人，死于结直肠癌的风险低约 16%。原值 RR 0.84，可信范围 95% CI 0.78 到 0.90。至少参加过一轮的人低约 25%（RR 0.75）。再看 NordICC 那项随机试验。被邀请去做肠镜的人，10 年里结直肠癌的发病从 1.20% 降到 0.98%。原值 RR 0.82，可信范围 95% CI 0.70 到 0.93', '争议。NordICC 是按「被邀请去做肠镜」的人来算的，结直肠癌死亡 0.28% 对 0.31%（RR 0.90，95% CI 0.64 到 1.16），差别还在误差范围内。这说明肠镜对死亡率的好处以前被高估过。粪便检测在死亡率上的证据反而更硬。从几岁开始查，各国指南在 45 到 50 岁之间。家里有人得过这个病的要更早开始。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-20', 'concept_archive_s1-20', 'claim_archive_s1-20', 'action', 'life_archive', '有心血管病的人和老年人每年打流感疫苗', '1. 不要早死', '心梗之后打流感疫苗的那项试验里，一年内死亡的比例从 4.9% 降到 2.9%。有心血管病的人和老人，每年秋天补一针，50 到 150 元。', '争议。A 级只对应有心血管病的人。对本来健康的老年人，Cochrane 综述只给出一个结论：一季流感的发病从 6% 降到 2.4%。它把这条证据的可信度评为「低」，死亡率方面的证据评为「极低」。综述出处是 Demicheli V 等 2018 年那篇。', NULL, NULL, NULL, '一针 50 到 150 元。每年秋天打一次。', '一项试验在心肌梗死之后做，2571 人随机分组。医生和病人都不知道打的是哪一针。打流感疫苗的人，12 个月里的总死亡率是 2.9%。打安慰剂的是 4.9%。原值 HR 0.59，可信范围 95% CI 0.39 到 0.89。安慰剂就是不含有效成分的对照针。心血管死亡的 HR 是 0.59。另一项研究把多项研究合起来一起算。打流感疫苗的人主要心血管事件为 3.6%，对照为 5.4%。原值 RR 0.66，可信范围 95% CI 0.53 到 0.83。心血管死亡 RR 0.74（95% CI 0.42 到 1.30，这点差别还在误差范围内，算不上有统计学意义）', '争议。A 级只对应有心血管病的人。对本来健康的老年人，Cochrane 综述只给出一个结论：一季流感的发病从 6% 降到 2.4%。它把这条证据的可信度评为「低」，死亡率方面的证据评为「极低」。综述出处是 Demicheli V 等 2018 年那篇。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-21', 'concept_archive_s1-21', 'claim_archive_s1-21', 'action', 'life_archive', '50 岁以后打带状疱疹疫苗', '1. 不要早死', '三期试验里，这支疫苗把带状疱疹挡掉了 97%，各个年龄段都差不多。缺点是两针三四千元全自费。这笔钱买回来的，是九成七的发病率降幅。', '它在性价比上排得靠后，原因是贵。带状疱疹本身很少要命，麻烦在带状疱疹后神经痛，可能疼上几个月到几年。打完疫苗，打针的地方疼、发烧的比例都不低。其中最重的那一档（三级症状）是 17.0% 对 3.2%', NULL, NULL, NULL, '重组带状疱疹疫苗要打两针，合计约 3000 到 4000 元。这笔钱全部自己出。', '一项三期试验跨 18 个国家，有 1.54 万人。试验把人随机分成两组，一组打疫苗，一组打对照针，平均跟踪 3.2 年。结果疫苗组 6 例、安慰剂组 210 例发生带状疱疹。换算成每千人年是 0.3 对 9.1，每千人年的意思是 1000 个人观察一年里出现的例数。原文写「疫苗对带状疱疹的总体效力为 97.2%（95% CI 93.7–99.0，P&lt;0.001）」。各年龄组的效力在 96.6% 到 97.9% 之间', '它在性价比上排得靠后，原因是贵。带状疱疹本身很少要命，麻烦在带状疱疹后神经痛，可能疼上几个月到几年。打完疫苗，打针的地方疼、发烧的比例都不低。其中最重的那一档（三级症状）是 17.0% 对 3.2%', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 多","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-22', 'concept_archive_s1-22', 'claim_archive_s1-22', 'action', 'life_archive', '65 岁以上打肺炎球菌疫苗', '1. 不要早死', '8.45 万老人的试验里，13 价肺炎球菌疫苗把疫苗管得住的那几型肺炎挡掉约 46%，把最凶险的侵袭性感染挡掉 75%。但对「所有原因的肺炎」没看出效果，别指望它管住全部肺炎。', '它只防疫苗覆盖的那几个型别，不是打了就不得肺炎。中国老年人常打的是 23 价多糖疫苗，和这项试验用的 13 价结合疫苗不是同一种，上面的效力数据不能直接套过去', NULL, NULL, NULL, '几百元。部分地区对老年人免费。', '荷兰把 8.45 万名 65 岁以上老人随机分成两组来比。用的是 13 价肺炎球菌结合疫苗。它对疫苗覆盖型肺炎的效力是 45.6%。可信范围是 95.2% CI 21.8–62.5。疫苗覆盖型就是这支疫苗管得住的那几个菌型。对侵袭性肺炎球菌病的效力是 75.0%（95% CI 41.4–90.8），这是最凶险的那一类感染。对全部原因加在一起的肺炎，它没有效果', '它只防疫苗覆盖的那几个型别，不是打了就不得肺炎。中国老年人常打的是 23 价多糖疫苗，和这项试验用的 13 价结合疫苗不是同一种，上面的效力数据不能直接套过去', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-23', 'concept_archive_s1-23', 'claim_archive_s1-23', 'action', 'life_archive', '查幽门螺杆菌，阳性就根除', '1. 不要早死', '山东临朐那项跟踪了 22 年的试验里，把幽门螺杆菌根除掉的人，后来得胃癌的概率低约一半，死于胃癌的概率低约四成。查一次一两百块，根除要吃两周药。', '根除以后还可能再感染，所以家里人一起查、一起治。这项试验的人群是胃癌高发区的居民。住在低发区的人，实际拿到的好处会小得多。', NULL, NULL, NULL, '碳 13 或碳 14 呼气试验 100 到 200 元。根除要同时吃四种药，两周药费 200 到 500 元。难的地方是这两周的药要按点吃满。', '山东临朐那项随机分组的试验跟踪了 22 年。做过幽门螺杆菌根除治疗的人，得胃癌的风险低约一半。原值 OR 0.48，可信范围 95% CI 0.32 到 0.71。死于胃癌的风险低约 38%（HR 0.62，95% CI 0.39 到 0.99）', '根除以后还可能再感染，所以家里人一起查、一起治。这项试验的人群是胃癌高发区的居民。住在低发区的人，实际拿到的好处会小得多。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-24', 'concept_archive_s1-24', 'claim_archive_s1-24', 'action', 'life_archive', '重度吸烟者每年做一次低剂量胸部 CT', '1. 不要早死', '符合条件的重度吸烟者每年做一次低剂量 CT，死于肺癌的概率比只拍胸片低 20%，总的死亡概率低 6.7%。代价是查出可疑结果后的复查，和那一段时间的提心吊胆。', '这条只适用于高危吸烟者。同一项试验里，做低剂量 CT 的人有 24.2% 查出可疑结果，这些人里 96.4% 是虚惊一场（假阳性）。不吸烟的人做这项检查，等于花钱买焦虑。', NULL, NULL, NULL, '一次 200 到 400 元，10 分钟做完。另外要算上虚惊一场之后的复查，和那段时间的提心吊胆。', '美国 NLST 随机试验收了 53,454 人，都是 55 到 74 岁、吸烟史 30 包年以上、戒烟不超过 15 年的人。包年是算烟量的单位，每天一包抽一年算一包年。结果是这样。做低剂量 CT 的人比只拍胸片的人，肺癌死亡相对下降 20.0%。可信范围 95% CI 6.8 到 26.7。总死亡率相对下降 6.7%，可信范围 95% CI 1.2 到 13.6', '这条只适用于高危吸烟者。同一项试验里，做低剂量 CT 的人有 24.2% 查出可疑结果，这些人里 96.4% 是虚惊一场（假阳性）。不吸烟的人做这项检查，等于花钱买焦虑。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-25', 'concept_archive_s1-25', 'claim_archive_s1-25', 'action', 'life_archive', '抑郁或有自杀念头时打 12356，家里不囤安眠药和农药', '1. 不要早死', '把能要命的东西从手边拿走，这类做法的证据一直在变强：管住镇痛药以后，相关自杀降 43%；常有人跳楼的地方装上防护，降 86%。所以家里不囤安眠药和农药。想不开的时候先打 12356，全国通用，每天至少开 18 小时。', '给 B 的原因：限制手段那边的证据多数是生态学研究，做法是比较政策出台前后的数字；热线本身没有降低死亡率的证据。自杀的冲动往往只持续几分钟到几小时，把能致死的东西挪远一步，本身就是干预。这个时间尺度的数据，以及未遂之后的长期结局，见本节第 32 条（自杀念头一冒出来先告诉身边的一个人）。被救回来之后会留下什么，见本节第 33 条。', NULL, NULL, NULL, '不花钱。打一个电话。另外把药锁起来，农药不放在家里。', '一篇把近 10 年的研究系统梳理了一遍的综述：限制人拿到致死手段，这方面的证据一直在增强。管控镇痛药以后，和镇痛药有关的自杀下降 43%。常有人跳楼的地点加了防护之后，下降 86%（79% 到 91%，括号里是这个数的可信范围）。学校里开展的认知类项目，让自杀未遂低约 55%（OR 0.45，95% CI 0.24 到 0.85）。治抑郁的药物和心理治疗，是预防自杀的重要一环。中国从 2025 年 5 月 1 日起，全国拨 12356 都能接通心理援助热线，每天开通不少于 18 小时', '给 B 的原因：限制手段那边的证据多数是生态学研究，做法是比较政策出台前后的数字；热线本身没有降低死亡率的证据。自杀的冲动往往只持续几分钟到几小时，把能致死的东西挪远一步，本身就是干预。这个时间尺度的数据，以及未遂之后的长期结局，见本节第 32 条（自杀念头一冒出来先告诉身边的一个人）。被救回来之后会留下什么，见本节第 33 条。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-26', 'concept_archive_s1-26', 'claim_archive_s1-26', 'action', 'life_archive', '备齐灭火器、灭火毯、逃生呼吸面罩和急救包，每年检查一次', '1. 不要早死', '灭火器、灭火毯、逃生面罩、急救包，都在应急管理部那份 11 样的家庭应急清单里。一套几百元，买一次就行。上门做过家庭安全指导的那些研究里，伤害发生率低约四分之一。', '争议。同一份 Cochrane 汇总里，不发装备的那一类干预，受伤率低约两成。原值 IRR 0.78，可信范围 95% CI 0.66 到 0.92。发了装备的那一组并没有做得更好。降低伤害的主要是入户教育和改造，所以装备的收益记「中」，不记「大」。买灭火器认准 CCC 标志，贮压式的指针要停在绿区。灭火毯多是玻璃纤维的，只抓那两根拉带，别光着手摸毯面。拿它盖油锅也有争议：荷兰监管机构 2014 年测了 22 个牌子，按普通人的用法没有一个能稳定扑灭。油锅着火先关火、盖锅盖。烟雾报警器和一氧化碳报警器见本节第 3 条。止血带的用法见第 13 节第 12 条。每样东西怎么选、放在哪里、几年换一次，见 [docs/家庭应急装备清单.md](../docs/家庭应急装备清单.md)', NULL, NULL, NULL, '灭火器、灭火毯、每人一只呼吸面罩，再加一个急救包，一套几百元。买一次就行，以后每年花十分钟检查一遍。', '应急管理部的《全国基础版家庭应急物资储备建议清单》一共 11 样。其中「灭火器和灭火毯」用于「初起火灾的扑救」，清单还写明「灭火毯可披覆在身上逃生」。「呼吸面罩」指的是「消防过滤式自救呼吸器，用于火灾逃生使用」。「外用药品」是「止血粉、止血贴、纱布绷带等，用于处理伤口」。Cochrane 把 98 项研究、2,605,044 人合起来一起算。家庭安全干预让伤害发生率降到 IRR 0.89。可信范围是 95% CI 0.78 到 1.01。其中上门开展的干预，伤害发生率低约 25%（IRR 0.75，95% CI 0.62 到 0.91）', '争议。同一份 Cochrane 汇总里，不发装备的那一类干预，受伤率低约两成。原值 IRR 0.78，可信范围 95% CI 0.66 到 0.92。发了装备的那一组并没有做得更好。降低伤害的主要是入户教育和改造，所以装备的收益记「中」，不记「大」。买灭火器认准 CCC 标志，贮压式的指针要停在绿区。灭火毯多是玻璃纤维的，只抓那两根拉带，别光着手摸毯面。拿它盖油锅也有争议：荷兰监管机构 2014 年测了 22 个牌子，按普通人的用法没有一个能稳定扑灭。油锅着火先关火、盖锅盖。烟雾报警器和一氧化碳报警器见本节第 3 条。止血带的用法见第 13 节第 12 条。每样东西怎么选、放在哪里、几年换一次，见 [docs/家庭应急装备清单.md](../docs/家庭应急装备清单.md)', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-27', 'concept_archive_s1-27', 'claim_archive_s1-27', 'action', 'life_archive', '尿里出现肉眼看得见的血，哪怕不疼、哪怕第二天就干净了，也要去查一次', '1. 不要早死', '60 岁以上的人出现一次肉眼看得见的血尿，最后查出膀胱癌的概率约 2.8%，40 到 59 岁约 1.2%。这个数不算高，但也高到必须去查一次。哪怕第二天不出血了也要去查。', '「不疼」是关键。结石和感染引起的血尿，多半同时腰腹绞痛，或者尿频、尿急、尿痛。肿瘤引起的往往一点感觉都没有，而且会自己停几天再出现，很多人就这么放过了。正在吃抗凝药，不是可以不查的理由。剧烈运动之后、女性经期前后的血尿，可以先复查一次再定。收益记「小」，是因为只有检出率，没有「早查能降低多少死亡」的效应量。', NULL, NULL, NULL, '尿常规几十元，泌尿系超声一两百元。医生认为需要的话，再加一个膀胱镜，千元上下。', '英国拿社区全科门诊（初级医疗）的电子病历做了一项研究，4915 例膀胱癌对 21718 例对照。出现肉眼血尿的人里，最后真查出膀胱癌的比例是这样。60 岁以上是 2.8%，可信范围 95% CI 2.5 到 3.1。40 到 59 岁是 1.2%，可信范围 0.6 到 2.3。这个比例的学名叫阳性预测值。只有在显微镜下才看得见的血尿，同样有意义。比值比 20，可信范围 95% CI 12 到 33。60 岁以上这个比例为 1.6%，可信范围 1.2 到 2.1', '「不疼」是关键。结石和感染引起的血尿，多半同时腰腹绞痛，或者尿频、尿急、尿痛。肿瘤引起的往往一点感觉都没有，而且会自己停几天再出现，很多人就这么放过了。正在吃抗凝药，不是可以不查的理由。剧烈运动之后、女性经期前后的血尿，可以先复查一次再定。收益记「小」，是因为只有检出率，没有「早查能降低多少死亡」的效应量。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-28', 'concept_archive_s1-28', 'claim_archive_s1-28', 'action', 'life_archive', '勃起功能出了问题，先去查心血管，别当成单纯的「那方面的事」', '1. 不要早死', '有勃起功能障碍的男性，后来得心血管病的比别人多约四成，心梗多约六成。越年轻的人差得越多。这个毛病常常比胸痛先出现。所以先去查血压、血糖、血脂，别自己买药压过去。', '这 14 项都是跟踪一群人看结果的研究，不是随机分组试验。所以「多四成」是关联，不能当成因果。偶尔一两次不算数，持续三个月以上才按问题看。要查的东西和本节第 7、8 条是同一批：量血压、查空腹血糖，再加血脂、吸烟和腰围。别在网上买「壮阳」保健品。正规的那类药是处方药，说明书把硝酸酯类列为禁忌，正在用硝酸甘油这类药的人不能吃，一起用会让血压骤降。怎么改善见本节第 29 条（减重、戒烟能让勃起功能好转）。收益记「中」不记「大」：44% 是两群人的风险差距，不是「去查一次能降多少死亡」。也不记「小」：本节第 27 条（尿里出现肉眼看得见的血）那种信号只有检出率，而这里查出来的高血压、糖尿病、血脂异常都有现成的治疗办法。', NULL, NULL, NULL, '挂号几十元。量血压、抽血查血糖和血脂，一两百元。跑一趟医院，等几天结果。', '一篇荟萃分析把 14 项跟踪研究合起来算，共 92,757 名男性，平均跟踪 6.1 年。和没有勃起功能障碍的人相比，有这个问题的人后来的风险是这样。总的心血管事件高约 44%（RR 1.44，95% CI 1.27 到 1.63，这是可信范围）。心梗高约 62%（RR 1.62，1.34 到 1.96）。脑血管事件高约 39%（RR 1.39，1.23 到 1.57）。全因死亡高约 25%（RR 1.25，1.12 到 1.39）。心血管死亡那一项没有拉开差距（RR 1.19，0.97 到 1.46）。年龄越轻，倍数越高。本来心血管风险属于中等的那批人，倍数比高风险和低风险的人都高。用问卷判定的研究，算出来的倍数是 1.61（1.38 到 1.86）。只问一句话的研究是 1.27（1.18 到 1.37）', '这 14 项都是跟踪一群人看结果的研究，不是随机分组试验。所以「多四成」是关联，不能当成因果。偶尔一两次不算数，持续三个月以上才按问题看。要查的东西和本节第 7、8 条是同一批：量血压、查空腹血糖，再加血脂、吸烟和腰围。别在网上买「壮阳」保健品。正规的那类药是处方药，说明书把硝酸酯类列为禁忌，正在用硝酸甘油这类药的人不能吃，一起用会让血压骤降。怎么改善见本节第 29 条（减重、戒烟能让勃起功能好转）。收益记「中」不记「大」：44% 是两群人的风险差距，不是「去查一次能降多少死亡」。也不记「小」：本节第 27 条（尿里出现肉眼看得见的血）那种信号只有检出率，而这里查出来的高血压、糖尿病、血脂异常都有现成的治疗办法。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-29', 'concept_archive_s1-29', 'claim_archive_s1-29', 'action', 'life_archive', '减重、戒烟、把血压血糖控住，勃起功能能跟着好转', '1. 不要早死', '把心血管的危险因素管起来，勃起功能本身会好转。用一份问卷打分，平均能多 2 到 3 分。这份问卷总分 25 分，22 分以上算正常。', '这 6 项试验的干预不一样，有的是减重加运动，有的是用药控血压血脂。总共只有 740 人。所以方向明确，具体能好多少因人而异。收益记「小」，是因为终点只有问卷评分，没有「后来少得多少病」的数字。同样这几个动作在别处是有硬终点的：戒烟见第 2 节第 1 条（戒烟，越早越好），减重见第 2 节第 32 条（把 BMI 控制在 20–25），血压见本节第 7 条（量血压，高了就吃药）。吃药本身不是禁区，前提是医生开的处方药。网上卖的「保健品」常偷加这类成分，剂量不明，怎么分辨见第 28 节第 4 条（不买承诺快速瘦的减肥药）。', NULL, NULL, NULL, '不花钱，还可能省钱。难的是长期坚持：管住吃、动起来、把烟戒掉。', '一篇荟萃分析把 6 项随机对照试验、740 名男性合起来算。干预是改生活方式，或者用药控制心血管危险因素，随访至少 6 周。结果：勃起功能问卷（IIEF-5）的评分平均提高 2.66 分（95% CI 1.86 到 3.47，这是可信范围）。把其中用他汀的 2 项试验（143 人）去掉，剩下 4 项纯靠改生活方式的（597 人）仍然提高 2.40 分（1.19 到 3.61）。IIEF-5 是一份 5 个问题的问卷，总分 5 到 25 分。原文按得分分成五档，22 到 25 分算没有障碍，5 到 7 分算重度', '这 6 项试验的干预不一样，有的是减重加运动，有的是用药控血压血脂。总共只有 740 人。所以方向明确，具体能好多少因人而异。收益记「小」，是因为终点只有问卷评分，没有「后来少得多少病」的数字。同样这几个动作在别处是有硬终点的：戒烟见第 2 节第 1 条（戒烟，越早越好），减重见第 2 节第 32 条（把 BMI 控制在 20–25），血压见本节第 7 条（量血压，高了就吃药）。吃药本身不是禁区，前提是医生开的处方药。网上卖的「保健品」常偷加这类成分，剂量不明，怎么分辨见第 28 节第 4 条（不买承诺快速瘦的减肥药）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-30', 'concept_archive_s1-30', 'claim_archive_s1-30', 'action', 'life_archive', '性行为全程用安全套，不和别人共用针具', '1. 不要早死', '每一次都全程戴，异性之间传染艾滋病的概率大约降七成以上。「大部分时候戴」的效果，和不戴差不了多少。梅毒、淋病这些也一并挡住。', '「不规律使用」和「不用」的差距很小，要每次、全程都用才有效。共用针具是另一条独立的高效传播途径，和性行为无关，注射毒品、纹身、穿孔都算。高风险人群还可以用暴露前预防（PrEP），就是事先吃药挡住感染。把 18 项研究合起来算，凡是超过七成人按时吃药的试验，吃 PrEP 的人感染 HIV 的风险比吃安慰剂的低约七成。原值是风险比 0.30，可信范围 95% CI 0.21 至 0.45。按时吃药的人少的那些试验，则看不到保护效果。PrEP 是处方药，去感染科或者疾控问，别自己网购。已经暴露之后怎么办见第 13 节', NULL, NULL, NULL, '一只一两元。难的地方不在钱，在于每一次都用，而且从一开始就戴上。', '一项研究把 25 项研究、10676 对异性伴侣合起来一起算。这些伴侣都是一方感染 HIV、一方没感染，学名叫血清不一致。和从来不用的人相比，坚持每次都用安全套的人，HIV 传播风险低约 71%。原值 RR 0.29，可信范围 95% CI 0.20 至 0.43。和用得断断续续的人相比，低约 77%（RR 0.23，95% CI 0.13 至 0.40）。作者的结论是，安全套虽然不完美，但「坚持使用可使 HIV 传播降低 70% 以上」。同一层保护还覆盖梅毒、淋病、衣原体等其他性传播感染', '「不规律使用」和「不用」的差距很小，要每次、全程都用才有效。共用针具是另一条独立的高效传播途径，和性行为无关，注射毒品、纹身、穿孔都算。高风险人群还可以用暴露前预防（PrEP），就是事先吃药挡住感染。把 18 项研究合起来算，凡是超过七成人按时吃药的试验，吃 PrEP 的人感染 HIV 的风险比吃安慰剂的低约七成。原值是风险比 0.30，可信范围 95% CI 0.21 至 0.45。按时吃药的人少的那些试验，则看不到保护效果。PrEP 是处方药，去感染科或者疾控问，别自己网购。已经暴露之后怎么办见第 13 节', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-31', 'concept_archive_s1-31', 'claim_archive_s1-31', 'action', 'life_archive', '有过高危行为就去查一次艾滋病，疾控中心免费、结果保密', '1. 不要早死', '去疾控查艾滋病不花钱。没有你本人同意，任何单位和个人都不得公开你的姓名、住址、工作单位和病史。查出来也不是判死刑：坚持吃药把病毒压到测不出来的人，不会再传给性伴侣。那项研究跟了七百多对伴侣、七万多次无套性行为，伴侣间传染是零。', '窗口期决定什么时候查才算数。广东省疾控中心的口径是：核酸检测约 1 周、第四代抗原抗体联合检测约 2 周、第三代抗体检测约 3 周可以检出。建议至少 2 周后再查，间隔 2 至 4 周复查一次。最后一次高危行为满 3 个月后，99.99% 以上可以排除感染。自测试剂显示阳性不等于确诊，必须去疾控或者正规机构复核。条例第三条写明，任何单位和个人不得歧视感染者及其家属，婚姻、就业、就医、入学等权益受法律保护。第三十八条同时规定，感染者有义务「将感染或者发病的事实及时告知与其有性关系者」。孕期的三病筛查和母婴阻断见第 27 节', NULL, NULL, NULL, '不花钱。跑一趟疾控或者指定的医疗机构，抽一管血。难的地方是开口去查这一步。', '《艾滋病防治条例》第二十三条写明。县级以上地方人民政府卫生主管部门会指定一些医疗卫生机构。这些机构「应当为自愿接受艾滋病咨询、检测的人员免费提供咨询和初筛检测」。查得早有实际用处：现在的抗病毒治疗能把病毒压到检测不到。世界卫生组织的口径是「接受抗病毒治疗且病毒载量检测不到的感染者不会把 HIV 传染给性伴侣」。PARTNER 研究跟踪了 782 对同性伴侣，每对都是一方感染、一方没感染，学名叫血清不一致。合计 1593 对年（每对跟踪年数相加）。期间共 76088 次无套性行为，出现 15 例新感染。比对病毒基因做系统发育分析之后，这 15 例全部不来自伴侣，伴侣间传播为零。《艾滋病防治条例》第三十九条规定：「未经本人或者其监护人同意，任何单位或者个人不得公开艾滋病病毒感染者、艾滋病病人及其家属的姓名、住址、工作单位、肖像、病史资料以及其他可能推断出其具体身份的信息。」', '窗口期决定什么时候查才算数。广东省疾控中心的口径是：核酸检测约 1 周、第四代抗原抗体联合检测约 2 周、第三代抗体检测约 3 周可以检出。建议至少 2 周后再查，间隔 2 至 4 周复查一次。最后一次高危行为满 3 个月后，99.99% 以上可以排除感染。自测试剂显示阳性不等于确诊，必须去疾控或者正规机构复核。条例第三条写明，任何单位和个人不得歧视感染者及其家属，婚姻、就业、就医、入学等权益受法律保护。第三十八条同时规定，感染者有义务「将感染或者发病的事实及时告知与其有性关系者」。孕期的三病筛查和母婴阻断见第 27 节', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-32', 'concept_archive_s1-32', 'claim_archive_s1-32', 'action', 'life_archive', '自杀念头一冒出来先告诉身边的一个人，把这几十分钟交出去', '1. 不要早死', '自杀未遂的人里将近一半说，从念头冒出来到动手不超过 10 分钟，所以要熬过去的往往就是这几十分钟。四分之三的人那段时间和身边人有过接触，只是没开口。因自伤进过医院的人，1 年后约 2% 死于自杀，9 年以上约 7%，绝大多数人后来没有死于自杀。', '给 B 的原因：Deisenhammer 那项只有 82 人，出自一家医院，靠当事人事后回忆。Owens 那篇给的是 90 项做法各异的研究取中间的那个比例，不是把它们合成一个数。同一篇里还明确写着，自伤者的自杀风险仍是普通人群的几百倍。所以「绝大多数人后来没有死于自杀」说的是这批人整体的情况，不能当成对某一个人的保证，该看的病还是要看。把致死手段挪远和 12356 见本节第 25 条。情绪低落时先做的几件事见第 3 节第 18 条。救回来之后的后遗症见本节第 33 条。身边人流露出这种念头时你能做什么，见第 8 节第 15 条', NULL, NULL, NULL, '不花钱。难的地方是当时开口，以及承认自己这几个小时不能一个人待着。', '82 名自杀未遂者在入院 3 天内接受访谈：47.6%（39 人）说，从这一次第一次冒出自杀念头到真的动手，不超过 10 分钟。这个过程拖得长一些的人，自杀意图评分明显更高。冲动性量表的得分和过程长短没有关系。76.8%（63 人）说，在这段时间里和伴侣、家人或者朋友有过某种接触。作者的结论是：能干预的时间窗通常很短，专业人员在这个阶段能介入的余地有限，所以要把识别信号和干预办法普及到普通人。另有一篇系统综述汇总了 90 项随访研究。因自伤就诊的人，1 年后再次自伤但没死的比例取中间值为 16%。1 年后死于自杀的为 2%。随访 9 年以上的，约 7% 死于自杀', '给 B 的原因：Deisenhammer 那项只有 82 人，出自一家医院，靠当事人事后回忆。Owens 那篇给的是 90 项做法各异的研究取中间的那个比例，不是把它们合成一个数。同一篇里还明确写着，自伤者的自杀风险仍是普通人群的几百倍。所以「绝大多数人后来没有死于自杀」说的是这批人整体的情况，不能当成对某一个人的保证，该看的病还是要看。把致死手段挪远和 12356 见本节第 25 条。情绪低落时先做的几件事见第 3 节第 18 条。救回来之后的后遗症见本节第 33 条。身边人流露出这种念头时你能做什么，见第 8 节第 15 条', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-33', 'concept_archive_s1-33', 'claim_archive_s1-33', 'action', 'life_archive', '别把「救回来」当成兜底：喝农药、吸煤气之后急诊能保住的是命，保不住肺和脑子', '1. 不要早死', '百草枯没有解药，喝下去的人四成多救不回来。它会让肺发炎、慢慢变硬，肾和肝也跟着受伤。煤气中毒被救回来的人，六周后将近一半脑子不如从前，做了高压氧的也还有四分之一。', '给 B 的原因：这几项研究的对象是中毒病人，不是单一的自杀未遂人群，一氧化碳那项试验里还含意外中毒的人。所以上面的后遗症比例，不能直接当成「自杀未遂者的后果概率」。能确定的是，没有哪一种方式能不留后遗症。一氧化碳的现场处置见第 13 节第 19 条。误服农药和药物先别催吐、带上瓶子就医，见第 13 节第 20 条。家里不囤农药和安眠药见本节第 25 条。本书不比较不同方式的致死率，也不写任何具体做法', NULL, NULL, NULL, '不花钱。只是先知道这件事。', '一篇百草枯中毒的系统综述：病死率极高，原因是它本身毒性强，又缺乏有效治疗。它被逆着浓度差主动搬进肺组织，学名叫逆浓度梯度主动摄取，结果是肺炎和肺纤维化，同时还造成肾损伤和肝损伤。综述写明：不应进行洗胃。血液透析和血液灌流不大可能改变临床病程。激素与免疫抑制剂的疗效证据很弱。综述还写了一句：「所有中心的病死率都很高，尽管治疗差异很大」。孟加拉 10 家三级医院 2013 至 2024 年收了 1420 例，其中可分析的 257 例：病死率 43.2%。常见表现是急性肾衰引起的下肢肿胀 71.2%、呕吐 65.8%、腹痛 58.0%。急性一氧化碳中毒的试验是双盲随机分组，两组各 76 人。医生和病人都不知道进的是哪一组。六周时留下认知后遗症的，高压氧组 19/76（25.0%）。常压氧组 35/76（46.1%），P=0.007。把其他因素校正之后 OR 0.45（95% CI 0.22 至 0.92，括号里是这个数的可信范围）。另一项研究连续观察了 73 例：30% 有认知后遗症，12% 出现脑白质高信号。中国自 2014 年 7 月 1 日起撤销百草枯水剂的登记和生产许可，并停止生产。2016 年 7 月 1 日起，水剂在国内停止销售和使用。2020 年 9 月 26 日起，禁止可溶胶剂在境内销售、使用。文件写明，「致使服用百草枯自杀事件时有发生」是加强监管的直接原因', '给 B 的原因：这几项研究的对象是中毒病人，不是单一的自杀未遂人群，一氧化碳那项试验里还含意外中毒的人。所以上面的后遗症比例，不能直接当成「自杀未遂者的后果概率」。能确定的是，没有哪一种方式能不留后遗症。一氧化碳的现场处置见第 13 节第 19 条。误服农药和药物先别催吐、带上瓶子就医，见第 13 节第 20 条。家里不囤农药和安眠药见本节第 25 条。本书不比较不同方式的致死率，也不写任何具体做法', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-34', 'concept_archive_s1-34', 'claim_archive_s1-34', 'action', 'life_archive', '别拿「躺几天就好」赌高处坠落：进了创伤 ICU 的人多数活下来，代价按年算', '1. 不要早死', '从高处摔下来进了创伤 ICU 的人，死亡的只有 5.5%，但伤得重、治得久。将近一半同时伤到三个以上部位，三分之一多上了呼吸机，最长的在 ICU 住了 132 天。一半人摔下来的高度不超过 3 米。伤得重的人，后来能回去上班的不到六成。', '给 B 的原因：坠落那一组是一家医院翻旧病历统计出来的，没有分开意外和自伤。重返工作那一组只有 84 人，而且在德国。两组都不能当成「跳楼之后一个人会怎么样」。次均住院费用是拿全国所有住院算出来的平均数，不是坠落伤的费用，引它只为给一个可以核对的下限。原文只给了这批人的高度分布，所以这里不写高度与后果的对应关系。长期卧床期间最该盯的压疮见第 17 节第 8 条。深静脉血栓与肺栓塞见第 13 节第 11 条（一条腿突然肿起来）。念头冒出来时怎么办见本节第 32 条。中毒的后果见本节第 33 条（别把「救回来」当成兜底）。下面是作者本人的经历：从四楼坠落，事前以为「十几天就好」，实际住院一年、四处手术、上了钢板、半年不能自己翻身坐起，家里为此借钱', NULL, NULL, NULL, '不花钱。只是先把这笔账看清。', '新疆南部一家创伤 ICU（重症监护病房）做过统计。从 2020 年 4 月到 2024 年 7 月，这里共收了 289 例高处坠落。这批人平均年龄 40.3 岁。坠落高度中位数 3 米，26.6% 从 5 米以上坠落，11.4% 从 10 米以上坠落。伤情评分 ISS 中位数 24，这套评分越高伤得越重，63.3% 的人 ISS 大于 20。47.1% 伤及 3 个以上部位，18.3% 伤及 4 个以上。36% 需要上呼吸机（机械通气），上机时长中位 103.5 小时。在 ICU 住院中位 8 天，最短 1 天，最长 132 天。院内或 30 天死亡率 5.5%（16/289）。德国一家创伤中心收了 84 例 ISS ≥ 25 的多发伤病人，多发伤就是同时伤到多个部位。随访期内重返工作的比例为 58%。年龄、ICU 治疗时长和自评健康是预测因素。2024 年全国医院次均住院费用（平均每次住院花的钱）9870.0 元，按当年价格比上年下降 4.3%。同年全国卫生总费用 90895.5 亿元，其中个人卫生支出 25007.5 亿元，占 27.5%', '给 B 的原因：坠落那一组是一家医院翻旧病历统计出来的，没有分开意外和自伤。重返工作那一组只有 84 人，而且在德国。两组都不能当成「跳楼之后一个人会怎么样」。次均住院费用是拿全国所有住院算出来的平均数，不是坠落伤的费用，引它只为给一个可以核对的下限。原文只给了这批人的高度分布，所以这里不写高度与后果的对应关系。长期卧床期间最该盯的压疮见第 17 节第 8 条。深静脉血栓与肺栓塞见第 13 节第 11 条（一条腿突然肿起来）。念头冒出来时怎么办见本节第 32 条。中毒的后果见本节第 33 条（别把「救回来」当成兜底）。下面是作者本人的经历：从四楼坠落，事前以为「十几天就好」，实际住院一年、四处手术、上了钢板、半年不能自己翻身坐起，家里为此借钱', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-35', 'concept_archive_s1-35', 'claim_archive_s1-35', 'action', 'life_archive', '别拿「少一个肾没什么」换钱：剩下那个要替两个干活，卖过肾的人事后 86% 说身体变差', '1. 不要早死', '捐肾前层层筛查、捐后有人复查的正规捐献者，15 年后走到尿毒症的是每万人 31 人，同样健康但没捐的人是每万人 4 人。卖肾的人没有筛查也没有复查，6 年后 86% 说身体变差，四分之三还欠着债。', '争议：Ibrahim 那项拿普通人当比较对象，结论是捐肾者的存活、以及走到尿毒症（ESRD）的风险，都和普通人相仿。Muzaale 和 Mjøen 把比较对象换成「同样健康、同样够格捐肾」的人之后，风险就明显高出来。分歧在拿谁来比，不在捐献者身上。三项研究都同意绝对风险不大（15 年 30.8/万，即一万人里 30.8 个）。所以重点不在「捐肾很危险」，要看的是另外两件事。剩下那个肾确实在付代价，高血压和蛋白尿的比例摆在那里。这些数字全都出自术前经过筛查、术后有人复查、出事能回医院的人群，黑市卖肾这三样一样都没有，印度那份回访给出的是另一种结局。原始研究只给到自述健康变差、蛋白尿、高血压和尿毒症发生率，没有「多少人卧床」这类数字，这里不替它补。合法捐献的亲属限制、罚款与刑责见第 9 节第 22 条（不卖自己的器官）。已经要透析的，跨省直接结算和长期用药见第 16 节第 1、2 条（药按医嘱吃满、门诊慢特病异地备案）', NULL, NULL, NULL, '不花钱。只是先把这笔账看清。', '美国把 96,217 名活体捐肾者和 20,024 名条件相当的健康未捐者作了比较。后者来自美国全国健康与营养调查（NHANES III）。再看捐后 15 年走到尿毒症的估计风险。捐献者为每万人 30.8 人，可信范围 95% CI 24.3–38.5。健康未捐者为每万人 3.9 人，可信范围 95% CI 0.8–8.9，P&lt;0.001。尿毒症的学名是终末期肾病 ESRD，到了这一步得靠透析或移植维持。估计一辈子走到 ESRD 的风险：捐献者每万人 90 人，未经筛查的一般人群每万人 326 人，健康未捐者每万人 14 人。挪威也做过一次比较。一边是 1901 名捐肾者，中位随访 15.1 年。另一边是 32,621 名符合捐献条件的对照，中位随访 24.9 年。捐肾者的全因死亡高约三成（HR 1.30，95% CI 1.11–1.52）。心血管死亡高约四成（HR 1.40，1.03–1.91）。走到 ESRD 高十倍上下（HR 11.38，4.37–29.6）。这批捐献者的 ESRD 总发生率为每百万人 302 例。美国另有 3698 名捐肾者，其中 11 人发生 ESRD，相当于每百万人观察一年里 180 例，同期一般人群是 268 例。这批人里有 255 人在捐后平均 12.2±9.2 年回来复查。其中 85.5% 的肾滤过功能 GFR ≥ 60 ml/min/1.73 m²。60 是临床正常下限。32.1% 有高血压。12.7% 有蛋白尿（尿里漏出蛋白）。印度金奈调查了 305 名卖肾者，平均在卖肾 6 年后接受调查：96% 为还债而卖，平均拿到 1070 美元。切肾后家庭平均收入下降三分之一（P&lt;0.001），生活在贫困线以下的人数增加，四分之三在调查时仍负债。86% 报告健康状况较切肾前变差，79% 不建议他人卖肾', '争议：Ibrahim 那项拿普通人当比较对象，结论是捐肾者的存活、以及走到尿毒症（ESRD）的风险，都和普通人相仿。Muzaale 和 Mjøen 把比较对象换成「同样健康、同样够格捐肾」的人之后，风险就明显高出来。分歧在拿谁来比，不在捐献者身上。三项研究都同意绝对风险不大（15 年 30.8/万，即一万人里 30.8 个）。所以重点不在「捐肾很危险」，要看的是另外两件事。剩下那个肾确实在付代价，高血压和蛋白尿的比例摆在那里。这些数字全都出自术前经过筛查、术后有人复查、出事能回医院的人群，黑市卖肾这三样一样都没有，印度那份回访给出的是另一种结局。原始研究只给到自述健康变差、蛋白尿、高血压和尿毒症发生率，没有「多少人卧床」这类数字，这里不替它补。合法捐献的亲属限制、罚款与刑责见第 9 节第 22 条（不卖自己的器官）。已经要透析的，跨省直接结算和长期用药见第 16 节第 1、2 条（药按医嘱吃满、门诊慢特病异地备案）', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-36', 'concept_archive_s1-36', 'claim_archive_s1-36', 'action', 'life_archive', '不捡、不拆、不卖来路不明的金属件，带三叶草警示标志的离远点', '1. 不要早死', '辐射没有气味、颜色和温度，多数放射源就是一截普通金属，所以「看着没事」不能当判断。普通人撞上的概率极低，每年每万枚放射源出事不到 1 起。可一旦撞上就无法挽回，1987 年巴西有人把废弃诊所的放疗机当废铁拆开，最后 4 人死亡。', '真遇到了：离远点，记住位置，别搬动，打 110。条例要求向生态环境主管部门、公安部门、卫生主管部门报告。距离和时间是唯一有效的防护，隔着口袋或者塑料袋没有任何用。X 光机、CT 这类靠通电产生射线的装置，断电之后不残留放射性。真正危险的是设备里那枚密封放射源。医院的放疗机、管道和锅炉上的 γ 探伤机、测井仪、料位计都含源。拆开外壳就是把源暴露出来。而它们的外观和普通金属件没有区别。所以别指望认出放射源，来路不明的设备部件一律不拆、不卖、不带回家。国内也出过有人不知情捡起放射源的事。2014 年 5 月，南京化工园区一家工厂里，探伤作业丢了一枚铱-192 放射源。一名仓库管理员巡检时把它捡起来，装进了工作服口袋。他后来被诊断为轻度急性放射病和右腿急性放射性皮肤损伤，住院治了一年，几年后仍要拄双拐走路。另有两名工人说见过它，其中一人在上班路上以为是项链，拿起来看过又扔了。丢源的是天津宏迪工程检测发展有限公司。此事没有找到官方事故通报。捡源者的伤情取自江苏省疾控中心医生发表的随访论文，捡起又扔掉那段只有《中国环境报》的记者报道。废品回收、拆解、五金和工地这几行的人，风险比一般人高得多，工地上见到画着三叶草标志的警戒区就绕行。核电站泄漏是另一类事故，普通人遇到的概率更低。受益人主要是你自己和同在现场的家人。', NULL, NULL, NULL, '不花钱。看见不认识的金属圆柱、铅罐、从设备上拆下来的部件就绕开，不捡、不拆、不放进口袋。', '截至 2025 年，全国约有 17.8 万枚在用放射源和 35.5 万台（套）射线装置。放射源辐射事故的年发生率稳定在每万枚 1 起以下。分级是这样的。Ⅰ类、Ⅱ类放射源丢失、被盗、失控，就构成重大辐射事故。Ⅲ类为较大辐射事故。Ⅳ类、Ⅴ类丢失被盗，或者导致人员受到超过年剂量限值的照射，为一般辐射事故。官方案例：2020 年 6 月，宁夏钢铁集团炼铁厂在高炉管道改造项目上做 γ 射线探伤作业。一枚 Ⅱ 类铱-192 放射源使三名作业人员受到照射。陈某某左手急性放射性皮肤损伤 Ⅲ 度。刘某某左手拇指、食指 Ⅳ 度，中指、无名指、小指 Ⅲ 度。樊某某左手 Ⅰ-Ⅱ 度。三人受照剂量均严重超过国家标准规定的剂量限值，两家责任单位被吊销辐射安全许可证并罚款 7 万元。国际案例：1987 年巴西戈亚尼亚，废弃诊所的远距离治疗机被拆解，取出了里面 50.8 TBq 的铯-137 放射源，还弄破了装源的密封囊。约 112,000 人接受监测。其中 249 人受到体内或体外污染。这 249 人里，129 人为中度至重度污染，50 人需密切医学监护。最后 4 人死亡（全国 / 国际）', '真遇到了：离远点，记住位置，别搬动，打 110。条例要求向生态环境主管部门、公安部门、卫生主管部门报告。距离和时间是唯一有效的防护，隔着口袋或者塑料袋没有任何用。X 光机、CT 这类靠通电产生射线的装置，断电之后不残留放射性。真正危险的是设备里那枚密封放射源。医院的放疗机、管道和锅炉上的 γ 探伤机、测井仪、料位计都含源。拆开外壳就是把源暴露出来。而它们的外观和普通金属件没有区别。所以别指望认出放射源，来路不明的设备部件一律不拆、不卖、不带回家。国内也出过有人不知情捡起放射源的事。2014 年 5 月，南京化工园区一家工厂里，探伤作业丢了一枚铱-192 放射源。一名仓库管理员巡检时把它捡起来，装进了工作服口袋。他后来被诊断为轻度急性放射病和右腿急性放射性皮肤损伤，住院治了一年，几年后仍要拄双拐走路。另有两名工人说见过它，其中一人在上班路上以为是项链，拿起来看过又扔了。丢源的是天津宏迪工程检测发展有限公司。此事没有找到官方事故通报。捡源者的伤情取自江苏省疾控中心医生发表的随访论文，捡起又扔掉那段只有《中国环境报》的记者报道。废品回收、拆解、五金和工地这几行的人，风险比一般人高得多，工地上见到画着三叶草标志的警戒区就绕行。核电站泄漏是另一类事故，普通人遇到的概率更低。受益人主要是你自己和同在现场的家人。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-37', 'concept_archive_s1-37', 'claim_archive_s1-37', 'action', 'life_archive', '赌到借钱还赌、心情一直低落时，先打 12356，再把银行卡和支付密码交给家人管', '1. 不要早死', '去医院看过赌博问题的人，自杀死亡是同龄人的 15 倍，总死亡是 1.8 倍。能预先看出谁会自杀的信号是抑郁。所以赌到借钱还赌、情绪一直低落，先打 12356。', '给 B 是因为只有一项研究，而且只算了去专科看过病的人。这些人病情偏重，所以 15 倍不能套到所有打牌的人身上。把钱交给家人管是经验做法，没有直接研究，单算是 C 级。赌博的法律红线见第 9 节第 13 条（不抽头、不玩网络赌博）。家里人欠了赌债该不该替他还，见第 8 节第 44 条（赌债不算夫妻共同债务）。自杀念头冒出来之后怎么办，见本节第 32 条（先告诉身边的一个人）。受益人主要是你自己，家人发现苗头时也可以拉着他照这条办。', NULL, NULL, NULL, '不花钱。打一个电话。把银行卡、支付密码和借贷 App 交给家人管。难在要先承认自己控制不住。', '瑞典一项全国登记研究，找出 2005 到 2016 年在专科被诊断为赌博障碍的 2099 人。赌博障碍就是控制不住地赌、赌到影响生活。和同龄的瑞典人比，20 到 74 岁这些人的总死亡率是 1.8 倍，自杀死亡率是 15 倍（这两个数是标准化死亡比 SMR）。随访期间 67 人死亡，其中 21 人死于自杀。能预测自杀死亡的是抑郁。作者 2023 年发了更正：男性自杀是 12.1 倍，女性是 16.1 倍。中国从 2025 年 5 月 1 日起，全国拨 12356 能接通心理援助热线，每天开通不少于 18 小时（瑞典 / 全国）', '给 B 是因为只有一项研究，而且只算了去专科看过病的人。这些人病情偏重，所以 15 倍不能套到所有打牌的人身上。把钱交给家人管是经验做法，没有直接研究，单算是 C 级。赌博的法律红线见第 9 节第 13 条（不抽头、不玩网络赌博）。家里人欠了赌债该不该替他还，见第 8 节第 44 条（赌债不算夫妻共同债务）。自杀念头冒出来之后怎么办，见本节第 32 条（先告诉身边的一个人）。受益人主要是你自己，家人发现苗头时也可以拉着他照这条办。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-38', 'concept_archive_s1-38', 'claim_archive_s1-38', 'action', 'life_archive', '有高危性行为的男男性行为者，去艾滋病定点医院问暴露前预防药，按时吃能少感染七成以上', '1. 不要早死', '还没感染的人提前吃一种抗病毒药，叫暴露前预防。按时吃的人，感染风险能少七成以上。吃吃停停的人，基本没效果。它是处方药，要先在医院查过身体再开，之后定期复查。', '试验里的人主要是男男性行为者，所以最该去问的是这群人。其他有高危性行为的人，也可以去问医生合不合适。开药前必须先确认没感染，已经感染的人吃它会让病毒耐药，自测试纸的结果不能当依据。有乙肝的人停药可能让肝炎发作，所以开药前要查。世界卫生组织只对男男性行为者推荐按需吃，适合平均每周少于 2 次的人。吃法是性行为前 2 到 24 小时吃 2 片，之后 24 小时、48 小时各吃 1 片。女性和有乙肝的人只能每天吃。按需吃的试验里，吃药组胃肠道和肾脏的不良反应比安慰剂组多，所以复查不能省。国内 2019 年起在男男性行为人群里试点，2024 年的规划写的是「规范实施」。全国免费的政策没有查到。去当地艾滋病定点医院的感染科或性病艾滋病门诊开，先打当地疾控电话问哪家能开。它不防梅毒、淋病这些性病，安全套照样要用，见本节第 30 条（性行为全程用安全套）。已经发生了高危行为，补救见第 13 节第 38 条（72 小时内拿阻断药）。受益人主要是你自己，也护住你的伴侣。', NULL, NULL, NULL, '这是处方药，多数地方自费，价格从几百到几千元不等。开药前要查 HIV、肾功能和乙肝。之后每 3 个月复查一次。难的是天天按时吃。', '这种药是恩曲他滨加替诺福韦的复方片。iPrEx 试验让 2499 名男男性行为者和跨性别女性每天吃药或者吃安慰剂。吃药组感染少了 44%（95% CI 15–63）。血里测得到药的人，保护效果强得多。英国的 PROUD 试验有 544 名男男性行为者。立刻吃药的一组比推迟一年的一组感染少 86%（90% CI 64–96，90% 可信范围）。法国的 IPERGAY 试验在性行为前后按需吃药，感染少 86%（95% CI 40–98）。世界卫生组织用的一篇荟萃分析把各项试验合起来。总体 RR 0.49（0.33–0.73，低约 51%）。吃药率超过七成的试验，RR 0.30（0.21–0.45，低约 70%）。吃药率不到四成的，RR 0.95，基本无效。国家药监局 2020 年 8 月批准这个药用于暴露前预防。成人和体重至少 35 公斤的青少年可以用（多国 / 中国）', '试验里的人主要是男男性行为者，所以最该去问的是这群人。其他有高危性行为的人，也可以去问医生合不合适。开药前必须先确认没感染，已经感染的人吃它会让病毒耐药，自测试纸的结果不能当依据。有乙肝的人停药可能让肝炎发作，所以开药前要查。世界卫生组织只对男男性行为者推荐按需吃，适合平均每周少于 2 次的人。吃法是性行为前 2 到 24 小时吃 2 片，之后 24 小时、48 小时各吃 1 片。女性和有乙肝的人只能每天吃。按需吃的试验里，吃药组胃肠道和肾脏的不良反应比安慰剂组多，所以复查不能省。国内 2019 年起在男男性行为人群里试点，2024 年的规划写的是「规范实施」。全国免费的政策没有查到。去当地艾滋病定点医院的感染科或性病艾滋病门诊开，先打当地疾控电话问哪家能开。它不防梅毒、淋病这些性病，安全套照样要用，见本节第 30 条（性行为全程用安全套）。已经发生了高危行为，补救见第 13 节第 38 条（72 小时内拿阻断药）。受益人主要是你自己，也护住你的伴侣。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-39', 'concept_archive_s1-39', 'claim_archive_s1-39', 'action', 'life_archive', '65 岁以上的女性去做一次双能 X 线骨密度检查，绝经后有骨质疏松危险因素的不用等到 65 岁', '1. 不要早死', '65 岁以上的女性，以及绝经后有骨质疏松危险因素的女性，该去查一次骨密度。先查风险、再给高风险的人用药，髋部骨折能少约 17%。折算下来，每 1000 个去查的人里，约少 5 人髋部骨折。总死亡率没有看出变化。', '争议：SCOOP 事先定的主要结果是所有骨质疏松性骨折，筛查组并没有明显减少（HR 0.94，95% CI 0.85 到 1.03），少的只是髋部骨折。三项试验都是「先评估风险、再查骨密度」，没有一项单独比较只查骨密度。证据综述还估计，查出来的人里有 11.8% 到 24.1% 属于过度诊断，也就是这辈子本来不会因此骨折的人。男性要不要查，美国说证据不足，中国指南定在 70 岁以上，按医生的建议走。这条管的是骨头经不经得起摔，少摔一跤靠第 13 条（平衡和腿部力量），两条一起做。查出骨质疏松之后怎么办，见第 40 条（查出骨质疏松就用药）。受益人主要是你自己，也包括你的父母。', NULL, NULL, NULL, '去医院做一次双能 X 线骨密度检查（简称 DXA），查腰椎和髋部，躺着几分钟就做完。自费一般一两百元，各地价格不同。体检里踩一脚的跟骨超声只能初筛，不能确诊。', '美国预防服务工作组 2025 年发的推荐是：65 岁及以上的女性做骨质疏松筛查（B 级推荐）。绝经后、不到 65 岁、但按风险评估骨折风险高的女性，也推荐筛查（B 级）。男性证据不足，没有表态。给这份推荐做的证据综述合并了 3 项随机试验、42009 名欧洲老年女性。筛查的做法是先评估骨折风险，风险高的再查骨密度，查出高风险就用药。筛查组髋部骨折低约 17%。原值 RR 0.83，可信范围 95% CI 0.73 到 0.93。折成绝对数，每 1000 人筛查少 5 例髋部骨折。其中英国 SCOOP 试验找了 12483 名 70 到 85 岁的女性，筛查组髋部骨折低约 28%（HR 0.72，95% CI 0.59 到 0.89），死亡率没有看出差别。中华医学会 2017 年版诊疗指南建议：女性 65 岁以上、男性 70 岁以上做骨密度检查。不到这个年龄、但有一个或多个骨质疏松危险因素的，也建议查。2017 到 2018 年的全国调查里，40 岁以上女性骨质疏松的患病率是 20.6%，男性是 5.0%（中国）', '争议：SCOOP 事先定的主要结果是所有骨质疏松性骨折，筛查组并没有明显减少（HR 0.94，95% CI 0.85 到 1.03），少的只是髋部骨折。三项试验都是「先评估风险、再查骨密度」，没有一项单独比较只查骨密度。证据综述还估计，查出来的人里有 11.8% 到 24.1% 属于过度诊断，也就是这辈子本来不会因此骨折的人。男性要不要查，美国说证据不足，中国指南定在 70 岁以上，按医生的建议走。这条管的是骨头经不经得起摔，少摔一跤靠第 13 条（平衡和腿部力量），两条一起做。查出骨质疏松之后怎么办，见第 40 条（查出骨质疏松就用药）。受益人主要是你自己，也包括你的父母。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-40', 'concept_archive_s1-40', 'claim_archive_s1-40', 'action', 'life_archive', '查出骨质疏松，或者轻轻一摔就骨折过，就请医生开抗骨质疏松药并坚持用，别拿补钙代替', '1. 不要早死', '已经确诊骨质疏松、或者轻轻一摔就骨折过的人，按医生的方案用药，髋部骨折能少约一半，脊柱骨折也少一半多。髋部骨折做完手术就开始每年输一次药的老人，两年里再骨折的少约三成五。单靠补钙代替不了这些药。', '争议：一篇合并了 38 项试验的荟萃分析没有看出这类药能降低总死亡率（RR 0.98，95% CI 0.91 到 1.05）。单看唑来膦酸也不显著（RR 0.88，95% CI 0.68 到 1.13）。作者的结论是，这类药只该为了少骨折而用。Cochrane 那几个数字的可信度也被评为低到中等。还没骨折、骨折风险较低的女性，阿仑膦酸钠对髋部骨折没看出明显作用（RR 0.76，95% CI 0.43 到 1.32）。下颌骨坏死、不典型股骨骨折这类少见的副作用，几年的试验看不全，所以要按时复查、不自己加药停药。有的人适合打针，有的人适合吃药，选哪种由医生定。怎么查出骨质疏松，见第 39 条（骨密度检查）。绝经激素治疗也能减少骨折，但一般只在不适合用别的药时才考虑。为了潮热盗汗用激素，见第 2 节第 43 条（绝经前后潮热去评估激素治疗）。受益人主要是你自己，也包括你的父母。', NULL, NULL, NULL, '要开处方，连着用几年。常用的有每周吃一次的口服药，也有每年输一次液的针剂。刚开始用药要每年复查骨密度，稳定后每 1 到 2 年查一次。难的是没感觉也要坚持用。', '脆性骨折，是受到轻微外伤或日常活动中就发生的骨折。中华医学会 2017 年版指南认定的用药对象有三类。一是脊柱或髋部发生过脆性骨折的人。二是骨密度 T 值在 -2.5 及以下的人，不管有没有骨折过。三是骨量偏低、又在手腕、上臂或骨盆有过脆性骨折，或者算出来骨折风险高的人。指南还写明「目前尚无充分证据表明单纯补钙可以替代其他抗骨质疏松药物治疗」。Cochrane 2025 年更新了阿仑膦酸钠的综述。在已有骨质疏松或骨折的绝经后女性里，用药组髋部骨折低约 51%。原值 RR 0.49，可信范围 95% CI 0.25 到 0.96。有症状的脊柱骨折低约 55%（RR 0.45，95% CI 0.28 到 0.73）。HORIZON 试验找了 2127 名髋部骨折做过手术的人，平均 74.5 岁。手术后 90 天内开始每年输一次唑来膦酸，跟踪的中位数是 1.9 年。新的骨折从 13.9% 降到 8.6%，少了约 35%。死亡从 13.3% 降到 9.6%，少了约 28%。指南写到，髋部骨折后一年内约 20% 的人死于各种并发症。2017 到 2018 年的全国调查里，确诊骨质疏松或骨折过的女性只有 1.4% 在用药，男性只有 0.3%（中国）', '争议：一篇合并了 38 项试验的荟萃分析没有看出这类药能降低总死亡率（RR 0.98，95% CI 0.91 到 1.05）。单看唑来膦酸也不显著（RR 0.88，95% CI 0.68 到 1.13）。作者的结论是，这类药只该为了少骨折而用。Cochrane 那几个数字的可信度也被评为低到中等。还没骨折、骨折风险较低的女性，阿仑膦酸钠对髋部骨折没看出明显作用（RR 0.76，95% CI 0.43 到 1.32）。下颌骨坏死、不典型股骨骨折这类少见的副作用，几年的试验看不全，所以要按时复查、不自己加药停药。有的人适合打针，有的人适合吃药，选哪种由医生定。怎么查出骨质疏松，见第 39 条（骨密度检查）。绝经激素治疗也能减少骨折，但一般只在不适合用别的药时才考虑。为了潮热盗汗用激素，见第 2 节第 43 条（绝经前后潮热去评估激素治疗）。受益人主要是你自己，也包括你的父母。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"1. 不要早死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-41', 'concept_archive_s1-41', 'claim_archive_s1-41', 'action', 'life_archive', '上野外冰面前先打孔量厚度，不到 15 厘米别上，河上的冰和冰钓洞边别去', '1. 不要早死', '国内官方的说法是，冰厚到 15 厘米，成年人才能上去滑冰。美国和加拿大的底线是 10 厘米，而且只算新结的透明冰。发白的冰结实程度只有一半，厚度要翻倍。同一片冰，这里一尺厚，几步外可能只有一两寸，所以要边走边量。', '官方指南都说没有百分之百安全的冰，量够了厚度只是门槛，不是保证。刚上冻的初冬和开始化冰的初春最危险。真掉进去了，别脱衣服，厚衣服里存着空气能帮你浮着。转身朝来的方向，那边的冰最结实。手臂搭上冰面，把冰锥扎进冰里，脚往后蹬，把身子拖上来。上来后别站起来，平躺着滚离冰洞，再尽快取暖，冻得厉害的要去医院。看见别人掉进冰窟窿，别跑过去拉，做法见第 13 节第 25 条（看到有人溺水自己不下水）：先叫人、打 110，再递杆子、抛绳子。受益人主要是你自己和带去玩冰的孩子。', NULL, NULL, NULL, '最省事的是去有人管的正规冰场，不用多花钱。非要上野外的冰，就带冰钻或冰镩打孔量厚度。再买一对救生冰锥，就是两根带握柄的尖钉，挂在胸前。这些加起来几十到一两百元。每走一段量一次，要多花些时间。', '中国气象局的科普说，冰层厚度达到 15 厘米，成年人可以上去滑冰。露天冰场的冰层也要达到 15 厘米才能开放。北京市水务局说，正规天然冰场要冰厚 15 厘米，之后一周气温保持在 -8℃ 到 1℃、没有大风，才能开放。野冰上常有钓鱼的人凿的冰洞，凿开后很难再冻结实。美国明尼苏达州自然资源部的指南只针对新结的透明冰：不到 4 英寸（约 10 厘米）别上，4 英寸可以步行和冰钓。积雪化了又冻上的白冰，结实程度只有透明冰的一半左右，厚度要按两倍算。同一片水面，冰可能这里一英尺厚，几英尺外只有一两英寸。流水上的冰通常危险，溪流、桥和涵洞附近尤其如此。岸边的冰也可能比远处薄。美国国家气象局给的步行、冰钓、滑冰门槛也是 4 英寸。加拿大职业健康与安全中心转述加拿大红十字会的建议：几个人一起滑冰、步行要 15 厘米，人多的滑冰聚会要 20 厘米。这些都是安全指南，没有研究算过照着做能少死多少人（全国 / 美国、加拿大）', '官方指南都说没有百分之百安全的冰，量够了厚度只是门槛，不是保证。刚上冻的初冬和开始化冰的初春最危险。真掉进去了，别脱衣服，厚衣服里存着空气能帮你浮着。转身朝来的方向，那边的冰最结实。手臂搭上冰面，把冰锥扎进冰里，脚往后蹬，把身子拖上来。上来后别站起来，平躺着滚离冰洞，再尽快取暖，冻得厉害的要去医院。看见别人掉进冰窟窿，别跑过去拉，做法见第 13 节第 25 条（看到有人溺水自己不下水）：先叫人、打 110，再递杆子、抛绳子。受益人主要是你自己和带去玩冰的孩子。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s1-42', 'concept_archive_s1-42', 'claim_archive_s1-42', 'action', 'life_archive', '装好护罩、戴上护目镜加面屏再用角磨机，双手握稳，别装木工锯片切木头', '1. 不要早死', '角磨机转得极快，片子碎了会飞出来伤人，装上木工锯片还会突然反弹。国内两起事故都是装了锯片、没装护罩，一人割断大腿动脉，一人割破颈动脉，都没救回来。护罩、护目镜加面屏、双手握稳，这几样花不了几个钱。', '给 C 是因为这些做法来自安全机构的指南和事故调查，没有研究算过照做能少伤多少人。伤情数据只说明伤得多重，而且都是一家医院或一个国家的病例。收益量级定为中，凭的是判断：后果可以是死亡、失明、断指，但只落在用角磨机的人身上。哈尔滨那台机器的说明书本来就写着不要装带齿锯片、必须装护罩。那名工人手边就有手锯，切木头该用它这类木工工具。宽松衣服、垂下来的首饰和长头发都要收好，会被卷进去。磨的时候粉尘和噪声都大，口罩和耳塞的讲究见第 19 节第 10 条（防护用品单位必须给）。真割破了大血管，先死死压住伤口，见第 13 节第 12 条（大出血先用手死死压住伤口）。受益人主要是你自己，也护住站在旁边帮忙的家人。', NULL, NULL, NULL, '一副护目镜加一个面屏，几十元。每次开机前看一眼护罩和片子，换片前拔掉插头，多花一两分钟。难在嫌麻烦时也不拆护罩、不单手干活。', '加拿大职业健康与安全中心和澳大利亚昆士兰州的安全机构列的做法如下。开机前检查护罩和片子，有裂纹、缺口、变形的不用。片子上标的最高转速，不能低于机器上标的转速。片子的直径和中间的孔要和机器配套。换片前断开电源。要磨要切的东西先固定住。戴防护眼镜或护目镜，外面再加面屏。双手握住两个手柄，脚下站稳。切割片不能拿来打磨，那样片子更容易碎。片子完全停转之前不把机器放下。火花和碎屑朝向没人的地方，周围不放易燃的东西。昆士兰的通报说，切割片边缘的设计速度约为每秒 70 米。把 356 毫米的大片装到 230 毫米的机器上，边缘速度至少到每秒 120 米，片子容易碎。2016 年 2 月，当地一名工人用 230 毫米的角磨机时被碎片击中胸部，内伤死亡。国内有两份事故调查报告。2019 年哈尔滨一名工人把切割片换成带齿锯片，没装护罩就去切木板。锯片卷住裤子，割断大腿动脉，失血死亡。2024 年深圳福田一名工人用装着木工锯片、没装护罩和辅助手柄的角磨机切木门框。机器反弹，割破颈动脉死亡。报告引用的国家标准写着「不要附装上锯链、木雕刀片或带齿锯片」。韩国 2011 到 2018 年的急诊伤害监测里，被高速旋转的切割工具弄伤的有 8697 人次，其中 4603 人次在用砂轮机这一类工具。他们伤在手上的占 46.4%，伤在头部的占 23.0%。和其他同类工具比，砂轮机伤成重伤的可能高约一倍（OR 2.07，95% CI 1.88–2.29）。四川绵阳一家医院两年收治 36 名角磨机伤眼的住院病人。手术后戴上眼镜的最好视力仍低于 0.05 的有 10 人。土耳其一家医院一年的 742 例手和前臂急性外伤里，角磨机造成 82 例。除 8 例外都不是上班时伤的，44% 是退休的人。日本一家创伤中心 2017 到 2018 年的 15 名角磨机伤者里，9 人是装上锯片切木头这类错用。其中 2 人整根手指断掉，1 人断了一截（加拿大、澳大利亚 / 中国 / 韩国、土耳其、日本）', '给 C 是因为这些做法来自安全机构的指南和事故调查，没有研究算过照做能少伤多少人。伤情数据只说明伤得多重，而且都是一家医院或一个国家的病例。收益量级定为中，凭的是判断：后果可以是死亡、失明、断指，但只落在用角磨机的人身上。哈尔滨那台机器的说明书本来就写着不要装带齿锯片、必须装护罩。那名工人手边就有手锯，切木头该用它这类木工工具。宽松衣服、垂下来的首饰和长头发都要收好，会被卷进去。磨的时候粉尘和噪声都大，口罩和耳塞的讲究见第 19 节第 10 条（防护用品单位必须给）。真割破了大血管，先死死压住伤口，见第 13 节第 12 条（大出血先用手死死压住伤口）。受益人主要是你自己，也护住站在旁边帮忙的家人。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"1. 不要早死","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-1', 'concept_archive_s2-1', 'claim_archive_s2-1', 'action', 'life_archive', '戒烟，越早越好', '2. 不要慢慢死', '吸烟的人平均比不吸烟的人少活十年以上。40 岁前戒掉，能把接着吸烟带来的死亡风险抹掉九成左右。戒得越早，捡回来的越多。骨折以后接着抽，骨头长不上的几率约是不抽的 2.3 倍，所以骨头没长好之前别抽。', '吸别人的烟同样会死人：2004 年全球约有 60.3 万人死于二手烟，占当年全球总死亡的约 1%。自己不吸，也要躲开别人的烟，尤其别让孩子吸到。怎么戒，具体办法在后面四条：第 3 条（戒烟药）、第 4 条（定一个戒烟日）、第 5 条（去戒烟门诊）、第 6 条（电子烟）。骨不愈合那个数字来自只记录、不分组的研究，吸烟的人在别的方面也可能和不吸烟的人不同，没法全部扣干净。骨折后那项戒烟试验只有 105 人，换一种算法差别就不显著。', NULL, NULL, NULL, '不花钱，反过来还省钱。一天一包烟约 20–30 元，戒了这笔钱就留下了。难在戒断期要熬，一般是几周到几个月。', '美国一项跟踪一群人的研究（只记录、不分组）发现：现在还吸烟的人，比从不吸烟的人预期寿命短 10 年以上。40 岁前戒掉，可以消除继续吸烟所带来死亡风险的约 90%。25–34 岁戒烟约多活 10 年，35–44 岁约多活 9 年，45–54 岁约多活 6 年（原文以寿命年报告）。中国的同类研究：2010 年代，城市男性吸烟者的死亡风险是不吸烟者的 1.65 倍（RR 1.65），农村男性是 1.22 倍。主动戒烟满 10 年后，吸烟带来的这部分风险接近消失。骨折之后也一样。19 项只记录、不分组的研究合起来算，吸烟的人骨折不愈合（骨头长不上）的几率约是不吸烟者的 2.3 倍（OR 2.32，95% CI 1.76–3.06，已扣除其他因素）。小腿胫骨骨折和开放性骨折里同样偏高。瑞典一项随机试验里，骨折急诊手术后参加 6 周戒烟项目的 50 人，20% 出现至少一种术后并发症。没参加的 55 人是 38%。提前约好的手术，可以在术前 4 到 8 周开始戒烟，每周有人辅导，配尼古丁替代品。这样做术后并发症低约 58%（RR 0.42，95% CI 0.27–0.65，2 项试验、210 人）。', '吸别人的烟同样会死人：2004 年全球约有 60.3 万人死于二手烟，占当年全球总死亡的约 1%。自己不吸，也要躲开别人的烟，尤其别让孩子吸到。怎么戒，具体办法在后面四条：第 3 条（戒烟药）、第 4 条（定一个戒烟日）、第 5 条（去戒烟门诊）、第 6 条（电子烟）。骨不愈合那个数字来自只记录、不分组的研究，吸烟的人在别的方面也可能和不吸烟的人不同，没法全部扣干净。骨折后那项戒烟试验只有 105 人，换一种算法差别就不显著。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-2', 'concept_archive_s2-2', 'claim_archive_s2-2', 'action', 'life_archive', '别在家里和车里抽烟，也别让客人在家里抽', '2. 不要慢慢死', '全球每年约 60 万人死于吸别人的烟，其中近三成是孩子。长期吸二手烟的人，高血压、心脏病、卒中的风险都高三成上下。在家里吸到的，比在外面吸到的更伤人。', '先管家里，因为在家待得久，而且多项研究合起来看，在家吸到的二手烟比在家外危害更大。二手烟造成的健康损失里，61% 落在孩子身上。自己戒烟见本节第 1 条。', NULL, NULL, NULL, '不花钱，也不占时间。难在要开口，让家人和客人别在家里抽。', '2004 年全球有 603,000 人死于二手烟，约占全球死亡的 1.0%，其中 28% 是儿童。把 57 项研究合起来算：吸到二手烟的人得高血压的机会，约为没吸到的人的 1.28 倍（比值比）。心脏病是 1.39 倍，心肌梗死是 1.50 倍，卒中是 1.36 倍。在家里吸到二手烟的风险，高于在家外吸到的', '先管家里，因为在家待得久，而且多项研究合起来看，在家吸到的二手烟比在家外危害更大。二手烟造成的健康损失里，61% 落在孩子身上。自己戒烟见本节第 1 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-3', 'concept_archive_s2-3', 'claim_archive_s2-3', 'action', 'life_archive', '戒烟别光靠忍，先去拿药：成功率能翻一倍多', '2. 不要慢慢死', '光靠忍，多数人戒不掉。吃伐尼克兰的人戒成的比例，是吃安慰剂的两倍多。用尼古丁贴片、咀嚼胶这类替代品的，比不用药的高五成左右。贴片和咀嚼胶一起用，还能再高两成多。', '国内在卖的戒烟药就上面三类，只有尼古丁替代品是非处方药。伐尼克兰常见的反应是恶心、多梦、睡不好，有精神科病史的要跟医生说明。尼古丁替代品的疗程一般 8 到 12 周，别自己突然停，按医生说的减量。药只解决戒断那几周的难受，不解决「想抽」的场合，所以要和本节第 4 条（定一个戒烟日）、第 5 条（去戒烟门诊）一起用。', NULL, NULL, NULL, '尼古丁贴片和咀嚼胶是非处方药，药店柜台就能买。一个疗程 8 到 12 周，几百元到一千多元。伐尼克兰和安非他酮是处方药，要去戒烟门诊或者呼吸内科开。这笔钱和同期少买的烟大致抵消。', '41 项随机试验、17395 人合起来算，伐尼克兰组的戒烟成功率是安慰剂组的 2.32 倍（RR 2.32，95% CI 2.15–2.51，这是可信范围；高确定性证据）。伐尼克兰也高于安非他酮（RR 1.36，高约 36%）和单用一种尼古丁替代品（RR 1.25，高约 25%）。尼古丁替代品和不用药比：133 项试验、64640 人，成功率高约 55%（RR 1.55，95% CI 1.49–1.61）。贴片再加一种见效快的剂型（咀嚼胶、含片），比只用一种高约 27%（RR 1.27，95% CI 1.17–1.37，16 项试验、12169 人，高确定性证据）。', '国内在卖的戒烟药就上面三类，只有尼古丁替代品是非处方药。伐尼克兰常见的反应是恶心、多梦、睡不好，有精神科病史的要跟医生说明。尼古丁替代品的疗程一般 8 到 12 周，别自己突然停，按医生说的减量。药只解决戒断那几周的难受，不解决「想抽」的场合，所以要和本节第 4 条（定一个戒烟日）、第 5 条（去戒烟门诊）一起用。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-4', 'concept_archive_s2-4', 'claim_archive_s2-4', 'action', 'life_archive', '定一个戒烟日，到那天一次停掉，别先慢慢减', '2. 不要慢慢死', '很多人打算先每天少抽几根，慢慢减到零。可到了第六个月，定好日子一次停掉的人里 22% 没再抽，慢慢减的只有 15.5%。所以定一个日子，到那天一次停掉。', '争议。Cochrane 原先有一篇专门比这两种办法的综述，结论是两者差不多（RR 0.94，95% CI 0.79–1.13，10 项试验、3760 人），但那篇已于 2019 年撤回、不再更新。所以眼下最好的证据是上面这项随机试验，方向支持一次停。另外那项试验里两组都在戒烟日之前就开始用尼古丁替代品，这个做法本身也有证据：提前用比戒烟日当天才开始，成功率高约 25%（RR 1.25，95% CI 1.08–1.44，9 项试验、4395 人，中等确定性证据）。所以合理的排法是先定日子，提前两周贴上，到日子一次停。', NULL, NULL, NULL, '不花钱。就是在日历上挑一天，提前告诉家里人和同事。', '英国 697 名吸烟者随机分成两组。一组在戒烟日当天一次停掉，一组在戒烟日前两周先把烟量减掉 75%。两组都有护士的行为支持，戒烟日前后都用尼古丁替代品。第 4 周时，一次停那组 49.0%（95% CI 43.8–54.2，这是可信范围）没复吸，慢慢减那组 39.2%（34.0–44.4），相对风险比 0.80（0.66–0.93）。到第 6 个月，一次停那组 22.0%（18.0–26.6），慢慢减那组 15.5%（12.0–19.7），相对风险比 0.71（0.46–0.91）。原本就偏好慢慢减的人，第 4 周的成功率也低于偏好一次停的人（38.3% 对 52.2%）。', '争议。Cochrane 原先有一篇专门比这两种办法的综述，结论是两者差不多（RR 0.94，95% CI 0.79–1.13，10 项试验、3760 人），但那篇已于 2019 年撤回、不再更新。所以眼下最好的证据是上面这项随机试验，方向支持一次停。另外那项试验里两组都在戒烟日之前就开始用尼古丁替代品，这个做法本身也有证据：提前用比戒烟日当天才开始，成功率高约 25%（RR 1.25，95% CI 1.08–1.44，9 项试验、4395 人，中等确定性证据）。所以合理的排法是先定日子，提前两周贴上，到日子一次停。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-5', 'concept_archive_s2-5', 'claim_archive_s2-5', 'action', 'life_archive', '去戒烟门诊，或者打 12320 问当地有没有戒烟服务', '2. 不要慢慢死', '药和「有人定期问你」是两件事，合起来最管用。一边吃药一边有专人跟进的人，戒成的比例接近只听一句简短建议的人的两倍。电话也算：主动打回来的戒烟热线，能把成功率再提高两三成。', '国内怎么找：微信搜「中国戒烟平台」小程序，里面有各地戒烟热线和戒烟门诊的名单；也可以打 12320 问当地有没有戒烟门诊。上面的试验多数在国外做，各地戒烟门诊的服务强度差别很大，数字只能当方向看。要配的药见本节第 3 条（戒烟药）。', NULL, NULL, NULL, '挂一次号几元到几十元。行为支持一般是 4 到 8 次面谈，每次半小时到一小时，加起来多在 5 小时以内。打热线不花钱。', '52 项试验、19488 人合起来算，药物加行为支持组的戒烟成功率是常规照护或简短建议组的 1.83 倍（RR 1.83，95% CI 1.68–1.98，这是可信范围；高质量证据）。在医疗机构招募的那 43 项试验里是 1.97 倍（1.79–2.18）。电话咨询单独算：在自己打过戒烟热线的人里，接受多次主动回访的比只拿到材料或只谈一次的高约 38%（RR 1.38，95% CI 1.19–1.61，14 项试验、32484 人）；没主动打过热线、由研究方提供电话咨询的，高约 25%（RR 1.25，95% CI 1.15–1.35，65 项试验、41233 人）。两项都是中等确定性证据。', '国内怎么找：微信搜「中国戒烟平台」小程序，里面有各地戒烟热线和戒烟门诊的名单；也可以打 12320 问当地有没有戒烟门诊。上面的试验多数在国外做，各地戒烟门诊的服务强度差别很大，数字只能当方向看。要配的药见本节第 3 条（戒烟药）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-6', 'concept_archive_s2-6', 'claim_archive_s2-6', 'action', 'life_archive', '已经戒不掉再考虑电子烟，本来不吸烟的人别碰', '2. 不要慢慢死', '把烟换成含尼古丁的电子烟，戒成的人比用尼古丁贴片多约六成，这个结论很可靠。但它不是无害的，长期吸的安全数据还没有。本来不吸烟的人吸它没有任何好处。', '争议。世界卫生组织不推荐把电子烟当戒烟手段。理由是长期安全数据不够，还会让年轻人开始接触尼古丁。英国则把它放进了戒烟服务。国内不是全面禁售电子烟，但管得很严，规矩写在《电子烟管理办法》里。只准卖烟草口味的，果味的和能自己加烟油的都不准卖。只能在拿了烟草专卖零售许可证的实体店买。除了国家统一的电子烟交易管理平台，在别的网站、网店和社交软件上卖都不合法。也不准卖给未成年人。所以还能买到的水果味电子烟走的是非法渠道，不在监管之内。掺了合成大麻素的「上头电子烟」就是这么流出来的，见第 22 节第 4 条（不接别人递的烟弹）。综述里测的都是受监管的含尼古丁产品，来路不明的烟油不在其内。顺序上先试本节第 3 条（戒烟药），那边的证据更硬、也更便宜。', NULL, NULL, NULL, '设备加烟弹每月几十到几百元。国内只能买烟草口味的，而且只能在有烟草专卖零售许可证的店里买。', '一份持续更新的综述纳入 80 项随机试验、29861 人。含尼古丁的电子烟和尼古丁替代疗法比，戒烟成功率高约 61%（RR 1.61，95% CI 1.23–2.12，这是可信范围；高确定性证据，11 项试验、4114 人）。换成绝对数，大约是每 100 人里多 4 人戒成（多 1 到 7 人）。严重不良事件的发生比例两组大致相当（风险差 0.01，95% CI −0.01 到 0.02，中等确定性证据）。和只有行为支持或没有支持比，高约 75%（RR 1.75，95% CI 1.39–2.20，低确定性证据）。', '争议。世界卫生组织不推荐把电子烟当戒烟手段。理由是长期安全数据不够，还会让年轻人开始接触尼古丁。英国则把它放进了戒烟服务。国内不是全面禁售电子烟，但管得很严，规矩写在《电子烟管理办法》里。只准卖烟草口味的，果味的和能自己加烟油的都不准卖。只能在拿了烟草专卖零售许可证的实体店买。除了国家统一的电子烟交易管理平台，在别的网站、网店和社交软件上卖都不合法。也不准卖给未成年人。所以还能买到的水果味电子烟走的是非法渠道，不在监管之内。掺了合成大麻素的「上头电子烟」就是这么流出来的，见第 22 节第 4 条（不接别人递的烟弹）。综述里测的都是受监管的含尼古丁产品，来路不明的烟油不在其内。顺序上先试本节第 3 条（戒烟药），那边的证据更硬、也更便宜。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-7', 'concept_archive_s2-7', 'claim_archive_s2-7', 'action', 'life_archive', '不喝含糖饮料，换成无糖的也不算解决', '2. 不要慢慢死', '每天喝两瓶以上甜饮料的人，同期死亡的概率比几乎不喝的人高约两成。每天一到两瓶的，也高一成多。换成无糖的也没见着好处：每天喝两杯以上代糖饮料的人，反而高约四分之一。', '争议在无糖饮料上。代糖饮料的关联反而比含糖的更强，这很可能是因果反过来了：已经超重或者得了糖尿病的人，才改喝无糖版。所以别据此说代糖更毒。但它至少说明，「换成无糖就没事」这个说法没有证据支持。换成白水或者无糖茶最稳妥。另外，这类研究只是跟踪记录，没做分组试验，喝甜饮料多的人本来生活方式就更差，所以数字可能偏大。', NULL, NULL, NULL, '不花钱，也不占时间。换成白水或无糖茶还省钱。难在要改掉喝甜饮料的习惯，包括无糖的。', '美国有两项跟踪一群人的大型研究。这两项只记录、不分组，约 11.8 万人、3.6 万例死亡。每天喝 2 份以上的人，死亡风险比每月不到 1 份的人高约 21%（HR 1.21）。每天喝 1–2 份的，高约 14%（HR 1.14）。欧洲 EPIC 跟踪研究只记录、不分组，有 45 万人、10 个国家。每天喝 2 杯以上的人和每月不到 1 杯的人比：含糖软饮这项高约 8%（HR 1.08，95% CI 1.01–1.16）。人工甜味剂饮料（无糖版）高约 26%（HR 1.26，1.16–1.35）。所有软饮合起来算，高约 17%（HR 1.17，1.11–1.22）。', '争议在无糖饮料上。代糖饮料的关联反而比含糖的更强，这很可能是因果反过来了：已经超重或者得了糖尿病的人，才改喝无糖版。所以别据此说代糖更毒。但它至少说明，「换成无糖就没事」这个说法没有证据支持。换成白水或者无糖茶最稳妥。另外，这类研究只是跟踪记录，没做分组试验，喝甜饮料多的人本来生活方式就更差，所以数字可能偏大。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-8', 'concept_archive_s2-8', 'claim_archive_s2-8', 'action', 'life_archive', '不嚼槟榔', '2. 不要慢慢死', '嚼槟榔的人，同期死亡的概率比不嚼的人高约两成。糖尿病和代谢综合征的风险高近五成。口腔癌和食管癌的风险还要另算。', '嚼的年头越长、每天嚼得越多，口腔癌风险越高。戒了以后，风险会随时间往下走。含烟草的槟榔更危险', NULL, NULL, NULL, '不花钱，也不占时间，还省下买槟榔的钱。难在要戒掉嚼的习惯。', '把 17 项亚洲研究、38.8 万人合起来算。嚼槟榔的人死亡风险比不嚼的人高约 21%（相对风险 1.21，P=0.02）。死亡这一项算的是其中的 17.96 万人。得糖尿病的风险高约 47%（1.47）。得代谢综合征的风险高约 51%（1.51）。槟榔本身也是口腔癌和食管癌的已知危险因素', '嚼的年头越长、每天嚼得越多，口腔癌风险越高。戒了以后，风险会随时间往下走。含烟草的槟榔更危险', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-9', 'concept_archive_s2-9', 'claim_archive_s2-9', 'action', 'life_archive', '把家里的食盐换成低钠盐（钾盐）', '2. 不要慢慢死', '得过中风或 60 岁以上有高血压的人，把家里的盐换成低钠盐，五年内死亡的概率低约 12%，中风低约 14%。', '争议。PURE 这项研究只长期跟踪记录，不分组。它报告：一天排钠不到 3 g 的人，死亡加心血管事件的风险高约 27%。一天排钠 7 g 以上的人，高约 15%。按它的结果，吃太少和吃太多都不好，中间最好。但本条引的那项中国农村随机试验里，低钠盐只是替换掉一部分，不会把钠压得那么低。另外要注意，试验对象是高危老人。健康年轻人换盐得到的好处要小得多。肾功能不全的人，或者正在吃保钾类药物的人，换盐前先问医生。', NULL, NULL, NULL, '一袋比普通盐贵几元。买的时候顺手换，不额外占时间。口味几乎不变。', '一项把人随机分成两组的试验，在中国农村做的，20995 人，都是得过卒中的人或者 60 岁以上的高血压病人，跟踪了 4.74 年。结果：用低钠盐的那组比用普通盐的那组，死亡风险低约 12%（RR 0.88）。卒中低约 14%（RR 0.86）。主要心血管事件低约 13%（RR 0.87）。血钾过高的事件，两组没看出统计上的差别。', '争议。PURE 这项研究只长期跟踪记录，不分组。它报告：一天排钠不到 3 g 的人，死亡加心血管事件的风险高约 27%。一天排钠 7 g 以上的人，高约 15%。按它的结果，吃太少和吃太多都不好，中间最好。但本条引的那项中国农村随机试验里，低钠盐只是替换掉一部分，不会把钠压得那么低。另外要注意，试验对象是高危老人。健康年轻人换盐得到的好处要小得多。肾功能不全的人，或者正在吃保钾类药物的人，换盐前先问医生。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-10', 'concept_archive_s2-10', 'claim_archive_s2-10', 'action', 'life_archive', '认真刷牙，每天清一次牙缝，缺牙及时补', '2. 不要慢慢死', '每天用牙线或牙缝刷的人，同期死亡的概率低约一成。牙掉光的老人，死亡的概率高约九成。剩不到 20 颗牙的，高约一倍。', '争议。这类研究只是跟踪记录。牙不好的人，往往整体健康和经济状况也差。到底是牙拖累了身体，还是身体不好连累了牙，说不清。但这件事成本极低，而且牙周炎和缺牙本身就影响吃东西。种一颗牙要花多少、看牙哪些项目医保报，见第 24 节第 12 条（种牙之前先问清包干价）', NULL, NULL, NULL, '牙线或牙缝刷一年几十元，洗牙每次一两百元。每天多花两三分钟。难在要把清牙缝变成每天都做的事。', '日本有一项研究，9676 人，跟踪 6 年。用牙缝清洁工具的人，死亡风险低约 11%（风险比 0.89）。用舌苔清洁工具的人，低约 23%（0.77）。另外把多项研究合起来算，对象是住在社区的老人。一颗牙都没有的人，死亡的机会约为 1.87 倍（比值比，95% CI 1.35–2.59，这是可信范围）。牙齿少于 20 颗的，约为 2.04 倍（1.67–2.49）', '争议。这类研究只是跟踪记录。牙不好的人，往往整体健康和经济状况也差。到底是牙拖累了身体，还是身体不好连累了牙，说不清。但这件事成本极低，而且牙周炎和缺牙本身就影响吃东西。种一颗牙要花多少、看牙哪些项目医保报，见第 24 节第 12 条（种牙之前先问清包干价）', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-11', 'concept_archive_s2-11', 'claim_archive_s2-11', 'action', 'life_archive', '每天走到 7000–8000 步，或者每周累计快走 150–300 分钟', '2. 不要慢慢死', '每天走 7800 步左右的人，同期死亡的概率比只走 3500 步的人低约四成半。按时间算也一样，每周快走 150–300 分钟，比不运动低约三成。多到一定量就不再往下降了，60 岁以上走到 6000–8000 步就够。两种数法达标一个就行。', '步数和运动时间说的是同一件事，只是换了个数法，达标一个就行。从 4000 步加到 7000 步这一段最划算，不必非要凑一万步。要注意这类研究只是跟踪记录：走得最少、动得最少的那批人里，混着本来就病着走不动的。他们是快不行了才动得少，不是因为少动才早死。所以算出的差距常常偏大。用仪器实测活动量的那几项，跟踪时间短，参与者偏老，真实好处没有「风险降到 0.52 倍」那么大。但越动越好的趋势是清楚的。', NULL, NULL, NULL, '不花钱。按步数算，每天走 60–90 分钟，可以拆进上下班和买菜里。按运动时间算，每天 20–45 分钟。难在要长期坚持下来。', '把 15 项跟踪一群人的研究合起来算，只记录、不分组。这 15 项共 47471 人、3013 例死亡。按每天步数把人分成四档，最低那档中位是 3553 步/天。另外三档的中位是 5801、7842、10901 步/天。这三档的死亡风险比最低档分别低约 40%、45%、53%（HR 0.60、0.55、0.47）。60 岁以上的人走到 6000–8000 步以后，再多走收益就趋平了。60 岁以下的人是在 8000–10000 步以后趋平。另有一项分析把多项研究合起来算：从约 3867 步/天开始有效。之后每多走 1000 步/天，死亡风险降约 15%。按运动时间算：把多项跟踪研究汇总到一起算（只记录、不分组），运动量达到指南下限 1–2 倍的人，死亡风险比不运动的人低约 31%（HR 0.69）。这个量是 7.5–15 MET·h/周，大约合快走 150–300 分钟/周。没达到下限的人也低约 20%（HR 0.80）。达到下限 3–5 倍的人低约 39%（HR 0.61），这是降幅的顶点。再往上加不会更低，但也没害处（10 倍以上是 HR 0.69）。另一项用加速度计测量的汇总研究：中高强度活动最多的那四分之一人，比最少的那四分之一死亡风险低约 48%（HR 0.52）。加速度计是戴在身上实测活动量的仪器。', '步数和运动时间说的是同一件事，只是换了个数法，达标一个就行。从 4000 步加到 7000 步这一段最划算，不必非要凑一万步。要注意这类研究只是跟踪记录：走得最少、动得最少的那批人里，混着本来就病着走不动的。他们是快不行了才动得少，不是因为少动才早死。所以算出的差距常常偏大。用仪器实测活动量的那几项，跟踪时间短，参与者偏老，真实好处没有「风险降到 0.52 倍」那么大。但越动越好的趋势是清楚的。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-12', 'concept_archive_s2-12', 'claim_archive_s2-12', 'action', 'life_archive', '有高血压、高血脂就按医嘱规律吃药，别自行停', '2. 不要慢慢死', '血压每降 10 mmHg，死亡的概率降约 13%，中风降约 27%。他汀把低密度胆固醇降 1 个单位，死亡的概率降约一成。按时吃药的人比经常漏吃的人，死亡的概率低三成到四成半。', '只有医生判断该吃药的人才照这个做，健康人不用吃。「坚持吃药」那组数字来自跟踪记录，能坚持吃药的人本身也更自律，所以会把好处说大。前面两组随机分组试验的数字更可靠。本节没有单独列控制血糖这一条：把血糖压得更低对总死亡率的好处，证据不像血压、血脂那样一致。', NULL, NULL, NULL, '集采的降压药和他汀每月几元到几十元。每天吃一次，花不了多少时间。难在要一直吃下去，不能觉得没事了就停。', '把多项随机分组试验合起来算：收缩压每降 10 mmHg，死亡风险低约 13%（RR 0.87）。收缩压就是血压里的高压。主要心血管事件低约 20%（RR 0.80）。卒中低约 27%（RR 0.73）。心衰低约 28%（RR 0.72）。吃他汀让低密度脂蛋白胆固醇（LDL）往下降。LDL 每降 1.0 mmol/L，死亡风险低约 10%（RR 0.90）。同样这一降，主要血管事件低约 22%（RR 0.78）。另外把多项跟踪研究合起来算，只记录、不分组。按医嘱吃到 ≥80% 的人，死亡风险比经常漏吃的人低。他汀这一项低约 45%（RR 0.55）。降压药这一项低约 29%（RR 0.71）。', '只有医生判断该吃药的人才照这个做，健康人不用吃。「坚持吃药」那组数字来自跟踪记录，能坚持吃药的人本身也更自律，所以会把好处说大。前面两组随机分组试验的数字更可靠。本节没有单独列控制血糖这一条：把血糖压得更低对总死亡率的好处，证据不像血压、血脂那样一致。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-13', 'concept_archive_s2-13', 'claim_archive_s2-13', 'action', 'life_archive', '每晚睡 7 小时左右，作息固定', '2. 不要慢慢死', '长期睡不到 7 小时的人，同期死亡的概率高约一成。作息越乱，风险越高。睡得最规律的人比最不规律的人低两成到近五成。也就是说，作息规不规律比睡多久更能看出死亡风险。', '要改的是睡得太少和作息乱这两样，不必刻意去压缩睡眠时间。睡得长的人风险高，多半是因果反过来了：抑郁、慢性病、睡眠呼吸暂停会让人睡得多。另外，作息规律这一点目前有两项跟踪研究支持，都是只记录、不分组的，单独看属于 B 级证据。熬夜之后怎么补见本节第 38 条（熬夜之后第二天晚上就补觉）。', NULL, NULL, NULL, '不花钱。要拿出时间来睡，多数人是把刷手机的时间换成睡觉。难在要把上床和起床的点固定住。', '把 16 项跟踪研究合起来算，只记录、不分组，138 万人、11.3 万例死亡。睡得短的人死亡风险高约 12%（RR 1.12）。睡得长的人高约 30%（RR 1.30）。另一项汇总按睡眠时长分档：7 小时那档风险最低。少于 7 小时的，每少 1 小时高约 6%（RR 1.06）。多于 7 小时的，每多 1 小时高约 13%（RR 1.13）。英国生物银行有约 6.1 万人的腕表记录，只记录、不分组。把人按作息规律程度分成五档。较规律的那四档比最不规律的那档，死亡风险低 20%–48%。作息规不规律，比睡多久更能预测死亡。另有一项英国生物银行的研究，用腕表测了 51,562 人的睡眠时刻，其间 3,853 人新发心血管病。社会时差指工作日和周末的睡眠中点差多少。社会时差达到 2 小时以上的人，心血管病风险高约 30%（HR 1.30，95% CI 1.11–1.54）。这个关联在睡眠时长正常的人里同样存在。', '要改的是睡得太少和作息乱这两样，不必刻意去压缩睡眠时间。睡得长的人风险高，多半是因果反过来了：抑郁、慢性病、睡眠呼吸暂停会让人睡得多。另外，作息规律这一点目前有两项跟踪研究支持，都是只记录、不分组的，单独看属于 B 级证据。熬夜之后怎么补见本节第 38 条（熬夜之后第二天晚上就补觉）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-14', 'concept_archive_s2-14', 'claim_archive_s2-14', 'action', 'life_archive', '每周打三次球拍类运动，每次 45 分钟', '2. 不要慢慢死', '常打网球、羽毛球、乒乓球的人，同期死亡的概率比不打的人低约一半，心血管死亡低约 56%。游泳的人低约 28%。跑步和足球在这份数据里没看出差别。', '争议。这类研究只是跟踪记录。打球的人本身就更健康，社交也更多。跑步那组看不出差别，也说明起作用的可能是「什么样的人挑了什么运动」。别因为这条就认为跑步没用，本节另有按运动总量算的条目', NULL, NULL, NULL, '场地费每次几十元。每周约 2 小时。难在要凑齐人和场地，还得每周都去。', '英国一项 8.03 万人的跟踪研究，比的是做某项运动的人和不做这项运动的人。打球拍类运动的人，死亡风险低约 47%（风险比 0.53，95% CI 0.40–0.69，可信范围）。心血管死亡低约 56%（0.44，0.24–0.83）。球拍类指网球、羽毛球、乒乓球。游泳的人这两个数分别是 0.72 和 0.59，有氧操是 0.73 和 0.64，骑车是 0.85。跑步和足球没看出统计上的差别', '争议。这类研究只是跟踪记录。打球的人本身就更健康，社交也更多。跑步那组看不出差别，也说明起作用的可能是「什么样的人挑了什么运动」。别因为这条就认为跑步没用，本节另有按运动总量算的条目', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-15', 'concept_archive_s2-15', 'claim_archive_s2-15', 'action', 'life_archive', '把爬楼梯、快走赶路这类零碎的用力活动攒到每天四五分钟', '2. 不要慢慢死', '平时完全不锻炼的人，只要每天有三次一两分钟的用力活动，同期死亡的概率就比一点没有的人低约四成，心血管死亡低近一半。用力活动指爬楼梯、快步赶路这类。', '争议。这项研究用可穿戴设备实测活动量，比让人填问卷回忆可靠。但它仍然只是跟踪记录，没有做分组试验，而且只跟了 6.9 年。研究对象是完全不锻炼的人，已经在规律运动的人不适用这一条', NULL, NULL, NULL, '不花钱，也不用额外挤出锻炼时间。难在要记着走楼梯、走快些，别图省事。', '英国生物银行有一项研究，对象是 2.52 万名平时不专门锻炼的人。平均跟踪 6.9 年，其中 852 人去世。有的人每天有 3 次、每次 1–2 分钟的零碎剧烈活动。和完全没有的人比，他们的死亡风险和癌症死亡风险降低 38%–40%。心血管死亡风险降低 48%–49%。每天这类活动累计 4.4 分钟的人，死亡风险和癌症死亡风险降低 26%–30%。心血管死亡风险降低 32%–34%', '争议。这项研究用可穿戴设备实测活动量，比让人填问卷回忆可靠。但它仍然只是跟踪记录，没有做分组试验，而且只跟了 6.9 年。研究对象是完全不锻炼的人，已经在规律运动的人不适用这一条', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-16', 'concept_archive_s2-16', 'claim_archive_s2-16', 'action', 'life_archive', '每周做 30–60 分钟力量训练', '2. 不要慢慢死', '每周练 30–60 分钟力量的人，同期死亡的概率比不练的人低一到两成。再多练不会更好。力量和有氧一起做效果最好。', '这类研究只是跟踪记录，运动量还是参与者自己报的。「练过头反而变差」那一段的证据很弱，不必为此限制训练量。力量训练对老年人还有防跌倒、保住肌肉的好处，那些写在第 1 节。', NULL, NULL, NULL, '徒手深蹲、俯卧撑不花钱。每周练 1–2 次，每次 20–30 分钟。难在要把它排进每周的日程里。', '把多项跟踪研究合起来算（只记录、不分组）：做力量训练的人比不做的人，死亡风险低 10%–17%。不是练得越多越好，每周约 30–60 分钟时降幅最大，约 10%–20%，再多练不会多出好处。力量和有氧都做的人，比两样都不做的人死亡风险更低。', '这类研究只是跟踪记录，运动量还是参与者自己报的。「练过头反而变差」那一段的证据很弱，不必为此限制训练量。力量训练对老年人还有防跌倒、保住肌肉的好处，那些写在第 1 节。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-17', 'concept_archive_s2-17', 'claim_archive_s2-17', 'action', 'life_archive', '别连着坐太久，隔一阵起身动一动', '2. 不要慢慢死', '坐得最久的人，同期死亡的概率是坐得最少的人的 2.6 倍。一次连着坐很久，还要另算一笔风险。但只要每天有 60–75 分钟中等强度活动，久坐多出来的风险基本就被抵消了。', '可靠的结论是：坐多久不如动多少重要，运动量够的时候久坐的风险基本消失。要注意这类研究只是跟踪记录，坐得最多的人里有大量本来就病着的，「风险高到 2.63 倍」里明显含着「先病了才久坐」。另外同一份汇总里，每天看电视 3 小时以上的风险在各个运动量的人身上都存在，最活跃那组只是把这个起点推到 5 小时。', NULL, NULL, NULL, '不花钱，起身几下也用不了多少时间。难在坐进去就忘了时间，得设个提醒。', '美国有一项跟踪研究，只记录、不分组，用加速度计实测。把人按每天久坐总时长分成四份。久坐最多的那份人，死亡风险是最少那份的 2.63 倍（HR 2.63）。再按一次连着坐多久分成四份：连坐最久的那份人，是连坐最短那份的 1.96 倍（HR 1.96）。所以坐的总量和一次连坐多久，各自单独相关。另一项汇总把上百万人的研究合起来算，只记录、不分组。每天坐 8 小时以上、又几乎不运动的人，死亡风险是另一类人的 1.59 倍（HR 1.59）。另一类人是每天坐不到 4 小时、又最活跃的。每天约 60–75 分钟中等强度活动，可以抵消久坐多出来的风险。最活跃那组即使每天坐 8 小时以上，HR 也只有 1.04，没看出统计上的差别。', '可靠的结论是：坐多久不如动多少重要，运动量够的时候久坐的风险基本消失。要注意这类研究只是跟踪记录，坐得最多的人里有大量本来就病着的，「风险高到 2.63 倍」里明显含着「先病了才久坐」。另外同一份汇总里，每天看电视 3 小时以上的风险在各个运动量的人身上都存在，最活跃那组只是把这个起点推到 5 小时。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-18', 'concept_archive_s2-18', 'claim_archive_s2-18', 'action', 'life_archive', '少吃加工肉（火腿、培根、香肠、午餐肉）', '2. 不要慢慢死', '火腿、培根、香肠吃得最多的人，同期死亡的概率比吃得最少的人高约两成。每天多吃一份加工肉，概率也高两成。', '争议。NutriRECS 指南用一套通行的证据打分法（GRADE），把这些研究评为「不太靠得住」。它只给了一句很弱的建议：照现在这么吃就行。双方争的是证据够不够硬，不是方向。没有研究说加工肉有好处。没加工的红肉影响小，也看不出统计上的差别。要管住的是加工肉。', NULL, NULL, NULL, '不花钱，甚至省钱，也不占时间。难在要少吃自己爱吃的那口。', '把多项跟踪研究合起来算（只记录、不分组）：加工肉吃得最多的那组，比吃得最少的那组死亡风险高约 23%（RR 1.23）。红肉合计高约 29%（RR 1.29）。没加工的红肉高约 10%（RR 1.10），但这一项没看出统计上的差别。另一项汇总是按每天吃的量算的。加工肉每天多吃 1 份，死亡风险高约 23%（RR 1.23）。红肉每天多吃 1 份，高约 10%（RR 1.10）。', '争议。NutriRECS 指南用一套通行的证据打分法（GRADE），把这些研究评为「不太靠得住」。它只给了一句很弱的建议：照现在这么吃就行。双方争的是证据够不够硬，不是方向。没有研究说加工肉有好处。没加工的红肉影响小，也看不出统计上的差别。要管住的是加工肉。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-19', 'concept_archive_s2-19', 'claim_archive_s2-19', 'action', 'life_archive', '少喝或不喝酒', '2. 不要慢慢死', '每周喝过 100 g 纯酒精以后，喝得越多死得越早。100 g 纯酒精大约是 2.5 L 啤酒。40 岁时每周喝 100–200 g 的人，少活半年左右；喝 200–350 g 的少一两年；超过 350 g 的少四五年。按整体健康算，最划算的量是不喝。', '争议。认为「少喝有好处」的一方，是一份 34 项长期跟踪研究的汇总。它报告：少量饮酒的人总死亡率最多低 17%–18%。它给的量是男性每天不超过 4 杯、女性不超过 2 杯。在这个量以内，喝得多的人死亡率反而低。反方认为，「不喝酒」那一组里混进了因病戒酒的人和本来身体就差的人。有一项汇总专门把这些干扰扣掉，做完以后保护作用就没了。全球疾病负担研究也给出 0 最安全。稳妥的读法是：少喝不会明显伤寿命，多喝一定伤。「为了健康开始喝酒」没有依据。想少喝怎么办见本节第 21 条（先数杯数再找医生）。天天喝的人不能自己硬戒，见本节第 20 条（别自己硬戒）', NULL, NULL, NULL, '不花钱，还省钱，也不占时间。难在社交场合推酒时的一点尴尬。', '把 83 项往后跟踪的研究合起来算，只记录、不分组，60 万名在喝酒的人。死亡风险的最低点，在每周不超过 100 g 纯酒精。这个量大约是 5% 的啤酒 2.5 L，或者 40 度白酒 300 mL。40 岁时每周喝 100–200 g 的人，预期寿命少约 6 个月。每周喝 200–350 g 的少 1–2 年。超过 350 g 的少 4–5 年。以上三项原文以寿命年报告。全球疾病负担研究 GBD 2016 把各类健康损失合起来算，风险最低的饮酒量是 0 杯/周。还有一项汇总把研究设计上的偏差校正过了。每天喝 1.3–24 g 的人和一辈子不喝的人比，死亡风险低约 7%（RR 0.93）。但这一项没看出统计上的差别。每天喝 45–64 g 的高约 19%（RR 1.19）。每天 65 g 以上的高约 35%（RR 1.35）。', '争议。认为「少喝有好处」的一方，是一份 34 项长期跟踪研究的汇总。它报告：少量饮酒的人总死亡率最多低 17%–18%。它给的量是男性每天不超过 4 杯、女性不超过 2 杯。在这个量以内，喝得多的人死亡率反而低。反方认为，「不喝酒」那一组里混进了因病戒酒的人和本来身体就差的人。有一项汇总专门把这些干扰扣掉，做完以后保护作用就没了。全球疾病负担研究也给出 0 最安全。稳妥的读法是：少喝不会明显伤寿命，多喝一定伤。「为了健康开始喝酒」没有依据。想少喝怎么办见本节第 21 条（先数杯数再找医生）。天天喝的人不能自己硬戒，见本节第 20 条（别自己硬戒）', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-20', 'concept_archive_s2-20', 'claim_archive_s2-20', 'action', 'life_archive', '每天都喝酒、一停就手抖心慌的人，别自己硬戒', '2. 不要慢慢死', '天天大量喝酒的人突然停，会出戒断反应。轻的手抖、出汗、心慌、睡不着，重的会抽搐或者出现震颤谵妄，那是会死人的急症。挪威跟踪了三万多人，得过震颤谵妄的那批，往后每年有 8% 的人死亡。想戒就先去医院，说清你每天喝多少。', '自己怎么判断：几乎天天喝、一天不喝就手抖出汗心慌睡不着、早上要喝一点才舒服，占一条就别自己硬停。医院的常规做法是用苯二氮䓬类药物把这几天顶过去，同时补硫胺素（维生素 B1）。定 B 级是因为挪威那份队列说的是「得过震颤谵妄的人后来怎么样」，不是「自己硬戒会怎么样」，两者之间是推断。酒还是要戒，只是换成去医院戒。每周喝多少算多见本节第 19 条（少喝或不喝酒），想少喝怎么办见本节第 21 条（先数杯数再找医生）。', NULL, NULL, NULL, '挂一次精神科或者成瘾医学科的号，几元到几十元。严重的要住几天院。', '一篇 2026 年的临床综述写明：长期大量饮酒的人在突然停酒或者大幅减量之后会出现戒断综合征，表现包括震颤、自主神经兴奋、焦虑、失眠、感知异常、癫痫发作和震颤谵妄，在普通内科诊疗中「常见且可能危及生命」。挪威的全国登记队列纳入 2009 到 2015 年诊断为酒精依赖、酒精戒断状态或震颤谵妄的 36287 人：震颤谵妄组的年死亡率 8.0%，戒断状态组 5.0%，酒精依赖组 3.6%。震颤谵妄组的标准化死亡比 9.8（95% CI 8.9–10.7，这是可信范围），意思是死亡风险约为同龄一般人群的 9.8 倍。', '自己怎么判断：几乎天天喝、一天不喝就手抖出汗心慌睡不着、早上要喝一点才舒服，占一条就别自己硬停。医院的常规做法是用苯二氮䓬类药物把这几天顶过去，同时补硫胺素（维生素 B1）。定 B 级是因为挪威那份队列说的是「得过震颤谵妄的人后来怎么样」，不是「自己硬戒会怎么样」，两者之间是推断。酒还是要戒，只是换成去医院戒。每周喝多少算多见本节第 19 条（少喝或不喝酒），想少喝怎么办见本节第 21 条（先数杯数再找医生）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-21', 'concept_archive_s2-21', 'claim_archive_s2-21', 'action', 'life_archive', '想少喝酒，先把一周喝了多少数出来，再找医生聊几分钟', '2. 不要慢慢死', '医生花几分钟看你的饮酒量、说清风险、帮你定个目标，一年后平均每周少喝 20 克纯酒精，大约半升啤酒。谈更久并没有更多好处。已经停不下来的，国外有两种药被证明管用，大约每治 12 个人能多 1 个人不再回到一喝就喝多。', '收益量级定「小」，是因为这两份证据量到的都是喝了多少，不是死亡率，按本书的规矩只有替代终点就记「小」。药物那部分的试验多在国外做，受试者多数已达到酒精依赖的诊断标准，而且试验里都同时给了心理社会干预，数字是「在这个基础上额外多出来的好处」。这两种药在国内的适应症和能不能开，以医生和药品说明书为准，别自行网购。已经出现戒断反应的见本节第 20 条（别自己硬戒）。', NULL, NULL, NULL, '不花钱。数杯数每天记一笔就行。在门诊顺口问一句也不额外花钱。', '34 项随机试验、15197 人合起来算，接受简短干预的人在一年后比只接受最少干预或不干预的人每周少喝 20 克纯酒精（95% CI 少 12 到 28 克，这是可信范围；中等质量证据）。这些研究里受试者的基线饮酒量平均是每周 244 克。简短干预指的是不超过 5 次、总时长不到 60 分钟的建议或生活方式咨询；谈得更久并没有多出好处。药物方面：122 项随机试验、22803 人合起来算，阿坎酸每治疗 12 人（95% CI 8 到 26）可多让 1 人不再回到任何饮酒；口服纳曲酮每天 50 毫克，每治疗 12 人（8 到 26）可多让 1 人不再回到重度饮酒。', '收益量级定「小」，是因为这两份证据量到的都是喝了多少，不是死亡率，按本书的规矩只有替代终点就记「小」。药物那部分的试验多在国外做，受试者多数已达到酒精依赖的诊断标准，而且试验里都同时给了心理社会干预，数字是「在这个基础上额外多出来的好处」。这两种药在国内的适应症和能不能开，以医生和药品说明书为准，别自行网购。已经出现戒断反应的见本节第 20 条（别自己硬戒）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-22', 'concept_archive_s2-22', 'claim_archive_s2-22', 'action', 'life_archive', '每天吃一小把坚果', '2. 不要慢慢死', '常吃坚果的人，同期死亡的概率比不吃的人低约两成。一周吃一次就能看出差别，低约一成。吃到每天一把，差别最明显。', '买原味不加盐的。坚果热量不低，别当零食敞开吃。要注意这类研究只是长期跟踪一群人，吃坚果的人整体生活方式更好，所以数字要打个折', NULL, NULL, NULL, '每天吃 28 克，一年约两三百元。顺手就吃，不占时间。', '两项美国跟踪研究，11.9 万人，300 多万人年。人年就是人数乘以各自跟踪的年数。和不吃坚果的人比：每周吃不到 1 次的人死亡风险低约 7%（风险比 0.93，95% CI 0.90–0.96，这是可信范围）。每周吃 1 次的低约 11%（0.89，0.86–0.93）。每周 2–4 次的低约 13%（0.87，0.83–0.90）。每周 5–6 次的低约 15%（0.85，0.79–0.91）。每周 7 次以上的低约 20%（0.80，0.73–0.86）', '买原味不加盐的。坚果热量不低，别当零食敞开吃。要注意这类研究只是长期跟踪一群人，吃坚果的人整体生活方式更好，所以数字要打个折', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-23', 'concept_archive_s2-23', 'claim_archive_s2-23', 'action', 'life_archive', '把一部分红肉换成鱼和禽肉', '2. 不要慢慢死', '每周多吃两份加工肉或者红肉，同期死亡的概率高约 3%。换成同样份数的鱼或者禽肉，就看不出升高。这条的效应在本节里偏小，属于顺手就换、不必较劲的事。', '每周两份带来的差别很小，别指望靠换肉多活几年。同样花钱吃肉，可以优先挑鱼和禽肉', NULL, NULL, NULL, '不花钱，也不占时间。这是把肉换一种，不是多买。难在要改点口味偏好。', '把美国 6 项跟踪研究、近 3 万人合起来算。每周多吃两份加工肉，死亡风险高约 3%（风险比 1.03，95% CI 1.02–1.05，可信范围）。每周多吃两份没加工的红肉，也高约 3%（1.03，1.01–1.05）。同样的吃法换成禽肉，是 0.99（0.97–1.02）；换成鱼，是 0.99（0.97–1.01）。这两项都没看出统计上的差别', '每周两份带来的差别很小，别指望靠换肉多活几年。同样花钱吃肉，可以优先挑鱼和禽肉', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-24', 'concept_archive_s2-24', 'claim_archive_s2-24', 'action', 'life_archive', '把一部分精米白面换成全谷物', '2. 不要慢慢死', '每天多吃 90 g 全谷物的人，同期死亡的概率低约 17%。90 g 大约是三份。吃到每天 200 g 左右，还在继续往下降。', '不必全换成全谷物，换一半就已经在好处最明显的那一段了。要注意这类研究只是跟踪记录，吃全谷物的人本来就更健康，数字偏大。各项研究之间的结果差得也远（I² 83%，这个数越大说明各研究结论越不一致）。', NULL, NULL, NULL, '糙米、燕麦、全麦面比精米白面贵一点，不占时间。难在口感要慢慢适应。', '把多项跟踪研究合起来算（只记录、不分组）：全谷物每天多吃 90 g，死亡风险低约 17%（RR 0.83）。90 g 大约是 3 份。这份好处一直持续到每天 210–225 g。另一项汇总里，每天多吃 1 份低约 8%（RR 0.92）。', '不必全换成全谷物，换一半就已经在好处最明显的那一段了。要注意这类研究只是跟踪记录，吃全谷物的人本来就更健康，数字偏大。各项研究之间的结果差得也远（I² 83%，这个数越大说明各研究结论越不一致）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-25', 'concept_archive_s2-25', 'claim_archive_s2-25', 'action', 'life_archive', '每周喝三次以上茶', '2. 不要慢慢死', '有喝茶习惯的人，同期死亡的概率低约 15%。从 50 岁算起，平均多活 1.26 年，多出 1.41 年不得心血管病的时间。', '争议在于：这类研究只是跟踪记录，中国男性喝茶的人里抽烟喝酒的比例高。作者已经扣掉一部分这类影响，但扣不干净。还有一点，别喝滚烫的，热饮温度见本节关于热饮温度的一条。有人担心茶叶里有霉菌毒素。国内查过 158 份黑茶，有 2 份检出黄曲霉毒素，按喝茶的量算，吃进去的量低于国际上的可接受值。另一项查了 352 份茶、16 种霉菌毒素，只有黑茶里的赭曲霉毒素 A 平均含量超过限量。按国人喝茶的量算，两项都没算出膳食风险。茶叶放在干燥的地方，受潮发霉的别喝。绿茶提取物胶囊不一样：高浓度的儿茶素一次大量吞下去会伤肝，冲泡的茶没有这个问题。所以这里说的只是泡的茶，别拿提取物保健品代替', NULL, NULL, NULL, '一年几十到几百元。泡一杯几分钟，不占什么时间。', '中国一项 10.09 万人的研究（China-PAR），其中一半人跟踪满了 7.3 年。有喝茶习惯的人，死亡风险低约 15%（风险比 0.85，95% CI 0.79–0.90，这是可信范围）。以 50 岁为起点算：有喝茶习惯的人，没得动脉粥样硬化性心血管病的年数多 1.41 年，预期寿命多 1.26 年', '争议在于：这类研究只是跟踪记录，中国男性喝茶的人里抽烟喝酒的比例高。作者已经扣掉一部分这类影响，但扣不干净。还有一点，别喝滚烫的，热饮温度见本节关于热饮温度的一条。有人担心茶叶里有霉菌毒素。国内查过 158 份黑茶，有 2 份检出黄曲霉毒素，按喝茶的量算，吃进去的量低于国际上的可接受值。另一项查了 352 份茶、16 种霉菌毒素，只有黑茶里的赭曲霉毒素 A 平均含量超过限量。按国人喝茶的量算，两项都没算出膳食风险。茶叶放在干燥的地方，受潮发霉的别喝。绿茶提取物胶囊不一样：高浓度的儿茶素一次大量吞下去会伤肝，冲泡的茶没有这个问题。所以这里说的只是泡的茶，别拿提取物保健品代替', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-26', 'concept_archive_s2-26', 'claim_archive_s2-26', 'action', 'life_archive', '每天喝三到四杯咖啡，不加糖不加奶盖', '2. 不要慢慢死', '每天喝三到四杯咖啡的人，同期死亡的概率比不喝的人低约 17%。', '争议在于：原作者写明证据几乎全来自跟踪记录，还说「需要可靠的随机对照试验才能判断是否为因果」。意思是要把人随机分成两组来比，光看跟踪记录断不了因果。做的时候喝黑咖啡，加糖加奶盖会把好处抵消掉。孕妇，还有心律失常、焦虑、失眠的人，不适用这一条', NULL, NULL, NULL, '自己冲每天一两元。冲一杯几分钟，不占什么时间。', '一篇综述把 201 项汇总研究的结果又合到一起算，这些汇总底下的原始研究都只记录、不分组。结果：每天喝 3–4 杯咖啡的人和不喝的人比，死亡风险低 17%（相对风险 0.83，95% CI 0.79–0.88，这是可信范围）', '争议在于：原作者写明证据几乎全来自跟踪记录，还说「需要可靠的随机对照试验才能判断是否为因果」。意思是要把人随机分成两组来比，光看跟踪记录断不了因果。做的时候喝黑咖啡，加糖加奶盖会把好处抵消掉。孕妇，还有心律失常、焦虑、失眠的人，不适用这一条', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-27', 'concept_archive_s2-27', 'claim_archive_s2-27', 'action', 'life_archive', '每天吃够 5 份（约 400 g）水果蔬菜', '2. 不要慢慢死', '每天多吃 200 g 蔬菜水果，同期死亡的概率低约一成。每天吃够 5 份的人，比只吃 2 份的人低约 13%。再往上吃，不会更低。', '吃够 5 份就行，不用凑到 10 份，两项研究在这一点上的答案一致。要注意这类研究只是跟踪记录，干扰明显：吃菜多的人，收入、教育、运动都和别人不一样。所以「风险低约 10%」已经是上限了。', NULL, NULL, NULL, '每天几元到十几元。每天要花点时间洗和切。难在要天天买、天天吃够量。', '把多项跟踪研究合起来算（只记录、不分组）：每天多吃 200 g 果蔬，死亡风险低约 10%（RR 0.90）。这份好处一直持续到每天 800 g。美国两项大型跟踪研究加上 26 项研究的汇总：每天吃够 5 份的人，比只吃 2 份的人死亡风险低约 13%（HR 0.87）。最好的搭配是 2 份水果加 3 份蔬菜，再多不再降。', '吃够 5 份就行，不用凑到 10 份，两项研究在这一点上的答案一致。要注意这类研究只是跟踪记录，干扰明显：吃菜多的人，收入、教育、运动都和别人不一样。所以「风险低约 10%」已经是上限了。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-28', 'concept_archive_s2-28', 'claim_archive_s2-28', 'action', 'life_archive', '少吃超加工食品（薯片、方便面、糕点、速食）', '2. 不要慢慢死', '超加工食品吃得最多的人，同期死亡的概率比吃得最少的人高约两成，心血管死亡高五成。不过这类证据被评为不太确定，数字要往回打折看。', '争议在三点。一是这套分类（NOVA）把营养差别很大的食物划成了一类。二是它和含糖饮料、加工肉（第 7、18 条）大量重叠，分不清到底是哪一项在起作用。三是按通行的证据打分法（GRADE）评，等级也低。所以做到那两条之后，这一条还能多带来多少好处，说不准。反方的证据就是同一篇综述给出的低评级本身，目前没有得出相反结论的原始研究。所以先把第 7、18 条（不喝含糖饮料、少吃加工肉）做到，再看这一条。', NULL, NULL, NULL, '不花钱，换着买而已。要自己做饭，或者花时间挑没怎么加工过的食材，每天都得占些时间。难在要长期对抗「方便就好」的惯性。', '一篇综述把多项汇总研究又合到一起算，这些汇总底下的原始研究都只记录、不分组。结果：超加工食品吃得多的人比吃得少的人，死亡风险高约 21%（RR 1.21），心血管病死亡高约 50%（RR 1.50）。这两项的证据分级分别是「高度提示」和「令人信服」。但按通行的证据打分法（GRADE）评，确定性是低或极低。', '争议在三点。一是这套分类（NOVA）把营养差别很大的食物划成了一类。二是它和含糖饮料、加工肉（第 7、18 条）大量重叠，分不清到底是哪一项在起作用。三是按通行的证据打分法（GRADE）评，等级也低。所以做到那两条之后，这一条还能多带来多少好处，说不准。反方的证据就是同一篇综述给出的低评级本身，目前没有得出相反结论的原始研究。所以先把第 7、18 条（不喝含糖饮料、少吃加工肉）做到，再看这一条。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-29', 'concept_archive_s2-29', 'claim_archive_s2-29', 'action', 'life_archive', '做饭、取暖不烧煤和柴，换成电或燃气', '2. 不要慢慢死', '做饭烧煤或烧柴的人，同期死亡的概率高约一成；取暖烧煤柴的高约 14%。已经改用电或燃气的人，比还在烧煤柴的人死亡概率低 13%–33%。', '这类研究只是跟踪记录。换了燃料的家庭往往也更富裕，「风险降到 0.67 倍」这个数里混着家境的影响。至于室外的 PM2.5，个人能做的有限，无非是搬家、戴口罩、用净化器。空气净化器没有以死亡率为终点的研究，所以本节不给数字。', NULL, NULL, NULL, '农村家庭要换灶具，加上燃料费，一年几百到上千元。换一次就完事，不长期占时间。城里人基本已经是电或燃气了。', '中国有一项慢性病往后跟踪的研究，只记录、不分组，27.1 万名没有心血管病的成人。做饭用煤柴这类固体燃料的人，死亡风险比用电或燃气的人高约 11%（HR 1.11）。取暖用固体燃料的人高约 14%（HR 1.14）。已经从固体燃料换成清洁燃料的人，和还在烧的人比，做饭这项低约 13%（HR 0.87）。取暖这项低约 33%（HR 0.67）。室外的 PM2.5 另有一笔账。把 104 项跟踪研究合起来算，长期吸到的浓度每高 10 µg/m³，自然原因死亡风险高约 8%（RR 1.08）。自然原因就是非意外的病死。', '这类研究只是跟踪记录。换了燃料的家庭往往也更富裕，「风险降到 0.67 倍」这个数里混着家境的影响。至于室外的 PM2.5，个人能做的有限，无非是搬家、戴口罩、用净化器。空气净化器没有以死亡率为终点的研究，所以本节不给数字。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-30', 'concept_archive_s2-30', 'claim_archive_s2-30', 'action', 'life_archive', '热的东西放一放再喝，不喝滚烫的茶、汤和咖啡', '2. 不要慢慢死', '喝很烫的茶，得食管癌的概率是喝温茶的 8 倍。就算只是「热」，也有 2 倍。倒出来不到两分钟就喝，风险是等四分钟以上再喝的 5 倍。', '国际癌症研究机构把 65 ℃ 以上的热饮列为 2A 类，意思是很可能致癌。同一份评估认定咖啡本身不致癌。中国的潮汕、太行山一带食管癌高发，和趁烫喝的习惯有关', NULL, NULL, NULL, '不花钱，每次多等两三分钟。难在嘴馋的时候忍住不喝。', '在伊朗北部的食管癌高发区，拿 300 名患者和 571 名没得病的人对比。下面都和喝温茶的人比。喝「热」茶的人，得食管鳞癌的机会约为 2.07 倍（比值比，95% CI 1.28–3.35，可信范围）。喝「很热」的约为 8.16 倍（3.93–16.9）。倒出后不到 2 分钟就喝的人，约为等 4 分钟以上再喝的人的 5.41 倍（2.63–11.1）', '国际癌症研究机构把 65 ℃ 以上的热饮列为 2A 类，意思是很可能致癌。同一份评估认定咖啡本身不致癌。中国的潮汕、太行山一带食管癌高发，和趁烫喝的习惯有关', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-31', 'concept_archive_s2-31', 'claim_archive_s2-31', 'action', 'life_archive', '白天出门晒晒太阳，别整天不见光', '2. 不要慢慢死', '刻意躲太阳的女性，预期寿命比晒得最多的人少 0.6 到 2.1 年。不吸烟但躲太阳的人，寿命和晒得最多的吸烟者差不多。', '争议在于：瑞典纬度高、日照少，结论不能直接搬到中国。而且回避晒太阳的人，可能本来就体弱、不爱出门。另外别晒到晒伤，正午强光下还是要遮挡，因为晒太阳会增加皮肤癌风险', NULL, NULL, NULL, '不花钱。每天十几分钟，上下班路上和午休就够了。', '瑞典一项研究，2.95 万名女性，跟踪 20 年。和晒太阳最多的那组比，刻意回避晒太阳的人预期寿命少 0.6 到 2.1 年。作者写道「不吸烟但回避晒太阳的人，预期寿命与晒太阳最多组里的吸烟者相当」', '争议在于：瑞典纬度高、日照少，结论不能直接搬到中国。而且回避晒太阳的人，可能本来就体弱、不爱出门。另外别晒到晒伤，正午强光下还是要遮挡，因为晒太阳会增加皮肤癌风险', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-32', 'concept_archive_s2-32', 'claim_archive_s2-32', 'action', 'life_archive', '把 BMI 控制在 20–25，超重就减', '2. 不要慢慢死', '死亡的概率在 BMI 20–25 这一段最低。BMI 到 27.5–30 高约两成，30–35 高约四成半，35–40 接近翻倍。东亚人对超重更敏感，BMI 每高 5，风险高约四成。', '争议。有一方认为「胖一点反而活得久」。他们汇总后得到：超重的人死亡风险低约 6%，轻度肥胖的低约 5%。双方分歧主要在要不要把三类数据剔掉：抽烟的人、已经得病的人、刚入组头几年的数据。之所以要剔，是因为重病的人会先瘦下来。那项汇总 239 项研究的分析把这三类剔掉之后，超重带来的风险又出现了。另外还要注意，没有随机试验证明减重本身能降低总死亡率。上面的收益是拿不同胖瘦的人横着比出来的，不代表减掉就能降这么多。要减重的人不必在吃饭时间上下功夫，早餐和 16:8 轻断食都没有额外好处，见第 6 节第 26 条（不要指望吃早餐或 16:8 帮你控制体重）', NULL, NULL, NULL, '不花钱。饮食加运动每天都要占时间。这是全节最费毅力的一条：要长期管住嘴、迈开腿，减下来之后维持比减更难。', '把 239 项往后跟踪的研究的个人数据合起来算（只记录、不分组）。这份分析只留了三类人：从不吸烟的、入组时没有慢性病的、入组后又活过 5 年的。结果：死亡风险在 BMI 20–25 最低。BMI 25–27.5 高约 7%（HR 1.07）。27.5–30 高约 20%（HR 1.20）。30–35 高约 45%（HR 1.45）。35–40 高约 94%（HR 1.94）。40–60 是 2.76 倍（HR 2.76）。BMI 25 以上的人每高 5 kg/m²，东亚人群的风险高约 39%（HR 1.39）。', '争议。有一方认为「胖一点反而活得久」。他们汇总后得到：超重的人死亡风险低约 6%，轻度肥胖的低约 5%。双方分歧主要在要不要把三类数据剔掉：抽烟的人、已经得病的人、刚入组头几年的数据。之所以要剔，是因为重病的人会先瘦下来。那项汇总 239 项研究的分析把这三类剔掉之后，超重带来的风险又出现了。另外还要注意，没有随机试验证明减重本身能降低总死亡率。上面的收益是拿不同胖瘦的人横着比出来的，不代表减掉就能降这么多。要减重的人不必在吃饭时间上下功夫，早餐和 16:8 轻断食都没有额外好处，见第 6 节第 26 条（不要指望吃早餐或 16:8 帮你控制体重）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-33', 'concept_archive_s2-33', 'claim_archive_s2-33', 'action', 'life_archive', '每周吃四次以上辣椒', '2. 不要慢慢死', '每周吃四次以上辣椒的人，同期死亡的概率比很少吃的人低约 23%，心血管死亡低约三分之一。', '争议在于：这是在地中海饮食的背景下做的跟踪记录，吃辣的人可能整体饮食更接近当地的传统吃法。还要注意，有胃食管反流、痔疮、肠易激的人，吃辣会加重症状，不必勉强', NULL, NULL, NULL, '不花钱，也不占时间。', '意大利一项 2.28 万人的研究，其中一半人跟踪满了 8.2 年，共 1236 人去世。每周吃辣椒 4 次以上的人，死亡风险比很少吃的人低约 23%（风险比 0.77，95% CI 0.66–0.90，可信范围）。心血管死亡低约 34%（0.66，0.50–0.86）', '争议在于：这是在地中海饮食的背景下做的跟踪记录，吃辣的人可能整体饮食更接近当地的传统吃法。还要注意，有胃食管反流、痔疮、肠易激的人，吃辣会加重症状，不必勉强', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-34', 'concept_archive_s2-34', 'claim_archive_s2-34', 'action', 'life_archive', '每天喝一两份奶或酸奶', '2. 不要慢慢死', '每天喝两份以上奶或者酸奶的人，同期死亡的概率比不喝的人低约 17%。', '争议在于：PURE 纳入了大量中低收入国家，在那里能天天喝奶本身就说明家境不错，这层干扰很难排干净。另外乳糖不耐受的人改喝酸奶或者低乳糖奶，不必硬喝牛奶', NULL, NULL, NULL, '每天几元，不占时间。', 'PURE 跟踪研究覆盖 21 个国家、13.6 万人，平均跟踪 9.1 年，共 6796 人去世。每天吃两份以上奶制品的人，死亡风险比不吃的人低约 17%（风险比 0.83，95% CI 0.72–0.96，可信范围），趋势 P=0.0052', '争议在于：PURE 纳入了大量中低收入国家，在那里能天天喝奶本身就说明家境不错，这层干扰很难排干净。另外乳糖不耐受的人改喝酸奶或者低乳糖奶，不必硬喝牛奶', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-35', 'concept_archive_s2-35', 'claim_archive_s2-35', 'action', 'life_archive', '鸡蛋不用戒，但别每天三四个', '2. 不要慢慢死', '每天多吃半个全蛋，同期死亡的概率高约 7%。把这半个换成蛋清、鱼、禽肉或者坚果，各项死亡风险反而都更低。不用戒鸡蛋，只是别每天吃三四个。', '争议很大：也有长期跟踪大批人的研究，以及多项研究的汇总，没发现鸡蛋和死亡率有关。美国膳食指南已经取消了胆固醇的每日上限。要避免的只是每天吃三四个，一天一个不必担心', NULL, NULL, NULL, '不花钱，也不占时间。', '美国一项 52.1 万人的跟踪研究，共 12.9 万人去世。每天多吃半个全蛋，死亡风险高约 7%（风险比 1.07，95% CI 1.06–1.08，这是可信范围）。把这半个全蛋换成等量的蛋清、禽肉、鱼、奶制品或者坚果豆类，死亡风险会更低，心血管、癌症、呼吸系统这三项的死亡风险也都更低', '争议很大：也有长期跟踪大批人的研究，以及多项研究的汇总，没发现鸡蛋和死亡率有关。美国膳食指南已经取消了胆固醇的每日上限。要避免的只是每天吃三四个，一天一个不必担心', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-36', 'concept_archive_s2-36', 'claim_archive_s2-36', 'action', 'life_archive', '有条件就泡澡，别只冲淋浴', '2. 不要慢慢死', '几乎每天泡澡的人，心血管事件的风险比每周泡不到两次的人低约 28%，脑出血低约 46%。', '争议在于：这是在日本人群和浴缸文化下做出的结果，中国多数家庭没有条件天天泡。另外水别太烫，也别泡太久。对老年人和有心脑血管病的人，水温过高、泡得太久反而危险，日本每年有大量老人在浴缸里猝死', NULL, NULL, NULL, '多花些水费电费。每次半小时。', '日本一项 3.0 万人的研究，跟踪 19 年，共 2097 例心血管事件。几乎每天泡澡的人，比每周泡不超过两次的人心血管事件风险低约 28%（风险比 0.72，95% CI 0.62–0.84，这是可信范围）。冠心病低约 35%（0.65，0.45–0.94）。脑卒中低约 26%（0.74，0.62–0.87）。脑出血低约 46%（0.54，0.40–0.73）', '争议在于：这是在日本人群和浴缸文化下做出的结果，中国多数家庭没有条件天天泡。另外水别太烫，也别泡太久。对老年人和有心脑血管病的人，水温过高、泡得太久反而危险，日本每年有大量老人在浴缸里猝死', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-37', 'concept_archive_s2-37', 'claim_archive_s2-37', 'action', 'life_archive', '把午睡控制在半小时内，别超过一小时，非得睡一两小时才撑得住就去查原因', '2. 不要慢慢死', '午睡不超过一小时的人，死亡和慢性病的风险没有升高，脑子还更清醒一些。睡过一小时的人，冠心病风险高约三成，糖尿病和肥胖高约两成。所以定个闹钟，半小时叫醒自己。要是每天非得睡一两小时才撑得住，那是该去查身体的信号。', '争议。上面两项都是只记录、不分组的研究。午睡时间长的人，本来就更可能有睡眠呼吸暂停、贫血、甲状腺功能减退、抑郁或者别的慢性病。所以「睡得久的人死得多」里有多少是午睡本身造成的，说不清。用基因做的因果推断（孟德尔随机化，45.3 万人加 54.1 万人）只支持一件事：午睡越频繁，血压和腰围越高一点。它没有查到午睡对冠心病和糖尿病有因果影响。所以别把「少睡午觉」当成降死亡率的手段。「去查原因」那半是作者建议，属于 C 级：白天困到必须长睡，先查夜里的睡眠，打呼噜和睡觉憋气要查睡眠呼吸暂停，再查血常规和甲状腺。短午睡怎么提神见第 3 节第 11 条（下午困了睡 10 分钟）。夜间睡多久见本节第 13 条（每晚睡 7 小时）。', NULL, NULL, NULL, '不花钱。睡前定个闹钟就行，几乎不用毅力。', '一篇伞形综述汇总了 16 篇荟萃分析、244 个健康结局。伞形综述就是把已有的汇总研究再汇总一遍。结论是：午睡少于 60 分钟的人，总死亡率和慢性病风险都没有升高，脑力改善也最明显（SMD 0.69，95% CI 0.37–1.00，这是可信范围）。20 到 30 分钟的短午睡对运动表现的改善最大（SMD 0.99，0.67–1.31）。午睡超过 60 分钟的人，冠心病风险高约 30%，糖尿病和肥胖风险高约 20%。另一项研究让 1338 名 56 岁以上的老人戴腕表实测午睡，不靠自己填问卷。跟踪最长 19 年，期间 926 人去世。午睡每多 1 小时，死亡风险高约 13%（HR 1.13，95% CI 1.04–1.23）。每天多睡一次，高约 7%（HR 1.07，1.02–1.13）。在上午睡的人，比在下午早些时候睡的人高约 30%（HR 1.30，1.03–1.64）。', '争议。上面两项都是只记录、不分组的研究。午睡时间长的人，本来就更可能有睡眠呼吸暂停、贫血、甲状腺功能减退、抑郁或者别的慢性病。所以「睡得久的人死得多」里有多少是午睡本身造成的，说不清。用基因做的因果推断（孟德尔随机化，45.3 万人加 54.1 万人）只支持一件事：午睡越频繁，血压和腰围越高一点。它没有查到午睡对冠心病和糖尿病有因果影响。所以别把「少睡午觉」当成降死亡率的手段。「去查原因」那半是作者建议，属于 C 级：白天困到必须长睡，先查夜里的睡眠，打呼噜和睡觉憋气要查睡眠呼吸暂停，再查血常规和甲状腺。短午睡怎么提神见第 3 节第 11 条（下午困了睡 10 分钟）。夜间睡多久见本节第 13 条（每晚睡 7 小时）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-38', 'concept_archive_s2-38', 'claim_archive_s2-38', 'action', 'life_archive', '熬夜之后第二天晚上就补觉，别攒到周末', '2. 不要慢慢死', '少睡之后第二天晚上没补上的人，死亡风险比作息规律的人高约 15%，少得厉害又不补的高约 42%。补上了的人看不出风险升高。所以熬了夜，第二天晚上就早点上床。', '这是只记录、不分组的研究。补不上的人可能本来就更忙、身体更差，这一层排不干净。「补上了的两组看不出风险升高」只是没查出差别，它们的点估计仍然大于 1，补了也不等于没事。所以熬了夜要尽快还上，也不能因此随便熬夜。这项研究里的补觉指少睡之后第一晚多睡一会儿，不包括攒到周末一次补。把「工作日熬、周末补」固定成每周的节奏，叫社会时差，本身和心血管病有关，见本节第 13 条（每晚睡 7 小时左右，作息固定）。周末也固定起床那条见第 3 节第 2 条（固定起床时间，周末也一样），和本条不冲突：本条让你当晚早点上床，不是让你第二天睡到中午。', NULL, NULL, NULL, '不花钱。补的那一两个小时本来就想睡。', '英国生物银行 85,618 人，平均年龄 61.8 岁，戴腕表记录逐日睡眠，中位随访 8 年。研究先按每个人自己的睡眠需求算出「少睡的夜」，指比自己需要的少睡 2.5 小时以上。少睡那段之后的第一晚算「补觉夜」，这一晚比自己需要的多睡就算补上了。按这个分成五种模式。和作息规律的人相比，少睡又不补的全因死亡风险高约 15%（HR 1.15，95% CI 1.01–1.31，这是可信范围）。累计少睡超过 3.5 小时又不补的高约 42%（HR 1.42，1.24–1.63）。补上了的两组都没有显著关联，其中少睡后补是 HR 1.12（0.98–1.28）。本来就睡得短的人里，少睡不补高约 19%（1.19，1.01–1.40），严重少睡不补高约 38%（1.38，1.17–1.63）。这个结果在另一批 4,586 人的美国健康调查里也重复出来了。', '这是只记录、不分组的研究。补不上的人可能本来就更忙、身体更差，这一层排不干净。「补上了的两组看不出风险升高」只是没查出差别，它们的点估计仍然大于 1，补了也不等于没事。所以熬了夜要尽快还上，也不能因此随便熬夜。这项研究里的补觉指少睡之后第一晚多睡一会儿，不包括攒到周末一次补。把「工作日熬、周末补」固定成每周的节奏，叫社会时差，本身和心血管病有关，见本节第 13 条（每晚睡 7 小时左右，作息固定）。周末也固定起床那条见第 3 节第 2 条（固定起床时间，周末也一样），和本条不冲突：本条让你当晚早点上床，不是让你第二天睡到中午。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-39', 'concept_archive_s2-39', 'claim_archive_s2-39', 'action', 'life_archive', '上夜班干得越久心血管风险越高，能转岗就趁早转', '2. 不要慢慢死', '上夜班的人，心血管病比不上夜班的人多约 13%，心血管死亡多约 27%。而且干得越久越多：每多上 5 年夜班，心血管病再多约 7%。所以这笔账按年数算，能转岗就趁早。至于夜班致癌，证据比流传的说法软得多。', '这些都是只记录、不分组的研究。上夜班的人在吸烟、体重、收入上本来就和别人不一样，校正不干净。夜班致癌这件事，证据比流传的说法软得多。汇总 12 项研究、12,132 例乳腺癌的分析里，干过夜班的人风险只高约 5%，可信范围跨过了 1（RR 1.05，0.96–1.14）。干满 20 年那一档高约 25%（1.25，1.01–1.55），但作者做影响分析后这一项就不显著了，校正可能的发表偏倚后接近 1，原话是这个关联「远未确立」。另一项跟踪中国男性 16.1 年、8,202 例癌症的研究里，夜班和总癌症及多数常见癌都没有关联，只有胰腺癌在累计干 11 到 20 年那一档高约 59%（HR 1.59，1.09–2.31）。所以这条按心血管算账，不按癌症。不是谁都该离开夜班岗位，按年数算的这笔账要你自己算。已经在干的，先把能改的改掉：戒烟见本节第 1 条（戒烟，越早越好），血压血脂见本节第 12 条（有高血压、高血脂就按医嘱规律吃药），夜班之后的觉怎么补见本节第 38 条（熬夜之后第二天晚上就补觉）。另有两条能试的对策：把进食集中在白天，以及用强光加白天严格遮光把生物钟搬过去。后者是唯一被证明真能搬动生物钟的办法。普通室内照明下连上六个夜班，生物钟纹丝不动；换成 7000 到 12000 勒克斯的强光加白天近乎全黑，四天就整个倒了过来。夜里的光要够亮、白天睡觉要严格遮光、下班路上戴墨镜挡晨光，三样缺一不可，漏掉最后一样等于白做。两条对策的终点都只到代谢指标和睡眠，没有试验测过照做能不能把心血管风险降下来。休息日过回白天的生活，钟还会被打回去。剂量、原始数字和其余来源，连同身体怎么认时间，都在 [docs/生物钟和夜班.md](../docs/生物钟和夜班.md)。', NULL, NULL, NULL, '转岗或换工作可能少拿钱，夜班津贴也没了。找工作要花时间，下决心也难。如果是挑工作的时候把这笔账算进去，成本是零。', '把 23 项跟踪研究合起来算，只记录、不分组。上夜班的人心血管事件风险高约 13%（RR 1.13，95% CI 1.10–1.16，这是可信范围）。心血管死亡高约 27%（RR 1.27，1.18–1.36）。按年数看：每多上 5 年夜班，心血管病发生率再高约 7%（RR 1.07，1.04–1.09），心血管死亡再高约 5%（RR 1.05，1.03–1.06）。分病看，冠心病发生高约 22%（1.22，1.16–1.28），冠心病死亡高约 22%（1.22，1.10–1.36），缺血性心脏病死亡高约 39%（1.39，1.06–1.84），卒中死亡高约 49%（1.49，1.04–2.12）。卒中的发生率那一项不显著（1.06，0.95–1.18）。', '这些都是只记录、不分组的研究。上夜班的人在吸烟、体重、收入上本来就和别人不一样，校正不干净。夜班致癌这件事，证据比流传的说法软得多。汇总 12 项研究、12,132 例乳腺癌的分析里，干过夜班的人风险只高约 5%，可信范围跨过了 1（RR 1.05，0.96–1.14）。干满 20 年那一档高约 25%（1.25，1.01–1.55），但作者做影响分析后这一项就不显著了，校正可能的发表偏倚后接近 1，原话是这个关联「远未确立」。另一项跟踪中国男性 16.1 年、8,202 例癌症的研究里，夜班和总癌症及多数常见癌都没有关联，只有胰腺癌在累计干 11 到 20 年那一档高约 59%（HR 1.59，1.09–2.31）。所以这条按心血管算账，不按癌症。不是谁都该离开夜班岗位，按年数算的这笔账要你自己算。已经在干的，先把能改的改掉：戒烟见本节第 1 条（戒烟，越早越好），血压血脂见本节第 12 条（有高血压、高血脂就按医嘱规律吃药），夜班之后的觉怎么补见本节第 38 条（熬夜之后第二天晚上就补觉）。另有两条能试的对策：把进食集中在白天，以及用强光加白天严格遮光把生物钟搬过去。后者是唯一被证明真能搬动生物钟的办法。普通室内照明下连上六个夜班，生物钟纹丝不动；换成 7000 到 12000 勒克斯的强光加白天近乎全黑，四天就整个倒了过来。夜里的光要够亮、白天睡觉要严格遮光、下班路上戴墨镜挡晨光，三样缺一不可，漏掉最后一样等于白做。两条对策的终点都只到代谢指标和睡眠，没有试验测过照做能不能把心血管风险降下来。休息日过回白天的生活，钟还会被打回去。剂量、原始数字和其余来源，连同身体怎么认时间，都在 [docs/生物钟和夜班.md](../docs/生物钟和夜班.md)。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-40', 'concept_archive_s2-40', 'claim_archive_s2-40', 'action', 'life_archive', '买预包装、有 SC 编号的食用油，不买小作坊散装自榨花生油', '2. 不要慢慢死', '花生受潮发霉会长黄曲霉毒素，它是明确的致癌物，主要伤肝。广州管住小作坊之后，常吃自榨油的居民肝功能异常少了约三成半。广西的孕妇吃自榨花生油，孩子出生体重偏低的风险高约九成，早产高约八成。', '两项研究都只是跟踪记录、没有分组对照。广州那项的终点是肝功能化验，不是肝癌和死亡。自榨油的毒素中位数其实低于国标对花生油的限量 20 μg/kg，风险来自长年吃和个别高的批次。国标限量对所有花生油都适用，但预包装油要过生产许可和出厂检验，小作坊按各省的管理办法管，抽检少得多。本条受益人主要是你和一起吃饭的家人。', NULL, NULL, NULL, '换个地方买，钱差不多。看一眼包装上有没有 SC 开头的食品生产许可编号就行。难在说服习惯买自榨油的长辈。', '黄曲霉毒素是国际癌症研究机构定的 1 类致癌物（确定能让人得癌），主要是肝癌。广州一项研究测了 2010 到 2022 年小作坊自榨花生油里的黄曲霉毒素 B1。中位数 1.29 μg/kg，中间一半样品在 0.12 到 6.58 之间。当地出台小作坊管理条例后，油里的毒素马上降了 2.865 μg/kg，之后每年再降 2.593。常吃自榨油那片居民的肝功能异常比例随之下降（PR 0.650，95% CI 0.469–0.902，可信范围），低约 35%。广西一项跟踪 1611 名孕妇的研究里，81.7% 吃自榨花生油。吃的人孩子低出生体重的风险高约九成（aOR 1.9，1.1–3.2），早产高约八成（aOR 1.8，1.1–3.0）。', '两项研究都只是跟踪记录、没有分组对照。广州那项的终点是肝功能化验，不是肝癌和死亡。自榨油的毒素中位数其实低于国标对花生油的限量 20 μg/kg，风险来自长年吃和个别高的批次。国标限量对所有花生油都适用，但预包装油要过生产许可和出厂检验，小作坊按各省的管理办法管，抽检少得多。本条受益人主要是你和一起吃饭的家人。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-41', 'concept_archive_s2-41', 'claim_archive_s2-41', 'action', 'life_archive', '做饭用植物油代替猪油和黄油，不必为了健康换着买油，也别指望亚麻籽油护心', '2. 不要慢慢死', '少吃猪油黄油这类饱和脂肪、换成植物油，心脏病和中风这类事少约一成七，但总的死亡风险没看出变化。大豆油、玉米油、菜籽油之间换来换去，没有证据说有什么区别。亚麻籽油吃多了，心脏病风险也没看出下降。', '争议：有人主张大豆油、玉米油里的 omega-6 太多会促炎，所以要少吃、换油。上面 omega-6 那篇的随机试验没看出害处，证据质量作者自评为低。收益量级按心血管事件低 17% 定为中，总死亡率没变。哪种油都要控制用量，膳食指南建议每人每天烹调油 25 到 30 克。', NULL, NULL, NULL, '不多花钱。植物油本来就是大多数家庭的主力。难在改掉用猪油炒菜、拌饭的口味习惯。', 'Cochrane 汇总了 15 项随机试验、56,675 人，每项至少做两年。少吃饱和脂肪，心血管事件合计低约 17%（RR 0.83，0.70–0.98）。总死亡率几乎不变（RR 0.96，0.90–1.03），心血管死亡也不变（RR 0.95，0.80–1.12）。换成多不饱和脂肪（大豆油、玉米油的主要成分）和换成碳水，效果没看出差别。换成单不饱和脂肪（菜籽油、橄榄油的主要成分）的数据太少，说不清。另一篇 Cochrane 汇总 19 项随机试验、6461 人，多吃 omega-6（亚油酸）对总死亡率 RR 1.00（0.88–1.12），对心血管事件 RR 0.97（0.81–1.15），看不出好处也看不出害处。第三篇汇总 86 项随机试验、162,796 人，多吃植物来源的 omega-3（亚麻籽油、紫苏油的主要成分），总死亡率 RR 1.01（0.84–1.20），冠心病事件 RR 1.00（0.82–1.22），基本没有作用。', '争议：有人主张大豆油、玉米油里的 omega-6 太多会促炎，所以要少吃、换油。上面 omega-6 那篇的随机试验没看出害处，证据质量作者自评为低。收益量级按心血管事件低 17% 定为中，总死亡率没变。哪种油都要控制用量，膳食指南建议每人每天烹调油 25 到 30 克。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-42', 'concept_archive_s2-42', 'claim_archive_s2-42', 'action', 'life_archive', '炒菜、煎炸时打开抽油烟机，从开火一直开到做完', '2. 不要慢慢死', '不吸烟的中国女性，炒菜时不开或很少开抽油烟机，得肺癌的风险约是常开的两倍。住过厨房通风差的房子，风险也高约五成，烧煤的人家最明显。', '争议：支持开抽油烟机的数字主要来自病例对照研究。病人确诊后回忆过去，容易少报开抽油烟机的次数，数字可能偏大。上海那项往后跟踪的研究里，风险升高主要落在烧煤又通风差的人家。只烧燃气的人家开不开差多少，那项研究给不出单独的数。所以证据等级只给 B，收益按约两倍的风险差定为大。做饭不烧煤柴见本节第 29 条（做饭、取暖不烧煤和柴）。本条受益人主要是家里常掌勺的人。', NULL, NULL, NULL, '家里装了抽油烟机的，只多花一点电费。没装的，买一台连安装要几百到上千元。难在每次开火都记得开，别嫌吵就关掉。', '把 10 项病例对照研究合起来算，对象都是不吸烟的中国女性。病例对照是拿肺癌病人和没病的人比，回头问过去的习惯。接触做饭油烟的人，得肺癌的机会约为 1.74 倍（比值比，95% CI 1.57–1.94，可信范围）。其中 4 项比的是接触油烟又不用抽油烟机的人，约为 2.11 倍（1.54–2.89）。台湾一项研究拿 1302 名不吸烟的女性肺癌病人，和 1302 名没病的人对比。只看做饭十年以上的人。三分之二以上的年头都开抽油烟机的，和三分之一以下的比，风险低约一半（比值比 0.49，0.32–0.76）。上海有一项往后跟踪的研究，7.1 万名不吸烟的女性，从 1996 年跟到 2009 年，查出 429 例肺癌。自己说住过厨房通风差的房子的，得肺癌的风险高约 49%（HR 1.49，1.15–1.95）。烧煤又通风差 20 年以上的，约为 2.03 倍（HR 2.03，1.35–3.05）。单看烧没烧过煤，没看出差别（HR 1.03，0.84–1.26）。炒菜用哪种油，也没看出差别。', '争议：支持开抽油烟机的数字主要来自病例对照研究。病人确诊后回忆过去，容易少报开抽油烟机的次数，数字可能偏大。上海那项往后跟踪的研究里，风险升高主要落在烧煤又通风差的人家。只烧燃气的人家开不开差多少，那项研究给不出单独的数。所以证据等级只给 B，收益按约两倍的风险差定为大。做饭不烧煤柴见本节第 29 条（做饭、取暖不烧煤和柴）。本条受益人主要是家里常掌勺的人。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"2. 不要慢慢死","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s2-43', 'concept_archive_s2-43', 'claim_archive_s2-43', 'action', 'life_archive', '绝经前后潮热盗汗影响到生活，就去妇科评估激素治疗，别硬扛也别自己买药，更别拿它防心脏病', '2. 不要慢慢死', '绝经前后潮热、盗汗，用激素治疗，潮热次数比吃安慰剂少约 75%。代价是乳腺癌、血栓、中风会多一点，每年每 1 万名女性里各多出约 8 个人。50 到 59 岁开始用的人，总死亡率没有升高。它不能用来防心脏病和老年痴呆。', '争议：WHI 的女性平均 63 岁，用的是一种固定的口服方案。现在多数人是 50 来岁、刚绝经时为了症状才用，和试验里的人不完全一样。50 到 59 岁那组死亡率低，是分年龄组看出来的，跟到 18 年就不显著了，所以不能说激素能延寿。Cochrane 也写明，试验的规模不够看清绝经 10 年内女性的风险。下面几类人一般不适合用：得过乳腺癌的、有过血栓的、心血管病风险高的、很胖的，具体由医生判断。有子宫的人只用雌激素，子宫内膜癌会增加，所以要同时用孕激素；切了子宫的才可以只用雌激素。激素也能减少骨折，但一般只在不适合用别的抗骨质疏松药时才考虑。骨质疏松先看第 1 节第 39 条（骨密度检查）和第 1 节第 40 条（查出骨质疏松就用药）。收益量级按潮热次数少约 75% 定为大，终点是症状，不是总死亡率。本条受益人主要是你自己，也包括你的母亲和配偶。', NULL, NULL, NULL, '去妇科或更年期门诊看一次。医生会问病史，看你有没有不适合用激素的情况，合适的再开处方。用上以后要按医生的要求复查。难在放下「激素一碰就得癌」的害怕，也别听说能抗衰老就自己去买。', 'Cochrane 汇总了 24 项随机试验、3329 人，比的是口服激素和安慰剂。用激素的人，每周潮热次数比安慰剂少约 75%（95% CI 64.3–82.3，可信范围）。潮热的严重程度也明显减轻（OR 0.13，0.07–0.23）。吃安慰剂的人潮热也少了约 57.7%，所以说能治潮热的东西，都要和安慰剂比过才算数。风险看美国 WHI 随机试验。16608 名有子宫的 50 到 79 岁女性，用雌激素加孕激素，平均跟了 5.2 年。冠心病高约 29%（HR 1.29，1.02–1.63）。浸润性乳腺癌高约 26%（HR 1.26，1.00–1.59）。中风高约 41%（HR 1.41，1.07–1.85）。肺栓塞约为 2.13 倍（HR 2.13，1.39–3.25）。折成绝对数，每 1 万名女性每年多 7 例冠心病、8 例中风、8 例肺栓塞、8 例浸润性乳腺癌。同时少 6 例结直肠癌、5 例髋部骨折。切除了子宫、只用雌激素的女性，累计跟踪 13 年，乳腺癌反而低约 21%（HR 0.79，0.65–0.97）。两项试验合起来跟踪 18 年，总死亡率没有变化（HR 0.99，0.94–1.03）。按开始用药的年龄分，50 到 59 岁那组在用药那几年总死亡率低约 31%（HR 0.69，0.51–0.94）。60 到 69 岁是 1.04（0.87–1.25），70 到 79 岁是 1.13（0.94–1.36），都不显著。跟到 18 年，50 到 59 岁那组是 0.89（0.79–1.01），也不显著了。Cochrane 2017 年的综述单看 50 到 59 岁的女性，唯一明显升高的是雌孕激素联用时的血栓，绝对风险不到 1/500。65 岁以上用雌孕激素联用的女性，4 年里痴呆从每千人 9 例升到 11 到 30 例。美国预防服务工作组 2022 年反对用激素预防慢性病（D 级推荐），结论是没有净好处。', '争议：WHI 的女性平均 63 岁，用的是一种固定的口服方案。现在多数人是 50 来岁、刚绝经时为了症状才用，和试验里的人不完全一样。50 到 59 岁那组死亡率低，是分年龄组看出来的，跟到 18 年就不显著了，所以不能说激素能延寿。Cochrane 也写明，试验的规模不够看清绝经 10 年内女性的风险。下面几类人一般不适合用：得过乳腺癌的、有过血栓的、心血管病风险高的、很胖的，具体由医生判断。有子宫的人只用雌激素，子宫内膜癌会增加，所以要同时用孕激素；切了子宫的才可以只用雌激素。激素也能减少骨折，但一般只在不适合用别的抗骨质疏松药时才考虑。骨质疏松先看第 1 节第 39 条（骨密度检查）和第 1 节第 40 条（查出骨质疏松就用药）。收益量级按潮热次数少约 75% 定为大，终点是症状，不是总死亡率。本条受益人主要是你自己，也包括你的母亲和配偶。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"2. 不要慢慢死","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-1', 'concept_archive_s3-1', 'claim_archive_s3-1', 'action', 'life_archive', '关掉非必要通知，工作时把手机放到视线之外', '3. 不要浪费精力', '手机响一下，哪怕你没看、没碰，注意力任务的成绩也会掉。掉的幅度和你真去接电话、发短信差不多。还有一种情况：手机就搁在桌上，你忍住不看，脑子能用的余量一样会变少。越离不开手机的人，掉得越多。', '这些都是实验室里的单次任务。天天这样累积下来是什么结果，没人测过。真正需要随叫随到的岗位，可以只留少数几个联系人的通知。', NULL, NULL, NULL, '不花钱。花几分钟改一下设置，几乎不需要毅力。', '只是收到一条通知，不看也不碰，注意力任务的成绩就明显变差。变差的幅度和真的接打电话、发短信相当。这是实验室里做的，受试者是大学生。另有两项实验显示：即便成功克制住不去看手机，自己的手机搁在旁边，也会让脑子能用的余量变少。手机依赖强的人下降最多。', '这些都是实验室里的单次任务。天天这样累积下来是什么结果，没人测过。真正需要随叫随到的岗位，可以只留少数几个联系人的通知。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-2', 'concept_archive_s3-2', 'claim_archive_s3-2', 'action', 'life_archive', '固定起床时间，周末也一样', '3. 不要浪费精力', '作息最乱的那五分之一人，生物钟比最规律的那五分之一晚了约 2.5 小时。等于长期活在时差里。作息越规律的学生，成绩也越好。', '只有这一项研究，人数少，也没有分组对照。研究者推算，生物钟的差别主要来自每天晒到的光不一样。所以固定起床时间要配合早上见光，才有效果。偶尔熬夜之后怎么补，见第 2 节第 38 条（熬夜之后第二天晚上就补觉）：办法是当晚早点上床，不是第二天睡到中午。', NULL, NULL, NULL, '不花钱。周末要少睡懒觉，需要一点毅力。', '61 名大学生记录了 30 天。作息最不规律的五分之一，生物钟（昼夜节律）比最规律的五分之一晚约 2.5 小时。具体是褪黑素开始分泌的时刻 00:08 对 21:32。最困、最想睡的时段也晚约 1.8 小时。作息越规律，学业成绩越好（相关系数 r = 0.37）。', '只有这一项研究，人数少，也没有分组对照。研究者推算，生物钟的差别主要来自每天晒到的光不一样。所以固定起床时间要配合早上见光，才有效果。偶尔熬夜之后怎么补，见第 2 节第 38 条（熬夜之后第二天晚上就补觉）：办法是当晚早点上床，不是第二天睡到中午。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-3', 'concept_archive_s3-3', 'claim_archive_s3-3', 'action', 'life_archive', '每晚睡够 7 到 8 小时，别把 6 小时当作够用', '3. 不要浪费精力', '连着两周每晚只睡 6 小时，脑子的表现会掉到相当于两天两夜没合眼的水平。麻烦的是自己感觉不到。自己打分的困倦头几天涨完就不再涨，睡 6 小时的人和睡 4 小时的人打分一样困。所以「我睡 6 小时够用」这句话本身就是缺觉的症状。', '「自己觉得不困」不是睡够了的证据。长期睡 6 小时的人只是感觉上习惯了，表现并没有跟上。汇总多项研究的那部分说的是整夜不睡。「长期少睡」只有一项随机对照试验支持。睡多久和死亡风险的关系另算，见第 2 节第 13 条（每晚睡 7 小时左右）：那边按死亡率算，7 小时那档风险最低。', NULL, NULL, NULL, '不花钱。每天要多留 1 到 2 小时给睡眠。早一点上床，需要一点毅力。', '48 名 21 到 38 岁的健康成人，连续 14 天每晚只睡 6 小时。他们的脑力表现累计下降，掉到相当于连续 2 晚完全不睡的水平。而自己打分的困倦程度只在头几天上升，之后几乎不再增加。6 小时组和 4 小时组的自评困倦没有差别。这是把人随机分成两组做的对照试验（RCT）。另外，短时间不睡（急性睡眠剥夺，不超过 48 小时）对简单注意力走神的效果大小 g = -0.776，对推理准确率 g = -0.125。这部分是把 70 项研究合起来算的。', '「自己觉得不困」不是睡够了的证据。长期睡 6 小时的人只是感觉上习惯了，表现并没有跟上。汇总多项研究的那部分说的是整夜不睡。「长期少睡」只有一项随机对照试验支持。睡多久和死亡风险的关系另算，见第 2 节第 13 条（每晚睡 7 小时左右）：那边按死亡率算，7 小时那档风险最低。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"3. 不要浪费精力","A 级","性价比 一般","口径 时间","钱 0","时间 多","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-4', 'concept_archive_s3-4', 'claim_archive_s3-4', 'action', 'life_archive', '下午两点以后不碰咖啡因', '3. 不要浪费精力', '睡前 6 小时喝一大杯咖啡（400 mg），当晚用仪器测出来少睡 1 小时以上。可自己写的睡眠日记根本看不出差别。一杯普通咖啡（107 mg）要在睡前 8.8 小时以上喝完，才不影响睡眠。十一点睡的人，下午两点就是界线。', 'Drake 那项只有一个实验室做过，用的 400 mg 偏大，大约两三杯咖啡。咖啡因代谢慢的人，截止时间还要更早。少喝咖啡因换回来的是睡眠时长，和第 3 条（每晚睡够 7 到 8 小时）叠加。', NULL, NULL, NULL, '不花钱。习惯下午喝咖啡的人，要忍住不喝，需要一点毅力。', '睡前 6 小时喝 400 mg 咖啡因，仪器测到的总睡眠时间比喝安慰剂少 1.1 到 1.2 小时。安慰剂就是不含咖啡因的对照饮料。可是受试者自己写的睡眠日记没有报出差别，自己察觉不到。把多项研究合起来算（荟萃分析）：咖啡因平均让总睡眠时间减少 45 分钟。躺在床上真正睡着的比例（睡眠效率）下降 7%。一杯咖啡（107 mg）要在睡前 8.8 小时以上喝完，才不影响睡眠。', 'Drake 那项只有一个实验室做过，用的 400 mg 偏大，大约两三杯咖啡。咖啡因代谢慢的人，截止时间还要更早。少喝咖啡因换回来的是睡眠时长，和第 3 条（每晚睡够 7 到 8 小时）叠加。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"3. 不要浪费精力","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-5', 'concept_archive_s3-5', 'claim_archive_s3-5', 'action', 'life_archive', '把邮件和消息改成每天固定几次批量处理', '3. 不要浪费精力', '同一批人对比了两周。把邮件限制成每天只查 3 次的那一周，日常压力明显更低，而收发的邮件数量一样多。不加限制的时候，人平均每天要查 15.5 次。', '只有一项研究，效果中等偏小，量的是压力，不是干出来的活。即时消息没人直接研究过，这里只是照着推的。', NULL, NULL, NULL, '不花钱。要花点时间跟同事说清楚你多久回一次。忍住不随时翻邮件，需要一点毅力。', '124 名成年人，两周里同一批人前后对比（自身对照）。限制为每天查 3 次邮件的那周，日常压力明显低于不限次数那周（效果大小 Cohen''s d = 0.37）。两周收到和回复的邮件数量并没有差别。一开始不加限制时，人们平均每天查邮件 15.5 次。', '只有一项研究，效果中等偏小，量的是压力，不是干出来的活。即时消息没人直接研究过，这里只是照着推的。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-6', 'concept_archive_s3-6', 'claim_archive_s3-6', 'action', 'life_archive', '做需要连续思考的工作时，把哪怕几秒钟的打断也挡在外面', '3. 不要浪费精力', '一次平均 2.8 秒的打断，就让接下来的操作出错概率翻倍。4.4 秒的打断翻三倍。现场跟踪还发现，被打断的那件事平均要 25 分钟才回得来，中间还插进两件别的事。被打断的人干得更快，但压力、挫败感和费劲程度全都更高。', '那项现场研究把打断分成两类：一类是别人来找你的，一类是自己点开的。关门只挡得住前一类。后一类要配合第 1 条（关掉非必要通知）和第 5 条（批量处理消息）一起用。', NULL, NULL, NULL, '不花钱。关上门，戴上耳机，或者挂一个「勿扰」牌。', '平均 2.8 秒的打断，会让按顺序一步步做的任务（序列任务）步骤出错率翻倍。4.4 秒的打断让它翻三倍。这是实验室里做的。另一项是对 24 名办公室白领（信息工作者）的现场观察。他们平均每 11 分钟切换一次工作主题。57% 的工作主题被打断。当天回到被打断的那件事上，平均要 25 分 26 秒。中间还插了 2.26 件别的事。还有一项 48 人的实验：被打断的人做得更快，但报告的压力、挫败感、时间压力和费劲程度都更高。', '那项现场研究把打断分成两类：一类是别人来找你的，一类是自己点开的。关门只挡得住前一类。后一类要配合第 1 条（关掉非必要通知）和第 5 条（批量处理消息）一起用。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 极高","口径 时间","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-7', 'concept_archive_s3-7', 'claim_archive_s3-7', 'action', 'life_archive', '一次只做一件事，不要边开会边回消息', '3. 不要浪费精力', '任务一切换，反应就更慢，也更容易出错。经常同时开好几个屏的人，并没有练出同时做几件事的本事，反而在任务切换测试上表现更差。', '来回切换要多费多少，随干的活差别很大，这里不给统一数字。Ophir 那项是同一时间点的比较，分不清是「多任务让注意力变差」，还是「注意力差的人更爱多任务」。', NULL, NULL, NULL, '不花钱。开会时忍住不回消息，需要一点毅力。', '任务切换以后，反应明显更慢，也更容易出错。这部分来自多项研究的综述。另一项实验室研究的受试者是大学生。经常同时用好几种媒体的人（重度媒体多任务者）更容易被不相干的东西和不相干的记忆带跑。他们在任务切换测试上反而表现更差。', '来回切换要多费多少，随干的活差别很大，这里不给统一数字。Ophir 那项是同一时间点的比较，分不清是「多任务让注意力变差」，还是「注意力差的人更爱多任务」。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-8', 'concept_archive_s3-8', 'claim_archive_s3-8', 'action', 'life_archive', '睡前一小时不看发光屏幕，要看就看纸书或墨水屏', '3. 不要浪费精力', '睡前读发光屏幕，比读纸书晚约 10 分钟才睡着。褪黑素被压低 55%。第二天生物钟往后推 1.5 小时以上，早上更困，要更久才清醒。', '人数少，是实验室里控好条件做的。按日常的手机亮度和使用时长，影响可能没这么大。手机的夜间模式管多大用，这项研究没测。', NULL, NULL, NULL, '不花钱。睡前一小时放下手机，要长期对抗惯性，需要毅力。', '实验室里让同一批人两种条件轮着做（交叉试验）。睡前读发光的电子书，比读纸书入睡慢约 10 分钟（25.7 分钟对 15.8 分钟）。晚间褪黑素被压低 55%。第二天的生物钟（昼夜节律）推迟超过 1.5 小时，褪黑素开始分泌的时刻是 22:31 对 21:01。第二天早上更困，要更长时间才完全清醒。', '人数少，是实验室里控好条件做的。按日常的手机亮度和使用时长，影响可能没这么大。手机的夜间模式管多大用，这项研究没测。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-9', 'concept_archive_s3-9', 'claim_archive_s3-9', 'action', 'life_archive', '到点就睡，不为游戏、短视频、色情内容熬夜', '3. 不要浪费精力', '2025 年中国人夜里平均睡 6.97 小时，平均 0:10 才入睡。睡前用手机、平板的人，睡不够的概率是两倍多，白天犯困的概率是 2.7 倍。设备只是放在卧室里不用，数字也差不多。所以最省事的办法是手机不进卧室。', '争议。熬夜本身的代价见本节第 3 条（每晚睡够 7 到 8 小时）。色情内容对普通人的精力和脑力有什么影响，目前没有可靠证据说得清是不是它造成的。一项把多项研究汇总起来的分析认为，所谓「色情问题」更多来自一个人的观念和自己的行为对不上，而不在内容本身。另一项研究汇总了 280 名男性的数据。结果是看的时长和跟伴侣性生活时的勃起功能没有关系。本条针对的只是它挤占睡眠时间。6.97 小时和 0:10 两个数，中国睡眠研究会官网没有挂出发布稿（2026 年 9 月查），以福建省卫健委转载的健康报报道为准。', NULL, NULL, NULL, '不花钱。难在长期对抗「再看一集」的惯性。手机不进卧室最省力。', '2025 年我国居民夜间平均睡眠 6.97 小时，平均入睡时间 0:10（中国睡眠研究会）。睡前用便携设备的人，睡不够的可能性约为 2.17 倍（OR 2.17）。睡眠质量差约 1.46 倍（OR 1.46）。白天犯困约 2.72 倍（OR 2.72）。设备只是放在卧室里、并不使用，数字也差不多，约 1.79、1.53、2.27 倍（OR 1.79/1.53/2.27）。这部分是把 20 项同一时间点的调查、125198 名儿童青少年合起来算的。另一项同一时间点的调查：844 名 18 到 94 岁成人中，关灯后仍用手机的人入睡更慢，躺在床上真正睡着的比例更低，白天更疲劳。', '争议。熬夜本身的代价见本节第 3 条（每晚睡够 7 到 8 小时）。色情内容对普通人的精力和脑力有什么影响，目前没有可靠证据说得清是不是它造成的。一项把多项研究汇总起来的分析认为，所谓「色情问题」更多来自一个人的观念和自己的行为对不上，而不在内容本身。另一项研究汇总了 280 名男性的数据。结果是看的时长和跟伴侣性生活时的勃起功能没有关系。本条针对的只是它挤占睡眠时间。6.97 小时和 0:10 两个数，中国睡眠研究会官网没有挂出发布稿（2026 年 9 月查），以福建省卫健委转载的健康报报道为准。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-10', 'concept_archive_s3-10', 'claim_archive_s3-10', 'action', 'life_archive', '深夜不做重大决定、不发要紧的消息', '3. 不要浪费精力', '人睡饱的时候，很快就能学会躲开高风险的选项。连着两晚没睡之后，反而一次次挑高风险的，年纪越大越明显。少睡几小时有多大影响没人测过，但要紧的决定还是推到睡醒以后。', '研究的是连续两晚不睡的极端情况。普通人熬到凌晨两点会怎样，没有直接测过。「不发消息」那半是作者经验（C 级），第二天再发也不迟。', NULL, NULL, NULL, '不花钱。只是把事情推到睡醒之后再办。', '34 名健康人在 49.5 小时不睡之后，做爱荷华赌博任务。这是一种衡量风险决策的实验。休息充足时，他们能很快学会避开高风险选项。缺觉之后，反而更多地选高风险选项。年纪大的人受影响更大。这是一项实验，只有这一项研究。', '研究的是连续两晚不睡的极端情况。普通人熬到凌晨两点会怎样，没有直接测过。「不发消息」那半是作者经验（C 级），第二天再发也不迟。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-11', 'concept_archive_s3-11', 'claim_archive_s3-11', 'action', 'life_archive', '下午困了就睡 10 分钟，不要睡半小时', '3. 不要浪费精力', '10 分钟的小睡当场就能提神，效果能撑两个半小时。睡 5 分钟基本没用。睡 20 分钟要等半小时以后才见效。睡 30 分钟，醒来先有一段发懵，那阵子表现比不睡还差。', '只有一项实验室研究，受试者都是健康年轻人。睡不着也不必勉强。闭着眼躺 10 分钟有没有用，没有研究支持。午睡睡过一小时反而和更高的死亡率、冠心病风险连在一起，见第 2 节第 37 条（午睡控制在半小时内）。', NULL, NULL, NULL, '不花钱。花 10 分钟，再找一个能躺下或者趴着的地方。', '在前一晚没睡够之后，10 分钟的小睡能立刻改善困倦、疲劳、精力和脑力表现，一部分好处维持到 155 分钟以后。睡 5 分钟几乎没有好处。睡 20 分钟的好处要等 35 分钟以后才出现。睡 30 分钟以后先有一段睡眠惰性：刚醒那阵表现反而更差，之后才改善。', '只有一项实验室研究，受试者都是健康年轻人。睡不着也不必勉强。闭着眼躺 10 分钟有没有用，没有研究支持。午睡睡过一小时反而和更高的死亡率、冠心病风险连在一起，见第 2 节第 37 条（午睡控制在半小时内）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-12', 'concept_archive_s3-12', 'claim_archive_s3-12', 'action', 'life_archive', '在开放式办公室工作时用耳塞或找安静房间做需要记忆的活', '3. 不要浪费精力', '背景噪音从 39 分贝涨到 51 分贝，能记住的词就变少，人更累，也更不想干活。休息的时候看带声音的自然风光片，比接着听办公室噪音更能把精力找回来。', '只有一项实验室研究。噪音里最碍事的是能听清内容的说话声。白噪音耳机对这一点有帮助，但这项研究没测过耳机。', NULL, NULL, NULL, '耳塞几十元。预订安静的会议室要花点时间。', '让学生在模拟的开放式办公室里工作。背景噪音从 39 分贝升到 51 分贝（dB，LAeq）时，他们记住的词更少，自己评分更疲劳，也更不想干活。休息时看带声音的自然影片，比只听河流声或者办公室噪音，更能把精力评分拉回来。', '只有一项实验室研究。噪音里最碍事的是能听清内容的说话声。白噪音耳机对这一点有帮助，但这项研究没测过耳机。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-13', 'concept_archive_s3-13', 'claim_archive_s3-13', 'action', 'life_archive', '每周工作时间不要超过 49 小时', '3. 不要浪费精力', '一战时英国军工厂的记录显示，每周干 49 小时以内，干多久就出多少活。超过 49 小时，多干一小时多出的活越来越少。一周干 70 小时和干 56 小时出的活几乎一样，多干的那 14 小时是白干。', '数据来自一百年前的工厂，干的是体力活，工人以女性为主。这道坎搬到脑力工作上不一定一样，作者自己也说别的工种可能更高或更低。可靠的是方向：过了某个点，再多干也几乎不多出活。49 这个具体数字不可靠。', NULL, NULL, NULL, '可能少拿一些加班费。也可能要花力气和上级谈。', '一战时期英国军工厂工人的产出记录：每周 49 小时以内，产出与工时成正比。超过 49 小时，产出的增速开始变慢。大约 63 小时达到最大。干 70 小时的产出与干 56 小时几乎没有差别，多干的 14 小时等于白干。', '数据来自一百年前的工厂，干的是体力活，工人以女性为主。这道坎搬到脑力工作上不一定一样，作者自己也说别的工种可能更高或更低。可靠的是方向：过了某个点，再多干也几乎不多出活。49 这个具体数字不可靠。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 高","口径 时间","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-14', 'concept_archive_s3-14', 'claim_archive_s3-14', 'action', 'life_archive', '发现自己在反复回想同一件糟心事时，换个需要动手的活', '3. 不要浪费精力', '反复回想同一件糟心事，不会想出答案。它只会加重抑郁，把负面念头钉得更牢，让人更解决不了问题，也更难真动手，还会把身边愿意听你说的人耗光。察觉到自己在原地绕，就去干点要动手的活。', '综述只给了方向，没有数字。「换个活」是作者自己的做法。文献能撑住的只有一句：把注意力岔开，好过接着在原地绕。至于换成什么活，没人比较过。', NULL, NULL, NULL, '不花钱。难在要先察觉自己正在反复回想（这叫反刍），察觉本身就要练。', '多项研究的综述说，反复回想同一件糟心事（反刍思维）会加重抑郁。它还会强化负面思考，削弱解决问题的能力。它会妨碍实际行动，还会把身边愿意听你说的人耗光。它与焦虑、暴食、酗酒、自伤相关。', '综述只给了方向，没有数字。「换个活」是作者自己的做法。文献能撑住的只有一句：把注意力岔开，好过接着在原地绕。至于换成什么活，没人比较过。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-15', 'concept_archive_s3-15', 'claim_archive_s3-15', 'action', 'life_archive', '把「事情肯定会更糟」这类念头当症状看，不当事实看', '3. 不要浪费精力', '一项跟踪了 20 年的双生子研究里，悲观程度每高一个档，同期死亡的概率高约 13%，死于心血管病的概率高约 20%。反过来，乐观得分高并没有带来相应的好处。所以要处理的是悲观，不是「不够正能量」。', '争议。这只是观察，没有分组。有人会说「其实是先有病才悲观」，作者反驳说，真那样的话癌症死亡也该相关。但仍然可能有没测到的因素。乐观并没有保护作用，所以不必强迫自己「积极思考」。要做的是别把悲观预期当成对未来的准确预测。', NULL, NULL, NULL, '不花钱。难在把这种念头当成症状看，而不是当成事实。', '澳大利亚 2978 名 50 岁以上的双生子，平均跟踪 20 年，其间有 1068 人死亡。悲观量表每高 1 个标准差，同期死亡的风险高约 13%（风险比 1.134）。这个数字的可信范围是 95% CI 1.065–1.207，P=8.85×10⁻⁵。心血管死亡高约 20%（1.196，1.045–1.368，P=0.0093）。与癌症死亡无关。乐观得分与死亡率也没有明显关联。', '争议。这只是观察，没有分组。有人会说「其实是先有病才悲观」，作者反驳说，真那样的话癌症死亡也该相关。但仍然可能有没测到的因素。乐观并没有保护作用，所以不必强迫自己「积极思考」。要做的是别把悲观预期当成对未来的准确预测。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-16', 'concept_archive_s3-16', 'claim_archive_s3-16', 'action', 'life_archive', '减少让你消耗的人际关系，学会拒绝不想接的请求', '3. 不要浪费精力', '一个消耗你的人造成的损失，比一个支持你的人带来的好处更大，也更一致。所以先做减法，再做加法。', '受访人群特殊，而且是一次性问卷，看不出先后。量的是幸福感，不是精力。放在本节是作者的推断。哪些关系算「消耗」没有客观标准，只能自己判断。', NULL, NULL, NULL, '不花钱。短期内会有社交摩擦，可能失去一部分关系。开口拒绝需要相当的毅力。', '对 120 名 60 到 89 岁丧偶女性的调查：让人难受的来往和心理幸福感的关联，比让人舒服的来往更一致、也更强。按这个结果，一个消耗你的人造成的损失，大于一个支持你的人带来的好处。', '受访人群特殊，而且是一次性问卷，看不出先后。量的是幸福感，不是精力。放在本节是作者的推断。哪些关系算「消耗」没有客观标准，只能自己判断。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","C 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-17', 'concept_archive_s3-17', 'claim_archive_s3-17', 'action', 'life_archive', '生气时先离场，把对方当天气而不是当敌人', '3. 不要浪费精力', '换个角度解释刚发生的事，或者站到对方立场想一下，都能实打实把情绪降下来，后一种更管用。硬压着不表现出来没有效果。另外，惩罚了冒犯者的人，事后反而更久地反复想这件事；不报复的人翻篇更快。报复带来的痛快，人们事先高估了。', '汇总多项研究的那部分量的是情绪强度，不是精力，效果小到中等。报复那部分只有一组实验，所以定 B。「空船」是庄子《山木》里的寓言：空船撞过来不生气，船上有人才生气，可撞的是同一下。这是类比，不是证据。真有损失，就走第 8 节和第 9 节的法律路径，比当场发作便宜得多。', NULL, NULL, NULL, '不花钱。当场要忍住不回嘴，转身走开，事后再决定要不要处理。这需要一点练习。', '把 306 组实验比较合起来算（荟萃分析）：换个角度解释发生的事（认知重评）对情绪的效果大小 d = 0.36。站到对方立场看 d = 0.45。转移注意 d = 0.27。硬压住感受无效（d = -0.04）。另有三项实验显示：惩罚冒犯者的人，事后反而更久地反复想对方；不惩罚的人更快「翻篇」。人们事先高估了报复带来的痛快。', '汇总多项研究的那部分量的是情绪强度，不是精力，效果小到中等。报复那部分只有一组实验，所以定 B。「空船」是庄子《山木》里的寓言：空船撞过来不生气，船上有人才生气，可撞的是同一下。这是类比，不是证据。真有损失，就走第 8 节和第 9 节的法律路径，比当场发作便宜得多。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-18', 'concept_archive_s3-18', 'claim_archive_s3-18', 'action', 'life_archive', '情绪低落时先做性价比最高的几件事：动起来、晒太阳、按时睡、找人说、打 12356', '3. 不要浪费精力', '对抑郁来说，快走和慢跑效果最好，强度越大越有效，细节见第 22 节第 6 条（心情差就去走或者跑）。晒光照对季节性抑郁效果很强，对不分季节的抑郁也有效。网上的自助认知行为课程管用，症状偏重时有人带着做更好。想不开先打 12356。', '这些都是轻中度抑郁的辅助手段。中重度、有自杀念头的要去就医，先打 12356（见第 1 节第 25 条）。运动试验大多人数少，又没法像试药那样瞒住谁在运动。光照研究只到 2003 年，人数也少。「按时睡」「找人说」是作者经验，没有单列文献。别把「动起来」当成对抑郁者的要求，能走十分钟就算数。', NULL, NULL, NULL, '不花钱，或者花很少。每周几次快走、慢跑或者力量训练。白天出门晒太阳。作息固定下来。想不开时打一个电话。', '把 218 项随机分组的对照试验、14170 人合起来算（网络荟萃分析）。对照组是同样在做别的活动的人。和他们相比，步行或慢跑对抑郁的效果大小 g = -0.62（95% 可信区间 -0.80 到 -0.45）。瑜伽 -0.55，力量训练 -0.49。强度越大效果越好。把多项光照治疗研究合起来算：季节性抑郁效果大小 0.84（0.60 到 1.08），非季节性抑郁 0.53（0.18 到 0.89）。还有一项分析，把各项研究逐个病人的数据合起来算。它看的是互联网认知行为疗法（网上自助课程）。有人指导和无人指导，都比对照组好。中重度（PHQ-9 大于 9 分）的时候，有人指导的更好。12356 是全国心理援助热线，每日开通不少于 18 小时。', '这些都是轻中度抑郁的辅助手段。中重度、有自杀念头的要去就医，先打 12356（见第 1 节第 25 条）。运动试验大多人数少，又没法像试药那样瞒住谁在运动。光照研究只到 2003 年，人数也少。「按时睡」「找人说」是作者经验，没有单列文献。别把「动起来」当成对抑郁者的要求，能走十分钟就算数。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"3. 不要浪费精力","A 级","性价比 高","口径 时间","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-19', 'concept_archive_s3-19', 'claim_archive_s3-19', 'action', 'life_archive', '把警察、医生、柜员当成按规则上班的人，别当成角色：能推动事情的是文书和期限，不是情绪', '3. 不要浪费精力', '警察、医生、柜员都是按岗位规则上班的人，被文书、期限和监督管着。对方态度好不好，和你的事办不办、几天办完基本无关。所以要拿回执、记期限、按渠道申诉，别想着把道理讲到对方认同。', '定 C 的理由：「很多人把窗口后面的人当成一个角色、不当成上班的人」这个判断本身没有文献可引。能引的只有规则那一半：期限、文书和救济渠道都是明文的。本条引的数字全部来自第 8 节第 39 条（报警之后的流程）那两份公安部规章。按流程走管不了「对方态度差」，也不保证一定办成，改的只是你的预期和第一步动作。银行柜员、政务窗口也一样：他们操作留痕、要复核、出错要追责。所以该做的是留凭条、要回单、按渠道投诉，别凭「他会不会坑我」瞎猜。合法的优先级都写在明处，比如急诊按病情分级，不按先来后到（第 24 节第 7 条，急诊预检分诊）。想谢救过你的医生，就走感谢信和满意度评价，见第 24 节第 11 条。想「送点东西让人家多上点心」，对办案执法的人就是行贿罪，而且是明文从重的，见第 8 节第 40 条。遇到明显的区别对待，该投诉就投诉，别当成潜规则去模仿。', NULL, NULL, NULL, '不花钱。改的是你的预期和动作顺序。第一次要忍住「把道理讲到对方认同」的冲动。', '把和机构打交道的动作换一换：从「求人、生气、反复复述委屈」，换成「拿文书、记期限、按渠道申诉」。省下的是重复沟通和反复回想的时间。这属于一次性的观念调整，不是每天都省时间。能拿来核对的是这些期限本身，它们都写在文件里。治安案件从受理那天算起，办案期限不超过 30 日；案情重大复杂的，经上一级公安机关批准可以延长 30 日。有控告人的案件决定不予立案的，不予立案通知书要在 3 日以内送达。控告人 7 日以内可以申请复议，公安机关 30 日以内作出决定。不服的，再 7 日以内向上一级申请复核。', '定 C 的理由：「很多人把窗口后面的人当成一个角色、不当成上班的人」这个判断本身没有文献可引。能引的只有规则那一半：期限、文书和救济渠道都是明文的。本条引的数字全部来自第 8 节第 39 条（报警之后的流程）那两份公安部规章。按流程走管不了「对方态度差」，也不保证一定办成，改的只是你的预期和第一步动作。银行柜员、政务窗口也一样：他们操作留痕、要复核、出错要追责。所以该做的是留凭条、要回单、按渠道投诉，别凭「他会不会坑我」瞎猜。合法的优先级都写在明处，比如急诊按病情分级，不按先来后到（第 24 节第 7 条，急诊预检分诊）。想谢救过你的医生，就走感谢信和满意度评价，见第 24 节第 11 条。想「送点东西让人家多上点心」，对办案执法的人就是行贿罪，而且是明文从重的，见第 8 节第 40 条。遇到明显的区别对待，该投诉就投诉，别当成潜规则去模仿。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","C 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-20', 'concept_archive_s3-20', 'claim_archive_s3-20', 'action', 'life_archive', '别把「别人过得怎么样」当每日必读：给刷同龄人动态的应用设限或关掉', '3. 不要浪费精力', '习惯在网上跟过得更好的人比的人，往往情绪更差、自尊更低。把 Facebook 停用四周的人，幸福感小幅提高，但对时事的了解也掉了一截。把三个社交平台各限到每天 10 分钟的人，三周后孤独和抑郁都降了下来。', '「相关」那一半只说明两件事一起出现，不能读成谁导致谁，作者自己也说还需要更多长期跟踪的研究。随机分组那一半能说因果，但受试者是 2018 年美国中期选举前的 Facebook 用户，搬到中国的平台上属于硬套。Hunt 那项只有 143 名本科生，而且就这一项。效应量都不大，别指望关掉应用就能解决情绪问题。要拦的是「看别人过得怎么样」这一类使用，和家人朋友联系、查信息、找工作不在内。真按不住，就先从关推送、关「可能认识的人」和首页推荐入手。总屏幕时间的账见第 4 节第 15、16 条（短视频硬上限、不看滚动新闻）。情绪低落时先做什么，见本节第 18 条（动起来、晒太阳、按时睡）。靠买东西找回身份感见第 6 节第 23 条。为了「往上挪一档」多花钱见第 6 节第 24 条。', NULL, NULL, NULL, '不花钱。给应用设限时，或者把账号停掉，都是几分钟的事。难的是之后不再打开，要长期对抗惯性。', '把多项研究合起来算（荟萃分析）：54 个独立样本、94 个效应量、N = 36,583，用的是三层随机效应模型。网上向上社会比较与心理适应不良的平均相关 r = 0.330（95% CI 0.289–0.370，可信范围）。按具体结果分开看。怕被人看轻这类社会评价性的负面情绪 0.438，焦虑 0.382。抑郁 0.306，幸福感偏低 0.268，自尊偏低 0.263。年龄、文化背景、数据采集年份都不影响这个关联的强弱。长期跟踪的研究得出的结果，也不比同一时间点的调查更强。另有一项随机分组的对照试验，受试者是 2,743 名美国 Facebook 用户。其中 61% 的人愿意以低于 102 美元接受停用。这些人被随机分为停用四周组与对照组。停用为普通受试者每天空出 60 分钟。主观幸福感指数提高 0.09 个标准差。分项是生活满意度 0.12、焦虑 0.10、抑郁 0.09、快乐 0.08。把多次比较碰巧的成分扣掉后，这些仍然算数。作者给了一个参照，是让人变积极的心理干预。这类干预对主观幸福感约 +0.34 个标准差，对抑郁约 -0.23 个标准差。所以这个效应约为常规心理干预的 25% 到 40%。同期的代价是：时事知识指数下降 0.19 个标准差，政治立场对立程度下降 0.16 个标准差。实验结束后，停用组的 Facebook 使用仍比对照低 12 分钟/天（0.31 个标准差，降幅 23%）。还有一项随机分组的对照试验，受试者是 143 名本科生，被随机分成两组。一组把 Facebook、Instagram、Snapchat 每个平台每天限 10 分钟，另一组照常使用。三周后，限时组的孤独与抑郁明显下降。两组的焦虑与错失恐惧都比一开始低。', '「相关」那一半只说明两件事一起出现，不能读成谁导致谁，作者自己也说还需要更多长期跟踪的研究。随机分组那一半能说因果，但受试者是 2018 年美国中期选举前的 Facebook 用户，搬到中国的平台上属于硬套。Hunt 那项只有 143 名本科生，而且就这一项。效应量都不大，别指望关掉应用就能解决情绪问题。要拦的是「看别人过得怎么样」这一类使用，和家人朋友联系、查信息、找工作不在内。真按不住，就先从关推送、关「可能认识的人」和首页推荐入手。总屏幕时间的账见第 4 节第 15、16 条（短视频硬上限、不看滚动新闻）。情绪低落时先做什么，见本节第 18 条（动起来、晒太阳、按时睡）。靠买东西找回身份感见第 6 节第 23 条。为了「往上挪一档」多花钱见第 6 节第 24 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"3. 不要浪费精力","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-21', 'concept_archive_s3-21', 'claim_archive_s3-21', 'action', 'life_archive', '觉得「所有人都看见我出丑了」的时候，把这个估计除以二', '3. 不要浪费精力', '穿一件尴尬的 T 恤走进有人的房间，穿的人以为将近一半人认得出衣服上印的是谁，实际不到四分之一。穿自己觉得体面的 T 恤，估计的人数是实际的六倍。人聊完天，也普遍低估对方有多喜欢自己。所以觉得「所有人都记住我出丑了」时，砍一半仍然偏高。', '定 B 的理由：都是人数不多的实验室与校园研究，场景是穿衣服和跟陌生人聊天。搬到「被同事议论」「在会上说错话」上，没有直接证据。这些数字只说明高估的方向和大致倍数，没法当系数套。别人的看法也不是都不重要。真正在评价你的场合，比如面试、答辩、考核、体检报告，评价是实打实的，该准备就准备。要打折的只是日常里那种「所有人都在看我」的感觉，那部分要对付的是你自己的估计偏差。', NULL, NULL, NULL, '不花钱。只是在紧张的时候多问自己一句：他们真的看见了吗。', '实验一：让参与者穿上印有 Barry Manilow 头像的 T 恤，走进有其他参与者的房间。穿的人平均估计 46% 的旁观者能正确指出衣服上的人是谁。旁观者实际正确率 23%，估计值恰为实际值的两倍。逐场把估计值减去实际值，平均高估 23 个百分点（95% CI 9–38，可信范围）。剔除只有两名和三名旁观者的那两场之后，为 27 个百分点（11–43）。实验二：改穿参与者自选的、自认为正面的 T 恤。平均估计 48%，旁观者实际正确率 8%，为六倍。另一系列研究有三种场景：陌生人配对交谈、大学新生室友、成人工作坊。结果是人们系统性低估交谈对象对自己的喜欢程度，也低估对方对这次交谈的享受程度。作者称之为「喜欢差」。不同长度的交谈中都存在，在新生室友之间持续数月。', '定 B 的理由：都是人数不多的实验室与校园研究，场景是穿衣服和跟陌生人聊天。搬到「被同事议论」「在会上说错话」上，没有直接证据。这些数字只说明高估的方向和大致倍数，没法当系数套。别人的看法也不是都不重要。真正在评价你的场合，比如面试、答辩、考核、体检报告，评价是实打实的，该准备就准备。要打折的只是日常里那种「所有人都在看我」的感觉，那部分要对付的是你自己的估计偏差。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-22', 'concept_archive_s3-22', 'claim_archive_s3-22', 'action', 'life_archive', '把「别人要求我做到完美」当症状看，不当事实看', '3. 不要浪费精力', '总觉得「周围的人要求我完美，做不到就会被否定」的人，更容易有自杀念头。「我自己要求自己完美」和自杀念头的关系弱得多，只有前一种的三分之一左右。把原本就有的念头扣掉，前一种感觉仍和后来念头变多有关，只是幅度不大。', '定 B 的理由：纳入的研究多数是一次性问卷，看不出先后。相关强度中等（r 约 .28），大致只解释几个到一成的差异。量的是自杀念头和自杀未遂，不是死亡本身，所以收益量级按「只有替代终点」记小。作者自己也说，完美主义担忧与自杀未遂这一组像是有发表偏倚。发表偏倚指结果不好看的研究没被发出来。把估算的缺失研究补回去后，结论方向不变。高标准本身不是问题，也不必因此降低要求。区别在于标准从哪来，以及达不到时会不会觉得「我这个人就完了」。它和第 15 条（把「事情肯定会更糟」这类念头当症状看）里的悲观预期一样，是可以当症状处理的东西。有自杀念头先打 12356、把致死手段挪远，见第 1 节第 25 条。身边人流露出这种念头时你能做什么，见第 8 节第 15 条。孩子的抑郁筛查见第 30 节第 8 条。', NULL, NULL, NULL, '不花钱。难的是把这种念头当成需要处理的东西，而不是当成对别人真实要求的准确测量。', '把多项研究合起来算（荟萃分析）：45 项研究、N = 11,747，人群为本科生、医学生、社区成人与精神科患者，用的是随机效应模型。下面是与自杀念头的加权平均相关。完美主义担忧 r = .28（95% CI .24–.32，可信范围；42 项研究、7,936 人）。完美主义担忧是一个合集，包括社会规定型完美主义、在意犯错、对行动的怀疑、现实与标准的落差等。其中社会规定型完美主义单独算，也是 r = .28（.25–.32，30 项研究、3,640 人）。完美主义追求 r = .10（.07–.13，31 项研究、4,588 人），它是自我导向的完美主义与个人标准的合集。父母批评 r = .20（.11–.29）。再看与自杀未遂的关系。完美主义担忧 r = .12（.07–.17，15 项研究、5,275 人）。社会规定型完美主义 r = .19（.08–.29，8 项研究、689 人）。跟踪一段时间的那部分：把一开始就有的自杀念头扣除后，社会规定型完美主义仍与后来随访时的自杀念头同向变化，幅度不大。自我导向与他人导向的完美主义都看不出关联。', '定 B 的理由：纳入的研究多数是一次性问卷，看不出先后。相关强度中等（r 约 .28），大致只解释几个到一成的差异。量的是自杀念头和自杀未遂，不是死亡本身，所以收益量级按「只有替代终点」记小。作者自己也说，完美主义担忧与自杀未遂这一组像是有发表偏倚。发表偏倚指结果不好看的研究没被发出来。把估算的缺失研究补回去后，结论方向不变。高标准本身不是问题，也不必因此降低要求。区别在于标准从哪来，以及达不到时会不会觉得「我这个人就完了」。它和第 15 条（把「事情肯定会更糟」这类念头当症状看）里的悲观预期一样，是可以当症状处理的东西。有自杀念头先打 12356、把致死手段挪远，见第 1 节第 25 条。身边人流露出这种念头时你能做什么，见第 8 节第 15 条。孩子的抑郁筛查见第 30 节第 8 条。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-23', 'concept_archive_s3-23', 'claim_archive_s3-23', 'action', 'life_archive', '生气时别靠砸东西、打沙袋、跑一圈来发泄，先让身体慢下来', '3. 不要浪费精力', '打沙袋、摔东西、去跑一圈，这类让身体更兴奋的发泄办法，整体上消不了气。慢呼吸、正念、冥想这类让身体静下来的办法，能明显压下怒气和想动手的劲。', '量的是怒气和攻击性，不是精力。口径记成时间，是作者的归类：少吵一架，就少收拾一次残局。当场能用的办法见第 22 节第 8 条（循环叹息），还有本节第 17 条（生气时先离场）。跑步不是没用。长期看，它对情绪低落有效，见第 22 节第 6 条（心情差就去走或者跑）。它只是不适合拿来当场消气。气头上别开车，别发消息，别做决定。如果是有人在打你，先离开、报警。那时要处理的不是你的情绪，见第 8 节第 43 条（被家暴了）。', NULL, NULL, NULL, '不花钱。气头上改做几分钟让心跳慢下来的事：慢慢呼吸，坐下来，静一静。难在当时最想做的恰恰是发泄。', '把 154 项研究合起来算（荟萃分析），共 184 组样本、10,189 人。让身体平静下来的办法，比如深呼吸、正念、冥想，能降低怒气和攻击性。效果大小 g = -0.63，95% CI -0.82 到 -0.43（可信范围）。这个结果在不同性别、种族、年龄和文化的人里都稳定。让身体更兴奋的办法，比如打沙袋、慢跑、骑车，整体无效。它的效果大小 g = -0.02，95% CI -0.13 到 0.09。作者的结论是：发泄怒气、去跑一圈，都不是管用的消气办法。', '量的是怒气和攻击性，不是精力。口径记成时间，是作者的归类：少吵一架，就少收拾一次残局。当场能用的办法见第 22 节第 8 条（循环叹息），还有本节第 17 条（生气时先离场）。跑步不是没用。长期看，它对情绪低落有效，见第 22 节第 6 条（心情差就去走或者跑）。它只是不适合拿来当场消气。气头上别开车，别发消息，别做决定。如果是有人在打你，先离开、报警。那时要处理的不是你的情绪，见第 8 节第 43 条（被家暴了）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"3. 不要浪费精力","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-24', 'concept_archive_s3-24', 'claim_archive_s3-24', 'action', 'life_archive', '心里压着一件事，可以连着几天把想法和感受写下来，但别指望它治病', '3. 不要浪费精力', '把糟心事写下来，平均有一点好处，但很小。汇总的结论也不一致，有两项汇总算下来没有效果。它几乎不花钱，可以试。情绪问题重了，别拿它代替看医生。', '争议。支持的一方是 146 项研究的汇总，效果为正但很小。反对的一方是两项只收随机对照试验的汇总，都没算出显著效果。成本栏里写几次、每次多久，来自最早的实验设计，Mogk 那篇汇总的摘要里写了。它几乎不花钱，也不花多少时间，一个人就能做。不想找人说、身边也没人可说的时候，可以用它。量的不是精力，口径记成时间是作者的归类。写着写着越来越难受，就停下，改打 12356，见第 1 节第 25 条（12356）。', NULL, NULL, NULL, '不花钱。研究里常见的做法是写 3 到 4 次，每次 15 到 20 分钟。写一件让你难受的事，写你最深的想法和感受。', '一项分析汇总了 146 项随机分组的研究（荟萃分析）。研究里的人把对自己重要的事写下来或者说出来。平均效果是正的，也显著，但很小，效果大小 r = .075。另一项汇总只收随机对照试验，30 项试验合起来算，身体健康和心理健康两方面都没有显著效果。针对癌症病人和康复者的 16 项随机试验合起来算，心理、身体、生活质量三方面都不显著。其中心理方面 g = 0.04，95% CI -0.06 到 0.14（可信范围）。', '争议。支持的一方是 146 项研究的汇总，效果为正但很小。反对的一方是两项只收随机对照试验的汇总，都没算出显著效果。成本栏里写几次、每次多久，来自最早的实验设计，Mogk 那篇汇总的摘要里写了。它几乎不花钱，也不花多少时间，一个人就能做。不想找人说、身边也没人可说的时候，可以用它。量的不是精力，口径记成时间是作者的归类。写着写着越来越难受，就停下，改打 12356，见第 1 节第 25 条（12356）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"3. 不要浪费精力","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s3-25', 'concept_archive_s3-25', 'claim_archive_s3-25', 'action', 'life_archive', '痛经就吃布洛芬这类止痛药，别硬扛；痛到耽误上班上学、吃三个月药也压不住，就去妇科查', '3. 不要浪费精力', '痛经吃布洛芬这类药，痛明显减轻的人从不到两成升到约一半，比对乙酰氨基酚管用，副作用多一点。痛到耽误上班上学、同房时深处痛，或者吃三个月药还压不住，就去妇科查子宫内膜异位症。这个病平均拖 6.7 年才确诊。', '60 岁以上、胃出过血、在吃抗凝药或激素的人，用这类药前先问医生。细节见第 34 节第 3 条（布洛芬这类止痛药）。美国布洛芬说明书写明，它可能引起严重过敏，对阿司匹林过敏的人更容易出，表现里有哮喘发作。有哮喘的人用前也要先问医生。可能怀孕时先问医生，怀孕 20 周以后别自己吃，见第 34 节第 5 条（怀孕 20 周以后）。不能吃这类药的，可以改用对乙酰氨基酚，一天的上限见第 34 节第 1 条（对乙酰氨基酚）。痛经只在来月经那几天吃药。第 34 节第 9 条（止痛药一个月别吃超过 15 天）的门槛管的是头痛，痛经吃药的天数也远到不了。定 A 是因为止痛效果来自大量随机试验。作者把多数比较的证据质量评为低，主要是试验方法写得不清楚，59% 的试验由药厂资助。收益定「中」是判断：综述只量了痛不痛，没量少请几天假。荷兰那项调查里，月经带来的损失折合每年约 10 天，摊到每周是小时级。子宫内膜异位症那组人是已经去做腹腔镜的，不代表痛经的人多数有这个病。受益人主要是你自己。', NULL, NULL, NULL, '一盒布洛芬十几块钱，只在痛的那几天吃。需要去妇科的，挂号、做 B 超要花一些钱和半天时间。', '一篇 Cochrane 系统综述汇总了 80 项随机对照试验、5820 名原发性痛经的女性。原发性痛经指查不出别的病的痛经。和安慰剂比，非甾体抗炎药止痛更有效（OR 4.37，95% CI 3.76–5.09，可信范围）。换算过来，吃安慰剂的人有 18% 得到中等以上的缓解，吃这类药的人是 45% 到 53%。代价是副作用多一些（OR 1.29，1.11–1.51）。吃安慰剂的人有 10% 出副作用，吃这类药的是 11% 到 14%。多出来的主要是肠胃不适（OR 1.58）和神经系统反应（OR 2.74）。和对乙酰氨基酚比，这类药止痛也更有效（OR 1.89，1.05–3.43），不过只有 3 项试验。哪一种这类药最好，没比出差别。英国 NICE 指南（2024 年更新）列出要怀疑子宫内膜异位症的几种情况。它们是长期盆腔痛，痛经影响日常活动和生活质量，同房时或同房后深处痛。还有经期排便痛，经期尿血或尿痛，以及伴有这些症状的不孕。17 岁及以下的女孩也算在内。指南建议先试用对乙酰氨基酚或这类药，比如 3 个月。止痛不够，就转去做进一步检查。妇科检查和 B 超都正常，也不能排除这个病。一项研究在 10 个国家的 16 家医院调查了 1418 名做腹腔镜的女性。从出现症状到手术确诊子宫内膜异位症，平均拖了 6.7 年，主要耽误在基层看病那一段。确诊的女性平均每周少干 10.8 小时的活，多数是人在岗上、效率下降。荷兰一项网上调查问了 32748 名 15 到 45 岁的女性。13.8% 因为月经请过假，平均每年 1.3 天。80.7% 来月经时人在岗上但效率下降，折合每年少干 8.9 天。', '60 岁以上、胃出过血、在吃抗凝药或激素的人，用这类药前先问医生。细节见第 34 节第 3 条（布洛芬这类止痛药）。美国布洛芬说明书写明，它可能引起严重过敏，对阿司匹林过敏的人更容易出，表现里有哮喘发作。有哮喘的人用前也要先问医生。可能怀孕时先问医生，怀孕 20 周以后别自己吃，见第 34 节第 5 条（怀孕 20 周以后）。不能吃这类药的，可以改用对乙酰氨基酚，一天的上限见第 34 节第 1 条（对乙酰氨基酚）。痛经只在来月经那几天吃药。第 34 节第 9 条（止痛药一个月别吃超过 15 天）的门槛管的是头痛，痛经吃药的天数也远到不了。定 A 是因为止痛效果来自大量随机试验。作者把多数比较的证据质量评为低，主要是试验方法写得不清楚，59% 的试验由药厂资助。收益定「中」是判断：综述只量了痛不痛，没量少请几天假。荷兰那项调查里，月经带来的损失折合每年约 10 天，摊到每周是小时级。子宫内膜异位症那组人是已经去做腹腔镜的，不代表痛经的人多数有这个病。受益人主要是你自己。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"3. 不要浪费精力","A 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-1', 'concept_archive_s4-1', 'claim_archive_s4-1', 'action', 'life_archive', '把「打算做」写成「几点、在哪、遇到什么就做什么」', '4. 不要浪费时间', '把「我要做这件事」改写成「周二早 8 点坐到书桌前就先写引言」。94 项检验合起来算，这么写的人把目标做成的比例明显更高，属于中到大的效果。改的只是一句话的写法，不花钱，也不费力气。', '这招只对你自己真想做的事有效。目标本身你就不想要，写再多句也没用。另外，这些研究找的多是学生，看的多是健康方面的习惯，搬到工作场景不一定同样管用。', NULL, NULL, NULL, '不花钱。每件事花 1 到 2 分钟，写一句「如果……就……」。比如「周二早 8 点坐到书桌前就先写引言」。', '把 94 项独立检验合起来算，先把打算写成「如果……就……」的人，目标达成率更高。这种写法在心理学里叫实施意图。效果大小 d = 0.65，算中到大。管用的环节有三个：开始动手、被打扰的时候顶住、从注定做不成的事上撤出来。', '这招只对你自己真想做的事有效。目标本身你就不想要，写再多句也没用。另外，这些研究找的多是学生，看的多是健康方面的习惯，搬到工作场景不一定同样管用。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"4. 不要浪费时间","A 级","性价比 极高","口径 时间","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-2', 'concept_archive_s4-2', 'claim_archive_s4-2', 'action', 'life_archive', '开工前写下退出条件', '4. 不要浪费时间', '开工前先写好一句话：到某月某日还没达到某个指标就停。多项研究合起来算，这种写法确实能帮人从注定做不成的事上撤下来。省下的是你本来还要接着往里砸的全部时间。', '退出条件要在刚开工、情绪还冷静的时候定。事后再定会被已经投进去的成本带偏。判断时只看未来投入和未来回报，见第 3 条。另外，「肯撤出」只是多项研究汇总里的一个分项结论，没有人单独算过它能省下多少时间。', NULL, NULL, NULL, '不花钱。开工的时候花 5 分钟，写清「到某月某日没达到某个指标就停」。难在到了那天要认账，当着人停手有点丢面子。', '把多项实施意图研究合起来算，结果是：事先定好的「如果……就……」，同样能帮人从注定做不成的事上撤出来。原文的说法是 disengagement from failing courses of action。省下的时间，就是你本来还会继续投进去的那些。', '退出条件要在刚开工、情绪还冷静的时候定。事后再定会被已经投进去的成本带偏。判断时只看未来投入和未来回报，见第 3 条。另外，「肯撤出」只是多项研究汇总里的一个分项结论，没有人单独算过它能省下多少时间。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-3', 'concept_archive_s4-3', 'claim_archive_s4-3', 'action', 'life_archive', '决定是否继续时，只看未来投入和未来回报，不看已投入多少', '4. 不要浪费时间', '已经投进去的钱和时间，会让人更想接着干下去。98 组数据合起来算，这个倾向稳定存在。所以判断要不要继续，只算往后还要投多少、还能拿回多少。已经花掉的那些，不要算进去。', 'Arkes 和 Blumer 那项剧院实验是这样做的。俄亥俄大学剧院卖季票，随机给买票的人原价 15 美元、便宜 2 美元、便宜 7 美元三种价。前半季，原价那组平均看了 4.11 场，另两组是 3.32 和 3.29 场。后半季三组就没有明显差别了。Roth 等人发现，这种影响会随时间变淡，年纪大的人受影响更小。', NULL, NULL, NULL, '不花钱。难在要接受一件事：之前投进去的时间已经没了，拿不回来。', '已经投入的钱、精力和时间，会让人更想继续做下去。这在心理学里叫沉没成本效应。把 98 组数据合起来算，分析确认这种倾向稳定存在。避开这种倾向，就不会为了「不想浪费」继续往里投时间。', 'Arkes 和 Blumer 那项剧院实验是这样做的。俄亥俄大学剧院卖季票，随机给买票的人原价 15 美元、便宜 2 美元、便宜 7 美元三种价。前半季，原价那组平均看了 4.11 场，另两组是 3.32 和 3.29 场。后半季三组就没有明显差别了。Roth 等人发现，这种影响会随时间变淡，年纪大的人受影响更小。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-4', 'concept_archive_s4-4', 'claim_archive_s4-4', 'action', 'life_archive', '估工期时按过去同类任务的实际耗时估，不按计划推', '4. 不要浪费时间', '学生估自己 33.9 天写完论文，实际用了 55.5 天，只有 29.7% 的人按自己估的时间做完。另一组被要求先回想上次同类的事花了多久再估，按时完成的比例从 29.3% 升到 60.0%。', 'Buehler 那项只找了加拿大大学生，是单独一项研究，人也少，37 人和每组约 40 人。照同类项目的历史数据来估，这种做法叫参考类预测，工程上具体怎么做见 Flyvbjerg。Halkjelsvik 汇总多项研究后指出，估少比估多更常见，但差多少随任务和研究方法变化很大。', NULL, NULL, NULL, '不花钱。估之前花几分钟，翻一下上次同类的事实际做了多久。', '学生预计 33.9 天完成论文，实际用了 55.5 天。只有 29.7% 的人按自己的估计按时完成。研究者要求另一组人先把过去的经历和眼下这件事挂上钩，再去估。这一组按时完成的比例，从对照组的 29.3% 升到 60.0%。把工期往少了估的那种乐观，在这一组身上不再出现。', 'Buehler 那项只找了加拿大大学生，是单独一项研究，人也少，37 人和每组约 40 人。照同类项目的历史数据来估，这种做法叫参考类预测，工程上具体怎么做见 Flyvbjerg。Halkjelsvik 汇总多项研究后指出，估少比估多更常见，但差多少随任务和研究方法变化很大。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 极高","口径 时间","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-5', 'concept_archive_s4-5', 'claim_archive_s4-5', 'action', 'life_archive', '会前发议程，没议程的会不开；能站着开就站着开', '4. 不要浪费时间', '会前发了议程的会，参会者更容易觉得这个会有用。实验里，坐着开的会比站着开的长 34%，而两种开法做出的决定，好坏没有差别。', '站会那项实验做的是 5 人小组在实验室里的任务。长会和大型会议不能照搬这个结论。Leach 测的是参会者自己觉得效果如何，不是实际干出了多少活。', NULL, NULL, NULL, '不花钱。组织者会前花 5 到 10 分钟写一份议程。站着开会要参会者配合。', '两项调查分别有 958 人和 292 人。结果是：会前发了议程的会，参会者更容易觉得这个会有效果，这个关系在统计上站得住。另一项实验里 55 组坐着开会，56 组站着开会，坐着开的时长多 34%。两种开法做出的决定，质量没有差别。', '站会那项实验做的是 5 人小组在实验室里的任务。长会和大型会议不能照搬这个结论。Leach 测的是参会者自己觉得效果如何，不是实际干出了多少活。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-6', 'concept_archive_s4-6', 'claim_archive_s4-6', 'action', 'life_archive', '砍会议数量，能用文字异步解决的不开会', '4. 不要浪费时间', '当天开的会越多，人越累，自己感觉手上的活也越多。砍掉一个会，省下的时间就是那个会本身的长度，一分不打折。', '争议：Rogelberg 2006 发现，会议多少和幸福感之间不是一边倒。工作上高度依赖别人的岗位，会议多反而不算坏事。另外，没有研究把「改用文字异步沟通」和开会直接比过，这条是作者自己的推论。', NULL, NULL, NULL, '不花钱。要同事和上级配合。难在写清楚一段文字，比张嘴说一句费精力。', '两项调查找的是每周工作 35 小时以上的员工，分别有 676 人和 304 人。开会占掉多少时间，对工作态度和幸福感的影响不是固定的，要看两件事：会开得好不好，这个岗位干活有多依赖别人。另一项研究让人连记一周日记，结果是当天开会次数越多，疲劳和自己感觉到的工作量越高。省下的时间，等于你砍掉的会议时长本身。', '争议：Rogelberg 2006 发现，会议多少和幸福感之间不是一边倒。工作上高度依赖别人的岗位，会议多反而不算坏事。另外，没有研究把「改用文字异步沟通」和开会直接比过，这条是作者自己的推论。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-7', 'concept_archive_s4-7', 'claim_archive_s4-7', 'action', 'life_archive', '把大任务拆成子任务再估时、再开工', '4. 不要浪费时间', '人估工期的时候，不会自动把任务拆开一件件算。先把子任务列出来再估，就能少估短一截。拆开之后，每一小步都能马上动手，也就不那么容易拖。', '拆到什么程度合适：以「每个子任务能在一次坐下来的时间里做完」为准，拆得过细本身也耗时间。另外，Kruger 和 Evans 那项只从摘要核实到方向，具体百分比没核到原文。', NULL, NULL, NULL, '不花钱。拆分本身花 5 到 15 分钟。', '人们估工期时，不会自己把一件有好几头的任务拆成几块。比如写文献综述、写讨论、整理参考文献，这本来就是几件事。先把子任务列出来再估，能少犯把工期估短的毛病，这个毛病叫规划谬误。拆开之后，每一小步都成了一个可以立刻开始的动作，拖延也跟着变少。研究里最能预示拖延的因素，包括对这件事的厌恶感，以及任务本身被往后推。', '拆到什么程度合适：以「每个子任务能在一次坐下来的时间里做完」为准，拆得过细本身也耗时间。另外，Kruger 和 Evans 那项只从摘要核实到方向，具体百分比没核到原文。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-8', 'concept_archive_s4-8', 'claim_archive_s4-8', 'action', 'life_archive', '给没有外部截止的事自己定一个日期', '4. 不要浪费时间', '有别人定的截止日期时，80.6% 的学生能在那之前做完。按自己预计的时间做完的，只有 38.7%。什么时候做完，几乎由截止日期决定，和自己估的关系不大。所以没有截止日期的事，自己给它定一个，并且认账。', '把自己定的日期告诉别人，它就更接近别人定的那一种。要说明的是，研究验证的是别人定的截止日期管用。自己给自己定的那种，比如时间盒、番茄钟，没人直接测过，这里是照着推的。', NULL, NULL, NULL, '不花钱。难在定了就要认，到了那天不当回事就等于没定。', '有外部截止日期的学生，80.6% 在截止前完成。而在自己预计的时间内完成的，只有 38.7%。什么时候做完，几乎跟着截止日期走，相关系数 r = 0.82，这个数越接近 1 说明跟得越紧。和自己的预计只有很弱的关系。', '把自己定的日期告诉别人，它就更接近别人定的那一种。要说明的是，研究验证的是别人定的截止日期管用。自己给自己定的那种，比如时间盒、番茄钟，没人直接测过，这里是照着推的。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-9', 'concept_archive_s4-9', 'claim_archive_s4-9', 'action', 'life_archive', '把拖延当成在躲开难受，不要当成不够努力', '4. 不要浪费时间', '拖延和懒、和性格关系不大。最能看出一个人拖不拖的，是这件事本身让他多难受、他觉不觉得自己做得成、他有多容易被眼前的东西带走。所以有用的是把任务改得没那么难受、把第一步改小，不是骂自己一顿再硬上。', '收益量级记「中」，因为这些研究只指出方向，没有量过能省下多少小时。具体动作在本节第 1 条（写成「几点、在哪、遇到什么就做什么」）、第 7 条（把大任务拆成子任务）、第 8 条（给没有外部截止的事定一个日期）。这些是相关研究的汇总，看不出谁导致谁。', NULL, NULL, NULL, '不花钱。改的只是判断方向：先问这件事哪里让你难受，再想办法。', '一份汇总了 691 个相关系数的荟萃分析发现，和拖延关系强而稳定的有几样：任务让人厌恶的程度、离截止还有多远、自我效能感（觉得自己做得成）、冲动性，以及尽责性和它下面的自控、易分心、条理性、成就动机。而神经质、叛逆、寻求刺激和拖延只有很弱的关联。作者用时间动机理论来解释这组结果：一件事现在的吸引力，随着回报变远而快速变小。', '收益量级记「中」，因为这些研究只指出方向，没有量过能省下多少小时。具体动作在本节第 1 条（写成「几点、在哪、遇到什么就做什么」）、第 7 条（把大任务拆成子任务）、第 8 条（给没有外部截止的事定一个日期）。这些是相关研究的汇总，看不出谁导致谁。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"4. 不要浪费时间","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-10', 'concept_archive_s4-10', 'claim_archive_s4-10', 'action', 'life_archive', '把要用的东西摆到手边，把不想碰的挪远，别指望当场忍住', '4. 不要浪费时间', '东西离得远一点，人就少拿一点。把同样的零食放远，吃下去的量明显下降，属于中等大小的效果。少摆几个选项，拿的人也明显变少。这类办法不用你当场忍，几分钟就能布置好。', '定 B 级的理由：这份综述收进来的 24 项研究全部是食物，酒和烟一项都没有；14 项在实验室做，全部来自高收入国家。所以「挪远就少碰」搬到手机和游戏上属于顺推，没有直接试验。把手机放到视线之外这一件事有人直接测过，见第 3 节第 1 条（关掉非必要通知，工作时把手机放到视线之外）。', NULL, NULL, NULL, '不花钱，一次几分钟。把手机放到另一个房间，把书和电脑摊在桌上。', '一份纳入 24 项随机试验的 Cochrane 综述。把食物放得更远，吃掉的量下降，标准化均数差 −0.60（95% CI −0.84 到 −0.36，这是可信范围；12 项研究、1098 人，低确定性证据），属于中等效应。把可选项减少，选择该食物的下降更明显，标准化均数差 −1.13（95% CI −1.90 到 −0.37，3 项研究、154 人，低确定性证据）。回归分析显示：放得越远、可选项越单一，效果越强。', '定 B 级的理由：这份综述收进来的 24 项研究全部是食物，酒和烟一项都没有；14 项在实验室做，全部来自高收入国家。所以「挪远就少碰」搬到手机和游戏上属于顺推，没有直接试验。把手机放到视线之外这一件事有人直接测过，见第 3 节第 1 条（关掉非必要通知，工作时把手机放到视线之外）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-11', 'concept_archive_s4-11', 'claim_archive_s4-11', 'action', 'life_archive', '想让自己做到就把钱押上，但先问自己肯不肯押', '4. 不要浪费时间', '想逼自己做到，可以做到了就领奖金，也可以先交押金、做到才退还再加奖。两种都肯参加的人里，交押金的做到的多出 13 个百分点。但肯交押金的只有 13.7%，肯拿奖金的有 90%，所以押金只对肯押的人有用。', '这个试验测的是戒烟，搬到写论文、健身这类事上属于顺推，所以收益量级记「中」。选方案时先看自己会不会真的用它。多数人不肯接受的办法，效果再强，对这些人也没有用。所以先挑你肯接受的那种，押小一点也比不押强。戒烟本身怎么戒见第 2 节第 3 条（戒烟药）。', NULL, NULL, NULL, '押金式的方案要先拿出一笔自己的钱，做不到就没收。试验里押的是 150 美元。', '美国一项 2538 人的随机试验，把员工和他们的亲友随机分到四种激励方案或常规照护。奖励型（做到给约 800 美元）的接受率 90.0%，押金型（先交 150 美元，另加 650 美元奖励）13.7%。六个月的持续戒烟率：四种激励方案在 9.4% 到 16.0% 之间，常规照护 6.0%。奖励型 15.7%，押金型 10.2%。但在只算「两种都肯参加」的那 13.7% 的人里，押金型的六个月戒烟率比奖励型高 13.2 个百分点（95% CI 3.1 到 22.8，这是可信范围）。', '这个试验测的是戒烟，搬到写论文、健身这类事上属于顺推，所以收益量级记「中」。选方案时先看自己会不会真的用它。多数人不肯接受的办法，效果再强，对这些人也没有用。所以先挑你肯接受的那种，押小一点也比不押强。戒烟本身怎么戒见第 2 节第 3 条（戒烟药）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"4. 不要浪费时间","A 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-12', 'concept_archive_s4-12', 'claim_archive_s4-12', 'action', 'life_archive', '新习惯按月算，不要按「21 天」算', '4. 不要浪费时间', '「21 天养成一个习惯」没有依据。一项跟踪 12 周的研究算下来，一个动作变得不用想就做，快的 18 天，慢的要 254 天。两三周还没变轻松是正常的。中间漏掉一天，也不会把进度清零。', '只有这一项研究，96 人，做的都是简单动作（比如饭后吃一份水果）。复杂的事要多久，比如每周跑三次、每天写作，没人测过。所以两周后还很费劲，不能当成失败的证据。要让重复真的发生，把动作绑在一个固定场景上，见本节第 1 条（写成「几点、在哪、遇到什么就做什么」）。', NULL, NULL, NULL, '不花钱。要的是在同一个场景下每天重复同一个动作，持续几个月。', '96 名志愿者各挑一个吃、喝或者活动方面的动作，在固定场景下（比如「早饭后」）每天做，持续 12 周，每天给自己的自动化程度打分。82 人的数据够用来分析，模型在 62 人身上拟合成功。达到各自自动化上限 95% 所需的天数，范围是 18 天到 254 天。研究还发现，漏掉一次执行机会对习惯养成过程没有实质影响。', '只有这一项研究，96 人，做的都是简单动作（比如饭后吃一份水果）。复杂的事要多久，比如每周跑三次、每天写作，没人测过。所以两周后还很费劲，不能当成失败的证据。要让重复真的发生，把动作绑在一个固定场景上，见本节第 1 条（写成「几点、在哪、遇到什么就做什么」）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-13', 'concept_archive_s4-13', 'claim_archive_s4-13', 'action', 'life_archive', '拖延已经影响生活的，用有随机试验支持的自助材料，不用非找治疗师', '4. 不要浪费时间', '拖延严重到让人痛苦，是能治的。照着认知行为自助材料练十周，有人带着做和完全自己做，都明显比什么都不做好。有人带和没人带看不出差别，所以自己照着做也有效。', '受试者是瑞典成年人，用的是瑞典语材料，中文里没有现成的同一套，所以收益量级记「中」。材料里的成分就是常见那几样：行为激活、行为实验、刺激控制、关于动机和工作方法的讲解。刺激控制那一样在本节第 10 条（把不想碰的挪远）。拖延同时伴着明显的情绪低落或者焦虑，先按第 3 节第 18 条（动起来、晒太阳、按时睡、找人说、打 12356）来。', NULL, NULL, NULL, '一本自助书几十元，有的免费。要投入十周左右，每周读一节、做一次练习。', '150 人随机分成三组：有治疗师指导的自助、无指导的自助、等待名单对照。十周后，纯拖延量表上的组间效应量，有指导组 d = 0.70（95% CI 0.29–1.10，这是可信范围），无指导组 d = 0.50（0.10–0.90）；非理性拖延量表上分别是 0.81（0.40–1.22）和 0.69（0.29–1.09）。达到临床意义改善的比例：有指导组 31.3% 到 40.0%，无指导组 24.0% 到 36.0%。两组在任何一项结果上都没有显著差别。', '受试者是瑞典成年人，用的是瑞典语材料，中文里没有现成的同一套，所以收益量级记「中」。材料里的成分就是常见那几样：行为激活、行为实验、刺激控制、关于动机和工作方法的讲解。刺激控制那一样在本节第 10 条（把不想碰的挪远）。拖延同时伴着明显的情绪低落或者焦虑，先按第 3 节第 18 条（动起来、晒太阳、按时睡、找人说、打 12356）来。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"4. 不要浪费时间","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-14', 'concept_archive_s4-14', 'claim_archive_s4-14', 'action', 'life_archive', '用自己的时薪决定哪些家务外包', '4. 不要浪费时间', '中国人平均每天花 1 小时 17 分做家务。当天真动手做的那部分人，花 1 小时 59 分。花钱买时间的人，生活满意度更高。同样一笔钱，花在买时间上比买东西，当下更让人开心。', '先算时薪，算法是一个月税后收入 ÷ 一个月实际工作小时。再看这项家务外包要多少钱。外包单价低于你的时薪，而且省下的时间你确实会用在挣钱或者休息上，就外包。每个人的时薪和外包价都不同，结论要自己算。另外，Whillans 测的是花钱买时间之后人开不开心，不是省下了多少小时。', NULL, NULL, NULL, '要花一笔外包的钱，多少看你买的是什么服务。另外要先花一次时间，把自己的时薪算清楚。', '中国居民做家务每天平均 1 小时 17 分钟。只算做了家务的人，平均 1 小时 59 分钟。这是 2024 年的调查，覆盖 3.85 万户、10.7 万人。另一项研究取了四个国家 6271 人的样本，花钱买时间的人生活满意度更高。研究者还在真实生活里做了实验：同一笔钱，花在买时间上比买实物带来更高的当下幸福感。', '先算时薪，算法是一个月税后收入 ÷ 一个月实际工作小时。再看这项家务外包要多少钱。外包单价低于你的时薪，而且省下的时间你确实会用在挣钱或者休息上，就外包。每个人的时薪和外包价都不同，结论要自己算。另外，Whillans 测的是花钱买时间之后人开不开心，不是省下了多少小时。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 高","口径 时间","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-15', 'concept_archive_s4-15', 'claim_archive_s4-15', 'action', 'life_archive', '给短视频和无目的刷屏设硬上限', '4. 不要浪费时间', '中国人平均每天上网 5 小时 37 分。当天真上了网的人，是 6 小时 3 分。2018 年按同样算法还只有 2 小时 42 分。这是本节里数字最大的一项。每天砍掉一小时，一年就多出 365 小时。', '上网时间里包含工作、学习和社交，不全是浪费。定成 C 级，是因为没有研究算过「限制之后省回多少、这些时间又用到了哪里」，手上只有总量统计。其中「刷别人过得怎么样」这一类，有随机试验测过省回多少、情绪变了多少，见第 3 节第 20 条。', NULL, NULL, NULL, '不花钱。动作只要几分钟：关掉推送，删掉应用，或者给应用设一个每天的时间上限。难在管住手，忍住不点开。', '中国居民上网每天平均 5 小时 37 分钟。只算当天真上了网的人，平均 6 小时 3 分钟。当天用过网的人占 92.9%。这些是 2024 年的数字。2018 年按同样算法只有 2 小时 42 分钟。这是本节里数字最大的一项。每天砍掉其中一小时，等于每年多出 365 小时。另据中国互联网络信息中心，到 2025 年 6 月，网民平均每周上网 30.6 小时，比半年前多 1.9 小时。短视频用户有 10.68 亿人，占网民的 95.1%。', '上网时间里包含工作、学习和社交，不全是浪费。定成 C 级，是因为没有研究算过「限制之后省回多少、这些时间又用到了哪里」，手上只有总量统计。其中「刷别人过得怎么样」这一类，有随机试验测过省回多少、情绪变了多少，见第 3 节第 20 条。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","C 级","性价比 高","口径 时间","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-16', 'concept_archive_s4-16', 'claim_archive_s4-16', 'action', 'life_archive', '不看电视和滚动新闻，需要的信息定时集中看', '4. 不要浪费时间', '美国 15 岁以上的人每天看 2.6 小时电视，占掉全部闲暇时间的一半。中国人平均每天看 1 小时 40 分，75 到 84 岁的老人看 3 小时 16 分。把要看的信息改成定时集中看，省下的就是这一整块。', '手上只有总量统计。没有研究算过，少看电视和新闻之后，省下的时间被用到了哪里。「集中看」这个做法是作者经验。', NULL, NULL, NULL, '不花钱。难在改掉随手打开的习惯，还可能错过一些即时消息。', '美国 15 岁以上的人每天看电视 2.6 小时。他们全部休闲时间是 5.2 小时，看电视占掉一半。这是 2025 年的数字。中国居民看电视每天平均 1 小时 40 分钟，75 到 84 岁的人 3 小时 16 分钟。这是 2018 年的数字。', '手上只有总量统计。没有研究算过，少看电视和新闻之后，省下的时间被用到了哪里。「集中看」这个做法是作者经验。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","C 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-17', 'concept_archive_s4-17', 'claim_archive_s4-17', 'action', 'life_archive', '花一次时间学常用软件的键盘快捷键和自动化', '4. 不要浪费时间', '多数用了很多年 Word 的人，还是在点工具栏图标。分组对比的实验里，快捷键比菜单和图标都快。学这一次是一次性花费，之后每天每次操作都在回本。做同一类工作越久，赚回来越多。', '只学你每天要用到十次以上的操作，学得太全是另一种浪费。要说明的是，那项效率实验只有 6 名参与者，摘要也没有给出每次操作节省的秒数。', NULL, NULL, NULL, '不花钱。要一次性投入几小时到几十小时去学。难在刚上手那阵子比用鼠标还慢。', '研究看了 251 名有经验的 Word 用户，多数人很少用更快的快捷键，还是以点图标工具栏为主。分组对比的实验确认，菜单、图标、快捷键这三种方式里，快捷键最快。省回的时间随每天操作次数一点点累积。长期做同一类工作的人，收益最大。', '只学你每天要用到十次以上的操作，学得太全是另一种浪费。要说明的是，那项效率实验只有 6 名参与者，摘要也没有给出每次操作节省的秒数。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s4-18', 'concept_archive_s4-18', 'claim_archive_s4-18', 'action', 'life_archive', '选住处时把通勤时长放在前面，缩短单程通勤', '4. 不要浪费时间', '通勤越长的人，自己觉得过得越不好。这笔损失并没有在工资或者住房上被补回来。单程少 30 分钟，一周就省出 5 小时。', '争议：Chatterjee 等人汇总多项研究后指出，通勤长短和整体生活满意度之间还看不出稳定的关系。他们认为，人们大体上能用更好的工作或住房，把长通勤的损失换回来。还要注意，交通活动的统计算的是所有出行，不只是通勤。另外能错峰上下班的话，同样一段路也能跑得更短。', NULL, NULL, NULL, '成本高。可能要付更高的房租，或者换一套更小的房子。搬家本身也要花时间。', '中国居民每天花在交通上平均 50 分钟。只算当天有出行的人，是 1 小时 2 分钟。这是 2024 年的数字。德国长期跟踪同一批人的数据显示，通勤越长的人主观幸福感（自己觉得过得好不好）稳定地更低。而且这笔损失没有在收入或住房上得到补偿。把多项研究梳理到一起的综述也确认，通勤时间越长，人对通勤越不满意，这一点和用什么交通方式无关。单程少 30 分钟，每周约省 5 小时。', '争议：Chatterjee 等人汇总多项研究后指出，通勤长短和整体生活满意度之间还看不出稳定的关系。他们认为，人们大体上能用更好的工作或住房，把长通勤的损失换回来。还要注意，交通活动的统计算的是所有出行，不只是通勤。另外能错峰上下班的话，同样一段路也能跑得更短。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"4. 不要浪费时间","B 级","性价比 一般","口径 时间","钱 多","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-1', 'concept_archive_s5-1', 'claim_archive_s5-1', 'action', 'life_archive', '关掉所有自动续费，改为到期手动续', '5. 不要浪费钱', '省下来的，是那些你早就不用、每月还在扣钱的订阅。翻一遍支付宝、微信、苹果和安卓的自动扣款列表，用不了 20 分钟。按规定，商家扣款前要明显提醒你，还必须给你一个随时能取消的入口，而且要好找好点。', '你确实经常用的服务，年付一般比月付便宜，留着自动续费反而划算。要关的是你早就忘了、却还在扣钱的那些。', NULL, NULL, NULL, '不花钱。把支付宝、微信、苹果、安卓的「自动扣款」列表翻一遍，一次 10 到 20 分钟。以后每次续费，要自己多点一次。', '省下的钱，等于你已经不用、却还在扣费的那些订阅加起来的钱。每个人不一样，没有统一数字。监管要求商家在续费前明显提醒你，还要给你一个「简便的随时取消」的选项，取消不用另外花钱（中国，2021 年起施行）', '你确实经常用的服务，年付一般比月付便宜，留着自动续费反而划算。要关的是你早就忘了、却还在扣钱的那些。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-2', 'concept_archive_s5-2', 'claim_archive_s5-2', 'action', 'life_archive', '每年三月到六月做一次个税汇算，专项附加扣除该填的填', '5. 不要浪费钱', '这几种人办下来通常能退到钱：全年只干了几个月，年中换过工作，或者子女教育、房贷、房租、赡养老人这些扣除没填。在手机上十几分钟就能办。如果你一年综合所得不到 12 万元，或者该补的税不到 400 元，可以不办。', '该补税的人也要办，不办是违法的。专项附加扣除一共七项：子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人、3 岁以下婴幼儿照护。其中房贷和房租只能选一样，不能两样都填', NULL, NULL, NULL, '不花钱。在「个人所得税」App 上办，十几分钟就完了。', '把工资薪金、劳务报酬、稿酬、特许权使用费这四项合起来算一次总账。多交的退给你，少交的要补上。有两种情况可以不办：你一年的综合所得收入不超过 12 万元，或者要补的税不超过 400 元。这两条是国家税务总局 2023 年公告定的，管到 2027 年 12 月 31 日。反过来，下面这几种人办下来通常能退到钱：全年只有几个月有收入的，年中换过工作的，有子女教育、房贷、房租、赡养老人等扣除没填的', '该补税的人也要办，不办是违法的。专项附加扣除一共七项：子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人、3 岁以下婴幼儿照护。其中房贷和房租只能选一样，不能两样都填', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-3', 'concept_archive_s5-3', 'claim_archive_s5-3', 'action', 'life_archive', '公积金不只用来买房：租房、装修、物业费都能提，2026 年 9 月 20 日起按新条例办', '5. 不要浪费钱', '公积金不是只有买房才能动。新条例把能提取的情况列了九项，租房、装修自己住的房子、交物业费都算在里面。你交了申请，公积金中心要在 3 天内答复你准不准提。', '账户里的钱是你自己的工资，加上单位给你配的那一部分。这笔钱放着不动，只按很低的利率算利息。条例还写明：职工死亡，或者被宣告死亡的，继承人和受遗赠人可以提取账户余额。办理要交哪些材料、具体怎么办，各地由当地公积金管理中心定。跑之前先查一下本地中心的办事指南。', NULL, NULL, NULL, '不花钱。去办一次提取手续就行。', '修改后的条例把可以提取的情况列到九项。其中包括：支付房租，装修自己住的房子，支付自己住的房子的物业费。公积金管理中心要从受理你申请那天算起，3 日内作出准予提取或者不准提取的决定', '账户里的钱是你自己的工资，加上单位给你配的那一部分。这笔钱放着不动，只按很低的利率算利息。条例还写明：职工死亡，或者被宣告死亡的，继承人和受遗赠人可以提取账户余额。办理要交哪些材料、具体怎么办，各地由当地公积金管理中心定。跑之前先查一下本地中心的办事指南。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-4', 'concept_archive_s5-4', 'claim_archive_s5-4', 'action', 'life_archive', '每年重算一次手机和宽带套餐，用不上的降档，运营商不给转就投诉', '5. 不要浪费钱', '你用的老套餐，往往比现在新卖的贵几十块钱。一个月几十，一年就是几百块白扔。按规定，运营商没有正当理由，不能拒绝你转网，也不能拖着不给你办，更不能专门给转网的人单独设一套资费。它卡着不放，你就投诉。', '先在营业厅 App 里查你近半年实际用了多少流量和通话，再按这个用量去选套餐。客服要是说「降档得到营业厅办」「合约期内不能改」，你就要求他给出书面依据。他给不出，就打 12300 投诉', NULL, NULL, NULL, '不花钱。查一次账单，十几分钟。难的是要顶住客服不给你降档。', '工信部的规章写明，运营商不得「无正当理由拒绝、阻止、拖延向用户提供携号转网服务」。也不得「采取拦截、限制等技术手段影响携号转网用户的通信服务质量」。还不得「为携号转网用户设置专项资费方案和营销方案」。老套餐往往比现在在售的套餐贵几十元。一直不换，就是每年白扔几百元', '先在营业厅 App 里查你近半年实际用了多少流量和通话，再按这个用量去选套餐。客服要是说「降档得到营业厅办」「合约期内不能改」，你就要求他给出书面依据。他给不出，就打 12300 投诉', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-5', 'concept_archive_s5-5', 'claim_archive_s5-5', 'action', 'life_archive', '不买彩票', '5. 不要浪费钱', '按规定，乐透数字型彩票拿出来当奖金的钱，最少是销售额的 50%，双色球是 51%。也就是你每投 1 元，长期平均只能拿回 0.51 元，稳定亏掉 49%。2024 年全国卖了 6234.86 亿元彩票，其中 1610.31 亿元直接进了公益金，这部分不在奖金里。', '长期平均下来一定亏，这是制度定死的，和运气无关。要买也行，但只能当成 2 元一次的娱乐花销，不能当成理财。', NULL, NULL, NULL, '不花钱。不买就是省钱。', '财政部规定了奖金占销售额的最低比例：乐透型和数字型彩票 50%，即开型 65%，竞猜型 73%。双色球按销售额的 51% 提奖金，每卖 100 元只拿出 51 元当奖金。换算到你身上，每投入 1 元，长期平均只能拿回 0.51 元，亏掉 49%。2024 年全国彩票卖了 6234.86 亿元，其中 1610.31 亿元进了公益金，没有回到买彩票的人手里（中国，2024 年）', '长期平均下来一定亏，这是制度定死的，和运气无关。要买也行，但只能当成 2 元一次的娱乐花销，不能当成理财。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-6', 'concept_archive_s5-6', 'claim_archive_s5-6', 'action', 'life_archive', '看到「高收益」「保本」「稳赚」直接走开', '5. 不要浪费钱', '监管部门自己的说法是：收益率超过 6% 就要打问号，超过 8% 很危险，10% 以上就要准备赔光本金。正规理财已经不许承诺保本保收益了。参加非法集资亏掉的钱，按规定由你自己承担，出事没人替你兜底。', '6%、8%、10% 这三条线是监管者按经验画的，不是法律条文。原话是在讲打击非法集资时说的，针对的是承诺高回报的理财产品和投资公司。不构成投资建议。', NULL, NULL, NULL, '不花钱。听到这几个词的时候停一下就行。', '原银保监会主席 2018 年在陆家嘴论坛上说过一句话。原话是：「收益率超过 6% 的就要打问号，超过 8% 的就很危险，10% 以上就要准备损失全部本金」。资管新规要求金融机构「不得承诺保本保收益」，还要求「出现兑付困难时，金融机构不得以任何形式垫资兑付」。所以正规理财已经没有保本这一说。参与非法集资的损失「由集资参与人自行承担」，出事以后没有人替你赔（中国，2018、2021 年）', '6%、8%、10% 这三条线是监管者按经验画的，不是法律条文。原话是在讲打击非法集资时说的，针对的是承诺高回报的理财产品和投资公司。不构成投资建议。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-7', 'concept_archive_s5-7', 'claim_archive_s5-7', 'action', 'life_archive', '不用信用卡最低还款，不为消费开分期或消费贷；非借不可，先把利息换成年化利率再比', '5. 不要浪费钱', '最低还款是按天算利息的贷款，折合一年 18% 上下，用了免息期就作废。分期写「每月手续费 0.6%」，按年算约 13.8%，不是 7.2%。因为本金每月在还，手续费却一直按最初的数收。比哪笔贷款贵，只看年化利率，别看日息和月费率。', '18.25% 是拿「万分之五 × 365」直接乘出来的，没有算利滚利。真按月滚起来还要更高。个别银行有折扣，以你自己账单上写明的年化利率为准。真周转不开的时候，优先去找利率更低的正规渠道借，不要拖着最低还款滚利息。比两笔贷款时，让对方给按复利算的年化利率。对方给的是单利，按规定要写明「单利」，单利会比复利低一些。13.8% 和 1.8 到 2 倍是本书照人民银行的算法自己算的，算法写在核实记录里。民间借贷别碰高利贷，另见第 7 节第 15 条（不借高利贷）。', NULL, NULL, NULL, '不花钱。要在账单日之前留够全额还款的现金。难的是忍住不用分期把大额开销摊薄。非借不可时，花几分钟问清每笔贷款的年化利率。', '信用卡透支利率在 2020 年以前有上下限：上限是「日利率万分之五」，下限是上限的 0.7 倍。万分之五折合成一年是 18.25%，这是单利：按一年 18.25% 算，利息不再滚进本金里。2021 年起改成由发卡机构和持卡人自己商量定价。用了最低还款以后，没还的那部分本金每天全额算利息，免息期同时作废。央行已经要求发卡机构用明显的方式展示年化利率（按整年折算的利率），「不得仅展示日利率、日还款额」。2021 年起，所有放贷的机构做广告、签合同，都要明显写出年化利率。日利率、月利率可以一起写，但不能比年化利率更显眼。年化利率要把利息和跟贷款直接有关的各种费用都算进去。分期还本的，按每期还完后剩下的本金算你实际用了多少钱。人民银行给过一个算例：借 10 万元，分 12 个月还，每月交最初本金的 0.5% 作分期费。借款当时还要交 1000 元服务费。按单利算，年化约 12.80%。按复利算（内部收益率法），年化约 13.58%。光看费率，会以为一年只花 0.5% × 12 + 1% = 7%。实际差不多是它的两倍，因为本金每月在减少，分期费却一直按 10 万元收。照同样的算法，信用卡分 12 期、每期手续费 0.6%、没有别的费用，名义上是一年 7.2%。按复利算，年化约 13.8%，是名义数字的 1.9 倍左右。分 6 到 36 期，都在 1.8 到 2 倍之间。借给你钱的是个人或普通公司，就是民间借贷。约定的利率超过签合同时一年期 LPR 4 倍，法院不支持超出的部分。2026 年 8 月 20 日的一年期 LPR 是 3.0%，4 倍就是 12%。先从借款里扣掉的利息，法院按实际到手的钱算本金。这条线管不到银行、消费金融公司这些持牌金融机构。小额贷款公司、典当行、融资租赁公司等七类地方金融组织也不适用。所以不能拿 12% 去套它们的贷款，要看合同上写的年化利率（中国，2020、2021 年）', '18.25% 是拿「万分之五 × 365」直接乘出来的，没有算利滚利。真按月滚起来还要更高。个别银行有折扣，以你自己账单上写明的年化利率为准。真周转不开的时候，优先去找利率更低的正规渠道借，不要拖着最低还款滚利息。比两笔贷款时，让对方给按复利算的年化利率。对方给的是单利，按规定要写明「单利」，单利会比复利低一些。13.8% 和 1.8 到 2 倍是本书照人民银行的算法自己算的，算法写在核实记录里。民间借贷别碰高利贷，另见第 7 节第 15 条（不借高利贷）。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-8', 'concept_archive_s5-8', 'claim_archive_s5-8', 'action', 'life_archive', '不给主播打赏、不给游戏充值、不冲动下单', '5. 不要浪费钱', '国内玩游戏的人，平均每人一年在游戏上花约 480 元，花出去基本追不回来。法律只让未成年人没经家长同意花的钱退回来，成年人没有这一条。最省力的办法是提前设防：关掉免密支付，设单笔和每日限额，把支付方式解绑。', '定成 B 级，是因为没有人直接测过「不打赏能省多少钱」，只有游戏行业的总量数字。关免密、设限额这两招是经验做法，单算是 C 级。民法典第十九条、第一百四十五条的原文，已经在第 9 条（孩子用手机充值打赏）里逐字引出来了。不构成投资建议。', NULL, NULL, NULL, '不花钱。花几分钟做三件事：关掉免密支付，设好单笔和每日限额，把平台里绑的支付方式删掉。难的是当场忍住不点那一下。', '这是一笔很大的支出。2024 年国内游戏市场实际销售收入 3257.83 亿元，用户 6.74 亿人，人均约 480 元（这是拿前面两个数相除算出来的）。花出去的钱基本追不回来。只有一种情况例外：限制民事行为能力人（这里指未成年人）没经过监护人同意的打赏和充值，监护人要求退钱时「人民法院应予支持」。成年人自己的打赏和充值，没有这样的规定。另外，未成年人玩网络游戏本来就只能在周五、周六、周日和法定节假日玩，每天 20 时至 21 时这 1 小时（中国，2020、2021 年）', '定成 B 级，是因为没有人直接测过「不打赏能省多少钱」，只有游戏行业的总量数字。关免密、设限额这两招是经验做法，单算是 C 级。民法典第十九条、第一百四十五条的原文，已经在第 9 条（孩子用手机充值打赏）里逐字引出来了。不构成投资建议。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-9', 'concept_archive_s5-9', 'claim_archive_s5-9', 'action', 'life_archive', '孩子用手机充值打赏，八岁以上的大额支出未经家长追认可以主张退', '5. 不要浪费钱', '八岁以上的孩子花的钱，只要金额和他的年龄、智力明显不相称，家长既不同意也不认这笔账，这笔交易就是无效的，可以要求退。不满八岁的孩子，本来就不能自己做主花钱。家长一直不表态，法律上就算作不认这笔账。', '关键在举证：你要拿出证据，证明操作手机的是孩子，不是你。有用的材料有这几样：充值时间集中在上课时段或者家长上班时段，设备的使用记录，孩子的聊天记录和游戏记录，还有孩子本人的说明。「与年龄智力相适应」没有统一的金额线，几十元的游戏皮肤和几万元的打赏不是一回事。事前防住更省力：给支付方式设免密上限，开启青少年模式，别把支付密码告诉孩子。你自己冲动打赏充值的情况，见本节「不给主播打赏、不给游戏充值、不冲动下单」那条。', NULL, NULL, NULL, '不花钱。要花时间收集证据、跟平台交涉，平台通常先拒绝、后退款。谈不拢就只能起诉，那是几个月起步的事，律师费要自己出。所以先把材料备齐，走平台和 12315 更划算。难的是孩子不肯说，你得耐着性子问清楚。', '八周岁以上的未成年人是限制民事行为能力人，意思是他只能自己做和年龄、智力相称的事。和他年龄、智力不相称的民事法律行为，要经过法定代理人同意或者追认才有效：家长要事先点头，或者事后认账。不满八周岁的孩子是无民事行为能力人，自己做不了主，他的事由法定代理人代他办。法定代理人没有表示的，视为拒绝追认：家长一直不吭声，就算作不认这笔账', '关键在举证：你要拿出证据，证明操作手机的是孩子，不是你。有用的材料有这几样：充值时间集中在上课时段或者家长上班时段，设备的使用记录，孩子的聊天记录和游戏记录，还有孩子本人的说明。「与年龄智力相适应」没有统一的金额线，几十元的游戏皮肤和几万元的打赏不是一回事。事前防住更省力：给支付方式设免密上限，开启青少年模式，别把支付密码告诉孩子。你自己冲动打赏充值的情况，见本节「不给主播打赏、不给游戏充值、不冲动下单」那条。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-10', 'concept_archive_s5-10', 'claim_archive_s5-10', 'action', 'life_archive', '教孩子记一句话：任何人让你拿家长的手机去操作、去报验证码，都是骗子', '5. 不要浪费钱', '这六类骗局的套路各不相同，但最后一步永远是同一个动作：让孩子拿家长的手机去转账，或者念验证码。所以教会一句就够用了：谁让你动家长的手机、报验证码，谁就是骗子。再加一句「被骗了先跟我说，我不骂你」。孩子敢当天说，钱才有可能追回来。', '定成 B 级，是因为官方给的是骗子话术的拆解和个案，没有发案率，也没有防范效果的统计数字。要和第 9 条（孩子用手机充值打赏）分清楚：孩子自己充值打赏花掉的钱，可以按民法典要求退。被骗子骗走的钱不适用那一条，只能按第 8 节第 2 条报警止付。能不能追回来，要看钱还在不在账上。骗子吓唬孩子的核心话术是「你违规了、你家长要坐牢」。事先就跟孩子说清楚，这句话本身就是骗局的标志，比事后追问管用。「被骗了先说、我不骂你」这句要真做到。孩子怕挨骂、瞒着不说，是这几个案例里损失越滚越大的共同原因。冒充熟人的成人版，还有 AI 换脸，见第 8 节第 3、4 条（反诈硬规则、涉及转账先挂断）。大人也一样，验证码和刷脸不替任何人做，见第 8 节第 45 条（念验证码）。', NULL, NULL, NULL, '不花钱。给孩子把下面六类讲一遍，再和他约定一句「被骗了先跟我说，我不骂你」。同时把支付设上免密上限，开青少年模式，支付密码不告诉孩子。难的是真被骗了以后你要忍住不发火。', '泉州市反诈骗中心联合泉州市教育局，拆了六类专门骗青少年的骗局。它们套路各不相同，但最后一步是同一个动作：让孩子拿家长的手机转账。第一类，游戏账号和装备低价私下交易。小王私下转了 260 元，对方说「未成年人转账违规，账号要冻结」，他用爸爸的手机点了「核查链接」，账户里 3 万多元被转走。第二类，「解除防沉迷」。对方威胁「不转账取消，你家长要坐牢」，孩子用妈妈的手机转了 7000 元。原文写明防沉迷是官方设定的，「根本没有『私下解锁』渠道」。第三类，打赏退款。骗子冒充「官方客服」，说未成年人打赏可以退，要求「用家长支付宝给指定直播间刷礼物才能退款」，妈妈账户里 7.3 万元被打赏出去，人被拉黑。原文说「有人加你让你『刷礼物退款』，100% 是诈骗」。第四类，冒充同学或者老师。骗子盗了号，发语音报出名字来借钱。开学季还混进班级群冒充老师，发「交学杂费 500 元」，头像和昵称都和真老师一样，还安排「托」在群里说「已交」。第五类，追星。骗子把孩子拉进「明星粉丝群，领 888 元红包」。先让孩子转 48.88 元「验证」。再吓唬说「未成年人参与违规，平台要冻结 8 万，家长要坐牢」。一共骗走 1.6 万元。原文说「真警察、律师绝不会在网上联系未成年人调查，更不会要家长手机操作」。第六类，二手平台上用低价商品把人引出平台，私下转账。同一份材料还列了三条孩子自己别踩的红线。一是银行卡和电话卡不借、不卖、不租，卡被用去转移赃款，可能构成帮助信息网络犯罪活动罪，留下案底会影响考研和考公。二是「手机口」兼职是违法犯罪。三是境外的「高薪招聘」，人可能一到境外就被控制住（全国，2025 年 10 月）', '定成 B 级，是因为官方给的是骗子话术的拆解和个案，没有发案率，也没有防范效果的统计数字。要和第 9 条（孩子用手机充值打赏）分清楚：孩子自己充值打赏花掉的钱，可以按民法典要求退。被骗子骗走的钱不适用那一条，只能按第 8 节第 2 条报警止付。能不能追回来，要看钱还在不在账上。骗子吓唬孩子的核心话术是「你违规了、你家长要坐牢」。事先就跟孩子说清楚，这句话本身就是骗局的标志，比事后追问管用。「被骗了先说、我不骂你」这句要真做到。孩子怕挨骂、瞒着不说，是这几个案例里损失越滚越大的共同原因。冒充熟人的成人版，还有 AI 换脸，见第 8 节第 3、4 条（反诈硬规则、涉及转账先挂断）。大人也一样，验证码和刷脸不替任何人做，见第 8 节第 45 条（念验证码）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-11', 'concept_archive_s5-11', 'claim_archive_s5-11', 'action', 'life_archive', '拒绝电子产品的延长保修（延保）', '5. 不要浪费钱', '延保一般卖到原价的 10% 到 50%，卖延保的赚头是普通商品的十几倍，这个差价就是你多付的钱。洗衣机、冰箱的电机这类主要部件，国家本来就规定保修 3 年。碰上很便宜的延保，拿延保价除以修一次的钱，得数就是这几年里至少坏一次的可能要多大才回本。', '毛利率那个数字是论文引用别人的行业估算（Business Week 2004），不是论文自己测出来的。上面的算法适用于自己掏得起一次维修费的普通人。靠一台设备吃饭、又没有备用机的人，要另外算。手机碎屏险这一类也要单独算：先估自己多久摔一次，再看保费划不划算。很便宜的延保买了也亏不了几十元，买之前看清三样：从哪天开始算（从买的那天算的，头几年和三包重叠），是商家、品牌还是第三方公司在保，上门费和换件费另不另收。也先看说明书和保修卡，品牌自己承诺的保修期可能比三包长。', NULL, NULL, NULL, '不花钱。代价是保修期过了以后，万一要修，得自己掏钱，不过这种事概率不大。', '延保的定价通常是商品原价的 10% 到 50%。研究里引用的行业估计说，延保的平均毛利率是 50% 到 60%：卖出去 100 元，有 50 到 60 元是赚的。这大约是普通商品毛利率的 18 倍。2003 年，延保只占百思买营收的 3% 到 4%，却贡献了超过 50% 的利润（美国，2000 年代零售数据）。碰上价格远低于这个区间的延保，可以自己算一笔：延保价 ÷ 修一次要花的钱 = 回本需要的故障概率。你估计延保那几年里至少坏一次的可能比这个数大，才值得买。比如 25 元的延保，假设修一次 300 元，至少坏一次的可能要超过约 8% 才回本。这里的 300 元只是举例，不是统计数字。算之前先扣掉国家规定已经保了的部分。国家规定的三包期从开发票那天算：洗衣机和电冰箱整机 1 年，主要部件 3 年。洗衣机的主要部件是电机、定时器、程控器和电容器，电冰箱是压缩机、温控器等。延保和三包重叠的那段，等于花钱买了本来就有的东西（全国，1995 年起）', '毛利率那个数字是论文引用别人的行业估算（Business Week 2004），不是论文自己测出来的。上面的算法适用于自己掏得起一次维修费的普通人。靠一台设备吃饭、又没有备用机的人，要另外算。手机碎屏险这一类也要单独算：先估自己多久摔一次，再看保费划不划算。很便宜的延保买了也亏不了几十元，买之前看清三样：从哪天开始算（从买的那天算的，头几年和三包重叠），是商家、品牌还是第三方公司在保，上门费和换件费另不另收。也先看说明书和保修卡，品牌自己承诺的保修期可能比三包长。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-12', 'concept_archive_s5-12', 'claim_archive_s5-12', 'action', 'life_archive', '优先选通过一致性评价的仿制药和集采中选药', '5. 不要浪费钱', '集采第二批药平均降价 53%，降得最多的降了 93%。到 2026 年 4 月，已经做了 11 批，覆盖 490 种药。开药买药时多问一句「有没有集采的、通用名的」，成分一样，钱能少花一大截。', '争议：常有人说「一致性评价只比成分，不比疗效」。这话对了一半。过评的做法是找健康人来吃药，抽血看药进到血液里以后的浓度曲线，再拿这条曲线和原研药的比，落在 80% 到 125% 之间就算过关。剂量差一点就出事的那类药，要求更严。辅料指有效成分之外的填充和包衣，允许和原研药不一样。法规只要求有效成分、剂型、吃法和治疗作用相同。所以它确实不是「找病人吃一段时间，看病好没好」。病人身上的效果由另一套研究来回答。国家医保局组织医院做过真实世界研究。到 2024 年 12 月，覆盖了 63 种集采药、近百家三甲医院、30 多万病人。结果都是和原研药没差别。比如二甲双胍，糖化血红蛋白达标率是仿制组 83.4%、原研组 78.9%；空腹血糖达标率反过来，仿制组 83.8%、原研组 87.6%。两组互有高低。2025 年 1 月，有医生公开说集采药「血压不降、麻药不睡、泻药不泻」。医保和药监去上海 7 家医院查过，结论是这些说法多半来自转述和个人感觉，其中被点名的那种泻药当时还没开始在医院用。同一次也承认确实抽到过问题药。前 9 批 1600 多个中选产品里，有 9 个因为质量风险被取消资格。这 9 个里，6 个是进口药（含 3 个原研药），3 个是国产药。有两件事你能落实。一是想继续用原研药，通常还是开得到的：集采只占医院采购量的 60% 到 80%，剩下的由医院自己定，原研药没有被禁，代价是自己多掏钱。二是慢病换了药以后别凭感觉判断，按第 16 节第 3 条（把每次指标记在同一个本子上）盯住血压、血糖、糖化。真变差了就去找医生，请医生上报药品不良反应，别自己停药。', NULL, NULL, NULL, '不花钱。医生开药、你去买药的时候，多问一句「有没有集采的、通用名的药」。', '国家组织的药品集采，第二批平均降价 53%，最高降 93%。截至 2026 年 4 月，已经开展了 11 批，覆盖 490 种药品。通过或者视同通过一致性评价的药品达到 1695 个。这大约占临床常用化学药的 2/3（中国，2020 到 2026 年官方数据）', '争议：常有人说「一致性评价只比成分，不比疗效」。这话对了一半。过评的做法是找健康人来吃药，抽血看药进到血液里以后的浓度曲线，再拿这条曲线和原研药的比，落在 80% 到 125% 之间就算过关。剂量差一点就出事的那类药，要求更严。辅料指有效成分之外的填充和包衣，允许和原研药不一样。法规只要求有效成分、剂型、吃法和治疗作用相同。所以它确实不是「找病人吃一段时间，看病好没好」。病人身上的效果由另一套研究来回答。国家医保局组织医院做过真实世界研究。到 2024 年 12 月，覆盖了 63 种集采药、近百家三甲医院、30 多万病人。结果都是和原研药没差别。比如二甲双胍，糖化血红蛋白达标率是仿制组 83.4%、原研组 78.9%；空腹血糖达标率反过来，仿制组 83.8%、原研组 87.6%。两组互有高低。2025 年 1 月，有医生公开说集采药「血压不降、麻药不睡、泻药不泻」。医保和药监去上海 7 家医院查过，结论是这些说法多半来自转述和个人感觉，其中被点名的那种泻药当时还没开始在医院用。同一次也承认确实抽到过问题药。前 9 批 1600 多个中选产品里，有 9 个因为质量风险被取消资格。这 9 个里，6 个是进口药（含 3 个原研药），3 个是国产药。有两件事你能落实。一是想继续用原研药，通常还是开得到的：集采只占医院采购量的 60% 到 80%，剩下的由医院自己定，原研药没有被禁，代价是自己多掏钱。二是慢病换了药以后别凭感觉判断，按第 16 节第 3 条（把每次指标记在同一个本子上）盯住血压、血糖、糖化。真变差了就去找医生，请医生上报药品不良反应，别自己停药。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-13', 'concept_archive_s5-13', 'claim_archive_s5-13', 'action', 'life_archive', '在医保 App 上办一次家庭共济绑定，职工医保个人账户的钱就能给配偶、父母、子女看病买药', '5. 不要浪费钱', '办一次绑定，你职工医保个人账户里的钱，就能给配偶、父母、孩子看病买药用。不办，这笔钱就只能你自己用，一直躺在账户里。', '很多人的个人账户里躺着几千元，同时家里老人在自费买药。绑定一次以后长期有效。各地大多叫「家庭共济」，在本地医保 App 里就能办。注意反过来的一条红线：个人账户不能用于健身、养生保健这类消费。拿它去药店买保健品套现，属于骗保。', NULL, NULL, NULL, '不花钱。在参保地的医保 App 上，或者去经办机构，办一次家庭共济绑定。', '个人账户里的钱，可以用来支付你本人和你的配偶、父母、子女在定点医疗机构看病时自己要掏的那部分医疗费。也可以用来支付在定点零售药店买药品、医疗器械、医用耗材时自己要掏的那部分钱。文件还提出，要探索把个人账户用于给家人交城乡居民医保的个人缴费', '很多人的个人账户里躺着几千元，同时家里老人在自费买药。绑定一次以后长期有效。各地大多叫「家庭共济」，在本地医保 App 里就能办。注意反过来的一条红线：个人账户不能用于健身、养生保健这类消费。拿它去药店买保健品套现，属于骗保。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-14', 'concept_archive_s5-14', 'claim_archive_s5-14', 'action', 'life_archive', '喝烧开的自来水，不常年买瓶装水', '5. 不要浪费钱', '北京第一阶梯的水价，折合 0.005 元一升。瓶装水按 1 元 500 毫升算，是 2 元一升。两者差 400 倍。自来水执行的是强制性的国家标准，平时烧开了喝就行。真碰上水源出事、水发臭发浑，那不是多煮几分钟能解决的，要停下来别喝，并且向外反映。', '争议在于，所谓「达标」查的是水厂出来的水和管道末端的水。水源或者管网出问题的时候，会短暂失守。2025 年 7 月 16 日，杭州余杭仁和水厂进的原水气味不对，仁和、良渚部分小区的自来水发臭。官方结论是藻类在缺氧条件下分解，产生了硫醚类物质。换了水源以后，出厂水的总大肠菌群、大肠埃希氏菌都没有检出，全部项目符合生活饮用水标准 GB 5749-2022。事后 7 名干部被问责，7 月水费全免，还免费换了滤芯。但同一个水源的粪大肠菌群，事发前已经连着几个月往上走。苕溪永胜取水口 4 月是 10 个/L，5 月 7300 个/L，6 月 16000 个/L。地表水标准 GB 3838 Ⅲ 类的限值是 10000 个/L。同月四岭水库 28000 个/L、馒头山水库 24000 个/L 也超了。烧开只能杀微生物，除不掉气味物质，也除不掉溶在水里的化学物。闻到异味，或者水发黄发浑，就停下来别喝，向供水企业和 12345 反映，临时改喝瓶装水，别指望多煮几分钟压过去。但这是局部的偶发事故，当地也按次赔了，仍然不构成常年买瓶装水的理由。网上传的「粪水管接错」是伪造的警情通报，发布者已经被刑事拘留（见第 9 节）。瓶装水 1 元 500 毫升是为了算账设的假设价，你按自己所在城市的实际价格重算。老旧小区的二次供水设施不达标的，可以加装过滤，或者只在这种情况下买水喝。各地水价不同，北京这个数字只用来看个量级。', NULL, NULL, NULL, '买一个水壶。每次烧水要花一点时间，还有少量燃气费或者电费。', '北京居民第一阶梯水价是 5 元一立方米，折合 0.005 元一升。瓶装水如果按 1 元 500 毫升算，就是每升 2 元，是自来水的 400 倍。生活饮用水执行的是强制性国家标准 GB 5749-2022。这个标准 2022 年 3 月 15 日发布，2023 年 4 月 1 日起施行。主管部门是国家疾控局（中国，2015 年水价与 2022 年标准）', '争议在于，所谓「达标」查的是水厂出来的水和管道末端的水。水源或者管网出问题的时候，会短暂失守。2025 年 7 月 16 日，杭州余杭仁和水厂进的原水气味不对，仁和、良渚部分小区的自来水发臭。官方结论是藻类在缺氧条件下分解，产生了硫醚类物质。换了水源以后，出厂水的总大肠菌群、大肠埃希氏菌都没有检出，全部项目符合生活饮用水标准 GB 5749-2022。事后 7 名干部被问责，7 月水费全免，还免费换了滤芯。但同一个水源的粪大肠菌群，事发前已经连着几个月往上走。苕溪永胜取水口 4 月是 10 个/L，5 月 7300 个/L，6 月 16000 个/L。地表水标准 GB 3838 Ⅲ 类的限值是 10000 个/L。同月四岭水库 28000 个/L、馒头山水库 24000 个/L 也超了。烧开只能杀微生物，除不掉气味物质，也除不掉溶在水里的化学物。闻到异味，或者水发黄发浑，就停下来别喝，向供水企业和 12345 反映，临时改喝瓶装水，别指望多煮几分钟压过去。但这是局部的偶发事故，当地也按次赔了，仍然不构成常年买瓶装水的理由。网上传的「粪水管接错」是伪造的警情通报，发布者已经被刑事拘留（见第 9 节）。瓶装水 1 元 500 毫升是为了算账设的假设价，你按自己所在城市的实际价格重算。老旧小区的二次供水设施不达标的，可以加装过滤，或者只在这种情况下买水喝。各地水价不同，北京这个数字只用来看个量级。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-15', 'concept_archive_s5-15', 'claim_archive_s5-15', 'action', 'life_archive', '不频繁交易股票，行情暴涨暴跌的时候更要少动手', '5. 不要浪费钱', '买卖最频繁的美国家庭，每年只赚 11.4%，同期整个市场是 17.9%，差距几乎全是手续费。国内 2014 到 2015 年那轮暴涨暴跌里，账户最小的 85% 家庭买卖太勤。他们比一直拿着不动少赚 2500 亿元，约是本金的三成。', '美国那份数据是 1990 年代的，A 股的佣金和印花税结构和它不一样，但「换手越高、到手收益越低」这个道理是一样的。国内那项研究没有说别买股票。它算的是同一段行情里，账户小的那一头越主动交易，钱越往对手盘走。赚走这笔钱的也不是机构，是账户最大的那一批个人：这段时间上交所约九成成交量来自散户账户。网上流传的「九成散户亏钱」找不到可核对的官方统计，本条不用这个数字。换手率可以对照着看：这轮行情里国内家庭账户一年换近 18 次，美国那批家庭一年只换掉四分之三。平静的年份里国内这个差距只有百分之一到三，所以最该忍住的是行情最热的时候。不构成投资建议。', NULL, NULL, NULL, '不花钱。难的是看到消息就想动手，别人都在赚钱时想跟着加码，要忍住。', '这项研究看的是 66,465 个美国折扣券商的家庭账户，时间是 1991 到 1996 年。交易最频繁的那一组，年化收益 11.4%，也就是平均每年赚 11.4%。同期整个市场是 17.9%，平均一个家庭是 16.4%。平均一个家庭一年的换手率是 75%，一年里把手上的股票换掉了四分之三。频繁交易的那组和不频繁的那组，毛收益（扣手续费前赚的钱）差别很小，所以差距主要来自买卖时付掉的交易成本（美国，1991 到 1996 年）。国内的数据：研究用的是上海证券交易所的逐日账户数据，覆盖全部约 4000 万个账户。样本期是 2014 年 7 月到 2015 年 12 月，共 18 个月。这 18 个月里上证综指先涨了 150% 以上。它在 2015 年 6 月 12 日见顶 5166.35 点，到 12 月底又跌了 40%。家庭账户按期初市值分成四档。最小的一档占全部家庭账户的 85%，最大的一档占 0.5%。两档期初的股票总市值差不多，分别是 8800 亿元和 8080 亿元。结果是最小的那 85% 因为主动交易损失 2500 亿元，最大的那 0.5% 赚到 2540 亿元。这里的「损失」是和同一段行情里一直持有不动、什么都不做相比。两个数各约相当于本组期初股票市值的三成，前者 28%，后者 31%。作为对照，2014 年 6 月之前的两年半市场较平静。那段时间任取 18 个月，同类差额只有期初市值的 1% 到 3%。这轮行情里，家庭账户平均约三周就把手上的股票换一遍，一年近 18 次（中国上海，2014 到 2015 年；对照期 2012 到 2014 年）', '美国那份数据是 1990 年代的，A 股的佣金和印花税结构和它不一样，但「换手越高、到手收益越低」这个道理是一样的。国内那项研究没有说别买股票。它算的是同一段行情里，账户小的那一头越主动交易，钱越往对手盘走。赚走这笔钱的也不是机构，是账户最大的那一批个人：这段时间上交所约九成成交量来自散户账户。网上流传的「九成散户亏钱」找不到可核对的官方统计，本条不用这个数字。换手率可以对照着看：这轮行情里国内家庭账户一年换近 18 次，美国那批家庭一年只换掉四分之三。平静的年份里国内这个差距只有百分之一到三，所以最该忍住的是行情最热的时候。不构成投资建议。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-16', 'concept_archive_s5-16', 'claim_archive_s5-16', 'action', 'life_archive', '不借钱投资、不加杠杆、不买自己看不懂的', '5. 不要浪费钱', '借钱买股票，一旦跌破线，你又补不上钱，就会被强制卖掉。账面上的亏损当场变成真亏，连「等它涨回来」的机会都没有。监管规定，开户不满半年、最近 20 个交易日日均资产不到 50 万元的人，不能开融资账户。这个门槛本身就说明，它不是给普通人用的。', '「看不懂的不买」这句没有直接的文献支持，属于共识，单算是 C 级。用消费贷或者信用卡套现去投资，也是变相的杠杆，它们的利率见本节第 7 条（不用信用卡最低还款）。不构成投资建议。', NULL, NULL, NULL, '不花钱。难的是行情好的时候，要忍住不去想「借点钱多赚一点」。', '杠杆就是借钱来买，它会把亏损放大。你用融资买入以后，抵押物的市值可能跌到维持担保比例线以下。这条线是券商划的，管的是你抵押在它那里的东西。跌破了这条线，你又没能追加担保把它补回来，就会被强制平仓，由券商直接替你卖掉。账面上的亏损当场变成真亏，没有「等它涨回来」的机会。监管规定，「从事证券交易时间不足半年、缺乏风险承担能力、最近 20 个交易日日均证券类资产低于 50 万元」的客户，不得开立信用账户。这个门槛本身就说明，它不是给普通人用的工具（中国，2015 年）', '「看不懂的不买」这句没有直接的文献支持，属于共识，单算是 C 级。用消费贷或者信用卡套现去投资，也是变相的杠杆，它们的利率见本节第 7 条（不用信用卡最低还款）。不构成投资建议。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-17', 'concept_archive_s5-17', 'claim_archive_s5-17', 'action', 'life_archive', '用宽基指数基金替代主动管理基金作为长期底仓（长期拿着不动的那部分钱）', '5. 不要浪费钱', '主动基金合起来买的那堆股票，已经很接近整个市场了。但它们多收的那笔管理费，是实打实从你到手的收益里扣掉的。把基金的业绩当成运气反复重算来比，能靠多赚的那部分把自己收的费挣回来的基金，很少。', '争议：有一篇文章重新检验过这个结论。它指出，Fama-French 那套反复重抽样本的检验方法抽得不够。照它的算法，就算一只基金多赚的那部分确实很明显，也可能被判成「和运气分不出区别」。所以「几乎没有基金有技能」这个结论可能下得过重了。中国的数字没有美国那么一边倒。标普道琼斯截至 2025 年 6 月的统计，A 股大盘主动基金跑输标普中国 A 股 300 指数的比例，1 年是 60.5%，3 年是 69.6%，5 年是 50.8%。这份统计只算到 5 年，拿不出更长的数。所以在中国，主动基金长期跑不赢指数还没有定论，但指数基金费率低这一点照样成立。不构成投资建议。', NULL, NULL, NULL, '不花钱。代价是你放弃了「选中明星基金经理」的可能。难的是指数跌的时候，你也要跟着一起承受，不能中途跑掉。', '美国主动股票型基金的整体组合接近市场组合：这些基金合起来持有的股票，和整个市场差不多。但主动管理的高成本原封不动地变成了投资者更低的净回报（扣完费用后到手的收益）。研究用了自助法模拟，把业绩反复随机重排，看单凭运气能做到什么程度。结果显示，很少有基金能产生足以覆盖成本的超额收益：基金比市场多赚的那部分，够不上它收的那笔费（美国，2010 年发表）。标普道琼斯指数公司每年统计一次：2024 年，美国主动管理的大盘股票基金有 65% 跑输标普 500。它统计了 24 年，平均每年有 64% 跑输。截至 2024 年底的 15 年里，所有类别中都没有哪一类是多数主动基金跑赢的', '争议：有一篇文章重新检验过这个结论。它指出，Fama-French 那套反复重抽样本的检验方法抽得不够。照它的算法，就算一只基金多赚的那部分确实很明显，也可能被判成「和运气分不出区别」。所以「几乎没有基金有技能」这个结论可能下得过重了。中国的数字没有美国那么一边倒。标普道琼斯截至 2025 年 6 月的统计，A 股大盘主动基金跑输标普中国 A 股 300 指数的比例，1 年是 60.5%，3 年是 69.6%，5 年是 50.8%。这份统计只算到 5 年，拿不出更长的数。所以在中国，主动基金长期跑不赢指数还没有定论，但指数基金费率低这一点照样成立。不构成投资建议。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-18', 'concept_archive_s5-18', 'claim_archive_s5-18', 'action', 'life_archive', '同类基金优先选费率低的', '5. 不要浪费钱', '一年的费率每高 1 个百分点，20 年后到手的钱少约 18%，30 年后少约 26%。在同一类基金里挑费率低的，是这件事上唯一一个你能提前确定的东西。', '这个算式只是照公式算出来的，前提是两只基金扣费之前赚得一样多。实际还要算上申购费、赎回费，以及 C 类份额的销售服务费。不构成投资建议。', NULL, NULL, NULL, '不花钱。买之前多看一眼「管理费 + 托管费 + 销售服务费」这三项加起来是多少。', '费率的差别会按复利一点点吃掉本金，意思是每年被扣掉的那一点会年年叠加。一年的费率高 1 个百分点，20 年后的终值少 0.99^20 ≈ 18.2%，终值就是到那时候账户里剩下的钱；30 年后少约 26%。中国从 2023 年起推行公募基金费率改革，下调了主动权益类基金（主要买股票、由基金经理挑股的那种）的费率上限。从 2023 年 7 月 7 日起，新注册的这类基金管理费率不超过 1.2%，托管费率不超过 0.2%。136 家基金公司把旗下老产品的这两项也降到了这条线以下', '这个算式只是照公式算出来的，前提是两只基金扣费之前赚得一样多。实际还要算上申购费、赎回费，以及 C 类份额的销售服务费。不构成投资建议。', '极高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-19', 'concept_archive_s5-19', 'claim_archive_s5-19', 'action', 'life_archive', '别把钱押在一只股票、一个平台、一套房上', '5. 不要浪费钱', '几样东西只要不是完全一起涨、一起跌，把钱分开放，平均能赚到的不变，账户的起伏却会小一些。反过来，钱全押在一只股票、一个平台、一套房上，它一出事，就等于你全部出事。', '定成 B 级，是因为那篇经典文献是纯数学推导，没有算出「分散能少亏多少钱」的实际数字。分散只能让账户的涨跌小一些，不保证你不亏。买宽基指数基金（见本节第 17 条）本身就是最省事的分散办法。不构成投资建议。', NULL, NULL, NULL, '不花钱。难的是要接受一件事：你不会正好押中最赚的那一个。', '只要几项资产不是完全同涨同跌，把钱分开放，预期收益（平均能赚到的）不变，波动（账户上下起伏）却更小。这是 Markowitz 1952 年提出的组合选择基本结论，此后几十年一直沿用。反过来说，钱全押在一只股票或者一个平台上，它的方差就是你全部的方差，它涨跌多少你就跟着涨跌多少。出事的时候没有任何对冲，也就没有别的资产能帮你补回来', '定成 B 级，是因为那篇经典文献是纯数学推导，没有算出「分散能少亏多少钱」的实际数字。分散只能让账户的涨跌小一些，不保证你不亏。买宽基指数基金（见本节第 17 条）本身就是最省事的分散办法。不构成投资建议。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-20', 'concept_archive_s5-20', 'claim_archive_s5-20', 'action', 'life_archive', '交个税且税率到 10% 及以上的人开个人养老金账户，每年最多 12000 元能在税前扣掉；不交个税或税率只有 3% 的人开了不划算', '5. 不要浪费钱', '你每存进去一元，省下的税是「你那一档税率减 3%」。一年存满 12000 元，税率 10% 的人省 840 元，20% 的省 2040 元，30% 的省 3240 元。税率只有 3% 的人，省下的税领钱时又交回去，白锁到退休。不交个税的人领钱时还要交 3%，是净亏。', '这个账户是「封闭运行」的，钱交进去就取不出来。只有四种情况能领：达到领取基本养老金的年龄、完全丧失劳动能力、出国（境）定居、国家规定的其他情形。所以它不是理财，是一笔要锁很多年的税务安排。省下的税只拿一次，钱却要锁到退休，离退休越远，摊到每年的好处越小。粗算一下：税率 10% 的人每存一元省 7 分钱，离退休还有 30 年，摊到每年才 0.2% 多一点。税率 20% 的人每存一元省 1 角 7 分，离退休还有 10 年，摊到每年约 1.7%。先算清楚自己每多赚一元要交多少税，再决定交多少。别为了「薅羊毛」把应急金锁进去（应急金见第 27 条）。账户里的钱还要你自己选产品去投资，是会亏的。选产品的规则和本节第 17、18 条（宽基指数基金、优先选费率低的）一样。扣除凭证由个人养老金信息管理服务平台出具。抵扣的时机你可以选：一种是当年发工资代扣税的时候就扣，另一种是第二年汇算的时候再扣（汇算见第 2 条）。', NULL, NULL, NULL, '开户不花钱。真正的代价是这笔钱会锁到你退休，中途取不出来。', '交进去的钱，每年最多 12000 元，可以从综合所得或者经营所得里如实扣掉：你存进去多少，就能从要交税的收入里减掉多少。这笔钱在账户里投资赚到的收益，暂时不收个人所得税。将来领出来的时候不并进综合所得，单独按 3% 计税。所以你省下的是「你的边际税率减去 3%」乘以你实际交进去的钱。边际税率就是你每多赚一元要按的那一档税率。算下来：边际税率 10% 的人每年最多省 840 元，20% 的省 2040 元，30% 的省 3240 元。本来就不用交个税的人（年综合所得扣完各项后没到起征点），交钱的时候一分没省，领的时候反而要按 3% 交，是净亏。边际税率只有 3% 的人也不划算。全年综合所得扣完各项后不超过 36000 元，就落在这一档。这些人交钱时省 3%，领钱时再交 3%，正好抵消，钱却白白锁到退休。每月工资被扣了个税，不等于你就在 10% 那一档，要看全年扣完各项后的数。每年的缴费额度按自然年度累计，第二年重新算，当年没交满的不能结转到下一年。这项政策从 2024 年 12 月 15 日起在全国实施（全国）', '这个账户是「封闭运行」的，钱交进去就取不出来。只有四种情况能领：达到领取基本养老金的年龄、完全丧失劳动能力、出国（境）定居、国家规定的其他情形。所以它不是理财，是一笔要锁很多年的税务安排。省下的税只拿一次，钱却要锁到退休，离退休越远，摊到每年的好处越小。粗算一下：税率 10% 的人每存一元省 7 分钱，离退休还有 30 年，摊到每年才 0.2% 多一点。税率 20% 的人每存一元省 1 角 7 分，离退休还有 10 年，摊到每年约 1.7%。先算清楚自己每多赚一元要交多少税，再决定交多少。别为了「薅羊毛」把应急金锁进去（应急金见第 27 条）。账户里的钱还要你自己选产品去投资，是会亏的。选产品的规则和本节第 17、18 条（宽基指数基金、优先选费率低的）一样。扣除凭证由个人养老金信息管理服务平台出具。抵扣的时机你可以选：一种是当年发工资代扣税的时候就扣，另一种是第二年汇算的时候再扣（汇算见第 2 条）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-21', 'concept_archive_s5-21', 'claim_archive_s5-21', 'action', 'life_archive', '健身房按次付费或短周期付费，除非有一年以上的稳定记录', '5. 不要浪费钱', '美国那份三年的数据里，选月费 70 美元以上合同的会员，平均每月只去 4.3 次，折合每次超过 17 美元。而按次买 10 次卡，每次只要 10 美元。这些人在会籍期间平均多付了 600 美元。除非你已经有一年以上稳定去的记录，否则按次买或者买短期的更划算。', '这只是一项研究，用的是美国数据。但背后的道理很普遍：人会高估自己将来的自控力。如果你已经有连续一年、每周去两次以上的记录，那年卡确实更便宜。', NULL, NULL, NULL, '按次买，单次价格比年卡摊下来贵一些。你要老实估计自己一个月到底去几次。', '这项研究看的是美国 3 家健身俱乐部 7,752 名会员 3 年的数据。选月费超过 70 美元合同的会员，平均每月只去 4.3 次，折合每次超过 17 美元。而 10 次卡只要每次 10 美元。这些人在会籍期间平均多付了 600 美元。另外，月付会员超过一年还没退卡的比例，比年付会员高 17%（美国，三年面板数据）', '这只是一项研究，用的是美国数据。但背后的道理很普遍：人会高估自己将来的自控力。如果你已经有连续一年、每周去两次以上的记录，那年卡确实更便宜。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-22', 'concept_archive_s5-22', 'claim_archive_s5-22', 'action', 'life_archive', '交预付款要签书面合同；商家出风险要停收，跑路前你有权要回未消费的余额', '5. 不要浪费钱', '商家收你的预付款，必须和你签书面合同，写清楚怎么退。商家经营出了大问题，就该停止收钱，要停业或搬走也得提前告诉你。这时你可以要它接着提供服务，或者把没花完的余额退给你。商家违反这些规定会被罚款。', '条例给的是事后打官司的依据，事前防不住。商家真跑了，钱多半已经不在账上了。所以先按本节「健身房按次付费或短周期付费」那条少充一点，真出事了再靠这个条例去维权。同一个条例第二十七条还规定，商家收押金必须事先约定好退还的方式、程序和时限，不得对退还设置不合理的条件。', NULL, NULL, NULL, '不花钱。难的是当场坚持要一份书面合同，不接受「先充了再说」。', '条例规定，商家收预付款必须订立书面合同，并且在合同里约定退款方式。商家出现重大经营风险的，应当停止收取预付款。商家决定停业或者搬迁的，应当提前告知消费者。消费者有权要求它继续履行，或者退还没消费完的余额。违反的，可以处违法所得 1 到 10 倍的罚款；没有违法所得的，处 50 万元以下罚款', '条例给的是事后打官司的依据，事前防不住。商家真跑了，钱多半已经不在账上了。所以先按本节「健身房按次付费或短周期付费」那条少充一点，真出事了再靠这个条例去维权。同一个条例第二十七条还规定，商家收押金必须事先约定好退还的方式、程序和时限，不得对退还设置不合理的条件。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-23', 'concept_archive_s5-23', 'claim_archive_s5-23', 'action', 'life_archive', '大额非必需购买设 24 小时冷静期，网购善用七日无理由退货', '5. 不要浪费钱', '省下来的，是那些你第二天就不想要的东西。网购的东西，从你收到货那天算起，七天之内可以无理由退。有几类不能退：按你的要求定做的，生鲜和容易坏的，已经拆封的数字商品，还有报刊。', '「冷静期」本身是经验做法，没有直接的文献支持。冷静期没拦住的，还有七日无理由退货这条制度可用。退货之前先确认两件事：这件商品在不在不能退的清单里，包装还完不完好。', NULL, NULL, NULL, '不花钱。想要的东西要晚一天才拿到。退货的运费通常要你自己出。难的是当天忍住不下单。', '省下来的是冲动买的东西里「第二天就不想要了」的那部分。这部分占多少，给不出统一的比例。网上买的商品，从收到那天算起七日内可以无理由退货。有四类除外：定做的、鲜活易腐的、已经拆封的数字商品、报刊（中国，2017 年起施行）', '「冷静期」本身是经验做法，没有直接的文献支持。冷静期没拦住的，还有七日无理由退货这条制度可用。退货之前先确认两件事：这件商品在不在不能退的清单里，包装还完不完好。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-24', 'concept_archive_s5-24', 'claim_archive_s5-24', 'action', 'life_archive', '不为「划线价」和大促囤货', '5. 不要浪费钱', '人判断一样东西贵不贵，靠的是最先看到的那个数字，之后再怎么调整都调不够。所以「原价 999 现价 499」会让你系统性地高估它有多便宜。而按规定，打折要拿来当基准的，只是这家店促销前七天里的最低成交价。那个划掉的价格，不一定真卖过。', '锚定效应是实验室里得出的结论，没有人算过囤货实际亏多少钱。囤货还有几笔你不会记在账上的成本：东西过期，占地方，以及「反正家里有，那就多用点」。只囤这三种都满足的东西：保质期长，确定会用完，单价确实比以前的价格低。', NULL, NULL, NULL, '不花钱。代价是有些真折扣你也放过了。你得记住自己常买那几样东西的日常价。难的是大促当天忍住不囤。', '人的判断会被最先看到的数字定住，之后再调整通常调不够。所以「原价 999 现价 499」会系统性地抬高你对「便宜了多少」的估计。监管规定，折价的基准应当是促销前七日内同一家店的最低成交价，打几折要拿这家店促销前七天里实际卖出去的最低价当参照。划掉的那个价格，不一定真的卖过（中国，2020 年起施行）', '锚定效应是实验室里得出的结论，没有人算过囤货实际亏多少钱。囤货还有几笔你不会记在账上的成本：东西过期，占地方，以及「反正家里有，那就多用点」。只囤这三种都满足的东西：保质期长，确定会用完，单价确实比以前的价格低。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-25', 'concept_archive_s5-25', 'claim_archive_s5-25', 'action', 'life_archive', '保险优先买消费型，把「返还」「分红」当作不保证的部分', '5. 不要浪费钱', '分红和返还的那部分钱，保险公司不保证给你。说明书上必须用加粗字写明「未来的保单红利为非保证利益」。你为返还多交的保费，等于交给保险公司替你存着，收益不保证，想取出来也不容易。', '争议：对完全存不下钱的人来说，返还型保险逼着你按期交钱，这个作用有实际价值。上面的建议针对的是能管住自己的普通人。「买消费型，把省下的保费自己拿去投资」比「买返还型」到底好多少，要看具体产品，本节没有可以引用的系统性数据。不构成投资建议。', NULL, NULL, NULL, '消费型保险到期不返钱，心里会觉得「这钱白花了」。存钱的事要你自己安排。难的就是接受这笔钱拿不回来。', '监管规则要求，分红型产品的说明书要用加粗字体提示「未来的保单红利为非保证利益，其红利分配是不确定的」。红利演示就是保险公司给你看的那张分红测算表，它的利差上限是 4.5% 减去产品预定利率。预定利率就是合同里定死的那一档收益率。返还型和分红型多交的那部分保费，相当于交给保险公司代管的储蓄。它收益不保证，流动性也差，想取出来不容易（中国，2023 年起施行）', '争议：对完全存不下钱的人来说，返还型保险逼着你按期交钱，这个作用有实际价值。上面的建议针对的是能管住自己的普通人。「买消费型，把省下的保费自己拿去投资」比「买返还型」到底好多少，要看具体产品，本节没有可以引用的系统性数据。不构成投资建议。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-26', 'concept_archive_s5-26', 'claim_archive_s5-26', 'action', 'life_archive', '三者险买够：交强险限额全国统一且不高，超出的部分从你自己家里出', '5. 不要浪费钱', '你有责任时，交强险最多赔三项：死亡伤残 18 万元，医疗费用 1.8 万元，财产损失 2000 元。三项分开算，不能互相挪用。撞伤人的赔偿很容易超过这些限额，超出的钱要你自己家掏，所以商业三者险要买够。', '限额由金融监管部门定，会调整。这组数字是 2020 年 9 月车险综合改革以后的现行值，买保险前可以再核一次。关键是它的结构：交强险按项目分开赔，一项没赔完，剩下的额度不能挪去补另一项。撞伤人的赔偿总额可以远远超过它，超出的差额没有任何保险替你出。三者险保额到底买多少，本书不给数字。但它是这本书里少数几处「多花几百元，换掉一件概率很小、真摊上能压垮一个家的事」。', NULL, NULL, NULL, '商业第三者责任险一年几百到上千元。保额买得越高，平摊到每一元保额上的保费反而越便宜。', '交强险在全国范围内实行统一的责任限额。限额分成四项分别计算：死亡伤残、医疗费用、财产损失，以及你没有责任时的赔偿。2020 年车险综合改革以后，现行的总责任限额是 20 万元。这 20 万元里，死亡伤残 18 万元、医疗费用 1.8 万元、财产损失 0.2 万元。你没有责任的时候，死亡伤残 1.8 万元、医疗费用 1800 元、财产损失 100 元。超出限额的部分由侵权人自己承担，撞了人的一方要自己掏钱。没投交强险的，车辆会被扣留，还要罚应缴保险费的 2 倍', '限额由金融监管部门定，会调整。这组数字是 2020 年 9 月车险综合改革以后的现行值，买保险前可以再核一次。关键是它的结构：交强险按项目分开赔，一项没赔完，剩下的额度不能挪去补另一项。撞伤人的赔偿总额可以远远超过它，超出的差额没有任何保险替你出。三者险保额到底买多少，本书不给数字。但它是这本书里少数几处「多花几百元，换掉一件概率很小、真摊上能压垮一个家的事」。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-27', 'concept_archive_s5-27', 'claim_archive_s5-27', 'action', 'life_archive', '先存出 3 到 6 个月生活费的应急金，放在随时能取的地方', '5. 不要浪费钱', '把 3 到 6 个月的生活费放在随时能取出来的地方。这样失业或者生病的时候，你就不用去借那种一年要付 18% 利息的钱，也不用亏着把手里的投资卖掉。存在银行里的钱有存款保险，同一家银行最高赔 50 万元。', '「3 到 6 个月」是大家通行的经验，没有找到官方或者学术上的原始出处，所以标成 C 级。金额按你自己每月的固定支出来算，不按收入算。不构成投资建议。', NULL, NULL, NULL, '不花钱。代价是这笔钱要放弃更高的收益，只能放在活期、货币基金，或者随时能取的存款里。难的是攒的过程中忍住不动它。', '有了应急金，失业或者生病的时候你就不用去借钱，也不用亏着把投资卖掉。消费贷和信用卡最低还款按年算的利率，见本节第 7 条（不用信用卡最低还款）。存在银行里的钱受存款保险保护，同一家银行最高偿付 50 万元（中国，2015 年）', '「3 到 6 个月」是大家通行的经验，没有找到官方或者学术上的原始出处，所以标成 C 级。金额按你自己每月的固定支出来算，不按收入算。不构成投资建议。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-28', 'concept_archive_s5-28', 'claim_archive_s5-28', 'action', 'life_archive', '提前还房贷之前先做一道比较题，不要凭感觉', '5. 不要浪费钱', '提前还房贷，等于稳稳赚到你的房贷利率。所以只问一件事：你能长期稳定拿到的税后收益，比房贷利率高吗？高就别急着还，不高或说不准就还。等额本息前几年利息占得多，越早还省得越多。银行 App 的「提前还款试算」能直接算出数字。', '这里只给算法，不下结论。投资收益能稳定超过房贷利率的情况是少数。但不管你选哪一边，都要先留够应急现金。另外注意看合同里有没有提前还款违约金的条款。不构成投资建议。', NULL, NULL, NULL, '不花钱。花半小时算一笔账。你要老实估计自己能拿到的、扣完税以后的稳定收益率。', '算法是这样。先设房贷年利率为 r，按你的合同来。2026 年 8 月 20 日 5 年期以上 LPR 为 3.5%，实际执行的利率是在 LPR 上加点或者减点。再设 g 为你可选的另一种投资扣完税后的年化收益：这笔钱换个地方投，平均每年能赚到的比例。提前还款的确定收益率就是 r，每还掉一笔，就等于稳稳赚到了 r。如果 g 稳定大于 r，钱留在投资里更划算。如果 g 小于 r，或者 g 根本说不准，那提前还款就等于锁定一笔无风险的 r。等额本息前几年你还进去的钱里，利息占得多，所以越早还省下的利息越多。这一点用银行 App 的「提前还款试算」直接看数字（中国，2026 年利率）', '这里只给算法，不下结论。投资收益能稳定超过房贷利率的情况是少数。但不管你选哪一边，都要先留够应急现金。另外注意看合同里有没有提前还款违约金的条款。不构成投资建议。', '极高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-29', 'concept_archive_s5-29', 'claim_archive_s5-29', 'action', 'life_archive', '网购认平台规则和法条，不认主播和「好评」', '5. 不要浪费钱', '商家骗你，按你付的价款三倍赔，不到 500 元的按 500 元算。平台明知卖家侵权还不管，要跟着一起赔。定金最多收合同金额的 20%，你违约定金不退，卖家违约要双倍退你。直播间刷单、刷好评要担责，大数据杀熟是明文禁止的。', '「哪个平台性价比最高、不容易买到劣质品」这件事，没有可以引用的官方对比数据，所以本书不给平台排名。能查到的只有整体的抽查结果（见第 32 条，查国家抽检通报）。反不正当竞争法 2025 年修订以后，虚假宣传从旧的第八条改到了第九条。罚则从第二十条改到了第二十五条。新法 2025 年 10 月 15 日起施行。写材料时别抄旧条号。山东那批案例里，有一家公司组织「刷手」做了 75 笔虚假交易、本金 68 万余元，被查处了，罚款数字通报里没有写。七日无理由退货见本节第 23 条（网购善用七日无理由退货）。', NULL, NULL, NULL, '不花钱。下单前多看一眼售后条款和定金规则。收到货以后，把订单、直播回放截图和聊天记录都留好。难的是不被主播的气氛带着走。', '经营者有欺诈行为的，按价款的三倍赔偿，不足 500 元的按 500 元算。平台明知道或者应该知道卖家侵权却不处理的，要承担连带责任，这笔赔偿你可以直接找平台要。直播间和主播不得虚构交易、关注、浏览、点赞这些流量，也不得发布虚假信息，造成损害的要承担民事责任。组织虚假交易、虚假评价帮人刷宣传的，罚 100 万元以下；情节严重的罚 100 万到 200 万元，还可以吊销执照。定金不得超过合同标的额的 20%。你不履行合同，定金不退；卖家不履行，要双倍返还给你。用个人信息做自动化决策的，不得在交易价格等条件上搞不合理的差别待遇，这就是俗称的大数据杀熟（全国）', '「哪个平台性价比最高、不容易买到劣质品」这件事，没有可以引用的官方对比数据，所以本书不给平台排名。能查到的只有整体的抽查结果（见第 32 条，查国家抽检通报）。反不正当竞争法 2025 年修订以后，虚假宣传从旧的第八条改到了第九条。罚则从第二十条改到了第二十五条。新法 2025 年 10 月 15 日起施行。写材料时别抄旧条号。山东那批案例里，有一家公司组织「刷手」做了 75 笔虚假交易、本金 68 万余元，被查处了，罚款数字通报里没有写。七日无理由退货见本节第 23 条（网购善用七日无理由退货）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-30', 'concept_archive_s5-30', 'claim_archive_s5-30', 'action', 'life_archive', '直播间买的东西出了问题，先向平台要卖家和带货人的信息，平台必须给', '5. 不要浪费钱', '直播间买东西出了问题，最常见的死结是你找不到该告谁。这时候你可以直接要求平台，提供直播间运营者和带货人的信息，以及相关的经营记录。平台必须给。', '下单之前把直播画面和主播的承诺录屏留下来。出了问题先向平台要卖家和带货人的信息，再决定是投诉还是起诉。同一个条例还规定了三件事。一是商家不得自己扩大「不适用七日无理由退货」的商品范围。二是不得把「不适用无理由退货」设成默认选项。三是没有经过你确认，不得拒绝你退货。', NULL, NULL, NULL, '不花钱。向平台提出要求就行。', '发生消费争议的时候，直播营销平台的经营者应当按照消费者的要求，提供直播间运营者、直播营销人员的相关信息，以及相关的经营活动记录。直播维权最常见的难处是找不到该告谁，拿到这些信息就知道该告谁了', '下单之前把直播画面和主播的承诺录屏留下来。出了问题先向平台要卖家和带货人的信息，再决定是投诉还是起诉。同一个条例还规定了三件事。一是商家不得自己扩大「不适用七日无理由退货」的商品范围。二是不得把「不适用无理由退货」设成默认选项。三是没有经过你确认，不得拒绝你退货。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-31', 'concept_archive_s5-31', 'claim_archive_s5-31', 'action', 'life_archive', '买到不安全的食品，除了退钱还能要十倍价款，增加赔偿不足一千元的按一千元算', '5. 不要浪费钱', '买到过期、变质的食品，东西本身、包装和小票就是你的证据，别急着扔。你可以要价款十倍或损失三倍的赔偿，不到一千元的按一千元算。找卖家还是找厂家由你挑，被你找上的那一方必须先赔，不许推给另一方。', '证据的顺序比金额更重要。先拍照录像，把包装、生产日期、异物、购买记录都拍进去，再去联系商家或者平台。别在沟通之前就把东西扔了或者洗了。12315 做的是调解，不是裁决。商家咬死不认，就只剩起诉这条路，小额诉讼怎么算见第 8 节第 22 条（网购、二手交易被骗）。还要注意：吃出头发、虫子这类异物，要不要按「不符合食品安全标准」定性，通常得由市场监管部门认定或者做鉴定，不是你说了算。所以「吃出一根头发就稳拿一千元」这话不成立。普通商品的欺诈按三倍赔、不足 500 元按 500 元算，见本节第 29 条（网购认平台规则和法条）。自己做食品去卖的，要办哪些证、标签怎么写、为什么不许说能治病，这些都另有规定。细节见第 12 节第 8 到 11 条（食品的许可、标签、疗效红线和刑事线）。反过来说，把索赔做成一门生意有明确的红线。一是恶意制造出商家违法生产经营的假象，再拿投诉、起诉来要挟索取赔偿金的，涉嫌敲诈勒索，法院要把线索和材料移送公安。二是拿制造出来的假象去起诉的，法院驳回诉讼请求；构成虚假诉讼的，按情节轻重罚款、拘留，商家还可以反过来告你侵害名誉权。这一条的受益人是自己和家人这一档。', NULL, NULL, NULL, '不花钱。把食品、包装、小票留着，别扔也别洗，当场拍照。先找商家或者平台，谈不成就打 12315。真走到起诉，要几个月。难的是忍住别把东西先扔了。', '因为不符合食品安全标准的食品受到损害的，你可以向经营者要求赔偿损失，也可以向生产者要求。接到你赔偿要求的那一方实行首负责任制，要先行赔付、不得推诿。意思是你找的是谁，谁就得先把钱赔了，不能把你推给另一方。除了要求赔偿损失，你还可以要求对方支付价款十倍或者损失三倍的赔偿金，而且「增加赔偿的金额不足一千元的，为一千元」。但有一处例外：「食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外」。司法解释还定了几条。第一，要同时满足三个条件。购买者是因为个人或者家庭生活消费需要买的。食品不符合食品安全标准。又没有证据证明他买的时候就知道。满足了就「以其实际支付价款为基数计算价款十倍的惩罚性赔偿金」。第二，明知不符合标准还是买、然后索赔的，人民法院只「在合理生活消费需要范围内」支持。连续购买、反复起诉的，按多次购买的总数放在同一个范围内认定。第三，有几种瑕疵法院不支持惩罚性赔偿，前提是它不会让消费者对食品安全产生误解。这几种瑕疵是：文字字号不规范，有错别字、多字漏字。还有净含量与规格的标示方式不规范。还有对没有特殊贮存条件要求的食品没有标示贮存条件（全国）', '证据的顺序比金额更重要。先拍照录像，把包装、生产日期、异物、购买记录都拍进去，再去联系商家或者平台。别在沟通之前就把东西扔了或者洗了。12315 做的是调解，不是裁决。商家咬死不认，就只剩起诉这条路，小额诉讼怎么算见第 8 节第 22 条（网购、二手交易被骗）。还要注意：吃出头发、虫子这类异物，要不要按「不符合食品安全标准」定性，通常得由市场监管部门认定或者做鉴定，不是你说了算。所以「吃出一根头发就稳拿一千元」这话不成立。普通商品的欺诈按三倍赔、不足 500 元按 500 元算，见本节第 29 条（网购认平台规则和法条）。自己做食品去卖的，要办哪些证、标签怎么写、为什么不许说能治病，这些都另有规定。细节见第 12 节第 8 到 11 条（食品的许可、标签、疗效红线和刑事线）。反过来说，把索赔做成一门生意有明确的红线。一是恶意制造出商家违法生产经营的假象，再拿投诉、起诉来要挟索取赔偿金的，涉嫌敲诈勒索，法院要把线索和材料移送公安。二是拿制造出来的假象去起诉的，法院驳回诉讼请求；构成虚假诉讼的，按情节轻重罚款、拘留，商家还可以反过来告你侵害名誉权。这一条的受益人是自己和家人这一档。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-32', 'concept_archive_s5-32', 'claim_archive_s5-32', 'action', 'life_archive', '买大件前先查国家抽检通报、3C 认证和能效标识', '5. 不要浪费钱', '2024 年国家抽检了 25250 批次产品，14.3% 不合格。电商渠道更差：抽了 7297 批次，23.5% 不合格；实体店是 15.1%。买大件之前花几分钟，查一下抽检通报，再查一下 3C 证书是不是真的。该贴能效标识的，不能缺。', '抽查是监管部门挑一部分货来检，结果不等于整个市场的合格率，也不能拿它给平台排名。「查一下能少买到多少劣质品」这件事没有研究，所以定成 B 级。认监委的查询平台 cx.cnca.cn，本节核实的时候打不开，入口以 cnca.gov.cn 首页为准。抽查通报的数字每年更新，用的时候查最新一期。', NULL, NULL, NULL, '不花钱。花几分钟，在市场监管总局和认监委的官网上查一下。', '2024 年国家监督抽查了 25250 批次产品，不合格率 14.3%。其中电商渠道抽了 7297 批次，不合格率 23.5%，比上一年升了 1.8 个百分点。实体店抽了 8055 批次，不合格率 15.1%。强制性产品认证（3C）的证书，可以在认监委官网的「认证结果」栏里查真伪。能效标识按产品目录强制管理，标识上必须有能效等级、能效指标和能效信息码。伪造、冒用能效标识，或者该标不标的，按节约能源法处罚（全国）', '抽查是监管部门挑一部分货来检，结果不等于整个市场的合格率，也不能拿它给平台排名。「查一下能少买到多少劣质品」这件事没有研究，所以定成 B 级。认监委的查询平台 cx.cnca.cn，本节核实的时候打不开，入口以 cnca.gov.cn 首页为准。抽查通报的数字每年更新，用的时候查最新一期。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-33', 'concept_archive_s5-33', 'claim_archive_s5-33', 'action', 'life_archive', '手串、玉石、名表、潮玩按「花掉的钱」算账，不按「存下的钱」算', '5. 不要浪费钱', '这类东西的价钱里先含了一截消费税：每只 1 万元及以上的手表是 20%，金银铂金首饰和钻石是 5%，其他珠宝玉石是 10%，增值税另算。这笔税转手卖掉时拿不回来。真喜欢就当消费买，别算成理财。', '押给典当行要算清楚：每月的综合费用上限是借款额的 42‰，一年就是借款额的五成左右，借款的利息还要另算。这个「一年五成」是拿月费率直接乘 12 算的粗账，用来看个量级，不是精确的一年利率。税率和费率都是明文写着的数字。但「这类东西长期能不能升值」没有可以引用的官方统计，本书不做预测，也不点评任何品类。要拦的只是把消费当投资的那部分理由：喜欢、戴着高兴，按消费买没问题；以「保值」「以后能卖更高」为理由把预算加上去，才是亏钱的地方。黄金也分两头：按克重买卖的投资性金条，和按件卖的首饰不是一回事。首饰的价钱里含设计费和工费，回收的时候通常不算这部分。二手平台上的挂牌价不是成交价，别当行情看。', NULL, NULL, NULL, '不花钱。只是别把「以后能升值」算进你买它的理由里。难的是忍住不为「保值」加预算。', '先看买入这一头。《消费税税目税率表》定的税率是这样的。「高档手表」20%。「贵重首饰及珠宝玉石」里，金银首饰、铂金首饰、钻石及钻石饰品 5%。其他贵重首饰和珠宝玉石 10%。「高档手表」的口径是「销售价格（不含增值税）每只在 10000 元（含）以上的各类手表」。再看变现这一头，依据是《典当管理办法》。第三十六条：典当期限最长不得超过 6 个月。第三十七条讲的是当金利率，指典当行借给你那笔钱的利息。这个利息按中国人民银行公布的 6 个月期法定贷款利率和典当期限折算。利息不得预扣，不能从给你的钱里先扣走。第三十八条：动产质押典当（押手表玉石这类东西）的月综合费率，不得超过当金的 42‰，每月另收的综合费用不超过借款额的 4.2%。房地产抵押是 27‰，财产权利质押是 24‰。第四十条：期限到了以后 5 日内既不赎当也不续当，就算绝当，东西不再等你来赎。第四十三条：估价金额 3 万元以上的绝当物，可以委托拍卖。拍卖收入要先扣掉拍卖费用和当金本息。剩下的退还给当户，不够的部分还要向当户追索（全国）', '押给典当行要算清楚：每月的综合费用上限是借款额的 42‰，一年就是借款额的五成左右，借款的利息还要另算。这个「一年五成」是拿月费率直接乘 12 算的粗账，用来看个量级，不是精确的一年利率。税率和费率都是明文写着的数字。但「这类东西长期能不能升值」没有可以引用的官方统计，本书不做预测，也不点评任何品类。要拦的只是把消费当投资的那部分理由：喜欢、戴着高兴，按消费买没问题；以「保值」「以后能卖更高」为理由把预算加上去，才是亏钱的地方。黄金也分两头：按克重买卖的投资性金条，和按件卖的首饰不是一回事。首饰的价钱里含设计费和工费，回收的时候通常不算这部分。二手平台上的挂牌价不是成交价，别当行情看。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-34', 'concept_archive_s5-34', 'claim_archive_s5-34', 'action', 'life_archive', '珠宝玉石只认带 CMA 标志的检测报告，并到发证部门官网核一下这家机构', '5. 不要浪费钱', '证书能伪造，所以要查的是出证书的那家机构。检测机构对外出报告必须有资质，报告上要印 CMA 标志。发证部门会在官网公布机构名单，你自己就能查这家在不在上面。官方查处的案子里，随货的「国检证书」有自己找人做的。', '珠宝玉石的名称有国家标准。检测结论写出来是「石英岩玉（染色）」「翡翠（处理）」这种带括号的形式，括号里那两个字就是差价所在。「A 货」「老坑」「无优化」是卖家的话术，不是鉴定结论。前面那家卖染色石英岩玉的直播间，用的就是这套词。同一批案例里还有别的花样：伪造矿区现场、安排人扮成「矿工」直播，安排水军在直播间烘托气氛，编「急用钱」「亲人重病」的剧本。还有宣称商品能「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」的，这一类按虚假宣传查处。买大件的通用查法见本节第 32 条（查抽检通报和 3C 认证）。直播间出了事该找谁，见第 29、30 条（网购认平台规则、直播间出问题找平台要信息）。', NULL, NULL, NULL, '不花钱。下单之前查一次出证机构的资质，几分钟就够。', '先看规则，依据是《检验检测机构资质认定管理办法》。第二条：资质认定，是对「向社会出具具有证明作用的数据、结果」的检验检测机构做的评价许可：先审查它，再发给它出证书的资格。第十五条：资质认定标志由 CMA 图案和资质认定证书编号两部分组成。第二十一条：机构对外出具有证明作用的数据、结果的，应当在检验检测报告上标注资质认定标志。第二十二条：资质认定部门应当在官方网站上公布取得资质认定的机构信息，并注明证书状态。第三十四条：没有依法取得资质认定就擅自对外出具有证明作用的数据、结果的，处 3 万元罚款。第三十七条：伪造、变造、冒用资质认定证书或者标志的，处 3 万元以下罚款。再看官方案例，出自市场监管总局 2026 年 6 月 4 日公布的传统工艺市场「打假清源」典型案例。一，江苏东海一个直播间宣称，卖的是「天然的、无酸洗、无优化、缅甸的 A 货」。直播间还配了「国检证书」。送检结果却是石英岩玉（染色）、翡翠（处理）、玻璃和塑料。那张证书是当事人自己联系人做出来的。二，同一个县还有一案，扣押了 469 件疑似假冒的天然水晶制品，检出 210 件是天然水晶、259 件是合成水晶。三，河南镇平一家店铺私自做了一块展板，用于直播。展板上写的是「GIA CMA 中玉珠宝玉石鉴定中心认证合作单位」。这家店还从网上买了 181 只「国家珠宝玉石质量监督检验中心」的合格证标识。这些标识配着手镯一起卖（全国）', '珠宝玉石的名称有国家标准。检测结论写出来是「石英岩玉（染色）」「翡翠（处理）」这种带括号的形式，括号里那两个字就是差价所在。「A 货」「老坑」「无优化」是卖家的话术，不是鉴定结论。前面那家卖染色石英岩玉的直播间，用的就是这套词。同一批案例里还有别的花样：伪造矿区现场、安排人扮成「矿工」直播，安排水军在直播间烘托气氛，编「急用钱」「亲人重病」的剧本。还有宣称商品能「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」的，这一类按虚假宣传查处。买大件的通用查法见本节第 32 条（查抽检通报和 3C 认证）。直播间出了事该找谁，见第 29、30 条（网购认平台规则、直播间出问题找平台要信息）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-35', 'concept_archive_s5-35', 'claim_archive_s5-35', 'action', 'life_archive', '盲盒、抽卡这类随机销售，按「这笔钱不会回来」算', '5. 不要浪费钱', '商家必须把抽取规则、抽取概率、限量款数量摆在显眼处，不许后台操纵结果，不许设空盒。保底和花钱、抽取次数的上限，文件只是鼓励商家做。网上买的盲盒，商家讲清楚、你也确认过的，拆封后就不能七日无理由退货。', '这份文件是指引，管的是经营者该怎么做，它本身不是处罚依据。真出了事，按产品质量法、反不正当竞争法、消费者权益保护法处理。有三种情况是你能投诉的具体事由：概率没公示，公示的概率和实际对不上，买到空盒。投诉之前，先把页面上的规则和开箱的过程录屏留下来。拆封后不适用七日无理由退货有个前提：商家充分告知了，你在单次购买时也确认了，而且不得用默认勾选替你确认。卖给未成年人另有规定：不满 8 周岁的孩子商家不得卖给他，8 周岁及以上的要先确认已经取得监护人同意。孩子拿手机充值打赏怎么退款，见本节第 9 条（孩子用手机充值打赏）。大额非必需购买的 24 小时冷静期，见第 23 条（大额非必需购买设冷静期）。「买到手就淡了、于是接着买」这个循环，见第 6 节第 23 条（别指望买东西改善心情）。', NULL, NULL, NULL, '不花钱。只是买之前把预算定死。难的是没抽到想要的那个，还要停手。', '依据是《盲盒经营行为规范指引（试行）》。第九条列了一串关键信息，应当以显著方式对外公示，保证消费者买之前就知道。这些信息是：商品名称、种类、样式、抽取规则、商品分布、限量商品投放数量、抽取概率、商品价值范围。同一条还规定了三件不许做的事。一是不得通过后台操纵改变抽取结果、随意调整抽取概率等方式变相诱导消费。二是不得用折现、回购、换购等方式拒绝或者故意拖延发放盲盒。三是不得设置空盒。第十一条只是「鼓励」经营者建立保底机制，通过设定抽取时间、抽取金额上限和次数上限等方式引导理性消费。第十七条管的是以互联网形式卖的盲盒商品。经营者充分告知提示了，消费者也在单次购买时确认了，这种盲盒拆封后可以不适用七日无理由退货。经营者不得用默认勾选的方式替代消费者的确认环节。第二十一条：不得以盲盒的名义从事或者变相从事赌博活动。第二十三条：不得向未满 8 周岁的未成年人销售盲盒；向 8 周岁及以上的未成年人销售，应当依法确认已经取得相关监护人的同意（全国）', '这份文件是指引，管的是经营者该怎么做，它本身不是处罚依据。真出了事，按产品质量法、反不正当竞争法、消费者权益保护法处理。有三种情况是你能投诉的具体事由：概率没公示，公示的概率和实际对不上，买到空盒。投诉之前，先把页面上的规则和开箱的过程录屏留下来。拆封后不适用七日无理由退货有个前提：商家充分告知了，你在单次购买时也确认了，而且不得用默认勾选替你确认。卖给未成年人另有规定：不满 8 周岁的孩子商家不得卖给他，8 周岁及以上的要先确认已经取得监护人同意。孩子拿手机充值打赏怎么退款，见本节第 9 条（孩子用手机充值打赏）。大额非必需购买的 24 小时冷静期，见第 23 条（大额非必需购买设冷静期）。「买到手就淡了、于是接着买」这个循环，见第 6 节第 23 条（别指望买东西改善心情）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-36', 'concept_archive_s5-36', 'claim_archive_s5-36', 'action', 'life_archive', '在意食品里加了什么，就买预包装的：散装柜台法律上不要求标配料表', '5. 不要浪费钱', '法律只要求预包装食品标配料表，散装的不要求。散装柜台只要标名称、生产日期、保质期和谁生产的。所以「没写添加剂」不等于「没加」，只等于法律没要求写。在意就买预包装的那一版，配料表和添加剂名称都印在上面。', '「没标」不等于「没加」，只等于法律没要求标。想知道成分，就买预包装的那一版。冻虾仁、冻鱼块这类，预包装上的净含量是扣掉冰衣之后的重量。按它算单价才是真实价格。散装的按标价算，解冻后可能缩掉一大截。保水剂在限量内是合法的，也不是安全问题，别把它当毒。超量添加和包冰增重是钱的问题：你按水产品的价钱买了水。反过来，散装柜台该标的那四样也可能没标。名称、生产日期、保质期、生产经营者的名称地址电话，少一样就违反第六十八条。可以不买，也可以打 12315。你自己开店卖装袋食品时该怎么标，见第 12 节第 9 条（预包装食品标签）。这条的受益人是你自己和家人，属于最高的两档。', NULL, NULL, NULL, '不花钱。同样的东西，预包装的通常比散装贵一点。看一眼配料表，几秒钟。', '食品安全法第六十七条规定，预包装食品的包装上应当有标签。标签必须标明九项内容。其中第二项是「成分或者配料表」，第七项是「所使用的食品添加剂在国家标准中的通用名称」。第六十八条对散装食品的要求少得多。原文是：食品经营者销售散装食品，应当在散装食品的容器、外包装上标明「食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容」。这一条没有提配料表，也没有提添加剂。冷冻水产品是这个差别最明显的地方。GB 2760—2024 允许在冷冻水产品里用磷酸及磷酸盐做水分保持剂，俗称保水剂。最大使用量是 5.0 g/kg，以磷酸根计。在这个量以内用是合法的。出问题的是超量用和包冰增重。2025 年央视 3·15 晚会曝光虾仁「违规超量添加保水剂（复合磷酸盐）及包冰增重」之后，市场监管部门要求企业「产品标签应明确标注保水剂（如磷酸盐）成分、净含量（扣除冰衣重量）、配料表」（全国，食品安全法 2025 年第三次修正，2025 年 12 月 1 日起施行）', '「没标」不等于「没加」，只等于法律没要求标。想知道成分，就买预包装的那一版。冻虾仁、冻鱼块这类，预包装上的净含量是扣掉冰衣之后的重量。按它算单价才是真实价格。散装的按标价算，解冻后可能缩掉一大截。保水剂在限量内是合法的，也不是安全问题，别把它当毒。超量添加和包冰增重是钱的问题：你按水产品的价钱买了水。反过来，散装柜台该标的那四样也可能没标。名称、生产日期、保质期、生产经营者的名称地址电话，少一样就违反第六十八条。可以不买，也可以打 12315。你自己开店卖装袋食品时该怎么标，见第 12 节第 9 条（预包装食品标签）。这条的受益人是你自己和家人，属于最高的两档。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-37', 'concept_archive_s5-37', 'claim_archive_s5-37', 'action', 'life_archive', '亏了的股票也要按事先定好的规则卖掉，不靠往下补仓摊平成本翻身', '5. 不要浪费钱', '人的本能是赚了就卖、亏了死扛。一万个美国账户七年的记录里，涨了的股票被卖掉的可能比跌了的高五成以上。同一批人还更爱给亏着的股票加仓。可他们留下的亏损股，后面一年平均还比卖掉的那些差 3.4 个百分点。', '这一条管的是「卖不卖」，第 15 条（不频繁交易股票）管的是「别老动手」，两条不冲突。事先定好规则再照着执行，动手次数反而更少。往下补仓摊平成本，算术上没错，多买一点平均成本就是低一点。错的是把它当成翻身的办法，它的实际效果是把你押在这一只股票上的钱变多了，见第 19 条（别把钱押在一只股票）。抵税那一段是按美国税制算的，中国不照搬，其余部分仍然成立。这是美国 1980 到 1990 年代的账户数据，A 股的交易成本和税制都不一样。不构成投资建议。', NULL, NULL, NULL, '不花钱。难的是承认这一笔已经亏了，然后把它卖掉。', '这项研究看的是美国一家折扣券商 10,000 个账户 1987 到 1993 年的全部交易记录。盈利股被卖出的比例（PGR）是 0.148。亏损股被卖出的比例（PLR）是 0.098。两者相差 0.050，t 值超过 35。按天算，涨了的股票被卖掉的可能性比跌了的高 50% 以上。同一批账户给亏损股加仓也更积极。亏损股被再买一次的比例是 0.135，盈利股是 0.094，t 值 19。研究还检验了「留着的会涨回来」这个想法。结果是反的：卖掉的盈利股在此后一年的超额收益，平均比留着没卖的亏损股高 3.4 个百分点。超额收益指的是比市场指数多出来的那一部分。作者还按平均值算过一个例子。同样卖掉 1000 美元的股票，卖亏损的那只比卖盈利的那只，此后一年回报高约 4.4%。这 4.4% 里含了卖亏损股提前抵税省下的钱。抵税是按美国的税制算的（美国，1987 到 1993 年）', '这一条管的是「卖不卖」，第 15 条（不频繁交易股票）管的是「别老动手」，两条不冲突。事先定好规则再照着执行，动手次数反而更少。往下补仓摊平成本，算术上没错，多买一点平均成本就是低一点。错的是把它当成翻身的办法，它的实际效果是把你押在这一只股票上的钱变多了，见第 19 条（别把钱押在一只股票）。抵税那一段是按美国税制算的，中国不照搬，其余部分仍然成立。这是美国 1980 到 1990 年代的账户数据，A 股的交易成本和税制都不一样。不构成投资建议。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-38', 'concept_archive_s5-38', 'claim_archive_s5-38', 'action', 'life_archive', '想买美股这类海外资产，走 QDII 基金或港股通，别去境外券商开户，也别拿每年的换汇额度去买', '5. 不要浪费钱', '老虎、富途、长桥这类境外券商，2026 年 5 月起不许再给境内的人开户。已经开了的，两年内只能卖出、把钱转出来，不能再买。换汇额度也不许拿去买境外股票，违规的当年和之后 2 年都不能再用这个额度。想买海外资产，走 QDII 基金或港股通。', '这几份文件管的是境外机构，没有写对投资者本人的处罚。已经在境外券商有账户的，两年内卖出、把钱转回来即可。三条合法渠道各有开通条件，先在自己的银行或券商问清楚。美股过去涨得多，不代表以后也会。买 QDII 同样按第 17 条（宽基指数基金）和第 19 条（别把钱押在一只股票、一个平台、一套房上）的办法，挑宽基指数，别押在单一市场上。境外取现另有额度，见第 21 节第 6 条（境外取现）。不构成投资建议。', NULL, NULL, NULL, '不花钱。在自己的银行或证券 App 里就能买 QDII 基金，几分钟。代价是能买的品种比境外券商少。', '2026 年 5 月 22 日，证监会、工业和信息化部、公安部、中国人民银行、市场监管总局、金融监管总局、国家网信办、国家外汇局八个部门印发《综合整治非法跨境证券期货基金经营活动实施方案》。总体要求是「经过2年集中整治，全面取缔境外证券期货基金经营机构非法跨境经营活动」。境外机构不得在境内开展营销招揽，不得「提供相关开户、处理交易指令、资金划转等交易服务」。对已经开了户的人，方案写的是「禁止境外机构为存量投资者在境内非法提供买入交易、转入资金等服务，只允许单向卖出交易并转出资金」。两年期满后，「全面关停境内网站、交易软件及配套服务器」。同一天证监会通报，拟没收老虎、富途、长桥境内外相关主体全部违法所得，并依法严厉处罚。配套的答记者问写明，要「引导境内投资者通过港股通、合格境内机构投资者（QDII）及跨境理财通等合法渠道开展境外投资」。换汇这头，国家外汇局的《个人购汇申请书》写明，个人购汇「不得用于境外买房、证券投资、购买人寿保险和投资性返还分红类保险等尚未开放的资本项目」。违规的人列入「关注名单」，「当年及之后连续 2 年不享有个人便利化额度」，还会被行政处罚、移送反洗钱调查，信息纳入个人征信记录（全国，2026 年 5 月起）', '这几份文件管的是境外机构，没有写对投资者本人的处罚。已经在境外券商有账户的，两年内卖出、把钱转回来即可。三条合法渠道各有开通条件，先在自己的银行或券商问清楚。美股过去涨得多，不代表以后也会。买 QDII 同样按第 17 条（宽基指数基金）和第 19 条（别把钱押在一只股票、一个平台、一套房上）的办法，挑宽基指数，别押在单一市场上。境外取现另有额度，见第 21 节第 6 条（境外取现）。不构成投资建议。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-39', 'concept_archive_s5-39', 'claim_archive_s5-39', 'action', 'life_archive', '只给自己扛不住的损失买保险，扛得住的损失用应急金兜着', '5. 不要浪费钱', '你交的保费不会全部赔回来，有一部分要付保险公司的费用和利润。所以值得买的，是很少发生、一旦发生家里掏不出来的损失，比如大病、开车撞伤人、家里挣钱的人走了。存款扛得住的小损失，交给应急金。', '定 C 级，是因为没有官方数字能算出哪种保险买了划算，这里给的是取舍的办法。碎屏险、航班延误险这类，损失几百元，自己掏得起，按这个标准可以不买。重疾险赔的是生病停工那几年的收入，存款够撑一两年停工的人，可以考虑不买。基本医保是社会保险，不按这个办法取舍，照样要交，见第 7 节第 9 条（居民医保）。小损失靠什么兜，见本节第 27 条（应急金）。这条的受益人是你自己和家人。', NULL, NULL, NULL, '不花钱。要做的是把家里可能遇到的大损失列一遍，看哪几样存款扛不住。一次半小时。', '保险公司收上来的保费，只有一部分会作为赔款付出去。剩下的要付销售和运营的费用，还有公司的利润。监管要求卖个人短期健康险的公司，每半年在官网公布一次「综合赔付率」。它大致是赔出去的钱占保费的比例，想知道一家公司赔出去多少，可以去它官网查。所以对一件损失来说，买保险长期平均是亏一点钱。换来的是把一次能压垮家里的大额支出，摊成每年一笔小钱。损失越小、你越掏得起，这笔交换越不划算。按这个标准，书里已经写过的几样是值得买的。一年期医疗险见第 7 节第 20 条（一年期医疗险）。有车的人见本节第 26 条（三者险）。出国的人见第 21 节第 4 条（境外医疗）。家里有人靠你的收入过日子的，见本节第 40 条（定期寿险）（全国，2021 年起）', '定 C 级，是因为没有官方数字能算出哪种保险买了划算，这里给的是取舍的办法。碎屏险、航班延误险这类，损失几百元，自己掏得起，按这个标准可以不买。重疾险赔的是生病停工那几年的收入，存款够撑一两年停工的人，可以考虑不买。基本医保是社会保险，不按这个办法取舍，照样要交，见第 7 节第 9 条（居民医保）。小损失靠什么兜，见本节第 27 条（应急金）。这条的受益人是你自己和家人。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-40', 'concept_archive_s5-40', 'claim_archive_s5-40', 'action', 'life_archive', '家里有人靠你的收入过日子，先给挣钱的人买定期寿险，别先给孩子买', '5. 不要浪费钱', '定期寿险只保固定的年数，这些年里人走了，家里拿到一笔钱。它是给靠你收入过日子的家人留的，比如房贷没还完、孩子还小。没人靠你养，就用不着。孩子不挣钱，给孩子买的死亡保险，法律还限了能赔多少。', '定 C 级，是因为官方只有定义和限额，「先保大人」是按「谁的收入断了家里过不下去」推出来的。孩子出事，家里并不会少一份收入。家里挣钱的人走了，房贷和孩子的开销还在。钱有限时，先给挣钱的人买定期寿险和一年期医疗险，再轮到孩子的医疗险。如实告知和保证续保怎么看，见第 7 节第 20 条（一年期医疗险）。这条的受益人落在第 ② 档，是你的配偶和孩子。', NULL, NULL, NULL, '一年几百到几千元，看年龄、保额和保多少年（作者粗估，无官方数字）。投保前要如实告知健康状况，一次性花半小时。', '监管对寿险的定义是：以人的寿命为保险标的的人身保险，分定期寿险、终身寿险、两全保险等。定期寿险以被保险人死亡为给付保险金的条件，保险期间是固定的年数。终身寿险保到终身。意外伤害保险只在意外事故导致身故、残疾时才赔，生病去世不赔，代替不了寿险。以死亡为给付条件的合同，要经被保险人本人同意并认可保额，否则合同无效。父母给未成年子女投保死亡保险不受这条限制，但因孩子死亡给付的保险金总和，不得超过监管机构规定的限额。寿险保额通常在数十万元级，收益因此定为大。保额买多少没有官方口径。作者的算法是：没还完的房贷，加上孩子长到成年前的开销，再加几年的家用（全国，2015 年修正）', '定 C 级，是因为官方只有定义和限额，「先保大人」是按「谁的收入断了家里过不下去」推出来的。孩子出事，家里并不会少一份收入。家里挣钱的人走了，房贷和孩子的开销还在。钱有限时，先给挣钱的人买定期寿险和一年期医疗险，再轮到孩子的医疗险。如实告知和保证续保怎么看，见第 7 节第 20 条（一年期医疗险）。这条的受益人落在第 ② 档，是你的配偶和孩子。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","C 级","性价比 高","口径 金钱","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-41', 'concept_archive_s5-41', 'claim_archive_s5-41', 'action', 'life_archive', '签了一年以上的人身险又后悔，在犹豫期内退掉，保费基本全退', '5. 不要浪费钱', '一年以上的人身险都有犹豫期。在银行买的，是收到保单后 15 天，这期间退保最多扣 10 元工本费。过了犹豫期再退，只能拿回保单里能退的那部分钱，往往比交的少。保险公司打回访电话问你清不清楚，没弄懂就别说清楚。', '犹豫期是给一年以上人身险定的规矩。一年期的医疗险、意外险，规定里没要求，有没有要看条款。不在银行买的，天数以合同写的为准，拿到保单先翻「犹豫期」那一条。储蓄型、分红型保险交的钱多，犹豫期最值得用上，见本节第 25 条（消费型）。收益定「中」，是因为能省下的是交的保费和现金价值之间的差，常见在数百到数千元，没有官方统计。这条的受益人是你自己。', NULL, NULL, NULL, '不花钱。打保险公司的客服电话或者去柜台办，十几分钟。难的是签完以后，在 15 天里静下心把合同读一遍。', '保险期间超过一年的人身险，监管要求写明犹豫期从哪天算、有几天。投保人在犹豫期里有什么权利，也要写明。长期健康险的犹豫期不得少于 15 天。在银行买的、保险期间超过一年的保险，合同里一律约定 15 日犹豫期。它从你收到保单并书面签收那天算起，按自然日算。这类保单的封面上要印这句提示：「您在收到保险合同后15日内有全额退保（扣除不超过10元的工本费）的权利。超过15日退保有损失。」过了犹豫期，你仍然可以随时解除合同。保险公司要在 30 日内，按合同约定退还保单的现金价值（保单里能退的那部分钱）。金融监管部门的风险提示说，长期人身险犹豫期后退保，现金价值往往低于已交的总保费。一年以上的人身险新单，保险公司要在犹豫期内回访你。回访要确认你知不知道退保的损失和犹豫期的权利（全国，2010、2019 年起）', '犹豫期是给一年以上人身险定的规矩。一年期的医疗险、意外险，规定里没要求，有没有要看条款。不在银行买的，天数以合同写的为准，拿到保单先翻「犹豫期」那一条。储蓄型、分红型保险交的钱多，犹豫期最值得用上，见本节第 25 条（消费型）。收益定「中」，是因为能省下的是交的保费和现金价值之间的差，常见在数百到数千元，没有官方统计。这条的受益人是你自己。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-42', 'concept_archive_s5-42', 'claim_archive_s5-42', 'action', 'life_archive', '在银行柜台签字前，先看清手里的是存款还是保险', '5. 不要浪费钱', '银行能代卖保险，但不许说成存款。保险合同的封面要用大字印「保险合同」和保险公司的名字，不许出现「存款」「储蓄」字样。封面上是保险公司，这钱就不是存款，过了犹豫期再退会亏。65 岁以上的人在银行买，原则上只能买收益确定的。', '定 B 级，是因为规定写得很清楚，但没有「被误导的人亏了多少」的官方数字。家里老人在银行存钱时最容易碰上，陪他们去的时候帮着看一眼封面。已经签了的，在 15 天内按本节第 41 条（犹豫期）退掉。觉得被误导了怎么投诉，见本节第 43 条（代理退保）。这条的受益人是你自己和家里老人。', NULL, NULL, NULL, '不花钱。签字前多看两分钟合同封面。', '规定写明，银行不得把保险和储蓄存款、基金、银行理财混在一起卖。不得把保险的收益和存款简单类比，不得把不确定的收益说成保证收益。保险单证和宣传材料不许用银行的名称和标识，不许出现「存款」「储蓄」「与银行共同推出」这类字样。保险单封面要用不小于 72 号的字印「保险合同」，用不小于二号的字印保险公司名称。有三种人买保险，原则上只能卖保单利益确定的产品：投保人超过 65 周岁的；买期缴产品、投保人超过 60 周岁的；填的年收入低于当地居民人均可支配收入的。这三种人的保单还要转给保险公司人工核保，不许在网点自动出单。保险公司的人不许在银行网点里卖保险。银行卖的一年以上保险，有 15 日犹豫期，过了犹豫期退保就有损失（全国，2019 年 10 月起）', '定 B 级，是因为规定写得很清楚，但没有「被误导的人亏了多少」的官方数字。家里老人在银行存钱时最容易碰上，陪他们去的时候帮着看一眼封面。已经签了的，在 15 天内按本节第 41 条（犹豫期）退掉。觉得被误导了怎么投诉，见本节第 43 条（代理退保）。这条的受益人是你自己和家里老人。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-43', 'concept_archive_s5-43', 'claim_archive_s5-43', 'action', 'life_archive', '想退保就自己找保险公司办，别找「代理退保」，觉得被误导了打 12378 投诉', '5. 不要浪费钱', '网上喊「全额退保、不成功不收费」的，多半是非法代理退保。他们要拿走退回来的钱的三到五成，还要你的身份证、银行卡和验证码。退了保，保障也就没了。觉得被误导了，先找保险公司客服，谈不拢打 12378，全程免费。', '湖南金融监管局 2025 年通报过一个案例。一位女士被「朋友」劝去代理退保，交了「咨询费」，最后还是按现金价值退的保。退保 3 个月后，她确诊乳腺癌，那份重疾险已经没了。退不退要自己算：保障还用得上的，交不起就先问减额交清。自己在犹豫期里退，见本节第 41 条（犹豫期）。这条的受益人是你自己。', NULL, NULL, NULL, '不花钱。自己打保险公司客服电话或者去柜台，比交给中介多跑一两趟。', '2026 年 2 月，金融监管总局、中央网信办、公安部、中国人民银行、中国证监会联合发了风险提示。它说「全额退保」这类说法属于不实信息，和保险法等法律法规不符。「代理维权」的人会收高额服务费，你中途想退出，还可能因为「违约」吃官司。他们还会收集你的手机卡、银行卡、保单、家庭住址、孩子的学校这些信息。这些信息被倒卖，你可能碰上电信诈骗和盗刷。宁夏金融监管局 2026 年 6 月的提示写得更细。这类中介约定退保成功后，收退保金额 30% 到 50% 的代理费，中途不干了要交高额违约金。他们教人编造销售误导、代签名这类理由去投诉。照做的人可能违反治安管理处罚法，严重的可能涉嫌诬告陷害或敲诈勒索的共同犯罪。退保后保险责任马上终止。以后再买同类保险，可能因为年纪大了、身体查出问题，而涨价或者被拒保。真被误导了，先找保险公司官方客服投诉协商，谈不拢打 12378 银行保险消费者投诉维权热线，全程免费。只是一时交不起保费，可以先问保险公司能不能办减额交清、保单贷款这类服务。减额交清就是以后不再交钱，保额按比例降下来（全国，2026 年）', '湖南金融监管局 2025 年通报过一个案例。一位女士被「朋友」劝去代理退保，交了「咨询费」，最后还是按现金价值退的保。退保 3 个月后，她确诊乳腺癌，那份重疾险已经没了。退不退要自己算：保障还用得上的，交不起就先问减额交清。自己在犹豫期里退，见本节第 41 条（犹豫期）。这条的受益人是你自己。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"5. 不要浪费钱","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-44', 'concept_archive_s5-44', 'claim_archive_s5-44', 'action', 'life_archive', '保单上把受益人写成具体的人，出了事记得去领钱：寿险 5 年、其他保险 2 年内要主张', '5. 不要浪费钱', '没写受益人，或者受益人先走了，保险金就算遗产，要先拿去还去世的人欠的债。受益人写了「妻子某某」，后来离婚了，出事时算没写。家里人要知道有这张保单：寿险从知道出事起 5 年内要去主张，其他保险是 2 年。', '诉讼时效过了，保险公司可以拒绝给钱，打官司也很难要回来。所以家里人至少要知道你在哪几家公司买过保险。离婚、再婚、孩子出生以后，回头把受益人改一次。人走了以后逐个去取各处的钱，见第 25 节第 9 条（逐个去取）。用死还债这条路走不通，见第 29 节第 13 条（还债）。这条的受益人落在第 ② 档，是你的配偶和孩子。', NULL, NULL, NULL, '不花钱。投保时填一次，以后改受益人要书面通知保险公司。', '保险法规定，受益人由被保险人或者投保人指定。投保人指定的，要经被保险人同意。有三种情况，保险金算被保险人的遗产，按继承的规矩给。一是没指定受益人，或者指定得不清楚。二是受益人死在被保险人前面，又没有别的受益人。三是受益人依法丧失或者放弃受益权，又没有别的受益人。受益人和被保险人在同一件事里去世、分不清先后的，推定受益人先死。算作遗产的钱，要先清偿去世的人欠的税和债，剩下的才分。最高法的解释写明：受益人写成「姓名加身份关系」，出事时身份关系变了，算没指定受益人。改受益人没通知保险公司的，对保险公司不生效。领钱的诉讼时效，人寿保险是 5 年，其他保险是 2 年，都从知道或者应当知道出事那天算起。寿险保额通常在数十万元级，收益因此定为大（全国，2015 年修正、2021 年起）', '诉讼时效过了，保险公司可以拒绝给钱，打官司也很难要回来。所以家里人至少要知道你在哪几家公司买过保险。离婚、再婚、孩子出生以后，回头把受益人改一次。人走了以后逐个去取各处的钱，见第 25 节第 9 条（逐个去取）。用死还债这条路走不通，见第 29 节第 13 条（还债）。这条的受益人落在第 ② 档，是你的配偶和孩子。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-45', 'concept_archive_s5-45', 'claim_archive_s5-45', 'action', 'life_archive', '别拿钱买比特币、泰达币这类虚拟货币，别人拉你一起投也不跟：交易不受法律保护，亏了打官司也要不回来', '5. 不要浪费钱', '国内不承认虚拟货币是钱，个人买币的交易可以被判无效，亏了算自己的。有人跟人买泰达币，付了约 44.8 万元，后来平台提不了现，起诉要钱被法院驳回。被人偷走的是另一回事，偷的人照样按盗窃罪判。', '「损失自己承担」管的是你和卖币、带单的人之间的钱款纠纷，法院不帮你把投资款要回来，所以别指望事后起诉。被人偷走、骗走属于刑事案子，照样报警。已经有币的人还要防扫码盗币。江苏涟水有人和对方见面扫了一个码，钱包里约 5.7 万个泰达币被转走。这些币价值约 39.4 万元（精确值 393665.461434 元），人民法院报刊文认为应按盗窃罪处理。美国联邦调查局 2022 年警示过一种类似手法：钱包里弹出一串权限，你点了同意，对方就能不限数额地转走你的币。它给的防法是：拿不准的网站不连钱包，定期用第三方的授权查询工具，看看钱包给过哪些网站转币权限。用自己的银行卡替别人收钱、买币、转币，是另一件事，可能被判刑，见第 9 节第 5 条（「兼职」要你用自己的卡收钱）。承诺高回报的「理财」怎么认，见第 6 条（看到「高收益」「保本」「稳赚」直接走开）。想买海外资产的合法渠道，见第 38 条（买美股走 QDII 基金或港股通）。不构成投资建议。', NULL, NULL, NULL, '不花钱。不买币，不进「带单」「稳赚」的币圈群。代价是币价上涨的时候赚不到。', '2026 年 2 月，人民银行等八个部门发了银发〔2026〕42 号通知。通知写明，比特币、以太币、泰达币这类虚拟货币「不具有法偿性，不应且不能作为货币在市场上流通使用」。人民币换币、币换币、发币融资，都属于非法金融活动，「一律严格禁止」。境外机构也不许给境内的人提供这类服务。个人投资这一头，通知原话是：「任何单位和个人投资虚拟货币、现实世界资产代币及相关金融产品，违背公序良俗的，相关民事法律行为无效，由此引发的损失由其自行承担」。2021 年的银发〔2021〕237 号通知同时废止，这句话在新通知里保留了。法院案例：汤某 2018 年 2 月到 2019 年 7 月，向两个自称平台商户的人买泰达币，付了约 44.8 万元（精确值 448000 元）。后来平台提不了现，也登不上。他起诉要回这笔钱。法院认为用人民币换虚拟货币，这个投资行为无效，损失由他自己承担，驳回了起诉，二审维持（江苏宜兴，2025 年 3 月发布）。被偷是另一回事：有人账户里价值 400 余万元的虚拟币被「黑客」盗走，其中一名盗窃者被以盗窃罪判 7 年，罚 2 万元（河南郑州）', '「损失自己承担」管的是你和卖币、带单的人之间的钱款纠纷，法院不帮你把投资款要回来，所以别指望事后起诉。被人偷走、骗走属于刑事案子，照样报警。已经有币的人还要防扫码盗币。江苏涟水有人和对方见面扫了一个码，钱包里约 5.7 万个泰达币被转走。这些币价值约 39.4 万元（精确值 393665.461434 元），人民法院报刊文认为应按盗窃罪处理。美国联邦调查局 2022 年警示过一种类似手法：钱包里弹出一串权限，你点了同意，对方就能不限数额地转走你的币。它给的防法是：拿不准的网站不连钱包，定期用第三方的授权查询工具，看看钱包给过哪些网站转币权限。用自己的银行卡替别人收钱、买币、转币，是另一件事，可能被判刑，见第 9 节第 5 条（「兼职」要你用自己的卡收钱）。承诺高回报的「理财」怎么认，见第 6 条（看到「高收益」「保本」「稳赚」直接走开）。想买海外资产的合法渠道，见第 38 条（买美股走 QDII 基金或港股通）。不构成投资建议。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s5-46', 'concept_archive_s5-46', 'claim_archive_s5-46', 'action', 'life_archive', '没单位的人自己交职工养老保险，按最低档交、先把年限交够最划算；别当成一交就赚，按最低档也要领约 10 年才回本', '5. 不要浪费钱', '没单位的人自己交职工养老，按最低档交、把年限交够最划算。领的钱大头跟着退休那年当地的平均工资走。按那时的工资水平折算，最低档交 15 年、60 岁开始领，约领 10 年回本，往高档多交的部分要领约 17 年。值得交，但不是一交就赚。', '算例只用来看量级。你实际能领多少，取决于当地平均工资、你交的档次、个人账户的记账利息、哪年退休。退休后养老金会往上调，这一点没算进去，所以实际回本会早一些。延迟退休以后计发月数更少，个人账户每月领得更多。在单位上班的，单位交 16%，你自己交 8%。没单位就没人替你出那 16%，20% 全是自己掏。还没领够就去世的，个人账户余额可以继承，遗属还能领丧葬补助金和抚恤金。每月交不起最低档的，可以先参加城乡居民养老保险，见第 31 节第 11 条（不进单位就是灵活就业）。能不能拿社保补贴，见第 7 节第 12 条（就业困难人员认定）。断缴和补交见第 7 节第 18 条（社保断缴）。换城市以后养老关系怎么转，见第 19 节第 19 条（养老和医保关系转到新参保地）。', NULL, NULL, NULL, '钱全部自己出，按缴费基数的 20% 交，最低档每月也要几百到上千元。要按时交满 15 年以上，2030 年起这个年限逐年往 20 年涨。交满退休之前，这笔钱取不出来。', '怎么交、怎么领，国务院 2005 年的决定写明了。没单位、自己交的人（正式说法是灵活就业人员）按缴费基数的 20% 交，其中 8% 记进个人账户。2019 年起，缴费基数可以自己选。范围是本省全口径城镇单位就业人员平均工资的 60% 到 300%。退休后的养老金分两块。第一块叫基础养老金。把当地上年度在岗职工月平均工资，和你自己的平均缴费工资加起来除以 2，每交满 1 年发 1%。第二块叫个人账户养老金，是账户里的钱除以计发月数。60 岁退休的计发月数是 139，55 岁是 170，退休越晚，月数越少。下面是按公式自己算的例子，不是官方数字。假设退休那年当地月平均工资 8000 元，两种平均工资按同一个数算。下面的金额都按退休那年的工资水平折算，个人账户的利息按刚好跟上工资上涨算。按最低档 60% 交，缴费基数是 4800 元，每月交 960 元。交 15 年共交约 17.3 万元（精确值 172800 元）。60 岁起每月领约 1457 元：基础养老金 960 元，个人账户养老金约 497 元。一年约 1.75 万元（精确值约 17487 元），要领约 9.9 年才回本，也就是领到 70 岁上下。按 100% 档交，15 年共交约 28.8 万元（精确值 288000 元），每月领约 2029 元。比最低档多交的约 11.5 万元（精确值 115200 元），每月只多领约 572 元，要领约 16.8 年才回本。原因是基础养老金有一半按当地平均工资算，和你交多少无关，交得少的人占便宜。按最低档每多交一年，回本年限还是约 9.9 年，比提高档次划算。按最低档交，基础养老金占了领到的钱的大头。这个回本年限和当地工资高低无关。工资高的地方，交的和领的按同一个比例变高，回本年限不变。早年交的钱面额小，退休时却按当时的平均工资发。所以只看交钱和领钱的面额，回本比 9.9 年早。法律规定：退休时累计交满 15 年，才能按月领。不满的，可以接着交满。2030 年 1 月 1 日起，这个最低年限每年提高 6 个月，逐步提高到 20 年。人去世了，个人账户里剩的钱可以继承。国家会根据职工平均工资增长和物价上涨，适时调高养老金。养老保险基金不够发的时候，由政府补贴（全国）', '算例只用来看量级。你实际能领多少，取决于当地平均工资、你交的档次、个人账户的记账利息、哪年退休。退休后养老金会往上调，这一点没算进去，所以实际回本会早一些。延迟退休以后计发月数更少，个人账户每月领得更多。在单位上班的，单位交 16%，你自己交 8%。没单位就没人替你出那 16%，20% 全是自己掏。还没领够就去世的，个人账户余额可以继承，遗属还能领丧葬补助金和抚恤金。每月交不起最低档的，可以先参加城乡居民养老保险，见第 31 节第 11 条（不进单位就是灵活就业）。能不能拿社保补贴，见第 7 节第 12 条（就业困难人员认定）。断缴和补交见第 7 节第 18 条（社保断缴）。换城市以后养老关系怎么转，见第 19 节第 19 条（养老和医保关系转到新参保地）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"5. 不要浪费钱","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-1', 'concept_archive_s6-1', 'claim_archive_s6-1', 'action', 'life_archive', '不要为了长寿或防心血管病吃复合维生素', '6. 反面清单', '1.4 万名男医生吃了十一年复合维生素。心脏和血管出大事的人、死掉的人，和不吃的一样多。把 9 项试验、5 万多人放一起看，对死亡也看不出影响。不买能省下一年两百到七百块。查出来确实缺某种营养的人、孕妇补叶酸，不在这条里面。', '争议：同一批男医生里还看过癌症。吃的人得癌症的比例低约 8%（0.86–0.998，P=0.04，勉强够上「不像碰巧」的线）。因为癌症死掉的比例低约 12%（0.77–1.01）。这个范围跨过了 1，所以可能只是偶然。这点好处很小，而且只在男医生身上看到过。查出来确实缺营养的人、孕妇（补叶酸）、平时吃得实在很偏的人，不算在内，按医生说的补', NULL, NULL, NULL, '一天约 0.5 到 2 元，一年 200 到 700 元。吃它不费时间，一粒的事。吃久了容易产生依赖，觉得哪天没吃就像少做了点什么。', 'PHS II 试验找了 14,641 名男医生，跟踪了 11.2 年（这是中位数，一半人比它长、一半人比它短）。吃的人和不吃的人，心脏血管出大事的比例一样。主要心血管事件 HR 1.01（HR 是风险比，1 就是两边一个样）。95% CI 0.91–1.10 是这个数的可信范围。死亡也一样，全因死亡 HR 0.94（0.88–1.02）。美国给预防措施打分的机构 USPSTF，2022 年把 9 项随机分组的对照试验、51,550 人合起来算，结果是多维片和总死亡没有关联。评级 I，意思是证据不够、说不清。它看起来划算，是因为「一片补齐所有营养」听着顺，而且一天只要几毛钱', '争议：同一批男医生里还看过癌症。吃的人得癌症的比例低约 8%（0.86–0.998，P=0.04，勉强够上「不像碰巧」的线）。因为癌症死掉的比例低约 12%（0.77–1.01）。这个范围跨过了 1，所以可能只是偶然。这点好处很小，而且只在男医生身上看到过。查出来确实缺营养的人、孕妇（补叶酸）、平时吃得实在很偏的人，不算在内，按医生说的补', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-2', 'concept_archive_s6-2', 'claim_archive_s6-2', 'action', 'life_archive', '不要为了预防心血管病吃普通鱼油', '6. 反面清单', '两项大试验分别找了 2.6 万人和 1.5 万名糖尿病患者。每天吃 1 克鱼油的人，心脏血管出大事的、死掉的，都和不吃的一样多。「吃鱼有好处」不等于「吃鱼油胶囊有好处」。不买能省下一年四百到一千块。', '争议：有一项试验是有效的。REDUCE-IT 试验找了 8,179 人，他们本来就有心血管病或糖尿病，都在吃他汀，甘油三酯还偏高（135–499 mg/dL）。他们每天吃 4 g 纯 EPA 的处方药，出事的比例 17.2% 对 22.0%。风险低约四分之一（HR 0.75，0.68–0.83）。但那是给高危病人开的大剂量处方药，不等于普通人吃保健品鱼油。这里说的也不包括吃鱼本身', NULL, NULL, NULL, '一天约 1 到 3 元，一年 400 到 1000 元。吃它不费时间。', 'VITAL 试验找了 25,871 人，每天吃 1 克鱼油，跟踪了 5.3 年（中位数）。心脏血管出大事和死亡，两边都没看出差别。主要心血管事件 HR 0.92（HR 是风险比，1 就是两边一个样）。95% CI 0.80–1.06 是这个数的可信范围。它跨过了 1，说明看不出差别。全因死亡 HR 1.02（0.90–1.15）。ASCEND 试验找了 15,480 名糖尿病患者，也是每天 1 克，平均跟踪 7.4 年，同样没看出差别。严重血管事件 RR 0.97（0.87–1.08）。全因死亡 RR 0.95（0.86–1.05）。它看起来划算，是因为很多人把「吃鱼有好处」直接当成了「吃鱼油胶囊有好处」', '争议：有一项试验是有效的。REDUCE-IT 试验找了 8,179 人，他们本来就有心血管病或糖尿病，都在吃他汀，甘油三酯还偏高（135–499 mg/dL）。他们每天吃 4 g 纯 EPA 的处方药，出事的比例 17.2% 对 22.0%。风险低约四分之一（HR 0.75，0.68–0.83）。但那是给高危病人开的大剂量处方药，不等于普通人吃保健品鱼油。这里说的也不包括吃鱼本身', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-3', 'concept_archive_s6-3', 'claim_archive_s6-3', 'action', 'life_archive', '不要为了长寿给不缺维生素 D 的人补维生素 D', '6. 反面清单', '本来就不缺维 D 的人补上 5 年，得癌症、得心血管病和死亡的人数，都和不补的人一样。查出来确实缺的人、有骨质疏松的人、长期晒不到太阳的人不在这条里面，他们按医生说的补。', '争议：这两项试验都没有特意去招真正缺维生素 D 的人，所以结论只管「本来就不缺的人」。查出确实缺的人、有骨质疏松的人、长期晒不到太阳的人、婴幼儿，还是按医生说的补。这里只看了总死亡和癌症、心脏血管这几件事，别的没看', NULL, NULL, NULL, '一天约 0.2 到 0.5 元，一年 100 到 200 元。钱不算多，真正的代价是以为自己已经做了预防。', 'VITAL 试验找了 25,871 人，每天吃 2000 IU，跟踪了 5.3 年（中位数）。癌症、心脏血管的毛病和死亡都没看出差别。会扩散的那类癌 HR 0.96（HR 是风险比，1 就是两边一个样；95% CI 0.88–1.06 是可信范围）。主要心血管事件 HR 0.97（0.85–1.12）。全因死亡 HR 0.99（0.87–1.12）。D-Health 试验找了 21,315 名 60 岁以上的澳大利亚人。他们每月吃 60,000 IU，跟踪 5 年。这一项也没看出差别，全因死亡 HR 1.04（0.93–1.18）。死亡的比例是 5.3% 对 5.1%。它看起来划算，是因为有些研究只跟踪记录、不做任何干预，发现维 D 水平低的人死得多，这被误读成了「补上就管用」', '争议：这两项试验都没有特意去招真正缺维生素 D 的人，所以结论只管「本来就不缺的人」。查出确实缺的人、有骨质疏松的人、长期晒不到太阳的人、婴幼儿，还是按医生说的补。这里只看了总死亡和癌症、心脏血管这几件事，别的没看', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-4', 'concept_archive_s6-4', 'claim_archive_s6-4', 'action', 'life_archive', '不要为了防癌吃抗氧化补剂（β 胡萝卜素、维生素 E、维生素 A）', '6. 反面清单', '这一条不只是没用。78 项试验、近 30 万人合起来算，吃抗氧化补剂的人死亡率反而略高一点。两项专门找吸烟者做的大试验里，β 胡萝卜素让得肺癌的比例高了 18% 到 28%，死亡高了 8% 到 17%。吸烟的人、接触过石棉的人尤其别吃。', '美国那个负责给预防措施打分的官方机构 USPSTF，2022 年给 β 胡萝卜素和维生素 E 评了 D 级，意思是建议别用。吸烟的人和接触过石棉的人已经因此受了害。蔬菜水果里本身含的抗氧化物不算在内，照吃', NULL, NULL, NULL, '一天约 0.5 到 2 元。对吸烟的人来说，真正的成本是肺癌风险跟着往上走。', 'Cochrane 把 78 项随机分组的对照试验、296,707 人合起来算。吃抗氧化补剂的人，总死亡 RR 1.02（RR 是风险比，1 就是两边一个样；95% CI 0.98–1.05 是可信范围）。只看设计更严谨、不容易跑偏的那批试验，RR 1.04（1.01–1.07），略高一点。单看 β 胡萝卜素 RR 1.05（1.01–1.09），单看维生素 E RR 1.03（1.00–1.05）。ATBC 试验找了 29,133 名男性吸烟者，每天吃 20 mg，得肺癌的比例高 18%（3%–36%），总死亡高 8%（1%–16%）。CARET 试验找了 18,314 名吸烟者或者接触过石棉的人。他们得肺癌的风险高约 28%（RR 1.28，1.04–1.57）。死亡风险高约 17%（全因死亡 RR 1.17，1.03–1.33）。它看起来划算，是因为「抗氧化就是抗衰老，抗衰老就能防癌」这条推理链，每一步听上去都像常识', '美国那个负责给预防措施打分的官方机构 USPSTF，2022 年给 β 胡萝卜素和维生素 E 评了 D 级，意思是建议别用。吸烟的人和接触过石棉的人已经因此受了害。蔬菜水果里本身含的抗氧化物不算在内，照吃', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-5', 'concept_archive_s6-5', 'claim_archive_s6-5', 'action', 'life_archive', '不要指望氨糖（葡萄糖胺）/软骨素治膝关节炎', '6. 反面清单', '膝盖有骨关节炎的人吃 24 周假药，也有六成说没那么疼了。吃氨糖或软骨素的人只比这多出四五个百分点，小到可能只是碰巧。一年花七百到一千八，买到的基本就是那六成的心理作用。', '争议：同一个试验里，一开始就疼得厉害的那批人，两样一起吃的有效比例是 79.2%，对照组 54.3%（P=0.002）。但作者说这是事后从数据里翻出来的，只能当线索，不能当结论。膝关节炎真正有证据的做法是减重和练肌肉，见第 2 节', NULL, NULL, NULL, '一天约 2 到 5 元，一年 700 到 1800 元。', 'GAIT 试验找了 1,583 名膝骨关节炎患者，吃 24 周。吃安慰剂（假药）的人里，也有 60.1% 说疼痛缓解了。氨糖只比它高 3.9 个百分点（P=0.30）。软骨素高 5.3 个百分点（P=0.17）。两样一起吃高 6.5 个百分点（P=0.09）。这几个差距都太小，不能排除只是碰巧。同一个试验里用来做对照的真药塞来昔布，高 10.0 个百分点（P=0.008）。它看起来划算，是因为「补软骨的原料」听起来正好对症，而且光吃假药就有六成人说有效', '争议：同一个试验里，一开始就疼得厉害的那批人，两样一起吃的有效比例是 79.2%，对照组 54.3%（P=0.002）。但作者说这是事后从数据里翻出来的，只能当线索，不能当结论。膝关节炎真正有证据的做法是减重和练肌肉，见第 2 节', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-6', 'concept_archive_s6-6', 'claim_archive_s6-6', 'action', 'life_archive', '不要靠维生素 C 预防感冒', '6. 反面清单', '天天吃维 C 基本不会让你少得感冒，感冒了才开始吃，效果也时有时无。天天吃能把一次感冒缩短约 8%，也就是少难受半天，值不值一年三五百自己算。马拉松选手和在寒冷地区行军的士兵是例外，他们吃了得感冒的人能少一半。', '争议：同一篇综述里，天天吃确实能缩短感冒难受的时间。成人缩短约 8%（3%–12%），儿童缩短 14%（7%–21%）。算下来一次感冒少病半天左右。马拉松运动员、滑雪的人、在寒冷地区行军的士兵是例外。5 项试验、598 人里，得感冒的人少了约一半（RR 0.48，0.35–0.64）。绝大多数人不属于这两类', NULL, NULL, NULL, '泡腾片一片约 1 到 2 元，一年 300 到 700 元。', 'Cochrane 把 29 项对照试验、11,306 人合起来算。普通人天天吃维 C，基本不减少得感冒的次数。得感冒的比例 RR 0.97（RR 是风险比，1 就是两边一个样）。95% CI 0.94–1.00 是可信范围。感冒之后才开始吃的那些试验，原文说「未见一致效应」：有的试验有效，有的没有。同一篇综述里，长期天天吃能把感冒难受的时间缩短约 8%（成人，95% CI 3%–12%），儿童缩短 14%（7%–21%）。马拉松运动员、滑雪的人和在寒冷地区行军的士兵是例外。5 项试验、598 人里，得感冒的人少约一半。发生率 RR 0.48（95% CI 0.35–0.64）。它看起来划算，是因为便宜、酸甜好喝，而且「维 C 防感冒」这个说法已经传了半个世纪', '争议：同一篇综述里，天天吃确实能缩短感冒难受的时间。成人缩短约 8%（3%–12%），儿童缩短 14%（7%–21%）。算下来一次感冒少病半天左右。马拉松运动员、滑雪的人、在寒冷地区行军的士兵是例外。5 项试验、598 人里，得感冒的人少了约一半（RR 0.48，0.35–0.64）。绝大多数人不属于这两类', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-7', 'concept_archive_s6-7', 'claim_archive_s6-7', 'action', 'life_archive', '不要给没有症状的自己做「全身 PET-CT」或「肿瘤标志物套餐」', '6. 反面清单', '没症状的人去查，查出来最多的是虚惊一场。做全身 CT 的人八成多至少查出一处「异常」，将近四成被叫回去复查，可大多数是良性的。女性查卵巢癌标志物，死于卵巢癌的反而略多一点，还有人因为虚惊一场白做了一次手术。', '肿瘤标志物那部分有随机对照试验撑着。全身 CT 和 PET-CT 那部分只有「看做过的人后来怎么样」这类跟踪记录，没有分组对照，证据要弱一档，相当于 B 级。真正有证据的那几项筛查，像结直肠癌、宫颈癌、乳腺癌、高危的人做低剂量胸部 CT，是另一回事，见第 1 节。已经有症状的人，或者已经确诊癌症的人做 PET-CT，那是看病不是筛查，另当别论', NULL, NULL, NULL, '全身 PET-CT 一次约 7000 到 10000 元，还要挨一次电离辐射。肿瘤标志物套餐几百元。真正的成本在后面：查出来一处「异常」，其实是虚惊一场（这叫假阳性），接下来的复查、取组织化验、开刀，钱和罪都在这一段。', '美国那个给预防措施打分的机构 USPSTF，对没有症状的女性用 CA-125 和超声筛查卵巢癌给了 D 级，意思是建议不做。依据是 PLCO 试验。因卵巢癌死亡的比例，筛查组 0.34%、常规组 0.29%。RR 1.18（95% CI 0.82–1.71）。查了没有好处。因为查错了（假阳性）而白挨一刀的比例，各试验里是 0.2%–3.25%，这些人里最多 15% 出现严重的手术并发症。另一项研究给 1,192 名没有症状的人做全身 CT 筛查。其中 86% 至少查出一处「异常」，37% 被建议进一步检查。原文说「大多数发现按描述是良性的」。它看起来划算，是因为「一次查全身、早发现早治疗」太符合直觉', '肿瘤标志物那部分有随机对照试验撑着。全身 CT 和 PET-CT 那部分只有「看做过的人后来怎么样」这类跟踪记录，没有分组对照，证据要弱一档，相当于 B 级。真正有证据的那几项筛查，像结直肠癌、宫颈癌、乳腺癌、高危的人做低剂量胸部 CT，是另一回事，见第 1 节。已经有症状的人，或者已经确诊癌症的人做 PET-CT，那是看病不是筛查，另当别论', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-8', 'concept_archive_s6-8', 'claim_archive_s6-8', 'action', 'life_archive', '不要指望手环/手表的运动量化帮你减重', '6. 反面清单', '超重的人做同样的饮食和运动安排，戴运动手环的人两年减了 3.5 公斤，不戴的人反而减了 5.9 公斤。想减重，花钱买设备帮不上忙，真正管用的是运动本身。', '这只有一项试验，用的还是 2010 年代初戴在胳膊上的设备，不能据此说「所有可穿戴设备都没用」。运动本身是有效的，见第 2 节。结论只有一句：想减重，设备不是必须花的钱', NULL, NULL, NULL, '设备 200 到 2000 元。另外每天还要分神去看那些数据。', 'IDEA 试验找了 471 名超重或肥胖的成年人，跟了 24 个月。大家做的饮食和运动安排是一样的，区别只在戴不戴可穿戴设备。戴的那组减重 3.5 公斤（95% CI 2.6–4.5，这是可信范围）。不戴的那组减了 5.9 公斤（5.0–6.8），反而更多。两组差 2.4 公斤（1.0–3.7，P=0.002）。它看起来划算，是因为「量化才能管理」这句话听着有道理，而且设备买一次就完事', '这只有一项试验，用的还是 2010 年代初戴在胳膊上的设备，不能据此说「所有可穿戴设备都没用」。运动本身是有效的，见第 2 节。结论只有一句：想减重，设备不是必须花的钱', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-9', 'concept_archive_s6-9', 'claim_archive_s6-9', 'action', 'life_archive', '不要为了「更健康」花溢价买有机食品', '6. 反面清单', '没有有力的证据说有机食品更有营养。真正看了人吃完以后健康怎么样的研究只有 3 项，都没看出差别。有机农产品被检出农药残留的比例确实低 30 个百分点，但检出不等于超标。多吃蔬菜水果本身有用，是不是有机的不影响这一点。', '直接看人吃了以后健康怎么样的研究非常少。所以结论是「没有证据说它更好」，不是「已经证明它没好处」。对环境的影响、动物福利、口味好不好，这里不管。多吃蔬菜水果本身有效，是不是有机的不影响这一点', NULL, NULL, NULL, '一般是同类普通食品价格的 1 到 3 倍。', '有一篇系统综述，把 17 项在人身上做的研究和 223 项测食品成分的研究合起来看。结论是「缺乏有力证据表明有机食品比常规食品显著更有营养」。这里面只有 3 项研究看的是人吃了以后健康怎么样（看的是过敏和有症状的感染），两边没看出差别。有机农产品被检出农药残留的比例低 30 个百分点，但检出不等于超标。它看起来划算，是因为「没农药就更安全，更安全就更健康」，每一步听上去都像常识', '直接看人吃了以后健康怎么样的研究非常少。所以结论是「没有证据说它更好」，不是「已经证明它没好处」。对环境的影响、动物福利、口味好不好，这里不管。多吃蔬菜水果本身有效，是不是有机的不影响这一点', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-10', 'concept_archive_s6-10', 'claim_archive_s6-10', 'action', 'life_archive', '不要花大钱买保健品、膏方、滋补品来「调理身体」', '6. 反面清单', '多维、鱼油、维 D 这些常见成分，本节前六条已经一样样查过，都没看出管用。包装上那句「保健食品不是药物，不能代替药物治疗疾病」，是管保健食品的部门规定必须印的。这笔钱多半是买给父母、提着上门的，那份心意没有问题，只是东西选错了。', '结论是「没有证据支持」，不是「已经证明无效」，所以只给 C 级。成分写得明确的产品，按前几条去查对应的研究。查出确实缺营养的人、正在治病的人，按医生说的来。要否掉的是产品，不是心意。老人自己买了、已经在吃的，只要没拿它顶替正在吃的药、也没吃出问题，就不必上门去争这一场，把该打的疫苗和该做的筛查安排上更要紧。同样的钱换成下面这些，每一项在书里都能翻到出处。陪老人去打每年的流感疫苗，见第 1 节第 20 条。50 岁以后的带状疱疹疫苗见第 1 节第 21 条。65 岁以上的肺炎球菌疫苗见第 1 节第 22 条。买个血压计，盯着他把降压药按医嘱吃满、把血压降到达标，见第 1 节第 7 条。把家里的浴室和楼梯改一改，陪他练平衡和腿部力量，见第 1 节第 13 条。到了年纪的癌症筛查，陪他去做一次，见第 1 节第 17 到 19 条。老人已经长期卧床的，压疮防护和长期护理保险见第 17 节第 7、8 条。要提东西上门，换成水果、米面、他爱吃的东西，比膏方实在。真正要拦的是两类：一类是先交钱的投资养老，一类是会顶替掉药的，见第 17 节第 5 条', NULL, NULL, NULL, '从几百元到上万元不等。做成礼品装之后，价钱常常翻好几倍。', '换回的是省下的这笔钱。理由在本节前 6 条：保健品里最常见的几种成分，多维、鱼油、维 D、抗氧化剂、氨糖、维 C，在随机分组对照试验里都没看出预期的好处，各自的数字在那 6 条的收益栏里。监管规定只说明它能宣称什么，不能当成它没用的证据。国家市场监管总局规定，保健食品包装的正面必须用不小于 20% 的面积标上一句话：「保健食品不是药物，不能代替药物治疗疾病」。同一份规定还把保健食品的用途框死在「补充膳食营养物质、维持改善机体健康状态或者降低疾病发生风险因素」这个范围里。它看起来划算，是因为「不治病，只调理」这句话怎么说都不算错，谁也没办法证明它是假的。而且送礼时掏这笔钱，靠的是人情，不是证据', '结论是「没有证据支持」，不是「已经证明无效」，所以只给 C 级。成分写得明确的产品，按前几条去查对应的研究。查出确实缺营养的人、正在治病的人，按医生说的来。要否掉的是产品，不是心意。老人自己买了、已经在吃的，只要没拿它顶替正在吃的药、也没吃出问题，就不必上门去争这一场，把该打的疫苗和该做的筛查安排上更要紧。同样的钱换成下面这些，每一项在书里都能翻到出处。陪老人去打每年的流感疫苗，见第 1 节第 20 条。50 岁以后的带状疱疹疫苗见第 1 节第 21 条。65 岁以上的肺炎球菌疫苗见第 1 节第 22 条。买个血压计，盯着他把降压药按医嘱吃满、把血压降到达标，见第 1 节第 7 条。把家里的浴室和楼梯改一改，陪他练平衡和腿部力量，见第 1 节第 13 条。到了年纪的癌症筛查，陪他去做一次，见第 1 节第 17 到 19 条。老人已经长期卧床的，压疮防护和长期护理保险见第 17 节第 7、8 条。要提东西上门，换成水果、米面、他爱吃的东西，比膏方实在。真正要拦的是两类：一类是先交钱的投资养老，一类是会顶替掉药的，见第 17 节第 5 条', '极高', 'C', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-11', 'concept_archive_s6-11', 'claim_archive_s6-11', 'action', 'life_archive', '不要在没有肠道问题时长期吃益生菌', '6. 反面清单', '45 项在健康成年人身上做的试验合起来看，吃益生菌不能让肠道里的菌长期变个样，停了就回到原样，血脂也没有改善。吃抗生素吃出腹泻这类特定情况另有证据，不在这条里面。', '同一篇综述也说健康人身上有一些小的改善，比如大便更成形、软硬合适，女性阴道里的乳杆菌变多。吃抗生素引起的腹泻，以及某一个特定菌株用在某一种特定的病上，各自有单独的证据，另当别论。这里只针对健康人每天当保健品吃', NULL, NULL, NULL, '一天约 2 到 5 元，一年 700 到 1800 元。', '一篇综述把 45 项在健康成年人身上做的试验合起来看，结论是「未能支持益生菌能引起肠道菌群的持久改变，也未能改善健康成人的血脂」。肠道里的菌确实会变，但只是暂时的，停了就回去。它看起来划算，是因为「肠道健康」这个说法足够宽、怎么套都不算错，而且每天一瓶单价很低', '同一篇综述也说健康人身上有一些小的改善，比如大便更成形、软硬合适，女性阴道里的乳杆菌变多。吃抗生素引起的腹泻，以及某一个特定菌株用在某一种特定的病上，各自有单独的证据，另当别论。这里只针对健康人每天当保健品吃', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-12', 'concept_archive_s6-12', 'claim_archive_s6-12', 'action', 'life_archive', '不要为了「增强免疫力」逼自己洗冷水澡', '6. 反面清单', '3018 人的试验里，洗冷水澡的人请病假的次数少了 29%，但请假的总天数和别人一样，所以谈不上少生病。2025 年把 11 项试验合起来看，冲完冷水之后，身体发炎的指标反而短暂升高，免疫的指标没变化。爱洗随便洗，只是别把它当成一笔健康投资。', '争议：请病假的次数确实少了 29%，这个差距不像是碰巧。但生病的总天数并没有少，所以更像是「病了也照常去上班」，而不是真的少生病。运动员训练完之后用冷水帮助恢复，那是另一个问题，这里不管。冷水澡本身对健康人没有害处，只是别把它当成健康投资', NULL, NULL, NULL, '不花钱。每天要难受 30 到 90 秒，冬天想坚持得靠毅力。有心血管病的人还要当心，冷刺激对他们有风险。', '荷兰做过一项随机分组对照试验，3,018 人，洗完热水澡之后再冲 30 秒、60 秒或 90 秒冷水。这些人请病假的次数少了 29%（IRR 0.71，这是次数之比）。但原文写明「病假天数没有显著组间差异」：总共病了多少天，两边一样。生活质量、工作效率、焦虑也都没看出有意义的差别。2025 年一篇系统综述把 11 项随机分组试验、3,177 人合起来算。泡完冷水的当下和 1 小时后，身体发炎的指标反而升高。免疫指标没变化。压力只在 12 小时那个时间点降低。作者自己说证据「受限于 RCT 少、样本小」，意思是这类随机分组试验数量太少、每项人也不多。它看起来划算，是因为不花钱，而且「吃苦就有效」这个直觉太顺', '争议：请病假的次数确实少了 29%，这个差距不像是碰巧。但生病的总天数并没有少，所以更像是「病了也照常去上班」，而不是真的少生病。运动员训练完之后用冷水帮助恢复，那是另一个问题，这里不管。冷水澡本身对健康人没有害处，只是别把它当成健康投资', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-13', 'concept_archive_s6-13', 'claim_archive_s6-13', 'action', 'life_archive', '不要买排毒、清肠、酵素、碱性水这类产品', '6. 反面清单', '排毒这个产业做得很大，可支持它的临床证据非常少，也没人拿市面上卖的排毒饮食认真做过试验。有人去查饮食酸碱、碱性水和癌症有没有关系，够格的研究只找到 1 篇，也没看出关联。', '只能说「没有证据支持」，所以只给 C 级。把身体代谢产生的废物清出去，本来就是肝和肾在干的活。只要这两个器官没有生病，就不需要额外做什么「排毒」', NULL, NULL, NULL, '几百到几千元。靠饿肚子来「排毒」的那种，还可能把血糖饿低、把营养搞缺。', '那篇综述的结论是「尽管排毒产业蓬勃发展，支持这些饮食的临床证据非常少」，而且「没有针对商业排毒饮食的随机对照试验」。另一篇系统综述专门查饮食的酸碱、碱性水和癌症有没有关系：翻了 8,278 篇文献，只有 1 篇够格收进来，结果也没看出关联。作者写的是「向公众推广碱性饮食和碱性水用于癌症预防或治疗是不合理的」。它看起来划算，是因为「身体里有毒素要排出来」「体质发酸会致癌」这两个前提听上去很像生理学', '只能说「没有证据支持」，所以只给 C 级。把身体代谢产生的废物清出去，本来就是肝和肾在干的活。只要这两个器官没有生病，就不需要额外做什么「排毒」', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-14', 'concept_archive_s6-14', 'claim_archive_s6-14', 'action', 'life_archive', '不要为了凑够「每天 8 杯水」强迫自己喝水', '6. 反面清单', '有人专门去追「每天 8 杯水」的出处，一项支持它的研究都没找到。食物和别的饮料里本来就带着大量水分，所以用不着喝那么多。渴了就喝，看看尿的颜色就够了。天热干活、剧烈运动、得过肾结石的人，还有不太觉得渴的老人，要另外主动喝。', '要否掉的是「每天必须喝够几杯」这个数字，不是说多喝水有害。渴了就喝，看看尿的颜色，这样就够了。在高温下干活的人、剧烈运动的人、得过肾结石的人，以及上年纪之后不太觉得渴的人要主动喝，另当别论', NULL, NULL, NULL, '不花钱。要花一点时间和精力去记着喝，晚上起夜也会变多。', '有一篇文献回顾专门查「8×8」这个说法，指的是每天 8 杯、每杯 8 盎司水。它的结论是「未找到任何支持 8×8 的科学研究」。它还写道，「对数千名成年人的食物与液体摄入调查强烈提示不需要如此大量」，因为食物和其他饮品已经提供了大量水分。这个说法看起来划算，是因为水不要钱、8 这个数字又整齐，而且「多喝水」这话在任何场合说出来都显得没坏处', '要否掉的是「每天必须喝够几杯」这个数字，不是说多喝水有害。渴了就喝，看看尿的颜色，这样就够了。在高温下干活的人、剧烈运动的人、得过肾结石的人，以及上年纪之后不太觉得渴的人要主动喝，另当别论', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-15', 'concept_archive_s6-15', 'claim_archive_s6-15', 'action', 'life_archive', '不要花钱算命、看塔罗、看星座来做决定', '6. 反面清单', '有个经典的课堂实验：学生拿到的「个人性格分析」其实人手一份、一模一样，大家却普遍觉得很准。算命显得准，道理就在这里。占星师挑对的次数和瞎猜差不多。代价不只几十块：河南息县那个算命团伙，收香火钱和最高 3888 元的「供养套餐」，主犯判了十一年。', '这两篇都只是单独的一项研究。Forer 那篇原文没有直接写平均分，4.26 是按原文表 1 的分布算出来的。这里只说「它预测不准」，不评价任何信仰。当娱乐花几十块钱不算在内，拿它来定辞职、结婚、投资才是亏钱的地方。', NULL, NULL, NULL, '不花钱。难的是放弃一条拿主意的捷径，以后得自己想。', '经典课堂实验：学生做完性格测验后拿到的「个人分析」其实人人都一样，却普遍认为很准。作者的结论是「被本人或分析者接受，不能证明解释正确」。39 个学生按 0 到 5 分给这份分析打准确度分，34 人打了 4 分或 5 分，按表里的分布算平均约 4.26 分。这就解释了算命为什么总显得准，这个现象叫巴纳姆效应。占星术也做过双盲检验，结果发表在 Nature 上。占星师要从三份性格测验结果里挑出和星盘对得上的那一份。116 份里挑中 40 份，纯靠瞎猜也能挑中 38.5 份，占星师事先自己预计能挑中 58.5 份。官方案例：河南息县检察院通报过一个网络算命诈骗团伙，先用免费看手相把人引进来，再收「香火钱」和最高 3888 元的「供养套餐」。被害人 50 余人，追回赃款 200 余万元，主犯判有期徒刑十一年，并处罚金 10 万元', '这两篇都只是单独的一项研究。Forer 那篇原文没有直接写平均分，4.26 是按原文表 1 的分布算出来的。这里只说「它预测不准」，不评价任何信仰。当娱乐花几十块钱不算在内，拿它来定辞职、结婚、投资才是亏钱的地方。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-16', 'concept_archive_s6-16', 'claim_archive_s6-16', 'action', 'life_archive', '不要买防蓝光眼镜来「保护视力」，也不要相信「对着屏幕干几个月眼睛就废了」，但眼睛胀痛发红要当急症', '6. 反面清单', '防蓝光镜片没用，不买能省下几百到上千的加价。和普通镜片比，戴它的人眼睛累不累、能看多清都没差别，也没找到它护眼底的证据。看屏幕看得眼酸眼干能缓过来，真正会把眼睛伤坏的是电焊弧光、紫外线、激光，还有青光眼急性发作。', '看屏幕带来的是视疲劳和干眼，表现是眼酸、发干、看久了发糊。休息一下、多眨眼就能缓解。它是能缓过来的，不等于「把眼睛看坏了」。这句话是眼科的共识，不是来源栏那篇 Cochrane 综述的结论，所以只算 C 级。真正会在短时间里造成不可逆眼损伤的，是电焊弧光、紫外线、激光这类强光源。被电焊弧光伤到眼睛叫「电光性眼炎」，是法定的职业病。挡它靠的是护目镜和面罩，不是防蓝光镜片，见第 19 节第 10 条（粉尘噪声化学毒物的防护）。熬夜通宵盯着屏幕要防的不是屏幕本身，是一个例外：眼睛胀痛发红、看灯有一圈彩虹、还头痛恶心呕吐，那是急性闭角型青光眼发作，几天之内就能把视神经压坏，当天就要去眼科急诊，见第 13 节第 6 条（眼科急诊）。暗处瞳孔散大、长时间低头又把晶状体往前顶，这两件事是它的诱因，高危的是 50 岁以上、远视、前房浅的人。屏幕带来的干眼拖久了也会变成要看医生的慢性病，不是睡一觉就没了。眼睛一直不舒服，或者视力真的在往下掉，去眼科查清原因，别自己换个镜片就算完。儿童青少年怎么防近视，见第 30 节第 4、12、9 条（每天户外 2 小时、散瞳验光、不买「治愈近视」的产品）。', NULL, NULL, NULL, '不花钱，还能省下镜片上那几百到上千元的加价。', 'Cochrane 2023 年的系统综述收了 17 项随机分组的对照试验，每项 5 到 156 人，跟踪时间从不到 1 天到 5 周不等。因为数据太少、各项试验招的人差别大、跟踪时间又不一致，作者没有把它们合起来算一个总数。下面的结果都是和不带蓝光过滤的镜片相比。跟踪不到一周时，自己报告的眼疲劳程度「可能没有差别」，证据确定性低。其中一项 120 人的试验，两组相差 9.76 个单位。这个差值的可信范围是 95% CI −33.95 到 53.47。范围横跨正负，说明看不出差别。临界闪烁融合频率是一项衡量眼睛疲劳的客观指标，两组「可能几乎没有差别」，确定性低。配上眼镜矫正之后能看到的最好视力「大概没有影响」。两组相差 0.00 logMAR（95% CI −0.02 到 0.02）。这一项只有 1 项研究、156 人，确定性中等。对白天清醒程度有没有影响说不清（2 项试验、42 人，确定性极低）。这篇综述也没有找到支持它保护眼底黄斑的证据', '看屏幕带来的是视疲劳和干眼，表现是眼酸、发干、看久了发糊。休息一下、多眨眼就能缓解。它是能缓过来的，不等于「把眼睛看坏了」。这句话是眼科的共识，不是来源栏那篇 Cochrane 综述的结论，所以只算 C 级。真正会在短时间里造成不可逆眼损伤的，是电焊弧光、紫外线、激光这类强光源。被电焊弧光伤到眼睛叫「电光性眼炎」，是法定的职业病。挡它靠的是护目镜和面罩，不是防蓝光镜片，见第 19 节第 10 条（粉尘噪声化学毒物的防护）。熬夜通宵盯着屏幕要防的不是屏幕本身，是一个例外：眼睛胀痛发红、看灯有一圈彩虹、还头痛恶心呕吐，那是急性闭角型青光眼发作，几天之内就能把视神经压坏，当天就要去眼科急诊，见第 13 节第 6 条（眼科急诊）。暗处瞳孔散大、长时间低头又把晶状体往前顶，这两件事是它的诱因，高危的是 50 岁以上、远视、前房浅的人。屏幕带来的干眼拖久了也会变成要看医生的慢性病，不是睡一觉就没了。眼睛一直不舒服，或者视力真的在往下掉，去眼科查清原因，别自己换个镜片就算完。儿童青少年怎么防近视，见第 30 节第 4、12、9 条（每天户外 2 小时、散瞳验光、不买「治愈近视」的产品）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-17', 'concept_archive_s6-17', 'claim_archive_s6-17', 'action', 'life_archive', '不要把献血当保健：「排毒、降血脂、防心梗」没有随机试验支持，频繁献倒是真会缺铁', '6. 反面清单', '说献血能排毒、降血脂、防心梗，靠不住。能一直去献血的人，本来身体就更好，把这层扣掉，每年多献一次血的死亡率降幅从近两成缩到 7.5%。真正把人分开对比的试验里，死亡人数没有差别。反过来，献得太勤确实会让人没力气、怕冷，原因是缺铁。', '要否掉的是「为了自己的身体去献血」，不是献血这件事本身。血是给别人用的，按本书的受益人分档落在第④档（陌生人）。真正能回到你自己这边的，是制度给的那一份。《献血法》第十四条规定，无偿献血的人自己在医院用血，采集、储存、分离、检验这几笔费用都免交，配偶和直系亲属可以按省级政府的规定免交或者少交。国家卫健委 2024 年 1 月的通知写明，28 个省份已经做到无偿献血者和亲属在省内医院用血的费用出院时直接减免。拿到无偿献血奉献奖的人，还可以按当地的「三免」政策免费坐公共交通、免费逛政府投资主办的公园、免交公立医院的普通门诊诊察费。要献就按法定间隔来。《献血法》第九条规定，每次一般 200 毫升，最多不超过 400 毫升。两次之间间隔不少于 6 个月。提倡的年龄是 18 至 55 周岁。别为了凑荣誉或者团体指标，把间隔压到最短。女性、体重偏低的人、月经量多的人，身体里的铁本来就紧张，反复献血的人可以自费查一次铁蛋白。献完之后如果一直乏力、怕冷，或者晚上躺下腿里难受得忍不住要动（这叫不宁腿），别自己猜是「元气伤了」，去查血常规和铁蛋白。查出缺铁就按医生说的补铁，同时把献血间隔拉长。怕冷那一段的人体证据只有 10 个人，用来解释为什么会这样，不是说有多少人会这样', NULL, NULL, NULL, '不花钱。一次献血，填表、采血加上留下观察休息，大约要一小时。之后几周，身体一直在把丢掉的铁补回来。', '芬兰 Kuopio 研究跟踪了 2862 名 42 至 60 岁的男性，平均将近 9 年。开始统计之前的 24 个月里献过血的有 153 人，其中 1 人（0.7%）发生了急性心梗。没献过的 2529 人里有 316 人（12.5%）发生（两个比例的差异 P&lt;0.0001）。把年龄和其他冠心病危险因素的影响扣掉之后，献过血的人心梗风险低约 88%。相对风险 0.12（95% CI 0.02–0.86，P=0.035）。但这只是跟踪记录出来的，没有分组对照。北欧 SCANDAT 数据库里有 1,182,495 名献血者，累计跟踪 9,526,627 人年，其中 15,401 人死亡。只扣掉年龄性别这类特征时，每年多献一次血，死亡率低 18.6%（95% CI 16.8%–20.4%）。再把「一直健康才一直被允许献血」这一层也扣掉，降幅只剩 7.5%（5.7%–9.4%）。作者的结论是「不能解释为有益健康的确凿证据」。FeAST 随机分组对照试验找了 1277 名有症状的下肢动脉疾病患者，随机分成两组，一组每 6 个月定期放血减铁，一组做对照。主要看的是全因死亡，125/636（20%）对 148/641（23%）。HR 0.85（HR 是风险比，1 就是两边一个样）。95% CI 0.67–1.08，P=0.17。死亡加上没死的心梗与卒中合起来算，是 180（28%）对 205（32%），HR 0.88（0.72–1.07，P=0.20）。两项都没看出差别。INTERVAL 随机分组试验找了 45,263 名献全血的人。这些人分成三种献血间隔。男性是 12 周、10 周、8 周，女性是 16 周、14 周、12 周。间隔缩短之后，两年内采到的血明显更多（男性 8 周组比 12 周组多 1.69 单位，95% CI 1.59–1.80）。生活质量、体力活动、认知功能各组都没看出差别。但献血带来的不适更多，包括乏力、气短、眩晕、头晕和不宁腿（夜里腿难受得躺不住）。同时血红蛋白与铁蛋白的平均值更低，因为血红蛋白低而被推迟献血的次数也更多（各项 P&lt;0.0001）。缺铁会影响身体产热：10 名缺铁性贫血的女性、8 名铁储备已经耗光但还没贫血的人、12 名对照女性，在 28 ℃ 的水里泡 100 分钟。贫血那组直肠温度 36.0±0.2 ℃，对照组 36.2±0.1 ℃（P=0.001）。耗氧量 5.28±0.26 对 5.99±0.29 mL·min⁻¹·kg⁻¹（P=0.04）。甲状腺素和三碘甲状腺原氨酸这两种甲状腺激素也更低（P&lt;0.002）。这个说法看起来成立，是因为献血的人本来就是被反复筛查过的健康人，而「把铁放掉就能护心」这个假说在随机试验里没验出来', '要否掉的是「为了自己的身体去献血」，不是献血这件事本身。血是给别人用的，按本书的受益人分档落在第④档（陌生人）。真正能回到你自己这边的，是制度给的那一份。《献血法》第十四条规定，无偿献血的人自己在医院用血，采集、储存、分离、检验这几笔费用都免交，配偶和直系亲属可以按省级政府的规定免交或者少交。国家卫健委 2024 年 1 月的通知写明，28 个省份已经做到无偿献血者和亲属在省内医院用血的费用出院时直接减免。拿到无偿献血奉献奖的人，还可以按当地的「三免」政策免费坐公共交通、免费逛政府投资主办的公园、免交公立医院的普通门诊诊察费。要献就按法定间隔来。《献血法》第九条规定，每次一般 200 毫升，最多不超过 400 毫升。两次之间间隔不少于 6 个月。提倡的年龄是 18 至 55 周岁。别为了凑荣誉或者团体指标，把间隔压到最短。女性、体重偏低的人、月经量多的人，身体里的铁本来就紧张，反复献血的人可以自费查一次铁蛋白。献完之后如果一直乏力、怕冷，或者晚上躺下腿里难受得忍不住要动（这叫不宁腿），别自己猜是「元气伤了」，去查血常规和铁蛋白。查出缺铁就按医生说的补铁，同时把献血间隔拉长。怕冷那一段的人体证据只有 10 个人，用来解释为什么会这样，不是说有多少人会这样', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-18', 'concept_archive_s6-18', 'claim_archive_s6-18', 'action', 'life_archive', '不要靠通用体检套餐防病，按年龄性别做那几项有证据的筛查', '6. 反面清单', '定期做通用健康检查的人，和不做的人死亡率一样，死于心血管病、癌症的也一样多。按年龄性别做那几项有证据的筛查就够了。35 岁以上每年能免费量一次血压，65 岁以上每年有一次免费体检。', '要否掉的是「拿年度套餐当防病手段」，不是说所有检查都别做。另外，35 岁以上每年免费测一次血压、65 岁以上每年一次免费体检，本来就是国家基本公共卫生服务项目给的，不用自己掏钱。有理由该查的项目照查。血压、血糖、乙肝见第 1 节第 7、8、14 条。乳腺、宫颈、结直肠见第 1 节第 17、18、19 条。幽门螺杆菌和低剂量 CT 见第 1 节第 23、24 条。65 岁以上女性的骨密度检查，见第 1 节第 39 条（骨密度检查）。有过高危行为就去查，见第 1 节第 31 条。从几岁开始查、隔多久查一次都写在那里。单位组织的、别人付钱的体检照去，要拦的是自己花钱买套餐和自己加项目。已经有慢性病的人、有症状的人，或者医生按病情开的检查，不算在内，那是看病不是筛查。套餐里最常见的没有证据的项目是肿瘤标志物和全身影像，见本节第 7 条（全身 PET-CT 和肿瘤标志物套餐）。查出来尿酸高但从没痛过、胆囊结石但从没疼过怎么办，见本节第 19 条（无症状的尿酸高）和第 20 条（无症状的胆囊结石）。另外，Cochrane 收进来的试验多数是在高收入国家做的，那里本来看病就方便，医疗资源紧张的地区不宜直接照搬这个结论。', NULL, NULL, NULL, '不花钱，还省下每年几百到几千元的套餐费。换来的义务是自己记住该查哪几项、各隔多久查一次。', 'Cochrane 系统综述 2019 年更新版收了 17 项随机分组的对照试验。算总死亡率时，合并了其中 11 项试验、233,298 名参与者、21,535 例死亡。做通用健康检查的那组和对照组一样，RR 1.00。RR 是风险比，1 就是两边一个样。95% CI 0.97–1.03 是可信范围。算因心血管病死亡时，合并 9 项试验、170,227 人、6,237 例死亡，RR 1.05（95% CI 0.94–1.16）。算因癌症死亡时，合并 8 项试验、139,290 人、3,663 例死亡，RR 1.01（95% CI 0.92–1.12）。这两项也都没看出差别。作者的结论是「通用健康检查不大可能有益」。国家基本公共卫生服务项目给 35 岁及以上的常住居民每年免费测量一次血压，给 65 岁及以上的老年人每年免费提供一次健康体检。这次免费体检包含体格检查、血常规、尿常规、空腹血糖和心电图。肝功能查谷草转氨酶、谷丙转氨酶、总胆红素。肾功能查血清肌酐、血尿素。血脂查总胆固醇、甘油三酯、低密度脂蛋白胆固醇、高密度脂蛋白胆固醇。最后还有肝胆胰脾的腹部 B 超（全国）', '要否掉的是「拿年度套餐当防病手段」，不是说所有检查都别做。另外，35 岁以上每年免费测一次血压、65 岁以上每年一次免费体检，本来就是国家基本公共卫生服务项目给的，不用自己掏钱。有理由该查的项目照查。血压、血糖、乙肝见第 1 节第 7、8、14 条。乳腺、宫颈、结直肠见第 1 节第 17、18、19 条。幽门螺杆菌和低剂量 CT 见第 1 节第 23、24 条。65 岁以上女性的骨密度检查，见第 1 节第 39 条（骨密度检查）。有过高危行为就去查，见第 1 节第 31 条。从几岁开始查、隔多久查一次都写在那里。单位组织的、别人付钱的体检照去，要拦的是自己花钱买套餐和自己加项目。已经有慢性病的人、有症状的人，或者医生按病情开的检查，不算在内，那是看病不是筛查。套餐里最常见的没有证据的项目是肿瘤标志物和全身影像，见本节第 7 条（全身 PET-CT 和肿瘤标志物套餐）。查出来尿酸高但从没痛过、胆囊结石但从没疼过怎么办，见本节第 19 条（无症状的尿酸高）和第 20 条（无症状的胆囊结石）。另外，Cochrane 收进来的试验多数是在高收入国家做的，那里本来看病就方便，医疗资源紧张的地区不宜直接照搬这个结论。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-19', 'concept_archive_s6-19', 'claim_archive_s6-19', 'action', 'life_archive', '不要因为体检查出尿酸高、但从没痛过，就开始吃降尿酸药', '6. 反面清单', '尿酸超标、但从没发作过痛风也没长痛风石的人，美国风湿病学会建议先不吃降尿酸药。24 个人吃满 3 年，才拦得住一次痛风发作。想靠它护肾也落空了，吃药的人肾功能照样往下掉，和吃假药的一样快。真发作过了再治。', '要否掉的是「从没发作过就开始终身吃降尿酸药」，不是说尿酸高无所谓。同一份指南也列了例外。下面这几种情况可以考虑开始吃。一是第一次发作的同时还有 3 期及以上的慢性肾病。二是血尿酸 &gt;9 mg/dL（约 535 µmol/L）。三是长过尿路结石。已经发作过的人、长了痛风石的人、片子上看到骨头已经被侵蚀的人，该吃药。具体见第 16 节第 9 条（确诊痛风就长期吃降尿酸药）。汉族人里约 7.4% 的人带一个叫 HLA-B*5801 的基因型，白人只有 0.7%。带这个型的人吃别嘌醇，更容易起会要命的严重药疹，亚裔出现超敏综合征的风险是白人的 3 倍。这本来就是可以先不吃的药，没必要多冒这一次风险。真要开始吃之前，先去查这个基因型，见第 16 节第 9 条（确诊痛风就长期吃降尿酸药）。那两项肾脏试验做的是慢性肾病和 1 型糖尿病的病人，不能直接推广成「高尿酸对肾完全无害」。它们否掉的只是「吃药降尿酸能护肾」这一个做法', NULL, NULL, NULL, '不花钱，还省下长期的药费和定期复查的钱，也免掉一次没必要的用药风险。', '美国风湿病学会 2020 年的痛风指南讲到无症状高尿酸血症。它指的是血尿酸 &gt;6.8 mg/dL，而且以前没发作过痛风、皮下也没长痛风石。指南有条件地建议这些人不要开始吃任何降尿酸药。药包括别嘌醇、非布司他、丙磺舒。证据确定性评为「高」。表下面的脚注写明「按归因风险计算，需治疗 24 名患者 3 年才能预防一次痛风发作」。CKD-FIX 随机分组对照试验找了 363 人。他们是 3 期或 4 期慢性肾病，没有痛风史但有恶化风险。一组每天吃 100–300 mg 别嘌醇，一组吃安慰剂。试验做了 104 周。eGFR 是反映肾功能的指标，单位是 mL/min/1.73 m²。一组每年变化 -3.33（95% CI -4.11 到 -2.55）。另一组每年变化 -3.23（-3.98 到 -2.47）。两组相差 -0.10（-1.18 到 0.97），P=0.85，肾功能下降的速度一样快。严重不良事件 46% 对 44%。PERL 随机分组对照试验找了 530 名 1 型糖尿病合并早中期糖尿病肾病的人，吃 3 年别嘌醇，再停药 2 个月把药效洗掉。别嘌醇确实把血尿酸从 6.1 降到了 3.9 mg/dL。但停药之后，两组的肾功能指标 GFR 只差 0.001 mL/min/1.73 m²。这个差值的可信范围是 95% CI -1.9 到 1.9，P=0.99。尿里漏出的白蛋白，在吃别嘌醇那组反而高 40%（0 到 80）。它看起来划算，是因为「指标超标就该吃药压下去」这个直觉太顺', '要否掉的是「从没发作过就开始终身吃降尿酸药」，不是说尿酸高无所谓。同一份指南也列了例外。下面这几种情况可以考虑开始吃。一是第一次发作的同时还有 3 期及以上的慢性肾病。二是血尿酸 &gt;9 mg/dL（约 535 µmol/L）。三是长过尿路结石。已经发作过的人、长了痛风石的人、片子上看到骨头已经被侵蚀的人，该吃药。具体见第 16 节第 9 条（确诊痛风就长期吃降尿酸药）。汉族人里约 7.4% 的人带一个叫 HLA-B*5801 的基因型，白人只有 0.7%。带这个型的人吃别嘌醇，更容易起会要命的严重药疹，亚裔出现超敏综合征的风险是白人的 3 倍。这本来就是可以先不吃的药，没必要多冒这一次风险。真要开始吃之前，先去查这个基因型，见第 16 节第 9 条（确诊痛风就长期吃降尿酸药）。那两项肾脏试验做的是慢性肾病和 1 型糖尿病的病人，不能直接推广成「高尿酸对肾完全无害」。它们否掉的只是「吃药降尿酸能护肾」这一个做法', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-20', 'concept_archive_s6-20', 'claim_archive_s6-20', 'action', 'life_archive', '不要因为体检查出胆囊结石、但从没疼过，就去预防性切胆囊', '6. 反面清单', '胆囊里有石头、但从没疼过的人，近九年里约八成一直没出症状。不动它，每年出胆囊炎、胰腺炎这类急症的约千分之一到千分之三。切胆囊也不是零风险，约 1.5% 的人胆管会被伤到。所以欧洲和英国的指南都说，没症状先不切。', '争议。国内胆道外科 2021 版的专家共识，把一部分无症状胆囊结石列进了手术指征。同一本杂志的解读文章写明，争议的核心之一就在这里。共识全文要订阅，具体是哪几种情形没核到原文（TODO：待核实）。另一处反方意见是小石头：5 毫米以内的小结石和胰腺炎更相关。荷兰一项测算说，这类人预防性切除可能多活也可能少活，取决于胰腺炎有多常见、有多致命。欧洲指南也列了例外：胆囊壁钙化（瓷化胆囊）、同时有 1 厘米以上的胆囊息肉，这两种该切。要做别的腹部大手术时，可以考虑顺带切掉。这条说的只是一种情形：石头长在胆囊里，而且从来没疼过。胆总管里的石头是另一回事。同一份指南第 1.3.1 条明确写着，胆总管结石不管有没有症状，都要把胆管里的石头清掉，并且切除胆囊。出现下面这些情况要当天就去医院，别拿这个结论硬扛：右上腹或者上腹一直绞痛、发热打寒战、眼白或皮肤发黄、小便颜色变深。医生看过影像之后建议手术时，问清楚他是基于哪一条理由，比如胆管受了累、同时长了息肉、胆囊壁有异常，别拿这个结论去反驳他。它挡的只是「没有任何理由、单纯因为查出石头就切」。上面两项研究都是跟着一群人往后看，没有分组对照。但它们要回答的是「不去动它会怎么样」，而不是「哪种治疗更好」，用在这里合适。另外这两项跟踪的年头是 4 到 9 年，年头再长一些，出症状的比例会往上走', NULL, NULL, NULL, '不花钱，还省下一次全身麻醉的手术和一次住院。换来的义务是记住哪几个信号一出现就得马上去医院。', '意大利 MICOL 人群普查给 11,229 名 29 至 69 岁的人做了超声。查出 856 人有胆结石，其中 580 人没有症状，平均跟踪 8.7 年。这 580 人里，453 人（78.1%）一直没症状，61 人（10.5%）出现轻症状，66 人（11.4%）出现重症状。跟踪期内一共做了 189 例胆囊切除，其中 41.3% 做在没有症状的人身上。作者的结论是「期待治疗对多数患者仍是有效的处理方式」，期待治疗的意思是先观察、不动手术。美国一家 HMO 做过跟踪统计，HMO 是一种管理式医疗机构，691 名确诊胆结石的人，平均跟踪 78±61.6 个月。其中 135 名没有症状的人跟踪了 58±50.2 个月（中位数 46.3 个月），只有 10% 出现了胆结石的症状，7% 接受了手术。全组 50 例死亡里只有 2 例和胆道有关，而且都在有症状的那一组。作者的结论是「有无声结石的患者不需要在出现症状前手术」，无声结石就是不吭声、不发作的石头。英国 NICE 指南 CG188 第 1.2.1 条是这么写的。「对胆囊和胆道均正常、偶然发现无症状胆囊结石的人，应告知其在出现症状前不需要治疗」。欧洲肝病学会 2016 年的胆结石指南把两边的风险放在一起写。没症状的人每年约 0.7% 到 2.5% 出现症状。每年出急性胆囊炎、急性胰腺炎、梗阻性黄疸（胆道堵住、人发黄）或胆管炎的，是 0.1% 到 0.3%。第一次绞痛之后，并发症才升到每年 1% 到 3%，所以多数人出大事前会先疼一次。手术这边，瑞典全国登记的 51041 例胆囊切除里，1.5% 伤到了胆管。其中约五分之一（0.3%）是胆管部分或完全断开。伤到胆管的人一年内死亡率 3.9%，没伤到的是 1.1%。指南还写，切完以后有 10% 到 40% 的病人仍有不适，或者好了一阵又回来。指南的结论是：没症状的人做手术，不管开腹还是腹腔镜，都不延长寿命，因为手术本身的死亡和并发症风险超过了不切的风险。等出了症状再处理，总花费也更低。1983 年的一项测算给过具体数：30 岁男性预防性切除，比先观察平均少活 4 天，50 岁少活 18 天。切和不切，至今没有一项随机分组的试验比较过。预防性切除看起来划算，是因为「早晚要疼，不如趁年轻一次切了」这个直觉', '争议。国内胆道外科 2021 版的专家共识，把一部分无症状胆囊结石列进了手术指征。同一本杂志的解读文章写明，争议的核心之一就在这里。共识全文要订阅，具体是哪几种情形没核到原文（TODO：待核实）。另一处反方意见是小石头：5 毫米以内的小结石和胰腺炎更相关。荷兰一项测算说，这类人预防性切除可能多活也可能少活，取决于胰腺炎有多常见、有多致命。欧洲指南也列了例外：胆囊壁钙化（瓷化胆囊）、同时有 1 厘米以上的胆囊息肉，这两种该切。要做别的腹部大手术时，可以考虑顺带切掉。这条说的只是一种情形：石头长在胆囊里，而且从来没疼过。胆总管里的石头是另一回事。同一份指南第 1.3.1 条明确写着，胆总管结石不管有没有症状，都要把胆管里的石头清掉，并且切除胆囊。出现下面这些情况要当天就去医院，别拿这个结论硬扛：右上腹或者上腹一直绞痛、发热打寒战、眼白或皮肤发黄、小便颜色变深。医生看过影像之后建议手术时，问清楚他是基于哪一条理由，比如胆管受了累、同时长了息肉、胆囊壁有异常，别拿这个结论去反驳他。它挡的只是「没有任何理由、单纯因为查出石头就切」。上面两项研究都是跟着一群人往后看，没有分组对照。但它们要回答的是「不去动它会怎么样」，而不是「哪种治疗更好」，用在这里合适。另外这两项跟踪的年头是 4 到 9 年，年头再长一些，出症状的比例会往上走', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-21', 'concept_archive_s6-21', 'claim_archive_s6-21', 'action', 'life_archive', '不要为了防肾结石把钙戒掉', '6. 反面清单', '长过草酸钙结石的人常被劝少吃钙，试验的结果正好反过来。反复长结石的男性正常吃钙、同时少吃动物蛋白和盐，五年里复发的人只有吃低钙饮食的一半。英国的指南也写明不要限制钙。', '争议：这项试验只做在男性身上，而且这些人都是反复长草酸钙结石、尿里钙又偏高的，不能直接套到所有类型的结石上。另外试验组同时改了三样，正常吃钙、少吃动物蛋白、少吃盐，所以不能把全部好处都记在「不戒钙」这一件事上，低盐和少动物蛋白同样在起作用。要否掉的是「主动把含钙的东西戒掉」，不是说「应该多补钙」。这里改的是一日三餐里的钙，钙补充剂是另一回事，长过结石的人要不要吃补充剂，问主治医生。多喝水那条见第 16 节第 8 条（肾结石后把水喝到每天 2.5–3 升）', NULL, NULL, NULL, '不花钱。反过来还省事，不用天天提防哪些东西含钙。', '有一项做了 5 年的随机分组对照试验，找了 120 名反复长草酸钙结石、同时尿里钙又偏高（叫特发性高钙尿）的男性。他们被随机分成两组。一组正常吃钙，每天 30 mmol。这一组同时少吃动物蛋白（每天 52 g）、少吃盐（每天 50 mmol 氯化钠）。另一组吃传统的低钙饮食，每天 10 mmol。5 年里复发的是 12/60 对 23/60。没做校正的相对风险 0.49（95% CI 0.24–0.98，这是可信范围），P=0.04，正常吃钙那组的复发风险只有一半。跟踪期间，两组尿里的钙都降了大约每天 170 mg。但尿里排出的草酸不一样。低钙组平均每天升高 5.4 mg，正常钙组平均每天下降 7.2 mg。英国 NICE 指南 NG118 第 1.8.1 条写明，不要限制每天吃进去的钙。成年人保持每天 700 到 1,200 mg。儿童青少年按年龄每天 350 到 1,000 mg。戒钙看起来划算，是因为「结石是钙做的，那就少吃钙」这个直觉', '争议：这项试验只做在男性身上，而且这些人都是反复长草酸钙结石、尿里钙又偏高的，不能直接套到所有类型的结石上。另外试验组同时改了三样，正常吃钙、少吃动物蛋白、少吃盐，所以不能把全部好处都记在「不戒钙」这一件事上，低盐和少动物蛋白同样在起作用。要否掉的是「主动把含钙的东西戒掉」，不是说「应该多补钙」。这里改的是一日三餐里的钙，钙补充剂是另一回事，长过结石的人要不要吃补充剂，问主治医生。多喝水那条见第 16 节第 8 条（肾结石后把水喝到每天 2.5–3 升）', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-22', 'concept_archive_s6-22', 'claim_archive_s6-22', 'action', 'life_archive', '不要为了「转运」「招财」「养人」买水晶、手串、貔貅这类物件', '6. 反面清单', '说戴了能改运、能招财、能养人，没有可以核查的证据。它和算命显得准是一个道理，话说得足够笼统，你会自己往身上套。商家把话说到治病的功效上就是虚假宣传，2026 年有直播间因此被查处。当装饰品买没问题。', '结论只有一个：它的功效无从核查，也测不出任何预测能力。不评价任何信仰或者习俗，也不针对送礼、纪念、传家这些用途。要分清两件事：商家宣称的功效有明文规定可依，能去投诉；而「转运」这类说法既没有研究，也没法证明它是假的，只能靠自己划预算管住。买之前先把它当成普通饰品，问自己一句「如果它什么都不改变，这个价钱我还买吗」。材质和证书怎么查、把它当投资为什么不划算，见第 5 节第 33、34 条（手串名表按花掉的钱算、珠宝玉石认 CMA 报告）。花钱算命见本节第 15 条（算命塔罗星座）。', NULL, NULL, NULL, '不花钱。要做的只是别把「转运」「养人」算进买它的理由里。难在别人都在戴、都在说灵的时候，自己不跟。', '经典课堂实验显示，人人拿到的都是同一份笼统的「个人分析」，却普遍认为很准，这个现象叫巴纳姆效应。它解释了「戴上之后确实顺了」这种体验是从哪来的。那位作者的结论是「被本人接受不能证明解释正确」。官方案例：市场监管总局 2026 年 6 月 4 日公布了一批传统工艺市场「打假清源」典型案例。其中广东四会有一家珠宝店，在直播间里编造商品材质。它还假称商品有「防治风湿病、提高免疫力、改善睡眠质量、疏通血管」等功效。这家店靠编剧本演戏来误导、欺骗消费者。这违反了反不正当竞争法第九条第一款（全国）', '结论只有一个：它的功效无从核查，也测不出任何预测能力。不评价任何信仰或者习俗，也不针对送礼、纪念、传家这些用途。要分清两件事：商家宣称的功效有明文规定可依，能去投诉；而「转运」这类说法既没有研究，也没法证明它是假的，只能靠自己划预算管住。买之前先把它当成普通饰品，问自己一句「如果它什么都不改变，这个价钱我还买吗」。材质和证书怎么查、把它当投资为什么不划算，见第 5 节第 33、34 条（手串名表按花掉的钱算、珠宝玉石认 CMA 报告）。花钱算命见本节第 15 条（算命塔罗星座）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-23', 'concept_archive_s6-23', 'claim_archive_s6-23', 'action', 'life_archive', '不要指望买东西改善心情或身份感', '6. 反面清单', '把钱和物质看得越重的人，自己觉得越不幸福，但关联很弱，也分不出谁导致谁。还有研究发现，花钱买一段经历比买东西更让人快乐。所以心情差的时候，把钱花在一次出门、一顿和人吃的饭上，比塞满购物车更可能有用。', '争议：收进来的研究大多是在同一个时间点问一批人，看两件事同不同步，分不出谁先谁后。作者自己在结论里也说，要看清方向还得靠更多的实验和长期跟踪研究。所以不能读成「买东西会让人不快乐」，只能读成「靠买东西来变快乐，指望不大」。而且关联很弱：r = -0.19 大概只解释了几个百分点的差异，人和人之间差别很大。两项研究用的都是国外样本，中国人群没有可以引用的同类数据。这里不反对为喜欢的东西花钱，反对的是把购物当成调节情绪的手段，因为那会让你下次心情差时的第一反应还是下单。省钱的具体动作见第 5 节。情绪差的时候真正有证据的做法，见第 22 节后半节和第 29 节。为「比别人强一档」而加的预算，见本节第 24 条（往上挪一档）。', NULL, NULL, NULL, '不花钱。难的是心情差的时候忍住不下单。', '一项荟萃分析（把很多项研究合起来算）共 259 项独立样本、753 个效应量。结果是：越看重物质的人，自己报告的幸福感越低。在最常用的那种多维量表上，相关系数 r = -0.19（校正后 ρ = -0.24）。只测「重视金钱」这一个方面的量表上，关联更弱，r = -0.08 到 -0.11。按看的是哪种结果分开看，强弱不一样。和冒险的健康与消费行为、对自己的负面评价关联最强，r = -0.28 到 -0.44。和生活满意度、负面情绪关联最弱，r = -0.13 到 -0.15。作者还做了中介分析（查中间通过什么传过去），结果提示这种负向关联可能是因为心理上的需要没有得到满足。另一项研究：两次面向不同人群的调查中，受访者都说为获得一段生活经历而花的钱比买东西更让自己快乐。随后的实验室实验里，回想一次为经历花钱之后的好心情，也高于回想一次买东西（全国口径不适用，这两项用的都是国外样本）', '争议：收进来的研究大多是在同一个时间点问一批人，看两件事同不同步，分不出谁先谁后。作者自己在结论里也说，要看清方向还得靠更多的实验和长期跟踪研究。所以不能读成「买东西会让人不快乐」，只能读成「靠买东西来变快乐，指望不大」。而且关联很弱：r = -0.19 大概只解释了几个百分点的差异，人和人之间差别很大。两项研究用的都是国外样本，中国人群没有可以引用的同类数据。这里不反对为喜欢的东西花钱，反对的是把购物当成调节情绪的手段，因为那会让你下次心情差时的第一反应还是下单。省钱的具体动作见第 5 节。情绪差的时候真正有证据的做法，见第 22 节后半节和第 29 节。为「比别人强一档」而加的预算，见本节第 24 条（往上挪一档）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-24', 'concept_archive_s6-24', 'claim_archive_s6-24', 'action', 'life_archive', '不要为了「在周围人里往上挪一档」多花钱换房、换车、换圈子', '6. 反面清单', '拿收入一样的人来比，邻居挣得越多，这个人报告的幸福感越低。这只发生在学历和自己相同、又常来往的邻居之间。所以为了搬进一个人人都比你宽裕的地方而多花的钱，买到的是把自己往下挪一档。但收入一起涨的时候，人还是觉得更好过，绝对水平仍然算数。', '定 B 级的理由有几条：数据来自反复回访同一批人的问卷，只有这一项研究，样本又在国外；看的结果是受访者自己报的幸福感，不是钱。作者确实用统计手段排掉了几类干扰，比如同一个人前后比、同一个州同一轮之间比，但终究不是随机试验。中国人群也没有可以引用的同类数据。收益量级定「中」，是沿用本节第 23 条（别指望买东西改善心情）的口径。省下的钱确实可能到万元级。但「省下这笔钱能换来多少幸福感」没有数字支撑，所以不按万元级记成「大」。这里不反对为更大的房子、更安静的小区、更短的通勤花钱，那些买的是东西本身。要拦的是「同事都换了，我不能比他们差」这一个理由。住处该按什么排序见第 4 节第 18 条（选住处时把通勤时长放在前面）。买东西调情绪见本节第 23 条（别指望买东西改善心情）。在网上老往上比见第 3 节第 20 条（别把「别人过得怎么样」当每日必读）', NULL, NULL, NULL, '不花钱。要做的只是在加预算之前多问一句：这笔加价买的是东西本身，还是我在这群人里的位置。难在周围人都换了的时候，自己不跟。', '美国全国家庭与住户调查（NSFH）两轮回访了同一批人。作者把这份数据和本地平均收入对上。本地平均收入（PUMA）是按 1990 年人口普查 5% 抽样推算出来的。把本人收入和一系列个人特征都扣掉之后，结果是：邻居收入越高，自己报告的幸福感越低。这个效应大，换一种算法也稳，而且高度显著。作者的表述是，「邻居收入上升」和「本人收入下降同样幅度」带来的幸福感下降处于同一数量级。改成同一个人前后自己跟自己比之后（这叫加个体固定效应），系数方向不变、大小也相近，只是显著性降到了 10% 的水平。再限定在同一个州、同一轮调查之间比（这叫加州和调查轮次的固定效应），结果基本不变。这说明它不是「爱搬去穷地方的人本来就更快乐」造成的，也不是州一级某些没测到的因素造成的。效应在常和邻居来往的人身上更强，在只和社区外朋友来往的人身上不显著。租房的人和自己有房的人没有差异，这一点不支持「贵地方房价高，所以实际可花的钱少」这种解释。幸福感只随学历相同的邻居的收入而下降，对学历不同的邻居的收入几乎没有反应。而且它主要是通过「对自己物质处境的满意度」传过去的，不是通过对家庭生活等其他方面的满意度。最后，如果本人和邻居的收入按同样比例一起上升，幸福感仍然上升', '定 B 级的理由有几条：数据来自反复回访同一批人的问卷，只有这一项研究，样本又在国外；看的结果是受访者自己报的幸福感，不是钱。作者确实用统计手段排掉了几类干扰，比如同一个人前后比、同一个州同一轮之间比，但终究不是随机试验。中国人群也没有可以引用的同类数据。收益量级定「中」，是沿用本节第 23 条（别指望买东西改善心情）的口径。省下的钱确实可能到万元级。但「省下这笔钱能换来多少幸福感」没有数字支撑，所以不按万元级记成「大」。这里不反对为更大的房子、更安静的小区、更短的通勤花钱，那些买的是东西本身。要拦的是「同事都换了，我不能比他们差」这一个理由。住处该按什么排序见第 4 节第 18 条（选住处时把通勤时长放在前面）。买东西调情绪见本节第 23 条（别指望买东西改善心情）。在网上老往上比见第 3 节第 20 条（别把「别人过得怎么样」当每日必读）', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-25', 'concept_archive_s6-25', 'claim_archive_s6-25', 'action', 'life_archive', '不要相信「意志力像肌肉，用一会儿就没了」', '6. 反面清单', '流行的说法是：先做一件费自控的事，接下来就更容易破功，所以要省着用意志力。23 个实验室、2141 人按同一套方案重做了这个实验，结果几乎是零。别再用「今天意志力用完了」解释自己，也别为此花钱买教你攒意志力的课。', '要否掉的是「自控是一种会被消耗完的资源」这个模型，不是否掉「人会累」。睡不够、连着干太久会让人效率下降，那是另一回事，按第 3 节的睡眠和工时几条处理。真正有随机试验支持的做法是改环境和改写法，见第 4 节第 10 条（把不想碰的挪远）和第 4 节第 1 条（写成「几点、在哪、遇到什么就做什么」）。把穿什么、吃什么固定下来仍然值得做，因为几乎不花成本。它省下的是那几分钟和几次纠结，不是意志力，别指望它让你下午判断得更好。本节其他条目算的是钱，这里算的是时间和精力，两者不做换算。', NULL, NULL, NULL, '不花钱。要改的只是一个说法。', '一项多实验室预注册重复研究，23 个实验室、共 2141 名受试者，按 Sripada 等人的标准化方案重做了序贯任务范式：先做一件消耗自控的任务，再做第二件需要自控的任务。汇总结果显示自我损耗效应很小，而且 95% 可信区间包含 0（d = 0.04，95% CI −0.07 到 0.15）。作者据此讨论了「自控是有限资源」这一模型还成不成立。另一次同样事先登记方案的重做，36 个实验室、3531 人，效果大小 d = 0.06，同样小到不能算数。', '要否掉的是「自控是一种会被消耗完的资源」这个模型，不是否掉「人会累」。睡不够、连着干太久会让人效率下降，那是另一回事，按第 3 节的睡眠和工时几条处理。真正有随机试验支持的做法是改环境和改写法，见第 4 节第 10 条（把不想碰的挪远）和第 4 节第 1 条（写成「几点、在哪、遇到什么就做什么」）。把穿什么、吃什么固定下来仍然值得做，因为几乎不花成本。它省下的是那几分钟和几次纠结，不是意志力，别指望它让你下午判断得更好。本节其他条目算的是钱，这里算的是时间和精力，两者不做换算。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-26', 'concept_archive_s6-26', 'claim_archive_s6-26', 'action', 'life_archive', '不要指望吃早餐或 16:8 轻断食帮你控制体重，吃饭时间挑你能长期坚持的', '6. 反面清单', '流行说法是不吃早餐会让人午饭晚饭暴食，一天总量反而更多。试验里不是这样：不吃早餐的人一天少吃了两百多千卡，体重还略轻一点。16:8 和单纯少吃比，一年下来体重也没差别。长期不吃早餐的人心血管病确实多约一成七，总死亡率则看不出差别。', '争议。心血管那 17% 来自只记录、不分组的研究。不吃早餐的人本来就更可能吸烟、喝酒、久坐、收入低，这些因素校正不干净。所以那 17% 里有多少是早餐本身造成的，说不清。全因死亡那一项本来就跨过了 1。16:8 也有争议：汇总 30 项试验、1341 人，在两组吃一样多的前提下，限时进食那组多减 1.46 kg（−2.65 到 −0.26），代价是多掉 0.41 kg 瘦体重。但这些试验多数很短，最长最严的那项十二个月试验说没差别。长时间空腹还和胆囊有关。一项 6,547 人的横断面调查里，一天中第一餐每晚一小时，查出胆结石的比例高约 5%（OR 1.05，1.02–1.08）；第一餐拖到 9 点至 14 点的人比更早吃的高约 49%（OR 1.49，1.24–1.77）。机制是胆汁在胆囊里存得越久越容易析出结石。但这是同一时点的调查，也可能是先有了胆囊问题才改的吃饭习惯。中国开滦队列跟踪 5.6 年、369 例消化道癌：不吃早餐的人结直肠癌风险 2.32 倍（1.34–4.01），胆囊和肝外胆管癌 5.43 倍（1.34–21.93）。后一个数的可信范围宽到 21.93，说明事件太少，只能当线索看。合起来看，就控制体重而言，吃饭时间的影响很小，别为它花心力。至于长期完全不吃早餐好不好，现有证据全是关联、不能证明因果，但方向一致偏不利，想稳妥就正常吃，只是别指望它帮你减重。胃炎和胃溃疡的主因不是空腹，是幽门螺杆菌和长期吃止痛药，该查的见第 1 节第 23 条（查幽门螺杆菌，阳性就根除）。体检查出胆囊结石但从没疼过该怎么办，见本节第 20 条（体检查出胆囊结石但从没疼过，不要预防性切胆囊）。想控制体重，真正有证据的是吃什么和吃多少，见第 2 节第 27 条（每天吃够 5 份水果蔬菜）、第 2 节第 28 条（少吃超加工食品）和第 2 节第 32 条（把 BMI 控制在 20–25）。糖尿病人、正在吃降糖药或者怀孕的人不适用，漏一顿可能低血糖，按医嘱来。极端断食和催吐是另一回事，见第 28 节第 1 条（不要用极端节食、断食或催吐来控制体重）。', NULL, NULL, NULL, '不花钱。省下的是每天跟吃饭时间较劲的那点心力。', '先看「不吃早餐会让人后面吃更多」这个说法。一篇荟萃分析把 13 项随机试验合起来算。被分到吃早餐那组的人，每天摄入比不吃早餐那组多 259.79 kcal（95% CI 78.87–440.71，这是可信范围）。体重高 0.44 kg（0.07–0.82）。不吃早餐的人并没有在午饭晚饭补回来。这些试验跟踪时间都很短，看体重的平均 7 周，看摄入的平均 2 周。再看 16:8 这类只在固定几小时内吃饭的做法。一项让 116 名超重成人做 12 周。只在中午 12 点到晚上 8 点吃饭的那组，和每天规律吃三顿的那组，体重差 −0.26 kg（−1.30 到 0.78），不显著。另一项在广州做，139 名肥胖患者，跟踪 12 个月。限时进食加控制热量，比单纯控制热量多减 1.8 kg（−4.0 到 0.4），也不显著。最后看长期不吃早餐有没有害。238 万人的汇总里，不吃早餐的人心血管病风险高约 17%（OR 1.17，1.09–1.26），心血管死亡高约 49%（OR 1.49，1.20–1.84）。但这些是只记录、不分组的研究。跟踪 17 到 23 年的那项原始研究里，全因死亡的风险比是 1.19，可信范围 0.99 到 1.42，跨过了 1，算不上有差别。', '争议。心血管那 17% 来自只记录、不分组的研究。不吃早餐的人本来就更可能吸烟、喝酒、久坐、收入低，这些因素校正不干净。所以那 17% 里有多少是早餐本身造成的，说不清。全因死亡那一项本来就跨过了 1。16:8 也有争议：汇总 30 项试验、1341 人，在两组吃一样多的前提下，限时进食那组多减 1.46 kg（−2.65 到 −0.26），代价是多掉 0.41 kg 瘦体重。但这些试验多数很短，最长最严的那项十二个月试验说没差别。长时间空腹还和胆囊有关。一项 6,547 人的横断面调查里，一天中第一餐每晚一小时，查出胆结石的比例高约 5%（OR 1.05，1.02–1.08）；第一餐拖到 9 点至 14 点的人比更早吃的高约 49%（OR 1.49，1.24–1.77）。机制是胆汁在胆囊里存得越久越容易析出结石。但这是同一时点的调查，也可能是先有了胆囊问题才改的吃饭习惯。中国开滦队列跟踪 5.6 年、369 例消化道癌：不吃早餐的人结直肠癌风险 2.32 倍（1.34–4.01），胆囊和肝外胆管癌 5.43 倍（1.34–21.93）。后一个数的可信范围宽到 21.93，说明事件太少，只能当线索看。合起来看，就控制体重而言，吃饭时间的影响很小，别为它花心力。至于长期完全不吃早餐好不好，现有证据全是关联、不能证明因果，但方向一致偏不利，想稳妥就正常吃，只是别指望它帮你减重。胃炎和胃溃疡的主因不是空腹，是幽门螺杆菌和长期吃止痛药，该查的见第 1 节第 23 条（查幽门螺杆菌，阳性就根除）。体检查出胆囊结石但从没疼过该怎么办，见本节第 20 条（体检查出胆囊结石但从没疼过，不要预防性切胆囊）。想控制体重，真正有证据的是吃什么和吃多少，见第 2 节第 27 条（每天吃够 5 份水果蔬菜）、第 2 节第 28 条（少吃超加工食品）和第 2 节第 32 条（把 BMI 控制在 20–25）。糖尿病人、正在吃降糖药或者怀孕的人不适用，漏一顿可能低血糖，按医嘱来。极端断食和催吐是另一回事，见第 28 节第 1 条（不要用极端节食、断食或催吐来控制体重）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-27', 'concept_archive_s6-27', 'claim_archive_s6-27', 'action', 'life_archive', '不要相信「手淫伤身」「戒色才能变好」，真正要看的是有没有耽误睡觉、工作和关系', '6. 反面清单', '没有研究说手淫伤身。美国一项大研究反而看到，射精次数多的男性，前列腺癌少约两成。英国一项研究看到二三十岁时次数多的人风险偏高，所以两边都不能当成锻炼身体的理由。很多人觉得自己「看色情上瘾」，更多是因为这事和自己的道德观打架。', '争议。前列腺癌这两项研究都只是记录、没有分组对照，次数又是本人回忆的，所以结论只能到「没看到伤身的证据」，不能反过来劝人多做。英国那项的作者自己也说，五十多岁那段可能是先病了才次数少。色情那篇的摘要没有给出效应量，所以这里只写方向。收益定成小，是因为降的主要是低危前列腺癌，不是死亡。真正该去精神科或心理科的信号是：为这事熬夜、误工、影响伴侣关系，想停也停不下来。熬夜见第 3 节第 9 条（不为游戏、短视频、色情内容熬夜）。担心看色情看出了勃起问题，先按第 1 节第 28 条（勃起功能出了问题先去查心血管）去查。往群里发、卖资源的法律后果见第 9 节第 4 条（黄色视频自己看归自己）。受益人是你自己。', NULL, NULL, NULL, '不花钱。省下的是买「补肾」偏方和「戒色」课程的钱，还有长期自责的那份焦虑。', '先看身体。美国一项研究跟踪了 31925 名男性，到 2010 年。每个人自己报告每月射精几次，再按次数分组。和每月 4 到 7 次的人比，每月 21 次以上的人前列腺癌 HR 0.81（95% CI 0.72–0.92，低约 19%），这是按 20 到 29 岁时的次数算的。按 40 到 49 岁时的次数算，HR 0.78（0.69–0.89，低约 22%）。少掉的主要是低危的前列腺癌。反方是英国一项病例对照研究，比了 431 名 60 岁前确诊的患者和 409 名对照。二三十岁时手淫频繁的人风险偏高，五十多岁时频繁的人风险偏低。再看色情内容。一篇系统综述加荟萃分析认为，很多人觉得自己「上瘾了」，更多是行为和自己信的道理对不上，不只是看得多（美国 / 英国）', '争议。前列腺癌这两项研究都只是记录、没有分组对照，次数又是本人回忆的，所以结论只能到「没看到伤身的证据」，不能反过来劝人多做。英国那项的作者自己也说，五十多岁那段可能是先病了才次数少。色情那篇的摘要没有给出效应量，所以这里只写方向。收益定成小，是因为降的主要是低危前列腺癌，不是死亡。真正该去精神科或心理科的信号是：为这事熬夜、误工、影响伴侣关系，想停也停不下来。熬夜见第 3 节第 9 条（不为游戏、短视频、色情内容熬夜）。担心看色情看出了勃起问题，先按第 1 节第 28 条（勃起功能出了问题先去查心血管）去查。往群里发、卖资源的法律后果见第 9 节第 4 条（黄色视频自己看归自己）。受益人是你自己。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-28', 'concept_archive_s6-28', 'claim_archive_s6-28', 'action', 'life_archive', '不要花钱做「性取向矫正」「同性恋治疗」，也不要把家里人送去', '6. 反面清单', '美国心理学会的专家组看完研究后说，这类矫正改不了性取向，还可能伤人。美国一项调查里，做过矫正的人有过自杀念头的多了近九成。国内有精神病院以「性偏好障碍」为名强制收治一名男子，被法院判侵权、赔 5000 元。', '争议。Sullins 2022 用同一批数据重算，扣掉了矫正之前就有的自杀念头。这样算下来，矫正和自杀念头不再是正相关（OR 0.44，0.20–0.94）。Sullins 所在的机构立场反对同性恋，原作者也写了回应。所以伤害有多大还有争议，但「改不了」这一点没有看到反方证据。给 B 是因为伤害的数字都来自事后回忆的调查。法律上，住院治疗实行自愿原则，只有严重精神障碍、又有伤害自己或别人的危险，才能强制住院。心理咨询人员不许做心理治疗。故意把不是精神障碍的人送进医院治疗，要承担赔偿责任。2014 年，一名男子在重庆心语飘香心理咨询中心被催眠、电击「治疗」同性恋，事后起诉。北京海淀法院判这家中心公开道歉、赔偿经济损失。据报道，判决书写明同性恋不是精神疾病，中心承诺能治属于虚假宣传。此案只有澎湃新闻的报道，法院官网上没找到判决原文。心里为这件事长期痛苦的，可以去精神科或临床心理科，目标是缓解痛苦。孩子说出来之后家里怎么做，见第 30 节第 15 条（孩子说自己喜欢同性）。受益人是你自己和家里人。', NULL, NULL, NULL, '不花钱。省下的是矫正机构、心理诊所和「戒同」营收的钱。难的是家里人坚持要送。', '美国心理学会 2009 年的工作组报告说，改变性取向的努力「不太可能成功，并且有一定的伤害风险」。对把未成年人送进强制或住院式的矫正项目，报告建议父母和孩子都不要考虑。美国一项全国代表性调查访问了 1518 名性少数成年人，约 7% 做过矫正，其中八成来自宗教人士。扣除年龄、童年不幸经历等因素后，做过矫正的人一生中有过自杀念头的 OR 1.92（95% CI 1.01–3.64，高约九成）。计划过自杀的 OR 1.75（1.01–3.06）。没受伤或受轻伤的自杀尝试 OR 1.88（1.01–3.50）。另一项研究访问了 245 名 21 到 25 岁的年轻人。青春期没被矫正过的，22.0% 试过自杀。父母自己试图改变孩子性取向的，是 48.1%。父母还把孩子送去找治疗师或宗教人士的，是 62.8%。世界卫生组织的疾病分类 ICD-10 写明：「性取向本身不被视为一种障碍」。2017 年河南驻马店驿城区法院审了一个案子：精神病院以「性偏好障碍」为名强制收治一名男子。法院认为他「病情一般，也无自杀、伤人、毁物等行为或危险，不符合应当强制治疗的条件」。法院判医院公开道歉，赔精神抚慰金 5000 元（美国 / 中国）', '争议。Sullins 2022 用同一批数据重算，扣掉了矫正之前就有的自杀念头。这样算下来，矫正和自杀念头不再是正相关（OR 0.44，0.20–0.94）。Sullins 所在的机构立场反对同性恋，原作者也写了回应。所以伤害有多大还有争议，但「改不了」这一点没有看到反方证据。给 B 是因为伤害的数字都来自事后回忆的调查。法律上，住院治疗实行自愿原则，只有严重精神障碍、又有伤害自己或别人的危险，才能强制住院。心理咨询人员不许做心理治疗。故意把不是精神障碍的人送进医院治疗，要承担赔偿责任。2014 年，一名男子在重庆心语飘香心理咨询中心被催眠、电击「治疗」同性恋，事后起诉。北京海淀法院判这家中心公开道歉、赔偿经济损失。据报道，判决书写明同性恋不是精神疾病，中心承诺能治属于虚假宣传。此案只有澎湃新闻的报道，法院官网上没找到判决原文。心里为这件事长期痛苦的，可以去精神科或临床心理科，目标是缓解痛苦。孩子说出来之后家里怎么做，见第 30 节第 15 条（孩子说自己喜欢同性）。受益人是你自己和家里人。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-29', 'concept_archive_s6-29', 'claim_archive_s6-29', 'action', 'life_archive', '不要指望学会「正确搬运姿势」、上搬运培训就能防腰痛，要减的是搬的重量和次数，平时多锻炼', '6. 反面清单', '上过搬运姿势培训的工人，后来腰痛的并不比没上过的少。搬东西时腰弯得多的人，也没看出更容易腰痛。和腰痛有关的是搬得重、搬得多，每次多搬 10 公斤或每天多搬 10 次，风险高约一成。平时规律锻炼的人，腰痛发作少三成多到四成多。', '争议。搬得重、搬得多这一侧说法不一。2010 年一篇系统综述找到 9 项高质量研究，4 项看到关联，5 项没看到。作者认为工作中搬东西不太可能单独导致腰痛。所以「少搬重的」只有关联证据，证明不了因果。弯腰那篇的研究质量低，多数只比了同一时间的两群人。培训那篇的可信范围很宽，它也说没有随机试验看过培训能不能治已有的腰痛。HSE 仍然教一套手法：东西贴近腰，脚站稳，别扭腰，别猛拽。起身时背、髋、膝都微微弯，比完全弯腰或完全蹲下都好。照做没坏处，只是别指望它单独防住腰痛。收益定中，因为按降幅锻炼够得上大，但单靠锻炼的证据质量低，锻炼加讲解也没看出能少请病假，腰痛又不致命。锻炼怎么做见第 2 节第 16 条（每周做 30–60 分钟力量训练）和第 2 节第 11 条（每天走到 7000–8000 步）。受益人是你自己。', NULL, NULL, NULL, '不花钱。不用再为搬东西时腰弯没弯较劲，也不用为护腰课和护腰带花钱。要做的是两件事。重的东西拆开搬、用推车或找人一起搬，这只多花几分钟。每周抽几次时间锻炼，这要长期坚持。', '先看培训。Cochrane 系统综述 2011 年版汇总了 9 项随机分组的试验，共 20101 名员工。其中 7 项试验、19317 人的结果是：上过搬运培训的人和什么都没做的人，后来报告的腰痛差不多（OR 1.17，95% CI 0.68–2.02，可信范围跨过 1）。和只看了一段视频的人比，RR 0.93（0.69–1.25），也差不多。证据质量是中等。作者的结论是，搬运建议和培训不管配不配搬运工具，都防不住腰痛和腰痛造成的失能。再看弯腰。2020 年一篇系统综述汇总了搬东西时腰弯多少的研究，证据质量低。唯一一项跟踪研究里，后来腰痛和没腰痛的人，搬东西时腰最多弯的角度只差 1.5 度（−0.7 到 3.7），不显著。11 项研究里有 9 项没看到两组有差别。另有 7 项研究换了一种量法，腰痛的人搬东西时腰反而少弯 6.0 度（−11.2 到 −0.9）。作者的结论是，没有证据说腰弯得多会招来腰痛。最后看该怎么做。一篇荟萃汇总了 8 项跟踪研究：每次搬的东西每重 10 公斤，腰痛风险 OR 1.11（1.05–1.18，高约 11%）。每天每多搬 10 次，OR 1.09（1.03–1.15，高约 9%）。另一篇汇总了 21 项随机试验、30850 人。锻炼加讲解让腰痛发作的风险 RR 0.55（0.41–0.74，低约 45%），证据质量中等。单靠锻炼 RR 0.65（0.50–0.86，低约 35%），证据质量低到很低。单靠讲解 RR 1.03（0.83–1.27），护腰带 RR 1.01（0.71–1.44），都看不出效果。英国健康与安全执行局（HSE）的官方指南也写明：单靠培训保证不了搬运安全，好的搬运手法也替代不了配搬运工具、改进任务和货物。', '争议。搬得重、搬得多这一侧说法不一。2010 年一篇系统综述找到 9 项高质量研究，4 项看到关联，5 项没看到。作者认为工作中搬东西不太可能单独导致腰痛。所以「少搬重的」只有关联证据，证明不了因果。弯腰那篇的研究质量低，多数只比了同一时间的两群人。培训那篇的可信范围很宽，它也说没有随机试验看过培训能不能治已有的腰痛。HSE 仍然教一套手法：东西贴近腰，脚站稳，别扭腰，别猛拽。起身时背、髋、膝都微微弯，比完全弯腰或完全蹲下都好。照做没坏处，只是别指望它单独防住腰痛。收益定中，因为按降幅锻炼够得上大，但单靠锻炼的证据质量低，锻炼加讲解也没看出能少请病假，腰痛又不致命。锻炼怎么做见第 2 节第 16 条（每周做 30–60 分钟力量训练）和第 2 节第 11 条（每天走到 7000–8000 步）。受益人是你自己。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"6. 反面清单","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s6-30', 'concept_archive_s6-30', 'claim_archive_s6-30', 'action', 'life_archive', '不要指望骨折之后猛补钙、喝骨头汤能让骨头长得更快', '6. 反面清单', '骨折后补维生素 D 的试验，没有一项看出骨头长得更好。钙和维 D 一起补的研究很少，说不清有没有用。一大碗骨头汤里的钙，只有每天该吃的几十分之一。本来就缺维 D、有骨质疏松的人另说。', '争议：有两处小苗头。丹麦一项试验找了 30 名上臂近肩处骨折的老年女性，她们有骨质疏松或骨量偏低。每天吃 800 IU 维 D 加 1 克钙的人，第 6 周骨折处骨密度更高（0.623 对 0.570 g/cm²）。但它只量了骨密度，没看骨头长没长好，人也太少。那项 102 人的试验事后拆开看，大剂量维 D 的人功能评分略好，作者说还要再做试验确认。本来就缺维 D 的人另说。荷兰一项跟踪记录里，补了以后仍然缺的人，愈合拖慢的占 9.7%。本来不缺的人占 0.3%，补上来的人占 1.7%。这只是跟踪记录，证明不了因果。查出缺了，按医生说的补到正常。已经确诊骨质疏松、或者轻轻一摔就骨折的人，要的是抗骨质疏松药，见第 1 节第 40 条（抗骨质疏松药），钙片代替不了它。不缺维 D 的人长期补没有好处，见本节第 3 条（补维生素 D）。要否掉的是「额外猛补」，不是少吃钙，三餐里的钙照常吃够，见本节第 21 条（防肾结石把钙戒掉）。刚摔了怀疑骨折怎么办，见第 13 节第 41 条（怀疑骨折）。收益定中，是按一年钙片和维 D 的钱算的。受益人是你自己。', NULL, NULL, NULL, '不花钱，还省下钙片、维生素 D 和天天熬汤的钱和工夫。要做的只是查出缺了再补，不缺就不额外补。', '先看维生素 D。2023 年一篇系统综述收了 14 项研究、2734 名骨折病人。作者的结论是，单补维生素 D 对骨头愈合、长没长上和恢复后的功能影响很小。看出好处的几项研究，质量普遍偏低。作者写明，只算随机分组的试验，没有一项看出补了有好处。其中一项找了 100 名维 D 偏低的长骨骨折病人。一半人伤后两周内一次吃 10 万 IU，一半人吃安慰剂（假药）。两边各有 2 人骨头没长上，合起来是 4%。另一项找了 102 名 18 到 50 岁的大腿骨或小腿骨骨折病人，分四组吃不同剂量或安慰剂。3 个月和 12 个月时，愈合评分都没看出差别。还有一项找了 32 名手腕骨折的绝经后女性。和不补的人比，每天折合 1800 IU 的大剂量组，骨头的抗压硬度反而更低。再看钙。2014 年一篇系统综述说，维 D 不足或补维 D 对骨折愈合影响的临床研究很少，结论说不清。它找到的两项研究是钙和维 D 一起补，看到的是骨折处骨密度或骨痂（新长出来的骨头）多了，没看愈合快慢。最后看骨头汤。台湾高雄一项测定买了三种骨头汤面食，一份汤 450 到 550 克。每份汤里的钙平均 14 到 39 毫克，占每天 1000 毫克推荐量的 1.4% 到 3.9%。作者的结论是，一份汤的钙不到每天推荐量的 5%。中国的推荐量是 18 到 49 岁每天 800 毫克，50 岁以上 1000 毫克，每天上限 2000 毫克。这份标准写明，长期吃过量的钙会增加得肾结石的风险。美国一项试验找了 36282 名绝经后女性，每天吃 1000 毫克钙加 400 IU 维 D，平均跟踪 7 年。肾结石风险高约 17%（HR 1.17，95% CI 1.02–1.34，可信范围）。髋部骨折低约 12%，但不显著（HR 0.88，0.72–1.08）。它看起来划算，是因为「骨头是钙做的，多吃钙就长得快」这个直觉', '争议：有两处小苗头。丹麦一项试验找了 30 名上臂近肩处骨折的老年女性，她们有骨质疏松或骨量偏低。每天吃 800 IU 维 D 加 1 克钙的人，第 6 周骨折处骨密度更高（0.623 对 0.570 g/cm²）。但它只量了骨密度，没看骨头长没长好，人也太少。那项 102 人的试验事后拆开看，大剂量维 D 的人功能评分略好，作者说还要再做试验确认。本来就缺维 D 的人另说。荷兰一项跟踪记录里，补了以后仍然缺的人，愈合拖慢的占 9.7%。本来不缺的人占 0.3%，补上来的人占 1.7%。这只是跟踪记录，证明不了因果。查出缺了，按医生说的补到正常。已经确诊骨质疏松、或者轻轻一摔就骨折的人，要的是抗骨质疏松药，见第 1 节第 40 条（抗骨质疏松药），钙片代替不了它。不缺维 D 的人长期补没有好处，见本节第 3 条（补维生素 D）。要否掉的是「额外猛补」，不是少吃钙，三餐里的钙照常吃够，见本节第 21 条（防肾结石把钙戒掉）。刚摔了怀疑骨折怎么办，见第 13 节第 41 条（怀疑骨折）。收益定中，是按一年钙片和维 D 的钱算的。受益人是你自己。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"6. 反面清单","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-1', 'concept_archive_s7-1', 'claim_archive_s7-1', 'action', 'life_archive', '失业了先在线申领失业保险金', '7. 没钱的时候怎么活', '单位和你自己交满 1 年、又不是你主动提的辞职，办完失业登记就能领钱。交满 1 年不到 5 年，最多领 12 个月。满 5 年不到 10 年，最多 18 个月。10 年以上，最多 24 个月。领钱这段时间，职工医保有失业保险替你交。', '自己主动辞职的，不算「非因本人意愿」，领不了。所以离职时别签「个人原因主动辞职」，见第 19 节第 7 条。失业保险金从办失业登记那天起算，晚办一个月就少拿一个月的钱。走人之后第一件事就是去登记。登记要用单位开的离职证明，见第 19 节第 17 条（离职证明）。竞业协议要不要守、公司不给补偿怎么办，见第 11 节第 12 条（签了竞业协议）。领取期间的职工医保由失业保险替你交。各省金额差得多，以你参保那个地方公布的为准。「最低工资 90%」出自人社部、财政部 2017 年的指导意见（人社部发〔2017〕71 号），原话是「逐步将失业保险金标准提高到最低工资标准的90%」。这是目标，不是现在就按 90% 发。人社部官网的原文页在本机打不开，这句按辽宁省人社厅文件里的引文核对。', NULL, NULL, NULL, '不花钱。用手机就能交申请，三个入口都行：「掌上 12333」App、微信或支付宝里的电子社保卡小程序、国家社会保险公共服务平台。手上有社保卡或者身份证就能办，多数地区不用跑现场。前提是先办好失业登记。', '要同时满足三个条件。一是单位和你本人交失业保险累计满 1 年。二是不是你自己主动提的辞职（法律叫「非因本人意愿中断就业」）。三是已经办了失业登记，并且有找工作的意愿。能领多久按缴费年限算。累计满 1 年不足 5 年，最长领 12 个月。满 5 年不足 10 年，最长 18 个月。10 年以上，最长 24 个月。每月发多少由省级政府定，各省不一样。金额低于当地最低工资，高于城市低保。国家的目标是逐步提到最低工资标准的 90%。领失业保险金这段时间，你照样参加职工基本医疗保险、享受基本医疗保险待遇。该交的那笔基本医疗保险费从失业保险基金里出，你个人不交（全国，条例 1999 年起施行）', '自己主动辞职的，不算「非因本人意愿」，领不了。所以离职时别签「个人原因主动辞职」，见第 19 节第 7 条。失业保险金从办失业登记那天起算，晚办一个月就少拿一个月的钱。走人之后第一件事就是去登记。登记要用单位开的离职证明，见第 19 节第 17 条（离职证明）。竞业协议要不要守、公司不给补偿怎么办，见第 11 节第 12 条（签了竞业协议）。领取期间的职工医保由失业保险替你交。各省金额差得多，以你参保那个地方公布的为准。「最低工资 90%」出自人社部、财政部 2017 年的指导意见（人社部发〔2017〕71 号），原话是「逐步将失业保险金标准提高到最低工资标准的90%」。这是目标，不是现在就按 90% 发。人社部官网的原文页在本机打不开，这句按辽宁省人社厅文件里的引文核对。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-2', 'concept_archive_s7-2', 'claim_archive_s7-2', 'action', 'life_archive', '被欠薪先投诉劳动监察，再申请劳动仲裁，两条路都不收费，多数案子几个月内有结果', '7. 没钱的时候怎么活', '两条路都不收钱。先打 12333 或者去人社局劳动监察投诉，立案后 60 个工作日内查完，能责令公司限期付钱，逾期不付还要多赔 50% 到 100%。再不行就申请劳动仲裁，45 天内结案。但「结案」不等于「到账」：公司没财产、老板跑了，赢了也可能拿不到钱。', '投诉和仲裁有用，但要分清「结案」和「到账」。98.2% 的结案率说的只是程序走完了。公司没财产、老板跑路的，赢了也照样拿不到钱。最高法只公布执行到位的总额（2024 年 2.3 万亿元）和「执行完毕率保持高位」，欠薪案最后有多少真进了当事人口袋，没有官方数据。「仲裁终结率」这个词公报没给定义，本条按「裁决之后没再打到法院去」理解。欠薪到一定数额就够刑事立案了。一种是欠一个人 3 个月以上，金额在 5000 到 2 万元以上。另一种是欠 10 人以上，累计 3 万到 10 万元以上。这两种情况，责令支付后还是不付的，就够立案。各省高院和省检察院在这个幅度内定本省的具体数额并公布，投诉前查一下本省是多少，投诉时当面提出来。工地上的农民工另有工资专用账户和总包先行清偿的规定，找总包比找包工头管用。这两条路的前提是有用人单位。没办执照的作坊、店铺照样算，可以投诉和仲裁。给家庭或个人干私活，比如当保姆，就不算劳动关系，要去法院，见第 22 条（先分清雇你的是谁）。进城务工人员为讨薪申请法律援助的，不查经济困难。劳动合同法、民事诉讼法的原文引自税务总局和贵州省市场监管局的转载页（都是 gov.cn），因为中国人大网的页面打不开。刑法修正案（八）在中国人大网抓取失败，改用 curl 打开核对', NULL, NULL, NULL, '不花钱，投诉和仲裁都不收费。要备齐劳动合同、工资条、考勤记录、转账记录和聊天记录，跑人社局或者仲裁委 1 到 3 趟。申请仲裁有 1 年的时限（法律上叫仲裁时效）。人还在这家单位干着、工资被拖欠的，不受这 1 年的限制。已经离职的，从离职那天算起 1 年内必须提出。难在要一趟趟跑、一份份找证据，中间容易泄气。', '第一步是投诉。拨 12333，或者去当地人社局的劳动监察投诉。法律规定立案后 60 个工作日内查完，案情复杂的可以再延 30 个工作日。查实了，能责令公司限期把钱付掉。过了期限还不付的，要按该付金额的 50% 到 100% 再加付一笔赔偿金。2024 年全国监察机构查处 13.7 万件，为 65.4 万人追回工资 86.5 亿元。手上有欠条或者工资表、欠薪事实清楚的，还可以直接向基层法院申请支付令。支付令就是法院给公司下的付款命令，法院受理后 15 日内发出。第二步是申请仲裁。法律规定受理后 45 日内结案，可以再延 15 日。讨工资的可以申请先予执行：不等案子全部审完，先执行一部分。欠的钱不超过当地月最低工资 12 倍的，属于一裁终局：仲裁裁完就算定了，公司不能再起诉。2024 年全国办理 425.7 万件，办结 415.6 万件。结案金额 934.7 亿元。调解成功率 79.6%，仲裁结案率 98.2%，仲裁终结率 73.7%。有人说这事要拖「半年一年」，说的是仲裁之后又打到法院去的那部分案子：一审 6 个月（走简易程序的 3 个月），再加二审 3 个月。2024 年法院审结追索劳动报酬案 8.8 万件、追回 285.4 亿元，998 人因拒不支付劳动报酬罪获刑（全国）', '投诉和仲裁有用，但要分清「结案」和「到账」。98.2% 的结案率说的只是程序走完了。公司没财产、老板跑路的，赢了也照样拿不到钱。最高法只公布执行到位的总额（2024 年 2.3 万亿元）和「执行完毕率保持高位」，欠薪案最后有多少真进了当事人口袋，没有官方数据。「仲裁终结率」这个词公报没给定义，本条按「裁决之后没再打到法院去」理解。欠薪到一定数额就够刑事立案了。一种是欠一个人 3 个月以上，金额在 5000 到 2 万元以上。另一种是欠 10 人以上，累计 3 万到 10 万元以上。这两种情况，责令支付后还是不付的，就够立案。各省高院和省检察院在这个幅度内定本省的具体数额并公布，投诉前查一下本省是多少，投诉时当面提出来。工地上的农民工另有工资专用账户和总包先行清偿的规定，找总包比找包工头管用。这两条路的前提是有用人单位。没办执照的作坊、店铺照样算，可以投诉和仲裁。给家庭或个人干私活，比如当保姆，就不算劳动关系，要去法院，见第 22 条（先分清雇你的是谁）。进城务工人员为讨薪申请法律援助的，不查经济困难。劳动合同法、民事诉讼法的原文引自税务总局和贵州省市场监管局的转载页（都是 gov.cn），因为中国人大网的页面打不开。刑法修正案（八）在中国人大网抓取失败，改用 curl 打开核对', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-3', 'concept_archive_s7-3', 'claim_archive_s7-3', 'action', 'life_archive', '打不起官司就申请法律援助，讨薪、赡养费、工伤这类案子本来就在范围内', '7. 没钱的时候怎么活', '讨薪、要赡养费、要社保或低保待遇、见义勇为受了损失，都能申请免费法律援助。打 12348，或者去当地的法律援助中心。现在不用回原籍开经济困难证明，本人如实说明就行。可能判死刑的，还有盲、聋、哑和未成年的被告人，一律指派律师。', '法律援助法从 2022 年 1 月 1 日起施行，有一处变化。原来要「提交经济困难证明」。现在改成本人如实说明自己的经济状况就行，不用再回原籍开证明。入口是各地的法律援助中心、公共法律服务中心，也可以打 12348', NULL, NULL, NULL, '不花钱。法律援助不向被援助的人收一分钱。', '国务院的条例里写明了民事法律援助管哪六类事。条例的原话是：「依法请求国家赔偿的；请求给予社会保险待遇或者最低生活保障待遇的；请求发给抚恤金、救济金的；请求给付赡养费、抚养费、扶养费的；请求支付劳动报酬的；主张因见义勇为行为产生的民事权益的」。说白了就是：要国家赔偿，要社保或低保待遇，要抚恤金救济金，要赡养费抚养费，讨工资，见义勇为受了损失。刑事案件这边，可能判处死刑的被告人，以及盲、聋、哑和未成年的被告人，不看经济状况一律指派律师', '法律援助法从 2022 年 1 月 1 日起施行，有一处变化。原来要「提交经济困难证明」。现在改成本人如实说明自己的经济状况就行，不用再回原籍开证明。入口是各地的法律援助中心、公共法律服务中心，也可以打 12348', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-4', 'concept_archive_s7-4', 'claim_archive_s7-4', 'action', 'life_archive', '走投无路时去救助站，管吃住和返乡车票', '7. 没钱的时候怎么活', '救助站管吃、管住，生病了送医院，还帮你联系家里人。没钱回家的发车票。一般住不超过 10 天。自愿来、自愿走，不是收容，也不发现金。车票按户籍地或者住所地开，去之前先想清楚要回哪儿。', '自愿求助、自愿离站，不是收容。给的是基本食宿，不发现金。乘车凭证按户籍地或者住所地开，求助前先想清楚要去哪。', NULL, NULL, NULL, '不花钱。自己到当地的救助管理站求助，也可以告诉民警或者民政部门，让他们带你去。进站要如实登记姓名和随身物品。难在要开口跟人说自己没钱、没地方去。', '救助站提供符合卫生要求的食物和住处。在站里突发急病的，送医院治。还会帮你联系亲属和单位。没钱买票回户籍地或者住所地的，发乘车（船）凭证，就是车票船票。户籍地就是老家，住所地就是现在常住的地方。救助期限一般不超过 10 天。等家人来接、等治疗、等安置的，可以延长。公安和其他行政机关的人执行职务时碰上流浪乞讨人员，应当告诉他可以去求助。对残疾人、未成年人、老年人和行动不便的人，要引导护送过去（全国，2003 年起）', '自愿求助、自愿离站，不是收容。给的是基本食宿，不发现金。乘车凭证按户籍地或者住所地开，求助前先想清楚要去哪。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-5', 'concept_archive_s7-5', 'claim_archive_s7-5', 'action', 'life_archive', '找活先用免费的公共就业服务和零工市场，不找收费中介', '7. 没钱的时候怎么活', '就业服务中心、人力资源市场这些公家机构，介绍工作、职业指导、政策咨询、办就业和失业登记，全都不收钱。法律还明文不许它们拿这些服务去赚钱。零工市场的登记和发布信息也免费。顺手把失业登记办掉，领失业金和认定就业困难人员都要用它。', '失业登记是领失业保险金、认定就业困难人员的前置手续，顺手办掉。干零工按天结账的，当场核对工钱，留下对方的联系方式和干活记录。', NULL, NULL, NULL, '不花钱。到县级以上的公共就业服务机构登记，比如就业服务中心、人力资源市场。本地的零工市场也可以登记。不知道地址就拨 12333 问。', '法律规定下面这几样一律免费：就业政策咨询；哪里在招人、哪里缺人的信息；职业指导和职业介绍；办就业登记和失业登记；对就业困难人员的就业援助。这些机构不得从事经营性活动，不许靠这些服务赚钱。零工的求职招聘信息，登记和发布也免费向社会提供，已经纳入公共就业信息服务的范围。对待工时间长的人（就是长期接不到活的）、低收入家庭等困难零工人员，还要加强帮扶（全国）', '失业登记是领失业保险金、认定就业困难人员的前置手续，顺手办掉。干零工按天结账的，当场核对工钱，留下对方的联系方式和干活记录。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-6', 'concept_archive_s7-6', 'claim_archive_s7-6', 'action', 'life_archive', '突发变故先申请临时救助', '7. 没钱的时候怎么活', '家里突然出事，比如火灾、车祸、家人突发重病，把基本生活一时压垮了，就可以向乡镇政府或者街道办申请临时救助。不要求你已经是低保户。多是一次性发一笔，金额各地差别很大。', '不要求你已经是低保户。多是一次性发一笔，金额各地差得很多，以当地当年公布的为准。', NULL, NULL, NULL, '不花钱。向乡镇政府或者街道办提出申请，说清楚家里出了什么事。比如火灾、交通事故、家人突发重大疾病，或者日常非花不可的开销突然涨上来。审核公示之后，由县级民政部门审批。材料按当地给的清单准备，通常跑 1 到 2 趟。', '两类家庭可以拿临时救助。一类是因为意外事件、家庭成员突发重大疾病这些原因，连吃住看病这些最基本的开销都一时撑不住的家庭。另一类是非花不可的开销突然增加、超出自己承受能力的低保家庭。救哪些事、给多少钱，由县级以上地方政府自己定并公布（全国制度，金额地方定，2014 年起）', '不要求你已经是低保户。多是一次性发一笔，金额各地差得很多，以当地当年公布的为准。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","B 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-7', 'concept_archive_s7-7', 'claim_archive_s7-7', 'action', 'life_archive', '收入低于当地低保线就申请低保', '7. 没钱的时候怎么活', '全家收入除以人数，低于当地低保线，家里财产也符合规定的，就可以申请。2024 年末，全国城市低保线平均每人每月 798.1 元，农村 593.9 元。批下来发的是低保线减去家里每人每月收入的差额。有房有车有存款，或者子女能赡养你，可能批不下来。', '低保是最后一道保障，要回户籍地申请。家里的房、车、存款超过当地标准，或者子女有能力赡养你，都可能批不下来。批下来之后还有别的好处：交居民医保有资助（居民医保见第 9 条），看病能走医疗救助（医疗救助见第 10 条），申请法律援助不查经济困难（法律援助见第 3 条）。', NULL, NULL, NULL, '不花钱。由一起过日子的家庭成员，向户口所在地的乡镇政府或者街道办交一份书面申请。自己办不方便的，可以委托村委会、居委会代办。要接受家庭收入和财产核查。通常跑 2 到 3 趟，带上身份证、户口本和收入财产证明。难在要把家底摊开给人查，还要等公示。', '全家收入除以人数，低于当地低保标准，家里财产也在规定范围内的，可以拿低保。2024 年末，全国城市低保平均标准是 798.1 元/人·月，农村是 593.9 元/人·月。城市低保保障 625.0 万人，农村保障 3361.5 万人。低保金按差额按月发：当地低保标准减去家庭人均收入。比如当地标准 798.1 元，家里每人每月收入 500 元，每人每月领的是 298.1 元，不是 798.1 元。低保标准这么定：拿当地上年度居民人均消费支出，乘以一个量化比例，隔一段时间再调一次。说白了就是拿当地上一年平均每人花掉多少钱，打个折算出来（全国平均，各地不同）', '低保是最后一道保障，要回户籍地申请。家里的房、车、存款超过当地标准，或者子女有能力赡养你，都可能批不下来。批下来之后还有别的好处：交居民医保有资助（居民医保见第 9 条），看病能走医疗救助（医疗救助见第 10 条），申请法律援助不查经济困难（法律援助见第 3 条）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-8', 'concept_archive_s7-8', 'claim_archive_s7-8', 'action', 'life_archive', '持残疾人证的去申请残疾人两项补贴', '7. 没钱的时候怎么活', '低保家庭里的残疾人，可以领生活补贴。残疾等级是一级、二级，又需要长期照护的，可以领护理补贴。两项能同时领。标准各省自己定，差别很大，具体问街道。带上第二代残疾人证，去街道或者乡镇办一次。', '标准由省级政府定，各地差别很大，每月从几十元到几百元不等。申请要带第二代残疾人证。本人不方便的，可以委托家属代办', NULL, NULL, NULL, '不花钱。带上残疾人证，到街道或者乡镇提交一次申请就行。', '国务院定下了两项补贴。第一项是困难残疾人生活补贴，文件写的对象是「低保家庭中的残疾人，有条件的地方可逐步扩大到低收入残疾人及其他困难残疾人」。意思是先保低保家庭里的残疾人，地方财力允许的可以往外扩。第二项是重度残疾人护理补贴，文件写的对象是「残疾等级被评定为一级、二级且需要长期照护的重度残疾人」。这两项可以同时领', '标准由省级政府定，各地差别很大，每月从几十元到几百元不等。申请要带第二代残疾人证。本人不方便的，可以委托家属代办', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-9', 'concept_archive_s7-9', 'claim_archive_s7-9', 'action', 'life_archive', '居民医保每年 400 元不要断，困难户可减免', '7. 没钱的时候怎么活', '个人一年交 400 元起，财政再按人头补 700 元上下。特困人员全额资助，低保对象定额资助。断缴是有代价的：没在集中期参保、或者没连着交的，交完之后有 3 个月看病不给报，每多断 1 年原则上再多加 1 个月。', '国家医保局 2025 年那份通知（医保发〔2025〕22 号）没有在医保局官网和中国政府网公开挂出。700 元和 400 元两个数在河北、安徽两省的文件里一致，安徽那份写明是按这份通知定的。领失业保险金那段时间，职工医保由失业保险替你交，不必重复参保。', NULL, NULL, NULL, '自己交的那部分，每人每年不低于 400 元。这是 2024、2025 年的国家标准，各地可以比这个高。要在每年固定的那段集中缴费期里交。特困人员是全额资助，这笔钱全由政府出。低保对象是定额资助，政府出固定的一部分。', '除了自己交的那部分，财政再按人头补一笔。2024 年不低于 670 元，2025 年比上年提高 30 元，不低于 700 元，个人缴费仍是不低于 400 元（医保发〔2025〕22 号，按省级文件转述）。2026 年的政府工作报告里说再提高 24 元。低保对象和特困人员，符合规定的医疗费，医保报完之后剩下的部分，还能按不低于 70% 的比例走医疗救助再报一次。断缴的代价是等待期。没在集中缴费期参保、或者没连着交的，交完之后有 3 个月固定待遇等待期，这段时间看病不给报。每多断 1 年，原则上再加 1 个月（2025 年起，全国）', '国家医保局 2025 年那份通知（医保发〔2025〕22 号）没有在医保局官网和中国政府网公开挂出。700 元和 400 元两个数在河北、安徽两省的文件里一致，安徽那份写明是按这份通知定的。领失业保险金那段时间，职工医保由失业保险替你交，不必重复参保。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-10', 'concept_archive_s7-10', 'claim_archive_s7-10', 'action', 'life_archive', '得了重病先走医保、大病保险、医疗救助和异地备案，不碰网贷', '7. 没钱的时候怎么活', '顺序是固定的。跨省住院前先在「国家医保局」公众号里备案，出院直接结算，不用先垫全款。报销完自己还掏不起的，向乡镇或者街道申请医疗救助。在职的按工龄有 3 到 24 个月医疗期，这期间公司不能辞你。网贷和民间高息借款不要碰。', '医疗救助报多大比例、一年最多报多少，由你参保的那个地方自己定。医疗期分六档，看你一共工作了几年、在这家单位干了几年。医疗期一过，公司就可能合法跟你解约，提前看清自己在哪一档。急诊抢救的人也在需要备案的名单里。医保局的页面没说急诊算不算自动备案、事后能不能补办，打电话问参保地。网贷和民间高息借款不要碰。法院只保护到一年期 LPR 的 4 倍这条线（不借高利贷见第 15 条）。超出那条线的部分不受保护，本金还是照还。躺在病床上也没精力去打这种官司。急重伤病是另一回事：没钱也要打 120，医院不得拒绝、推诿或者拖延救治，那一段的急救费由疾病应急救助基金付，见第 24 节第 8 条（急诊也必须先救）。劳部发〔1995〕309 号的原文页在人社部官网打不开，内容取自省人社厅的转载。', NULL, NULL, NULL, '不花钱。顺序是固定的，一步一步来。第一步，跨省住院之前，用「国家医保局」微信公众号里的「国家异地就医备案」小程序备案。第二步，出院时直接结算。第三步，报销之后自己要掏的还是太重，就向乡镇政府或者街道办申请医疗救助。第四步，还在上班的按医疗期请病假，医疗期就是生病停工又不能被辞退的那段时间；属于工伤的走工伤保险。第五步，信用卡还不上，主动找银行协商分期。第六步，实在不够，再上民政部指定的个人求助平台筹款。材料主要是诊断证明、费用清单、结算单，跑 2 到 4 趟。难在人在病中，还要一趟趟跑手续。', '国家把基本医保、大病保险、医疗救助合起来叫「三重制度」，一层一层往下兜。低保对象和特困人员，符合规定的医疗费用按不低于 70% 救助。本来不穷、看病看穷了的重病患者，可以自己提出申请再救助。跨省住院前备了案，就能出院直接结算，不必先垫全款再回参保地报。生病停工有 3 到 24 个月的医疗期，具体多久按工龄长短定。这段时间里，公司不得解除劳动合同，病假工资不得低于当地最低工资的 80%。工伤职工有停工留薪期，就是养伤不上班的那段时间，原来的工资福利照发，由单位按月发，一般不超过 12 个月。信用卡欠款超出还款能力、本人又愿意还的，可以和银行协商个性化分期，把欠款重新排一个还款计划，最长 5 年，签了协议银行就必须停止催收。网上替本人筹钱的个人求助平台，必须经国务院民政部门指定。平台要核验求助信息是不是真的。捐来的钱只能打给求助人本人，或者他提供的账户（全国）', '医疗救助报多大比例、一年最多报多少，由你参保的那个地方自己定。医疗期分六档，看你一共工作了几年、在这家单位干了几年。医疗期一过，公司就可能合法跟你解约，提前看清自己在哪一档。急诊抢救的人也在需要备案的名单里。医保局的页面没说急诊算不算自动备案、事后能不能补办，打电话问参保地。网贷和民间高息借款不要碰。法院只保护到一年期 LPR 的 4 倍这条线（不借高利贷见第 15 条）。超出那条线的部分不受保护，本金还是照还。躺在病床上也没精力去打这种官司。急重伤病是另一回事：没钱也要打 120，医院不得拒绝、推诿或者拖延救治，那一段的急救费由疾病应急救助基金付，见第 24 节第 8 条（急诊也必须先救）。劳部发〔1995〕309 号的原文页在人社部官网打不开，内容取自省人社厅的转载。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-11', 'concept_archive_s7-11', 'claim_archive_s7-11', 'action', 'life_archive', '身份证丢了立刻补办，急用先领临时身份证', '7. 没钱的时候怎么活', '补办的，从交表那天算起 60 天内发证。急用的，当场再申请一张临时身份证，3 天内发，有效期 3 个月。没有身份证，找工作、住宿、开户、领补贴全都办不成，它是所有手续的前提。', '没有身份证，找工作、住宿、开户、领补贴都办不了，这是所有手续的前置条件。身份证法 2011 年有过修正，本条所引的是 2003 年公布的文本，条款以现行的为准。能不能异地办理，以当地公安的公告为准。', NULL, NULL, NULL, '要交证件工本费。这是法定收费，收多少由国家定，以当地公示的为准。到常住户口所在地的派出所申请，跑 1 趟。', '从你交上《居民身份证申领登记表》那天算起，公安机关要在 60 日内发证。新办、换证、补办的这段时间里，如果急着用证，可以申请一张临时居民身份证。公安机关收到申请后 3 日内发放，有效期 3 个月（全国）', '没有身份证，找工作、住宿、开户、领补贴都办不了，这是所有手续的前置条件。身份证法 2011 年有过修正，本条所引的是 2003 年公布的文本，条款以现行的为准。能不能异地办理，以当地公安的公告为准。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-12', 'concept_archive_s7-12', 'claim_archive_s7-12', 'action', 'life_archive', '办失业登记后争取就业困难人员认定，拿社保补贴或公益性岗位', '7. 没钱的时候怎么活', '认定下来之后，自己交社保能拿补贴，原则上不超过你实际交的三分之二，最长 3 年。被单位招用、或者安排到公益性岗位的，单位那部分社保也有补贴。公益性岗位的工资参照当地最低工资。这类岗位钱不多，但带社保，适合过渡。社保补贴多是先交后补，得先垫钱。', '公益性岗位工资不高，但有社保，适合过渡。社保补贴多是先交后补，要先垫钱。具体条件问 12333 或者街道。', NULL, NULL, NULL, '不花钱。到街道或者社区的公共就业服务机构申请认定。认定条件各地不同，常见的有大龄、长期失业、低保家庭、残疾、零就业家庭这几类。要先办好失业登记才能申请。难在得一项项核对自己够不够条件，社保还要先垫钱。', '认定下来之后，没有单位、自己交社保的（这叫灵活就业）可以拿社保补贴。补贴标准原则上不超过你实际交的 2/3，最长拿 3 年。被单位招用、或者被安排到公益性岗位的，单位按实际缴纳的养老、医疗、失业保险费拿补贴。公益性岗位就是政府出钱开发的岗位，它的补贴参照当地最低工资。政府开发的公益性岗位，优先安排就业困难人员。另外还有一次性求职补贴，发给高校毕业生。范围是低保家庭、零就业家庭、特困人员里的毕业生。残疾的、拿过国家助学贷款的毕业生也算。这笔钱在毕业那一学年领（全国框架，认定条件与金额地方定）', '公益性岗位工资不高，但有社保，适合过渡。社保补贴多是先交后补，要先垫钱。具体条件问 12333 或者街道。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-13', 'concept_archive_s7-13', 'claim_archive_s7-13', 'action', 'life_archive', '失业期间去领职业培训补贴、就业见习补贴和社保补贴，别自费上培训班', '7. 没钱的时候怎么活', '培训不用自己掏钱。参加培训并拿到规定的证书，就有职业培训补贴，同一个人最多领 3 次。毕业两年内没找到工作的高校毕业生、16 到 24 岁的失业青年，可以参加就业见习，见习期间领基本生活费。先去当地人社局官网查「职业培训补贴目录」，别自费报班。', '具体的补贴目录和金额由各省定，先在当地人社局官网查「职业培训补贴目录」。低保家庭、零就业家庭的毕业年度高校毕业生，还有欠着助学贷款的、残疾的，另有一次性求职创业补贴', NULL, NULL, NULL, '不花钱。培训本身要占掉你不少时间。难在要连着上完课、考出证书，才拿得到补贴。', '财政部、人社部的规章里列了一批就业补助资金项目，就是财政专门拿来补贴就业的那笔钱。参加培训并拿到符合规定的证书，给职业培训补贴，同一个人最多领 3 次。就业困难人员自己交社保（灵活就业）的补贴最长 3 年；离法定退休年龄不到 5 年的，可以延到退休。高校毕业生自己交社保的补贴最长 2 年，被企业招走的最长 1 年。毕业 2 年内没找到工作的高校毕业生，还有 16 至 24 岁的失业青年，可以参加就业见习，见习期间领基本生活费', '具体的补贴目录和金额由各省定，先在当地人社局官网查「职业培训补贴目录」。低保家庭、零就业家庭的毕业年度高校毕业生，还有欠着助学贷款的、残疾的，另有一次性求职创业补贴', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-14', 'concept_archive_s7-14', 'claim_archive_s7-14', 'action', 'life_archive', '求职别只投简历，用系统方法：学技巧、定目标、找人帮', '7. 没钱的时候怎么活', '参加过求职辅导的人，找到工作的几率是没参加的人的 2.67 倍。管用的是这几样：学具体的求职技巧，把自己讲清楚，定明确目标，主动出击，开口找人帮忙。找人帮忙落到实处，就是托熟人内推。', '这些研究多数在欧美做，形式是成套的小组课程。搬到中国是拿别处的结果套过来，不是国内测出来的。争取社会支持落到实处，就是让熟人帮着介绍和内推，别不好意思开口。', NULL, NULL, NULL, '不花钱。每天要花 1 到 2 小时，连着做上几周。付费课程可以不报，用公共就业服务机构的免费职业指导代替。难在没人盯着的时候天天坚持，还要主动开口找人帮忙。', '把 47 项做过对照的求职辅导研究合并起来算。这些研究是实验或者准实验设计，都分了组做比较。结果是：参加辅导的那组，找到工作的几率是没参加那组的 2.67 倍（OR 2.67，即几率之比）。辅导里管用的成分有这几样。一是教求职技巧。二是改善自我呈现（把自己讲清楚）。三是提升自我效能（相信自己做得到）。四是鼓励主动出击。五是设定目标。六是争取社会支持（开口找人帮忙）。既教技能、又能提起劲头的辅导，效果最大', '这些研究多数在欧美做，形式是成套的小组课程。搬到中国是拿别处的结果套过来，不是国内测出来的。争取社会支持落到实处，就是让熟人帮着介绍和内推，别不好意思开口。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-15', 'concept_archive_s7-15', 'claim_archive_s7-15', 'action', 'life_archive', '不交押金、不押证件、不签「培训贷」、不进传销、不借高利贷', '7. 没钱的时候怎么活', '用人单位不能扣你的身份证，不能收押金，也不能换个名目收钱。中介没给你介绍成工作，必须退中介费。先交培训费再上岗的培训贷、靠拉人头算钱的传销，都是官方点名的骗局。借钱的利息超过一年期 LPR 四倍的部分，法院不支持，但本金照还。', '4 倍 LPR 是法院愿意保护的利息上限，不是「借了可以不还」，本金照还。这份司法解释 2020 年 12 月又改过一次，条文序号有变，以现行文本为准。分期和网贷的手续费怎么换算成年化利率，见第 5 节第 7 条（把利息换成年化利率）。越急着用钱，越容易被这些套路盯上。先走本节前面那几条正规渠道：失业保险金、劳动监察投诉、法律援助、救助站、临时救助。', NULL, NULL, NULL, '不花钱。遇到「先交钱再上岗」「先培训再安排工作」「拉人头」这三种说法，当场拒绝。留好聊天记录和转账凭证。难在越缺钱越想赌一把，当场说「不」不容易。', '公司不得扣押你的身份证等证件，不得要你找人担保，也不得换个名目收你的钱和物。违反的责令退还，并按每人 500 元以上 2000 元以下罚款。职业中介同样不得扣证件、收押金，工作没介绍成，必须把中介费退给你。打着招聘的名义，诱导你先交培训费或者先贷款，这是人社部等五部门点名提示的「招转培」「培训贷」骗局。靠拉人头算提成、交了钱才能加入的，属于传销，参加的人可罚 2000 元以下。民间借贷的利息，超过签合同时一年期 LPR 4 倍的那部分，法院不支持。这条新规矩取代了原来按 24%、36% 两条线划三段的老办法（全国，2020 年 8 月起）', '4 倍 LPR 是法院愿意保护的利息上限，不是「借了可以不还」，本金照还。这份司法解释 2020 年 12 月又改过一次，条文序号有变，以现行文本为准。分期和网贷的手续费怎么换算成年化利率，见第 5 节第 7 条（把利息换成年化利率）。越急着用钱，越容易被这些套路盯上。先走本节前面那几条正规渠道：失业保险金、劳动监察投诉、法律援助、救助站、临时救助。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-16', 'concept_archive_s7-16', 'claim_archive_s7-16', 'action', 'life_archive', '住房困难先排公租房', '7. 没钱的时候怎么活', '要同时占上三条：在本地没房，或者住房面积低于标准；收入和财产低于标准；外来务工的还要在本地稳定就业满规定年限。轮候期由当地公布。这是远水，解不了近渴，但排队不花钱，早报名早轮到。', '这是远水，解不了近渴，但排队不花钱，早报名早轮到。各地另有保障性租赁住房等别的类型，规则不一样，去当地住建部门的网站查。', NULL, NULL, NULL, '申请不收费。向市、县的住房保障部门交材料，还要书面同意他们去核实你报的情况。材料不齐的，他们会一次性告诉你要补哪些。排队等房的期限叫轮候期，一般不超过 5 年。', '三项条件都占上就能申请。一是在本地没有住房，或者住房面积低于规定标准。二是收入和财产低于规定标准。三是外来务工人员要在本地稳定就业满规定年限。具体条件由直辖市和市、县的住房保障部门定了公布。登记上排队名单的人叫轮候对象，住房保障部门应当在轮候期内给他安排房源（全国框架，门槛和租金地方定，2012 年起）', '这是远水，解不了近渴，但排队不花钱，早报名早轮到。各地另有保障性租赁住房等别的类型，规则不一样，去当地住建部门的网站查。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-17', 'concept_archive_s7-17', 'claim_archive_s7-17', 'action', 'life_archive', '把住和吃压到最低：合租月租代替日租，自炊和助餐食堂代替外卖', '7. 没钱的时候怎么活', '2025 年全国人均消费里，吃占 29.3%，住占 21.7%，两项加起来过半，所以压这两项最有效。按作者的经验，日租房、钟点房折算到一个月，比合租贵；自己做饭比点外卖便宜。找工作时问清包不包吃住，包的岗位等于把这两大项抹掉。', '日租房、钟点房按月算比合租贵得多，这是经验判断，没有官方数字。老年助餐点对不对非老年人开放、价格多少，各地不同。找工作时问清是不是包吃住，包吃住的岗位能把这两大项直接抹掉。人社部的原表页面打不开，数字取自四川省人社厅的转载页。', NULL, NULL, NULL, '找房要花 1 到 3 天。押金通常是 1 个月房租（作者粗估）。自己做饭，每天要占 30 到 60 分钟。难在天天自己动手做，忍住不点外卖。', '2025 年，全国居民平均每人一年花掉 29476 元（这叫人均消费支出）。其中食品烟酒 8631 元，占 29.3%。居住 6397 元，占 21.7%。两项加起来过半，所以压这两项最有效。老年助餐服务面向全体老年人开展，形式有老年食堂、老年餐桌、助餐点，困难老人另有差异化补贴。作个参照：截至 2026 年 1 月 1 日，各省第一档月最低工资最低是青海 2080 元，最高是上海 2740 元（全国，2025 至 2026 年）', '日租房、钟点房按月算比合租贵得多，这是经验判断，没有官方数字。老年助餐点对不对非老年人开放、价格多少，各地不同。找工作时问清是不是包吃住，包吃住的岗位能把这两大项直接抹掉。人社部的原表页面打不开，数字取自四川省人社厅的转载页。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-18', 'concept_archive_s7-18', 'claim_archive_s7-18', 'action', 'life_archive', '社保断缴不要慌：养老按累计算，医保按规则补', '7. 没钱的时候怎么活', '养老金按累计年限算，不按连续年限算，断了不清零，到退休年龄累计满 15 年就能按月领。职工医保交够年限的，退休后不用再交，各地的年限不一样，打 12393 问参保地。真正受影响的是买房、落户、积分这些要求连续缴费的资格。', '职工医保退休不用再交的那个年限，法律写的是「国家规定年限」，各地执行的数不一样，男女也常常不同，打 12393 或者问参保地医保局。断缴主要影响当地那些要求连着交满多少个月的资格，比如买房、落户、积分，这些规则各地自己定，去当地查。花钱找人「挂靠」代缴，钱可能打水漂，也有法律风险，不建议。换城市工作时养老和医保关系怎么转、别办退保，见第 19 节第 19 条（养老和医保关系转到新参保地）。15 年这条线 2030 年起每年提高 6 个月，逐步到 20 年，自己交怎么算账见第 5 节第 46 条（自己交职工养老保险）。', NULL, NULL, NULL, '不花钱。居民养老、居民医保可以自己按年交。职工社保断了，不必为了「别断档」去花钱找人挂靠。', '基本养老保险按累计缴费年限算，中间断过也不清零。到法定退休年龄，累计满 15 年就能按月领养老金。不够的，可以接着缴到满 15 年。换个地方就业的（正式说法是跨统筹地区），养老关系跟着人走，缴费年限接着往上累计。职工医保累计缴费达到国家规定年限的，退休后不用再交。居民医保断缴的代价是等待期：重新交上之后，有一段时间看病不给报（居民医保见第 9 条）（全国）', '职工医保退休不用再交的那个年限，法律写的是「国家规定年限」，各地执行的数不一样，男女也常常不同，打 12393 或者问参保地医保局。断缴主要影响当地那些要求连着交满多少个月的资格，比如买房、落户、积分，这些规则各地自己定，去当地查。花钱找人「挂靠」代缴，钱可能打水漂，也有法律风险，不建议。换城市工作时养老和医保关系怎么转、别办退保，见第 19 节第 19 条（养老和医保关系转到新参保地）。15 年这条线 2030 年起每年提高 6 个月，逐步到 20 年，自己交怎么算账见第 5 节第 46 条（自己交职工养老保险）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-19', 'concept_archive_s7-19', 'claim_archive_s7-19', 'action', 'life_archive', '坐过牢、破过产、上过失信名单，法律上都有重来的路，先把手续走完', '7. 没钱的时候怎么活', '刑满释放的人，在就业、就学、社保上不得被歧视，生活困难的由政府帮助安置。犯罪时不满 18 岁、判 5 年以下的，记录封存，当兵找工作不必报告。失信名单的期限是 2 年，钱还清了法院应在 3 个工作日内删名。成年人的前科不封存，当兵、就业时要如实报告。', '成年人的案底不封存。刑法第一百条要求当兵、找工作时必须如实报告自己受过刑事处罚。公务员、法官、律师、教师这些职业和政审另有法定限制。监狱法在 2026 年 11 月 1 日之前的现行文本，对应第三十七、三十八条，条号以生效文本为准。中办发〔2010〕5 号在中央政府网没找到原文页，取自区政府的转载。个人破产的考察期内，不能坐飞机头等舱、不能高消费、不能买房；故意侵害别人人身造成的赔偿等 8 类债务不免除；靠欺诈拿到的免责，还可能被撤销。从失信名单上被删掉，不等于征信记录跟着变干净，那是两套系统。', NULL, NULL, NULL, '不收手续费。刑满释放的，到户籍地或者居住地的司法所、街道报到，申请安置帮教（政府的安置和帮扶）。上了失信被执行人名单的，把该还的还完，再向执行法院申请把名字删掉。在深圳参保满 3 年的个人，可以申请个人破产。每一步都要准备材料、接受面谈，还有 1 到 3 年的考察期。难在要一遍遍跟人讲过去的事，考察期还得熬。', '刑满释放人员依法享有与其他公民平等的权利，在就业、就学和享受社会保障方面不受歧视。生活困难的，由户籍地或者居住地政府帮助安置、依法救助帮扶（监狱法 2026 年修订，11 月 1 日起施行）。中央 2010 年的文件要求对他们强化职业培训，符合条件的纳入低保，还要建立过渡性安置基地。犯罪时不满 18 岁、并且判刑 5 年以下的，犯罪记录封存，当兵、找工作时不必报告；本人申请无犯罪记录证明的，3 个工作日内出具。上失信名单的期限是 2 年。钱还清了，或者和对方达成和解等情形下，法院应在 3 个工作日内把名字删掉。深圳经济特区个人破产条例是目前唯一的个人破产法规，宣告破产后熬满 3 年考察期，没还完的债可以免掉。企业法人还不上到期的债、欠的又比有的多（这叫资不抵债），可以申请重整、和解或者破产清算，债随着这家企业一并了结（全国，个人破产仅深圳）', '成年人的案底不封存。刑法第一百条要求当兵、找工作时必须如实报告自己受过刑事处罚。公务员、法官、律师、教师这些职业和政审另有法定限制。监狱法在 2026 年 11 月 1 日之前的现行文本，对应第三十七、三十八条，条号以生效文本为准。中办发〔2010〕5 号在中央政府网没找到原文页，取自区政府的转载。个人破产的考察期内，不能坐飞机头等舱、不能高消费、不能买房；故意侵害别人人身造成的赔偿等 8 类债务不免除；靠欺诈拿到的免责，还可能被撤销。从失信名单上被删掉，不等于征信记录跟着变干净，那是两套系统。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-20', 'concept_archive_s7-20', 'claim_archive_s7-20', 'action', 'life_archive', '大病之前，基本医保之外配一份一年期医疗险或重疾险，看清「保证续保」四个字', '7. 没钱的时候怎么活', '这类保险补的是医保报完之后你自己要掏的那部分，还有停工的损失。买之前认准「保证续保」四个字：没有这四个字的，明年可能停售或者涨价。健康状况要如实告知，瞒了会被拒赔。先把基本医保交上，再考虑这条。', '定 B 级，是因为官方只给了定义和规则，没有「买了能省多少」的数字。「百万医疗险」是卖的时候的叫法，法规上它算短期健康险。条款里不写「保证续保」的，明年可能停售或者涨价，买之前先在条款里找这四个字。两份按实际花费报销的医疗险，同一笔钱不能报两次，别叠着买。已经有病还投保、又不如实告知的，出事会被拒赔。如实告知有个两年的期限：合同成立满两年，保险公司就不能再以你没如实告知为由解除合同，出了事要赔。两年内被查出故意没告知的，合同解除前出的事不赔，保费也不退。哪些损失值得用保险兜，见第 5 节第 39 条（扛不住的损失）。先把居民医保（第 9 条）交上，再考虑这条。疾病定义规范是行业协会发布、银保监会指导的，不是政府文件。', NULL, NULL, NULL, '年轻人买一年期的费用补偿型医疗险，每年几百元。费用补偿型就是按你实际花掉的钱报销那种。重疾险每年几千元起（作者粗估，无官方数字）。投保前要如实告知自己的健康状况，一次性花半小时。', '官方把这类产品分成两种。医疗保险按你实际花掉的医疗费报销。疾病保险是一确诊合同里约定的那些病，就按约定的数额直接赔一笔钱。两者补的都是医保报完之后自己要掏的那部分，以及停工的损失。保险期间在一年及以下、条款里又没写保证续保的，属于短期健康险。超过一年的，或者写了保证续保的，才是长期健康险。「保证续保」的意思是：到期续保时，公司必须按原来的条款和约定的费率接着保。保险公司不得诱导同一个人重复买保障功能相同或者类似的费用补偿型医疗险。买两份，同一笔钱也只能报一次。重疾险的疾病定义有行业统一规范，包括 28 种重度疾病和 3 种轻度疾病。恶性肿瘤、急性心肌梗死、脑中风后遗症是核心病种（全国，2019、2020 年起）', '定 B 级，是因为官方只给了定义和规则，没有「买了能省多少」的数字。「百万医疗险」是卖的时候的叫法，法规上它算短期健康险。条款里不写「保证续保」的，明年可能停售或者涨价，买之前先在条款里找这四个字。两份按实际花费报销的医疗险，同一笔钱不能报两次，别叠着买。已经有病还投保、又不如实告知的，出事会被拒赔。如实告知有个两年的期限：合同成立满两年，保险公司就不能再以你没如实告知为由解除合同，出了事要赔。两年内被查出故意没告知的，合同解除前出的事不赔，保费也不退。哪些损失值得用保险兜，见第 5 节第 39 条（扛不住的损失）。先把居民医保（第 9 条）交上，再考虑这条。疾病定义规范是行业协会发布、银保监会指导的，不是政府文件。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","B 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-21', 'concept_archive_s7-21', 'claim_archive_s7-21', 'action', 'life_archive', '实在没地方睡，24 小时营业场所只能应急一晚，优先去救助站', '7. 没钱的时候怎么活', '机场、火车站的候车区能撑一夜，有厕所也有电源。但没有任何官方数据说这样安全。财物贴身放好，不接陌生人递的吃喝，别去偏僻角落。桥洞、河边、工地夜里不能睡。救助站免费管吃住，优先去那儿。', '安全风险是真的存在。财物贴身放好，不接陌生人递的饮料和食物，避开偏僻角落。夜间不要露宿在桥洞、河边、工地。极端天气里露宿会出人命。第 4 条的救助站免费管吃住，先去那里。有些场所半夜会清场，不要和安保起冲突。', NULL, NULL, NULL, '机场、火车站的候车区通常不花钱。快餐店、网吧得花点钱消费。睡不踏实，财物有被偷的风险。难在一整夜都不敢真睡。', '能撑过一夜，有厕所，也能充电。没有官方数字', '安全风险是真的存在。财物贴身放好，不接陌生人递的饮料和食物，避开偏僻角落。夜间不要露宿在桥洞、河边、工地。极端天气里露宿会出人命。第 4 条的救助站免费管吃住，先去那里。有些场所半夜会清场，不要和安保起冲突。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","C 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s7-22', 'concept_archive_s7-22', 'claim_archive_s7-22', 'action', 'life_archive', '被欠了工钱，先分清雇你的是谁：没执照的作坊和包工头照样找劳动监察，给家庭或个人干私活才去法院', '7. 没钱的时候怎么活', '没办执照的作坊、店铺，欠了工资照样能投诉劳动监察、申请劳动仲裁，老板本人也能被追。包工头转包工地上的活欠了钱，由总包或建设单位来付。只有给家庭或个人干私活，比如当保姆，才不算劳动争议，要去法院起诉。', '按这个顺序判断。先看活是不是从公司或工地转下来的，是就找发包的公司或者总包。工地上的工资专用账户和总包先行清偿，见第 2 条（被欠薪先投诉劳动监察）。再看对方是不是在做生意：开店、办厂、开作坊的，有没有执照都走监察和仲裁，仲裁时把老板本人一起列上。剩下给家庭或个人干私活的，才去法院。去法院要自己起诉、自己举证，一审普通程序 6 个月起。律师费不在法院判给输家承担的诉讼费用里，请律师要自己出，打不起可以申请法律援助，见第 3 条（法律援助）。手上有欠条的可以先申请支付令，金额小的走小额诉讼，见第 8 节第 22 条（二手交易被骗、小额诉讼）。诉讼时效 3 年，见第 8 节第 19 条（维权有期限）。走哪条路都不保证钱到账，对方没有财产的，赢了也拿不到。', NULL, NULL, NULL, '不花钱。先弄清三件事：对方是不是在开店办厂做生意，活是不是从公司或工地转包下来的，你是不是给人家里干活。对方有没有执照，可以在国家企业信用信息公示系统上查。', '劳动合同法第二条把用人单位限定为企业、个体经济组织、民办非企业单位等组织，自然人不在其中。最高法的劳动争议司法解释列了几种不属于劳动争议的纠纷。一是家庭或者个人与家政服务人员之间的纠纷。二是个体工匠与帮工、学徒之间的纠纷。三是农村承包经营户与受雇人之间的纠纷。这几种要去法院按普通民事纠纷起诉，诉讼时效 3 年。没有营业执照的用人单位不在这个例外里。劳动合同法第九十三条规定，不具备合法经营资格的用人单位，劳动者已经付出劳动的，该单位或者其出资人应当支付劳动报酬、经济补偿、赔偿金。该解释第二十九条规定，劳动者与未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位发生争议的，应当将用人单位或者其出资人列为当事人。劳动保障监察条例第三十三条规定，对无营业执照或者已被依法吊销营业执照、有劳动用工行为的，由劳动保障行政部门实施劳动保障监察。个人承包经营违法招用劳动者、给劳动者造成损害的，发包的组织和个人承包经营者承担连带赔偿责任（劳动合同法第九十四条）。建设单位或者施工总承包单位把工程发包、分包给个人或者不具备合法经营资格的单位，导致拖欠农民工工资的，由建设单位或者施工总承包单位清偿（保障农民工工资支付条例第三十六条）（全国）', '按这个顺序判断。先看活是不是从公司或工地转下来的，是就找发包的公司或者总包。工地上的工资专用账户和总包先行清偿，见第 2 条（被欠薪先投诉劳动监察）。再看对方是不是在做生意：开店、办厂、开作坊的，有没有执照都走监察和仲裁，仲裁时把老板本人一起列上。剩下给家庭或个人干私活的，才去法院。去法院要自己起诉、自己举证，一审普通程序 6 个月起。律师费不在法院判给输家承担的诉讼费用里，请律师要自己出，打不起可以申请法律援助，见第 3 条（法律援助）。手上有欠条的可以先申请支付令，金额小的走小额诉讼，见第 8 节第 22 条（二手交易被骗、小额诉讼）。诉讼时效 3 年，见第 8 节第 19 条（维权有期限）。走哪条路都不保证钱到账，对方没有财产的，赢了也拿不到。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"7. 没钱的时候怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-1', 'concept_archive_s8-1', 'claim_archive_s8-1', 'action', 'life_archive', '出了交通事故先停车、救人、报警，不要跑', '8. 别把自己搭进去：法律与财产安全', '跑了，这起事故就默认算你全责。驾照吊销，这辈子都不能再考。还有更现实的一层：车损险和三者险对逃逸一律不赔，几十万的赔偿全要自己掏。留在现场救人、报警，最多耗掉一两个小时。', '有人受伤，先救人，再报警。为了救人必须挪动现场的，先把车和人原来的位置标出来。「撞了一下没感觉就开走」，事后也可能被算成逃逸，拿不准就报警。保险那一条引的是示范条款，它是保险行业的统一模板，你实际能赔到什么，以自己手里的保单为准。', NULL, NULL, NULL, '不花钱。停车、开双闪、救人、打电话报警，等交警最多耗掉一两个小时。小事故要是没人受伤、双方对事实也没争议，就先拍照。再记下对方的姓名、电话、车牌、驾驶证号、保险凭证号和撞到的部位。双方签字后可以先撤离现场，再自己协商。', '跑了的那一方，要承担这次事故的全部责任。只有你能证明对方也有错，责任才可能减轻一点。跑了还要吊销驾驶证，而且这辈子都不能再考。如果这起事故构成交通肇事罪，跑了判 3 到 7 年。如果因为跑了导致人死亡，判 7 年以上。保险也不管：商业车险里的车损险和三者险，遇上「交通肇事逃逸」「故意破坏、伪造现场、毁灭证据」一律不赔，几十万的赔偿要你自己全掏（全国）', '有人受伤，先救人，再报警。为了救人必须挪动现场的，先把车和人原来的位置标出来。「撞了一下没感觉就开走」，事后也可能被算成逃逸，拿不准就报警。保险那一条引的是示范条款，它是保险行业的统一模板，你实际能赔到什么，以自己手里的保单为准。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-2', 'concept_archive_s8-2', 'claim_archive_s8-2', 'action', 'life_archive', '发现被骗，立刻打 110 或 96110 要求止付，别先自己查', '8. 别把自己搭进去：法律与财产安全', '钱刚转出去的那一小段时间，是唯一的窗口。这段时间警方可以紧急止付、快速冻结，银行必须配合。等钱被层层转走、分散开，就基本追不回来了。所以先打 110 或者 96110，别自己先去查、先去问。96110 打进来的是警察在劝阻你，要接。', '凡是自称公检法、让你把钱转到「安全账户」的，都是骗局。法律只写了「建立止付冻结制度」，意思是让银行把钱扣住。能追回多少，要看你报警的时候钱还在不在账上。「国家反诈中心」App 和 96110 的介绍引自福建省公安厅的页面，公安部网站的原文页打不开。', NULL, NULL, NULL, '不花钱。打一个电话，说清转账的时间、金额和对方的账号。把转账截图和聊天记录留好。', '公安机关有权对涉案的资金做即时查询、紧急止付、快速冻结。银行和支付机构必须配合。冻结住的钱，按程序返还给被害人。钱一旦被转走、分散开，追回的概率大幅下降，所以止付越早越有效。96110 是全国统一的反诈预警热线，来电是警方在劝阻你，务必接（全国，2022 年 12 月起）', '凡是自称公检法、让你把钱转到「安全账户」的，都是骗局。法律只写了「建立止付冻结制度」，意思是让银行把钱扣住。能追回多少，要看你报警的时候钱还在不在账上。「国家反诈中心」App 和 96110 的介绍引自福建省公安厅的页面，公安部网站的原文页打不开。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-3', 'concept_archive_s8-3', 'claim_archive_s8-3', 'action', 'life_archive', '记住反诈硬规则：来电不轻信、信息不透露、链接不点击、转账多核实，七种最常见的骗局都是这个形状', '8. 别把自己搭进去：法律与财产安全', '凡是让你转账、共享屏幕、下载陌生 App、点链接、报验证码的，先挂断，再用官方号码打回去核实。刷单返利、虚假投资理财、网络贷款、冒充客服、冒充公检法、杀猪盘、色诱刷单这七类最常见，都是要你先转钱。事前认出来，比事后追钱便宜得多。', '自称公检法、客服、领导、平台风控，要你「配合调查」「取消会员」「刷单返利」「投资内幕」的，都是同一个套路。真贷款不需要交保证金，公检法没有「安全账户」，这两句记住就能挡掉一大半。定 B 级是因为这句口诀只是官方的宣传口径，没有「记住之后少被骗多少」的数字。口诀和七类拆解取自省级公安厅的页面。公安部 2026 年通报的 10 类高发诈骗还包括冒充电商物流客服、贷款征信、网络游戏虚假交易、网络婚恋交友、冒充领导熟人和机票退改签，套路都一样，最后都要你转钱。熟人当面找你「帮忙刷个脸」办贷款，不让你转钱，却让你背债，见第 45 条（帮忙刷个脸）。做生意时撞上的代运营骗局，见第 12 节第 24 条（代运营网店）。', NULL, NULL, NULL, '不花钱。把「三不一多」记住，读一遍下面那七类，再装一个「国家反诈中心」App，96110 来电必接。凡是让你转账、共享屏幕、下载陌生 App、点链接、报验证码的，先挂断，再打官方电话核实。难在对方往往催得很急，你要顶住这股催促先挂断。', '法律要求政府和有关部门把各类电信网络诈骗的手法讲给大家。公安机关会同金融、电信、网信部门建立预警劝阻系统，发现可能要被骗的人就及时劝阻。96110 就是这条全国统一的预警劝阻热线，来电要接。公安部 2026 年 6 月通报，最高发的 10 类诈骗占了全部电诈案件的 85%。刷单返利发案最多，占 25%。虚假网络投资理财损失最大，约占全部损失的 40%。福建省公安厅逐类拆解的识别特征如下。刷单返利：「喊你一起赚钱的大概率是想赚你的钱」，任务单做不完就不退本金。虚假投资理财：群里「水军」晒收益，先给小额返利再让你加大投入，提现要「缴税」。网络贷款：「贷款并不需要交保证金、做银行流水账，一旦遇上了，一定是假的」。冒充客服：说你开了会员要自动扣费、影响征信，逼你转账取消。冒充公检法：「公检法机关不存在所谓的『安全账户』，凡是通过电话、QQ、微信、网络等办案、做笔录的『公检法机关』，都是诈骗」。杀猪盘：「对于从未见过面，只见到照片或者视频的『恋人』，不可轻信」，永远不视频不见面却常有急事要钱。色诱刷单：约见面先「做任务」，钱越交越多。事前认出来，比事后止付便宜得多。止付能追回多少，取决于报警时钱还在不在账上，止付怎么做见第 2 条（打 110 或 96110 要求止付）（全国，2022 年 12 月起）', '自称公检法、客服、领导、平台风控，要你「配合调查」「取消会员」「刷单返利」「投资内幕」的，都是同一个套路。真贷款不需要交保证金，公检法没有「安全账户」，这两句记住就能挡掉一大半。定 B 级是因为这句口诀只是官方的宣传口径，没有「记住之后少被骗多少」的数字。口诀和七类拆解取自省级公安厅的页面。公安部 2026 年通报的 10 类高发诈骗还包括冒充电商物流客服、贷款征信、网络游戏虚假交易、网络婚恋交友、冒充领导熟人和机票退改签，套路都一样，最后都要你转钱。熟人当面找你「帮忙刷个脸」办贷款，不让你转钱，却让你背债，见第 45 条（帮忙刷个脸）。做生意时撞上的代运营骗局，见第 12 节第 24 条（代运营网店）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-4', 'concept_archive_s8-4', 'claim_archive_s8-4', 'action', 'life_archive', '视频里看见脸、电话里听见声音都不算核实，涉及转账先挂断，用自己通讯录里的旧号码打回去', '8. 别把自己搭进去：法律与财产安全', '看见脸、听见声音，都不算核实。只要涉及转账就先挂断，再用自己通讯录里存的旧号码打回去，或者找共同认识的人问一句。对方说「信号不好」「在开会」，不肯当面视频，直接当骗局处理。', '回拨要用自己通讯录里存的旧号码。不要回拨来电显示的那个号码，也不要用对方在聊天里发来的新号码。对方以「信号不好」「在开会」为由不肯当面视频、不肯做指定动作的，直接当骗局处理。动作验证法只是辅助，AI 一直在变好，唯一稳的是第三条核实。已经转了钱，见本节第 2 条（立刻打 110 要求止付）。防止自己的人脸和声音被采集见第 14 节。定 B 级是因为官方给的是识别办法和案例，没有「按这个方法核实后被骗率下降多少」的数字。公安部官网（mps.gov.cn）这次仍然全站 521 打不开，公安部网安局和刑侦局的原文取自福建省公安厅的转载页。', NULL, NULL, NULL, '不花钱。多打一个电话，多等几分钟。平时少在公开账号上发正脸视频和大段语音。难在对方常常催得很急，你要忍住不当场转账。', '公安部网安局给了三条办法。第一条是动作验证：请对方做一个连贯的转头动作，或者用手掌完全遮住脸再快速移开。原文说「目前的 AI 技术在模拟这些复杂的面部遮挡和光影变化时，容易出现卡顿、模糊或扭曲」。第二条是听声音细节：「AI 生成的语音有时会缺乏自然的呼吸停顿、情感起伏，或者带有轻微的机械感、背景杂音异常」。第三条是多渠道核实。原文说这是「最核心的一招」：「挂断后直接拨打对方常用且你熟悉的电话号码（不要回拨可疑来电号码），或者通过你们共同认识的第三人进行侧面核实」。口诀是「视频语音莫轻信，动作验证多核实」。法律上，换脸换声早就被禁止用于诈骗。人脸生成、人脸替换、合成人声、仿声这几类服务，平台必须打上显著标识。任何组织和个人不得恶意删除、篡改、伪造、隐匿这个标识。但守规矩的是平台，骗子不会加，所以「没看到 AI 标识」不能反过来当成对方是真人的证据。公安部刑侦局公布过一起案件。14 人团伙被查获合成动态人脸视频 5 万多条，公民个人信息 50 多万条。警方还扣押了云服务器 60 台（全国，标识义务自 2025 年 9 月 1 日起）', '回拨要用自己通讯录里存的旧号码。不要回拨来电显示的那个号码，也不要用对方在聊天里发来的新号码。对方以「信号不好」「在开会」为由不肯当面视频、不肯做指定动作的，直接当骗局处理。动作验证法只是辅助，AI 一直在变好，唯一稳的是第三条核实。已经转了钱，见本节第 2 条（立刻打 110 要求止付）。防止自己的人脸和声音被采集见第 14 节。定 B 级是因为官方给的是识别办法和案例，没有「按这个方法核实后被骗率下降多少」的数字。公安部官网（mps.gov.cn）这次仍然全站 521 打不开，公安部网安局和刑侦局的原文取自福建省公安厅的转载页。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-5', 'concept_archive_s8-5', 'claim_archive_s8-5', 'action', 'life_archive', '被指控或被传唤，先请律师，不私了、不删记录', '8. 别把自己搭进去：法律与财产安全', '被叫去问话的第一次，你就可以请律师了。律师要求见你，看守所最迟 48 小时内安排，谈话不会被听。跟这个案子无关的问题，你可以不答。', '不要私下去找对方，也不要去找他家里人。任何「私了」都可能被理解成你认了。聊天记录、通话记录、行程记录是你自证清白的材料，删掉等于把自己的证据也删了。记错了、举报的事后来查下来不成立，不算诬告陷害罪。本条对被指控的人不分男女。展开的三条见本节第 33 条（追究捏造事实的一方）、第 34 条（证据不足应当判无罪与申诉再审）、第 35 条（羁押后的国家赔偿按天算）。', NULL, NULL, NULL, '律师费从几千元起。经济困难的可以向法律援助机构申请免费律师。被问话时只回答和本案有关的问题，其余交给律师。难在当场稳住，不急着自己解释。', '从第一次讯问起，或者从被采取强制措施（被限制人身自由）起，你就有权委托律师。案子还在公安手里侦查的这一段，只能委托律师，不能请律师以外的人当辩护人。律师提出会见，看守所最迟 48 小时内安排，会见不被监听。不得强迫任何人证实自己有罪。和本案无关的问题，你有权拒绝回答。传唤、拘传一次最长 12 小时，特别重大复杂的最长 24 小时。传唤是通知你去问话，拘传是强制把你带去问话。不得连着传唤，把人变相关住。捏造事实诬告别人、想让他被追究刑事责任的，判 3 年以下，造成严重后果的判 3 到 10 年。被拘留、逮捕之后又撤案、不起诉或者判无罪的，可以申请国家赔偿，每天按上一年度全国职工日平均工资计算（全国）', '不要私下去找对方，也不要去找他家里人。任何「私了」都可能被理解成你认了。聊天记录、通话记录、行程记录是你自证清白的材料，删掉等于把自己的证据也删了。记错了、举报的事后来查下来不成立，不算诬告陷害罪。本条对被指控的人不分男女。展开的三条见本节第 33 条（追究捏造事实的一方）、第 34 条（证据不足应当判无罪与申诉再审）、第 35 条（羁押后的国家赔偿按天算）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-6', 'concept_archive_s8-6', 'claim_archive_s8-6', 'action', 'life_archive', '出了事主动去说清楚：自首最多能减四成刑，「躲过追诉期」这条路是堵死的', '8. 别把自己搭进去：法律与财产安全', '自首最多能把刑期减掉四成，情节较轻的可以直接不罚。被找上门之后才如实交代，最多也能减两成。跑掉、拒不承认，这些都换不来。指望躲几年让案子过期也不成立：已经立案的，你躲着的这段时间不算进追诉期限。', '这条的受益人是自己。自首只是从轻情节，罪照样要定，减多少由法院定，量刑意见对严重暴力犯罪、毒品犯罪的从宽幅度要求从严掌握。交通事故另有一套算法：留在现场、救人、向公安机关报告的算自动投案，但因为这些本来就是法定义务，从宽幅度要从严掌握；跑了以后再投案也还算自首，只是要按更重的那一档法定刑当基准，再决定减不减、减多少，怎么做见本节第 1 条（出了交通事故先停车、救人、报警）。先请律师和如实供述不冲突，见本节第 5 条（被指控先请律师）：律师帮你核对的是笔录写得对不对，不是帮你编说法。', NULL, NULL, NULL, '不花钱。自己去公安机关投案，或者留在原地打电话报警，再把事情如实说一遍。难的是顶住「再等等看，说不定没人查」这个念头。', '刑法第六十七条：犯罪以后自动投案、如实供述自己罪行的，是自首。对自首的，可以从轻或者减轻处罚，其中犯罪较轻的可以免除处罚。没有投案但如实供述自己罪行的（坦白），可以从轻处罚；因如实供述避免特别严重后果发生的，可以减轻处罚。两高的量刑指导意见给了明码幅度。基准刑就是先按案情算出来的那个刑期，下面的百分比都在它之上往下减。自首可以减少基准刑的 40% 以下，犯罪较轻的可以减少 40% 以上或者依法免除处罚。坦白里，如实供述自己罪行的减少 20% 以下，如实供述司法机关尚未掌握的同种较重罪行的减少 10% 到 30%，因如实供述避免特别严重后果发生的减少 30% 到 50%。认罪认罚减少 30% 以下，同时有自首、重大坦白、退赃退赔、赔偿谅解等情节的减少 60% 以下，犯罪较轻的减少 60% 以上或者依法免除处罚。追诉期限按法定最高刑分四档：5 年、10 年、15 年、20 年（刑法第八十七条）。但刑法第八十八条写明，检察院、公安机关、国家安全机关立案侦查，或者法院受理案件以后，逃避侦查或者审判的，不受追诉期限的限制（全国，量刑幅度自 2021 年 7 月 1 日起施行）', '这条的受益人是自己。自首只是从轻情节，罪照样要定，减多少由法院定，量刑意见对严重暴力犯罪、毒品犯罪的从宽幅度要求从严掌握。交通事故另有一套算法：留在现场、救人、向公安机关报告的算自动投案，但因为这些本来就是法定义务，从宽幅度要从严掌握；跑了以后再投案也还算自首，只是要按更重的那一档法定刑当基准，再决定减不减、减多少，怎么做见本节第 1 条（出了交通事故先停车、救人、报警）。先请律师和如实供述不冲突，见本节第 5 条（被指控先请律师）：律师帮你核对的是笔录写得对不对，不是帮你编说法。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-7', 'concept_archive_s8-7', 'claim_archive_s8-7', 'action', 'life_archive', '喝了酒就不碰方向盘，包括电动车和「挪一下车」', '8. 别把自己搭进去：法律与财产安全', '酒后开车，扣证 6 个月，罚一两千。再犯就拘留加吊销。醉驾直接吊销，5 年内不能重考，还要按危险驾驶罪追刑责，留下案底，影响政审和一部分职业。保险也不管：喝了酒开车，车险一律不赔。「就挪一下车」也算驾驶。', '醉驾是刑事犯罪，会留案底，影响本人政审和一部分职业资格。「饮酒」和「醉酒」按血液里的酒精含量划线，具体界线由国家标准规定。本节没有核实这个数值，别靠感觉估算自己到了哪一档。', NULL, NULL, NULL, '代驾或者打车几十元。聚会之前先说好今天谁不喝。难在场面上被劝酒时顶回去。', '酒后驾车，暂扣驾驶证 6 个月，罚 1000 到 2000 元。再犯的，拘留 10 日以下并吊销驾驶证。醉驾直接吊销驾驶证，5 年内不得重考，并按危险驾驶罪追究刑事责任，判拘役并罚钱，拘役就是短期关押。开营运车的更重：酒驾拘留 15 日、罚 5000 元、5 年禁驾；醉驾 10 年禁驾，而且这辈子不能再开营运车。酒后或者醉驾造成重大事故、构成犯罪的，终生禁驾。商业车险对饮酒、吸毒后驾车一律不赔（全国）', '醉驾是刑事犯罪，会留案底，影响本人政审和一部分职业资格。「饮酒」和「醉酒」按血液里的酒精含量划线，具体界线由国家标准规定。本节没有核实这个数值，别靠感觉估算自己到了哪一档。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-8', 'concept_archive_s8-8', 'claim_archive_s8-8', 'action', 'life_archive', '不把银行卡、手机卡、支付账号借给任何人，「跑分」不是兼职', '8. 别把自己搭进去：法律与财产安全', '把银行卡、手机卡、支付账号租给、借给、卖给别人，这件事本身就违法。罚违法所得的 1 到 10 倍，没有所得的最高罚 20 万元，情节严重的拘留 15 日，还会被记入信用记录、限制账户功能。要是明知对方拿去犯罪还帮着收钱转钱，就是帮信罪，判 3 年以下。', '说「我不知道他拿卡去干什么」挡不住。办案时会从外在情形反推你知不知情：收过好处费、流水明显不正常，都可能算你知道。卡被人用来收赃款的，就算你最后不构成犯罪，账户也会被冻结，本人也会被惩戒。替别人刷脸、念验证码过实名核验，罚则和这条相同，见第 45 条（帮忙刷个脸）。', NULL, NULL, NULL, '不花钱。有人说「借卡走个账，给你几百块」，拒绝就行。', '出租、出借、买卖电话卡、银行账户、支付账户、互联网账号，这件事本身就是违法。没收违法所得，再罚违法所得的 1 到 10 倍。没有违法所得的，最高罚 20 万元。情节严重的，拘留 15 日以下。还可能被记入信用记录、限制账户功能、停掉非柜面业务（只能去柜台办）。明知别人用网络实施犯罪，还给他提供支付结算这类帮助，情节严重的，构成帮助信息网络犯罪活动罪（简称帮信罪），判 3 年以下并处罚金（全国）', '说「我不知道他拿卡去干什么」挡不住。办案时会从外在情形反推你知不知情：收过好处费、流水明显不正常，都可能算你知道。卡被人用来收赃款的，就算你最后不构成犯罪，账户也会被冻结，本人也会被惩戒。替别人刷脸、念验证码过实名核验，罚则和这条相同，见第 45 条（帮忙刷个脸）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-9', 'concept_archive_s8-9', 'claim_archive_s8-9', 'action', 'life_archive', '每年免费查两次自己的征信报告，看有没有不是自己办的贷款和卡', '8. 别把自己搭进去：法律与财产安全', '你每年可以在网上免费查两次自己的信用报告，十分钟就能查完。用人民银行征信中心官网或者手机银行查，别用第三方的「查征信」App，那类 App 在收集你的信息。不良记录从这件事结束那天起留 5 年，过了就该删。有异议可以提，20 天内必须书面答复你。', '身份证被人冒用去网贷、办卡，本人往往要到买房贷款被拒的时候才发现，那时已经拖了好几年。查询的入口是中国人民银行征信中心官网，或者手机银行。别用第三方的「查征信」App，那类 App 本身就在收集你的信息。帮熟人「刷个脸、做个见证」之后，尤其要查一次，见第 45 条（帮忙刷个脸）。', NULL, NULL, NULL, '不花钱。在网上查，十分钟就能查完。', '行政法规写着「个人信息主体有权每年两次免费获取本人的信用报告」，你每年可以免费查自己两次。不良信息的保存期限是「自不良行为或者事件终止之日起为 5 年；超过 5 年的，应当予以删除」。对报告有异议的，你可以提出来，征信机构或者提供这条信息的机构应当在收到异议之日起 20 日内书面答复你', '身份证被人冒用去网贷、办卡，本人往往要到买房贷款被拒的时候才发现，那时已经拖了好几年。查询的入口是中国人民银行征信中心官网，或者手机银行。别用第三方的「查征信」App，那类 App 本身就在收集你的信息。帮熟人「刷个脸、做个见证」之后，尤其要查一次，见第 45 条（帮忙刷个脸）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-10', 'concept_archive_s8-10', 'claim_archive_s8-10', 'action', 'life_archive', '起了冲突先报警不动手，先动手的那个几乎一定吃亏', '8. 别把自己搭进去：法律与财产安全', '打人，拘留 5 到 10 日，罚五百到一千。结伙打、打老人孕妇孩子残疾人、多次打人，拘留 10 到 15 日，罚一两千。打成轻伤就是刑事案件，判 3 年以下，重伤判 3 到 10 年。两个人对着打不算正当防卫，先动手的那个几乎一定吃亏。退到人多的地方报警，比还手管用。', '治安管理处罚法 2025 年修订之后条款号全变了，殴打他人从旧法第四十三条改成了第五十一条，引用旧条号的资料已经过时。「打成轻伤就要判刑」里的轻伤怎么算，由鉴定标准定，本节没有核实。对方已经倒地，或者已经跑了，侵害就算停了，你再追上去打，就不算防卫。为了防身随身带刀、甩棍、电击器，平时被查到就要罚，见第 9 节第 26 条（别为了防身买甩棍、电击器）。', NULL, NULL, NULL, '不花钱。退到人多的地方报警，让对方的动作留在监控里。难在忍住不还嘴、不推搡。', '殴打他人或者故意伤害的，拘留 5 到 10 日，并罚 500 到 1000 元。结伙打、打老人孕妇儿童残疾人、多次打人或者一次打多人的，拘留 10 到 15 日，并罚 1000 到 2000 元。结伙斗殴按寻衅滋事处理，最高拘留 15 日并罚 2000 元，寻衅滋事就是无事生非、起哄闹事。故意伤害他人身体、构成犯罪的，判 3 年以下；把人打成重伤的，判 3 到 10 年。两个人对着打，法律上叫相互斗殴，不算正当防卫。但如果对方先动手、手段又明显过激，或者你已经努力躲开、对方还接着打，你还击一般会被认定为防卫。还手过了头才叫防卫过当，要同时满足两条：明显超过必要限度，并且造成重大损害。就算真的过当，也应当减轻或者免除处罚（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', '治安管理处罚法 2025 年修订之后条款号全变了，殴打他人从旧法第四十三条改成了第五十一条，引用旧条号的资料已经过时。「打成轻伤就要判刑」里的轻伤怎么算，由鉴定标准定，本节没有核实。对方已经倒地，或者已经跑了，侵害就算停了，你再追上去打，就不算防卫。为了防身随身带刀、甩棍、电击器，平时被查到就要罚，见第 9 节第 26 条（别为了防身买甩棍、电击器）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-11', 'concept_archive_s8-11', 'claim_archive_s8-11', 'action', 'life_archive', '躲不掉的侵害可以还手，但只打正在动手的那个人，他停你就停', '8. 别把自己搭进去：法律与财产安全', '对方正在侵害你或者别人的时候，你动手制止、把他打伤，不负刑事责任。对方正在行凶、杀人、抢劫、强奸、绑架，打伤打死也不算过当。但只能打正在动手的那个人，他停你就停。最后认定站你这边，你也可能先被立案、先被关上几天。', '默认的动作还是第 10 条说的退开报警（起了冲突先报警不动手）。两个人对着打不算防卫，对方倒地或者跑了你还追着打也不算。只有退无可退的那一刻才考虑还手。事后有三件事要做。第一，报警之后别离开现场。第二，赶紧把监控和目击者保住，指导意见要求公安第一时间去调现场的录像录音、第一时间问目击者。第三，被警察正式问话之前先请律师，见第 5 条（被指控先请律师）。最后案子撤了、不起诉或者判无罪的，被关的那些日子可以按天申请国家赔偿，见第 35 条（羁押后的国家赔偿）。为别人出手防卫，法律上同样允许。但空着手去插手陌生人之间的打斗，风险要另算，见第 13 节第 37 条（撞见一群人打架）。这条的受益人主要是自己和家人。', NULL, NULL, NULL, '律师费几千元起，经济困难的可以申请法律援助。代价主要在事后：常常先被按故意伤害立案，要配合调查，甚至先被关上十几天。难在这段日子里稳住不乱。', '刑法规定了什么算正当防卫。国家、公共利益、自己或者别人的人身、财产和其他权利，正在被不法侵害。这时候动手制止、把正在侵害的人打伤，属于正当防卫，不负刑事责任。同一条还写着：「正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚」。另有一款：「对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任」。两高一部的指导意见把边界说得更细。认定防卫过当，要同时具备「明显超过必要限度」和「造成重大损害」两条，缺一不可。「造成重大损害」是指把不法侵害人打成重伤或者打死，造成轻伤以及更轻的伤不算。只有不法侵害人确实已经失去侵害能力，或者确实已经放弃侵害，才算侵害结束。防卫必须针对不法侵害人本人。对显著轻微的不法侵害，在看得出来只是轻微侵害的情况下，直接用足以致人重伤或者死亡的方式制止的，不认定为防卫行为。过程成本有官方案例。检例第 47 号于海明案：2018 年 8 月 27 日当晚，公安以「故意伤害案」立案侦查。9 月 1 日，昆山市公安局依据刑法第二十条第三款认定为正当防卫，撤销了案件。检例第 45 号陈某案：一名学生被 9 人围殴，持刀反击致 3 人重伤。公安以涉嫌故意伤害立案侦查，把他刑事拘留。检察机关认定属于正当防卫，不批准逮捕，公安才把人放了。被拘留之后公安认为需要逮捕的，应当在 3 日内提请检察院审查批准（报检察院批不批捕）。特殊情况可以延长 1 至 4 日。流窜作案、多次作案、结伙作案的重大嫌疑分子，可以延长到 30 日。检察院再在 7 日内作出决定（全国）', '默认的动作还是第 10 条说的退开报警（起了冲突先报警不动手）。两个人对着打不算防卫，对方倒地或者跑了你还追着打也不算。只有退无可退的那一刻才考虑还手。事后有三件事要做。第一，报警之后别离开现场。第二，赶紧把监控和目击者保住，指导意见要求公安第一时间去调现场的录像录音、第一时间问目击者。第三，被警察正式问话之前先请律师，见第 5 条（被指控先请律师）。最后案子撤了、不起诉或者判无罪的，被关的那些日子可以按天申请国家赔偿，见第 35 条（羁押后的国家赔偿）。为别人出手防卫，法律上同样允许。但空着手去插手陌生人之间的打斗，风险要另算，见第 13 节第 37 条（撞见一群人打架）。这条的受益人主要是自己和家人。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-12', 'concept_archive_s8-12', 'claim_archive_s8-12', 'action', 'life_archive', '跟谁结了怨——被欠薪、被开除、被坑了钱——走投诉、仲裁、起诉，别去找人算账', '8. 别把自己搭进去：法律与财产安全', '走法定路径，最坏的结果是钱要不回来。去报复，结果是钱照样要不回来，还要自己抵命。无锡那起案子：徐某金没拿到毕业证、又不满实习报酬，持刀行凶致 8 死 17 伤，判死刑并已执行。欠薪走投诉和仲裁，2024 年全国靠这条给 65.4 万人追回了 86.5 亿元。', '还在上学的实习生，一般不算和单位建立了劳动关系。实习报酬要不到，只能找学校协调，或者去法院起诉，走不了劳动仲裁那条路。给家庭或个人干私活被欠了钱，也一样要去法院，见第 7 节第 22 条（先分清雇你的是谁）。被欠工资了具体怎么投诉、怎么仲裁，见第 7 节第 2 条。讨债的红线见第 9 节第 15 条（要债不扣人、不关人）。走法定路径也可能要不回钱，因为案子结了不等于钱到账。去报复，钱照样要不回来，还要自己抵命。', NULL, NULL, NULL, '不花钱，投诉和仲裁都不收费。要跑一两趟，等上几个月。难在这几个月里忍住不动手。', '法定路径有官方数字。2024 年全国劳动监察查处 13.7 万件，为 65.4 万人追回工资 86.5 亿元。还有 998 人因为拒不支付劳动报酬罪获刑。欠薪怎么投诉劳动监察、怎么申请劳动仲裁，见第 7 节第 2 条。报复路径的价目写在刑法第二百三十二条：「故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑」。官方案例：徐某金考试不合格，没拿到毕业证书，又对实习报酬不满。2024 年 11 月 16 日，他回无锡工艺职业技术学院持刀行凶，致 8 人死亡、17 人受伤。一审以故意杀人罪判处死刑、剥夺政治权利终身，2025 年 1 月 20 日经最高人民法院核准执行。他不满的是学校和那笔报酬，受害的却是同学，那笔报酬他也一分没拿到（全国）', '还在上学的实习生，一般不算和单位建立了劳动关系。实习报酬要不到，只能找学校协调，或者去法院起诉，走不了劳动仲裁那条路。给家庭或个人干私活被欠了钱，也一样要去法院，见第 7 节第 22 条（先分清雇你的是谁）。被欠工资了具体怎么投诉、怎么仲裁，见第 7 节第 2 条。讨债的红线见第 9 节第 15 条（要债不扣人、不关人）。走法定路径也可能要不回钱，因为案子结了不等于钱到账。去报复，钱照样要不回来，还要自己抵命。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-13', 'concept_archive_s8-13', 'claim_archive_s8-13', 'action', 'life_archive', '再恨也别对不相干的人下手：驾车冲撞人群、在公共场所行凶按以危险方法危害公共安全定罪，起刑三年，死了人就是死刑', '8. 别把自己搭进去：法律与财产安全', '驾车冲撞人群、在公共场所行凶，按以危险方法危害公共安全定罪。一个人都没伤着，也是三年起。死了人就是十年以上、无期或者死刑。珠海那起：樊维秋不满离婚财产分割，开车冲进体育中心正在锻炼的人群，致 35 死 43 伤，判死刑并已执行。', '「反正我也不想活了」在量刑上不是折扣。最高人民法院 2025 年工作报告对这类案件的口径是「对挑战法律和道德底线的罪大恶极者，坚决依法从严从重从快惩处」。只是放话也已经违法。放话要放火、爆炸、投毒这类危害公共安全的事，把公共秩序搅乱了的，拘留 5 到 10 日，还可以罚 1000 元以下。写恐吓信，或者用别的办法威胁别人人身安全，同样违法。这种要拘留 5 日以下，或者罚 1000 元以下（治安管理处罚法 2026 年 1 月 1 日起施行）。念头已经到这一步的，看第 14 条（冒出「拉个垫背的」这种念头当急症处理）。', NULL, NULL, NULL, '不花钱。难在气头上把这个念头压住。', '刑法第一百一十四条：「放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑」。一个人都没伤着，也是三年起。第一百一十五条：致人重伤、死亡，或者使公私财产遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。官方案例：樊维秋因为婚姻破裂、生活失意，又不满离婚财产分割的结果，「决意通过驾车冲撞人群方式发泄私愤」。2024 年 11 月 11 日晚，他驾车冲入珠海市体育中心正在锻炼的人群，致 35 人死亡、43 人受伤。一审以以危险方法危害公共安全罪判处死刑、剥夺政治权利终身，2025 年 1 月 20 日经最高人民法院核准执行。被撞的是他不认识的跑步者（全国）', '「反正我也不想活了」在量刑上不是折扣。最高人民法院 2025 年工作报告对这类案件的口径是「对挑战法律和道德底线的罪大恶极者，坚决依法从严从重从快惩处」。只是放话也已经违法。放话要放火、爆炸、投毒这类危害公共安全的事，把公共秩序搅乱了的，拘留 5 到 10 日，还可以罚 1000 元以下。写恐吓信，或者用别的办法威胁别人人身安全，同样违法。这种要拘留 5 日以下，或者罚 1000 元以下（治安管理处罚法 2026 年 1 月 1 日起施行）。念头已经到这一步的，看第 14 条（冒出「拉个垫背的」这种念头当急症处理）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-14', 'concept_archive_s8-14', 'claim_archive_s8-14', 'action', 'life_archive', '冒出「拉个垫背的」「同归于尽」这种念头，当急症处理：离开现场，把车钥匙和刀交给别人，打 12356', '8. 别把自己搭进去：法律与财产安全', '这类念头从冒出来到动手，窗口很短。82 个自杀未遂的人里，47.6% 说从第一次起念到动手不超过 10 分钟。所以要做的不是「想通」，而是先把方向盘、刀、燃气阀、绳子和自己隔开一步，把这十分钟熬过去。然后打 12356。', '定 B 级的原因是，这两项证据都出自研究自杀的文献，套到「想伤害别人的冲动」上并没有直接研究。Deisenhammer 那一项还只有 82 个人，只在一家医院做。状态不对的时候别开车，也别去值那种要替别人安全负责的班，先交班再说。想伤害自己的，见第 1 节第 25 条（有自杀念头时打 12356）。情绪低落时先做什么，见第 3 节第 18 条。', NULL, NULL, NULL, '不花钱。难在承认自己此刻不对劲，也难在把东西交到别人手上。', '这类念头到动手的窗口很短。对 82 名自杀未遂者在入院三天内做的访谈里，47.6% 的人说，从第一次冒出念头到实施不超过 10 分钟。一项 10 年系统综述（把十年间的研究合起来梳理一遍）认为，限制致死手段的证据在持续增强。镇痛药管控之后，与之相关的自杀下降 43%。跳楼热点加了防护之后，自杀下降 86%（79% 到 91%）。把方向盘、刀、燃气阀、绳子隔开一步，等的就是这十分钟过去。12356 是全国统一心理援助热线，每天接听不少于 18 小时（全国，2025 年 5 月 1 日起）', '定 B 级的原因是，这两项证据都出自研究自杀的文献，套到「想伤害别人的冲动」上并没有直接研究。Deisenhammer 那一项还只有 82 个人，只在一家医院做。状态不对的时候别开车，也别去值那种要替别人安全负责的班，先交班再说。想伤害自己的，见第 1 节第 25 条（有自杀念头时打 12356）。情绪低落时先做什么，见第 3 节第 18 条。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-15', 'concept_archive_s8-15', 'claim_archive_s8-15', 'action', 'life_archive', '身边人说出「谁也别想好过」「带着孩子一起走」，别当气话：近亲属可以直接送诊，公安接到报警也必须管', '8. 别把自己搭进去：法律与财产安全', '家里人说出「谁也别想好过」「带着孩子一起走」，近亲属可以直接把他送去医院，医院不得拒绝诊断。已经动过手、或者眼看要出事的，住院不需要本人同意。分不清是气话还是真的，先打 12356 问，或者报 110 让警察到场。替他瞒着不算帮他。', '按受益人口径，这条算的是同住的配偶、父母、子女。「谁也别想好过」里通常就包括你，而且法律把送诊的权利给的正是近亲属，外人想管也管不了，只能报警。送诊只用于真实的危险信号，吵架时的气话不算，也不能拿它把不听话的家人关进医院。同一部法律也写着：再查一次或者做了鉴定，认定人没有严重精神障碍的，医院不得留他住院（第三十五条）。分不清就先打 12356 问，或者报 110 让警察到场。德翼 9525 航班的调查结论是：当局和雇主没办法采取任何措施，阻止副驾驶当天飞行。原因是「无论是他本人，还是任何其他人——医生、同事或者家属——都没有告知他们」。机上 150 人全部遇难，其中 2 名飞行员、4 名乘务员、144 名乘客。', NULL, NULL, NULL, '挂号和诊查费几十到几百元。陪着跑一趟医院，要花半天到一天。难在开口劝他跟你去。', '精神卫生法第二十八条第二款写着：「疑似精神障碍患者发生伤害自身、危害他人安全的行为，或者有伤害自身、危害他人安全的危险的，其近亲属、所在单位、当地公安机关应当立即采取措施予以制止，并将其送往医疗机构进行精神障碍诊断」。同一条还规定：「医疗机构接到送诊的疑似精神障碍患者，不得拒绝为其作出诊断」。第二十九条要求医院把这类送来的人留在院里，立即指派精神科执业医师诊断，并及时出具结论。第三十条规定，住院治疗以自愿为原则。但有一种例外：诊断结论表明是严重精神障碍患者，而且「已经发生危害他人安全的行为，或者有危害他人安全的危险的」。这一类应当对他实施住院治疗，不以本人同意为前提。扬言伤人本身就可以直接报 110。写恐吓信，或者用其他办法威胁他人人身安全的，拘留 5 日以下或者罚 1000 元以下。扬言要实施放火、爆炸、投放危险物质等危害公共安全的犯罪行为，又把公共秩序搅乱了的，拘留 5 到 10 日，并可以罚 1000 元以下（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', '按受益人口径，这条算的是同住的配偶、父母、子女。「谁也别想好过」里通常就包括你，而且法律把送诊的权利给的正是近亲属，外人想管也管不了，只能报警。送诊只用于真实的危险信号，吵架时的气话不算，也不能拿它把不听话的家人关进医院。同一部法律也写着：再查一次或者做了鉴定，认定人没有严重精神障碍的，医院不得留他住院（第三十五条）。分不清就先打 12356 问，或者报 110 让警察到场。德翼 9525 航班的调查结论是：当局和雇主没办法采取任何措施，阻止副驾驶当天飞行。原因是「无论是他本人，还是任何其他人——医生、同事或者家属——都没有告知他们」。机上 150 人全部遇难，其中 2 名飞行员、4 名乘务员、144 名乘客。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-16', 'concept_archive_s8-16', 'claim_archive_s8-16', 'action', 'life_archive', '网上不骂人、不造谣、不转发没核实的事；被网暴先留证再报警', '8. 别把自己搭进去：法律与财产安全', '公开骂人或者造谣诽谤，拘留 5 日以下，或者罚 1000 元以下，情节较重的拘留 5 到 10 日。情节严重就构成侮辱罪、诽谤罪，判 3 年以下。转发不免责。反过来，你被网暴时，侮辱诽谤原则上要你自己去法院告，所以截图、录屏、存链接只能靠你自己。', '侮辱、诽谤这两个罪原则上「告诉的才处理」，就是得你自己去法院告。公安一般不主动立案，证据只能靠自己攒。但有两种例外。一是「严重危害社会秩序和国家利益的除外」，这种公安可以直接办（刑法第二百四十六条第二款）。二是在网上被诽谤、自己取证确实有困难的，法院可以要求公安帮着调查（同一条第三款，刑法修正案九新增）。转发了照样要担责，明知是假的还往外传，同样算「捏造事实」。自己被网暴之后怎么处置，见本节第 37 条（被网暴了先固证再挑路）。侮辱诽谤的条号由旧法第四十二条改成了新法第五十条。', NULL, NULL, NULL, '不花钱。发之前多想十秒。被攻击时截图、录屏，保存链接和账号 ID，先向平台投诉，再报警。难在被骂的时候忍住不回骂。', '公然侮辱别人，或者捏造事实诽谤别人的，拘留 5 日以下，或者罚 1000 元以下；情节较重的，拘留 5 到 10 日。多次发送侮辱恐吓信息、滋扰纠缠跟踪、偷拍并散布别人隐私的，同样这么罚。故意散布谣言、把公共秩序搅乱了的，拘留 5 到 10 日。情节严重的，构成侮辱罪、诽谤罪，判 3 年以下。通过网络诽谤的，受害人取证有困难，可以请法院要求公安协助（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', '侮辱、诽谤这两个罪原则上「告诉的才处理」，就是得你自己去法院告。公安一般不主动立案，证据只能靠自己攒。但有两种例外。一是「严重危害社会秩序和国家利益的除外」，这种公安可以直接办（刑法第二百四十六条第二款）。二是在网上被诽谤、自己取证确实有困难的，法院可以要求公安帮着调查（同一条第三款，刑法修正案九新增）。转发了照样要担责，明知是假的还往外传，同样算「捏造事实」。自己被网暴之后怎么处置，见本节第 37 条（被网暴了先固证再挑路）。侮辱诽谤的条号由旧法第四十二条改成了新法第五十条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-17', 'concept_archive_s8-17', 'claim_archive_s8-17', 'action', 'life_archive', '签字前把纸看完，不替人签字，不在空白纸上签', '8. 别把自己搭进去：法律与财产安全', '签了就算数，按手印和签名一样算数。「没看清」「以为是别的」在法庭上基本站不住。所以多花几分钟从头读到尾，看不懂的当场问，拍照留底。不替别人签，不在空白纸上签，身份证复印件写清用途。电子签和刷脸确认，同样算签字。', '「不替人签字、不签空白纸、身份证复印件写明用途」是经验做法，没有单独的官方文件。它们的目的是一样的：别让你的签名被拼进一份法律上成立、你又不得不认的合同里。电子签、刷脸确认同样算签字。熟人让你帮忙刷脸、签字办贷款的，见第 45 条（帮忙刷个脸）。', NULL, NULL, NULL, '不花钱。多花几分钟，把合同、借条、担保书、入职文件从头读到尾。看不懂的当场问，再拍照留底。难在当着对方的面慢慢看完。', '依法成立的合同受法律保护，对签字的双方都有约束力。签了就要按约定全面履行。民法典第四百九十条写着，用合同书订合同的，双方「签名、盖章或者按指印时合同成立」。按手印和签名、盖章是并列的三种办法，按了手印合同一样成立。「没看清」「以为是别的」在法庭上很难成立。不签，就不会背上不属于自己的债务和责任（全国）', '「不替人签字、不签空白纸、身份证复印件写明用途」是经验做法，没有单独的官方文件。它们的目的是一样的：别让你的签名被拼进一份法律上成立、你又不得不认的合同里。电子签、刷脸确认同样算签字。熟人让你帮忙刷脸、签字办贷款的，见第 45 条（帮忙刷个脸）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-18', 'concept_archive_s8-18', 'claim_archive_s8-18', 'action', 'life_archive', '借钱写清借条，替人担保前先想清楚自己愿不愿意替他还', '8. 别把自己搭进去：法律与财产安全', '借条要写全：出借人、借款人、金额、利率、期限、还款方式，双方签名。钱走转账，不给现金，写全了才好起诉。替人担保时看清有没有「连带」两个字。一般保证是等债权人先告了借款人、执行不到钱，才轮到你。写了连带责任保证，债权人可以直接找你要。', '借出去的钱，利息超过 4 倍 LPR 的那一部分法院不保护，见第 7 节。借条上写身份证号、注明「借款」是经验做法。担保书上有没有「连带」两个字，决定你是排在借款人后面，还是和他并排被要债，签之前看清楚。说好让你当担保人，实际签的却是借款合同，见第 45 条（借款人是你，不是担保人）。', NULL, NULL, NULL, '不花钱。用一张纸写清出借人、借款人、金额、利率、期限和还款方式，双方签名。钱走转账，留下痕迹，不给现金。', '借款合同应当采用书面形式，内容一般包括借款的种类、币种、用途、数额、利率、期限和还款方式。写全了才好起诉。担保合同没写清按哪种方式保证，或者写得不清楚的，按一般保证算。一般保证的担保人可以先等着：要债的人得先去起诉或者仲裁，再申请强制执行借款人的财产，执行完还是还不上，才轮到你替他还。反过来，签了「连带责任保证」就没有这层保护，要债的人可以直接找你要（全国）', '借出去的钱，利息超过 4 倍 LPR 的那一部分法院不保护，见第 7 节。借条上写身份证号、注明「借款」是经验做法。担保书上有没有「连带」两个字，决定你是排在借款人后面，还是和他并排被要债，签之前看清楚。说好让你当担保人，实际签的却是借款合同，见第 45 条（借款人是你，不是担保人）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-19', 'concept_archive_s8-19', 'claim_archive_s8-19', 'action', 'life_archive', '维权有期限：民事诉讼时效 3 年，劳动仲裁 1 年，过了对方一句「超过时效」就够', '8. 别把自己搭进去：法律与财产安全', '民事诉讼时效 3 年，从你知道权利受损那天算起。过了期，法院不会主动管，可对方在法庭上说一句「超过时效」就够了，钱还在，只是要不回来。而一条留了痕迹的催款消息，就能让这 3 年从头重算。劳动争议是另一套，仲裁时效 1 年。', '这大概是全书最便宜的一件事：一条留了痕迹的催款消息，就能把 3 年重新起算；什么都不做，就可能白白丢掉打赢官司的资格。事先说好「我不拿时效说事」不算数，两边约定把 3 年改长改短也不算数。反过来，过了期限对方仍然答应还的，就不能再拿时效来拒绝还钱。已经自愿还了的，也不能再要回去。借条和担保见第 18 条（借条和担保）。被执行的阶段见第 20 条（被起诉、被执行了如实报财产）。加班费和未休年休假工资走劳动仲裁那一套，见第 19 节第 1、2 条。', NULL, NULL, NULL, '不花钱。催款别只在心里催，用微信、短信、邮件或者挂号信留下痕迹。', '民法典规定「向人民法院请求保护民事权利的诉讼时效期间为三年」。起算点是「权利人知道或者应当知道权利受到损害以及义务人之日起计算」，从你知道自己吃了亏、又知道该找谁的那天起算。最长不超过自权利受到损害之日起 20 年。期间届满的，「义务人可以提出不履行义务的抗辩」。法院不会自己去翻时效，但对方在法庭上一提就有效，钱还在，只是要不回来了。有四种事情会让时效中断，一中断就从头重新计算 3 年。一是你向欠你的人提出要他履行。二是对方答应履行。三是你去起诉或者申请仲裁。四是和这些效力相同的其他情形。约定分期还的，从最后一期到期那天起算。有四类要求不受时效限制：要求停止侵害、排除妨碍、消除危险；要回自己的不动产和已经登记的动产；抚养费、赡养费、扶养费；法律规定的其他情形。劳动争议是另一套：仲裁时效 1 年，从知道或者应当知道权利被侵害之日起算。但「劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出」（全国）', '这大概是全书最便宜的一件事：一条留了痕迹的催款消息，就能把 3 年重新起算；什么都不做，就可能白白丢掉打赢官司的资格。事先说好「我不拿时效说事」不算数，两边约定把 3 年改长改短也不算数。反过来，过了期限对方仍然答应还的，就不能再拿时效来拒绝还钱。已经自愿还了的，也不能再要回去。借条和担保见第 18 条（借条和担保）。被执行的阶段见第 20 条（被起诉、被执行了如实报财产）。加班费和未休年休假工资走劳动仲裁那一套，见第 19 节第 1、2 条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-20', 'concept_archive_s8-20', 'claim_archive_s8-20', 'action', 'life_archive', '被起诉、被执行了，如实报财产、能还多少还多少，别把房和钱转给亲友或公司', '8. 别把自己搭进去：法律与财产安全', '把房子挂到公司名下、把钱转给亲友，正是拒执罪写明的情形，判 3 年以下，情节特别严重的判 3 到 7 年。帮着藏钱过户的亲友和公司按同伙算，钱照样追回。拒绝报告或者虚报财产，个人可罚 10 万元以下、拘留 15 日。真没钱不构成这个罪。', '网上流传的「把房子挂到公司名下当员工宿舍、钱全转给亲属」不是漏洞，正好是司法解释点名的白送和假转让。帮你操作的亲友和公司按同伙算，该追回的财产照样追回。反过来，真没钱不构成这个罪。判断你是不是「有钱不还」，要先扣掉你自己和你要养的家人过日子必需的开销。在检察院起诉之前把钱还上一部分或者全部、情节又轻的，可以不起诉。一审判决之前还上的，可以从轻甚至免罚。被列入名单、被限制消费之后怎么办，见第 21 条（被限制消费或者被列入失信名单）。履行完之后怎么恢复，见第 7 节第 19 条（上过失信名单之后怎么重来）。', NULL, NULL, NULL, '不花钱。按法院的要求报告财产：现在有什么，收到执行通知那天之前一年里有什么。能还的先还。还不上，就和申请执行人谈和解、谈分期，申请执行人就是要债的那一方。', '转移财产本身就是入罪的情形。全国人大常委会对刑法第三百一十三条作过解释。解释把「被执行人隐藏、转移、故意毁损财产或者无偿转让财产、以明显不合理的低价转让财产，致使判决、裁定无法执行」直接列为「有能力执行而拒不执行，情节严重」。藏钱、转钱、故意砸了自己的东西、白送出去、贱卖出去，让判决没法执行，都算。两高（最高人民法院和最高人民检察院）2024 年的解释又补了十项。其中包括用假和解、假转让的方式处置自己的财产权益。也包括用明显不合理的高价买下别人的财产，替别人的债务做担保。这些都是故意把自己可以用来还债的财产掏空。拒执罪判 3 年以下。情节特别严重的，判 3 到 7 年并处罚金。特别严重指这几种情形：用虚假诉讼、虚假仲裁、虚假公证妨害执行。聚众冲击执行现场。围攻、扣押、殴打执行人员。因为拒不执行导致申请执行人自杀自残。不是案件当事人的外人，明知情况还和他串通、帮着藏钱过户的，按拒执罪的共犯（同伙）论处。被违法处置的财产应当依法追缴（追回）或者责令退赔。在被告收到应诉通知之后、判决生效之前就动手转移的，同样算。民事上，白送和明显不合理的低价转让，要债的人可以请法院把这笔转让撤销。拒绝报告或者虚假报告财产的，法院可以罚款，对个人 10 万元以下，也可以拘留 15 日以下（全国，两高解释 2024 年 12 月起）', '网上流传的「把房子挂到公司名下当员工宿舍、钱全转给亲属」不是漏洞，正好是司法解释点名的白送和假转让。帮你操作的亲友和公司按同伙算，该追回的财产照样追回。反过来，真没钱不构成这个罪。判断你是不是「有钱不还」，要先扣掉你自己和你要养的家人过日子必需的开销。在检察院起诉之前把钱还上一部分或者全部、情节又轻的，可以不起诉。一审判决之前还上的，可以从轻甚至免罚。被列入名单、被限制消费之后怎么办，见第 21 条（被限制消费或者被列入失信名单）。履行完之后怎么恢复，见第 7 节第 19 条（上过失信名单之后怎么重来）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-21', 'concept_archive_s8-21', 'claim_archive_s8-21', 'action', 'life_archive', '被限制消费或者被列入失信名单，先查清是按哪一条纳入的，能纠正的申请纠正', '8. 别把自己搭进去：法律与财产安全', '先弄清自己是被限制消费，还是进了失信名单，这是两件事。失信名单只有六种情形能纳入，期限 2 年。已经履行完毕等七种情形，法院应当 3 个工作日内删除。限高禁九类消费，坐 G 字头高铁也算。生活或者经营必需的，可以一次一申请。', '限高就是限制高消费。这个规定 2010 年出台，2015 年经法释〔2015〕17 号修改，名称改成了《……及有关消费的若干规定》，本条按修改后的现行文本写。2015 年这次改动有三处要紧。一是加了第九类，高铁全部座位都算。二是删掉了「以其财产支付」这层限定，原来写的是「不得有以下以其财产支付费用的行为」。三是单位被限制消费的，实际控制人也跟着受限，但因私消费、花个人钱的，可以向执行法院申请。失信名单和限制消费是两回事，可能只沾上一样。这两样也都不等于征信有污点，从名单里删掉不会改征信，见第 7 节第 19 条（上过失信名单之后怎么重来）。配偶、子女花自己挣的钱受不受限，现行文本没有写明，碰到了去问执行法院。', NULL, NULL, NULL, '不花钱。去执行法院查清自己是按哪一项纳入的。准备好已经还了钱、已经照判决做了的凭据（履行凭证），或者准备担保材料。生活、经营必需的那笔消费，要一次一申请。难在得自己一趟趟跑、一次次申请。', '纳入失信名单只有六种情形。一是有履行能力而拒不履行。二是以伪造证据、暴力威胁妨碍抗拒执行。三是以虚假诉讼、虚假仲裁或者隐匿转移财产规避执行。四是违反财产报告制度。五是违反限制消费令。六是无正当理由拒不履行执行和解协议。提供了充分有效的担保，或者已经被查封扣押冻结的财产足够清偿的，法院不得按第一项（有履行能力而拒不履行）纳入。被执行人是未成年人的，不得纳入。纳入的期限是 2 年。以暴力威胁妨碍抗拒执行、情节严重的，或者有多项失信行为的，可以延长 1 到 3 年。已经履行完毕、和解协议已经履行完毕、法院裁定终结执行等七种情形，法院应当在 3 个工作日内删除。积极履行或者主动纠正失信行为的，还可以提前删除。被限制消费的自然人不得做九类高消费及非生活和工作必需的消费。一是坐飞机、列车软卧、轮船二等以上舱位。二是在星级以上宾馆、酒店、夜总会、高尔夫球场高消费。三是买不动产，或者新建、扩建、高档装修房屋。四是租高档写字楼、宾馆、公寓办公。五是买非经营必需的车辆。六是旅游、度假。七是子女就读高收费私立学校。八是花高额保费买保险理财产品。九是坐 G 字头动车组列车的任何座位，或者其他动车组列车一等以上座位。因为生活或者经营必需要做其中一项的，应当向法院申请，获得批准才能做。提供确实有效的担保，或者经申请执行人同意的，法院可以解除限高（全国）', '限高就是限制高消费。这个规定 2010 年出台，2015 年经法释〔2015〕17 号修改，名称改成了《……及有关消费的若干规定》，本条按修改后的现行文本写。2015 年这次改动有三处要紧。一是加了第九类，高铁全部座位都算。二是删掉了「以其财产支付」这层限定，原来写的是「不得有以下以其财产支付费用的行为」。三是单位被限制消费的，实际控制人也跟着受限，但因私消费、花个人钱的，可以向执行法院申请。失信名单和限制消费是两回事，可能只沾上一样。这两样也都不等于征信有污点，从名单里删掉不会改征信，见第 7 节第 19 条（上过失信名单之后怎么重来）。配偶、子女花自己挣的钱受不受限，现行文本没有写明，碰到了去问执行法院。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-22', 'concept_archive_s8-22', 'claim_archive_s8-22', 'action', 'life_archive', '网购、二手交易被骗，先平台投诉，再报警，再算值不值得起诉', '8. 别把自己搭进去：法律与财产安全', '先找平台。平台有保证金和处罚规则，处理最快。再报警：被骗 3000 元以上就够诈骗罪的立案线，不够刑事标准的按治安处罚，拘留 5 到 10 日。要打官司的，网购纠纷可以在收货地法院起诉，金额小的走小额诉讼，2 个月内审结，网上就能立案。', '值不值得打，可以这样算：拿你的税后时薪乘以要搭进去的时间，再加上法院的受理费。立案、开庭、可能还要申请执行，各按半天到一天算。算出来和你想要回的那笔钱比一比，再打个折扣，估一估赢了能不能真执行到钱。打不打，按这笔账自己定。治安管理处罚法 2025 年修订之后条号全变了，盗窃诈骗从旧法第四十九条改成了第五十八条。民诉法 2023 年修正之后，小额诉讼在第一百六十五条。这两处都别抄旧资料。「平台投诉优先」是经验：平台有保证金和处罚规则，处理最快。法释〔2011〕7 号在检察院官网页面上没有标文号，文号待与最高法原文页核对。', NULL, NULL, NULL, '平台投诉和报警都不花钱。起诉时，争的钱在 1 万元以内，受理费 50 元；走简易程序、调解或者撤诉的，再减半。立案、开庭、执行至少各占半天到一天，网上立案可以省掉跑腿。要保存订单、聊天记录、转账记录和物流单。难在来回折腾时别中途放弃。', '诈骗 3000 元至 1 万元以上，构成诈骗罪的「数额较大」，判 3 年以下，另外罚钱或者只罚钱，各省在这个幅度内定本地标准。不够刑事标准的，按治安管理处罚：拘留 5 到 10 日，或者罚 2000 元以下。情节较重的，拘留 10 到 15 日，并可以罚 3000 元以下。民事上，网购合同纠纷可以在收货地法院起诉，不必跑到卖家所在地。争的钱数在本省上年度就业人员年平均工资 50% 以下的，适用小额诉讼。小额诉讼一审终审（判完就生效、不能上诉）。立案后 2 个月内审结，简易程序 3 个月。民事诉讼可以在网上的平台进行，和线下同等效力（全国，民诉法 2024 年 1 月起，治安管理处罚法 2026 年 1 月起）', '值不值得打，可以这样算：拿你的税后时薪乘以要搭进去的时间，再加上法院的受理费。立案、开庭、可能还要申请执行，各按半天到一天算。算出来和你想要回的那笔钱比一比，再打个折扣，估一估赢了能不能真执行到钱。打不打，按这笔账自己定。治安管理处罚法 2025 年修订之后条号全变了，盗窃诈骗从旧法第四十九条改成了第五十八条。民诉法 2023 年修正之后，小额诉讼在第一百六十五条。这两处都别抄旧资料。「平台投诉优先」是经验：平台有保证金和处罚规则，处理最快。法释〔2011〕7 号在检察院官网页面上没有标文号，文号待与最高法原文页核对。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-23', 'concept_archive_s8-23', 'claim_archive_s8-23', 'action', 'life_archive', '恋爱和婚内的大额赠与，交付之前想清楚，交付之后原则上要不回', '8. 别把自己搭进去：法律与财产安全', '钱一交出去，原则上就要不回来了。送出去的东西，只有在过到对方名下之前才能随便撤销。过户完成之后，只有对方严重侵害你或者你的近亲属、该扶养你却不扶养、不履行约定义务这三种情形才撤得掉。所以大额转账之前先想清楚，这是借还是送。', '「520、1314 这类特殊数额通常认定为赠与」是实务里常见的说法，本节没有找到最高法的官方原文，不作为结论。去公证处公证过的赠与，就不能说反悔就反悔。一笔转账到底算借还是算送，最后要看证据，聊天记录里的一句「这钱我先借你」比事后争论有用得多。', NULL, NULL, NULL, '不花钱。大额转账之前先想一下：这是借，还是送。是借就写借条，转账备注写「借款」。难在开口把这句话说出来。', '送出去的东西，在过到对方名下之前可以撤销，法律把这个时点叫财产权利转移。一旦转账、过户完成，就只剩三种情形能撤销：收东西的一方严重侵害你或者你的近亲属；该扶养你却不扶养；不履行赠与合同里约定的义务。节日、生日这类有纪念意义的时点给的价值不大的礼物礼金，还有为了表达或者增进感情的日常消费支出，不属于彩礼，分手时不按彩礼返还（全国）', '「520、1314 这类特殊数额通常认定为赠与」是实务里常见的说法，本节没有找到最高法的官方原文，不作为结论。去公证处公证过的赠与，就不能说反悔就反悔。一笔转账到底算借还是算送，最后要看证据，聊天记录里的一句「这钱我先借你」比事后争论有用得多。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-24', 'concept_archive_s8-24', 'claim_archive_s8-24', 'action', 'life_archive', '彩礼走转账并备注，聊天记录留好；借婚姻要钱可以要回', '8. 别把自己搭进去：法律与财产安全', '借婚姻索取财物是法律禁止的，法院支持返还。没登记的、登记了但确实没共同生活的、婚前给了彩礼导致给钱一方生活困难的，可以要求返还。已登记又共同生活的一般不返还。所以彩礼、三金、改口费都走转账并备注用途，谁给的钱谁留证据，男女一样。', '彩礼算不算「数额过高」，要看给钱一方所在地的人均可支配收入和他家的情况，全国没有统一数字。该退多少，由法官一个案子一个案子地定。给钱的一方和收钱的一方规则一样，谁给的钱谁留证据。', NULL, NULL, NULL, '不花钱。彩礼、三金、改口费都走转账，并在备注里写清用途。口头说好的事，用聊天记录留痕，或者让家人在场确认。', '法律禁止借婚姻索取财物。一方以彩礼为名借婚姻索取财物的，另一方要求返还，法院支持。有三种情形可以要求返还：没办结婚登记；办了登记但确实没有共同生活；婚前给了彩礼，给到出钱那一方生活困难。已经登记并且共同生活的，一般不返还。但共同生活的时间短、彩礼数额又过高的，法院会按钱实际怎么花的、有没有嫁妆、有没有孕育、双方有没有过错，来确定返还的比例。没登记但已经同居的，同样按比例处理（全国，2024 年 2 月起）', '彩礼算不算「数额过高」，要看给钱一方所在地的人均可支配收入和他家的情况，全国没有统一数字。该退多少，由法官一个案子一个案子地定。给钱的一方和收钱的一方规则一样，谁给的钱谁留证据。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-25', 'concept_archive_s8-25', 'claim_archive_s8-25', 'action', 'life_archive', '婚前财产不用怕，房子加名和父母出资先写清楚', '8. 别把自己搭进去：法律与财产安全', '婚前的财产是你个人的，不会因为结婚年头长就变成共同财产。夫妻可以书面约定婚前婚后的财产各归各的。要留意一点：说好把房子加上对方的名，在变更登记之前还能反悔，登记完就是对方的了。离婚时藏钱、转移、挥霍或者伪造债务的一方，可以少分或者不分。', '财产协议对男女双方同样有效。想拿它对抗配偶欠外人的债，前提是债主知道你们有这个约定。他不知道，就管不到他。协议不公证也有效，公证只是省得日后为签名和日期扯皮。父母出钱买房怎么写清楚是借是送，见第 10 节第 11 条（父母出资买房）。', NULL, NULL, NULL, '自己写一份书面的财产协议不花钱，去公证另外收费。父母出钱时，请他们写一句书面说明。整件事一次性花掉几个小时。难在开口和家里人谈钱。', '婚前财产是个人财产，不会因为结婚年头长就变成共同财产。夫妻可以书面约定：婚前财产和婚后所得归各自、归共同，或者一部分共同，这个约定对双方都有约束力。婚前父母出资买房，视为给自己子女的赠与，除非明确表示是给两个人的。婚后父母出资的，按约定处理；没有约定的，按共同财产的原则处理。婚前或者婚内约定把一方的房产赠与另一方、或者变成两个人共有的，在变更登记之前，赠与的一方可以撤销，登记之后就是对方的了。离婚时隐藏、转移、变卖、挥霍共同财产，或者伪造债务的一方，可以少分或者不分（全国）', '财产协议对男女双方同样有效。想拿它对抗配偶欠外人的债，前提是债主知道你们有这个约定。他不知道，就管不到他。协议不公证也有效，公证只是省得日后为签名和日期扯皮。父母出钱买房怎么写清楚是借是送，见第 10 节第 11 条（父母出资买房）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-26', 'concept_archive_s8-26', 'claim_archive_s8-26', 'action', 'life_archive', '结婚前核对对方婚姻状况，以结婚为幌子骗钱的按诈骗罪追究', '8. 别把自己搭进去：法律与财产安全', '重婚的婚姻无效。有配偶还去结婚，或者明知对方有配偶还跟他结婚的，判 2 年以下。以结婚为幌子骗钱的，按诈骗罪追究：数额较大判 3 年以下，巨大判 3 到 10 年，特别巨大判 10 年以上或者无期。登记前看一眼对方身份证和户口簿上的婚姻状况。', '「骗婚」本身不是一个罪名。能不能按诈骗罪办，要看他一开始就想把钱占为己有，并且编了假话把钱骗到手，还得公安立案去查。够不够「数额较大」，金额由司法解释定，各地可以调整，本节没有核实。骗婚的受害者不分男女，被骗彩礼和被骗嫁妆的案例都有。', NULL, NULL, NULL, '不花钱。登记之前看一眼对方的身份证和户口簿上的婚姻状况。大额的财物往来，留下转账记录和聊天记录。', '重婚的婚姻无效。有配偶还去重婚的，或者明知对方有配偶仍然和他结婚的，判 2 年以下。诈骗公私财物数额较大的，判 3 年以下并处罚金。数额巨大的，判 3 到 10 年。数额特别巨大的，判 10 年以上或者无期，并处罚金或者没收财产（全国）', '「骗婚」本身不是一个罪名。能不能按诈骗罪办，要看他一开始就想把钱占为己有，并且编了假话把钱骗到手，还得公安立案去查。够不够「数额较大」，金额由司法解释定，各地可以调整，本节没有核实。骗婚的受害者不分男女，被骗彩礼和被骗嫁妆的案例都有。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-27', 'concept_archive_s8-27', 'claim_archive_s8-27', 'action', 'life_archive', '上门维修、验车、装修，先问价再动手，全程在旁边看着', '8. 别把自己搭进去：法律与财产安全', '家电维修必须明示收费标准，给维修凭证和发票，不得虚报故障，不得故意换掉性能正常的零件，情节严重的罚 3 万元以下。所有经营者都必须明码标价，不得在标价之外加价。所以动手前问清价钱和要换的件，修完要凭证和发票，旧件留下。被多收了先打 12315。', '被多收了先打 12315，处罚由商务、市场监管部门来做，不用你自己打官司。定 B 级是因为规则虽然是官方的，但「在旁边看着能少花多少」没有数字，主要靠经验。问价、留凭证、留旧件，对谁都一样做，不用以貌取人。家电那个办法只管家电维修，验车、装修参照明码标价规定和实施条例。上位的消费者权益保护法也写了这两样权利。第八条说你有权要求经营者说明服务的内容、规格、费用。第十条说你有权拒绝强制交易。', NULL, NULL, NULL, '不花钱。动手之前问清收费标准和要换哪些件，把报价拍下来，或者让对方发文字。修完要维修凭证和发票，把旧件留下。还要站在旁边看一两个小时。难在全程盯着不走开。', '家电维修经营者必须明示服务项目和配件的收费标准、质量规范、质保期限和投诉电话。必须给消费者维修服务凭证和收费发票，并如实填写维修的项目和详情。不得虚列、夸大、伪造维修项目，不得虚报故障部件，不得故意替换性能正常的部件。情节严重的，处 3 万元以下罚款。所有经营者都必须明码标价，不得在标价之外加价，不得收取任何没有标明的费用。低价诱骗、高价结算，以及虚假折价，属于价格欺诈。经营者必须用显著的方式标明服务的项目、内容、价格和计价方法，不得作虚假的或者引人误解的宣传（全国）', '被多收了先打 12315，处罚由商务、市场监管部门来做，不用你自己打官司。定 B 级是因为规则虽然是官方的，但「在旁边看着能少花多少」没有数字，主要靠经验。问价、留凭证、留旧件，对谁都一样做，不用以貌取人。家电那个办法只管家电维修，验车、装修参照明码标价规定和实施条例。上位的消费者权益保护法也写了这两样权利。第八条说你有权要求经营者说明服务的内容、规格、费用。第十条说你有权拒绝强制交易。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-28', 'concept_archive_s8-28', 'claim_archive_s8-28', 'action', 'life_archive', '别当「挂名法人」，别把身份证借给人注册公司', '8. 别把自己搭进去：法律与财产安全', '法律预设法定代表人就是那个管事的人，「我只是挂个名、什么都不知道」不是免责的理由。法定代表人执行职务给别人造成损害，公司先赔，赔完可以回头找有过错的你追偿。已经挂了名的，公司法允许你辞掉，公司要在 30 日内定出新的法定代表人。', '公司法原文只讲了责任归谁。挂名更常见的后果是：公司被法院执行的时候，法定代表人跟着被限制高消费，税务和行政处罚也可能牵连到你。这些后果出自其他法律和执行规定，本节没有核实原文，所以定 B 级。已经挂了名的，公司法允许你辞掉，公司要在 30 日内定出新的法定代表人。借你的名字去贷款，见第 45 条（帮忙刷个脸）。', NULL, NULL, NULL, '不花钱。有人请你「挂个名，不用管事」，拒绝就行。', '法定代表人由实际执行公司事务的董事或者经理担任，法律预设你就是管事的那个人。法定代表人执行职务给别人造成损害的，公司先赔，赔完可以回头向有过错的法定代表人追偿（把这笔钱要回去）。董事、高管对公司负有忠实义务和勤勉义务（忠于公司、尽心办事）。执行职务给别人造成损害，本人又有故意或者重大过失的，自己也要掏钱赔。「不知情」在法律上不是能免掉责任的理由（全国，2024 年 7 月起）', '公司法原文只讲了责任归谁。挂名更常见的后果是：公司被法院执行的时候，法定代表人跟着被限制高消费，税务和行政处罚也可能牵连到你。这些后果出自其他法律和执行规定，本节没有核实原文，所以定 B 级。已经挂了名的，公司法允许你辞掉，公司要在 30 日内定出新的法定代表人。借你的名字去贷款，见第 45 条（帮忙刷个脸）。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-29', 'concept_archive_s8-29', 'claim_archive_s8-29', 'action', 'life_archive', '出入境不帮陌生人带东西，不代收来路不明的包裹', '8. 别把自己搭进去：法律与财产安全', '外交部领事司给出国公民的建议是：不要替别人携带行李物品，特别是违禁品，或者你并不了解的东西。行李里真查出毒品或者走私品，「我不知道里面装的什么」要你自己举证。国内代收快递也一样，尤其是让你先垫钱、事后退款的。', '海关总署和公安部关于这件事的官方提示页面打不开，本条只引了外交部领事司的页面。而且原文只给原则、不给法条，所以定 B 级。国内代收快递也一样，尤其是让你先垫付、事后退款的。', NULL, NULL, NULL, '不花钱。拒绝就行。', '外交部领事司给出国公民的建议是「请务必避免为他人携带行李物品，特别是违禁物品或不了解的物品」。这么做是为了避免在不知情的情况下替别人携带违禁品，因而承担法律责任。行李里查出毒品或者走私品的时候，「不知道里面是什么」需要你自己举证', '海关总署和公安部关于这件事的官方提示页面打不开，本条只引了外交部领事司的页面。而且原文只给原则、不给法条，所以定 B 级。国内代收快递也一样，尤其是让你先垫付、事后退款的。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-30', 'concept_archive_s8-30', 'claim_archive_s8-30', 'action', 'life_archive', '养狗必须牵绳：不牵绳出了事是无过错责任（你有没有错都要赔），赔到底', '8. 别把自己搭进去：法律与财产安全', '狗伤了人，原则上不管你有没有错都要赔。只有能证明是对方故意或者有重大过失，才可能少赔或者不赔。而如果你违反规定没牵绳，就只剩「被侵权人故意」这一条能减轻，不牵绳等于把唯一的退路也堵死。禁养的烈性犬伤了人，没有任何免责的理由。', '狗咬人的赔偿包含医疗费、误工费、狂犬疫苗和免疫球蛋白，一次上万很常见。伤得重，或者伤到小孩的，数目还要更高。丢下不管也不脱责：遗弃、逃逸期间伤了人，仍然算原饲养人的。被咬之后怎么处置见第 13 节。', NULL, NULL, NULL, '一根绳几十元。难在每次出门都记得牵。', '自家养的动物伤了人，养的人或者当时管着它的人就要赔，法律叫承担侵权责任。只有能证明是被伤的人自己故意招惹，或者有重大过失，才可以不赔或者少赔。而违反管理规定、没采取安全措施的，比如该牵绳没牵，就只剩「被侵权人故意」这一条能减轻。禁止饲养的烈性犬伤了人，则没有任何能免责的理由', '狗咬人的赔偿包含医疗费、误工费、狂犬疫苗和免疫球蛋白，一次上万很常见。伤得重，或者伤到小孩的，数目还要更高。丢下不管也不脱责：遗弃、逃逸期间伤了人，仍然算原饲养人的。被咬之后怎么处置见第 13 节。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-31', 'concept_archive_s8-31', 'claim_archive_s8-31', 'action', 'life_archive', '对方喝到意识不清、睡着，或者可能不满 14 岁，就不要发生关系', '8. 别把自己搭进去：法律与财产安全', '对方喝到意识不清或者睡着，就没有能力表示同意，这时发生关系法律上也算强奸，基本刑是 3 到 10 年。事后你几乎无法证明对方当时同意。唯一可靠的做法是不发生关系，酒局散场把人交给对方自己的朋友或者家人。年龄的认定见第 9 节第 18 条（不满 14 岁）。', '给 B 是因为法条只写了「其他手段」四个字。「灌醉了也算强奸」出自检察院的普法文章，不是司法解释。强奸罪的法条只写了妇女。男性被这样侵害，按强制猥亵罪追究，所以对方是男是女都一样不能碰。自己是被害的一方，先做什么见第 13 节第 42 条（被性侵之后）。你自己喝到断片的时候，被指控和被敲诈这两种风险同时存在，见本节第 32 条（对方拿把柄来要钱就报警）。', NULL, NULL, NULL, '不花钱。代价是当时把事情停下来。难在当场停住。', '《刑法》第二百三十六条：以暴力、胁迫或者其他手段强奸妇女的，处三年以上十年以下有期徒刑。「其他手段」不限于动手，对方意识不清、睡着时无法有效同意，就落在这四个字里。强奸妇女情节恶劣的，强奸妇女多人的等情形，处十年以上有期徒刑、无期徒刑或者死刑。同一条还规定，奸淫不满十四周岁的幼女的，以强奸论并从重处罚，幼女怎么认定见第 9 节第 18 条（不满 14 岁）。北京市西城区人民检察院的普法文章说，把妇女「麻醉、灌醉后实施性侵的，同样构成强奸罪」。关键在「是否违背了被害人内心真实意愿」，被害人当时有没有反抗「并非关键」。《刑法》第二百三十七条管强制猥亵：以暴力、胁迫或者其他方法强制猥亵他人的，处五年以下有期徒刑或者拘役（全国）', '给 B 是因为法条只写了「其他手段」四个字。「灌醉了也算强奸」出自检察院的普法文章，不是司法解释。强奸罪的法条只写了妇女。男性被这样侵害，按强制猥亵罪追究，所以对方是男是女都一样不能碰。自己是被害的一方，先做什么见第 13 节第 42 条（被性侵之后）。你自己喝到断片的时候，被指控和被敲诈这两种风险同时存在，见本节第 32 条（对方拿把柄来要钱就报警）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-32', 'concept_archive_s8-32', 'claim_archive_s8-32', 'action', 'life_archive', '发生关系、裸聊之后对方拿报警、发照片、告诉你单位来要钱，一分钱不给，一条记录不删，直接报警', '8. 别把自己搭进去：法律与财产安全', '拿「我去报警」「把照片发给你单位」要挟你给钱，是敲诈勒索。一分钱不给，一条记录不删，当场报警，给了第一笔就会有第二笔。对方真把照片发出去，是他多一条罪。敲诈 2000 到 5000 元以上就判 3 年以下，3 万到 10 万以上判 3 到 10 年。', '三档金额是各省在司法解释给的幅度内自己定的。2000 到 5000 元以上算「数额较大」。3 万到 10 万元以上算「数额巨大」。30 万到 50 万元以上算「数额特别巨大」。落到你所在的省是哪个数，以当地标准为准。两年内敲诈三次以上的，每次金额不大也算「多次」。别自己删聊天记录、删照片、注销账号、拉黑了事，那是把自己的证据也删了，见本节第 5 条（被传唤先请律师、不删记录）。真被立案调查的，这些记录同时是你自证的材料。也别试图「谈判分期」。裸聊敲诈多是境外团伙干的，他们一边录屏，一边用木马读走你的通讯录。「群发给家人」是话术，报警后照样能立案。拿「告诉你家里人你喜欢同性」要挟要钱，也是同一种敲诈。江苏盐城有人在同性社交软件上约人见面后，这样要走 1.45 万元，受害人报案后他被起诉，此前他已两次因同样手法被判刑。拿裸照逼人发生关系，按强奸罪追究。浙江象山有人在社交平台上骗到多名女性的裸照，再拿公布裸照威胁她们，查明的被害人有 10 人。其中一人收到威胁就报了警，两人没见过面，检察院仍按强奸未遂处理，最后以强奸罪、强制猥亵罪起诉。所以别给网上认识的人发裸照。反过来，你自己是受害人、去向侵权方索赔的，金额高也不等于敲诈，见本节第 36 条（自己是受害人去索赔）。照片真被发到网上的，可以通知平台删除。民法典第一千一百九十五条规定，你有权通知平台删除、屏蔽、断开链接，通知里要附上侵权的初步证据和你的真实身份信息。平台收到通知不及时处理的，扩大的那部分损害由它和发帖人一起赔。', NULL, NULL, NULL, '不花钱。截图对方的账号、聊天记录和收款码，带着手机去派出所。难的是忍住「先给钱平事」的念头。', '《刑法》第二百七十四条：敲诈勒索公私财物，数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。拘役是短期关押，管制是不关押但限制自由，并处或者单处罚金就是另外罚钱或者只罚钱。数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金。数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。两高还有一份解释：《关于办理敲诈勒索刑事案件适用法律若干问题的解释》（法释〔2013〕10 号，2013 年 4 月 27 日起施行）。这份解释的第一条定了三档金额。敲诈勒索公私财物价值二千元至五千元以上的，认定为「数额较大」。三万元至十万元以上的，认定为「数额巨大」。三十万元至五十万元以上的，认定为「数额特别巨大」。第三条：二年内敲诈勒索三次以上的，应当认定为「多次敲诈勒索」（全国）。民法典第一千零三十二条：任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。第一千零三十三条禁止以电话、短信、即时通讯工具等方式侵扰私人生活安宁。所以对方真把照片发出去，是他多一条罪。福建省公安厅同类案件提示的原话是：「一定要保存好证据，及时拨打 110，切勿继续转账」', '三档金额是各省在司法解释给的幅度内自己定的。2000 到 5000 元以上算「数额较大」。3 万到 10 万元以上算「数额巨大」。30 万到 50 万元以上算「数额特别巨大」。落到你所在的省是哪个数，以当地标准为准。两年内敲诈三次以上的，每次金额不大也算「多次」。别自己删聊天记录、删照片、注销账号、拉黑了事，那是把自己的证据也删了，见本节第 5 条（被传唤先请律师、不删记录）。真被立案调查的，这些记录同时是你自证的材料。也别试图「谈判分期」。裸聊敲诈多是境外团伙干的，他们一边录屏，一边用木马读走你的通讯录。「群发给家人」是话术，报警后照样能立案。拿「告诉你家里人你喜欢同性」要挟要钱，也是同一种敲诈。江苏盐城有人在同性社交软件上约人见面后，这样要走 1.45 万元，受害人报案后他被起诉，此前他已两次因同样手法被判刑。拿裸照逼人发生关系，按强奸罪追究。浙江象山有人在社交平台上骗到多名女性的裸照，再拿公布裸照威胁她们，查明的被害人有 10 人。其中一人收到威胁就报了警，两人没见过面，检察院仍按强奸未遂处理，最后以强奸罪、强制猥亵罪起诉。所以别给网上认识的人发裸照。反过来，你自己是受害人、去向侵权方索赔的，金额高也不等于敲诈，见本节第 36 条（自己是受害人去索赔）。照片真被发到网上的，可以通知平台删除。民法典第一千一百九十五条规定，你有权通知平台删除、屏蔽、断开链接，通知里要附上侵权的初步证据和你的真实身份信息。平台收到通知不及时处理的，扩大的那部分损害由它和发帖人一起赔。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-33', 'concept_archive_s8-33', 'claim_archive_s8-33', 'action', 'life_archive', '被人捏造事实举报，可以要求追究：够治安处罚的拘留 5 日起，够罪的判 3 年以下', '8. 别把自己搭进去：法律与财产安全', '捏造事实诬告陷害别人，想让他被追究刑责或者被治安处罚，本身就是违法。这种要拘留 5 日以下，或者罚 1000 元以下。情节较重的，拘留 5 到 10 日。够得上犯罪的是诬告陷害罪，判 3 年以下。但记错了、告错了不算，要追究对方，你得证明他是有意诬陷。', '要追究对方，光证明「我没做过」不够，还要证明他「捏造事实」并且「有意诬陷」。后者难证明得多，追究不一定能成。全国范围内没有公开的诬告立案与处理统计，本书查不到，因此不写发生率，也不写性别分布。自己被指控后的举证和救济，见本节第 34、35 条（证据不足应判无罪、国家赔偿）。', NULL, NULL, NULL, '不花钱。去公安机关报案，说明对方是捏造的。难在拿出东西证明他是故意编的。', '《治安管理处罚法》（2025 年 6 月 27 日修订，2026 年 1 月 1 日起施行）第五十条管的是诬告。捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的，要处罚。处五日以下拘留，或者一千元以下罚款。情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款。《刑法》第二百四十三条管的是诬告陷害罪。捏造事实诬告陷害他人，意图使他人受刑事追究，情节严重的，处三年以下有期徒刑、拘役或者管制。造成严重后果的，处三年以上十年以下有期徒刑。国家机关工作人员犯前款罪的，从重处罚，从重是指在同一档刑罚里往重里判。不是有意诬陷，而是错告，或者检举失实的，不适用前两款的规定。记错了、告错了，不按这两款追究（全国）', '要追究对方，光证明「我没做过」不够，还要证明他「捏造事实」并且「有意诬陷」。后者难证明得多，追究不一定能成。全国范围内没有公开的诬告立案与处理统计，本书查不到，因此不写发生率，也不写性别分布。自己被指控后的举证和救济，见本节第 34、35 条（证据不足应判无罪、国家赔偿）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-34', 'concept_archive_s8-34', 'claim_archive_s8-34', 'action', 'life_archive', '证据不足本来就应当判无罪，逼出来的口供应当排除；判了还有申诉和再审', '8. 别把自己搭进去：法律与财产安全', '定罪的门槛写在刑事诉讼法里：定案的证据要经过法定程序查证属实，还要综合全案证据排除合理怀疑。做不到，就应当判无罪。刑讯逼供得来的口供、暴力威胁得来的证言，都应当排除，不能作为判决的依据。判决生效之后，你和你的法定代理人、近亲属还可以申诉。', '这些是制度写明的底线，结果并没有保证。本书没有中国刑事案件无罪率、申诉改判率的可核对官方数据，所以不写比例，也不评价个案。自己能做的有三件事。第一，第一次讯问之后就委托律师，见本节第 5 条（被指控先请律师）。第二，笔录逐字看完再签。第三，别为了「早点出去」认下没做过的事，认罪认罚只能从宽，免不了责。符合法定情形的，法院应当重新审判。', NULL, NULL, NULL, '走程序本身不花钱，但申诉和再审都很耗时间。通常要请律师，律师费几千元起。经济困难的可以申请法律援助，见本节第 5 条（被指控先请律师）。难在一轮轮等下去不放弃。', '《刑事诉讼法》第五十五条：证据确实、充分，要符合这些条件——定案的证据都经过法定程序查证属实，综合全案证据对认定的事实已经排除合理怀疑。排除合理怀疑，就是把全案证据合起来看，认定的事实不能还留着说得通的另一种可能。第五十六条：采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述，以及采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除。在侦查、审查起诉、审判时发现有应当排除的证据的，应当依法予以排除，不得作为起诉意见、起诉决定和判决的依据。第二百条第（三）项：证据不足，不能认定被告人有罪的，应当作出证据不足、指控的犯罪不能成立的无罪判决。第二百五十二条给了申诉的路。当事人及其法定代理人、近亲属，对已经发生法律效力的判决、裁定，可以向人民法院或者人民检察院提出申诉。但申诉不能停止判决、裁定的执行。第二百五十三条列举了人民法院应当重新审判的情形（全国）', '这些是制度写明的底线，结果并没有保证。本书没有中国刑事案件无罪率、申诉改判率的可核对官方数据，所以不写比例，也不评价个案。自己能做的有三件事。第一，第一次讯问之后就委托律师，见本节第 5 条（被指控先请律师）。第二，笔录逐字看完再签。第三，别为了「早点出去」认下没做过的事，认罪认罚只能从宽，免不了责。符合法定情形的，法院应当重新审判。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-35', 'concept_archive_s8-35', 'claim_archive_s8-35', 'action', 'life_archive', '被羁押后撤案、不起诉或者判无罪的，去申请国家赔偿，按天算钱', '8. 别把自己搭进去：法律与财产安全', '被拘留、逮捕后又撤案、不起诉或判无罪的，能申请国家赔偿。被关的日子按天赔，2026 年 5 月 18 日起每天 495.94 元，一年约 18 万元。后果严重的另给精神损害抚慰金。犯了事只因情节轻微不起诉的，不赔。过了追诉期、没到年龄、自己作假口供的也不赔。', '这个按天算的标准，每年 5 月随国家统计局公布的上年度城镇非私营单位年平均工资更新。用的时候查当年的数字，别直接套本条这个。拿到不起诉决定书，先看它写的依据。写的是「没有犯罪事实」或者「证据不足」，可以申请赔偿。写的是「犯罪情节轻微」，或者过了追诉时效，被关的日子原则上赔不了。不服相对不起诉的，收到决定书后 7 日内可以向检察院申诉。精神损害抚慰金由办案机关按后果定，没有统一公式。该赔钱的是当初决定关你的那个机关（公安、检察院或者法院），先找它提。对它的处理不服，再按国家赔偿法的程序往上申请。实际怎么算，可以看本节第 36 条（自己是受害人去索赔）里郭利那个案子的决定书。郭利被关了 1826 天。赔偿按作决定那一年的标准算，不按关他那一年的，用的是 2016 年度全国职工日平均工资 258.89 元。限制人身自由这部分赔了约 47.3 万元（472733.14 元），另给精神损害抚慰金约 16.5 万元（165450 元）。他自己申请的十年精神损害抚慰金 8888 万元，超出的部分不支持。也要知道哪些赔不了：那份决定书把误工费、身体健康方面的赔偿、财产损失、律师费、看守所的生活费补贴，都认定为不在国家赔偿的范围里。', NULL, NULL, NULL, '不花钱。向当初作出拘留、逮捕、起诉或者判决的那个机关提出赔偿申请。', '《国家赔偿法》第十七条列了几种情形，受害人有取得赔偿的权利。第一种是拘留：违反刑事诉讼法规定对公民采取拘留措施，或者依法拘留但超过法定时限。这之后决定撤销案件、不起诉，或者判决宣告无罪终止追究刑事责任的。第二种是逮捕：对公民采取逮捕措施后，决定撤销案件、不起诉，或者判决宣告无罪终止追究刑事责任的。第三种是再审：案子按审判监督程序再审改判无罪，原判刑罚已经执行的。审判监督程序就是把已经生效的判决重新拿出来审的程序。第三十三条：侵犯公民人身自由的，每日赔偿金按照国家上年度职工日平均工资计算。第三十五条：致人精神损害的，应当在侵权行为影响的范围内为受害人消除影响、恢复名誉、赔礼道歉，造成严重后果的应当支付相应的精神损害抚慰金。第十九条列了六种国家不赔的情形。一是自己故意作假口供，或者伪造其他有罪证据，因此被关或者被判刑。二是按刑法第十七条、第十八条不负刑事责任的人被关，比如没到负刑事责任的年龄，或者精神病人在不能辨认、不能控制自己行为的时候造成危害。三是按刑事诉讼法规定不追究刑事责任的人被关。这包括情节显著轻微、危害不大，不认为是犯罪的，过了追诉时效的，嫌疑人死亡的。也包括犯罪情节轻微、检察院决定不起诉的，就是常说的相对不起诉（也叫酌定不起诉）。未成年人附条件不起诉考验期满后不起诉的，和被害人达成和解后不起诉的，同样在内。四是办案人员和行使职权无关的个人行为。五是自己自伤、自残等故意行为造成的损害。六是法律规定的其他情形。两高 2015 年的刑事赔偿司法解释第七条再次确认：不负刑事责任的人和相对不起诉的人被羁押，国家不赔。但起诉后被法院错判拘役、有期徒刑、无期徒刑并已执行的，判决确定后继续关押的那段仍然要赔。该解释第八条：办案机关以「你自己作假口供」「你自己自伤自残」为理由不赔的，由办案机关举证。最高人民检察院 2026 年 5 月发了通知。国家统计局 2026 年 5 月 15 日公布，2025 年全国城镇非私营单位就业人员年平均工资约 12.9 万元（129441 元）。据此算出的日平均工资为 495.94 元。各级检察院自 2026 年 5 月 18 日起作出国家赔偿决定时，对侵犯公民人身自由的赔偿金按每日 495.94 元计算。上一个标准是每日 475.52 元，从 2025 年 5 月起用（全国）', '这个按天算的标准，每年 5 月随国家统计局公布的上年度城镇非私营单位年平均工资更新。用的时候查当年的数字，别直接套本条这个。拿到不起诉决定书，先看它写的依据。写的是「没有犯罪事实」或者「证据不足」，可以申请赔偿。写的是「犯罪情节轻微」，或者过了追诉时效，被关的日子原则上赔不了。不服相对不起诉的，收到决定书后 7 日内可以向检察院申诉。精神损害抚慰金由办案机关按后果定，没有统一公式。该赔钱的是当初决定关你的那个机关（公安、检察院或者法院），先找它提。对它的处理不服，再按国家赔偿法的程序往上申请。实际怎么算，可以看本节第 36 条（自己是受害人去索赔）里郭利那个案子的决定书。郭利被关了 1826 天。赔偿按作决定那一年的标准算，不按关他那一年的，用的是 2016 年度全国职工日平均工资 258.89 元。限制人身自由这部分赔了约 47.3 万元（472733.14 元），另给精神损害抚慰金约 16.5 万元（165450 元）。他自己申请的十年精神损害抚慰金 8888 万元，超出的部分不支持。也要知道哪些赔不了：那份决定书把误工费、身体健康方面的赔偿、财产损失、律师费、看守所的生活费补贴，都认定为不在国家赔偿的范围里。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-36', 'concept_archive_s8-36', 'claim_archive_s8-36', 'action', 'life_archive', '自己是受害人去索赔，走 12315、起诉或者律师，别单独赴对方的约，别把「给钱」和「我不曝光」绑成一句话', '8. 别把自己搭进去：法律与财产安全', '自己是受害人，向侵权方索赔，本身有法律依据，不会因为「要价高」就自动变成敲诈勒索。但代价可能很大：郭利先被以敲诈勒索罪判了五年，后来才再审宣告无罪。所以走留痕的渠道，别单独去对方指定的地方谈，别把「给钱」和「我就不曝光」绑成一个条件说出口。', '给 B 是因为这只是一个案子，不是能推广的比例。它同时说明两件事：索赔本身合法，以及你仍然可能被警方当成案子立案来查。风险最低的走法是把索赔交给律师，或者直接去法院起诉，自己不和对方单独接触。对方约你去他所在地「面谈解决」时尤其要留意，报案和立案通常发生在对方所在地。和解协议签了就照协议走，签完再另起一笔高额索赔，最容易被解读成「要挟」。被立案之后怎么处置，见本节第 5、34、35 条（先请律师、证据不足应判无罪、国家赔偿）。对方拿把柄向你索财的情形，见本节第 32 条（对方拿报警、发照片来要钱）。', NULL, NULL, NULL, '不花钱。通过 12315、去法院起诉，或者委托律师提出。见面谈的时候全程录音。难在忍住不自己跟对方单独谈。', '官方案例：2008 年有关部门公布部分批次「施恩」牌奶粉含三聚氰胺之后，郭利之女的检查结果为「双肾中央集合系统内可见数个点状强回声」。郭利多次向销售商和施恩公司索赔，并向媒体曝光。2009 年 6 月双方达成协议，施恩公司补偿 40 万元，郭利出具书面材料表示不再追诉并放弃赔偿要求。此后公司报案，郭利被潮安县人民法院以敲诈勒索罪判处有期徒刑五年。广东省人民检察院提出了再审建议。建议认为「现有证据不足以证实郭利主观上具有非法占有的目的」。郭利作为法定监护人，「有权利向奶粉的生产厂家索赔，其索赔行为有法律依据」。建议还写着，「消费者对损害其合法权益的行为，有权通过大众传播媒介予以揭露、批评」。2017 年 4 月 7 日，广东省高级人民法院再审宣告郭利无罪。理由是「原审认定郭利以非法占有为目的，使用威胁、要挟的方法，强行索取财物行为的事实不清，证据不足，郭利的行为性质未超出民事纠纷的范畴」。郭利自 2009 年 7 月 23 日至 2014 年 7 月 22 日被羁押 1826 天（广东，2017 年再审改判）', '给 B 是因为这只是一个案子，不是能推广的比例。它同时说明两件事：索赔本身合法，以及你仍然可能被警方当成案子立案来查。风险最低的走法是把索赔交给律师，或者直接去法院起诉，自己不和对方单独接触。对方约你去他所在地「面谈解决」时尤其要留意，报案和立案通常发生在对方所在地。和解协议签了就照协议走，签完再另起一笔高额索赔，最容易被解读成「要挟」。被立案之后怎么处置，见本节第 5、34、35 条（先请律师、证据不足应判无罪、国家赔偿）。对方拿把柄向你索财的情形，见本节第 32 条（对方拿报警、发照片来要钱）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-37', 'concept_archive_s8-37', 'claim_archive_s8-37', 'action', 'life_archive', '被网暴了：先开防护、先固证，再在平台、禁令、报警三条路里挑', '8. 别把自己搭进去：法律与财产安全', '当场先做三件事：打开平台的防护设置，用快捷取证把内容存下来，再从快捷入口举报。之后可以向法院申请禁令，让他先停手。也可以自己去法院告，取证难可以请公安协助。后果特别严重、影响又恶劣的，由检察院起诉，不用你自己举证。', '顺序按「快且便宜」排：平台最快、成本最低，先固证、先举报。法院最慢最贵，最后再定要不要打。三条路的过程成本都得自己扛。禁令要自己向法院申请。自诉是自己去法院立案、自己拿证据。想让检察院接手、改走公诉，得撞上法发〔2023〕14 号第 12 条列的那五种情形之一，够不上就只能自己告。有两件事别做。一是不对骂，骂回去会把你自己变成本节第 16 条（网上不骂人、不造谣）里被处罚的那一个。二是不删自己账号里的内容，那是证据。扛不住的时候打 12356，见第 1 节第 25 条。要求平台删除你的个人信息，见第 14 节第 8 条。因为帮了陌生人被拍、被传上网的情形，见 [docs/遇到陌生人出事该不该停.md](../docs/遇到陌生人出事该不该停.md)。', NULL, NULL, NULL, '不花钱。当场花十几分钟做防护和取证。如果走到申请禁令或者自诉这一步，要跑法院，可能还要请律师。难在被骂的时候先去存证，不去对骂。', '法发〔2023〕14 号第 15 条讲的是禁令。权利人有证据证明，行为人正在实施或者即将实施侵害其人格权的违法行为。不及时制止，将使其合法权益受到难以弥补的损害。权利人依据民法典第九百九十七条申请的，人民法院可以依法作出人格权侵害禁令。人格权侵害禁令就是一道责令对方先停手的法院命令。该解释第 11 条讲的是取证。自诉案件里，「被害人提供证据确有困难的，可以要求公安机关提供协助」。公安机关应当及时查明行为主体，收集传播扩散情况及影响等证据材料。网络服务提供者应当提供必要的技术支持。「经公安机关协助取证，达到自诉案件受理条件的，人民法院应当决定立案」。无法收集的，公安机关应当书面说明。自诉案件就是要受害人自己去法院起诉的案件。该解释第 12 条列了五种情形，应当认定为刑法第二百四十六条第二款说的「严重危害社会秩序」。一是造成被害人或者其近亲属精神失常、自杀等严重后果，且社会影响恶劣。二是随意以普通公众为侵害对象，信息大范围传播引发大量低俗恶意评论，且社会影响恶劣。三是侮辱诽谤多人或者多次散布，且社会影响恶劣。四是组织、指使人员在多个平台大量散布，且社会影响恶劣。五是其他。该解释第 4 条：组织「人肉搜索」，违法收集并向不特定多数人发布公民个人信息，情节严重的以侵犯公民个人信息罪定罪处罚。《网络暴力信息治理规定》第二十三条要求平台提供这些防护选项。可以屏蔽陌生用户或者特定用户。可以限制本人发布信息的可见范围。可以禁止转载或者评论。可以只接收好友私信，或者拒绝接收所有私信。第二十五条要求提供快捷取证功能。第二十六条要求在显著位置设快捷投诉举报入口。第十五条要求平台发现涉嫌违法犯罪的，及时向公安机关报案', '顺序按「快且便宜」排：平台最快、成本最低，先固证、先举报。法院最慢最贵，最后再定要不要打。三条路的过程成本都得自己扛。禁令要自己向法院申请。自诉是自己去法院立案、自己拿证据。想让检察院接手、改走公诉，得撞上法发〔2023〕14 号第 12 条列的那五种情形之一，够不上就只能自己告。有两件事别做。一是不对骂，骂回去会把你自己变成本节第 16 条（网上不骂人、不造谣）里被处罚的那一个。二是不删自己账号里的内容，那是证据。扛不住的时候打 12356，见第 1 节第 25 条。要求平台删除你的个人信息，见第 14 节第 8 条。因为帮了陌生人被拍、被传上网的情形，见 [docs/遇到陌生人出事该不该停.md](../docs/遇到陌生人出事该不该停.md)。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-38', 'concept_archive_s8-38', 'claim_archive_s8-38', 'action', 'life_archive', '「先给人买保险再动手」这条路法律上从头堵死：钱一分拿不到，罪按故意杀人加保险诈骗数罪并罚', '8. 别把自己搭进去：法律与财产安全', '四道门都是关着的。背着家人给他买以死亡为条件的保险，合同无效。投保人故意造成被保险人死亡的，保险公司不赔。故意杀害被继承人的，丧失继承权。刑法还把这种骗保单列一项，和故意杀人罪数罪并罚，最高死刑。钱一分拿不到。', '这条的受益人是自己，避免的是死刑或者无期。案例的伤亡和判决取自检察机关公布的典型案例原文，正文不写侦查手段之外的细节。伪造事故、夸大损失这类不涉及人命的骗保，同样是犯罪，连帮忙作证的人一起算，见第 9 节第 21 条（伪造事故、夸大损失骗理赔）。给家人买保险本身是正常的，要防的是「买了保险再动手」这个念头。想伤害家人的冲动按急症处理，见本节第 14、15 条（自己冒出念头、身边人说出狠话）', NULL, NULL, NULL, '不花钱。', '保险法第三十四条：以死亡为给付保险金条件的合同，未经被保险人同意并认可保险金额的，合同无效。被保险人就是被保的那个人。父母为未成年子女投保不受这个限制。第三十九条：投保人指定受益人时须经被保险人同意。投保人是掏钱买保险的人，受益人是出事后领钱的人。第四十三条管的是故意害人。投保人故意造成被保险人死亡、伤残或者疾病的，保险人不承担给付保险金的责任。投保人已交足二年以上保险费的，向其他权利人退还现金价值。受益人故意造成被保险人死亡、伤残、疾病的，或者故意杀害被保险人未遂的，该受益人丧失受益权。第二十七条第二款：投保人、被保险人故意制造保险事故的，保险人有权解除合同、不承担赔偿或者给付责任，除第四十三条规定外不退还保险费。民法典第一千一百二十五条：故意杀害被继承人的，丧失继承权。刑法第一百九十八条第一款第五项，把「投保人、受益人故意造成被保险人死亡、伤残或者疾病，骗取保险金」列为保险诈骗。数额较大的，处 5 年以下并处 1 万至 10 万元罚金。数额巨大的，处 5 至 10 年。特别巨大的，处 10 年以上。第二款：有该项行为同时构成其他犯罪的，依照数罪并罚的规定处罚，数罪并罚就是几个罪合在一起算刑。第二百三十二条：故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑。案例是安徽宣城的张某松案。2016 年 7 月 18 日凌晨，他驾车冲入池塘，妻子溺亡。事发前不到半个月，他为妻子投保 4 份，每份 100 万元。7 月 25 日他被抓获。法院以故意杀人罪、保险诈骗罪数罪并罚，判处死缓并处罚金 5 万元', '这条的受益人是自己，避免的是死刑或者无期。案例的伤亡和判决取自检察机关公布的典型案例原文，正文不写侦查手段之外的细节。伪造事故、夸大损失这类不涉及人命的骗保，同样是犯罪，连帮忙作证的人一起算，见第 9 节第 21 条（伪造事故、夸大损失骗理赔）。给家人买保险本身是正常的，要防的是「买了保险再动手」这个念头。想伤害家人的冲动按急症处理，见本节第 14、15 条（自己冒出念头、身边人说出狠话）', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-39', 'concept_archive_s8-39', 'claim_archive_s8-39', 'action', 'life_archive', '报警当场要受案回执，不立案要书面通知：7 日内可申请复议，再 7 日可申请复核，检察院能通知公安立案', '8. 别把自己搭进去：法律与财产安全', '报了警要当场拿到受案回执，这是你报过案的唯一凭据。公安决定不立案，应当给你书面的不予立案通知书。不服可以 7 日内申请复议，还不服再 7 日内申请复核。你也可以找检察院，请它监督公安立案。', '受益人是你自己。报了警不一定就会处理，但办不办、多久办，都有明文的标准和期限。三个动作按顺序记。① 当场拿受案回执，把案件编号和受理单位记下来。② 到期没结果，就按上面的期限去问进度，问「案子在哪个环节」，别问「为什么不管我」。③ 收到不予立案通知书，先看理由，7 日内复议，再 7 日复核，同时可以向人民检察院提出立案监督，三条路不冲突。治安案件，就是打架、小偷小摸这类。办案期限从受理那天算起，不超过 30 日。案情重大复杂的，经上一级公安机关批准可以再延 30 日。做鉴定的时间不算在内。接待态度差就走督察投诉，案子本身照样按立案流程追。捡到失物、邻里纠纷这类本来就不是刑事案件，公安机关按行政案件或者调解处理，甚至只是登记备案，别按「报案没人管」来理解。被诈骗之后的止付流程，见本节第 2 条（立刻打 110 要求止付）。被网暴见本节第 37 条（被网暴了先固证再挑路）', NULL, NULL, NULL, '不花钱。当场多问一句，把受案回执要到手。之后按上面的日期去追问进度。难在一次次开口去问。', '《公安机关办理刑事案件程序规定》（公安部令第 159 号修正后）第一百七十一条管的是受案回执。原文是：「公安机关接受案件时，应当制作受案登记表和受案回执，并将受案回执交扭送人、报案人、控告人、举报人」。第一百七十四条：「对接受的案件，或者发现的犯罪线索，公安机关应当迅速进行审查」。第一百七十八条管的是立不立案。接受案件后经审查，认为有犯罪事实需要追究刑事责任，又属于自己管辖的，经县级以上公安机关负责人批准予以立案。不立案也要给你一张纸：「对有控告人的案件，决定不予立案的，公安机关应当制作不予立案通知书，并在三日以内送达控告人」。第一百七十九条管的是不服怎么办。原文是：「控告人对不予立案决定不服的，可以在收到不予立案通知书后七日以内向作出决定的公安机关申请复议；公安机关应当在收到复议申请后三十日以内作出决定」。接着写：「控告人对不予立案的复议决定不服的，可以在收到复议决定书后七日以内向上一级公安机关申请复核；上一级公安机关应当在收到复核申请后三十日以内作出决定。对上级公安机关撤销不予立案决定的，下级公安机关应当执行」。案情重大、复杂的可以延长复议复核的时限，但「不得超过三十日，并书面告知申请人」。刑事诉讼法第一百一十二条：认为有犯罪事实需要追究刑事责任的应当立案；不予立案的，「将不立案的原因通知控告人。控告人如果不服，可以申请复议」。第一百一十三条：「被害人认为公安机关对应当立案侦查的案件而不立案侦查，向人民检察院提出的，人民检察院应当要求公安机关说明不立案的理由。人民检察院认为公安机关不立案理由不能成立的，应当通知公安机关立案，公安机关接到通知后应当立案」。《公安机关办理行政案件程序规定》第六十一条也有同样的要求。属于本单位管辖的案件，「应当立即调查处理，制作受案登记表和受案回执，并将受案回执交报案人、控告人、举报人、扭送人」。办理治安案件的期限「自受理之日起不得超过 30 日；案情重大、复杂的，经上一级公安机关批准，可以延长 30 日」，鉴定期间不计入办案期限。《公安机关督察条例》第九条管的是投诉警察。原文是：「督察机构对群众投诉的正在发生的公安机关及其人民警察违法违纪行为，应当及时出警，按照规定给予现场处置，并将处理结果及时反馈投诉人」（全国）', '受益人是你自己。报了警不一定就会处理，但办不办、多久办，都有明文的标准和期限。三个动作按顺序记。① 当场拿受案回执，把案件编号和受理单位记下来。② 到期没结果，就按上面的期限去问进度，问「案子在哪个环节」，别问「为什么不管我」。③ 收到不予立案通知书，先看理由，7 日内复议，再 7 日复核，同时可以向人民检察院提出立案监督，三条路不冲突。治安案件，就是打架、小偷小摸这类。办案期限从受理那天算起，不超过 30 日。案情重大复杂的，经上一级公安机关批准可以再延 30 日。做鉴定的时间不算在内。接待态度差就走督察投诉，案子本身照样按立案流程追。捡到失物、邻里纠纷这类本来就不是刑事案件，公安机关按行政案件或者调解处理，甚至只是登记备案，别按「报案没人管」来理解。被诈骗之后的止付流程，见本节第 2 条（立刻打 110 要求止付）。被网暴见本节第 37 条（被网暴了先固证再挑路）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-40', 'concept_archive_s8-40', 'claim_archive_s8-40', 'action', 'life_archive', '别给办案、执法的人送钱送卡：行贿自己也判，对监察、执法、司法人员行贿还要从重', '8. 别把自己搭进去：法律与财产安全', '「花点钱把事摆平」在刑法里是独立的罪，被抓的不只是收钱那个人。行贿判 3 年以下。情节严重的判 3 到 10 年，特别严重的判 10 年以上或者无期。对监察、行政执法、司法人员行贿，还是明文从重的那一档。被勒索给了钱、又没拿到不正当利益的，不算行贿。', '受益人是你自己。别指望贿赂一下就能免除惩罚。对方有同事、有台账、有监控和督察，你送出去的东西是他被查时的证据，也是你自己的罪证，而且这一类行贿是明文从重的那一档。真遇到对方索要好处，就按第 39 条（报警当场要受案回执）的渠道走：留下受案回执和文书，向督察机构或者纪检监察机关反映。刑法第三百八十九条第三款给的免责条件是「被勒索且没有获得不正当利益」，一旦你借这个机会拿到了本来拿不到的东西，这个条件就不成立。医院里的红包属于另一套规则，见第 24 节第 11 条', NULL, NULL, NULL, '不花钱。只是不去做。', '刑法第三百八十九条给行贿下了定义：「为谋取不正当利益，给予国家工作人员以财物的，是行贿罪」。同一条还写着：「在经济往来中，违反国家规定，给予国家工作人员以财物，数额较大的，或者违反国家规定，给予国家工作人员以各种名义的回扣、手续费的，以行贿论处」。也留了一种例外：「因被勒索给予国家工作人员以财物，没有获得不正当利益的，不是行贿」。量刑写在刑法第三百九十条（刑法修正案十二修改，2024 年 3 月 1 日起施行）。原文是：「对犯行贿罪的，处三年以下有期徒刑或者拘役，并处罚金；因行贿谋取不正当利益，情节严重的，或者使国家利益遭受重大损失的，处三年以上十年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产」。有七种要往重里判的从重情形：「（一）多次行贿或者向多人行贿的；（二）国家工作人员行贿的；（三）在国家重点工程、重大项目中行贿的；（四）为谋取职务、职级晋升、调整行贿的；（五）对监察、行政执法、司法工作人员行贿的；（六）在生态环境、财政金融、安全生产、食品药品、防灾救灾、社会保障、教育、医疗等领域行贿，实施违法犯罪活动的；（七）将违法所得用于行贿的」。末款留了主动交待可以减免的口子：「行贿人在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚。其中，犯罪较轻的，对调查突破、侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚」（全国）', '受益人是你自己。别指望贿赂一下就能免除惩罚。对方有同事、有台账、有监控和督察，你送出去的东西是他被查时的证据，也是你自己的罪证，而且这一类行贿是明文从重的那一档。真遇到对方索要好处，就按第 39 条（报警当场要受案回执）的渠道走：留下受案回执和文书，向督察机构或者纪检监察机关反映。刑法第三百八十九条第三款给的免责条件是「被勒索且没有获得不正当利益」，一旦你借这个机会拿到了本来拿不到的东西，这个条件就不成立。医院里的红包属于另一套规则，见第 24 节第 11 条', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-41', 'concept_archive_s8-41', 'claim_archive_s8-41', 'action', 'life_archive', '可能翻脸的电话和面谈，直接开录音：自己参加的谈话，不用先征得对方同意', '8. 别把自己搭进去：法律与财产安全', '借钱、欠款、赔偿、退款、劳动纠纷，电话里说清楚了却没留下东西，几个月后双方就可能各说一套。你自己参加的谈话可以录下来，没提前告诉对方，不会单凭这一点就不能当证据。不能干的是窃听、偷窥别人隐私、闯进别人家里偷录，或者威胁对方说话。', '受益人是你自己和家人。录音里尽量让人、事、钱数和时间对得上。别只问「你什么时候给我」，可以自然地问「去年借你的 5 万元，你准备什么时候还」。录音交给法院、仲裁委或者警察用，别发到网上，公开别人的话可能惹上隐私和名誉纠纷，见本节第 16 条（网上不骂人、不造谣）。有录音不等于一定赢，法院还要结合别的证据看真不真、有没有关系。录音只解决能不能证明，要不要真去起诉、要花多久，得另外算。离职前该存的材料见第 19 节第 8 条（离职前把工资条、考勤先存下来）。本条的依据是民事诉讼规则，刑事和行政案件里怎么用证据另有规定。', NULL, NULL, NULL, '不花钱。手机打开通话录音或者录音软件就行。从头录到尾，录完把原文件留着，不剪辑、不覆盖。', '民事诉讼法第六十六条把视听资料、电子数据都列为证据。最高人民法院的民事诉讼法司法解释第一百零六条，只排除三种方法取得的证据：严重侵害他人合法权益的，违反法律禁止性规定的，严重违背公序良俗的。「没事先告诉对方」不在这三种里。最高人民法院的证据规定第十五条：拿录音录像当证据，要交存着它的原始载体，比如原来那部手机。第九十条：存有疑点的视听资料、电子数据，不能单独用来认定事实。最高人民法院官网转载的一篇法官文章也这样说：录音要合法取得、内容真实、不剪辑，还要和案子有关（全国）', '受益人是你自己和家人。录音里尽量让人、事、钱数和时间对得上。别只问「你什么时候给我」，可以自然地问「去年借你的 5 万元，你准备什么时候还」。录音交给法院、仲裁委或者警察用，别发到网上，公开别人的话可能惹上隐私和名誉纠纷，见本节第 16 条（网上不骂人、不造谣）。有录音不等于一定赢，法院还要结合别的证据看真不真、有没有关系。录音只解决能不能证明，要不要真去起诉、要花多久，得另外算。离职前该存的材料见第 19 节第 8 条（离职前把工资条、考勤先存下来）。本条的依据是民事诉讼规则，刑事和行政案件里怎么用证据另有规定。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-42', 'concept_archive_s8-42', 'claim_archive_s8-42', 'action', 'life_archive', '现场出了事，先拍全景，再拍位置关系，最后拍损坏和伤情，原图原视频别删', '8. 别把自己搭进去：法律与财产安全', '只对着车上一道划痕或者地上一件东西拍特写，过几天没人知道它原来在哪。先拍一段全景，把路口、门牌、车、人和周围都收进去，再拍相互位置，最后拍细节。要挪动东西或者车，能先拍就先拍。原图原视频留在手机里，别只存一份聊天软件里转过的。', '受益人是你自己和家人。给 C 是因为拍摄顺序只是经验，法律条文只管照片录像能当证据、要交原件。有人受伤、起火、漏气或者还有别的危险，先救人、先躲开，别为了拍照耽误。交通事故现场该做的事见本节第 1 条（出了交通事故先停车、救人、报警）。', NULL, NULL, NULL, '不花钱。拿手机连续拍几十秒到几分钟。先保证自己安全，不耽误救人和处置。', '民事诉讼法第六十六条把物证、视听资料和电子数据都列为证据。最高人民法院的证据规定第十四条把图片、音频、视频列为电子数据。第十五条要求交电子数据的原件，拿录像当证据要交原始载体。照片和录像能把马上会变的现场状态留下来，再和报警记录、维修记录、病历、证人说法互相对上。「全景、位置、细节」这个顺序是经验做法，法律没有规定（全国）', '受益人是你自己和家人。给 C 是因为拍摄顺序只是经验，法律条文只管照片录像能当证据、要交原件。有人受伤、起火、漏气或者还有别的危险，先救人、先躲开，别为了拍照耽误。交通事故现场该做的事见本节第 1 条（出了交通事故先停车、救人、报警）。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-43', 'concept_archive_s8-43', 'claim_archive_s8-43', 'action', 'life_archive', '被家暴了：先报警留下出警记录，再去法院申请人身安全保护令，不用先离婚，也不收费', '8. 别把自己搭进去：法律与财产安全', '在全世界被杀害的女性里，三分之一以上是伴侣下的手，往往是长期家暴的结局。同样挨打的女性里，被掐过脖子的，后来被杀的几率是没被掐过的 7 倍多。所以挨了打就报警，再去法院申请保护令。法院一般 72 小时内就要给答复。', '受益人主要是你自己和家人。命案比例是国外数据，我国没有公开的同口径统计。证据要攒：出警记录、告诫书、验伤结果、看病记录、对方写的保证书、聊天记录和录音都能用。录音见本节第 41 条（录音）。保护令不用请律师，一般几天内就有结果。要离婚或者要赔偿，是另一场官司，一审普通程序 6 个月起，律师费自己出。家暴受害人可以找法律援助，法院也可以缓收、减收或者免收诉讼费。保护令不等于人身安全有了保证，眼前有危险先打 110。受害人被强迫、被吓住，没法自己申请的，近亲属、公安机关、妇联、居委会、村委会可以代为申请。受害的是朋友或同事，你可以陪对方去报警、去医院。看见陌生人家里有人正在挨打，打 110 就够了。别自己上手拉架，理由见本节第 10 条（冲突先报警）。', NULL, NULL, NULL, '不花钱。申请人身安全保护令不交诉讼费，也不用交担保。要花的是报警、验伤、写申请的时间。最难的是对家里人开这个口。', '先说风险。66 个国家的数据合起来看（系统综述）。女性被杀的案子里，38.6% 是亲密伴侣干的，男性是 6.3%。作者说，这类命案往往是长期虐待的最后一步。另一项研究比较了 506 起命案和杀人未遂，还有 427 名挨过打但没出这种事的女性。以前被伴侣掐过脖子的，遭杀人未遂的几率是没被掐过的 6.70 倍（OR 6.70，95% CI 3.91–11.49）。被杀的几率是 7.48 倍（OR 7.48，95% CI 4.53–12.35）。再说法律。受害人和近亲属可以报警。公安机关要及时出警，制止家暴，调查取证，协助就医和验伤。情节较轻的，公安机关可以给对方出告诫书。遭受家暴或者面临家暴的现实危险，可以向法院申请人身安全保护令。法院受理后 72 小时内要作出裁定，情况紧急的 24 小时内。保护令可以禁止对方施暴，禁止对方骚扰、跟踪、接触你和你的近亲属，还可以让对方搬出你的住处。保护令最长管 6 个月，到期前可以申请延长。申请不以离婚为前提。法院认为家暴「存在较大可能性」就可以发。对方违反保护令，法院可以罚款 1000 元以下、拘留 15 日以下。构成犯罪的，按拒不执行判决、裁定罪处理。经常性的侮辱、威胁、跟踪、骚扰，还有挨冻挨饿，也算家暴。', '受益人主要是你自己和家人。命案比例是国外数据，我国没有公开的同口径统计。证据要攒：出警记录、告诫书、验伤结果、看病记录、对方写的保证书、聊天记录和录音都能用。录音见本节第 41 条（录音）。保护令不用请律师，一般几天内就有结果。要离婚或者要赔偿，是另一场官司，一审普通程序 6 个月起，律师费自己出。家暴受害人可以找法律援助，法院也可以缓收、减收或者免收诉讼费。保护令不等于人身安全有了保证，眼前有危险先打 110。受害人被强迫、被吓住，没法自己申请的，近亲属、公安机关、妇联、居委会、村委会可以代为申请。受害的是朋友或同事，你可以陪对方去报警、去医院。看见陌生人家里有人正在挨打，打 110 就够了。别自己上手拉架，理由见本节第 10 条（冲突先报警）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-44', 'concept_archive_s8-44', 'claim_archive_s8-44', 'action', 'life_archive', '家里人赌博欠了债，别急着替他还：赌债法律不保护，为赌借的钱也不算夫妻共同债务', '8. 别把自己搭进去：法律与财产安全', '在赌桌上欠的钱，法院不保护。债主明知他借钱去赌还借给他，这笔钱法院也不保护。一方为了赌博借的钱，不能算成两口子一起还的债。没经过审判，法院不能让没借钱的一方替他担责任。', '给 B 是因为这是法院的内部通知，没有数字，债主知不知情也要看证据。这份通知是按当时的婚姻法发的，民法典施行后怎么认定夫妻共同债务，见第 10 节第 12 条（配偶大额借的钱）。债主不知道他拿去赌的借款，照样要还，只是还钱的是借钱的人自己。要证明钱拿去赌了，得有转账流水、赌博平台记录或者公安的处理材料，平时就留着。债主真去起诉，一审普通程序 6 个月起，简易程序 3 个月。律师费各付各的，败诉方不负担。债主上门堵人、扣人，见第 9 节第 15 条（要债不扣人），直接报警。他本人要是已经赌到想死，见第 1 节第 37 条（赌到借钱还赌先打 12356）。受益人主要是配偶和直系亲属。', NULL, NULL, NULL, '不花钱。难在债主上门、家里人哭着求时，忍住不掏钱。债主真去起诉，你要应诉。', '最高人民法院 2017 年的通知写了四点。一方在赌博、吸毒这些违法犯罪活动里欠的债，不予法律保护。债主知道或者应当知道他借钱去赌博、吸毒，还借给他的，不予法律保护。一方用自己的名义借钱，拿去干违法犯罪的事，他要求按夫妻共同债务处理的，法院不支持。没经过审判程序，不能要求没借钱的那一方承担民事责任（全国，2017 年起）', '给 B 是因为这是法院的内部通知，没有数字，债主知不知情也要看证据。这份通知是按当时的婚姻法发的，民法典施行后怎么认定夫妻共同债务，见第 10 节第 12 条（配偶大额借的钱）。债主不知道他拿去赌的借款，照样要还，只是还钱的是借钱的人自己。要证明钱拿去赌了，得有转账流水、赌博平台记录或者公安的处理材料，平时就留着。债主真去起诉，一审普通程序 6 个月起，简易程序 3 个月。律师费各付各的，败诉方不负担。债主上门堵人、扣人，见第 9 节第 15 条（要债不扣人），直接报警。他本人要是已经赌到想死，见第 1 节第 37 条（赌到借钱还赌先打 12356）。受益人主要是配偶和直系亲属。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-45', 'concept_archive_s8-45', 'claim_archive_s8-45', 'action', 'life_archive', '熟人让你「帮忙刷个脸、做个见证」去办贷款，或者要你念验证码，别答应：这叫 AB 贷，借款人是你，不是担保人', '8. 别把自己搭进去：法律与财产安全', '所谓「帮忙刷个脸、做个见证」，其实是用你的名字向银行借钱。借款人是你，不是担保人，钱转给熟人以后，银行照样找你还。中介骗了你，但只要银行不知情，这份借款合同你就撤不掉。熟人写给你的「我来还」承诺书，也管不到银行。', '受益人主要是你自己，开口找你的 A 多半是家人或朋友。上海浦东一位检察长撰文说，B 往往碍于情面明知是自己贷款也照办，最后成了银行的催收对象。真想帮忙，先问清自己在合同上是什么身份，是借款合同就别签。愿意担保的，就以保证人的身份签保证合同，见第 18 条（替人担保）。已经被贷了款，先报警，再打放款银行官网上的电话说明情况，聊天和转账记录都留好。自己名下有几笔贷款，查征信见第 9 条（查征信报告）。银行贷前问话时别照中介教的说，作假可能自己担责，见第 9 节第 6 条（包装材料贷款）。刷脸和电子确认同样算签字，见第 17 条（签字前把纸看完）。法院也不是一律判本人还：广州互联网法院 2021 年判过，身份证被偷后当场报警挂失的人，银行拿不出她本人刷脸的证据就输了。所以身份证丢了要马上报警挂失，回执留好。机构要你刷脸时可以要别的方式，那是另一件事，见第 14 节第 9 条（刷脸不是必须答应的）。借你名字办事的同类套路见第 28 条（挂名法人）。手机和账户不外借，见第 8 条（不把银行卡借人）。给 B 是因为监管只给了套路和案例，没有被骗人数和金额的统计。', NULL, NULL, NULL, '不花钱。难在当面拒绝亲戚朋友。对方说「只是做个见证」「不用你担责任」，也照样拒绝。手机、身份证、银行卡不交给中介，也不照中介的安排刷脸、签字。验证码只自己用，熟人要也不念。', '金融监管总局福建监管局 2022 年的风险提示讲了这个套路。客户 A 资质不够，贷不下来。中介说要加一个担保人，让 A 去找资质好的 B。实际办的时候，中介用 B 的身份信息申请贷款，钱给 A 用。原文说「借款人实质为B」，B「直至被银行催收才知本人是借款人而非担保人」。山东监管局 2024 年的提示说，中介会向 B 承诺「不用承担任何责任」。中介还会事先教 B 怎么应付银行的贷前调查，实际由 B 作为借款人申请贷款。上海普陀区法院 2024 年公布过一起案子。业务员拿着 B 的手机下载银行 App，直接用 B 的名义申请贷款。钱到了 B 的账户，B 转给了 A，A 又付了 8 万多元手续费。中介一伙 8 人以合同诈骗罪被判 10 个月到 4 年。中介判了刑，这笔贷款也不会因此变成别人的。民法典第一百四十九条写着，第三人欺诈的，对方「知道或者应当知道」，受骗的一方才能请求撤销。这里的对方是银行，银行不知情就撤不掉。能撤的，要在知道被骗之日起 1 年内向法院请求（第一百五十二条）。借款人要按约定的期限还钱（第六百七十五条）。合同只约束签合同的人（第四百六十五条）。把债转给别人，要经银行同意（第五百五十一条）。所以 A 写的承诺书管不到银行。钱只能自己起诉 A 去要。替人刷了脸、没看合同，法院也认。内江市市中区法院 2025 年审结过一个案子：蒋某向小贷公司借钱，自己一个人借不到。张某的儿子背着她，把她的身份信息给了蒋某，让她当共同借款人。借款流程里要她本人刷脸，她刷了，但没看合同。法院说她「应当预见人脸识别的重要性及法律后果」，判她和蒋某一起还剩下的本金 6 万多元。电子签名法写明，「可靠的电子签名与手写签名或者盖章具有同等的法律效力」。反电信网络诈骗法规定，任何人「不得提供实名核验帮助」，违反的要罚款，情节严重的拘留。普通程序一审 6 个月内审结，可以延长。律师费不在法定的诉讼费用里，要自己出（全国）', '受益人主要是你自己，开口找你的 A 多半是家人或朋友。上海浦东一位检察长撰文说，B 往往碍于情面明知是自己贷款也照办，最后成了银行的催收对象。真想帮忙，先问清自己在合同上是什么身份，是借款合同就别签。愿意担保的，就以保证人的身份签保证合同，见第 18 条（替人担保）。已经被贷了款，先报警，再打放款银行官网上的电话说明情况，聊天和转账记录都留好。自己名下有几笔贷款，查征信见第 9 条（查征信报告）。银行贷前问话时别照中介教的说，作假可能自己担责，见第 9 节第 6 条（包装材料贷款）。刷脸和电子确认同样算签字，见第 17 条（签字前把纸看完）。法院也不是一律判本人还：广州互联网法院 2021 年判过，身份证被偷后当场报警挂失的人，银行拿不出她本人刷脸的证据就输了。所以身份证丢了要马上报警挂失，回执留好。机构要你刷脸时可以要别的方式，那是另一件事，见第 14 节第 9 条（刷脸不是必须答应的）。借你名字办事的同类套路见第 28 条（挂名法人）。手机和账户不外借，见第 8 条（不把银行卡借人）。给 B 是因为监管只给了套路和案例，没有被骗人数和金额的统计。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s8-46', 'concept_archive_s8-46', 'claim_archive_s8-46', 'action', 'life_archive', '给门窗装好锁、门外装一盏感应灯，出门真的锁上：防入室盗窃靠这几样，单装一个报警器看不出用', '8. 别把自己搭进去：法律与财产安全', '英国的数据显示，门锁加窗锁的人家，被人进屋偷东西的几率只有什么都没装的十二分之一。再加一盏门外感应灯，降到三十多分之一。只装一个报警器、别的都不装，看不出能防盗。这管的是盗窃，不管有人在家的抢劫。', '争议：报警器那一半有反方数据。同一批作者用 1992 到 1996 年的数据算过，那时加装报警器是能降低被盗几率的。作者也说这个反常结果要谨慎看待，一种可能是被偷过的人家才去装报警器。所有数字都是英国的，而且只是比较装了和没装的人家，没有分组对照，所以给 B。这些数字只管入室盗窃，没有数据说门锁能挡住入室抢劫。真遇到有人在家里，先退开报警，见第 10 条（起了冲突先报警不动手）。退无可退时，见第 11 条（躲不掉的侵害可以还手）。租房的，换锁、加窗锁先跟房东说好。民法典规定，租客没经房东同意就加装、改装，房东可以要求恢复原状或者赔偿。买防盗门可以看一眼，防盗安全门有强制性国家标准 GB 17565-2022，2024 年 1 月 1 日起实施。受益人主要是你自己和家人。', NULL, NULL, NULL, '门锁换成要用钥匙才能反锁的，窗户加锁，门外装一盏感应灯，一般几十到几百元。换整扇防盗门要上千元。难在每次出门都真的锁上门窗，夏天开着窗时也要记得。', '英格兰和威尔士的犯罪调查，问了 2008 到 2012 年间 37416 户人家装了哪些防盗设施，再和被盗的人家比。什么都没装的只占全部人家的 4.9%，却占了被人进屋偷东西人家的 36.6%。作者算的是「保护倍数」：被盗几率是什么都没装人家的几分之一。门锁加窗锁是 12.54 倍，被盗几率降到约十二分之一。这里的门锁指双锁或者「死锁」（锁舌要用钥匙才能收回）。门锁、窗锁再加门外的感应灯或定时灯，是 34.41 倍。再加屋里的定时灯，是 49 倍。只装一样的，门外灯约 3 倍，门锁约 2.8 倍。单装窗锁看不出差别。装五样的，并不比装对了的三样强。只装报警器、别的都不装，被盗几率反而比什么都没装的高。挂假报警器盒子的，有人想闯进来没闯成的几率也更高。锁得真锁上才算数：1993 到 2006/07 年，撬锁、砸窗、拆门板进屋的盗窃从每千户 31 起降到 7 起，降了 77%。门窗没锁、直接走进去的那种，一直是每千户 7 起，没降（英格兰和威尔士）', '争议：报警器那一半有反方数据。同一批作者用 1992 到 1996 年的数据算过，那时加装报警器是能降低被盗几率的。作者也说这个反常结果要谨慎看待，一种可能是被偷过的人家才去装报警器。所有数字都是英国的，而且只是比较装了和没装的人家，没有分组对照，所以给 B。这些数字只管入室盗窃，没有数据说门锁能挡住入室抢劫。真遇到有人在家里，先退开报警，见第 10 条（起了冲突先报警不动手）。退无可退时，见第 11 条（躲不掉的侵害可以还手）。租房的，换锁、加窗锁先跟房东说好。民法典规定，租客没经房东同意就加装、改装，房东可以要求恢复原状或者赔偿。买防盗门可以看一眼，防盗安全门有强制性国家标准 GB 17565-2022，2024 年 1 月 1 日起实施。受益人主要是你自己和家人。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"8. 别把自己搭进去：法律与财产安全","B 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-1', 'concept_archive_s9-1', 'claim_archive_s9-1', 'action', 'life_archive', '群里不转发不知真假的灾情、疫情、警情消息，不 P 图、不用 AI 造现场图', '9. 普通人容易踩的法律红线', '一条灾情、疫情、警情的消息，你明知是假的还转出去，罚得和自己编一样重。不是你编的也一样：拘留 5 到 10 日，还要罚 1000 元。把社会秩序搅乱了判 3 年以下，造成严重后果判 3 到 7 年。P 图、AI 做的假现场图，都算自己编。', '明知是假还转发，和自己编，警察用的是同一个条款。「我只是转了一下」不免责。P 图和 AI 生成的假现场图，一样算自己编。公安部 2025 年公布过多批涉灾情、险情的网络谣言典型案例。本节写作时公安部网站打不开，所以没引用具体案例。', NULL, NULL, NULL, '不花钱。转发前看一眼，看它是不是官方发的通报。拿不准就不转，也不改图、不加「据说」。难在忍住那股当第一个报信人的劲头。', '故意散布谣言，谎报险情、疫情、灾情、警情，扰乱公共秩序的，拘留 5 到 10 日。还可以再罚 1000 元以下。情节较轻的那一档，是拘留 5 日以下，或者罚 1000 元以下。编造虚假的险情、疫情、灾情、警情，放到网上传播的，判 3 年以下。明知是假的还故意往外传，也是这一档。前提是把社会秩序搅乱得厉害，法条的说法是「严重扰乱社会秩序」。造成严重后果的，判 3 到 7 年（全国）', '明知是假还转发，和自己编，警察用的是同一个条款。「我只是转了一下」不免责。P 图和 AI 生成的假现场图，一样算自己编。公安部 2025 年公布过多批涉灾情、险情的网络谣言典型案例。本节写作时公安部网站打不开，所以没引用具体案例。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-2', 'concept_archive_s9-2', 'claim_archive_s9-2', 'action', 'life_archive', '不发、不转侮辱英烈的图片、表情包和评论，不拿国旗国歌开玩笑', '9. 普通人容易踩的法律红线', '拿英烈、国旗、国歌开玩笑，轻的拘留 5 到 10 日，或者罚 1000 到 3000 元。重一些的拘留 10 到 15 日。构成犯罪的判 3 年以下。有人在 499 人的村民微信群里发了 2 条诋毁袁隆平的话，判管制 6 个月，人没关进去，但行动受限制。', '治安管理处罚法的这一条，是 2025 年修订时才加进去的。在那之前，这种事只能走刑法，或者由检察院提民事公益诉讼。几百人的微信群，在法院眼里就算公开场合。', NULL, NULL, NULL, '不花钱。涉及英烈、国旗、国徽、国歌的内容，不评论、不改图、不转发。难在群里有人接玩笑时，忍住不跟着说一句。', '用辱骂、编造事实这类方式，侵害英雄烈士的姓名、肖像、名誉、荣誉，损害了公共利益的，按下面这档罚。拘留 5 到 10 日，或者罚 1000 到 3000 元。亵渎、否定英烈的事迹和精神，制作传播美化侵略战争的言论、图片、音视频，扰乱公共秩序的，也是这一档。情节较重的那一档，是拘留 10 到 15 日，还可以再罚 5000 元以下。到「情节严重」这一档就构成犯罪，判 3 年以下。在公共场合侮辱国旗国徽，或者改国歌的词曲、用歪曲贬损的方式唱国歌，情节严重的也判 3 年以下。官方案例：肖某在 499 人的村民微信群发 2 条信息诋毁侮辱袁隆平，判管制 6 个月（管制是不关进监狱、但行动受限制的刑罚）。仇某用 250 余万粉丝的微博发 2 条歪曲卫国戍边官兵事迹的内容，判 8 个月，还要在全国性媒体公开道歉（全国）', '治安管理处罚法的这一条，是 2025 年修订时才加进去的。在那之前，这种事只能走刑法，或者由检察院提民事公益诉讼。几百人的微信群，在法院眼里就算公开场合。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-3', 'concept_archive_s9-3', 'claim_archive_s9-3', 'action', 'life_archive', '境外网站上的东西看完就关，不截图、不转发、不搬进群里，也不在评论区跟着说', '9. 普通人容易踩的法律红线', '这些法条罚的是往外传，不罚看。你转发、搬进群、在评论区跟着说，办案时都算传播。传到煽动颠覆、煽动分裂这一档，判 5 年以下，带头的 5 年以上。恐怖主义、极端主义的书和音视频是例外，明知还存在手里，情节严重的就判 3 年以下。', '本条引的这几条法律，罚的是煽动别人、往外传、提供给别人，光看不在其中。恐怖主义、极端主义的材料是法条写明的例外，光存在自己手里就能定罪（第一百二十条之六），所以这一类一定不能存档。看到了就到此为止：不截图存档、不转发、不加评论、不拉人一起转。转发和在评论区跟着说，办案时都算传播，「我只是转了一下」不免责。内容出自境外平台的，还可能加重处罚。拿不准真假的更不要跟着转，见本节第 1 条（不转发不知真假的消息）。翻墙工具本身怎么罚，见第 11 节第 11 条。这类内容转出去得不到任何实在的好处，代价却是刑期、剥夺政治权利和没收财产。公开可查的同类案件只见于境外媒体和家属公布的文书，比如一名长期在境外平台发政治评论的博主 2023 年被判 7 年。本书没有拿到官方渠道可核对的判决书，所以只按法条写，没有附案例。', NULL, NULL, NULL, '不花钱。页面关掉，这件事就结束了。不存档、不转发、不搬到境内平台。不用能对上自己身份的账号，在境外平台长期发政治内容。境外机构、组织、个人给的稿费和资助也不接。难在看到扎眼的内容时忍住不截图、不分享。', '用造谣、诽谤或者别的方式，煽动别人颠覆国家政权、推翻社会主义制度的，判 5 年以下。带头的（法条叫「首要分子」）或者罪行重大的，判 5 年以上，有期徒刑最高 15 年。煽动分裂国家、破坏国家统一的，刑期和上面一样。和境外机构、组织、个人勾结着做这两件事的，从重处罚。境内外的机构、组织或者个人出钱资助别人做的，对直接负责的人判 5 年以下，情节严重的判 5 年以上。为境外的机构、组织、人员窃取、刺探、收买、非法提供国家秘密或者情报的，判 5 到 10 年。这一项里情节特别严重的判 10 年以上或者无期徒刑，情节较轻的判 5 年以下。危害国家安全的犯罪一律附加剥夺政治权利 1 到 5 年，这几年里选举权和当公职人员的资格都被取消。还可以并处没收财产，把个人财产收归国家。行政处罚上也有规定。任何个人和组织都不得利用网络，从事危害国家安全、荣誉和利益的活动。也不得煽动颠覆国家政权、推翻社会主义制度。不得煽动分裂国家、破坏国家统一。发布或者传输这类信息的，按有关法律、行政法规处罚（全国）。另有一类不用传播就成立。明知是宣扬恐怖主义、极端主义的东西，还非法拿在手里的，情节严重就够判。这里的东西包括图书、音频视频资料或者其他物品。刑期是 3 年以下有期徒刑、拘役（短期关押）或者管制（不关押但行动受限）。还要并处或者单处罚金，判刑的同时罚钱，也可能只罚钱。依据是刑法第一百二十条之六，由刑法修正案九新增。', '本条引的这几条法律，罚的是煽动别人、往外传、提供给别人，光看不在其中。恐怖主义、极端主义的材料是法条写明的例外，光存在自己手里就能定罪（第一百二十条之六），所以这一类一定不能存档。看到了就到此为止：不截图存档、不转发、不加评论、不拉人一起转。转发和在评论区跟着说，办案时都算传播，「我只是转了一下」不免责。内容出自境外平台的，还可能加重处罚。拿不准真假的更不要跟着转，见本节第 1 条（不转发不知真假的消息）。翻墙工具本身怎么罚，见第 11 节第 11 条。这类内容转出去得不到任何实在的好处，代价却是刑期、剥夺政治权利和没收财产。公开可查的同类案件只见于境外媒体和家属公布的文书，比如一名长期在境外平台发政治评论的博主 2023 年被判 7 年。本书没有拿到官方渠道可核对的判决书，所以只按法条写，没有附案例。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-4', 'concept_archive_s9-4', 'claim_archive_s9-4', 'action', 'life_archive', '黄色视频自己看归自己，别往群里发、别卖「资源」、别建群', '9. 普通人容易踩的法律红线', '自己看不在处罚条款里。往群里发一次就算向全群传播，拘留 10 到 15 日，再罚 5000 元以下，情节严重的判 2 年以下。卖「资源」挣钱的判 3 年以下，最重到无期。建 30 人以上的传播群，建群的、当管理员的、主要往里发的，都按犯罪算。', '这两部法律罚的都是「传播」，私下自己看不在条款里。但往群里发一次，就算向全群传播。「情节严重」到底要多少数量，由司法解释规定，本节没有核实具体数字。', NULL, NULL, NULL, '不花钱。不转发，不存进群文件，也不去当这种群的群主或者管理员。', '在网上传播淫秽信息的，拘留 10 到 15 日，还可以再罚 5000 元以下。情节较轻的那一档，是拘留 5 日以下，或者罚 1000 到 3000 元。内容涉及未成年人的，从重处罚。传播淫秽物品到了「情节严重」这一档的，判 2 年以下。为了挣钱去卖、去传的，判 3 年以下并罚钱。这一项里情节严重的判 3 到 10 年，特别严重的判 10 年以上或者无期徒刑。建一个主要用来传播淫秽电子信息的群，成员到 30 人以上的，按犯罪办。造成严重后果的也一样。建群的人、当管理员的人和主要往里发的人，都按传播淫秽物品罪定罪（全国）', '这两部法律罚的都是「传播」，私下自己看不在条款里。但往群里发一次，就算向全群传播。「情节严重」到底要多少数量，由司法解释规定，本节没有核实具体数字。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-5', 'concept_archive_s9-5', 'claim_archive_s9-5', 'action', 'life_archive', '「兼职」要你用自己的卡收钱、取现、转账，不管给多少好处费都不做', '9. 普通人容易踩的法律红线', '这类兼职挣的是几百块，代价是留一份案底。有人带着身份证和 1 张银行卡去指定地点，配合转账取款，挣了 500 多元。检察院没起诉他，公安还是拘留 10 日、罚 1000 元。另一人把自己和别人的银行卡、手机卡交给团伙收款取现，判 2 年 3 个月，罚 2.2 万元。', '把银行卡借给人、帮人「跑分」的后果，见第 8 节第 8 条（银行卡借给人）。本条讲的是自己动手取现、转账。收了钱换成泰达币这类虚拟币再转出去，也是同一件事。自己买币亏了钱为什么要不回来，见第 5 节第 45 条（别买虚拟货币）。「我不知道钱是哪来的」这句话，办案时不一定认。报酬高得离谱、要你刷脸配合、交易怎么看怎么不正常，凭这几样就能认定你其实知道。最轻的结果也是拘留 10 日，加一份案底。', NULL, NULL, NULL, '不花钱。放弃这类「日结几百、带卡去银行」的活。', '明知是犯罪来的钱和物，还帮着转移、收购、卖掉，或者用别的办法帮着遮掩的，判 3 年以下，并处或者单处罚金（判刑的同时罚钱，也可能只罚钱）。官方案例：王某某按指示带上身份证和 1 张银行卡，到指定地点配合转账取款，赚了 500 余元。检察院没有起诉他，公安按反电信网络诈骗法拘留 10 日，并罚 1000 元。满某某把自己和别人的银行卡、手机卡交给团伙收款、转账、取现，判 2 年 3 个月，并罚 2.2 万元（全国）。换成虚拟币转走也一样：安某某等三人按电诈团伙的指示，用自己的银行卡收钱，在交易平台上买成虚拟货币，再转到对方指定的账户，按比例拿提成。查实其中有被害人被骗的钱 50 余万元。三人以掩饰、隐瞒犯罪所得罪分别判 2 年 8 个月到 3 年 3 个月，各罚 3 万到 4 万元（北京通州）', '把银行卡借给人、帮人「跑分」的后果，见第 8 节第 8 条（银行卡借给人）。本条讲的是自己动手取现、转账。收了钱换成泰达币这类虚拟币再转出去，也是同一件事。自己买币亏了钱为什么要不回来，见第 5 节第 45 条（别买虚拟货币）。「我不知道钱是哪来的」这句话，办案时不一定认。报酬高得离谱、要你刷脸配合、交易怎么看怎么不正常，凭这几样就能认定你其实知道。最轻的结果也是拘留 10 日，加一份案底。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-6', 'concept_archive_s9-6', 'claim_archive_s9-6', 'action', 'life_archive', '有人拉你去「包装材料」贷款、按贷款额分你好处费，一个都不做', '9. 普通人容易踩的法律红线', '帮人「包装材料」去贷款、拿分成，按诈骗办。有个 126 人的团伙，把没工作的人包装成「优质客户」，在 80 多家银行骗贷 3000 多万元。出面签字的按贷款额拿三成好处费，已判的 80 人里 76 人判了 1 年 4 个月到 6 年 6 个月。钱贷在谁名下，债就是谁的。', '「我当时是想还的」这句话，在那个案子里没被采纳。检察机关查明这些人没工作、没固定资产，根本还不上，分到的钱又都花了，据此认定他们本来就没打算还。替团伙把钱取出来的，还可能另外加一条洗钱罪。钱贷在谁名下、合同谁签的字，谁就是借款人。就算不构成犯罪，这笔债和征信上的记录也是自己的。拿了钱跑到境外一样了结不了：立案之后再躲，过多少年都还能追。判了刑没服完的、正被当成犯罪嫌疑人或者被告人的，都不准出境。民事案子没了结的，法院可以不让你出境；被执行人不履行的，法院也能限制出境。替人取现、转账见本节第 5 条（「兼职」要你用自己的卡收钱），自己被人冒名贷款了怎么发现，见第 8 节第 9 条。', NULL, NULL, NULL, '不花钱。直接拒绝。不把身份证和自己的征信记录借给别人用，不签没看过的贷款合同，也不替人去银行面签。', '用骗的手段，从银行或者其他金融机构拿到贷款、票据承兑、信用证、保函等。给银行或者其他金融机构造成重大损失的，判 3 年以下。还要并处或者单处罚金，判刑的同时罚钱，也可能只罚钱。造成特别重大损失，或者有其他特别严重情节的，判 3 到 7 年并罚钱。警方立案追查的起点，是直接经济损失 50 万元以上。本来就没打算还，用编造的引进资金项目理由、假的经济合同、假的证明文件或者假的产权证明去骗贷款的，是贷款诈骗罪。这一项骗到 5 万元就立案，判 5 年以下并罚 2 万到 20 万元。数额巨大或者有其他严重情节的判 5 到 10 年，特别巨大的判 10 年以上直到无期徒刑。伪造、涂改、买卖国家机关的公文、证件、印章，判 3 年以下，情节严重的判 3 到 10 年。官方案例：一个 126 人的团伙，在 16 个省市把没工作的人包装成「优质客户」，在 80 多家银行网点骗贷 3000 余万元。出面贷款的「白户」按贷款金额的三成拿好处费。检察院追诉了 105 名「白户」。2026 年一审已判的 80 人里，76 人以贷款诈骗罪判 1 年 4 个月到 6 年 6 个月并罚钱。另有 4 人因为替团伙取现，被以贷款诈骗罪、洗钱罪数罪并罚（两个罪一起算刑期）。这 4 人判 2 年 4 个月到 7 年 6 个月（全国）。本条的骗取贷款罪，按刑法修正案（十一）2021 年 3 月起的文本。', '「我当时是想还的」这句话，在那个案子里没被采纳。检察机关查明这些人没工作、没固定资产，根本还不上，分到的钱又都花了，据此认定他们本来就没打算还。替团伙把钱取出来的，还可能另外加一条洗钱罪。钱贷在谁名下、合同谁签的字，谁就是借款人。就算不构成犯罪，这笔债和征信上的记录也是自己的。拿了钱跑到境外一样了结不了：立案之后再躲，过多少年都还能追。判了刑没服完的、正被当成犯罪嫌疑人或者被告人的，都不准出境。民事案子没了结的，法院可以不让你出境；被执行人不履行的，法院也能限制出境。替人取现、转账见本节第 5 条（「兼职」要你用自己的卡收钱），自己被人冒名贷款了怎么发现，见第 8 节第 9 条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-7', 'concept_archive_s9-7', 'claim_archive_s9-7', 'action', 'life_archive', '捡到银行卡不取钱，捡到手机、钱包联系失主或交给警察，不揣走', '9. 普通人容易踩的法律红线', '捡到东西留着自己用，金额到了「数额较大」又不肯交出来，判 2 年以下，数额巨大的判 2 到 5 年。拿捡来的银行卡去 ATM 取钱更重，算冒用别人的信用卡，数额较大就判 5 年以下，还要罚 2 万到 20 万元。取钱这一种警察直接立案，不用失主自己去告。', '侵占罪是「告诉的才处理」，得失主自己去法院起诉，警察不主动管。但拿捡来的卡取钱不一样，不用失主去告，警察直接立案。「数额较大」具体是多少钱，由司法解释规定，本节没有核实。东西送交有关部门之后，失主来领的时候要付保管费用（民法典第三百一十七条）。', NULL, NULL, NULL, '不花钱，几分钟的事。打个电话找失主，或者把东西送到派出所。', '捡到别人丢的东西，要还给失主，及时通知他来领，或者送交公安等部门。把别人落下的东西留着自己用，金额到了「数额较大」又不肯交出来的，构成侵占罪，判 2 年以下。数额巨大的判 2 到 5 年。捡到别人的信用卡拿到 ATM 上用，属于「冒用他人信用卡」。够得上犯罪的，按信用卡诈骗罪处理：数额较大的判 5 年以下，并罚 2 万到 20 万元。数额巨大或者有其他严重情节的，判 5 到 10 年，并罚 5 万到 50 万元（全国）', '侵占罪是「告诉的才处理」，得失主自己去法院起诉，警察不主动管。但拿捡来的卡取钱不一样，不用失主去告，警察直接立案。「数额较大」具体是多少钱，由司法解释规定，本节没有核实。东西送交有关部门之后，失主来领的时候要付保管费用（民法典第三百一十七条）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-8', 'concept_archive_s9-8', 'claim_archive_s9-8', 'action', 'life_archive', '优惠用自己的真实身份领，不买虚拟号批量注册小号，不靠漏洞重复领', '9. 普通人容易踩的法律红线', '用自己的真实身份、一个号领一次券，不在处罚范围里。批量注册假用户、自己下单自己接单去多领，按诈骗办，骗到 3000 元就能判 3 年以下，3 万元起判 3 到 10 年。有骑手用 0.1 元一个的虚拟号刷券，套现 9 万余元，同案 12 人都被判了刑。', '界线不在「薅了多少」，在有没有编假的。用自己的真实身份参加活动、一个号领一次、券用在自己身上，那是平台给你的优惠。为了多领去注册假用户、编造交易、瞒着自己已经退过款，就是让对方误以为是真的才把东西交出来，按诈骗认定，金额只决定判多久。车企的免费充电也有人这么薅过。2026 年 8 月看看新闻报道，上海两人买来大量虚拟手机号，轮流绑成某新能源车企 App 的子账号。每个号用「先充后付」充两次电就解绑，电费没人付，充电机会再卖给货车司机。浦东新区检察院认为这是诈骗，不是盗窃，已经批准逮捕。此案只有媒体报道，没有判决或官方通报。金额不够判刑的也有后果：平台可以封号、扣回优惠，还能按「不该得的钱要退回来」要求你返还。参与电诈、没到犯罪程度的，还有拘留和罚款那一档。「群里有人带、按单给我钱」不改变你自己这一份的性质。把方法教给别人、倒卖账号和手机号，是另外的罪名，几个罪会一起算账。受益人是你自己。自己写脚本、卖脚本见第 11 节第 3 条，卖卡、卖账号见第 8 节第 8 条（银行卡借给人）和本节第 16 条（身份证不借人）。', NULL, NULL, NULL, '不花钱。放弃「羊毛任务群」里的活。发现平台有漏洞，不去碰它。难在忍住不把优惠当成可以批量复制的收入。', '骗别人或者公家的财物，数额较大的判 3 年以下，并处或者单处罚金（判刑的同时罚钱，也可能只罚钱）。数额巨大，或者有其他严重情节的，判 3 到 10 年并罚钱。数额特别巨大，或者有其他特别严重情节的，判 10 年以上或者无期徒刑，并罚钱或者没收财产。数额较大、巨大、特别巨大这三档，各省在下面的幅度内定本地标准。较大是 3000 元至 1 万元以上。巨大是 3 万元至 10 万元以上，特别巨大是 50 万元以上。把方法教给别人、卖「教程」的，按传授犯罪方法罪判 5 年以下，情节严重的判 5 到 10 年，特别严重的判 10 年以上或者无期徒刑。买卖手机号、验证码的上下游，按侵犯公民个人信息罪判 3 年以下，特别严重的判 3 到 7 年。用批量账号、网络地址自动切换系统，以及批量接收短信验证的接码平台，本身就是反电信网络诈骗法第十四条明令禁止的。非法买卖、出租、出借电话卡和互联网账号、帮别人过实名核验，在第三十一条之列。违反第十四条的，赚到的钱全部没收，再按赚到的钱罚 1 到 10 倍。没赚到钱，或者赚的不到 5 万元的，罚 50 万元以下，情节严重的还要拘留 15 日以下。违反第三十一条的，罚款同样是 1 到 10 倍，没赚到钱或者赚的不到 2 万元的罚 20 万元以下，情节严重的也要拘留 15 日以下。参与电信网络诈骗、还不够判刑的，拘留 10 到 15 日。赚到的钱没收，再罚 1 到 10 倍。没赚到钱或者赚的不到 1 万元的，罚 10 万元以下。官方案例一：外卖骑手刘某某以 0.1 元一个买虚拟手机号，注册某平台新用户。他领满 29 减 15 的新人券下单，再把商品倒卖给小商铺套现。他还用虚拟号互相邀请，领 2 元至 20 元的奖励金。他和骑手谭某某分别骗得 9 万余元和 7 万余元。上海杨浦区检察院以诈骗罪起诉 12 人，法院判 3 年 6 个月至拘役 3 个月。官方案例二：王某利用网店退款与回收虚拟抽奖币的时间差。他退款 1156 笔，提走手办 224 件，金额 24.9 万余元。他还在二手平台变现，法院以诈骗罪判 3 年缓 4 年，并处罚金 3 万元。他在审理期间退赃并预缴罚金，共 33 万元。官方案例三：某网约车平台的新用户优惠券和司机补贴，被「自己打车自己接单」的虚假跑单骗取，涉及 19 省 70 余市，金额 200 余万元。辽宁朝阳龙城区检察院起诉 163 人，全部被判有罪。主犯黄某、蔡某以诈骗罪、侵犯公民个人信息罪、传授犯罪方法罪数罪并罚（几个罪一起算刑期），各判 3 年 6 个月。另有 34 名情节轻微的从犯，检察院决定不起诉，仍然移送公安作行政处罚（全国）', '界线不在「薅了多少」，在有没有编假的。用自己的真实身份参加活动、一个号领一次、券用在自己身上，那是平台给你的优惠。为了多领去注册假用户、编造交易、瞒着自己已经退过款，就是让对方误以为是真的才把东西交出来，按诈骗认定，金额只决定判多久。车企的免费充电也有人这么薅过。2026 年 8 月看看新闻报道，上海两人买来大量虚拟手机号，轮流绑成某新能源车企 App 的子账号。每个号用「先充后付」充两次电就解绑，电费没人付，充电机会再卖给货车司机。浦东新区检察院认为这是诈骗，不是盗窃，已经批准逮捕。此案只有媒体报道，没有判决或官方通报。金额不够判刑的也有后果：平台可以封号、扣回优惠，还能按「不该得的钱要退回来」要求你返还。参与电诈、没到犯罪程度的，还有拘留和罚款那一档。「群里有人带、按单给我钱」不改变你自己这一份的性质。把方法教给别人、倒卖账号和手机号，是另外的罪名，几个罪会一起算账。受益人是你自己。自己写脚本、卖脚本见第 11 节第 3 条，卖卡、卖账号见第 8 节第 8 条（银行卡借给人）和本节第 16 条（身份证不借人）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-9', 'concept_archive_s9-9', 'claim_archive_s9-9', 'action', 'life_archive', '阳台、窗户不往外扔任何东西，烟头、垃圾袋、酒瓶都算', '9. 普通人容易踩的法律红线', '往楼下扔东西，没砸到人也能拘留 5 日、罚 1000 元，情节严重的拘留 10 到 15 日。砸到人就换罪名了：有人在 21 楼酒后把空酒瓶、玻璃杯扔到楼下操场，砸中 13 岁学生致重伤，判 10 年。还有人从 32 楼扔 8 块砖头砸死 1 人，2024 年被核准死刑。', '没砸到人也能拘留，条文只要求「有危险」。民法典对高空抛物另有一条民事赔偿规定（第一千二百五十四条）。本节写作时没能打开原文，所以没有引用。', NULL, NULL, NULL, '不花钱，也不费时间。烟头、垃圾袋、酒瓶都拿到屋里的垃圾桶扔，不从窗口和阳台往外丢。', '从楼上或者其他高处往下扔东西，只要有伤到人、砸坏财物或者危及公共安全的危险，就可以拘留 5 日以下，或者罚 1000 元以下。情节严重的拘留 10 到 15 日，还可以再罚 1000 元以下。情节严重到构成高空抛物罪的，判 1 年以下，并处或者单处罚金（判刑的同时罚钱，也可能只罚钱）。砸伤砸死人的，按更重的罪名处理。官方案例：李某晨在 21 楼酒后把空酒瓶、玻璃杯扔到楼下操场，砸中 13 岁学生致重伤二级，以危险方法危害公共安全罪判 10 年。周某从 32 楼向人群投掷 8 块砖头砸死 1 人，2024 年最高法核准死刑（全国）', '没砸到人也能拘留，条文只要求「有危险」。民法典对高空抛物另有一条民事赔偿规定（第一千二百五十四条）。本节写作时没能打开原文，所以没有引用。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-10', 'concept_archive_s9-10', 'claim_archive_s9-10', 'action', 'life_archive', '不网购仿真枪、钢珠枪、气枪，不买来路不明的「玩具枪」', '9. 普通人容易踩的法律红线', '网上买的钢珠枪、气枪，枪口比动能到了 1.8 焦耳/平方厘米，就按枪支认定。没有许可拿在手里，判 3 年以下，情节严重的判 3 到 7 年。有对夫妇卖「玩具枪」，43 支里有 18 支被鉴定为枪，只因证明不了他们知情才没被起诉。', '那起案子不起诉的关键，是认定他们「不明知」。成年人特意上网买钢珠枪、气枪，事后再说不知道那是枪，很难成立。弩和管制刀具随身带的罚则，见本节第 26 条（别为了防身买甩棍、电击器、匕首）。', NULL, NULL, NULL, '不花钱。想打枪，去正规射击馆。', '没有许可就持有、私藏枪支的，判 3 年以下，情节严重的判 3 到 7 年。打不了制式子弹的非制式枪，只要枪口比动能大于等于 1.8 焦耳/平方厘米，一律认定为枪支。枪口比动能，指的是子弹出膛时每平方厘米带的能量。不少网上买的钢珠枪、气枪都超过这个数。2018 年起最高法、最高检要求，对比动能偏低的气枪，要综合外观、材质、价格、用途、本人是不是知情等等评估之后，再决定要不要定罪。官方案例：赵某某夫妇在集贸市场卖「玩具枪」，查获 43 支，其中 18 支经鉴定符合枪支标准。因为没有充分证据证明他们知道那是枪支，按证据存疑不起诉（全国）', '那起案子不起诉的关键，是认定他们「不明知」。成年人特意上网买钢珠枪、气枪，事后再说不知道那是枪，很难成立。弩和管制刀具随身带的罚则，见本节第 26 条（别为了防身买甩棍、电击器、匕首）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-11', 'concept_archive_s9-11', 'claim_archive_s9-11', 'action', 'life_archive', '买了无人机先实名登记，机场、军事区和城市管制空域不飞，不破解限高', '9. 普通人容易踩的法律红线', '没实名登记就飞，罚 200 元以下，情节严重的罚 2000 到 2 万元。没批准在管制空域飞，罚 500 元以下，情节严重的没收无人机，再罚 1000 到 1 万元。情节较重的还能拘留 5 到 10 日。有人花钱破解限高，飞到近 3000 米拍云层发到网上，被拘留 5 日。', '微型和轻型无人机在适飞空域飞，不用批准。微型指空机重量小于 0.25 千克的那种。适飞空域就是管制空域以外的地方，而机场、军事设施、政府机关周边多半属于管制空域。公安部的原文页面本节写作时打不开，所以引用的是湖北省公安厅的转载页。', NULL, NULL, NULL, '实名登记不花钱，几分钟就办完。每次起飞前，用官方渠道查一下要飞的这块地方是不是管制空域。', '没做实名登记就飞的，责令改正，还可以罚 200 元以下，情节严重的罚 2000 到 2 万元。没批准就在管制空域飞微型、轻型、小型无人机的，责令停止飞行，还可以罚 500 元以下。这一项里情节严重的，没收无人机，并罚 1000 到 1 万元。违反空域管理规定飞行、情节较重的，拘留 5 到 10 日。官方案例：李某某付费破解限高，把无人机飞到近 3000 米拍云层并发布，拘留 5 日。张某某替人破解限高和禁飞区限制 20 余台次，赚了 1.5 万余元。他被以提供侵入、非法控制计算机信息系统程序、工具罪定罪。判 6 个月，缓刑 1 年，并处罚金（全国，2024 年 1 月起）', '微型和轻型无人机在适飞空域飞，不用批准。微型指空机重量小于 0.25 千克的那种。适飞空域就是管制空域以外的地方，而机场、军事设施、政府机关周边多半属于管制空域。公安部的原文页面本节写作时打不开，所以引用的是湖北省公安厅的转载页。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-12', 'concept_archive_s9-12', 'claim_archive_s9-12', 'action', 'life_archive', '不偷拍别人，不在出租屋、民宿、酒店房间装摄像头', '9. 普通人容易踩的法律红线', '偷拍、偷窥、散布别人的隐私，拘留 5 日以下或者罚 1000 元以下，情节较重的拘留 5 到 10 日。用专门的偷拍设备、造成严重后果的，判 2 年以下。有两人在三家酒店的房间装器材远程偷拍，分别判了 1 年 3 个月和 1 年。家里装监控不算，装在别人住的房间就算。', '偷拍的东西一旦拿去卖或者传播，另按制作、贩卖淫秽物品牟利等罪处理，同一批案例里有判 10 年的。自己家里装监控不算，装在别人使用的房间里就算。', NULL, NULL, NULL, '不花钱，也不费时间。不偷拍别人，也不在出租屋、民宿、酒店房间里装摄像头。', '偷窥、偷拍、窃听、散布别人隐私的，拘留 5 日以下，或者罚 1000 元以下。情节较重的拘留 5 到 10 日，还可以再罚 1000 元以下。非法使用窃听、窃照专用器材、造成严重后果的，判 2 年以下。窃听、窃照专用器材，指专门用来偷听、偷拍的设备。官方案例：颜某平、颜某建在网上买了窃照器材，装进三家酒店的多个房间远程偷拍，分别判 1 年 3 个月和 1 年（全国）', '偷拍的东西一旦拿去卖或者传播，另按制作、贩卖淫秽物品牟利等罪处理，同一批案例里有判 10 年的。自己家里装监控不算，装在别人使用的房间里就算。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-13', 'concept_archive_s9-13', 'claim_archive_s9-13', 'action', 'life_archive', '麻将、扑克可以打，不抽头、不当庄、不组局收钱，不玩网络赌博', '9. 普通人容易踩的法律红线', '亲友之间小额打牌，法律不管。从局里抽头、当庄、组局收钱，性质就变了：参与赌博、赌资较大的，拘留 5 日以下或者罚 1000 元以下。聚众赌博、靠赌博过日子的判 3 年以下，开赌场的判 5 年以下。多少算「赌资较大」，各地自己定，没有全国统一数字。', '多少算「赌资较大」没有全国统一数字，各地自己定，所以这条只给 B 级。从局里抽成、替网络赌博平台代收投注，办案时常常按开设赌场认定。相关的司法解释原文本节没有核实。也没有找到官方案例。', NULL, NULL, NULL, '不花钱。亲友之间小额娱乐照打。不从局里抽成，不当庄，不组局收钱。难在有人张罗时忍住不去接手。', '为了挣钱给赌博提供便利条件，或者参与赌博、赌资较大的，拘留 5 日以下，或者罚 1000 元以下。情节严重的拘留 10 到 15 日，并罚 1000 到 5000 元。为了挣钱把人聚起来赌，或者靠赌博过日子的，判 3 年以下并罚钱。开赌场的判 5 年以下并罚钱，情节严重的判 5 到 10 年（全国）', '多少算「赌资较大」没有全国统一数字，各地自己定，所以这条只给 B 级。从局里抽成、替网络赌博平台代收投注，办案时常常按开设赌场认定。相关的司法解释原文本节没有核实。也没有找到官方案例。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","B 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-14', 'concept_archive_s9-14', 'claim_archive_s9-14', 'action', 'life_archive', '不吃野味，不买卖、不养保护动物当宠物', '9. 普通人容易踩的法律红线', '吃国家重点保护动物，东西没收，再按价值罚 2 到 20 倍。收购、运输、出售珍贵濒危动物，判 5 年以下，情节严重的判 5 到 10 年。人工繁育、当宠物买卖的一般不算犯罪，有人卖了 40 多只人工繁育的鹦鹉，没被起诉。野外抓的、来路不明的不在此列。', '「一般不作为犯罪」说的只是人工繁育、当宠物养的那一类。野外抓的、来路不明的不适用。哪些算国家重点保护动物，以名录为准。买之前先查一下名录，比出事以后再解释省事。', NULL, NULL, NULL, '不花钱。宠物只买来源合法、人工繁育的品种。', '吃国家重点保护野生动物，或者为了吃去买的，东西没收，再按它的价值罚 2 到 20 倍的钱。没有许可证就繁育国家重点保护野生动物的，没收，并罚 1 到 10 倍。非法收购、运输、出售国家重点保护的珍贵、濒危野生动物和它们的制品，判 5 年以下并罚钱。这一项里情节严重的判 5 到 10 年，特别严重的判 10 年以上。为了吃而猎捕、收购、运输、出售其他陆生野生动物，情节严重的判 3 年以下。官方案例：养殖户王某等 3 人卖了 40 余只人工繁育的费氏牡丹鹦鹉（国家二级保护），总价不到 400 元，2021 年检察院决定不起诉。2022 年起最高法、最高检明确，人工繁育技术成熟、已经成规模、当宠物买卖运输的，一般不按犯罪处理（全国）', '「一般不作为犯罪」说的只是人工繁育、当宠物养的那一类。野外抓的、来路不明的不适用。哪些算国家重点保护动物，以名录为准。买之前先查一下名录，比出事以后再解释省事。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-15', 'concept_archive_s9-15', 'claim_archive_s9-15', 'action', 'life_archive', '要债不扣人、不关人、不跟到家里赖着不让走', '9. 普通人容易踩的法律红线', '钱是真欠你的，也不能扣人、关人。法条专门写了：为了讨债扣人、关人，照样按非法拘禁办。轻的拘留 10 到 15 日，并罚 1000 到 2000 元。构成非法拘禁罪的判 3 年以下，把人弄成重伤的判 3 到 10 年，弄死人的判 10 年以上。要债去法院起诉。', '「他确实欠我钱」这句话在这条里不管用。法条专门写了，为了讨债扣人、关人也按非法拘禁办。中国法院网上有好几起案子，都是讨合法债务把人关起来，判了 7 个月到 1 年。本节写作时该网站打不开，所以没有引用。', NULL, NULL, NULL, '不花钱。对方欠钱不还，去法院起诉。借条怎么写，见第 8 节第 18 条（借条）。难在对方赖账时忍住不动手、不跟到他家去。', '非法限制别人的人身自由、擅自闯进别人家，或者非法搜别人的身，拘留 10 到 15 日，并罚 1000 到 2000 元。情节较轻的拘留 5 到 10 日，并罚 1000 元以下。非法拘禁判 3 年以下有期徒刑、拘役（短期关押）、管制（不关押但行动受限）或者剥夺政治权利。把人弄成重伤的判 3 到 10 年，弄死人的判 10 年以上。为了讨债扣人、关人的，照这同一套规定处罚，债是真的也一样（全国）', '「他确实欠我钱」这句话在这条里不管用。法条专门写了，为了讨债扣人、关人也按非法拘禁办。中国法院网上有好几起案子，都是讨合法债务把人关起来，判了 7 个月到 1 年。本节写作时该网站打不开，所以没有引用。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-16', 'concept_archive_s9-16', 'claim_archive_s9-16', 'action', 'life_archive', '身份证不借人，不用别人的身份证，也不拿别人的证件登记、开卡、买票', '9. 普通人容易踩的法律红线', '把身份证借给、租给、转给别人，警告并罚 200 元以下。冒用别人的身份证，或者用骗领来的，罚 200 到 1000 元，或者拘留 10 日以内。买火车票、住店这类必须实名的场合用假证件或者别人的证件，情节严重的判拘役或者管制。', '身份证借出去，可能被拿去注册公司、办银行卡。这两样的后果见第 8 节第 28、8 条（别当挂名法人、不把银行卡借给人）。用别人的身份证买火车票、住店，属于法条说的「应当提供身份证明的活动」。本条没有找到官方案例。去网吧上网也一样用自己的证。网吧必须核对登记身份证，登记内容和上网记录至少存 60 天，公安和文化部门随时能调。用谁的证上网，那段时间机器上干的事就记在谁头上。', NULL, NULL, NULL, '不花钱。有人开口借，拒绝就行。要给复印件的，在复印件上写明这份只用在哪件事上。', '把自己的居民身份证出租、出借、转让给别人的，警告并罚 200 元以下。冒用别人的身份证，或者使用骗领来的身份证，罚 200 到 1000 元，或者拘留 10 日以下。购买、出售、使用伪造变造的身份证的，也是这一档。有些场合按国家规定必须出示身份证明。在这些场合使用伪造、变造或者盗用别人的证件，情节严重的就要判刑。证件包括身份证、护照、社保卡、驾驶证等。刑罚是拘役（短期关押）或者管制（不关押但行动受限），还要并处或者单处罚金，判刑的同时罚钱，也可能只罚钱（全国）', '身份证借出去，可能被拿去注册公司、办银行卡。这两样的后果见第 8 节第 28、8 条（别当挂名法人、不把银行卡借给人）。用别人的身份证买火车票、住店，属于法条说的「应当提供身份证明的活动」。本条没有找到官方案例。去网吧上网也一样用自己的证。网吧必须核对登记身份证，登记内容和上网记录至少存 60 天，公安和文化部门随时能调。用谁的证上网，那段时间机器上干的事就记在谁头上。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-17', 'concept_archive_s9-17', 'claim_archive_s9-17', 'action', 'life_archive', '被警察拦下或带走时配合，不推、不打、不抢执法记录仪，喝了酒更要忍', '9. 普通人容易踩的法律红线', '现场阻碍执法，警告或者罚 500 元以下，情节严重的拘留 5 到 10 日。对警察动手是另一档：撕咬、掌掴、踢打、抱摔、扔东西，造成轻微伤以上就算暴力袭警，判 3 年以下。用枪支、管制刀具或者开车撞的，判 3 到 7 年。甩手、挣脱这类一般的抗拒不算。', '最高检 2021 年通报，袭警单独定罪之后的头一个月，就批准逮捕 405 人。江苏的 42 件里，酒后闹事引起的占 47.6%。湖北的 16 件里有 12 件，只是拳打脚踢、撕咬这种程度。对辅警动手，按妨害公务罪办。本条没有找到写明个人案情的官方案例。', NULL, NULL, NULL, '不花钱。现场不动手。有意见等事后再提：投诉、申请行政复议、去法院起诉。难在被拦下的那几分钟里、尤其喝了酒时忍住脾气。', '阻碍国家机关工作人员依法办公务的，警告或者罚 500 元以下。情节严重的拘留 5 到 10 日，还可以再罚 1000 元以下。阻碍的是人民警察，就从重处罚。暴力袭击正在依法执行职务的人民警察，判 3 年以下。用枪支、管制刀具或者开车撞等严重危及警察人身安全的，判 3 到 7 年。撕咬、掌掴、踢打、抱摔、投掷物品造成轻微伤以上的，才算「暴力袭击」。甩手、挣脱、蹬腿这类一般性抗拒不算（全国）', '最高检 2021 年通报，袭警单独定罪之后的头一个月，就批准逮捕 405 人。江苏的 42 件里，酒后闹事引起的占 47.6%。湖北的 16 件里有 12 件，只是拳打脚踢、撕咬这种程度。对辅警动手，按妨害公务罪办。本条没有找到写明个人案情的官方案例。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-18', 'concept_archive_s9-18', 'claim_archive_s9-18', 'action', 'life_archive', '对方不满 14 岁就不能发生关系，「她同意」不是理由', '9. 普通人容易踩的法律红线', '对方不满 14 岁，不管她同不同意，都按强奸罪从重处理，基本刑期是 3 到 10 年。对方不满 12 岁的，一律认定你「应当知道」。12 到 14 岁的，从发育、举止、穿着能看出可能是幼女，你还下手，就认定你「明知」。说自己确实不知道，法院把关很严。', '两高两部关于办理性侵害未成年人刑事案件的意见原文，以及最高法 2003 年批复的页面，本节写作时都打不开。所以「明知」的认定标准，引的是最高法官网上的答复。法条里的用语是「幼女」。本条不区分动手的人是男是女。', NULL, NULL, NULL, '不花钱。对方的年龄不确定，就不要发生关系。', '和不满 14 周岁的幼女发生性关系的，按强奸罪处理并从重处罚，基础刑期 3 到 10 年。最高法的口径是这样：用暴力、胁迫等强制手段的，不管知不知道对方是幼女，都定强奸罪。没用强制手段的，对不满 12 周岁的一律认定「应当知道」。12 到 14 周岁的，从身体发育、言谈举止、衣着等能看出可能是幼女，还下手的，认定为「明知」。「确实不知道」这个例外把握得很严（全国）', '两高两部关于办理性侵害未成年人刑事案件的意见原文，以及最高法 2003 年批复的页面，本节写作时都打不开。所以「明知」的认定标准，引的是最高法官网上的答复。法条里的用语是「幼女」。本条不区分动手的人是男是女。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-19', 'concept_archive_s9-19', 'claim_archive_s9-19', 'action', 'life_archive', '动手打人前算清这笔账：拘留、赔钱、判刑', '9. 普通人容易踩的法律红线', '动手一次的账：拘留 5 到 10 日，加罚 500 到 1000 元。打成轻伤就是刑事案件，判 3 年以下，打成重伤判 3 到 10 年。钱另算：有人打断对方三根肋骨，赔了 11.3 万元和解，才没被起诉。另一人打断对方桡骨，没赔，判了 10 个月。', '怎么避免冲突、先动手为什么吃亏、正当防卫的边界在哪，见第 8 节第 10 条（冲突和正当防卫）。为了泄愤对人下手的账，见第 8 节第 11 到 14 条。因民间纠纷引起、情节较轻的打架，公安可以调解。打成轻伤的，跟对方谈妥赔偿并且真赔了，可以从轻，甚至不起诉，但赔的钱一分都少不了。伤到什么程度算轻伤，由鉴定标准定，本节没有核实。误工费、护理费按实际收入和耽误的天数算，没有统一数字。', NULL, NULL, NULL, '不花钱，也不花时间。难的就是动手前的那几秒钟。', '打人或者故意伤害的，拘留 5 到 10 日，并罚 500 到 1000 元。结伙打、打残疾人孕妇老人小孩、多次打或者一次打好几个人的，拘留 10 到 15 日，并罚 1000 到 2000 元。打成轻伤就是故意伤害罪，判 3 年以下有期徒刑、拘役（短期关押）或者管制（不关押但行动受限）。打成重伤的判 3 到 10 年。民事上还要赔医疗费、误工费（耽误上班少挣的钱）、护理费、交通费、住院伙食补助费、营养费。把人打残的，另外赔残疾赔偿金。残疾赔偿金的算法，是审案法院所在地上年度城镇居民人均可支配收入乘 20 年。伤者 60 岁以上的，每多一岁减一年，75 岁以上按 5 年算。2022 年全国检察机关受理轻伤害案件 7 万余件，多数是婚姻家庭邻里纠纷或者偶然事件引起的。最高检典型案例：卢某打断对方三根肋骨（轻伤二级），赔了 11.3 万元达成和解，才获不起诉。石某打断对方桡骨（轻伤二级），没有赔，判有期徒刑十个月（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', '怎么避免冲突、先动手为什么吃亏、正当防卫的边界在哪，见第 8 节第 10 条（冲突和正当防卫）。为了泄愤对人下手的账，见第 8 节第 11 到 14 条。因民间纠纷引起、情节较轻的打架，公安可以调解。打成轻伤的，跟对方谈妥赔偿并且真赔了，可以从轻，甚至不起诉，但赔的钱一分都少不了。伤到什么程度算轻伤，由鉴定标准定，本节没有核实。误工费、护理费按实际收入和耽误的天数算，没有统一数字。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-20', 'concept_archive_s9-20', 'claim_archive_s9-20', 'action', 'life_archive', '孩子生下来养不了，只有民政登记这一条合法出路：收钱把孩子给人可能按拐卖罪判，扔下不管是遗弃罪', '9. 普通人容易踩的法律红线', '养不了有出路，但合法的只有一条：到民政部门办收养登记，收养关系从登记那天才成立。私下把孩子给人，尤其是收了钱，可能从「送养」变成拐卖儿童罪，起刑就是 5 年以上。把孩子扔下不管、拒不抚养，情节恶劣的是遗弃罪，判 5 年以下。', '要不要生这里不谈。孩子生下来之后，按这个顺序走最省事。第一步，去医院生，产检和住院分娩见第 27 节。出生医学证明是后面所有手续的前提。第二步，要送养就直接找县级以上民政部门，别经由中间人。钱一旦过手，性质就可能变。产后一年之内，如果出现「有伤害自己或者伤害孩子的念头」，按急症处理。孕期和产后要立刻去医院的清单，见第 27 节第 7 条。产后 42 天复查同时是产后抑郁筛查，见第 27 节第 16 条。有自杀念头时打 12356，见第 1 节第 25 条。本条没有配案例：拐卖亲生子女的官方典型案例，本轮没有逐案核对，所以只引了条文和意见原文。', NULL, NULL, NULL, '不花钱。到县级以上民政部门办收养登记，要交材料，还要等审核和收养评估，前后要花些时间。', '刑法第二百四十条：「拐卖妇女、儿童的，处五年以上十年以下有期徒刑，并处罚金」。有加重情形的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。「情节特别严重的，处死刑，并处没收财产」。《关于依法惩治拐卖妇女儿童犯罪的意见》第 17 条，说的是怎么区分卖亲生孩子和民间送养。判断标准是「关键在于行为人是否具有非法获利的目的」。也就是看有没有想靠这件事挣钱。有三种情形可以认定为出卖亲生子女，按拐卖妇女、儿童罪定罪。第一种是「将生育作为非法获利手段，生育后即出卖子女的」。第二种是「明知对方不具有抚养目的，或者根本不考虑对方是否具有抚养目的，为收取钱财将子女『送』给他人的」。第三种是「为收取明显不属于『营养费』『感谢费』的巨额钱财将子女『送』给他人的」。反过来，不是为了挣钱、确实迫于生活困难私自送养、只收少量营养费感谢费的，属于民间送养，不按拐卖罪定罪。再看刑法第二百六十一条。「对于年老、年幼、患病或者其他没有独立生活能力的人，负有扶养义务而拒绝扶养，情节恶劣的，处五年以下有期徒刑、拘役或者管制」。民法典第一千零九十四条规定，能当送养人的只有三种：孤儿的监护人、儿童福利机构、有特殊困难无力抚养子女的生父母。第一千一百零五条：「收养应当向县级以上人民政府民政部门登记。收养关系自登记之日起成立」', '要不要生这里不谈。孩子生下来之后，按这个顺序走最省事。第一步，去医院生，产检和住院分娩见第 27 节。出生医学证明是后面所有手续的前提。第二步，要送养就直接找县级以上民政部门，别经由中间人。钱一旦过手，性质就可能变。产后一年之内，如果出现「有伤害自己或者伤害孩子的念头」，按急症处理。孕期和产后要立刻去医院的清单，见第 27 节第 7 条。产后 42 天复查同时是产后抑郁筛查，见第 27 节第 16 条。有自杀念头时打 12356，见第 1 节第 25 条。本条没有配案例：拐卖亲生子女的官方典型案例，本轮没有逐案核对，所以只引了条文和意见原文。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-21', 'concept_archive_s9-21', 'claim_archive_s9-21', 'action', 'life_archive', '别伪造事故、别夸大损失骗理赔：这是保险诈骗罪，帮你作证、帮你修车、帮你鉴定的人一起算', '9. 普通人容易踩的法律红线', '编造事故、夸大损失去骗理赔，是保险诈骗罪，数额较大的判 5 年以下，再罚 1 万到 10 万元。帮你作证、鉴定、评估财产的人故意出假证明，和你一起按共犯定罪。安徽宣城一起案子里，8 个人被判 2 到 4 年，各罚 1 万元。', '下面几种自以为无害的做法都在这五项里。出了小事故找修理厂「多报一点」，把旧伤旧损算进这一次，和朋友对撞一下再报案，没出事却编一个出来。车险该怎么买，见第 5 节第 26 条（三者险买够）。给家人投保后故意造成他死亡的，法条明确要数罪并罚，见第 8 节第 38 条（给家人投保）。医保是另一套规则，空刷医保卡、拿医保个人账户套现按诈骗办，见第 5 节第 13 条的备注', NULL, NULL, NULL, '不花钱，也不费时间，不去做就行。', '刑法第一百九十八条列了五种情形。（一）投保人故意虚构保险标的，编一个根本不存在的投保对象。（二）投保人、被保险人或者受益人对发生的保险事故编造虚假的原因，或者夸大损失的程度。（三）编造未曾发生的保险事故。（四）投保人、被保险人故意造成财产损失的保险事故。（五）投保人、受益人故意造成被保险人死亡、伤残或者疾病。数额较大的，处 5 年以下有期徒刑或者拘役，并处 1 万元以上 10 万元以下罚金。数额巨大或者有其他严重情节的，处 5 至 10 年，并处 2 万至 20 万元罚金。数额特别巨大或者有其他特别严重情节的，处 10 年以上，并处 2 万至 20 万元罚金或者没收财产。这一条的末款管的是帮忙的人：保险事故的鉴定人、证明人、财产评估人。他们故意出具虚假的证明文件、给别人骗保创造条件的，按保险诈骗的共犯处理，和骗保的人一起定罪。保险法第二十七条：没出保险事故却谎称出了的，保险公司有权解除合同，并且不退保费。用伪造、变造的证明资料，或者编造虚假事故原因、夸大损失程度的，保险公司对多报的那部分不赔，已经赔出去的要退回来或者赔偿。案例：安徽宣城张某松案中，王某信等 8 人因保险诈骗罪被判处有期徒刑 4 年到 2 年不等，均并处罚金 1 万元。这案子牵出的一起虚假诉讼里，保险公司核定损失 2 万元，当事人靠伪造车辆转让协议取得起诉资格去打官司，法院判赔 7 万余元。这份已经生效的民事判决，于 2019 年 9 月 26 日经再审被撤销。《反保险欺诈工作办法》要求：卖保单和赔钱这两头（承保端和理赔端）都要核验风险信息。还要探索建立多险种的行业反欺诈信息平台、反欺诈情报中心。这些平台集中筛查欺诈可疑数据，线索交由行业协会、反欺诈组织和保险机构核查。涉嫌犯罪的及时向公安机关报案。金融监管总局和它的派出机构，要和公安机关、人民检察院、人民法院建立健全行政执法与刑事司法的衔接机制（全国，2024 年 7 月 31 日印发）', '下面几种自以为无害的做法都在这五项里。出了小事故找修理厂「多报一点」，把旧伤旧损算进这一次，和朋友对撞一下再报案，没出事却编一个出来。车险该怎么买，见第 5 节第 26 条（三者险买够）。给家人投保后故意造成他死亡的，法条明确要数罪并罚，见第 8 节第 38 条（给家人投保）。医保是另一套规则，空刷医保卡、拿医保个人账户套现按诈骗办，见第 5 节第 13 条的备注', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-22', 'concept_archive_s9-22', 'claim_archive_s9-22', 'action', 'life_archive', '不卖自己的器官，也别帮人找供体：肾到手 2 万多，同一枚转手卖 20 万，钱要被没收还要按交易额罚 10 到 20 倍', '9. 普通人容易踩的法律红线', '活体器官只能捐给配偶、直系血亲或者三代以内的旁系血亲，买卖都违法。北京一起案子里，卖肾的人只拿到 2 万多，同一枚肾卖给病人要 18 万到 22 万。卖得的钱会被没收，再按交易额罚 10 到 20 倍。摘肾后身体的代价见第 1 节第 35 条（剩下那个肾替两个干活）。', '受益人是你自己。这笔交易表面上是「一次性拿两万」，实际是拿一个器官换一台手机。少年卖肾案的鉴定结论是重伤、三级伤残，休息几个月好不了。那起案子里，检方认定 5 名被告人触犯刑法第二百三十四条第二款，以故意伤害罪起诉。理由之一是医务人员术前没有核实「供体」是不是未成年人，就切了右肾。今天再出同样的事，拉人头的按组织出卖人体器官罪办，摘取不满十八周岁的人的器官，仍然依第二百三十四条按故意伤害罪定罪处罚。黑中介的手术在出租屋或者借来的场地做，没有配型之外的评估，也没有术后随访，出了并发症找不到人认账。真想给亲人捐，走第十一条那条路：在有移植资质的医疗机构做，经伦理委员会审查，全程不收钱。身后的遗体器官捐献是无偿的，不在本条范围。摘掉一个肾之后身体要付什么代价，见第 1 节第 35 条（剩下那个肾替两个干活）。缺钱缺到考虑卖器官的时候，先看第 7 节的救助渠道（失业保险、临时救助、低保）。网贷和「包装材料」贷款的坑，见本节第 6 条。', NULL, NULL, NULL, '不花钱，也不费时间，不去做就行。', '《人体器官捐献和移植条例》第五条：「任何组织或者个人不得以任何形式买卖人体器官，不得从事与买卖人体器官有关的活动」。第十条：「任何组织或者个人不得获取未满 18 周岁公民的活体器官用于移植」。第十一条：「活体器官的接受人限于活体器官捐献人的配偶、直系血亲或者三代以内旁系血亲」。第三十七条规定了买卖人体器官怎么罚。买卖人体器官或者从事与买卖人体器官有关活动的，由县级以上地方人民政府卫生健康部门查处。先没收违法所得，把这笔交易得来的钱全部收走。再按交易额罚 10 倍以上 20 倍以下的钱。医务人员参与的，吊销执业证书并终身禁止从事医疗卫生服务。构成犯罪的，依法追究刑事责任（全国，2024 年 5 月 1 日起施行，原《人体器官移植条例》同时废止）。刑法第二百三十四条之一：「组织他人出卖人体器官的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产」。还有三种情形，依照刑法第二百三十四条、第二百三十二条定罪处罚。一是未经本人同意摘取他的器官。二是摘取不满十八周岁的人的器官。三是强迫或者欺骗他人捐献器官。这几种按故意伤害、故意杀人处理。案例一：北京市第一中级人民法院 2014 年 8 月 20 日终审的郑伟等 15 人案，涉及 51 枚肾脏，涉案金额 1034 万余元。卖肾的人（供体）「换来的仅仅是 2 万到 2.5 万元不等的报酬」。等肾的病人一方（受体方）出的价码，「以前是一个肾 18 万或 19 万，后来是 21 万或 22 万」。摘肾点是每月 7500 元租的四层小楼，团伙护士长供述该处「脏乱不堪，连抢救设备都没有」。组织者郑伟以组织出卖人体器官罪判处有期徒刑 12 年，其余 14 人判 3 年半至 9 年。案例二：最高人民检察院公布的「少年卖肾买苹果手机」案。17 岁的王某 2011 年 4 月 28 日晚在郴州被切除右肾。动手术的场地，是一家没有移植资质的医院里由人承包的科室提供的。5 月 2 日出院时他拿到 2.2 万元，受体方付给中介的是 15 万元人民币和 1 万美元，主犯获利 5.6 万余元。王某术后肾功能不全，「伤情构成重伤、三级伤残」', '受益人是你自己。这笔交易表面上是「一次性拿两万」，实际是拿一个器官换一台手机。少年卖肾案的鉴定结论是重伤、三级伤残，休息几个月好不了。那起案子里，检方认定 5 名被告人触犯刑法第二百三十四条第二款，以故意伤害罪起诉。理由之一是医务人员术前没有核实「供体」是不是未成年人，就切了右肾。今天再出同样的事，拉人头的按组织出卖人体器官罪办，摘取不满十八周岁的人的器官，仍然依第二百三十四条按故意伤害罪定罪处罚。黑中介的手术在出租屋或者借来的场地做，没有配型之外的评估，也没有术后随访，出了并发症找不到人认账。真想给亲人捐，走第十一条那条路：在有移植资质的医疗机构做，经伦理委员会审查，全程不收钱。身后的遗体器官捐献是无偿的，不在本条范围。摘掉一个肾之后身体要付什么代价，见第 1 节第 35 条（剩下那个肾替两个干活）。缺钱缺到考虑卖器官的时候，先看第 7 节的救助渠道（失业保险、临时救助、低保）。网贷和「包装材料」贷款的坑，见本节第 6 条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-23', 'concept_archive_s9-23', 'claim_archive_s9-23', 'action', 'life_archive', '别嫖娼：默认档是拘留 10 到 15 日，不是罚点钱了事', '9. 普通人容易踩的法律红线', '被抓到不是罚点钱了事。法条写的默认档是拘留 10 到 15 天，还可以再罚 5000 元以下。只有情节较轻的，才是 5 天以下拘留或者 1000 元以下罚款。另外，明知自己有梅毒、淋病还去嫖，是犯罪，判 5 年以下。', '这里的拘留是行政拘留，人要进拘留所，不是罚完就走。找人介绍、给人提供场地，罚得和自己嫖一样重，第七十九条那一档管的就是这个。在宾馆、KTV 上班的人替客人通风报信，同样按第八十七条拘留 10 到 15 日。刑法第三百六十条原来还有第二款「嫖宿幼女罪」，2015 年刑法修正案（九）把它删了，现在这种事直接按强奸罪从重处罚，见本节第 18 条（对方不满 14 岁就不能发生关系）。「上门保健」「按摩推拿」这类招牌不改变性质，按实际发生的事认定。染上性病和艾滋病的风险，见第 1 节第 30 条（性行为全程用安全套）和第 13 节第 38 条（72 小时内去拿阻断药）。娱乐场所本身要注意的见第 22 节。', NULL, NULL, NULL, '不花钱，也不费时间，不去做就行。', '《治安管理处罚法》第七十八条：卖淫、嫖娼的，处十日以上十五日以下拘留，可以并处五千元以下罚款。情节较轻的，处五日以下拘留或者一千元以下罚款。在公共场所拉客招嫖的，处五日以下拘留或者一千元以下罚款。第七十九条：引诱、容留、介绍他人卖淫的，处十日以上十五日以下拘留，可以并处五千元以下罚款。情节较轻的，处五日以下拘留或者一千元以上二千元以下罚款。第八十七条：旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处卖淫、嫖娼活动时为违法犯罪行为人通风报信的，或者以其他方式为上述活动提供条件的，处十日以上十五日以下拘留。《刑法》第三百六十条是传播性病罪：明知自己患有梅毒、淋病等严重性病卖淫、嫖娼的，处五年以下有期徒刑、拘役或者管制，并处罚金（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', '这里的拘留是行政拘留，人要进拘留所，不是罚完就走。找人介绍、给人提供场地，罚得和自己嫖一样重，第七十九条那一档管的就是这个。在宾馆、KTV 上班的人替客人通风报信，同样按第八十七条拘留 10 到 15 日。刑法第三百六十条原来还有第二款「嫖宿幼女罪」，2015 年刑法修正案（九）把它删了，现在这种事直接按强奸罪从重处罚，见本节第 18 条（对方不满 14 岁就不能发生关系）。「上门保健」「按摩推拿」这类招牌不改变性质，按实际发生的事认定。染上性病和艾滋病的风险，见第 1 节第 30 条（性行为全程用安全套）和第 13 节第 38 条（72 小时内去拿阻断药）。娱乐场所本身要注意的见第 22 节。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-24', 'concept_archive_s9-24', 'claim_archive_s9-24', 'action', 'life_archive', '汉化漫画、搬运影视剧、分享网盘资源和盗版电子书，不收钱也是侵权；挂广告、收会员费就可能判刑', '9. 普通人容易踩的法律红线', '别人的作品没经许可翻译了贴出来，或者传到网上，不收钱也是侵权，要删、要赔钱。一挂广告、收会员费，就算为了挣钱。挣到 3 万元、传到 500 部或者会员到 1000 人，就够判刑，最重判 10 年。人人影视字幕组的老板判了 3 年 6 个月。', '受益人是你自己。自己买来看、自己翻着看，在法条允许的范围里。界线在「放到网上让大家看」。字幕组、汉化组不收钱，够不上侵犯著作权罪，因为这个罪要求为了挣钱。但民事侵权照样成立，权利人可以要求删掉、赔钱。在日本不收钱也可能犯法。2018 年 2 月，几名在日中国公民涉嫌违反日本著作权法被捕，中国驻长崎总领事馆随后提醒：没经授权翻译、发布、传播作品，即使不为盈利，也可能违法。一挂广告、开会员、拿「捐赠」换会员权益，就落进为了挣钱那一档。人人影视案里，只做翻译、校对的人参与程度低，警方是按证人取证的。最高检在这个案例里写明，起头、分钱、管平台的人要从严追究。受雇干活的从犯可以从宽，临时招来、情节轻微的可以不追究刑事责任。旧的 2004、2007、2020 年三部知识产权刑事司法解释，2025 年 4 月 26 日起废止。2011 年三部门意见没有被点名废止，和新解释不一致的地方以新解释为准。比如点击量门槛，就从 5 万次改成了 10 万次。写同人、做二创拿去出版的另一种风险，见本节第 25 条（写同人）。把别人的图印在商品上卖，见第 12 节第 21 条（图案要买授权）。自己做平台、收到权利人的侵权通知怎么办，见第 26 节第 9 条（接到侵权通知）。', NULL, NULL, NULL, '不花钱。买来的、下载的，自己看、自己翻着玩都行，只是别传到网上给大家看。不做挂广告、收会员费的资源站和资源群，也不卖网盘链接。难在「大家都在传」的时候，忍住不跟着当搬运工。', '先说民事。著作权法给作者的权利里有翻译权，就是把作品从一种文字转成另一种文字的权利。还有信息网络传播权，就是把作品放到网上、让公众随时随地能看到的权利。没经许可翻译别人的作品，是侵权。没经许可把作品传到网上，也是侵权。侵权的要停止侵害、赔偿损失。只有为个人学习、研究或者欣赏，用别人已经发表的作品，才不用许可、不用付钱。赔多少，先按权利人的实际损失或者你挣到的钱算。都算不清的，由法院在 500 元到 500 万元之间定。故意侵权、情节严重的，可以判 1 到 5 倍。权利人为制止侵权花的合理开支，也要你一起赔。再说刑事。刑法第二百一十七条的前提是「以营利为目的」。为了挣钱，没经许可把别人的作品放到网上给公众看，够了门槛就是侵犯著作权罪。判 3 年以下，同时罚钱，或者只罚钱。数额巨大或者情节特别严重的，判 3 到 10 年并罚钱。什么算为了挣钱：除了卖，在网页上挂收费广告的算，用会员制收注册费或者其他费用的也算。收来的服务费、会员费、广告费，都算违法所得。够罪的门槛，下面到一条就够。违法所得 3 万元以上。非法经营数额 5 万元以上，人人影视案里算的是会员费、广告费和卖硬盘的总收入。在网上传播别人的作品合计 500 件（部）以上。被下载 1 万次以上，或者被点击 10 万次以上。用会员制传播，注册会员 1000 人以上。几项都没到，但有两项各到了一半以上，也算。到这些数的 10 倍，就进 3 到 10 年那一档。罚金一般是违法所得的 1 到 10 倍。官方案例一：梁永平等人从境外网站下载没授权的影视剧，组织人翻译、做字幕后上传。这些片子放在「人人影视字幕组」网站和客户端上，供人在线看和下载。网站里没授权的影视作品有 32824 部，会员 683 万余个。2018 年 1 月到 2021 年 1 月，收会员费 270 余万元，广告费 880 余万元。卖拷了影视剧的移动硬盘，又挣了 100 余万元。网站挂着「捐赠」二维码，捐了就能得到会员权益。检察机关认定，这就是换了个名目收会员费。2021 年 11 月 22 日，梁永平被判 3 年 6 个月，罚金 150 万元。另外 14 人判 1 年 6 个月到 3 年，都是缓刑，罚 4 万到 35 万元。官方案例二：柯某某用爬虫软件抓了 5 万余部影视剧的播放地址，放到自己的网站和 App 上让人免费看。他在开屏位置投广告，按展现量收钱，挣了 35 万余元。2023 年他被判 3 年、缓刑 4 年，罚金 40 万元。官方案例三：黄某在自己家里租服务器，搭了一个音乐下载论坛。他把 10 万余首歌传进 18 个网盘，在论坛发链接。会员要充值换论坛币，才能拿到链接和提取码。会员充值共 50 余万元。2023 年他被判 3 年、缓刑 4 年，罚金 55 万元（全国，司法解释 2025 年 4 月 26 日起施行）', '受益人是你自己。自己买来看、自己翻着看，在法条允许的范围里。界线在「放到网上让大家看」。字幕组、汉化组不收钱，够不上侵犯著作权罪，因为这个罪要求为了挣钱。但民事侵权照样成立，权利人可以要求删掉、赔钱。在日本不收钱也可能犯法。2018 年 2 月，几名在日中国公民涉嫌违反日本著作权法被捕，中国驻长崎总领事馆随后提醒：没经授权翻译、发布、传播作品，即使不为盈利，也可能违法。一挂广告、开会员、拿「捐赠」换会员权益，就落进为了挣钱那一档。人人影视案里，只做翻译、校对的人参与程度低，警方是按证人取证的。最高检在这个案例里写明，起头、分钱、管平台的人要从严追究。受雇干活的从犯可以从宽，临时招来、情节轻微的可以不追究刑事责任。旧的 2004、2007、2020 年三部知识产权刑事司法解释，2025 年 4 月 26 日起废止。2011 年三部门意见没有被点名废止，和新解释不一致的地方以新解释为准。比如点击量门槛，就从 5 万次改成了 10 万次。写同人、做二创拿去出版的另一种风险，见本节第 25 条（写同人）。把别人的图印在商品上卖，见第 12 节第 21 条（图案要买授权）。自己做平台、收到权利人的侵权通知怎么办，见第 26 节第 9 条（接到侵权通知）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-25', 'concept_archive_s9-25', 'claim_archive_s9-25', 'action', 'life_archive', '写同人、做二创拿去出版或卖钱，先取得原作许可，或者把借来的人物名字和关系换成自己的', '9. 普通人容易踩的法律红线', '同人哪怕只借了人物名字、性格和关系，拿去出版也可能被判侵权。江南的《此间的少年》借了金庸 60 多个人物，二审判他赔 168 万元，外加 20 万元开支。官司打了 9 年，最后调解，他答应不再原样再版。免费写着玩的同人怎么算，法院说要具体分析。', '受益人是你自己。定 B 级，是因为同人的法律边界还没有定论。这个案子两审结论不一样，最后以调解结案，两份判决都不再生效。广东高院的承办法官答问时说，和解协议只约束这个案子的当事人。同人是否侵权，「要具体情况具体分析，不能一概而论」。法官给的判断顺序是三步。先看两部作品相同的是抽象的想法，还是具体的表达。再看这些表达是不是原作者独创的。最后看是不是属于合理使用这类不侵权的情形。所以只借一个题材、一种设定，和成套借走人物名字、性格和关系，风险不一样。免费贴在网上的同人，本书没有找到法院下判的官方案例。著作权法里也没有「不收钱就不算侵权」的例外。过程成本要算进去：这个案子从 2016 年 7 月起诉，到 2025 年 9 月和解，前后 9 年。中间经过一审、二审和再审审查，金庸本人在二审期间去世。原作者把版权卖掉以后，自己写续作照样可能被买家告，天下霸唱那次就是。著作权官司里，赢的一方为制止侵权花的合理开支可以算进赔偿，这个案子一审判的 20 万元就是律师费。汉化、搬运、分享别人作品的风险，见本节第 24 条（汉化漫画、搬运影视剧）。', NULL, NULL, NULL, '不花钱。拿去出版、卖钱之前，先找原作的权利人谈授权。谈不下来，就把借来的人物名字、性格和人物关系换成自己的。书名、副标题和宣传语里，也别蹭原作的名头。', '江南的小说《此间的少年》，用了郭靖、黄蓉、乔峰、令狐冲等金庸小说里的人物名字。书里讲的是这些人在大学校园里的故事。2002 年出版时，副标题是「射雕英雄的大学生涯」。到起诉时，这本书出了多个版本，发行上百万册。金庸 2016 年起诉江南和出版方，索赔 500 万元。一审认为不构成著作权侵权。理由是：离开了具体情节，光是人物名字、关系和性格，很难算受保护的具体表达。但一审认定，江南借原作名气吸引读者，构成不正当竞争。按历年版税 560 万元的 30%，判赔 168 万元，外加律师费 20 万元。二审由广州知识产权法院审理，改判构成著作权侵权。二审认为，两本书的故事情节不算实质性相似，也就是情节没有抄。但 60 多个人物合起来的「人物群像」，名字、性格、关系和背景都是金庸的选择和安排。这属于著作权法保护的表达，江南侵害了金庸四部小说的著作权。副标题故意和《射雕英雄传》挂钩，另外构成不正当竞争。二审判江南停止不正当竞争、登报消除影响，赔 168 万元和合理开支 20 万元。两家出版发行公司对其中 33 万元承担连带责任，也就是这部分要一起赔。二审没有判停止侵权，但要求以后再版，按再版版税收入的 30% 付给原作权利人。二审之后，双方都向广东省高级人民法院申请再审。2025 年 9 月 19 日，各方在广东高院主持下达成和解。和解里，各方同意不把这件事定性为「剽窃」。江南承认，他创作时缺乏著作权法律知识，没有事先取得金庸的改编许可，给金庸造成了损害。江南同意不再原样再版这本书。以后再版，不再用金庸作品里的独创人物名字和相关内容。各方确认，那个副标题构成不正当竞争。二审判的赔偿，江南已经付了。调解书签收后，原来的一审、二审判决都不再有法律效力。另一个案子的被告是《鬼吹灯》作者张牧野，笔名天下霸唱。2006 年，他把这套小说著作权里的财产权全部转让给了上海玄霆娱乐信息科技有限公司。后来他授权出版新书《摸金校尉》，书里用了《鬼吹灯》的人物名字、人物关系和盗墓规矩。新书封面用了《寻龙诀》的电影海报，这部电影是从《鬼吹灯》改编的。玄霆公司起诉，索赔 2000 万元。上海浦东法院认为，新书有自己独立的情节，不算侵犯著作权。但封面让读者误以为这本书和《寻龙诀》原著有关，构成虚假宣传。法院判两家出版发行公司赔 90 万元，出版社对其中 60 万元承担连带责任，二审维持。法条上，改编权是改变作品、创作出有独创性的新作品的权利。没经著作权人许可，用改编、翻译、注释等方式使用作品，要承担停止侵害、赔偿损失等民事责任（全国）', '受益人是你自己。定 B 级，是因为同人的法律边界还没有定论。这个案子两审结论不一样，最后以调解结案，两份判决都不再生效。广东高院的承办法官答问时说，和解协议只约束这个案子的当事人。同人是否侵权，「要具体情况具体分析，不能一概而论」。法官给的判断顺序是三步。先看两部作品相同的是抽象的想法，还是具体的表达。再看这些表达是不是原作者独创的。最后看是不是属于合理使用这类不侵权的情形。所以只借一个题材、一种设定，和成套借走人物名字、性格和关系，风险不一样。免费贴在网上的同人，本书没有找到法院下判的官方案例。著作权法里也没有「不收钱就不算侵权」的例外。过程成本要算进去：这个案子从 2016 年 7 月起诉，到 2025 年 9 月和解，前后 9 年。中间经过一审、二审和再审审查，金庸本人在二审期间去世。原作者把版权卖掉以后，自己写续作照样可能被买家告，天下霸唱那次就是。著作权官司里，赢的一方为制止侵权花的合理开支可以算进赔偿，这个案子一审判的 20 万元就是律师费。汉化、搬运、分享别人作品的风险，见本节第 24 条（汉化漫画、搬运影视剧）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s9-26', 'concept_archive_s9-26', 'claim_archive_s9-26', 'action', 'life_archive', '别为了防身买甩棍、电击器、匕首、辣椒水带在身上，放在车里也算携带', '9. 普通人容易踩的法律红线', '匕首、弹簧刀、警棍、电击器这类东西，带出门被查到，可以拘留 5 日以下。带进车站、商场、公交车，拘留 5 到 10 日。真拿出来用也容易吃亏：有人被空手打了一拳，就拿事先藏好的刀捅人，按防卫过当判了 4 年。', '受益人是你自己。带了刀，正当防卫并不会自动不成立。检例第 45 号里，学生陈某被 9 人围殴，掏出随身的水果刀反击，仍被认定为正当防卫。检察院写明，影响认定的不是带没带工具，而是有没有互殴的故意。吃亏落在两处。一是东西本身违法，平时被查到就罚，和用没用无关。二是刀在手边，面对一拳一推也容易捅出去，伤到重伤以上就可能变成防卫过当。辣椒水喷雾，本书没查到全国层面禁止个人持有的原文，只知道坐火车不能带。网上卖的甩棍算不算警棍，本书也没查到全国统一的认定原文。真遇到事，先看第 8 节第 10 条（起了冲突先报警不动手）。退无可退时，看第 8 节第 11 条（躲不掉的侵害可以还手）。野外被人堵住要钱，见第 13 节第 36 条（荒郊野外被陌生人索财）。', NULL, NULL, NULL, '不花钱。已经买了的留在家里，不带出门，也不放进车里。真遇到事，先退开报警，躲不掉再还手。', '先看治安管理处罚法第三十八条。非法携带弩、匕首等国家规定的管制器具的，拘留 5 日以下，可以再罚 1000 元以下。情节较轻的，警告或者罚 500 元以下。带进公共场所或者公共交通工具的，拘留 5 到 10 日，可以再罚 1000 元以下。刑法第一百三十条更重。非法携带管制刀具进入公共场所或者公共交通工具，危及公共安全、情节严重的，判 3 年以下。哪些刀算管制刀具，公安部 2007 年的认定标准列了五类。第一类是匕首：有刀柄、刀格和血槽，刀尖角度小于 60 度。第二类是三棱刮刀。第三类是带自锁装置的弹簧刀，俗称跳刀。第四类是刀尖角度小于 60 度、刀身超过 150 毫米的刀。第五类是刀尖角度大于 60 度、刀身超过 220 毫米的刀。没开刃、刀尖磨圆的武术和工艺礼品刀不算。警棍是警察的警械。人民警察法规定，警械只许警察持有和使用。别人持有的，没收，拘留 15 日以下或者警告，可以再按违法所得罚 5 倍以下。铁路的禁带目录把警棍、催泪器、电击器、防卫器都列为管制器具。坐火车时这些东西不许随身带，也不许托运。车里放着一样会被查：有人开车带着管制刀具过检查站，被民警查获，行政拘留。真用了的账，看正当防卫指导意见。它把「是否使用或者准备使用凶器」列为区分防卫和互殴的情节之一。官方案例：杨某和人吵架，对方扬言找人报复，他回家把两把刀藏在身上。对方回来空手打了他脸一拳，他拿刀捅对方胸腹，对方死亡。法院认定他有防卫性质，但对方只是空手打，他捅的是要害，属于防卫过当。他以故意伤害罪被判 4 年（全国，治安管理处罚法 2026 年 1 月 1 日起施行）', '受益人是你自己。带了刀，正当防卫并不会自动不成立。检例第 45 号里，学生陈某被 9 人围殴，掏出随身的水果刀反击，仍被认定为正当防卫。检察院写明，影响认定的不是带没带工具，而是有没有互殴的故意。吃亏落在两处。一是东西本身违法，平时被查到就罚，和用没用无关。二是刀在手边，面对一拳一推也容易捅出去，伤到重伤以上就可能变成防卫过当。辣椒水喷雾，本书没查到全国层面禁止个人持有的原文，只知道坐火车不能带。网上卖的甩棍算不算警棍，本书也没查到全国统一的认定原文。真遇到事，先看第 8 节第 10 条（起了冲突先报警不动手）。退无可退时，看第 8 节第 11 条（躲不掉的侵害可以还手）。野外被人堵住要钱，见第 13 节第 36 条（荒郊野外被陌生人索财）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"9. 普通人容易踩的法律红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-1', 'concept_archive_s10-1', 'claim_archive_s10-1', 'action', 'life_archive', '认识更多人，而不是死磕一个：两个人合不合得来，见面之前预测不出来', '10. 恋爱和结婚划不划算', '两场闪电约会研究让人在见面前填了 100 多项择偶问卷。问卷只能算出谁普遍容易喜欢别人、谁普遍受欢迎，算不出这两个人之间来不来电。合不合得来只有见了面才知道。所以多认识几个人，比押在一个人身上划算。', '两项研究只说明「见面之前算不出来」，没说「怎么努力都没用」。合不合得来只能见了面才知道，所以把时间花在多认识几个人上，每个都真正见一面，比全押在一个人身上划算。研究对象都是欧美大学生。中国的婚恋环境不一样，套到自己身上要打折', NULL, NULL, NULL, '不花钱。时间花在多认识几个人上，别反复琢磨同一个人。难在忍住不死磕。', '两场闪电约会研究里，参与者见面前先填了 100 多项与择偶有关的自陈量表（自己给自己打分的问卷）。研究者用随机森林模型（一种找规律的算法）来算。能算出「一个人整体上有多容易喜欢别人」，这些问卷能说明其中 4%–18% 的方差，方差就是人与人之间的差别，问卷只能说明其中一小部分。也能算出「一个人整体上有多受欢迎」，能说明 7%–27%。但「这两个具体的人之间来不来电」算不出来，会前的特质和偏好怎么组合都算不出来。同一批研究者更早还做过一项闪电约会实验。参与者会前自己报了理想型偏好，比如看重外貌还是看重经济前景。这个偏好预测不了他们在现场对具体某个人的兴趣', '两项研究只说明「见面之前算不出来」，没说「怎么努力都没用」。合不合得来只能见了面才知道，所以把时间花在多认识几个人上，每个都真正见一面，比全押在一个人身上划算。研究对象都是欧美大学生。中国的婚恋环境不一样，套到自己身上要打折', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-2', 'concept_archive_s10-2', 'claim_archive_s10-2', 'action', 'life_archive', '对方明确拒绝之后就停下，继续纠缠是治安违法，不是「诚意」', '10. 恋爱和结婚划不划算', '对方明确说了拒绝，你还发消息、还去等人，2026 年 1 月起就是治安违法。可以拘留 5 日以下，或者罚 1000 元以下。情节较重的拘留 5 到 10 日。公安还可以下令禁止你接触对方，违反了再拘留 5 到 10 日。', '「死追到底会感动对方」没有任何研究支持，但拘留和禁止接触令是白纸黑字的。留下的记录还会影响考公、考编、政审，还有一部分职业的从业资格。追一个人和骚扰一个人的界线，不看你怎么想，看对方有没有明确说过拒绝', NULL, NULL, NULL, '不花钱，也不花时间。难在忍住：不再发消息，不再去等人。', '2026 年 1 月 1 日起施行的治安管理处罚法，把纠缠、跟踪单列成一项。条文写的是「多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的」。这种行为处五日以下拘留，或者一千元以下罚款。情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款。这一项还多一层：经公安机关负责人批准，可以责令行为人在一定期限内禁止接触被侵害人。违反禁止接触规定的，再处五日以上十日以下拘留', '「死追到底会感动对方」没有任何研究支持，但拘留和禁止接触令是白纸黑字的。留下的记录还会影响考公、考编、政审，还有一部分职业的从业资格。追一个人和骚扰一个人的界线，不看你怎么想，看对方有没有明确说过拒绝', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-3', 'concept_archive_s10-3', 'claim_archive_s10-3', 'action', 'life_archive', '判断对方有没有兴趣，看行为不看「信号」：谁主动、谁安排、谁跟进', '10. 恋爱和结婚划不划算', '让 52 对陌生男女聊十来分钟，再互相判断对方有没有在调情。结果是「对方没在调情」判得比较准，「对方在调情」反而看不出来。换成 261 个人看视频判断，结论一样。所以别猜表情和语气，看行为：谁主动发起，谁安排下一次，你不推进时对方跟不跟进。', '争议。另有研究认为，不是男性高估了女性的性意图，而是女性填问卷时把自己的意图报低了。到底谁判断得更准，仍无定论。但两派都同意一件事：从表情、语气这类细微线索反推对方心思，准确率很低。看得见的行为要可靠得多：对方是否主动发起，是否安排下一次，是否在你不推进时也跟进', NULL, NULL, NULL, '不花钱，也不花多少时间。难在改习惯：别再琢磨对方的表情和语气，改成记录事实。', '两项研究测了人识别调情的准确率。第一项让 52 对互不相识的异性两两交谈 10 到 12 分钟。谈完各自报告自己有没有在调情，也报告觉得对方有没有在调情。结果是「没有发生调情的互动被判断得更准，发生了调情的互动反而判断得更差」。第二项用 26 段一分钟的视频，给 261 名旁观者判断，结论一致。人能比较可靠地看出「对方没在调情」，却很难看出「对方在调情」', '争议。另有研究认为，不是男性高估了女性的性意图，而是女性填问卷时把自己的意图报低了。到底谁判断得更准，仍无定论。但两派都同意一件事：从表情、语气这类细微线索反推对方心思，准确率很低。看得见的行为要可靠得多：对方是否主动发起，是否安排下一次，是否在你不推进时也跟进', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-4', 'concept_archive_s10-4', 'claim_archive_s10-4', 'action', 'life_archive', '关系好不好，主要看你自己在这段关系里的感受，不是看对方条件', '10. 恋爱和结婚划不划算', '最能说明关系好不好的，是你自己的感受，不是对方的条件。比如你觉得对方认不认真、欣不欣赏你，你们吵得多不多。你自己的感受比伴侣的说法管用二到四倍。但这段关系往后变好还是变坏，任何问卷都基本算不出来。', '同一项研究还发现，这段关系在研究期间是变好还是变坏，用问卷里任何一组自评指标都基本算不出来。所以判断眼下这段关系好不好，问自己的感受比核对对方的条件清单准，但别指望能预测它以后会怎样。关系好坏和身体好坏连在一起的那笔账，见本节第 17 条（把关系好坏当成一笔健康账）。', NULL, NULL, NULL, '不花钱，也不花多少时间。难在改视角：把择偶清单收起来，改成看相处过程。', '29 个实验室、43 份纵向配对数据的机器学习分析，纵向就是跟着同一批伴侣一路记录。最能预测关系质量的几项，全部来自当事人对这段关系的感受：感觉到对方的承诺、欣赏、性满意度、感觉到对方满意、冲突。跟个人有关的几项里最强的是生活满意度、负面情绪、抑郁、回避型依恋、焦虑型依恋。关于关系的这些项，在刚开始调查时最多能解释 45% 的方差。方差指伴侣与伴侣之间关系质量的差别，45% 是其中能用这些项说清的部分。到研究结束时最多解释 18%。而且「自己报告的那些项」的预测力，是「伴侣报告的那些项」的二到四倍。在自己报告的关系感受之外，再把个体差异和伴侣的报告加进来，没有多出任何预测力', '同一项研究还发现，这段关系在研究期间是变好还是变坏，用问卷里任何一组自评指标都基本算不出来。所以判断眼下这段关系好不好，问自己的感受比核对对方的条件清单准，但别指望能预测它以后会怎样。关系好坏和身体好坏连在一起的那笔账，见本节第 17 条（把关系好坏当成一笔健康账）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-5', 'concept_archive_s10-5', 'claim_archive_s10-5', 'action', 'life_archive', '想拉近距离就轮流回答一组由浅入深的问题，别学话术', '10. 恋爱和结婚划不划算', '两个陌生人轮流回答 36 道由浅入深的问题，45 分钟后，比光闲聊同样久的人亲近得多。起作用的是轮流说真话、一层层往深里说，不靠话术。这只说明当时更亲近，不代表能发展成长期关系。', '只做过一次实验，对象是大学生，只测了短时间内的亲近感，没测能不能发展成长期关系。实验里的亲近感来自两个人轮流、一层层往深里说自己的真实情况，靠的不是话术、套路或单方面表现。所以聊天时可以「我说一点真实的，也问一句一样深的」，两边轮流', NULL, NULL, NULL, '不花钱。要花 45 分钟。', '把互不相识的两人配对，让他们轮流回答三组逐步深入的问题，一共 36 题。问题从「你最想请谁吃饭」一直到「上一次当着别人的面哭是什么时候」。45 分钟后的亲近感，显著高于做同样时长闲聊的对照组。也高于该研究中大学生对自己现实中最亲密关系的平均评分', '只做过一次实验，对象是大学生，只测了短时间内的亲近感，没测能不能发展成长期关系。实验里的亲近感来自两个人轮流、一层层往深里说自己的真实情况，靠的不是话术、套路或单方面表现。所以聊天时可以「我说一点真实的，也问一句一样深的」，两边轮流', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-6', 'concept_archive_s10-6', 'claim_archive_s10-6', 'action', 'life_archive', '异地不比同城差，真正的坎是搬到一起之后的头三个月', '10. 恋爱和结婚划不划算', '异地在分开期间反而更稳，因为见得少，容易把对方想得比实际好。真正的坎在搬到一起之后。追踪数据里约一半异地伴侣走到了同城这一步，另一半在分开期间就结束了。重聚的这一半里，三分之一在 3 个月内分手。', '对象是美国大学生的恋爱关系，不含婚姻，年代也较早，绝对比例别直接套。另一项研究调查了 717 人异地、425 人同城。两类关系的质量差别很小，关系好不好主要看两个人各自的情况和这段关系本身。所以决定要不要异地时，别拿「异地一定散」当理由。要提前准备的是重聚后那几个月，那时自主空间变少，彼此了解变多，冲突和吃醋也变多', NULL, NULL, NULL, '要花路费，还要花来回路上的时间。见面次数比同城少。难在长期扛住见不着面。', '两项研究的结论一致。异地恋在分开期间反而比同城恋更稳定。原因是异地关系里把对方想得比实际更好的程度明显更高，研究测的是理想化失真、浪漫爱、关系回忆、感知到的一致这几项。而且见面越少，想得越美。但这种稳定只在双方仍然分开时成立，一旦变成同城，异地伴侣更容易分手。追踪异地转同城的那项研究给出的比例是：约一半异地伴侣走到了搬到一起这一步，另一半在分开期间就结束了。在重聚的这一半里，三分之一在重聚后 3 个月内分手。分开期间见面间隔越长、理想化越强，重聚后越不稳', '对象是美国大学生的恋爱关系，不含婚姻，年代也较早，绝对比例别直接套。另一项研究调查了 717 人异地、425 人同城。两类关系的质量差别很小，关系好不好主要看两个人各自的情况和这段关系本身。所以决定要不要异地时，别拿「异地一定散」当理由。要提前准备的是重聚后那几个月，那时自主空间变少，彼此了解变多，冲突和吃醋也变多', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 时间","钱 多","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-7', 'concept_archive_s10-7', 'claim_archive_s10-7', 'action', 'life_archive', '先看登记数据再听长辈：结婚率、离婚率各是什么口径', '10. 恋爱和结婚划不划算', '2024 年全国结婚登记 610.6 万对，比上一年少了两成，离婚 351.3 万对。网上说离婚率过半，是拿这两个数一除，约 57.5%。可离婚的和结婚的不是同一批人，不能读成一半婚姻会离。公报里的结婚率 4.3‰、离婚率 2.5‰，是除以全国人口算的。', '网上常见的「离婚率 50% 以上」，是拿当年离婚的对数除以当年结婚的对数，351.3 / 610.6 ≈ 57.5%。这叫「离结比」。相除的两个数不是同一批人，公报里也没有这个指标，所以不能读成「一半婚姻会离」。要算「一段婚姻最后离掉的概率」，得盯住同一批结婚的人一路统计下去，这种官方数据本节没找到', NULL, NULL, NULL, '不花钱。读一遍民政部年度公报里的婚姻登记那一段，几分钟。', '2024 年全国依法办理结婚登记 610.6 万对，比上年下降 20.5%，结婚率 4.3‰。同年依法办理离婚手续 351.3 万对，其中民政部门登记离婚 262.2 万对，法院判决和调解离婚 89.1 万对，离婚率 2.5‰。公报注明，结（离）婚率 = 当年结（离）婚对数 / 当年平均总人口数 × 1000‰。这是「粗率」，分母是全体人口，不是已婚人口', '网上常见的「离婚率 50% 以上」，是拿当年离婚的对数除以当年结婚的对数，351.3 / 610.6 ≈ 57.5%。这叫「离结比」。相除的两个数不是同一批人，公报里也没有这个指标，所以不能读成「一半婚姻会离」。要算「一段婚姻最后离掉的概率」，得盯住同一批结婚的人一路统计下去，这种官方数据本节没找到', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-8', 'concept_archive_s10-8', 'claim_archive_s10-8', 'action', 'life_archive', '把健康收益算进去，但按观察性数据打折', '10. 恋爱和结婚划不划算', '已婚的人同期死亡的概率比非婚的人低约 12%，从未结过婚的人比已婚的人高约 24%。但这只是两件事同时出现，不是结婚起的作用。本来健康、收入高、社交多的人，既更容易结婚，也更容易活得久。这些数字基本来自欧美，对国内只能当量级参考。', '争议在于结婚的人本来就是被挑过的：健康、收入高、社交多的人，既更容易结婚，也更容易活得久。三项荟萃用的都是现成人群的观察数据，只是跟踪记录，没有分组对照。作者自己也写了有发表偏倚或方法局限。Roelfs 还发现研究做得越严谨，算出的差距越小。这些数字以欧美人群为主，对国内只能当量级参考', NULL, NULL, NULL, '不花钱，也不花时间。只要记住一点：这些数字说的是已婚的人里死亡率更低，是两件事同时出现，不是结婚让你活得久。', '一项针对老年人的荟萃分析，把多项研究汇总重算，共 53 组比较、25 万余人。已婚相对非婚的全因死亡 RR 0.88，95% CI 0.85–0.91（RR 是风险比，CI 是可信范围），同期死亡的概率低约 12%。同一项里丧偶 1.11、离异或分居 1.16、未婚 1.11，分别高约 11%、16%、11%。男女无差异。最保守的估计是 RR 0.94，只低约 6%。另一项荟萃分析比的是未婚（从未结婚）相对已婚，用了 95 篇文献、5 亿余人。结果 HR 1.24（1.19–1.30），同期死亡的概率高约 24%。而且年纪越大，差距越小。还有一项按性别拆的荟萃分析，21 项研究、789 万余人：不论男女，非婚都与总死亡、癌症死亡、心血管死亡同时出现。男性这边的心血管死亡和总死亡差距更大。未婚男性相对未婚女性，卒中死亡多 31%，全因死亡多 9%', '争议在于结婚的人本来就是被挑过的：健康、收入高、社交多的人，既更容易结婚，也更容易活得久。三项荟萃用的都是现成人群的观察数据，只是跟踪记录，没有分组对照。作者自己也写了有发表偏倚或方法局限。Roelfs 还发现研究做得越严谨，算出的差距越小。这些数字以欧美人群为主，对国内只能当量级参考', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-9', 'concept_archive_s10-9', 'claim_archive_s10-9', 'action', 'life_archive', '时间账按「无酬劳动」算，谈清分工再领证', '10. 恋爱和结婚划不划算', '全国时间利用调查里，家务和陪伴照料家人这类没报酬的活，男性每天平均 1 小时 52 分，女性 3 小时 29 分。调查没按结没结婚分组，所以「结了婚家务会多多少」没有官方数字，这个性别差距只能当上限参考。分工可以在领证前谈成另一个样子。', '两次调查都只按性别、城乡、年龄分组，没有按结没结婚分组。所以「结婚后家务会多多少」没有官方数字，只能用性别差距做上限参考。数字是全国平均，你们两个人的分工完全可以谈成另一个样子', NULL, NULL, NULL, '不花钱。婚前花一两个小时，把家务、照料老小、谁的工作让步这些没报酬的活谈成明确分工，之后按分工执行。难在把话摊开谈，别拖着不说。', '2024 年全国时间利用调查。无酬劳动就是家务、陪伴照料家人这些没有报酬的活。当天做了这类活的人，每日平均花 2 小时 45 分，其中男性 1 小时 52 分、女性 3 小时 29 分。一天里做过这类活的人占多大比例，男性是 67.5%、女性是 83.9%。居民家务劳动每日平均 1 小时 17 分，只算做了的人是 1 小时 59 分，比 2018 年少 28 分。陪伴照料家人每日平均 30 分，只算做了的人是 1 小时 46 分。2018 年的数字是：家务劳动男性 45 分、女性 2 小时 6 分，陪伴照料孩子男性 17 分、女性 53 分', '两次调查都只按性别、城乡、年龄分组，没有按结没结婚分组。所以「结婚后家务会多多少」没有官方数字，只能用性别差距做上限参考。数字是全国平均，你们两个人的分工完全可以谈成另一个样子', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 时间","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-10', 'concept_archive_s10-10', 'claim_archive_s10-10', 'action', 'life_archive', '钱账先看法律默认规则，再决定要不要书面约定', '10. 恋爱和结婚划不划算', '不签书面约定的话，法律默认婚后挣的工资奖金、经营和投资收益、继承或受赠的财产都归两人共有。婚前财产、遗嘱或赠与合同写明只给一方的，才是个人的。两个人可以书面约定各归各，签了就有约束力。因带孩子、照料老人多付出的一方，离婚时可以要求补偿。', '彩礼、婚礼、婚房没有官方统计，本条不写数字。第一千零八十八条那笔补偿给多少，先由两人自己谈，谈不成由法院定，没有固定公式。书面财产约定对两边都管用：收入高的一方用得上，家务照料这类没报酬的活干得多的一方也用得上', NULL, NULL, NULL, '不花钱。读一遍民法典婚姻家庭编里讲财产的那几条。有需要就两个人签一份书面财产约定，法律只要求写成书面的，不必去公证。难在把钱的事提前说开。', '不另作约定时的默认规则是：婚后所得的工资奖金劳务报酬、生产经营投资收益、知识产权收益、继承或受赠财产，归夫妻共同所有（第一千零六十二条）。婚前财产、人身损害赔偿、遗嘱或赠与合同明确只归一方的财产、一方专用生活用品，是个人财产（第一千零六十三条）。双方可以书面约定婚前和婚后财产归各自所有、共同所有，或者部分各自所有部分共同所有，这个约定对双方有法律约束力（第一千零六十五条）。因抚育子女、照料老人、协助另一方工作而负担较多义务的一方，离婚时有权请求补偿（第一千零八十八条）', '彩礼、婚礼、婚房没有官方统计，本条不写数字。第一千零八十八条那笔补偿给多少，先由两人自己谈，谈不成由法院定，没有固定公式。书面财产约定对两边都管用：收入高的一方用得上，家务照料这类没报酬的活干得多的一方也用得上', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-11', 'concept_archive_s10-11', 'claim_archive_s10-11', 'action', 'life_archive', '父母出资买房，在转账的时候就把是借是送写清楚', '10. 恋爱和结婚划不划算', '婚前父母出钱买房，默认只给自己孩子。婚后出的钱没约定，按夫妻共同财产算。2025 年 2 月起，婚后一方父母全额出资、又没写明只给自己孩子的，离婚时法院可以把房判给出资方的孩子，再定补不补偿另一方。要算借款，就当天写清楚、双方签字。', '写清楚对两边都有用。出钱的父母不必再指望离婚时补一张借条来保住出资。解释（二）施行后，钱是谁出的本身就是分房子的依据，房本写谁的名字不再决定归属。接受出资的一方，也不用等到离婚才知道这笔钱算什么。要按借款办就真按借款办：双方说好是借，约定怎么还，转账写明，必要时留下还款记录。缺一样，上了法庭都要解释', NULL, NULL, NULL, '不花钱。出资当天写一页说明，写明这笔钱是赠与谁、还是借给谁，出资的父母和子女都签字。如果写的是借款，就让夫妻两个人都签，转账备注也写同一句话。', '婚前父母为双方购房出资的，认定为对自己子女个人的赠与。父母明确表示赠与双方的除外。婚后出资的，有约定按约定。没有约定或者约定不明确的，按夫妻共同财产的原则处理。2025 年 2 月 1 日起还有一条。婚内由一方父母全额出资、赠与合同又没写明只赠与自己子女的，离婚分割时，法院可以判房屋归出资人子女一方所有。判归之后再综合几项情况，确定要不要给另一方补偿、补多少。这几项是共同生活和生育共同子女的情况、离婚过错、对家庭的贡献大小、离婚时房屋市场价格。一方父母部分出资，或者双方父母都出资的，以出资来源和比例为基础判归其中一方，并合理补偿（全国）', '写清楚对两边都有用。出钱的父母不必再指望离婚时补一张借条来保住出资。解释（二）施行后，钱是谁出的本身就是分房子的依据，房本写谁的名字不再决定归属。接受出资的一方，也不用等到离婚才知道这笔钱算什么。要按借款办就真按借款办：双方说好是借，约定怎么还，转账写明，必要时留下还款记录。缺一样，上了法庭都要解释', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-12', 'concept_archive_s10-12', 'claim_archive_s10-12', 'action', 'life_archive', '配偶一方大额借的钱，你没签字也没追认，不自动变成你的债', '10. 恋爱和结婚划不划算', '配偶背着你借的钱，只要明显超出家里日常开销，你又没签字、没事后认账，就不自动变成你的债。要债的人得自己证明这钱用在了共同生活或共同经营上。但买房这种钱如果确实变成了你们一起住或共有的房子，对方往往证得到这一层。', '离婚分财产时，对方父母突然拿出一张只有配偶签字的借款协议，要分两步看。第一步看这笔借款到底有没有真发生。你说钱根本没交过，又能把理由说圆的，法院会结合几件事一起判断。先看借款金额、钱怎么交的、双方的经济能力，再看平时怎么交易、财产有没有相应变动、证人怎么说。对方只拿得出转账凭证的，仍要由他证明这笔借款成立。第二步，借款成立之后再看是不是共同债务。借条和担保书的一般规则见第 8 节第 18 条', NULL, NULL, NULL, '不花钱。别在配偶的借条、担保书上签「共同借款人」「担保人」。也别在聊天里写「这钱我们会还」这类话，它可能被当成你事后认下了这笔债。难在被催的时候忍住不接话。', '下面几种情形借的钱属于夫妻共同债务。一是夫妻双方共同签名的。二是一方事后追认，就是事后认下这笔债，两个人都认账。三是一方在婚内以个人名义为家庭日常生活需要借的。一方以个人名义借的、明显超出家庭日常开销的钱，不属于夫妻共同债务。例外是债权人（要债的一方）能证明这笔钱用于夫妻共同生活、共同生产经营，或者是两个人都认的账。买房的钱明显超出家庭日常生活需要，举证责任在主张债权的一方，要债的人得自己拿出证据。但这笔钱如果确实变成了夫妻共同居住或共有的房子，债权人往往能证到「用于夫妻共同生活」这一层。所以更管用的是第 11 条（父母出资时写清是借是送）那一步（全国，2021 年起）', '离婚分财产时，对方父母突然拿出一张只有配偶签字的借款协议，要分两步看。第一步看这笔借款到底有没有真发生。你说钱根本没交过，又能把理由说圆的，法院会结合几件事一起判断。先看借款金额、钱怎么交的、双方的经济能力，再看平时怎么交易、财产有没有相应变动、证人怎么说。对方只拿得出转账凭证的，仍要由他证明这笔借款成立。第二步，借款成立之后再看是不是共同债务。借条和担保书的一般规则见第 8 节第 18 条', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-13', 'concept_archive_s10-13', 'claim_archive_s10-13', 'action', 'life_archive', '领证只要身份证加一份签字声明，不用户口簿，不收钱，当场发证', '10. 恋爱和结婚划不划算', '2025 年 5 月起领证只要两样东西：本人身份证，加一份签字声明。声明里写明本人没有配偶，和对方没有直系血亲、三代以内旁系血亲关系。户口簿不用带，也不用回一方户口所在地办。登记一分钱不收，符合条件当场发证。', '登记机关不给办的只有四种情况：没到法定结婚年龄，不是双方完全自愿，一方或双方已经有配偶，两人是直系血亲或三代以内旁系血亲。可能收费的只有照相、复印这类周边服务。登记本身一分钱不收，遇到「工本费」「加急费」直接拒绝并投诉。离婚登记的 30 天冷静期见本节退出成本那条', NULL, NULL, NULL, '不花钱。两个人都要亲自到场。办完通常几十分钟。', '2025 年 5 月 10 日起施行的新婚姻登记条例，改了内地居民结婚要交的材料。条文写的是只需出具两样东西：「（一）本人的居民身份证；（二）本人无配偶以及与对方当事人没有直系血亲和三代以内旁系血亲关系的签字声明」。户口簿不再是必需材料。登记机关是「县级人民政府民政部门或者省、自治区、直辖市人民政府按照便民原则确定的乡（镇）人民政府」。旧条例里「到一方当事人常住户口所在地」的限制已经取消。条例还写明「婚姻登记机关办理婚姻登记，不得收取费用」，以及「对当事人符合结婚条件的，应当当场予以登记，发给结婚证」', '登记机关不给办的只有四种情况：没到法定结婚年龄，不是双方完全自愿，一方或双方已经有配偶，两人是直系血亲或三代以内旁系血亲。可能收费的只有照相、复印这类周边服务。登记本身一分钱不收，遇到「工本费」「加急费」直接拒绝并投诉。离婚登记的 30 天冷静期见本节退出成本那条', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-14', 'concept_archive_s10-14', 'claim_archive_s10-14', 'action', 'life_archive', '婚前做一次婚检，有重大疾病必须在登记前如实告诉对方', '10. 恋爱和结婚划不划算', '有重大疾病，没在登记前如实告诉对方，对方可以去法院请求撤销这段婚姻。要在知道之日起一年内提出。婚检本身从 2003 年起就不是领证的前置条件，去不去自愿。费用看本地政策，花半天。', '婚检自 2003 年起就不是领证必须先做的一步，去不去自愿。但「有重大疾病不如实说」这一条，确实给了对方去法院撤销这段婚姻的权利，要在知道之日起一年内提。全国没有统一规定婚检免费。国家卫健委等五部门 2020 年的通知只写了「积极倡导各地结合实际推行免费婚前检查」。所以是否免费、查哪些项目由各地自己定，去当地妇幼保健机构或婚姻登记处的一站式窗口问。', NULL, NULL, NULL, '多数地区对适龄人群免费或者减免。自费也就几百元。要花半天时间。', '隐瞒的法律后果是明确的。新婚姻登记条例规定「一方当事人患有重大疾病的，应当在结婚登记前如实告知另一方当事人；不如实告知的，另一方当事人可以依据民法典第一千零五十三条的规定向人民法院请求撤销婚姻」。国家把婚检当作出生缺陷防治的第一道关口。现行目标是「婚前医学检查率、孕前优生健康检查目标人群覆盖率分别保持在 70% 和 80% 以上」。文件还要求「推进婚前医学检查机构与婚姻登记场所就近设置方便群众」，并推广「婚姻登记、婚前医学检查、生育指导『一站式』服务」。民法典规定，一方患有重大疾病的应当在结婚登记前如实告知，不如实告知的，另一方可以向人民法院请求撤销婚姻。请求撤销婚姻的，应当自知道或者应当知道撤销事由之日起一年内提出', '婚检自 2003 年起就不是领证必须先做的一步，去不去自愿。但「有重大疾病不如实说」这一条，确实给了对方去法院撤销这段婚姻的权利，要在知道之日起一年内提。全国没有统一规定婚检免费。国家卫健委等五部门 2020 年的通知只写了「积极倡导各地结合实际推行免费婚前检查」。所以是否免费、查哪些项目由各地自己定，去当地妇幼保健机构或婚姻登记处的一站式窗口问。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-15', 'concept_archive_s10-15', 'claim_archive_s10-15', 'action', 'life_archive', '算退出成本：协议离婚有 30 天冷静期，诉讼离婚有法定条件', '10. 恋爱和结婚划不划算', '协议离婚不是签完就完。交了申请后 30 天内，任何一方都能撤回。期满还要在 30 天内两人亲自去领离婚证，不去就当撤回。对方不同意，只能起诉。法院先调解，要有家暴、重婚、分居满两年这些情形，调解不成才判离。', '冷静期只适用于协议离婚。诉讼离婚没有冷静期，但周期更长。诉讼费、律师费各地不同，本条不写数字。退出成本高不等于不该结婚，但结婚前就该知道这些', NULL, NULL, NULL, '不花钱。婚前花点时间读一遍：万一要退出，要花多久，走什么程序。难在结婚前就去想散伙的事。', '协议离婚要签书面离婚协议，并亲自到婚姻登记机关申请（第一千零七十六条）。自登记机关收到申请之日起 30 日内，任何一方可以撤回。期满后 30 日内，双方须亲自申领离婚证，不申领视为撤回（第一千零七十七条）。一方不同意时走诉讼，法院应先调解。有重婚或与他人同居、家庭暴力或虐待遗弃、赌博吸毒屡教不改、因感情不和分居满二年等情形的，调解无效应准予离婚。判不离后又分居满一年，再起诉应准予（第一千零七十九条）。2024 年全国离婚 351.3 万对，其中 89.1 万对走的是法院判决、调解', '冷静期只适用于协议离婚。诉讼离婚没有冷静期，但周期更长。诉讼费、律师费各地不同，本条不写数字。退出成本高不等于不该结婚，但结婚前就该知道这些', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-16', 'concept_archive_s10-16', 'claim_archive_s10-16', 'action', 'life_archive', '给「为长辈结婚」单独记一笔账，别和自己的账混在一起', '10. 恋爱和结婚划不划算', '长辈那份收益，也就是安心、面子、不再催，是真的。但它不会自动变成你的健康收益或关系质量。而时间账、钱账和退出成本这三笔，全部由你自己承担。在纸上分两栏，把哪些收益归自己、哪些归长辈写开，这笔账划不划算自己一眼就能看出来。', '长辈那一栏也可以算成很重的一笔，怎么权衡由你自己定。填空清单见 [docs/结婚划不划算.md](../docs/结婚划不划算.md)', NULL, NULL, NULL, '不花钱。在纸上分两栏写。一栏是这段婚姻里哪些收益是你自己的，本节前面几条能算出来。另一栏是哪些收益是长辈的：安心、面子、催婚停止。难在把长辈那一栏单独放着，不往自己这栏里并。', '长辈的收益是真实的。但它不会自动转成你的健康收益（第 8 条）或关系质量（第 4 条，关系好不好看自己的感受）。而时间账（第 9 条）、钱账（第 10 到 12 条）和退出成本（第 15 条），全部由当事人承担。分开记账以后，「做任务式结婚」的性价比是高是低，自己就能看出来', '长辈那一栏也可以算成很重的一笔，怎么权衡由你自己定。填空清单见 [docs/结婚划不划算.md](../docs/结婚划不划算.md)', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","C 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-17', 'concept_archive_s10-17', 'claim_archive_s10-17', 'action', 'life_archive', '把关系好坏当成一笔健康账：吵架对事不对人，别骂人、别挖苦', '10. 恋爱和结婚划不划算', '夫妻关系好的，身体好一些，死亡风险也低一些。这个关联不大，和饮食对健康的关联差不多大。一项实验里，吵架时一直带着敌意的夫妻，实验做出的小伤口愈合速度只有平和夫妻的六成。', '定 B 的理由：汇总的研究大多只是跟踪记录，没有分组对照。所以分不清是关系差让人生病，还是身体差让关系变差。有的研究扣掉年龄和收入之后，关联仍然在。Robles 原文还写明，一部分结果有发表偏倚。明确比较过男女的研究，基本没发现男女不同。本节没有找到直接比较「关系差的婚姻」和「不结婚」死亡率的汇总分析，所以「坏婚姻比不结婚更伤身」只能算推论。伤口实验只有 42 对夫妻。「对事不对人，不骂人不挖苦」是作者从实验里的「敌意行为」推出来的做法，没有研究直接比较过。吵得凶又改不了，两个人一起去做伴侣治疗，见本节第 20 条（伴侣治疗）。吵到动手，或者长期辱骂、威胁，就不是沟通问题了，是家暴，见第 8 节第 43 条（被家暴了）。想清楚要不要走，退出成本见本节第 15 条（退出成本）。', NULL, NULL, NULL, '不花钱。吵架时只说眼前这件事，不骂人，不挖苦，不翻旧账。难在气头上管住嘴。', '把 126 篇研究、7.2 万多人合起来算（荟萃分析）。婚姻质量越高，身体越好，相关系数 r 在 .07 到 .21 之间。相关系数 0 是毫无关系，1 是完全同步。其中和死亡风险更低的相关是 r = .11。吵架时心血管反应更小，r = -.13。作者说，这些效应都小，和饮食这类健康习惯与健康的关联差不多大。另一项交叉实验里，42 对健康夫妻各住院两次，每次 24 小时。一次做互相支持的谈话，一次讨论一件有分歧的事。吵完之后，实验做出的水泡伤口愈合更慢。两次都表现出更多敌意的夫妻，伤口愈合速度只有低敌意夫妻的 60%。吵架第二天早上，他们血里的炎症指标（IL-6、肿瘤坏死因子）也升得更多。', '定 B 的理由：汇总的研究大多只是跟踪记录，没有分组对照。所以分不清是关系差让人生病，还是身体差让关系变差。有的研究扣掉年龄和收入之后，关联仍然在。Robles 原文还写明，一部分结果有发表偏倚。明确比较过男女的研究，基本没发现男女不同。本节没有找到直接比较「关系差的婚姻」和「不结婚」死亡率的汇总分析，所以「坏婚姻比不结婚更伤身」只能算推论。伤口实验只有 42 对夫妻。「对事不对人，不骂人不挖苦」是作者从实验里的「敌意行为」推出来的做法，没有研究直接比较过。吵得凶又改不了，两个人一起去做伴侣治疗，见本节第 20 条（伴侣治疗）。吵到动手，或者长期辱骂、威胁，就不是沟通问题了，是家暴，见第 8 节第 43 条（被家暴了）。想清楚要不要走，退出成本见本节第 15 条（退出成本）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-18', 'concept_archive_s10-18', 'claim_archive_s10-18', 'action', 'life_archive', '同性伴侣趁两个人都清醒，办好授权委托、意定监护和遗嘱：法律上你们不是近亲属，不办就没有签字权和继承权', '10. 恋爱和结婚划不划算', '法律上的近亲属是配偶、父母、子女、兄弟姐妹这些人，伴侣不算。不提前办文件，一方病重时，另一方替他做不了主。一方去世时，另一方一分遗产也继承不到。三份文件各管一段：活着时靠授权委托，失去判断能力后靠意定监护，身后靠遗嘱。', '伴侣拿遗产的身份是「受遗赠人」，不是继承人。知道有这份遗赠后，60 天内要明确表示接受，不表示就算放弃。伴侣本人和跟他有利害关系的人，不能当遗嘱见证人。立了几份遗嘱，以最后一份为准，见第 17 节第 2 条（遗嘱后立的推翻先立的）。意定监护人能不能直接签手术同意书，各医院做法不一，提前问一下常去的医院。家属不认这些文件，就要打官司：一审普通程序 6 个月起，律师费自己出。所以文件尽量去公证处办。一起买的房子、一起存的钱，按真实出资另外写书面约定。意定监护怎么办，见第 17 节第 1 条（书面指定将来的监护人）。受益人是你自己和伴侣。', NULL, NULL, NULL, '意定监护和遗嘱去公证处办，公证费各地不同，几百元起。自己手写遗嘱不花钱。前后要花一两个半天。难在两个人要坐下来谈生病和死。', '民法典第一千零四十五条列的近亲属是配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女。第一千一百二十七条的法定继承人先是配偶、子女、父母，其次是兄弟姐妹、祖父母、外祖父母。伴侣两处都不在。第一千二百一十九条管的是手术、特殊检查、特殊治疗。不能或者不宜向患者说明的，医务人员要向患者的「近亲属」说明，并取得同意。有三条路可以补上。第一，第三十三条允许成年人和「其他愿意担任监护人的个人」事先书面约定监护人。本人丧失或者部分丧失民事行为能力后，这个人来当监护人，监护人就是法定代理人。第二，第一百六十五条规定，书面授权委托书要写明代理人的姓名、代理事项、权限和期限，由本人签名或者盖章。本人一去世，委托就终止。第三，第一千一百三十三条允许立遗嘱，把个人财产赠给法定继承人以外的个人。湖北省司法厅网站刊登的宜昌市司法局文章写明，同性伴侣可以办意定监护协议公证，指定对方当自己将来的监护人（全国）', '伴侣拿遗产的身份是「受遗赠人」，不是继承人。知道有这份遗赠后，60 天内要明确表示接受，不表示就算放弃。伴侣本人和跟他有利害关系的人，不能当遗嘱见证人。立了几份遗嘱，以最后一份为准，见第 17 节第 2 条（遗嘱后立的推翻先立的）。意定监护人能不能直接签手术同意书，各医院做法不一，提前问一下常去的医院。家属不认这些文件，就要打官司：一审普通程序 6 个月起，律师费自己出。所以文件尽量去公证处办。一起买的房子、一起存的钱，按真实出资另外写书面约定。意定监护怎么办，见第 17 节第 1 条（书面指定将来的监护人）。受益人是你自己和伴侣。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-19', 'concept_archive_s10-19', 'claim_archive_s10-19', 'action', 'life_archive', '别靠隐瞒性取向结婚，也别把形婚当成省事的办法：法律上它就是一段真婚姻，想退出只能走离婚', '10. 恋爱和结婚划不划算', '隐瞒性取向结婚，法律上不算无效，也不能撤销，想退出只能离婚。形婚也是真婚姻，婚后挣的钱、欠的债都按夫妻算。被瞒的一方离婚时，可以要求多分财产、赔精神损失，但法院支不支持还没有定论。', '多分财产和精神赔偿只有一篇分析文章，没写案子最后怎么判，所以能不能拿到要看具体法院。民法典比旧法多了「其他重大过错」这一项，给了被瞒的一方一个可以争的口子。法律条文本身是 A 级。形婚双方各有同性伴侣的，伴侣之间不受婚姻法保护，财产要另外写清楚，见本节第 18 条（同性伴侣办意定监护和遗嘱）。形婚离婚一样要走 30 天冷静期或者打官司，见本节第 15 条（协议离婚有 30 天冷静期）。协议离婚时写明放弃赔偿的，事后再起诉不会支持。受益人首先是会被瞒的那个配偶，其次是你自己：隐瞒被发现后，离婚、分财产、孩子抚养会一起摊上。', NULL, NULL, NULL, '不花钱。难的是顶住家里催婚的压力，这可能要扛很多年。', '民法典第一千零五十一条规定，婚姻无效只有三种情形：重婚、有禁止结婚的亲属关系、未到法定婚龄。第一千零五十二、一千零五十三条规定，能撤销的只有两种：被胁迫结婚，婚前隐瞒重大疾病。婚姻家庭编解释（一）第十七条规定，拿这三种以外的理由请求确认婚姻无效，法院判决驳回。所以想退出只能离婚。形婚登记了也是合法婚姻。第一千零六十二条规定，婚后的工资、奖金、劳务报酬等是夫妻共同财产。第一千零六十四条规定，两人共同签字借的债、一方为家庭日常生活借的债，是夫妻共同债务。离婚损害赔偿看第一千零九十一条，限于重婚、与他人同居、家庭暴力、虐待遗弃家庭成员，以及「有其他重大过错」。解释（一）第二条把「与他人同居」限定为和「婚外异性」同居。所以同性关系只能按「其他重大过错」去争。赔偿包括精神损害赔偿，被瞒的一方起诉离婚时要一并提出，判不离就不支持。民法典施行后，没有查到法院公开的这类判决。旧法时期，江苏省高级人民法院网站 2013 年刊登的一篇文章，讨论了妻子因丈夫隐瞒同性恋起诉离婚的案子。文章列了两种看法。一种认为同性恋不在当时法定的过错里，多分财产和精神赔偿都不该支持。作者赞同另一种：把被瞒的一方当作「无过错方」，分财产时照顾她，还应赔精神抚慰金（全国）', '多分财产和精神赔偿只有一篇分析文章，没写案子最后怎么判，所以能不能拿到要看具体法院。民法典比旧法多了「其他重大过错」这一项，给了被瞒的一方一个可以争的口子。法律条文本身是 A 级。形婚双方各有同性伴侣的，伴侣之间不受婚姻法保护，财产要另外写清楚，见本节第 18 条（同性伴侣办意定监护和遗嘱）。形婚离婚一样要走 30 天冷静期或者打官司，见本节第 15 条（协议离婚有 30 天冷静期）。协议离婚时写明放弃赔偿的，事后再起诉不会支持。受益人首先是会被瞒的那个配偶，其次是你自己：隐瞒被发现后，离婚、分财产、孩子抚养会一起摊上。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s10-20', 'concept_archive_s10-20', 'claim_archive_s10-20', 'action', 'life_archive', '关系卡在反复吵架和冷战里，两个人一起去做伴侣治疗：干等着基本不会自己好', '10. 恋爱和结婚划不划算', '关系卡住的伴侣一起做完伴侣治疗，对这段关系明显满意多了，大约七成有好转。光排队干等的伴侣，基本没变化。但效果会变淡：跟到第 5 年，约一半还明显好着，约四分之一已经分居或离婚。', '争议在效果能保持多久。只收随机试验的另一项荟萃分析里，做完时 g = 0.60，半年后 0.44。到 12 个月只剩行为伴侣治疗有数据，g = 0.06，几乎没保住。另一篇汇总 20 项荟萃分析的综述说，有临床意义的效果出现在 40% 到 50% 的人身上。「七成好转」和「四到五成明显好转」用的标准不一样，别混着比。5 年那项试验没有不做治疗的对照，所以说不清离婚是变多还是变少了。2020 年那项汇总的全是异性伴侣，本条也没有找到国内的随机试验，套到自己身上要打折。国内去哪做：精神卫生法规定心理治疗要在医疗机构里做，心理咨询人员不得做心理治疗。可以去医院的精神科、心理科问有没有夫妻治疗。在医院外找机构，先问清对方的资质和受过什么训练。有家暴的先别一起做。2016 年那项荟萃分析写明，结论只适用于轻到中度、双方因冲突动手的情况。以控制对方、严重伤害为特征的暴力不在其内。业内也担心谈完回家遭报复。被打了先看第 8 节第 43 条（被家暴了）。吵架时怎么说话见本节第 17 条（吵架对事不对人），想清楚要不要走见本节第 15 条（退出成本）。受益人是你自己和配偶。', NULL, NULL, NULL, '要花钱。按次收费，各地各医院不一样，本条不写数字。研究里一般每周去一次，一项试验前后做了约 8 个月。难在两个人都得去，还得坚持做完。', '2020 年一项荟萃分析汇总了 58 项研究、2092 对伴侣。做完伴侣治疗，关系满意度的前后变化 g = 1.12（可信范围 0.92–1.31），作者说是大效应。g 是效应量，见 README 术语表。分到排队等候的伴侣，同一段时间 g = 0.12（−0.04 到 0.29），没有明显改善。开始时关系越差的，改善反而越多。2012 年一篇综述写的是，伴侣治疗让 70% 接受治疗的伴侣有好转。另一项随机试验找了 134 对长期、严重不和的夫妻，做了约 8 个月的两种行为伴侣治疗。做完时满意度变化 d = 0.90 和 0.71。到第 5 年，两种做法分别有 50.0% 和 45.9% 的夫妻仍有明显好转。这里的明显好转，作者叫「有临床意义的改善」。同时有 25.7% 和 27.9% 已经分居或离婚', '争议在效果能保持多久。只收随机试验的另一项荟萃分析里，做完时 g = 0.60，半年后 0.44。到 12 个月只剩行为伴侣治疗有数据，g = 0.06，几乎没保住。另一篇汇总 20 项荟萃分析的综述说，有临床意义的效果出现在 40% 到 50% 的人身上。「七成好转」和「四到五成明显好转」用的标准不一样，别混着比。5 年那项试验没有不做治疗的对照，所以说不清离婚是变多还是变少了。2020 年那项汇总的全是异性伴侣，本条也没有找到国内的随机试验，套到自己身上要打折。国内去哪做：精神卫生法规定心理治疗要在医疗机构里做，心理咨询人员不得做心理治疗。可以去医院的精神科、心理科问有没有夫妻治疗。在医院外找机构，先问清对方的资质和受过什么训练。有家暴的先别一起做。2016 年那项荟萃分析写明，结论只适用于轻到中度、双方因冲突动手的情况。以控制对方、严重伤害为特征的暴力不在其内。业内也担心谈完回家遭报复。被打了先看第 8 节第 43 条（被家暴了）。吵架时怎么说话见本节第 17 条（吵架对事不对人），想清楚要不要走见本节第 15 条（退出成本）。受益人是你自己和配偶。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"10. 恋爱和结婚划不划算","A 级","性价比 一般","口径 时间","钱 多","时间 中","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-1', 'concept_archive_s11-1', 'claim_archive_s11-1', 'action', 'life_archive', '动手前先问三句：损害了谁的利益、对方多有能力追究、我留了多少证据；被追究后马上找刑事律师', '11. 程序员和技术人容易踩的红线', '动手之前先问一句：厂商、平台、公司会不会去报案。服务器日志、支付记录、群聊记录，办案时都调得出来。真被刑事拘留了，最长 37 天内决定抓不抓你。从第一次问话起你就能请律师，这 37 天是找刑事律师最管用的时候。', '这 37 天，算的是从被拘留到检察院决定批不批准逮捕，不是关押的上限。批捕之后还有侦查期间的羁押期限，接着往下算。懂行的律师最管用的也是这 37 天：见到人、向检察院递一份「不该批捕」的意见、申请取保候审。等到起诉之后再找律师就晚了。本节其余条目讲的都是同一件事：对方有没有报案的理由。', NULL, NULL, NULL, '不花钱。动手前把「技术上能不能做」换成另一个问题：厂商、平台、公司会不会去报案。难在忍住「这点小事没人管」的念头，因为服务器日志、支付记录、群聊记录，办案时默认都会被调出来', '任何单位和个人发现犯罪事实，都有权去报案。办案机关认为有犯罪事实，就应当立案。被刑事拘留之后，公安要在 3 日内提请批捕（向检察院申请正式逮捕）。特殊情况可以延长 1 到 4 日。流窜作案（跨地方连续作案）这类情形可以延长到 30 日。检察院再用 7 日决定。加起来最长 37 天内决定捕不捕。从第一次讯问起，或者从被采取强制措施（被拘留、逮捕这一类）起，你就可以委托律师。案子还在公安手里查的阶段，只能委托律师。律师要求会见，看守所最迟 48 小时内安排。可能判管制、拘役这类比坐牢轻的刑罚，或者只判附加刑、不判主刑的，可以取保候审：交一笔保证金或者找个保证人，先回家等着办案。取保最长 12 个月（全国）', '这 37 天，算的是从被拘留到检察院决定批不批准逮捕，不是关押的上限。批捕之后还有侦查期间的羁押期限，接着往下算。懂行的律师最管用的也是这 37 天：见到人、向检察院递一份「不该批捕」的意见、申请取保候审。等到起诉之后再找律师就晚了。本节其余条目讲的都是同一件事：对方有没有报案的理由。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","C 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-2', 'concept_archive_s11-2', 'claim_archive_s11-2', 'action', 'life_archive', '不做、不卖游戏外挂和辅助，包括「只读屏幕不碰内存」的 AI 辅助，也不卖给微信这类软件加功能的改版', '11. 程序员和技术人容易踩的红线', '外挂卖出 20 人次，或者挣到 5000 元，就够判 3 年以下，特别严重的判 3 到 7 年。有人做透视、自瞄外挂，3 个月卖了 8 万多，判 1 年缓 1 年、罚 5000 元。有人拿服务端程序开私服，收了 2000 多万充值，最重判 4 年，罚金最高 1000 万元。', '已经公布的外挂判例，都是读写游戏内存、绕过反作弊的那种。「只截屏、只模拟按键」的辅助还没见过官方判例。但第 3 条的抢票案说明，不碰内存、只发请求，一样能定非法获取数据罪。最后算不算犯罪、按哪个罪算，由办案机关根据厂商报案时交上去的材料定，不是作者说了算。卖 20 人次就够「情节严重」，这个量很小。', NULL, NULL, NULL, '不花钱。代价是放弃这类接单和「小工具」的收入。难在这笔钱来得快，又看不出谁会来追究', '提供专门用于侵入、非法控制计算机信息系统的程序、工具，情节严重的判 3 年以下，并处或单处罚金。并处是判刑的同时罚钱，单处是只罚钱。情节特别严重的判 3 到 7 年并处罚金。「情节严重」的门槛是提供工具 20 人次以上，或者违法所得 5000 元以上。违法所得就是靠这件事挣到的钱。故意绕开或者破坏权利人设的技术保护措施，还可能构成侵犯著作权罪，判 3 年以下，严重的判 3 到 10 年。官方案例：王某等人制售外挂，靠读取和修改游戏内存实现透视、自瞄。3 个月卖了 8 万余元，获利 3 万余元。判 1 年缓 1 年、罚 5000 元。缓 1 年就是判了 1 年但先不关，这一年里不再犯事就不用去坐牢。项某等人卖「TZ」系列外挂，销售额 20 余万元，项某判 3 年缓 3 年、罚 2 万元。刘某某等人拿到游戏服务端程序，改参数开私服，收了充值 2000 余万元。判 4 年到 2 年 6 个月，罚 1000 万到 130 万元。不只是游戏。上海一家公司做了刷机包，让手机里的微信多出自动转发、点赞、群发等几十种功能，当「营销手机」卖了 2381 台。2019 年上海徐汇法院按侵犯著作权罪判公司罚金 50 万元，负责人判 1 年 6 个月缓 1 年 6 个月（全国）', '已经公布的外挂判例，都是读写游戏内存、绕过反作弊的那种。「只截屏、只模拟按键」的辅助还没见过官方判例。但第 3 条的抢票案说明，不碰内存、只发请求，一样能定非法获取数据罪。最后算不算犯罪、按哪个罪算，由办案机关根据厂商报案时交上去的材料定，不是作者说了算。卖 20 人次就够「情节严重」，这个量很小。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-3', 'concept_archive_s11-3', 'claim_archive_s11-3', 'action', 'life_archive', '不写、不卖抢票、秒杀、刷单、薅羊毛脚本，哪怕只是「自动化点按钮」', '11. 程序员和技术人容易踩的红线', '脚本不改内存、不破解，只是发请求比人快，一样会被定罪，挣到 5000 元或让对方损失 1 万元就够。有人用买来的 12306 账号代抢 200 多张票、挣了 2 万多，判 1 年 6 个月缓 1 年 6 个月、罚 5000 元。在网店卖抢票软件的，按不正当竞争赔了 2 万元。', '抢票案里的脚本不改内存、不破解，只是「比人快」，仍然按刑法 285 条定罪。收钱代抢和卖脚本都算牟利。自己用一次的情形，没有找到官方案例。', NULL, NULL, NULL, '不花钱，也不占时间', '侵入计算机信息系统，或者用其他技术手段拿到里面的数据，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。「情节严重」的门槛是违法所得 5000 元以上，或者造成损失 1 万元以上。官方案例：某人用外挂批量导入买来的 12306 账号，多线程密集提交购票请求。他代抢火车票 200 余张，获利 2 万余元。法院以非法获取计算机信息系统数据罪，判他 1 年 6 个月缓 1 年 6 个月、罚 5000 元。郑某在网店卖针对某售票 App 的抢票软件，被判构成不正当竞争，赔 2 万元（全国）', '抢票案里的脚本不改内存、不破解，只是「比人快」，仍然按刑法 285 条定罪。收钱代抢和卖脚本都算牟利。自己用一次的情形，没有找到官方案例。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-4', 'concept_archive_s11-4', 'claim_archive_s11-4', 'action', 'life_archive', '爬虫只爬无需登录的公开页面，不绕反爬、不碰个人信息，爬到的数据不卖', '11. 程序员和技术人容易踩的红线', '要登录、要 token、要破解签名才拿得到的数据，属于绕过防护，判 3 年以下，严重的判 3 到 7 年。爬到个人信息更麻烦。行踪、通信、征信、财产类 50 条，就算情节严重。住宿、健康、交易类 500 条，其他类 5000 条，或者挣到 5000 元，也一样。', '2017 年那份司法解释规定，「未经本人同意，把合法收集来的信息给别人」也算「提供」。公司里把用户表导给外部合作方，同样落在这句里。5000 条只是一张小表的量。', NULL, NULL, NULL, '不花钱。爬虫就是自动翻网页、把上面的数据抓下来的程序。爬之前先看一眼 robots 文件和接口授权说明，robots 是网站放在自己根目录、写明哪些页面不让抓的那份文件。要登录、要 token（一串临时通行凭证）、要破解签名才拿得到的数据，不爬。难在这些数据技术上一抓就到手，忍住全靠自觉', '绕过防护拿系统里的数据，量刑和第 3 条（抢票秒杀刷单脚本）一样，判 3 年以下，或者 3 到 7 年。非法获取、出售或者提供公民个人信息，达到下面任何一条就算「情节严重」：行踪轨迹、通信内容、征信、财产信息 50 条以上；住宿、通信记录、健康、交易信息 500 条以上；其他个人信息 5000 条以上；违法所得 5000 元以上。情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。官方案例：软件开发人员李某把窃取手机相册的功能伪装成「颜值检测」软件，拿到人脸照片 1751 张，还倒卖社工库资料，判 3 年缓 3 年。社工库就是把各处泄露的个人信息汇总起来的数据库。某网络科技公司用爬虫拿外卖平台的店铺、订单数据，造成损失 4 万余元，被以非法获取计算机信息系统数据罪追诉（全国）', '2017 年那份司法解释规定，「未经本人同意，把合法收集来的信息给别人」也算「提供」。公司里把用户表导给外部合作方，同样落在这句里。5000 条只是一张小表的量。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-5', 'concept_archive_s11-5', 'claim_archive_s11-5', 'action', 'life_archive', '不接赌博、诈骗、色情 App 的开发单，不替「客户」搭支付通道、解封账号', '11. 程序员和技术人容易踩的红线', '这类报价高、需求含糊的单子，接了就算赌博团伙的共犯。按开设赌场罪判 5 年以下，严重的 5 到 10 年，比单纯帮忙最多判 3 年重。有个电竞竞猜 App，写代码的 28 人判了 1 年到 3 年 6 个月。替诈骗团伙解封 QQ 号的，判 1 年 6 个月、罚 2 万元。', '「明知」不需要对方把用途说出口。报价明显高于市价、功能是充值提现加赔率、客户不肯说用途，办案时都会拿来推断你心里清楚。开发赌博 App 的技术人员，是按开设赌场罪的共犯办，不是帮信罪封顶 3 年那一档。帮信罪是「帮助信息网络犯罪活动罪」的简称。', NULL, NULL, NULL, '不花钱。代价是放弃这类报价高、需求又说不清的外包。难在对方给的钱常常比正常单子高一大截', '明知别人在利用网络犯罪，还给他提供技术支持、支付结算这类帮助，情节严重的判 3 年以下，并处或单处罚金。同时还构成其他犯罪的，按更重的那个罪判。开设赌场判 5 年以下并处罚金，情节严重的判 5 到 10 年。官方案例：张盛集团研发赌博游戏后「包网外销」，收建站费、报表费。涉案近 70 亿元。张盛判 9 年 9 个月、罚 5000 万元。负责外包研发的王强等 79 人，判 6 个月到 9 年 9 个月不等。陈东等人开发运营电竞竞猜 App，技术团队在海南写代码，28 人以开设赌场罪判 3 年 6 个月到 1 年不等，并处罚金。张某某开工作室替诈骗团伙解封被封的 QQ 号，判 1 年 6 个月、罚 2 万元（全国）', '「明知」不需要对方把用途说出口。报价明显高于市价、功能是充值提现加赔率、客户不肯说用途，办案时都会拿来推断你心里清楚。开发赌博 App 的技术人员，是按开设赌场罪的共犯办，不是帮信罪封顶 3 年那一档。帮信罪是「帮助信息网络犯罪活动罪」的简称。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-6', 'concept_archive_s11-6', 'claim_archive_s11-6', 'action', 'life_archive', '离职时交清账号权限，不删库、不留后门、不改密码锁系统，哪怕公司欠你钱', '11. 程序员和技术人容易踩的红线', '账号密码是公司给的，不等于离职后还能用，登进去就算非法控制，判 3 年以下。删数据让系统跑不起来的，判 5 年以下，后果特别严重的判 5 年以上。有个被辞退的高级工程师，用原管理员账号登录公司服务器删数据和日志，损失 12 万多元，判 3 年缓 5 年、罚 3 万元。', '账号密码是公司给的，不等于离职后还能用。用原账号登录，就算「非法控制」。损失按数据恢复费用算，几万元就够立案。', NULL, NULL, NULL, '不花钱。公司欠你工资，走劳动仲裁要回来，别自己动手（劳动仲裁见第 7 节）。难在气头上要忍住不去碰系统', '非法控制计算机信息系统，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。删除、修改系统功能或者数据，造成系统不能正常运行，后果严重的判 5 年以下，特别严重的判 5 年以上。官方案例：IT 高级工程师吕某某被辞退后，用原管理员账号登录公司共享服务器。他改了密码，删了数据和日志，造成损失 12 万余元。判 3 年缓 5 年、罚 3 万元。软件公司员工白某某写升级程序时故意加进错误代码，导致客户系统无法登录，损失 4 万余元，以破坏计算机信息系统罪追诉（全国）', '账号密码是公司给的，不等于离职后还能用。用原账号登录，就算「非法控制」。损失按数据恢复费用算，几万元就够立案。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-7', 'concept_archive_s11-7', 'claim_archive_s11-7', 'action', 'life_archive', '离职不带走源码、客户名单和技术文档，不上传个人网盘，不在下家复用', '11. 程序员和技术人容易踩的红线', '自己写的代码著作权也归公司，客户名单也算商业秘密，带走就是拿公司的东西。有离职员工带着安检系统源码去新公司，本人判 5 年、罚 50 万元，新公司罚 400 万元。有人钻系统漏洞下载 3.3 万多个设计文件，判 1 年 10 个月。公司还可以另外找你索赔。', '「自己写的代码」著作权也归公司，这一点见第 13 条（用公司资源写的代码归公司）。带走就是拿公司的东西。客户名单属于经营信息，同样是商业秘密。判刑之外，公司还会另起民事索赔。', NULL, NULL, NULL, '不花钱。离职前把个人电脑和网盘里的公司资料删干净。难在有些文件是自己一行行写出来的，舍不得', '违反保密义务，把商业秘密说出去或者自己拿来用，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 10 年并处罚金。反不正当竞争法还把两件事列为侵权：用「电子侵入」（技术手段侵入系统）拿商业秘密；教唆、帮助别人违反保密义务。官方案例：孙某明等离职员工带走安检系统源码和核心算法，用在新公司的产品上，孙某明判 5 年、罚 50 万元，新公司罚 400 万元。田某某利用系统漏洞下载 3.3 万余个设计文件，判 1 年 10 个月、罚 10 万元。工程师杨某某把 App 模块源码存进个人电脑和云端，跳槽后做同类 App，以侵犯商业秘密罪追诉（全国）', '「自己写的代码」著作权也归公司，这一点见第 13 条（用公司资源写的代码归公司）。带走就是拿公司的东西。客户名单属于经营信息，同样是商业秘密。判刑之外，公司还会另起民事索赔。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-8', 'concept_archive_s11-8', 'claim_archive_s11-8', 'action', 'life_archive', '不在别人的电脑、服务器、摄像头上跑自己的程序，公司机器不拿来挖矿', '11. 程序员和技术人容易踩的红线', '没经允许控制别人的电脑、服务器、摄像头，到 20 台就判 3 年以下，特别严重的判 3 到 7 年。够不上犯罪的，也要拘留 5 日以下，还可能罚 5 万到 50 万元。受过刑事处罚的人，终身不能干网络安全管理和网络运营的关键岗位。', '用公司服务器挖矿，没有找到最高检、最高法公布的案例，这条是按「没经过允许就控制别人的系统」那条法条写的。「终身不得从事关键岗位」是网络安全法在罚款、判刑之外附带的一道后果，对技术人来说比罚款重。', NULL, NULL, NULL, '不花钱，也不占时间', '对计算机信息系统实施非法控制，情节严重的判 3 年以下，并处或单处罚金，特别严重的判 3 到 7 年。非法控制 20 台以上就算「情节严重」。还够不上犯罪的，公安没收违法所得，拘留 5 日以下，并可以罚 5 万到 50 万元。情节较重的拘留 5 到 15 日，并可以罚 10 万到 100 万元。受过治安处罚的 5 年内、受过刑事处罚的终身，不得从事网络安全管理和网络运营的关键岗位。官方案例：李某买来网络摄像头的 IP，用软件控制了 105 台摄像头窥探隐私，判 3 年缓 5 年、罚 2 万元。吴某等人把木马植入手机主板，控制 330 余万部手机回传验证码，判 2 年到 4 年 6 个月（全国）', '用公司服务器挖矿，没有找到最高检、最高法公布的案例，这条是按「没经过允许就控制别人的系统」那条法条写的。「终身不得从事关键岗位」是网络安全法在罚款、判刑之外附带的一道后果，对技术人来说比罚款重。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-9', 'concept_archive_s11-9', 'claim_archive_s11-9', 'action', 'life_archive', '没有书面授权不测别人的系统，「出于好意」和「事后上报」都不是出罪理由', '11. 程序员和技术人容易踩的红线', '定不定罪看有没有授权、拿到了多少，不看你本意。拿到 500 组普通账号密码，或者挣到 5000 元、让对方损失 1 万元，就够判 3 年以下。为了证明漏洞顺手导一张用户表，常常一次就过了 500 组。手里有账号密码，用在授权范围以外也算侵入。', '检例第 36 号那个指导性案例，本身是卖数据牟利的案子。引它只是为了「超出授权范围登录也算侵入」这一句，不是说善意测试会判得一样重。你本意想干什么、事后有没有上报，都不能把罪名抵消掉，只可能影响判多重、起不起诉。厂商先道谢、回头再报案，两件事并不矛盾，道谢不等于授权。2016 年，一名白帽子把世纪佳缘网站的漏洞提交到第三方漏洞平台，后来世纪佳缘报了警，他被抓。世纪佳缘对记者说，报警是因为有数据被人拿走，当时不知道拿数据的就是提交漏洞的人。此案只有媒体报道，没有判决，也没有官方通报，最后怎么处理没有官方说法。最高法、最高检官网上也没找到能逐字核对的善意测试类案例，所以本条只按法条和处罚标准定级。要做就走厂商公开的 SRC，或者有书面委托的测评，把范围、目标和时间窗口都写进文件。证明漏洞存在用最少的证据，不批量取数据。够不上犯罪的那一档也要挨治安处罚，还有从业禁止，罚款数额和年限同第 8 条（不在别人的机器上跑自己的程序）。发现漏洞之后怎么处理，见第 10 条（漏洞按规定报送）。', NULL, NULL, NULL, '不花钱。参加厂商 SRC 或者众测之前，先拿到写明授权范围、目标清单和可测时间段的文件。SRC 是厂商自己办的安全应急响应中心，专门接收外部报来的漏洞。验证到漏洞确实存在就停手。难在放弃「顺手试一下」这一下', '普通公司和个人的系统，属于国家事务、国防建设、尖端科学技术领域以外的计算机信息系统。侵入这类系统，或者采用其他技术手段，拿到里面存储、处理、传输的数据，情节严重的判 3 年以下有期徒刑或者拘役，并处或单处罚金。特别严重的判 3 到 7 年并处罚金。「情节严重」有几条标准：拿到支付结算、证券交易、期货交易等网络金融服务的身份认证信息（账号密码这类）10 组以上；拿到其他身份认证信息 500 组以上；非法控制计算机信息系统 20 台以上；违法所得 5000 元以上，或者造成经济损失 1 万元以上。上面这些数字的 5 倍以上，就是「情节特别严重」。官方案例：检例第 36 号确立了一句话，「超出授权范围使用账号、密码登录计算机信息系统，属于侵入计算机信息系统的行为」。意思是手里本来就有账号密码，但用在授权范围以外，这个行为本身就算侵入。该案三人用工作中掌握的账号、密码和令牌，异地登录公司内部系统，下载了不属于工作范围的数据，拿到网上出售，违法所得 37000 元。三人分别判 4 年、3 年 9 个月、4 年，各罚 4 万元（全国）', '检例第 36 号那个指导性案例，本身是卖数据牟利的案子。引它只是为了「超出授权范围登录也算侵入」这一句，不是说善意测试会判得一样重。你本意想干什么、事后有没有上报，都不能把罪名抵消掉，只可能影响判多重、起不起诉。厂商先道谢、回头再报案，两件事并不矛盾，道谢不等于授权。2016 年，一名白帽子把世纪佳缘网站的漏洞提交到第三方漏洞平台，后来世纪佳缘报了警，他被抓。世纪佳缘对记者说，报警是因为有数据被人拿走，当时不知道拿数据的就是提交漏洞的人。此案只有媒体报道，没有判决，也没有官方通报，最后怎么处理没有官方说法。最高法、最高检官网上也没找到能逐字核对的善意测试类案例，所以本条只按法条和处罚标准定级。要做就走厂商公开的 SRC，或者有书面委托的测评，把范围、目标和时间窗口都写进文件。证明漏洞存在用最少的证据，不批量取数据。够不上犯罪的那一档也要挨治安处罚，还有从业禁止，罚款数额和年限同第 8 条（不在别人的机器上跑自己的程序）。发现漏洞之后怎么处理，见第 10 条（漏洞按规定报送）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-10', 'concept_archive_s11-10', 'claim_archive_s11-10', 'action', 'life_archive', '漏洞按规定报送，修补前不公开细节、不发利用工具、不交给境外', '11. 程序员和技术人容易踩的红线', '个人也归《网络产品安全漏洞管理规定》管。厂商拿出修补办法之前，你不能公开漏洞，也不能公开正在用的系统的漏洞细节。不能发专门利用漏洞的程序和工具，公开时要同时说清怎么修。没公开的漏洞，不能交给厂商以外的境外组织和个人。', '规定把个人明确写进了管的对象里，「我只是个业余爱好者」不在例外里。往境外的漏洞赏金平台提交国内系统的洞，正落在「未公开的漏洞不得提供给境外」这一条上。有没有资格去测，见第 9 条（没有书面授权不测别人的系统），和拿到漏洞后怎么处置要分开看。合法发现的漏洞，也可能因为发布方式违规被罚；未经授权测出来的漏洞，测和发布两头都有问题。报送渠道里，工信部平台和国家互联网应急中心（CNCERT）用得最多。规定没有专门区分「已经通知厂商、厂商却不修」这种情况，实际做法是把协商和报告的过程留下记录，同时报给官方平台。', NULL, NULL, NULL, '不花钱。把漏洞报给产品提供者，或者报给官方平台。厂商修好之前，不发细节，也不发验证代码', '这份规定管三类对象：境内的网络产品提供者、网络运营者，以及从事漏洞发现、收集、发布等活动的组织或者个人。任何组织或者个人，不得利用漏洞从事危害网络安全的活动，不得非法收集、出售、发布漏洞信息。向社会发布漏洞信息要守五条。第一，不得在产品提供者提供修补措施之前发布。第二，不得发布网络运营者在用的网络、信息系统及其设备存在漏洞的细节情况。第三，不得刻意夸大危害和风险，不得利用漏洞信息实施恶意炒作或者诈骗。第四，不得发布或者提供专门用于利用漏洞从事危害网络安全活动的程序和工具。第五，发布时应当同步发布修补或者防范措施。另外，未公开的漏洞信息，不得提供给产品提供者之外的境外组织或者个人。规定鼓励把漏洞报给四个官方平台。一是工业和信息化部网络安全威胁和漏洞信息共享平台。二是国家网络与信息安全信息通报中心漏洞平台。三是国家计算机网络应急技术处理协调中心漏洞平台。四是中国信息安全测评中心漏洞库。违反规定收集、发布漏洞信息的，由工业和信息化部、公安部依据各自职责依法处理。构成网络安全法规定情形的，依该法处罚。向社会发布系统漏洞等网络安全信息，应当遵守国家有关规定。违反的，由有关主管部门责令改正、给予警告，可以处 1 万元以上 10 万元以下罚款。拒不改正或者情节严重的，处 10 万元以上 100 万元以下罚款。还可以责令暂停相关业务、停业整顿、关闭网站或者应用程序。也可以吊销相关业务许可证或者吊销营业执照。对直接负责的主管人员和其他直接责任人员，处 1 万元以上 10 万元以下罚款（全国）', '规定把个人明确写进了管的对象里，「我只是个业余爱好者」不在例外里。往境外的漏洞赏金平台提交国内系统的洞，正落在「未公开的漏洞不得提供给境外」这一条上。有没有资格去测，见第 9 条（没有书面授权不测别人的系统），和拿到漏洞后怎么处置要分开看。合法发现的漏洞，也可能因为发布方式违规被罚；未经授权测出来的漏洞，测和发布两头都有问题。报送渠道里，工信部平台和国家互联网应急中心（CNCERT）用得最多。规定没有专门区分「已经通知厂商、厂商却不修」这种情况，实际做法是把协商和报告的过程留下记录，同时报给官方平台。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-11', 'concept_archive_s11-11', 'claim_archive_s11-11', 'action', 'life_archive', '不卖翻墙工具、VPN 账号，不替人搭这类节点', '11. 程序员和技术人容易踩的红线', '自己搭线路出境，或者用国家公用信道以外的国际信道，公安可以责令停止联网、给予警告，罚 1.5 万元以下并没收违法所得。靠这个做生意的，办案机关可以按非法经营罪办，情节严重的判 5 年以下。这条讲的是卖和搭节点。个人自己用的，处罚以警告加罚款为上限。', '本节写作时，未在最高法、最高检官网找到公布的翻墙类判例，各地处理差异也大，所以定 B 级。个人自己用的，处罚最重是暂行规定第十四条写的警告加罚款。', NULL, NULL, NULL, '不花钱，也不占时间', '直接进行国际联网，必须使用国家公用电信网提供的国际出入口信道。任何单位和个人不得自行建立或者使用其他信道：既不能自己搭线路出境，也不能用别人搭的。违反的，由公安责令停止联网、给予警告，可以并处 1.5 万元以下罚款，没收违法所得。靠这个做生意的，办案机关可以按非法经营罪处理。情节严重的判 5 年以下，并处或单处违法所得 1 到 5 倍的罚金。特别严重的判 5 年以上（全国）', '本节写作时，未在最高法、最高检官网找到公布的翻墙类判例，各地处理差异也大，所以定 B 级。个人自己用的，处罚最重是暂行规定第十四条写的警告加罚款。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","B 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-12', 'concept_archive_s11-12', 'claim_archive_s11-12', 'action', 'life_archive', '签了竞业协议，离职后公司不按月给补偿就书面催告，满 3 个月没给可以解除；没接触过商业秘密的岗位可请求确认条款不生效', '11. 程序员和技术人容易踩的红线', '竞业限制就是离职后一段时间不许去同行干活，最长 2 年，公司要按月给补偿。没约定数额的，按离职前 12 个月平均工资的 30% 给，不低于当地最低工资。公司的原因 3 个月没给，你可以请求解除。2025 年起，没接触过商业秘密的岗位，可以请求确认条款不生效。', '反过来，协议有效、公司也按月付了钱，你还去竞品上班，就要按约定掏违约金。掏完还可能被要求把剩下的竞业期守完。在职期间约定的竞业，公司不另外给钱也算数。', NULL, NULL, NULL, '不花钱。离职时留好竞业协议的原件，以及公司没有按月付钱的证据', '竞业限制只能约束高管、高级技术人员，以及其他负有保密义务的人。期限最长 2 年。公司必须在这段期限内按月给经济补偿。没有约定补偿数额的，按离职前 12 个月平均工资的 30% 给，并且不低于当地最低工资。因为公司自己的原因 3 个月没付，劳动者可以请求解除这份竞业限制。公司主动解除的，要额外付 3 个月补偿。2025 年起，岗位上没知道、没接触过商业秘密的劳动者，可以请求确认条款不生效。约定范围超出他实际知道的那部分秘密的，超出的部分无效。官方案例：某医药公司起诉首席技术官郑某，索赔违约金 710 万元。法院认定他新东家的产品与原公司不具替代性，竞业范围应当限于他实际知悉的秘密，判决全部驳回（全国）', '反过来，协议有效、公司也按月付了钱，你还去竞品上班，就要按约定掏违约金。掏完还可能被要求把剩下的竞业期守完。在职期间约定的竞业，公司不另外给钱也算数。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-13', 'concept_archive_s11-13', 'claim_archive_s11-13', 'action', 'life_archive', '上班时间、用公司资源写的代码归公司，自己的开源项目用自己的时间和设备做，不混公司代码', '11. 程序员和技术人容易踩的红线', '主要靠公司的设备、内网或业务数据写出来、由公司担责的软件，著作权归公司，你只保留署名权，合同这么约定的也一样。下班写的，只要用了公司电脑或业务数据，同样可能算公司的。用公司资源做出的发明，专利也归公司。', '软件被直接写进「著作权归单位」那一类，程序员几乎落不进「著作权归作者、单位两年内优先使用」那一档。「下班写的」只要用了公司电脑、内网或者公司业务数据，一样可能被算成主要是靠单位的设备和资料做出来的。想把个人项目做干净，就用自己的机器，不碰公司仓库，不和公司业务重叠。', NULL, NULL, NULL, '不花钱。入职时把劳动合同里的知识产权条款看清楚。难在个人项目和公司的活常常混在一台电脑上，要分开', '为完成单位工作任务创作的作品是职务作品（上班干活做出来的东西）。一般情形下著作权归作者，单位有权在业务范围内优先使用，并且 2 年内作者不得许可第三人以相同方式使用。但有两类情况不一样。一类是主要利用单位物质技术条件创作、并由单位承担责任的工程设计、软件等作品。另一类是合同约定归单位的作品。这两类作者只保留署名权。单位物质技术条件指的是公司的设备、内网、业务数据这些。执行本单位任务，或者主要利用本单位物质技术条件完成的发明创造，是职务发明，申请专利的权利和拿到的专利权都归单位（全国）', '软件被直接写进「著作权归单位」那一类，程序员几乎落不进「著作权归作者、单位两年内优先使用」那一档。「下班写的」只要用了公司电脑、内网或者公司业务数据，一样可能被算成主要是靠单位的设备和资料做出来的。想把个人项目做干净，就用自己的机器，不碰公司仓库，不和公司业务重叠。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-14', 'concept_archive_s11-14', 'claim_archive_s11-14', 'action', 'life_archive', '用 GPL 等开源代码做产品，按许可证要求开源或换许可证，不当「没人管」', '11. 程序员和技术人容易踩的红线', '侵犯著作权，按对方的损失或你挣到的钱赔，故意且情节严重的，能判到 1 到 5 倍。有家公司招了对手的前员工，做出实质相似的软件，辩称对方软件用了 GPLv2、本该开源。最高法认为对方开不开源不影响它的著作权，照样判停止侵害、赔 50 万元。', '这个案子说明，「对方用了 GPL 代码」不能当成你抄它的理由。反过来，GPL 作者起诉不开源的商用方，在国内已经有生效判决，本节未在最高法官网找到原文，所以不引。定 B 级是因为守不守开源许可证，只能靠合同和著作权法里的通用规定管，没有一条专门的法条。', NULL, NULL, NULL, '不花钱。用别人的开源代码之前，看一眼它的许可证（作者写明的使用条件）。GPL 这一系要求用了它的产品也得把源码开出来，和闭源卖钱冲突，冲突就换一个。难在舍掉一个已经用顺手的库', '侵犯著作权，按权利人的实际损失赔，或者按侵权人挣到的钱赔。这两样都算不清的，参照正常买这份授权要付多少钱来定。故意侵权并且情节严重的，可以判 1 到 5 倍赔偿。损害公共利益的，还可以没收违法所得并处罚款。官方案例：（2021）最高法知民终 51 号。被告招聘了原告的前员工，开发出的网关软件与原告软件实质相似。被告抗辩说，原告软件基于 GPLv2、本来就该开源。最高法认定「开发者自身是否违反 GPLv2 协议和是否享有软件著作权是两个独立问题」，判停止侵害、赔偿 50 万元（全国）', '这个案子说明，「对方用了 GPL 代码」不能当成你抄它的理由。反过来，GPL 作者起诉不开源的商用方，在国内已经有生效判决，本节未在最高法官网找到原文，所以不引。定 B 级是因为守不守开源许可证，只能靠合同和著作权法里的通用规定管，没有一条专门的法条。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-15', 'concept_archive_s11-15', 'claim_archive_s11-15', 'action', 'life_archive', '做 App 只收业务必需的个人信息，14 岁以下要监护人同意，隐私政策写清楚', '11. 程序员和技术人容易踩的红线', '只收业务必需的信息，不满 14 岁的要监护人同意。违规的先责令改正，App 可能被停掉。拒不改正罚 100 万元以下，负责人罚 1 万到 10 万元。严重的罚 5000 万元以下或上年营业额的 5%，负责人罚 10 万到 100 万元，写代码和做产品的也可能算负责人。', '「直接责任人员」在实务里常常落到写代码和做产品的人头上。工信部定期通报下架违规 App，本节没有核实到具体是哪一期通报，所以不引。', NULL, NULL, NULL, '不花钱。上线前把 App 申请的权限列表和隐私政策对一遍，能不要的权限就不要。难在产品那边总想多留一些「以后可能用得上」的数据', '处理个人信息应当有明确合理的目的，与这个目的直接相关，并且采取对个人权益影响最小的方式。处理个人信息要取得个人同意，或者符合法定情形。不满 14 周岁的，必须取得父母或者监护人同意。违反的，由监管部门责令改正、给予警告、没收违法所得，对违法的 App 责令暂停或者终止提供服务。拒不改正的罚 100 万元以下，对直接负责的主管人员和其他直接责任人员罚 1 万到 10 万元。情节严重的罚 5000 万元以下，或者上一年度营业额 5% 以下。责任人员罚 10 万到 100 万元。这些人还可能被禁止在一定期限内担任相关企业的董事、监事、高管。出售或者提供个人信息构成犯罪的，见第 4 条（全国）', '「直接责任人员」在实务里常常落到写代码和做产品的人头上。工信部定期通报下架违规 App，本节没有核实到具体是哪一期通报，所以不引。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","B 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-16', 'concept_archive_s11-16', 'claim_archive_s11-16', 'action', 'life_archive', '网站、App 上线前先做 ICP 备案，按等级保护要求留 6 个月以上日志', '11. 程序员和技术人容易踩的红线', '备案不要钱，走云厂商流程大概几周，境内服务器不备案会被关站。备案说不收费、实际在收钱的，罚 10 万到 100 万元。日志要留满 6 个月，拒不改正或出了后果的罚 1 万到 10 万元。', '境内服务器不备案，域名根本解析不了。备案怎么办、不挂备案号罚多少、怎么查服务商有没有资质，见第 26 节第 4 条（服务器放境内就要备案）。常见的坑有两种：备案成个人非经营性，实际却在收费；换了域名或者换了主体，没去变更备案。日志留 6 个月既是义务也是自保，出事时能证明不是你干的。', NULL, NULL, NULL, '备案免费，走云厂商的流程大概几周。等级保护测评按级别收费。等级保护简称等保，是国家按系统重要程度分级、要求网站和系统做到的一套安全管理动作，小站一般不需要做测评', '经营性的互联网信息服务实行许可，非经营性的实行备案。没有取得许可、或者没有备案的，不得从事。未备案的，由电信管理机构责令改正，拒不改正的责令关闭网站。未经许可经营的，没收违法所得，并罚违法所得的 3 到 5 倍，或者罚 10 万到 100 万元。网站主页不标备案号，罚 5000 元到 5 万元。网络运营者要按等级保护制度（等保）制定安全管理制度、防范攻击、留存网络日志不少于 6 个月、对数据分类备份加密。不履行的，责令改正、给予警告。拒不改正或者造成后果的，罚 1 万到 10 万元，主管人员罚 5000 元到 5 万元（全国）', '境内服务器不备案，域名根本解析不了。备案怎么办、不挂备案号罚多少、怎么查服务商有没有资质，见第 26 节第 4 条（服务器放境内就要备案）。常见的坑有两种：备案成个人非经营性，实际却在收费；换了域名或者换了主体，没去变更备案。日志留 6 个月既是义务也是自保，出事时能证明不是你干的。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-17', 'concept_archive_s11-17', 'claim_archive_s11-17', 'action', 'life_archive', '对公众提供生成式 AI 服务前先按规定做安全评估和算法备案，生成内容加标识', '11. 程序员和技术人容易踩的红线', '面向公众、能影响舆论或动员人的生成式 AI 服务，上线前要做安全评估、办算法备案，改了或停了还要办变更、注销。生成的图片和视频要加标识。自己用、不对公众开放的小工具不用管这些。违反了按网络安全法等法律处罚。', '这个办法自己没写罚多少钱。违反了要回到网络安全法、数据安全法、个人信息保护法里找处罚，所以定 B 级。用 AI 生成的内容侵犯别人著作权、肖像的民事案例，本节未在最高法官网核实原文，不引。低价转卖境外大模型接口的中转站，见本节第 19 条（AI 中转站）。', NULL, NULL, NULL, '不花钱，但要走网信部门的流程，办下来要花些时间。个人做的小工具只要不对公众开放，就不触发这一套', '提供具有舆论属性或者社会动员能力的生成式人工智能服务，应当按国家规定开展安全评估，并按算法推荐管理规定办算法备案，以及后续的变更、注销手续。舆论属性或者社会动员能力，指的是能影响公众看法，或者能把人组织动员起来。提供者应当对图片、视频等生成内容进行标识。办法自 2023 年 8 月 15 日施行（全国）', '这个办法自己没写罚多少钱。违反了要回到网络安全法、数据安全法、个人信息保护法里找处罚，所以定 B 级。用 AI 生成的内容侵犯别人著作权、肖像的民事案例，本节未在最高法官网核实原文，不引。低价转卖境外大模型接口的中转站，见本节第 19 条（AI 中转站）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","B 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-18', 'concept_archive_s11-18', 'claim_archive_s11-18', 'action', 'life_archive', '不做、不发自动跳过或屏蔽别家 App 广告的工具，免费、不联网也可能被判不正当竞争', '11. 程序员和技术人容易踩的红线', '做软件替用户跳过、屏蔽别家 App 的广告，会被对方告不正当竞争。不收钱也可能算，法律管的经营者包括提供服务的个人。有浏览器默认屏蔽芒果TV 的片头广告，赔了 80 万元。有 App 让人直接跳过芒果TV 的开屏广告，赔了 8 万元损失。', '两起判决用的是修订前的条文。2025 年修订后，这一条挪到第十三条，还加上了数据、算法和平台规则。二审法院说判的是屏蔽，用户自己点「跳过」不受影响。2023 年 8 月，安卓上的免费跳广告工具「李跳跳」收到腾讯的律师函。律师函说它屏蔽了腾讯浏览器的广告，构成不正当竞争，要它 48 小时内下架。开发者说它是公益性质、不盈利，报道说它只收零星打赏，但它还是宣布无限期停更，几款同类软件也停了。此事只有媒体报道，没有起诉，也没有判决。个人开发者收到律师函，要么停手，要么自己花钱请律师应诉。一审普通程序 6 个月起，律师费一般自己出。自己写个脚本只给自己用，没找到被追究的案例。卖抢票软件按不正当竞争赔钱，见本节第 3 条（抢票秒杀脚本）。受益人是你自己。', NULL, NULL, NULL, '不花钱。代价是放掉一个很受欢迎的小工具。难在你觉得自己没挣钱，只是替用户点了一下「跳过」', '法律规定，经营者不得利用技术手段，妨碍、破坏其他经营者合法提供的网络产品或服务正常运行。这里的经营者，指提供商品或服务的自然人、法人和非法人组织。给对方造成损害的，按对方的实际损失赔，或者按你因此得到的好处赔，再加上对方为制止侵权花的合理开支。市场监管部门还可以罚 10 万到 100 万元，情节严重的罚 100 万到 500 万元。官方案例：720 浏览器的内置功能默认拦截芒果TV 网站的片头广告和暂停广告。一审驳回了芒果TV 的起诉。广州知识产权法院二审改判，认定构成不正当竞争，判赔经济损失和合理开支 80 万元。2021 年最高法把它列为典型案例。「拦精灵」App 让用户直接跳过芒果TV 的开屏广告。一审判它停止，赔经济损失 8 万元、合理开支 1 万元。2024 年 4 月，北京知识产权法院二审维持。二审认为它实际是把开屏广告屏蔽了，不只是替用户点「跳过」（全国）', '两起判决用的是修订前的条文。2025 年修订后，这一条挪到第十三条，还加上了数据、算法和平台规则。二审法院说判的是屏蔽，用户自己点「跳过」不受影响。2023 年 8 月，安卓上的免费跳广告工具「李跳跳」收到腾讯的律师函。律师函说它屏蔽了腾讯浏览器的广告，构成不正当竞争，要它 48 小时内下架。开发者说它是公益性质、不盈利，报道说它只收零星打赏，但它还是宣布无限期停更，几款同类软件也停了。此事只有媒体报道，没有起诉，也没有判决。个人开发者收到律师函，要么停手，要么自己花钱请律师应诉。一审普通程序 6 个月起，律师费一般自己出。自己写个脚本只给自己用，没找到被追究的案例。卖抢票软件按不正当竞争赔钱，见本节第 3 条（抢票秒杀脚本）。受益人是你自己。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s11-19', 'concept_archive_s11-19', 'claim_archive_s11-19', 'action', 'life_archive', '不搭「AI 中转站」低价转卖境外大模型接口：上海已有站长被刑事拘留', '11. 程序员和技术人容易踩的红线', 'AI 中转站就是低价转卖境外大模型接口的网站。上海有个站长因此被刑事拘留 37 天，取保后他自己说肯定会被判刑，已经退赔退赃。国家安全部也发过提示，说不少中转站没有运营资质，还私自把用户数据传到境外。', '此案只有媒体报道和当事人自述，没有判决，也没有警方通报，按什么罪名办没有官方说法。网上流传的具体罪名和刑期出自律师文章，本书不引。所以不能说「做中转站一定犯罪」，只能说已经有人因此被刑事拘留。正规做模型聚合，收费要办经营许可，见第 26 节第 2 条（收费的网站要许可证）。对公众提供生成式 AI 服务要备案，见本节第 17 条（生成式 AI 安全评估）。把用户数据传到境外有法定条件，见第 26 节第 10 条（用户信息出境）。用中转站的人另有风险，见第 14 节第 10 条（AI 中转站）。受益人是你自己。', NULL, NULL, NULL, '不花钱。代价是放掉一门门槛低、流水看着不错的副业。真想做模型聚合就走正路，办经营许可、接有官方授权的模型，钱和时间都要花不少', '国家安全部 2026 年 6 月发布风险提示。提示说，AI 中转站是夹在用户和模型厂商官方服务之间的代理层。部分中转站运营资质缺失。有的没取得数据出境的合规资质，也没走安全评估的法定流程，就把用户输入的数据传到境外服务器。有的还能让用户绕过网络访问、官方授权和跨境传输的限制。《中国新闻周刊》2026 年 6 月报道了一个案子。2026 年 5 月，一名上海的中转站站长在技术社区发了关停声明。他说自己因为非法获取大模型接口，被上海警方刑事拘留 37 天，现在取保候审。他说「将来肯定会被判刑」，已经退赔退赃，还要交罚金。报道说，这类中转站批量注册或购买境外大模型的订阅账号，在海外架服务器当跳板，再低价转卖给国内用户（全国 / 上海）', '此案只有媒体报道和当事人自述，没有判决，也没有警方通报，按什么罪名办没有官方说法。网上流传的具体罪名和刑期出自律师文章，本书不引。所以不能说「做中转站一定犯罪」，只能说已经有人因此被刑事拘留。正规做模型聚合，收费要办经营许可，见第 26 节第 2 条（收费的网站要许可证）。对公众提供生成式 AI 服务要备案，见本节第 17 条（生成式 AI 安全评估）。把用户数据传到境外有法定条件，见第 26 节第 10 条（用户信息出境）。用中转站的人另有风险，见第 14 节第 10 条（AI 中转站）。受益人是你自己。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"11. 程序员和技术人容易踩的红线","C 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-1', 'concept_archive_s12-1', 'claim_archive_s12-1', 'action', 'life_archive', '只拿亏得起的钱创业，不动家底、不借钱开张', '12. 创业与做生意：别把家底赔进去', '个体户欠的钱，要拿你自己名下的钱和东西还。分不清是不是全家一起做的，就拿全家的财产还。开公司也不保险：公司还不上债的时候，你当初答应出、还没到期的那笔出资，会被要求提前掏出来。所以投多少，按「全亏光也照样还房贷、看病」来定。', '「亏得起」的意思是：这笔钱全亏掉，你也不用卖房，不用找亲戚借钱补窟窿。有多少企业能活下来、平均活几年，这类官方统计本次在国家统计局和市场监管总局官网都没找到能核实的原文。所以正文不写数字，只写法律后果，定 B 级。', NULL, NULL, NULL, '不花钱。动手前先给自己定一个数：这笔钱全亏光，也不影响你还房贷、养孩子、看病。超过这个数就不投。家里人的钱和借来的钱，不算在这个数里。难的是生意看着有起色的时候，忍住不再往里追加。', '亏了不只是钱没了。个体工商户欠的债，如果生意是你一个人做的，要拿你自己名下的钱和东西还（以个人财产承担）。如果是全家一起做的，或者分不清是谁做的，要拿全家的钱和东西还（以家庭财产承担）。夫妻两人都签了字的债，算两个人一起还的共同债务。一方事后点了头的，也算。一方用自己名义借的钱，只要债主能证明这笔钱用在了两口子一起做的生意上，照样两个人一起还。公司这边也有一条：公司还不上到期的债时，股东当初在注册资本里答应出、还没到缴纳期限的那笔钱（认缴出资），债主可以要求他提前交出来（全国）', '「亏得起」的意思是：这笔钱全亏掉，你也不用卖房，不用找亲戚借钱补窟窿。有多少企业能活下来、平均活几年，这类官方统计本次在国家统计局和市场监管总局官网都没找到能核实的原文。所以正文不写数字，只写法律后果，定 B 级。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-2', 'concept_archive_s12-2', 'claim_archive_s12-2', 'action', 'life_archive', '不给公司贷款签个人担保，配偶更不要跟着签', '12. 创业与做生意：别把家底赔进去', '签的是「连带责任保证」，公司还不上钱，债主可以绕开公司直接找你要。写「一般保证」才是先告公司，卖完公司财产还差多少才轮到你。配偶跟着签字，两个人的家产一起搭进去，有限公司的「有限」对你个人就不算数了。', '银行给小微企业放贷款，几乎都要股东个人签连带担保。贷款照样可以贷，只是签字之前要弄清楚这一页签掉的是什么，再把担保的金额压在第 1 条（只拿亏得起的钱创业）那个「亏得起」的数以内。借条和担保书的一般规则，见第 8 节第 18 条。', NULL, NULL, NULL, '不花钱。银行、供应商、房东要你签「股东个人连带担保」或者「配偶签字」时，先停一下。签那一页，等于你亲手放弃了「公司的债不找个人」这层保护（放弃有限责任）。能不签就不签。非签不可，就只签「一般保证」，并且写清自己最多担保多少钱。难的是对方常说「不签就不放款」，要顶得住。', '担保书上的那句话，意思就是「欠钱的人不还，由你来还」。写成「连带责任保证」的，债主可以不去找公司，直接上门找你要。写成「一般保证」的，债主得先去告公司或者去仲裁，再请法院把公司的财产强制卖掉抵债。卖完还差多少，才轮到你补。夫妻两人都签了字的债，算两个人一起还的共同债务。一方事后点了头的，也算。配偶签了字，就是两个人的家产一起搭进去（全国，2021 年起）', '银行给小微企业放贷款，几乎都要股东个人签连带担保。贷款照样可以贷，只是签字之前要弄清楚这一页签掉的是什么，再把担保的金额压在第 1 条（只拿亏得起的钱创业）那个「亏得起」的数以内。借条和担保书的一般规则，见第 8 节第 18 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-3', 'concept_archive_s12-3', 'claim_archive_s12-3', 'action', 'life_archive', '开张前选对主体：个体户和合伙人赔到底，有限公司才「有限」', '12. 创业与做生意：别把家底赔进去', '个体户和普通合伙人要赔到底，欠多少还多少。有限公司的股东只赔自己注册时答应出的那个数。但答应了多少，5 年内就要真拿出多少：填 100 万，就是可能欠着 100 万。公司账和自家账混着用，「有限」也会失效。', '「有限」的前提是公私分明：公司账户和个人账户不混着用，不用公司的钱付家里的开销，账目留全。注册资本别为了好看填大数。认缴多少，5 年内就要真拿出多少。填 100 万，就是 100 万的潜在债务。', NULL, NULL, NULL, '登记在当地政务服务网上办，一次几个小时。开了有限公司之后每个月要记账报税，这是长期的开销：自己做花时间，请人代记账花钱，各地价格不同。', '个体工商户欠的债，要拿个人的钱和东西还，或者拿全家的钱和东西还。普通合伙企业的合伙人，对合伙企业的债承担无限连带责任。意思是欠多少还多少，还不完不算完。债主还可以只揪住其中一个人，要他还全部。有限合伙不一样，里面的有限合伙人只赔到自己答应出的那笔钱（以认缴出资为限）为止。有限责任公司的股东也是只赔到自己答应出的那笔钱（以认缴出资额为限）。但「有限」会在三种情况下失效。一是答应出的钱要在公司成立起 5 年内真交齐，公司还不上到期的债时，债主可以要求提前交。二是已经投进去又抽走的钱（抽逃出资）要还回来。三是拿公司当壳子躲债。只有一个股东的公司，又证明不了公司的钱和自己的钱是分开的，也算在这第三种里。这两种做法之下，公司的债你个人要跟着一起还（承担连带责任）（全国，2024 年 7 月起）', '「有限」的前提是公私分明：公司账户和个人账户不混着用，不用公司的钱付家里的开销，账目留全。注册资本别为了好看填大数。认缴多少，5 年内就要真拿出多少。填 100 万，就是 100 万的潜在债务。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-4', 'concept_archive_s12-4', 'claim_archive_s12-4', 'action', 'life_archive', '不当挂名股东，不替人代持股权', '12. 创业与做生意：别把家底赔进去', '名字登记在册，你在法律上就是股东。注册时答应出的钱要按期交齐，交不上除了补交还要赔公司的损失。公司开办时别的股东没真把钱交进来，缺多少你也跟着还多少。生意是别人做的，债记在你名下。', '替人挂名的股东和真正出钱的人之间，代持协议没有无效情形的就算数。但真正出钱的人想把名字换上来，要其他股东半数以上同意。挂名的人把股权卖了或者押了，法院参照民法典的善意取得处理。买方不知情、价格合理、已经办了登记的，出钱的人拿不回股权，只能找挂名的人赔。这份司法解释 2025 年 9 月已出了新解释的征求意见稿，定稿施行后整份废止，以截至 2026 年 9 月仍有效的 2020 年修正本为准。挂名法定代表人的风险，见第 8 节第 28 条。', NULL, NULL, NULL, '不花钱。有人来说「借你身份证挂个股东」「股份先放你名下」，一律回绝。', '登记在册的股东，就是法律上的股东。你要按公司章程定的期限，把答应出的钱一分不少地交进去（足额缴纳认缴出资）。没按期交的，除了补交还要赔公司的损失。公司开办时有股东没把钱真交进来的，开办时的其他股东在这个缺口里跟着一起还（承担连带责任）。公司还不上到期的债时，债主可以要求还没到期限的那笔钱提前交。真正做生意的人不在登记上，债却记在你名下（全国，2024 年 7 月起）', '替人挂名的股东和真正出钱的人之间，代持协议没有无效情形的就算数。但真正出钱的人想把名字换上来，要其他股东半数以上同意。挂名的人把股权卖了或者押了，法院参照民法典的善意取得处理。买方不知情、价格合理、已经办了登记的，出钱的人拿不回股权，只能找挂名的人赔。这份司法解释 2025 年 9 月已出了新解释的征求意见稿，定稿施行后整份废止，以截至 2026 年 9 月仍有效的 2020 年修正本为准。挂名法定代表人的风险，见第 8 节第 28 条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-5', 'concept_archive_s12-5', 'claim_archive_s12-5', 'action', 'life_archive', '加盟前先查商务部备案，拿到书面披露，把「冷静期」写进合同', '12. 创业与做生意：别把家底赔进去', '按规定，品牌方自己得先开 2 个直营店、经营满 1 年，签约后 15 日内还要去商务部门备案。签约前，它必须把加盟费、保证金怎么退、现有门店赚不赚钱等 12 项写成书面材料给你。查不到备案、不肯给材料、要先交钱才让看合同的，直接走人。', '查不到备案、不肯给披露文件、要先交钱再看合同的，直接走。「冷静期」就是签约之后还能自己一方说退就退的那几天。天数由合同定，条例只说「一定期限」，所以签约时要求把天数写进去。品牌方披露的「现有加盟店平均销售量、毛利、纯利」，要追问数字是哪来的，办法要求品牌方说明来源。不叫加盟、只收「代运营」「开店培训」服务费的，见第 24 条（代运营和开店培训）。', NULL, NULL, NULL, '不花钱。上商务部的「商业特许经营信息管理系统」网站，查品牌方有没有备案。再要求对方在签约前，把该交代的事写成书面材料给你，连同合同文本一起。几个小时能做完。', '法规要求品牌方（法规里叫特许人）至少有 2 个自己开、自己经营的直营店，而且开满 1 年以上。从第一次签加盟合同那天算起，15 日内它要去商务主管部门备案。不备案的，罚 1 万到 5 万元。过了期限还不备案的，罚 5 万到 10 万元，并且对外公告。签约之前，它必须把该交代的事写成书面材料交给你，一共 12 项。里面包括加盟费收哪几种、各多少钱，保证金什么情况下退，现有多少家加盟店、生意做得怎么样。还有近 2 年查过账的审计报告摘要，近 5 年打过的官司和仲裁。合同里还必须写明，加盟商在签约后的一段时间内可以自己一方说退就退（单方解除）。品牌方瞒着不说，或者给的是假信息，加盟商可以解除合同（全国，2007 年 5 月起）', '查不到备案、不肯给披露文件、要先交钱再看合同的，直接走。「冷静期」就是签约之后还能自己一方说退就退的那几天。天数由合同定，条例只说「一定期限」，所以签约时要求把天数写进去。品牌方披露的「现有加盟店平均销售量、毛利、纯利」，要追问数字是哪来的，办法要求品牌方说明来源。不叫加盟、只收「代运营」「开店培训」服务费的，见第 24 条（代运营和开店培训）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-6', 'concept_archive_s12-6', 'claim_archive_s12-6', 'action', 'life_archive', '注册前把名称、经营场所、经营范围和注册资本定下来，材料齐了当场就能领执照', '12. 创业与做生意：别把家底赔进去', '登记本身不花钱，注册费 2015 年起就停征了。要交的材料只有五项：申请书、身份或资格证明、经营场所文件、章程或合伙协议（个体户不用交），加上法规另外点名要的。材料齐了当场发执照，当场发不了的 3 个工作日内办完。被收的那笔钱多半是代办跑腿费。', '登记本身不收费，被收的那笔多半是代办的跑腿费。刻章的价格由市场定。国务院办公厅明令「严禁指定公章制作单位制作公章」，所以有人说「必须去指定的地方刻章」，你不必接受。注册资本填多少不影响门面，只决定你的责任上限，而且 5 年内要缴足，见本节第 3 条（开张前选对主体）。经营范围里带许可项目的，证没下来不能开张，见本节第 7 条（要许可证的行当）', NULL, NULL, NULL, '登记这一步不花钱。企业和个体工商户的注册登记费，从 2015 年 1 月 1 日起就停收了。自己在当地政务服务网上办，或者去政务大厅办，一次几个小时。刻公章、请人代记账、租一个注册地址（地址托管），是在市场上买服务，不是政府收的费。', '条例把要交的材料写死为五项。「（一）申请书」。「（二）申请人资格文件、自然人身份证明」。「（三）住所或者主要经营场所相关文件」。「（四）公司、非公司企业法人、农民专业合作社（联合社）章程或者合伙企业合伙协议」。「（五）法律、行政法规和国务院市场监督管理部门规定提交的其他材料」。翻成大白话：一份申请书；一份证明你是谁、或者你有资格办这件事的材料；一份能证明店面或者办公地归你用的材料；公司章程或者合伙协议；再加上法规另外点名要的。公司还要交法定代表人、董事、监事和高管的任职文件和身份证明。个体户不用交章程。名字「由申请人依法自主申报」，自己起、自己报。注册资本「实行认缴登记制」，先写上答应出多少，不用当场掏出来。经营范围从登记机关公布的分类里挑。材料齐全、格式也对的，「予以确认并当场登记」。当场办不完的，「3 个工作日内」办完，情况复杂的再多给 3 个工作日。「营业执照签发日期为市场主体的成立日期」：执照上印的那天，就是公司或者店铺成立的日子（全国，2022 年 3 月起）', '登记本身不收费，被收的那笔多半是代办的跑腿费。刻章的价格由市场定。国务院办公厅明令「严禁指定公章制作单位制作公章」，所以有人说「必须去指定的地方刻章」，你不必接受。注册资本填多少不影响门面，只决定你的责任上限，而且 5 年内要缴足，见本节第 3 条（开张前选对主体）。经营范围里带许可项目的，证没下来不能开张，见本节第 7 条（要许可证的行当）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-7', 'concept_archive_s12-7', 'claim_archive_s12-7', 'action', 'life_archive', '要许可证的行当，证没下来不开张', '12. 创业与做生意：别把家底赔进去', '没证就开张，轻的是勒令停业、把挣到的钱收走，再罚 1 万元以下。要是做的是专营专卖的东西，或者证券、期货、保险、资金支付结算这几类，情节严重就构成非法经营罪，判 5 年以下起步。先装修后办证、证下来之前先试营业，是最常踩的一脚。', '金融、医疗、教培这几类的许可条件，各有专门的法律，本条只核实了通用的查处规则和刑法条款。奶茶店、小吃店属于餐饮服务，要办食品经营许可。先装修后办证、证下来之前先试营业，是常见的踩坑点。食品这一行分哪几档、卖生鲜肉菜要不要证，见第 8 条（做食品先看自己落在哪一档）。', NULL, NULL, NULL, '不花钱。开张前先查清楚，自己要做的这门生意要不要办许可证。做餐饮、卖食品要办食品经营许可。只卖别人做好的整包装食品，不用许可，改成备案。证下来了再开门营业。', '没拿到许可就开门做生意的，由法律法规指定的那个部门来查处。没有执照就经营、法律又没写明怎么罚的，勒令停下来，把挣到的钱（违法所得）收走，再罚 1 万元以下。还有更重的一档。法律法规规定的专营、专卖或者限制买卖的物品，没经许可就去经营。证券、期货、保险、资金支付结算这几类生意，没经批准就去做。这两种情形，情节严重的构成非法经营罪。判 5 年以下有期徒刑或者拘役（短期关押），同时按挣到的钱的 1 到 5 倍罚钱。情节特别严重的判 5 年以上（全国）', '金融、医疗、教培这几类的许可条件，各有专门的法律，本条只核实了通用的查处规则和刑法条款。奶茶店、小吃店属于餐饮服务，要办食品经营许可。先装修后办证、证下来之前先试营业，是常见的踩坑点。食品这一行分哪几档、卖生鲜肉菜要不要证，见第 8 条（做食品先看自己落在哪一档）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-8', 'concept_archive_s12-8', 'claim_archive_s12-8', 'action', 'life_archive', '做食品先看自己落在哪一档：生产和做餐饮要许可，只卖预包装的改备案，卖生鲜肉菜不用证', '12. 创业与做生意：别把家底赔进去', '自己做东西去卖，像小吃店、卤味、烘焙、自制酱菜，都要办许可。只卖别人做好的整包装食品不用许可，到县级以上市场监管部门备案就行。卖生鲜肉、蔬菜这类不用证。没证就干，最低也罚 5 万到 10 万，比多数小本生意的本钱还高。', '小作坊、小餐饮、食品摊贩的门槛是各省定的，本条不写具体数字。去你所在省的市场监管局官网，搜「食品小作坊小餐饮小摊贩管理条例」，看当地的版本。在网上卖自制食品，不会因为「在网上」就少一张证，该许可的照样要许可。许可之外还有这一节的通用规则：主体和执照见第 6 条（注册前把名称、场所、经营范围定下来），别的行当要不要证见第 7 条（要许可证的行当）。买家能要多少赔偿见第 5 节第 31 条（食品的十倍赔偿）。', NULL, NULL, NULL, '许可证本身不收费。但场地和设施要达标，现场核查加上办证要几个星期。卖肉的还要每批留好检疫证明和肉品品质检验合格证。', '食品安全法：做食品生意要先拿许可。自己生产食品、卖食品、做餐饮，都要依法拿到许可。「但是，销售食用农产品和仅销售预包装食品的，不需要取得许可。仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案」。食用农产品就是生鲜肉、蔬菜这类没加工过的。预包装食品就是别人做好、连包装一起卖的。「食品生产加工小作坊和食品摊贩等的具体管理办法由省、自治区、直辖市制定」，这两类由各省自己出规矩。没拿到许可就做食品生意的，挣到的钱、食品以及工具设备原料全部没收。这批货按售价算的总金额（货值金额）不足一万元的，另罚 5 万元以上 10 万元以下。货值金额一万元以上的，按货值的 10 倍以上 20 倍以下罚。生猪屠宰管理条例：猪只能在国家指定的屠宰厂宰，由官方集中检疫。「除农村地区个人自宰自食的不实行定点屠宰外，任何单位和个人未经定点不得从事生猪屠宰活动」。「从事生猪产品销售、肉食品生产加工的单位和个人以及餐饮服务经营者、集中用餐单位生产经营的生猪产品，必须是生猪定点屠宰厂（场）经检疫和肉品品质检验合格的生猪产品」。所以你卖的、用的猪肉都得来自指定屠宰厂，检疫和肉品品质检验这两道都得过。没在指定屠宰厂私自宰猪的，勒令关停，猪、屠宰的工具设备和挣到的钱一起没收，罚多少和上面没证做食品那一档一样。动物防疫法：卖的和运的动物产品，要随货带着检疫证明和检疫标志。没带的勒令改正，再按同类合格货的货值金额罚一倍以下。司法解释：小作坊和食品摊贩做的、卖的食品不符合食品安全标准的，买家要求按十倍赔（惩罚性赔偿，就是退钱之外再多赔的那笔），法院应当支持（全国）', '小作坊、小餐饮、食品摊贩的门槛是各省定的，本条不写具体数字。去你所在省的市场监管局官网，搜「食品小作坊小餐饮小摊贩管理条例」，看当地的版本。在网上卖自制食品，不会因为「在网上」就少一张证，该许可的照样要许可。许可之外还有这一节的通用规则：主体和执照见第 6 条（注册前把名称、场所、经营范围定下来），别的行当要不要证见第 7 条（要许可证的行当）。买家能要多少赔偿见第 5 节第 31 条（食品的十倍赔偿）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-9', 'concept_archive_s12-9', 'claim_archive_s12-9', 'action', 'life_archive', '装袋卖就是预包装食品：标签上生产日期、保质期、配料表一样都不能少', '12. 创业与做生意：别把家底赔进去', '食品装进包装再卖，法律上就叫预包装食品，包装上必须有标签，而且有九项必须标，生产日期和保质期都在里面。散装食品也要标名称、日期和卖家的名称地址。该标的没标，货值不到一万罚 5000 到 5 万，够一万按货值罚 5 到 10 倍。', '标签的毛病分两种，罚多少、赔多少都跟着这个分法走。一种是小毛病，比如错别字、字号不规范，既不影响食品安全，也不会让人误解。这种市场监管部门只让你改，拒不改才罚 2000 元以下，买家也要不到十倍赔偿。另一种是该标的没标，比如漏了生产日期、保质期。司法解释明文说这不算小毛病：罚款按货值算，不足一万元的罚 5000 元到 5 万元，一万元以上的罚货值的 5 到 10 倍。而且买家还能另外向你要食品价款的十倍赔偿，不足一千元的按一千元算（见第 5 节第 31 条，食品的十倍赔偿）。GB 7718-2025 的逐条要求，本条只核到了公告和官方解读给出的日期与展示方式，具体格式以标准原文为准。', NULL, NULL, NULL, '印标签几分钱到几毛钱一张。每一批都要把日期和配料填对，要占一些时间。', '食品安全法：预包装食品（装进包装再卖的食品）包装上必须有标签。标签要标明名称、规格、净含量、生产日期，成分或者配料表，生产者的名称、地址、联系方式，保质期。还有产品标准代号、贮存条件、所用食品添加剂在国家标准里的通用名称、生产许可证编号。法律法规或者食品安全标准另外要求标的，也要标。散装食品是不装袋、按需称的那种。卖散装食品，容器和外包装上也要标：食品的名称，生产日期或者生产批号，保质期，生产经营者的名称、地址、联系方式等内容。做的、卖的预包装食品没标签，或者标签、说明书不符合本法规定的，挣到的钱和食品一起没收。这批货按售价算的总金额（货值金额）不足一万元的，另罚 5000 元以上 5 万元以下。货值金额一万元以上的，按货值的 5 倍以上 10 倍以下罚。情节严重的勒令停产停业，直到把许可证收回。标签、说明书只是有小毛病（瑕疵），既不影响食品安全也不会让消费者误解的，先勒令改正，拒不改才罚 2000 元以下。新版《预包装食品标签通则》编号 GB 7718-2025，2025 年 3 月 16 日发布，2027 年 3 月 16 日起实施，中间有两年过渡期。它要求在包装上设置独立区域，同时展示生产日期和保质期到期日。日期要用高对比度、容易看清的字体和颜色，并且按年-月-日的顺序排列（全国）', '标签的毛病分两种，罚多少、赔多少都跟着这个分法走。一种是小毛病，比如错别字、字号不规范，既不影响食品安全，也不会让人误解。这种市场监管部门只让你改，拒不改才罚 2000 元以下，买家也要不到十倍赔偿。另一种是该标的没标，比如漏了生产日期、保质期。司法解释明文说这不算小毛病：罚款按货值算，不足一万元的罚 5000 元到 5 万元，一万元以上的罚货值的 5 到 10 倍。而且买家还能另外向你要食品价款的十倍赔偿，不足一千元的按一千元算（见第 5 节第 31 条，食品的十倍赔偿）。GB 7718-2025 的逐条要求，本条只核到了公告和官方解读给出的日期与展示方式，具体格式以标准原文为准。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-10', 'concept_archive_s12-10', 'claim_archive_s12-10', 'action', 'life_archive', '普通食品不许说能治病：标签、说明书、广告和直播话术都算', '12. 创业与做生意：别把家底赔进去', '普通食品的标签、说明书和广告里，都不能说自己能防病治病。除了医疗、药品、医疗器械这三类广告，别的广告都不许说能治病，也不许用听着像药的词。罚的是广告费的 1 到 3 倍。算不出广告费的，罚 10 万到 20 万。情节严重的还能吊销营业执照。', '「保健功能」也不是普通食品能说的。保健食品能声称的保健功能，只能从国家定的目录里来，产品还要经过注册或者备案，普通食品没有这道程序。买家怎么识别这类话术，见第 6 节第 10 条（不要花大钱买保健品调理身体）。除了包装和广告，详情页、直播话术、朋友圈文案同样算广告内容，发出去就留下了痕迹。', NULL, NULL, NULL, '不花钱。把宣传语、商品详情页和直播的话术过一遍。难的是忍住不说「降三高」「治便秘」这类话。', '食品安全法：「食品和食品添加剂的标签、说明书，不得含有虚假内容，不得涉及疾病预防、治疗功能。生产经营者对其提供的标签、说明书的内容负责」。「食品广告的内容应当真实合法，不得含有虚假内容，不得涉及疾病预防、治疗功能。食品生产经营者对食品广告内容的真实性、合法性负责」。意思是包装、说明书和广告里都不能说自己能防病治病，写了什么由卖家自己担责。在广告里对食品吹牛、骗消费者的，按广告法罚。广告法也有一条禁令。「除医疗、药品、医疗器械广告外，禁止其他任何广告涉及疾病治疗功能，并不得使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语」。除了医疗、药品、医疗器械这三类广告，其他广告一律不许说能治病，也不许用听着像药、像医疗器械的词。违反这一条的，勒令停掉广告。还要让出广告的那一方（广告主）在发过的范围里公开澄清、消除影响。再按广告费用的 1 倍以上 3 倍以下罚钱。广告费用算不出来，或者报得明显偏低的，罚 10 万元以上 20 万元以下。情节严重的，按广告费用的 3 倍以上 5 倍以下罚，或者罚 20 万元以上 100 万元以下，还可以把营业执照吊销、生意直接做不成（全国）', '「保健功能」也不是普通食品能说的。保健食品能声称的保健功能，只能从国家定的目录里来，产品还要经过注册或者备案，普通食品没有这道程序。买家怎么识别这类话术，见第 6 节第 10 条（不要花大钱买保健品调理身体）。除了包装和广告，详情页、直播话术、朋友圈文案同样算广告内容，发出去就留下了痕迹。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-11', 'concept_archive_s12-11', 'claim_archive_s12-11', 'action', 'life_archive', '食品这一行有刑事线：卖病死肉、超标货就够罪，掺了有毒有害的不看金额、起刑五年', '12. 创业与做生意：别把家底赔进去', '前面几条罚的是钱，这条抓的是人。卖病死肉、检验不合格的肉，或者农残兽残重金属严重超标的东西，只要「足以」让人吃出严重中毒就够罪，不用真有人吃坏，判 3 年以下。往食品里掺有毒有害的非食品原料，起步就是 5 年以下，不看你卖了多少钱。', '和前面三条的分界线是：有没有踩到食品安全本身。没办证、标签漏项、吹疗效，罚的是钱。卖病死肉、超标货、乱加添加剂、掺非食品原料，进的是刑事程序。最省事的防线还是第 8 条（做食品先看自己落在哪一档）里那套动作。肉只从定点屠宰厂进。每批留好检疫证明和肉品品质检验合格证。配料只用查得到批准文号的。所谓「便宜处理的肉」「不知道哪来的边角料」，最常出事。原始来源最高人民法院公报的页面本轮返回 502，所以引了两份省级官方转载，并且互相逐字核对过。', NULL, NULL, NULL, '不花钱。按第 8 条（做食品先看自己落在哪一档）那套做：留好检疫证明和进货凭证，配料表里只放查得到批准文号的东西。', '刑法第一百四十三条管的是这一档。你做的、卖的食品不符合食品安全标准。只要「足以造成严重食物中毒事故或者其他严重食源性疾病的」，就够罪。判 3 年以下有期徒刑或者拘役（短期关押），同时罚钱。把人的健康搞出严重损害，或者有其他严重情节的，判 3 年以上 7 年以下并罚钱。后果特别严重的，判 7 年以上有期徒刑直到无期，罚钱或者把名下财产全部没收。第一百四十四条：在做的、卖的食品里掺进有毒有害的非食品原料，或者明知掺了还卖的，判 5 年以下有期徒刑并罚钱。把人的健康搞出严重损害，或者有其他严重情节的，判 5 年以上 10 年以下并罚钱。把人吃死了，或者有其他特别严重情节的，按第一百四十一条处罚（10 年以上、无期或者死刑）。最高人民法院和最高人民检察院出过一份解释（两高解释）。它列明了哪几种情形算「足以造成严重食物中毒事故或者其他严重食源性疾病」。一是「含有严重超出标准限量的致病性微生物、农药残留、兽药残留、生物毒素、重金属等污染物质」。二是「属于病死、死因不明或者检验检疫不合格的畜、禽、兽、水产动物肉类及其制品的」。三是「属于国家为防控疾病等特殊需要明令禁止生产、销售的」。四是「特殊医学用途配方食品、专供婴幼儿的主辅食品营养成分严重不符合食品安全标准的」。添加剂用超量、用错地方，到了会造成上述后果的程度，同样按第一百四十三条定罪。什么算「有毒、有害的非食品原料」，不由你说了算。一类是法律法规禁止往食品里加的物质。另一类是国务院有关部门公告的名单上的物质，比如禁用农药、禁止用在食用动物身上的药。还有一种情形也算第一百四十四条里的「其他严重情节」。做了、卖了 10 万元以上不满 20 万元。地点在中小学校园、托幼机构、养老机构及周边。卖的对象是未成年人、老年人。不在指定屠宰厂、自己私设猪的屠宰场干屠宰和销售，情节严重的按非法经营罪判。做到 10 万元以上，或者挣到 5 万元以上，就算「情节严重」（全国）', '和前面三条的分界线是：有没有踩到食品安全本身。没办证、标签漏项、吹疗效，罚的是钱。卖病死肉、超标货、乱加添加剂、掺非食品原料，进的是刑事程序。最省事的防线还是第 8 条（做食品先看自己落在哪一档）里那套动作。肉只从定点屠宰厂进。每批留好检疫证明和肉品品质检验合格证。配料只用查得到批准文号的。所谓「便宜处理的肉」「不知道哪来的边角料」，最常出事。原始来源最高人民法院公报的页面本轮返回 502，所以引了两份省级官方转载，并且互相逐字核对过。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-12', 'concept_archive_s12-12', 'claim_archive_s12-12', 'action', 'life_archive', '领了执照就开始有申报义务，没有收入也要按期零申报（照报一张全是零的表）', '12. 创业与做生意：别把家底赔进去', '领了执照就要按期报税。一分钱没赚也要报，只是表上数字全填零。不报先罚 2000 元以下，情节严重的罚 2000 到 1 万。连着三个月所有税种都不报，系统会自动把你列为非正常户，发票就开不了了。', '「多证合一」之后不用单独办税务登记。拿营业执照上的统一社会信用代码登录电子税务局，确认登记信息，报上自己要交哪些税。个体工商户和个人独资企业交的是经营所得个税。先「在月度或者季度终了后十五日内」交一笔，再「在取得所得的次年三月三十一日前办理汇算清缴」（全年算总账，多退少补）。没开张也要报，零申报同样是申报。放着不管三个月就成了非正常户，发票停用，想注销也走不了简易程序，见本节第 23 条（亏了就按程序退场）', NULL, NULL, NULL, '不花钱。自己在电子税务局按月或者按季申报，一次几分钟。请人代记账是另一笔市场上的开支。用了人的，还要从成立那天算起 30 日内办社保登记。难的是没生意的月份也得记着按时报。', '「纳税人在纳税期内没有应纳税款的，也应当按照规定办理纳税申报」：这一期一分税都不用交，表照样要报。不按期报的，「由税务机关责令限期改正，可以处二千元以下的罚款；情节严重的，可以处二千元以上一万元以下的罚款」。不报又少缴了税的，税要追回来，还要把按天加收的滞纳金一起补上，另罚少缴那笔税的「百分之五十以上五倍以下的罚款」。滞纳金按每天万分之五加。「连续三个月所有税种均未进行纳税申报的，税收征管系统自动将其认定为非正常户，并停止其发票领用簿和发票的使用」。三个月什么都不报，系统就自己把你列为非正常户，发票领不了也开不了。补报并且接受处罚之后，自动解除。用了人的单位「应当自成立之日起三十日内……向当地社会保险经办机构申请办理社会保险登记」（全国）', '「多证合一」之后不用单独办税务登记。拿营业执照上的统一社会信用代码登录电子税务局，确认登记信息，报上自己要交哪些税。个体工商户和个人独资企业交的是经营所得个税。先「在月度或者季度终了后十五日内」交一笔，再「在取得所得的次年三月三十一日前办理汇算清缴」（全年算总账，多退少补）。没开张也要报，零申报同样是申报。放着不管三个月就成了非正常户，发票停用，想注销也走不了简易程序，见本节第 23 条（亏了就按程序退场）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-13', 'concept_archive_s12-13', 'claim_archive_s12-13', 'action', 'life_archive', '发票只按真实交易开，小规模纳税人用足免税额', '12. 创业与做生意：别把家底赔进去', '你要是按简易办法交税的小规模纳税人，一个月卖不到 10 万、一个季度卖不到 30 万，增值税就免了。本来按 3% 交的，同期也减到按 1% 交。反过来，「找人开票抵成本」就是虚开，起步判 3 年以下，还要罚 2 万到 20 万。', '增值税法从 2026 年 1 月 1 日起施行。原来的两份小规模纳税人减免公告，2023 年第 19 号和 2023 年第 1 号，跟着停止执行或者废止。金额门槛没变，但依据换了，本条已经按新文件更新。刑法原文页是 1997 年版，第二百零五条后来经修正案调过判几年的档次，本条只写核实到、而且没被改动过的那几档。免的是增值税，所得税另算。「找人开票抵成本」就是虚开，不是节税。', NULL, NULL, NULL, '不花钱。不买发票，不卖发票，也不替别人「走账开票」。按真实发生的生意开票、报税。', '规模小、按简易办法交税的那一档叫小规模纳税人。法律写的是「销售额未达到起征点的，免征增值税」。这条线叫起征点。从 2026 年 1 月 1 日到 2027 年 12 月 31 日，起征点是按月算 10 万元，按季度算 30 万元，按次或者按天算 1000 元，卖不到这条线就不用交。同一段时间里，本来按 3% 交的减到按 1% 交，卖房租房和转让土地使用权除外。反过来说，开了没有真实买卖的增值税专用发票，或者其他能拿去抵税的发票，判 3 年以下有期徒刑或者拘役，并罚 2 万到 20 万元。给别人开、给自己开、让别人给自己开、介绍别人开，都算。涉及税额较大的判 3 到 10 年。数额巨大的判 10 年以上或者无期（全国）', '增值税法从 2026 年 1 月 1 日起施行。原来的两份小规模纳税人减免公告，2023 年第 19 号和 2023 年第 1 号，跟着停止执行或者废止。金额门槛没变，但依据换了，本条已经按新文件更新。刑法原文页是 1997 年版，第二百零五条后来经修正案调过判几年的档次，本条只写核实到、而且没被改动过的那几档。免的是增值税，所得税另算。「找人开票抵成本」就是虚开，不是节税。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-14', 'concept_archive_s12-14', 'claim_archive_s12-14', 'action', 'life_archive', '自称税务局催你交钱报税的都是骗子，办税只走电子税务局和 12366', '12. 创业与做生意：别把家底赔进去', '税务部门不会打电话要你的银行卡密码、支付密码或者短信验证码，也不会给你一个账号让你把税打过去。真上门查账的，要出示检查通知书和检查证。接到这类电话先挂断，再打 12366 核实。已经转了钱，立刻打 110 或者 96110 止付。', '这类骗局专挑刚注册的个体户和小公司。话术是「系统显示你没报税，今天不处理就罚款」，然后把你引到他们自己的公众号或者小程序，一次收几百元。而那笔申报本来免费，自己几分钟就能做完。找市场上的机构代记账不违法，但它不是政府部门，也不会用税务局的名义催你。已经付钱或者转了账的，按第 8 节第 2 条（被骗止付）立刻打 110 或 96110 要求止付', NULL, NULL, NULL, '不花钱。接到「税务抽查」「账户异常」「不报税就罚款」的电话、短信，或者有人加你好友，先挂断、不回。再打 12366，或者打主管税务机关的固定电话核实。', '税务总局的提示原文：「税务部门不会通过微信小程序、电话、短信等方式索要银行卡密码、支付密码、账户余额及与银行卡收付款项相关的短信验证码」。「一些不法分子冒充税务干部以提供『帮办纳税申报』『税收优惠代办』『政策辅导』等为名接触纳税人」。要核实就打「12366 纳税缴费服务热线或主管税务机关固定电话」。真上门查账（稽查）的，「必须出示检查通知书和检查证」。「税款只能通过电子税务局或者在办税大厅缴纳，税务部门不会提供指定账号」。替人办税的中介机构也有一条。「以税务机关和税务人员的名义敲诈纳税人、扣缴义务人的」，按情节轻重罚款。打着税务局和税务干部的旗号，敲诈交税的人和代扣代缴税款的单位，就是这种情形。冒充国家机关工作人员招摇撞骗的，拘留 10 日以上 15 日以下，还可以再罚 1000 元以下。既够诈骗罪又够招摇撞骗罪的，「依照处罚较重的规定定罪处罚」（哪条罚得重按哪条判）（全国）', '这类骗局专挑刚注册的个体户和小公司。话术是「系统显示你没报税，今天不处理就罚款」，然后把你引到他们自己的公众号或者小程序，一次收几百元。而那笔申报本来免费，自己几分钟就能做完。找市场上的机构代记账不违法，但它不是政府部门，也不会用税务局的名义催你。已经付钱或者转了账的，按第 8 节第 2 条（被骗止付）立刻打 110 或 96110 要求止付', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-15', 'concept_archive_s12-15', 'claim_archive_s12-15', 'action', 'life_archive', '收钱写「定金」不写「订金」，违约金写明数，账期当放贷来审', '12. 创业与做生意：别把家底赔进去', '写「定金」这两个字才有双倍规则：你毁约，这笔钱要不回来；对方毁约，要退你双倍。超过合同金额 20% 的那部分不算。写成「订金」，法律上没有这套规则。给账期等于把自己的钱白借给对方，对方倒了就是坏账。', '「订金」在民法典里没有定金那套规则，一般只当预付款看待。这是实务里的通行说法，本节没有核实判例。账期就是把自己的钱无息借给对方，对方倒了就是坏账。给账期之前，先去国家企业信用信息公示系统查对方的记录，看它有没有被起诉过。', NULL, NULL, NULL, '不花钱。合同里写「定金」这两个字，金额不超过合同总金额的 20%。先收钱再发货。答应对方先拿货、后付款（给账期）之前，先把对方查一遍。', '定金要等钱真交到对方手上才算数（自实际交付时成立）。付定金的一方毁约，这笔钱要不回来。收定金的一方毁约，要原数退回，再赔上同样一份（双倍返还）。超过合同总金额（主合同标的额）20% 的那部分，不按定金算。约定的违约金比实际损失高得离谱或者低得离谱的，法院可以按一方的请求往下调或者往上调。违约金和定金都写进了合同的，真出了违约只能挑一样要，不能两样都拿（全国，2021 年起）', '「订金」在民法典里没有定金那套规则，一般只当预付款看待。这是实务里的通行说法，本节没有核实判例。账期就是把自己的钱无息借给对方，对方倒了就是坏账。给账期之前，先去国家企业信用信息公示系统查对方的记录，看它有没有被起诉过。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-16', 'concept_archive_s12-16', 'claim_archive_s12-16', 'action', 'life_archive', '用人第一个月内签书面合同，30 日内办社保登记', '12. 创业与做生意：别把家底赔进去', '人来上班满一个月还没签书面合同，从第二个月起，每个月要按双倍发工资，一直算到满一年。社保要在用工 30 天内登记，不办的罚该交社保费的 1 到 3 倍。法律上没有「员工自愿放弃社保」这一项。', '双倍工资从第二个月一直算到满一年，越拖越贵。没签合同、没缴社保的员工，一旦出了工伤，或者离职之后去仲裁，补缴加上罚款再加上赔偿，往往比省下的那点钱多得多。', NULL, NULL, NULL, '社保里由公司出的那一部分，要一直交下去，各地的比例不一样。签合同本身不花钱，直接用当地人社部门的合同范本就行。', '人来上班满一个月、不满一年还没签书面合同的，每个月要按双倍发工资。从人上班第一天算起，30 日内要给他办社保登记。不办的先勒令改正。过了期限的，按该交的社保费罚 1 到 3 倍，经办这件事的人另罚 500 到 3000 元。社保没按时交、没足额交的，从欠的那天起按每天万分之五加钱（滞纳金）。过了期限还不交的，再按欠款罚 1 到 3 倍。单位要自己申报，按时把钱交足。只有天灾这类没法抗的法定事由，才能晚交或者少交。没有「员工自愿放弃」这一项（全国）', '双倍工资从第二个月一直算到满一年，越拖越贵。没签合同、没缴社保的员工，一旦出了工伤，或者离职之后去仲裁，补缴加上罚款再加上赔偿，往往比省下的那点钱多得多。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 多","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-17', 'concept_archive_s12-17', 'claim_archive_s12-17', 'action', 'life_archive', '工资按合同和法律给，加薪、借款、奖金都走书面', '12. 创业与做生意：别把家底赔进去', '工资要按合同和法律按时足额发。欠了，员工可以直接找法院开支付令。加薪、奖金、垫付只是口头说说，真吵起来，拿不出证据的一方吃亏。自己掏钱借给员工，要写书面借条，写清数额、利息和什么时候还。', '不是不帮人，是帮人也要走制度。制度之外的恩惠一旦成了惯例，想停掉就会起纠纷。私人借款和公司账混在一起，公司亏了，坏账就落在你自己头上。法条部分已核实，建议本身是经验，故 C 级。', NULL, NULL, NULL, '不花钱。合同里把工资写清楚。加薪、奖金、垫付、借款，一律签字留一张纸。不口头承诺。也不从自己口袋里掏钱替公司发工资。难的是熟人开口时也照这个规矩办。', '劳动合同里必须写明的内容，就包括工资怎么给、社保怎么交。单位要按合同和国家规定，及时、足额发工资。拖着不发的，员工可以直接向法院申请支付令（法院开出的催款文书）。老板拿自己的钱借给员工，这就是一份借款合同。除了两个自然人之间另有约定的，都要写成书面的，写清借了多少、利息怎么算、什么时候还、怎么还。口头答应的奖金没有白纸黑字，真吵起来，拿不出证据的一方吃亏（全国）', '不是不帮人，是帮人也要走制度。制度之外的恩惠一旦成了惯例，想停掉就会起纠纷。私人借款和公司账混在一起，公司亏了，坏账就落在你自己头上。法条部分已核实，建议本身是经验，故 C 级。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-18', 'concept_archive_s12-18', 'claim_archive_s12-18', 'action', 'life_archive', '先卖再造：用预售和小订单验证有人买，再投钱生产', '12. 创业与做生意：别把家底赔进去', '有人跟踪了 116 家意大利新公司大约一年：先立一个假设、再拿市场反馈去验的创业者，生意做得更好，也更愿意及时换方向，而且并没有更早放弃。所以，没人肯预付、没人肯下小单，就别信「做出来自然有人买」。', '只有这一项研究，样本小，而且是在意大利做的，所以定 B 级。标题、出处和摘要经 Crossref 与 Semantic Scholar 核对过，全文里的效果数字本节没有核实。落到操作上：没人肯预付、没人肯下小单，就别相信「做出来就有人买」。', NULL, NULL, NULL, '几十到几百元，做个样品或者一个页面。再去找几十个真实客户，让他们预付或者下小单。这样比直接开工慢几个星期。难的是忍住不先把货做出来。', '一项随机对照试验，跟踪了 116 家意大利初创企业大约一年。随机对照试验就是把人随机分成两组，只给一组做培训，再比两组的结果。结果是：受过培训、按「先提假设、再用市场反馈严格检验」来做决定的创业者，业绩更好，也更可能及时掉头换别的方案，早期放弃的比例并不更高。作者的解释是，这种做法减少了往看着有戏、其实做不成的项目（假阳性项目）上继续砸钱的概率（意大利，2020 年发表）', '只有这一项研究，样本小，而且是在意大利做的，所以定 B 级。标题、出处和摘要经 Crossref 与 Semantic Scholar 核对过，全文里的效果数字本节没有核实。落到操作上：没人肯预付、没人肯下小单，就别相信「做出来就有人买」。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-19', 'concept_archive_s12-19', 'claim_archive_s12-19', 'action', 'life_archive', '样品做出来先过一遍量产清单，再谈开工', '12. 创业与做生意：别把家底赔进去', '一件样品和一千件的差别，在于钱压在哪里。良率决定真实成本。起订量和账期决定你要先垫多少钱。库存决定钱什么时候能回来。产品要是在强制性认证目录里，没认证、没标认证标志就不能出厂和销售。', '清单本身是经验方法，法条部分已核实原文。投产之前，先到国家知识产权局的商标查询系统查一下有没有近似的注册，再去申请自己的商标。用别人的商标和图案的红线，见第 20、21 条（进货留票据、图案要自己做或买授权）。强制认证目录以市场监管总局最新公布的为准。', NULL, NULL, NULL, '几百元做一次小批量试产。再花几个小时，把这几项算清楚：良率（100 件里有几件能卖）、供应商的起订量和账期、库存要占多少钱、包装和物流、认证和许可、商标。难的是忍住不跳过这一步直接开工。', '一件样品和一千件的差别，在于钱压在哪里。良率决定真实成本，良率就是做出来的一批里有几成合格能卖。供应商一次最少要你订多少（起订量），发货之后多久才收得到钱（账期），这两项决定你要先垫多少钱。库存决定钱什么时候回来。列入强制性产品认证目录的产品，必须先通过认证，并且在产品上标出认证标志，才能出厂和销售。没认证就擅自出厂销售的，按认证认可条例处罚。做餐饮和卖食品要办食品经营许可（全国）', '清单本身是经验方法，法条部分已核实原文。投产之前，先到国家知识产权局的商标查询系统查一下有没有近似的注册，再去申请自己的商标。用别人的商标和图案的红线，见第 20、21 条（进货留票据、图案要自己做或买授权）。强制认证目录以市场监管总局最新公布的为准。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","C 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-20', 'concept_archive_s12-20', 'claim_archive_s12-20', 'action', 'life_archive', '进货一批留一批票据和上家信息，进货价明显低于市场价的不进：员工进的假货，老板是被判的那个', '12. 创业与做生意：别把家底赔进去', '卖假货，挣到 3 万，或者卖到 5 万，就够判刑，判 3 年以下。货压在仓库没卖出去也算。「我不知道是假的」不由你说了算：进货价明显低于市场价又说不出理由，就会被认定你知情。留住采购合同、发票、付款记录和上家信息，才有免赔那条路。', '化妆品、酒水、母婴、数码、服装是这类案子的高发品类。共同点是同一款货有巨大的价差空间。「渠道货」「尾单」「海外免税」这些说法，都不能替代票据。判刑之外还有一道行政处罚：认定侵权成立的，侵权商品和工具要没收，违法经营额 5 万元以上的还可以并处 5 倍以下罚款。已经进了货才发现不对，立刻停售、封存，再联系品牌方或者市场监管部门。别继续卖，更别把货和账销毁。销毁证据正好落进上面「推定你明知是假货」的第五种情形。用别人的图案见第 21 条（图案要么自己做要么买授权）。有一种套路专门打这条：有人主动上门，说这批笔或者别的小商品白送给你，放店里卖了再分钱。过些天就有人来买走、当场取证，再按侵权来索赔。白给的货，免赔要的三个条件恰好全缺：没有采购合同和付款记录，说不出真实的提供者，价格明显不正常。「合法取得并说明提供者」一条都用不上。所以主动送货上门、不给票据、只留一个微信号的，一律不上架。真要做代销，就签书面的代销合同，留下对方的身份证和营业执照复印件，把货归谁、侵权了算谁的写进去。', NULL, NULL, NULL, '不花钱。每批货都留好这几样：采购合同、发票、付款记录、上家的营业执照和授权文件。再定一条内部规矩：谁进的货谁签字，价格明显低于市场价的一律不进。难的是放过那些看着很赚钱的低价货。', '明知是假冒注册商标的商品还卖，挣到的钱（违法所得）够 3 万元，或者卖出去的金额够 5 万元，就到了要判刑的门槛。判 3 年以下，同时罚钱，或者只罚钱。达到这个标准十倍的，判 3 到 10 年并罚钱。货还压在仓库没卖出去也算：货值到了销售金额标准三倍以上的，同样构成犯罪。「明知」不用你自己承认。最高人民法院和最高人民检察院 2025 年的司法解释，列了五种可以直接认定你知情的情形，你拿得出证据证明确实不知道的除外。一是知道商品上的注册商标被涂改、调换或者覆盖。二是伪造、涂改商标注册人授权文件，或者知道该文件被伪造、涂改。三是因销售假冒商品受过刑事或者行政处罚，又销售同一种的。四是无正当理由，以明显低于市场价格进货或者销售的。五是被行政执法机关、司法机关发现后，转移、销毁侵权商品和会计凭证等证据，或者提供虚假证明的。公司犯这一条的，「对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员」按同一条处罚。就是公司罚钱，拍板的负责人和经手的人按同一条判。所以货是员工进的，挨罚挨判的还是拍板的那个人。反过来，商标法留了一条出路：卖的时候确实不知道这货侵犯了别人的注册商标，「能证明该商品是自己合法取得并说明提供者的，不承担赔偿责任」。能不能免赔，全看有没有票据和上家信息，没留就用不上这一条（全国，司法解释 2025 年 4 月 26 日起施行）', '化妆品、酒水、母婴、数码、服装是这类案子的高发品类。共同点是同一款货有巨大的价差空间。「渠道货」「尾单」「海外免税」这些说法，都不能替代票据。判刑之外还有一道行政处罚：认定侵权成立的，侵权商品和工具要没收，违法经营额 5 万元以上的还可以并处 5 倍以下罚款。已经进了货才发现不对，立刻停售、封存，再联系品牌方或者市场监管部门。别继续卖，更别把货和账销毁。销毁证据正好落进上面「推定你明知是假货」的第五种情形。用别人的图案见第 21 条（图案要么自己做要么买授权）。有一种套路专门打这条：有人主动上门，说这批笔或者别的小商品白送给你，放店里卖了再分钱。过些天就有人来买走、当场取证，再按侵权来索赔。白给的货，免赔要的三个条件恰好全缺：没有采购合同和付款记录，说不出真实的提供者，价格明显不正常。「合法取得并说明提供者」一条都用不上。所以主动送货上门、不给票据、只留一个微信号的，一律不上架。真要做代销，就签书面的代销合同，留下对方的身份证和营业执照复印件，把货归谁、侵权了算谁的写进去。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-21', 'concept_archive_s12-21', 'claim_archive_s12-21', 'action', 'life_archive', '商品、包装、吊牌和宣传图上的图案要么自己做要么买授权，改个颜色、加个图标不算「改过了」', '12. 创业与做生意：别把家底赔进去', '在别人的图上改个颜色、换个底色、加个自己的图标，还是没经许可用别人的作品。为赚钱复制别人的美术作品，挣到 3 万、做到 5 万，或者印够 500 张，就构成侵犯著作权罪，判 3 年以下。商标那边，「像到容易混淆」本身就算侵权。', '常踩的有三处。一是把网上搜来的卡通形象和明星图，印在衣服、杯子、手机壳上。二是字体：商用字体多数要单独授权，免费预览不等于免费商用。三是给客户做的设计稿里夹了没授权的素材，责任仍然在卖货的人身上。要省事，就用有商用授权的图库，并且把授权页存下来。或者让设计方在合同里写清素材从哪儿来、授权到什么范围，出了事由设计方负责。判刑之外还有民事赔偿和行政罚款：损害公共利益的，可以没收违法所得，并按违法经营额的 1 到 5 倍罚款。投产前查商标见第 19 条（样品先过一遍量产清单）。反过来，自己的图被别人用了，也按这套规则维权。把别人的漫画、影视剧传到网上，挂广告、收会员费的刑事线，见第 9 节第 24 条（汉化漫画、搬运影视剧）。', NULL, NULL, NULL, '正版图库的授权从几十元一张起。找人原创设计，几百到几千元。每一张用在商品上的图，都留一份授权凭证和购买记录。难的是不去用网上随手搜来的图。', '著作权法把「未经著作权人许可，以改编、翻译、注释等方式使用作品」和直接复制并列为侵权行为。所以在原图上改颜色、换底色、加个自己的图标，仍然是未经许可使用别人的作品。要判刑的门槛在这里：为了赚钱，没经作品的版权人（著作权人）许可，就把美术作品印出来卖（复制发行）。够上罪的是三个数。挣到的钱（违法所得）够 3 万元。或者这门买卖做到 5 万元（非法经营数额）。或者印出来的件数加起来够 500 份（张）。到了其中任何一个数，就构成侵犯著作权罪。判 3 年以下，同时罚钱，或者只罚钱。达到十倍标准的判 3 到 10 年。只是卖别人印的侵权货，挣到 5 万元以上，或者卖出去 10 万元以上，按销售侵权复制品罪判 5 年以下。商标也一样：在同一种商品上使用与注册商标近似的商标，或者在类似商品上使用相同或者近似的商标，「容易导致混淆的」本身就在侵权范围内。「近似」是法条明写的侵权情形，稍微改一改仍然算侵权（全国，司法解释 2025 年 4 月 26 日起施行）', '常踩的有三处。一是把网上搜来的卡通形象和明星图，印在衣服、杯子、手机壳上。二是字体：商用字体多数要单独授权，免费预览不等于免费商用。三是给客户做的设计稿里夹了没授权的素材，责任仍然在卖货的人身上。要省事，就用有商用授权的图库，并且把授权页存下来。或者让设计方在合同里写清素材从哪儿来、授权到什么范围，出了事由设计方负责。判刑之外还有民事赔偿和行政罚款：损害公共利益的，可以没收违法所得，并按违法经营额的 1 到 5 倍罚款。投产前查商标见第 19 条（样品先过一遍量产清单）。反过来，自己的图被别人用了，也按这套规则维权。把别人的漫画、影视剧传到网上，挂广告、收会员费的刑事线，见第 9 节第 24 条（汉化漫画、搬运影视剧）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 自由","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-22', 'concept_archive_s12-22', 'claim_archive_s12-22', 'action', 'life_archive', '在岗位上按规程办事，规程之外的好意先想清楚责任归谁', '12. 创业与做生意：别把家底赔进去', '以护士为例：条例写明，发现病人病情危急，要立即通知医师；发现医嘱违反规定，要向开医嘱的医师提出。别的岗位也一样，先看清自己这份规程把「必须上报」划在哪儿。法律也没让人见死不救：自愿出手紧急救助，把人弄伤了，不用赔钱。', '岗位之内按规程办，紧急救人受法律保护。其余的事，先分清是谁的权限、谁的责任，别用私人的好意代替制度上的决定。护士条例 2020 年经国务院令第 726 号修订，只改了注册那几条，第十七条一字未动。医师法里关于按诊疗规范执业的条款，本次未能打开官方原文，所以没有引用。', NULL, NULL, NULL, '不花钱。上班做事按制度、按医嘱、按流程走。不在自己的权限之外替人做决定。想帮忙之前，先问自己一句：出了事谁负责。难的是当场顶住「通融一下」的请求。', '以护士为例，法规写明的职务边界是这样的。发现病情危急，立即通知医师。紧急情况下为抢救垂危患者，可以先行实施必要的紧急救护。发现医嘱违法违规，或者违反诊疗技术规范的，要向医师提出，必要时向科室负责人报告。民法典另有规定：自愿出手做紧急救助，结果把被救的人弄伤了的，救人的一方不用赔钱（不承担民事责任）（全国）', '岗位之内按规程办，紧急救人受法律保护。其余的事，先分清是谁的权限、谁的责任，别用私人的好意代替制度上的决定。护士条例 2020 年经国务院令第 726 号修订，只改了注册那几条，第十七条一字未动。医师法里关于按诊疗规范执业的条款，本次未能打开官方原文，所以没有引用。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-23', 'concept_archive_s12-23', 'claim_archive_s12-23', 'action', 'life_archive', '亏了就按程序退场：能简易注销就注销，资不抵债走破产，别放着不管', '12. 创业与做生意：别把家底赔进去', '没欠债、不欠工资税款社保的，全体投资人写份承诺，公示 20 天没人提异议就能简易注销。个体户不用公示，10 天没异议直接注销。还不上债就申请破产。放着不管、2 年不报年报又联系不上的，吊销执照，负有责任的法定代表人 3 年内不能再当法定代表人。', '企业信息公示暂行条例 2024 年经国务院令第 777 号修订，5 月 1 日起施行，此后没有再改。旧版第十七条「经营异常满 3 年列入严重违法企业名单」已经删掉。现在的严重违法失信名单管的是年报弄虚作假、情节严重的企业。网上很多说法还是旧版，别照抄。个人破产制度（个体户也算在内）目前只有个别地区在试点，本节没有核实原文，所以不写。', NULL, NULL, NULL, '简易注销自己就能办：在国家企业信用信息公示系统上挂出来 20 日。还有债没还完的，要先把账理清，该收的收回来，该还的还掉，这一步叫清算。走破产要向法院申请，耗时几个月。难的是亏了之后不想面对，一直拖着不办。', '欠别人的和别人欠你的都没有，或者都已经还清。不欠工资、不欠社保、不欠税。全体投资人写了书面承诺。满足这几条，挂出来公示 20 日没人提异议，就能走简易注销。个体户不用公示，有关部门 10 日内没有异议就直接注销。公司还不上到期的债、欠的又比手上有的多（资不抵债）的，可以向法院申请重整、和解或者破产清算。已经解散又没清算、欠的比有的多的，该负责清算的人应当去申请破产清算。放着不管的后果是这样的：不按期公示年报，会被列进经营异常名录。连续 2 年不报年报、被列进经营异常名录还不改，按登记的地址又联系不上的，吊销营业执照。担任被吊销执照企业的法定代表人、对此负有个人责任的，从吊销那天算起 3 年内不得再当公司的法定代表人和董事、监事、高管。已经列进经营异常名录的，连简易注销都走不了（全国）', '企业信息公示暂行条例 2024 年经国务院令第 777 号修订，5 月 1 日起施行，此后没有再改。旧版第十七条「经营异常满 3 年列入严重违法企业名单」已经删掉。现在的严重违法失信名单管的是年报弄虚作假、情节严重的企业。网上很多说法还是旧版，别照抄。个人破产制度（个体户也算在内）目前只有个别地区在试点，本节没有核实原文，所以不写。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s12-24', 'concept_archive_s12-24', 'claim_archive_s12-24', 'action', 'life_archive', '花钱请人代运营网店、上开店培训、做「无货源」之前，先问清后面还要不要加钱、销量从哪来', '12. 创业与做生意：别把家底赔进去', '这类骗局先收一笔小钱，再拿「升级套餐」、垫付货款、解冻金让你一次次加钱。后台的订单和收益可能是做出来的，想提现时就提不出来。靠刷单冲销量本身就违法，被查到的代运营要挨罚。', '看到「零基础」「无需囤货」「低投入，高回报」「保证盈利」，就先停下。让你往它指定的平台里垫货款的，也先停下。交钱前去国家企业信用信息公示系统，查对方的执照和处罚记录。合同里写清服务内容、达不到怎么退钱。聊天记录、合同和转账截图都留好。已经转了钱，立刻打 110 或者 96110 要求止付，见第 8 节第 2 条（被骗止付）。对方确实干了活、只是效果差，多半算合同纠纷，要走协商、投诉或者起诉。撤销合同要打官司，一审普通程序 6 个月起，律师费自己出，判下来对方也可能早就跑了。打着加盟旗号收钱的，先按第 5 条（加盟前先查商务部备案）查备案。受益人主要是你自己。', NULL, NULL, NULL, '不花钱。交钱之前要到三样东西：书面合同、对方公司的全称、退钱的条件。钱只付给合同上那家公司，不转给个人账号。难的是对方晒出「学员月入过万」的截图时，忍住不当场交钱。', '广东省高级人民法院判过一个代运营骗局。蒋某、徐某等 55 人在广州、南宁、杭州开了多家公司。法院认定他们「明知根本不具备电商代运营的能力和技术条件」。他们还是以给淘宝网店代运营为名，诱骗 7711 名被害人购买、升级「服务套餐」。一共骗走 5299.4 万余元。两名首犯按诈骗罪分别判了 14 年和 13 年 6 个月。法院说，骗局设计得「严丝合缝」，「多名被害人一再受骗」。江苏省公安厅 2025 年把「无货源」跨境电商骗局拆成四步。第一步，在社交平台发「零基础」「无需囤货」的信息。第二步，以「运营指导」的身份加你，让你下载指定的平台。第三步，你开店后很快有第一单。对方让你先付商品成本价，说买家的货款冻结在平台里，收货后解冻。随后后台造出大量订单，让你不断加钱。第四步，想提现时就说「账户异常」「系统维护」，要你再交解冻金、手续费。案例里的张女士陆续垫进去 90 余万元，3 天后网站就打不开了。刷单那一头：一家代运营商给商户组织虚假团购冲排名。市场监管部门罚了它 10 万元，平台扣了它 5 万元保证金，法院支持平台扣钱。最高人民法院 2026 年把它列为典型案例，原话是「虚假交易、刷单炒信本为法律明令禁止的行为」。市场监管总局 2025 年也公布过一个案子。一家公司卖「一键搬家」「一键代发」软件，把别的平台的商品信息爬过来上架，被罚 53 万元。总局提示经营者「不得实施『搬家盗店』『无货源经营』等」违法行为。出路在民法典里：被对方用欺诈手段骗着签的合同，你可以请法院或者仲裁机构撤销。要在知道被骗那天起 1 年内提出。撤销以后，对方因此拿到的钱应当返还（全国）', '看到「零基础」「无需囤货」「低投入，高回报」「保证盈利」，就先停下。让你往它指定的平台里垫货款的，也先停下。交钱前去国家企业信用信息公示系统，查对方的执照和处罚记录。合同里写清服务内容、达不到怎么退钱。聊天记录、合同和转账截图都留好。已经转了钱，立刻打 110 或者 96110 要求止付，见第 8 节第 2 条（被骗止付）。对方确实干了活、只是效果差，多半算合同纠纷，要走协商、投诉或者起诉。撤销合同要打官司，一审普通程序 6 个月起，律师费自己出，判下来对方也可能早就跑了。打着加盟旗号收钱的，先按第 5 条（加盟前先查商务部备案）查备案。受益人主要是你自己。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"12. 创业与做生意：别把家底赔进去","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-1', 'concept_archive_s13-1', 'claim_archive_s13-1', 'action', 'life_archive', '有人倒地没呼吸，立刻用力按压胸口，让旁人打 120 并找 AED', '13. 紧急情况：先做什么', '你最可能按的是自家人：心脏骤停有 79.2% 发生在家里。有人按压，活着出院的比例从 3.9% 升到 16.1%。叫不应、没呼吸，就直接按。位置在两乳头连线的中点，双手叠起来用力压，每秒 2 次，不停。让第二个人打 120、拿 AED，你的手别停。', '不满 1 岁的孩子手法不同，要吹气，见本节第 44 条（婴儿心肺复苏）。不要先掐人中，不要先找家属，不要先拍视频。也不要因为怕按断肋骨就不敢用力。民法典第一百八十四条写明：自愿做紧急救助、把受助人弄伤了，救助人不承担民事责任。', NULL, NULL, NULL, '不花钱。红十字会或者医院的心肺复苏课，半天到一天，学一次够用多年。没学过也能做：双手叠起来放在两乳头连线的中点，每秒大约 2 次用力往下压，不要停。', '79 项研究、142,740 人合起来算（荟萃分析）：心跳停在医院外面（院外心脏骤停）的人，活着出院的总共只有 7.6%。在场的人做了心肺复苏的，活着出院的比例从 3.9% 升到 16.1%。有人在旁边看见发作的占 53%，真得到在场者按压的只有 32%。中国 BASIC-OHCA 登记了 38,227 例急救接诊病例。其中 30,282 例（79.2%）的心脏骤停发生在家中。这批人里，在场者按压率 20.3%，活着出院的 1.2%。顺序是先按压，再让第二个人打电话和拿 AED。机器开机后照着它的语音做', '不满 1 岁的孩子手法不同，要吹气，见本节第 44 条（婴儿心肺复苏）。不要先掐人中，不要先找家属，不要先拍视频。也不要因为怕按断肋骨就不敢用力。民法典第一百八十四条写明：自愿做紧急救助、把受助人弄伤了，救助人不承担民事责任。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-2', 'concept_archive_s13-2', 'claim_archive_s13-2', 'action', 'life_archive', '老人摔倒、有人倒地，先蹲下喊他、打 120，别急着把人扶起来；陌生人这档走开也合法，停下来就别上手搬', '13. 紧急情况：先做什么', '这条的主线是自家老人和身边熟人。先看有没有呼吸，没有就按第 1 条（用力按压胸口）压胸。有呼吸也别抱起来：人可能是先中风、先晕厥才摔的，硬扶会加重。蹲下叫他，问他记不记得自己怎么倒的。腰背疼、像骨折的一律不搬，原地打 120。', '定 B 是因为指南只说了该怎么处置，没有「照做能少死多少人」的数字。第一百八十四条免的是救人过程中弄出的损害，前提是你自愿、情况紧急。「自作主张把人塞进私家车送医」这类它不管，等 120 更稳妥。打完 120 别挂电话，按接线的调度员说的做。这套判断首先是给自家老人和熟人用的。换成路上不认识的人，走开不违法，也最省事：法律没规定你必须救。停下来要付的账要逐层算：时间、留号码、被家属找上、被告上法庭、闹到单位、被拍被传上网。详见 [docs/遇到陌生人出事该不该停.md](../docs/遇到陌生人出事该不该停.md)。真决定停下，唯一必须做到的是别上手搬，理由在医学上：硬扶可能加重脑出血或者脊柱损伤。有一个例外：这地方要是你在经营、你在管，或者活动是你组织的，走开就可能要担责。民法典第一千一百九十八条给的安全保障义务，要求你为场子里的人负一份安全责任。防跌倒本身见第 1 节第 13 条（练平衡和腿部力量）。老人磕过头之后的迟发症状见本节第 10 条。救人受伤之后的钱见本节第 39 条。被网暴怎么留证报警见第 8 节第 16 条。', NULL, NULL, NULL, '不花钱。蹲下去问一句、打个电话，几分钟。难的是忍住伸手去扶的那一下。对陌生人还要多算一笔：打 120 会留下你的号码，可能被回电，也可能被问一次话。真被家属盯上，打官司是几个月起步的事。而且就算最后判你赢，律师费也得自己出。', '卫生部《老年人跌倒干预技术指南》写明两句话。一句是「跌倒是我国 65 岁以上老年人伤害死亡的首位原因」。另一句是「发现老年人跌倒，不要急于扶起，要分情况进行处理」。意识不清的，立即拨打急救电话。有呕吐的，把头偏向一侧并清理口鼻。呼吸心跳停止的，立即做胸外按压。「如需搬动，应保证平稳，尽量平卧」。意识清楚的，先问他对跌倒过程有没有记忆，「如不能记起，可能为晕厥或脑血管意外」。有剧烈头痛，或者口角歪斜、言语不利、手脚无力的，「立即扶起老年人可能加重脑出血或脑缺血，使病情加重」。有骨折迹象，或者腰背疼痛、大小便失禁的，「如无相关专业知识，不要随便搬动」。以上几种都应立即拨打急救电话。老人自己想站起来的，可以协助他缓慢起立，「坐、卧休息并观察，确认无碍后方可离开」。说到「怕被讹」，法律上是这样规定的。《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十条有两句。头一句是「当事人对自己提出的诉讼请求所依据的事实……应当提供证据加以证明」。第二句是「在作出判决前，当事人未能提供证据或者证据不足以证明其事实主张的，由负有举证证明责任的当事人承担不利的后果」。民法典第一千一百九十八条的原文是：「宾馆、商场、银行、车站、机场、体育场馆、娱乐场所等经营场所、公共场所的经营者、管理者或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担侵权责任。」民法典第一百八十四条：「因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任」。最高人民法院公布过一个典型案例。药店经营者给心脏骤停的人做心肺复苏，压断了对方的肋骨。受助人住院 18 天，索赔 9 千余元。法院判决救助人不承担民事责任', '定 B 是因为指南只说了该怎么处置，没有「照做能少死多少人」的数字。第一百八十四条免的是救人过程中弄出的损害，前提是你自愿、情况紧急。「自作主张把人塞进私家车送医」这类它不管，等 120 更稳妥。打完 120 别挂电话，按接线的调度员说的做。这套判断首先是给自家老人和熟人用的。换成路上不认识的人，走开不违法，也最省事：法律没规定你必须救。停下来要付的账要逐层算：时间、留号码、被家属找上、被告上法庭、闹到单位、被拍被传上网。详见 [docs/遇到陌生人出事该不该停.md](../docs/遇到陌生人出事该不该停.md)。真决定停下，唯一必须做到的是别上手搬，理由在医学上：硬扶可能加重脑出血或者脊柱损伤。有一个例外：这地方要是你在经营、你在管，或者活动是你组织的，走开就可能要担责。民法典第一千一百九十八条给的安全保障义务，要求你为场子里的人负一份安全责任。防跌倒本身见第 1 节第 13 条（练平衡和腿部力量）。老人磕过头之后的迟发症状见本节第 10 条。救人受伤之后的钱见本节第 39 条。被网暴怎么留证报警见第 8 节第 16 条。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-3', 'concept_archive_s13-3', 'claim_archive_s13-3', 'action', 'life_archive', '突然嘴歪、一侧胳膊没劲、说话说不清，立刻打 120，不要等、不要自己开车去', '13. 紧急情况：先做什么', '嘴歪、一侧胳膊抬不起、说话说不清，立刻打 120。发病 3 小时内打药通开血管，恢复到生活基本能自理的可能性大约是不打药的 1.75 倍。拖到 3 到 4.5 小时只剩 1.26 倍。超过 4.5 小时就看不出差别了。记下症状开始的准确时间。别喂水喂药，别自己开车。', '溶栓越早越有效，超过 4.5 小时就基本没用了。打 120 而不是自己开车，是因为救护车会直接送到有卒中中心的医院，还会提前通知对方准备。记下症状开始的准确时间，医生要用它决定能不能溶栓。别喂水喂药，别等「休息一下看看」', NULL, NULL, NULL, '不花钱。三个动作，看一遍就会：让他笑一下、双手平举、说一句完整的话。', '把 16 项静脉溶栓随机试验、6756 名患者的个体数据合起来算（荟萃分析）。静脉溶栓就是打药把堵住的血管通开。发病 3 小时内用阿替普酶溶栓，恢复到生活基本能自理（改良 Rankin 评分 0–1）的比值比 1.75，95% CI 1.35–2.27（可信范围）。这个结果出现的可能性约为不溶栓的 1.75 倍。拖到 3 到 4.5 小时是 1.26（1.05–1.51）。超过 4.5 小时是 1.15（0.95–1.40），统计上已经看不出差别', '溶栓越早越有效，超过 4.5 小时就基本没用了。打 120 而不是自己开车，是因为救护车会直接送到有卒中中心的医院，还会提前通知对方准备。记下症状开始的准确时间，医生要用它决定能不能溶栓。别喂水喂药，别等「休息一下看看」', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-4', 'concept_archive_s13-4', 'claim_archive_s13-4', 'action', 'life_archive', '突然天旋地转站不稳、看东西成双、一只眼发黑，或者手指点不到自己鼻尖，也按卒中打 120', '13. 紧急情况：先做什么', '只看「脸歪、抬手、说话」三条，一成多的卒中会被漏掉，因为有的卒中一开始既不歪嘴也不瘫手。把站不稳、看东西重影或缺一块也算进去，漏掉的降到 4.4%。突然天旋地转站不住、看东西成双、手指点不到自己鼻尖，一样打 120，一样记下时间。', '小脑和脑干那一片的血管堵了（后循环梗死），常常不歪嘴、不瘫手。它只是天旋地转、走路偏斜、复视（看东西成双）、喝水吃饭呛，最容易被当成颈椎病、低血糖、耳石症耽误。指鼻不准、闭眼站不住，是小脑受累的表现。但没有哪个动作能反过来排除卒中：突然出现、不缓解就打 120，并记下发作的准确时间。该研究只翻了一家医院的病历，作者自己写明还要再验证', NULL, NULL, NULL, '不花钱。在「脸歪、抬手、说话」这三个动作（第 3 条，突然嘴歪、说话说不清）之外再加两个。一个是让他站直闭眼，看晃不晃，再问他看东西有没有重影、有没有缺一块。另一个是自己怀疑时伸手指点鼻尖，闭上眼再点一次。', '美国肯塔基大学卒中中心 2014 年回顾了 736 例急性缺血性卒中（血管堵住引起的中风）的病历。其中 14.1% 的病人发病时完全没有脸歪、胳膊无力、说话不清这三个症状（FAST）。把「走路不稳、腿没劲、视觉症状」也算进筛查，漏掉的比例从 14.1% 降到 4.4%', '小脑和脑干那一片的血管堵了（后循环梗死），常常不歪嘴、不瘫手。它只是天旋地转、走路偏斜、复视（看东西成双）、喝水吃饭呛，最容易被当成颈椎病、低血糖、耳石症耽误。指鼻不准、闭眼站不住，是小脑受累的表现。但没有哪个动作能反过来排除卒中：突然出现、不缓解就打 120，并记下发作的准确时间。该研究只翻了一家医院的病历，作者自己写明还要再验证', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-5', 'concept_archive_s13-5', 'claim_archive_s13-5', 'action', 'life_archive', '一只眼睛突然像拉下窗帘一样黑掉，哪怕几分钟就自己好了，也当天按卒中去急诊', '13. 紧急情况：先做什么', '一只眼突然像拉下窗帘一样黑掉，是眼底血管堵了，堵得越久，能救回的视网膜越少。它也是脑缺血的一种，接下来几天容易中风。当天评估、当天开始治的人，90 天内再中风的比例从 10.3% 降到 2.1%。当天去有卒中中心的急诊，别等第二天挂眼科。', '定 B 是因为 EXPRESS 不是随机试验。它比的是同一片人群改做法之前、之后两段时间，两段之间别的条件也可能变了，这部分分不开。眼前一黑几分钟又自己恢复，最容易被当成「累的」「低血糖」放过去。它是短暂性脑缺血发作的一种，接下来几天正是卒中高发的窗口。不疼、不红、不流泪的单眼看不见，尤其要当回事。别等第二天挂眼科门诊，直接去有卒中中心的医院急诊。', NULL, NULL, NULL, '不花钱。急诊评估和血管检查要占掉半天到一天。', '美国心脏协会 2021 年关于视网膜中央动脉阻塞（眼底那根主血管被堵住）的科学声明写明：「急性视网膜中央动脉阻塞是急症」。救治体系应当把它按急诊来识别、按轻重缓急排顺序。断血时间越长，还能救回来的视网膜越少。牛津 EXPRESS 研究看的是两类病人：小卒中，和症状自己好转的脑缺血（医学上叫短暂性脑缺血发作）。这批病人改为当天评估、当天开始治疗之后，90 天内再发卒中的比例从 10.3%（32/310）降到 2.1%（6/281）', '定 B 是因为 EXPRESS 不是随机试验。它比的是同一片人群改做法之前、之后两段时间，两段之间别的条件也可能变了，这部分分不开。眼前一黑几分钟又自己恢复，最容易被当成「累的」「低血糖」放过去。它是短暂性脑缺血发作的一种，接下来几天正是卒中高发的窗口。不疼、不红、不流泪的单眼看不见，尤其要当回事。别等第二天挂眼科门诊，直接去有卒中中心的医院急诊。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-6', 'concept_archive_s13-6', 'claim_archive_s13-6', 'action', 'life_archive', '一只眼又胀又痛、发红，看灯有一圈彩虹，还头痛恶心想吐，当天去眼科急诊', '13. 紧急情况：先做什么', '这是青光眼急性发作。眼睛里的水排不出去，眼压一下子顶上去。拖得越久，视神经压坏得越多，坏了就回不来。武汉封控期间的病人平均拖了 241 小时才治上，失明的占 21.87%。第二年同期没封控，平均拖 121 小时，失明的占 7.84%。', '定 B 的原因有两条。一是武汉那两组是翻旧病历比出来的，封控本身还带来别的差别，和「拖延」这一项分不开。二是韩国那组只有 50 只眼，也是回顾性的。诱因说的不是看屏幕，是两件事叠在一起：暗处瞳孔会散大，长时间低头或者趴着又把晶状体往前顶。前房本来就浅的人容易被这样诱发，所以真正高危的是 50 岁以上、远视、家里有人得过闭角型青光眼的人。年轻人通宵打游戏基本不会这样发作。发作时最常见的错判是当成胃肠炎、偏头痛或者血压高，因为头痛呕吐比眼睛的症状更抢眼。不疼不红的单眼看不见是另一回事，见第 5 条（一只眼睛突然黑掉）。防蓝光眼镜有没有用，见第 6 节第 16 条（防蓝光眼镜）。', NULL, NULL, NULL, '不花钱。眼科急诊量眼压、查前房，占掉半天。', '武汉一家眼科医院比了两段时间的急性原发性闭角型青光眼病人。2020 年封控的 76 天里有 54 人 64 眼，2021 年同期有 46 人 51 眼，两组的人口特征相近。从出现症状到接受治疗，封控那组是 241.84±211.95 小时，对照组是 121.53±96.12 小时（P=0.001）。就诊时的眼压是 52.63±12.45 mmHg 对 45.16±9.79 mmHg（P=0.001）。失明的比例是 21.87% 对 7.84%。查出青光眼性视神经病变的是 20/64 眼（31.25%）对 7/51 眼（13.73%）（P=0.03）。韩国一家医院回顾了 50 只发作过一次、后来摘了晶状体的眼睛。一年之后 25 只（50%）留下了不同程度的视野缺损。从症状出现到把眼压降下来的这段时间越长，留下缺损的可能越大（P=0.005）。另有一项前瞻研究，让 43 名前房浅的人在暗室里俯卧 1 小时。两只眼的眼压都明显升高（P&lt;0.01）。平时主要用的那只眼中位数升了 3.60 mmHg，另一只升了 2.70 mmHg（P&lt;0.05）', '定 B 的原因有两条。一是武汉那两组是翻旧病历比出来的，封控本身还带来别的差别，和「拖延」这一项分不开。二是韩国那组只有 50 只眼，也是回顾性的。诱因说的不是看屏幕，是两件事叠在一起：暗处瞳孔会散大，长时间低头或者趴着又把晶状体往前顶。前房本来就浅的人容易被这样诱发，所以真正高危的是 50 岁以上、远视、家里有人得过闭角型青光眼的人。年轻人通宵打游戏基本不会这样发作。发作时最常见的错判是当成胃肠炎、偏头痛或者血压高，因为头痛呕吐比眼睛的症状更抢眼。不疼不红的单眼看不见是另一回事，见第 5 条（一只眼睛突然黑掉）。防蓝光眼镜有没有用，见第 6 节第 16 条（防蓝光眼镜）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-7', 'concept_archive_s13-7', 'claim_archive_s13-7', 'action', 'life_archive', '胸口压着疼、闷、发紧超过 15 分钟不缓解，打 120，不要自己扛也不要自己开车', '13. 紧急情况：先做什么', '胸口压着疼、闷、发紧，超过 15 分钟不缓解，打 120。到医院后 55 分钟内把血管撑开的，30 天内死亡 2.8%。超过 55 分钟的 9.7%。耽误的每一段，都在多坏死一块心肌。别自己开车，路上失去意识就是第二场事故。', '该研究比的是进了医院之后耽误的那段，不是从发病到进医院那段。但道理一样：每耽误一会儿，就多坏死一块心肌。疼可能疼在上腹、后背、下巴，也可能是左胳膊发麻。糖尿病人和老年人可能不疼，只是喘。不要自己开车，路上失去意识就是第二场事故', NULL, NULL, NULL, '不花钱。', '以色列做过一项全国急性冠脉综合征调查。分析的对象是 ST 段抬高心肌梗死患者，这是一类心梗。算的是从进医院到用球囊把堵住的血管撑开（球囊扩张）这一段间隔。间隔 ≤55 分钟的，30 天内死亡 5/178（2.8%）。间隔 &gt;55 分钟的，30 天内死亡 15/155（9.7%）', '该研究比的是进了医院之后耽误的那段，不是从发病到进医院那段。但道理一样：每耽误一会儿，就多坏死一块心肌。疼可能疼在上腹、后背、下巴，也可能是左胳膊发麻。糖尿病人和老年人可能不疼，只是喘。不要自己开车，路上失去意识就是第二场事故', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-8', 'concept_archive_s13-8', 'claim_archive_s13-8', 'action', 'life_archive', '突然像被撕开一样的剧痛，从胸口往后背、往腰一路挪，打 120 并说清「疼在移动」', '13. 紧急情况：先做什么', '撕裂一样的剧痛从胸口往后背、往腰一路挪，打 120 时直接说「像撕开一样，疼在往下走」。这病不手术、光吃药的死亡率 58%。它的处理和心梗正相反：医生想到它，才会去做增强 CT，而不是给你抗凝溶栓。两条胳膊血压差很多、一侧摸不到脉，也一起说出来。', '夹层和心梗的处理正好相反。心梗要用抗凝、溶栓这类让血别凝住的药，用在夹层上等于给撕口放血。所以到医院要主动说「撕裂样，疼在往下走」，让医生想到查增强 CT。两条胳膊血压差很多、一侧摸不到脉搏，是提示。血压控制不好的、有马凡综合征的、家里得过主动脉瘤或者夹层的，风险高。同样不要自己开车，不要忍到第二天', NULL, NULL, NULL, '不花钱。', '国际急性主动脉夹层登记（IRAD）收了 12 家中心的 464 例。主动脉夹层就是胸背撕裂样剧痛那种病。病人最先说出来的症状里，最常见的是突然发作的剧烈锐痛。住院期间总死亡率 27.4%。A 型夹层没做手术、只吃药的，死亡率 58%', '夹层和心梗的处理正好相反。心梗要用抗凝、溶栓这类让血别凝住的药，用在夹层上等于给撕口放血。所以到医院要主动说「撕裂样，疼在往下走」，让医生想到查增强 CT。两条胳膊血压差很多、一侧摸不到脉搏，是提示。血压控制不好的、有马凡综合征的、家里得过主动脉瘤或者夹层的，风险高。同样不要自己开车，不要忍到第二天', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-9', 'concept_archive_s13-9', 'claim_archive_s13-9', 'action', 'life_archive', '突然一记「这辈子最疼的头痛」，一小时内就到最疼，立刻去急诊做头颅 CT', '13. 紧急情况：先做什么', '要看的是多快疼到最厉害。一小时内疼到顶的剧烈头痛，约 6% 是脑表面的血管破了。40 岁以上、脖子痛或发硬、有人看到你晕过去、活动中起病、瞬间炸开、脖子往前低不下去，中一条就去急诊做头颅 CT。去查的人大多没事，但漏一次再出血就是死亡。', '要看的不是「有多疼」，是「多快到最疼」，几秒到一分钟内炸开的头痛才是危险信号，慢慢加重的偏头痛不是。伴呕吐、脖子发硬、怕光、短暂晕厥，更要当回事。特异性只有 15.3%，意思是按这条去查的人绝大多数查完没事。但漏掉一次再出血就是死亡，值得查。不要吃片止痛药压下去接着睡', NULL, NULL, NULL, '看急诊本身不花什么钱。急诊做一次头颅 CT 几百元。', '加拿大 10 家急诊对 2131 例「一小时内达到最痛的剧烈头痛」做了前瞻队列研究，事先定好标准，再一路跟踪记录。其中 132 例（6.2%）是蛛网膜下腔出血（脑表面的血管破了）。渥太华 SAH 规则有六条：40 岁及以上、脖子痛或者发硬、有人看到晕过去。另外三条是活动中发作、一下子炸开式发作、医生查体时脖子前屈受限。符合任一条就要查。这条规则把出血的人全都挑了出来，敏感性 100%，95% CI 97.2%–100.0%（可信范围）。代价是没出血的人里只有 15.3% 被它排除掉（特异性 15.3%）', '要看的不是「有多疼」，是「多快到最疼」，几秒到一分钟内炸开的头痛才是危险信号，慢慢加重的偏头痛不是。伴呕吐、脖子发硬、怕光、短暂晕厥，更要当回事。特异性只有 15.3%，意思是按这条去查的人绝大多数查完没事。但漏掉一次再出血就是死亡，值得查。不要吃片止痛药压下去接着睡', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-10', 'concept_archive_s13-10', 'claim_archive_s13-10', 'action', 'life_archive', '老人磕过头之后两三周到几个月变得走路不稳、迟钝、嗜睡或者一侧没劲，去做头颅 CT', '13. 紧急情况：先做什么', '老人磕头之后，血通常到第三周才积起来。撞的当时可以完全没事，人自己都想不起磕过。这病开刀之后复发率能到 33%，病死率能到 32%。发现老人突然糊涂、走路发飘、总想睡、一只手没劲，先倒回去问这两三个月摔没摔过头，再去做 CT。', '撞的时候可以完全没事，老人自己甚至想不起磕过。所以家里发现「最近突然糊涂了、走路发飘、总想睡、一只手没劲」，先倒回去问这两三个月有没有摔过、撞过头，再去做 CT。别直接归到「老年痴呆」或者「上次中风的后遗症」上，归错了就会耽误。吃阿司匹林、氯吡格雷、华法林或者新型口服抗凝药的老人，风险更高，长期大量喝酒也是。防跌倒见第 1 节第 13 条（练平衡和腿部力量）。', NULL, NULL, NULL, '做一次头颅 CT 两三百元。', '中华医学会神经外科学分会等发布过《慢性硬膜下血肿药物治疗中国专家共识》。慢性硬膜下血肿，是脑膜之间慢慢积起来的一摊血。专业说法是蛛网膜与硬脑膜之间积血形成的慢性占位。它「通常在颅脑外伤后第三周形成」，多见于老年人。开刀之后复发率可达 33%，病死率可达 32%。90 岁以上的病人，总体上恢复得好的只有 24%。系统综述：全球每 10 万人每年新发 3.39 到 39.1 例，随年龄升高，80 岁以上可达三倍。最常见的起因是外伤和跌倒，其次是长期酗酒、用防止血液凝固的药（抗凝）和暴力伤害。老年医学综述：临床表现「典型包括意识模糊、认知下降、步态障碍或嗜睡，可能与其他老年综合征相似」', '撞的时候可以完全没事，老人自己甚至想不起磕过。所以家里发现「最近突然糊涂了、走路发飘、总想睡、一只手没劲」，先倒回去问这两三个月有没有摔过、撞过头，再去做 CT。别直接归到「老年痴呆」或者「上次中风的后遗症」上，归错了就会耽误。吃阿司匹林、氯吡格雷、华法林或者新型口服抗凝药的老人，风险更高，长期大量喝酒也是。防跌倒见第 1 节第 13 条（练平衡和腿部力量）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-11', 'concept_archive_s13-11', 'claim_archive_s13-11', 'action', 'life_archive', '一条腿突然肿起来、发紧、按着疼，尽快就医；再加上突然喘不上气或者胸痛，立刻打 120', '13. 紧急情况：先做什么', '一条腿突然肿起来、比另一条粗一圈、按着疼，尽快去做腿部静脉超声。再出现突然喘不上气、深吸气时胸痛、心跳快、发晕，血块可能已经跑到肺里，直接打 120。确诊肺栓塞的人 3 个月内死亡 17.4%。久坐超过 4 小时风险大约翻倍，但摊到一个人头上仍然很低。', '两条腿一起肿，多半是心、肝、肾或者静脉功能的问题。一条腿突然肿、比另一条粗一圈，才是深静脉血栓的典型样子。容易出事的是长途坐车坐飞机、手术或骨折后卧床、打石膏、怀孕生产前后、肿瘤、吃口服避孕药。血块脱落、堵住肺动脉就是肺栓塞：突然喘不上气、深吸一口气胸口更疼、心跳快、发晕、咳出血（咯血）。到这一步直接打 120。17.4% 是确诊肺栓塞病例的死亡率，不是「腿肿了就有这么大风险」，别对着这个数字吓自己。', NULL, NULL, NULL, '腿部血管做一次超声（下肢静脉超声），一两百元。', '国际肺栓塞协作登记（ICOPER）收了 7 个国家 52 家医院的 2454 例确诊急性肺栓塞病人。肺栓塞就是血块堵住肺动脉。这批人 3 个月内不分原因的死亡率是 17.4%（426/2454）。世界卫生组织 WRIGHT 项目：连续 4 小时以上的旅行，让静脉里长血块、血块跑到肺里（静脉血栓栓塞）的风险「大约翻倍」。但摊到一个人头上的概率仍然很低，久坐不动超过 4 小时「约为六千分之一」', '两条腿一起肿，多半是心、肝、肾或者静脉功能的问题。一条腿突然肿、比另一条粗一圈，才是深静脉血栓的典型样子。容易出事的是长途坐车坐飞机、手术或骨折后卧床、打石膏、怀孕生产前后、肿瘤、吃口服避孕药。血块脱落、堵住肺动脉就是肺栓塞：突然喘不上气、深吸一口气胸口更疼、心跳快、发晕、咳出血（咯血）。到这一步直接打 120。17.4% 是确诊肺栓塞病例的死亡率，不是「腿肿了就有这么大风险」，别对着这个数字吓自己。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-12', 'concept_archive_s13-12', 'claim_archive_s13-12', 'action', 'life_archive', '大出血先用手死死压住伤口，四肢压不住就上止血带，同时打 120', '13. 紧急情况：先做什么', '先用手或衣物死死压住，四肢压不住就上止血带，再打 120，上了就不松开。战地伤员里，休克前上止血带的活了九成，休克后才上的只活一成，该上没上的 5 个人全死了。扎在伤口上方，拧到血停，记下时间。别拿鞋带绳子代替。脖子和躯干只能压，不能扎。', '不要拿绳子、鞋带这类细东西当止血带，勒不住动脉，还割破皮肤。上了止血带不要隔一会儿松一下「放放血」。脖子和躯干上的出血只能压，不能扎。那份战地数据里，止血带本身没有让谁截肢，出现短暂神经麻痹的有 4 例。中国急诊医师的专家共识说法一致：院前一旦用上就不建议松开，除非有别的办法能彻底止血。上臂出血扎在上臂中上三分之一，大腿出血扎在大腿根。前臂、小腿、肘、膝上不要扎。共识建议到医院前后总共尽量别超过 2 小时，但到不了医院、又没别的办法止血的，等到正规救援之前不解开。皮带、领带、衣袖临时做的止血带，单用很难止住血，要配一根棍子绞紧。', NULL, NULL, NULL, '一根旋压式止血带几十到一百多元，放车里和急救包里。学一次「扎在伤口上方、拧到血停、记时间」，几分钟。', '美国得州 11 家一级创伤中心 6 年里收了 1,026 例四肢血管伤，其中 181 例（17.6%）在到医院之前上了止血带。不做任何调整直接算，上了止血带的死亡 3.9%，没上的 5.2%。把其他条件拉平之后（多因素校正），上止血带仍然单独和活下来相关。校正 OR 5.86，可信范围是 95% CI 1.41 到 24.47。巴格达战地医院的 232 名伤员：休克出现前上止血带的存活 90%，休克后才上的只有 10%。需要止血带而没上的 5 人全部死亡，上了的存活 87%。顺序是：直接压迫，衣物、毛巾都行 → 压不住的四肢出血上止血带 → 打 120 → 不松开', '不要拿绳子、鞋带这类细东西当止血带，勒不住动脉，还割破皮肤。上了止血带不要隔一会儿松一下「放放血」。脖子和躯干上的出血只能压，不能扎。那份战地数据里，止血带本身没有让谁截肢，出现短暂神经麻痹的有 4 例。中国急诊医师的专家共识说法一致：院前一旦用上就不建议松开，除非有别的办法能彻底止血。上臂出血扎在上臂中上三分之一，大腿出血扎在大腿根。前臂、小腿、肘、膝上不要扎。共识建议到医院前后总共尽量别超过 2 小时，但到不了医院、又没别的办法止血的，等到正规救援之前不解开。皮带、领带、衣袖临时做的止血带，单用很难止住血，要配一根棍子绞紧。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 少","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-13', 'concept_archive_s13-13', 'claim_archive_s13-13', 'action', 'life_archive', '被狗、猫咬伤或抓破皮，先用肥皂水和流水交替冲 15 分钟，当天去打疫苗', '13. 紧急情况：先做什么', '狂犬病一旦发病，病死率几乎 100%，冲洗加疫苗是唯一的路。先用肥皂水和流动清水交替冲 15 分钟，当天去打疫苗。咬穿了、破皮的地方被舔，属于三级暴露，还要加打被动免疫制剂。「家养的、打过针的」不改变处置，级别按伤口定，不按狗的来历定。', '不要因为「家养的、打过针的」就不处理。规范看的是伤口到了哪一级（暴露级别），不看狗的来历。不要自己包伤口。十日观察法只能决定要不要停针，不能决定要不要开始打。被野生动物、蝙蝠咬伤，同样这么处理。', NULL, NULL, NULL, '冲洗不花钱。狂犬病疫苗全程几百元。三级暴露还要加打狂犬病被动免疫制剂（直接打进现成的抗体），几百到上千元。', '国家疾控局、国家卫健委 2023 年版规范原文：「狂犬病病死率几乎达 100%」。处置是「用肥皂水（或者其他弱碱性清洁剂）和一定压力的流动清水交替彻底冲洗所有咬伤和抓伤处约 15 分钟」。裸露皮肤被轻咬、无出血抓伤，是 II 级暴露，要打疫苗。贯穿性咬伤、破损皮肤被舔，是 III 级暴露，「应处置伤口并注射狂犬病被动免疫制剂和接种狂犬病疫苗」。WHO：全球每年约 5.9 万人死于狂犬病，99% 由狗传播', '不要因为「家养的、打过针的」就不处理。规范看的是伤口到了哪一级（暴露级别），不看狗的来历。不要自己包伤口。十日观察法只能决定要不要停针，不能决定要不要开始打。被野生动物、蝙蝠咬伤，同样这么处理。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-14', 'concept_archive_s13-14', 'claim_archive_s13-14', 'action', 'life_archive', '烫伤后立刻用凉的流动水冲 20 分钟，别抹牙膏酱油', '13. 紧急情况：先做什么', '受伤 3 小时内用凉的流动水冲够 20 分钟，后来需要植皮的可能性大约只有没冲的六成。是凉水不是冰水，冰敷会加重损伤。衣服粘在伤口上别硬撕，冲完拿干净布盖住去医院。牙膏、酱油、香油、面粉都不要抹。隔了一会儿才想起来，三小时内补冲仍然有用。', '是凉水不是冰水，冰敷会加重损伤。衣服粘在伤口上就别硬撕，冲完用干净布盖住去医院。牙膏、酱油、香油、面粉都不要抹，会影响医生判断深度，还容易感染。三小时内补冲仍然有用', NULL, NULL, NULL, '不花钱。占 20 分钟。', '澳大利亚跟踪了 2495 名烧烫伤儿童。受伤后 3 小时内用凉流动水冲 20 分钟的孩子，后来需要植皮的比值比是 0.6，95% CI 0.4–0.8（可信范围），大约只有没这么冲的六成。7 项研究合起来算的结果同样发现，「伤后三小时内 20 分钟凉流动水显著降低了需要植皮和手术处理创面的可能」', '是凉水不是冰水，冰敷会加重损伤。衣服粘在伤口上就别硬撕，冲完用干净布盖住去医院。牙膏、酱油、香油、面粉都不要抹，会影响医生判断深度，还容易感染。三小时内补冲仍然有用', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-15', 'concept_archive_s13-15', 'claim_archive_s13-15', 'action', 'life_archive', '突然全身起疹、喘不上气或者发晕，按过敏性休克处理，立刻叫 120 并说清楚', '13. 紧急情况：先做什么', '突然全身起疹，再加上喘不上气或者发晕，就按过敏性休克办。立刻打 120，直接说「怀疑过敏性休克」，让急救带着肾上腺素来。抗过敏药和激素起效慢，替不了肾上腺素。有过一次的人找医生开自动注射笔，打大腿中外侧，隔着裤子也能打。', '这份过敏指南（EAACI）自己写明，这个领域「证据大多停留在很低的等级」。它列为强推荐，是因为好处远大于风险，不是因为有大型试验。肾上腺素在国内是处方药，普通人手上通常没有。能做的是叫 120，并说「怀疑过敏性休克」，让急救带着药来。有过一次严重过敏的，找医生开自动注射笔，学会打大腿中外侧（外侧偏前），隔着裤子也能打。', NULL, NULL, NULL, '不花钱。已知有严重过敏的人自备肾上腺素笔要花钱，而且它是处方药。', '肾上腺素是二级及以上过敏性休克首选的药（一线药），指南把它列为强推荐。抗过敏药和激素起效慢，顶不了它的位置', '这份过敏指南（EAACI）自己写明，这个领域「证据大多停留在很低的等级」。它列为强推荐，是因为好处远大于风险，不是因为有大型试验。肾上腺素在国内是处方药，普通人手上通常没有。能做的是叫 120，并说「怀疑过敏性休克」，让急救带着药来。有过一次严重过敏的，找医生开自动注射笔，学会打大腿中外侧（外侧偏前），隔着裤子也能打。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-16', 'concept_archive_s13-16', 'claim_archive_s13-16', 'action', 'life_archive', '有人抽搐倒地，清开周围、让他侧躺、看表计时，什么都别往嘴里塞', '13. 紧急情况：先做什么', '把周围的硬东西挪开，让他侧躺、嘴朝下，看表记时间。别按住他，别掰嘴，别往嘴里塞东西，那只会弄伤牙齿和下颌。超过 5 分钟不停、停了很快又发作、发作后叫不醒或者呼吸困难、在水里发作、这是头一次发作，都要叫救护车。等人完全清醒再给水。', '同一页还列了另外几种要立刻叫救护车的情况：一次结束后很快又发作、发作后叫不醒或者呼吸困难、发作中受了伤、在水里发作、这是第一次发作。发作停了让他侧躺、嘴朝下，等人完全清醒再给水。家里有癫痫病人的，这套动作最用得上。对陌生人做同样的动作，好处回到你身上的机会小一些，但也不会让你担责（民法典第一百八十四条，见本节第 2 条，别急着把人扶起来）。', NULL, NULL, NULL, '不花钱。', '避免掰嘴、塞硬物造成的牙齿和下颌损伤。避免强行按住造成的骨折。超过 5 分钟不停，是必须叫救护车的红线', '同一页还列了另外几种要立刻叫救护车的情况：一次结束后很快又发作、发作后叫不醒或者呼吸困难、发作中受了伤、在水里发作、这是第一次发作。发作停了让他侧躺、嘴朝下，等人完全清醒再给水。家里有癫痫病人的，这套动作最用得上。对陌生人做同样的动作，好处回到你身上的机会小一些，但也不会让你担责（民法典第一百八十四条，见本节第 2 条，别急着把人扶起来）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-17', 'concept_archive_s13-17', 'claim_archive_s13-17', 'action', 'life_archive', '糖尿病人突然发抖、出冷汗、说话不清，先给 15 克糖，15 分钟后复测', '13. 紧急情况：先做什么', '先吃 15 克糖，方糖、一小盒果汁都行。15 分钟后再测一次，还低就再来一次。血糖低于 3.0 mmol/L 就是医学上要当回事的低血糖。到了要别人帮忙才能处理的程度，可以致命。意识不清的人一口都别喂，会呛进气管，直接打 120。', '意识不清的人不要喂东西，会呛进气管，直接叫 120。同一份标准还建议，打胰岛素的人、容易低血糖的人，都该备一份胰高血糖素。原文是「All individuals treated with insulin or who are at high risk of hypoglycemia...should be prescribed glucagon」。鼻喷的和事先装好药的针剂，比要临时兑药的好用。这些做法默认是给你自己或者家里的糖尿病人准备的，随身带糖也是给他们带的。', NULL, NULL, NULL, '不花钱。随身带几块方糖或者一小盒果汁。', '血糖低于 3.0 mmol/L，属于临床上有意义的低血糖。出现意识或者行动改变、需要别人帮忙处理的，是重度低血糖，可以致命', '意识不清的人不要喂东西，会呛进气管，直接叫 120。同一份标准还建议，打胰岛素的人、容易低血糖的人，都该备一份胰高血糖素。原文是「All individuals treated with insulin or who are at high risk of hypoglycemia...should be prescribed glucagon」。鼻喷的和事先装好药的针剂，比要临时兑药的好用。这些做法默认是给你自己或者家里的糖尿病人准备的，随身带糖也是给他们带的。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-18', 'concept_archive_s13-18', 'claim_archive_s13-18', 'action', 'life_archive', '有人触电，先断电，再用干燥的木棍之类挑开电源，不要直接上手拉', '13. 紧急情况：先做什么', '先断电，或者用干燥的木棍之类把电源挑开，再碰人。直接上手拉，一个伤者就变成两个。脱离电源后没有呼吸的，立刻按第 1 条（用力按压胸口）按压，别因为是电伤就不敢碰。高压线落地、变电设备附近不自己处置，退远等电力部门断电。', '「先断电再碰人」是纯自利规则：直接上手拉，倒下的第二个就是你。高压线落地、变电设备附近不要自己处置，退远等电力部门断电。触电引起的心脏骤停，照常规按压、照常规除颤就行，别因为是「电伤」就不敢上手。', NULL, NULL, NULL, '不花钱。', '避免施救的人一起被电住，把一个伤者变成两个。脱离电源后没有呼吸的，按本节第 1 条（用力按压胸口）做心肺复苏。美国疾控中心的急救步骤是：先看，别碰，人可能还连着电。能断电先断电，断不了就用纸板、塑料或木头这类不导电的东西把电源拨开。脱离电源后，呼吸或脉搏停了的，立刻做心肺复苏。一篇综述说，触电后心跳骤停、被救回来的人，预后往往不错', '「先断电再碰人」是纯自利规则：直接上手拉，倒下的第二个就是你。高压线落地、变电设备附近不要自己处置，退远等电力部门断电。触电引起的心脏骤停，照常规按压、照常规除颤就行，别因为是「电伤」就不敢上手。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-19', 'concept_archive_s13-19', 'claim_archive_s13-19', 'action', 'life_archive', '一氧化碳报警器响了，或者一屋子人同时头痛恶心，先出门再打电话', '13. 紧急情况：先做什么', '报警器响了，或者一屋子人同时头痛、恶心、发晕，先把人都带到室外，再打电话。别留在屋里找原因，也别回去关阀门。症状像感冒，「出门就好转」是最强的提示。中国 2018 年报告了 11523 人死于一氧化碳中毒，冬天最多，大多死在家里。', '症状像感冒，又像喝多了。一屋子人一起难受、出门就好转，是最强的提示。别留在屋里找原因，别回去关阀门，人先出来再打电话。报警器怎么装见第 1 节第 3 条。', NULL, NULL, NULL, '不花钱。', '中国疾控的死因监测系统 2018 年报告了 11523 例一氧化碳中毒死亡。最多的是 1 月（2845 例）、2 月（2321 例）和 12 月（2010 例）。冬天这三个月，死在家里的占 66% 到 73%。这是系统里报上来的数，不是按全国人口推算的。美国每年 400 多人死于与火灾无关的意外一氧化碳中毒。10 万人以上进急诊，1.4 万人以上住院', '症状像感冒，又像喝多了。一屋子人一起难受、出门就好转，是最强的提示。别留在屋里找原因，别回去关阀门，人先出来再打电话。报警器怎么装见第 1 节第 3 条。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-20', 'concept_archive_s13-20', 'claim_archive_s13-20', 'action', 'life_archive', '误服清洁剂、农药、药物先别催吐，带上瓶子立刻就医；溅到眼睛或皮肤用大量清水至少冲 15 分钟', '13. 紧急情况：先做什么', '误服清洁剂、农药、药物不要催吐，腐蚀性液体吐出来会把食管再烧一遍。先喝适量牛奶或者蛋清，带上瓶子和说明书立刻去医院。溅到皮肤或者眼睛，用大量清水至少冲 15 分钟，眼睛要撑开眼皮冲、不要揉。消毒液和洁厕剂混着用会产生氯气。', '定 B 是因为官方科普只讲了该怎么处理、怎么认出来，没有「照做能少出多少事」的数字。不催吐的道理是：腐蚀性的液体吐出来，会把食管（嗓子到胃那根管子）再烧一遍。拿不准误服的是什么，就把瓶子、说明书连同呕吐物一起带去医院。预防比急救便宜得多：分类存放，别和食物饮料混放，用完拧紧盖子扔掉空瓶，绝不倒进矿泉水瓶。使用时戴橡胶手套和护目镜，开窗通风，不同类型不混用。一氧化碳见第 19 条，烧烫伤见第 14 条。酸碱这类化学品溅到身上，怎么脱衣服、冲多久，见第 21 条（化学品溅到身上）。', NULL, NULL, NULL, '不花钱。把清洁剂、消毒液、农药和药品放到孩子够不着的高处，或者带锁的柜子里。绝不分装进饮料瓶。', '中国疾控中心职业卫生与中毒控制所给的处置口径分四种。吃进嘴里（消化道摄入）的，立即饮用适量的牛奶或蛋清，「切记，不要催吐」。尽快就医，同时携带包装或说明书，「以便于医生快速判断成分并制定救治方案」。吸进气里（呼吸道吸入）：立即转移至通风良好的区域，解开衣领保持呼吸通畅；出现剧烈咳嗽、气促或呼吸困难的，立即就医。皮肤接触：立即用大量清水冲洗接触部位至少 15 分钟，注意别让冲洗液溅到眼睛或者其他完好皮肤。眼睛接触的，立即用大量清水或生理盐水冲洗眼睛至少 15 分钟。冲洗时撑开眼睑，让水流充分接触眼球及眼睑内侧，「切勿揉搓眼睛」。冲洗后立即前往眼科。高危产品按酸碱度（pH）认。pH&lt;3 的是洁厕剂、除垢剂、地板清洁剂、不锈钢光亮剂。部分强力管道疏通剂还含稀硫酸。pH&gt;11 的是管道疏通剂、厨房强力除污剂、洗碗粉、爆炸盐、去污粉。还有一个当场出事的组合：消毒液和含盐酸的洁厕剂一起用会产生氯气，刺激呼吸道、引起剧烈咳嗽和气促，甚至危及生命', '定 B 是因为官方科普只讲了该怎么处理、怎么认出来，没有「照做能少出多少事」的数字。不催吐的道理是：腐蚀性的液体吐出来，会把食管（嗓子到胃那根管子）再烧一遍。拿不准误服的是什么，就把瓶子、说明书连同呕吐物一起带去医院。预防比急救便宜得多：分类存放，别和食物饮料混放，用完拧紧盖子扔掉空瓶，绝不倒进矿泉水瓶。使用时戴橡胶手套和护目镜，开窗通风，不同类型不混用。一氧化碳见第 19 条，烧烫伤见第 14 条。酸碱这类化学品溅到身上，怎么脱衣服、冲多久，见第 21 条（化学品溅到身上）。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-21', 'concept_archive_s13-21', 'claim_archive_s13-21', 'action', 'life_archive', '酸碱等化学品溅到身上，立刻脱掉污染的衣服、用大量流动清水冲，眼睛要掰开眼皮冲，冲够时间再走', '13. 紧急情况：先做什么', '三步。第一步，立刻脱掉沾上的衣服鞋袜，衣服兜住的地方伤得最重。第二步，用大量流动清水冲，皮肤和眼睛都至少 15 分钟，湖南省应急管理厅给到 20 到 30 分钟，按长的那个来。第三步，眼睛撑开眼皮冲，冲完直接去眼科。用常温水，不用热水。', '定 B 是因为冲多久这件事，两份官方材料一份写 15 分钟、一份写 20 到 30 分钟，没有统一的国家标准数字。去医院带上化学品的名字、包装，或者那张安全数据表（SDS），医生要靠它定方案。不要随手抓另一种酸或者碱去「中和」：两样兑到一起会放热，倒多少也没法控制。湖南那份材料里说的「中和液」，指的是单位事先备好的专用冲洗液，不是现场拿东西对冲。石灰粉、水泥粉这类干粉先刷掉再冲水（有的地方应急页面据此说浓硫酸也要先擦干，这一点各处口径不一，本书不写）。家里的清洁剂和误服见第 20 条。上岗前的防护和体检见第 19 节第 9、10 条（上岗前看危害告知、防护用品单位必须给）。', NULL, NULL, NULL, '不花钱。上岗第一天就把洗眼器和冲淋装置的位置看好，别等出事再找。', '现场三步。第一步，立即脱去受污染的衣物鞋袜：毒物会继续经皮肤吸收，衣服兜着的部分伤得最重。第二步，用大量流动清水冲洗。中国疾控中心职业卫生与中毒控制所给的下限，是皮肤和眼睛各「至少 15 分钟」。湖南省应急管理厅给的口径是创面冲洗 20 至 30 分钟，「强烈的化学品要更长」。两个口径里取长的那个。第三步，眼睛要「撑开眼睑，确保水流充分接触眼球及眼睑内侧」，「切勿揉搓眼睛」，冲完立即去眼科。用常温或微温水，禁用热水。新鲜创面上不要涂油膏、红药水或者任何东西，也不要用脏布包裹，涂了会影响医生判断深度。法律上，「化学性皮肤灼伤」和「化学性眼部灼伤」都在法定职业病目录里，工作中发生的按职业病和工伤走。发生急性职业病危害事故的，用人单位「应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担」（全国）', '定 B 是因为冲多久这件事，两份官方材料一份写 15 分钟、一份写 20 到 30 分钟，没有统一的国家标准数字。去医院带上化学品的名字、包装，或者那张安全数据表（SDS），医生要靠它定方案。不要随手抓另一种酸或者碱去「中和」：两样兑到一起会放热，倒多少也没法控制。湖南那份材料里说的「中和液」，指的是单位事先备好的专用冲洗液，不是现场拿东西对冲。石灰粉、水泥粉这类干粉先刷掉再冲水（有的地方应急页面据此说浓硫酸也要先擦干，这一点各处口径不一，本书不写）。家里的清洁剂和误服见第 20 条。上岗前的防护和体检见第 19 节第 9、10 条（上岗前看危害告知、防护用品单位必须给）。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-22', 'concept_archive_s13-22', 'claim_archive_s13-22', 'action', 'life_archive', '高温下头晕、恶心、不出汗或意识不清，立刻挪到阴凉处脱衣泼水降温，意识不清的不喂水、打 120', '13. 紧急情况：先做什么', '皮肤烫红、说话含糊、意识混乱是热射病。从头晕到昏迷可以只有几十分钟，病死率极高。立刻挪到阴凉通风处、脱掉衣服、用凉水和湿毛巾降温，同时打 120。意识不清的一口水都不要喂，会呛。', '不要等「缓一缓」，热射病从头晕到昏迷可以只有几十分钟。不要给意识不清的人灌水，会呛。冰袋放哪里，两边说法不同。中国疾控说敷在脖子、腋窝和大腿根，荒野医学会说研究看不出敷这几处有降温效果。它的建议是，只有冰袋可用时就把全身盖满，冰袋不够再放脸颊、手心和脚底。两边都说有条件就用冷水浸泡。', NULL, NULL, NULL, '不花钱。', '美国国家气象局：热射病是「严重的医疗急症」。它的表现是体温高于 103°F（39.4°C）、意识混乱、说话含糊、皮肤发烫发红。处理是立刻叫急救、移到凉处、用凉水和湿布降温、「不要给液体」。热衰竭的表现是大汗、乏力、皮肤湿冷、脉快而弱，处理是移到凉处、松开衣服、小口喝水；呕吐、恶化或者超过 1 小时不缓解就就医。云南省疾控局提示：立即转移到阴凉通风处，用冷湿毛巾降温，意识清醒的补含盐饮料，症状严重的立即拨打急救电话；重症热射病「病死率极高」。中国疾控中心提示：先降温，后转运，在病人失去意识后的「黄金半小时」内降温。有条件的，无基础疾病的青壮年可以用冷水浸泡快速降温，老人和有基础病的往皮肤上喷水、靠蒸发降温。荒野医学会 2024 年更新的热病指南说，冷水浸泡是治重症中暑最重要的办法，降温最快。没有冰水就用手边最凉的水，泡不了就喷水加扇风，速度大约是浸泡的一半', '不要等「缓一缓」，热射病从头晕到昏迷可以只有几十分钟。不要给意识不清的人灌水，会呛。冰袋放哪里，两边说法不同。中国疾控说敷在脖子、腋窝和大腿根，荒野医学会说研究看不出敷这几处有降温效果。它的建议是，只有冰袋可用时就把全身盖满，冰袋不够再放脸颊、手心和脚底。两边都说有条件就用冷水浸泡。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-23', 'concept_archive_s13-23', 'claim_archive_s13-23', 'action', 'life_archive', '中暑的人只要清醒，就少量多次喝凉的淡盐水或运动饮料，别猛灌、别喝酒和高糖饮料', '13. 紧急情况：先做什么', '只有清醒的人才喝。凉的淡盐水或运动饮料少量多次喝，一小时 500 到 1000 毫升。别猛灌，吐出来呛进气管更要命。不喝酒和高糖饮料，它们会让人丢更多水。先用凉水擦身、冰袋敷脖子腋下大腿根降温，再补水。意识不清、说话含糊的，一口都不喂。', '出大汗后只灌白开水，会把血里的盐冲淡（血钠低），所以水里要含一点盐。一次猛灌容易吐，吐的东西呛进气管比中暑本身更快要命。「别喝冰镇的」是中国疾控 2014 年那版指南里的建议，理由是怕胃痉挛，没有量化证据。别把它误读成「不能用冷的」。第 22 条（高温下头晕恶心时脱衣泼水降温）里讲了几样降温法。分别是凉水擦洗、冷水浸泡、冰袋敷脖子、腋下、大腿根（腹股沟）。这几样正是官方推荐的头一档降温法，是往身上用的，不往嘴里灌。降温永远排在补水前面。意识不清、说话含糊的，一口都不要喂', NULL, NULL, NULL, '不花钱。一瓶运动饮料几元。', '中国疾控中心发布过《公众高温中暑预防与紧急处理指南（2014 版）》。里面写着「至少每小时喝 2~4 杯凉水（500~1000ml），水温不宜过高，饮水应少量多次」。还写着「不要饮用含酒精或大量糖分的饮料。这些饮料会导致失去更多的体液。同时，还应避免饮用过凉的冰冻饮料」。对热射病则明确写「不要给病人喝水」。美国 NIOSH：热衰竭要「鼓励小口频繁地喝凉水」；热痉挛每 15 到 20 分钟补一次含糖和电解质的运动饮料，「不要用盐片」', '出大汗后只灌白开水，会把血里的盐冲淡（血钠低），所以水里要含一点盐。一次猛灌容易吐，吐的东西呛进气管比中暑本身更快要命。「别喝冰镇的」是中国疾控 2014 年那版指南里的建议，理由是怕胃痉挛，没有量化证据。别把它误读成「不能用冷的」。第 22 条（高温下头晕恶心时脱衣泼水降温）里讲了几样降温法。分别是凉水擦洗、冷水浸泡、冰袋敷脖子、腋下、大腿根（腹股沟）。这几样正是官方推荐的头一档降温法，是往身上用的，不往嘴里灌。降温永远排在补水前面。意识不清、说话含糊的，一口都不要喂', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-24', 'concept_archive_s13-24', 'claim_archive_s13-24', 'action', 'life_archive', '火灾时贴地爬、摸门再开门、门烫就别开，走楼梯不坐电梯，出去了别回头', '13. 紧急情况：先做什么', '趴到地上，从烟底下爬向出口。开门前先摸门把和门板，烫、或者门缝在冒烟，就别开这扇门，换第二条路。开门要慢，一冒浓烟立刻关上。走楼梯不坐电梯，一断电就困在里面。出去了不为拿东西回头。衣服着火就停下、倒地、打滚，用手护住脸。', '不要坐电梯，断电就困在里面。不要为拿财物回头。不要往上跑，除非确认楼顶门开着。不要跳楼。湿毛巾要对折 3 次叠成 8 层，水别太多，太湿反而喘不上气。烟和毒气太浓的时候，毛巾也挡不住。', NULL, NULL, NULL, '家里装 1 到 2 个独立烟感，几十元。提前看一眼楼道的两条出口。', '美国 FEMA 逃生原文：「趴到地上，从烟下面爬向出口」。开门前先摸门把和门板，「如果是热的，或者门缝有烟，别开这扇门，用第二条路」。开门要慢，一有浓烟立刻关上。衣服着火就「停下、倒地、打滚」，用手护脸。出不去就关门，用布或者胶带堵住门缝和通风口，打电话报位置。应急管理部的火灾自救提示和这一致：逃生不要坐电梯，火不大时尽量往楼下跑，用湿毛巾或口罩蒙住口鼻，趴着或弯腰撤离', '不要坐电梯，断电就困在里面。不要为拿财物回头。不要往上跑，除非确认楼顶门开着。不要跳楼。湿毛巾要对折 3 次叠成 8 层，水别太多，太湿反而喘不上气。烟和毒气太浓的时候，毛巾也挡不住。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-25', 'concept_archive_s13-25', 'claim_archive_s13-25', 'action', 'life_archive', '看到有人溺水，先叫人和打 110/120，伸竿、抛漂浮物，自己不下水', '13. 紧急情况：先做什么', '溺水的人会本能地把施救者往水下按，下水的人自己也可能淹死。顺序是：大喊叫人 → 打 110/120 → 递长杆、绳子 → 抛救生圈、空桶、矿泉水瓶 → 人上岸没呼吸就立刻按压。不结手拉手的链子下水。全球每年约 30 万人溺亡，这是 1 到 4 岁孩子的第四位死因。', 'C 级原因是「不下水」这条规则没有找到官方原文，只有 WHO 的死亡数字和「安全救援」的方向。不要手拉手结成链子下水。没受过训练就不要去拖人，溺水者会把施救者往下按。「不下水」同样是自利规则：下水的人自己淹死，水里那个是谁都一样。真要救的多半是自家孩子，怎么防在第 1 节第 12 条（儿童近水不离视线）。有人掉进冰窟窿，同样不跑上冰面去拉，冰面怎么防见第 1 节第 41 条（野外冰面先量厚度）。', NULL, NULL, NULL, '不花钱。难的是忍住往下跳的冲动。', 'WHO：全球每年约 30 万人溺亡，92% 在中低收入国家。溺水是 1 到 4 岁儿童的第四位死因，5 到 14 岁的第三位死因。WHO 推荐的干预是「安全救援和复苏培训」，比如先学会不下水的救法。顺序是：大喊叫人 → 打电话 → 递长杆、绳子，抛救生圈、空桶、矿泉水瓶 → 人上岸后无呼吸立刻按压', 'C 级原因是「不下水」这条规则没有找到官方原文，只有 WHO 的死亡数字和「安全救援」的方向。不要手拉手结成链子下水。没受过训练就不要去拖人，溺水者会把施救者往下按。「不下水」同样是自利规则：下水的人自己淹死，水里那个是谁都一样。真要救的多半是自家孩子，怎么防在第 1 节第 12 条（儿童近水不离视线）。有人掉进冰窟窿，同样不跑上冰面去拉，冰面怎么防见第 1 节第 41 条（野外冰面先量厚度）。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-26', 'concept_archive_s13-26', 'claim_archive_s13-26', 'action', 'life_archive', '有人噎住说不出话，站到背后做 5 次拍背加 5 次腹部冲击，倒下就做心肺复苏', '13. 紧急情况：先做什么', '先问「你噎住了吗，能说话吗」。还能用力咳、能出声的不要动手，让他咳。说不出话就站到背后，5 次拍背接 5 次腹部冲击，反复做到东西出来或者人倒下。倒下就做心肺复苏，同时叫人打急救电话。孕妇和很胖的人改冲胸口。别伸手去嘴里掏看不见的东西。', '不要往嘴里伸手掏看不见的东西，会推得更深。不要拍还能咳嗽的人。噎住最常发生在自家饭桌上，受益的主要是家里人。国内的教法也是这一套：福建省红十字应急救护培训中心说，1 岁以上的孩子和成人，中国红十字系统一直按 5 次拍背加 5 次腹部冲击循环来教。网上不少老教程只教腹部冲击，那是旧版。不满 1 岁的孩子不按肚子，改按胸口，见本节第 43 条（婴儿噎住）。', NULL, NULL, NULL, '不花钱。看一遍动作：一手握拳顶在肚脐上方，另一手包住，向内向上快速冲击。', '美国国立医学图书馆原文：先问「你噎住了吗，能说话吗」。「能用力咳嗽、能说话的不要动手」，咳嗽本身多能把异物咳出。说不出话就「反复做 5 次拍背接 5 次腹部冲击，直到异物出来或人失去意识」。「失去意识就开始心肺复苏」，同时叫人打急救电话。孕妇、肥胖者改做胸部冲击', '不要往嘴里伸手掏看不见的东西，会推得更深。不要拍还能咳嗽的人。噎住最常发生在自家饭桌上，受益的主要是家里人。国内的教法也是这一套：福建省红十字应急救护培训中心说，1 岁以上的孩子和成人，中国红十字系统一直按 5 次拍背加 5 次腹部冲击循环来教。网上不少老教程只教腹部冲击，那是旧版。不满 1 岁的孩子不按肚子，改按胸口，见本节第 43 条（婴儿噎住）。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-27', 'concept_archive_s13-27', 'claim_archive_s13-27', 'action', 'life_archive', '在戈壁、沙漠、无人区迷路或车坏了，留在原地或车旁，先报位置，再遮阳保温，省水，不乱走', '13. 紧急情况：先做什么', '留在原地或者车旁，车是最大的遮阳物。顺序是：有信号先发位置再打电话 → 遮阳保暖 → 省水，白天不动、夜里凉了再动 → 不乱走 → 用反光镜、烟、三堆火发信号。进去之前把路线、目的地、返回日期和车型车牌告诉别人。', 'C 级原因是这些都是官方提示，不是研究数据。饮水量、报备、信号覆盖、待在车旁、求救信号都是官方原话。流传的「三声一组」没有找到官方原文，所以改写成官方的三堆火和三短三长三短。不要在正午徒步找路。不要喝尿。不要为了省水而不喝。', NULL, NULL, NULL, '进无人区前告诉别人路线、目的地、返回日期、车型车牌。每人每天 4 升水起。卫星通讯器或者北斗短报文设备上千元，租一次几百元。难的是守住「留在原地不乱走」。', '美国国家公园管理局的莫哈韦沙漠页面有三句原文。一句是「每人每天至少 1 加仑（约 3.8 升）水，徒步和骑行者每人每天 2 加仑」。一句是「告诉别人你的路线、目的地、返回日期、车型和车牌」。还有一句是「手机信号时有时无」。死亡谷原文：「热的时候不要在谷底和低海拔徒步」，荒野区域「几乎没有手机信号」，推荐带卫星电话。莫哈韦的沙漠驾驶页面原文：「出了紧急情况，待在车旁是你能做的最重要的事」。页面还说，这种事不常见，但确实有人在走回公路的路上，死于暴露在酷热或寒冷里。优先级分五步。第一步是报平安和坐标，有信号时先发位置再打电话。第二步是遮阳保暖，车是最大的遮蔽物。第三步是水，白天不动、夜里凉了再动。第四步是不乱走。第五步是信号。重庆市应急管理局的提示是：摆成三角形的三堆火是国际通行的求救信号。离得近就喊「三声短、三声长、再三声短」，隔 1 分钟重复。有太阳时用镜子、罐头盖这类亮东西反光。文化和旅游部提醒自驾游客谨慎前往无人区，尽量多车同行，必要时租卫星电话', 'C 级原因是这些都是官方提示，不是研究数据。饮水量、报备、信号覆盖、待在车旁、求救信号都是官方原话。流传的「三声一组」没有找到官方原文，所以改写成官方的三堆火和三短三长三短。不要在正午徒步找路。不要喝尿。不要为了省水而不喝。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","C 级","性价比 一般","口径 死亡率","钱 多","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-28', 'concept_archive_s13-28', 'claim_archive_s13-28', 'action', 'life_archive', '发抖、说话含糊、走路打晃是失温，换掉湿衣、包起来，先暖躯干，喝热甜饮不喝酒', '13. 紧急情况：先做什么', '体温降到 35℃ 以下就是失温，人会发抖、说话含糊、走路打晃、想不清楚事。换掉湿衣服，用保温毯或者干衣裹起来，先暖躯干、不先暖手脚。给热的甜饮料，不给酒，酒会压住寒战。不抖了不是好转，是加重。没有意识就做心肺复苏。', '不要搓手脚。不要泡热水澡。不要硬拖硬拽地搬，失温重的人心脏容易骤停。不要因为「不抖了」就以为好转，不打哆嗦（寒战停止）是加重。荒野医学会指南全文需订阅，本次只核实了摘要。', NULL, NULL, NULL, '一张铝箔保温毯几元，再加一件备用干衣。学会看信号不花钱。', '美国国家气象局原文：体温 95°F（35°C）以下就是失温，「觉得冷、迟钝、想不清楚，立刻看医生」。处理是「立即就医，把人移到有暖气的室内，先从身体中心开始复温」，给热饮。「酒精会减少寒战」，所以不喝。「失去意识做心肺复苏」。冻伤用温水或者体温回暖，「不要用热水或壁炉一类辐射热」。荒野医学会 2019 年失温指南是这个领域的执业指南', '不要搓手脚。不要泡热水澡。不要硬拖硬拽地搬，失温重的人心脏容易骤停。不要因为「不抖了」就以为好转，不打哆嗦（寒战停止）是加重。荒野医学会指南全文需订阅，本次只核实了摘要。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-29', 'concept_archive_s13-29', 'claim_archive_s13-29', 'action', 'life_archive', '被蛇咬，坐下别动、摘掉戒指手表、尽快送医院打抗蛇毒血清，不切、不吸、不绑死', '13. 紧急情况：先做什么', '坐下别动，把被咬的肢体固定住。先摘掉戒指手表，接下来会肿。尽快送到有抗蛇毒血清的医院，血清是唯一能逆转大部分毒性作用的东西。不切开，不用嘴吸，不冰敷，不用绳子勒到发紫。别喝酒，别跑动。能远远拍张蛇的照片就拍，别去抓。', '能拍到蛇的照片就拍，别去抓。不要喝酒，不要跑动，不要用嘴吸，不要冰敷，不要用绳子勒到发紫。中国的全国蛇伤死亡数没有官方统计。那 11 个省的住院死亡率看着低，但有一成多病人没治完就自己出院了，他们后来怎样不在统计里。', NULL, NULL, NULL, '不花钱。提前知道附近哪家医院有抗蛇毒血清。难的是忍住自己动手处理伤口。', 'WHO 原文有三句。一句是「立即完全固定被咬的身体部位，并迅速送到最近的医疗机构就医」。一句是「避免使用止血带，并避免切割伤口」。还有一句是「用针对当地蛇种的适当抗蛇毒血清进行治疗」。「高质量抗蛇毒血清是防止或逆转蛇咬伤的大部分毒性作用的最有效治疗方法」。全球每年约 8.1 万到 13.8 万人死于蛇咬伤，截肢和永久残疾的人数约为死亡数的 3 倍。中国 2024 年的蛇伤救治指南估计，国内每年有 25 万到 28 万例毒蛇咬伤，被咬的多是 50 岁以上的人。长江流域和南方 11 个省的医院 2017 到 2021 年收治了 40817 名蛇伤病人，住院期间死亡 23 人（0.06%）', '能拍到蛇的照片就拍，别去抓。不要喝酒，不要跑动，不要用嘴吸，不要冰敷，不要用绳子勒到发紫。中国的全国蛇伤死亡数没有官方统计。那 11 个省的住院死亡率看着低，但有一成多病人没治完就自己出院了，他们后来怎样不在统计里。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-30', 'concept_archive_s13-30', 'claim_archive_s13-30', 'action', 'life_archive', '地震时先看自己在什么房子里：符合抗震设防的楼里就地躲，会垮的老房子门在几步外就出去', '13. 紧急情况：先做什么', '先看自己在什么房子里。2001 年以后按规范建的楼，要下楼梯、穿门厅才能出去的，就地躲：护住头颈钻到结实桌子下面，抓牢桌腿。平房、老砖房、没抗震设防的自建房，门就在几步外，出去。任何情况都不跳楼、不坐电梯、不在摇晃中下楼梯。', '争议，两种结论针对的是两种房子。中国地震局自己也把「躲」的前提写成了「符合抗震设防要求的建筑内」。它还要求「因地制宜」「因人而异」，一起看楼抗不抗震、你人在哪个位置、自己跑不跑得动。亚美尼亚那批楼整栋垮塌，躲无处可躲，出去才占优。美国 FEMA 对本国住宅给的是「就地趴下、护住头颈、抓牢，不要往外跑」，那里的伤主要来自坠物和摇晃中移动摔倒。Northridge 的研究还提示，伸手去接东西、扶住「看起来稳」的东西会加重受伤。所以光问「跑不跑」没用，要判断「这栋楼会不会垮、你几秒内能不能到空地」。2001 年以后按规范建的楼房，需要下楼梯或者穿门厅的，就地躲。平房、老旧砖房、无抗震设防的自建房，门就在几步外，出去。亚美尼亚这项研究只比了幸存者中受伤与未受伤的，没把遇难者算进去，也没说明有没有把楼层高低的影响扣掉。能跑出去的人本来就可能住在低层，数字要打折看。任何情况下都不跳楼、不坐电梯、不在摇晃中下楼梯。到室外要远离高大建筑、高架桥、电线杆、玻璃幕墙和广告牌。', NULL, NULL, NULL, '不花钱。提前看一眼自己家出门要几步、走哪条路、哪张桌子结实。', '中国地震局科普片《地震来了，是躲还是跑？》的口诀是「震时就近躲避，震后迅速撤离」，并明确限定「这里指的是在符合抗震设防要求的建筑内」。理由是这类建筑「整体垮塌的可能性较小」。原文说「坠落的建筑构件及装饰物品」「才是对生命安全最大的威胁」。而「震时无保护措施的盲目乱跑」「反而容易被坠落的天花板、吊灯（扇）等物品砸伤」。躲的做法是「用手或者其他软物保护好头颈部」「并牢牢地抓住桌腿」；没有桌子就「迅速贴紧承重墙蹲伏」「避开外墙、窗户、阳台」。「如果在户外」则「应该第一时间疏散到空旷的地方避震」。反过来看，1988 年亚美尼亚地震是苏联式预制板楼成片垮塌。那次的病例对照研究写着，「第一下震动之后离开建筑是保护性行为」。待在室内的人受伤的可能性，是跑出去的 4.40 倍（比值比 4.40），95% CI 2.24–8.71（可信范围）。在建筑里受伤的可能性，是在室外的 12.20 倍（3.62–63.79）。在 5 层以上的楼里，是在更矮的楼里的 3.65 倍（2.12–6.33）', '争议，两种结论针对的是两种房子。中国地震局自己也把「躲」的前提写成了「符合抗震设防要求的建筑内」。它还要求「因地制宜」「因人而异」，一起看楼抗不抗震、你人在哪个位置、自己跑不跑得动。亚美尼亚那批楼整栋垮塌，躲无处可躲，出去才占优。美国 FEMA 对本国住宅给的是「就地趴下、护住头颈、抓牢，不要往外跑」，那里的伤主要来自坠物和摇晃中移动摔倒。Northridge 的研究还提示，伸手去接东西、扶住「看起来稳」的东西会加重受伤。所以光问「跑不跑」没用，要判断「这栋楼会不会垮、你几秒内能不能到空地」。2001 年以后按规范建的楼房，需要下楼梯或者穿门厅的，就地躲。平房、老旧砖房、无抗震设防的自建房，门就在几步外，出去。亚美尼亚这项研究只比了幸存者中受伤与未受伤的，没把遇难者算进去，也没说明有没有把楼层高低的影响扣掉。能跑出去的人本来就可能住在低层，数字要打折看。任何情况下都不跳楼、不坐电梯、不在摇晃中下楼梯。到室外要远离高大建筑、高架桥、电线杆、玻璃幕墙和广告牌。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-31', 'concept_archive_s13-31', 'claim_archive_s13-31', 'action', 'life_archive', '遇到熊、野猪、成群野狗，别跑、别尖叫、别对视，侧身慢慢退开', '13. 紧急情况：先做什么', '别跑，熊上下坡都跑得像赛马。也别爬树，黑熊棕熊都会爬。站住，低声一直跟它说话，等它不动了再侧身慢慢退开。棕熊扑上来就趴下装死，双手扣在颈后、两腿分开。黑熊扑上来不装死，往车里或屋里跑，跑不掉就拿手边东西反击。被狗抓咬按第 13 条冲洗打针。', 'B 级只对应熊。野猪和野狗的「不跑、慢退、找高处或者障碍物挡」是经验，算 C 级，国家林草局和地方林草的官方提示本次未找到。不要拿食物引，不要凑近拍照，不要带狗进有野猪的山。中国的熊多是黑熊和棕熊，装死还是不装死，按这两种分开看。', NULL, NULL, NULL, '不花钱。进山带根登山杖，结伴走、出声走，让动物先知道你来了。难的是站住不跑。', '美国国家公园管理局关于熊的原文有六句。一句是「不要跑，熊上下坡都能跑得像赛马一样快」。一句是「保持冷静，大多数熊不想攻击你，只想被放着不管」。一句是「用低沉的声音持续跟熊说话」。一句是「熊不动时，侧着身慢慢退开，这样既能盯着熊又不会绊倒」。一句是「让自己显得尽量大」。还有一句是「不要爬树，灰熊和黑熊都会爬树」。被棕熊攻击时「装死，趴着双手扣在颈后、双腿分开」。被黑熊攻击时「不要装死，逃向车或房子，逃不了就用手边任何东西反击」。被狗咬伤按第 13 条处理', 'B 级只对应熊。野猪和野狗的「不跑、慢退、找高处或者障碍物挡」是经验，算 C 级，国家林草局和地方林草的官方提示本次未找到。不要拿食物引，不要凑近拍照，不要带狗进有野猪的山。中国的熊多是黑熊和棕熊，装死还是不装死，按这两种分开看。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-32', 'concept_archive_s13-32', 'claim_archive_s13-32', 'action', 'life_archive', '野外遇上雷雨，钻进有硬顶的车或建筑，避开山脊、孤树、水面和金属', '13. 紧急情况：先做什么', '雷暴范围内的户外没有安全的地方。钻进硬顶的车或者建筑，敞篷车、摩托、帐篷、凉亭、树下、突出的岩石下面都不算。避开开阔地、山脊山顶、孤立的大树、水面和铁栏杆。一群人走不了就散开站。听见雷就撤，最后一声雷过去 30 分钟才算安全。', '帐篷、凉亭、树下、岩石突出部都不算掩体。硬顶汽车算，敞篷车和摩托不算。听见雷就开始撤，不要等雨下下来。', NULL, NULL, NULL, '不花钱。代价是行程被打断半小时以上。难的是雷声还远的时候就肯往回走。', '雷暴范围内的户外没有安全的地方。最后一声雷响过 30 分钟，才算安全', '帐篷、凉亭、树下、岩石突出部都不算掩体。硬顶汽车算，敞篷车和摩托不算。听见雷就开始撤，不要等雨下下来。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-33', 'concept_archive_s13-33', 'claim_archive_s13-33', 'action', 'life_archive', '上高原按睡眠海拔（当晚睡在多高）慢慢升，症状加重就下撤，不要硬扛', '13. 紧急情况：先做什么', '算的是睡在多高，不是白天到过多高。睡在 2450 米以上就有高原病风险。过了 3000 米之后，每晚睡觉的高度只往上加 500 米，每升 1000 米多留一天适应。头痛加恶心、走路打晃、意识变化，或者不动也喘不上气，就往下走。下撤排在吸氧和吃药前面。', '算的是「睡在多高」，不是白天到过多高。头痛加恶心、走路打晃、意识变化，或者不动也喘不上气，都是往下走的信号。下撤优先于吸氧和吃药，吸着氧继续往上是错的。', NULL, NULL, NULL, '多花一到两天做适应。预防药是处方药，要在出发前问医生。难的是行程排得紧时还肯留出这几天。', '睡在 2450 米以上就有高原病风险。高原脑水肿和肺水肿（脑子和肺里积水），不及时往低处撤会死', '算的是「睡在多高」，不是白天到过多高。头痛加恶心、走路打晃、意识变化，或者不动也喘不上气，都是往下走的信号。下撤优先于吸氧和吃药，吸着氧继续往上是错的。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-34', 'concept_archive_s13-34', 'claim_archive_s13-34', 'action', 'life_archive', '被蜱虫叮住，用尖头镊子贴着皮肤稳稳拉出来，别涂油别用火烧', '13. 紧急情况：先做什么', '用尖头镊子贴着皮肤夹住蜱的头部，稳稳地朝外拉出来。别涂油，别用火烧，别扭着拽，那会刺激它把带病原体的体液挤进皮肤，还容易把口器留在肉里。拔完记下日期。之后几周里发烧、起疹、乏力，看病时主动说被蜱咬过。', '拔完把日期记下来。之后几周里发烧、起皮疹、乏力，看病时主动说被蜱咬过。医生不问、你不说，很容易被按感冒处理。', NULL, NULL, NULL, '一把尖头镊子。', '涂油、用火烧、扭着拽，会刺激蜱虫，把带病原体的体液挤进皮肤。这么做也容易把它扎在肉里的那部分嘴（口器）留在里面。蜱虫在中国传的发热伴血小板减少综合征，2024 年全国报告 6602 例、死亡 306 例，都是发现这种病以来最多的一年。2010 到 2024 年平均病死率 4.79%，年纪越大越高，85 岁以上是 9.15%', '拔完把日期记下来。之后几周里发烧、起皮疹、乏力，看病时主动说被蜱咬过。医生不问、你不说，很容易被按感冒处理。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-35', 'concept_archive_s13-35', 'claim_archive_s13-35', 'action', 'life_archive', '野外的水一律烧开再喝，滚开一分钟就够，不用因为海拔高多煮', '13. 紧急情况：先做什么', '所有能靠喝水致病的微生物，在沸点温度下几秒就死了。再滚一分钟，只是给「看走眼」留的余量，不用因为海拔高就多煮。烧不了就用过滤器或者消毒片，这两样各有覆盖不到的病原体，能烧还是烧。看着清澈的溪水、雪水一样可能有寄生虫。', '同一页也写了不必真的烧开：60 ℃ 保持 30 分钟同样有效，烧开只是不用温度计就能看见的终点。烧不了就用过滤器或者化学消毒片，两者各有覆盖不到的病原体，能烧就烧。看起来清澈的溪水、雪水一样可能有寄生虫，别凭外观判断。', NULL, NULL, NULL, '多背一套炉具和燃料的重量。', '所有能靠喝水致病的微生物，在水烧开的温度下几秒就被杀死（灭活）。「高海拔水烧不到位」是常见误解', '同一页也写了不必真的烧开：60 ℃ 保持 30 分钟同样有效，烧开只是不用温度计就能看见的终点。烧不了就用过滤器或者化学消毒片，两者各有覆盖不到的病原体，能烧就烧。看起来清澈的溪水、雪水一样可能有寄生虫，别凭外观判断。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-36', 'concept_archive_s13-36', 'claim_archive_s13-36', 'action', 'life_archive', '荒郊野外被陌生人索财，钱给他，不动手，记特征，脱身后报警', '13. 紧急情况：先做什么', '钱给他，不动手，不还嘴。对方为几百块冒的是抢劫罪：三年以上十年以下起步，入户、持枪、致人重伤死亡的十年以上，直到死刑。他拿了钱转身走，你追上去打就不再算正当防卫。脱身后立刻记下体貌、口音、车牌和逃跑方向，打 110。', 'C 级原因是「给钱不对抗更安全」没有直接文献，法条只说明对方的风险和你的边界。不要跟去偏僻处「取钱」。不要交手机密码。不要上对方的车。先给钱只限当面被堵住、人身安全受威胁的场合，脱身后照样报警。网上被人拿隐私照片、裸聊录像来要钱是反过来的，一分钱都不能给，见第 8 节第 32 条（对方拿把柄来要钱）。别指望随身带的甩棍、电击器、匕首，带着出门本身就会被罚，见第 9 节第 26 条（别为了防身买甩棍、电击器）。', NULL, NULL, NULL, '身上的现金。难的是压住火气。', '命比钱贵，对方为几百元冒的是重罪。刑法第二百六十三条规定，以暴力、胁迫或者其他方法抢劫公私财物的，处三年以上十年以下有期徒刑并处罚金。持枪、入户、致人重伤死亡等情形，判十年以上直至死刑。刑法第二十条的正当防卫只保护「制止正在进行的不法侵害」。对方拿了钱转身走，你追上去打就不再是防卫。脱身后立刻记下体貌、口音、车牌、逃跑方向，打 110', 'C 级原因是「给钱不对抗更安全」没有直接文献，法条只说明对方的风险和你的边界。不要跟去偏僻处「取钱」。不要交手机密码。不要上对方的车。先给钱只限当面被堵住、人身安全受威胁的场合，脱身后照样报警。网上被人拿隐私照片、裸聊录像来要钱是反过来的，一分钱都不能给，见第 8 节第 32 条（对方拿把柄来要钱）。别指望随身带的甩棍、电击器、匕首，带着出门本身就会被罚，见第 9 节第 26 条（别为了防身买甩棍、电击器）。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-37', 'concept_archive_s13-37', 'claim_archive_s13-37', 'action', 'life_archive', '撞见一群人打架，退开走人，别上去拉架、别围观、别捡地上的家伙；要报警就退到安全距离打 110', '13. 紧急情况：先做什么', '你一动手，劝架就成了参加打架。参加聚众斗殴判 3 年以下，人多、在马路上、拿了家伙的判 3 到 10 年。围观也容易被误伤。该做的是退开走人。愿意报警就退到安全距离打 110，说清地点、几个人、有没有拿刀棍、有没有人躺下不动。', '定 B 是因为后果那一半有硬条文，但「退开报警、不上手拉架」这一步没有官方原文，是从条文和「互殴怎么认定」推出来的。「我是来劝架的」不是护身符，认定看的是你动没动手、打了谁。对方已经倒地或者跑了，你还追上去打，就不再算防卫。看到有人被围着单方面挨打，法律上你确实可以制止。正当防卫保护的不只是自己，也包括别人。但徒手上去多半只是再添一个伤员。喊人、远远录像、报警更管用。「不上手、不围观」对你只有好处。打 110 的好处主要落在地上那个人身上，属于本书受益人里最低的那一档，愿不愿意花这个时间你自己权衡。权衡之前要知道几件事。作证义务本来就有：刑诉法第六十二条写明，凡是知道案件情况的人都有作证的义务，不打这个电话它也不会消失。出了重伤或者人命，警方调监控照样找到在场的人，站着围观反而最容易被登记。报案人不愿公开姓名的，办案机关「应当为他保守秘密」（第一百一十一条）。说清地点、人数、有没有拿家伙就可以挂，不必留在原地。会走到训诫或者十日以下拘留的，是法院通知你出庭、你又拿不出正当理由还不肯作证（第一百九十三条），路人极少走到这一步。不报警本身不违法：刑诉法第一百一十条那句「有权利也有义务」没有罚则，刑法里也没有处罚普通人知情不报的罪名，走开是合法选项。走开之后的红线只有两条。一是事后帮着藏人或者作假证明包庇（刑法第三百一十条，3 年以下，情节严重 3 到 10 年）。二是被找去做证时故意作假证（第三百零五条，3 年以下，情节严重 3 到 7 年）。沉默和如实说都没事，编话才有事。自己被卷进冲突见第 8 节第 10 条，被陌生人索财见本节第 36 条，救人受伤之后的钱见本节第 39 条。', NULL, NULL, NULL, '不花钱。难的是忍住上前拉一把、以及站着看热闹这两种冲动。报警之后可能被回访做一次笔录，最多搭进半天。', '刑法第二百九十二条：「聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制」。多次聚众斗殴的，人数多规模大社会影响恶劣的，在公共场所或者交通要道造成社会秩序严重混乱的，持械的，「处三年以上十年以下有期徒刑」。「聚众斗殴，致人重伤、死亡的」，按故意伤害罪、故意杀人罪定罪处罚。治安管理处罚法也有罚则。殴打他人，拘留 5 到 10 日并罚 500 到 1000 元。结伙斗殴按寻衅滋事处理，最高拘留 15 日并罚 2000 元。《关于依法适用正当防卫制度的指导意见》第 5 条：不法侵害「既包括针对本人的不法侵害，也包括危害国家、公共利益或者针对他人的不法侵害」。该意见第 9 条：一方先动手且手段明显过激，或者一方先动手、在对方努力避免冲突的情况下仍继续侵害的，还击一方一般应当认定为防卫行为', '定 B 是因为后果那一半有硬条文，但「退开报警、不上手拉架」这一步没有官方原文，是从条文和「互殴怎么认定」推出来的。「我是来劝架的」不是护身符，认定看的是你动没动手、打了谁。对方已经倒地或者跑了，你还追上去打，就不再算防卫。看到有人被围着单方面挨打，法律上你确实可以制止。正当防卫保护的不只是自己，也包括别人。但徒手上去多半只是再添一个伤员。喊人、远远录像、报警更管用。「不上手、不围观」对你只有好处。打 110 的好处主要落在地上那个人身上，属于本书受益人里最低的那一档，愿不愿意花这个时间你自己权衡。权衡之前要知道几件事。作证义务本来就有：刑诉法第六十二条写明，凡是知道案件情况的人都有作证的义务，不打这个电话它也不会消失。出了重伤或者人命，警方调监控照样找到在场的人，站着围观反而最容易被登记。报案人不愿公开姓名的，办案机关「应当为他保守秘密」（第一百一十一条）。说清地点、人数、有没有拿家伙就可以挂，不必留在原地。会走到训诫或者十日以下拘留的，是法院通知你出庭、你又拿不出正当理由还不肯作证（第一百九十三条），路人极少走到这一步。不报警本身不违法：刑诉法第一百一十条那句「有权利也有义务」没有罚则，刑法里也没有处罚普通人知情不报的罪名，走开是合法选项。走开之后的红线只有两条。一是事后帮着藏人或者作假证明包庇（刑法第三百一十条，3 年以下，情节严重 3 到 10 年）。二是被找去做证时故意作假证（第三百零五条，3 年以下，情节严重 3 到 7 年）。沉默和如实说都没事，编话才有事。自己被卷进冲突见第 8 节第 10 条，被陌生人索财见本节第 36 条，救人受伤之后的钱见本节第 39 条。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-38', 'concept_archive_s13-38', 'claim_archive_s13-38', 'action', 'life_archive', '可能被 HIV 暴露了，72 小时内去拿阻断药，越早越好', '13. 紧急情况：先做什么', '怀疑自己被传染上艾滋病，72 小时是硬线，最好 2 小时内就吃上药。药要连吃 28 天。超过 72 小时这条路就没了，所以别等到第二天再决定。', '去哪里拿：当地疾控中心指定的艾滋病定点医疗机构，通常挂感染科（性病艾滋病门诊）。不少城市已经建了 24 小时门诊，重庆的公开数据是 26 个区县 29 家门诊，其中 14 家全天候。去之前打当地疾控电话问哪家有药，别在急诊科耗时间。算「暴露」的情况包括没做防护的性行为、安全套破了、被针头扎到、血沾到黏膜上，到底用不用药由医生判断。药必须吃满 28 天，漏几次会让效果明显变差。之后按医嘱在第 4 至 6 周、3 个月复查。阻断药只是补救，日常预防和检测见第 1 节第 30、31 条（全程用安全套、有过高危行为就去查）。', NULL, NULL, NULL, '一个 28 天疗程的药费上千元，多数地区自费。当晚就得跑一趟医院。难的是当场承认自己可能被传染，立刻出门。', '北京市人民政府防艾科普栏目的口径是：接触之后的预防用药叫暴露后预防（英文缩写 PEP），应「尽可能在 2 小时内进行预防性用药，最好在 24 小时内、不超过 72 小时」。还要「连续服用 28 天」。超过 72 小时就不再建议启动，这是一条硬时限', '去哪里拿：当地疾控中心指定的艾滋病定点医疗机构，通常挂感染科（性病艾滋病门诊）。不少城市已经建了 24 小时门诊，重庆的公开数据是 26 个区县 29 家门诊，其中 14 家全天候。去之前打当地疾控电话问哪家有药，别在急诊科耗时间。算「暴露」的情况包括没做防护的性行为、安全套破了、被针头扎到、血沾到黏膜上，到底用不用药由医生判断。药必须吃满 28 天，漏几次会让效果明显变差。之后按医嘱在第 4 至 6 周、3 个月复查。阻断药只是补救，日常预防和检测见第 1 节第 30、31 条（全程用安全套、有过高危行为就去查）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 死亡率","钱 多","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-39', 'concept_archive_s13-39', 'claim_archive_s13-39', 'action', 'life_archive', '救人受了伤、搭进了钱，先找加害人和医保，再去申报见义勇为确认', '13. 紧急情况：先做什么', '救人把自己搭进去，不用自认倒霉。见义勇为负伤的先救治、后收费。医疗费由加害人出，人跑了或者赔不起的走基本医保。没有加害人的，被你救下的人依法应当给适当补偿。同时去申报见义勇为确认，受了伤的按工伤保险待遇落实。', '定 B 是因为能拿什么待遇由全国文件定死，但奖金给多少、怎么走认定，是各省自己的见义勇为条例说了算，数字各地不同，本轮未逐省核实。一般是向出事地方的公安机关或者见义勇为工作机构（基金会）申报。能不能认定靠证据：报警回执、现场监控、目击者的姓名和电话、医院病历，当场就留下来。要打官司，见义勇为的民事权益本来就在免费法律援助的范围内。一次性工亡补助金的全国标准和伤残等级怎么换算成钱，见第 19 节第 14、15 条。法律援助怎么申请见第 7 节第 3 条。', NULL, NULL, NULL, '不花钱。申报要交材料、等认定，跑几趟，几周到几个月。', '民法典第一百八十三条：「因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿」。国办发〔2012〕39 号讲了见义勇为负伤人员怎么办。医疗机构要建立绿色通道，「坚持『先救治、后收费』的原则」。医疗费这一块的原文是「因紧急救治发生的医疗费用，有加害人或责任人的，由加害人或责任人承担；无加害人或责任人以及加害人或责任人逃逸或者无力承担的，按规定通过基本医疗保障制度解决」。死亡的，「符合烈士评定条件的，依法评定为烈士」；「属于视同工伤情形的，享受一次性工亡补助金以及相当于本人 40 个月工资的遗属特别补助金」。伤残的，「符合享受工伤保险待遇条件的，依据《工伤保险条例》落实相应待遇；不符合的，由民政部门评定伤残等级并落实相应待遇」。就业上「优先纳入就业援助，予以重点支持」，公益性岗位「优先安排符合条件的见义勇为人员」。住房上「优先纳入住房保障体系，优先配租、配售保障性住房或发放住房租赁补贴」', '定 B 是因为能拿什么待遇由全国文件定死，但奖金给多少、怎么走认定，是各省自己的见义勇为条例说了算，数字各地不同，本轮未逐省核实。一般是向出事地方的公安机关或者见义勇为工作机构（基金会）申报。能不能认定靠证据：报警回执、现场监控、目击者的姓名和电话、医院病历，当场就留下来。要打官司，见义勇为的民事权益本来就在免费法律援助的范围内。一次性工亡补助金的全国标准和伤残等级怎么换算成钱，见第 19 节第 14、15 条。法律援助怎么申请见第 7 节第 3 条。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-40', 'concept_archive_s13-40', 'claim_archive_s13-40', 'action', 'life_archive', '刀、钢筋、玻璃扎进身体，压住异物周围止血，不要把它拔出来', '13. 紧急情况：先做什么', '拔出来可能造成大出血，也会让医生更难判断伤了多深。做法是：打 120，用手或者敷料压住异物周围止血，把异物垫稳别让它晃。肚子上的伤口有内脏露出来，不要往回塞，盖一块干净的湿敷料。胸口的伤口在冒泡的，别用塑料布封死，封死可能把肺压瘪。', '定 B 是因为这是指南里的公认做法，没有随机试验，总不能把伤者分成「拔」和「不拔」两组来试。唯一的例外是异物堵住气道、人喘不上气。到了医院直接找急诊门口那张分轻重缓急的台子（预检分诊台），报「穿透伤」。这属于要立刻进抢救室的那一级，不要去挂号窗口排队（见第 24 节第 7 条）。真扎穿了就打 120，救护车会提前通知医院准备接诊。大出血怎么压、怎么上止血带见第 12 条。', NULL, NULL, NULL, '不花钱。难的是忍住「先拔出来」的本能，守着人等救护车。', '国际红十字与红新月会联合会 2025 年国际急救指南：「急救的人应当压住扎进身体的异物（比如刀）周围，把异物稳住，不要把它拔出来」。「不要从腹部或胸部的伤口里拔出任何扎入的异物，拔出来可能造成大出血，也会让医生更难判断伤得有多重」。「扎在身体里的异物应当稳住；异物随脉搏跳动的，就让它跳，松松地稳住即可」。「急救的人不应把露出来的内脏塞回体内」。没有在往外涌血的开放性胸壁伤口「可以敞着、不加敷料，因为把伤口封死可能让空气积在胸腔里，使肺部分或完全塌陷（气胸）」。所有穿透性胸腹部伤口都应立即呼叫急救', '定 B 是因为这是指南里的公认做法，没有随机试验，总不能把伤者分成「拔」和「不拔」两组来试。唯一的例外是异物堵住气道、人喘不上气。到了医院直接找急诊门口那张分轻重缓急的台子（预检分诊台），报「穿透伤」。这属于要立刻进抢救室的那一级，不要去挂号窗口排队（见第 24 节第 7 条）。真扎穿了就打 120，救护车会提前通知医院准备接诊。大出血怎么压、怎么上止血带见第 12 条。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-41', 'concept_archive_s13-41', 'claim_archive_s13-41', 'action', 'life_archive', '怀疑骨折就别再动那个部位，托着不动、冷敷 20 分钟以内，别自己掰正', '13. 紧急情况：先做什么', '手脚受了伤先当骨折处理，能站能动也排除不了。伤处保持不动，用手托住或用硬板在原位撑住，冷敷一次不超过 20 分钟。别自己掰正，骨头戳出皮肤的先止血，别按回去。X 光可能漏看骨折。片子正常但医生仍怀疑骨折或者韧带伤的，按医生说的复查或做核磁。', '定 B 是因为这些都是公认做法。送医院之前给股骨（大腿骨）骨折做牵引固定，只有一项翻旧病历的研究撑着，证据可信度很低。结果是 24 小时内输血量更少、住院更短，死亡和并发症的差别小到说不清。至于先复位（把骨头对回原位）还是原样固定，根本没找到证据。三个常见误解要改掉：能站能走不等于没骨折；只用冷不用热，也不要冷热交替；扭伤不会「活动开就好了」，先歇着。骨头没长好之前别抽烟，见第 2 节第 1 条（戒烟）。别指望猛补钙、喝骨头汤让骨头长得快，见第 6 节第 30 条（骨折之后猛补钙）。老人跌倒后怀疑骨折的搬动禁忌见第 2 条。打了石膏或者卧床之后一条腿肿起来要警惕血栓，见第 11 条。治完之后要不要做伤残鉴定、要不要办残疾人证，见第 24 节第 9、10 条。', NULL, NULL, NULL, '不花钱。找块硬板、卷起的杂志或者衣物当支撑。冷的东西隔层布敷。', '国际红十字与红新月会联合会发布了 2025 年国际急救指南。里面写着「手脚上的任何一处伤，都应当先按可能的骨折来处理」。还写着「确诊骨折唯一准确的办法是拍 X 光。拿不准就当骨折办」。固定的目的是「尽量减少活动和疼痛」。冷敷「一次最多连续 20 分钟，这样可以减轻疼痛；冷得比这更久可能损伤皮肤」。「伤到股骨这类长骨时，光是骨头本身出的血就可能致命」。疼痛或者肿胀明显、有休克表现、股骨（大腿骨）骨折或者肢体位置明显不对时，应呼叫急救。折弯成角的骨折，要两个条件同时成立，才考虑在现场掰回原位（复位）。一是「地处偏远（或者条件有限），而且成角处下方的肢体发凉、发白，或者急救的人没法固定好以便搬动」。二是施救者受过训练。开放性骨折（断骨戳破皮肤）的优先事项是止血和防感染。但第一次 X 光没看出来，不等于没骨折。英国国家卫生与临床优化研究所（NICE）的髋部骨折指南写：X 光正常但仍怀疑髋部骨折的，「做磁共振（核磁）」。24 小时内做不了，就考虑做 CT。它的骨折指南写：怀疑手腕舟骨骨折的，「经过仔细的体格检查后，考虑首先做磁共振」。舟骨是手腕里的一块小骨头。考克兰（Cochrane）的一篇文献汇总说：「最初的 X 光片不能排除骨折」。它收的研究里，X 光正常、医生仍怀疑舟骨骨折的人，真有骨折的比例中位数是 20%。美国放射学会有一份膝关节外伤的检查标准。它写：X 光没看到骨折，但仍怀疑有隐藏骨折或关节内部损伤的，下一步「通常适合」做磁共振。它还写，磁共振查隐藏骨折、半月板和韧带损伤都很准', '定 B 是因为这些都是公认做法。送医院之前给股骨（大腿骨）骨折做牵引固定，只有一项翻旧病历的研究撑着，证据可信度很低。结果是 24 小时内输血量更少、住院更短，死亡和并发症的差别小到说不清。至于先复位（把骨头对回原位）还是原样固定，根本没找到证据。三个常见误解要改掉：能站能走不等于没骨折；只用冷不用热，也不要冷热交替；扭伤不会「活动开就好了」，先歇着。骨头没长好之前别抽烟，见第 2 节第 1 条（戒烟）。别指望猛补钙、喝骨头汤让骨头长得快，见第 6 节第 30 条（骨折之后猛补钙）。老人跌倒后怀疑骨折的搬动禁忌见第 2 条。打了石膏或者卧床之后一条腿肿起来要警惕血栓，见第 11 条。治完之后要不要做伤残鉴定、要不要办残疾人证，见第 24 节第 9、10 条。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-42', 'concept_archive_s13-42', 'claim_archive_s13-42', 'action', 'life_archive', '被性侵之后，先到安全的地方打 110；验伤之前别洗澡、别洗衣服、别收拾房间，72 小时内去医院', '13. 紧急情况：先做什么', '身上、衣服上和屋里留下的痕迹，是指认对方最要紧的证据。所以验伤前尽量别洗澡，也别洗衣服、收拾房间，尽早打 110。紧急避孕药药店就有，越早吃越有效。72 小时内去医院，让医生判断要不要吃阻断药。', '给 B 是因为这些是官方的办案经验和用药建议，没有「照做之后定罪率高多少」的数字。受益人主要是你自己和家人。紧急避孕药的 72 小时是国内说明书的口径，世界卫生组织说 5 天内都有用，但越晚越差，别拖。已经怀孕的，紧急避孕药没有作用。报警时如实说，不隐瞒，也不夸大。对方事后找你私了、给钱或者威胁你，都留下记录，别删。想好了再报警也可以，但证据会随时间消失。不管报不报警，都要在时限内去医院。录音见第 8 节第 41 条（录音）。对方事后拿照片、拿报警来要挟你，同样是犯罪，见第 8 节第 32 条（对方拿报警、发照片来要钱）。朋友出了这种事，陪对方去报警、去医院，别先劝对方洗个澡休息一下。', NULL, NULL, NULL, '报警不花钱。紧急避孕药是非处方药，药店就能买。阻断药一个疗程上千元，要不要吃由医生判断，见本节第 38 条（72 小时内去拿阻断药）。难的是当时很难开口，也很想马上洗个澡。', '北京市人民检察院的检察官说：「无论是未成年人还是成年人，遇到侵害，都应当第一时间拨打110报警」。及时报警、就医，「便于侦查机关及时勘查现场、提取物证痕迹、固定证据」。贵州省民政厅转载的人民日报防性侵手册写：「一旦不幸遭遇性侵害，最重要的事情就是留存证据」。要保留「体液、毛发、皮屑、通信记录等证据」，「被侵害后，不要擅自洗澡、洗衣物、收拾房间、扔东西」。熟人作案的，保留通话、通信记录。对方事后威胁或者收买，也要留下证据。北京市西城区人民检察院写的是：「在接受身体检查之前尽量不要洗澡」。世界卫生组织说，紧急避孕可以用在「女性在未采取有效的避孕保护措施时遭受性侵犯」的时候。建议在 5 天内用，越早越有效。含左炔诺孕酮（一种孕激素）的紧急避孕药，用过的女性怀孕率是 1.2% 到 2.1%。国内药店卖的左炔诺孕酮片是非处方药。武汉市卫健委的说法是：在无防护性生活后「72小时以内，服药越早，预防妊娠效果越好」。艾滋病阻断药要尽可能 2 小时内吃上，最晚不超过 72 小时（全国）', '给 B 是因为这些是官方的办案经验和用药建议，没有「照做之后定罪率高多少」的数字。受益人主要是你自己和家人。紧急避孕药的 72 小时是国内说明书的口径，世界卫生组织说 5 天内都有用，但越晚越差，别拖。已经怀孕的，紧急避孕药没有作用。报警时如实说，不隐瞒，也不夸大。对方事后找你私了、给钱或者威胁你，都留下记录，别删。想好了再报警也可以，但证据会随时间消失。不管报不报警，都要在时限内去医院。录音见第 8 节第 41 条（录音）。对方事后拿照片、拿报警来要挟你，同样是犯罪，见第 8 节第 32 条（对方拿报警、发照片来要钱）。朋友出了这种事，陪对方去报警、去医院，别先劝对方洗个澡休息一下。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-43', 'concept_archive_s13-43', 'claim_archive_s13-43', 'action', 'life_archive', '不满 1 岁的婴儿噎住哭不出声，趴着拍背 5 下、翻过来按胸口 5 下，轮着做，别按肚子', '13. 紧急情况：先做什么', '孩子还能咳、能哭出声，就让他自己咳，你在旁边盯着。哭不出声、脸发紫，就让人打 120，你把孩子脸朝下趴在前臂上，用掌根在两块肩胛骨中间拍 5 下。没出来就翻过来，在胸口正中快速按 5 下，两样轮着做，别按肚子。孩子没反应了就改做心肺复苏。', '定 B 是因为支撑这套手法的主要是病例报告，没有「照做能少死多少人」的数字。收益定「大」是凭判断：完全堵住的气道几分钟内就会让孩子心跳停下。受益的几乎都是自家孩子。1 岁以上的孩子和成人改按肚子，见本节第 26 条（噎住拍背加腹部冲击）。按胸口用什么手法，各家写法不同。美国指南和国内红十字新版用一只手的掌根，国际红十字用两个拇指，老教程用两根手指。2025 年美国指南因为两指按不够深，已经不再推荐它。急救时用哪种都比不按强。东西咳出来了也要去医院看，可能有碎块留在肺里。硬币、小玩具这类小东西放到孩子够不着的地方。孩子没反应之后怎么做，见本节第 44 条（婴儿心肺复苏）。', NULL, NULL, NULL, '不花钱。看一遍动作或者上一次婴儿急救课，几分钟到半天。难的是慌乱中先把孩子翻过来趴好。', '美国心脏协会和美国儿科学会出了 2025 年的儿童基础生命支持指南。指南写：窒息（比如异物堵住气道）「是婴儿和儿童的主要死因之一」。婴儿最常呛进去的是液体。还在咳、还能出声的是轻度，让孩子自己咳，同时盯着有没有变重。咳得很弱或者咳不出、哭不出、脸色发紫的是重度。重度要先叫急救，再「反复做 5 次拍背、接 5 次胸部冲击，直到异物出来或者婴儿失去反应」。指南不建议给婴儿做腹部冲击，因为可能伤到肚子里的脏器。胸部冲击现在推荐用一只手的掌根，因为它比原来的两指法按得更深。婴儿失去反应就开始心肺复苏，先按压，不摸脉搏。吹气前看得见的异物要取出来。指南明写「不要用手指盲目去掏」。国际红十字与红新月会联合会的 2025 年国际急救指南也是这一套。先在两肩胛骨之间用力拍最多 5 下，不行就把孩子翻过来按胸口最多 5 下，再不行马上叫急救。它按胸口用的是双手环抱、两个拇指按。福建省红十字应急救护培训中心说，1 岁以下婴儿要做「5 次背部拍击 + 5 次胸部冲击」。拍背时让婴儿俯卧在前臂上，头低于躯干', '定 B 是因为支撑这套手法的主要是病例报告，没有「照做能少死多少人」的数字。收益定「大」是凭判断：完全堵住的气道几分钟内就会让孩子心跳停下。受益的几乎都是自家孩子。1 岁以上的孩子和成人改按肚子，见本节第 26 条（噎住拍背加腹部冲击）。按胸口用什么手法，各家写法不同。美国指南和国内红十字新版用一只手的掌根，国际红十字用两个拇指，老教程用两根手指。2025 年美国指南因为两指按不够深，已经不再推荐它。急救时用哪种都比不按强。东西咳出来了也要去医院看，可能有碎块留在肺里。硬币、小玩具这类小东西放到孩子够不着的地方。孩子没反应之后怎么做，见本节第 44 条（婴儿心肺复苏）。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s13-44', 'concept_archive_s13-44', 'claim_archive_s13-44', 'action', 'life_archive', '不满 1 岁的婴儿没反应、没正常呼吸，开免提打 120，做婴儿心肺复苏：按 30 下吹 2 口气', '13. 紧急情况：先做什么', '拍脚底没反应、没正常呼吸，就开免提打 120，手不停。双手环抱胸口用两个拇指按，抱不住就用一只手的掌根，按下去约 4 厘米，每秒约 2 下。每按 30 下，嘴包住孩子口鼻吹 2 口气。婴儿心跳停多半是喘不上气引起的，做了带吹气的心肺复苏，活下来的更多。', '定 B 是因为存活的数字来自只跟踪记录的登记研究，而且算的是全体孩子，婴儿单独的数字摘要里没给。收益定「大」是按全体孩子的数字算的：活着出院从 9.5% 到 13.2%，相对多了约四成。受益的几乎都是自家孩子。和本节第 1 条（用力按压胸口）的区别有三点。一是婴儿要吹气，只按不吹对婴儿效果差。二是用两个拇指或一只掌根，按约 4 厘米，不用双手叠着压。三是一个人又没法边按边打电话时，先按再去打。先按多久各家不一：首都儿科研究所和美国指南的单人流程是 2 分钟，国际红十字是 1 分钟。手机开免提就没有这个问题。欧洲复苏委员会教的是先吹 5 口气再按，美国指南是先按后吹，两种都比不做强。国内老教程教两指按压，2025 年美国指南已经去掉了这种手法。噎住引起的，吹气前看一眼嘴里，看得见的异物才取，见本节第 43 条（婴儿噎住）。', NULL, NULL, NULL, '不花钱。婴儿心肺复苏要上课练一次，半天到一天。难的是对着孩子口鼻吹气，还有不敢用力按。', '美国心脏协会和美国儿科学会出了 2025 年的儿童基础生命支持指南。指南写：婴儿和儿童心跳骤停，主要原因仍是呼吸出了问题。在医院外心跳骤停的婴儿，活着出院的只有 6.6%。普通人遇到没反应、没正常呼吸、没有生命迹象的婴儿或儿童，「应当立即开始心肺复苏」，不要去摸脉搏。按压深度至少是胸廓前后径的三分之一，婴儿「约 1.5 英寸（4 厘米）」。频率每分钟 100 到 120 次。一个人做时，按 30 下吹 2 口气。两个人做时，按 15 下吹 2 口气。婴儿用一只手的掌根按，或者双手环抱、两个拇指按。环抱不住就用掌根。两根手指按的做法已经取消，因为按不够深。指南还写，院外心脏骤停的婴儿和儿童，按压之外再加吹气能提高存活。美国一个登记库统计了 3900 名 18 岁以下院外心脏骤停的孩子，59.4% 是婴儿。在场的人做了心肺复苏的，调整后活着出院的比例是 13.2%，没做的是 9.5%。调整后 OR 1.57（活下来的几率高约 57%），95% CI 1.25–1.96（可信范围）。在婴儿里，带吹气的心肺复苏和更高的存活有关，活下来的孩子脑子也恢复得更好。只按不吹的，结果和没人做差不多。国际红十字与红新月会联合会的 2025 年国际急救指南写：看婴儿有没有反应，要把孩子抱起来或者拍他的脚底。只有你一个人，就开免提自己打急救电话。手边没有能边按边打的电话，就先做 1 分钟心肺复苏再去打。首都儿科研究所有一篇科普，北京市卫健委转载了。它写：「如果只有1个人在场，先进行2分钟的心肺复苏后呼叫120救护车」。按压幅度「婴儿4cm」。1 岁以内吹气要「口对口鼻」', '定 B 是因为存活的数字来自只跟踪记录的登记研究，而且算的是全体孩子，婴儿单独的数字摘要里没给。收益定「大」是按全体孩子的数字算的：活着出院从 9.5% 到 13.2%，相对多了约四成。受益的几乎都是自家孩子。和本节第 1 条（用力按压胸口）的区别有三点。一是婴儿要吹气，只按不吹对婴儿效果差。二是用两个拇指或一只掌根，按约 4 厘米，不用双手叠着压。三是一个人又没法边按边打电话时，先按再去打。先按多久各家不一：首都儿科研究所和美国指南的单人流程是 2 分钟，国际红十字是 1 分钟。手机开免提就没有这个问题。欧洲复苏委员会教的是先吹 5 口气再按，美国指南是先按后吹，两种都比不做强。国内老教程教两指按压，2025 年美国指南已经去掉了这种手法。噎住引起的，吹气前看一眼嘴里，看得见的异物才取，见本节第 43 条（婴儿噎住）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"13. 紧急情况：先做什么","B 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-1', 'concept_archive_s14-1', 'claim_archive_s14-1', 'action', 'life_archive', '邮箱、支付、社交账号都开二次验证，优先用手机弹窗确认，其次才是短信验证码', '14. 账号与信息安全', '二次验证是指登录时除了密码，还要再确认一次是不是本人。用手机上弹个窗、你点一下确认的办法，九成以上的钓鱼盗号都被拦住了。靠回答「上次在哪登的」「备用邮箱是什么」这种老办法，钓鱼盗号只能拦下一成左右。', '同一项研究也发现，这类验证有时会把本人挡在外面。52% 的真用户第一次没登进去，不过最后有 97% 还是进去了。先给邮箱开这个功能，因为别的账号大多能用邮箱找回密码。验证码只自己用，替别人报码、刷脸会背上什么，见第 8 节第 45 条（念验证码）', NULL, NULL, NULL, '不花钱。每个账号设置一次，两三分钟就设完。', '谷歌统计了 35 万次真实的盗号尝试（也叫账号劫持）。一类是靠设备来验证，比如手机上弹窗让你点确认，或者插一把安全密钥。这一类拦下了「超过 94% 源于钓鱼的劫持尝试和 100% 的自动化劫持尝试」。钓鱼是指骗你在假网站上输密码，自动化是指机器拿泄露的密码批量去试。另一类是靠回答问题来验证，比如问你上次在哪登录、备用邮箱是什么。这一类「只拦下了低至 10% 的钓鱼劫持和 73% 的自动化劫持」', '同一项研究也发现，这类验证有时会把本人挡在外面。52% 的真用户第一次没登进去，不过最后有 97% 还是进去了。先给邮箱开这个功能，因为别的账号大多能用邮箱找回密码。验证码只自己用，替别人报码、刷脸会背上什么，见第 8 节第 45 条（念验证码）', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"14. 账号与信息安全","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-2', 'concept_archive_s14-2', 'claim_archive_s14-2', 'action', 'life_archive', '邮箱密码单独一个，不和任何网站重复', '14. 账号与信息安全', '别的网站被偷走的密码，会被人拿来直接登你的邮箱。邮箱一旦被人登进去，凡是能用邮箱找回密码的账号，都跟着一起丢。所以邮箱的密码要单独一个，别的地方一律不用。', '记不住就用浏览器自带的密码管理器。它替你记住每个网站的密码，比到处用同一个密码强得多。别把密码存在微信收藏或者备忘录里', NULL, NULL, NULL, '不花钱。用密码管理器存着就不用自己记。难的是要改掉一个密码到处用的老习惯。', '把别处泄露的账号和密码挨个拿来试着登，这叫撞库，是最省事的攻击方式，你的邮箱也会被这样试。邮箱一旦被人登进去，所有用它找回密码的账号一起丢。美国网络安全和基础设施安全局的建议是：每个账号用一个不同的强密码，至少 16 位，交给密码管理器存', '记不住就用浏览器自带的密码管理器。它替你记住每个网站的密码，比到处用同一个密码强得多。别把密码存在微信收藏或者备忘录里', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"14. 账号与信息安全","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-3', 'concept_archive_s14-3', 'claim_archive_s14-3', 'action', 'life_archive', '手机设锁屏密码，SIM 卡设 PIN 码', '14. 账号与信息安全', 'SIM 卡就是手机里那张小卡片，短信验证码靠它来收。手机丢了，捡到的人会把这张卡拔下来，插进别的手机收验证码，再挨个重置你的账号。给卡设一个 PIN 码，卡换到别的手机上，一开机就要先输这个码，这条路就断了。', 'PIN 码在手机设置里的「SIM 卡锁」那一项里设。出厂时的初始码一般是 1234 或者 0000。连着输错三次，就要用运营商给的 PUK 码才能解开。所以设完先把这个码记在纸上', NULL, NULL, NULL, '不花钱。锁屏密码和 PIN 码各设一次就行。', '手机丢了以后，捡到的人最快的一条路是把 SIM 卡插到别的手机上，收你的短信验证码。有了验证码，他就能一个个重置你的账号。SIM 卡设了 PIN 码，换到别的手机上开机就要先输密码，捡到的人就没法拿它收验证码', 'PIN 码在手机设置里的「SIM 卡锁」那一项里设。出厂时的初始码一般是 1234 或者 0000。连着输错三次，就要用运营商给的 PUK 码才能解开。所以设完先把这个码记在纸上', '极高', 'C', 1, 'strong', 'low', 'action', 'published', '{"14. 账号与信息安全","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-4', 'concept_archive_s14-4', 'claim_archive_s14-4', 'action', 'life_archive', '手机丢了按这个顺序做：挂失 SIM 卡、远程锁定、改密码、报警、冻结银行卡', '14. 账号与信息安全', '顺序比手快更重要。第一步挂失 SIM 卡，验证码这条命脉就断了。接着远程锁住手机，再用电脑改邮箱和支付密码，然后报警拿回执，最后看情况冻结银行卡。手机不在身上，借别人的手机打运营商客服也能挂失。', '提前把三家运营商的客服号记下来：移动 10086，联通 10010，电信 10000。自己的手机号是在哪个城市办的，也记一下，客服会问。用别人的手机一样能打客服挂失', NULL, NULL, NULL, '不花钱。整套做下来十几分钟。', '顺序比速度更重要。第一步，挂失 SIM 卡，别人就收不到你的验证码了。第二步，远程锁定手机，并清空手机里的内容。第三步，从电脑上改邮箱和支付密码。第四步，报警，拿回执。最后按需要冻结银行卡。美国联邦通信委员会的提示也是：就算觉得只是弄丢了，也要远程锁住。被偷了马上报警，报上型号和 IMEI 串号（手机的身份编号），并马上告诉运营商', '提前把三家运营商的客服号记下来：移动 10086，联通 10010，电信 10000。自己的手机号是在哪个城市办的，也记一下，客服会问。用别人的手机一样能打客服挂失', '极高', 'C', 1, 'strong', 'low', 'action', 'published', '{"14. 账号与信息安全","C 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-5', 'concept_archive_s14-5', 'claim_archive_s14-5', 'action', 'life_archive', '卡被盗刷先挂失冻结再报警，然后要求银行赔：证明「是你自己刷的」是银行的责任', '14. 账号与信息安全', '卡被人盗刷，不用你去证明「这不是我刷的」。反过来，是银行要拿出证据证明这笔是你本人刷的，拿不出就得赔你。前提是你一发现就挂失冻结。拖着不挂失，后面多出来的损失要自己承担。', '有两种情形要你自己担责。一是银行卡、密码、验证码这些东西你没保管好，自己有过错（原文是「未尽妥善保管义务具有过错」），错多少担多少。所以密码不告诉别人，验证码不转发给别人（见第 1 条，二次验证优先用手机弹窗确认）。二是没及时挂失，让损失接着扩大，多出来那部分自己承担。所以第一步永远是挂失冻结，别先打客服争论。第三方支付机构也适用这套规则。它的宣传资料里写了「先行赔付」，而且承诺得具体明确的，可以照着要求它先赔。钱是你被人骗着自己转出去的，要走另一套办法，见第 8 节第 2 条（发现被骗立刻打 110 或 96110 要求止付）。', NULL, NULL, NULL, '不花钱。发现卡上有不对劲的动静，立刻挂失或者冻结。把报警记录、挂失记录、银行发来的交易通知都留着。卡还在自己身上的，就近做一笔小额查询或者存取，留下记录证明出事的时候真卡在你手上。难的是要忍住别先跟客服争论，先挂失。', '最高法的规定把「谁来拿证据」分开了。你说这是伪卡盗刷或者网络盗刷，要先拿证据。伪卡盗刷就是卡被人复制了一张去刷。这些都能用来证明：已经生效的法律文书、银行卡交易时真卡在哪里、交易发生在哪里。还有账户交易明细、交易通知、报警记录、挂失记录等等。反过来，发卡银行、非银行支付机构（第三方支付）说这笔是持卡人本人刷的、或者是经他授权刷的，要由它们拿出证据。你告知银行之后，银行没及时核实，或者没及时提供、保存交易单据和监控录像，证据因此拿不到的，拿不出证据的后果由银行承担。认定成立以后：借记卡（储蓄卡）持卡人，可以要求发卡银行把被盗刷的存款本息付给你，并赔偿损失。信用卡持卡人，可以要求退回被扣走的透支款本息和违约金，并赔偿损失；银行反过来要你还这笔透支款的，法院不予支持。你还可以要求发卡银行及时撤销相应的不良征信记录（全国，2021 年 5 月 25 日起施行）', '有两种情形要你自己担责。一是银行卡、密码、验证码这些东西你没保管好，自己有过错（原文是「未尽妥善保管义务具有过错」），错多少担多少。所以密码不告诉别人，验证码不转发给别人（见第 1 条，二次验证优先用手机弹窗确认）。二是没及时挂失，让损失接着扩大，多出来那部分自己承担。所以第一步永远是挂失冻结，别先打客服争论。第三方支付机构也适用这套规则。它的宣传资料里写了「先行赔付」，而且承诺得具体明确的，可以照着要求它先赔。钱是你被人骗着自己转出去的，要走另一套办法，见第 8 节第 2 条（发现被骗立刻打 110 或 96110 要求止付）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"14. 账号与信息安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-6', 'concept_archive_s14-6', 'claim_archive_s14-6', 'action', 'life_archive', '每隔一段时间看一次账号的登录设备和已授权应用，不用的清掉', '14. 账号与信息安全', '「登录设备」是指现在还能用你账号的那些手机和电脑。盗号的人常常先潜伏一阵再动手。列表里冒出你不认识的设备，或者早就不用的软件还连着你的账号，看到就退出全部登录，再改密码。', '微信、支付宝、邮箱、苹果账号和安卓账号里都有这个入口。发现不认识的设备，就点退出全部登录，再改密码', NULL, NULL, NULL, '不花钱。每次看几分钟。难的是没人提醒，要自己记得去看。', '被盗号往往不是当场就动手，对方会先潜伏一阵。账号里的登录设备列表，记着现在还能用这个账号的手机和电脑。已授权应用列表，记着你准许它用这个账号登录的别家软件。列表里的陌生设备，和早就不用的第三方软件，是最容易发现的痕迹', '微信、支付宝、邮箱、苹果账号和安卓账号里都有这个入口。发现不认识的设备，就点退出全部登录，再改密码', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"14. 账号与信息安全","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-7', 'concept_archive_s14-7', 'claim_archive_s14-7', 'action', 'life_archive', '别为了用 App 点「全部同意」：不是必需的信息，你不同意也不能拒绝给你服务', '14. 账号与信息安全', 'App 要你的信息，如果不是提供这项服务必须用的，你不同意给，它不能因此不让你用。它能收的，也只限于用得着的那些。地图要你的位置是必须的，手电筒要你的通讯录就不是。', '判断标准是这项信息是不是提供这个服务所必需的。地图要位置是必需的，手电筒要通讯录不是。App 装完，先到手机设置里的应用权限页，把不必需的权限关掉。等真用到的时候，再选只这一次允许。', NULL, NULL, NULL, '不花钱。难的是要忍住不点「全部同意」。', '法律明写了两条。一是不得以个人不同意、或者撤回同意为由，拒绝提供产品或者服务；处理这些信息属于提供服务所必需的除外。二是收集应当限于实现处理目的的最小范围，只能收用得着的那些', '判断标准是这项信息是不是提供这个服务所必需的。地图要位置是必需的，手电筒要通讯录不是。App 装完，先到手机设置里的应用权限页，把不必需的权限关掉。等真用到的时候，再选只这一次允许。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"14. 账号与信息安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-8', 'concept_archive_s14-8', 'claim_archive_s14-8', 'action', 'life_archive', '你有权查看、复制、更正和删除自己的个人信息，被拒绝可以起诉', '14. 账号与信息安全', '你有权要求企业让你查看、复制、更正和删除自己的信息。服务停了、保存期限到了、你撤回同意的，企业本来就该自己删掉。它拒绝你，必须说明理由；不办，你可以直接去法院告它。注销账号和删除信息是两件事，注销之后还要另外提删除。', '注销账号和删除个人信息是两件事，注销之后还要单独提出删除。换手机或者卖旧手机之前，先在旧手机上把所有账号退出、解除绑定，再恢复出厂设置。法律给你的是事后的删除权，它不能替你把已经泄露出去的东西收回来。', NULL, NULL, NULL, '不花钱。只有对方拖着不办，才需要去投诉或者起诉。真打官司就是几个月起步，律师费还要自己出，所以先投诉更划算。难的是对方拖着的时候得反复去催。', '有几种情形企业应当主动删除：服务停了、约定的保存期限到了、你撤回同意、当初收集的目的已经达到等等。它没删，你可以要求它删。它拒绝你行使这些权利的，必须说明理由。你可以直接向法院起诉', '注销账号和删除个人信息是两件事，注销之后还要单独提出删除。换手机或者卖旧手机之前，先在旧手机上把所有账号退出、解除绑定，再恢复出厂设置。法律给你的是事后的删除权，它不能替你把已经泄露出去的东西收回来。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"14. 账号与信息安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-9', 'concept_archive_s14-9', 'claim_archive_s14-9', 'action', 'life_archive', '刷脸不是必须答应的：有别的办法就不能只让你刷脸，你不同意得给你其他方式', '14. 账号与信息安全', '只要还有别的办法能办成同一件事，对方就不能只让你刷脸。你不同意刷脸，它得给你刷卡、密码或者身份证这类别的办法，也不许拿「那就办不了业务」来逼你。宾馆客房、公共浴室、更衣室、卫生间这些地方，谁都不许装人脸识别设备。', '最常遇到的是小区门禁、租房平台、健身房、酒店要你录人脸。对方说「系统只支持刷脸」的时候，把办法的原话念给他听。原话是：「实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式」。然后要求它提供刷卡、密码或者身份证这类别的方式。还是不给的，向当地网信部门反映。国家对刷脸验证身份另有规定的，比如一部分金融和政务场景，按那些规定办。人脸和密码最大的区别是泄露之后改不掉，所以它值得比密码更谨慎。存了 10 万人以上人脸信息的单位，要在 30 个工作日内向省级以上网信部门备案，这也是判断对方正不正规的一个问法。查阅、更正、删除自己个人信息的权利见第 8 条。别人借你的脸去办他自己的贷款，是另一回事，见第 8 节第 45 条（帮忙刷个脸）。', NULL, NULL, NULL, '不花钱。被要求刷脸时，问一句「有没有别的验证方式」。对方说没有，就要求它提供一个。难的是要当面开口问。', '人脸识别技术应用安全管理办法写明：「实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式。个人不同意通过人脸信息进行身份验证的，应当提供其他合理、便捷的方式。」办法还写明：「任何组织和个人不得以办理业务、提升服务质量等为由，误导、欺诈、胁迫个人接受人脸识别技术验证个人身份。」要是按你同意来处理人脸信息，得取得「在充分知情的前提下自愿、明确作出的单独同意」：单独就这一件事问你，你单独点头才算。你有权撤回同意，处理者要提供便捷的撤回方式。处理不满十四周岁未成年人的人脸信息，应当取得父母或者其他监护人的同意。公共场所安装人脸识别设备，「应当为维护公共安全所必需」，并设置显著提示标识。宾馆客房、公共浴室、公共更衣室、公共卫生间等公共场所中的私密空间内部，任何组织和个人不得安装。人脸信息应当存储于人脸识别设备内，不得通过互联网对外传输。两种情况例外：法律、行政法规另有规定，或者取得了单独同意（全国，2025 年 6 月 1 日起施行）', '最常遇到的是小区门禁、租房平台、健身房、酒店要你录人脸。对方说「系统只支持刷脸」的时候，把办法的原话念给他听。原话是：「实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式」。然后要求它提供刷卡、密码或者身份证这类别的方式。还是不给的，向当地网信部门反映。国家对刷脸验证身份另有规定的，比如一部分金融和政务场景，按那些规定办。人脸和密码最大的区别是泄露之后改不掉，所以它值得比密码更谨慎。存了 10 万人以上人脸信息的单位，要在 30 个工作日内向省级以上网信部门备案，这也是判断对方正不正规的一个问法。查阅、更正、删除自己个人信息的权利见第 8 条。别人借你的脸去办他自己的贷款，是另一回事，见第 8 节第 45 条（帮忙刷个脸）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"14. 账号与信息安全","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s14-10', 'concept_archive_s14-10', 'claim_archive_s14-10', 'action', 'life_archive', '别把代码、密钥和隐私资料交给来路不明的「AI 中转站」，让 AI 自动执行命令时尤其如此', '14. 账号与信息安全', '中转站夹在你和模型厂商中间，你发出去的内容和收回来的回答，它都看得见、改得了。有研究测了 400 多个中转站，9 个往回答里塞恶意代码，17 个动了研究者故意放进去的云服务密钥。让 AI 自动执行命令的，一条被改过的命令就够让电脑被人控制。', '定 B 级，是因为只有一项研究，而且是预印本，也就是正式发表前公开的版本。测的中转站多数是免费的，付费的只有 28 个，算不出「中转站有几成有问题」。有媒体把那次被盗写成 50 万美元，论文原文是不到 50 美元。收益量级凭后果定为中：密钥和代码被偷的损失大小差得很远，研究里没有金额可套。已经用过来路不明的中转站，就到模型厂商那里把用过的密钥作废、重新生成，云服务和代码仓库的密钥一起换。经过中转站时，别让 AI 全自动执行命令，命令先看一眼再放行。开中转站的一方有刑事风险，见第 11 节第 19 条（AI 中转站）。受益人是你自己。', NULL, NULL, NULL, '官方直连通常比中转站贵，充值也没那么方便。难在中转站便宜，一个入口能调好几家模型', '国家安全部 2026 年 6 月发布风险提示。部分中转站会把用户提交的数据留在服务器上，有的私自截留，倒卖给别的大模型厂商做训练。有的暗藏后门，向用户设备植入恶意代码，窃取账号密钥和云端凭证，甚至装上远程控制程序。提示建议用官方直连、正规授权的平台，不用来源不明、没有运营资质、没有安全保障的平台。用的时候先给个人隐私和项目资料脱敏，管好密钥、定期更换。遇到异常扣费、无故封号、数据异常，立即停用、改密钥、查杀病毒、留存证据。加州大学圣塔芭芭拉分校等单位的研究者 2026 年做了一项测量。他们从淘宝、闲鱼和海外网店买了 28 个付费中转站，又从公开社区收集了 400 个免费中转站。结果 1 个付费的和 8 个免费的，会往返回的工具调用里注入恶意代码。工具调用就是 AI 让你的电脑去执行的命令，比如安装软件包。还有 2 个会挑时机下手，论文举的例子是只对全自动执行的会话下手。17 个动用过研究者故意放进去的亚马逊云服务密钥。1 个转走了研究者以太坊钱包里的钱，钱包里只放了很少的钱，损失不到 50 美元。论文演示的改法很隐蔽：把安装命令里的 requests 换成拼法相近的 reqeusts，一眼看不出来（全国）', '定 B 级，是因为只有一项研究，而且是预印本，也就是正式发表前公开的版本。测的中转站多数是免费的，付费的只有 28 个，算不出「中转站有几成有问题」。有媒体把那次被盗写成 50 万美元，论文原文是不到 50 美元。收益量级凭后果定为中：密钥和代码被偷的损失大小差得很远，研究里没有金额可套。已经用过来路不明的中转站，就到模型厂商那里把用过的密钥作废、重新生成，云服务和代码仓库的密钥一起换。经过中转站时，别让 AI 全自动执行命令，命令先看一眼再放行。开中转站的一方有刑事风险，见第 11 节第 19 条（AI 中转站）。受益人是你自己。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"14. 账号与信息安全","B 级","性价比 一般","口径 自由","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-1', 'concept_archive_s15-1', 'claim_archive_s15-1', 'action', 'life_archive', '押金的数额、退还时间和扣减情形，必须写进合同', '15. 租房与买房', '押金多少、什么时候退、什么情况下能扣，签字前就要写进合同。合同里没写的扣款理由，房东退租时不能拿来扣你的押金。', '退租那天和房东一起拍照录像。水表、电表、燃气表的读数都拍下来，墙面和地面也拍。押金被无故扣了，先找房屋租赁管理部门投诉。金额不大的走小额诉讼，见第 8 节', NULL, NULL, NULL, '不花钱。签合同时多花十分钟。难在要当着房东的面提出来', '行政法规写得很明白：「出租人收取押金的，应当在住房租赁合同中约定押金的数额、返还时间以及扣减押金的情形等事项。除住房租赁合同约定的情形以外，出租人无正当理由不得扣减押金。」三件事要写进合同：押金收多少、什么时候退、什么情况下能扣。合同里没写的理由，房东不能拿来扣你的钱', '退租那天和房东一起拍照录像。水表、电表、燃气表的读数都拍下来，墙面和地面也拍。押金被无故扣了，先找房屋租赁管理部门投诉。金额不大的走小额诉讼，见第 8 节', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-2', 'concept_archive_s15-2', 'claim_archive_s15-2', 'action', 'life_archive', '被断水断电、换锁、上门威胁赶人，先报警留证：法规禁止用这些方式逼你腾房', '15. 租房与买房', '房东不能靠断水断电、换锁、上门威胁逼你解约或者搬走，法规明令禁止。遇上了先报警。出警记录是你以后要求赔损失的证据。不要自己动手和对方对抗。', '报警是为了留下出警记录，以后要求赔损失时它就是证据。同时通知房屋租赁管理部门', NULL, NULL, NULL, '不花钱。打个电话报警，当场就能做', '行政法规写得很明白：「出租人不得采取暴力、威胁或者其他非法方式迫使承租人解除住房租赁合同或者腾退租赁住房。」腾退就是让你搬走。遇到这类情况先报警，把证据留下。不要自己动手对抗', '报警是为了留下出警记录，以后要求赔损失时它就是证据。同时通知房屋租赁管理部门', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-3', 'concept_archive_s15-3', 'claim_archive_s15-3', 'action', 'life_archive', '中介不得代收代付租金和押金，钱直接给房东', '15. 租房与买房', '按规定，房租和押金不能由中介代收代付，钱直接付给房东。钱在中介手里过一道，就多一次它卷款跑路的机会。真跑了，你租金白交，还会被房东赶走。付款前核对收款人是不是产权证上的名字。', '付款前核对收款人是不是产权证上的名字。不是本人的，问清楚，并留一份书面授权。中介只能收牵线撮合的居间服务费', NULL, NULL, NULL, '不花钱。付款前核对收款人，几分钟。难在要顶住中介让你把钱转给它的说法', '行政法规把「代收、代付住房租金、押金」列为房地产经纪机构的禁止行为，中介不能替房东收你的房租和押金。钱在中介手里过一道，就多一次卷款跑路的机会', '付款前核对收款人是不是产权证上的名字。不是本人的，问清楚，并留一份书面授权。中介只能收牵线撮合的居间服务费', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-4', 'concept_archive_s15-4', 'claim_archive_s15-4', 'action', 'life_archive', '租长租公寓先查它的资金监管账户，别图便宜一次性付一年', '15. 租房与买房', '一次性付一年，拿到的折扣就那么点。公司一旦倒了，你的押金和剩下十几个月的房租一起没。绑了租金贷更糟：公寓跑了，贷款还是你按月还完。签约前先查它有没有公示资金监管账户。', '签约时看清有没有绑定贷款。如果是分期 App 把一年的钱一次性给了公寓、你按月还贷，那么公寓跑了你还要接着还。这种合同不签', NULL, NULL, NULL, '不花钱。查一次十几分钟', '行政法规要求转租经营的住房租赁企业「设立住房租赁资金监管账户并向社会公示」。转租经营就是企业从房东手里整租下来，再转租给你。一次性付一年拿到的那点折扣，抵不上企业跑路时押金和剩余租金一起没的风险。同时签了租金贷的，风险更大', '签约时看清有没有绑定贷款。如果是分期 App 把一年的钱一次性给了公寓、你按月还贷，那么公寓跑了你还要接着还。这种合同不签', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-5', 'concept_archive_s15-5', 'claim_archive_s15-5', 'action', 'life_archive', '房子租期内被卖掉，租约继续有效，不用搬', '15. 租房与买房', '租期内房子被卖掉，你的租约照样有效。新房东要按原来的合同让你住到期满。不用搬，也不用重新谈价钱。前提是你已经合法住在里面，合同、转账记录、入住时间的证据都留好。', '前提是你已经合法住进去了，法条里的说法是合法占有使用。合同、转账记录、入住时间的证据要留好', NULL, NULL, NULL, '不花钱', '民法典里有一条叫「买卖不破租赁」。法条原话是：租赁物在租赁期限内发生所有权变动的，不影响租赁合同的效力。意思是租期里房子换了主人，已经签好的租约照样有效。新房东要按原合同让你住到期满', '前提是你已经合法住进去了，法条里的说法是合法占有使用。合同、转账记录、入住时间的证据要留好', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-6', 'concept_archive_s15-6', 'claim_archive_s15-6', 'action', 'life_archive', '签约前核对产权证和抵押情况，所有款项走转账并备注用途', '15. 租房与买房', '最常见的两种血本无归，一是租金付给了不是产权人的人，二是房子早就抵押给银行、后来被查封。签约前去不动产登记中心查一次产权和抵押。所有钱走转账，备注写「某某房屋某月租金」，出了纠纷这就是直接证据。', '产权信息可以去当地不动产登记中心查。签约时让房东本人到场，本人来不了的，要一份授权委托书。二房东转租给你的，要有原房东的书面同意', NULL, NULL, NULL, '不花钱。查一次半小时', '最常见的两种血本无归，一是把租金付给了不是产权人的人，二是房子早就抵押给银行，后来被查封。转账时备注「某某房屋某月租金」，出了纠纷这就是直接证据', '产权信息可以去当地不动产登记中心查。签约时让房东本人到场，本人来不了的，要一份授权委托书。二房东转租给你的，要有原房东的书面同意', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"15. 租房与买房","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-7', 'concept_archive_s15-7', 'claim_archive_s15-7', 'action', 'life_archive', '二手房让中介代收房款的，必须走中介在银行开的交易资金专用存款账户', '15. 租房与买房', '房款是几十万到几百万，是这本书里单笔金额最大的一件事。中介代收房款的，按规定必须走它在银行开的专用账户，不能微信转给经纪人个人。另外，两家中介合做一单只能收一份佣金，代办贷款、代办过户要单独签合同、事先说清收费。', '房款是几十万到几百万，是这本书里单笔金额最大的一件事，别用微信转给经纪人。还有两种常见的多收钱。一是两家中介联合做同一单，这种只能收一份佣金。二是代办贷款、代办过户，这属于另外的服务，要单独签合同并事先告知收费。所有款项都走转账并备注用途，见第 6 条（签约前核对产权证和抵押情况）。', NULL, NULL, NULL, '不花钱。难在要坚持走专用账户，可能得跟中介多争几句', '规章写得很明白：约定由房地产经纪机构代收代付交易资金的，应当通过其在银行开设的客户交易结算资金专用存款账户划转。意思是房款进的是受监管的专用账户，不是中介自己的账户，也不是某个经纪人的私人账户', '房款是几十万到几百万，是这本书里单笔金额最大的一件事，别用微信转给经纪人。还有两种常见的多收钱。一是两家中介联合做同一单，这种只能收一份佣金。二是代办贷款、代办过户，这属于另外的服务，要单独签合同并事先告知收费。所有款项都走转账并备注用途，见第 6 条（签约前核对产权证和抵押情况）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-8', 'concept_archive_s15-8', 'claim_archive_s15-8', 'action', 'life_archive', '别租隔断房：最小出租单位是原设计的房间，厨房、卫生间、阳台不得住人', '15. 租房与买房', '按规定，最小的出租单位是原来设计好的那间房。厨房、卫生间、阳台和地下储藏室不能住人。这种房被查处之后，你可能要搬走。另外，租期内房东也不能自己说涨租就涨租。', '违规隔断被查处时，搬家的是租客，押金和已经付掉的租金往往拿不回来。安全上也差：隔断墙常常堵住逃生的通道，一屋住很多人还共用一条电线。看房时注意三点：墙是不是后来砌的，房间有没有窗，电表带不带得动这么多人。', NULL, NULL, NULL, '不花钱。代价是同样的预算，要么住得远一点，要么住得小一点', '规章写得很明白，最小的出租单位是原设计的房间，不能把一间房再隔成几间分开租。人均租住建筑面积不得低于当地规定的最低标准。厨房、卫生间、阳台和地下储藏室不得出租供人员居住。租期内出租人也不得单方面随意提高租金', '违规隔断被查处时，搬家的是租客，押金和已经付掉的租金往往拿不回来。安全上也差：隔断墙常常堵住逃生的通道，一屋住很多人还共用一条电线。看房时注意三点：墙是不是后来砌的，房间有没有窗，电表带不带得动这么多人。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s15-9', 'concept_archive_s15-9', 'claim_archive_s15-9', 'action', 'life_archive', '城镇户口想搬去乡下住，只租农房，别买宅基地和宅基地上的房子', '15. 租房与买房', '城镇户口的人不能到农村买宅基地、农民的房子或者「小产权房」，国家文件明令禁止。村里人说「写个合同就行」也不行，钱付出去，房子也成不了你的。想在乡下长住，就签租赁合同，一次最长签 20 年，到期再续。', '宅基地就是村里分给本村村民盖房的地，只能分给本村人。租农房时和出租的农户签书面合同，写清租期、租金、能不能装修改建，以及装修的钱到期怎么算。文件规定租期不超过 20 年，别签「租 50 年」「租 70 年」这类合同，更别一次付清多年租金。文件还禁止下乡用宅基地盖别墅大院和私人会馆，别出钱给村民「合建」。', NULL, NULL, NULL, '不花钱。代价是房子不归你，租期一次最长 20 年，到期要重新和房东谈', '国务院办公厅的文件写得很明白：「城镇居民不得到农村购买宅基地、农民住宅或『小产权房』。」同一份文件还规定，农民卖掉或者租出住房以后，再申请宅基地不予批准。2019 年中央农办和农业农村部的文件又说了一遍：「严禁城镇居民到农村购买宅基地。」同一份文件给出了合法的路：城镇居民可以租农房居住或者经营，租赁合同的期限不得超过二十年，到期双方可以另行约定', '宅基地就是村里分给本村村民盖房的地，只能分给本村人。租农房时和出租的农户签书面合同，写清租期、租金、能不能装修改建，以及装修的钱到期怎么算。文件规定租期不超过 20 年，别签「租 50 年」「租 70 年」这类合同，更别一次付清多年租金。文件还禁止下乡用宅基地盖别墅大院和私人会馆，别出钱给村民「合建」。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"15. 租房与买房","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-1', 'concept_archive_s16-1', 'claim_archive_s16-1', 'action', 'life_archive', '药按医嘱吃满，别感觉好了就停', '16. 得了慢性病之后怎么活', '按医生说的把药吃满的人，同期死亡的可能性大约只有断断续续吃药的人的一半。这个数要打折看。连假药都吃满的人死亡率也低，说明有一部分好处来自「能坚持吃药的人本来就更注意健康」。但停药的害处是确定的，降压药、抗凝药、抗排异药尤其如此。', '争议。这也是这本书里最需要打折看的一个数字。同一项汇总分析里，连安慰剂（假药）都吃满的人死亡率也低（0.56，0.43–0.74）。这说明相当一部分好处来自「能坚持吃药的人本来就更注意健康」。作者把这层混进来的因素叫健康依从者效应。但停药本身的害处是明确的，尤其是降压药、抗凝药和抗排异药', NULL, NULL, NULL, '不花钱，反而省下以后治并发症的钱。每天吃药占不了几分钟，难在一天不落地吃下去。', '21 项研究、46847 人合起来算（荟萃分析）：和吃药断断续续的人相比，按医嘱吃满的人同期死亡的可能性约低 44%。原值是比值比 0.56，95% CI 0.50–0.63（可信范围）。只看确有疗效的治疗，约低 45%（0.55，0.49–0.62）', '争议。这也是这本书里最需要打折看的一个数字。同一项汇总分析里，连安慰剂（假药）都吃满的人死亡率也低（0.56，0.43–0.74）。这说明相当一部分好处来自「能坚持吃药的人本来就更注意健康」。作者把这层混进来的因素叫健康依从者效应。但停药本身的害处是明确的，尤其是降压药、抗凝药和抗排异药', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-2', 'concept_archive_s16-2', 'claim_archive_s16-2', 'action', 'life_archive', '先办门诊慢特病认定再办异地备案，高血压、糖尿病、放化疗、透析、抗排异就能异地直接结算', '16. 得了慢性病之后怎么活', '高血压、糖尿病、恶性肿瘤门诊放化疗、尿毒症透析、器官移植后抗排异，这五种在外地看门诊也能直接刷医保。不用先自己垫钱，再回参保地报销。但要先在参保地办门诊慢特病认定，再办异地就医备案。两件事都办了才管用。', '前提是两件事都要办：先在参保地办门诊慢特病认定，再做异地就医备案。新增的 5 个病种开到了哪一步，各地进度不一样，以当地医保部门公布的为准', NULL, NULL, NULL, '不花钱。出发前在医保 App 上办一次异地就医备案，手机上就能办。', '国家医保局的文件说已经做到了这一步。原话是「基本实现高血压、糖尿病、恶性肿瘤门诊放化疗、尿毒症透析、器官移植术后抗排异治疗等 5 种门诊慢特病费用跨省直接结算县域可及」。「县域可及」的意思是在县一级就能办到。文件还在这 5 种的基础上再新增 5 种', '前提是两件事都要办：先在参保地办门诊慢特病认定，再做异地就医备案。新增的 5 个病种开到了哪一步，各地进度不一样，以当地医保部门公布的为准', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-3', 'concept_archive_s16-3', 'claim_archive_s16-3', 'action', 'life_archive', '复查按医生给的间隔做，把每次的指标记在同一个本子上', '16. 得了慢性病之后怎么活', '慢性病看的是一段时间里的变化，不是某一次的数值。把日期、指标、当时吃的药和剂量记在同一个本子上。换医院的时候拿出来，不用把检查重做一遍、重花一遍钱。', '每次至少记四样：日期、指标值、当时在吃的药、药的剂量。用手机拍化验单也行，但都要放在同一处，别东一张西一张', NULL, NULL, NULL, '每次检查几十到几百元。去一趟医院加上等结果，要占一点时间。难在隔一段就得去一次，容易一拖再拖。', '慢性病要看的是数值一段时间里怎么变，只看某一次不够。记在同一处还有一个好处：换医院时不用重复检查，也不用重复花钱', '每次至少记四样：日期、指标值、当时在吃的药、药的剂量。用手机拍化验单也行，但都要放在同一处，别东一张西一张', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","C 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-4', 'concept_archive_s16-4', 'claim_archive_s16-4', 'action', 'life_archive', '别为了试偏方、保健品停掉正规治疗', '16. 得了慢性病之后怎么活', '停药的坏处是确定的，偏方和保健品的好处是不确定的。这等于拿确定的损失去换不确定的好处。想试补充剂就先告诉主治医生。有些补充剂会影响抗凝药、抗排异药在血里的浓度。', '想试补充剂就先告诉主治医生。有些补充剂会和处方药相互作用，比如影响抗凝药、抗排异药在血里的浓度', NULL, NULL, NULL, '不花钱，还省下买保健品的钱。不占时间。难在别人反复劝你试的时候能顶住。', '停药的害处是确定的，偏方的好处是不确定的。常见的无效品类，这本书第 6 节列了一批', '想试补充剂就先告诉主治医生。有些补充剂会和处方药相互作用，比如影响抗凝药、抗排异药在血里的浓度', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-5', 'concept_archive_s16-5', 'claim_archive_s16-5', 'action', 'life_archive', '病情稳定的慢性病，在社区医院一次可以开到 12 周的药', '16. 得了慢性病之后怎么活', '病情稳定、吃的药也没换的人，在社区卫生服务中心一次能开够 12 周的药。省掉每月往返大医院排队挂号的半天。在同一个参保地里，住基层医院的报销比例通常还比上一级医院高十个百分点左右。', '「符合条件」由医生判断，一般是诊断已经明确、用药方案也稳定的人。药还是那个药，省下的是每月跑一趟的半天和挂号费。基层没有你要的那种药，可以问问有没有缺药登记和配送。同一份文件还要求三级医院逐步减掉这类慢病的普通门诊，同一批专家的普通门诊改到社区去开。还把大医院当开药点，以后会越来越难挂号。', NULL, NULL, NULL, '不花钱。去社区卫生服务中心问一句能不能开长期处方，一句话的事。', '不用每月往返大医院排队开药。在同一个参保地（也叫统筹地区）里，住基层医院的报销比例原则上比上一级医院高约 10 个百分点', '「符合条件」由医生判断，一般是诊断已经明确、用药方案也稳定的人。药还是那个药，省下的是每月跑一趟的半天和挂号费。基层没有你要的那种药，可以问问有没有缺药登记和配送。同一份文件还要求三级医院逐步减掉这类慢病的普通门诊，同一批专家的普通门诊改到社区去开。还把大医院当开药点，以后会越来越难挂号。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-6', 'concept_archive_s16-6', 'claim_archive_s16-6', 'action', 'life_archive', '在社区签家庭医生之前，问清楚哪些进医保、哪些自费', '16. 得了慢性病之后怎么活', '签约的基本服务包按规定走医保。个性化服务包的钱要全部自己出。有人推销「升级包」的时候，先问清楚这是基本包还是个性化包、备没备案、一年多少钱。', '签约本身的价值在于有人长期跟着你这个病，不在于打包了多少项目。有人推销「升级包」时，先问三句：这是基本包还是个性化包，备没备案，一年多少钱。', NULL, NULL, NULL, '不花钱。签约前多问一句，一分钟的事。', '基本服务包按规定由医保付。个性化服务包的钱全部自己出，这种包还要向县级卫生健康部门备案', '签约本身的价值在于有人长期跟着你这个病，不在于打包了多少项目。有人推销「升级包」时，先问三句：这是基本包还是个性化包，备没备案，一年多少钱。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-7', 'concept_archive_s16-7', 'claim_archive_s16-7', 'action', 'life_archive', '确诊糖尿病就去查一次眼底，之后按医生给的间隔查；每年查一次脚', '16. 得了慢性病之后怎么活', '糖尿病伤到眼底、伤到脚，在坏到看不见、烂起来之前几乎没有感觉。早查出来还有得治。2 型糖尿病确诊当时就查一次散瞳眼底，1 型在发病 5 年后开始查。查过一两次没事、血糖也达标的，可以放宽到一两年一次。脚每年查一次。', '2 型糖尿病确诊的时候就要查，1 型是发病 5 年后才开始查。差别在于 2 型往往已经悄悄高了好几年。查过一两次没事、血糖也达标的，可以放宽到 1 到 2 年一次。脚上感觉变迟钝的人，每天自己看一眼脚底，用镜子照也行。', NULL, NULL, NULL, '一次散瞳眼底检查几十到几百元。足部检查通常包含在门诊里，不另花钱。难在眼睛和脚都没不舒服的时候也要记着去查。', '糖尿病伤到眼底叫视网膜病变，伤到脚叫糖尿病足。这两样在出问题之前几乎没有感觉。早查出来还有得治。等到看不见或者脚烂起来，就晚了', '2 型糖尿病确诊的时候就要查，1 型是发病 5 年后才开始查。差别在于 2 型往往已经悄悄高了好几年。查过一两次没事、血糖也达标的，可以放宽到 1 到 2 年一次。脚上感觉变迟钝的人，每天自己看一眼脚底，用镜子照也行。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-8', 'concept_archive_s16-8', 'claim_archive_s16-8', 'action', 'life_archive', '得过肾结石就把水喝到每天 2.5–3 升，盐降到 6 克以内', '16. 得了慢性病之后怎么活', '第一次长了钙结石的人，什么都不做的话，五年里约四分之一会再长。每天把水喝够的人，五年里复发的只有一成多，少了一半多。英国指南给的量是每天喝 2.5 到 3 升水，盐不超过 6 克。', '复发少了大约 55%，又不花钱，按本书的排序规则这是本节性价比最高的一条。要盯的是 24 小时尿量，目标是 2 到 2.5 升以上，不是看喝进去多少。出汗多的人、在高温环境里干活的人，得喝得更多。那项试验做的是第一次发作的特发性钙结石患者。结石成分不止一种，尿酸结石、感染性结石、胱氨酸结石各有各的对策。复发过的人值得做一次结石成分分析和 24 小时尿检，再定要不要加药。别为了防结石把钙戒掉，见第 6 节第 21 条。发作时腰腹绞痛得厉害要去医院，不是靠多喝水冲下去的。不疼的血尿另有要查的东西，见第 1 节第 27 条', NULL, NULL, NULL, '不花钱。把随时喝水变成习惯。出汗多的日子还要再多喝一些，难在天天记着。', '一项为期 5 年、随机分成两组的对照试验，对象是 199 名第一次得钙结石、又查不出原因的患者（也叫特发性钙结石）。一组每天至少喝 2 升水，另一组不做任何干预。5 年里复发的，多喝水那组 12/99（12.1%），不干预那组 27/100（27.0%），P=0.008。P 值越小，越说明两组的差别不是碰巧。平均隔多久复发：38.7±13.2 个月对 25.1±16.4 个月，P=0.016。一开始测的 24 小时尿量，结石患者明显低于没结石的人：男性是 1,057±238 mL 对 1,401±562 mL（P&lt;0.0001），女性是 990±230 mL 对 1,239±440 mL（P&lt;0.001）。NICE 指南 NG118 第 1.8.1 条建议，成人每天喝 2.5 到 3 升水，儿童青少年按年龄喝 1 到 2 升。水里加点鲜柠檬汁，别喝碳酸饮料，成人每天盐不超过 6 克', '复发少了大约 55%，又不花钱，按本书的排序规则这是本节性价比最高的一条。要盯的是 24 小时尿量，目标是 2 到 2.5 升以上，不是看喝进去多少。出汗多的人、在高温环境里干活的人，得喝得更多。那项试验做的是第一次发作的特发性钙结石患者。结石成分不止一种，尿酸结石、感染性结石、胱氨酸结石各有各的对策。复发过的人值得做一次结石成分分析和 24 小时尿检，再定要不要加药。别为了防结石把钙戒掉，见第 6 节第 21 条。发作时腰腹绞痛得厉害要去医院，不是靠多喝水冲下去的。不疼的血尿另有要查的东西，见第 1 节第 27 条', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s16-9', 'concept_archive_s16-9', 'claim_archive_s16-9', 'action', 'life_archive', '确诊痛风就长期吃降尿酸药，把血尿酸压到 360 µmol/L 以下并一直维持', '16. 得了慢性病之后怎么活', '痛风要长期吃降尿酸药，把尿酸压到 360 µmol/L 以下，不能只在疼的时候吃止痛药。由护士按化验结果帮着调药量的病人，两年后 95% 达标，照常看病的只有 30%。达标之后也不能停药。靠忌口降不到这条线，戒酒也只低 1.6 mg/dL。', '争议：用哪种药降尿酸，各国指南不一样。美国指南首选别嘌醇，有心血管病的人能换就别吃非布司他，但欧洲 FAST 试验没看到非布司他更危险。国内还能买到苯溴马隆，它是促进尿酸排出的药。中华医学会的指南（2019 版和 2024 更新版）对选药和碱化尿液单独给了推荐。吃苯溴马隆要不要加碳酸氢钠碱化尿液，美国指南认为没有证据，按你的医生的意见办，多喝水不能省。汉族人用别嘌醇之前值得先查 HLA-B*5801。它是一种天生的、管免疫反应的基因型号，查一次结果终身不变。带着这个基因的人，在汉族、韩国、泰国人里占 7.4%，白人和西班牙裔只有 0.7%。亚裔和非裔用别嘌醇之后发生别嘌醇超敏综合征的风险是白人的 3 倍，这个病严重时皮肤会大面积剥脱，能要命。美国风湿病学会 2020 年痛风指南对这两类人建议，用药前可以考虑先查一下。刚开始降尿酸反而更容易诱发发作，所以指南明确要求头 3 到 6 个月同时吃一种抗炎的预防药。「吃了降尿酸药反而更疼，所以停了」是这件事最常见的失败方式。疼起来该做的是按医嘱加抗炎药，不是停降尿酸药。达标值各家写法不同：&lt;6 mg/dL 约合 360 µmol/L，中国的化验单多用 µmol/L。体检查出尿酸高但从没发作过是另一回事，见第 6 节第 19 条。含糖饮料和酒见第 2 节第 7、19 条（不喝含糖饮料、少喝或不喝酒）', NULL, NULL, NULL, '别嘌醇每月几元到几十元。刚开始每几周查一次血尿酸来调药量，稳定之后每几个月查一次。头 3 到 6 个月还要同时吃一种预防发作的药。难在不疼的时候也得一直吃下去。', '一项随机分成两组的对照试验，517 名过去 12 个月内发作过的成人。一组由护士主导，给患者讲清楚病是怎么回事，再按指标把尿酸调到达标。另一组照常找全科医生看。2 年时血尿酸降到 &lt;360 µmol/L（6 mg/dL）的比例，95% 对 30%。达标的可能性是常规组的 3.18 倍（RR 3.18，95% CI 2.42–4.18，这个区间是数字的可信范围），P&lt;0.0001。第 2 年的发作频率、痛风石、生活质量这几项次要指标，也都优于常规组。每多换来一年算上生活质量折算的寿命（质量调整生命年），花费 £5,066。同一试验还做了随访研究，438 人发了问卷，收回 82%。两组都自己报告了过去 12 个月的发作次数。达标组的中位数是 0 次（中间一半人落在 0–0 次）。常规组是 1 次（0–3），P&lt;0.001。括号里的这个范围叫四分位距。仍在吃降尿酸药的比例，达标组是常规组的 1.19 倍（校正后 RR 1.19，1.09–1.30）。美国风湿病学会 2020 年痛风指南强烈推荐三种人启动降尿酸治疗：皮下长了痛风石的、影像检查看到痛风把骨头啃出缺损的、每年发作 ≥2 次的。做法是持续监测血尿酸，照着结果调剂量直到达标，目标 &lt;6 mg/dL。首选别嘌醇，3 期及以上慢性肾病的人也是首选它，起始剂量 ≤100 mg/日。启动时同时给抗炎的预防用药，至少吃 3 到 6 个月。同一指南还引用了一组病例观察。这些患者长期控制良好之后停了药，停药后血尿酸仍保持 &lt;7 mg/dL。他们当中，5 年跟踪期内一次都没发作的只有 13%（27/211）。饮食方面，限酒或戒酒的人，血尿酸比不限的人低 1.6 mg/dL，一份啤酒使血尿酸升高 0.16 mg/dL。健康饮食、地中海饮食、DASH 饮食的效果更小。首选哪种降尿酸药有分歧。美国风湿病学会指南强烈推荐别嘌醇作为首选，理由是剂量用够时有效、耐受好、安全、便宜。它还有条件地建议：吃非布司他的人如果有心血管病史，或新出了心血管事件，有别的药可换就换掉。这条推荐和 FDA 给非布司他加的黑框警告一致。依据之一是 CARES 试验，6190 名合并心血管病的痛风病人随机吃非布司他或别嘌醇。非布司他组的全因死亡风险是别嘌醇组的 1.22 倍（HR 1.22，95% CI 1.01–1.47，高约 22%）。心血管死亡是 1.34 倍（1.03–1.73，高约 34%）。欧洲的 FAST 试验结论不同。它纳入 6128 名 60 岁以上、有心血管危险因素的病人，非布司他的主要心血管事件不比别嘌醇多（HR 0.85，0.70–1.03）。死亡人数是非布司他组 7.2%、别嘌醇组 8.6%。吃促进尿酸从肾排出的药的人，美国风湿病学会有条件地不建议碱化尿液，因为没有证据说明有效，证据确定性很低。它同时要求叮嘱这些人多喝水，已知有肾结石或 3 期及以上慢性肾病的人不该用这类药', '争议：用哪种药降尿酸，各国指南不一样。美国指南首选别嘌醇，有心血管病的人能换就别吃非布司他，但欧洲 FAST 试验没看到非布司他更危险。国内还能买到苯溴马隆，它是促进尿酸排出的药。中华医学会的指南（2019 版和 2024 更新版）对选药和碱化尿液单独给了推荐。吃苯溴马隆要不要加碳酸氢钠碱化尿液，美国指南认为没有证据，按你的医生的意见办，多喝水不能省。汉族人用别嘌醇之前值得先查 HLA-B*5801。它是一种天生的、管免疫反应的基因型号，查一次结果终身不变。带着这个基因的人，在汉族、韩国、泰国人里占 7.4%，白人和西班牙裔只有 0.7%。亚裔和非裔用别嘌醇之后发生别嘌醇超敏综合征的风险是白人的 3 倍，这个病严重时皮肤会大面积剥脱，能要命。美国风湿病学会 2020 年痛风指南对这两类人建议，用药前可以考虑先查一下。刚开始降尿酸反而更容易诱发发作，所以指南明确要求头 3 到 6 个月同时吃一种抗炎的预防药。「吃了降尿酸药反而更疼，所以停了」是这件事最常见的失败方式。疼起来该做的是按医嘱加抗炎药，不是停降尿酸药。达标值各家写法不同：&lt;6 mg/dL 约合 360 µmol/L，中国的化验单多用 µmol/L。体检查出尿酸高但从没发作过是另一回事，见第 6 节第 19 条。含糖饮料和酒见第 2 节第 7、19 条（不喝含糖饮料、少喝或不喝酒）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"16. 得了慢性病之后怎么活","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-1', 'concept_archive_s17-1', 'claim_archive_s17-1', 'action', 'life_archive', '趁老人清醒，书面指定将来的监护人', '17. 家里有老人', '趁老人头脑还清楚，花几百元去公证处办一份书面文件，写明将来谁当他的监护人。没有这份文件，等老人不能自己做决定了，谁替他签字、谁替他管钱，要由法院来指定。家里人意见不一致，还会拖得更久。', '这份文件叫意定监护，意思是自己提前指定的人。这个人排在法律默认的那套监护顺序前面。老人独居、子女在外地、家里关系复杂的，更需要提前办。建议去公证处做公证', NULL, NULL, NULL, '去公证处办一份，几百元。和老人谈一次话就能定下来。难在开口：要当面说到将来他自己管不了自己的那一天', '民法典规定，头脑清醒、能自己做主的成年人（法律叫「具有完全民事行为能力的成年人」），可以提前和人商量好将来谁当自己的监护人。商量的对象可以是近亲属，也可以是其他愿意当监护人的个人或者组织。商量好了要「以书面形式确定自己的监护人」。将来他不能做决定了，或者只能做一部分决定了（法律叫「丧失或者部分丧失民事行为能力」），就由写定的这个人来管。没有这份文件，将来谁替他签字、谁替他管钱，要走法院指定', '这份文件叫意定监护，意思是自己提前指定的人。这个人排在法律默认的那套监护顺序前面。老人独居、子女在外地、家里关系复杂的，更需要提前办。建议去公证处做公证', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-2', 'concept_archive_s17-2', 'claim_archive_s17-2', 'action', 'life_archive', '把遗嘱立了，记住后立的推翻先立的，公证遗嘱不再优先', '17. 家里有老人', '法律认六种遗嘱，但形式写错了整份作废，这是最常见的翻车点。自己手写的那种，要本人从头到尾手写，签上名，写清年月日。立了好几份、内容互相打架的，按最后立的那份算。2021 年起，公证过的那份也不再自动排在前面。', '自己手写的遗嘱，要本人从头到尾手写，签上名，写清年月日。打印的遗嘱要有两个以上见证人。遗嘱人和见证人要在每一页上签名，并写清年月日。继承人、被写进遗嘱要分东西的人，以及他们的近亲属，都不能当见证人。形式错了整份作废，这是最常见的翻车点', NULL, NULL, NULL, '自己手写一份遗嘱，不花钱。找公证处公证，几百到上千元。难在开口：要和家里人谈身后事', '民法典认可六种遗嘱形式：自己手写的、请人代写的、打印的、录音录像的、口头的、公证的。每一种都有各自必须做到的手续要求（法律叫「形式要件」）。如果立了好几份，内容互相打架，以最后立的那份为准。2021 年起，公证的那份不再自动排在前面', '自己手写的遗嘱，要本人从头到尾手写，签上名，写清年月日。打印的遗嘱要有两个以上见证人。遗嘱人和见证人要在每一页上签名，并写清年月日。继承人、被写进遗嘱要分东西的人，以及他们的近亲属，都不能当见证人。形式错了整份作废，这是最常见的翻车点', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-3', 'concept_archive_s17-3', 'claim_archive_s17-3', 'action', 'life_archive', '老人的钱单独放一个账户，大额支出定一个双人确认的规矩', '17. 家里有老人', '骗老人买保健品、买收藏品、买理财的，套路都一样：先花几个月和他处熟，再一次性收割。事先约好一条规矩，超过多少钱的支出要先跟某个人说一声。这等于把掏钱那一刻往后拖，拖过最冲动的那一阵。', '别把这件事讲成「怕你被骗」。讲成「家里的钱统一记账」，老人更容易接受。也别把老人的所有钱都交给子女保管，那会引出另一类纠纷', NULL, NULL, NULL, '不花钱。和家里人商量一次，定下一个数额就行。难在怎么开口，别让老人觉得你在防着他', '针对老人的保健品、收藏品、理财骗局，套路都是先用几个月把信任攒足，再一次性收割。事先约好「超过多少钱的支出要先和某个人说一声」。这等于把掏钱这个决定往后拖，拖过最冲动的那一阵', '别把这件事讲成「怕你被骗」。讲成「家里的钱统一记账」，老人更容易接受。也别把老人的所有钱都交给子女保管，那会引出另一类纠纷', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"17. 家里有老人","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-4', 'concept_archive_s17-4', 'claim_archive_s17-4', 'action', 'life_archive', '给老人备好一句随时能说出口的推辞：「我要回去和家里人商量」', '17. 家里有老人', '推销和诈骗靠的是现场压力，让人当场不好意思拒绝。事先和老人商量好一句话：「我要回去和家里人商量。」他随时能说出口，当场有台阶下。这比事后再跟他讲道理管用。', '和第 3 条（老人的钱单独放一个账户）一起用。家里的防跌倒改造也顺手做了，见第 1 节。这句话是给老人留个台阶，让他不用当场硬顶，不是用来防着他的。被推销围住的时候，最难的是当着一屋子人开口拒绝，比判断真假还难', NULL, NULL, NULL, '不花钱。和老人对一次话，几分钟就行', '推销和诈骗都靠现场施压。事先商量好一句「我要回去和家里人商量」，让老人有台阶可下。这比事后讲道理有效', '和第 3 条（老人的钱单独放一个账户）一起用。家里的防跌倒改造也顺手做了，见第 1 节。这句话是给老人留个台阶，让他不用当场硬顶，不是用来防着他的。被推销围住的时候，最难的是当着一屋子人开口拒绝，比判断真假还难', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"17. 家里有老人","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-5', 'concept_archive_s17-5', 'claim_archive_s17-5', 'action', 'life_archive', '凡是让老人先交钱的「投资养老」都别碰：办卡、买床位、买养老公寓、旅居养老、买老年产品是同一套非法集资', '17. 家里有老人', '让老人先交钱、又许诺回报的养老名目，都是同一套骗局：办卡、买床位、买养老公寓、旅居养老、开会卖老年产品。按规定，这种钱亏了只能自己认。有人借预定养老公寓床位收走 1.36 亿元，坑了 2100 多人。能拦住的只有掏钱那一步。', '判断不靠「这家看着正规」，靠「有没有让你先交钱、有没有承诺回报」。养老机构本来是卖服务的，话里一带上投资、返利、回本，就别信。老人被拉去听课、旅游、义诊，本身不违法，也很难拦住。能拦的是掏钱那一步，配合第 3 条的双人确认规矩用。已经交了钱，就立刻按第 8 节第 2 条打 110 或 96110 要求止付，同时向当地负责处置非法集资的牵头部门举报。以房养老是另一套路径，见第 6 条（住房反向抵押养老保险）。', NULL, NULL, NULL, '不花钱。把下面这几种名目念给老人听一遍，几分钟。以后遇上就直接拒绝：不去听课，不去参观，不留电话。难在老人要是已经去过几次、和人处熟了，就不容易劝回来', '民政部列了五种表现形式，认名目比认人可靠。第一种，假借养老服务机构之名：没有实体，临时租个场地，宣称和养老机构签了合作协议来「碰瓷」。第二种，以提供「养老服务」为名：卖「贵宾卡」「会员卡」「预付卡」，让人预交「养老服务费用」，承诺的服务明显超过自己的床位供给能力。第三种，以投资「养老项目」为名。常见名目有入股养生养老基地、销售虚构的养老公寓。还有长期出租养老床位、「时间银行」互助养老。打的幌子是返本销售、售后返租、约定回购。第四种，以销售「老年产品」为名：商品回购、寄存代售、消费返利、免费体检、赠送礼品、会议营销、养生讲座、专家义诊。第五种，以享受「旅居养老」为名：低价或免费旅游、储值返利、积分养老。钱追不回来，条例里写明了。防范和处置非法集资条例第二十五条规定，「因参与非法集资受到的损失，由集资参与人自行承担」，亏掉的钱只能自己认。官方通报过的案子里，戴某平等人以预定养老公寓床位名义非法集资 1.36 亿元，被害人 2100 余人，戴某平以集资诈骗罪判 15 年，并处罚金 40 万元。曹某铭以投资养老产业为名集资诈骗 132.07 亿元，涉及 11 万余人，判无期徒刑、剥夺政治权利终身、没收个人全部财产。保健品会销走的是诈骗罪。倪某荣用免费宴请、赠送礼品、专车接送，把老年人拉去听课。讲师用「虚假人设、虚假案例、虚高砍价」编造防癌抗癌功效。老人被诱骗以成本价的数十倍买「二氢槲皮素」。销售金额 62 万余元。倪某荣判 10 年 3 个月，并处罚金 12 万元（全国，条例 2021 年 5 月 1 日起施行）', '判断不靠「这家看着正规」，靠「有没有让你先交钱、有没有承诺回报」。养老机构本来是卖服务的，话里一带上投资、返利、回本，就别信。老人被拉去听课、旅游、义诊，本身不违法，也很难拦住。能拦的是掏钱那一步，配合第 3 条的双人确认规矩用。已经交了钱，就立刻按第 8 节第 2 条打 110 或 96110 要求止付，同时向当地负责处置非法集资的牵头部门举报。以房养老是另一套路径，见第 6 条（住房反向抵押养老保险）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-6', 'concept_archive_s17-6', 'claim_archive_s17-6', 'action', 'life_archive', '除了保险公司的住房反向抵押养老保险，其他「以房养老」都别碰，绝不抵押房子去买理财', '17. 家里有老人', '正规的以房养老只有一种，就是保险公司的住房反向抵押养老保险，还在试点。上门推销的那种和它毫无关系，是骗老人抵押房子，再拿借来的钱买它推荐的理财。有人连房子被抵押了都不知道，最后房子没了，还背着贷款。', '给 B 级是因为这些说法出自监管部门的风险提示和经验判断，不是研究数据。6%、8%、10% 这三条线是监管给消费者的参考线，不是法律定的标准。银保监会已经并入国家金融监督管理总局，原发布页打不开，这里引的是省级金融监管局的转载页。理财亏钱还在其次，房子被抵押出去以后老人还欠着一笔贷款，损失远大于本金。签字和空白合同的一般规则见第 8 节第 17 条，被骗之后怎么止付见第 8 节第 2 条。', NULL, NULL, NULL, '不花钱。家里的房产证，不交给任何以「以房养老」名义上门的人。抵押、担保、借贷这些协议，签字前先给子女看一遍。难在上门的人往往很热情、跑了很多趟，老人不好意思回绝', '银保监会消保局把真假两种说清楚了。正规的以房养老只有一种，叫「老年人住房反向抵押养老保险」。拥有房屋完全合法产权的老年人，把房产抵押给保险公司。房子照样归自己住、自己用、自己收租。要卖、要处置，得经抵押权人（保险公司）同意。老人按约定条件领取养老金，一直领到去世。这项业务目前仍处于试点阶段，做的人比较少。不法分子说的「以房养老」，与国家试行的住房反向抵押养老保险「完全无关」，是「假借国家政策、为非法集资活动造势宣传的手段」。它的操作是诱骗老人办房产抵押，再把借来的钱去买它推荐的理财产品，「往往是『以新还旧』的庞氏骗局」。后果原文写的是「有的参与人甚至都不知道自己的房产被抵押，最终失去了房子，还背负贷款」。提示里还给了一条看收益率的线。原话是「理财产品如果承诺收益率超过 6% 就要打问号，超过 8% 就很危险，10% 以上就要准备损失全部本金，『保本高收益』就是金融诈骗」。同一份提示还要求「慎重对待合同签署环节，不在空白合同签字」（全国，2021 年 6 月）', '给 B 级是因为这些说法出自监管部门的风险提示和经验判断，不是研究数据。6%、8%、10% 这三条线是监管给消费者的参考线，不是法律定的标准。银保监会已经并入国家金融监督管理总局，原发布页打不开，这里引的是省级金融监管局的转载页。理财亏钱还在其次，房子被抵押出去以后老人还欠着一笔贷款，损失远大于本金。签字和空白合同的一般规则见第 8 节第 17 条，被骗之后怎么止付见第 8 节第 2 条。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"17. 家里有老人","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-7', 'concept_archive_s17-7', 'claim_archive_s17-7', 'action', 'life_archive', '家里老人长期卧床或重度失能，去参保地医保部门申请长期护理保险；它不是只发给老人', '17. 家里有老人', '长期护理保险帮你出请人照护的钱。家里有人重度失能、持续半年以上，就去参保地医保部门申请。护理费不用先自己垫，职工参保的报七成左右，城乡居民参保的报五成左右，床位费、伙食费不报。它没有年龄门槛，年轻人重度失能也能申请。', '失能要「长期持续（一般为6个月以上）」，住院几周还不到申请的条件。享受待遇前还有 6 个月等待期。床位费、伙食费这类不算护理的费用，长护险不付。本该医保付的医疗费，长护险也不付。已经在领工伤生活护理费的，不重复享受。这笔钱和残疾人两项补贴里的护理补贴是两套手续、两笔钱，不冲突，见第 7 节第 8 条（两项补贴）。在家里和在社区接受护理，报销比例上有倾斜，不一定非得住进机构。这项制度各地分批落地，失能评估标准也不一样。先打 12393 或者参保地医保经办机构的电话，问本地启没启动、评估怎么约。评估不通过也别放弃，失能状态变重之后可以再申请。', NULL, NULL, NULL, '去参保地医保部门交一次申请。再做一次失能等级评估。第一次评估就通过的，评估费由基金出，不用自己掏', '符合规定的长期护理服务费用不设起付线。起付线就是先自己垫够一个数才开始报，这里不用垫。按单位职工政策参保的，由基金报销约 70%。按未就业城乡居民政策参保的，约 50%。一年最多能报到的钱（年度最高支付限额），不超过本地统筹地区上年度城乡居民人均可支配收入的 50%', '失能要「长期持续（一般为6个月以上）」，住院几周还不到申请的条件。享受待遇前还有 6 个月等待期。床位费、伙食费这类不算护理的费用，长护险不付。本该医保付的医疗费，长护险也不付。已经在领工伤生活护理费的，不重复享受。这笔钱和残疾人两项补贴里的护理补贴是两套手续、两笔钱，不冲突，见第 7 节第 8 条（两项补贴）。在家里和在社区接受护理，报销比例上有倾斜，不一定非得住进机构。这项制度各地分批落地，失能评估标准也不一样。先打 12393 或者参保地医保经办机构的电话，问本地启没启动、评估怎么约。评估不通过也别放弃，失能状态变重之后可以再申请。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"17. 家里有老人","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-8', 'concept_archive_s17-8', 'claim_archive_s17-8', 'action', 'life_archive', '家里有人长期卧床，把压疮当头号敌人：上电动气垫床、定时翻身、每天看一遍骨头突出的地方', '17. 家里有老人', '髋部骨折开刀前就有压疮的老人，30 天内去世的可能性高约两成。换电动气垫床，新长压疮的少约六成。按时翻身真正做到位，少约七成。别让人长时间趴着。每天看一遍骶尾、足跟、髋部、肩背，发现压了不褪的红，当天找护士或医生。', '给 B 的原因有三条。一是死亡率那两项研究只看到「有压疮的人后来处境更差」，这不等于「防住压疮就能把死亡率降下来」。二是翻身间隔那几项随机试验的结论很不牢靠。三是气垫床那条证据要硬一些，但研究里比的是医院病床的垫子，套到家用床垫上属于往外推。每天查骶尾、足跟、髋部、肩背，看有没有「压下去不褪色的红」，这是护理的常规做法，没有单独的文献。长期护理保险能报的照护服务，见本节第 7 条。突然一条腿肿起来，按深静脉血栓处理，见第 13 节第 11 条。因坠落或重伤长期卧床的那一段，见第 1 节第 34 条', NULL, NULL, NULL, '家用电动交替压力气垫床，几百元起。翻一次身只要几分钟。难的是每隔两三小时就得翻一次，夜里也不停，一个人扛不下来', '19520 例髋部骨折手术患者（美国 NSQIP 2016 至 2019 年）。开刀前就有压疮的人，30 天内死亡的比例更高。把其他因素算进去之后，这个关联仍然成立（OR 1.2，几率增加 21%，P=0.004）。这些人还更容易出别的问题：深静脉血栓（OR 1.59）、肺炎（OR 1.39）、非计划再住院（OR 1.43），平均住院日也多 0.4 天。324 名住院老人（平均 86 岁）随访中位 18 个月。压疮能单独预测长期死亡（HR 1.500，95% CI 1.059 至 2.126，P=0.020）。单独预测的意思是，把别的因素排掉之后，它自己就能预测。65 项随机试验放在一起算（网络荟萃分析）。比的是电动主动气流支撑面和标准病床垫（标准病床支撑面）。电动主动气流支撑面就是电动气垫床这一类。用它的人压疮发生率更低（RR 0.42，95% CI 0.29 至 0.63，中等确定性）。电动混合气流支撑面是 RR 0.22（0.07 至 0.66）。11 项试验 4462 人的 Cochrane 综述（2026 年更新）。2 小时翻一次和 4 小时翻一次比，差别说不清（RR 1.05，95% CI 0.79 至 1.39，确定性极低）。其他翻身间隔之间的比较，同样极不确定。1226 名 ICU 患者的试验里，用可穿戴传感器实时提醒并给出视觉警示，把 2 小时翻一次真正落实下来。压疮发生率低于常规护理（RR 0.28，95% CI 0.10 至 0.75，中等确定性）。116 人的试验中，俯卧位（趴着）那组的压疮发生率高于仰卧位（平躺）那组（RR 4.55，95% CI 2.31 至 8.98）', '给 B 的原因有三条。一是死亡率那两项研究只看到「有压疮的人后来处境更差」，这不等于「防住压疮就能把死亡率降下来」。二是翻身间隔那几项随机试验的结论很不牢靠。三是气垫床那条证据要硬一些，但研究里比的是医院病床的垫子，套到家用床垫上属于往外推。每天查骶尾、足跟、髋部、肩背，看有没有「压下去不褪色的红」，这是护理的常规做法，没有单独的文献。长期护理保险能报的照护服务，见本节第 7 条。突然一条腿肿起来，按深静脉血栓处理，见第 13 节第 11 条。因坠落或重伤长期卧床的那一段，见第 1 节第 34 条', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"17. 家里有老人","B 级","性价比 一般","口径 死亡率","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s17-9', 'concept_archive_s17-9', 'claim_archive_s17-9', 'action', 'life_archive', '老人的白内障已经影响看路，就去眼科评估做手术；两只眼都有的，第二只别拖太久', '17. 家里有老人', '70 岁以上的女性尽快做第一只眼的白内障手术，一年里跌倒的次数少约三成四，骨折的人也少了。但摔过跤的人数没有少。第二只眼做不做，跌倒上没看出明显差别。做了手术的老人，一年内髋部骨折低约一成六。', '争议：两项随机试验合起来算，摔过跤的人数没有明显减少（OR 0.81，95% CI 0.55 到 1.17）。澳大利亚西部的全人群住院记录里，做完第一只眼后的一年，因跌倒受伤住院的反而多了 27%。两次手术之间那段，这类住院是术前的 2.14 倍。这类前后对比分不开手术的影响和人变老的影响。另一项澳大利亚的跟踪研究里，做完第二只眼以后，跌倒次数降得最多。所以两只眼都有白内障的，第二只别拖太久。两次手术之间那段，走路和上下楼要格外小心。Cochrane 还收了一项帮老人处理视力问题的试验，跌倒次数反而多了约五成七。手术管的是看不看得清，少摔跤还要靠第 1 节第 13 条（平衡和腿部力量）。骨头经不经得起摔，见第 1 节第 39 条（骨密度检查）和第 1 节第 40 条（查出骨质疏松就用药）。国家眼健康规划写明，白内障复明手术已在县域普遍开展，不一定要去大城市的医院。受益人主要是你的父母和祖父母。', NULL, NULL, NULL, '先陪老人去眼科查一次，由医生判断该不该做。一只眼做一次手术，很多医院按日间手术做，当天就能回家。两只眼都有白内障的，要分两次做。自己掏多少钱，看换进眼里的人工晶体（人造镜片）选哪种、当地医保怎么报，术前问清楚。', '一项随机试验找了 306 名 70 岁以上、有白内障的女性。一半在约 4 周内做第一只眼的手术，另一半按常规等 12 个月。一年里，尽快做手术的人跌倒次数少约 34%。原值是跌倒率之比 0.66，可信范围 95% CI 0.45 到 0.96。跌过至少一次的人，手术组 49%，等待组 45%，没有少。跌过两次以上的人，手术组 18%，等待组 25%。手术组 4 人骨折（3%），等待组 12 人（8%）。Cochrane 综述收了这项试验，结论是女性第一只眼的手术减少了跌倒次数，第二只眼的手术没有。第二只眼的随机试验找了 239 名 70 岁以上的女性。手术组跌倒率低 32%，但差别可能是碰巧（跌倒率之比 0.68，95% CI 0.39 到 1.19）。美国医保 5% 抽样里，有 1113640 名 65 岁以上的白内障病人（2002 到 2009 年）。这项研究只是跟踪记录，没有分组对照。做了手术的人，一年内髋部骨折的几率低约 16%（OR 0.84，95% CI 0.81 到 0.87）。绝对差是 0.20 个百分点，约每 1000 人少 2 例', '争议：两项随机试验合起来算，摔过跤的人数没有明显减少（OR 0.81，95% CI 0.55 到 1.17）。澳大利亚西部的全人群住院记录里，做完第一只眼后的一年，因跌倒受伤住院的反而多了 27%。两次手术之间那段，这类住院是术前的 2.14 倍。这类前后对比分不开手术的影响和人变老的影响。另一项澳大利亚的跟踪研究里，做完第二只眼以后，跌倒次数降得最多。所以两只眼都有白内障的，第二只别拖太久。两次手术之间那段，走路和上下楼要格外小心。Cochrane 还收了一项帮老人处理视力问题的试验，跌倒次数反而多了约五成七。手术管的是看不看得清，少摔跤还要靠第 1 节第 13 条（平衡和腿部力量）。骨头经不经得起摔，见第 1 节第 39 条（骨密度检查）和第 1 节第 40 条（查出骨质疏松就用药）。国家眼健康规划写明，白内障复明手术已在县域普遍开展，不一定要去大城市的医院。受益人主要是你的父母和祖父母。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"17. 家里有老人","B 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s18-1', 'concept_archive_s18-1', 'claim_archive_s18-1', 'action', 'life_archive', '先把能领的算进来：国家育儿补贴每孩每年 3600 元，发到 3 岁', '18. 养孩子划不划算', '孩子在 2025 年 1 月 1 日以后出生、还不满 3 周岁，就能领这笔钱。父母中的一个人去孩子户口所在地申请。每个孩子每年 3600 元，一直领到 3 岁。这笔钱不用交个人所得税。申请低保这类救助时，也不算进你家的收入。', '这是全国统一的最低线。有的省市另有自己的地方补贴，可以和这笔叠加着一起领。三年加起来 10800 元，在养孩子的开支里只是很小的一块，别把它当成生不生的依据', NULL, NULL, NULL, '不花钱。去孩子户口所在地申请，跑一趟就办完', '中共中央办公厅、国务院办公厅印发的方案规定：2025 年 1 月 1 日起出生、3 周岁以下的婴幼儿，按「每孩每年 3600 元」发放。由孩子的父母一方或者其他监护人去申领。这笔补贴「免征个人所得税」。认定低保这类救助的时候，它「不计入家庭或个人收入」', '这是全国统一的最低线。有的省市另有自己的地方补贴，可以和这笔叠加着一起领。三年加起来 10800 元，在养孩子的开支里只是很小的一块，别把它当成生不生的依据', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"18. 养孩子划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s18-2', 'concept_archive_s18-2', 'claim_archive_s18-2', 'action', 'life_archive', '产假 98 天，生育津贴由生育保险基金按单位上年度职工月平均工资发', '18. 养孩子划不划算', '生孩子至少能休 98 天产假，其中产前可以先休 15 天。难产再加 15 天。每多生一个孩子，也再加 15 天。这段时间发的钱叫生育津贴，由生育保险基金出。单位没给你上生育保险的，就由单位自己发。', '98 天是国家定的最低标准。各省的人口与计划生育条例普遍还要再加 60 天以上的生育奖励假，加起来通常是 158 天起。奖励假这段时间的工资由哪一方出，各省规定不一样', NULL, NULL, NULL, '不花钱。由单位去申报，你自己不用跑', '产假天数由国务院规定。「女职工生育享受 98 天产假，其中产前可以休假 15 天；难产的，增加产假 15 天；生育多胞胎的，每多生育 1 个婴儿，增加产假 15 天。」产假期间拿的钱叫生育津贴。已经参加生育保险的，「按照用人单位上年度职工月平均工资的标准由生育保险基金支付」。没参保的，由用人单位按你产假前的工资标准发给你', '98 天是国家定的最低标准。各省的人口与计划生育条例普遍还要再加 60 天以上的生育奖励假，加起来通常是 158 天起。奖励假这段时间的工资由哪一方出，各省规定不一样', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"18. 养孩子划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s18-3', 'concept_archive_s18-3', 'claim_archive_s18-3', 'action', 'life_archive', '知道这条：不得因怀孕、生育、哺乳降工资或者辞退', '18. 养孩子划不划算', '怀孕、生孩子、喂奶这几段时间里，单位给你降工资或者把你辞了，都是违法的，要按每人 1000 到 5000 元罚款。孩子不满一周岁的，你每天有 1 小时喂奶时间，单位也不能安排你加班和上夜班。索赔怎么走见第 19 节。', '真的被违法辞退了，索赔路径见第 19 节。取证的重点是调岗、降薪的书面通知和聊天记录，这两样要留好', NULL, NULL, NULL, '不花钱', '国务院规定：「用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。」这三段时间里单位不能给你减钱，也不能把你辞退或者解约。哺乳未满 1 周岁婴儿的，每天有 1 小时哺乳时间。单位也不得安排你延长劳动时间，不得安排夜班。单位违反上面这些的，按每人 1000 元以上 5000 元以下罚款', '真的被违法辞退了，索赔路径见第 19 节。取证的重点是调岗、降薪的书面通知和聊天记录，这两样要留好', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"18. 养孩子划不划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s18-4', 'concept_archive_s18-4', 'claim_archive_s18-4', 'action', 'life_archive', '时间账按「谁的时间被占掉」算，不按「辛不辛苦」算', '18. 养孩子划不划算', '把每天看孩子的小时数、夜里被吵醒的次数，都折算成时间。再乘上干这些活的那个人的时薪。算出来的数，一般远远大于奶粉尿布钱。所以分工最好在生之前就谈好。', '数字不必算得很准。有用的是两个人在生之前对着同一张表谈分工，免得生完再吵', NULL, NULL, NULL, '不花钱，花的是时间。孩子 3 岁前基本是全天被占住。难在天天如此，没法咬牙几天就过去', '把每天照看孩子的时间、夜里被吵醒的次数，都折算成小时。再乘以干这些活的那个人的时薪。得到的数字通常远大于奶粉尿布钱。照看、做饭、夜里起夜这些活虽然没人付钱，也照这样记进成本。算法和第 10 节算家务的那套一样。先谈好分工，再决定生不生', '数字不必算得很准。有用的是两个人在生之前对着同一张表谈分工，免得生完再吵', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"18. 养孩子划不划算","C 级","性价比 一般","口径 时间","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s18-5', 'concept_archive_s18-5', 'claim_archive_s18-5', 'action', 'life_archive', '钱账分三段算：0 到 3 岁、义务教育、义务教育之后', '18. 养孩子划不划算', '0 到 3 岁的钱，主要花在怎么带上：自己带、老人带，还是请人带。小学到初中这段，主要花在住房和课外。再往后，主要花在升学这条路上。三段的花法完全不同，混在一起只会算出一个吓人的总数。', '先把育儿补贴、生育津贴、医保报销这些确定能拿到的钱算进来，再看还差多少。别拿网上流传的「养大一个孩子要多少万」做决定，那类数字口径不明，你不知道它算了哪些、又漏了哪些', NULL, NULL, NULL, '花多少钱没有固定数，城市不同、带法不同，差得很远。难在要静下心来把三段账分开算，不能凭感觉拍一个数', '0 到 3 岁的大头是照料方式：自己带、老人带还是请人带。义务教育阶段（小学到初中）的大头是住房和课外支出。这之后的大头是升学路径。这三段钱花在哪完全不同，混在一起算，只会得到一个吓人的总数', '先把育儿补贴、生育津贴、医保报销这些确定能拿到的钱算进来，再看还差多少。别拿网上流传的「养大一个孩子要多少万」做决定，那类数字口径不明，你不知道它算了哪些、又漏了哪些', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"18. 养孩子划不划算","C 级","性价比 一般","口径 金钱","钱 多","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s18-6', 'concept_archive_s18-6', 'claim_archive_s18-6', 'action', 'life_archive', '为长辈生、为婚姻生、为养老生，各记一笔账', '18. 养孩子划不划算', '别人希望你生，这可以算你的一个考虑因素。但时间和钱是记在你自己账上的。「养儿防老」要单独算一笔，因为它赌的是二十年后另一个人的经济能力和意愿。把不生的后果也写下来，两边对照。', '把「不生的后果」也写下来，和「生的后果」放在一起对照着看', NULL, NULL, NULL, '不花钱，花的是一次认真的谈话。难在要把话说开，不绕过去', '思路和第 10 节一样。别人的期待可以算你的一个考虑因素。但成本要记在你自己的账上，不记在他们账上。「养儿防老」尤其要单独算一笔，因为它假定的是二十年后另一个人的经济能力和意愿', '把「不生的后果」也写下来，和「生的后果」放在一起对照着看', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"18. 养孩子划不划算","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-1', 'concept_archive_s19-1', 'claim_archive_s19-1', 'action', 'life_archive', '加班费按 1.5 倍、2 倍、3 倍三档算，不给就投诉劳动监察，逾期不付还要加付 50% 到 100%', '19. 在职、离职和工伤', '平时加班按工资的 1.5 倍给钱。休息日加班又没让你补休，按 2 倍。元旦、春节、劳动节、国庆这类法定假日上班按 3 倍，而且不能拿补休顶掉。公司不给，就去劳动监察投诉。被责令限期付款以后还不给的，单位还要另加付欠款的一半到一倍。', '休息日和法定休假日要分开算。法定休假日全年只有元旦、春节、劳动节、国庆节等法定的那几天。调休凑出来的连休日按休息日算，给 200%。「公司规定加班要审批」「我是自愿留下的」，这两句话不等于公司就可以不给钱，但会让你更难拿出证据，所以派活和审批记录要留着。公司想实行综合计算工时制、不定时工时制这两种特殊工时安排，得先经劳动行政部门批准，不是自己说了算。争议的仲裁时效见第 8 节第 19 条。', NULL, NULL, NULL, '不花钱。平时顺手把打卡记录、排班表、加班审批单存一份，工作群里领导派活的消息也截图留着。难在每个月都要记得存。', '法律规定的正常上班时间是每天不超过 8 小时，平均每周不超过 44 小时。平时加班一般每天不得超过 1 小时。有特殊原因要多干的，每天不得超过 3 小时，而且一个月加起来不得超过 36 小时。加班费分三档。平时安排你延长工作时间的，按不低于工资的 150% 给。休息日安排你上班、又安排不了补休的，不低于 200%。法定休假日安排你上班的，不低于 300%。法定休假日这一档，法条里没有「拿补休顶掉」这个选项。单位安排了加班又不给加班费的，由劳动行政部门勒令它限期付清。过了期限还不付的，勒令它在欠款之外，再按应付金额的 50% 以上 100% 以下加付一笔赔偿金给劳动者（全国）', '休息日和法定休假日要分开算。法定休假日全年只有元旦、春节、劳动节、国庆节等法定的那几天。调休凑出来的连休日按休息日算，给 200%。「公司规定加班要审批」「我是自愿留下的」，这两句话不等于公司就可以不给钱，但会让你更难拿出证据，所以派活和审批记录要留着。公司想实行综合计算工时制、不定时工时制这两种特殊工时安排，得先经劳动行政部门批准，不是自己说了算。争议的仲裁时效见第 8 节第 19 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-2', 'concept_archive_s19-2', 'claim_archive_s19-2', 'action', 'life_archive', '年休假按累计工龄算 5、10、15 天，没休成的按日工资 300% 折钱', '19. 在职、离职和工伤', '在所有单位的工龄加起来满 1 年不满 10 年，每年 5 天年休假。满 10 年是 10 天，满 20 年是 15 天。换过工作也照样往上累计。单位安排不了、你又同意不休的，那几天按日工资的 3 倍给钱。「自愿放弃年休假」的表一签，就只剩正常工资了。', '累计工作时间要跨单位加起来算，换过工作的别按现单位工龄算。只有职工「因本人原因且书面提出不休」，单位才可以只支付正常工资，所以「自愿放弃年休假」的表别签。请事假累计 20 天以上、单位又不扣你工资的，当年不享受年休假。病假超过对应月数的也不享受：工龄不满 10 年是 2 个月，10 到 20 年是 3 个月，20 年以上是 4 个月。探亲假、婚丧假、产假和工伤停工留薪期不计入年休假。', NULL, NULL, NULL, '不花钱。把自己在所有单位干过的年头加起来算一遍，社保缴费记录就是证明。难在公司递「自愿放弃年休假」的表时要能不签。', '连续工作满 12 个月就有年休假。天数按累计工作时间定，在所有单位干过的年头都加起来算。满 1 年不满 10 年 5 天，满 10 年不满 20 年 10 天，满 20 年 15 天。国家法定休假日和休息日不算进年休假的天数里。单位确实因为工作需要安排不了、又征得你本人同意不休的，该休没休的那几天「按照该职工日工资收入的 300% 支付年休假工资报酬」。这 300% 里已经含了正常上班那天本来就该给的一份，所以实际额外多拿到手的是 200%。日工资 = 本人月工资 ÷ 21.75。月工资按发这笔钱之前 12 个月的工资算，去掉加班费之后取月平均数。当年才进单位的，按在这家单位剩下的日历天数折算。离职时按当年已经干了多久折算并结清，已经多休的不倒扣回来。单位既不安排休、又不给钱的，勒令限期改正。过了期限还不改的，除了那笔年休假工资报酬，还要再按同样的数额加付一笔赔偿金（全国，2008 年 1 月 1 日起施行）', '累计工作时间要跨单位加起来算，换过工作的别按现单位工龄算。只有职工「因本人原因且书面提出不休」，单位才可以只支付正常工资，所以「自愿放弃年休假」的表别签。请事假累计 20 天以上、单位又不扣你工资的，当年不享受年休假。病假超过对应月数的也不享受：工龄不满 10 年是 2 个月，10 到 20 年是 3 个月，20 年以上是 4 个月。探亲假、婚丧假、产假和工伤停工留薪期不计入年休假。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-3', 'concept_archive_s19-3', 'claim_archive_s19-3', 'action', 'life_archive', '试用期有法定上限、工资不得低于 80%，而且只能约定一次', '19. 在职、离职和工伤', '合同签 1 年以内的，试用期最多 1 个月。签 1 到 3 年的最多 2 个月。签 3 年以上的最多 6 个月。同一家公司只能试用你一次，转正后调个岗再来一次是违法的。试用期工资不能低于同岗位最低档或者合同约定工资的 80%，也不能低于当地最低工资。', '最常见的三种违法做法。一是合同只签 1 年，却约定 3 个月试用期。二是转正之后调岗，再来一次试用期。三是「试用期不交社保」，社保义务从上班第一天起算，和试不试用无关，用人一侧的义务见第 12 节第 16 条。试用期被辞退不等于一分钱没有，要看单位给的理由是不是法律允许辞退的那几种。被违法解除的按第 6 条算 2N。', NULL, NULL, NULL, '不花钱。签字前花几分钟，把合同写的期限和试用期长度对一遍。', '合同签 3 个月以上不满 1 年的，试用期不得超过 1 个月。签 1 年以上不满 3 年的，不得超过 2 个月。签 3 年以上的，以及不写到期日的无固定期限合同，不得超过 6 个月。以干完一件活为期限的合同，或者总共不到 3 个月的合同，不许约定试用期。「同一用人单位与同一劳动者只能约定一次试用期」，同一家公司对同一个人只能试用一回。合同里只写了试用期的，这段试用期不成立，这个期限就是劳动合同期限。试用期工资「不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准」。试用期约得超过法定长度、人又实际干了的，单位要按你试用期满后的月工资标准，就超出去的那段时间另付一笔赔偿金。试用期内单位想解除合同，只能按法律列明的那几种情形，而且要向劳动者说明理由（全国）', '最常见的三种违法做法。一是合同只签 1 年，却约定 3 个月试用期。二是转正之后调岗，再来一次试用期。三是「试用期不交社保」，社保义务从上班第一天起算，和试不试用无关，用人一侧的义务见第 12 节第 16 条。试用期被辞退不等于一分钱没有，要看单位给的理由是不是法律允许辞退的那几种。被违法解除的按第 6 条算 2N。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-4', 'concept_archive_s19-4', 'claim_archive_s19-4', 'action', 'life_archive', '被裁先算清 N：每满一年一个月工资，不满六个月按半个月', '19. 在职、离职和工伤', '被裁时公司要给的经济补偿这样算：干满一年给一个月工资，满半年不满一年按一年算，不满半年给半个月。这里的月工资是走人前 12 个月的平均数，奖金、津贴、补贴都要算进去。工资高过当地上年度月平均工资 3 倍的按 3 倍封顶，年限最多算 12 年。', '月工资指劳动合同解除前十二个月的平均工资。奖金、津贴和补贴都要算进去，不是只算基本工资。这一点最容易被公司做低。这笔钱要不要交个税，见本节第 18 条（补偿的个税）', NULL, NULL, NULL, '不花钱。拿计算器算一次，十分钟。', '劳动合同法定的经济补偿，就是被裁时单位该给的那笔钱，大家常叫它 N。算法是：「每满一年支付一个月工资……六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资」。月工资高过当地上年度职工月平均工资三倍的，按三倍封顶算，而且工龄最多只算到十二年', '月工资指劳动合同解除前十二个月的平均工资。奖金、津贴和补贴都要算进去，不是只算基本工资。这一点最容易被公司做低。这笔钱要不要交个税，见本节第 18 条（补偿的个税）', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-5', 'concept_archive_s19-5', 'claim_archive_s19-5', 'action', 'life_archive', '公司辞退你没提前 30 天通知，还要多付一个月工资', '19. 在职、离职和工伤', '公司因为你病后干不了、干不了工作或者情况大变而辞退你，没有提前 30 天书面通知，要在 N 之外再多给一个月工资，这就是常说的 N+1。谈的时候把这一个月单独列出来，别让公司把它算进 N 里面。', '这一个月只出现在劳动合同法第四十条的三种情形里：生病或非因工负伤、医疗期满后干不了原来的活也干不了另安排的活；干不了工作、培训或调岗后仍干不了；订合同时的客观情况发生重大变化、协商不成。别的情形没有这一个月：经济性裁员（第四十一条）只要求公司提前 30 天向工会或者全体职工说明情况；公司提出、双方协商解除的是 N；你有严重违纪这类过错被辞退，没有补偿；公司违法解除是 2N。属于第四十条那三种的，谈判时把 N 和 1 分开算，别让公司把多的那一个月算进 N 里', NULL, NULL, NULL, '不花钱。', '劳动合同法规定，用人单位按这一条解除劳动合同的，有两种做法。一种是「提前三十日以书面形式通知劳动者本人」。另一种是「额外支付劳动者一个月工资后，可以解除劳动合同」。想让你立刻走，就得多掏一个月工资。这多出来的一个月俗称代通知金，是 N 之外另算的一笔。这一个月按你上一个月的工资算，N 按离职前 12 个月的平均工资算，两笔的基数不一样', '这一个月只出现在劳动合同法第四十条的三种情形里：生病或非因工负伤、医疗期满后干不了原来的活也干不了另安排的活；干不了工作、培训或调岗后仍干不了；订合同时的客观情况发生重大变化、协商不成。别的情形没有这一个月：经济性裁员（第四十一条）只要求公司提前 30 天向工会或者全体职工说明情况；公司提出、双方协商解除的是 N；你有严重违纪这类过错被辞退，没有补偿；公司违法解除是 2N。属于第四十条那三种的，谈判时把 N 和 1 分开算，别让公司把多的那一个月算进 N 里', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-6', 'concept_archive_s19-6', 'claim_archive_s19-6', 'action', 'life_archive', '公司违法解除的，赔偿金是经济补偿标准的二倍', '19. 在职、离职和工伤', '公司属于违法解除的，赔偿金按经济补偿的标准翻倍，也就是常说的 2N。是不是违法解除要看具体情形。先找法律援助或者律师问清楚，再决定是跟公司谈，还是去仲裁。', '这就是俗称的 2N。什么算违法解除要看具体情形。先咨询法律援助或者律师，再决定是谈还是去仲裁，路径见第 7 节', NULL, NULL, NULL, '不花钱。走仲裁要等几个月。难在这几个月要一直跟着办，不能中途放弃。', '劳动合同法规定，用人单位违反本法规定解除或者终止劳动合同的，「应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金」。算法是先按经济补偿那套标准算出一份，再翻一倍给你', '这就是俗称的 2N。什么算违法解除要看具体情形。先咨询法律援助或者律师，再决定是谈还是去仲裁，路径见第 7 节', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-7', 'concept_archive_s19-7', 'claim_archive_s19-7', 'action', 'life_archive', '不要签「个人原因主动辞职」，那一签就没有 N 了', '19. 在职、离职和工伤', '签字承认「个人原因主动辞职」，经济补偿和失业保险金通常一起落空。自己提出离职，本来就不在给补偿的那几种情形里，公司欠薪、不缴社保这类过错除外。不必当天签，冷静一晚再说。', '公司常用的话术是「先签了好走流程，补偿另外给」。要就当场写进协议，不写就不签。当天不签不会有任何法律后果，冷静一晚再说', NULL, NULL, NULL, '不花钱。难在要顶住当场签字的压力。', '劳动合同法把该给经济补偿的情形限定在法律列明的那几类里。劳动者自己提出走人，不在里面，除非是因为公司欠薪、不缴社保这类法定过错。签了「主动辞职」，经济补偿和失业保险金通常一起落空', '公司常用的话术是「先签了好走流程，补偿另外给」。要就当场写进协议，不写就不签。当天不签不会有任何法律后果，冷静一晚再说', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-8', 'concept_archive_s19-8', 'claim_archive_s19-8', 'action', 'life_archive', '离职前把工资条、考勤、劳动合同、社保记录和聊天记录先存下来', '19. 在职、离职和工伤', '电脑和账号一交回去，工资条、考勤、合同、社保记录和聊天记录就再也拿不到了。仲裁时工资多少、有没有加班，还是要靠你自己手上的材料。存的是自己的劳动关系材料，公司的源码和客户名单不要带走。', '存的是自己的劳动关系材料。不要顺手带走公司的源码、客户名单和技术文档，带走的风险见第 11 节。走的时候还要找单位要离职证明，见本节第 17 条（离职证明）', NULL, NULL, NULL, '不花钱。花半小时把材料存好。难在走之前要记得存。', '一旦交回电脑和账号，这些材料就再也拿不到了。仲裁时谁来举证，虽然会朝单位那边偏一些，但工资多少、有没有加班这些事，还是要靠你自己手上的证据', '存的是自己的劳动关系材料。不要顺手带走公司的源码、客户名单和技术文档，带走的风险见第 11 节。走的时候还要找单位要离职证明，见本节第 17 条（离职证明）', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-9', 'concept_archive_s19-9', 'claim_archive_s19-9', 'action', 'life_archive', '进有粉尘、噪声、化学品的岗位之前，先看合同里写没写危害；三次职业健康检查由单位安排并掏钱', '19. 在职、离职和工伤', '签合同时，单位必须把岗位有什么职业病危害、怎么防护、有什么待遇如实写进合同。瞒了你，你可以拒绝干这个活，单位不能因此辞退你。上岗前、在岗时、离岗时三次职业健康检查，由单位安排并掏钱。没做离岗体检，单位不能和你解除合同。', '面试时问三句，就能大致判断这家正不正规：这个岗位有没有职业病危害、合同里写不写、上岗前体检谁出钱。答不上来或者说「先干着再说」的，风险自己掂量。离岗体检最容易被忽略：没做离岗体检，单位不能和你解除或终止劳动合同。这份体检还是日后申请职业病诊断的关键材料，档案复印件同理，走之前要拿到手。职业病本身按工伤走，待遇见第 11 条起。', NULL, NULL, NULL, '不花钱。签合同时把「职业病危害告知」那部分逐条看完。每次体检的报告都要一份自己留着。难在要当面开口问、当面把材料要到手。', '职业病防治法规定，签劳动合同的时候，单位要把四件事讲清楚：干这份活可能产生哪些职业病危害、会落下什么后果、怎么防护、有什么待遇。法条原文是「如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗」。合同签完之后又调你去干合同里没交代过的有害活儿的，要重新如实告知，并且跟你商量着改合同条款。单位没做到的，「劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同」。体检一共三次：上岗前、在岗期间、离岗时。「职业健康检查费用由用人单位承担」，钱由单位出，结果要书面告诉你本人。没做上岗前体检的人，单位不得安排去干接触职业病危害的活。身体条件本来就不适合这类活的人（有职业禁忌的），也不得安排去干这些禁忌作业。查出跟这份工作有关的健康损害的，要把人调离原岗位并妥善安置。「对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同」。离职时你「有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章」。这份职业健康监护档案，单位要照实复印一份免费给你，还要在复印件上盖章（全国）', '面试时问三句，就能大致判断这家正不正规：这个岗位有没有职业病危害、合同里写不写、上岗前体检谁出钱。答不上来或者说「先干着再说」的，风险自己掂量。离岗体检最容易被忽略：没做离岗体检，单位不能和你解除或终止劳动合同。这份体检还是日后申请职业病诊断的关键材料，档案复印件同理，走之前要拿到手。职业病本身按工伤走，待遇见第 11 条起。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-10', 'concept_archive_s19-10', 'claim_archive_s19-10', 'action', 'life_archive', '粉尘、噪声、化学毒物造成的损伤不可逆：防护用品单位必须给，没有防护措施的作业可以拒绝', '19. 在职、离职和工伤', '尘肺、噪声聋、化学性眼灼伤都是法定职业病，肺和听力坏了就治不回来。你有权知道岗位有什么危害，有权要单位给防护设施和防护用品。没有防护的活你可以不干。单位因此给你降薪或辞退你，都不算数。', '口罩要认对，防颗粒物的口罩才挡粉尘，普通纱布口罩和一次性外科口罩不挡。噪声岗位单位不发耳塞就自己买，几元一副，听力掉了补不回来。「干两年攒够钱就走」在尘肺上不成立。矽肺可以在脱离粉尘作业多年之后才发病，而且还会继续加重。所以离岗体检格外重要（见第 9 条，三次职业健康检查由单位安排并掏钱）。新版目录还新增了两类。一类是职业性肌肉骨骼疾病，里面是腕管综合征，只限长时间重复用手腕或者用力干活的制造业工人。另一类是职业性精神和行为障碍，里面是创伤后应激障碍，只限参与突发事件处置的人民警察、医疗卫生人员、消防救援等应急救援人员。化学品溅到身上的现场处理见第 13 节第 21 条。', NULL, NULL, NULL, '不花钱。难在要一直戴防颗粒物口罩、耳塞、护目镜，还要拒绝没有防护的活，代价是可能被同事说「事多」。', '法定职业病自 2025 年 8 月 1 日起是 12 大类 135 种，其中含 4 项开放性条款。排在第一类的是职业性尘肺病。里面有矽肺、煤工尘肺、石墨尘肺、碳黑尘肺、石棉肺、滑石尘肺。还有水泥尘肺、云母尘肺、陶工尘肺、铝尘肺、电焊工尘肺、铸工尘肺，再加一项开放条款。职业性耳鼻喉口腔疾病里有噪声聋和爆震聋。职业性眼病里有化学性眼部灼伤和电光性眼炎。这些损伤都不可逆，没有哪种治疗能把肺和听力修回来。法律给了四条可以当场搬出来用的权利。一是知道这个工作场所里有哪些职业病危害、会造成什么后果、该采取哪些防护措施。二是要求单位提供合格的防护设施和个人防护用品、改善工作条件。三是对违反职业病防治法律法规的做法、以及会危及生命健康的做法提出批评、检举和控告。四是「拒绝违章指挥和强令进行没有职业病防护措施的作业」，不合规的指挥和没有防护的活，你可以不干。并且「因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效」。因为你用了这几条权利就给你降薪、降待遇或者辞退你，这些做法不算数（全国）', '口罩要认对，防颗粒物的口罩才挡粉尘，普通纱布口罩和一次性外科口罩不挡。噪声岗位单位不发耳塞就自己买，几元一副，听力掉了补不回来。「干两年攒够钱就走」在尘肺上不成立。矽肺可以在脱离粉尘作业多年之后才发病，而且还会继续加重。所以离岗体检格外重要（见第 9 条，三次职业健康检查由单位安排并掏钱）。新版目录还新增了两类。一类是职业性肌肉骨骼疾病，里面是腕管综合征，只限长时间重复用手腕或者用力干活的制造业工人。另一类是职业性精神和行为障碍，里面是创伤后应激障碍，只限参与突发事件处置的人民警察、医疗卫生人员、消防救援等应急救援人员。化学品溅到身上的现场处理见第 13 节第 21 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-11', 'concept_archive_s19-11', 'claim_archive_s19-11', 'action', 'life_archive', '上班受伤、上下班路上被撞，第一件事是做工伤认定，单位不报你自己报', '19. 在职、离职和工伤', '上班受伤算工伤。上下班路上被撞、主要责任不在你的，也算工伤。但不做工伤认定，医药费、养伤期间照发的工资、伤残补助金就全部落空。单位应当在 30 天内申报。单位不报的，你或者家属、工会可以在一年内自己去社保行政部门报。', '1 年要当真，别拖。但不是你自己的原因耽误的时间不算在 1 年里：不可抗力、人身自由受限、单位的原因、社保部门登记制度不完善、为确认劳动关系去申请仲裁或者打官司。所以单位拖着不报、拖到超期的，照样去申请，并把单位拖延的证据带上。社保部门不受理，或者认定结论你不服，可以申请行政复议，也可以直接起诉。单位说不算工伤，得由单位举证。但你自己也要留材料：出事当天的照片、同事联系方式、就诊记录、考勤。条例第十六条列了三种不认的情形：故意犯罪、醉酒或者吸毒、自残或者自杀。第十五条另有「视同工伤」：在工作时间和工作岗位突发疾病死亡，或者 48 小时之内经抢救无效死亡的。', NULL, NULL, NULL, '不花钱，跑一趟社保行政部门。要带三样材料：工伤认定申请表、劳动关系证明、医疗诊断证明。', '没做工伤认定，医药费、养伤期间照发的工资（停工留薪期工资）、伤残补助金就全部落空。单位超过 30 日不申报的，这段时间里该给的工伤待遇费用由单位自己掏', '1 年要当真，别拖。但不是你自己的原因耽误的时间不算在 1 年里：不可抗力、人身自由受限、单位的原因、社保部门登记制度不完善、为确认劳动关系去申请仲裁或者打官司。所以单位拖着不报、拖到超期的，照样去申请，并把单位拖延的证据带上。社保部门不受理，或者认定结论你不服，可以申请行政复议，也可以直接起诉。单位说不算工伤，得由单位举证。但你自己也要留材料：出事当天的照片、同事联系方式、就诊记录、考勤。条例第十六条列了三种不认的情形：故意犯罪、醉酒或者吸毒、自残或者自杀。第十五条另有「视同工伤」：在工作时间和工作岗位突发疾病死亡，或者 48 小时之内经抢救无效死亡的。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-12', 'concept_archive_s19-12', 'claim_archive_s19-12', 'action', 'life_archive', '别信「撑到工位就算工伤」：突发不适先打 120，不是先赶去打卡', '19. 在职、离职和工伤', '突发不适往公司赶，不会让你多拿一笔钱。视同工伤要求人在工作时间、又在工作岗位上发病，路上发病没到岗的本来就不算。抢救超过 48 小时的反而也不算。为了凑条件耽误的那几十分钟，换掉的是自己的存活率。', '两个条件要同时满足：在工作时间，并且在工作岗位。路上发病没到岗的不适用。在岗发病后被送回家或者送医、48 小时内经抢救无效死亡的，仍可能适用。看的是发病时人在哪，不看最后死在哪。短视频把这条讲成「撑到公司就有钱」，方向正好反了。能改变结局的是发病后那几十分钟有没有去医院。另外 48 小时是硬线，抢救超过 48 小时反而不算。', NULL, NULL, NULL, '不花钱。', '视同工伤要求人「在工作时间和工作岗位」上突发疾病死亡，或者在 48 小时之内经抢救无效死亡。为了凑齐这两个条件而耽误就医，赔的是自己活下来的机会，换来的赔偿也不一定拿得到', '两个条件要同时满足：在工作时间，并且在工作岗位。路上发病没到岗的不适用。在岗发病后被送回家或者送医、48 小时内经抢救无效死亡的，仍可能适用。看的是发病时人在哪，不看最后死在哪。短视频把这条讲成「撑到公司就有钱」，方向正好反了。能改变结局的是发病后那几十分钟有没有去医院。另外 48 小时是硬线，抢救超过 48 小时反而不算。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-13', 'concept_archive_s19-13', 'claim_archive_s19-13', 'action', 'life_archive', '单位没给你交工伤保险，工伤待遇一样有，由单位按同样的标准全额出', '19. 在职、离职和工伤', '单位没给你交工伤保险，工伤待遇一样有。只是改成由单位按同样的项目和标准全额付，一分不少。没参保是对单位加罚：责令补缴、按日加收万分之五滞纳金，逾期还要罚欠缴额的 1 到 3 倍。「公司没买工伤险所以赔不了」是假话。', '「公司没给你买工伤险，所以赔不了」是这类事里最常见的一句假话。没参保只会让单位被加罚，你的待遇不减。', NULL, NULL, NULL, '不花钱。单位不认的，就要走仲裁甚至打官司，几个月起步。难在这几个月要一直跟着办。', '条例明写：没给员工交工伤保险的单位，员工出了工伤，由这家单位按条例规定的项目和标准把钱付出来。该给哪几笔、每笔给多少，和交了保险的完全一样，只是改成单位自己掏', '「公司没给你买工伤险，所以赔不了」是这类事里最常见的一句假话。没参保只会让单位被加罚，你的待遇不减。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-14', 'concept_archive_s19-14', 'claim_archive_s19-14', 'action', 'life_archive', '伤情稳定后去做劳动能力鉴定，伤残等级直接换算成钱', '19. 在职、离职和工伤', '伤情稳定之后去做劳动能力鉴定，等级直接换算成钱。一次性伤残补助金按本人工资算：五级 18 个月、六级 16 个月、七级 13 个月、八级 11 个月、九级 9 个月、十级 7 个月。鉴定结果出来之前，不要签「一次性了结」的协议。', '五级、六级保留劳动关系，人还算这家单位的员工，按月拿伤残津贴。七到十级的人，合同到期或者自己提出解除时，另有两笔钱：一次性工伤医疗补助金由基金出，一次性伤残就业补助金由单位出，给多少由省里定。鉴定结果出来之前不要签「一次性了结」的协议。', NULL, NULL, NULL, '不花钱。走一次劳动能力鉴定的流程，前后要等一段时间。', '一次性伤残补助金按伤残等级折算成几个月的工资，一次付清。五级 18 个月、六级 16 个月、七级 13 个月的本人工资。八级 11 个月、九级 9 个月、十级 7 个月的本人工资', '五级、六级保留劳动关系，人还算这家单位的员工，按月拿伤残津贴。七到十级的人，合同到期或者自己提出解除时，另有两笔钱：一次性工伤医疗补助金由基金出，一次性伤残就业补助金由单位出，给多少由省里定。鉴定结果出来之前不要签「一次性了结」的协议。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-15', 'concept_archive_s19-15', 'claim_archive_s19-15', 'action', 'life_archive', '工亡的三笔钱要分清：丧葬补助金、供养亲属抚恤金、一次性工亡补助金', '19. 在职、离职和工伤', '因工死亡是三笔钱，别只谈其中一笔。丧葬补助金是当地上年度职工月平均工资的 6 个月。供养亲属抚恤金按死者本人工资按月发，配偶每月 40%，其他亲属每人每月 30%。一次性工亡补助金是上一年度全国城镇居民人均可支配收入的 20 倍，全国就这一个数。', '一次性工亡补助金全国统一，金额每年随国家统计局公布的数据更新。谈赔偿时不接受「我们这边地方标准低」的说法。', NULL, NULL, NULL, '不花钱，办一套手续。', '因工死亡的钱分三笔。第一笔是丧葬补助金，金额是参保所在地区（统筹地区）上年度职工月平均工资的 6 个月。第二笔是供养亲属抚恤金，按死者本人工资按月发，配偶每月 40%，其他亲属每人每月 30%。第三笔是一次性工亡补助金，金额是上一年度全国城镇居民人均可支配收入的 20 倍，全国只有这一个数，不分地区。2026 年因工死亡的，这一笔是约 113 万元（1130040 元）。算法是上一年度全国城镇居民人均可支配收入 56502 元乘以 20。', '一次性工亡补助金全国统一，金额每年随国家统计局公布的数据更新。谈赔偿时不接受「我们这边地方标准低」的说法。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-16', 'concept_archive_s19-16', 'claim_archive_s19-16', 'action', 'life_archive', '在单位长期被欺负、辱骂、刁难，别硬扛：先记下来留证据，再按性质走投诉、报警或者仲裁', '19. 在职、离职和工伤', '在单位被欺负的人，后来得心脏病、中风的风险高约六成，被欺负得越多风险越高。被欺负的人几年后冒出自杀念头的几率约是别人的两倍。挨骂受气不是忍一忍就过去的小事。', '定 B 的理由：健康数字来自跟踪记录，不是分组实验，「被欺负」是本人自己报的。能先做的有四步。第一步，从今天起记录，录音见第 8 节第 41 条（录音）。第二步，按单位内部渠道书面反映，留下反映过的记录。第三步，被打、被关、被当众侮辱的，报警。第四步，因为欠薪、不缴社保被逼走的，按本节第 7 条（别签主动辞职）和第 8 条（离职前存证据）来办。经济补偿怎么算，见本节第 4 条（被裁先算清 N）。单纯的冷落、排挤、刁难，多数对不上哪一条法律，能走的主要是内部投诉、调岗和换工作。仲裁从受理起最长 60 天，打官司一审 6 个月起，律师费自己出。已经撑不住了，先打 12356，见第 1 节第 25 条（12356）。不主张一受气就辞职，换工作的代价由你自己算。', NULL, NULL, NULL, '不花钱。要花时间记录：日期、在场的人、对方原话，聊天截图和邮件留原件。走仲裁、打官司要花几个月。换工作的代价最高，走不走由你自己算。', '健康上，瑞典和丹麦三个队列合起来，共 79,201 名 18 到 65 岁的在职者。他们起初都没有心血管病，平均跟踪 12.4 年。9% 的人说过去一年在单位被欺负过。被欺负的人得心血管病（冠心病和脑血管病）的风险高约 59%（HR 1.59，95% CI 1.28–1.98）。在单位遭遇过暴力的，高约 25%（HR 1.25，1.12–1.40）。两种都是遭遇越多，风险越高。挪威一项全国随机抽样的跟踪调查，1846 名在职者，隔两到三年测一次，共测三次。被欺负的人后来出现自杀念头的几率约是别人的 2 倍（OR 2.05，95% CI 1.08–3.89）。反过来，先有自杀念头的人，后来并不更容易被欺负。法律上，我国没有专门管「职场霸凌」的法律，要按具体行为对号。单位侮辱、体罚、殴打、非法搜查或者拘禁劳动者的，要受行政处罚，造成损害要赔偿，构成犯罪的追究刑事责任。单位用暴力、威胁强迫你干活的，你可以立即解除合同，不用事先通知，还能拿经济补偿。单位要采取措施，预防和制止有人利用职权、上下级关系实施性骚扰。受害人可以要求骚扰的人承担民事责任。劳动仲裁从受理那天算起 45 日内结案，复杂的最多再延 15 日。', '定 B 的理由：健康数字来自跟踪记录，不是分组实验，「被欺负」是本人自己报的。能先做的有四步。第一步，从今天起记录，录音见第 8 节第 41 条（录音）。第二步，按单位内部渠道书面反映，留下反映过的记录。第三步，被打、被关、被当众侮辱的，报警。第四步，因为欠薪、不缴社保被逼走的，按本节第 7 条（别签主动辞职）和第 8 条（离职前存证据）来办。经济补偿怎么算，见本节第 4 条（被裁先算清 N）。单纯的冷落、排挤、刁难，多数对不上哪一条法律，能走的主要是内部投诉、调岗和换工作。仲裁从受理起最长 60 天，打官司一审 6 个月起，律师费自己出。已经撑不住了，先打 12356，见第 1 节第 25 条（12356）。不主张一受气就辞职，换工作的代价由你自己算。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","B 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-17', 'concept_archive_s19-17', 'claim_archive_s19-17', 'action', 'life_archive', '离职时找单位要一份离职证明，写明合同期限、离职日期、岗位和工作年限', '19. 在职、离职和工伤', '不管是被辞退、合同到期还是自己辞职，单位都要在你离职时给一份离职证明，并在 15 天内转走档案和社保。证明上要写合同期限、离职日期、岗位和在这家干了几年。办失业登记要用它。单位不给，劳动部门会责令改正，害你受了损失还要赔。', '法条没有把出证明和工作交接挂在一起，交接办完才付的是经济补偿。单位拖着不给，先发书面消息再要一次。再不给，就打 12333 或者去人社局劳动监察投诉。投诉不收费，立案后 60 个工作日内查完，复杂的可以再延 30 个工作日。要单位赔损失的，走劳动仲裁，也不收费，要在 1 年内申请。仲裁受理后 45 日内结案，最多再延 15 日。损失要你自己拿证据证明，比如因为没有证明耽误了失业登记、被新单位拒收。不服裁决再去法院，一审普通程序 6 个月起。法院收的劳动争议受理费每件 10 元，律师费不在诉讼费用里，要自己出。条例要求写的四样里没有离职原因。证明上写了「个人原因主动辞职」而事实不是这样，当场提出来，理由见本节第 7 条（别签主动辞职）。失业保险金怎么领，见第 7 节第 1 条（失业保险金）。', NULL, NULL, NULL, '不花钱。走之前当面要，或者发一条书面消息要，留下要过的记录。难在关系闹僵了还得开这个口。单位拖着不给，就要投诉或者申请仲裁，前后几十天到几个月。', '劳动合同法规定，单位要在解除或者终止劳动合同时出具证明。法条不分是谁提出的，合同到期不续、你自己辞职、被辞退都在内。单位还要在 15 日内为你办好档案和社会保险关系的转移手续。实施条例规定证明上要写四样：劳动合同期限、解除或者终止的日期、工作岗位、在本单位的工作年限。失业保险条例规定，职工失业后要拿着单位出具的这份证明，及时去社保经办机构办失业登记。失业保险金从办失业登记那天起算。单位不出书面证明的，由劳动行政部门责令改正。给你造成损害的，单位要赔。法律另外规定，新单位招了还没和原单位解除合同的人，给原单位造成损失的，要承担连带赔偿责任。离职证明就是你已经和原单位解除合同的书面凭据（全国）', '法条没有把出证明和工作交接挂在一起，交接办完才付的是经济补偿。单位拖着不给，先发书面消息再要一次。再不给，就打 12333 或者去人社局劳动监察投诉。投诉不收费，立案后 60 个工作日内查完，复杂的可以再延 30 个工作日。要单位赔损失的，走劳动仲裁，也不收费，要在 1 年内申请。仲裁受理后 45 日内结案，最多再延 15 日。损失要你自己拿证据证明，比如因为没有证明耽误了失业登记、被新单位拒收。不服裁决再去法院，一审普通程序 6 个月起。法院收的劳动争议受理费每件 10 元，律师费不在诉讼费用里，要自己出。条例要求写的四样里没有离职原因。证明上写了「个人原因主动辞职」而事实不是这样，当场提出来，理由见本节第 7 条（别签主动辞职）。失业保险金怎么领，见第 7 节第 1 条（失业保险金）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-18', 'concept_archive_s19-18', 'claim_archive_s19-18', 'action', 'life_archive', '拿到离职补偿先看个税：当地上年职工平均工资 3 倍以内免税，超出的部分单独算，不并进当年工资', '19. 在职、离职和工伤', '因为解除劳动合同拿到的一次性补偿，在当地上年职工平均工资 3 倍以内的部分不交个税。超出的部分单独算税，不和当年工资加在一起。单位要是把整笔并进当月工资扣了税，先找单位问清楚，再打 12366 问税务局。', '同一份文件里，全年一次性奖金那项写了截止日期，后来延到 2027 年 12 月 31 日。解除劳动关系补偿这一项没写截止日期，不跟着奖金那项走。文件只点名了经济补偿金、生活补助费和其他补助费，没有单独点名代通知金和违法解除的赔偿金。这两笔算不算，拿不准就打 12366 问当地税务局。「当地上年职工平均工资」用哪个数，也以当地税务局为准。补偿本身怎么算，见本节第 4 条（被裁先算清 N）、第 5 条（没提前 30 天通知）和第 6 条（违法解除的赔偿金）。提前退休、内部退养拿的一次性补贴另有算法，不适用这一条。', NULL, NULL, NULL, '不花钱。查一下当地上年职工平均工资，再花几分钟核对单位是怎么扣的税。个人所得税 App 里能查到每笔收入的申报明细。', '财政部和税务总局的文件规定，个人和用人单位解除劳动关系拿到的一次性补偿收入，包括经济补偿金、生活补助费和其他补助费。其中在当地上年职工平均工资 3 倍以内的部分，免征个人所得税。超过 3 倍的部分，不并入当年综合所得，单独按综合所得税率表算税。这张表全年 36000 元以内的部分税率 3%，36000 元到 144000 元的部分 10%，再往上分级加到 45%。举个例子，当地上年职工平均工资是 10 万元，3 倍就是 30 万元。拿到 36 万元补偿，只就超出的 6 万元算税，是 3480 元。同样 36 万元要是整笔都按这张表算，是 58080 元。这条从 2019 年 1 月 1 日起执行，没有写截止日期（全国）', '同一份文件里，全年一次性奖金那项写了截止日期，后来延到 2027 年 12 月 31 日。解除劳动关系补偿这一项没写截止日期，不跟着奖金那项走。文件只点名了经济补偿金、生活补助费和其他补助费，没有单独点名代通知金和违法解除的赔偿金。这两笔算不算，拿不准就打 12366 问当地税务局。「当地上年职工平均工资」用哪个数，也以当地税务局为准。补偿本身怎么算，见本节第 4 条（被裁先算清 N）、第 5 条（没提前 30 天通知）和第 6 条（违法解除的赔偿金）。提前退休、内部退养拿的一次性补贴另有算法，不适用这一条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s19-19', 'concept_archive_s19-19', 'claim_archive_s19-19', 'action', 'life_archive', '换城市工作时，把养老和医保关系转到新参保地，缴费年限接着累计，别办退保', '19. 在职、离职和工伤', '换城市工作，养老和医保关系都能跟着你走，以前交的年限接着往上加。没到领养老金的年龄，不能办退保把钱取出来。医保断交超过 3 个月，到新地方可能要等最多 6 个月才能报销，所以中间别空太久。', '跨省去的不是户口所在省，而且男的满 50 岁、女的满 40 岁，养老关系会留在原参保地。新地方只开一个临时账户，记下单位和个人的全部缴费。退休时在哪领养老金，规则是这样的。关系在户籍所在省的，在户籍地领。不在户籍地、但在关系所在地累计交满 10 年的，在当地领。都不满 10 年的，转回上一个交满 10 年的地方领。每个地方都不满 10 年的，归集到户籍地领。领取地不同，算养老金用的平均工资也不同。省内跨市怎么转，由各省自己定办法，问当地社保经办机构。已经在领养老金的人，不再转移关系。断缴之后年限怎么算、哪些资格要连续缴费，见第 7 节第 18 条（社保断缴）。不进单位、自己交社保的，见第 31 节第 11 条（灵活就业）。', NULL, NULL, NULL, '不花钱。在新地方参保缴费以后，由新单位或你自己提出转移申请，跑一趟窗口或者网上办。养老这边前后要等几十个工作日，医保要等 15 个工作日左右。', '社会保险法规定，换个地方就业的（正式说法是跨统筹地区），养老关系随本人转移，缴费年限累计计算。职工医保也一样，关系跟着人走，年限累计计算。退休时养老金分段计算、统一支付。跨省转养老关系按国务院办公厅转发的转移接续办法办。没到领取待遇的年龄，不得终止养老关系、办理退保。社会保险法也写明个人账户不得提前支取。个人账户里的钱连本带息全部转走。单位交的那部分叫统筹基金，按你 1998 年以后各年实际缴费工资的 12% 转过去。领养老金时，按你各年的缴费工资、缴费年限和领取地各年的平均工资算。手续是在新地方参保缴费以后，由单位或你自己向新参保地书面申请。新参保地 15 个工作日内审核，原参保地接到同意接收函后 15 个工作日内办好转出。新参保地收到关系和资金后，再 15 个工作日内办结。按 2020 年的跨省通办清单，这件事要在当年底前实现跨省通办。你向转入地申请就行，不用再回转出地办。职工医保要原参保地先停保、新地方已经参保，才能申请转移。可以在国家医保服务平台网上申请，也可以去窗口。原参保地 10 个工作日内转出，新参保地 5 个工作日内转入，个人账户余额一起划过去。转之前断缴 3 个月以内的，按新地方规定补缴后不设等待期，缴费当月就能报销，中间那段也能追溯报。断缴超过 3 个月的，等待期按各地规定，原则上不超过 6 个月（全国）', '跨省去的不是户口所在省，而且男的满 50 岁、女的满 40 岁，养老关系会留在原参保地。新地方只开一个临时账户，记下单位和个人的全部缴费。退休时在哪领养老金，规则是这样的。关系在户籍所在省的，在户籍地领。不在户籍地、但在关系所在地累计交满 10 年的，在当地领。都不满 10 年的，转回上一个交满 10 年的地方领。每个地方都不满 10 年的，归集到户籍地领。领取地不同，算养老金用的平均工资也不同。省内跨市怎么转，由各省自己定办法，问当地社保经办机构。已经在领养老金的人，不再转移关系。断缴之后年限怎么算、哪些资格要连续缴费，见第 7 节第 18 条（社保断缴）。不进单位、自己交社保的，见第 31 节第 11 条（灵活就业）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"19. 在职、离职和工伤","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-1', 'concept_archive_s20-1', 'claim_archive_s20-1', 'action', 'life_archive', '让孩子仰着睡，睡硬的平面，同房不同床，床上不放任何软东西', '20. 刚出生的孩子怎么带', '让孩子脸朝上躺着睡，睡在硬的平面上。大人和孩子睡同一间房，但不睡同一张床。床上不放枕头、被子、床围、毛绒玩具和定型枕。斜着的摇篮和婴儿椅只能坐，不能当床睡。光美国每年就有约 3500 个婴儿死在睡眠里。', '「床上不放任何软东西」是指枕头、被子、床围、毛绒玩具、定型枕全都不放。看起来很安全的哺乳枕也不放。斜着的摇篮和婴儿椅不能当睡觉的地方。这一节里，这件事的差别最大，也最需要顶住长辈的压力', NULL, NULL, NULL, '不花钱。床垫要换成硬的，几百元。难在要顶住长辈的说法，一直按这个来', '美国每年约 3500 名婴儿死于睡眠相关原因。这里面包括婴儿猝死综合征、死因不明和在床上意外憋住。美国儿科学会给的安全睡眠环境是「仰卧位；使用坚实、不倾斜的睡眠表面；同房不同床；避免柔软的寝具和过热」。还有几件事也能降低风险：母乳喂养、别让孩子接触尼古丁和酒精、按时接种疫苗、使用安抚奶嘴', '「床上不放任何软东西」是指枕头、被子、床围、毛绒玩具、定型枕全都不放。看起来很安全的哺乳枕也不放。斜着的摇篮和婴儿椅不能当睡觉的地方。这一节里，这件事的差别最大，也最需要顶住长辈的压力', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-2', 'concept_archive_s20-2', 'claim_archive_s20-2', 'action', 'life_archive', '出生后 24 小时内打上乙肝疫苗第一针', '20. 刚出生的孩子怎么带', '孩子出生后 24 小时之内要打上第一针乙肝疫苗。在婴儿期和幼儿期感染乙肝的人里，约有 95% 会转成慢性肝炎。成年以后才感染的，绝大多数能自己好。所以这一针越早打越有用。妈妈乙肝表面抗原是阳性的，孩子还要同时打乙肝免疫球蛋白。', '妈妈的乙肝表面抗原是阳性的，孩子出生后还要同时打一针乙肝免疫球蛋白。这件事产检的时候就要查清楚，别等生完再问。妈妈自己要做的筛查见第 1 节', NULL, NULL, NULL, '不花钱。乙肝疫苗属于免疫规划疫苗，本来就免费。孩子出生当天在医院就打了，不用另外跑', '世界卫生组织的说法是：「所有婴儿都应在出生后尽早（24 小时内）接种乙肝疫苗。」原因是「婴儿期和幼儿期感染约有 95% 会发展为慢性肝炎」。成年后感染的绝大多数能自愈（不用治也会好）', '妈妈的乙肝表面抗原是阳性的，孩子出生后还要同时打一针乙肝免疫球蛋白。这件事产检的时候就要查清楚，别等生完再问。妈妈自己要做的筛查见第 1 节', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-3', 'concept_archive_s20-3', 'claim_archive_s20-3', 'action', 'life_archive', '按国家免疫规划把该打的疫苗打齐，全程免费，错过了只补没打完的剂次', '20. 刚出生的孩子怎么带', '国家免疫规划里的疫苗全程免费，接种单位不能收钱。孩子入托、入学都要查预防接种证，漏打的会被查出来补上。错过了只补没打完的那几剂，不用从头再打，换了厂家也能接着打。湿疹、荨麻疹、过敏性鼻炎、哮喘只要病情稳定，新生儿黄疸也一样，都能正常打。', '最常见的误会是「孩子体质不好，先别打」。官方说法是：所谓「过敏性体质」、家里人有过敏的病、孩子以前对食物或药物过敏过，都不是不能打的理由。特应性皮炎（湿疹）、荨麻疹、过敏性鼻炎、支气管哮喘，只要病情稳定就能正常打。正在吃抗过敏药，或者在用吸入型激素，也能打。新生儿的生理性黄疸、母乳性黄疸也能正常打。真正不能打的只有两种：以前打同一种疫苗出现过急性的严重过敏反应，或者对疫苗里已知的某种成分严重过敏。有免疫缺陷的孩子，以及正在化疗放疗、正在用免疫抑制剂的孩子，要一个个单独评估，去接种门诊说明情况再定。乙肝第一针见第 2 条。自费的非免疫规划疫苗要另收疫苗费和接种服务费，和这条说的免费无关。', NULL, NULL, NULL, '不花钱。法律写明「接种单位接种免疫规划疫苗不得收取任何费用」。要按月龄跑几趟接种门诊。预防接种证收好，别弄丢', '孩子入托、入学的时候，托幼机构和学校要查验预防接种证。发现没按规定接种免疫规划疫苗的，要报告接种单位，并且配合督促监护人补种。所以漏打的疫苗拖不过去，入学时一定会被查出来。现在执行的是 2026 年版程序。人乳头瘤病毒（HPV）疫苗已经纳入国家免疫规划。百白破疫苗的起始接种年龄从 3 月龄改成 2 月龄，一共 5 剂，分别在 2 月龄、4 月龄、6 月龄、18 月龄和 6 周岁各打 1 剂。西藏、青海、新疆和新疆生产建设兵团的适龄儿童，2026 年 3 月起也常规接种乙脑疫苗。几种疫苗可以同一天打：现阶段国家免疫规划疫苗都可以按免疫程序或补种原则同时接种。两种及以上打针的疫苗要打在不同部位，「严禁将两种或多种疫苗混合吸入同一支注射器内接种」。没在同一天打的，两种及以上打针的减毒活疫苗之间要间隔不小于 28 天。灭活疫苗、口服的减毒活疫苗和其他疫苗之间的间隔不作限制。不满 18 周岁的补种原则是尽早补种，「只需补种未完成的剂次，无需重新开始全程接种」，同一种疫苗换厂家可以接着打（全国，2026 年版程序）', '最常见的误会是「孩子体质不好，先别打」。官方说法是：所谓「过敏性体质」、家里人有过敏的病、孩子以前对食物或药物过敏过，都不是不能打的理由。特应性皮炎（湿疹）、荨麻疹、过敏性鼻炎、支气管哮喘，只要病情稳定就能正常打。正在吃抗过敏药，或者在用吸入型激素，也能打。新生儿的生理性黄疸、母乳性黄疸也能正常打。真正不能打的只有两种：以前打同一种疫苗出现过急性的严重过敏反应，或者对疫苗里已知的某种成分严重过敏。有免疫缺陷的孩子，以及正在化疗放疗、正在用免疫抑制剂的孩子，要一个个单独评估，去接种门诊说明情况再定。乙肝第一针见第 2 条。自费的非免疫规划疫苗要另收疫苗费和接种服务费，和这条说的免费无关。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-4', 'concept_archive_s20-4', 'claim_archive_s20-4', 'action', 'life_archive', '前 6 个月只喂母乳，连水都不用喂，6 个月起加辅食并继续母乳', '20. 刚出生的孩子怎么带', '孩子出生后第一个小时里就开始喂奶。前 6 个月只喂母乳，连水都不用喂。满 6 个月起加辅食，每天要有含铁多的动物性食物，母乳接着喂到 2 岁或更久。母乳不够或者不能喂，就用配方奶，不用自责。喂什么对孩子安危的影响，远没有睡姿大。', '母乳不够，或者身体不允许喂，就用配方奶。喂母乳还是喂配方奶，差距远小于安全睡眠那条。加辅食的次数：6 至 8 月龄每天 1 到 2 次，9 至 12 月龄每天 2 到 3 次。每天吃的东西，至少要覆盖七类里的四类。孩子有重度湿疹或鸡蛋过敏时，花生要不要躲着，见本节第 12 条（别躲着花生）。', NULL, NULL, NULL, '不花钱，还省下奶粉钱。费的是时间，喂奶每天都要占掉不少。难在要一直喂下去，前 6 个月不能断', '世界卫生组织的建议是「在出生后第一个小时内开始母乳喂养」。前 6 个月「纯母乳喂养，即不提供其他任何食物或液体，包括水」。然后「从 6 月龄起开始添加安全充足的辅食，同时继续母乳喂养到 2 岁或以上」。国家卫健委的服务指南也提倡 0 至 6 月龄纯母乳喂养。这份指南还要求满 6 月龄起「每天的辅食必须包含含铁丰富的动物性食物」', '母乳不够，或者身体不允许喂，就用配方奶。喂母乳还是喂配方奶，差距远小于安全睡眠那条。加辅食的次数：6 至 8 月龄每天 1 到 2 次，9 至 12 月龄每天 2 到 3 次。每天吃的东西，至少要覆盖七类里的四类。孩子有重度湿疹或鸡蛋过敏时，花生要不要躲着，见本节第 12 条（别躲着花生）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-5', 'concept_archive_s20-5', 'claim_archive_s20-5', 'action', 'life_archive', '冲奶粉用 70 ℃ 以上的水，冲好放凉再喂，喝剩的倒掉', '20. 刚出生的孩子怎么带', '奶粉不是无菌的，可能带一种叫阪崎克罗诺杆菌的细菌。新生儿一旦感染，报告的病死率在四成到八成之间。冲的时候先把热水倒进奶瓶，等水温降到约 73.8 ℃ 再放奶粉。这时奶液还在 70 ℃ 以上，能把这种菌杀到原来的十万分之一以下。冲好放凉再喂，喝剩的倒掉。', '70 ℃ 这个门槛来自公共卫生指南。Beary 等人的原话是「针对高危婴儿照护者的公共卫生指南建议用加热到至少 70 ℃（158 ℉）的水冲调配方奶粉以灭活微生物」。早产儿、体重偏低的孩子和不满 2 个月的孩子风险最高。别用保温杯里放了一天的水来冲。也别把冲好的奶搁在室温下，等着下一顿再喂', NULL, NULL, NULL, '不花钱。每次多等几分钟把奶放凉。难在孩子饿得哭的时候，也要等水温降下来再冲', '奶粉不是无菌的，可能带阪崎克罗诺杆菌。新生儿感染后的病死率，报告为 40% 到 80%。实验研究显示：先把热水倒进奶瓶，等水温降到约 73.8 ℃ 再加奶粉，绝大多数情况下奶液温度还在 70 ℃ 以上。这样可以让这种菌减少 5 个对数级以上，降到原来的十万分之一以下', '70 ℃ 这个门槛来自公共卫生指南。Beary 等人的原话是「针对高危婴儿照护者的公共卫生指南建议用加热到至少 70 ℃（158 ℉）的水冲调配方奶粉以灭活微生物」。早产儿、体重偏低的孩子和不满 2 个月的孩子风险最高。别用保温杯里放了一天的水来冲。也别把冲好的奶搁在室温下，等着下一顿再喂', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-6', 'concept_archive_s20-6', 'claim_archive_s20-6', 'action', 'life_archive', '不满 1 岁不喂蜂蜜', '20. 刚出生的孩子怎么带', '孩子不满 1 岁，不要喂蜂蜜。蜂蜜水、拌进辅食里的蜂蜜、含蜂蜜的糕点，都算。蜂蜜里可能带有引起肉毒中毒的细菌。大人肚子里的菌群能压住它，婴儿压不住。自家做的腌菜和发酵食品，也是同样的道理。', '不能喂的包括蜂蜜水、拌了蜂蜜的辅食、含蜂蜜的糕点。同样的道理，自家做的腌菜和发酵食品，也不要给婴儿吃', NULL, NULL, NULL, '不花钱', '美国疾控中心的说法是「不要给 1 岁以下的儿童喂蜂蜜」，因为「蜂蜜可能含有引起肉毒中毒的细菌」。成年人的肠道菌群能压住这种芽孢（这种细菌的休眠状态），婴儿压不住', '不能喂的包括蜂蜜水、拌了蜂蜜的辅食、含蜂蜜的糕点。同样的道理，自家做的腌菜和发酵食品，也不要给婴儿吃', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-7', 'concept_archive_s20-7', 'claim_archive_s20-7', 'action', 'life_archive', '出生时的维生素 K 针一定要打', '20. 刚出生的孩子怎么带', '新生儿身体里存的维生素 K 很少，不补可能出血，晚出现的那种常常是脑子里出血。在没普遍打这一针的地方，每 10 万个新生儿有 478 个出这种血。打了这一针，估计能少掉七成八以上。国内正规医院会常规打，在家生或在不正规机构生的，要主动问一句打了没有。', '在中国的正规医院生孩子，医院会常规打这一针，不用自己操心。在家生的，或者在不正规机构生的，要主动去确认。口服的效果不如打针，这里说的打针是打进肌肉里', NULL, NULL, NULL, '0 元到几十元。这笔钱通常已经包含在住院生孩子的费用里，不用另外交', '新生儿体内存的维生素 K 很少。不补充可能出现维生素 K 缺乏性出血，晚出现的那一种常常表现为颅内出血（脑子里出血）。比利时的共识建议是「出生时肌肉注射 1 或 2 毫克维生素 K 一次」。在没有系统提供预防的地区，维生素 K 缺乏性出血的发生率是每 10 万人 478 例，这个数字来自塔什干的 4.2 万名新生儿。作者估计，做了预防可以使发生率下降「高于 78.5%」', '在中国的正规医院生孩子，医院会常规打这一针，不用自己操心。在家生的，或者在不正规机构生的，要主动去确认。口服的效果不如打针，这里说的打针是打进肌肉里', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-8', 'concept_archive_s20-8', 'claim_archive_s20-8', 'action', 'life_archive', '不满 3 个月的婴儿体温到 38 ℃ 就直接去医院，不在家观察', '20. 刚出生的孩子怎么带', '孩子不满 3 个月，体温到 38 ℃ 就直接去医院。不要在家观察，也不要先喂退烧药再等等看。这个月龄的孩子就算得的是严重细菌感染，也可能只表现为发热。所以「看着精神还行」不能当成在家等的理由。出生不满 8 天的孩子，连指南都没覆盖，更要马上去。', '这个月龄的孩子，得了严重细菌感染也可能只表现为发热。所以看着「精神还行」，不能作为在家观察的理由。也别自己先喂退烧药，再等等看', NULL, NULL, NULL, '挂号加检查几百元', '美国儿科学会为 8 至 60 日龄、看上去状态还可以的足月婴儿制定了专门指南。这份指南把发热定义为「体温 ≥38.0 ℃」。它按 8 至 21 日龄、22 至 28 日龄、29 至 60 日龄分成三档，各给一条处理路径。不满 8 日龄的婴儿甚至不在这份指南的范围里，意思是这个阶段更要立即就医', '这个月龄的孩子，得了严重细菌感染也可能只表现为发热。所以看着「精神还行」，不能作为在家观察的理由。也别自己先喂退烧药，再等等看', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-9', 'concept_archive_s20-9', 'claim_archive_s20-9', 'action', 'life_archive', '无论多累多气都不要摇晃婴儿', '20. 刚出生的孩子怎么带', '婴儿的头大，脖子没力气。用力摇晃会让他脑子里、眼睛里出血，可能要了他的命，也可能留下一辈子的残疾。哄睡时轻轻晃不算，危险的是控制不住的猛晃。快压不住火时，把孩子放回婴儿床，人走开几分钟，让他哭一会儿比抱着晃安全。', '真的到了要失控的那一刻，先把孩子放回婴儿床里，人走开几分钟。让他哭一会儿，比抱在手上晃安全得多。一个人带孩子、长期睡不够的人，最要记住这一点。自己的情绪怎么处理，见第 3 节', NULL, NULL, NULL, '不花钱。难在自己太累、太气的时候要停住手', '婴儿头部占比大，颈部肌肉弱。剧烈摇晃会造成颅内出血和视网膜出血（脑子里和眼睛里出血），可能致死，也可能留下终身残疾。哄睡时的轻柔摇动不算，危险的是失控的剧烈晃动。医学上把摇晃、撞击造成的这类伤叫「虐待性头部外伤」。它是 2 岁以下孩子头部外伤致死的首要原因。美国 1999 到 2014 年，它造成近 2250 名 5 岁以下孩子死亡', '真的到了要失控的那一刻，先把孩子放回婴儿床里，人走开几分钟。让他哭一会儿，比抱在手上晃安全得多。一个人带孩子、长期睡不够的人，最要记住这一点。自己的情绪怎么处理，见第 3 节', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-10', 'concept_archive_s20-10', 'claim_archive_s20-10', 'action', 'life_archive', '尿布不看牌子看三件事：合不合身、换得勤不勤、有没有被抽检通报过', '20. 刚出生的孩子怎么带', '没有哪个官方机构排过「哪个牌子最好」。能查的只有两样：市场监管总局的产品质量抽检通报，和监管部门对具体事件的调查。贵的不等于安全，进口的不等于合格。先买小包装试一周，看孩子有没有红屁股和勒痕，合适再囤。', '联合调查组成立时只说「有关情况将及时公布」。TODO（待核实：调查结论。截至 2026 年 9 月 30 日，市场监管总局官网和近年的国家监督抽查通报里都没找到纸尿裤的结论）。实际怎么买：贵的不等于安全，进口的不等于合格。先买小包装试一周，看孩子有没有红屁股和勒痕，合适再囤。红屁股主要是换得不够勤、不透气造成的，和牌子的关系没有想象中大。查抽检通报的方法见第 5 节', NULL, NULL, NULL, '每月两三百到上千元不等，看你用什么档次的', '没有任何官方机构发布过「哪个牌子最好」的排名，所以本书不给品牌推荐。能核查的信息只有两类。一类是国家市场监督管理总局的产品质量抽检通报。另一类是监管部门对具体事件的调查。2026 年 6 月「婴幼儿纸尿裤甲酰胺问题」引起关注之后，市场监管总局牵头成立了联合调查组去核查', '联合调查组成立时只说「有关情况将及时公布」。TODO（待核实：调查结论。截至 2026 年 9 月 30 日，市场监管总局官网和近年的国家监督抽查通报里都没找到纸尿裤的结论）。实际怎么买：贵的不等于安全，进口的不等于合格。先买小包装试一周，看孩子有没有红屁股和勒痕，合适再囤。红屁股主要是换得不够勤、不透气造成的，和牌子的关系没有想象中大。查抽检通报的方法见第 5 节', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","C 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-11', 'concept_archive_s20-11', 'claim_archive_s20-11', 'action', 'life_archive', '大件按「借、买二手、买新」的顺序考虑，别一次性配齐', '20. 刚出生的孩子怎么带', '婴儿车、婴儿床、抱被、玩具用的时间都短，二手货很多。先问人借，借不到买二手，再不行才买新的，通常能省下上千元。安全座椅和床垫别买二手，座椅撞过以后的损伤眼睛看不出来。月子会所、早教课这类大钱，先冷静 24 小时再定。', '月子会所、早教课、婴儿游泳馆这几类，本书不推荐也不否定。但它们都是可花可不花的一笔大钱，适用第 5 节讲的 24 小时冷静期', NULL, NULL, NULL, '不用额外花钱，省下来的钱通常以千元计。难在忍住不一次性把东西配齐', '婴儿车、婴儿床、抱被、玩具的使用期都很短，二手市场上供给远大于需求。真正不能省、也不建议买二手的是两样：安全座椅和床垫。安全座椅撞过之后的结构损伤，肉眼看不出来', '月子会所、早教课、婴儿游泳馆这几类，本书不推荐也不否定。但它们都是可花可不花的一笔大钱，适用第 5 节讲的 24 小时冷静期', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","C 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-12', 'concept_archive_s20-12', 'claim_archive_s20-12', 'action', 'life_archive', '孩子有严重湿疹或鸡蛋过敏，别躲着花生，按医生指导早点加上，但绝不能喂整粒', '20. 刚出生的孩子怎么带', '有重度湿疹或鸡蛋过敏的婴儿，从 4 到 11 个月起定期吃花生，到 5 岁时花生过敏的只有 1.9%，完全躲开的是 13.7%。皮试已经有点反应的孩子，吃的是 10.6%，躲的是 35.3%。加之前先带孩子看医生。绝不能喂整粒花生，会噎住气管。', '形式只能是花生酱调稀或者花生粉拌进辅食，绝不能给整粒花生。卫健委的喂养核心信息写得很明白：「整粒花生、坚果、果冻等食物易吸入气管，引起窒息，婴幼儿应当避免食用」。噎住了怎么办见第 13 节第 26 条（有人噎住说不出话）。适用的只是高危孩子：有重度湿疹，或者已经对鸡蛋过敏的那些。加之前必须先看医生做评估，不要自己在家试：LEAP 试验入组前给每个孩子做了皮试，皮试反应大于 4 毫米的孩子被排除在试验之外，没让他们吃。一般孩子的证据弱得多。另一项 1162 名普通母乳喂养婴儿的试验里，按分组算，早引入组食物过敏 5.6%、常规组 7.1%，差别不显著（P=0.32）；只有在真正做到了的那部分孩子里才显著（2.4% 对 7.3%）。这种算法容易把效果说大，作者自己说按分组算没能证出效力，但也说明早引入是安全的。中国的官方喂养文件目前对「该早引入还是该回避易过敏食物」没有说法，所以这条按国际试验证据写。时间点上也要注意：LEAP 从 4 月龄起，而中国是满 6 月龄开始加辅食，见本节第 4 条（前 6 个月只喂母乳）。高危孩子几月龄开始、怎么开始，听医生的。', NULL, NULL, NULL, '一罐花生酱几十元。每周喂几次，顺手就做。加之前要带孩子看一次医生，做个评估。', '英国 LEAP 随机试验。640 名婴儿入组，条件是有重度湿疹、鸡蛋过敏，或者两样都有。入组时 4 到 11 个月大。随机分成两组，一组定期吃花生制品，一组完全回避，到 60 个月大时看花生过敏率。入组时花生皮试阴性的 530 人里，回避组 13.7% 过敏，吃的组 1.9%（P&lt;0.001）。入组时皮试已经弱阳性的 98 人里，回避组 35.3%，吃的组 10.6%（P=0.004）。两组的严重不良事件没有差别。', '形式只能是花生酱调稀或者花生粉拌进辅食，绝不能给整粒花生。卫健委的喂养核心信息写得很明白：「整粒花生、坚果、果冻等食物易吸入气管，引起窒息，婴幼儿应当避免食用」。噎住了怎么办见第 13 节第 26 条（有人噎住说不出话）。适用的只是高危孩子：有重度湿疹，或者已经对鸡蛋过敏的那些。加之前必须先看医生做评估，不要自己在家试：LEAP 试验入组前给每个孩子做了皮试，皮试反应大于 4 毫米的孩子被排除在试验之外，没让他们吃。一般孩子的证据弱得多。另一项 1162 名普通母乳喂养婴儿的试验里，按分组算，早引入组食物过敏 5.6%、常规组 7.1%，差别不显著（P=0.32）；只有在真正做到了的那部分孩子里才显著（2.4% 对 7.3%）。这种算法容易把效果说大，作者自己说按分组算没能证出效力，但也说明早引入是安全的。中国的官方喂养文件目前对「该早引入还是该回避易过敏食物」没有说法，所以这条按国际试验证据写。时间点上也要注意：LEAP 从 4 月龄起，而中国是满 6 月龄开始加辅食，见本节第 4 条（前 6 个月只喂母乳）。高危孩子几月龄开始、怎么开始，听医生的。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s20-13', 'concept_archive_s20-13', 'claim_archive_s20-13', 'action', 'life_archive', '盯住新生儿黄疸的几个信号：出生 24 小时内就黄、越来越黄、叫不醒不吃奶、大便发白，就当天去医院', '20. 刚出生的孩子怎么带', '八成以上的新生儿会有点黄，多数自己会退。出生不满 24 小时就黄，或者越来越黄、比平时嗜睡叫不醒、不吃奶、身子发软或发硬，要当天去医院。大便颜色发白，可能是胆道闭锁，也要尽快去查。胆红素太高会伤到脑子，留下一辈子的残疾。', '照蓝光（光照治疗）是用特殊的光照孩子的皮肤，让胆红素变成容易排出去的形式。别在家晒太阳代替：美国儿科学会说，晒太阳很难做到既安全又不晒伤，所以不推荐拿它当治疗。也别喂水或葡萄糖水来退黄，这个指南也明确不推荐。肉眼看黄的深浅，估不准胆红素有多高。英国 NICE 指南写明不要只靠肉眼，拿不准就去测一次。不满 38 周出生、哥哥姐姐照过蓝光、母乳没吃够的孩子，更容易黄得重。复查按国家基本公共卫生服务规范走：出院后 1 周内，医务人员上门访视。出生后 28 到 30 天，到社区卫生服务中心或乡镇卫生院随访。两次都要看黄疸。出院时医生另约了复查胆红素的，按约的时间去。足月的孩子黄了超过 14 天，早产的超过 21 天，NICE 指南要求查一次结合胆红素，并看大便是不是发白。黄疸本身不耽误打疫苗，见本节第 3 条（疫苗）。新生儿筛查见第 27 节第 13 条（足跟血筛查）。', NULL, NULL, NULL, '挂号加测胆红素，几百元以内。要照蓝光的，一般在医院照两天左右。难在孩子看着还好的时候，也要跑这一趟', '美国儿科学会 2022 年的指南说，「超过 80% 的新生儿会有某种程度的黄疸」。胆红素太高，会引起急性胆红素脑病和核黄疸。指南说核黄疸是「永久的致残性神经系统疾病」。它的表现包括手脚不自主扭动的脑瘫、眼睛往上看不了、乳牙釉质发育不良和听力损害。指南把「出生后 24 小时内出现黄疸」列为会发展成重度黄疸的风险因素。英国国家医疗服务体系（NHS）给家长的说法分两档。第一档要打急救电话或直接去急诊。这一档是孩子有黄疸，同时比平时嗜睡或叫不醒、不吃奶、身子发软或发硬、有抽动。孩子出生还不满 24 小时就有黄疸的，也算这一档。第二档要尽快约医生。这一档是出生超过 24 小时，黄疸不见好或越来越重，尿深黄或褐色，或者大便是淡奶油色。全球估算，2010 年约 48 万名新生儿得了 Rh 溶血病（母子血型不合引起）或极重度的高胆红素血症。这些孩子里 24% 死亡，13% 发展成核黄疸。核黄疸活下来的孩子里，83% 以上留下一种或多种残损。大便发白可能是胆道闭锁，这种病要在 60 天内做葛西手术（Kasai 手术），预后才明显更好。台湾从 2004 年起，把大便比色卡印进每个新生儿的儿童健康手册。60 天内做上手术的比例，从 2004 年的 60% 升到 2005 年的 74.3%。另一项台湾全民研究里，推行比色卡之后，胆道闭锁孩子的死亡率从 26.2% 降到 15.9%。这是前后对比，不是分组试验', '照蓝光（光照治疗）是用特殊的光照孩子的皮肤，让胆红素变成容易排出去的形式。别在家晒太阳代替：美国儿科学会说，晒太阳很难做到既安全又不晒伤，所以不推荐拿它当治疗。也别喂水或葡萄糖水来退黄，这个指南也明确不推荐。肉眼看黄的深浅，估不准胆红素有多高。英国 NICE 指南写明不要只靠肉眼，拿不准就去测一次。不满 38 周出生、哥哥姐姐照过蓝光、母乳没吃够的孩子，更容易黄得重。复查按国家基本公共卫生服务规范走：出院后 1 周内，医务人员上门访视。出生后 28 到 30 天，到社区卫生服务中心或乡镇卫生院随访。两次都要看黄疸。出院时医生另约了复查胆红素的，按约的时间去。足月的孩子黄了超过 14 天，早产的超过 21 天，NICE 指南要求查一次结合胆红素，并看大便是不是发白。黄疸本身不耽误打疫苗，见本节第 3 条（疫苗）。新生儿筛查见第 27 节第 13 条（足跟血筛查）。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"20. 刚出生的孩子怎么带","B 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-1', 'concept_archive_s21-1', 'claim_archive_s21-1', 'action', 'life_archive', '出发前查一次外交部安全提醒，标了「暂勿前往」的地方就别去', '21. 出国、旅行与境外安全', '外交部把国外的安全风险分成四档，最高的一档叫「暂勿前往」。2026 年 9 月 15 日起，避开高风险的国家和地区写进了行政法规。办证件和出境过关的时候，工作人员还会提醒你，必要时会劝你别去。出发前翻一遍那一页，几分钟的事。', '提醒会随局势变动，本书不抄名单，出行前自己查一次那一页。截至 2026 年 9 月 7 日，该栏目里还挂着这几条「暂勿前往」类提醒：斯威士兰（2026-08-25）、巴勒斯坦（2023-10-10）、苏丹（2023-04-17）。另外四条是阿富汗（2023-02-17）、叙利亚（2023-01-04）、秘鲁（2022-12-29）、索马里（2022-11-24）。另外还有针对缅北地区、刚果（金）部分省份的专门提醒。旅行社也有告知义务。跟团之前，你可以要求对方书面说明目的地的风险', NULL, NULL, NULL, '不花钱。打开中国领事服务网翻一遍，几分钟就看完。', '外交部按风险高低公开发布国外安全提醒。从低到高大致是四档：「注意安全」「加强安全防范」「谨慎前往」「暂勿前往」。2026 年 9 月 15 日起施行的新规，把个人的义务也写进了行政法规。原文是：「中国公民应当关注国外安全提醒和旅游目的地安全风险提示，避免前往及驻留高风险国家或者地区」。新规同时要求移民管理机构（办出入境证件和管边检的部门），在办证和出境边检时提醒要去高风险地区的人。这一条的原文是：「对准备前往风险等级为最高级别或者严重危及人身安全案件突发高发的国家或者地区的中国公民，必要时应当劝阻其前往」', '提醒会随局势变动，本书不抄名单，出行前自己查一次那一页。截至 2026 年 9 月 7 日，该栏目里还挂着这几条「暂勿前往」类提醒：斯威士兰（2026-08-25）、巴勒斯坦（2023-10-10）、苏丹（2023-04-17）。另外四条是阿富汗（2023-02-17）、叙利亚（2023-01-04）、秘鲁（2022-12-29）、索马里（2022-11-24）。另外还有针对缅北地区、刚果（金）部分省份的专门提醒。旅行社也有告知义务。跟团之前，你可以要求对方书面说明目的地的风险', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-2', 'concept_archive_s21-2', 'claim_archive_s21-2', 'action', 'life_archive', '把 12308 和当地使领馆的领保电话存进手机，再抄一份放钱包，别等出事再找', '21. 出国、旅行与境外安全', '出事时的求助电话就一个。人在国内打 12308，人在国外打 +86-10-12308。这条热线开通以来接了 300 多万通电话。同一时期，外交部和驻外机构办了 50 多万起领事保护案件。', '驻当地使领馆自己还有一个领保电话，通常比总台更快。出发前在中国领事服务网上按国家查到，和总台号码一起存进手机。手机丢了或者没电，存的号码就用不上了。所以再手抄一份放在钱包里，或者把号码写一份给家里人', NULL, NULL, NULL, '不花钱。存两个号码，再抄一份，几分钟。', '外交部有一条全球领事保护与服务应急热线，24 小时有人接。人在国内拨 12308。人在国外拨 +86-10-12308，或者 +86-10-65612308。这条热线从 2014 年开通到现在，累计接听 300 多万通来电。同一时期，外交部和驻外机构处置各类领事保护案件 50 多万起', '驻当地使领馆自己还有一个领保电话，通常比总台更快。出发前在中国领事服务网上按国家查到，和总台号码一起存进手机。手机丢了或者没电，存的号码就用不上了。所以再手抄一份放在钱包里，或者把号码写一份给家里人', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-3', 'concept_archive_s21-3', 'claim_archive_s21-3', 'action', 'life_archive', '知道领事保护能做什么、不能做什么：能探视，不能捞人，费用还得自己付', '21. 出国、旅行与境外安全', '你在国外被抓，使领馆能做的是：向当地核实情况、要求依法公正处理、去看你、开庭时旁听。它不能替你改判，也不能把人领走。别人先垫的食宿、交通、医疗费，最后还是你自己付。所以出国前把钱和保险备好，别把「出事了国家会兜底」当成计划。', '使领馆不替你交罚款、不替你付医药费、不替你买机票，也改变不了所在国法院的结论。它能给你的是当地律师、翻译、医疗、殡葬机构的信息，还能帮你联系亲友、帮你找到救济渠道。所以出国前自己把钱和保险准备好，别把「出事了国家会兜底」当成计划', NULL, NULL, NULL, '不花钱。花几分钟把这条界线读明白。', '你被抓时，使领馆能做这么几件事。向所在国有关部门核实情况，要求依法公正处理。条例原文是「按照驻在国法律和我国与驻在国缔结或者共同参加的国际条约对其进行探视或者与其联络，了解其相关需求，要求驻在国有关部门给予该中国公民人道主义待遇和公正待遇」。说白了就是照当地法律和两国签的条约去看你、跟你联络、问你要什么，并要求当地按人道和公正的标准对待你。开庭时使领馆可以旁听，可以要求保障你的诉讼权利。你受了伤或者赶上灾，它能催当地紧急救助，能帮家属处理善后。但费用上条例写得同样清楚：「中国公民、法人、非法人组织在领事保护与协助过程中，得到第三方提供的食宿、交通、医疗等物资和服务的，应当支付应由其自身承担的费用」。别人先垫的食宿、交通、医疗，该你掏的还是你掏', '使领馆不替你交罚款、不替你付医药费、不替你买机票，也改变不了所在国法院的结论。它能给你的是当地律师、翻译、医疗、殡葬机构的信息，还能帮你联系亲友、帮你找到救济渠道。所以出国前自己把钱和保险准备好，别把「出事了国家会兜底」当成计划', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-4', 'concept_archive_s21-4', 'claim_archive_s21-4', 'action', 'life_archive', '买一份含境外医疗和医疗转运的保险，别只买航班延误险', '21. 出国、旅行与境外安全', '在国外看病的钱要自己掏。国内医保基本不报，使领馆也不垫。真正能拖垮一个家的不是门诊费，是重伤以后的住院，还有把人运回国，那得靠专机或者医疗护送。买旅行险主要看两个额度：境外医疗费用，紧急医疗转运与送返。', '10 万美元是一个下限说法，不是费用区间。官方或行业公开的费用区间统计没有找到，所以本书不写具体区间。买之前确认三件事。第一，你要去的国家在不在承保范围里。第二，潜水、滑雪、骑摩托这类高风险活动是不是被排除在外。第三，理赔是保险公司直接和医院结账，还是你先垫钱回来再报销。去免签的国家也一样要买', NULL, NULL, NULL, '一份短期的境外旅行险，几十到几百元。', '在境外看病的钱要自己出。国内医保在境外基本不报销。领事保护也不垫付这笔钱（见第 3 条，领事保护能做什么、不能做什么，依据是条例第二十六条）。真正会把一个家拖垮的不是门诊费，是重伤以后的住院和医疗转运。把人从境外医院转回国，要用专机或者医疗护送，属于自费项目里最贵的一类。美国疾控中心的说法是，把病人从偏远地方紧急转运到好医院，自己付的话可能要花 10 万美元以上。买保险时优先看两项额度。一是境外医疗费用额度。二是紧急医疗转运与送返额度，管的是出事后转院、把人送回国最多能赔多少', '10 万美元是一个下限说法，不是费用区间。官方或行业公开的费用区间统计没有找到，所以本书不写具体区间。买之前确认三件事。第一，你要去的国家在不在承保范围里。第二，潜水、滑雪、骑摩托这类高风险活动是不是被排除在外。第三，理赔是保险公司直接和医院结账，还是你先垫钱回来再报销。去免签的国家也一样要买', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","C 级","性价比 高","口径 金钱","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-5', 'concept_archive_s21-5', 'claim_archive_s21-5', 'action', 'life_archive', '「境外高薪招聘」一律当诈骗看，被骗去做电诈回来还要被限制出境', '21. 出国、旅行与境外安全', '月薪高得离谱、不问学历经验、不签正规合同、让你先到边境城市集合、还替你保管护照。这种活去了，人和护照都不在自己手上。出境时材料造假，边检会把你拦下不放行。在境外参与了违法犯罪，回国之后还可能 6 个月到 3 年不准出境。', '识别特征基本固定：月薪远高于同岗位、不要求学历经验、不签正规合同、让你先到边境城市集合、代办签证并保管你的护照。缅北地区已经有专门的领事提醒。真去了，人身自由和护照都不在自己手上，想走也走不了', NULL, NULL, NULL, '不花钱。难的是亲手推掉一份看起来很好的工作。', '官方对这类案件的定性很直接。近年出现「上当受骗出境或者虚构事由非法出境从事跨境赌博、电信网络诈骗等违法活动，严重危害人民群众生命和财产安全」。说的是被人骗出去，或者编个理由偷着出去，到那边干赌博和电信诈骗。新规针对这一点两头收紧。出境这头：「申请出境入境、停留居留的事由应当真实、合法」。交假材料或者说假话的，移民管理机构有权不给你发证件、不放你出境。回国这头：「中国公民在境外从事违法犯罪活动，危害国家安全和利益的，可以……决定自回国之日起 6 个月至 3 年以内不准其出境」。因为骗取证件、非法出境入境被行政拘留的，同样是 6 个月至 3 年不准出境', '识别特征基本固定：月薪远高于同岗位、不要求学历经验、不签正规合同、让你先到边境城市集合、代办签证并保管你的护照。缅北地区已经有专门的领事提醒。真去了，人身自由和护照都不在自己手上，想走也走不了', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-6', 'concept_archive_s21-6', 'claim_archive_s21-6', 'action', 'life_archive', '境外取现一年不能超过 10 万元人民币，是本人名下所有卡合起来算的', '21. 出国、旅行与境外安全', '境外取现的额度不是一张卡一个，是你名下所有银行卡（附属卡也算）合起来算，每个自然年 10 万元人民币。取满了，当年剩下的时间和第二年都不能再在境外取现。停的只是取现，刷卡消费不受影响，也不占你每年 5 万美元的购汇额度。', '额度按自然年度算，1 月 1 日重新开始累计。停的只是在境外取现，刷卡消费不受影响。真的需要在境外用大额现金，就按《个人外汇管理办法》先办购汇，再带外币现钞出境。取现本身还有两个坑，银联国际「境外ATM取款」页面写明了。一是双标识卡在部分国家的部分 ATM 上，没法选银联通道取款。二是部分境外 ATM 会在屏幕上提示额外手续费（surcharge），这笔钱由当地收单机构收，「与银联无关」。同一页还提示「由于信用卡取款需支付透支利息，建议持卡人境外取款使用银联借记卡」。卡丢了、被吞了或者被盗刷怎么办，见第 14 节第 5 条（卡被盗刷先挂失冻结再报警）', NULL, NULL, NULL, '不花钱。出发前估一下这趟要取多少现金，剩下的靠刷卡。难的是改掉习惯，能刷卡就别取现。', '依据是国家外汇管理局《关于规范银行卡境外大额提取现金交易的通知》（汇发〔2017〕29 号，2018 年 1 月 1 日起实施）。第一条：「个人持境内银行卡在境外提取现金，本人名下银行卡（含附属卡）合计每个自然年度不得超过等值 10 万元人民币。超过年度额度的，本年及次年将被暂停持境内银行卡在境外提取现金」。同条第二款：「个人不得通过借用他人银行卡或出借本人银行卡等方式规避或协助规避境外提取现金管理」。第二条：外汇局每天把暂停名单发给发卡银行，发卡银行应不晚于北京时间当日 17 时起，暂停名单里的人用本行银行卡在境外取现。第三条：被列入暂停名单的人，可以拿本人有效身份证件到外汇局分支局，查自己的境外取现明细。第四条：外币卡每卡每日的上限，由等值 1000 美元调整为等值 1 万元人民币；人民币卡维持每卡每日不得超过等值 1 万元人民币。第六条：发卡银行、境内人民币卡清算组织和个人违反本通知规定的，按《中华人民共和国外汇管理条例》有关规定处罚。外汇局答记者问还讲清了几点。《通知》不影响个人持卡在境外消费。出境旅游、商务、留学所涉的食、宿、行、购等经常项下交易，都可以刷银行卡支付。这些消费也不占用个人便利化年度 5 万美元购汇额度。年度额度由外汇局汇总各家发卡金融机构的数据算出来，因为实时控制会拖慢交易响应，「外汇局采用延时控制手段」（不当场拦截）。另据统计，2016 年 81% 的境内银行卡境外提取现金低于 3 万元人民币（全国）', '额度按自然年度算，1 月 1 日重新开始累计。停的只是在境外取现，刷卡消费不受影响。真的需要在境外用大额现金，就按《个人外汇管理办法》先办购汇，再带外币现钞出境。取现本身还有两个坑，银联国际「境外ATM取款」页面写明了。一是双标识卡在部分国家的部分 ATM 上，没法选银联通道取款。二是部分境外 ATM 会在屏幕上提示额外手续费（surcharge），这笔钱由当地收单机构收，「与银联无关」。同一页还提示「由于信用卡取款需支付透支利息，建议持卡人境外取款使用银联借记卡」。卡丢了、被吞了或者被盗刷怎么办，见第 14 节第 5 条（卡被盗刷先挂失冻结再报警）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-7', 'concept_archive_s21-7', 'claim_archive_s21-7', 'action', 'life_archive', '护照、签证、身份证都拍照存一份在云端，丢了先报警再补旅行证', '21. 出国、旅行与境外安全', '护照丢了，使领馆能给你补一张回国用的旅行证件。前提是你能证明自己是谁。手里有资料页、签证页的照片和出入境记录，补办就快得多。你还得先在当地报警拿到回执，出境检查和保险理赔都认这张纸。手机常和护照一起丢，照片别只存在手机里。', '存法是拍完照放进两个不同的地方，比如云盘存一份、发给一位家人一份。另外打印一份纸质复印件，和原件分开放。银行卡、常用药的处方也一并拍下来。手机和护照通常一起丢，只存在手机里等于没存。云盘登录要收手机验证码的，手机一丢就可能登不进去。出发前在另一台设备上试登一次，确认不靠这部手机也能打开。证件照片是敏感信息，选能加密的存法更稳妥。但加密的存法忘了密码谁也打不开，所以发给家人的那一份不能省。', NULL, NULL, NULL, '不花钱。出发前拍几张照片。', '护照丢了，驻外使领馆能给你签发回国用的旅行证件，但需要你先证明自己的身份。手里有清晰的护照资料页照片、签证页照片和出入境记录，补办速度差别很大。同时你要先在当地报警，拿到报案回执。很多国家的出境检查和保险理赔都要这份材料。找使领馆的入口，就是第 2 条里存好的那两个领保电话', '存法是拍完照放进两个不同的地方，比如云盘存一份、发给一位家人一份。另外打印一份纸质复印件，和原件分开放。银行卡、常用药的处方也一并拍下来。手机和护照通常一起丢，只存在手机里等于没存。云盘登录要收手机验证码的，手机一丢就可能登不进去。出发前在另一台设备上试登一次，确认不靠这部手机也能打开。证件照片是敏感信息，选能加密的存法更稳妥。但加密的存法忘了密码谁也打不开，所以发给家人的那一份不能省。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-8', 'concept_archive_s21-8', 'claim_archive_s21-8', 'action', 'life_archive', '境外自驾先确认当地认不认中国驾照，网上卖的「国际驾照」多数是废纸', '21. 出国、旅行与境外安全', '网上代办的「国际驾照」在中国内地不成立。那本证是 1949 年日内瓦公约缔约方之间互认的翻译件，103 个缔约方里没有中国内地。所以国内不管谁给你办，都没有法律效力。能不能用中国驾照开车，看目的地自己的规定，没确认清楚就别开。', '在多数国家，无证驾驶是刑事犯罪，或者要重罚。而且出了事保险大概率拒赔，这才是真正的成本。查法有两个：在中国领事服务网上找目的地国家的「中国公民须知」，或者直接让租车公司给你一份书面确认。香港、澳门、台湾地区以及部分国家另有单独安排', NULL, NULL, NULL, '不花钱。出发前查一次目的地的规定。', '所谓「国际驾照」（IDP），是 1949 年《道路交通公约》缔约国之间互相认可的翻译件。这份公约 1949 年 9 月 19 日在日内瓦订立，1952 年 3 月 26 日生效。目前有 103 个缔约方（签约的国家和地区）。中国内地不在这份名单里。所以中国不签发这种国际驾照。任何机构在国内「代办国际驾照」，都不产生法律效力。能不能用中国驾照开车，取决于目的地国家或地区自己的规定：有的承认中国驾照加公证翻译件，有的要求换领当地驾照，有的完全不认', '在多数国家，无证驾驶是刑事犯罪，或者要重罚。而且出了事保险大概率拒赔，这才是真正的成本。查法有两个：在中国领事服务网上找目的地国家的「中国公民须知」，或者直接让租车公司给你一份书面确认。香港、澳门、台湾地区以及部分国家另有单独安排', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-9', 'concept_archive_s21-9', 'claim_archive_s21-9', 'action', 'life_archive', '找中介办签证、留学、移民，先问它有没有在移民管理机构备案', '21. 出国、旅行与境外安全', '2026 年 9 月 15 日起，办签证、留学、移民的中介要向移民管理机构备案。「包过」「保签」「材料我们帮你做」这些话，本身就在明令禁止之列。自己填表填错，顶多这次被拒签。用了假材料被认定弄虚作假，污点会留在你往后的出入境记录里。', '把「包过」「保签」「材料我们帮你做」挂在嘴上的中介，做的本来就是被明令禁止的事。一旦查出来，留下污点的是你的签证记录。自己填表申请出了问题，最多是这次被拒签。用了假材料被认定弄虚作假，后果重得多。不为赚钱的政策咨询和信息查询，不算中介服务', NULL, NULL, NULL, '不花钱。多问一句它有没有备案，再把书面材料留好。', '2018 年取消了因私出入境中介机构的准入许可（开中介不必先拿批文）。此后机构数量快速增长，也出现了「机构底数不清、部分机构违法违规办理业务、损害出境入境人员合法权益」的问题，官方连有多少家都数不清。2026 年 9 月 15 日起，这类中介改成备案管理。机构应当自设立之日起 15 日内，向所在地移民管理机构报备。此前已经在做的，要在施行之日起 90 日内补办。明令禁止的行为有这几类。一是「发布虚假信息，或者通过夸大宣传、误导性宣传等方式招徕服务对象」。二是「提供或者协助提供虚假材料，协助他人违规办理签证、停留居留证件、护照等出境入境证件或者手续」。三是「泄露、出售、非法提供……个人隐私或者个人信息」。四是「组织或者协助他人从事跨境违法犯罪活动」。境外企业、机构不得在中国境内提供这类中介服务', '把「包过」「保签」「材料我们帮你做」挂在嘴上的中介，做的本来就是被明令禁止的事。一旦查出来，留下污点的是你的签证记录。自己填表申请出了问题，最多是这次被拒签。用了假材料被认定弄虚作假，后果重得多。不为赚钱的政策咨询和信息查询，不算中介服务', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-10', 'concept_archive_s21-10', 'claim_archive_s21-10', 'action', 'life_archive', '别替陌生人出具邀请函，也别让人借你的名义办出入境手续', '21. 出国、旅行与境外安全', '替别人出邀请函或者申请材料，内容不实，罚的是出具人。个人罚 5000 元到 1 万元，有违法所得一并没收。单位罚 1 万到 5 万，经手的人另外罚 5000 到 1 万。一次人情，换来的是自己掏这笔钱。', '这和第 8 节「不帮陌生人带东西」是同一类风险：材料以你的名义出具，后果就落在你身上。公职人员和军队人员想通过中介违规办外国国籍或者境外居留资格的，中介不但不能办，还得报告监察机关', NULL, NULL, NULL, '不花钱。难的是当面推掉一次人情。', '出具邀请函的人，要对内容是不是真实负责。原文是：「个人为他人申请出境入境、停留居留出具虚假邀请函件或者其他申请材料的，由移民管理机构处 5000 元以上 1 万元以下罚款；有违法所得的，没收违法所得」。单位出具虚假材料的，罚 1 万元以上 5 万元以下。同时对直接负责的主管人员和其他直接责任人员（管事的领导和经手人），再处 5000 元以上 1 万元以下罚款', '这和第 8 节「不帮陌生人带东西」是同一类风险：材料以你的名义出具，后果就落在你身上。公职人员和军队人员想通过中介违规办外国国籍或者境外居留资格的，中介不但不能办，还得报告监察机关', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s21-11', 'concept_archive_s21-11', 'claim_archive_s21-11', 'action', 'life_archive', '出境前把行程、住处和同行人发给一位家人，约好多久联系一次', '21. 出国、旅行与境外安全', '人在境外失联，家里人可以找使领馆求助，使领馆会告诉家属当地怎么报警，立案后还会催办。前提是国内有人知道你该在哪、该什么时候联系。把航班号、住址、同行人电话和约好多久联系一次，发给一个家人就够。', '写清四样就够：航班号、住处地址、同行人的姓名和电话、约好的联系频率。要去信号差或者治安差的地方，再把「多久没消息就报警」这句话说明白。上面这些救助程序，都要先有家人知道你的行程才能开始', NULL, NULL, NULL, '不花钱。出发前发一条消息。', '中国公民在境外下落不明时，亲属可以向驻外外交机构求助。条例原文是「驻外外交机构应当提供当地报警方式及其他获取救助的信息」。当地警方立案以后，使领馆会催他们及时处理。这些求助能不能启动，取决于国内有没有人知道你本该在哪、本该什么时候联系', '写清四样就够：航班号、住处地址、同行人的姓名和电话、约好的联系频率。要去信号差或者治安差的地方，再把「多久没消息就报警」这句话说明白。上面这些救助程序，都要先有家人知道你的行程才能开始', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"21. 出国、旅行与境外安全","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-1', 'concept_archive_s22-1', 'claim_archive_s22-1', 'action', 'life_archive', '进 KTV、酒吧、密室之前先看一眼安全出口在哪，被锁被堵就换一家', '22. 怎么放松：娱乐场所和减压', '按规定，娱乐场所营业时，疏散通道和安全出口必须畅通。不许封堵，不许上锁，不许摆东西挡路，也不许遮住指示标志。网吧同样不许封门锁窗。做不到就是违法，你可以举报。包厢在地下、只有一个出口、走道堆满杂物的，换一家。', '下面几样占了任何一样，就换个地方：包厢在地下、只有一个出口、走道堆满杂物、安全出口的指示灯不亮。这类场所着火时烟大、走道窄、人多，而且多数人喝了酒。留给你逃出去的时间以秒计。举报电话按条例应当写在场所内的警示标志上', NULL, NULL, NULL, '不花钱。进门时抬头看 10 秒。', '这是经营者的法定义务。做不到就是违法，你可以举报。条例原文：「营业期间，娱乐场所应当保证疏散通道和安全出口畅通，不得封堵、锁闭疏散通道和安全出口，不得在疏散通道和安全出口设置栅栏等影响疏散的障碍物」。条例还要求，「应当在疏散通道和安全出口设置明显指示标志，不得遮挡、覆盖指示标志」。网吧也一样，被要求「营业期间禁止封堵或者锁闭门窗、安全疏散通道和安全出口」，并「禁止明火照明和吸烟」', '下面几样占了任何一样，就换个地方：包厢在地下、只有一个出口、走道堆满杂物、安全出口的指示灯不亮。这类场所着火时烟大、走道窄、人多，而且多数人喝了酒。留给你逃出去的时间以秒计。举报电话按条例应当写在场所内的警示标志上', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-2', 'concept_archive_s22-2', 'claim_archive_s22-2', 'action', 'life_archive', '点单前要价目表，娱乐场所必须明码标价，不接受「先玩后算」', '22. 怎么放松：娱乐场所和减压', '按规定，娱乐场所卖服务、卖东西都必须明码标价，还要主动把价目表拿给你看。所谓「天价酒水」，几乎都出在没看过价目表、事后按口头报价结账的场合。进包厢先要单子拍照。点完再要一份确认清单。结账有争议就当场打 12315。', '怎么做：进包厢先要一份价目表，纸质的电子的都行，拿到就拍照。点完单再要一份确认好的清单。服务员推荐的「特调」「果盘」，一律先问价再点。结账有争议时当场打 12315。别先付款再去维权，付了款你要举证就难得多', NULL, NULL, NULL, '不花钱。开口要一次单子。难在当着人开口问价，有点抹不开面子。', '条例原文：「娱乐场所提供娱乐服务项目和出售商品，应当明码标价，并向消费者出示价目表；不得强迫、欺骗消费者接受服务、购买商品。」违反价格法律法规的，由有关部门依法处罚。所谓「天价酒水」纠纷，绝大多数发生在这种场合：没有出示价目表，事后按口头报价结账', '怎么做：进包厢先要一份价目表，纸质的电子的都行，拿到就拍照。点完单再要一份确认好的清单。服务员推荐的「特调」「果盘」，一律先问价再点。结账有争议时当场打 12315。别先付款再去维权，付了款你要举证就难得多', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-3', 'concept_archive_s22-3', 'claim_archive_s22-3', 'action', 'life_archive', '场子里有人递「东西」就立刻走，容留和提供都不是「帮朋友」', '22. 怎么放松：娱乐场所和减压', '娱乐场所不许贩毒、不许提供毒品，也不许留人在里面吸，违反的要停业整顿 3 到 6 个月，重的吊销许可证。你自己吸要受治安处罚。在你订的包厢或住处让人「用一下」，就是容留他人吸毒，属于刑事犯罪。有人掏出不明粉末、片剂、烟弹请你试，当场走。', '只要有人拿出不明的粉末、片剂、电子烟弹，请你「试试」，就当场离开，别留下来看热闹。你个人担的风险比场所更重。自己吸毒，本身就要受治安处罚。在自己订的包厢或者自己住处「让朋友在这儿用一下」，构成的是容留他人吸毒，属于刑事犯罪', NULL, NULL, NULL, '不花钱。站起来走出去。难在要当着一桌人的面离席。', '条例明令禁止娱乐场所「贩卖、提供毒品，或者组织、强迫、教唆、引诱、欺骗、容留他人吸食、注射毒品」。从业人员也不得吸毒，不得为顾客做上面这些事提供条件。违反的，由公安部门没收违法所得和非法财物，责令停业整顿 3 至 6 个月。情节严重的吊销娱乐经营许可证。条例还要求场所在大厅、包厢、包间的显著位置悬挂禁毒、禁赌、禁止卖淫嫖娼的警示标志，并注明举报电话', '只要有人拿出不明的粉末、片剂、电子烟弹，请你「试试」，就当场离开，别留下来看热闹。你个人担的风险比场所更重。自己吸毒，本身就要受治安处罚。在自己订的包厢或者自己住处「让朋友在这儿用一下」，构成的是容留他人吸毒，属于刑事犯罪', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-4', 'concept_archive_s22-4', 'claim_archive_s22-4', 'action', 'life_archive', '不吃陌生人给的糖和零食，不喝离开过视线的饮料，不接别人递的烟弹', '22. 怎么放松：娱乐场所和减压', '现在的毒品不长毒品的样子。掺了合成大麻素的「上头」电子烟，看着和普通电子烟差不多，有人专在酒吧、KTV、宾馆里递给人试。骗人吸的拘留 10 到 15 日、罚 1000 到 5000 元，被骗吸了的人也要拘留 10 到 15 日。饮料离开过视线就换一杯。', '不只是娱乐场所，学校门口、朋友聚会、长途车上同理。给的是糖果、饮料还是烟弹，也都一样。被下药之后常跟着抢劫、性侵和敲诈，这部分没有公开的官方统计，属于经验判断。饮料只要离开过视线就换一杯，比事后追究省事得多。场子里有人拿出不明粉末、片剂、烟弹时怎么办，见本节第 3 条。替人带东西见第 8 节第 29 条。', NULL, NULL, NULL, '不花钱。别人递过来的一律不接。自己的杯子离开过视线，就换一杯。', '现在的毒品不长毒品的样子。合成大麻素类物质自 2021 年 7 月 1 日起被整类列管，这一大类整体按毒品管。有人把它掺进烟油，做成「上头」电子烟。最高检报道的案子里，办案人员的描述是：这种烟油「可以通过添加食用颜料变成各种颜色、各种口味」，「在外观上和普通电子烟基本一致」。卖家在酒吧、KTV、宾馆呼朋引伴推销，诱导他人吸食。报道里，当地当年办理的吸食案件中，未成年吸食者占比近四成。依托咪酯自 2023 年 10 月 1 日起列入第二类精神药品目录。骗人吸食本身就是一档违法：引诱、教唆、欺骗或者强迫他人吸食、注射毒品的，拘留 10 到 15 日并罚 1000 到 5000 元。构成犯罪的判 3 年以下，情节严重的判 3 到 7 年，强迫的判 3 到 10 年，对未成年人下手的从重。后果也落在被骗的人身上：吸食、注射毒品的，处 10 到 15 日拘留并可罚 3000 元以下。情节较轻的处 5 日以下拘留或者 1000 元以下罚款。还可能被同时责令 6 个月到 1 年内不得进入娱乐场所。成瘾的责令社区戒毒 3 年。拒绝社区戒毒、或者戒毒期间再吸的，强制隔离戒毒 2 年，最长可再延长 1 年（全国，治安管理处罚法 2026 年 1 月起）', '不只是娱乐场所，学校门口、朋友聚会、长途车上同理。给的是糖果、饮料还是烟弹，也都一样。被下药之后常跟着抢劫、性侵和敲诈，这部分没有公开的官方统计，属于经验判断。饮料只要离开过视线就换一杯，比事后追究省事得多。场子里有人拿出不明粉末、片剂、烟弹时怎么办，见本节第 3 条。替人带东西见第 8 节第 29 条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-5', 'concept_archive_s22-5', 'claim_archive_s22-5', 'action', 'life_archive', '剧本杀、密室别去开在居民楼里或者地下二层以下的', '22. 怎么放松：娱乐场所和减压', '五部门 2022 年的通知写明，剧本娱乐场所不得开在居民楼内，也不得开在地下一层以下。这类场地黑、隔断多、道具易燃，门还常常要解谜才打得开。一旦起火，比普通商铺难跑得多。订之前在点评页看一眼地址和楼层，不合规的换一家。', '这类场所的特点是黑暗、隔断多、道具易燃，门常常需要「解谜」才能打开。一旦起火，比普通商铺更难跑出去。订之前在点评页面上就能看出楼层，也能看出是不是居民楼。不合规的直接换一家', NULL, NULL, NULL, '不花钱。订之前问一句地址在几层。', '五部门 2022 年的专门通知写得很具体：「剧本娱乐经营场所不得设在居民楼内、建筑物地下一层以下（不含地下一层）等地」。通知还要求场所落实安全生产法和消防法的要求，「常态化开展火灾风险自知、自查、自改，提高紧急情况下的组织疏散逃生和初起火灾扑救能力」。同一份通知还要求剧本设置适龄提示。场景不适宜未成年人的，不得允许未成年人进入。除法定节假日、休息日及寒暑假外，不得向未成年人提供剧本娱乐活动', '这类场所的特点是黑暗、隔断多、道具易燃，门常常需要「解谜」才能打开。一旦起火，比普通商铺更难跑出去。订之前在点评页面上就能看出楼层，也能看出是不是居民楼。不合规的直接换一家', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-6', 'concept_archive_s22-6', 'claim_archive_s22-6', 'action', 'life_archive', '心情差就去走或者跑，抗抑郁的效应量（效果大小）跟强度成正比', '22. 怎么放松：娱乐场所和减压', '心情差的时候，快走或慢跑改善最明显。其次是瑜伽、力量训练、太极气功，几种差距不大。强度开得越高效果越好，力量训练和瑜伽最容易坚持。这方面的证据质量偏低，能确定的是动比不动好，挑自己坚持得下来的那种。', '争议。作者自己写明，218 项研究里只有 1 项做得够干净、不容易被设计带偏。按通行的打分法，快走慢跑只算「低」可信，其余是「极低」。运动也瞒不住参与者，人知道自己在锻炼，就容易觉得好些，这份期待去不掉。结论方向仍然可用：动比不动好，强度别太低，选自己能坚持的那种。这是第 3 节「情绪低落时先动起来」的展开，不能替代确诊后的规范治疗', NULL, NULL, NULL, '不花钱。每次半小时上下。难在情绪差的时候最不想动，得推自己一把。', '这是把 218 项随机分成两组的对照试验合在一起算的结果。涉及 495 个组、14170 名符合重度抑郁临床标准的参与者。算法让各种运动互相比较（贝叶斯网状荟萃分析）。拿来对比的是常规照护和安慰剂片（主动对照）。效果大小用 Hedges'' g 表示，数越往负走，症状改善越多。快走或慢跑 −0.62（95% 可信区间 −0.80 至 −0.45，意思是真实值大致落在这一段里）。瑜伽 −0.55（−0.73 至 −0.36）。力量训练 −0.49（−0.69 至 −0.29）。混合有氧 −0.43（−0.61 至 −0.24）。太极或气功 −0.42（−0.65 至 −0.21）。原文说「运动的效果与所处方的强度成正比」：强度开得越高，效果越好。力量训练和瑜伽的可接受度最好，最容易坚持下来', '争议。作者自己写明，218 项研究里只有 1 项做得够干净、不容易被设计带偏。按通行的打分法，快走慢跑只算「低」可信，其余是「极低」。运动也瞒不住参与者，人知道自己在锻炼，就容易觉得好些，这份期待去不掉。结论方向仍然可用：动比不动好，强度别太低，选自己能坚持的那种。这是第 3 节「情绪低落时先动起来」的展开，不能替代确诊后的规范治疗', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-7', 'concept_archive_s22-7', 'claim_archive_s22-7', 'action', 'life_archive', '焦虑到影响生活时，正念减压课的效果不劣于常用的抗焦虑药', '22. 怎么放松：娱乐场所和减压', '确诊焦虑障碍的人上 8 周正念减压课，症状改善和吃抗焦虑药艾司西酞普兰几乎一样。吃药的人近八成出过不良反应，有人因此退出。上课的人约一成半出过，没人退出。课得是标准化的 8 周课程，随便一个冥想 App 不算。', '试验用的是标准化的 8 周正念减压课程（MBSR），随便一个冥想 App 不能和它划等号。它适用于已经达到焦虑障碍诊断标准的人，该看医生还是要看。如果你因为顾虑药物副作用一直拖着不治疗，这是一个证据强度相当的选项', NULL, NULL, NULL, '报课要花一点钱。课程 8 周，每周上一次课，还要每天在家练。难在连着 8 周每天都练。', '这是美国 3 家城市学术医疗中心做的试验，目的是看上课会不会比吃药差（非劣效随机对照试验）。276 名确诊焦虑障碍的成年人按 1:1 随机对半分组。一组上 8 周正念减压课程。一组吃艾司西酞普兰（10 至 20 mg 弹性剂量）。208 人做完全程。结束时按医生打的焦虑严重程度分（临床总体印象严重度量表）算，正念组下降 1.35，药物组下降 1.43。两组差 −0.07（95% CI −0.38 至 0.23，即真实差距大致落在这一段里；P=0.65，即这点差距和没差别看不出区别）。这一段的下限没有越过事先划好的「算不上更差」的线（非劣效界值 −0.495）。副作用差别很大：药物组 78.6% 至少出现一次和试验有关的不良反应，10 人因此退出。正念组 15.4%，无人因此退出', '试验用的是标准化的 8 周正念减压课程（MBSR），随便一个冥想 App 不能和它划等号。它适用于已经达到焦虑障碍诊断标准的人，该看医生还是要看。如果你因为顾虑药物副作用一直拖着不治疗，这是一个证据强度相当的选项', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-8', 'concept_archive_s22-8', 'claim_archive_s22-8', 'action', 'life_archive', '当场想缓过来，用 5 分钟「循环叹息」：吸气两段，呼气拉长', '22. 怎么放松：娱乐场所和减压', '每天做 5 分钟呼吸练习、坚持一个月，情绪改善和呼吸放慢都比同样时长的正念冥想好。几种呼吸法里，把呼气拉长的「循环叹息」最好。做法是用鼻子吸一口，再补吸一小口把肺撑满，然后用嘴慢慢吐尽。这只是一项试验，好坏靠本人自己报，但不花钱。', '做法是用鼻子吸一口，短暂再补吸一小口把肺撑满，然后用嘴把气缓慢长长地吐尽，重复 5 分钟。只有这一项试验，在家做，好不好由本人填问卷报，人数也不多。效果只是比冥想略好，解决不了问题。但它不花钱，只要 5 分钟，随时随地能做，性价比高', NULL, NULL, NULL, '不花钱。每天 5 分钟。', '这是一项在家做、随机分组的对照试验，比较三种每天 5 分钟的呼吸练习和同样时长的正念冥想，持续 1 个月。三种呼吸法是：循环叹息（强调延长呼气）、箱式呼吸（吸气、屏息、呼气等长）、带屏息的循环过度换气（吸气长、呼气短）。把各人各次的数据放在一起算（混合效应模型），呼吸练习都好过正念冥想，尤其是以呼气为主的循环叹息。它在情绪改善（P&lt;0.05，即这点差别不像是碰巧撞出来的）和呼吸频率下降（P&lt;0.05）上都更好', '做法是用鼻子吸一口，短暂再补吸一小口把肺撑满，然后用嘴把气缓慢长长地吐尽，重复 5 分钟。只有这一项试验，在家做，好不好由本人填问卷报，人数也不多。效果只是比冥想略好，解决不了问题。但它不花钱，只要 5 分钟，随时随地能做，性价比高', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-9', 'concept_archive_s22-9', 'claim_archive_s22-9', 'action', 'life_archive', '把「定期和人见面」当成健康支出，别只在心情差时才找人', '22. 怎么放松：娱乐场所和减压', '平时很少和人来往的人，同期死亡的概率高约三成。感到孤独的人高约四分之一，独居的人高约三成，65 岁以下的人更明显。这些都是跟踪观察出来的，也可能是身体本来就差的人更容易独居。', '争议。这些都是跟着人群观察出来的关联，不是分组对照试验，谁因谁果分不开。身体本来就差的人，更容易独居、更少社交。作者把社会关系看作和吸烟、肥胖同一量级的健康因素，但没有随机试验证明「增加社交能降低死亡率」。这条与第 3 节「减少让你消耗的人际关系」不冲突：那条砍掉消耗你的关系，这里要保住让你恢复精力的那几段', NULL, NULL, NULL, '要花一点钱，还要搭上见面的时间。难在心情好的时候也得主动约人。', '这是把 70 项先记录情况再往后跟踪的研究合在一起算的结果（荟萃分析），共 340 万名参与者，平均跟踪 7 年。社会隔离、孤独感、独居都与死亡率升高相关。把年龄、身体状况这些干扰因素扣掉之后，加权平均比值比分别是：社会隔离 1.29、孤独 1.26、独居 1.32。换算过来，同期死亡的概率分别高约三成、约四分之一、约三成。三者的效果大小差不多，而且在 65 岁以下人群中比在老年人群中更大', '争议。这些都是跟着人群观察出来的关联，不是分组对照试验，谁因谁果分不开。身体本来就差的人，更容易独居、更少社交。作者把社会关系看作和吸烟、肥胖同一量级的健康因素，但没有随机试验证明「增加社交能降低死亡率」。这条与第 3 节「减少让你消耗的人际关系」不冲突：那条砍掉消耗你的关系，这里要保住让你恢复精力的那几段', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s22-10', 'concept_archive_s22-10', 'claim_archive_s22-10', 'action', 'life_archive', '住得离绿地近就多用它，散步、遛弯、坐着都算', '22. 怎么放松：娱乐场所和减压', '住处周边 500 米内的绿化越好，同期死亡的概率越低，按植被指数每提高 0.1 算，低约 4%。量的是住处周边的绿化，不是你去公园的次数。绿化好的地段，住的人往往更有钱、空气也更好。所以别当成去公园就能延寿，选住处时把周边绿地算进去就行。', '争议。各项研究的结果差得很远（I²=95%，这个数越大越是彼此对不上）。而且它测的是居住地周边的绿化程度，和你去公园的次数无关。住在绿化好的地方的人往往也更富、空气更好、更爱运动，这几样和绿化分不开谁在起作用。别读成「去公园就能延寿」，可用的部分是选住处时把绿地算进去，成本为零。NDVI 这个数，裸地和水泥接近 0，茂密植被接近 1。所以「0.1」大致是从光秃街区挪到有成排行道树的街区那种差别', NULL, NULL, NULL, '不花钱。顺路就做了。', '这是把 9 项跟踪人群多年的研究合在一起算的结果（队列研究的荟萃分析），涉及 7 个国家、832 万人。看的是住处 500 米以内的周边绿化程度，用归一化植被指数（NDVI，把地面绿化折算成的一个数）衡量。绿化程度每增加 0.1 个指数，总死亡率的合并风险比为 0.96（95% CI 0.94–0.97），同期死亡的概率低约 4%，真实值大致落在低 3% 到低 6% 这一段。9 项研究中有 7 项发现绿化越好死亡率越低，差别也不像碰巧。另外 2 项没看出关联', '争议。各项研究的结果差得很远（I²=95%，这个数越大越是彼此对不上）。而且它测的是居住地周边的绿化程度，和你去公园的次数无关。住在绿化好的地方的人往往也更富、空气更好、更爱运动，这几样和绿化分不开谁在起作用。别读成「去公园就能延寿」，可用的部分是选住处时把绿地算进去，成本为零。NDVI 这个数，裸地和水泥接近 0，茂密植被接近 1。所以「0.1」大致是从光秃街区挪到有成排行道树的街区那种差别', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"22. 怎么放松：娱乐场所和减压","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-1', 'concept_archive_s23-1', 'claim_archive_s23-1', 'action', 'life_archive', '不满 16 周岁没有「去打工」这个选项：招你的单位每月被罚 5000 元，肯招的都是黑工', '23. 学什么技能划算', '初中毕业一般 15 到 16 岁，正好卡在这条线上。不满 16 岁，单位招你就是违法，每用一名童工每月罚 5000 元。所以肯要你的，都是明知违法还敢用的单位。真出了事，医药费和赔偿只能找这家单位要，它赖账或者跑了，就没人替它兜底。', '受益人是自己。满 16 岁以后打工是合法的。但肯要一个 16 岁、没学历的人的岗位，正好是本节第 10 条（挑抗自动化的技能）讲的那一类：流程固定，最容易被机器顶掉。第 19 节讲的加班费、年休假、工伤待遇，前提都是有劳动关系、有证据。黑工这两样都没有，那些钱也就拿不到', NULL, NULL, NULL, '不花钱。花一分钟算一下自己多大。', '《义务教育法》第十一条：「凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育」。第十四条：「禁止用人单位招用应当接受义务教育的适龄儿童、少年」。第五十八条：没有正当理由、不按本法规定送适龄儿童少年入学的，由当地乡镇人民政府或者县级人民政府教育行政部门「给予批评教育，责令限期改正」。《禁止使用童工规定》第二条：国家机关、社会团体、企业事业单位、民办非企业单位或者个体工商户「均不得招用不满16周岁的未成年人」。第六条：「按照每使用一名童工每月处5000元罚款的标准给予处罚」，逾期不改正的按每人每月 1 万元罚。第七条：介绍童工去就业的，「按照每介绍一人处5000元罚款」。第十条：童工患病或者受伤的，用人单位「应当负责送到医疗机构治疗，并负担治疗期间的全部医疗和生活费用」，伤残或死亡的还要一次性赔偿。第十三条只留了一个例外：文艺、体育单位经父母或者其他监护人同意，可以招用不满 16 周岁的专业文艺工作者、运动员（全国）', '受益人是自己。满 16 岁以后打工是合法的。但肯要一个 16 岁、没学历的人的岗位，正好是本节第 10 条（挑抗自动化的技能）讲的那一类：流程固定，最容易被机器顶掉。第 19 节讲的加班费、年休假、工伤待遇，前提都是有劳动关系、有证据。黑工这两样都没有，那些钱也就拿不到', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-2', 'concept_archive_s23-2', 'claim_archive_s23-2', 'action', 'life_archive', '把「读书有没有用」也放进死亡率账里：每多受一年教育，成人死亡风险降约 1.9%', '23. 学什么技能划算', '每多读一年书，成年后的死亡风险平均低约 1.9%。18 到 49 岁的人最明显，每多一年低约 2.9%，70 岁以上只低 0.8%。能一直读下去的人往往本来条件就好，这里面有多少是读书本身的作用，分不清。', '争议。作者自己报告了发表偏倚（p&lt;0.0001），意思是结果好看的研究更容易被发出来。各项研究之间的结果也差得很开。纳入的都是跟踪观察，不是把人分组做的试验。读书年数和家庭条件、地区、职业搅在一起，这 1.9% 里有多少是读书本身带来的、有多少是「能一直读下去的人本来条件就好」，这类研究分不开。反过来的路也分不开：小时候就有病、有心理问题的人，更容易辍学，也更容易早死，这会让读书的作用看起来比实际大。所以它能有力说明「多读书和活得久是同向的」，但不等于「你去读书就能延寿 1.9%」。收益量级定为小：读者面对的通常是再多读三四年，按每年 1.9% 算加起来不到一成，按全书的界线只算小。受益人是自己', NULL, NULL, NULL, '不花钱。花的是多读那几年的时间和精力，学费那部分见本节第 4 条（中职学费和助学金）。难在要一直读下去，中间不放弃。', '把此前的研究找齐再合在一起算（系统综述与荟萃分析）。检索范围是 1980 年 1 月到 2023 年 5 月，最终纳入 603 项研究、59 个国家 70 个地点、10355 个观测。教育和成人死亡率（各种原因加起来的死亡）是剂量反应关系（读得越多降得越多）。每多受一年教育，死亡风险平均下降 1.9%（95% 不确定区间 1.8–2.0，真实值大致落在这一段里）。18 至 49 岁的人每多一年下降 2.9%（2.8–3.0）。70 岁以上的人下降 0.8%（0.6–1.0）。男女之间没看出差别。按国家发展水平（社会人口指数）分开看，也没看出差别', '争议。作者自己报告了发表偏倚（p&lt;0.0001），意思是结果好看的研究更容易被发出来。各项研究之间的结果也差得很开。纳入的都是跟踪观察，不是把人分组做的试验。读书年数和家庭条件、地区、职业搅在一起，这 1.9% 里有多少是读书本身带来的、有多少是「能一直读下去的人本来条件就好」，这类研究分不开。反过来的路也分不开：小时候就有病、有心理问题的人，更容易辍学，也更容易早死，这会让读书的作用看起来比实际大。所以它能有力说明「多读书和活得久是同向的」，但不等于「你去读书就能延寿 1.9%」。收益量级定为小：读者面对的通常是再多读三四年，按每年 1.9% 算加起来不到一成，按全书的界线只算小。受益人是自己', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 死亡率","钱 0","时间 多","毅力 是","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-3', 'concept_archive_s23-3', 'claim_archive_s23-3', 'action', 'life_archive', '判断「学历是不是贬值了」之前，先看全国的学历结构：每 10 万人里只有 15467 人有大学文化程度（2020 年普查，2025 年抽样推算约 19%）', '23. 学什么技能划算', '2020 年人口普查时，全国念到大专及以上的约占 15%。2025 年的抽样调查推算约 19%，五年里多了几个百分点。两次都是初中学历的人最多。15 岁以上的人平均只读了 9.91 年书，刚过初中毕业。所以初中学历在中国不是「够用」，是最普通的那一档。', '这些数只说明学历在人群里稀不稀缺。某个具体的人读书划不划算，要按本节第 6 条（读书还是打工怎么算）的方法自己算。还要注意：普查数的是全国所有人口，老人小孩都算在内。年轻人里念到大学的比例比这个数高得多，拿它跟同龄人比会高估自己的优势。反过来，用它去反驳「读书没用」是成立的，因为分母正是要跟你抢饭碗的整个劳动力。2025 年的数是抽样推算的，普查是挨家挨户全数，两者口径不同，所以两组数并列，不拿新数替换旧数。19.4% 和 32.2% 是按公报的人数和总人口自己算的。受益人是自己', NULL, NULL, NULL, '不花钱。看一眼下面的数字就行。', '第七次全国人口普查的标准时点是 2020 年 11 月 1 日。全国人口里，有大学（大专及以上）文化程度的 218360767 人。高中（含中专）213005258 人。初中 487163489 人。小学 349658828 人。和 2010 年第六次人口普查相比，每 10 万人中有大学文化程度的由 8930 人上升为 15467 人。高中由 14032 人上升为 15088 人。初中由 38788 人下降为 34507 人。小学由 26779 人下降为 24767 人。15 岁及以上人口的平均受教育年限由 9.08 年提高到 9.91 年。文盲率由 4.08% 下降为 2.67%。2025 年全国 1% 人口抽样调查的标准时点是 2025 年 11 月 1 日，样本 2052 万人。按样本推算全国人口 140545 万人。其中大学（大专及以上）27233 万人，高中（含中专）24272 万人，初中 45283 万人，小学 33122 万人。公报没有给每 10 万人的数。按总人口自己折算，大学约占 19.4%，初中约占 32.2%，仍是人数最多的一档', '这些数只说明学历在人群里稀不稀缺。某个具体的人读书划不划算，要按本节第 6 条（读书还是打工怎么算）的方法自己算。还要注意：普查数的是全国所有人口，老人小孩都算在内。年轻人里念到大学的比例比这个数高得多，拿它跟同龄人比会高估自己的优势。反过来，用它去反驳「读书没用」是成立的，因为分母正是要跟你抢饭碗的整个劳动力。2025 年的数是抽样推算的，普查是挨家挨户全数，两者口径不同，所以两组数并列，不拿新数替换旧数。19.4% 和 32.2% 是按公报的人数和总人口自己算的。受益人是自己', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-4', 'concept_archive_s23-4', 'claim_archive_s23-4', 'action', 'life_archive', '「读不起」先按政策算一遍：中职学费大多已免，助学金 2300 元，助学贷款每年最高 2 万', '23. 学什么技能划算', '公办中职里，农村学生、城市涉农专业学生和家庭困难学生已经免学费。中职和普通高中的助学金，2025 年春季起每年 2300 元。上了大学，助学金每年 3700 元，助学贷款每年最多能借 2 万。钱不够可以推迟、可以换个办法，很少到必须现在退学去打工的地步。', '受益人是自己和子女。免学费具体覆盖哪些人、助学金分几档，都由各省定。民办学校按当地公办同类专业的标准补助，差额还是要自己付，所以入学前要按本地文件核一遍。助学贷款是贷款不是补助，毕业后要还。但它把「现在拿不出学费」和「这几年划不划算」拆成了两件事，先别把钱不够当成结论。第 7 节写过失业期间的培训补贴和临时救助，家里确实断了收入就先去申请那几样', NULL, NULL, NULL, '不花钱。开学前去学校的学生资助管理机构问一次，交一次材料。', '中职免学费是 2012 年秋季学期起的政策。原文是「对公办中等职业学校全日制正式学籍一、二、三年级在校生中所有农村（含县镇）学生、城市涉农专业学生和家庭经济困难学生免除学费（艺术类相关表演专业学生除外）」。2024 年调整了学生资助政策。本专科生国家助学金由每生每年 3300 元提高到 3700 元。国家励志奖学金由 5000 元提高到 6000 元。这两项从 2024 年秋季学期起执行（励志奖学金自 2024 年起）。中等职业学校国家助学金、普通高中国家助学金都由每生每年 2000 元提高到 2300 元，从 2025 年春季学期起执行。国家助学贷款也调了，从 2024 年秋季学期起。本专科学生「每人每年申请贷款额度由不超过16000元提高至不超过20000元」。研究生「由不超过20000元提高至不超过25000元」。利率是同期同档次的贷款市场报价利率（LPR）减 70 个基点（再低 0.7 个百分点）（全国）', '受益人是自己和子女。免学费具体覆盖哪些人、助学金分几档，都由各省定。民办学校按当地公办同类专业的标准补助，差额还是要自己付，所以入学前要按本地文件核一遍。助学贷款是贷款不是补助，毕业后要还。但它把「现在拿不出学费」和「这几年划不划算」拆成了两件事，先别把钱不够当成结论。第 7 节写过失业期间的培训补贴和临时救助，家里确实断了收入就先去申请那几样', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-5', 'concept_archive_s23-5', 'claim_archive_s23-5', 'action', 'life_archive', '没考上普高不等于路断了：中职有贯通招生和单独考试，技能岗位招聘还可以降学历要求', '23. 学什么技能划算', '2022 年的职业教育法写明：职业教育和普通教育地位同等重要。中职可以和高职贯通招生，高职还必须留出招生计划或者单独考试，专门招中职毕业生。用人单位也不得因为你是职业学校毕业就设门槛卡你。分数不够上普高，是换一条路，不是停在初中学历。', '受益人是自己和子女。这些是法定的通道，不是保证录取。贯通培养有哪些专业、单独招生留多少比例、职教高考考哪些科目，都由各省定。报志愿前必须查本省当年的职教招生平台和招生计划，别按外省的经验推。挑中职专业时，用本节第 10 条（挑抗自动化的技能）的维度过一遍：要到现场、环境不标准的专业更难被顶掉。选学校就看它在不在本省当年的职教招生计划里。它发的证再按第 8 条（查证书在不在目录里）那三步验一遍。招生宣传里承诺「包分配」「保过」的一律不要', NULL, NULL, NULL, '不花钱。填中考志愿之前，查一次本省的职教招生平台。', '《职业教育法》（2022 年 5 月 1 日起施行）第三条：「职业教育是与普通教育具有同等重要地位的教育类型」。第三十七条：中等职业学校「可以按照国家有关规定，在有关专业实行与高等职业学校教育的贯通招生和培养」。高等职业学校「可以按照国家有关规定，采取文化素质与职业技能相结合的考核方式招收学生」。省级以上教育行政部门要建立职业教育统一招生平台，汇总发布学校、专业设置和招生情况，并提供查询报考服务。第五十三条：「职业学校学生在升学、就业、职业发展等方面与同层次普通学校学生享有平等机会」。高等职业学校和实施职业教育的普通高等学校「应当在招生计划中确定相应比例或者采取单独考试办法，专门招收职业学校毕业生」。「用人单位不得设置妨碍职业学校毕业生平等就业、公平竞争的报考、录用、聘用条件」。事业单位公开招聘中有职业技能等级要求的岗位「可以适当降低学历要求」（全国）', '受益人是自己和子女。这些是法定的通道，不是保证录取。贯通培养有哪些专业、单独招生留多少比例、职教高考考哪些科目，都由各省定。报志愿前必须查本省当年的职教招生平台和招生计划，别按外省的经验推。挑中职专业时，用本节第 10 条（挑抗自动化的技能）的维度过一遍：要到现场、环境不标准的专业更难被顶掉。选学校就看它在不在本省当年的职教招生计划里。它发的证再按第 8 条（查证书在不在目录里）那三步验一遍。招生宣传里承诺「包分配」「保过」的一律不要', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-6', 'concept_archive_s23-6', 'claim_archive_s23-6', 'action', 'life_archive', '把「读书还是打工」算成一道题：早挣的三年工资，对上往后几十年的年收入差', '23. 学什么技能划算', '把两种选择摊在纸上比。早工作挣到的是三年低门槛岗位的工资，只有这一次。继续读，换回的是往后每年多挣的那一截，还要乘以剩下的三四十年。中国城镇多读一年书，收入平均高 4.0%（1988 年）到 10.2%（2001 年）。数据老，只能看个大概。', '算之前先扣掉本节第 4 条（中职学费和助学金）那些免学费和助学金，另外还有本节第 2 条（多受一年教育和死亡率）那笔账。数据截至 2001 年，只覆盖城镇，不能直接当今天的数用。本节第 7 条那个全球平均 9% 也一样。真按这个方法算，结论会因人而异。学费高、专业和岗位对不上、读的年限又长的，算出来可能真不划算，但那只说明这个具体项目不划算，说明不了读书无用。还有几项进不了公式：法定的学历门槛，见本节第 5 条（中职的贯通招生和单独考试）；抗替代能力，见第 10 条（挑抗自动化的技能）；能不能换行业。受益人是自己', NULL, NULL, NULL, '不花钱。坐下来算一次，大概半小时。', '这是对中国城镇 1988 至 2001 年的估计。多读一年书能让收入高出多少，这叫教育回报率。原文写的是「从 1988 年每受教育一年 4.0% 大幅上升到 2001 年的 10.2%」。涨幅主要发生在 1992 年之后。它反映的是念到大学的人比没念的多挣的那一截（高等教育工资溢价）在变大。这是把「多读一年」折成年收入差时可用的中国本土量级。全球平均值见本节第 7 条（多受一年教育的全球平均回报）', '算之前先扣掉本节第 4 条（中职学费和助学金）那些免学费和助学金，另外还有本节第 2 条（多受一年教育和死亡率）那笔账。数据截至 2001 年，只覆盖城镇，不能直接当今天的数用。本节第 7 条那个全球平均 9% 也一样。真按这个方法算，结论会因人而异。学费高、专业和岗位对不上、读的年限又长的，算出来可能真不划算，但那只说明这个具体项目不划算，说明不了读书无用。还有几项进不了公式：法定的学历门槛，见本节第 5 条（中职的贯通招生和单独考试）；抗替代能力，见第 10 条（挑抗自动化的技能）；能不能换行业。受益人是自己', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"23. 学什么技能划算","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-7', 'concept_archive_s23-7', 'claim_archive_s23-7', 'action', 'life_archive', '先记住基准线：多受一年教育，全球平均的私人回报（落到自己收入上的那部分）约为每年 9%', '23. 学什么技能划算', '按全世界平均算，多读一年书，个人收入每年高约 9%，女性的回报一直高于男性。这个数说的是正规上学，报一个班不能直接套。拿它当尺子：一个课程要你花 3 万元和半年，就问它带来的收入变化抵不抵多读一年书。', '这是「多读一年书」的全球平均值，不能当成「报一个班」的收益，也不是中国的具体数字，只能当量级参照。它的用处是给所有培训方案一把尺子：一个课程要你花 3 万元和半年时间，就该问它能不能带来相当于一年正规教育的收入变化。还要注意，全球平均掩盖了巨大的专业差异和国别差异', NULL, NULL, NULL, '不花钱。把这个数记住，当成衡量各种「学点东西」方案的尺子。', '一项覆盖 1950 至 2014 年、139 个国家、1120 项估计的综述算出：「多受一年教育的全球平均私人回报率是每年 9%」。私人回报就是落到本人收入上的那一部分：多读一年书，收入平均高约 9%。高等教育的私人回报在上升。教育的社会回报（落到整个社会而不是本人身上的那部分）仍然很高。女性受教育的平均回报持续高于男性', '这是「多读一年书」的全球平均值，不能当成「报一个班」的收益，也不是中国的具体数字，只能当量级参照。它的用处是给所有培训方案一把尺子：一个课程要你花 3 万元和半年时间，就该问它能不能带来相当于一年正规教育的收入变化。还要注意，全球平均掩盖了巨大的专业差异和国别差异', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-8', 'concept_archive_s23-8', 'claim_archive_s23-8', 'action', 'life_archive', '花钱考证之前，先查这张证在不在国家职业资格目录或人社部备案的评价机构名单里', '23. 学什么技能划算', '有些机构打着新职业、技能等级的名义乱办班、乱收费、滥发证，还有假冒权威机构的，人社部专门治理过。报名前按三步查：这个职业在不在国家职业资格目录、发证机构是不是人社部门备案的评价机构、证书编号能不能在官方平台查到。查不到的，报名费就是白花。', '按这个顺序验。先看这个职业在不在《国家职业资格目录》里，不在目录里的就不是国家职业资格。再看发证机构是不是人社部门备案的评价机构。最后到官方的技能人才评价证书查询平台，查证书编号能不能查到。查不到的一律不报。带「国际」「高级」「注册」字样、承诺「包过」「挂靠有收入」的，风险最高', NULL, NULL, NULL, '不花钱。查一次，十几分钟。', '人社部专门为此开展过全国性治理。文件里点名的乱象是「一些机构和单位以新职业职业资格、职业技能等级等名义随意举办培训、评价、发证活动，乱收费、滥发证；一些机构和单位虚假或夸大宣传，甚至假冒权威机构名义组织培训、评价、颁发证书等」。治理措施包括联合网信、公安、市场监管等部门查处，「严厉打击假冒鉴定机构、人社部门备案评价机构的评价发证活动」。网站和新媒体上不合规的宣传，依法关停。文件同时要求「引导公众了解证书查询渠道和方式，判断证书合法合规性和含金量」', '按这个顺序验。先看这个职业在不在《国家职业资格目录》里，不在目录里的就不是国家职业资格。再看发证机构是不是人社部门备案的评价机构。最后到官方的技能人才评价证书查询平台，查证书编号能不能查到。查不到的一律不报。带「国际」「高级」「注册」字样、承诺「包过」「挂靠有收入」的，风险最高', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-9', 'concept_archive_s23-9', 'claim_archive_s23-9', 'action', 'life_archive', '培训优先走政府补贴渠道，别一上来就自费报商业班', '23. 学什么技能划算', '2025 年到 2027 年底，国家计划办 3000 万人次以上的补贴培训。钱从就业补助资金、失业保险基金、企业职工教育经费等多个口子出。哪个工种越缺人、培训成本越高，补贴就越高。在职的先问单位，其余人先翻当地人社局的补贴目录，再决定学什么。', '具体怎么领、能领多少由各省定。入口是当地人社局官网的「职业培训补贴目录」和公共实训基地。第 7 节写过失业期间的职业培训补贴（同一个人最多享受 3 次）和社保补贴。在职的人则先问单位的职工教育经费。先查补贴目录再选学什么，比先选好再去找补贴省钱得多', NULL, NULL, NULL, '不花钱，或者能大幅减免。培训本身要占时间。难在忍住别一冲动就自费报班，先去查一遍补贴目录。', '国家层面的规模是明确的：2025 年到 2027 年底，「聚焦高精尖产业与急需行业、就业重点群体等开展补贴性培训 3000 万人次以上」。资金来源被打通为一揽子：就业补助资金、失业保险基金、行业发展资金、东西部协作资金、企业职工教育经费等。补贴高低按职业（工种）的急需紧缺程度和培训成本来定，不同工种不一样。对企业还要求「按规定足额提取和使用职工教育经费，确保 60% 以上用于一线职工教育和培训」', '具体怎么领、能领多少由各省定。入口是当地人社局官网的「职业培训补贴目录」和公共实训基地。第 7 节写过失业期间的职业培训补贴（同一个人最多享受 3 次）和社保补贴。在职的人则先问单位的职工教育经费。先查补贴目录再选学什么，比先选好再去找补贴省钱得多', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-10', 'concept_archive_s23-10', 'claim_archive_s23-10', 'action', 'life_archive', '挑技能时优先看「要不要动手、要不要现场判断」，这类最难被自动化顶掉', '23. 学什么技能划算', '按美国的估算，约 47% 的岗位有较高风险被计算机接手，后来按具体任务估的比例低得多。机器难过的坎有三样：手上的灵巧劲、想出新东西、跟人打交道。所以要到现场、环境不标准、得临场判断的活更难被顶掉，流程固定、主要处理信息的岗位风险最高。', '争议。这项研究是 2013 年一份没正式发表的论文稿，打分打的是「整个职业能不能被机器接手」。后来有研究改成拆到一件件具体任务上去估，算出来的高风险比例低得多。它也不说这事会在哪一年发生。用它时别盯着 47% 这个数，要看它点出的那三处卡住机器的地方。现场安装、检修、护理这类活比纯文书更抗替代，原因就在这里。所以「学个技能」优先该选需要到现场、面对非标准环境的那种', NULL, NULL, NULL, '不花钱。选之前先按这个维度把想学的活过一遍。', '给美国 702 个职业逐个估「这活多大概率能交给计算机做」（可计算化概率评估），结果是约 47% 的就业岗位处于高风险区间。模型里决定风险高低的，是三处机器目前迈不过去的坎，作者叫它「工程瓶颈」。一是感知与操作，包括手指灵巧度、手部灵巧度、在狭窄空间和别扭姿势下作业。二是创造性智能（想出新东西的能力）。三是社会智能（跟人打交道的能力）。所以环境非标准、需要手上功夫和临场判断的活，被替代的概率一贯更低，不是个别职业的偶然。流程固定、以信息处理为主的岗位风险最高', '争议。这项研究是 2013 年一份没正式发表的论文稿，打分打的是「整个职业能不能被机器接手」。后来有研究改成拆到一件件具体任务上去估，算出来的高风险比例低得多。它也不说这事会在哪一年发生。用它时别盯着 47% 这个数，要看它点出的那三处卡住机器的地方。现场安装、检修、护理这类活比纯文书更抗替代，原因就在这里。所以「学个技能」优先该选需要到现场、面对非标准环境的那种', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"23. 学什么技能划算","B 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-11', 'concept_archive_s23-11', 'claim_archive_s23-11', 'action', 'life_archive', '学之前先确认这个技能有没有等级评价，等级能不能换成钱', '23. 学什么技能划算', '国家在推「新八级工」，要求企业把岗位工资和技能等级挂钩，表现突出的职工还能不看工龄资历直接认定等级。这是政策方向，各地各企业差别很大。有国家职业标准和等级通道的技能，往后才谈得上按等级涨薪，学之前先查一下有没有。', '这是政策方向，不是已经兑现的工资数，各地各企业的落地程度差别很大。能照着做的部分是：选技能时看它有没有对应的国家职业标准和等级通道，有通道的技能后面才谈得上按等级涨薪。没有等级、也没有行业准入门槛的「技能」，学完只能靠自己找活', NULL, NULL, NULL, '不花钱。查一次就行。', '国家正在推「新八级工」职业技能等级制度。文件明确要求把等级和薪酬挂钩，原话是「强化技能导向的薪酬分配制度……指导企业实行岗位薪酬与岗位价值、技能等级双挂钩的分配办法」。各地要「加大高级工以上评聘力度和批次」。符合条件的企业可以自己给职工做技能等级评价。对表现突出的职工，「可打破工作年限、等级、资历等条件，直接认定相应职业技能等级」', '这是政策方向，不是已经兑现的工资数，各地各企业的落地程度差别很大。能照着做的部分是：选技能时看它有没有对应的国家职业标准和等级通道，有通道的技能后面才谈得上按等级涨薪。没有等级、也没有行业准入门槛的「技能」，学完只能靠自己找活', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"23. 学什么技能划算","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-12', 'concept_archive_s23-12', 'claim_archive_s23-12', 'action', 'life_archive', '别把「网上说工资高」当成缺人，去查当地的紧缺职业目录和补贴目录', '23. 学什么技能划算', '各地给哪个工种的培训补贴多，是按急需紧缺程度和培训成本定的，所以补贴额度能看出当地缺不缺人。网上说的「某工种月入多少」，多半是招聘平台的挂牌价或个人自述。你看到的多是挣到钱的人，也没算工时、通勤、职业病和淡旺季。', '官方的分职业工资只分到五大类岗位，没有具体工种。国家统计局 2025 年的数字是，规模以上企业平均年工资约 10.6 万元（精确值 106080 元）。中层以上管理人员约 21 万元（精确值 210016 元），专业技术人员约 15.5 万元（精确值 155491 元），办事人员 94936 元，生产制造人员 80739 元，社会生产和生活服务人员 79857 元。人社部的「最缺工的 100 个职业排行」在中国就业网上能查，最新一期停在 2022 年第四季度，按全国 102 个城市公共就业服务机构的招聘和求职数据编。网上流传的「某工种月入多少」，几乎都来自招聘平台的挂牌价或者个人自述。能被你看到的，多半是挣到钱的那批人，而且都不算工时、通勤、职业病和淡旺季。要看真实需求，去当地人社局官网查补贴目录，再查公共就业服务机构的岗位需求排行。最后去实际的工地、工厂、门店问在职的人', NULL, NULL, NULL, '不花钱。查两份当地的文件。', '补贴额度本身就是官方对「哪些工种缺人」的定价。政策要求「健全根据职业（工种）急需紧缺程度、培训成本等情况确定的差异化补贴机制」，各地据此确定本地的补贴性职业技能培训项目范围。所以同一个工种在不同城市的补贴额度差多少，直接反映了当地的紧缺程度', '官方的分职业工资只分到五大类岗位，没有具体工种。国家统计局 2025 年的数字是，规模以上企业平均年工资约 10.6 万元（精确值 106080 元）。中层以上管理人员约 21 万元（精确值 210016 元），专业技术人员约 15.5 万元（精确值 155491 元），办事人员 94936 元，生产制造人员 80739 元，社会生产和生活服务人员 79857 元。人社部的「最缺工的 100 个职业排行」在中国就业网上能查，最新一期停在 2022 年第四季度，按全国 102 个城市公共就业服务机构的招聘和求职数据编。网上流传的「某工种月入多少」，几乎都来自招聘平台的挂牌价或者个人自述。能被你看到的，多半是挣到钱的那批人，而且都不算工时、通勤、职业病和淡旺季。要看真实需求，去当地人社局官网查补贴目录，再查公共就业服务机构的岗位需求排行。最后去实际的工地、工厂、门店问在职的人', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"23. 学什么技能划算","C 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-13', 'concept_archive_s23-13', 'claim_archive_s23-13', 'action', 'life_archive', '同样的钱和时间，优先选能直接上岗的短周期项目', '23. 学什么技能划算', '政策鼓励的是能短期就业的「短平快」培训，还有职业院校的微专业。挑项目只看一条：学完有没有一个具体岗位能投简历。学一年半载、结业还要「再积累经验」的，实际花掉的时间远超标价。开工前就写好退出条件：学到什么程度还没找到活就停。', '判断标准就一条：学完之后有没有一个具体的岗位能投简历。学一年半载、结业后还要「再积累经验」的项目，实际成本远高于标价。第 4 节讲的退出条件同样适用：开工前就写清楚「学到什么程度还没找到活就停」', NULL, NULL, NULL, '要交短期课程的学费，钱不多。时间上要占一段。难在学到一半还没见效时，按说好的条件停下来。', '政策口径与此一致：支持「民办培训机构开展市场化的高质量职业技能培训项目和能短期实现就业的『短平快』式职业技能培训项目」。同时推动职业院校「聚焦就业市场急需知识和技能……开设微专业和职业能力培训课程」', '判断标准就一条：学完之后有没有一个具体的岗位能投简历。学一年半载、结业后还要「再积累经验」的项目，实际成本远高于标价。第 4 节讲的退出条件同样适用：开工前就写清楚「学到什么程度还没找到活就停」', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"23. 学什么技能划算","C 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-14', 'concept_archive_s23-14', 'claim_archive_s23-14', 'action', 'life_archive', '学完先合上书自己考一遍，别回头重读', '23. 学什么技能划算', '读完再读一遍感觉很熟，其实记不牢。合上书考自己一遍，效果明显更好，课堂上加了小测验，成绩提高属于中等幅度。给十种常用学法排名时，自测排在最高一档。读完一节先默写要点，再翻回去对。', '自测是为了逼着把东西从脑子里调出来，不为打分。做法：读完一节合上书先默写要点，再翻回去对。有纠正性反馈的效果更好，所以对完答案要看清错在哪。收益量级记「大」，是按效应量和评级判的。这两份证据量的是成绩，没有量小时数，所以没按节省时间的阈值套。自测和第 15 条（把同样的时间摊到几天）是同一份综述里评级最高的两样，配合用。', NULL, NULL, NULL, '不花钱，总时间也不用增加。把原来用来重读的那段时间，改成合上书默写或者做题。难在自测当场就把没记住的暴露出来，感觉比重读难受。', '222 项独立研究、48478 名学生的荟萃分析：课堂测验让学生的学业成绩提高，效应量属于中等（g = 0.499）。效果大小受几个条件影响：对照组用的是什么学法、测验形式和最终考试是否一致、材料是否匹配、有没有给纠正性反馈、测验重复了几次、在哪里什么时候测、干预持续多久、用的是什么实验设计。另一份逐一评估十种常用学习方法的综述，把「练习性测验」和「分散练习」评为最高一档（high utility），理由是它们对不同年龄、不同能力的学习者都有效，在多种考核形式和真实教育场景里都被验证过。', '自测是为了逼着把东西从脑子里调出来，不为打分。做法：读完一节合上书先默写要点，再翻回去对。有纠正性反馈的效果更好，所以对完答案要看清错在哪。收益量级记「大」，是按效应量和评级判的。这两份证据量的是成绩，没有量小时数，所以没按节省时间的阈值套。自测和第 15 条（把同样的时间摊到几天）是同一份综述里评级最高的两样，配合用。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-15', 'concept_archive_s23-15', 'claim_archive_s23-15', 'action', 'life_archive', '把同样的时间摊到几天，别一次学完', '23. 学什么技能划算', '同样的时间，分几天学比一次学完记得牢。317 个实验都在测这件事，结论一致。还有一条实用规律：你要记到多久以后，复习间隔就该拉多长。明天考就当天复习，一个月后考就隔几天过一遍。', '和第 14 条（合上书自测）叠加用最好：把自测本身分散到几天做。Cepeda 那份荟萃分析里的材料多是词表记忆这类，复杂内容的最佳间隔没有给出通用天数。「考得越远、间隔越长」是原文给的规律，没有具体日程。考前一晚突击当场有用，问题是忘得快。', NULL, NULL, NULL, '不花钱，总时间也不变。变的只是排法：同样 3 小时，拆成三天各 1 小时。难在要提前几天开始，不能拖到最后一晚。', '一份汇总了 184 篇文章、317 个实验、839 次分散练习效果评估的荟萃分析。它比较了两件事：连着学完和分开几次学（间隔效应），以及间隔短和间隔长（延迟效应）。结论是复习间隔和「要记到多久之后」共同决定最终测验的保持率：要保持的时间越长，能带来最佳保持率的复习间隔也越长。另一份逐一评估十种常用学习方法的综述，把分散练习评为最高一档（high utility）。', '和第 14 条（合上书自测）叠加用最好：把自测本身分散到几天做。Cepeda 那份荟萃分析里的材料多是词表记忆这类，复杂内容的最佳间隔没有给出通用天数。「考得越远、间隔越长」是原文给的规律，没有具体日程。考前一晚突击当场有用，问题是忘得快。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-16', 'concept_archive_s23-16', 'claim_archive_s23-16', 'action', 'life_archive', '别把划重点、反复读、写摘要当成主要学法', '23. 学什么技能划算', '学生最常用的是划重点和反复读，可在十种常用学法的排名里，这两样都在最低一档。写摘要、关键词记忆法、给课文配图想象也在最低一档。它们不是完全没用，只是起作用的条件太窄，同样的时间换成自测更划算。', '划线可以用来「标出一会儿要自测哪几处」，出问题的是把划线本身当成学习。综述也说明，最低一档不等于零，只是能起作用的条件窄、还需要更多研究。替代动作见第 14 条（合上书自测）和第 15 条（把同样的时间摊到几天）。', NULL, NULL, NULL, '不花钱，反而省时间。难在这几样做起来最顺手，也最有「我在学习」的感觉。', '一份评估十种常用学习方法的综述，按「效果能不能跨学习条件、跨学生特征、跨材料、跨考核形式推广」给评级。评为最高一档的是练习性测验和分散练习。评为中等一档的是精细提问、自我解释、交错练习。评为最低一档的五种是：写摘要、划重点（或者画线）、关键词记忆法、为课文配图想象、反复阅读。综述写明：多数学生都说自己在用反复阅读和划重点，但这两种并不能稳定提高成绩，应当换成别的方法，比如用练习性测验代替反复阅读。', '划线可以用来「标出一会儿要自测哪几处」，出问题的是把划线本身当成学习。综述也说明，最低一档不等于零，只是能起作用的条件窄、还需要更多研究。替代动作见第 14 条（合上书自测）和第 15 条（把同样的时间摊到几天）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-17', 'concept_archive_s23-17', 'claim_archive_s23-17', 'action', 'life_archive', '几种题型混着练，别一种连做二十道', '23. 学什么技能划算', '同一类题连做一大串，当场做得很顺，过后不一定分得清该用哪个方法。把几类题打乱着练，长期效果更好，属于中等幅度。但这招挑材料：练图像、练分类最有效，数学题小一些，背单词反而不如分块练。', '第 16 条（别把划重点当主要学法）引的那份综述把交错练习评为中等一档，理由是当时研究还不够多。两份合起来看，用法是：需要「认出这是哪一类、该用哪个方法」的内容混着练，比如数学题型、病例、法条适用；需要死记的内容分块练，比如单词、名词解释。', NULL, NULL, NULL, '不花钱。把练习册按题型顺序做改成打乱着做。难在混着练当场正确率更低，感觉像退步。', '一份纳入 59 项研究、238 个效应量、158 个样本的多层荟萃分析。交错练习相对于分块练习的总体效应属于中等（Hedges'' g = 0.42）。按材料分：绘画类最好（g = 0.67），其他视觉材料也较好；数学任务的效应较小（g = 0.34）；说明性文本和味觉材料的总体效应不显著；词汇类反而是分块练习更好（g = −0.39）。回归分析显示：类别之间越相似、同一类别内部越不相似、材料越复杂，交错的好处越大。', '第 16 条（别把划重点当主要学法）引的那份综述把交错练习评为中等一档，理由是当时研究还不够多。两份合起来看，用法是：需要「认出这是哪一类、该用哪个方法」的内容混着练，比如数学题型、病例、法条适用；需要死记的内容分块练，比如单词、名词解释。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-18', 'concept_archive_s23-18', 'claim_archive_s23-18', 'action', 'life_archive', '别按「我是视觉型、他是听觉型」挑学法', '23. 学什么技能划算', '很多人相信每个人有自己的学习风格，比如视觉型、听觉型，按风格教才学得好。认真检验这件事的研究很少，几乎没有一项支持它，有几项的结果还正好相反。人确实各有偏好，但没有证据说按偏好上课就学得更好，不用花钱做风格测评。', '综述同时说明，这不等于所有版本的学习风格理论都被测过并被否定，很多根本没被测过。要避免的是花钱做风格测评、按风格挑培训班这两件事。挑培训的标准见第 9 条（培训优先走政府补贴渠道）和第 13 条（优先选能直接上岗的短周期项目）。', NULL, NULL, NULL, '不花钱。只是不再按这个分类挑材料、挑课程，也不再花钱做风格测评。', '一份受托评估学习风格证据的综述指出：要证明「按学习风格施教」有效，必须先按风格给学生分组，再把每组学生随机分配到不同教法，最后用同一份测验考。有效的判据是出现一种特定的交互作用：对一种风格最有效的教法，对另一种风格不是最有效的。综述的结论是：几乎没有发现这种交互作用；关于学习风格的文献虽然很多，但用了合格实验设计的研究极少，其中几项的结果还直接和「匹配假说」相反。作者据此认为，现有证据不足以支持把学习风格测评用进教育实践。', '综述同时说明，这不等于所有版本的学习风格理论都被测过并被否定，很多根本没被测过。要避免的是花钱做风格测评、按风格挑培训班这两件事。挑培训的标准见第 9 条（培训优先走政府补贴渠道）和第 13 条（优先选能直接上岗的短周期项目）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-19', 'concept_archive_s23-19', 'claim_archive_s23-19', 'action', 'life_archive', '要背的内容按将来的用法出题考自己，别原样背一遍就算完', '23. 学什么技能划算', '合上书考自己，好处不只停在背过的那几个字上。192 项对比、一万多人合起来算，它对换了题型的题、对应用题和推理题也管用，幅度中等偏小。但有两种情况几乎没用：把问法和答案对调，以及只在书上见过、从来没被考过的内容。', '「背」这个词平时把两件事混在一起：把材料再过一遍（反复读、划重点），和合上书主动回想。前一类在那份给十种学法排队的综述里评级最低，想看评级本身见第 16 条（别把划重点、反复读、写摘要当成主要学法）。要做的是后一类：合上书主动回想，具体见第 14 条（合上书自测），而且要分几天做，见第 15 条（摊到几天）。做法是先想清楚将来怎么用：是要在卷子上选出来，还是要在现场判断出来，然后照那个形式出题考自己。反过来对调着考一遍也值得做，因为这份荟萃分析里对调方向的迁移最弱，两个方向都得练到。', NULL, NULL, NULL, '不花钱，也不多花时间。变的只是练法：把「原样背一遍」换成「按将来的用法出题考自己」。难在得先想清楚这些东西将来要怎么用。', '一项荟萃分析汇总了 40 多年的研究，含 67 篇已发表和未发表的文章、122 个实验、192 个迁移效应量，总人数 10382 人。和「再看一遍但不考」的对照相比，练习性测验带来的学习确实能迁移到别的情境，效应量 d=0.40（95% CI 0.31 到 0.50）。迁移最强的几种情况是：换一种题型考、考应用题和推理题、医学诊断类的问题、考意思相近的线索词。迁移最弱的几种是：把刺激和反应对调、初学时见过但没被考过的材料、例题类问题。调节因素中，练时和考时的作答形式是否一致、有没有做过带详细反馈的提取练习、以及初次测验答对没有，都强烈影响会不会出现正向迁移。作者还用两种方法校正了发表偏倚，调节因素的效应量受影响很小，但截距估计被明显压低：上面这些条件一个都不具备时，常常看不到正向迁移', '「背」这个词平时把两件事混在一起：把材料再过一遍（反复读、划重点），和合上书主动回想。前一类在那份给十种学法排队的综述里评级最低，想看评级本身见第 16 条（别把划重点、反复读、写摘要当成主要学法）。要做的是后一类：合上书主动回想，具体见第 14 条（合上书自测），而且要分几天做，见第 15 条（摊到几天）。做法是先想清楚将来怎么用：是要在卷子上选出来，还是要在现场判断出来，然后照那个形式出题考自己。反过来对调着考一遍也值得做，因为这份荟萃分析里对调方向的迁移最弱，两个方向都得练到。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-20', 'concept_archive_s23-20', 'claim_archive_s23-20', 'action', 'life_archive', '评职称先弄清自己在哪个系列、哪一级，再按单位性质找申报渠道', '23. 学什么技能划算', '职称全国分 27 个系列，每个系列分初级、中级、高级。一般要一级一级往上报。在单位上班的，由单位审核、公示后往上报。在民营企业的，可以去职称申报受理服务点，或者找人才中介服务机构、行业协会申报。自由职业者报当地人社部门组织的评审。', '要准备哪些材料，全国没有统一清单。各系列、各省每年发申报通知，材料清单、申报时间和业绩条件都写在里面。所以第一步是在本省人社厅官网找当年的通知。论文不再是一律要有：2016 年的改革意见要求，不把论文当应用型人才的硬门槛，职称外语和计算机考试也不作统一要求。技术工人也有路：符合条件的高技能人才，可以参加工程系列的职称评审。公务员不能参加职称评审。', NULL, NULL, NULL, '不花钱。查一次本省当年的申报通知，半小时左右。', '全国共设 27 个职称系列，比如经济、工程、卫生、出版。职称分高级、中级、初级三层。人社部令第 40 号适用于企业、事业单位、社会团体、个体经济组织，也适用于自由职业者。申报人一般要逐级申报。你所在单位要审核材料，并在单位内公示，公示期不少于 5 个工作日。民营企业和自由职业者，可以由人事代理机构等替你审核、公示、推荐。各地要在科技园区、高新区等地设职称申报受理服务点，也可以通过人才中介服务机构、行业协会商会、学会受理申报。符合条件的自由职业者，按属地参加当地人社部门组织的评审。能在网上核验的材料，不得要求你另外开证明。材料不齐的，评审方要一次性告诉你缺哪些。民营企业的人一般在劳动关系所在地申报。被派到外地连续干满一年的，可以在派驻地申报。离退休人员不能申报。事业单位工作人员受记过以上处分的，处分期间不能申报（全国）', '要准备哪些材料，全国没有统一清单。各系列、各省每年发申报通知，材料清单、申报时间和业绩条件都写在里面。所以第一步是在本省人社厅官网找当年的通知。论文不再是一律要有：2016 年的改革意见要求，不把论文当应用型人才的硬门槛，职称外语和计算机考试也不作统一要求。技术工人也有路：符合条件的高技能人才，可以参加工程系列的职称评审。公务员不能参加职称评审。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-21', 'concept_archive_s23-21', 'claim_archive_s23-21', 'action', 'life_archive', '会计这类初级、中级职称靠全国统考拿，先对照学历和工作年限去报名', '23. 学什么技能划算', '有些系列的初级、中级职称是考出来的，考过就算，不再另外评审。会计就是这样：助理会计师要高中以上学历，会计师要本科干满 4 年会计、大专满 5 年。已经拿到某些职业资格的，也可能直接算作有相应职称。', '你的系列是考、是评，还是考评结合，看该系列那份「深化××职称制度改革的指导意见」。人社部和各行业主管部门分系列发过，在中国政府网政策文件库能搜到。考试的报名时间和科目，以当年的考试公告为准。公务员可以参加会计考试，但不能参加会计职称评审。', NULL, NULL, NULL, '报名费按各省标准交。备考要占几个月的业余时间。', '2016 年的改革意见规定，初级、中级职称实行全国统一考试的专业，不再进行相应的评审或认定。在职称和职业资格密切相关的领域，取得职业资格就可以认定具备相应职称，还可以作为申报高一级的条件。以会计为例。助理会计师和会计师实行全国统一考试。高级会计师考试和评审结合，正高级一般只评审。报考条件如下。助理会计师：高中毕业以上学历，含中专、职高、技校。会计师：博士学位；或硕士学位、干会计满 1 年；或第二学士学位、研究生班毕业、干满 2 年；或本科、干满 4 年；或大专、干满 5 年。有会计硕士、会计博士专业学位的，考会计师可以免考《财务管理》（全国）', '你的系列是考、是评，还是考评结合，看该系列那份「深化××职称制度改革的指导意见」。人社部和各行业主管部门分系列发过，在中国政府网政策文件库能搜到。考试的报名时间和科目，以当年的考试公告为准。公务员可以参加会计考试，但不能参加会计职称评审。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 一般","口径 时间","钱 少","时间 中","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-22', 'concept_archive_s23-22', 'claim_archive_s23-22', 'action', 'life_archive', '别找中介代评、别买论文代写、别在材料上造假：查实就撤销职称，记诚信档案 3 年', '23. 学什么技能划算', '用假材料、代写论文、剽窃成果拿到的职称，查实就撤销。失信记录要记 3 年，还进全国信用平台。申报时签的承诺书不实，3 年内不能再申报。人社部门还专门查处中介的虚假宣传、假冒评审和假证。', '辨真假有个办法：正规评审出来的职称，能在全国职称评审信息查询平台查到。入口是 12333 网站、12333 手机客户端和人社部官网。没经过备案的评审委员会评出来的，这个系统里查不到。所以承诺「包过」「不用本人参加」「证书查不到也能用」的，基本可以判定有问题。受益人主要是自己，收益量级按「避免撤销职称和 3 年失信记录」判。', NULL, NULL, NULL, '不花钱。难在忍住「花钱包过」的广告。', '人社部令第 40 号规定，提供虚假材料、剽窃他人作品和学术成果，或者用其他不正当手段取得职称的，撤销职称。同时记入职称评审诚信档案库，纳入全国信用信息共享平台，记录期限 3 年。2024 年的监管办法点名了申报人的几类违规：虚假承诺和伪造信息，论文造假代写，业绩造假，说情打招呼。申报时要签个人承诺书，承诺不实的，3 年内不得申报。人社部门会同公安、网信、市场监管查处中介的虚假网站、虚假宣传、合同陷阱、假冒评审和假证。情节严重涉嫌犯罪的，移送有关机关处理（全国）', '辨真假有个办法：正规评审出来的职称，能在全国职称评审信息查询平台查到。入口是 12333 网站、12333 手机客户端和人社部官网。没经过备案的评审委员会评出来的，这个系统里查不到。所以承诺「包过」「不用本人参加」「证书查不到也能用」的，基本可以判定有问题。受益人主要是自己，收益量级按「避免撤销职称和 3 年失信记录」判。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"23. 学什么技能划算","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s23-23', 'concept_archive_s23-23', 'claim_archive_s23-23', 'action', 'life_archive', '拿到职称不等于涨工资：先问清单位是按岗位比例评聘，还是评了不一定聘', '23. 学什么技能划算', '职称是聘用、考核、晋升的依据，但评上和聘上是两回事。事业单位一般在岗位比例内评，评上多半能聘。不实行岗位管理的单位可以评聘分开，评上了单位不一定给对应的岗位和工资。换单位、换地方后，职称可能要重新评或者确认。', '证据等级定 B，是因为文件只写了评聘怎么衔接，没有全国统一的「评上涨多少」的数字。能照着做的是：在事业单位和国企，先问人事部门本单位的岗位空缺和聘任规则。在私企，先问老板这张证认不认、加不加钱。', NULL, NULL, NULL, '不花钱。问一次单位人事部门就行。', '人社部令第 40 号第二条：职称评审结果是专业技术人才聘用、考核、晋升等的重要依据。2016 年的改革意见规定，全面实行岗位管理的事业单位，一般在岗位结构比例内开展职称评审。不实行岗位管理的单位，以及通用性强的系列和新兴职业，可以评聘分开。专业技术人才跨地区、跨单位流动时，职称按管理权限重新评审或者确认，国家另有规定的除外（全国）', '证据等级定 B，是因为文件只写了评聘怎么衔接，没有全国统一的「评上涨多少」的数字。能照着做的是：在事业单位和国企，先问人事部门本单位的岗位空缺和聘任规则。在私企，先问老板这张证认不认、加不加钱。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"23. 学什么技能划算","B 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-1', 'concept_archive_s24-1', 'claim_archive_s24-1', 'action', 'life_archive', '常见病先在社区看，经基层逐级转诊上去，住院起付线接着算', '24. 看病：怎么少花钱少走弯路', '先去社区，再由社区转到大医院住院，自己先掏的那一段钱只算一次。自己直接跑去三级医院住院、之后再转回社区康复，这段钱可能要掏两回。由大医院转回社区接着住的，同一个病这段时间里也不再重算一次。', '自己直接跑去三级医院住院，再转回基层康复，这段钱可能要掏两次，走转诊只算一次。转诊规则由各省、各市和医联体分别制定，去之前先问一下社区。稳定期的慢病别再去大医院开药：大医院的这类普通门诊会逐步减掉，社区一次能开 12 周的药，见第 16 节第 5 条（社区一次开到 12 周的药）。', NULL, NULL, NULL, '不花钱。要先去一趟社区。难在忍住不直接去挂专家号。', '经基层逐级转诊的参保患者，在上级医院的住院起付线可以连续计算。起付线就是每次住院自己先掏、掏够了医保才开始报的那一段。连续计算的意思是前后两家医院合起来只算一次，不用重新掏一遍。由上级医院下转回基层的住院患者，同一疾病周期内不再另设起付线', '自己直接跑去三级医院住院，再转回基层康复，这段钱可能要掏两次，走转诊只算一次。转诊规则由各省、各市和医联体分别制定，去之前先问一下社区。稳定期的慢病别再去大医院开药：大医院的这类普通门诊会逐步减掉，社区一次能开 12 周的药，见第 16 节第 5 条（社区一次开到 12 周的药）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-2', 'concept_archive_s24-2', 'claim_archive_s24-2', 'action', 'life_archive', '同一个统筹地区（医保参保地）里，级别越低报销比例越高，差距约 10 个百分点', '24. 看病：怎么少花钱少走弯路', '同一笔住院费，医院级别越低，报销报得越多。各地要把档次拉开，每往上一级差十个百分点左右。比如 1 万元住院费，报销从八成降到七成，自己掏的就从 2000 元变成 3000 元。新增的医保基金也往基层倾斜。', '同一笔住院费，在基层和在三级医院，自己掏的差额可能是几千元。能在基层办完的病别往上跑，并不是什么病都要在社区看。', NULL, NULL, NULL, '不花钱。难在忍住不往大医院跑。', '文件要求各地拉开不同等级医疗机构的住院报销水平，原则上逐级差 10 个百分点左右。按这个差距，同一笔住院费每往上跑一级医院，自己多掏的大约是这笔可报销费用的 10%。比如 1 万元可报销的住院费，报销比例从 80% 降到 70%，自己掏的从 2000 元变成 3000 元。多掏的 1000 元是总费用的一成，但比原来自己掏的多了一半。各地实际比例不同，起付线和封顶线也会让差额变化，这里只是按文件的 10 个百分点算的示意。年度新增医保基金也向基层倾斜', '同一笔住院费，在基层和在三级医院，自己掏的差额可能是几千元。能在基层办完的病别往上跑，并不是什么病都要在社区看。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-3', 'concept_archive_s24-3', 'claim_archive_s24-3', 'action', 'life_archive', '要去大医院，走基层转诊或者医院的转诊中心，别找号贩子', '24. 看病：怎么少花钱少走弯路', '大医院要留出一部分号和床位，专门给从基层转来的人。医院还要设转诊中心，或者指定一个固定部门专管转诊，2027 年全覆盖。挂不到号不等于没有路。号贩子的号除了贵，还可能把你送进不对口的科室。', '预留号源是专门留给转诊患者的，抢不到号可以走转诊。找号贩子除了贵，还可能让你落到不对口的科室。找不到转诊中心，就打医院的服务电话问。', NULL, NULL, NULL, '不花钱。要多办一道转诊手续。', '紧密型医联体的牵头医院，要为基层预留一定比例的号源和床位，并及时接诊经基层转诊的患者。紧密型医联体就是几家医院和社区卫生机构绑在一起协作的一组机构。所以从社区转上去有单独的号和床，不和大厅里抢号的人挤在一起。医疗机构要设转诊中心或指定固定部门，到 2027 年实现全覆盖', '预留号源是专门留给转诊患者的，抢不到号可以走转诊。找号贩子除了贵，还可能让你落到不对口的科室。找不到转诊中心，就打医院的服务电话问。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-4', 'concept_archive_s24-4', 'claim_archive_s24-4', 'action', 'life_archive', '跨省异地就医之前先在本地问一句，必要性原则上要副主任医师以上评估', '24. 看病：怎么少花钱少走弯路', '要不要去外地看病，原则上由二、三级医院副主任医师以上的医生评估。临时外出就医报销多少，和在参保地同级别医院会有差别，具体看本地规定。出发前在本地问一句，比人到了外地才发现报不了强。', '「临时外出就医」和「长期异地居住」是两种不同的备案，报销水平不一样。备案怎么办、哪几类病能直接结算，见第 16 节。别先跑到外地，再回头想报销的事。', NULL, NULL, NULL, '不花钱。出发前多问一句。', '跨统筹地区、跨省异地就医的必要性，原则上由二、三级医院副主任医师及以上职称人员评估。跨统筹地区就是跨出自己的医保参保地。去不去外地看，要由够级别的医生说了算。跨省临时外出就医人员的报销水平，与参保地同级别机构保持合理差异。在外地看同样的病，报回来的钱会比在家少一截', '「临时外出就医」和「长期异地居住」是两种不同的备案，报销水平不一样。备案怎么办、哪几类病能直接结算，见第 16 节。别先跑到外地，再回头想报销的事。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-5', 'concept_archive_s24-5', 'claim_archive_s24-5', 'action', 'life_archive', '每次看完病，把病历、检查报告和影像自己存一份', '24. 看病：怎么少花钱少走弯路', '查阅和复制自己的病历，是法律给你的权利。门诊病历、住院志、化验单、影像、手术和麻醉记录、病理资料、费用清单都能复制。医院有专门窗口受理，只能收工本费。换医院、找别的医生再看一遍、报商业保险、真起了纠纷，凭的都是这一摞材料。', '复印有专门窗口，不用去求医生。要复印的清单，直接照《医疗纠纷预防和处理条例》第十六条念。先是门诊病历、住院志、体温单、医嘱单、化验单、影像资料。再是手术和麻醉记录、病理资料、护理记录、医疗费用清单。拿到之后按时间顺序存一个文件夹。里面最要紧的是出院小结、手术记录、病理报告和关键影像。慢性病的历次指标记在同一个本子上，见第 16 节。', NULL, NULL, NULL, '不花钱。医院复印可以按规定收工本费，收费标准要公开。难在每次看完病都记得去复印一份。', '法规明确把查阅、复制病历列为患者的权利。范围覆盖门诊病历、住院志、化验单、医学影像、手术及麻醉记录、病理资料、医疗费用等全部资料。换医院、找第二个医生再看一遍、报商业保险、真起了纠纷，靠的都是这些', '复印有专门窗口，不用去求医生。要复印的清单，直接照《医疗纠纷预防和处理条例》第十六条念。先是门诊病历、住院志、体温单、医嘱单、化验单、影像资料。再是手术和麻醉记录、病理资料、护理记录、医疗费用清单。拿到之后按时间顺序存一个文件夹。里面最要紧的是出院小结、手术记录、病理报告和关键影像。慢性病的历次指标记在同一个本子上，见第 16 节。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-6', 'concept_archive_s24-6', 'claim_archive_s24-6', 'action', 'life_archive', '对诊疗有疑问就当场要求封存病历，双方在场、开清单、各执一份', '24. 看病：怎么少花钱少走弯路', '对治疗有疑问，可以要求把病历封存起来。封存要医患双方都在场，开清单、签字盖章、各拿一份。病历还没写完的，先封已经写完的那部分。怀疑是输液、输血、打针、用药出的问题，那袋液体、那支药和输液器要一起封存。', '封存和复印是两件事。复印是平时就该做的，见第 5 条（病历和影像自己存一份）。封存是纠纷发生时把证据固定住，防的是事后补写和修改。怀疑是输液、输血、用药出的问题，除了病历，还要一起封存那袋液体、那支药和输液器，别让人收走扔掉。医疗机构应当在显著位置公布医疗纠纷的解决途径、程序和联系方式，并设置统一的投诉管理部门。有事先找那个部门，不要找当班医生理论。', NULL, NULL, NULL, '不花钱。向医院提出封存要求，等医患双方到场把手续做完。难在当着医生的面把这句话说出口。', '条例规定「发生医疗纠纷需要封存、启封病历资料的，应当在医患双方在场的情况下进行」。封存的可以是原件，也可以是复制件，由医疗机构保管。病历尚未完成需要封存的，对已完成部分先行封存，后续完成后再封存。医疗机构应当对封存的病历开列封存清单，由医患双方签字或者盖章，各执一份。疑似输液、输血、注射、用药等引起不良后果的，医患双方应当共同对现场实物进行封存、启封。需要检验的，应当由双方共同委托有检验资格的机构。双方无法共同委托的，由医疗机构所在地县级人民政府卫生主管部门指定。疑似输血引起不良后果、需要封存血液的，医疗机构应当通知血站派员到场。另有一条硬约束：「任何单位和个人不得篡改、伪造、隐匿、毁灭或者抢夺病历资料。」封存后纠纷已解决，或者满 3 年未再提出解决要求的，医疗机构可以自行启封（全国，2018 年 10 月 1 日起施行）', '封存和复印是两件事。复印是平时就该做的，见第 5 条（病历和影像自己存一份）。封存是纠纷发生时把证据固定住，防的是事后补写和修改。怀疑是输液、输血、用药出的问题，除了病历，还要一起封存那袋液体、那支药和输液器，别让人收走扔掉。医疗机构应当在显著位置公布医疗纠纷的解决途径、程序和联系方式，并设置统一的投诉管理部门。有事先找那个部门，不要找当班医生理论。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-7', 'concept_archive_s24-7', 'claim_archive_s24-7', 'action', 'life_archive', '急重的伤病直奔急诊预检分诊台，别去挂号窗口排队', '24. 看病：怎么少花钱少走弯路', '急诊不按先来后到，按病情轻重分四级排。定级的地方是急诊入口的预检分诊台，不是挂号窗口。不去分诊，你在系统里就没有级别，伤得再重也只能跟着队伍慢慢挪。到了先报最危险的那一条：大出血、喘不上气、意识不清、身上扎着东西、胸口压着疼。', '分成四级是全国统一的。每一级多久得到处理，由各省市自己定，北京这份是能逐字核对的一版。定级看的是心跳、血压、血氧这些指标和症状，不是你觉得有多疼。1 级的硬指标包括这么几条。一是心率大于 180 次/分，或者小于 40 次/分。二是收缩压低于 70 mmHg，收缩压就是血压里的高压。三是血氧低于 80%。四是休克、明确心肌梗死、急性意识障碍。觉得分诊把你定低了，就补充说清最危险的那个症状。候诊中病情有变化，立刻回分诊台重新评一次。真正危重的时候打 120 比自己去更快，院前医生会按同一套标准先定一个级，并提前通知医院准备接诊（见第 13 节）。', NULL, NULL, NULL, '不花钱。进门多走几步找到预检分诊台。把最要命的那个症状，用一句话说清。', '国家卫生健康委 2024 年版急诊医学质控指标规定，急诊预检分诊要「按病情危重程度将患者分为四级」。「I 级为急危患者，需要立即得到救治」。「II 级为急重患者，往往评估与救治同时进行」。「III 级为急症患者，需要短时间内得到诊治」。「IV 级为非急症患者或亚急症患者，在普通诊疗区顺序就诊」。预检分诊就是进急诊先由专人评一遍病情轻重，定下看病顺序。北京市的执行标准给出了各级的响应要求。1 级「立即进行评估和救治，安排患者进入复苏室或抢救室」。2 级「立即监护生命体征，10 分钟内得到救治，安排患者进入抢救室」。3 级「先于 4 级患者优先诊治，安排患者在普通诊疗区候诊；若候诊时间大于 30 分钟，需再次评估」。4 级「顺序就诊，除非病情变化，否则候诊时间较长；若候诊时间大于 4 小时，可再次评估」。分诊要「坚持急危重症优先就诊原则」，急诊科入口显著位置应设预检分诊区域（四级标准为全国口径，响应时间为北京市标准）', '分成四级是全国统一的。每一级多久得到处理，由各省市自己定，北京这份是能逐字核对的一版。定级看的是心跳、血压、血氧这些指标和症状，不是你觉得有多疼。1 级的硬指标包括这么几条。一是心率大于 180 次/分，或者小于 40 次/分。二是收缩压低于 70 mmHg，收缩压就是血压里的高压。三是血氧低于 80%。四是休克、明确心肌梗死、急性意识障碍。觉得分诊把你定低了，就补充说清最危险的那个症状。候诊中病情有变化，立刻回分诊台重新评一次。真正危重的时候打 120 比自己去更快，院前医生会按同一套标准先定一个级，并提前通知医院准备接诊（见第 13 节）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-8', 'concept_archive_s24-8', 'claim_archive_s24-8', 'action', 'life_archive', '没带钱、没带证件、说不清自己是谁，急诊也必须先救', '24. 看病：怎么少花钱少走弯路', '国家有一笔疾病应急救助基金，专付两种人的急救费：身份查不出来的，和掏不出钱的。医院不能拒绝或拖延抢救，急救中心也不能因为钱的问题不出车。所以别因为没钱在家硬扛，也别怕欠费不叫救护车。这笔钱只管急救，后面住院还是走医保和医疗救助。', '基金只付「急救费用」那一段，而且是先救治，事后由医疗机构向基金申请，不用你去窗口领钱。有医保的照常先走医保。各省的申请流程和限额不同。转运原则里「就近、就急」排在「患者意愿」前面，所以救护车不一定送你指定的那家医院，危重时以最近能处理的为准。后续自己掏的部分仍然过重的，走医疗救助，见第 7 节第 10 条（医疗救助）。', NULL, NULL, NULL, '不花钱。', '疾病应急救助制度的救助对象是「在中国境内发生急重危伤病、需要急救但身份不明确或无力支付相应费用的患者」。基金支付两类费用：「无法查明身份患者所发生的急救费用」，和「身份明确但无力缴费的患者所拖欠的急救费用」。文件还写明「各级各类医疗机构及其工作人员必须及时、有效地对急重危伤患者施救，不得以任何理由拒绝、推诿或拖延救治」。院前急救也有规定：全国院前医疗急救呼叫号码为「120」。急救中心（站）「不得因指挥调度原因拒绝、推诿或者延误院前医疗急救服务」，也「不得因费用问题拒绝或者延误院前医疗急救服务」。转运遵循「就近、就急、满足专业需要、兼顾患者意愿的原则」（全国，2013 年起）', '基金只付「急救费用」那一段，而且是先救治，事后由医疗机构向基金申请，不用你去窗口领钱。有医保的照常先走医保。各省的申请流程和限额不同。转运原则里「就近、就急」排在「患者意愿」前面，所以救护车不一定送你指定的那家医院，危重时以最近能处理的为准。后续自己掏的部分仍然过重的，走医疗救助，见第 7 节第 10 条（医疗救助）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-9', 'concept_archive_s24-9', 'claim_archive_s24-9', 'action', 'life_archive', '伤残鉴定要等治疗终结之后再做，做早了等级会评低', '24. 看病：怎么少花钱少走弯路', '赔多少钱主要看评几级，评几级看的是治完之后还剩多少功能障碍。标准写明要在治疗终结、或者临床治疗效果稳定之后再做。骨头还没长好、钢板还没取就跑去评，评的是当时那个样子，等于自己把等级压低。长好了不影响功能的普通骨折，评不上。', '三套评残不通用，别搞混。被人打伤、交通事故和其他人身损害，走司法鉴定的《人体损伤致残程度分级》，用来算残疾赔偿金（见第 9 节）。工伤走劳动能力鉴定，用的是另一套十个伤残等级，管的是工伤待遇（见第 19 节）。想享受残疾人的政策待遇，要另外办残疾人证（见第 10 条，残疾人证）。鉴定前把病历、手术记录、复查影像备齐（见第 5 条，病历和影像自己存一份），缺影像是等级被压低最常见的原因。这次受伤和本来就有的老毛病混在一起时，鉴定意见还要写明这次受伤在残疾后果里占多大分量。这一栏直接影响赔多少钱。', NULL, NULL, NULL, '鉴定费几百到两千元不等，一般由提出申请的一方先垫。要等治疗终结，或者临床效果稳定，通常是伤后三到六个月，有时更久。难在伤还没好利索就想赶紧定下来，得忍住。', '《人体损伤致残程度分级》规定鉴定时机「应在原发性损伤及其与之确有关联的并发症治疗终结或者临床治疗效果稳定后进行鉴定」。标准「将人体损伤致残程度划分为 10 个等级，从一级（人体致残率 100%）到十级（人体致残率 10%），每级致残率相差 10%」。判断依据是「人体组织器官结构破坏、功能障碍及其对医疗、护理的依赖程度，适当考虑由于残疾引起的社会交往和心理因素影响」。十级里与骨折有关的条款包括这么几条。一是「一椎体压缩性骨折（压缩程度达 1/3）或者粉碎性骨折」。二是「骨盆两处以上骨折或者粉碎性骨折，畸形愈合」。三是「四肢任一大关节（踝关节除外）功能丧失 25% 以上」。同一部位和性质的残疾不得重复计算。两处以上致残的，应分别写明等级（全国，2017 年 1 月 1 日起施行）', '三套评残不通用，别搞混。被人打伤、交通事故和其他人身损害，走司法鉴定的《人体损伤致残程度分级》，用来算残疾赔偿金（见第 9 节）。工伤走劳动能力鉴定，用的是另一套十个伤残等级，管的是工伤待遇（见第 19 节）。想享受残疾人的政策待遇，要另外办残疾人证（见第 10 条，残疾人证）。鉴定前把病历、手术记录、复查影像备齐（见第 5 条，病历和影像自己存一份），缺影像是等级被压低最常见的原因。这次受伤和本来就有的老毛病混在一起时，鉴定意见还要写明这次受伤在残疾后果里占多大分量。这一栏直接影响赔多少钱。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-10', 'concept_archive_s24-10', 'claim_archive_s24-10', 'action', 'life_archive', '治完之后确实留下功能障碍，去户籍地县级残联申请残疾人证', '24. 看病：怎么少花钱少走弯路', '残疾人证是领残疾人待遇的门槛，不是伤情证明。分视力、听力、言语、肢体、智力、精神和多重七类，每类一到四级。流程是申请、受理、到指定机构评定、公示、审核批准、发证，有效期十年、到期免费换。评不上就是评不上，这不是找熟人能办下来的东西。', '办不办先算账。证本身不直接发钱。它接上的是残疾人两项补贴：低保家庭中的残疾人领生活补贴，一级二级且需长期照护的领护理补贴，见第 7 节第 8 条（两项补贴）。证还接上各地的康复、辅助器具、税费、就业和交通优惠。这些标准各省差别很大，先在当地残联官网查清楚，再决定跑不跑这一趟。它和司法鉴定的伤残等级、工伤的劳动能力鉴定是三套东西，互不替代（见第 9 条，伤残鉴定要等治疗终结之后再做）。证只限本人使用，不得转借。残疾状况不再符合标准的会被注销，注销后一年内不得重新申请。多重残疾按其中最重的一类定等级。', NULL, NULL, NULL, '证本身不收工本费。评定费和照片费原则上自己出，困难的可以申请减免。带身份证、户口本和 3 张两寸白底照片到户籍地县级残联。评定合格后在村（社区）公示 5 个工作日，残联 10 个工作日内审核完毕。难在要跑这几趟、等这段时间。', '残疾人证「是认定残疾人及其残疾类别、残疾等级的合法凭证，是残疾人依法享有国家和地方政府优惠政策的重要依据」。评定标准是国家标准《残疾人残疾分类和分级》（GB/T 26341-2010）。办证坚持申领自愿、属地管理。视力、听力、言语、肢体、智力、精神及多重七类残疾人均可申领，残疾等级为一至四级。县级残联负责申办受理与核发，依据省级指定的医院或专业机构作出的评定结论。评定结论符合标准的，在村（社区）公示五个工作日，县级残联「在十个工作日内审核完毕」。「办理残疾人证不收取工本费」。评定与照片费用「原则上由申请人个人自理；有条件的地方可由当地财政予以补贴，对特殊困难的申请人应协调有关部门予以减免」。证的有效期十年，期满免费换领。残疾类别或等级发生变化的，可申请重新评定。对评定结论有异议的，可在十个工作日内到地市级残联申请重新评定。仍有异议的，由省级残疾评定专家委员会作出最终结论（全国，2018 年 1 月 1 日起施行）', '办不办先算账。证本身不直接发钱。它接上的是残疾人两项补贴：低保家庭中的残疾人领生活补贴，一级二级且需长期照护的领护理补贴，见第 7 节第 8 条（两项补贴）。证还接上各地的康复、辅助器具、税费、就业和交通优惠。这些标准各省差别很大，先在当地残联官网查清楚，再决定跑不跑这一趟。它和司法鉴定的伤残等级、工伤的劳动能力鉴定是三套东西，互不替代（见第 9 条，伤残鉴定要等治疗终结之后再做）。证只限本人使用，不得转借。残疾状况不再符合标准的会被注销，注销后一年内不得重新申请。多重残疾按其中最重的一类定等级。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-11', 'concept_archive_s24-11', 'claim_archive_s24-11', 'action', 'life_archive', '谢救过你的医生，走感谢信、锦旗和满意度评价，别走红包：准则禁的是财物，不是谢意', '24. 看病：怎么少花钱少走弯路', '事先塞钱买不到优先，号源、床位、紧缺药品和手术安排都禁止拿来换好处。事后想谢救你命的医生，可以谢，但别送烟酒红包，他收了就是违规。能真正落到他身上的谢法有三种：认真填一次满意度评价，写一封点名的感谢信或送面锦旗，按医嘱复查。', '受益人是你自己，也是救了你的那个人。通宵抢救之后想谢是人之常情，可以谢，要改的只是形式。红包和烟酒把风险转给了对方，感谢信、锦旗和满意度评价是制度里认可的方式。已经送出去、对方推回来的，别当成嫌少或者摆架子，那是他按规定必须做的。另外分清楚两件事：送医生红包归行业纪律和医院管，送办案、执法人员财物是刑法上的行贿罪，两件事不是一个量级，后者见第 8 节第 40 条。写感谢信、送锦旗医院普遍接受，但「会进个人和科室记录」是经验之谈，没有文件规定。有文件依据的是满意度调查结果纳入三级公立医院绩效考核这一条。对诊疗本身有疑问，就当场要求封存病历（见本节第 6 条，封存病历），并留存病历与影像（第 5 条，病历和影像自己存一份）', NULL, NULL, NULL, '不花钱。写一封感谢信，或者在满意度平台上填一次，十几分钟。', '《医疗机构工作人员廉洁从业九项准则》（国卫医发〔2021〕41 号）第七项：「维护诊疗秩序，不破坏就医公平。坚持平等原则，共建公平就医环境。严禁利用号源、床源、紧缺药品耗材等医疗资源或者检查、手术等诊疗安排收受好处、损公肥私」。第八项：「共建和谐关系，不收受患方『红包』。恪守医德、严格自律」。同一项还写明「严禁索取或者收受患者及其亲友的礼品、礼金、消费卡和有价证券、股权、其他金融产品等财物」。患方出钱的饭局和娱乐也一样：「严禁参加其安排、组织或者支付费用的宴请或者旅游、健身、娱乐等活动安排」。文件同时要求医疗机构落实主体责任、开展督查、「坚决查处违规行为」。满意度评价被写进了三级公立医院的绩效考核。依据是《国务院办公厅关于加强三级公立医院绩效考核工作的意见》（国办发〔2019〕4 号）。文件说：「三级公立医院绩效考核指标体系由医疗质量、运营效率、持续发展、满意度评价等 4 个方面的指标构成」。文件还写明：「医院满意度由患者满意度和医务人员满意度两部分组成……」。后面接着说，要「通过门诊患者、住院患者和医务人员满意度评价，衡量患者获得感及医务人员积极性」。这套评价还有全国统一的平台：「国家建立公立医院满意度管理制度……」。时间表是：「2019 年 3 月底前，全国三级公立医院全部纳入国家卫生健康委满意度调查平台。各地要应用国家卫生健康委满意度调查平台，将调查结果纳入三级公立医院绩效考核」。医院还必须管投诉。依据是《医疗机构投诉管理办法》（国家卫生健康委令第 3 号，2019 年施行）第二条。投诉管理是指患者就医疗服务行为、医疗管理、医疗质量安全等方面「提出意见、建议或者投诉请求」。医院要负责调查、处理和反馈。「二级以上医疗机构应当设置医患关系办公室或者指定部门（以下统称投诉管理部门）统一承担投诉管理工作」。投诉管理部门的职责包括「统一受理投诉，调查、核实投诉事项，提出处理意见，及时答复患者」。医疗机构「应当鼓励工作人员主动收集患者对医疗服务、医疗质量安全等方面的意见和建议」（全国）', '受益人是你自己，也是救了你的那个人。通宵抢救之后想谢是人之常情，可以谢，要改的只是形式。红包和烟酒把风险转给了对方，感谢信、锦旗和满意度评价是制度里认可的方式。已经送出去、对方推回来的，别当成嫌少或者摆架子，那是他按规定必须做的。另外分清楚两件事：送医生红包归行业纪律和医院管，送办案、执法人员财物是刑法上的行贿罪，两件事不是一个量级，后者见第 8 节第 40 条。写感谢信、送锦旗医院普遍接受，但「会进个人和科室记录」是经验之谈，没有文件规定。有文件依据的是满意度调查结果纳入三级公立医院绩效考核这一条。对诊疗本身有疑问，就当场要求封存病历（见本节第 6 条，封存病历），并留存病历与影像（第 5 条，病历和影像自己存一份）', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s24-12', 'concept_archive_s24-12', 'claim_archive_s24-12', 'action', 'life_archive', '种牙之前先问清包干价含哪些项目，优先找承诺参与价格治理的机构，别信低价广告', '24. 看病：怎么少花钱少走弯路', '种植牙 2023 年集中降价以后，一颗常规种植牙的整体费用从平均 1.5 万元降到 6000 到 7000 元。三级公立医院单颗的服务费原则上不超过 4500 元，种植体和牙冠另算。种牙、镶牙、正畸医保不报，补牙、拔牙这类治疗各地普遍能报。', '4500 元这条线只管公立医院。民营机构自己定价，但专项治理通知要求它们不得用虚假的或误导性的「补贴」「低价」诱导患者。广告上的低价往往只是种植体一项，拔牙、植骨这些包干之外的项目才是加价的地方，所以签字前要拿到一份写清每项价格的单子。承诺参与价格治理的机构名单由国家医保局在官方微信公众号上公布。缺一两颗牙不一定非种不可，固定义齿和活动义齿也是修复方式，价格没有跟着变，问医生哪种适合你。职工医保个人账户能不能付种牙，全国没有统一说法，问当地医保部门；个人账户怎么给家人用见第 5 节第 13 条（家庭共济）。缺牙为什么要补见第 2 节第 10 条（缺牙及时补）。收益量级定为中：降价是政策带来的，读者自己这一步能省下的，主要是包干外加价和高价机构的那部分，单颗几千元', NULL, NULL, NULL, '不花钱。看牙前在国家医保局的公众号上查一次机构名单，当面把价目问清，十几分钟。', '国家医保局 2024 年 1 月的公告说，常规单颗牙种植费用由三部分构成。一是医疗服务费，采取包干的方式。包干范围包括「种植全过程的诊查费、生化检验和影像检查费、种植体植入费、牙冠置入费、扫描设计建模费，不包括拔牙、牙周洁治、根管治疗、植骨、软组织移植」。「各地三级公立医院单颗常规种植牙的医疗服务收费原则上不超过4500元」，经济发达地区按 2022 年的专项治理通知最多可以放宽 20%。二是种植体，2023 年 1 月全国集中采购，「中选价格区间为548元—1855元，均价900余元」。牵头的四川省医保局公布，进口的高价品牌从采购中位价 5000 元降到 1850 元左右，用量最大的几个品牌从 1500 元左右降到 770 元左右。三是牙冠，「价格区间为100元—656元，均价300余元」。国家医保局 2023 年下半年的新闻发布会说，各地治理措施在 4 月底 5 月初全部落地，「种植牙整体费用从平均1.5万元降至6000－7000元左右」。医保报不报：劳动保障部等部门 1999 年的文件把「义齿」（假牙）和「非功能性整容、矫形手术」列为基本医保不予支付。国家医保局 2019 年答复政协提案时说，「美容类（包括牙缺失修复、矫正等）的诊疗项目,不纳入医保基金支付范围。但是对于牙科治疗类的诊疗项目，国家层面没有排除，各地也普遍纳入了医保支付范围」（全国，截至 2026 年 10 月）', '4500 元这条线只管公立医院。民营机构自己定价，但专项治理通知要求它们不得用虚假的或误导性的「补贴」「低价」诱导患者。广告上的低价往往只是种植体一项，拔牙、植骨这些包干之外的项目才是加价的地方，所以签字前要拿到一份写清每项价格的单子。承诺参与价格治理的机构名单由国家医保局在官方微信公众号上公布。缺一两颗牙不一定非种不可，固定义齿和活动义齿也是修复方式，价格没有跟着变，问医生哪种适合你。职工医保个人账户能不能付种牙，全国没有统一说法，问当地医保部门；个人账户怎么给家人用见第 5 节第 13 条（家庭共济）。缺牙为什么要补见第 2 节第 10 条（缺牙及时补）。收益量级定为中：降价是政策带来的，读者自己这一步能省下的，主要是包干外加价和高价机构的那部分，单颗几千元', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"24. 看病：怎么少花钱少走弯路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-1', 'concept_archive_s25-1', 'claim_archive_s25-1', 'action', 'life_archive', '人在家里或外面没了，先分清正常死亡还是非正常死亡：意外、死因不明、独居才发现的，立刻报警，遗体和现场不要动', '25. 人走了以后要办什么', '意外走的、不知道怎么走的、独居很久才被发现的，死亡证明只有公安能开。现场被动过，事情说不清，证也不好开。这张纸拿不到，后面火化、销户、保险理赔全都卡住。分不清是哪一种，就先打 110。警察到场查完，照样给你开证。', '长期卧病、在家里临终的，算正常死亡。可以找生前给他看病的机构开证，也可以找住处这一片的社区卫生服务中心、乡镇卫生院。死亡证明谁救治谁开，见第 2 条（死亡证明）。分不清是哪一种，就按非正常处理，先打 110，警察到场调查完照样能出证。如果先把现场收拾干净再报警，谁也帮不了你。不要自己搬遗体、给他擦洗换衣服，也不要收走药瓶和字条。', NULL, NULL, NULL, '不花钱。打一个电话就行。', '户口登记条例第八条第二款：「公民因意外事故致死或者死因不明，户主、发现人应当立即报告当地公安派出所或者乡、镇人民委员会」。意思是：出了意外，或者不知道人是怎么没的，户主和发现的人要马上报派出所或者乡镇政府。殡葬管理条例第二十三条：「自然人正常死亡的，医疗卫生机构应当及时出具死亡证明。涉及公安机关依法处置且未经医疗卫生机构救治的非正常死亡案（事）件的逝者，由公安机关出具死亡证明」。意思是：正常病故的，由给他看病的医疗机构开死亡证明。没经医院救治、又归公安处理的那种，由公安开。非正常死亡的死亡证明只有公安能开。现场被动过，就既说不清也不好开。后面火化、销户、保险理赔，全都卡在这一张纸上', '长期卧病、在家里临终的，算正常死亡。可以找生前给他看病的机构开证，也可以找住处这一片的社区卫生服务中心、乡镇卫生院。死亡证明谁救治谁开，见第 2 条（死亡证明）。分不清是哪一种，就按非正常处理，先打 110，警察到场调查完照样能出证。如果先把现场收拾干净再报警，谁也帮不了你。不要自己搬遗体、给他擦洗换衣服，也不要收走药瓶和字条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-2', 'concept_archive_s25-2', 'claim_archive_s25-2', 'action', 'life_archive', '死亡证明是后面所有事的钥匙：谁救治谁开，家中正常死亡找社区卫生服务机构，一日内签发', '25. 人走了以后要办什么', '在医院走的，找管救治的那一家开死亡证明。在家里正常走的，找住处这一片的社区卫生服务机构、乡镇卫生院开。死因清楚的，一天内就签发。销户、火化、取公积金、领社保待遇、理赔、办继承，每一件都要用它。拿到先多复印几份。', '销户、火化、取公积金、领社保待遇、保险理赔、办继承，每一件都要用它。拿到手先多复印几份，能开电子证照的一并申请。补发只有一次机会，原件别弄丢。名字、身份证号有错要当场改，因为等到办继承时才发现，每个窗口都要重跑一遍。', NULL, NULL, NULL, '不花钱。', '《人口死亡信息登记管理规范（试行）》说：在医疗卫生机构内死亡的，由「负责救治的医疗卫生机构签发」，在医院或者卫生院走的，找管救治的那一家开。在家中或其他场所正常死亡的，「由本辖区社区卫生服务机构或乡镇（街道）卫生院签发」，找住处这一片的社区卫生服务中心、乡镇或街道卫生院开。公安司法机构判断为非正常死亡的，由公安司法部门按现行规定及程序办理。2026 年五部门通知说：《死亡证明》「纸质版与电子证照具有同等法律效力」，电子的和纸质的一样管用。死因已明确的正常死亡，要在死亡发生后一日内签发。证明丢了，可以向原签发机构申请补发一次。基本信息有误的，可以凭材料申请重新签发一次', '销户、火化、取公积金、领社保待遇、保险理赔、办继承，每一件都要用它。拿到手先多复印几份，能开电子证照的一并申请。补发只有一次机会，原件别弄丢。名字、身份证号有错要当场改，因为等到办继承时才发现，每个窗口都要重跑一遍。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-3', 'concept_archive_s25-3', 'claim_archive_s25-3', 'action', 'life_archive', '遗体接运、存放、火化只能走殡仪馆，医院太平间不办殡仪，存放一般不超过 3 日', '25. 人走了以后要办什么', '接运、存放、防腐、整容、火化，只能由殡仪馆来做。医院太平间不办丧事，最多让遗体临时放一放。殡仪馆存放一般不超过 3 日，要多放几天得去办延期。火化要凭死亡证明和火化确认书。火化后给的那张火化证明，办继承、理赔还要用。', '在医院去世后凑上来的「一条龙」，多半不是殡仪馆的人。接运本身属于基础项目，有定价，见第 6 条（基础项目清单）。火化证明收好，办继承、保险、迁骨灰都要用。本地实行火葬还是土葬，由省级政府划定。少数民族的丧葬习俗受条例第九条保护。该火化却土葬的，或者在公墓和生态安葬区域外埋葬、修坟的，民政部门会责令限期改正（限期改回来）。', NULL, NULL, NULL, '不花钱。', '殡葬管理条例第二十五条：「遗体接运、存放、防腐、整容、火化服务，由殡仪馆专门负责提供」。这几件事别家做不了。第二十四条：「医疗卫生机构的太平间不得外包，不得开展殡仪服务，可以为遗体暂时停放提供便利服务」。医院太平间只能临时放一放，不能承办丧事。第二十七条：「殡仪馆存放遗体一般不超过 3 日，需要延期存放的，丧属或者遗体移交方应当在殡仪馆办理延期存放手续」。要多放几天，就去殡仪馆办延期。第二十八条：「殡仪馆应当凭死亡证明和火化确认书火化遗体，并出具火化证明」。两样材料缺一不可，火化完会给你一张火化证明。第二十九条：「在实行火葬的地区，遗体应当就地、就近在殡仪馆火化」，要在人去世的地方就近找殡仪馆火化', '在医院去世后凑上来的「一条龙」，多半不是殡仪馆的人。接运本身属于基础项目，有定价，见第 6 条（基础项目清单）。火化证明收好，办继承、保险、迁骨灰都要用。本地实行火葬还是土葬，由省级政府划定。少数民族的丧葬习俗受条例第九条保护。该火化却土葬的，或者在公墓和生态安葬区域外埋葬、修坟的，民政部门会责令限期改正（限期改回来）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-4', 'concept_archive_s25-4', 'claim_archive_s25-4', 'action', 'life_archive', '对死因有异议，48 小时内提出尸检，同时封存病历', '25. 人走了以后要办什么', '对死因有疑问，要在人去世后 48 小时内提出尸检。医院有冻存条件的，可以延到 7 日。尸检还要近亲属签字同意。不签字，或者一直拖过了时间，死因查不清的责任就算在拖的那一方。提尸检的同时，要求把病历封存起来。遗体一火化，就再也做不了尸检。', '过了这个时限再说「当初就觉得不对」，责任反过来落在拖延的那一方。遗体一旦火化，就再没有尸检的可能，所以这件事要在联系殡仪馆之前定下来。病历怎么封存见第 24 节。', NULL, NULL, NULL, '不花钱。难的是在那个时候还想得起来提。', '尸检的时限写在医疗纠纷预防和处理条例第二十六条。原文是：「患者死亡，医患双方对死因有异议的，应当在患者死亡后 48 小时内进行尸检；具备尸体冻存条件的，可以延长至 7 日」。所以想查清死因，要在人去世后 48 小时内做尸检，医院有冷冻条件的最多放宽到 7 天。同一条还写着：「尸检应当经死者近亲属同意并签字，拒绝签字的，视为死者近亲属不同意进行尸检」。家属不签字，就当作不同意。还写着：「不同意或者拖延尸检，超过规定时间，影响对死因判定的，由不同意或者拖延的一方承担责任」。谁不同意、谁拖过了时间，后面查不清死因的责任就算谁的。第二十四条：封存、启封病历资料「应当在医患双方在场的情况下进行」。病历装封和拆封，你和医院都得在场', '过了这个时限再说「当初就觉得不对」，责任反过来落在拖延的那一方。遗体一旦火化，就再没有尸检的可能，所以这件事要在联系殡仪馆之前定下来。病历怎么封存见第 24 节。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-5', 'concept_archive_s25-5', 'claim_archive_s25-5', 'action', 'life_archive', '注销户口有法定时限：城市在安葬前，农村在一个月以内', '25. 人走了以后要办什么', '城市要在安葬前销户，农村要在一个月以内。带死亡证明和户口簿去派出所办。拖着不办，继承过户、领待遇、退保都会卡在户籍状态上。', '户口一直挂着，办继承过户、领待遇、退保都会卡住，这些窗口都看户籍状态。养老金要是还照发，那是冒领，早晚要退回去。去派出所时顺便问清楚：社保、医保待遇怎么停，丧葬补助怎么申领。那几笔钱见第 9 条（公积金余额、社保待遇）。', NULL, NULL, NULL, '不花钱。带上死亡证明和户口簿，去派出所跑一趟。', '户口登记条例第八条第一款：「公民死亡，城市在葬前，农村在一个月以内，由户主、亲属、抚养人或者邻居向户口登记机关申报死亡登记，注销户口。公民如果在暂住地死亡，由暂住地户口登记机关通知常住地户口登记机关注销户口」。意思是：城里在下葬前办，农村在一个月内办。户主、亲属、抚养人或者邻居都可以去户口登记机关（派出所）报死亡、销户口。人是在外地暂住时走的，由暂住地派出所通知户籍所在地派出所销户', '户口一直挂着，办继承过户、领待遇、退保都会卡住，这些窗口都看户籍状态。养老金要是还照发，那是冒领，早晚要退回去。去派出所时顺便问清楚：社保、医保待遇怎么停，丧葬补助怎么申领。那几笔钱见第 9 条（公积金余额、社保待遇）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-6', 'concept_archive_s25-6', 'claim_archive_s25-6', 'action', 'life_archive', '殡葬服务分基础项目和非基础项目，基础项目有清单、收费依法制定', '25. 人走了以后要办什么', '遗体接运、存放、告别、火化、骨灰寄存、生态安葬，都在国家的基础项目清单里。公办机构提供的骨灰格位安葬也在里面。这些项目的价钱按规定来定。清单之外，不许另立项目收钱。出发前先问清楚哪几项算基础项目、当地标准是多少，再谈别的。', '省、自治区、直辖市可以在国家清单的基础上再加项目。先问清楚哪几项属于基础项目、当地的收费标准是多少，再谈其余的。清单里的项目价钱按规定定死，清单外的是自选的，分清这两类，被多收的那部分才有得说。想把亲人的后事办得体面一点没有错，不劝你从简，钱花在哪儿由你自己定。', NULL, NULL, NULL, '不花钱。出发前花几分钟看一眼清单。', '遗体接运、遗体存放、遗体告别、遗体火化、骨灰寄存、生态安葬，都在国家的基础项目清单里。政府举办的殡葬服务机构提供的骨灰格位安葬，也在清单里。这些项目的收费标准依法制定，价钱按规定来定，不由殡仪馆自己说了算。非基础项目清单由设区的市级以上民政部门（地级市及以上的民政部门）确定', '省、自治区、直辖市可以在国家清单的基础上再加项目。先问清楚哪几项属于基础项目、当地的收费标准是多少，再谈其余的。清单里的项目价钱按规定定死，清单外的是自选的，分清这两类，被多收的那部分才有得说。想把亲人的后事办得体面一点没有错，不劝你从简，钱花在哪儿由你自己定。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-7', 'concept_archive_s25-7', 'claim_archive_s25-7', 'action', 'life_archive', '遇到强制搭售、标价外加价、把一项拆成几项收费，记下来投诉', '25. 人走了以后要办什么', '这几样都是条例点名的价格违法行为：不挂价目表、在标价之外加钱、捆绑着强卖丧葬用品、逼你接受别家的收费服务。把一项拆成几项收费，也算变相涨价。当场先要价目表，留好收费凭据和聊天记录。事后再投诉也来得及。查价格找市场监管，管殡葬服务找民政。', '查处价格违法归市场监管部门，殡葬服务本身归民政部门。当场先要一张价目表，收费凭据和聊天记录都留好，事后再去投诉也来得及。', NULL, NULL, NULL, '不花钱。难的是在那个当口还愿意较真。', '条例列了五类价格违法行为，下面说其中四类。不挂价目表、收比标价更多的钱，属于不明码标价或者在标价之外加价。不买这个就不给办那个，属于捆绑或者附加不合理条件强制销售。硬塞给你另一家的收费服务，属于强制或者变相强制接受第三方有偿服务。换个名目多收钱，属于变相提高收费标准。另外还禁止「分解项目、扩大范围收费等形式变相提高收费标准」。把一项服务拆成好几项分别收费，或者把收费范围往外扩，都在禁止之列', '查处价格违法归市场监管部门，殡葬服务本身归民政部门。当场先要一张价目表，收费凭据和聊天记录都留好，事后再去投诉也来得及。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-8', 'concept_archive_s25-8', 'claim_archive_s25-8', 'action', 'life_archive', '殡葬代理、用品代购、策划主持这类中介，要在县级民政备案', '25. 人走了以后要办什么', '殡葬代理、用品代购、策划主持、信息咨询这类中介，要在县级民政部门备案。没备案的，不进民政部门那套殡葬服务信息系统。能不能自己查各地不一样，最稳的是打电话问县级民政部门。用骗术乱收费、倒卖逝者信息的，会被依法处置。', '「倒卖逝者信息」是这一行里最常见的坑。刚办完手续就接到一堆推销电话，多半是信息被转卖了。网络祭扫平台也一样受管。条例第四十五条不许它诱导消费，也不许它违法处理逝者的信息。', NULL, NULL, NULL, '不花钱。问一句备没备案。', '没备案的中介，不在民政部门管的殡葬服务信息系统里。以欺骗手段违规收费、诱导大操大办、强迫接受服务、倒卖逝者信息的，会被依法处置，还会在系统中标注、向社会公开，谁都能看到', '「倒卖逝者信息」是这一行里最常见的坑。刚办完手续就接到一堆推销电话，多半是信息被转卖了。网络祭扫平台也一样受管。条例第四十五条不许它诱导消费，也不许它违法处理逝者的信息。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-9', 'concept_archive_s25-9', 'claim_archive_s25-9', 'action', 'life_archive', '分散在各处的钱要逐个去取：公积金余额、社保待遇、工伤待遇', '25. 人走了以后要办什么', '公积金余额继承人可以提取，它不在银行账户里，最容易漏。养老保险个人账户里剩的钱也能继承。因病去世的，家属另领丧葬补助金和 3 到 24 个月的抚恤金。因工死亡的，另有工伤那三笔钱。', '公积金那笔最常被忘掉，因为它不在银行账户里，也不会自动进遗产分配。养老保险个人账户里剩的钱和遗属待遇是分开算、分开发的，要去参保地的社保经办窗口一起办。各地要的材料不一样。缴费不满 5 年的，遗属待遇合起来不超过他自己交的钱。这套公式出自企业职工养老保险的办法，机关事业单位和城乡居民养老保险的遗属待遇去窗口问。遗嘱和继承的形式要求见第 17 节。', NULL, NULL, NULL, '不花钱，但要跑几个窗口。去之前备齐死亡证明和亲属关系证明。', '住房公积金账户余额（他公积金账户里还剩的钱），继承人、受遗赠人可以提取。受遗赠人是指写进遗嘱、要把东西留给他的那个人。因工死亡的，另有三笔钱：丧葬补助金、供养亲属抚恤金、一次性工亡补助金。养老保险个人账户里剩的钱，社会保险法写明可以继承。参加职工养老保险的人因病或者非因工死亡，家属还能领丧葬补助金和抚恤金，合称遗属待遇。企业职工的标准全国统一公式。丧葬补助金是本省上一年城镇居民月人均可支配收入的 2 倍。抚恤金以这个月收入为基数，按缴费年限发 3 到 24 个月：不满 5 年 3 个月，5 到 10 年 6 个月，10 到 15 年 9 个月，15 年以上每多 1 年加 1 个月，最多 24 个月。已经退休的，每领 1 年养老金减 1 个月，最少 9 个月', '公积金那笔最常被忘掉，因为它不在银行账户里，也不会自动进遗产分配。养老保险个人账户里剩的钱和遗属待遇是分开算、分开发的，要去参保地的社保经办窗口一起办。各地要的材料不一样。缴费不满 5 年的，遗属待遇合起来不超过他自己交的钱。这套公式出自企业职工养老保险的办法，机关事业单位和城乡居民养老保险的遗属待遇去窗口问。遗嘱和继承的形式要求见第 17 节。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s25-10', 'concept_archive_s25-10', 'claim_archive_s25-10', 'action', 'life_archive', '死者的账号和个人信息，近亲属可以要求查阅、复制、更正、删除', '25. 人走了以后要办什么', '人走以后，近亲属为了自己的合法正当利益，可以要求平台查阅、复制、更正、删除死者的个人信息。平台要是拒绝，得说明理由。你也可以去法院起诉。有一个例外：他生前另有安排的，比如设过账号继承人、留下过明确意愿，按他的安排来。', '法条里有一句「死者生前另有安排的除外」，生前设过账号继承人、或者留过明确意愿的，按他留下的来。所以趁人清醒的时候，值得把账号和密码的去向写下来，见第 17 节。注销账号和删除个人信息是两件事，见第 14 节。', NULL, NULL, NULL, '不花钱。平台不配合，才需要去投诉或者起诉。', '法律明写：自然人死亡的，近亲属为了自身合法、正当利益，可以对死者的相关个人信息行使查阅、复制、更正、删除等权利。近亲属可以要求平台把他的信息拿出来看、复制一份、改错、删掉', '法条里有一句「死者生前另有安排的除外」，生前设过账号继承人、或者留过明确意愿的，按他留下的来。所以趁人清醒的时候，值得把账号和密码的去向写下来，见第 17 节。注销账号和删除个人信息是两件事，见第 14 节。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"25. 人走了以后要办什么","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-1', 'concept_archive_s26-1', 'claim_archive_s26-1', 'action', 'life_archive', '平台不要自己收钱再转给卖家，让钱走持牌支付机构直接结算', '26. 做一个网站或平台：资质、备案和服务器', '买家的钱先进你的账户，你再转给卖家，这就是在做支付业务。做这门生意要中国人民银行批准，还要真拿出一亿元本钱。没批准就干，会被关停，挣的钱收走，还要罚款，老板和经办人另外罚。严重的还要判刑。稳妥做法只有一条：钱不进你的账户。', '把钱设计成不进你的账户，这是唯一稳妥的做法。市面上管这种代收代付叫「二清」，但官方文件里没有这个词。实施细则用的说法是「变相从事支付业务」，意思是没经批准却按用户的指令替人转钱。最高人民法院和最高人民检察院的那份解释只列了三种情形：编假交易套现、用单位账户套现、用支票套现。它没有点名平台代收代付，所以不能说平台代收代付「一定构成犯罪」', NULL, NULL, NULL, '不花钱。要花点时间接一家持牌支付机构的产品。持牌支付机构就是拿到了央行支付牌照的公司。用它的分账或者担保交易功能，买家的钱直接结给卖家，不进平台自己的账户', '法规说的支付业务，是「根据收款人或者付款人提交的电子支付指令转移货币资金」。说白了就是按别人的指令替人转钱。要做这门生意，「应当经中国人民银行批准，取得支付业务许可」。注册资本最低 1 亿元，而且是实缴货币资本，这 1 亿元要真金白银打进公司账户。「未经依法批准，擅自设立非银行支付机构、从事或者变相从事支付业务的，由中国人民银行依法予以取缔，没收违法所得」。没批准就干这件事的，直接关停，挣的钱收走。违法所得 50 万元以上的，再罚违法所得的 1 到 5 倍。没有违法所得、或者不足 50 万元的，罚 50 万到 200 万元。法定代表人和直接负责的人另外罚 10 万到 50 万元。刑法还把「非法从事资金支付结算业务」算作非法经营。情节严重的判 5 年以下，特别严重的判 5 年以上。什么算「情节严重」，最高人民法院和最高人民检察院的解释里划了线。这条线是非法经营数额 500 万元以上，或者违法所得 10 万元以上（全国，2024 年 5 月起）', '把钱设计成不进你的账户，这是唯一稳妥的做法。市面上管这种代收代付叫「二清」，但官方文件里没有这个词。实施细则用的说法是「变相从事支付业务」，意思是没经批准却按用户的指令替人转钱。最高人民法院和最高人民检察院的那份解释只列了三种情形：编假交易套现、用单位账户套现、用支票套现。它没有点名平台代收代付，所以不能说平台代收代付「一定构成犯罪」', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 高","口径 自由","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-2', 'concept_archive_s26-2', 'claim_archive_s26-2', 'action', 'life_archive', '收费的网站多数要许可证，自己卖货不让别人入驻的不用，撮合交易的是另一类许可，免费的只要备案', '26. 做一个网站或平台：资质、备案和服务器', '向用户收钱的网站，多数要先办增值电信业务经营许可证，这张证个人办不了。只在自己网站或 App 上卖货、不让别人入驻开店的，不用办。只开微信、支付宝小程序或网店的也不用。该办没办就收钱开站，会被没收收入再罚款，严重的关站。', '你要做的是不是 EDI 那一类，自己拿《电信业务分类目录》里的定义对号入座。官方没有任何一句话明说「带撮合和资金处理的电商平台必须办 EDI 许可」。工信部的办事指南只说「按照业务界定申请相应的电信业务经营许可」。所以要不要办，只能拿定义自己判断。还有一点：这张证个人办不了，申请人必须是依法设立的公司。自营不用办证那三种情形，出自广东省通信管理局的问答，它写明是按工信部要求，但别的省没查到同样的公开文字。拿不准就先打电话问属地的通信管理局。这份问答也提醒，办证不用找中介，只在工信部「电信业务市场综合管理信息系统」上交材料，官方不收费', NULL, NULL, NULL, '备案不花钱。增值电信业务经营许可证要花钱，它管的是「向用户收钱的网站能不能开」。办这张证先得有公司。只在省内经营的，注册资本不低于 100 万元。跨省经营的，不低于 1000 万元。审查期 60 日，证的有效期 5 年', '法规原话是「国家对经营性互联网信息服务实行许可制度；对非经营性互联网信息服务实行备案制度。未取得许可或者未履行备案手续的，不得从事互联网信息服务」。收钱的要先拿许可证，不收钱的要先备案，两样都没有就不能开站。什么叫经营性？法规说是「通过互联网向上网用户有偿提供信息或者网页制作等服务活动」。简单说就是向用户收钱。撮合交易的那一类叫在线数据处理与交易处理业务，业内简称 EDI。法规给它的定义是「利用各种与公用通信网或互联网相连的数据与交易/事务处理应用平台，通过公用通信网或互联网为用户提供在线数据处理和交易/事务处理的业务」。它还「包括交易处理业务、电子数据交换业务和网络/电子设备数据处理业务」。说的就是网站替用户在线处理数据，或者替买卖双方撮合和处理交易。没办证就经营，或者超范围经营，都要没收违法所得，再罚违法所得的 3 到 5 倍。超范围经营就是办了证，干的事却超出证上写的范围。没有违法所得、或者违法所得不足 5 万元的，罚 10 万到 100 万元。情节严重的，责令关闭网站（全国）。收钱不等于一定要办证。广东省通信管理局 2025 年 10 月发的问答说，按工信部要求，下面三种不用办这张证。第一种，企业在自己的网站、App 上「以自营方式直接销售自身或其它企业的商品或服务」，而且没有别的单位或个人入驻开店。第二种，企业在自己的网站、App 上只发自己的信息，不给别人提供发布信息的平台。第三种，企业只靠微信、支付宝这些平台上的小程序、公众号、视频号、网店做生意，「且无其他独立运营平台」。反过来，只要让别人入驻开店、或者让用户在你这里发信息，就不在这三种里面', '你要做的是不是 EDI 那一类，自己拿《电信业务分类目录》里的定义对号入座。官方没有任何一句话明说「带撮合和资金处理的电商平台必须办 EDI 许可」。工信部的办事指南只说「按照业务界定申请相应的电信业务经营许可」。所以要不要办，只能拿定义自己判断。还有一点：这张证个人办不了，申请人必须是依法设立的公司。自营不用办证那三种情形，出自广东省通信管理局的问答，它写明是按工信部要求，但别的省没查到同样的公开文字。拿不准就先打电话问属地的通信管理局。这份问答也提醒，办证不用找中介，只在工信部「电信业务市场综合管理信息系统」上交材料，官方不收费', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 多","时间 多","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-3', 'concept_archive_s26-3', 'claim_archive_s26-3', 'action', 'life_archive', '做直播要网络文化经营许可证，做视听节目的那张证民营基本拿不到', '26. 做一个网站或平台：资质、备案和服务器', '做直播、做游戏解说，要省级文化部门发的网络文化经营许可证。证上的经营范围里得写明网络表演。受理后 20 日内出结果，证管 3 年。播过的视频自己要留满 60 天。没办证就开张，会被叫停、警告，再罚 3 万元以下，不停就上黑名单。', '哪种业务配哪张证，七部门那份文件写得最清楚。靠直播赚钱的平台，要网文证加 ICP 备案，ICP 备案就是网站在工信部登记的那道手续。在网上放节目的，要视听证，或者完成登记。发新闻的，要互联网新闻信息服务许可证。另外，中国政府网 2025 年转发的《互联网文化管理暂行规定》登的是 2011 年未修订的原文，引用要以文化和旅游部的现行文本为准', NULL, NULL, NULL, '网络文化经营许可证俗称网文证，它管的是「能不能靠直播、游戏解说这类网络表演赚钱」。由省级文化行政部门审批，受理后 20 日内给结果，有效期 3 年，到期前 30 日去续办。视听节目许可管的是「能不能在网上放节目」，它要求申请人是国有独资或者国有控股单位', '做网络表演的单位要先办证。法规原话是「应当根据《互联网文化管理暂行规定》，向省级文化行政部门申请取得《网络文化经营许可证》，许可证的经营范围应当明确包括网络表演」。打游戏给人看、给人讲解的也按这一套管，法规原话是「参照本办法进行管理」。所有网络表演的视频资料，「保存时间不得少于60日」，播过的视频你要自己留满 60 天。没批准就做经营性互联网文化活动的，责令停止、给予警告，再罚 3 万元以下。叫了还不停的，列入文化市场黑名单。在网上放节目是另一张证，「应当取得《信息网络传播视听节目许可证》」。申请人要「具备法人资格，为国有独资或国有控股单位」，必须是国家全资或者国家控股的单位，民营公司基本拿不到。没这张证就做的，予以警告、责令改正，可以再罚 3 万元以下。情节严重的，按广播电视管理条例处罚（全国）', '哪种业务配哪张证，七部门那份文件写得最清楚。靠直播赚钱的平台，要网文证加 ICP 备案，ICP 备案就是网站在工信部登记的那道手续。在网上放节目的，要视听证，或者完成登记。发新闻的，要互联网新闻信息服务许可证。另外，中国政府网 2025 年转发的《互联网文化管理暂行规定》登的是 2011 年未修订的原文，引用要以文化和旅游部的现行文本为准', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 多","时间 多","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-4', 'concept_archive_s26-4', 'claim_archive_s26-4', 'action', 'life_archive', '服务器放境内就要备案，接入商必须自己持有增值电信许可', '26. 做一个网站或平台：资质、备案和服务器', '服务器放在境内，开站前就要备案。备案不花钱，跟着服务器在服务商那里提交，一般几天到几周。没备案会被责令限期改正，再罚 1 万元，不改就关站。主页上不挂备案号，另外罚 5000 元到 5 万元。', '谈价之前先查服务商有没有证。查证用工信部电信业务市场综合管理信息系统 tsm.miit.gov.cn，按公司全称或者证号查。查网站备案用 beian.miit.gov.cn。没有相应许可的「机房」，出事那天你连找谁申诉都不知道。把机器放到境外，确实能绕开备案。但用户在境内、钱在境内，本节第 5 到第 10 条写的那些义务一条都不会少，还多出一层数据出境的成本', NULL, NULL, NULL, '备案不花钱。它跟着服务器一起在服务商那里提交，通常要等几天到几周。查一次服务商有没有资质，十分钟就够', '法规原话是「未经备案，不得在中华人民共和国境内从事非经营性互联网信息服务」。不向用户收钱的网站，只要放在境内，也得先备案。没备案的，责令限期改正，再罚 1 万元。拒不改正的，关闭网站。帮你把服务器接上网的那家服务商也受管：它「不得为未经备案的组织或者个人从事非经营性互联网信息服务提供互联网接入服务」。替你收钱的服务商也一样。法规说这类服务商「不得为未依法取得经营许可证或者履行非经营性互联网信息服务备案手续的单位或者个人提供接入或者代收费等服务」。意思是没证也没备案的站，正规服务商不许接。再有，机房托管和云主机在法规里叫互联网数据中心业务，宽带接入叫互联网接入服务业务，这两样本身就要许可，服务商自己先得有证。网站主页上不标备案号的，责令改正，再罚 5000 元到 5 万元（全国）', '谈价之前先查服务商有没有证。查证用工信部电信业务市场综合管理信息系统 tsm.miit.gov.cn，按公司全称或者证号查。查网站备案用 beian.miit.gov.cn。没有相应许可的「机房」，出事那天你连找谁申诉都不知道。把机器放到境外，确实能绕开备案。但用户在境内、钱在境内，本节第 5 到第 10 条写的那些义务一条都不会少，还多出一层数据出境的成本', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-5', 'concept_archive_s26-5', 'claim_archive_s26-5', 'action', 'life_archive', '让用户上来卖东西，平台就要核验登记、报送信息、留存三年', '26. 做一个网站或平台：资质、备案和服务器', '让别人上你的平台卖东西，你就要先核卖家的身份、地址、联系方式和许可证，再登记建档。建完档，至少每六个月回头再核一次。卖家是谁要报给市场监管，纳税的情况每季度报给税务。商品和交易记录留三年。漏做一项，先责令改正，不改罚 2 万到 10 万元。', '卖家自己也要去办市场主体登记。法律列了几种不用办的：「个人销售自产农副产品、家庭手工业产品，个人利用自己的技能从事依法无须取得许可的便民劳务活动和零星小额交易活动」。「零星小额」有个具体数，网络交易监督管理办法第八条定的是年交易额 10 万元。平台这边还有两件事要做：把已登记和未登记的卖家分别标出来，以及不许删消费者的评价', NULL, NULL, NULL, '不花钱。要在后台做卖家的资质核验，还要建一份登记档案。每个季度报一次涉税信息，交易数据留三年。难在它是常年的活，不是办一次就完', '法律对平台有一段要求。原话是「应当要求申请进入平台销售商品或者提供服务的经营者提交其身份、地址、联系方式、行政许可等真实信息，进行核验、登记，建立登记档案，并定期核验更新」。卖家进场前要交身份、地址、联系方式和他该办的许可证。你要核一遍，登记建档，之后隔一段时间还要回头再核一次。「定期」是多久？部门规章说得更细，「至少每六个月核验更新一次」。你还要向市场监管部门报送平台内经营者的身份信息。税务那边也要报，原话是「依照税收征收管理法律、行政法规的规定，向税务部门报送平台内经营者的身份信息和与纳税有关的信息」。所以卖家是谁要报给市场监管，卖家的身份和纳税情况要报给税务。商品和服务信息、交易信息「保存时间自交易完成之日起不少于三年」，从一笔交易做完那天算起，数据至少留三年。上面任何一项没做到的，责令限期改正。逾期不改的，罚 2 万到 10 万元。情节严重的，责令停业整顿，再罚 10 万到 50 万元。涉税信息要「于季度终了的次月内」报送，每个季度结束后的下一个月里就要报掉。没按期报的，罚则一样（全国）', '卖家自己也要去办市场主体登记。法律列了几种不用办的：「个人销售自产农副产品、家庭手工业产品，个人利用自己的技能从事依法无须取得许可的便民劳务活动和零星小额交易活动」。「零星小额」有个具体数，网络交易监督管理办法第八条定的是年交易额 10 万元。平台这边还有两件事要做：把已登记和未登记的卖家分别标出来，以及不许删消费者的评价', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 多","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-6', 'concept_archive_s26-6', 'claim_archive_s26-6', 'action', 'life_archive', '用户发的内容你要管：审核机制、举报入口、发现违法立即停传并报告', '26. 做一个网站或平台：资质、备案和服务器', '用户发的东西，出了事由平台负责。你要把这套制度建起来：注册、发帖审核、评论审核、每天巡查、出事怎么处置。页面显眼的地方放举报入口。看到违法信息，马上停止传播、留好记录、报给主管部门。不做的，罚 5 万到 50 万元，严重的更多。', '审核规则不用自己想，照抄就行。哪九类内容不许发，互联网信息服务管理办法第十五条列得清清楚楚。做直播的还多三件事：要「建立直播内容审核平台」，要能随时掐断一场正在播的直播，法条管这个叫「即时阻断」，还要把直播内容和日志保存 60 日。网络表演的视频资料同样不少于 60 日', NULL, NULL, NULL, '要花钱雇人审核，这是平台最大的一笔长期开支。举报入口和每一次处置的记录都要留痕。难在它天天都得有人盯，停一天就可能出事', '法规说平台「应当履行信息内容管理主体责任」，用户发的东西由平台自己负责管。具体要「健全用户注册、账号管理、信息发布审核、跟帖评论审核、版面页面生态管理、实时巡查、应急处置和网络谣言、黑色产业链信息处置等制度」。从注册、发帖、评论，到日常巡查和出事处置，每一环都要有写下来的规矩。还「应当在显著位置设置便捷的投诉举报入口」，举报按钮要放在用户一眼看得见、点得到的地方。发现违法信息的，「应当依法立即采取处置措施，保存有关记录，并向有关主管部门报告」。网络安全法说得更具体。原话是「发现法律、行政法规禁止发布或者传输的信息的，应当立即停止传输该信息，采取消除等处置措施，防止信息扩散，保存有关记录，并向有关主管部门报告」。没做到的，责令改正、给予警告、予以通报，可以再罚 5 万到 50 万元。拒不改正、或者情节严重的，罚 50 万到 200 万元，还可能被责令停业整顿、关闭网站或者应用程序、吊销许可证或者营业执照。直接负责的人另外罚 5 万到 20 万元（全国）', '审核规则不用自己想，照抄就行。哪九类内容不许发，互联网信息服务管理办法第十五条列得清清楚楚。做直播的还多三件事：要「建立直播内容审核平台」，要能随时掐断一场正在播的直播，法条管这个叫「即时阻断」，还要把直播内容和日志保存 60 日。网络表演的视频资料同样不少于 60 日', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 少","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-7', 'concept_archive_s26-7', 'claim_archive_s26-7', 'action', 'life_archive', '提供信息发布、即时通讯服务，必须要求用户提供真实身份信息', '26. 做一个网站或平台：资质、备案和服务器', '你的网站能发帖，或者能聊天，就要在用户开通服务时要他的真实身份信息。不给的，不能让他用。做法是后台存真名，页面上显示什么昵称由他自己定，核验用手机号就行。不做实名的，先责令改正。不改的罚 5 万到 50 万元，还可能关站。', '条号换过位置。网络安全法 2025 年修正，2026 年 1 月 1 日施行。实名这一条从第二十四条移到了第二十六条，罚则从第六十一条移到了第六十四条。条文文字没变。你手上的材料如果还引旧条号，要改过来', NULL, NULL, NULL, '要接一条实名核验通道，这类通道按次收费。产品上按「后台实名、前台自愿」来设计：后台存真名，页面上显示昵称', '法律原话是「网络运营者为用户办理网络接入、域名注册服务，办理固定电话、移动电话等入网手续，或者为用户提供信息发布、即时通讯等服务，在与用户签订协议或者确认提供服务时，应当要求用户提供真实身份信息。用户不提供真实身份信息的，网络运营者不得为其提供相关服务」。没要实名的，或者用户没给真实身份、你还照样让他用的，责令改正。拒不改正、或者情节严重的，罚 5 万到 50 万元，还可能被责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销许可证或者营业执照。直接负责的人另外罚 1 万到 10 万元。直播服务按「后台实名、前台自愿」的原则，做「基于移动电话号码等方式的真实身份信息认证」。意思是平台后台存着用户的真名，页面上显示什么昵称由用户自己定，核验靠手机号一类方式。直播带货要求更严，是「基于身份证件信息、统一社会信用代码等真实身份信息认证」。统一社会信用代码就是营业执照上那串号（全国）', '条号换过位置。网络安全法 2025 年修正，2026 年 1 月 1 日施行。实名这一条从第二十四条移到了第二十六条，罚则从第六十一条移到了第六十四条。条文文字没变。你手上的材料如果还引旧条号，要改过来', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-8', 'concept_archive_s26-8', 'claim_archive_s26-8', 'action', 'life_archive', '不给未满 16 周岁的人开直播，打赏按年龄分档处理', '26. 做一个网站或平台：资质、备案和服务器', '不满 16 周岁的人，不能在你这里注册开播账号。满 16 周岁的要核验身份，还要父母或其他监护人同意。打赏分三档：不满 8 岁不能打赏，8 到 16 岁要监护人同意，16 岁以上要监护人同意或核验收入证明。孩子背着监护人打赏的钱，监护人来要，法院会判退还。', '真起了退款争议，按对未成年人最有利的方向处理。这件事的说法改过。2022 年四部门的意见和广电总局 2020 年的通知，说的都是未成年人一律不得打赏。2026 年 4 月的新通知改成按 8 岁、16 岁分档，却没写明前两份作废，官方也没说两者怎么衔接。所以「未成年人一律禁止打赏」这句话现在不准确', NULL, NULL, NULL, '不花钱。在注册和付款这两步各加一道流程：先判断年龄，再确认监护人同意过', '法律原话是「网络直播服务提供者不得为未满十六周岁的未成年人提供网络直播发布者账号注册服务；为年满十六周岁的未成年人提供网络直播发布者账号注册服务时，应当对其身份信息进行认证，并征得其父母或者其他监护人同意」。条例还要求「建立网络直播发布者真实身份信息动态核验机制」，开播的人的身份，你要能随时复核一遍。另外要「合理限制不同年龄阶段未成年人在使用其服务中的单次消费数额和单日累计消费数额」，按年龄给未成年人设单笔和单日的花钱上限。打赏现在分三档：「不得向八周岁以下的未成年人提供打赏服务。向八周岁至十六周岁的未成年人提供打赏服务，应征得其监护人同意。向十六周岁以上的未成年人提供打赏服务，应征得其监护人同意或核验其收入证明材料」。还有一条：限制民事行为能力人没经监护人同意就打赏的，监护人来要钱，法院应予支持，钱能要回去。限制民事行为能力人指法律上还不能完全自己做主的未成年人（全国）', '真起了退款争议，按对未成年人最有利的方向处理。这件事的说法改过。2022 年四部门的意见和广电总局 2020 年的通知，说的都是未成年人一律不得打赏。2026 年 4 月的新通知改成按 8 岁、16 岁分档，却没写明前两份作废，官方也没说两者怎么衔接。所以「未成年人一律禁止打赏」这句话现在不准确', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-9', 'concept_archive_s26-9', 'claim_archive_s26-9', 'action', 'life_archive', '接到侵权通知要及时处理，转送声明后 15 日没有下文就恢复', '26. 做一个网站或平台：资质、备案和服务器', '有人发来侵权通知，还附了初步证据，你要及时把东西删掉、屏蔽或者断开链接，同时把通知转给卖家。拖着不办，多出来的那部分损失你要和卖家一起赔。卖家申辩了，你把申辩转给对方，等 15 天。对方既没投诉也没起诉，就把东西恢复回去。', '你不是电商平台，只是一般网站，那就走民法典的通知删除规则。区别在于对方申辩之后你要等多久：电商法给了明确的 15 日，民法典只写「合理期限」。另外，把收到的通知、卖家的申辩和你的处理结果公示出来，是电商法第四十四条的明文要求。平台自己组织上传盗版，或者明知侵权还放着不管，「收到通知就删」这条规则护不住它，见第 9 节第 24 条（汉化漫画、搬运影视剧）', NULL, NULL, NULL, '不花钱。要建一条固定流程：收到通知、转给卖家、收卖家的申辩、把结果公示出来。每一步都留档', '权利人「有权通知电子商务平台经营者采取删除、屏蔽、断开链接、终止交易和服务等必要措施。通知应当包括构成侵权的初步证据」。权利人就是商标、著作权、专利这些权利的主人。光发一句话不算，要附上初步证据。平台接到通知后，「应当及时采取必要措施，并将该通知转送平台内经营者；未及时采取必要措施的，对损害的扩大部分与平台内经营者承担连带责任」。你拖着不处理，多出来的那部分损失，你要和卖家一起赔。卖家申辩之后，平台「在转送声明到达知识产权权利人后十五日内，未收到权利人已经投诉或者起诉通知的，应当及时终止所采取的措施」。意思是把卖家的申辩转给权利人，等 15 天。对方既没投诉也没起诉，就把删掉、下架的恢复回去。平台知道或者应当知道有侵权却不处理的，与侵权人承担连带责任。知识产权部门还可以责令你限期改正，逾期不改的罚 5 万到 50 万元，情节严重的罚 50 万到 200 万元。反过来，「恶意发出错误通知，造成平台内经营者损失的，加倍承担赔偿责任」（全国）', '你不是电商平台，只是一般网站，那就走民法典的通知删除规则。区别在于对方申辩之后你要等多久：电商法给了明确的 15 日，民法典只写「合理期限」。另外，把收到的通知、卖家的申辩和你的处理结果公示出来，是电商法第四十四条的明文要求。平台自己组织上传盗版，或者明知侵权还放着不管，「收到通知就删」这条规则护不住它，见第 9 节第 24 条（汉化漫画、搬运影视剧）', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-10', 'concept_archive_s26-10', 'claim_archive_s26-10', 'action', 'life_archive', '用户信息不要随手放到境外，出境有法定条件和人数门槛', '26. 做一个网站或平台：资质、备案和服务器', '把境内用户的信息传到境外的机器上，这就叫出境。服务器放在境外，不等于数据没出境。要出境得走四条路之一：网信部门的安全评估、专业机构的认证、按标准合同签约，或者法律另有规定。还要告诉用户境外收信息的是谁、拿去做什么，并专门就这件事问他一次。', '服务器放境外不等于「数据没出境」。用户在境内注册，你把他的信息传到境外的机器上，这就是出境。有一类不用走安全评估、认证、标准合同这三条路：跨境购物、跨境寄递、订机票酒店，这些是「为订立、履行个人作为一方当事人的合同」确实必须传的。还要注意人数怎么算：按「自当年 1 月 1 日起累计」算，不是从今天往回数十二个月', NULL, NULL, NULL, '不花钱。最省事的办法是把用户数据留在境内。确实要传到境外的，走标准合同或者做认证', '把境内用户的信息交给境外的公司、或者存到境外的机器上，法律上叫向境外提供个人信息，「应当具备」四项条件之一。一是通过网信部门组织的安全评估。二是经专业机构做个人信息保护认证。三是按网信部门制定的标准合同和境外接收方签约。四是法律、行政法规规定的其他条件。同时你要告诉用户这几样：境外接收方的名称、联系方式、处理目的、处理方式、个人信息的种类，以及他怎么行使自己的权利。而且要「取得个人的单独同意」，专门就这件事问用户一次。具体门槛按累计人数分档。普通企业在法规里叫关键信息基础设施运营者以外的数据处理者。这类企业有一条免办的线，原话是「自当年1月1日起累计向境外提供不满10万人个人信息（不含敏感个人信息）的」。到不了这条线，申报评估、订立标准合同、做认证这三样都免了。10 万人以上不满 100 万人的，应当订立标准合同或者通过认证。100 万人以上的，或者敏感个人信息达到 1 万人以上的，应当申报安全评估（全国，2024 年 3 月起）', '服务器放境外不等于「数据没出境」。用户在境内注册，你把他的信息传到境外的机器上，这就是出境。有一类不用走安全评估、认证、标准合同这三条路：跨境购物、跨境寄递、订机票酒店，这些是「为订立、履行个人作为一方当事人的合同」确实必须传的。还要注意人数怎么算：按「自当年 1 月 1 日起累计」算，不是从今天往回数十二个月', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s26-11', 'concept_archive_s26-11', 'claim_archive_s26-11', 'action', 'life_archive', '选服务器先看停机能不能忍，再看有没有人运维，最后才比价', '26. 做一个网站或平台：资质、备案和服务器', '三档的差别不在价格，在出事那天你手上有什么。大厂有备案通道，资质公开，坏了有公告、有赔偿条款，能找到人。小服务商便宜一半，可它超售、跑路、被上游封掉的时候，你连找谁都不知道。没有用户数据的静态站，几十元的 VPS 就够用。', '上面是经验判断，没有文献证据。能真正核查的只有一件事：服务商的许可证。要省钱就在配置和带宽上省，别在资质上省', NULL, NULL, NULL, '主流云厂商的云主机，每月数百到数千元。小服务商的 VPS，每月几十元起。VPS 就是一台虚拟的小服务器。独立服务器托管每年数千元起，而且硬件要自己买', '三档的差别不在价格，在出事那天你手上有什么。主流云厂商有备案通道，资质是公开的，出故障有公告，合同里有赔偿条款，出了问题能找到人。小服务商价格能低一半，但它超售、跑路、被上游封掉的时候，你没有申诉对象，所以谈价之前先去工信部系统查它有没有增值电信业务经营许可。独立服务器托管只有在两个条件都成立时才合算：带宽或者硬件成本明显更便宜，并且你自己有人做运维。怎么选：没有用户数据的静态站，用最便宜的 VPS 就够。有用户注册和交易的，选能弹性扩容、能快照备份的云主机，备份至少放在两个地方', '上面是经验判断，没有文献证据。能真正核查的只有一件事：服务商的许可证。要省钱就在配置和带宽上省，别在资质上省', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"26. 做一个网站或平台：资质、备案和服务器","C 级","性价比 一般","口径 金钱","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-1', 'concept_archive_s27-1', 'claim_archive_s27-1', 'action', 'life_archive', '准备怀孕就开始每天补 0.4 毫克叶酸，一直吃到孕早期满 3 个月', '27. 怀孕和生产：从发现怀孕到出院办证', '怀孕前后每天吃一粒叶酸，孩子出现神经管缺陷的概率大约能降七成。神经管缺陷就是无脑儿、脊柱裂这一类的出生缺陷。已经生过一个这样的孩子的人，再生一个还出问题的概率，大约降到原来的三分之一。', '关键是「怀孕前就开始吃」。胎儿的神经管在受孕后 28 天内就长合了。等你测出怀孕再吃，这段时间已经过去大半。所以打算要孩子，就提前 3 个月开始吃。同一篇汇总研究里，叶酸对唇腭裂、先天性心脏病、流产都没有明确效果，别指望它治别的', NULL, NULL, NULL, '几十元一瓶。农村妇女不用花钱，国家的免费增补叶酸项目会发。每天吃一粒，难在天天记得住', 'Cochrane 系统综述把 5 项试验、6708 例分娩合起来一起算，证据质量评为高。怀孕前后每天补叶酸，胎儿神经管缺陷的风险 RR 0.31（95% CI 0.17 至 0.58，可信范围），约降低七成。已经生过神经管缺陷孩子的人，再生一个又出问题的风险 RR 0.34（95% CI 0.18 至 0.64），降到原来的三分之一左右。按人群分组来看，0.4 毫克和更高的剂量效果没有差别。单独吃叶酸和吃复合维生素，效果也没有差别', '关键是「怀孕前就开始吃」。胎儿的神经管在受孕后 28 天内就长合了。等你测出怀孕再吃，这段时间已经过去大半。所以打算要孩子，就提前 3 个月开始吃。同一篇汇总研究里，叶酸对唇腭裂、先天性心脏病、流产都没有明确效果，别指望它治别的', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-2', 'concept_archive_s27-2', 'claim_archive_s27-2', 'action', 'life_archive', '孕 13 周前去社区卫生服务中心建《母子健康手册》，把免费产检额度用掉', '27. 怀孕和生产：从发现怀孕到出院办证', '孕期至少五次产检，加上产后上门访视和产后 42 天检查，这些钱国家出。领的办法是怀孕 13 周以前去社区建一本《母子健康手册》。不去建，这几次免费的就白白错过。', '这 5 次是免费的下限，不是产检的全部。医院会按情况加做超声、血糖、胎心监护，这些要自己掏钱。建册越早，妊娠风险分级越早做出来。妊娠风险分级就是按风险高低给孕妇分档，查出是高危的，才能早点转到接得住的医院。人住在外区的，按现在住的地方建册，不用回户籍地', NULL, NULL, NULL, '不花钱，这属于国家基本公共卫生服务项目。要按孕周跑几趟', '《国家基本公共卫生服务规范（第三版）》里有孕产妇健康管理服务。辖区内的常住孕产妇可以做这些。孕早期健康检查 1 次，孕中期 2 次，孕晚期 2 次，产后访视 1 次，产后 42 天健康检查 1 次。孕 13 周前要去建册，同时做第 1 次产前检查。孕中期那两次分别在孕 16 至 20 周、孕 21 至 24 周。孕晚期那两次分别在孕 28 至 36 周、孕 37 至 40 周。地方公开的服务清单里，还包含第一次的一整套化验和产后抑郁筛查', '这 5 次是免费的下限，不是产检的全部。医院会按情况加做超声、血糖、胎心监护，这些要自己掏钱。建册越早，妊娠风险分级越早做出来。妊娠风险分级就是按风险高低给孕妇分档，查出是高危的，才能早点转到接得住的医院。人住在外区的，按现在住的地方建册，不用回户籍地', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-3', 'concept_archive_s27-3', 'claim_archive_s27-3', 'action', 'life_archive', '第一次产检就把艾滋病、梅毒、乙肝三项查掉，查出来也有免费的阻断', '27. 怀孕和生产：从发现怀孕到出院办证', '第一次产检就把艾滋病、梅毒、乙肝这三样查掉，检测不用自己掏钱。真查出来也不是绝路。国家免费给药、给方案，挡住病从母亲传给孩子的那条路，这叫母婴阻断。', '这三项越早查越有用，因为阻断和治疗都需要时间。艾滋病防治条例第三条还写明「任何单位和个人不得歧视艾滋病病毒感染者、艾滋病病人及其家属」，结婚、找工作、看病、上学这些合法权益受法律保护。日常的预防和检测见第 1 节。发生高危行为之后的暴露后阻断见第 13 节', NULL, NULL, NULL, '不花钱，预防母婴传播项目提供免费检测', '母婴传播就是病从母亲传给孩子。《预防艾滋病、梅毒和乙肝母婴传播工作规范（2020 年版）》有要求。在孕早期或者第一次产前检查的时候，医院要告知相关信息，并「提供适宜、规范的免费检测」，这三项检测不用自己掏钱。再根据结果提供检测后咨询或者转诊。查出阳性也不是绝路。《艾滋病防治条例》第四十四条规定，向感染艾滋病病毒的孕产妇「免费提供预防艾滋病母婴传播的治疗和咨询」。第四十三条要求提供阻断（不让病传给孩子）、治疗、产后访视、婴儿随访和检测等服务。母亲乙肝表面抗原阳性的，新生儿出生时要同时打乙肝疫苗和乙肝免疫球蛋白（见第 20 节第 2 条）', '这三项越早查越有用，因为阻断和治疗都需要时间。艾滋病防治条例第三条还写明「任何单位和个人不得歧视艾滋病病毒感染者、艾滋病病人及其家属」，结婚、找工作、看病、上学这些合法权益受法律保护。日常的预防和检测见第 1 节。发生高危行为之后的暴露后阻断见第 13 节', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-4', 'concept_archive_s27-4', 'claim_archive_s27-4', 'action', 'life_archive', '整个孕期一支烟一口酒都不要，家里人也别在屋里抽', '27. 怀孕和生产：从发现怀孕到出院办证', '孕期抽烟，孩子早产、生下来太小、唇腭裂的概率都往上走。孕期和生产时异常出血的风险直接翻一倍。婴儿猝死的风险也更高。家里人在屋里抽，一样算。什么时候戒都还来得及。', '别人在屋里抽，孕妇吸到的二手烟对胎儿一样算数。所以同住的家人也别在屋里抽。酒也一样：没有哪个喝酒的量是已知安全的，孕期最省事的做法就是一口不喝。烟酒对成年人自己的账见第 2 节', NULL, NULL, NULL, '不花钱，还能省下烟酒钱。难在让同住的人跟着一起戒', '美国疾病控制与预防中心的口径：孕期吸烟会让孩子「足月出生也可能过小」「可能早产」。它会「使孕期和分娩期异常出血的风险翻倍」。它会提高唇裂、腭裂等出生缺陷的风险。它还会「损害胎儿正在发育的肺和大脑，损害可持续到儿童期」。孕期吸烟的母亲生的婴儿，以及出生后接触烟雾的婴儿，婴儿猝死综合征的风险更高。官方建议是「最好在怀孕前就戒烟，但如果已经怀孕，戒了仍然有用」「什么时候戒都不晚」', '别人在屋里抽，孕妇吸到的二手烟对胎儿一样算数。所以同住的家人也别在屋里抽。酒也一样：没有哪个喝酒的量是已知安全的，孕期最省事的做法就是一口不喝。烟酒对成年人自己的账见第 2 节', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-5', 'concept_archive_s27-5', 'claim_archive_s27-5', 'action', 'life_archive', '有子痫前期高危因素的，孕 12 周后开始每天一片小剂量阿司匹林', '27. 怀孕和生产：从发现怀孕到出院办证', '子痫前期是孕期的一种高血压病。上一胎得过、怀多胎、有慢性高血压、孕前有糖尿病、有肾病或自身免疫病的人算高危。高危的人从孕 12 周起每天一片小剂量阿司匹林，子痫前期低约一成半，早产和孩子在生产前后死亡都低约两成。其他人别自己吃。', '算高危的有：上一胎得过子痫前期、怀的是双胎或者多胎、有慢性高血压。还有怀孕前就有 1 型或者 2 型糖尿病、有肾病，以及有系统性红斑狼疮、抗磷脂综合征这类自身免疫病。不在这几类里的不要自己吃。这个药要医生开处方，产检的时候把病史说清楚，让医生判断。国内卖的多是 100 毫克的肠溶片，按医嘱吃', NULL, NULL, NULL, '几十元。每天一片，要一直吃到生。难在天天不忘', '美国预防服务工作组给的是 B 级推荐：对子痫前期高危的人，在孕 12 周之后开始吃小剂量阿司匹林（81 毫克/天）来预防。子痫前期是孕期的一种高血压疾病。把多项研究合起来算，结果如下，95% CI 是可信范围。子痫前期 RR 0.85（95% CI 0.75 至 0.95，16 项研究），低约 15%。早产 RR 0.80（95% CI 0.67 至 0.95，13 项研究），低约 20%。围产期死亡 RR 0.79（95% CI 0.66 至 0.96，11 项研究），低约 21%；围产期死亡就是生产前后这段时间里的死亡。小于胎龄儿／宫内生长受限 RR 0.82（95% CI 0.68 至 0.99，16 项研究），低约 18%；说的是胎儿长得比同孕周的偏小', '算高危的有：上一胎得过子痫前期、怀的是双胎或者多胎、有慢性高血压。还有怀孕前就有 1 型或者 2 型糖尿病、有肾病，以及有系统性红斑狼疮、抗磷脂综合征这类自身免疫病。不在这几类里的不要自己吃。这个药要医生开处方，产检的时候把病史说清楚，让医生判断。国内卖的多是 100 毫克的肠溶片，按医嘱吃', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-6', 'concept_archive_s27-6', 'claim_archive_s27-6', 'action', 'life_archive', '孕 24 周及以后做一次妊娠期糖尿病筛查，别嫌喝糖水麻烦', '27. 怀孕和生产：从发现怀孕到出院办证', '妊娠期糖尿病就是怀孕之后才出现的血糖高。孕 24 周以后花半个上午，喝一次糖水、抽几次血，就能查出来。不查也不管，胎儿长得过大、难产、挨一刀、子痫前期和新生儿低血糖的风险都会往上走。', '查出来的人里，大多数靠调饮食和运动就能把血糖控住，需要打胰岛素的是少数。别因为怕查出来要打针，就跳过这一次。生完之后还要复查血糖：得过妊娠期糖尿病的人，以后得 2 型糖尿病的风险明显更高', NULL, NULL, NULL, '几十到一百多元。要空腹去，抽几次血，占掉半个上午', '美国预防服务工作组的 B 级推荐：对没有症状（自己没觉出不舒服）的孕妇，在孕 24 周及以后筛查妊娠期糖尿病。妊娠期糖尿病就是怀孕之后才出现的血糖高。只做一次筛查的，这一次要放在孕 24 周及以后。孕 24 周之前就筛查好不好，工作组的结论是现有证据不足以判断好处和坏处（I 级）。妊娠期糖尿病不管，会推高这几样的风险：巨大儿（胎儿长得过大）、难产、剖宫产、子痫前期和新生儿低血糖', '查出来的人里，大多数靠调饮食和运动就能把血糖控住，需要打胰岛素的是少数。别因为怕查出来要打针，就跳过这一次。生完之后还要复查血糖：得过妊娠期糖尿病的人，以后得 2 型糖尿病的风险明显更高', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-7', 'concept_archive_s27-7', 'claim_archive_s27-7', 'action', 'life_archive', '背下这张「立刻去医院」的清单，孕期和产后一年内都算数', '27. 怀孕和生产：从发现怀孕到出院办证', '任何一条出现，当天就去医院，别在家等一晚。头痛不好或越来越重、看东西变样、发烧到 38 ℃。手或脸肿得厉害、喘不上气、胸痛或心跳快。肚子剧痛不缓解、胎动停了或明显变少、阴道出血或流液。一条胳膊或腿又肿又痛、想伤害自己或孩子。产后一年内也算。', '这张清单的用处，是把「再忍忍」和「必须马上走」分开。头痛加上看东西发花，再加上上腹部疼，指向的是子痫前期（孕期的高血压疾病）。一条小腿又肿又痛，指向的是深静脉血栓（见第 13 节）。产后大出血按世界卫生组织的说法，可以在几小时内夺走一个健康女性的生命。任何一条出现就直接去医院，不要先在家等一晚', NULL, NULL, NULL, '不花钱。花五分钟记住，最好也让同住的人知道', '美国疾病控制与预防中心列出的孕产期紧急预警信号有这些：头痛一直不好或者越来越重、头晕或者晕过去、看东西变样、体温达到 38 ℃ 或更高；手或者脸肿得厉害、有伤害自己或者伤害孩子的念头、呼吸困难、胸痛或者心跳过快；恶心呕吐很厉害、肚子剧烈疼痛一直不缓解、孕期胎动停止或者明显减少；孕期阴道出血或者流出液体、产后阴道出血或者分泌物不正常；一条胳膊或者一条腿严重肿胀、发红或者疼痛。这些问题在产后一年内都可能发生，不是「出了月子就没事」', '这张清单的用处，是把「再忍忍」和「必须马上走」分开。头痛加上看东西发花，再加上上腹部疼，指向的是子痫前期（孕期的高血压疾病）。一条小腿又肿又痛，指向的是深静脉血栓（见第 13 节）。产后大出血按世界卫生组织的说法，可以在几小时内夺走一个健康女性的生命。任何一条出现就直接去医院，不要先在家等一晚', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-8', 'concept_archive_s27-8', 'claim_archive_s27-8', 'action', 'life_archive', '破水了就地平躺、垫高臀部、打 120，不要走动也不要洗澡', '27. 怀孕和生产：从发现怀孕到出院办证', '破水了不是慢慢收拾东西再出发。正确做法是就地躺下、把屁股垫高、打 120。站着走动，羊水流得更快，脐带可能跟着被冲下来。那是能要孩子命的急症。', '快生的三个征兆是规律宫缩、见红、破水。前两个都可以从容收拾东西，破水是唯一一个「当场躺下叫车」的。破水后洗澡、蹲厕所、自己开车，都是典型的错误做法。记下破水的时间和羊水的颜色，告诉医生。羊水发黄绿色，或者带着胎粪颗粒，提示胎儿窘迫（胎儿在子宫里缺氧）。同时还有规律宫缩、胎动明显减少、发热打寒战的，更要跟医生强调这是急诊', NULL, NULL, NULL, '不花钱', '北京市卫生健康委员会给的处置办法：发现破水后「马上找个地方平躺下来，防止羊水流出来」「不要随意走动」，并且「立即拨打 120 急救电话」。等车的时候通知家里人带东西到医院会合。医疗机构的科普进一步说明了为什么：人站着的时候羊水流失更快，胎儿的脐带可能跟着掉出来，这叫脐带脱垂，是危及胎儿的急症。所以要躺下，把臀部垫高，可以取左侧卧位', '快生的三个征兆是规律宫缩、见红、破水。前两个都可以从容收拾东西，破水是唯一一个「当场躺下叫车」的。破水后洗澡、蹲厕所、自己开车，都是典型的错误做法。记下破水的时间和羊水的颜色，告诉医生。羊水发黄绿色，或者带着胎粪颗粒，提示胎儿窘迫（胎儿在子宫里缺氧）。同时还有规律宫缩、胎动明显减少、发热打寒战的，更要跟医生强调这是急诊', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-9', 'concept_archive_s27-9', 'claim_archive_s27-9', 'action', 'life_archive', '想要无痛分娩就直接说，它不增加剖宫产的风险', '27. 怀孕和生产：从发现怀孕到出院办证', '无痛分娩就是在腰上打一针麻药，把生孩子的疼压下去。它比别的止疼办法更管用，也不会让你更可能挨一刀。「打了无痛腰疼一辈子」同样没有依据。现在它有了单独的收费项目，医院也更愿意做。', '「打无痛会腰疼一辈子」和「打无痛会难产要挨刀」这两条流传最广的说法都没有依据。Cochrane 把硬膜外镇痛和别的镇痛办法放在一起汇总，结论是它对剖宫产风险和长期腰痛都没有影响。真实的副作用是这些：血压偏低、发热、腿发软、尿不出来，以及第一、第二产程变长、更可能要用缩宫素。做不做自己定，但别因为传言放弃。能不能做还要看医院有没有 24 小时在场的麻醉医生，产检的时候就问清楚', NULL, NULL, NULL, '几百到一千多元，各地价格不一样。要提前问医院和麻醉科能不能做。难在得自己开口提', 'Cochrane 系统综述的结论是：硬膜外镇痛在减轻产痛、提高产妇对镇痛的满意度上，比不用硬膜外的办法更有效。无痛分娩用的就是硬膜外镇痛。同一篇还说，「硬膜外镇痛对剖宫产风险和长期腰痛没有影响」。器械助产（用器械把孩子接出来）增加的现象，在 2005 年以后的研究中已经看不到。2024 年起，国家医保局的产科类医疗服务价格项目立项指南，把「分娩镇痛」「导乐分娩」「亲情陪产」单独立了项。理由正是原先没有独立的价格项目，医院提供分娩镇痛的积极性被压低', '「打无痛会腰疼一辈子」和「打无痛会难产要挨刀」这两条流传最广的说法都没有依据。Cochrane 把硬膜外镇痛和别的镇痛办法放在一起汇总，结论是它对剖宫产风险和长期腰痛都没有影响。真实的副作用是这些：血压偏低、发热、腿发软、尿不出来，以及第一、第二产程变长、更可能要用缩宫素。做不做自己定，但别因为传言放弃。能不能做还要看医院有没有 24 小时在场的麻醉医生，产检的时候就问清楚', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 时间","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-10', 'concept_archive_s27-10', 'claim_archive_s27-10', 'action', 'life_archive', '没有医学指征就别主动要求剖宫产，也别为了挑日子开刀', '27. 怀孕和生产：从发现怀孕到出院办证', '世界卫生组织的说法是，一个地方的剖宫产比例超过 10% 以后，母亲和新生儿的死亡就不再继续下降。该剖的一定要剖。为了挑日子、怕疼去剖，只是白挨一次腹部大手术。', '医学上确实需要的时候，剖宫产是救命手术，该做就做，别硬扛。要避免的是医学上并不需要还去开刀，比如怕疼、挑吉时、算孩子上学的年龄。剖宫产是腹部大手术，恢复更慢，下一胎出现前置胎盘、胎盘植入和子宫破裂的风险更高。这直接影响你还想不想生第二个', NULL, NULL, NULL, '不花钱。难在顶住家里人的说法', '世界卫生组织 2015 年的声明：一个人群里的剖宫产率上升到约 10% 时，孕产妇和新生儿的死亡数会下降。超过 10% 之后，没有证据显示死亡率还能进一步改善。世界卫生组织同时强调，应当尽一切努力，为有需要的产妇提供剖宫产，而不是为了凑某个特定的比率', '医学上确实需要的时候，剖宫产是救命手术，该做就做，别硬扛。要避免的是医学上并不需要还去开刀，比如怕疼、挑吉时、算孩子上学的年龄。剖宫产是腹部大手术，恢复更慢，下一胎出现前置胎盘、胎盘植入和子宫破裂的风险更高。这直接影响你还想不想生第二个', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-11', 'concept_archive_s27-11', 'claim_archive_s27-11', 'action', 'life_archive', '怀孕前就确认生育保险的参保状态，未就业的配偶也能报生育医疗费用', '27. 怀孕和生产：从发现怀孕到出院办证', '单位交了生育保险，生孩子的医疗费和产假期间的津贴都从这笔基金里出。配偶没工作的，医疗费这一块也能报。参保月数够不够、在外地生要不要先备案，都得提前问，事后补不了。', '两件事要提前问清楚，因为事后补不了。一是连续参保的月数够不够：各地都定了最低月数，不够就享受不了。二是不在参保地生的，要不要先办异地生育备案：没备案的可能只能自己先垫钱，回来再手工报销，甚至报不了。产假天数和生育津贴怎么算见第 18 节第 2 条', NULL, NULL, NULL, '不花钱。打一次社保或者医保的咨询电话', '《社会保险法》第五十四条：用人单位已经缴纳生育保险费的，其职工享受生育保险待遇。职工没有工作的配偶，按照国家规定享受生育医疗费用待遇，所需资金从生育保险基金中支付。说白了，单位交了生育保险，职工本人能享受待遇，职工那位没工作的配偶生孩子的医疗费，也能从这笔基金里出。生育保险待遇分两块：一块是生育医疗费用，就是生孩子这件事本身的医疗费；另一块是生育津贴，就是产假期间发给你的那笔钱。第五十六条列明了能领生育津贴的三种情形：女职工生育享受产假、享受计划生育手术休假、法律法规规定的其他情形。生育津贴「按照职工所在用人单位上年度职工月平均工资计发」，算的是你所在单位去年的职工月平均工资，不是你自己的工资', '两件事要提前问清楚，因为事后补不了。一是连续参保的月数够不够：各地都定了最低月数，不够就享受不了。二是不在参保地生的，要不要先办异地生育备案：没备案的可能只能自己先垫钱，回来再手工报销，甚至报不了。产假天数和生育津贴怎么算见第 18 节第 2 条', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-12', 'concept_archive_s27-12', 'claim_archive_s27-12', 'action', 'life_archive', '出院前把《出生医学证明》办掉，名字提前想好、别写错字', '27. 怀孕和生产：从发现怀孕到出院办证', '这张证是上户口、参保、上学的前置件，而且只有接生的那家机构能第一次开。出了院再回头补，要另走一套流程、多交材料。名字里的字，先确认户籍系统打得出来。', '填之前把父母姓名、身份证号和孩子姓名逐字核对一遍。姓名用字要能在户籍系统里打得出来，生僻字以后办事会很麻烦。改名和改证都要走补发或者换发，比当场核对麻烦得多。证拿到手就单独收好，和户口本、身份证一样要紧', NULL, NULL, NULL, '不花钱。办出院手续的时候顺手就办了', '《母婴保健法》第二十三条：医疗保健机构和从事家庭接生的人员，按照国务院卫生行政部门的规定，出具统一制发的新生儿出生医学证明。这张证是后面所有事的前置条件：上户口、参保、办医保卡、入园入学都要它。而且第一次签发只能由接生的机构办。出了院再回头补办，要走另一套流程，还需要额外的证明材料', '填之前把父母姓名、身份证号和孩子姓名逐字核对一遍。姓名用字要能在户籍系统里打得出来，生僻字以后办事会很麻烦。改名和改证都要走补发或者换发，比当场核对麻烦得多。证拿到手就单独收好，和户口本、身份证一样要紧', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-13', 'concept_archive_s27-13', 'claim_archive_s27-13', 'action', 'life_archive', '新生儿足跟血筛查和听力筛查都别拒绝', '27. 怀孕和生产：从发现怀孕到出院办证', '扎一次足跟血、做一次听力测试，能在孩子看起来完全正常的时候，查出甲减、苯丙酮尿症和听力障碍。等症状显出来，智力上的损害已经补不回来了。', '办法第十一条要求，筛查前要把项目、条件、方式、灵敏度（能查出多少）和费用如实告诉监护人，并签字同意。所以你会拿到一张知情同意书。签之前看清楚：哪些是国家规定的病种，哪些是自费的加项。初筛阳性不等于确诊，绝大多数复查一次就排除了，别在这一步先崩溃。听力初筛没过的要按通知去复筛，别自己判断「孩子听得见就算了」', NULL, NULL, NULL, '多数地区免费，或者几十元。有些扩展项目要自己掏钱。孩子出生后扎一次足跟', '《新生儿疾病筛查管理办法》第三条：「全国新生儿疾病筛查病种包括先天性甲状腺功能减低症、苯丙酮尿症等新生儿遗传代谢病和听力障碍。」这两类病有个共同点：早期完全看不出异常，等到症状明显的时候，智力损害已经不可逆了。而早发现早干预效果很好，办法是补充甲状腺素、喝特殊配方奶、戴助听器或者装人工耳蜗。第十条规定，筛查结果是阳性的，机构应当及时通知监护人去确诊', '办法第十一条要求，筛查前要把项目、条件、方式、灵敏度（能查出多少）和费用如实告诉监护人，并签字同意。所以你会拿到一张知情同意书。签之前看清楚：哪些是国家规定的病种，哪些是自费的加项。初筛阳性不等于确诊，绝大多数复查一次就排除了，别在这一步先崩溃。听力初筛没过的要按通知去复筛，别自己判断「孩子听得见就算了」', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 高","口径 死亡率","钱 少","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-14', 'concept_archive_s27-14', 'claim_archive_s27-14', 'action', 'life_archive', '拿到出生医学证明就给孩子办居民医保，别等落完户', '27. 怀孕和生产：从发现怀孕到出院办证', '拿到出生证就能在网上给孩子参保，不用等落户。参上了，出院时的住院费当场就能报。新生儿的住院费不低，参保和没参保差别很大。', '早产、黄疸照蓝光、新生儿肺炎，这些是新生儿住院的常见原因，动辄上万元，参保和不参保差别很大。各地对「出生后多少天内参保，可以从出生那天起享受待遇」的规定不完全一样。具体怎么执行，以当地医保部门说的为准。出院前打 12393 问一句最省事', NULL, NULL, NULL, '一年交一次居民医保保费，几百元', '中国政府网 2024 年的口径：「新生儿凭出生医学证明就可以在线上参保」，不必先落户。「新生儿出院以后就能够直接报销医药费用」。以前的做法是落了户才能参保，住院费得先全额垫付，再回头报销。参保缴费的平均办理时长，也从年初的 28.7 个工作日压减到 6.4 个工作日', '早产、黄疸照蓝光、新生儿肺炎，这些是新生儿住院的常见原因，动辄上万元，参保和不参保差别很大。各地对「出生后多少天内参保，可以从出生那天起享受待遇」的规定不完全一样。具体怎么执行，以当地医保部门说的为准。出院前打 12393 问一句最省事', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 金钱","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-15', 'concept_archive_s27-15', 'claim_archive_s27-15', 'action', 'life_archive', '孩子出生后一个月以内去派出所申报出生登记', '27. 怀孕和生产：从发现怀孕到出院办证', '法律给的是一个月，不是「有空再说」。落户卡着后面的打疫苗、入园、入学和办身份证。越往后拖，要补的材料越多。', '带齐这些：出生医学证明、父母双方的身份证和户口本、结婚证。跟父亲落户还是跟母亲落户可以自己选，但两个地方的政策不一样，学区和参保地都受影响。去之前想清楚，改起来麻烦。没结婚生的孩子，同样可以申报出生登记', NULL, NULL, NULL, '不花钱。跑一趟派出所的户籍窗口', '《户口登记条例》第七条：「婴儿出生后一个月以内，由户主、亲属、抚养人或者邻居向婴儿常住地户口登记机关申报出生登记。」这是法律定的时限，不是建议。落户是后面这些事的前置条件：打疫苗、入园、入学、办身份证。越往后拖，需要补的材料越多', '带齐这些：出生医学证明、父母双方的身份证和户口本、结婚证。跟父亲落户还是跟母亲落户可以自己选，但两个地方的政策不一样，学区和参保地都受影响。去之前想清楚，改起来麻烦。没结婚生的孩子，同样可以申报出生登记', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 自由","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s27-16', 'concept_archive_s27-16', 'claim_archive_s27-16', 'action', 'life_archive', '产后 42 天那次复查别跳过，它同时是产后抑郁的筛查', '27. 怀孕和生产：从发现怀孕到出院办证', '这次复查不花钱，含血常规、白带常规，还包含一次产后抑郁筛查。产后一年内都可能出大问题，别觉得出了月子就安全了。', '产后抑郁不是矫情，靠家里人劝一句「想开点」也解决不了。它有专门的筛查问卷，有治疗，可以恢复。有自杀念头时的处置见第 1 节。孩子生下来确实养不了时的合法出路见第 9 节第 20 条。这次复查还会看伤口长得怎么样、子宫恢复得怎么样、盆底功能好不好。避孕方案也在这次谈：产后不来月经，不等于不会怀孕', NULL, NULL, NULL, '不花钱，属于基本公共卫生服务。占半天时间。难在刚出月子懒得动', '《国家基本公共卫生服务规范（第三版）》的孕产妇健康管理里，产后有 1 次产后访视和 1 次产后 42 天健康检查。地方公开的服务清单里，这一次含化验（血常规、白带常规）和 1 次产后抑郁筛查。产后一年内都可能出现严重并发症。第 7 条那张「立刻去医院」的清单里，「有伤害自己或伤害孩子的念头」「产后阴道出血或异常分泌物」「一侧肢体严重肿痛」都属于产后', '产后抑郁不是矫情，靠家里人劝一句「想开点」也解决不了。它有专门的筛查问卷，有治疗，可以恢复。有自杀念头时的处置见第 1 节。孩子生下来确实养不了时的合法出路见第 9 节第 20 条。这次复查还会看伤口长得怎么样、子宫恢复得怎么样、盆底功能好不好。避孕方案也在这次谈：产后不来月经，不等于不会怀孕', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"27. 怀孕和生产：从发现怀孕到出院办证","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-1', 'concept_archive_s28-1', 'claim_archive_s28-1', 'action', 'life_archive', '不要用极端节食、断食或催吐来控制体重，要减就从运动那一侧减', '28. 别为了外形把身体搞坏', '神经性厌食的人，死亡概率大约是同龄人的 5.9 倍。每 1000 个人跟一年，死 5.1 个。死的人里每五个有一个是自杀。而它的入口就是节食：跟踪 44 所中学的学生三年，严重节食的女生出现进食障碍的概率是不节食的 18 倍。想控制体重就多运动，别少吃到饿。', '这里说的「严重节食」，指的是长期把吃的压到远低于身体需要，不是指少吃一顿或者不吃夜宵。已经出现催吐、暴食之后自责、反复称重停不下来的，去精神科或者综合医院的临床心理科看。这是有规范治疗办法的病，不是意志力的问题。BMI 与死亡率的关系见第 2 节第 32 条，那条讲长期体重区间，不讲减重手段。', NULL, NULL, NULL, '不花钱。反过来还省下买减肥产品的钱。', '36 项研究合起来算。神经性厌食这一批人累计被跟踪了 166,642 人年（每人被跟踪的年数加总）。他们的标准化死亡比是 5.86，即死亡概率约为同龄人的 5.9 倍。每 1000 人年死亡 5.1 例，就是 1000 个人跟一年死 5.1 个。死的人里约 1/5 死于自杀。贪食症的标准化死亡比是 1.93，其他进食障碍是 1.92，即各约为同龄人的 1.9 倍。另一项研究在澳大利亚维多利亚州的 44 所中学做，跟踪 14–15 岁学生 3 年、同一批学生三年里前后查了 6 波。女生新发进食障碍 21.8/1000 人年，即 1000 个女生跟一年新出 21.8 例。严重节食的女生发病风险是不节食者的 18 倍，中度节食者是 5 倍。再校正既往节食与精神症状，把「以前就节食过」和「本来就有精神症状」的影响扣掉。扣掉之后，BMI（体重除以身高平方算出的胖瘦指标）、运动量和性别都不再预测新发进食障碍。作者结论是「在青少年中用运动而非限食控制体重，发生进食障碍的风险似乎更低」', '这里说的「严重节食」，指的是长期把吃的压到远低于身体需要，不是指少吃一顿或者不吃夜宵。已经出现催吐、暴食之后自责、反复称重停不下来的，去精神科或者综合医院的临床心理科看。这是有规范治疗办法的病，不是意志力的问题。BMI 与死亡率的关系见第 2 节第 32 条，那条讲长期体重区间，不讲减重手段。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-2', 'concept_archive_s28-2', 'claim_archive_s28-2', 'action', 'life_archive', '打针、埋线、开刀之前查两样：机构许可证上有没有「医疗美容」，动手的人是不是主诊医师', '28. 别为了外形把身体搞坏', '动针、动刀、用医疗器械，会破皮或进到身体里的，就算看病。只能在许可证上写了「医疗美容」的机构做，动手的必须是注册过的执业医师。在美容院、工作室、酒店房间里做属于非法行医。动手的人情节严重判 3 年以下，伤了人判 3 到 10 年，致人死亡判 10 年以上。', '同一份办法第十六条还规定，医美项目只能在美容医疗机构里做，或者在设了医疗美容科室的医院、诊所里做。所以上门打针、在工作室里私下操作，光看地点就已经不合规。第二十条写明，未成年人这类还不能自己作主的人要做医美，必须经监护人同意，要家长签字。做脸、按摩、美甲属于生活美容，不归这套规矩管。但只要动到针和刀，就算医疗美容。', NULL, NULL, NULL, '不花钱。查这两张证只要几分钟。机构应该把《医疗机构执业许可证》挂在大厅里。医生的资质可以在卫健部门的执业医师查询里核对。', '《医疗美容服务管理办法》第二条给医疗美容下了定义。原文是「运用手术、药物、医疗器械以及其他具有创伤性或者侵入性的医学技术方法对人的容貌和人体各部位形态进行的修复与再塑」。说白了，只要破皮、进针、进到身体里，就按看病算。第八条和第二十四条要求先取得《医疗机构执业许可证》，并经登记机关核准医疗美容诊疗科目，才能开展。许可证上没写「医疗美容」这一项，就不能做。第十一条要求主诊医师（动手的那位医生）具有执业医师资格并且注册过。做美容外科的还要有 6 年以上相关专业临床工作经历，美容牙科 5 年以上，美容中医科与美容皮肤科各 3 年以上。第二十条要求动手之前书面告知适应症、禁忌症（什么情况适合做、什么情况不能做）、医疗风险和注意事项，并取得签字同意。《刑法》第三百三十六条管的是非法行医。非法行医就是没有医生执业资格的人给人打针、动刀、看病。情节严重的，处 3 年以下有期徒刑、拘役或者管制，并处或者单处罚金。严重损害就诊人身体健康的，处 3 年以上 10 年以下有期徒刑并处罚金。造成就诊人死亡的，处 10 年以上有期徒刑并处罚金', '同一份办法第十六条还规定，医美项目只能在美容医疗机构里做，或者在设了医疗美容科室的医院、诊所里做。所以上门打针、在工作室里私下操作，光看地点就已经不合规。第二十条写明，未成年人这类还不能自己作主的人要做医美，必须经监护人同意，要家长签字。做脸、按摩、美甲属于生活美容，不归这套规矩管。但只要动到针和刀，就算医疗美容。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-3', 'concept_archive_s28-3', 'claim_archive_s28-3', 'action', 'life_archive', '面部填充避开鼻背、眉间、额头这几个部位，更别为省钱找非正规注射', '28. 别为了外形把身体搞坏', '打填充针后失明的人里，一半多打的是鼻部，其次是眉间、额头和法令纹，八成多用的是玻尿酸。失明的人只有两成视力完全恢复，一成多部分恢复，将近两成还伤到了脑。目前没有一种抢救办法稳定管用，只能事先避开这些部位。', '这些数字是把期刊报过的病例一例一例数出来的。里面只有出事的人数，没有打针的总人数。所以算不出「打一针有多大概率失明」，只看得出哪些部位出事多、事后基本救不回来。证据记 B 级也是因为这个。正规机构降低风险的做法本来就是常规：先查清要打的地方底下血管怎么走，用钝头针不用尖针，边退针边少量推，事先备好透明质酸酶。每一样都要求动手的是受过训练的医生，这也是别找非正规渠道的理由。做之前先按本节第 2 条（查机构许可证和主诊医师）核一遍。', NULL, NULL, NULL, '不花钱。只是换个部位打，或者不做。', '把全世界期刊报过的病例汇总起来算。2015 年 1 月到 2018 年 9 月新增 48 例注射填充后部分或完全视力丧失。出事最多的部位是鼻部，占 56.3%。接下来是眉间 27.1%、前额 18.8%、鼻唇沟（法令纹那道沟）14.6%。81.3% 的病例填充物为透明质酸，就是玻尿酸。43.8% 出现皮肤改变。18.8% 出现中枢神经系统并发症（脑出了问题）。10 例（20.8%）视力完全恢复，8 例（16.7%）部分恢复，剩下的没恢复。作者结论为各家的处理方式差得很远，没有一种治疗被证明能持续奏效', '这些数字是把期刊报过的病例一例一例数出来的。里面只有出事的人数，没有打针的总人数。所以算不出「打一针有多大概率失明」，只看得出哪些部位出事多、事后基本救不回来。证据记 B 级也是因为这个。正规机构降低风险的做法本来就是常规：先查清要打的地方底下血管怎么走，用钝头针不用尖针，边退针边少量推，事先备好透明质酸酶。每一样都要求动手的是受过训练的医生，这也是别找非正规渠道的理由。做之前先按本节第 2 条（查机构许可证和主诊医师）核一遍。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-4', 'concept_archive_s28-4', 'claim_archive_s28-4', 'action', 'life_archive', '不要买承诺「快速瘦」的减肥药、减肥咖啡、瘦身糖果和酵素梅', '28. 别为了外形把身体搞坏', '这类产品里最常查出偷加的是西布曲明，它原来是减肥药，2010 年在中国被停掉了。有心脏病或糖尿病的超重的人吃了三年多，没致命的心梗高约三成，中风高约三成六。体重只多减了 1.7 公斤。抽检查出来的时候，你已经吃下去了。', 'SCOUT 招的是本来就有心脏病或者糖尿病的高危人群。这个试验没有证明健康年轻人吃了也一样出事。但正因为分不清谁是高危，监管才干脆让它退市。另一种常被偷加的成分是酚酞，它本来是泻药，长期吃多了会打乱体内电解质、诱发心律失常。怎么判断：正经减肥药是处方药，在药店和医院能查到批准文号。打着「咖啡」「糖果」「梅子」「代餐」旗号卖、又承诺一周掉几斤的，按定义就不该有药效，有药效就说明加了东西。国食药监办〔2010〕432 号的原文在国家药监局网站，本机打开一直报 412 错误，所以改引省级监管部门的转述页。「风险大于效益」和「2010 年 10 月停止生产销售使用」两句可以在那里逐字核对。', NULL, NULL, NULL, '不花钱。反过来还省下买这些产品的钱。难的是要接受没有「一周掉几斤」这回事。', 'SCOUT 试验招了 9,804 人。他们都是 55 岁以上、超重或肥胖，并且有心血管病或 2 型糖尿病。这些人抽签分成吃药和不吃药两组，平均治疗 3.4 年。主要终点是事先定好要数的几件坏事：非致死性心梗、非致死性卒中（中风）、心脏骤停后被救回来、心血管死亡。这几件事的发生率是 11.4% vs 10.0%。HR 1.16（95% CI 1.03–1.31，P=0.02），吃药的人出事概率高约一成六。真实值大致落在高 3% 到高 31% 之间。非致死性心梗 4.1% vs 3.2%，HR 1.28（1.04–1.57），高约三成。非致死性卒中 2.6% vs 1.9%，HR 1.36（1.04–1.77），高约三成六。心血管死亡与全因死亡未增加，全因就是各种原因加起来。抽签之后，西布曲明组平均多减重 1.7 kg。原国家食品药品监督管理局根据安全性评估认为「减肥治疗的风险大于效益」，2010 年 10 月通知停止西布曲明制剂及原料药的生产、销售、使用。西布曲明与酚酞均禁止添加于食品，保健食品也算在内', 'SCOUT 招的是本来就有心脏病或者糖尿病的高危人群。这个试验没有证明健康年轻人吃了也一样出事。但正因为分不清谁是高危，监管才干脆让它退市。另一种常被偷加的成分是酚酞，它本来是泻药，长期吃多了会打乱体内电解质、诱发心律失常。怎么判断：正经减肥药是处方药，在药店和医院能查到批准文号。打着「咖啡」「糖果」「梅子」「代餐」旗号卖、又承诺一周掉几斤的，按定义就不该有药效，有药效就说明加了东西。国食药监办〔2010〕432 号的原文在国家药监局网站，本机打开一直报 412 错误，所以改引省级监管部门的转述页。「风险大于效益」和「2010 年 10 月停止生产销售使用」两句可以在那里逐字核对。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-5', 'concept_archive_s28-5', 'claim_archive_s28-5', 'action', 'life_archive', '不要用合成代谢类固醇（「增肌针」「口服药」）来长肌肉', '28. 别为了外形把身体搞坏', '健身房兴奋剂检测阳性的男性，死亡风险是同龄人的 3 倍，每年跑医院的次数多一倍多。痤疮、男性乳房发育、勃起功能障碍，每十个用药的人里至少一个中招。这类药在中国是处方药，能卖给你的渠道本身就在违法。', '争议：这是跟踪一群人看结果的研究，不是随机分组试验。用药的人本身可能在别的方面也更冒险，3 倍这个数不能全记到药头上。真实倍数可能低到 1.3，也可能高到 7.0，范围很宽。但「痤疮、男性乳房发育、勃起功能障碍各有一成以上的人中招」是眼睛能看见的副作用，受这种偏差影响较小。这类药在法规里写作「蛋白同化制剂」，看到这四个字说的就是它。普通蛋白粉、肌酸不在本条之内。麻烦的是「宣称增肌特别快」的产品可能偷加成分。判断方法和减肥产品那条一样（第 4 条，不买承诺快速瘦的减肥药）：正经药是处方药、有批准文号可查。靠「增肌粉」「营养品」名义卖、又承诺几周见效的，真有效就是加了东西。', NULL, NULL, NULL, '不花钱，还省下药钱。难的是要接受肌肉长得慢。', '丹麦回头翻档案，给每个用药的人配同龄对照。用药的是 2006-01-03 至 2018-03-01 健身房兴奋剂检测雄激素类固醇阳性的 545 名男性，配了 5,450 名对照。另外又用 644 名拒绝受检者和 6,440 名对照复核了一遍。结果：使用者死亡率为对照的 3 倍，HR 3.0（95% CI 1.3–7.0），真实倍数大致在 1.3 到 7 之间。每年住院或就诊次数的中位数是 0.81 次 vs 0.36 次（P&lt;0.0001）。中位数就是一半人多于、一半人少于这个数。这个 P 值说明这个差别几乎不可能是碰巧。痤疮（长痘）、男性乳房发育、勃起功能障碍各影响超过 10% 的使用者，即每十个用药的人里至少一个中招，都明显高于对照（P&lt;0.0001）。复核的那一批结果一致。《反兴奋剂条例》第七条：国家对兴奋剂目录所列禁用物质实行严格管理，任何单位和个人不得非法生产、销售、进出口。同一条例规定蛋白同化制剂、肽类激素实行处方药管理，即只能凭医生处方买，蛋白同化制剂是法规里对这类药的叫法', '争议：这是跟踪一群人看结果的研究，不是随机分组试验。用药的人本身可能在别的方面也更冒险，3 倍这个数不能全记到药头上。真实倍数可能低到 1.3，也可能高到 7.0，范围很宽。但「痤疮、男性乳房发育、勃起功能障碍各有一成以上的人中招」是眼睛能看见的副作用，受这种偏差影响较小。这类药在法规里写作「蛋白同化制剂」，看到这四个字说的就是它。普通蛋白粉、肌酸不在本条之内。麻烦的是「宣称增肌特别快」的产品可能偷加成分。判断方法和减肥产品那条一样（第 4 条，不买承诺快速瘦的减肥药）：正经药是处方药、有批准文号可查。靠「增肌粉」「营养品」名义卖、又承诺几周见效的，真有效就是加了东西。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-6', 'concept_archive_s28-6', 'claim_archive_s28-6', 'action', 'life_archive', '要吃减肥药就去医院拿处方，别在不用处方就发货的网店买', '28. 别为了外形把身体搞坏', '处方药必须凭处方卖，网上卖也必须有真实处方并且实名。不问诊、不要处方、下单就发货的，要么卖的不是它说的药，要么这家店在违规。出了事，没人替你的剂量和禁忌负责。挂一次号几十块钱，就有医生替你把这一关。', '法条可以逐字核对，但「按处方吃比自己买着吃能少出多少事」没人做过量化研究，所以按「难以量化」记 B 级。本节第 5、7 条说的类固醇和性激素，也走同一套规则。真到了该靠药减重的程度，医生会先看体重指数、身上有没有别的病、有没有不能用药的情况，再定吃不吃、吃哪种。这个判断是买不到的。', NULL, NULL, NULL, '一次挂号，加上来回跑一趟。几十元，半天时间。', '《药品经营和使用质量监督管理办法》规定，药品零售企业要遵守处方药与非处方药分类管理制度。这个制度就是把药分成两类，一类必须凭医生处方买，一类可以自己买。药店要按规定凭处方销售处方药，处方保留不少于五年。药师或者其他药学技术人员不在岗时应挂牌告知，没经过他们审核不得销售处方药。处方药不得开架销售，不能摆在货架上由顾客自己拿。《药品网络销售监督管理办法》第九条规定，通过网络向个人销售处方药的，应当确保处方来源真实、可靠并实行实名制。第十条要求在每个药品展示页面下突出显示风险警示信息。通过处方审核前，不得展示说明书，也不得提供购买服务，处方没审过，页面上连买的按钮都不该给。第八条规定，国家实行特殊管理的药品不得在网络上销售。这类药包括疫苗、血液制品、麻醉药品、精神药品、医疗用毒性药品、放射性药品、药品类易制毒化学品', '法条可以逐字核对，但「按处方吃比自己买着吃能少出多少事」没人做过量化研究，所以按「难以量化」记 B 级。本节第 5、7 条说的类固醇和性激素，也走同一套规则。真到了该靠药减重的程度，医生会先看体重指数、身上有没有别的病、有没有不能用药的情况，再定吃不吃、吃哪种。这个判断是买不到的。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-7', 'concept_archive_s28-7', 'claim_archive_s28-7', 'action', 'life_archive', '性激素类药只在医生开方并定期复查的前提下用，不要网购、不要自己加量', '28. 别为了外形把身体搞坏', '这条不讨论该不该用，只讨论怎么用。用雌激素的跨性别女性，血管里长血块的比同龄人明显多，每一千人两年多出约 4 个，八年多出约 17 个。这类风险得靠定期复查盯着，网购药、自己调量就没人替你查。', '研究者自己写明了这项研究的短处：有多少人是在医院系统外自己买的药，他们查不到，所以「有没有用药」这条线本来就划不干净。所以用药更该放进正规随访里。这项研究看的只是血管出没出事，不回答激素治疗该不该用、用了有什么好处，那是另一套证据。所有用到性激素的场合都一样，包括避孕药、更年期激素治疗、睾酮补充。凡是自己网购、照着网帖调量、从不查血栓和肝肾指标的，风险都出在「没人盯着」这一段，和为什么用药无关。国内的正规路子是去正规医疗机构的内分泌科或者相应专科，做评估、开方、复查。', NULL, NULL, NULL, '定期挂号，加上抽血复查。一年几百元，占掉几个半天。', '研究者从 Kaiser Permanente 这家医疗集团的电子病历里跟踪了一批人。其中 2,842 名跨性别女性、2,118 名跨性别男性。平均跟踪 4.0 年与 3.6 年。每个人都按出生年、种族、就诊点和入组时间配了约 10 倍的顺性别对照，一共 48,686 名顺性别男性与 48,775 名顺性别女性。跨性别女性的静脉血栓栓塞（血管里长血块堵住）比对照多。和顺性别男性比，2 年是每 1000 人 4.1 例（95% CI 1.6–6.7）。8 年是 16.7 例（6.4–27.5）。算下来，1000 个人里两年多出 4.1 例，八年多出 16.7 例。和顺性别女性比，这两个数是 3.4（1.1–5.6）与 13.7（4.1–22.7）。缺血性卒中（血管堵住那一类中风）与心肌梗死总体各组接近。但在跟踪期内才开始激素治疗的跨性别女性中，静脉血栓与缺血性卒中的差异更明显。跨性别男性的证据不够，下不了结论。作者结论为「这些结果可能提示需要长期警惕跨性别激素中雌激素的血管副作用」', '研究者自己写明了这项研究的短处：有多少人是在医院系统外自己买的药，他们查不到，所以「有没有用药」这条线本来就划不干净。所以用药更该放进正规随访里。这项研究看的只是血管出没出事，不回答激素治疗该不该用、用了有什么好处，那是另一套证据。所有用到性激素的场合都一样，包括避孕药、更年期激素治疗、睾酮补充。凡是自己网购、照着网帖调量、从不查血栓和肝肾指标的，风险都出在「没人盯着」这一段，和为什么用药无关。国内的正规路子是去正规医疗机构的内分泌科或者相应专科，做评估、开方、复查。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-8', 'concept_archive_s28-8', 'claim_archive_s28-8', 'action', 'life_archive', '如果「觉得自己丑」已经到反复照镜子、反复想改的程度，先做一次体像评估再谈手术', '28. 别为了外形把身体搞坏', '去做整形手术的人里约 15% 有躯体变形障碍，就是把别人基本看不出的缺陷放大到影响生活。去皮肤科求美的人里约 13%，两边都是七成多为女性。这种人做完一处又会盯上下一处，手术解决不了。先挂一次号看看自己是不是这种情况，再决定动不动手术。', '各项研究测出来的比例从 2.21% 一直到 56.67%，差得极大。原因是用的问卷和调查的人群都不一样。所以只能读出「这个比例不低、值得先筛一次」，不能把 15.04% 当准确数字，记 B 级也是因为这个。想做医美的人绝大多数没有心理问题。本条针对的是「反复、持续、已经影响到工作和社交」这一小部分人，手术解决不了他们的问题。判断线索有这几条：一天里花很长时间检查或者遮挡某个部位，因此回避社交或者拍照，做完一处又盯上下一处。', NULL, NULL, NULL, '去精神科或者临床心理科挂一次号，几十元。难的是在约手术之前先去这一趟。', '按规矩把 33 项研究找齐再合起来算。整形外科就诊者中，躯体变形障碍（把别人基本看不出的缺陷放大到影响生活）患病率 15.04%，各项研究在 2.21%–56.67% 之间。换成人数，每 100 个去做整形的人里约 15 个符合，单看各项研究则从 2 个到 57 个不等。这批人平均年龄 34.54±12.41 岁，后一个数是上下浮动的幅度，74.38% 为女性。皮肤科就诊者是 12.65%，各项研究在 4.52%–35.16% 之间，平均年龄 27.79±9.03 岁，76.09% 为女性。作者建议整形外科医师与皮肤科医师主动评估、把高风险的人认出来，并安排几个科室一起管', '各项研究测出来的比例从 2.21% 一直到 56.67%，差得极大。原因是用的问卷和调查的人群都不一样。所以只能读出「这个比例不低、值得先筛一次」，不能把 15.04% 当准确数字，记 B 级也是因为这个。想做医美的人绝大多数没有心理问题。本条针对的是「反复、持续、已经影响到工作和社交」这一小部分人，手术解决不了他们的问题。判断线索有这几条：一天里花很长时间检查或者遮挡某个部位，因此回避社交或者拍照，做完一处又盯上下一处。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","B 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s28-9', 'concept_archive_s28-9', 'claim_archive_s28-9', 'action', 'life_archive', '矫正牙齿要找有正畸资质的医生当面检查、按时复诊，别网购牙套自己在家戴', '28. 别为了外形把身体搞坏', '透明牙套在国内是二类医疗器械，说明书要求在有正畸资质的医生指导下戴、定期复诊。美国药监部门说没批准过不经牙医开方就直接卖给个人的牙套。没人当面检查，可能咬合变歪、牙齿移错位置、疼痛，甚至掉牙。', '收益量级定为小，因为没找到出事比例，只能凭后果判断。国内药监和卫健部门针对「网购牙套在家自己戴」的风险提示没有找到，所以本条主要靠注册要求和 FDA 的说法。正畸属于医疗行为，做医疗美容性质的牙齿矫正，机构许可证要有对应科目，动手的医生要有资质，查法见本节第 2 条（机构许可证、主诊医师）。四部门 2023 年的口腔医疗通知也点名要严惩无证机构和聘用非卫生技术人员看牙。正畸医保不报，见第 24 节第 12 条（种牙之前先问清包干价）', NULL, NULL, NULL, '比网购多出挂号和复诊的钱，每隔一段时间要去一趟诊所。难在疗程常常一两年，要坚持复诊。', '国家药监局医疗器械技术审评中心 2022 年的《无托槽矫治器注册审查指导原则》说，这种牙套「管理类别为Ⅱ类」。它要求说明书写明「治疗过程中需在具有口腔正畸专业资质医师的指导下进行佩戴」，还要写「进食、刷牙及定期复诊的要求」。产品名称「不建议含有“隐形”等虚无、假设的概念性名称」。美国食品药品监督管理局（FDA）的说法是：「The FDA has not authorized clear aligners that are sold directly to consumers without a prescription and supervision by a dentist or orthodontist」，意思是不经牙医开方和监督、直接卖给个人的透明牙套，它一个都没批准过。FDA 还说：「In-person examination by a dentist or orthodontist can help lower the risks of uneven bite, unintended tooth movement, pain, and tooth loss」，也就是牙医当面检查能降低咬合不齐、牙齿移位、疼痛和掉牙的风险。开始戴以后定期当面复诊，才能确认牙在按计划安全移动。这两份都是监管文件，没有给出出事的比例', '收益量级定为小，因为没找到出事比例，只能凭后果判断。国内药监和卫健部门针对「网购牙套在家自己戴」的风险提示没有找到，所以本条主要靠注册要求和 FDA 的说法。正畸属于医疗行为，做医疗美容性质的牙齿矫正，机构许可证要有对应科目，动手的医生要有资质，查法见本节第 2 条（机构许可证、主诊医师）。四部门 2023 年的口腔医疗通知也点名要严惩无证机构和聘用非卫生技术人员看牙。正畸医保不报，见第 24 节第 12 条（种牙之前先问清包干价）', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"28. 别为了外形把身体搞坏","C 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-1', 'concept_archive_s29-1', 'claim_archive_s29-1', 'action', 'life_archive', '亲人刚走的那几天别一个人待着，有心脏病、高血压、糖尿病的照常吃药，胸口压着疼就叫 120', '29. 遭遇重大打击之后', '亲人去世后头一天，心梗发作的概率是平时的 21.1 倍，之后一天比一天低。60 到 89 岁的人在伴侣去世后 30 天内，心梗或中风的比例大约翻倍，一个月后回落。本来就有心血管病的人，这几天别停药。胸口压着疼、喘不上气、一侧手脚没力，立刻打 120。', '药盒交给别人管，别靠自己记。这几天别开长途。别靠喝酒扛过去，酒的账见第 2 节。心梗、中风怎么认、怎么叫车见第 13 节。两项都是回头翻人群数据的研究，分不清里面有多少人本来就要发病。但两项指的方向和时间段一致。没有人可以把药盒交出去、这几天注定一个人在屋里的，见本节第 6 条。', NULL, NULL, NULL, '不花钱。这几天别一个人待着，药照常吃。', '1985 名急性心梗患者，拿同一个人发病前后的不同时间段自己跟自己比。其中 270 人（13.6%）在发病前 6 个月内失去过重要的人，19 人是在心梗前 1 天内失去的。重要的人去世后 24 小时内，急性心梗发作率升高 21.1 倍（95% CI 13.1–34.1，真实倍数大致在 13 到 34 之间）。此后逐日下降。换成实际人数：十年心梗风险 5% 的人里，每 1394 个刚失去亲人的多出 1 例。风险 20% 的人里，每 320 个多出 1 例。英国另一项研究，比了 30447 名 60 至 89 岁丧偶者和 83588 名条件相当的对照。丧偶后 30 天内发生心梗或中风的，丧偶的一边 50 人（0.16%）。对照的一边 67 人（0.08%）。IRR 2.20（1.52–3.15），即出事的概率约为对照的 2.2 倍。其中心梗 2.14（1.20–3.81），约 2.1 倍。中风 2.40（1.22–4.71），约 2.4 倍。30 天以后减弱。90 天内还看了两类病。一类是非心梗急性冠脉综合征（心脏供血急性出问题、但还够不上心梗的那类），IRR 2.20（1.12–4.29）。一类是肺栓塞（血块堵在肺的血管里），IRR 2.37（1.18–4.75）', '药盒交给别人管，别靠自己记。这几天别开长途。别靠喝酒扛过去，酒的账见第 2 节。心梗、中风怎么认、怎么叫车见第 13 节。两项都是回头翻人群数据的研究，分不清里面有多少人本来就要发病。但两项指的方向和时间段一致。没有人可以把药盒交出去、这几天注定一个人在屋里的，见本节第 6 条。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-2', 'concept_archive_s29-2', 'claim_archive_s29-2', 'action', 'life_archive', '被告知重病诊断的那一周，别一个人去拿报告，治疗以外的决定往后放', '29. 遭遇重大打击之后', '拿到癌症诊断的第一周，自杀的概率是没确诊的人的 12.6 倍，死于心血管病的概率是 5.6 倍。到第一年，自杀风险降到 3.1 倍，越难治的癌越明显。所以拿报告那天带个人去，回家别一个人待着。辞职、卖房这类事，留到下次门诊再说。', '这是癌症病人的数据。换到别的重大诊断，没有同等分量的原文。出事的人其实很少：第一周自杀率 2.50/1000 人年，即 1000 人跟一年出 2.5 例。写出来不是吓人，是说明「刚知道的那几天」要有人在旁边。确诊后的长期管理、报销和复查见第 16 节和第 24 节。找不到人陪着去的见本节第 6 条（把「那个人」换成邻居和社区名单）。', NULL, NULL, NULL, '不花钱。找个人陪你去拿报告。把治疗以外的大决定推后几天。', '瑞典全国档案跟踪 607 万多人（6,073,240 人），时间是 1991 至 2006 年。和没确诊癌症的人相比，确诊后第一周自杀相对风险 12.6（95% CI 8.6–17.8），即约 12.6 倍。真实倍数大致在 8.6 到 17.8 之间。这一周的发病率是 2.50/1000 人年，也就是 1000 人跟一年出 2.5 例。到第一年降到 3.1（2.7–3.5，0.60/1000 人年），约 3.1 倍。心血管死亡第一周 5.6（5.2–5.9，116.80/1000 人年），约 5.6 倍。前 4 周 3.3（3.1–3.4，65.81/1000 人年）。风险升高在确诊后第一年内迅速回落。越是治起来难、活下来概率低的癌种，升得越明显。把同一批患者不同时间段自己跟自己比，结论一致', '这是癌症病人的数据。换到别的重大诊断，没有同等分量的原文。出事的人其实很少：第一周自杀率 2.50/1000 人年，即 1000 人跟一年出 2.5 例。写出来不是吓人，是说明「刚知道的那几天」要有人在旁边。确诊后的长期管理、报销和复查见第 16 节和第 24 节。找不到人陪着去的见本节第 6 条（把「那个人」换成邻居和社区名单）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-3', 'concept_archive_s29-3', 'claim_archive_s29-3', 'action', 'life_archive', '失业之后先把作息、医保和找工作的节奏固定下来，别整天待在家里', '29. 遭遇重大打击之后', '失业的人之后死亡的概率比在职的人高约六成，男性和年纪不大的人更明显，头十年最高。把抽烟喝酒的影响扣掉，升幅少了约四分之一，这部分自己能管住。先去办失业登记、领失业保险金，领的期间医保由失业保险代缴。', '这是回头翻人群数据的研究，分不清因果方向。本来身体差的人也更容易失业。但「把生活习惯那部分影响扣掉后，效应低 24%」给了可着手的方向。失业能领什么、去哪领、社保怎么续见第 7 节。被辞退该拿多少补偿、别签主动辞职见第 19 节。', NULL, NULL, NULL, '不花钱。先去办失业登记、领失业保险金，再把找工作排成固定日程。难在没人催你的时候还要按点起床。', '42 项研究、235 个死亡风险估计、逾 2000 万人合起来算。把年龄等条件的影响扣平之后，失业者各种原因加起来的死亡风险平均 HR 为 1.63，比在职的人高约六成。男性高于女性。对处在职业生涯早期和中期的人影响明显，晚期较小。跟踪的头 10 年风险最高，之后下降。在把抽烟喝酒这类健康行为也算进去的那部分研究里，平均 HR 低 24%，即算出来的升幅少了约四分之一', '这是回头翻人群数据的研究，分不清因果方向。本来身体差的人也更容易失业。但「把生活习惯那部分影响扣掉后，效应低 24%」给了可着手的方向。失业能领什么、去哪领、社保怎么续见第 7 节。被辞退该拿多少补偿、别签主动辞职见第 19 节。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-4', 'concept_archive_s29-4', 'claim_archive_s29-4', 'action', 'life_archive', '亲人死于自杀、意外或凶案的，别指望硬扛，主动去找专业帮助', '29. 遭遇重大打击之后', '配偶死于自杀的人，五年内被查出精神障碍的概率比一般人高约八成（男性）、七成（女性）。和配偶死于其他原因的人比，也高七成到一倍。这类丧亲的人更容易觉得被人疏远、觉得羞耻。这正是要主动去找人的理由，别等自己好起来。', '突然的、暴力性的死亡，指的是事故、凶案、灾害。这类死亡之后，创伤后应激障碍、抑郁和哀伤卡住的比例都比病亡后高。恢复也更慢。自己有自杀念头时的处置见第 1 节第 25 条。', NULL, NULL, NULL, '打 12356 不花钱。要看医生，挂心理门诊是普通门诊的钱。难在自己开口找人。', '丹麦全国档案跟踪 670 万成年人，时间是 1980 至 2014 年，合计逾 1.36 亿人年（所有人被跟踪的年数加总）。因配偶自杀而丧偶的人，5 年内新查出精神障碍的风险和一般人比，IRR 男性 1.8（95% CI 1.6–2.0），即高约八成。女性 1.7（1.6–1.8），即高约七成。和因其他死因丧偶的人相比，IRR 男性 1.7（1.5–1.9）、女性 2.0（1.9–2.2），即高七成到一倍。这批人里，自杀行为、死亡率与需要市政救助的比例也更高。肝硬化、睡眠障碍等身体上的病，风险同样升高。另有 57 项研究逐项归纳，不合并算数。因自杀丧亲，和下面四件事相关。一是伴侣自杀风险升高。二是子女自杀后父母住进精神科的风险升高。三是成年子女自杀后母亲自杀风险升高。四是父母自杀后子女抑郁风险升高。和因其他暴力死亡丧亲的人相比，因自杀丧亲的人更常说自己被人疏远、觉得羞耻', '突然的、暴力性的死亡，指的是事故、凶案、灾害。这类死亡之后，创伤后应激障碍、抑郁和哀伤卡住的比例都比病亡后高。恢复也更慢。自己有自杀念头时的处置见第 1 节第 25 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-5', 'concept_archive_s29-5', 'claim_archive_s29-5', 'action', 'life_archive', '丧偶后的头半年，把三餐、睡觉、慢性病的药和复查交给一个固定的人盯着', '29. 遭遇重大打击之后', '丧偶后不到半年，同期死亡的概率比没丧偶的人高约四成。半年以后降到高约一成半。男性高约两成三，女性那一档小到可能只是巧合。这个差不是靠想开点能扛过去的。该做的是把药、饭和复查落到一个具体的人身上，别指望自己记得住。', '这是回头翻人群数据的研究，别的因素掺进来去不掉。夫妻的生活方式和疾病本来就相似。但「头半年比之后高得多」这个规律，在两份各自独立的汇总分析里都一样，值得当成一段照看窗口。男性风险更高，也更少开口求助。家里有丧偶老人的，按第 17 节把账户、监护和遗嘱一并理清。找不到这样一个人的（独居、失独、子女也不在了），把这件事交给社区和手机，见本节第 6 条。', NULL, NULL, NULL, '不花钱。找一个具体的人，子女、兄弟姐妹或者朋友都行，让他定期上门或者打电话。难在要开口把这件事托付出去。', '15 项先登记再往后跟踪的研究、2,263,888 人合起来算。丧偶不足 6 个月时死亡 RR 1.41（95% CI 1.26–1.57），即同期死亡概率比没丧偶的人高约四成。6 个月以后是 1.14（1.10–1.18），降到高约一成半。男性 RR 1.23（1.18–1.28），高约两成三。女性 1.04（1.00–1.08，无统计学意义，即这点差可能只是巧合）。小于 65 岁与 65 岁以上没看出明显差别。另一项分析合并了 123 篇文献、1377 个风险估计、逾 5 亿人。把条件差异扣平后 HR 1.23（1.19–1.28），即整体高约两成三。男性还高于女性。男性 1.27（1.19–1.35），高两成七。女性 1.15（1.08–1.22），高一成五', '这是回头翻人群数据的研究，别的因素掺进来去不掉。夫妻的生活方式和疾病本来就相似。但「头半年比之后高得多」这个规律，在两份各自独立的汇总分析里都一样，值得当成一段照看窗口。男性风险更高，也更少开口求助。家里有丧偶老人的，按第 17 节把账户、监护和遗嘱一并理清。找不到这样一个人的（独居、失独、子女也不在了），把这件事交给社区和手机，见本节第 6 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-6', 'concept_archive_s29-6', 'claim_archive_s29-6', 'action', 'life_archive', '没有亲人也没有朋友的，把「盯着你的那个人」换成三样东西：能进你家门的邻居、社区的探访名单、手机里的紧急联络', '29. 遭遇重大打击之后', '没有亲人也没有朋友时，要顾的是两件事：出了事有人发现你，平时按时吃药吃饭。吃药吃饭靠自己，写成清单、上闹钟，别靠记性。有人发现靠三样：给邻居留一把备用钥匙，去居委会问能不能上探访关爱名单，手机设好紧急联络人、别关机。', '三样东西具体怎么办。一，把备用钥匙或者门锁的临时密码给一个邻居或者物业，跟他说一句「我这几天一个人」。不需要交情，只需要有人知道你在屋里。二，去社区居委会说明自己独居，问能不能上探访关爱的名单。老年人里独居、空巢、失独的是官方明确的服务对象，顺便问本地有没有免费装的智能呼叫器、智能水表这类装置。三，手机设好紧急联络人和医疗急救卡，这几天别静音、别关机。给 B 的原因有两条。一是独居和死亡率的关联来自回头翻人群数据的研究，去不掉「本来身体差、条件差的人更可能独居」这层反过来的解释，原文自己也写这个结果有待确认。二是探访关爱那份文件只覆盖老年人。不满 60 岁的没有对应的专门制度。能指望的是文件里的一条，它要求网格员和社工「及时发现家庭变故、失业、失学等心理危机风险」（见本节第 11 条，要人陪着说话打 12356）。「屋里有人」为什么值钱，看第 13 节第 1 条（按压胸口）。发生在医院外的心脏骤停，79.2% 发生在家里。旁边有人做按压的，活着出院的占 16.1%，没人的只有 3.9%。屋里没人就等于落在低的那一档。另外两件顺手的事。办丧事本身就要跑殡仪馆、社区卫生服务机构、公安、公积金好几个窗口（见第 25 节）。把它排成每天出门一次的固定日程，这几天的外出安排现成就有。热线可以反复打，不是只能打一次（见本节第 11 条，要人陪着说话打 12356）。「一个人住」本身还是个长期风险因素。独居的死亡比值比 1.32，高出约三成，见第 22 节第 9 条（把定期和人见面当健康支出）。但这里只管眼前这几天，长期那笔账另算。', NULL, NULL, NULL, '不花钱。难在要主动开口，跟邻居和居委会说一句「我一个人住，家里刚出事」。', '44,573 名门诊病人，都有动脉粥样硬化血栓的风险或者病史（血管里长斑块、容易被血块堵住的那类毛病）。他们由多国医生登记进 REACH 这个国际项目跟踪，2003 年 12 月至 2004 年 12 月入组，跟踪 4 年。其中 8,594 人（19%）独居。独居的人 4 年里各种原因加起来的死亡为 14.1%，同住的是 11.1%。心血管死亡 8.6% 对 6.8%。两项 log-rank P&lt;0.01，差别不太可能是碰巧。不同年龄段的差距不一样（交互 P=0.03）。45 至 65 岁，独居对同住的死亡为 7.7% 对 5.7%。把别的条件扣平后 HR 1.24（95% CI 1.01–1.51），即高约两成四。66 至 80 岁是 13.2% 对 12.3%，HR 1.12（1.01–1.26），高约一成。80 岁以上是 24.6% 对 28.4%，HR 0.92（0.79–1.06），反而没见升高。民政部等十部门 2022 年意见规定，要开展探访关爱服务。对象是独居、空巢、留守、失能、重残、计划生育特殊家庭等老年人。服务方式为「定期上门入户、电话视频、远程监测」。由乡镇（街道）摸底排查、村（居）民委员会协助，掌握基本信息和「接受探访关爱服务的意愿」并纳入基层网格化管理，也就是按片区分给专人盯着。到 2025 年底「确保特殊困难老年人月探访率达到 100%」，「对失能的特殊困难老年人，每月探访关爱不少于一次」。文件还倡导家庭配置智能呼叫系统、智能电水表、健康监测产品、养老监护装置，「一旦监测异常，能够及时预警，并同步向紧急联系人发送提示信息」。服务人员发现紧急问题「应当第一时间协助拨打紧急求助电话」', '三样东西具体怎么办。一，把备用钥匙或者门锁的临时密码给一个邻居或者物业，跟他说一句「我这几天一个人」。不需要交情，只需要有人知道你在屋里。二，去社区居委会说明自己独居，问能不能上探访关爱的名单。老年人里独居、空巢、失独的是官方明确的服务对象，顺便问本地有没有免费装的智能呼叫器、智能水表这类装置。三，手机设好紧急联络人和医疗急救卡，这几天别静音、别关机。给 B 的原因有两条。一是独居和死亡率的关联来自回头翻人群数据的研究，去不掉「本来身体差、条件差的人更可能独居」这层反过来的解释，原文自己也写这个结果有待确认。二是探访关爱那份文件只覆盖老年人。不满 60 岁的没有对应的专门制度。能指望的是文件里的一条，它要求网格员和社工「及时发现家庭变故、失业、失学等心理危机风险」（见本节第 11 条，要人陪着说话打 12356）。「屋里有人」为什么值钱，看第 13 节第 1 条（按压胸口）。发生在医院外的心脏骤停，79.2% 发生在家里。旁边有人做按压的，活着出院的占 16.1%，没人的只有 3.9%。屋里没人就等于落在低的那一档。另外两件顺手的事。办丧事本身就要跑殡仪馆、社区卫生服务机构、公安、公积金好几个窗口（见第 25 节）。把它排成每天出门一次的固定日程，这几天的外出安排现成就有。热线可以反复打，不是只能打一次（见本节第 11 条，要人陪着说话打 12356）。「一个人住」本身还是个长期风险因素。独居的死亡比值比 1.32，高出约三成，见第 22 节第 9 条（把定期和人见面当健康支出）。但这里只管眼前这几天，长期那笔账另算。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-7', 'concept_archive_s29-7', 'claim_archive_s29-7', 'action', 'life_archive', '家长去世后，如实告诉孩子、让他参加告别、别送去别处「换个环境」', '29. 遭遇重大打击之后', '18 岁前失去父亲或母亲的孩子，到成年早期死亡的概率比没经历过的孩子高约五成。父母死于意外、自杀的高约八成，死于疾病的高约三成。家里能做的是如实告诉他，让他参加告别，别中断上学，别送去亲戚家换环境。', '跟孩子说的时候别编「出远门了」，监护和抚养的安排要落到书面。给 B 不是因为数字不硬。这是三个国家全体人口的跟踪研究，数字本身够 A 级。给 B 是因为从这个数字到「怎么跟孩子说、要不要参加告别」的具体做法之间，没有直接试验证据。作者也写明，丧亲后亲子关系和孩子生活方式的数据都缺。升高里既有天生体质的成分，也有丧亲留下的长期影响。指定监护人和安排财产见第 17 节。孩子的抚养费和上学见第 18 节。', NULL, NULL, NULL, '不花钱。难在自己也正难受，还得跟孩子把话说清楚。', '丹麦 1968 至 2008 年、瑞典 1973 至 2006 年出生的全部人口都算进来。再加上芬兰 1987 至 2007 年出生者里抽出的 89.3%。合计逾 730 万人。其中 189,094 人在 18 岁前失去父母。这批孩子各种原因加起来的死亡率，比没丧亲的人高 50%（死亡率比 1.50，95% CI 1.43–1.58，即约 1.5 倍）。父母死于意外、自杀这类非自然原因的是 1.84（1.71–2.00），高约八成。死于疾病等自然原因的是 1.33（1.24–1.41），高约三成。孩子的死因和父母的死因属同一类时最高', '跟孩子说的时候别编「出远门了」，监护和抚养的安排要落到书面。给 B 不是因为数字不硬。这是三个国家全体人口的跟踪研究，数字本身够 A 级。给 B 是因为从这个数字到「怎么跟孩子说、要不要参加告别」的具体做法之间，没有直接试验证据。作者也写明，丧亲后亲子关系和孩子生活方式的数据都缺。升高里既有天生体质的成分，也有丧亲留下的长期影响。指定监护人和安排财产见第 17 节。孩子的抚养费和上学见第 18 节。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-8', 'concept_archive_s29-8', 'claim_archive_s29-8', 'action', 'life_archive', '哀伤过了半年还在原地、日子过不下去，去精神科或临床心理科挂号', '29. 遭遇重大打击之后', '大约每十个丧亲的成年人里有一个会卡住：半年以上还在持续想念到吃不下饭、上不了班、带不了孩子，人麻木，觉得生活没有意义。这不是不够坚强，它有诊断标准，也有专门的治疗。针对性治疗的有效率 51%，普通心理治疗是 28%，起效也更快。', '别自己卡月份。真正的判断是「影响到吃饭、睡觉、上班、带孩子」，对上了就去挂号。科室叫精神科、心理科或临床心理科，公立精神专科医院都有。这个诊断在不同资料里叫复杂哀伤，也叫延长哀伤障碍。不同标准要求持续多久也不一样，有的写 6 个月，有的写 12 个月。9.8% 这个比例来自 14 项做法差异不小的研究，作者也提醒它未必能照搬到别的人群身上。', NULL, NULL, NULL, '挂号费加治疗费。这类治疗按疗程做，试验里平均 19 周做 16 次。难在要自己迈出去挂这个号。', '14 项研究合起来算，对象是亲人不是死于暴力、本人也没在精神科就诊的成年人。延长哀伤障碍患病率 9.8%（95% CI 6.8–14.0），即每 100 个丧亲的成年人里约 10 个。年龄越大比例越高。另有一项研究检验这套诊断标准准不准，找了 291 名丧亲者，在丧亲后 0–6、6–12、12–24 个月分三次访谈。诊断的核心表现是对逝者的强烈想念。还要加上这九项里的至少五项。前五项是情感麻木、震惊、觉得生活没有意义、不信任他人、因这次失去而痛苦。后四项是难以接受、认不清自己该是谁、回避现实、无法继续生活。这些表现要每天都出现，或者严重到干不了事。而且在亲人去世至少 6 个月后仍然存在，还影响着日常生活。还有一项 95 人抽签分两组的试验，做 16 次治疗、平均 19 周。针对复杂哀伤的治疗有效率 51%。普通的人际心理治疗 28%（P=0.02，差别不太可能是碰巧）。前者起效也更快。需治疗人数 4.3，即平均每治 4.3 个人就多一个好转', '别自己卡月份。真正的判断是「影响到吃饭、睡觉、上班、带孩子」，对上了就去挂号。科室叫精神科、心理科或临床心理科，公立精神专科医院都有。这个诊断在不同资料里叫复杂哀伤，也叫延长哀伤障碍。不同标准要求持续多久也不一样，有的写 6 个月，有的写 12 个月。9.8% 这个比例来自 14 项做法差异不小的研究，作者也提醒它未必能照搬到别的人群身上。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 一般","口径 死亡率","钱 少","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-9', 'concept_archive_s29-9', 'claim_archive_s29-9', 'action', 'life_archive', '别一上来就花钱做哀伤咨询，先看自己的哀伤是不是真的卡住了（第 8 条那几条症状）', '29. 遭遇重大打击之后', '给所有丧亲的人都安排心理咨询，好处很小，过一阵就看不出来了，因为多数人本来会自己缓过来。但对已经明显适应不了的人，治疗和治别的心理问题一样有效。所以先对照第 8 条（哀伤卡住了去精神科），对上了再花这笔钱。', '意思是「不必人人做」，不是「都别做」。第 4 条（亲人死于自杀、意外或凶案）那类高危丧亲、第 8 条（哀伤卡住了去精神科）那类已经卡住的人，正是有证据支持该做的人。一篇 Lancet 综述的结论也是这样：哀伤不是病，多数人不需要专业干预。该把力气用在高危的人身上。也用在已经出现复杂哀伤、丧亲后抑郁和应激障碍的人身上。', NULL, NULL, NULL, '不花钱，反过来省下一笔咨询费。', '61 项对照研究合起来算。给丧亲的人普遍做心理干预，在治疗刚结束时好处很小，隔一段时间再看就看不出好处了。只招收「已经明显适应不了」的丧亲者的干预，效果和治疗其他心理问题的心理治疗一样好。事先不做筛查的研究结果不好，原因是没做干预的那一组本来也会随时间自己缓过来。另有 14 项抽签分组试验合起来算：对已经出问题的人做的治疗，在治疗后和之后回访时都明显好于对照，隔一段时间效果还在变大。对还没出问题的人普遍做的预防性干预无效。还有一项研究把 205 人从丧偶前一直跟到丧偶后 6、18 个月。这项研究分出五种走向。分别是普通哀伤、长期哀伤、长期抑郁、丧亲期间反而好转、韧性（扛得住）。其中韧性型最常见，普通哀伤型相对少见', '意思是「不必人人做」，不是「都别做」。第 4 条（亲人死于自杀、意外或凶案）那类高危丧亲、第 8 条（哀伤卡住了去精神科）那类已经卡住的人，正是有证据支持该做的人。一篇 Lancet 综述的结论也是这样：哀伤不是病，多数人不需要专业干预。该把力气用在高危的人身上。也用在已经出现复杂哀伤、丧亲后抑郁和应激障碍的人身上。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-10', 'concept_archive_s29-10', 'claim_archive_s29-10', 'action', 'life_archive', '分居离婚之后别断医保、别用酒顶着', '29. 遭遇重大打击之后', '分居或离婚的人早死的概率明显高于还在婚的人，男性和年纪较轻的人升得更多。这不一定是离婚造成的，离婚的人在健康、收入上本来就可能不一样。能自己管住的有两样：别让医保、体检断掉，别靠烟酒顶着。', '原文只说了「明显升高」和分组对比，没给能引用的倍数，所以这里不写具体数字。收益量级按「知道方向、没有可套阈值的降幅」定为中。离婚时的财产、债务与彩礼见第 8 节和第 10 节。孩子的抚养安排见第 18 节。', NULL, NULL, NULL, '不花钱。把医保续上，把酒停掉。难在这段时间容易靠酒顶着。', '32 项先登记再往后跟踪的研究合起来算，覆盖逾 650 万人、16 万例死亡、逾 75.5 万例离婚、11 个国家。和还在婚的人相比，分居或离婚的成年人早死风险明显升高。男性和年纪较轻的人，升得比女性和年长者明显。作者讨论了四条可能的路径。一是社会选择，本来健康或条件就不一样的人更容易走到离婚。二是资源中断，收入和保障断掉。三是健康行为改变，烟酒作息变差。四是慢性心理压力（长期紧绷）', '原文只说了「明显升高」和分组对比，没给能引用的倍数，所以这里不写具体数字。收益量级按「知道方向、没有可套阈值的降幅」定为中。离婚时的财产、债务与彩礼见第 8 节和第 10 节。孩子的抚养安排见第 18 节。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-11', 'concept_archive_s29-11', 'claim_archive_s29-11', 'action', 'life_archive', '要人陪着说话打 12356，未成年人和青少年打 12355，要看医生挂心理门诊', '29. 遭遇重大打击之后', '想找个人说话，打 12356，这是全国心理援助热线，免费。未成年人和青少年另有 12355 青少年综合服务平台。要看医生，就挂精神科、心理科或临床心理科的心理门诊。遇到家庭变故、失业、失学，社区网格员和社工本来就该主动发现。', '给 B 是因为村和社区的咨询室、县级的心理门诊都是 2030 年才要建成的目标，不是现在各地都有。12356 和 12355 则是现在就能打的。12356 的开通时间和每天接听多长时间见第 1 节第 25 条。心理咨询和心理治疗不是一回事。下诊断、开药得由精神科医师来，治疗要在有资质的医疗机构做。市面上按小时收费的「疗愈」「灵性咨询」不在这个体系里。', NULL, NULL, NULL, '不花钱。两条热线都免费。心理门诊按普通门诊挂号。', '国家卫生健康委等 25 部门 2026 年方案要求完善 12356 心理援助热线工作制度。要保证稳定运行、提升接通率。要推动建立省级 12356 信息化平台。要加强与 110 等服务热线的联动机制建设。还要建强用好 12355 青少年综合服务平台，并与 12356 联动协作。到 2030 年的目标有三条。一是 80% 以上的行政村、城市社区设心理咨询室或社会工作室并提供心理服务。二是各级公立精神专科医院、各县（区）至少有 1 所医院提供心理门诊服务。三是各省建成省级 12356 心理援助平台。心理危机干预与心理援助队伍，由精神科医师、心理治疗技师、心理咨询人员、社会工作专业人员和志愿者组成。方案还要求三类人平时就留意、早点发现。这三类人是网格员（社区里按片区负责的工作人员）、社会工作专业人员和志愿者。他们要及时发现家庭变故、失业、失学等心理危机风险（全国，2026 年 3 月印发）', '给 B 是因为村和社区的咨询室、县级的心理门诊都是 2030 年才要建成的目标，不是现在各地都有。12356 和 12355 则是现在就能打的。12356 的开通时间和每天接听多长时间见第 1 节第 25 条。心理咨询和心理治疗不是一回事。下诊断、开药得由精神科医师来，治疗要在有资质的医疗机构做。市面上按小时收费的「疗愈」「灵性咨询」不在这个体系里。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-12', 'concept_archive_s29-12', 'claim_archive_s29-12', 'action', 'life_archive', '变故后的头三个月，凡是不可逆的大决定一律往后推', '29. 遭遇重大打击之后', '这段时间你对各种「机会」的判断力最差。说能联系逝者的、说能帮你把钱翻回来的、劝你辞职去外地重新开始的、拉你合伙的，都会找上来。金额超过一个月收入、或者反悔代价很大的事，一律推后三个月。先讲给一个跟这件事没利益关系的人听，别当天拍板。', '身边没有这样一个没利益关系的人，就打 12356 讲一遍（见本节第 11 条，要人陪着说话打 12356），或者自己写下来隔三天再读一遍。「三个月」是作者自己划的线，没有文献支持这个具体时长，所以记 C 级。针对丧亲者和老人的常见骗局见第 17 节（投资养老、以房养老）和第 6 节（算命）。担保和借条的坑见第 8 节。有几笔钱要主动去办，不在「往后推」之列：公积金余额、社保待遇、工亡三笔钱，见第 25 节和第 19 节。', NULL, NULL, NULL, '不花钱，只是把决定往后推，可能因此错过某些机会。难在当时会觉得机会不等人。', '避免在刚受打击、判断力最差的那段时间，做出反悔不了的财产处置。这类事包括卖房、辞职、把抚恤金或赔偿款一次性投出去、仓促再婚、替人担保。这类决定的金额通常在数万元到一套房子这个量级，收益因此定为中。官方文件同样把「家庭变故、失业、失学」列为社区要主动排查的心理危机风险，这段时间的状态本来就被当成需要外人搭把手的状态', '身边没有这样一个没利益关系的人，就打 12356 讲一遍（见本节第 11 条，要人陪着说话打 12356），或者自己写下来隔三天再读一遍。「三个月」是作者自己划的线，没有文献支持这个具体时长，所以记 C 级。针对丧亲者和老人的常见骗局见第 17 节（投资养老、以房养老）和第 6 节（算命）。担保和借条的坑见第 8 节。有几笔钱要主动去办，不在「往后推」之列：公积金余额、社保待遇、工亡三笔钱，见第 25 节和第 19 节。', '一般', 'C', 1, 'strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","C 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s29-13', 'concept_archive_s29-13', 'claim_archive_s29-13', 'action', 'life_archive', '别拿死当还债的办法：两年内的寿险不赔，工伤不认，债照样先从遗产里扣', '29. 遭遇重大打击之后', '寿险合同两年内自杀的不赔，只退保单里能退的那点钱。工伤也不认，工亡的三笔钱一分没有。欠的债先从你留下的遗产里扣，家里人只拿剩下的。他们还要承受本节第 4 条（因自杀或暴力死亡丧亲）说的那份健康代价。', '这里只算钱这一笔账。本节和第 1 节的其他条目说的是别走到这一步。保险法第四十四条管的只是前两年，写出来是为了把条文说全，不是在给时间表。家人的健康代价见本节第 4 条（配偶死于自杀者 5 年内新发精神障碍风险高七到八成）。念头冒出来时怎么办见第 1 节第 25、32 条，救回来之后的后遗症见第 1 节第 33 条。工亡三笔钱的标准见第 19 节第 15 条。遗产和债务的具体手续见第 25 节第 9 条（逐个去取公积金和社保待遇）', NULL, NULL, NULL, '不花钱，只是把这笔账算清。', '保险法第四十四条管的是以被保险人死亡为给付保险金条件的合同。从合同成立或者合同效力恢复之日起算，二年内被保险人自杀的，保险人不承担给付保险金的责任。被保险人自杀时为无民事行为能力人的，也就是法律上不能为自己行为负责的人，不在此列。这种情况下保险公司应当按照合同约定退还保险单的现金价值，即只退保单里能退的那点钱，不赔保额。寿险保额通常在数十万元级，收益因此定为大。工伤保险条例第十六条第三项规定：自残或者自杀的，不得认定为工伤或者视同工伤。第三十九条那三笔工亡待遇随之全部落空。一是丧葬补助金，按当地上一年职工月平均工资发 6 个月。二是供养亲属抚恤金。三是一次性工亡补助金，为上一年度全国城镇居民人均可支配收入的 20 倍。民法典第一千一百五十九条规定：分割遗产应当清偿被继承人依法应当缴纳的税款和债务，即先拿遗产还税和债，剩下的才分。第一千一百六十一条规定：继承人以所得遗产实际价值为限清偿，也就是只用继承到的那部分还、不用自己再掏，放弃继承的可以不负清偿责任', '这里只算钱这一笔账。本节和第 1 节的其他条目说的是别走到这一步。保险法第四十四条管的只是前两年，写出来是为了把条文说全，不是在给时间表。家人的健康代价见本节第 4 条（配偶死于自杀者 5 年内新发精神障碍风险高七到八成）。念头冒出来时怎么办见第 1 节第 25、32 条，救回来之后的后遗症见第 1 节第 33 条。工亡三笔钱的标准见第 19 节第 15 条。遗产和债务的具体手续见第 25 节第 9 条（逐个去取公积金和社保待遇）', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"29. 遭遇重大打击之后","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-1', 'concept_archive_s30-1', 'claim_archive_s30-1', 'action', 'life_archive', '孩子说突然剧痛、而且越来越重，立刻去医院，不要让他忍到放学', '30. 上学以后的孩子', '有些病是按小时算的。男孩突然一侧阴囊剧痛，是睾丸扭转，也就是睾丸连着的那根血管拧住了，血供断了。6 小时内处理，睾丸保住的比例 97.2%。拖到 19 至 24 小时，只剩 42.5%。这种痛等不到放学，也等不到考完。', '提前跟男孩说一句：下面要是突然剧痛，马上讲，不用不好意思。睾丸扭转多发于青春期男孩，不少人因为难以启齿就硬忍。同样按小时算的还有急性阑尾炎（拖久了会穿孔）、糖尿病酮症酸中毒、脑膜炎。这几种本节没有逐条核实过「拖几小时坏多少」。它们共同的信号是：突然发作，一直加重，和以往任何一次都不一样。急症怎么认、怎么叫车见第 13 节。', NULL, NULL, NULL, '不花钱。请半天假，带孩子去挂急诊。', '按规矩把 30 组病例报告、2116 例睾丸扭转患者找齐，合起来看。其中 1283 例是按 6 小时一档统计的。从开始痛算起，0 至 6 小时睾丸保住的比例 97.2%。7 至 12 小时 79.3%。13 至 18 小时 61.3%。19 至 24 小时 42.5%。25 至 48 小时 24.4%。超过 48 小时 7.4%。合并成大段看，12 小时内 90.4%，13 至 24 小时 54.0%，超过 24 小时 18.1%。作者的结论是，能保住的时间可以比通常说的 6 至 8 小时更长。所以就算已经痛了很久，也还是要去处理，不要因为「反正晚了」就不去', '提前跟男孩说一句：下面要是突然剧痛，马上讲，不用不好意思。睾丸扭转多发于青春期男孩，不少人因为难以启齿就硬忍。同样按小时算的还有急性阑尾炎（拖久了会穿孔）、糖尿病酮症酸中毒、脑膜炎。这几种本节没有逐条核实过「拖几小时坏多少」。它们共同的信号是：突然发作，一直加重，和以往任何一次都不一样。急症怎么认、怎么叫车见第 13 节。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-2', 'concept_archive_s30-2', 'claim_archive_s30-2', 'action', 'life_archive', '该做的治疗别为了「等考完」往后拖，有些窗口跟着骨龄走，不跟着考试安排走', '30. 上学以后的孩子', '脊柱侧弯是脊柱往侧面弯。支具是一件硬壳背心，穿在身上把脊柱撑住。骨头还在长的时候戴，75% 的孩子没弯到要开刀的程度，只观察不戴的只有 42%。能戴的时间跟着骨头长完走，不跟着中考高考走，等考完往往只能开刀。', '这里用脊柱侧弯举例，是因为它有抽签分组的试验，有明确的时间窗口，而且正好是学生体检的重点项目之一（见第 7 条）。同类的还有斜视、弱视、龋齿，以及先天性心脏病那种可以挑时间做的手术。它们的共同点是越晚做效果越差，或者代价越大。具体窗口问专科医生。怕耽误上课，义务教育阶段可以休学，最长 1 年，学籍给留着，见第 11 条。', NULL, NULL, NULL, '不花钱，要定的只是早做还是晚做。请假和复诊要占时间，治疗本身的花费另算。难在支具要求每天至少戴 18 小时，孩子得一直忍着。', '多家医院一起做的试验，找了 242 例够条件戴支具的青少年特发性脊柱侧弯患者。其中 116 例抽签分组，126 例自己选戴不戴。成败事先定好怎么算：弯度长到 50 度以上算治疗失败，骨头长完时还没到这个度数算治疗成功。按最初分到哪一组来算，不管后来有没有真戴够。抽签戴支具组成功率 75%，抽签只观察组 42%（OR 4.11，95% CI 1.85–9.16），成功的机会约为只观察的 4 倍。把抽签的和自己选的两拨人合起来算，是 72% 对 48%（把两拨人本来的差别扣平后 OR 1.93，1.08–3.46，仍约 1.9 倍）。每天戴的小时数越多，成功率越高（P&lt;0.001，这个关系不太可能是碰巧）。试验因为支具确实有效，提前停掉了', '这里用脊柱侧弯举例，是因为它有抽签分组的试验，有明确的时间窗口，而且正好是学生体检的重点项目之一（见第 7 条）。同类的还有斜视、弱视、龋齿，以及先天性心脏病那种可以挑时间做的手术。它们的共同点是越晚做效果越差，或者代价越大。具体窗口问专科医生。怕耽误上课，义务教育阶段可以休学，最长 1 年，学籍给留着，见第 11 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-3', 'concept_archive_s30-3', 'claim_archive_s30-3', 'action', 'life_archive', '孩子被欺凌，当天就报到学校并要求书面处理，涉及打人、抢钱、传谣的直接报警', '30. 上学以后的孩子', '被同伴欺凌的孩子，冒出自杀念头的可能约是没被欺凌的 2.2 倍，有过自杀行为的约 2.6 倍。学校接到报告要立即调查，认定是欺凌就要处分，严重的不许瞒，必须报公安。所以当天就报，要求走认定程序，留下书面记录。', '孩子身上出现说不清来由的伤，突然不肯上学，东西反复丢失，先按第二十二条那几个信号去问。这份把多项研究合起来算的分析只是跟踪记录、没有分组对照，所以不能证明单是欺凌就导致自杀，但风险的方向和大小是清楚的。《加强中小学生欺凌综合治理方案》另外要求严格区分欺凌与学生之间的打闹嬉戏。所以学校有义务作出认定，不能一句「小孩子闹着玩」了事。', NULL, NULL, NULL, '不花钱。找班主任，也找学校的学生欺凌治理组织。要报警就打 110。难在要顶住「别把事闹大」这类劝法。', '34 项研究、284,375 名儿童青少年合起来算。被同伴欺凌和冒出自杀念头相关，OR 2.23（95% CI 2.10–2.37），出现念头的机会约为没被欺凌的 2.2 倍。另有 9 项研究、70,102 人，被欺凌和自杀未遂相关，OR 2.55（1.95–3.34），约 2.6 倍。男女、年龄和研究本身质量不同，结果都一样。网络欺凌和自杀念头的关联比线下欺凌更强。《未成年人学校保护规定》第二十一条列出五类行为：殴打、脚踢、掌掴、抓咬、推撞、拉扯；辱骂、讥讽、起侮辱性绰号；抢夺、强拿硬要或故意毁坏财物；恶意排斥孤立；通过网络捏造事实诽谤或散布谣言。该条还规定，在年龄、身体或人数上占优势的一方蓄意或恶意做这些事，造成人身伤害、财产损失或精神损害的，可以认定为欺凌。第二十二条要求教职工发现学生情绪反常、身体损伤，应及时了解并报告。第二十三条要求学校接到报告立即调查，提交欺凌治理组织认定处置，并通知家长参与。认定构成欺凌的，要作出教育惩戒或纪律处分。对违反治安管理或涉嫌犯罪的严重欺凌行为不得隐瞒，应当及时向公安机关、教育行政部门报告（全国，2021 年 9 月 1 日起施行）', '孩子身上出现说不清来由的伤，突然不肯上学，东西反复丢失，先按第二十二条那几个信号去问。这份把多项研究合起来算的分析只是跟踪记录、没有分组对照，所以不能证明单是欺凌就导致自杀，但风险的方向和大小是清楚的。《加强中小学生欺凌综合治理方案》另外要求严格区分欺凌与学生之间的打闹嬉戏。所以学校有义务作出认定，不能一句「小孩子闹着玩」了事。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-4', 'concept_archive_s30-4', 'claim_archive_s30-4', 'action', 'life_archive', '让孩子每天在户外待够 2 小时，这是目前唯一有随机试验支持的防近视办法', '30. 上学以后的孩子', '小学一年级每天多上 40 分钟户外课，三年后新近视的孩子从约四成降到约三成。卫健委给的量是每天白天在户外不少于 2 小时，或者一周加起来 14 小时。阴天也算数，课间到室外站着也算数。', '这项试验只做了 3 年，参加的孩子也都是从 6 岁开始的。两组近视的比例差 9.1 个百分点，只能让一部分人不近视，保证不了不近视。同一份核心知识十条还给了几条做法。读写要「一尺一拳一寸」。近距离用眼 20 分钟后，要远眺 20 秒以上。中小学生不为学习而用电子屏幕的，一次不超过 15 分钟，一天加起来不超过 1 小时。「待在户外」和「上体育课」不是一回事，课间到室外站着也算数。', NULL, NULL, NULL, '不花钱。但每天要腾出时间，多半得从写作业和上网课的时间里挤。难在天天都要做到，不是做几次就完。', '广州 12 所小学的一年级学生，以学校为单位抽签分组（干预校 952 人，对照校 951 人，平均年龄 6.6 岁）。干预的做法是每个上学日增加 1 节 40 分钟户外活动课，并鼓励家长在课外多带孩子出去。3 年里新近视的比例，干预组 30.4%，是 853 名合格者中的 259 例；对照组 39.5%，是 726 名中的 287 例。两组差值 -9.1 个百分点（95% CI -14.1 至 -4.1，P&lt;0.001），真实差距大致在少 4 到少 14 个百分点之间。3 年里度数的加深量（等效球镜变化）是 -1.42 D 对 -1.59 D，差 0.17 D（P=0.04）。干预组加深得略少一点。D 是量度数的单位。眼轴（眼球前后的长度）的增长，两组看不出差别（P=0.07）。《防控儿童青少年近视核心知识十条》要求儿童青少年每天日间户外活动不少于 2 小时，或每周累计 14 小时。它注明即使阴天，户外活动也有防护效果，并要求避开午后高温强晒的时段', '这项试验只做了 3 年，参加的孩子也都是从 6 岁开始的。两组近视的比例差 9.1 个百分点，只能让一部分人不近视，保证不了不近视。同一份核心知识十条还给了几条做法。读写要「一尺一拳一寸」。近距离用眼 20 分钟后，要远眺 20 秒以上。中小学生不为学习而用电子屏幕的，一次不超过 15 分钟，一天加起来不超过 1 小时。「待在户外」和「上体育课」不是一回事，课间到室外站着也算数。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 高","口径 死亡率","钱 0","时间 中","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-5', 'concept_archive_s30-5', 'claim_archive_s30-5', 'action', 'life_archive', '0 到 3 岁不给屏幕，3 到 6 岁尽量不给，中小学生非学习用途每天不超过 1 小时', '30. 上学以后的孩子', '国家卫健委要求 0 到 3 岁不给屏幕，3 到 6 岁尽量别碰，中小学生不为学习用的，一次不超过 15 分钟、一天不超过 1 小时。理由是长时间近距离用眼会让近视来得早。屏幕和近视的证据没这么硬，真正试出效果的是每天户外 2 小时。', '定 B 是因为官方给的是分档规定，不是试验测出来的数字。研究给的比值比下限正好压在 1.00，作者只敢说「可能相关」。所以把它当一条好执行的家规就行，不要当成「不看屏幕就不会近视」。真正有抽签试验撑着的是第 4 条（户外 2 小时）。学龄前也要查眼睛：同一份文件写明 1～3 岁、4～6 岁、7 岁之后都应当定期做屈光筛查，看远视储备还剩多少，查法见第 12 条（散瞳验光）。屏幕和孩子语言能力的关系也做过荟萃：42 项研究 18905 人，屏幕时间越长语言能力越弱（r=−0.14，95% CI −0.18 到 −0.10）。但一起看、看有教育内容的节目反过来是正相关（r=0.16 和 0.13）。这是相关不是因果，只能说明拿屏幕代替陪孩子说话不划算。', NULL, NULL, NULL, '不花钱。难的是把屏幕从孩子手里拿走，也难在家长自己当着孩子的面少看。', '《防控儿童青少年近视核心知识十条》第四条的原话是「0～3岁婴幼儿不使用手机、平板、电脑等视屏类电子产品；3～6岁幼儿尽量避免其接触和使用手机、平板、电脑等视屏类电子产品；中小学生非学习目的使用电子屏幕单次时长不宜超过15分钟，每天累计时长不宜超过1小时」。同一条写明「长时间近距离使用电子视屏类产品，易消耗儿童远视储备量，是儿童青少年近视早发、高发的重要原因」。教育部等八部门 2018 年的实施方案给家长的要求一致，还加了一句「年龄越小，连续使用电子产品的时间应越短」。研究证据要弱得多：一项系统综述收了 33 项研究，11 项进了合并计算，对象从 3 个月到 33 岁。只算手机和平板的，近视的比值比是 1.26（95% CI 1.00 到 1.60，I²=77%）。和电脑合起来算是 1.77（1.28 到 2.45，I²=87%）。作者的结论只写到「可能相关」，并写明 33 项研究没有一项有可靠的屏幕时间测量', '定 B 是因为官方给的是分档规定，不是试验测出来的数字。研究给的比值比下限正好压在 1.00，作者只敢说「可能相关」。所以把它当一条好执行的家规就行，不要当成「不看屏幕就不会近视」。真正有抽签试验撑着的是第 4 条（户外 2 小时）。学龄前也要查眼睛：同一份文件写明 1～3 岁、4～6 岁、7 岁之后都应当定期做屈光筛查，看远视储备还剩多少，查法见第 12 条（散瞳验光）。屏幕和孩子语言能力的关系也做过荟萃：42 项研究 18905 人，屏幕时间越长语言能力越弱（r=−0.14，95% CI −0.18 到 −0.10）。但一起看、看有教育内容的节目反过来是正相关（r=0.16 和 0.13）。这是相关不是因果，只能说明拿屏幕代替陪孩子说话不划算。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-6', 'concept_archive_s30-6', 'claim_archive_s30-6', 'action', 'life_archive', '把近视当成会留下的损伤：度数越深，将来视网膜脱离、黄斑病变、青光眼越多', '30. 上学以后的孩子', '近视不会自己好，度数也降不回去。它也不只是「戴个眼镜」的事。和不近视的人比，得近视性黄斑病变的可能，轻度近视高十几倍，600 度以上高几百倍。视网膜脱离，轻度高约 3 倍，600 度以上高约 13 倍。所以孩子近视得越早、涨得越快，将来要担的风险越大。', '汇总进去的都是观察性研究，比值比也大得不寻常。高度近视对黄斑变性那一项的可信范围从 230 到 3104，说明底下各项研究差别很大，数字只能看量级，不能当精确值用。这些并发症多数要到中老年才显出来。近视本身不是残疾，绝大多数人戴镜矫正后视力正常。但近视不是配副眼镜就完了，值得花力气推迟它、控制它。确诊之后怎么复查见第 12 条（散瞳验光）。别买号称能治好的产品，见第 9 条（治愈近视）。', NULL, NULL, NULL, '不花钱。本身不用做什么，要做的事在第 4、5 条（户外 2 小时、分龄管屏幕）。', '一项系统综述与荟萃分析汇总了 2019 年 6 月之前的研究，按度数分三档：轻度（−0.5 到 −3.00 D）、中度（−3.00 到 −6.00 D）、高度（≤−6.00 D，600 度以上）。和不近视的人相比，近视性黄斑变性的比值比依次是 13.57（95% CI 6.18 到 29.79）、72.74（33.18 到 159.48）、845.08（230.05 到 3104.34）。视网膜脱离依次是 3.15（1.92 到 5.17）、8.74（7.28 到 10.50）、12.62（6.65 到 23.94）。后囊下白内障依次是 1.56（1.32 到 1.84）、2.55（1.98 到 3.28）、4.55（2.66 到 7.75）。开角型青光眼，轻度是 1.59（1.33 到 1.91），中度和高度合起来是 2.92（1.89 到 4.52）。60 岁以上出现视力损害的比值比，三档依次是 1.71（1.07 到 2.74）、5.54（3.12 到 9.85）、87.63（34.50 到 222.58）。《防控儿童青少年近视核心知识十条》的说法一致：600 度以上为高度近视，这类人群里白内障、开角型青光眼、近视性黄斑病变、视网膜脱离、近视性视神经病变等致盲性眼病的发病率明显高于其他人群，而且「近视可防可控不可逆」', '汇总进去的都是观察性研究，比值比也大得不寻常。高度近视对黄斑变性那一项的可信范围从 230 到 3104，说明底下各项研究差别很大，数字只能看量级，不能当精确值用。这些并发症多数要到中老年才显出来。近视本身不是残疾，绝大多数人戴镜矫正后视力正常。但近视不是配副眼镜就完了，值得花力气推迟它、控制它。确诊之后怎么复查见第 12 条（散瞳验光）。别买号称能治好的产品，见第 9 条（治愈近视）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-7', 'concept_archive_s30-7', 'claim_archive_s30-7', 'action', 'life_archive', '每年那次学生体检的报告单要自己看一遍，异常项当年带去医院查', '30. 上学以后的孩子', '中小学校每年组织一次学生体检。报告单上的重点是超重、肥胖、营养不良、脊柱弯曲异常、视力不良、龋齿，这几样最容易被拖过去。别只看一眼身高体重就收起单子。这几项有异常，当年就带孩子去专科查清楚。', '给 B 是因为这是一份规定学校怎么做的文件，不是效果研究。它保证的是「每年查、查这几项、发现异常要跟进」，不保证查出来就有人管。体检只是先筛一遍，不是确诊。视力不良要去眼科做散瞳验光（第 12 条）。脊柱弯曲异常要去骨科或脊柱外科（第 2 条，别为了等考完推迟治疗）。这两步都得家长自己带孩子去。', NULL, NULL, NULL, '不花钱。义务教育阶段的体检费由学校公用经费出，家长不用另掏。', '《中小学生健康体检管理办法（2021 年版）》规定，中小学校每年组织 1 次在校学生健康体检。外科检查包括头部、颈部、胸部、脊柱、四肢、皮肤、淋巴结。眼科检查包括眼外观、远视力、屈光度（近视远视的度数）。发给个人的报告单应包括查出来的结果、总的评价和健康指导建议。其中超重、肥胖、营养不良、脊柱弯曲异常、视力不良、龋齿（蛀牙）须作为指导重点。教育行政部门应当对出现健康问题的学生建立档案并随访（记下来、之后再跟进）。义务教育阶段学生健康体检费用由学校公用经费开支，家长不另掏（全国，2021 年 9 月印发）', '给 B 是因为这是一份规定学校怎么做的文件，不是效果研究。它保证的是「每年查、查这几项、发现异常要跟进」，不保证查出来就有人管。体检只是先筛一遍，不是确诊。视力不良要去眼科做散瞳验光（第 12 条）。脊柱弯曲异常要去骨科或脊柱外科（第 2 条，别为了等考完推迟治疗）。这两步都得家长自己带孩子去。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-8', 'concept_archive_s30-8', 'claim_archive_s30-8', 'action', 'life_archive', '12 到 18 岁的孩子做一次抑郁筛查，别拿学校的心理测评当诊断', '30. 上学以后的孩子', '美国的预防指南建议给 12 到 18 岁的孩子筛查重度抑郁，11 岁及以下证据不够。自杀是 10 到 19 岁孩子的第二位死因。学校每年的心理测评只是普查，不能当诊断。孩子说难受，或者吃、睡、兴趣、成绩突然变样，直接挂精神科或临床心理科。', '给 B 是因为原文给的是推荐力度的评级，不是能换算成数字的效果。它还是美国的推荐，国内没有对应的官方筛查建议。筛查结果是阳性，只说明要再做一次评估，不等于确诊。有自杀念头时的处置见第 1 节第 25 条。家里的应对见第 29 节。', NULL, NULL, NULL, '0 到几十元，在社区或医院门诊填一份筛查问卷。12355 和 12356 两条热线打电话不要钱。', '美国预防服务工作组 2022 年发了一份推荐声明。它建议对 12 至 18 岁青少年筛查重度抑郁障碍（B 类推荐）。B 类的意思是把握中等、算下来好处也中等，值得做。对 11 岁及以下儿童筛查重度抑郁，证据不足（I 声明，即证据不够，给不出建议）。对儿童青少年专门筛查自杀风险，好处和坏处的证据都不足（I 声明）。文件指出，自杀是 10 至 19 岁人群的第二位死因。文件还指出，儿童青少年的重度抑郁和后来的很多问题关系密切。这些问题包括成年后抑郁反复发作、别的精神障碍，以及自杀念头、自杀未遂、自杀死亡的风险升高。《进一步加强中小学生心理健康工作十条措施》要求构建班主任、专兼职心理健康教师、精神科医师三级服务体系。每名学生每学年接受心理测评，一般不超过 1 次。文件还要求推进精神疾病转介就医和愈后复学机制。它要求发挥 12355 青少年服务台和 12356 心理援助热线的作用（全国，2025 年 10 月印发）', '给 B 是因为原文给的是推荐力度的评级，不是能换算成数字的效果。它还是美国的推荐，国内没有对应的官方筛查建议。筛查结果是阳性，只说明要再做一次评估，不等于确诊。有自杀念头时的处置见第 1 节第 25 条。家里的应对见第 29 节。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-9', 'concept_archive_s30-9', 'claim_archive_s30-9', 'action', 'life_archive', '不买号称能「治愈近视」「降低度数」的产品和服务', '30. 上学以后的孩子', '市场监管总局明说「在目前医疗技术条件下，近视不能治愈」。宣传「恢复」「降低度数」「近视治愈」「度数修复」这类说法的，要从严查处。看到这类词直接排除，不用再比价。护眼仪算医疗器械，电商平台有责任查卖家够不够格卖。', '给 B 是因为依据的是监管部门查处时的认定口径，不是拿产品做对照试验测出来的。但「近视不能治愈」这句话，卫生部门和监管部门说法一致：《防控儿童青少年近视核心知识十条》里写的是「近视可防可控不可逆」。真正有证据的两件事在第 4 条（户外）和第 12 条（规范验光配镜与复查）。防蓝光眼镜见第 6 节。', NULL, NULL, NULL, '不花钱，反过来还省下这笔钱。', '市场监管总局办公厅 2021 年 11 月至 2022 年 3 月的专项整治行动通知明确：「在目前医疗技术条件下，近视不能治愈」。通知要求依法从严查处使用「康复」「恢复」「降低度数」「近视治愈」「近视克星」「度数修复」等误导性表述营销儿童青少年近视防控产品的行为。通知要求加大打击力度，管的是冒用中医药名义、或者假借中医药理论技术做营销宣传欺骗消费者的行为。通知还要求严厉打击两类虚假违法广告：使用患者名义或形象作诊疗前后效果对比的，以及对诊疗安全性、功效作保证性承诺的。通知要求电商平台严格落实护眼仪等医疗器械及有关特殊商品的经营资质审查责任（查清卖家够不够格卖）（全国）', '给 B 是因为依据的是监管部门查处时的认定口径，不是拿产品做对照试验测出来的。但「近视不能治愈」这句话，卫生部门和监管部门说法一致：《防控儿童青少年近视核心知识十条》里写的是「近视可防可控不可逆」。真正有证据的两件事在第 4 条（户外）和第 12 条（规范验光配镜与复查）。防蓝光眼镜见第 6 节。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-10', 'concept_archive_s30-10', 'claim_archive_s30-10', 'action', 'life_archive', '睡眠、作业、体育和排名都有明文规定，学校做不到可以提', '30. 上学以后的孩子', '文件写明，小学生每天睡 10 小时，初中 9 小时，高中 8 小时。小学上午上课一般不早于 8:20，中学不早于 8:00。2025 年又规定每天体育活动不少于 2 小时，不得按考试成绩排名。孩子长期睡不够，先拿这几条去对，别先怪孩子磨蹭。', '这两份都是主管部门发的文件。各地各校执行到什么程度差别很大，所以本条给 B。它们的用处是让你知道哪些事学校本来就该做，去谈的时候手里有依据。成年人的睡眠账见第 2、3 节。', NULL, NULL, NULL, '不花钱。知道条文就行，必要时向学校或当地教育行政部门反映。难在要开口去提。', '《关于进一步加强中小学生睡眠管理工作的通知》规定：小学生每天睡眠应达 10 小时，初中生 9 小时，高中生 8 小时。小学上午上课时间一般不早于 8:20，中学一般不早于 8:00。学校不得要求学生提前到校参加统一的教育教学活动。小学生就寝一般不晚于 21:20，初中生不晚于 22:00，高中生不晚于 23:00。校外培训机构培训结束时间不得晚于 20:30，线上直播类培训结束不得晚于 21:00。每日 22:00 到次日 8:00 不得为未成年人提供游戏服务（全国，2021 年 3 月印发）。《进一步加强中小学生心理健康工作十条措施》另有几条规定：全面推行中小学生每天综合体育活动时间不低于 2 小时，鼓励推行「课间 15 分钟」。它还规定不得以考试成绩对学生进行排名，严禁布置机械重复、惩罚性作业，鼓励每周设置一天「无作业日」（全国，2025 年 10 月印发）', '这两份都是主管部门发的文件。各地各校执行到什么程度差别很大，所以本条给 B。它们的用处是让你知道哪些事学校本来就该做，去谈的时候手里有依据。成年人的睡眠账见第 2、3 节。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-11', 'concept_archive_s30-11', 'claim_archive_s30-11', 'action', 'life_archive', '孩子撑不住了可以休学，学籍学校必须给他留着，最长 1 年', '30. 上学以后的孩子', '休学有正式制度。父母或其他监护人提出申请，学校确认后报上级核准。一次最长 1 年，期满还要休就重新申请。休学期间学校要给孩子保留学籍，复学时回来接着上。具体办法各省定，问学校教务处或当地教育局。', '去办之前先问清三件事：要开什么医疗证明，休学这段时间学籍在系统里怎么记，复学是回原来的年级还是降一级。给 B 是因为休学要什么条件、交什么材料、复学怎么接上，都由省级教育部门自己定，全国层面只搭了个框架。《未成年人学校保护规定》还要求义务教育学校把辍学、休学和长期请假的学生登记备案，所以休学是学校办过的事，不是给你一个人开特例。', NULL, NULL, NULL, '不花钱。由父母或其他法定监护人向学校提出申请。难在要先接受孩子停一段时间。', '《中小学生学籍管理办法》第十六条规定了休学怎么办。学生休学由父母或其他法定监护人提出申请。学校确认后报上级学籍管理部门核准。复学时学校应及时办理相关手续。一次申请休学的期限不超过 1 年，期满后确实还要接着休的，应重新申请办理。学生休学期间学校应为其保留学籍（学生身份和位置给留着）。休学复学的具体办法由省级教育行政部门制定（全国，2025 年 1 月印发）。《进一步加强中小学生心理健康工作十条措施》要求推进精神疾病转介就医和愈后复学机制建设，指导学校制定校园突发心理危机事件处理预案', '去办之前先问清三件事：要开什么医疗证明，休学这段时间学籍在系统里怎么记，复学是回原来的年级还是降一级。给 B 是因为休学要什么条件、交什么材料、复学怎么接上，都由省级教育部门自己定，全国层面只搭了个框架。《未成年人学校保护规定》还要求义务教育学校把辍学、休学和长期请假的学生登记备案，所以休学是学校办过的事，不是给你一个人开特例。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-12', 'concept_archive_s30-12', 'claim_archive_s30-12', 'action', 'life_archive', '查出视力不良，去医院做散瞳验光，之后按医生给的间隔复查', '30. 上学以后的孩子', '散瞳验光是先滴一种眼药水，让眼睛里负责调焦的肌肉松下来，再验度数。这是在医院做的，诊断近视最准。卫健委写明这种药水对健康的眼睛不会造成损伤，停药后恢复正常。别拿眼镜店的一次电脑验光当诊断，也别因为「怕度数涨」不给孩子配镜。', '给 B 是因为这是官方科普文件给的做法，不是带具体数字的原始研究。高度近视会引出视网膜脱离一类的毛病，所以复查不只是为了换眼镜。学生体检查出的「视力不良」只是先筛出来的结果，还要拿去医院做一次完整的眼科检查，见第 7 条。', NULL, NULL, NULL, '几十到几百元的检查费和配镜费。散瞳之后孩子会怕光、看近处模糊，要半天到一两天才缓过来。', '《防控儿童青少年近视核心知识十条》写明了散瞳验光是怎么回事。先用睫状肌麻痹剂，再验光。睫状肌麻痹剂是让眼睛里负责调焦的那块肌肉松下来的眼药水。散瞳验光是在医院做的医学验光，为诊断近视的「金标准」（最准的做法）。散瞳药物对健康的眼睛不会产生损伤，用药后可短期出现怕光、看近处不清楚，停药后可恢复正常。一旦确诊近视，应及时科学干预，通过配戴眼镜等矫正。配戴合适的眼镜可以有效矫正视物不清、延缓近视进展。戴镜视力正常者，学龄前儿童及小学生每 3 至 6 个月复查一次，初高中学生每 6 至 12 个月复查一次，根据具体情况决定是否更换眼镜。儿童在 1 至 3 岁、4 至 6 岁、7 岁之后应定期接受屈光筛查（查度数），监测远视储备量（全国，2023 年 7 月印发）', '给 B 是因为这是官方科普文件给的做法，不是带具体数字的原始研究。高度近视会引出视网膜脱离一类的毛病，所以复查不只是为了换眼镜。学生体检查出的「视力不良」只是先筛出来的结果，还要拿去医院做一次完整的眼科检查，见第 7 条。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-13', 'concept_archive_s30-13', 'claim_archive_s30-13', 'action', 'life_archive', '恒磨牙长出来以后做窝沟封闭', '30. 上学以后的孩子', '窝沟封闭是把大牙咬东西那一面的沟槽用树脂封住，食物残渣就塞不进去。做完两年，长蛀牙的机会约为不封的八分之一。不封时有 16% 的牙面会蛀，封了只有约 5%。四年后仍然有效。', '第一颗恒磨牙（不会再换的那颗大牙）一般 6 岁左右冒头，第二颗 12 岁左右。封闭要趁牙刚长出来、还没坏的时候做，已经蛀了就只能补。不少地区把够年龄孩子的窝沟封闭列成免费项目，问当地疾控中心或社区卫生服务中心。本节没找到能逐字核对的全国性文件，所以不写覆盖范围和年龄段。龋齿也是学生体检重点指导的项目，见第 7 条。', NULL, NULL, NULL, '每颗几十到一两百元。不打麻药，也不用磨牙，一次几分钟。不少地方对够年龄的孩子有免费项目。', '38 项试验、7924 名 5 至 16 岁儿童，由 Cochrane 按规矩找齐后合起来算。拿树脂类封闭剂和不封闭比。5 至 10 岁儿童的第一恒磨牙，做完 24 个月时长蛀牙 OR 0.12（95% CI 0.08–0.19），长蛀牙的机会约为不封闭的八分之一。这一项来自 7 项试验，1548 名抽签分组、1322 名最后受检，证据质量中等。若对照组 24 个月内 16% 的牙面长蛀牙，封闭后为 5.2%（3.13%–7.37%）。对照组 40% 时为 6.25%（3.84%–9.63%）。对照组 70% 时为 19%（12.3%–27.2%）。做完 48 至 54 个月时 OR 0.21（0.16–0.28），仍是不封闭的约五分之一。作者结论为树脂封闭剂在 24 个月时比不封闭少长 11% 至 51% 的蛀牙。4 项记录了不良反应的试验中，没出现不良反应。玻璃离子这类别的封闭材料之间谁更好，证据不足', '第一颗恒磨牙（不会再换的那颗大牙）一般 6 岁左右冒头，第二颗 12 岁左右。封闭要趁牙刚长出来、还没坏的时候做，已经蛀了就只能补。不少地区把够年龄孩子的窝沟封闭列成免费项目，问当地疾控中心或社区卫生服务中心。本节没找到能逐字核对的全国性文件，所以不写覆盖范围和年龄段。龋齿也是学生体检重点指导的项目，见第 7 条。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-14', 'concept_archive_s30-14', 'claim_archive_s30-14', 'action', 'life_archive', '孩子爱打游戏，先看睡觉、作业和出门活动有没有被挤掉，别光盯着玩了多久', '30. 上学以后的孩子', '真正够得上「游戏障碍」的，大约每百人里两三个。问卷门槛定得低、专挑青少年查，比例就会虚高。拿游戏公司的真实记录看，玩多玩少和心情好坏几乎没关系。未成年人按规定只能在周五、周六、周日和节假日晚上 8 点到 9 点玩。', '给 B 是因为患病率随问卷变化太大，幸福感那项研究也只跟了六周。游戏最常见的代价是挤掉睡觉和户外时间。睡觉的明文要求见本节第 10 条（睡眠、作业、体育），户外见本节第 4 条（每天户外 2 小时），屏幕时长见本节第 5 条（非学习用途每天不超过 1 小时）。充值和退款见第 5 节第 9 条（孩子用手机充值打赏）。成绩、睡觉、和家里人的关系一起垮下来，劝也停不下来，这时带孩子去精神科或儿童心理科。别送去封闭管理的戒网瘾学校，见本节第 18 条（戒网瘾学校）。受益人是孩子。', NULL, NULL, NULL, '不花钱。每周留意一次孩子几点睡、作业交没交、有没有出门活动。', '一篇荟萃分析汇总了 17 个国家的 53 项研究、226247 人。游戏障碍的患病率是 3.05%（95% CI 2.38–3.91，这是可信范围）。只算抽样更严格的研究，是 1.96%。各研究结果差得远，77% 的差别出在用的是哪份问卷上。样本是青少年、门槛分数低、样本小，都会让比例偏高。另一项研究拿到 7 家游戏公司的数据，把 38935 名玩家六周的真实游戏时长，和他们自己填的幸福感连起来看。几乎找不到玩的时长影响幸福感的证据。国家新闻出版署规定，游戏企业只能在周五、周六、周日和法定节假日每天 20 时到 21 时，给未成年人提供 1 小时服务（全国 / 国际，2021 年起）', '给 B 是因为患病率随问卷变化太大，幸福感那项研究也只跟了六周。游戏最常见的代价是挤掉睡觉和户外时间。睡觉的明文要求见本节第 10 条（睡眠、作业、体育），户外见本节第 4 条（每天户外 2 小时），屏幕时长见本节第 5 条（非学习用途每天不超过 1 小时）。充值和退款见第 5 节第 9 条（孩子用手机充值打赏）。成绩、睡觉、和家里人的关系一起垮下来，劝也停不下来，这时带孩子去精神科或儿童心理科。别送去封闭管理的戒网瘾学校，见本节第 18 条（戒网瘾学校）。受益人是孩子。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 一般","口径 时间","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-15', 'concept_archive_s30-15', 'claim_archive_s30-15', 'action', 'life_archive', '孩子说自己喜欢同性，别骂、别赶出家门、别送去「矫正」：家里的态度和他会不会自杀有关', '30. 上学以后的孩子', '国内中学生里，喜欢同性或者两性都喜欢的孩子，一年里试过自杀的约是别人的 3 到 5.5 倍。国外研究看到，青春期被家里强烈排斥的孩子，后来试过自杀的多得多。被父母送去「矫正」的，试过自杀的最多。', '给 B 是因为这些都是一次性的调查，家里排斥的程度靠成年后回忆，只能说明有关联，说明不了谁导致谁。家长不必马上认同，先别做伤害孩子的事。法律上，父母不得虐待、遗弃孩子，也不得对孩子实施家庭暴力。经常性的谩骂、恐吓，也算家庭暴力。孩子情绪低落、说不想活了，先打 12356，见第 1 节第 25 条（有自杀念头时打 12356）。也可以按本节第 8 条（12 到 18 岁做一次抑郁筛查）去精神科。「矫正」为什么别碰，见第 6 节第 28 条（不要做性取向矫正）。受益人是孩子，也是你自己。', NULL, NULL, NULL, '不花钱。难在家长要先消化自己的情绪，当下不说狠话。', '国内一项调查覆盖 7 个省 506 所中学，共 150822 名初一到高三的学生。过去一年试过自杀的，男生里只喜欢异性的是 2.2%，只喜欢同性的是 6.9%，两性都喜欢的是 12.2%。女生对应是 3.1%、8.9%、10.9%。算下来约是只喜欢异性的同学的 3 到 5.5 倍。研究者扣除了年龄、学业压力、家庭经济、被欺凌这些因素。之后男生这两组的 OR 是 3.13（95% CI 2.28–4.28）和 3.83（2.85–5.14），高约两到三倍。一篇汇总 35 项研究的荟萃分析算出，性少数青少年试过自杀的 OR 3.50（2.98–4.12）。美国一项研究访问了 224 名 21 到 25 岁的同性恋和双性恋青年，请他们回忆青春期时家里的反应。和家里几乎不排斥的同龄人比，家里排斥程度高的试过自杀的 OR 是 8.4。另一项研究里，父母自己试图改变孩子性取向的，孩子试过自杀的 OR 3.08（1.39–6.83）。父母还把孩子送去找治疗师或宗教人士的，是 5.07（2.38–10.79）（中国 / 多国 / 美国）', '给 B 是因为这些都是一次性的调查，家里排斥的程度靠成年后回忆，只能说明有关联，说明不了谁导致谁。家长不必马上认同，先别做伤害孩子的事。法律上，父母不得虐待、遗弃孩子，也不得对孩子实施家庭暴力。经常性的谩骂、恐吓，也算家庭暴力。孩子情绪低落、说不想活了，先打 12356，见第 1 节第 25 条（有自杀念头时打 12356）。也可以按本节第 8 条（12 到 18 岁做一次抑郁筛查）去精神科。「矫正」为什么别碰，见第 6 节第 28 条（不要做性取向矫正）。受益人是孩子，也是你自己。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-16', 'concept_archive_s30-16', 'claim_archive_s30-16', 'action', 'life_archive', '管孩子别动手打，也别吼骂、骂他笨：常挨打挨骂的孩子，行为和情绪问题都更多', '30. 上学以后的孩子', '常挨打的孩子，攻击性和心理问题都更多，和父母也更疏远，挨更重的打也更多。打能不能让孩子当场听话，证据说不清。13 岁时常被吼、被骂笨的孩子，之后闯祸和抑郁都更多，父母平时再亲热也抵不掉。', '争议。这些研究几乎都只是跟踪记录、没有分组对照，说明不了谁导致谁。打屁股那篇荟萃里，72% 的研究只看两件事是否一起出现，或者靠事后回忆。另一篇荟萃只收前后跟踪的研究，扣掉孩子原来的行为之后，打屁股和外显问题的关联只剩 0.07，和内化问题只剩 0.10。那篇的作者认为影响很小。还有一篇荟萃发现，「有条件地打」在减少不听话和反社会行为上，比 13 种别的管法里的 10 种效果好。它也发现，打得过重或者以打为主，就比别的管法差。所以反方能说明的是：少量、有条件地打，未必比别的管法差。打得重、常打常骂，两边都认为更差。偶尔打一下、吼一句，法条没有明说就是家暴，它点名的是殴打和经常性的谩骂、恐吓。受益人主要是孩子。家里别人打孩子，报警和申请保护令见第 8 节第 43 条（人身安全保护令）。看到别人家长期打孩子，任何人都有权劝阻，或者向公安、民政、教育部门检举。对陌生人家里的事，打 110 或者告诉居委会就够了，别自己上门拉架。', NULL, NULL, NULL, '不花钱。难在火上来的那一刻停住手和嘴，还得换一套不打不骂的管法。换成什么管法，见本节第 17 条（教具体做法的家长课）。', '先看打。一篇荟萃分析只算「张开手打屁股或打手脚」这一种。它汇总了 75 项研究、111 个效果值，共 160927 名孩子。17 项结果里有 13 项和挨打明显有关，方向全是坏的。d 是效果大小，0.2 算小，0.5 算中等。小时候的攻击性 d = 0.37（95% CI 0.13–0.61，可信范围）。外显问题 0.41，指打人、违反规矩这类。内化问题 0.24，指焦虑、抑郁这类。心理健康问题 0.53，和父母关系差 0.51，自尊低 0.15，认知能力差 0.17。被父母施加身体虐待 0.64。长大后的反社会行为 0.36，心理健康问题 0.24。111 个效果值合起来是 d = 0.33（0.29–0.38）。孩子当场听不听话，和挨不挨打关系不明显（d = 0.14，−0.19–0.47），这一项只有 5 个效果值。另一篇综述只看前后跟踪的研究，共 69 项。体罚稳定地预示孩子之后的行为问题变多，没看到它和任何长期的好结果有关。其中 7 项研究看了打的次数，5 项发现打得越多、问题越重。再看吼骂。美国一项研究跟踪了 976 个父母双全的家庭。孩子 13 岁时，父母常吼叫、骂脏话、骂孩子笨或懒，孩子 13 到 14 岁之间闯祸和抑郁症状都增加。父母平时亲不亲热，都抵消不了这个关联。反过来也成立：13 岁时闯祸多的孩子，之后挨骂也更多。法律上，父母不得对孩子实施家庭暴力。《反家庭暴力法》第二条列了家庭暴力的方式：殴打、捆绑、残害、限制人身自由，以及经常性谩骂、恐吓。该法第十二条要求监护人用文明的方式进行家庭教育。父母侵犯孩子权益的，居委会、村委会要劝诫、制止，情节严重的报公安。公安、检察院、法院发现了，应当训诫父母，并可以责令他们接受家庭教育指导（全国）', '争议。这些研究几乎都只是跟踪记录、没有分组对照，说明不了谁导致谁。打屁股那篇荟萃里，72% 的研究只看两件事是否一起出现，或者靠事后回忆。另一篇荟萃只收前后跟踪的研究，扣掉孩子原来的行为之后，打屁股和外显问题的关联只剩 0.07，和内化问题只剩 0.10。那篇的作者认为影响很小。还有一篇荟萃发现，「有条件地打」在减少不听话和反社会行为上，比 13 种别的管法里的 10 种效果好。它也发现，打得过重或者以打为主，就比别的管法差。所以反方能说明的是：少量、有条件地打，未必比别的管法差。打得重、常打常骂，两边都认为更差。偶尔打一下、吼一句，法条没有明说就是家暴，它点名的是殴打和经常性的谩骂、恐吓。受益人主要是孩子。家里别人打孩子，报警和申请保护令见第 8 节第 43 条（人身安全保护令）。看到别人家长期打孩子，任何人都有权劝阻，或者向公安、民政、教育部门检举。对陌生人家里的事，打 110 或者告诉居委会就够了，别自己上门拉架。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-17', 'concept_archive_s30-17', 'claim_archive_s30-17', 'action', 'life_archive', '孩子难管、自己总忍不住打骂，去上一期教具体做法的家长课', '30. 上学以后的孩子', '教家长具体管法的课，在抽签分配的试验里，孩子打人、不守规矩的问题少了，家长的情绪也好了。家长打骂孩子也少了，刚上完课时最明显，一两年后还在，但小了很多。上海也试过这类课，有效。', '给 A 是因为有 Cochrane 和多项抽签试验合并出来的数字。试验里的课有几个共同点。带课的人教具体做法，比如陪孩子玩、夸奖、奖励和管教。家长在课上练习、演练，回家还有作业。只发资料或者只讨论的课被排除在外，所以证据管不到只听一场讲座的那种。国内公益家长学校讲什么、怎么讲，各地不一样，未必是这一类。挑课时看它是不是连上几周、让你练具体做法。课名里常见的有 Triple P、Incredible Years、亲子互动治疗（PCIT）。本书不推荐具体机构和收费产品。打骂少了的效果一两年后变小，课上完还得接着练。受益人是孩子，也是你自己。孩子已经有严重的情绪问题，带去精神科或儿童心理科，见本节第 8 条（抑郁筛查）。', NULL, NULL, NULL, '学校、幼儿园和社区办的家长学校是公益的，不收费。有证据的那类课每周或隔周上一次，每次一到两小时，从四周到二十四周不等。回家要照着练。难在坚持上完、天天练。', 'Cochrane 汇总了 13 项试验，其中 10 项是抽签分组的，共 1078 名家长。孩子 3 到 12 岁，都有行为问题。上过课的家长，孩子的行为问题少了。家长自己评是 SMD −0.53（95% CI −0.72 到 −0.34，可信范围），旁人独立评是 −0.44（−0.77 到 −0.11）。SMD 和 d 是同一把尺子，0.5 算中等。家长的心理健康变好，−0.36（−0.52 到 −0.20）。负面或严厉的管法变少，家长自己评 −0.77（−0.96 到 −0.59），旁人评 −0.42（−0.67 到 −0.16）。作者说这些是短期效果。另一篇荟萃筛出 346 项抽签分组的试验，其中 60 项量了打骂孩子这类行为，分布在 22 个国家。打骂在课刚上完时少了，d = −0.46（−0.59 到 −0.33）。1 到 6 个月后是 −0.24（−0.37 到 −0.11）。7 到 24 个月后是 −0.18（−0.34 到 −0.02），越往后越小。这些数据大多是家长自己报的。国内也有试验。上海 81 名家长抽签分组，一部分上 Triple P 小组课。上完课，孩子的适应问题、家长的管法和情绪，都比等着上课的家长好，6 个月后还在。农村一所幼儿园有 191 名带孩子的大人参加，一部分自学网课，再加两次小组讨论。上完两周，他们报告的虐待孩子行为比只发书读的少约 33%（IRR 0.67）。三个月后，孩子的行为问题也少了（d = −0.40）。《家庭教育促进法》要求父母自觉学习家庭教育知识。中小学校、幼儿园可以办家长学校，定期组织公益性的家庭教育指导。居委会、村委会可以办社区家长学校。省级以上政府要开公益性的网上家长学校和服务热线。家庭教育指导机构不得组织营利性培训（全国，2022 年 1 月 1 日起施行）', '给 A 是因为有 Cochrane 和多项抽签试验合并出来的数字。试验里的课有几个共同点。带课的人教具体做法，比如陪孩子玩、夸奖、奖励和管教。家长在课上练习、演练，回家还有作业。只发资料或者只讨论的课被排除在外，所以证据管不到只听一场讲座的那种。国内公益家长学校讲什么、怎么讲，各地不一样，未必是这一类。挑课时看它是不是连上几周、让你练具体做法。课名里常见的有 Triple P、Incredible Years、亲子互动治疗（PCIT）。本书不推荐具体机构和收费产品。打骂少了的效果一两年后变小，课上完还得接着练。受益人是孩子，也是你自己。孩子已经有严重的情绪问题，带去精神科或儿童心理科，见本节第 8 条（抑郁筛查）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","A 级","性价比 一般","口径 死亡率","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s30-18', 'concept_archive_s30-18', 'claim_archive_s30-18', 'action', 'life_archive', '别把孩子送进封闭管理的「戒网瘾学校」「特训营」：法律禁止用伤害身心的办法戒网瘾，已经有孩子被关死', '30. 上学以后的孩子', '法律明文禁止用伤害孩子身心的办法戒网瘾。合肥一所特训学校把刚送去的男孩铐在禁闭室里，约 44 个小时后人就死了。南昌豫章书院把学生关禁闭，几个负责人被判了刑，家长要求赔学费，法院没支持。', '给 C 是因为只有个案，没有这类学校出事多少的统计。合肥那起只有媒体报道，报道引用了一审判决书和二审裁定书，法院官网上没找到判决原文。豫章书院那起是新华社报道的法院宣判。孩子爱打游戏，先按本节第 14 条（孩子爱打游戏）看睡觉、作业和出门活动有没有被挤掉。成绩、睡觉、家里关系一起垮了，劝也停不下来，带孩子去精神科或儿童心理科，由医生诊断再治。已经送进去的，把孩子接回来。孩子说被关、被打，报警。受益人是孩子。', NULL, NULL, NULL, '不花钱，还省下一笔学费。难在孩子闹得最凶的时候，家长忍住不把他交给外人「封闭管教」。', '《未成年人保护法》第六十八条规定，任何组织和个人不得用侵害未成年人身心健康的方式，干预未成年人沉迷网络。下面两起案子都有法院判决。第一起在安徽合肥。2017 年 8 月，一名 18 岁男孩的父母和一家特训学校签了协议，要送他戒网瘾。学校的人把他强行带走，关进禁闭室，把他的双手铐在窗户栅栏上。他们限制他吃饭、喝水和休息，还打了他。约 44 个小时后，男孩死亡。鉴定结论是高温、限制体位、缺少饮食和外伤，引起水电解质紊乱死亡。2018 年 10 月 31 日，合肥市中级法院一审判决。学校负责人犯故意伤害罪和非法拘禁罪，判 16 年。四名教官判 1 年到 8 年 6 个月。2018 年 12 月 28 日，安徽省高级法院二审维持原判。二审裁定写明，这所学校没有经过有关部门批准，几名被告人也都没有教师资质。第二起在江西南昌。豫章书院 2013 年开办，2017 年 11 月注销停办。办学期间，学校把部分学生带进「烦闷解脱室」关禁闭，派专人看守，每次关三到十天。2023 年 4 月 28 日，萍乡市安源区法院重审一审宣判，五名被告人构成非法拘禁罪。四人判二年十个月到十一个月，并在一定期限内禁止从事和教育有关的职业，一人免予刑事处罚。家长要求赔学费和往返交通费，法院不支持（全国 / 安徽 / 江西）', '给 C 是因为只有个案，没有这类学校出事多少的统计。合肥那起只有媒体报道，报道引用了一审判决书和二审裁定书，法院官网上没找到判决原文。豫章书院那起是新华社报道的法院宣判。孩子爱打游戏，先按本节第 14 条（孩子爱打游戏）看睡觉、作业和出门活动有没有被挤掉。成绩、睡觉、家里关系一起垮了，劝也停不下来，带孩子去精神科或儿童心理科，由医生诊断再治。已经送进去的，把孩子接回来。孩子说被关、被打，报警。受益人是孩子。', '高', 'C', 1, 'strong', 'low', 'action', 'published', '{"30. 上学以后的孩子","C 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-1', 'concept_archive_s31-1', 'claim_archive_s31-1', 'action', 'life_archive', '先把门槛对一遍：十二条路的年龄和学历要求都是明文写死的', '31. 十八岁之后有哪几条路', '这十二条路的年龄和学历门槛，都明文写在文件里。打工要满 16 周岁。当兵是男性满 18 周岁，本科毕业生可以放宽到 24 周岁。考公务员要 18 到 35 周岁、大专以上学历。自考和办个体户这两条，既不看学历，也不看年龄。', '够得着门槛之后，还要过政治条件、体检和政治考核这几关。这几关没有公开的打分标准，条文里查不到。中职、技工院校和职教贯通招生的入口见第 23 节第 5 条，家里供不起时的资助见第 23 节第 4 条。个体户不看学历，但开店并不容易。本钱、个人担保和关门退场的成本见第 12 节。个人担保的意思是公司还不上，就得你自己还。起步钱能不能借到国家替你出一部分利息的贷款，见本节第 16 条。公费师范生和定向医学生这两条，在高考填志愿那天就定下了，代价写在第 13 条。出国打工的门槛不在你身上，在公司有没有资质上，怎么认见第 14 条。哪条路更划算，这里不作比较。', NULL, NULL, NULL, '不花钱。花十分钟对一遍，看自己够不够得着。', '当兵看兵役法：「年满十八周岁的男性公民，应当被征集服现役；当年未被征集的，在二十二周岁以前仍可以被征集服现役。普通高等学校毕业生的征集年龄可以放宽至二十四周岁，研究生的征集年龄可以放宽至二十六周岁」。考公务员看《公务员录用规定》第十八条。报考条件含「年龄为十八周岁以上，三十五周岁以下」「具有大学专科以上文化程度」。这两项经省级以上公务员主管部门批准可适当调整。该规定第十九条列了五类不得报考的人。比如因犯罪受过刑事处罚的、被开除公职的、被列为失信联合惩戒对象的。消防员看《国家综合性消防救援队伍消防员招录办法》。第五条「年龄为 18 周岁以上、22 周岁以下」「具有高中以上文化程度」。第六条「大学专科以上学历人员、解放军和武警部队退役士兵……年龄可以放宽至 24 周岁」。军队文职看《中国人民解放军文职人员条例》第九条，基本条件含「年满 18 周岁」。该条例第十九条写明，较低职级岗位首次招录聘用最高年龄 35 周岁。较低职级岗位就是入门层级的岗位。事业单位看《事业单位人事管理条例》第八条「事业单位新聘用工作人员，应当面向社会公开招聘」。个体户看《促进个体工商户发展条例》「有经营能力的公民……依法登记为个体工商户的，适用本条例」。自考看《高等教育自学考试暂行条例》。第三条「中华人民共和国公民，不受性别、年龄、民族、种族和已受教育程度的限制，均可依照本条例的规定参加高等教育自学考试」。第二十条「各级各类全日制学校的在校生不得报考」。公费师范生看《教育部直属师范大学本研衔接师范生公费教育实施办法》第二条。它只在六所部属师范大学招。分别是北京师范大学、华东师范大学、东北师范大学、华中师范大学、陕西师范大学和西南大学。本科和研究生阶段一体设计、分段考核，本科读完接着读研究生。在校期间的学费和住宿费由中央财政承担，另外还给生活费补助。该办法第五条「招收公费师范生实行提前批次录取」，就是在普通批次之前先录。定向医学生看《关于做好农村订单定向免费培养医学生就业安置和履约管理工作的通知》。它写着：「在录取后、获得入学通知书前，须与培养学校和定向就业所在地的县级卫生健康行政部门……人力资源社会保障部门签署协议」。出国打工看《对外劳务合作管理条例》。第五条：从事对外劳务合作应当经商务主管部门批准取得经营资格。第七条第四款：「未依法取得对外劳务合作经营资格证书并办理登记，不得从事对外劳务合作」。没有这张资格证的公司组织人出国打工，本身就违法。第八条第二款：「任何单位和个人不得以商务、旅游、留学等名义组织劳务人员赴国外工作」。平台接单和灵活就业没有法定学历门槛，自己参保和职业伤害保障的依据见本节第 11、12 条。义务教育法「禁止用人单位招用应当接受义务教育的适龄儿童、少年」（全国）', '够得着门槛之后，还要过政治条件、体检和政治考核这几关。这几关没有公开的打分标准，条文里查不到。中职、技工院校和职教贯通招生的入口见第 23 节第 5 条，家里供不起时的资助见第 23 节第 4 条。个体户不看学历，但开店并不容易。本钱、个人担保和关门退场的成本见第 12 节。个人担保的意思是公司还不上，就得你自己还。起步钱能不能借到国家替你出一部分利息的贷款，见本节第 16 条。公费师范生和定向医学生这两条，在高考填志愿那天就定下了，代价写在第 13 条。出国打工的门槛不在你身上，在公司有没有资质上，怎么认见第 14 条。哪条路更划算，这里不作比较。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 高","口径 时间","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-2', 'concept_archive_s31-2', 'claim_archive_s31-2', 'action', 'life_archive', '十八岁那年 10 月 31 日前要做兵役登记；义务兵服现役就是两年', '31. 十八岁之后有哪几条路', '兵役登记是法定义务，不是报名参军，登记了也不等于要去。当年满 18 周岁的男性，要在 10 月 31 日前上网登记完。不登记的，县里会责令你限期改正，还不改就强制你履行兵役义务并罚款。真去当兵，义务兵服现役就是两年。', '登记和应征是两件事，代价差一大截。两年内不准出境那一串惩戒，只罚应征之后反悔的人，见第 3 条（拒服兵役）。女性不强制做初次兵役登记，按军队需要征集。士兵考军校、表现好的士兵转为军官（提干），条件都写在军队内部法规里，外面查不到。兵役法只写了两句：现役军官从「表现优秀的现役士兵」等人员中选拔招收，军队院校招学员不受征集年龄限制。具体分数线和名额本书不给。', NULL, NULL, NULL, '不花钱。登记在网上填一次，几分钟就填完。真去当兵，代价是两年全职，这两年里没法同时干别的。', '登记看《兵役登记工作规定》。它写着：「县、自治县、不设区的市、市辖区人民政府兵役机关应当于每年 10 月 31 日前，组织本行政区域内当年 12 月 31 日以前年满 18 周岁的男性公民进行初次兵役登记」。同一份规定还写着：「初次兵役登记主要采取网络登记的方式进行，由公民通过兵役登记网络平台自主完成」。不登记会怎么样，看兵役法第五十七条第一款。这一款管的是「拒绝、逃避兵役登记的」。处罚是「由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款」。兵役法还写着「义务兵服现役的期限为二年」。「根据军队需要和本人自愿，可以征集年满十七周岁未满十八周岁的公民服现役」。军士「服现役满十二年或者符合国家规定的其他条件的，由安置地的县级以上地方人民政府安排工作」。军士「服现役满三十年或者年满五十五周岁或者符合国家规定的其他条件的，作退休安置」。安排工作就是由政府给一份工作，退休安置就是按退休办退下来。《征兵工作条例》写着「优先保证普通高等学校毕业生和对政治、身体条件或者专业技能有特别要求的兵员征集」。该条例还写着「应征公民为普通高等学校的全日制在校生、应届毕业生的，可以在入学前户籍所在地或者学校所在地应征」（全国）', '登记和应征是两件事，代价差一大截。两年内不准出境那一串惩戒，只罚应征之后反悔的人，见第 3 条（拒服兵役）。女性不强制做初次兵役登记，按军队需要征集。士兵考军校、表现好的士兵转为军官（提干），条件都写在军队内部法规里，外面查不到。兵役法只写了两句：现役军官从「表现优秀的现役士兵」等人员中选拔招收，军队院校招学员不受征集年龄限制。具体分数线和名额本书不给。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 时间","钱 0","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-3', 'concept_archive_s31-3', 'claim_archive_s31-3', 'action', 'life_archive', '应征之后拒服兵役，两年内不准出境或升学复学，还进不了公务员和国企', '31. 十八岁之后有哪几条路', '报了名又拒绝去当兵，后果是一串。公务员不能录用你，国有企业和事业单位也不能招你。两年内不准出境，不准升学，不准回学校复学。还会被列进履行国防义务严重失信主体名单。所以「先报上再说，不行就退回来」是个很贵的想法。', '这里算的是人身自由和就业资格，不是钱。这一串惩戒只罚两种人。一种是「应征公民拒绝、逃避征集服现役」的。另一种是入伍以后被除名、开除军籍、被追究刑责的。光是没做兵役登记的不在里面，兵役登记见第 2 条。罚的前提是「拒不改正」，由县级人民政府认定和处罚。罚多少钱各地自己定，本书不写。去不去由你自己定，但要在报名之前定下来。', NULL, NULL, NULL, '不花钱。代价是在报名之前，就要把去不去想清楚。', '兵役法第五十七条第一款第二项是「应征公民拒绝、逃避征集服现役的」。处罚同样是「由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款」。同一条第二款：「有前款第二项行为，拒不改正的，不得录用为公务员或者参照《中华人民共和国公务员法》管理的工作人员，不得招录、聘用为国有企业和事业单位工作人员，两年内不准出境或者升学复学，纳入履行国防义务严重失信主体名单实施联合惩戒。」联合惩戒就是多个部门照同一份名单，一起执行上面这些限制。第五十八条把同一套惩戒接到已经入伍的人身上。军人以逃避服兵役为目的，拒绝履行职责或者逃离部队，后果要看处理结果。被军队除名、开除军籍或者被依法追究刑事责任的，依照第五十七条第二款处罚。其中被除名的并处罚款（全国，2021 年 10 月 1 日起施行）', '这里算的是人身自由和就业资格，不是钱。这一串惩戒只罚两种人。一种是「应征公民拒绝、逃避征集服现役」的。另一种是入伍以后被除名、开除军籍、被追究刑责的。光是没做兵役登记的不在里面，兵役登记见第 2 条。罚的前提是「拒不改正」，由县级人民政府认定和处罚。罚多少钱各地自己定，本书不写。去不去由你自己定，但要在报名之前定下来。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-4', 'concept_archive_s31-4', 'claim_archive_s31-4', 'action', 'life_archive', '大学生当兵最实的两块：学费每年补最高 20000 元，学籍保留两年、考研有专项计划', '31. 十八岁之后有哪几条路', '在校生、应届毕业生和新生去当兵，国家替你出读书那几年的学费，按实际交的补，本专科生每年最高 20000 元，研究生最高 25000 元。学费本来就低的，只补到实际交的那么多。学籍给你留两年。考研另有一条只招退役大学生士兵的专项计划。', '还有两条通道。一是专升本免考文化课：专科生去当兵，退役后读完专科，可以申请免试专升本，由学校考职业技能后择优录取。这条从 2022 年招生起执行，具体办法看本省当年的通知。二是考研初试加 10 分：退役大学生士兵退役后 3 年内考研，初试总分加 10 分。报了专项计划就不再加分，两样不能一起享受。立过二等功以上的，可以申请免初试读研。招专项计划的学校名单每年变，2025 年是 523 所。学费标准调过两次：2019 年是 8000/12000，2023 年秋改成 16000/20000，2024 年秋改成 20000/25000。退役军人事务部 2022 年的摘要里还是最早那一版，别照抄。', NULL, NULL, NULL, '不花钱。退役以后按学校要求交材料申请，前后跑一两趟。', '财政部等四部门 2024 年通知说，去服兵役的高校学生有三样待遇：学费补偿、用于学费的国家助学贷款代偿、学费减免。代偿就是国家替你把这笔助学贷款还掉。这三样的标准「相应调整为本专科学生每人每年最高不超过 20000 元、研究生每人每年最高不超过 25000 元」。新标准自 2024 年秋季学期起执行。到底按多少补，看这一句：「按学生实际缴纳的学费或获得的国家助学贷款（包括本金及其全部偿还之前产生的利息）两者金额较高者执行」。后面还有一句是「超出标准部分不予补偿、代偿或减免」。所以每年拿到的，是「实际学费和助学贷款里较高的那个」与上限两者中较小的那个。学费每年 5000 元的就补 5000 元。补几年按读书的年数算，不按服役的年数算。2019 年的学生资助资金管理办法写着：「入伍前已完成规定的修业年限，即为学费补偿或国家助学贷款代偿的年限；退役复学后接续完成规定的剩余修业年限，即为学费减免的年限」。应届毕业生去当兵，补的是整个学制的学费。学籍看《退役军人保障法》。它写着：「现役军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习」。该法还写着：「高等学校根据国家统筹安排，可以通过单列计划、单独招生等方式招考退役军人」。考研看教育部办公厅 2026 年通知。这个计划叫「退役大学生士兵计划」。通知写着：「在全国硕士研究生招生计划总规模内单列下达、专项使用，不得调整为普通计划或其他专项计划。招生单位自主确定……初试成绩要求（一般不高于本单位相应学科专业普通计划考生初试成绩要求）……同等条件下服役时间长的考生优先录取」。单列、专项使用的意思是，这部分名额单独划出来，只能用来招退役大学生士兵。这个计划 2026 年由 532 所普通高等学校承担（全国）', '还有两条通道。一是专升本免考文化课：专科生去当兵，退役后读完专科，可以申请免试专升本，由学校考职业技能后择优录取。这条从 2022 年招生起执行，具体办法看本省当年的通知。二是考研初试加 10 分：退役大学生士兵退役后 3 年内考研，初试总分加 10 分。报了专项计划就不再加分，两样不能一起享受。立过二等功以上的，可以申请免初试读研。招专项计划的学校名单每年变，2025 年是 523 所。学费标准调过两次：2019 年是 8000/12000，2023 年秋改成 16000/20000，2024 年秋改成 20000/25000。退役军人事务部 2022 年的摘要里还是最早那一版，别照抄。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-5', 'concept_archive_s31-5', 'claim_archive_s31-5', 'action', 'life_archive', '退役后只有六种情况由政府安排工作；自主就业的 30 日内必须报到', '31. 十八岁之后有哪几条路', '「当兵包分配」早就不是普遍情况。现在只有六种情况由政府安排工作，义务兵服两年退役，绝大多数不在这六种里面。不由政府安排工作的那一档叫自主就业，它有个硬期限：退出现役之后 30 日内必须去报到。没有正当理由超过 30 日，就算你放弃安置待遇。', '这份条例施行的同一天，2011 年的《退役士兵安置条例》（国务院、中央军委令第 608 号）废止。网上大量攻略引的还是旧条例，条件表述已经变了，旧版写的是「平时荣获二等功以上奖励或者战时荣获三等功以上奖励」。30 日这个期限只管自主就业那一档，其他安置方式是「按照规定时间」报到。报到时会发退役军人优待证，后面的退役金、就业创业扶持和教育资助都从这里接上。', NULL, NULL, NULL, '不花钱。带上退役证明，到安置地的退役军人事务部门跑一趟。', '《退役军人安置条例》第二十五条列了六种情形，由安置地人民政府安排工作。原文是：「（一）军士服现役满 12 年的；（二）服现役期间个人获得勋章、荣誉称号的；（三）服现役期间个人荣获三等战功、二等功以上奖励的；（四）服现役期间个人获得一级表彰的；（五）因战致残被评定为 5 级至 8 级残疾等级的；（六）是烈士子女的」。该条例还写着：「安置地人民政府应当在接收退役军士和义务兵的 6 个月内完成安排退役军士和义务兵工作的任务」。用人单位「应当按照规定与其签订不少于 3 年的中长期聘用合同或者劳动合同。其中，企业接收军龄 10 年以上的退役军士的，应当与其签订无固定期限劳动合同」。无固定期限就是合同上不写到期日。待安排工作期间「按照当地月最低工资标准逐月发放生活补助」。不是因为你自己的原因没按规定安排上岗的，「按照不低于本单位同等条件人员平均工资 80% 的标准，逐月发放生活费直至上岗为止」。不得以安排工作方式安置的情形，包括被开除中国共产党党籍、受过刑事处罚。自主就业的期限看第五十一条：「自主就业的退役军士和义务兵，应当自被批准退出现役之日起 30 日内，到安置地人民政府退役军人工作主管部门报到。无正当理由不按照规定时间报到超过 30 日的，视为放弃安置待遇。」（全国，2024 年 9 月 1 日起施行）', '这份条例施行的同一天，2011 年的《退役士兵安置条例》（国务院、中央军委令第 608 号）废止。网上大量攻略引的还是旧条例，条件表述已经变了，旧版写的是「平时荣获二等功以上奖励或者战时荣获三等功以上奖励」。30 日这个期限只管自主就业那一档，其他安置方式是「按照规定时间」报到。报到时会发退役军人优待证，后面的退役金、就业创业扶持和教育资助都从这里接上。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-6', 'concept_archive_s31-6', 'claim_archive_s31-6', 'action', 'life_archive', '退役后的三笔账：一次性退役金、军龄算工龄、自己干每年扣减 20000 元税', '31. 十八岁之后有哪几条路', '退役之后有三笔账。第一笔是自主就业的一次性退役金，按服现役年限发，立过功的还增发。第二笔是当兵这几年不算社保空白，军龄算工龄，缴费年限跟入伍前和退役后合着算。第三笔是税：自己开店做生意的，3 年内每年最多能少交 20000 元的税。', '条例只写了金额由主管部门另定。能查到的官方数字是退役军人事务部官网 2020 年刊文里的「服现役每满一年，发给4500元」，同一篇也写着「适时调整」。那篇文章里的增发比例已经和现行条例对不上，要以条例为准。贵州省退役军人事务厅 2024 年 8 月刊文，在新条例之下仍写「现在执行的标准是：士兵服现役每满一年，发给4500元」。TODO（待核实：没找到正式的标准文件，只能确认到 2024 年 8 月省级部门仍这么写）。另外别把地方的「一次性经济补助」和它混在一起。那是各地自己定、自己发的另一笔钱，比如烟台 2024 年退役的每服役一年补助 6000 元。攻略上的新数字多数没有出处，有的就是把这两笔混在了一起。义务兵服役期间，家里还能另领一笔家庭优待金。兵役法只写「标准由地方人民政府制定，中央财政给予定额补助」，具体多少问批准你入伍的那个县级人民政府。税那一笔是每年最多能少交多少税。生意没做起来就用不满，所以整条的收益量级只定「中」。2026 年 8 月 1 日起施行的《退役军人就业创业促进条例》另加了一条：服役期间考到的技能人员职业资格证书，退役后全国通用。', NULL, NULL, NULL, '不花钱。退役时军队把你的社保关系和钱转出来。你再到安置地的社保经办机构（办社保的窗口）办接续。', '第一笔看《退役军人安置条例》。它写着：「对自主就业的退役军士和义务兵，根据其服现役年限发放一次性退役金」。钱由谁出：「由中央财政专项安排，具体标准由国务院退役军人工作主管部门、中央军事委员会政治工作部门会同国务院财政部门……确定，并适时调整」。增发比例分五档。获得勋章、荣誉称号增发 25%，一等战功或一级表彰 20%。二等战功、一等功或二级表彰 15%。三等战功或二等功 10%，四等战功或三等功 5%。该条例还写着：「退役军人未及时就业的，可以依法向户口所在地人力资源社会保障部门申领失业保险待遇，服现役年限视同参保缴费年限，但是以退休、供养方式安置的退役军人除外」。视同缴费年限的意思是，这几年你没交过钱，也按交过算。第二笔看《退役军人保障法》：「退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算」。工龄就是参加工作的年数，服役这几年和退役后的年数接着往上加。该法还写着，服现役年限与入伍前、退役后的养老、医疗、失业缴费年限「依法合并计算」，「退役的军士和义务兵服现役经历视为基层工作经历」。《军人保险法》：「军人服现役年限视同职工基本医疗保险缴费年限，与入伍前和退出现役后参加职工基本医疗保险的缴费年限合并计算」。第三笔看财政部、税务总局、退役军人事务部 2023 年第 14 号公告。公告写的是自主就业退役士兵从事个体经营的情形：「在 3 年（36 个月，下同）内按每户每年 20000 元为限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税。限额标准最高可上浮 20%」。扣减就是从当年该交的这几种税里按顺序往下减，减到限额为止，不是发给你的钱。企业招用的「定额标准为每人每年 6000 元，最高可上浮 50%」。执行期为 2023 年 1 月 1 日至 2027 年 12 月 31 日。到期未满 3 年的可继续享受至期满（全国）', '条例只写了金额由主管部门另定。能查到的官方数字是退役军人事务部官网 2020 年刊文里的「服现役每满一年，发给4500元」，同一篇也写着「适时调整」。那篇文章里的增发比例已经和现行条例对不上，要以条例为准。贵州省退役军人事务厅 2024 年 8 月刊文，在新条例之下仍写「现在执行的标准是：士兵服现役每满一年，发给4500元」。TODO（待核实：没找到正式的标准文件，只能确认到 2024 年 8 月省级部门仍这么写）。另外别把地方的「一次性经济补助」和它混在一起。那是各地自己定、自己发的另一笔钱，比如烟台 2024 年退役的每服役一年补助 6000 元。攻略上的新数字多数没有出处，有的就是把这两笔混在了一起。义务兵服役期间，家里还能另领一笔家庭优待金。兵役法只写「标准由地方人民政府制定，中央财政给予定额补助」，具体多少问批准你入伍的那个县级人民政府。税那一笔是每年最多能少交多少税。生意没做起来就用不满，所以整条的收益量级只定「中」。2026 年 8 月 1 日起施行的《退役军人就业创业促进条例》另加了一条：服役期间考到的技能人员职业资格证书，退役后全国通用。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-7', 'concept_archive_s31-7', 'claim_archive_s31-7', 'action', 'life_archive', '想进体制内不止考公一条：基层服务项目干满两年，能报每年 10% 的定向考录计划', '31. 十八岁之后有哪几条路', '想进体制内，不是只有考公一条路。「三支一扶」这类基层服务项目干满两年、考核合格，就能报只面向这些人的定向考录计划。各省每年要拿出公务员考录计划的 10% 左右招这些人。三年内考研，初试总分还加 10 分。代价是这两年拿的是财政补助。', '第四轮三支一扶计划管的是 2021 到 2025 年。这次没找到第五轮文件和 2026 年度通知，报名前查当年的招募公告。2025 年中央财政支持招募 34430 名。西部计划的实施方案原文在网上查不到，官网那个政策栏目打不开内容。它期满之后的优惠，按中办国办那份管所有基层服务项目的文件走。这两年拿的是财政补助，不是市场工资，这笔代价要和两年后的定向考录放在一起算。', NULL, NULL, NULL, '不花钱。代价是到乡镇基层服务两年。这两年拿的是财政补助，不是市场工资，难的是要耐得住这两年。', '第四轮「三支一扶」计划通知写着「服务期为两年」。它还写着：「各省（区、市）每年应拿出公务员考录计划的 10％左右，面向『三支一扶』计划等服务基层项目人员定向考录。各省（区、市）县乡基层事业单位公开招聘时，应根据本地区实际拿出一定数量或比例的岗位，对『三支一扶』服务期满考核合格的人员进行专项招聘……聘用后可以不再约定试用期」。定向考录和专项招聘的意思是，这部分名额只在干过基层服务项目的人里面考，别人报不了。同一份通知还写着：「期满考核合格的『三支一扶』人员，三年内参加全国硕士研究生招生考试的，初试总分加 10 分，同等条件下优先录取……高职（高专）毕业生期满且考核合格的，可免试入读成人高等学历教育专科起点本科」。免试入读就是不用再考试，直接去读专升本。通知还写着：「参加『三支一扶』计划前无工作经历的人员期满且考核合格的，两年内在参加机关和企事业单位考录（招聘）、自主创业、落户、升学等方面可同等享受应届毕业生相关政策。『三支一扶』人员在基层服务年限计算为工龄，其参加工作时间按其到基层报到之日起算」。中央财政补助标准为西部地区每人每年 3 万元、中部地区 2.4 万元、东部地区 1.2 万元。中办国办的意见写着：「参加基层服务项目前无工作经历的人员服务期满且考核合格后 2 年内，在参加机关事业单位考录（招聘）、各类企业吸纳就业、自主创业、落户、升学等方面可同等享受应届高校毕业生的相关政策」。该意见还写着：「省级以上机关录用公务员，除特殊职位外，按照有关规定一律从具有 2 年以上基层工作经历的人员中考录」。另一条路是西部计划。它由「共青团中央、教育部、财政部、人力资源社会保障部共同组织实施」。它招募高校应届毕业生或在读研究生，「到西部基层从事为期 1—3 年」的志愿服务（全国）', '第四轮三支一扶计划管的是 2021 到 2025 年。这次没找到第五轮文件和 2026 年度通知，报名前查当年的招募公告。2025 年中央财政支持招募 34430 名。西部计划的实施方案原文在网上查不到，官网那个政策栏目打不开内容。它期满之后的优惠，按中办国办那份管所有基层服务项目的文件走。这两年拿的是财政补助，不是市场工资，这笔代价要和两年后的定向考录放在一起算。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-8', 'concept_archive_s31-8', 'claim_archive_s31-8', 'action', 'life_archive', '特岗教师三年服务期满、考核合格又愿意留下的，应当及时入编', '31. 十八岁之后有哪几条路', '特岗计划是少数几条写明「期满入编」的路。条件是本科及以上学历、以师范类专业为主，年龄不超过 30 周岁，还要有相应的教师资格证。服务期三年，这三年的工资待遇跟当地公办学校的在编教师一样。三年期满考核合格、又愿意留下的，文件要求及时入编。', '收益量级定「大」，是因为期满入编等于拿到一份长期的在编工作，值的钱远过万元。能查到的最新一份是 2024 年度通知，2025、2026 年度的没进政策库。具体岗位、补助标准和年龄，以当年通知和本省的实施方案为准。中央定大框架，细则由省里定。教师资格证要先考出来，不能入职以后再补。', NULL, NULL, NULL, '不花钱。代价是三年在农村义务教育学校任教，进门前还得先考出教师资格证。难的是这三年要待得住。', '2024 年特岗计划通知写的招聘条件是：「要求本科及以上学历，以师范类专业为主，小学阶段可适当招聘师范高等专科学校毕业生」。「年龄不超过 30 周岁」。还须具有相应的教师资格证书。通知另写着：「参加过『大学生志愿服务西部计划』、有从教经历的志愿者和参加过半年以上实习支教的师范院校毕业生同等条件下优先录取」。「支持鼓励符合条件的退役军人到中小学任教，可综合考虑服役年限等因素对退役军人相应放宽年龄限制」。待遇和入编看这几句。「从 2024 年 1 月 1 日起，提高特岗教师工资性补助标准，中央财政……中部地区由年人均 3.52 万元提高到 3.88 万元，西部地区由 3.82 万元提高到 4.18 万元」。「同等条件下在薪酬待遇、职称评聘、评先评优、年度考核等方面享受与当地公办学校在编教师同等待遇」。「保证三年服务期满、考核合格且愿意留任的特岗教师及时入编并落实工作岗位，做好相关人事、工资关系等接转工作，连续计算工龄、教龄，不再实行试用期」（全国）', '收益量级定「大」，是因为期满入编等于拿到一份长期的在编工作，值的钱远过万元。能查到的最新一份是 2024 年度通知，2025、2026 年度的没进政策库。具体岗位、补助标准和年龄，以当年通知和本省的实施方案为准。中央定大框架，细则由省里定。教师资格证要先考出来，不能入职以后再补。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-9', 'concept_archive_s31-9', 'claim_archive_s31-9', 'action', 'life_archive', '消防员和军队文职是另外两个公开招录的口子，门槛比考公低', '31. 十八岁之后有哪几条路', '这两条路都不卡「大专以上」这道门槛。消防员招 18 到 22 周岁、高中以上文化程度的人，大专以上学历的人和退役士兵可以放宽到 24 周岁。军队文职只要求年满 18 周岁，入门层级的岗位首次招录最高 35 周岁。共同的代价是政治考核和体检刷人。', '2026 年 8 月 1 日起施行的《退役军人就业创业促进条例》另写明了两件事。一是消防员招录要拿出一定比例，专门招退役军士和义务兵。二是招警务辅助人员（辅警）的时候，同等条件下优先招退役军人。这两条路每年的名额、岗位和具体条件都以当年公告为准，本书只写办法里固定不变的门槛。消防员是纪律部队的岗位，进去之前把职业风险想清楚。', NULL, NULL, NULL, '不花钱。从报名到录用要走体检、政治考核、体能测试、心理测试和面试，前后几个月。难在这几关一关一关刷人。', '消防员看《国家综合性消防救援队伍消防员招录办法》。第五条基本条件含「年龄为 18 周岁以上、22 周岁以下」「具有高中以上文化程度」。第六条「大学专科以上学历人员、解放军和武警部队退役士兵、具有 2 年以上灭火救援实战经验的政府专职消防队员和政府专职林业扑火队员，年龄可以放宽至 24 周岁；对消防救援工作急需的特殊专业人才，经应急管理部批准年龄可以进一步放宽，原则上不超过 28 周岁」。第七条「消防员面向社会公开招录，主要从本省级行政区域常住人口中招录，根据需要也可以面向其他省份招录」。第九条写的招录程序是「宣传动员、组织报名、资格审查、体格检查、政治考核、体能测试和岗位适应性测试、心理测试和面试、公示、录用」。军队文职看《中国人民解放军文职人员条例》第十八条「军队实行公开招考、直接引进、专项招录相结合的文职人员招录聘用制度」。这是三条线：公开考试招人，直接引进现成的人才，面向特定人群专门招。该条例第九条基本条件含「年满 18 周岁」「符合军队招录聘用文职人员的政治条件」「符合岗位要求的文化程度、专业水平和工作能力」。第十九条写明，较低职级岗位首次招录聘用最高年龄 35 周岁。该条例还写明「文职人员岗位应当优先招录聘用符合条件的退役军人」（全国）', '2026 年 8 月 1 日起施行的《退役军人就业创业促进条例》另写明了两件事。一是消防员招录要拿出一定比例，专门招退役军士和义务兵。二是招警务辅助人员（辅警）的时候，同等条件下优先招退役军人。这两条路每年的名额、岗位和具体条件都以当年公告为准，本书只写办法里固定不变的门槛。消防员是纪律部队的岗位，进去之前把职业风险想清楚。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-10', 'concept_archive_s31-10', 'claim_archive_s31-10', 'action', 'life_archive', '学历不是一锤子买卖：自考不限年龄和已受教育程度，成人高考和开放大学都能补', '31. 十八岁之后有哪几条路', '十八岁那年没读成书，后面还有三条正规通道：自考、成人高考、开放大学。自考不限年龄，也不看你原来读到哪一级，但全日制在校生不能报。成人高考要先有高中或者专科的毕业证。三条路都慢，但都不看你十八岁那年考成什么样。', '还有一种给应届全日制大专毕业生读的普通专升本。全国层面公开的文件是教育部 2007 年的通知，写的是专升本计划不超过当年应届专科毕业生的 5%。2020 年起教育部扩大了专升本规模，当年同比增加 32.2 万人，5% 这条线实际已经不按它执行。每年的具体安排是教育部高校学生司发的函，比如 2026 年是教学司函〔2025〕53 号。这份函不对外公布，只能从各省转发的文件里看到文号。招生对象由各省自己定，基本只收本省当届全日制专科毕业生，所以正文不写它的条件。2025 年秋季起，高等学历继续教育不再叫「函授」「业余」，统一叫「非脱产」。高等学历继续教育就是成人后来补学历的那一类，还在用旧名称的宣传要留神。补学历和「学什么技能划算」是两件事，后者见第 23 节。花钱买的「快速拿证」和山寨证书见第 23 节第 8 条。', NULL, NULL, NULL, '报名费和教材费每年几百元。代价是长期自学，或者业余去上课，非脱产（边工作边读）的专升本最短要读两年半，难在要长期坚持。', '自考看《高等教育自学考试暂行条例》。第三条：「中华人民共和国公民，不受性别、年龄、民族、种族和已受教育程度的限制，均可依照本条例的规定参加高等教育自学考试」。第二十条：「各级各类全日制学校的在校生不得报考」。第二十五条写了拿毕业证的三个条件：考完全部课程并合格、完成毕业论文或实践任务、思想品德鉴定合格。都做到了就可取得毕业证书。这一条还写着「获得专科（基础科）或本科毕业证书者，国家承认其学历」。第三十二条写毕业证书获得者的工资待遇：「非在职人员录用后，与普通高等学校同类毕业生相同」。《高等教育法》第二十一条「国家实行高等教育自学考试制度，经考试合格的，发给相应的学历证书或者其他学业证书」。成人高考看《2025 年全国成人高校招生办法》。报名对象是「国家承认学历的各类高、中等学校在校生以外的从业人员和社会其他人员」。「报考高起本或高起专的考生应高级中等教育学校毕业或者具有同等学力。报考专升本的考生必须是已取得……专科毕业证书、本科结业证书或以上证书的人员」。「脱产最短学习时间为：高起本四年、高起专和专升本两年，非脱产最短学习时间为：高起本五年、高起专和专升本两年半」。脱产就是离开工作全天在校读，非脱产就是不离开工作、边干边读。开放大学看《教育部关于办好开放大学的意见》。它写着：「开放大学实行注册入学，学生修完课程并获得相应学分，即可获得课程证书，修满规定的学分并达到相关要求，即可获得相应的学历与非学历证书，符合学位授予条件的应授予相应学位」（全国）', '还有一种给应届全日制大专毕业生读的普通专升本。全国层面公开的文件是教育部 2007 年的通知，写的是专升本计划不超过当年应届专科毕业生的 5%。2020 年起教育部扩大了专升本规模，当年同比增加 32.2 万人，5% 这条线实际已经不按它执行。每年的具体安排是教育部高校学生司发的函，比如 2026 年是教学司函〔2025〕53 号。这份函不对外公布，只能从各省转发的文件里看到文号。招生对象由各省自己定，基本只收本省当届全日制专科毕业生，所以正文不写它的条件。2025 年秋季起，高等学历继续教育不再叫「函授」「业余」，统一叫「非脱产」。高等学历继续教育就是成人后来补学历的那一类，还在用旧名称的宣传要留神。补学历和「学什么技能划算」是两件事，后者见第 23 节。花钱买的「快速拿证」和山寨证书见第 23 节第 8 条。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 少","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-11', 'concept_archive_s31-11', 'claim_archive_s31-11', 'action', 'life_archive', '不进单位就是灵活就业：养老和医疗要自己在就业地参保，户籍限制已经放开', '31. 十八岁之后有哪几条路', '不进单位，不等于没有社保这回事，只是没人替你交那一半。文件要求各地放开灵活就业人员在就业地参保的户籍限制，个别超大城市可以逐步放开。所以别把「自由」理解成不用管社保。断着不交，退休金和医保报销都要按断缴的规则算。', '原文写的是「放开」户籍限制，还给超大城市留了口子，不是「全国已经取消」。到底放开到什么程度，问你要参保的那个城市。收益量级定「大」，是因为断缴丢的是养老和医疗待遇本身，值的钱远过万元。但成本也实打实，全额自缴每月上千元。社保断缴之后怎么补、年限怎么累计，见第 7 节第 18 条（社保断缴）。换城市以后养老和医保关系怎么转过去，见第 19 节第 19 条（养老和医保关系转到新参保地）。自己交职工养老按哪一档交、要领多少年才回本，见第 5 节第 46 条（自己交职工养老保险）。另外，在政府指定的地点和时间卖农副产品、日用品，或者用自己的手艺做依法不需要许可的便民活儿，不用办营业执照。这一条写在国办发〔2020〕27 号里。', NULL, NULL, NULL, '养老和医疗要你全额自己缴，按当地的缴费基数算，每月上千元。缴费基数就是一个用来算保费的基准数。这是灵活就业最容易被漏算的固定支出，难在每个月都得按时交。', '参保看《关于维护新就业形态劳动者劳动保障权益的指导意见》。它写着：「各地要放开灵活就业人员在就业地参加基本养老、基本医疗保险的户籍限制，个别超大型城市难以一步实现的，要结合本地实际，积极创造条件逐步放开。组织未参加职工基本养老、职工基本医疗保险的灵活就业人员，按规定参加城乡居民基本养老、城乡居民基本医疗保险，做到应保尽保。督促企业依法参加社会保险。企业要引导和支持不完全符合确立劳动关系情形的新就业形态劳动者根据自身情况参加相应的社会保险」。同一份文件把用工分成三类：「符合确立劳动关系情形的，企业应当依法与劳动者订立劳动合同。不完全符合确立劳动关系情形但企业对劳动者进行劳动管理……指导企业与劳动者订立书面协议……个人依托平台自主开展经营活动、从事自由职业等，按照民事法律调整双方的权利义务」（全国，2021 年起）', '原文写的是「放开」户籍限制，还给超大城市留了口子，不是「全国已经取消」。到底放开到什么程度，问你要参保的那个城市。收益量级定「大」，是因为断缴丢的是养老和医疗待遇本身，值的钱远过万元。但成本也实打实，全额自缴每月上千元。社保断缴之后怎么补、年限怎么累计，见第 7 节第 18 条（社保断缴）。换城市以后养老和医保关系怎么转过去，见第 19 节第 19 条（养老和医保关系转到新参保地）。自己交职工养老按哪一档交、要领多少年才回本，见第 5 节第 46 条（自己交职工养老保险）。另外，在政府指定的地点和时间卖农副产品、日用品，或者用自己的手艺做依法不需要许可的便民活儿，不用办营业执照。这一条写在国办发〔2020〕27 号里。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-12', 'concept_archive_s31-12', 'claim_archive_s31-12', 'action', 'life_archive', '送外卖、跑网约车、拉同城货运，平台按单给你交职业伤害保障费，自己不缴', '31. 十八岁之后有哪几条路', '送外卖、跑网约车、拉同城货运的人，平台要按单替你缴职业伤害保障费，你自己一分钱不出，每接一单就保一单。这还是试点，接单前先查自己所在的省份和平台在不在范围里。已经和平台建立劳动关系的，走工伤保险，不走这套。', '这还是试点，不是全国都有的正式制度。接单前确认你所在的省份和平台在不在范围里，不在的就只剩自己买商业保险这一层。另一份文件《关于维护新就业形态劳动者劳动保障权益的指导意见》还提了几条要求。平台给正常干活的人开的报酬不低于当地最低工资，要按时足额发，不得克扣或者无故拖欠。法定节假日还要付合理报酬。这份文件的文号是人社部发〔2021〕56 号，灵活就业那条也引了它，见第 11 条。出了事先照这套走，别先跟站点私了。医保和养老那一块还得自己参保，灵活就业参保见第 11 条。', NULL, NULL, NULL, '不花钱，这笔钱由平台缴。你要做的是查自己接单的平台在不在试点里。办法有两个：在 App 的保障或权益页面找「职业伤害保障」，或者打本省人社局的电话，问这家平台报没报。', '这项保障看《新就业形态人员职业伤害保障办法（试行）》。第二条写着：「平台企业应当依照本办法规定参加新就业形态人员职业伤害保障……为通过平台注册并接单，以平台企业名义提供出行、即时配送和同城货运等劳动并获得报酬或者收入的新就业形态人员缴纳职业伤害保障费，实现每单必保、每人必保。适用《工伤保险条例》规定的劳动者，企业应当依法为其参加工伤保险，不适用本办法」。第九条：「试行期间，出行行业按照每单 0.01 元执行；即时配送行业按照每单 0.07 元、0.25 元执行；同城货运行业按照每单 0.18 元执行」。试点怎么往外扩，看这一段：「2025 年 7 月 1 日起，在已先行试点 7 个省份和 7 个平台企业的基础上……增加天津、河北、辽宁、浙江、安徽、福建、山东、湖北、广西、宁夏等 10 个省份……2026 年，推动职业伤害保障试点在全国 31 个省份和新疆生产建设兵团实施；将出行、即时配送和同城货运三个行业的平台企业总体纳入职业伤害保障试点范围」（试点，逐年扩围）', '这还是试点，不是全国都有的正式制度。接单前确认你所在的省份和平台在不在范围里，不在的就只剩自己买商业保险这一层。另一份文件《关于维护新就业形态劳动者劳动保障权益的指导意见》还提了几条要求。平台给正常干活的人开的报酬不低于当地最低工资，要按时足额发，不得克扣或者无故拖欠。法定节假日还要付合理报酬。这份文件的文号是人社部发〔2021〕56 号，灵活就业那条也引了它，见第 11 条。出了事先照这套走，别先跟站点私了。医保和养老那一块还得自己参保，灵活就业参保见第 11 条。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-13', 'concept_archive_s31-13', 'claim_archive_s31-13', 'action', 'life_archive', '高考填志愿那天就能锁定编制的两条路：公费师范生和定向医学生，代价是 6 年履约', '31. 十八岁之后有哪几条路', '这两条路都是国家先替你出钱，你毕业后按协议去指定的地方干 6 年。公费师范生只在六所教育部直属师范大学招，提前批录取。定向医学生在拿到入学通知书前就要签三方协议。违约要退钱、交违约金，还进信用记录。想清楚这 6 年能不能接受，再填志愿。', '2024 年那份办法把公费师范生改成了「本研衔接」（本科接着读教育硕士）。2018 年的老办法已经废止，网上还在传的「本科毕业直接任教」是旧说法。办法发布前已经签了协议的，按原协议走。「有编制」不等于「进去就不用管」：编制要在现有总量里腾，具体岗位由地市组织用人学校专门招聘，你和学校互相挑。定向医学生服务期满想走是可以的，文件写明「服务期满，对自主择业的应予同意」。已经违约的也有把违约记录消掉的办法，代价是按原协议、或者改到省内其他农村基层机构再干满至少 6 年，已交的费用和违约金不退。医学生还要算上 3 年规培的时间，整个周期比师范长。各省还有自己的公费师范生和定向医学生计划，条件由省里定，填志愿前看当年本省的招生文件。', NULL, NULL, NULL, '学费和住宿费都不用你出，还能拿生活费补助。代价是毕业后 6 年不能自由择业，违约要退钱、交违约金、进信用记录。难在这 6 年里换不了地方。', '公费师范生看《教育部直属师范大学本研衔接师范生公费教育实施办法》（2024 年，2018 年办法同时废止）。第二条：由中央财政承担学生在校期间学费、住宿费并给予生活费补助。第三条：重点为中西部地区省会城市之外的地（市、州、盟）及以下培养。它还写着「不得定向到直辖市、计划单列市或省会城市主城区任教（五个自治区、陆地边境省份、海南省、贵州省、青海省除外）」。第九条：毕业后一般回生源所在省份定向地（市、州、盟）中小学任教，「承诺从事中小学教育工作 6 年以上」。到城镇学校工作的，「应到农村义务教育学校任教服务至少 1 年」。第十三条：没履约或者履约期限不够的，按协议承担责任。后果之一是「违约行为纳入信用记录，并及时与全国信用信息共享平台共享，违约相关材料归入本人人事档案」。另一句是「履约任务完成前不得到定向地（市、州、盟）之外从教，不得被招录（聘用）为其他公务人员。完成履约任务后即修复相关信用」。协议约定的服务期没干满之前，别的公职岗位报不了；干满了，信用记录才恢复。第六条：录取后经考察不适合从教的，入学 1 年内退还已享受的公费教育费用，并调整到非师范专业。第十四条：没在规定学习年限内取得教育硕士学历学位证书和教师资格证书的，按违约处理，退费并缴纳违约金。第二十一条：各地在现有事业编制总量内，解决公费师范生到中小学任教所需编制。农村订单定向免费医学生看另一份通知。录取后、获得入学通知书前，须与培养学校和定向就业所在地县级卫生健康、人社部门签署协议。协议里要「承诺毕业后到定向农村基层医疗卫生机构服务 6 年」。履约就是按协议去指定的地方干满。履约报到就业后，须参加 3 年全科专业住院医师规范化培训，简称规培。规培就是毕业后在医院按统一标准接着练本事的阶段。培训期间原人事、工资关系不变。违约记录归入个人人事档案，并作为医疗卫生机构等行政事业单位公开招录（招聘）、住院医师规范化培训招收、研究生招生录取的诚信评价依据。恶意违约的人，通过「信用中国」网站全国公示，并实行失信联合惩戒。违约的培训年限不计入服务期。没按协议退还费用和违约金的，由县级卫生健康行政部门通过法律途径追缴（全国）', '2024 年那份办法把公费师范生改成了「本研衔接」（本科接着读教育硕士）。2018 年的老办法已经废止，网上还在传的「本科毕业直接任教」是旧说法。办法发布前已经签了协议的，按原协议走。「有编制」不等于「进去就不用管」：编制要在现有总量里腾，具体岗位由地市组织用人学校专门招聘，你和学校互相挑。定向医学生服务期满想走是可以的，文件写明「服务期满，对自主择业的应予同意」。已经违约的也有把违约记录消掉的办法，代价是按原协议、或者改到省内其他农村基层机构再干满至少 6 年，已交的费用和违约金不退。医学生还要算上 3 年规培的时间，整个周期比师范长。各省还有自己的公费师范生和定向医学生计划，条件由省里定，填志愿前看当年本省的招生文件。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-14', 'concept_archive_s31-14', 'claim_archive_s31-14', 'action', 'life_archive', '想出国打工，先查这家公司有没有对外劳务合作经营资格：它不得向你收押金', '31. 十八岁之后有哪几条路', '出国打工这件事，法律管的不是你，是组织你出去的那家公司。只有拿到对外劳务合作经营资格证书、又办了登记的企业才能干这个。听到「先办旅游签过去再转工签」，这句话本身就说明对方在违法。公司也不得以任何名目向你收押金，或者要你拿财产做担保。', '合规的流程是这样：公司先和国外雇主签书面劳务合作合同，再和你签书面服务合同或者劳动合同。合同要写明工作内容、期限、报酬、工时、休假、社保和人身安全风险。签完 10 个工作日内，公司要报商务主管部门备案。公司还必须安排你接受技能、安全防范、外语和当地法律风俗的培训，并给你买境外工作期间的人身意外伤害保险。对方不让看合同、要押金、催你先走后补手续，就是要避开的那种公司。境外高薪招聘骗局和电诈园区见第 21 节第 5 条，出发前要查的安全提醒和 12308 在第 21 节，不重复。条例没给出去干活的人设学历或年龄门槛，门槛在公司的资质上，也在干活所在国给不给许可上。公司只能跟那个国家批准过的企业或机构签合同，不能跟国外的个人签。备用金由主管部门在公司赖账时动用，你不能自己去取。所以真出事还得先向商务主管部门投诉，第二十条给了你这个投诉权。往同一个国家或地区派超过 100 人的，要安排随行的管理人员并报使领馆备案。人少的项目没有这层保障，更要自己留好合同和转账记录。', NULL, NULL, NULL, '不花钱。出发前花十几分钟核一下公司资质，再把两份合同看完。', '《对外劳务合作管理条例》第五条：从事对外劳务合作应当经省级或者设区的市级商务主管部门批准取得经营资格。这个经营资格就是那张对外劳务合作经营资格证书，没有它就不能组织人出国干活。第七条：经营资格证书名单报国务院商务主管部门，并通报中国驻外使馆、领馆。这一条还写着「未依法取得对外劳务合作经营资格证书并办理登记，不得从事对外劳务合作」。第八条：「任何单位和个人不得以商务、旅游、留学等名义组织劳务人员赴国外工作」。第九条：企业应当自登记之日起 5 个工作日内在指定银行缴存「不低于 300 万元人民币的对外劳务合作风险处置备用金」，缴存名单向社会公布。第十条：备用金用于支付企业拒绝承担或者无力承担的应退服务费、劳动报酬和依法赔偿的损失。它还用于「因发生突发事件，劳务人员回国或者接受紧急救助所需费用」。第十一条：不得组织劳务人员赴国外从事与赌博、色情活动相关的工作。第十二条：没安排培训的不得组织出国。第十三条：应当为劳务人员购买在国外工作期间的人身意外伤害保险。第二十一、二十三条：须与国外雇主、与劳务人员分别订立书面合同，没订立的不得组织出国。第二十五条：「不得以任何名目向劳务人员收取押金或者要求劳务人员提供财产担保」。第二十六条：合同订立之日起 10 个工作日内报商务主管部门备案。第二十九条：劳务人员实际权益与合同不符的，企业应当协助索赔；没得到应有赔偿的，有权要求企业承担赔偿责任。第三十一条：有关国家或者地区安全状况难以保障人身安全的，企业不得组织劳务人员前往。第三十七条：商务主管部门建立不良信用记录和公告制度。罚则在后面几条。第三十九条：没资格从事对外劳务合作的，查处取缔，构成犯罪的追究刑事责任。第四十条：以商务、旅游、留学名义组织出国、出借资格、组织从事赌博色情相关工作的，吊销经营资格证书。第四十三条：没签合同、或者隐瞒信息、提供虚假信息组织出国的，罚 10 万元以上 20 万元以下。还要对主要负责人罚 2 万元以上 5 万元以下（全国）', '合规的流程是这样：公司先和国外雇主签书面劳务合作合同，再和你签书面服务合同或者劳动合同。合同要写明工作内容、期限、报酬、工时、休假、社保和人身安全风险。签完 10 个工作日内，公司要报商务主管部门备案。公司还必须安排你接受技能、安全防范、外语和当地法律风俗的培训，并给你买境外工作期间的人身意外伤害保险。对方不让看合同、要押金、催你先走后补手续，就是要避开的那种公司。境外高薪招聘骗局和电诈园区见第 21 节第 5 条，出发前要查的安全提醒和 12308 在第 21 节，不重复。条例没给出去干活的人设学历或年龄门槛，门槛在公司的资质上，也在干活所在国给不给许可上。公司只能跟那个国家批准过的企业或机构签合同，不能跟国外的个人签。备用金由主管部门在公司赖账时动用，你不能自己去取。所以真出事还得先向商务主管部门投诉，第二十条给了你这个投诉权。往同一个国家或地区派超过 100 人的，要安排随行的管理人员并报使领馆备案。人少的项目没有这层保障，更要自己留好合同和转账记录。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-15', 'concept_archive_s31-15', 'claim_archive_s31-15', 'action', 'life_archive', '在家给境外公司远程干活，这笔钱在税法上算境内所得：个税自己报，收汇走「职工报酬」', '31. 十八岁之后有哪几条路', '这笔钱算境内还是境外，看的是你在哪儿干活，不是钱从哪儿打进来。人在国内远程给境外公司干活，算境内所得，要在境内交个税。境外公司在中国没有机构，没人替你代扣，这笔税得你自己去报。钱汇进来走「职工报酬」这条路。', '按哪个税目算，看你和对方是什么关系。签的是雇佣合同、活儿听对方安排的，算工资薪金。自己按项目接活、交付成果的，算劳务报酬。两种算出来的税不一样，报之前先弄清自己是哪一种。钱汇进来时，一年等值 5 万美元以内的，凭身份证在银行结汇就行；超过的部分，要把雇佣合同和收入证明交给银行。别为了绕过额度找人分拆收款。以上说的是人在国内、不出境的情形。真的出境到境外给境外雇主干活是另一套，见本节第 14 条（想出国打工，先查这家公司有没有对外劳务合作经营资格）。以下四项本书暂未写。它们都可能有实际成本，但目前找不到可逐字核对的依据。一是这笔收入要不要缴增值税、要不要代开发票。二是长期这样做要不要办营业执照或者登记为个体户。三是能不能按劳动法向境外雇主主张权利，比如年假、加班费、解除补偿。四是数据出境与保密', NULL, NULL, NULL, '不花钱。每年办一次汇算清缴，时间是次年 3 月 1 日到 6 月 30 日。收汇超过年度总额的时候，还要准备一份雇佣合同和收入证明。难在这笔税得你自己记着去报。', '这笔钱算不算境内所得，看《个人所得税法实施条例》（国务院令第 707 号，2019 年 1 月 1 日起施行）第三条。它写着：「除国务院财政、税务主管部门另有规定外，下列所得，不论支付地点是否在中国境内，均为来源于中国境内的所得：（一）因任职、受雇、履约等在中国境内提供劳务取得的所得」。同一部条例第六条给两个税目下了定义。一个是工资薪金：「工资、薪金所得，是指个人因任职或者受雇取得的工资、薪金、奖金、年终加薪、劳动分红、津贴、补贴以及与任职或者受雇有关的其他所得」。另一个是劳务报酬：「劳务报酬所得，是指个人从事劳务取得的所得，包括从事设计、装潢、安装、制图、化验、测试、医疗、法律、会计、咨询、讲学、翻译、审稿、书画、雕刻、影视、录音、录像、演出、表演、广告、展览、技术服务、介绍服务、经纪服务、代办服务以及其他劳务取得的所得」。《个人所得税法》第六条写怎么算应纳税所得额：「居民个人的综合所得，以每一纳税年度的收入额减除费用六万元以及专项扣除、专项附加扣除和依法确定的其他扣除后的余额，为应纳税所得额」。同一条还写着「劳务报酬所得、稿酬所得、特许权使用费所得以收入减除百分之二十的费用后的余额为收入额」。减 20% 这一句只列了这三项，工资薪金不在其内。所以工资薪金按全额计入收入额，两个税目算出来的税不同。第九条：「个人所得税以所得人为纳税人，以支付所得的单位或者个人为扣缴义务人」。第十条：「有下列情形之一的，纳税人应当依法办理纳税申报：……（二）取得应税所得没有扣缴义务人；……（四）取得境外所得」。第十一条：「居民个人取得综合所得，按年计算个人所得税……需要办理汇算清缴的，应当在取得所得的次年三月一日至六月三十日内办理汇算清缴」。钱汇进来看《个人外汇管理办法》（中国人民银行令〔2006〕第 3 号，2007 年 2 月 1 日起施行）。第九条：「对个人结汇和境内个人购汇实行年度总额管理。年度总额内的，凭本人有效身份证件在银行办理；超过年度总额的，经常项目项下凭本人有效身份证件和有交易额的相关证明等材料在银行办理」。第七条：「银行和个人在办理个人外汇业务时，应当遵守本办法的相关规定，不得以分拆等方式逃避限额监管，也不得使用虚假商业单据或者凭证逃避真实性管理」。《个人外汇管理办法实施细则》（汇发〔2007〕1 号）第二条：「对个人结汇和境内个人购汇实行年度总额管理。年度总额分别为每人每年等值 5 万美元」。第十条：「境内个人经常项目项下非经营性结汇超过年度总额的，凭本人有效身份证件及以下证明材料在银行办理：……（七）职工报酬：雇佣合同及收入证明」（全国）', '按哪个税目算，看你和对方是什么关系。签的是雇佣合同、活儿听对方安排的，算工资薪金。自己按项目接活、交付成果的，算劳务报酬。两种算出来的税不一样，报之前先弄清自己是哪一种。钱汇进来时，一年等值 5 万美元以内的，凭身份证在银行结汇就行；超过的部分，要把雇佣合同和收入证明交给银行。别为了绕过额度找人分拆收款。以上说的是人在国内、不出境的情形。真的出境到境外给境外雇主干活是另一套，见本节第 14 条（想出国打工，先查这家公司有没有对外劳务合作经营资格）。以下四项本书暂未写。它们都可能有实际成本，但目前找不到可逐字核对的依据。一是这笔收入要不要缴增值税、要不要代开发票。二是长期这样做要不要办营业执照或者登记为个体户。三是能不能按劳动法向境外雇主主张权利，比如年假、加班费、解除补偿。四是数据出境与保密', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s31-16', 'concept_archive_s31-16', 'claim_archive_s31-16', 'action', 'life_archive', '不进单位自己干，起步钱先看创业担保贷款：个人最高 30 万、财政贴一半利息', '31. 十八岁之后有哪几条路', '如果一定要借钱起步，先看这笔有财政贴息的。个人最高能借 30 万元，最长 3 年，利息由财政替你出一半。有个硬条件常被忽略：申请时你和配偶名下不能有别的贷款，只有助学贷款、脱贫人口小额信贷、房贷、车贷和 5 万元以下的小额消费贷不算在内。', '财政替你出一半利息，不改变「借的钱要还」这件事。本书在第 12 节第 1 条的立场没变：创业只拿亏得起的钱，不动家底，不给公司贷款签个人担保，配偶更不要跟着签。如果你已经决定要借，这种政策贷款是利息最低的那一档，别去碰消费贷和民间借贷。额度和适用范围各省可以往上调，实际能批多少，以当地人社部门当年的说法为准。2020 年疫情期间那份「个人最高 20 万」的通知是临时文件，现在看这份办法。开店是办个体户还是开公司、许可证、报税和退场，见第 12 节。失业期间的培训补贴、社保补贴和就业见习，见第 7 节第 13 条（职业培训补贴）。', NULL, NULL, NULL, '咨询不花钱。先跑一次人社部门做资格审核，再到担保机构和经办银行（放贷款的银行）各办一次手续。难在借来的钱终究要还。', '个人申请条件写在《普惠金融发展专项资金管理办法》（财金〔2023〕75 号）第六条。第一个条件是要属于重点就业群体。文件列的是城镇登记失业人员、就业困难人员（含残疾人）、退役军人、刑满释放人员。还有高校毕业生（含大学生村官和留学回国学生）、化解过剩产能企业职工和失业人员。还有返乡创业农民工、网络商户、脱贫人口、农村自主创业农民等。第二个条件是名下不能有别的贷款：「除助学贷款、脱贫人口小额信贷、住房贷款、购车贷款、5 万元以下小额消费贷款（含信用卡消费）以外，申请人提交创业担保贷款申请时，本人及其配偶无其他贷款」。第九条：「对符合条件的创业担保贷款，财政部门给予贷款实际利率 50% 的财政贴息。对展期、逾期的创业担保贷款，财政部门原则上不予贴息」。贴息就是利息由财政替你出一半。展期是到期后再往后延，逾期是过期没还，这两种情况财政不再替你出。第十条：个人申请的 10 万元以下创业担保贷款原则上取消反担保，不必再另外找人、或者拿财产给担保机构做担保。第十一条：纳入奖补支持范围的个人创业担保贷款「额度不超过 30 万元，贷款期限不超过 3 年」。合伙创业可适当提高，最高不超过个人额度上限之和的 110%。奖补支持的贷款利率上限分三档：东部地区为 LPR+50BPs，中西部地区 LPR+150BPs，脱贫地区 LPR+250BPs。LPR 是银行贷款市场报价利率，BPs 是利率的计量单位，加得越多利息越高。「还款积极、带动就业能力强、创业项目好」的，到期后可继续申请，累计次数不超过 3 次。第八条：申请人先向当地人力资源社会保障部门申请资格审核，再向担保机构和经办银行提交申请。第十二条：经省级人民政府同意，各地可扩大支持范围、提高额度和贴息比例（全国）', '财政替你出一半利息，不改变「借的钱要还」这件事。本书在第 12 节第 1 条的立场没变：创业只拿亏得起的钱，不动家底，不给公司贷款签个人担保，配偶更不要跟着签。如果你已经决定要借，这种政策贷款是利息最低的那一档，别去碰消费贷和民间借贷。额度和适用范围各省可以往上调，实际能批多少，以当地人社部门当年的说法为准。2020 年疫情期间那份「个人最高 20 万」的通知是临时文件，现在看这份办法。开店是办个体户还是开公司、许可证、报税和退场，见第 12 节。失业期间的培训补贴、社保补贴和就业见习，见第 7 节第 13 条（职业培训补贴）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"31. 十八岁之后有哪几条路","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-1', 'concept_archive_s32-1', 'claim_archive_s32-1', 'action', 'life_archive', '交学费之前先查学校在不在留服中心的认证院校名单里', '32. 出国留学：身份、打工、保险和回国认证', '回国以后，这张文凭要用来考公、进国企、落户、评职称，就得先过一道认证。认证由教育部留学服务中心做。学校不在能认证的名单里，学费和时间就白花了，文凭在国内用不上。查名单不花钱，查完再交学费。', '中介嘴上说「教育部认可」不算数，以你自己上网查到的结果为准。名单会变，入学时在名单里，毕业时不一定还在，所以读书期间每年复查一次。中外合作办学的项目另有一套认证注册的制度。2008 年以后入学的，可以凭姓名和身份证号，在涉外监管信息网查自己的注册序号。', NULL, NULL, NULL, '不花钱。在留服中心的「认证院校查询」里输一次学校名，几分钟就查完', '中国（教育部）留学服务中心有一个认证院校查询入口。你可以按国家查，也可以按学校名字查。查的是这所学校发的学历学位在不在认证范围里。另外，教育部教育涉外监管信息网还公布中外合作办学和境外办学的监管信息', '中介嘴上说「教育部认可」不算数，以你自己上网查到的结果为准。名单会变，入学时在名单里，毕业时不一定还在，所以读书期间每年复查一次。中外合作办学的项目另有一套认证注册的制度。2008 年以后入学的，可以凭姓名和身份证号，在涉外监管信息网查自己的注册序号。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 极高","口径 金钱","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-2', 'concept_archive_s32-2', 'claim_archive_s32-2', 'action', 'life_archive', '盯住美国 F-1 新规的官司：「最长四年、读完 30 天内走」原定 2026 年 9 月 15 日生效，前一天被法院暂停，眼下仍是「读完为止」', '32. 出国留学：身份、打工、保险和回国认证', '美国原本要把 F-1 改成最长四年、读完 30 天内走。生效前一天，联邦法院把它暂停了。所以眼下还是老规矩：读多久算多久，读完有 60 天准备走人。暂停不是废除，政府还能上诉，规矩随时可能再变。', '本条截至 2026 年 9 月 25 日。政府可以向第一巡回上诉法院上诉，国土安全部也可以改好规则重新发布。所以要读好几年的人，别假定老规矩会一直不变。法院定了 2026 年 10 月 2 日再开庭听双方汇报进展，过了那天再看一次学校的通知。新规如果以后生效，要延期就得在期限到期之前另外申请，不会自动续上。老规矩下，提前不读了的，离境期限和读完的不一样，先问学校国际学生办公室。J 签证在同一份规则里，细节和 F-1 不一样，按自己的签证类别去查。', NULL, NULL, NULL, '不花钱。把 I-20 上的项目结束日期抄进日历，提前 90 天提醒一次。I-20 是学校发给你的留学资格证明。另外每学期看一次学校国际学生办公室的通知，看这场官司有没有新进展', '国土安全部 2026 年 7 月 17 日公布了一项规则，原定 2026 年 9 月 15 日生效。内容是 F-1 学生不再按「读完为止」入境，改成固定期限，最长四年，到期要另外申请延期。读完或者实习结束后，只留 30 天准备离境。2026 年 9 月 14 日，马萨诸塞州联邦地区法院的 Saylor 法官依《行政程序法》第 705 条，推迟了这项规则的生效。暂停管全国，管整份规则。法院没有撤销这项规则，撤销的请求被驳回，但允许以后再提。案子还在继续审。按法院这道命令，F、J、I 三类签证的人仍按「读完为止」入境，60 天离境宽限期照旧，也不需要另外申请延期', '本条截至 2026 年 9 月 25 日。政府可以向第一巡回上诉法院上诉，国土安全部也可以改好规则重新发布。所以要读好几年的人，别假定老规矩会一直不变。法院定了 2026 年 10 月 2 日再开庭听双方汇报进展，过了那天再看一次学校的通知。新规如果以后生效，要延期就得在期限到期之前另外申请，不会自动续上。老规矩下，提前不读了的，离境期限和读完的不一样，先问学校国际学生办公室。J 签证在同一份规则里，细节和 F-1 不一样，按自己的签证类别去查。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-3', 'concept_archive_s32-3', 'claim_archive_s32-3', 'action', 'life_archive', '打工时数是美加英澳四国都写死的红线，超一小时就是违反签证条件', '32. 出国留学：身份、打工、保险和回国认证', '四个国家都给学生签证的打工时间定了上限。超了就是违反签证条件，可能被取消签证、被遣返，以后再申请也会被追问。上限是：美国每周 20 小时，英国读学位每周 20 小时、学位以下 10 小时，加拿大每周 24 小时，澳大利亚每两周 48 小时。打两份工要合起来算。', '美国的校外打工必须先获批。申请打工许可的 I-765 还在审的时候，就不能开工。加拿大的旧许可上印的是每周 20 小时，只要还符合条件，实际可以做到 24 小时，以现行规定为准。英国不许自雇那条管得很宽：接私活、开网店、做自由职业都算。', NULL, NULL, NULL, '不花钱。自己按周把工时记下来。难在雇主会说「多干几个小时没人查」，这话不能信', '美国的 F-1 学生，校内打工在学期中每周不得超过 20 小时。经批准的校外兼职同样是每周 20 小时。假期可以全职。依据是美国联邦移民法规 8 CFR 214.2(f)(9)。英国的学生签证，读学位及以上课程的，学期内每周 20 小时，学位以下的每周 10 小时。非全日制课程一律不得打工。还不得自雇（自己给自己干活），也不得做职业运动员或者演艺工作。依据是英国移民规则里管学生的那一部分，附录 Student ST26.1、ST26.5。加拿大符合条件的全日制学生，校外打工每周最多 24 小时，依据是加拿大移民法实施条例 IRPR 第 186(v) 条。澳大利亚的学生签证，课程进行期间每两周最多 48 小时。研究型硕士、博士和他们的家属不受这个限制', '美国的校外打工必须先获批。申请打工许可的 I-765 还在审的时候，就不能开工。加拿大的旧许可上印的是每周 20 小时，只要还符合条件，实际可以做到 24 小时，以现行规定为准。英国不许自雇那条管得很宽：接私活、开网店、做自由职业都算。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-4', 'concept_archive_s32-4', 'claim_archive_s32-4', 'action', 'life_archive', '身份的根是「全日制在读」：休学、退学、转学空档期一律不能打工', '32. 出国留学：身份、打工、保险和回国认证', '能不能打工，看你是不是正在全日制上学。一旦休学、退学、被开除，或者转学期间没在上课，打工资格当场就没了。这时候接着干，就是非法打工。很多人以为签证没到期就没事，其实身份早断了。', '课业压力大，想减课之前先问清楚：减到多少就不算全日制了。这一条比打工更早出事。被学校开除、或者项目被终止的，身份通常当天就断。别等学校发正式信再行动。', NULL, NULL, NULL, '不花钱。停课、休学、换学校之前，先找学校的国际学生办公室，问清楚自己的身份状态', '加拿大明文规定，在获批的休学期间不得校外打工。转学期间没有在学习的，也不得校外打工。要等恢复学业以后，才能重新开始工作。美国的校内打工资格只给 SEVIS 里身份为 Active 的 F-1 学生。SEVIS 是美国的留学生身份档案系统，Active 是在读有效。这些学生还要维持全日制课业。英国的打工许可按课程类型给，非全日制课程不得打工', '课业压力大，想减课之前先问清楚：减到多少就不算全日制了。这一条比打工更早出事。被学校开除、或者项目被终止的，身份通常当天就断。别等学校发正式信再行动。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-5', 'concept_archive_s32-5', 'claim_archive_s32-5', 'action', 'life_archive', '美国：搬家后 10 天内必须报新地址', '32. 出国留学：身份、打工、保险和回国认证', '在美国换了住的地方，法律要求 10 天之内通知移民局。不报不是小事。一来它本身违法，二来移民局寄给你的信会寄丢。', '报了移民局，学校那边的 SEVIS 记录（你的留学生身份档案）还要另外更新。其余三个国家也都要求换了地址就通知移民局或者学校。期限和办法各国不同，按你所在国移民局的网页办。', NULL, NULL, NULL, '不花钱。在线提交一次改址，十分钟', '美国联邦移民法规 8 CFR 265.1 规定，按法律要登记的外国人，地址变了以后 10 日内要报告。报给 USCIS（美国移民局），按它要求的办法报，既报地址变了这件事，也报新地址', '报了移民局，学校那边的 SEVIS 记录（你的留学生身份档案）还要另外更新。其余三个国家也都要求换了地址就通知移民局或者学校。期限和办法各国不同，按你所在国移民局的网页办。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-6', 'concept_archive_s32-6', 'claim_archive_s32-6', 'action', 'life_archive', '出发前和在读期间，看一眼教育部的留学预警', '32. 出国留学：身份、打工、保险和回国认证', '教育部会对某个国家或者地区专门发预警，说那里近期的治安或者政策对中国留学生不利。这是官方公开发布的风险提示，白纸黑字能查到，比中介的说法可靠。看一眼不花钱。', '预警不是禁令，也不是说不能去，它给你一个掂量当地风险的官方依据。预警名单随形势变，本节不长期跟着更新，以网站上当期的页面为准。境外人身安全和领事保护见第 21 节。', NULL, NULL, NULL, '不花钱。出发前看一次，以后每学期看一次', '教育部通过教育涉外监管信息网发布留学预警。2025 年一共发了 4 号。第 1 号提示美国有关州通过的高等教育法案里含有涉华消极条款（2025-04-09）。第 2 号和第 3 号两次提示菲律宾针对中国公民的案件多发、留学环境不佳（2025-07-18、2025-08-30）。第 4 号提示日本治安形势和留学环境不佳，建议谨慎规划赴日留学（2025-11-16）', '预警不是禁令，也不是说不能去，它给你一个掂量当地风险的官方依据。预警名单随形势变，本节不长期跟着更新，以网站上当期的页面为准。境外人身安全和领事保护见第 21 节。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 自由","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-7', 'concept_archive_s32-7', 'claim_archive_s32-7', 'action', 'life_archive', '澳大利亚：OSHC 必须覆盖全程且中间不能断，落地拿不出保险可能被拒绝入境', '32. 出国留学：身份、打工、保险和回国认证', '澳大利亚把留学生医疗保险写进了签证条件，不是可买可不买。保险要盖住整个停留期。续签换保单的时候，中间不能有空档。入境时拿不出保险证明，可能当场被拒绝入境。家里人来陪读，每个人都要单独买一份。', '学校代办的，要问清楚保险公司名称、保单起止日期和保单号，签证申请里要填这些。买短了会让续签出问题，宁可买到毕业以后再多留一点。', NULL, NULL, NULL, '数千到上万元人民币。按签证时长一次性买，读几年买几年', '澳大利亚内政部规定，学生签证申请人和他的家属要买海外学生医疗保险（OSHC），而且在澳大利亚停留的全程都要有，不能断。保险要由澳大利亚认可的保险机构提供。符合可以免买的豁免情形的除外。新保险和前一个签证的保险之间不得有空档。入境时拿不出已经投保的证明，可能被拒绝入境。比课程开始时间更早入境的，保险起始日要写实际抵达澳大利亚的那一天', '学校代办的，要问清楚保险公司名称、保单起止日期和保单号，签证申请里要填这些。买短了会让续签出问题，宁可买到毕业以后再多留一点。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-8', 'concept_archive_s32-8', 'claim_archive_s32-8', 'action', 'life_archive', '英国：签证费之外还有一笔按年收的医疗附加费，学生每年 776 英镑，申请时一次付清', '32. 出国留学：身份、打工、保险和回国认证', '去英国要交的钱不止签证费。还要按签证年数预交医疗附加费，交了才能用英国的国民医疗服务。两年的签证就是一次交 1552 英镑。再加上签证费，出发前这一笔要一次交清，做预算别漏了。', '金额和汇率都会变，按来源里那两个页面上的当期数字算。读学位课程、年满 18 岁的，一般最长能待 5 年，学位以下的是 2 年。按这个年数估算要交多少附加费。', NULL, NULL, NULL, '签证费 558 英镑。医疗附加费每年 776 英镑。两笔都在申请时一次交清', '英国学生签证的费用是 558 英镑。在英国境外申请、在境内延期或者转换，都是这个数。另外还有医疗附加费，交了才能用英国的国民医疗服务，按签证年数在申请时一次预交。学生本人和他的家属是每年 776 英镑，比如 2 年的签证就是 1552 英镑。其他类别的申请人是每年 1035 英镑。签证超过 6 个月、不足 1 年的，按整年收取', '金额和汇率都会变，按来源里那两个页面上的当期数字算。读学位课程、年满 18 岁的，一般最长能待 5 年，学位以下的是 2 年。按这个年数估算要交多少附加费。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 一般","口径 金钱","钱 多","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-9', 'concept_archive_s32-9', 'claim_archive_s32-9', 'action', 'life_archive', '回国前留出认证时间：留服认证要 10 到 20 个工作日', '32. 出国留学：身份、打工、保险和回国认证', '国外的学历回国要用，得先做学历学位认证。光是审核就要 10 到 20 个工作日。赶上求职季，或者材料被退回来，还要更久。秋招、考公报名、落户都有截止日期，别等到要用了才开始办。', '要交的材料有这几样：文凭证书，护照或者通行证，居留卡或者签证签注，证件照片，授权声明。出国期间的出入境记录由系统自己调取，所以在外期间的签证页别丢。留服中心网站上还会发公告，说哪些认证书作废、暂停受理哪所学校的认证申请。办之前先看一眼有没有涉及自己的学校。', NULL, NULL, NULL, '线上申请，线上缴费。准备材料加上审核，按工作日算，前后一个月上下', '国（境）外学历学位认证在中国（教育部）留学服务中心的网上服务大厅办。流程是四步：注册并实名认证，在线提交申请和材料，在线缴费，等评估和审核。公布的认证工作时限是 10 至 20 个工作日。工作日不含周末和节假日，这段是留服中心审核用的时间', '要交的材料有这几样：文凭证书，护照或者通行证，居留卡或者签证签注，证件照片，授权声明。出国期间的出入境记录由系统自己调取，所以在外期间的签证页别丢。留服中心网站上还会发公告，说哪些认证书作废、暂停受理哪所学校的认证申请。办之前先看一眼有没有涉及自己的学校。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 一般","口径 时间","钱 少","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s32-10', 'concept_archive_s32-10', 'claim_archive_s32-10', 'action', 'life_archive', '认证被「加强审查」的学校每年都在加，花钱买文凭这条路已经走不通', '32. 出国留学：身份、打工、保险和回国认证', '留服中心会点名一批国外院校，对它们的学历认证单独加强审查，也会暂停受理个别学校的认证申请。被点名的往往就是宣传里「免语言、免出境、几个月拿硕士」的那种。报名前搜一次学校名，比事后申诉省事得多。', '「加强审查」不等于一定认证不了，但会要求你补交更多材料，时间也更长。凡是承诺「包认证」「内部渠道加急」的中介都是骗局，留服中心专门发过防诈骗提示。跨境找人代写论文、代上网课，被查到除了学历作废，还可能影响签证记录。', NULL, NULL, NULL, '不花钱。报名之前，在留服中心的通知公告里搜一次学校名', '中国（教育部）留学服务中心一直在发公告，对部分国外院校的学历学位认证加强认证审查（对这些学校的文凭单独多查一道）。最新一份是第九号（2025-10-28）。留服中心还发过暂停受理个别境外院校认证申请的公告，也发过提示，说有人借国（境）外学历学位认证实施诈骗', '「加强审查」不等于一定认证不了，但会要求你补交更多材料，时间也更长。凡是承诺「包认证」「内部渠道加急」的中介都是骗局，留服中心专门发过防诈骗提示。跨境找人代写论文、代上网课，被查到除了学历作废，还可能影响签证记录。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"32. 出国留学：身份、打工、保险和回国认证","A 级","性价比 高","口径 金钱","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-1', 'concept_archive_s33-1', 'claim_archive_s33-1', 'action', 'life_archive', '脊髓损伤之后突然剧烈头痛、出汗，先扶坐直、松开衣物，同时叫 120', '33. 残疾之后怎么活', '脊髓损伤的人，身体的报警线路断了一截。膀胱憋着、衣服勒着，本人可能没感觉，血压却会猛往上冲。信号是突然剧烈头痛和出汗。这时先把人扶坐直、松开勒紧的衣物、看是不是憋着尿，同时叫 120。', '定 B 是因为那三个现场动作背后没有随机对照试验，只有共识和生理学推理。综述自己也说，这些办法多数只有非对照研究支撑。用药那一段是医生的事，家里不要自己给降压药。让人躺平会让血压更高，所以要扶坐直。家属和护工也要会这三步。别把它当普通头痛扛过去。', NULL, NULL, NULL, '不花钱。三个动作，几十秒做完。', '这种发作叫自主神经反射异常。一篇系统综述检索了 Medline、CINAHL、EMBASE 和 PsycINFO 四个数据库，纳入 31 项研究，其中 6 项是随机对照试验。综述写明，发作当时的非药物处理是三步：把患者摆成直立体位、松开紧身衣物、去除诱发刺激。这三步的依据是临床共识和生理学数据，属于第 5 级证据。血压持续升高时才用降压药，其中哌唑嗪有第 1 级证据，硝苯地平和前列腺素 E2 有第 2 级证据。综述还写明，预防发作的策略主要针对泌尿生殖系统和手术这两类常见诱因，多数只有第 4 级和第 5 级证据支撑', '定 B 是因为那三个现场动作背后没有随机对照试验，只有共识和生理学推理。综述自己也说，这些办法多数只有非对照研究支撑。用药那一段是医生的事，家里不要自己给降压药。让人躺平会让血压更高，所以要扶坐直。家属和护工也要会这三步。别把它当普通头痛扛过去。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-2', 'concept_archive_s33-2', 'claim_archive_s33-2', 'action', 'life_archive', '致残之后的头十年是自杀的高风险期，别当成「想开点」就行的事', '33. 残疾之后怎么活', '刚残疾那几年，自己或者家人情绪垮掉，是常见的，不是意志力的问题。英国两家脊髓损伤中心的长期随访发现，这群人的自杀率是普通人的五倍。九成以上的自杀发生在受伤后的头十年。受伤原因本身就是自杀的人，风险还要高出一截。', '这项研究只看了脊髓损伤，套到失明、截肢、烧伤这些别的致残原因上属于往外推。它能说明的是时间窗：风险不是出院就过去了，要盯十年。要人陪着说话打 12356，见第 29 节第 11 条（12356）。家里别囤安眠药和农药，见第 1 节第 25 条（自杀念头）。哀伤和情绪卡住半年还在原地，去精神科或临床心理科挂号，见第 29 节第 8 条（哀伤过了半年）。', NULL, NULL, NULL, '不花钱。打一个电话，或者挂一次号。', '研究跟踪了 1991 到 2010 年新入院、熬过伤后第一年、出院时有神经功能缺损的 2304 例外伤性脊髓损伤患者，随访到 2014 年底。其中 63 例（2.7%）的受伤原因本身就是自杀未遂。到随访结束共 533 人死亡，其中 4.2% 死于自杀，91% 的自杀发生在受伤后的头十年。按年龄标化的自杀死亡率是每年每 10 万人 62.5 例（95% CI 36.4–88.6，可信范围），是 2014 年英格兰和威尔士普通人群自杀率（每 10 万人 12.2 例）的五倍。因自杀未遂致伤的那部分人，和其他致伤原因相比，死亡的比值比是 4.32（P&lt;0.001），自杀的比值比是 9.46（P&lt;0.001）', '这项研究只看了脊髓损伤，套到失明、截肢、烧伤这些别的致残原因上属于往外推。它能说明的是时间窗：风险不是出院就过去了，要盯十年。要人陪着说话打 12356，见第 29 节第 11 条（12356）。家里别囤安眠药和农药，见第 1 节第 25 条（自杀念头）。哀伤和情绪卡住半年还在原地，去精神科或临床心理科挂号，见第 29 节第 8 条（哀伤过了半年）。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-3', 'concept_archive_s33-3', 'claim_archive_s33-3', 'action', 'life_archive', '精神障碍住院以自愿为原则，只有两种情形可以不经本人同意', '33. 残疾之后怎么活', '家属或单位一句话，不能把一个人留在精神病院住院。法律只认两种情况：已经伤害自己或有这个危险，已经危害别人或有这个危险。第一种要监护人同意才能收。对诊断有异议的，三天内可以要求再次诊断，之后还能自己委托鉴定。', '反过来，也不是谁都不能送医。第二十八条规定，疑似精神障碍患者已经发生伤害自身、危害他人安全的行为，或者有这个危险的，其近亲属、所在单位、当地公安机关应当立即采取措施予以制止，并将其送往医疗机构进行精神障碍诊断。医疗机构接到送诊的，不得拒绝作出诊断。所以「送去做诊断」和「留下来住院」是两道门，前一道低，后一道高。第七十五条列了医疗机构的责任，违反规定实施约束隔离、把非精神障碍患者诊断成精神障碍患者，要被处分直至吊销执业证书。身边人有伤人冲动时怎么办，见第 8 节。', NULL, NULL, NULL, '不花钱。把两条情形记住，需要时能说出口。', '《精神卫生法》第三十条写明「精神障碍的住院治疗实行自愿原则」。只有诊断结论和病情评估表明就诊者是严重精神障碍患者、并且有下列情形之一的，才应当实施住院治疗。一是「已经发生伤害自身的行为，或者有伤害自身的危险的」。二是「已经发生危害他人安全的行为，或者有危害他人安全的危险的」。第三十一条：属于第一种情形的，经监护人同意医疗机构才实施住院治疗，监护人不同意的不得实施。第三十二条：属于第二种情形而本人或者监护人有异议的，可以要求再次诊断，应当自收到诊断结论之日起三日内提出，由二名初次诊断医师以外的精神科执业医师作出；对再次诊断结论仍有异议的，可以自主委托依法取得执业资质的鉴定机构做精神障碍医学鉴定。第三十五条：再次诊断结论或者鉴定报告表明不能确定为严重精神障碍患者、或者患者不需要住院治疗的，医疗机构不得对其实施住院治疗。第七十八条：将非精神障碍患者故意作为精神障碍患者送入医疗机构治疗的，依法承担赔偿责任（全国，2013 年 5 月 1 日起施行，2018 年修正）', '反过来，也不是谁都不能送医。第二十八条规定，疑似精神障碍患者已经发生伤害自身、危害他人安全的行为，或者有这个危险的，其近亲属、所在单位、当地公安机关应当立即采取措施予以制止，并将其送往医疗机构进行精神障碍诊断。医疗机构接到送诊的，不得拒绝作出诊断。所以「送去做诊断」和「留下来住院」是两道门，前一道低，后一道高。第七十五条列了医疗机构的责任，违反规定实施约束隔离、把非精神障碍患者诊断成精神障碍患者，要被处分直至吊销执业证书。身边人有伤人冲动时怎么办，见第 8 节。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 极高","口径 自由","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-4', 'concept_archive_s33-4', 'claim_archive_s33-4', 'action', 'life_archive', '长期照护家里残疾人的那个人，自己的身体要有人盯着', '33. 残疾之后怎么活', '照护者累垮不是矫情。一项美国研究跟踪了八百多位老人四年。一边照护失能的配偶、一边报告自己精神吃力的那批人，死亡风险比不照护的人高约六成。照护但不觉得吃力的人，没有出现这种升高。所以要盯的不是照护本身，是那份长期紧绷。', '争议：这项研究的可信范围下限正好压在 1.00 上，「没有差别」这个可能性没有被完全排除。人群是与配偶同住的美国老人，照护对象是失能的老年配偶，套到照护年轻残疾家属的人身上属于往外推。它能说明的是方向：吃力的那部分人风险更高。能分出去的照护活尽量分出去，托养和日间照料服务问当地残联和民政。照护者自己的慢性病别停药，见第 16 节第 1 条（药按医嘱吃满）。这条的受益人是你自己。', NULL, NULL, NULL, '不花钱。把照护的活分出去一部分，自己去做一次体检。', '研究是前瞻性人群队列，1993 到 1998 年，平均随访 4.5 年，在美国四个社区做。392 名照护者和 427 名非照护者，年龄 66 到 96 岁，都与配偶同住。四年内 103 人（12.6%）死亡。调整社会人口学因素、已有疾病和亚临床心血管疾病之后，一边照护一边报告有精神或情绪紧张的人，死亡风险比非照护对照高 63%（RR 1.63，95% CI 1.00–2.65，可信范围）。照护但未报告紧张的人（RR 1.08，95% CI 0.61–1.90）和配偶失能但本人不照护的人（RR 1.37，95% CI 0.73–2.58），调整后的死亡率都没有升高', '争议：这项研究的可信范围下限正好压在 1.00 上，「没有差别」这个可能性没有被完全排除。人群是与配偶同住的美国老人，照护对象是失能的老年配偶，套到照护年轻残疾家属的人身上属于往外推。它能说明的是方向：吃力的那部分人风险更高。能分出去的照护活尽量分出去，托养和日间照料服务问当地残联和民政。照护者自己的慢性病别停药，见第 16 节第 1 条（药按医嘱吃满）。这条的受益人是你自己。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 些","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-5', 'concept_archive_s33-5', 'claim_archive_s33-5', 'action', 'life_archive', '长期坐轮椅的，坐垫换成减压型，每天看一遍坐骨和尾骨', '33. 残疾之后怎么活', '普通海绵坐垫压久了会把皮肤压破，破了愈合很慢，容易感染。养老院里用减压坐垫的老人，坐骨那里的压疮明显更少，但把尾骨一起算就没看出差别。轮椅本身也要按人的尺寸配，别买个通用款就算了。', '定 B 的原因有两条。一是样本只有 232 人，主要终点的 P 值 0.04 刚过线，次要终点没有做出差别。二是人群是养老院里的高龄住户，套到年轻的轮椅使用者身上属于往外推。试验里所有人都先配了合身的轮椅，所以「合身」和「坐垫」是一起起作用的，别只换坐垫。长期卧床的压疮防护，气垫床和定时翻身，见第 17 节第 8 条（压疮）。基本型辅助器具的配置补贴怎么申请，见本节第 7 条（去县级残联问全）。', NULL, NULL, NULL, '一个减压坐垫几百元到上千元。每天看一遍，一分钟。', '这项随机临床试验在 12 家养老院做，2004 到 2008 年招募 232 名 65 岁以上、每天坐轮椅 6 小时以上、Braden 评分 18 分以下的住户。所有人先配了合身的轮椅，再随机分成两组。一组用皮肤保护型坐垫（空气、黏性流体加泡沫、或者凝胶加泡沫），一组用 7.6 厘米厚的分段式泡沫坐垫。随访 6 个月或者到发生压疮为止。坐骨结节部位的压疮，分段泡沫组 8 例（6.7%），皮肤保护型坐垫组 1 例（0.9%），P=0.04。把坐骨和骶尾部的压疮合起来算，分段泡沫组 21 例（17.6%），皮肤保护型坐垫组 12 例（10.6%），P=0.14，没有做出差别', '定 B 的原因有两条。一是样本只有 232 人，主要终点的 P 值 0.04 刚过线，次要终点没有做出差别。二是人群是养老院里的高龄住户，套到年轻的轮椅使用者身上属于往外推。试验里所有人都先配了合身的轮椅，所以「合身」和「坐垫」是一起起作用的，别只换坐垫。长期卧床的压疮防护，气垫床和定时翻身，见第 17 节第 8 条（压疮）。基本型辅助器具的配置补贴怎么申请，见本节第 7 条（去县级残联问全）。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","B 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-6', 'concept_archive_s33-6', 'claim_archive_s33-6', 'action', 'life_archive', '别买「能治好瘫痪、失明、耳聋」的疗法和器械', '33. 残疾之后怎么活', '广告法把话说死了。医疗、药品、医疗器械的广告，不许保证疗效，不许说治愈率和有效率，不许找人现身说法。所以「三个疗程站起来」「多少人已经康复」这类话本身就是违法广告，不用再研究它讲的原理。不是医疗器械的东西，连提治病都不允许。', '判断方法只有一条：看它敢不敢把话说满。正规医院的康复科不会承诺你几个疗程能站起来。碰到这类宣传，向 12315 或者当地市场监管部门举报。保健品那一套话术是同一个路子，见第 6 节第 10 条（保健品）。已经买了想退钱，按网购和预付式消费的办法走，见第 5 节第 29 条（网购认平台规则）。这条的受益人是你自己和家人。', NULL, NULL, NULL, '不花钱，是省钱。难在家里人抱着希望，劝不住。', '《广告法》第十六条规定，医疗、药品、医疗器械广告不得含有下列内容：「（一）表示功效、安全性的断言或者保证；（二）说明治愈率或者有效率；（三）与其他药品、医疗器械的功效和安全性或者其他医疗机构比较；（四）利用广告代言人作推荐、证明」。第十七条规定，除医疗、药品、医疗器械广告外，「禁止其他任何广告涉及疾病治疗功能，并不得使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语」。第四条规定，广告不得含有虚假或者引人误解的内容，不得欺骗、误导消费者，广告主应当对广告内容的真实性负责（全国，2021 年修正）', '判断方法只有一条：看它敢不敢把话说满。正规医院的康复科不会承诺你几个疗程能站起来。碰到这类宣传，向 12315 或者当地市场监管部门举报。保健品那一套话术是同一个路子，见第 6 节第 10 条（保健品）。已经买了想退钱，按网购和预付式消费的办法走，见第 5 节第 29 条（网购认平台规则）。这条的受益人是你自己和家人。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-7', 'concept_archive_s33-7', 'claim_archive_s33-7', 'action', 'life_archive', '残疾人证办下来之后，去县级残联把能申请的东西一次问全', '33. 残疾之后怎么活', '残疾人证本身不发钱，它是一把钥匙。接在它后面的是好几笔各自独立的待遇，每一笔都要自己去申请，不会自动上门。第一次去残联，就把清单上的项目一项项问过来，比来回跑几趟省事。', '办证本身的流程见第 24 节第 10 条（残疾人证）。补贴标准和具体办法多数由省一级定，同一项在两个省能差出好几倍。问的时候把每一项的名字记下来，回家按名字在当地残联官网和政府网站上再查一遍原文件，不要只听柜台上的口头说法。别指望一次问全，隔一年再去问一次，政策会变。', NULL, NULL, NULL, '不花钱。去一趟县级残联，问一上午。后面要跑的部门不止一个。', '证接上的待遇至少六项，各有各的出处。一是困难残疾人生活补贴和重度残疾人护理补贴，见第 7 节第 8 条（两项补贴）。二是残疾儿童康复救助，见本节第 8 条（康复救助）。三是基本型辅助器具配置补贴，依据是《残疾预防和残疾人康复条例》第二十六条。四是家庭无障碍设施改造补贴，见本节第 9 条（坡道扶手和浴室改造）。五是按比例就业和就业服务，见本节第 10 条（主动说明持证）。六是个人所得税减征，见本节第 11 条（个税减征）。《残疾预防和残疾人康复条例》第二十六条还写明，国家通过实施重点康复项目为城乡贫困残疾人、重度残疾人提供基本康复服务，「按照国家有关规定对基本型辅助器具配置给予补贴」。第二十条规定，县级以上人民政府有关部门和残联应当利用社区资源，设立康复场所或者购买服务，开展康复指导、日常生活能力训练、康复护理、辅助器具配置、信息咨询和转介等社区康复工作（全国，2017 年 7 月 1 日起施行）', '办证本身的流程见第 24 节第 10 条（残疾人证）。补贴标准和具体办法多数由省一级定，同一项在两个省能差出好几倍。问的时候把每一项的名字记下来，回家按名字在当地残联官网和政府网站上再查一遍原文件，不要只听柜台上的口头说法。别指望一次问全，隔一年再去问一次，政策会变。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-8', 'concept_archive_s33-8', 'claim_archive_s33-8', 'action', 'life_archive', '孩子不满 7 岁又有残疾或者孤独症的，去县级残联申请康复救助', '33. 残疾之后怎么活', '国家给 0 到 6 岁的残疾儿童和孤独症儿童建了一套康复救助制度，管手术、辅助器具和康复训练。救助对象先保困难家庭，地方财力允许的可以放宽年龄和家庭经济条件。这一段是康复效果最好的窗口，别拖到该上学了再说。机构要从残联的定点名单里挑。', '救助标准由各省定，先在当地残联官网查「残疾儿童康复救助实施办法」。定点机构名单也在残联手上。文件要求残联会同有关部门加强定点康复机构的准入和退出监管，建立定期检查和综合评估机制，并建立黑名单制度。不在名单里的机构，钱要自己全出，出了事也难追。这条的受益人是你的孩子，属于第二档。承诺「包好」的机构按本节第 6 条（能治好瘫痪）处理。', NULL, NULL, NULL, '不花钱。到县级残联交一次申请，然后在定点机构里选一家。', '《国务院关于建立残疾儿童康复救助制度的意见》写明，救助对象为符合条件的 0—6 岁视力、听力、言语、肢体、智力等残疾儿童和孤独症儿童。包括城乡最低生活保障家庭、建档立卡贫困户家庭的残疾儿童和儿童福利机构收留抚养的残疾儿童，残疾孤儿、纳入特困人员供养范围的残疾儿童，以及其他经济困难家庭的残疾儿童。其他经济困难家庭的具体认定办法由县级以上地方人民政府制定。文件还写明「有条件的地区，可扩大残疾儿童康复救助年龄范围，也可放宽对救助对象家庭经济条件的限制」。经费保障标准由县级以上地方人民政府依据本地财力状况、保障对象数量、残疾类别等分类确定，并建立动态调整机制。上位依据是《残疾预防和残疾人康复条例》第二十六条：国家建立残疾儿童康复救助制度，「逐步实现0—6岁视力、听力、言语、肢体、智力等残疾儿童和孤独症儿童免费得到手术、辅助器具配置和康复训练等服务」（全国，2018 年起）', '救助标准由各省定，先在当地残联官网查「残疾儿童康复救助实施办法」。定点机构名单也在残联手上。文件要求残联会同有关部门加强定点康复机构的准入和退出监管，建立定期检查和综合评估机制，并建立黑名单制度。不在名单里的机构，钱要自己全出，出了事也难追。这条的受益人是你的孩子，属于第二档。承诺「包好」的机构按本节第 6 条（能治好瘫痪）处理。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 高","口径 金钱","钱 0","时间 中","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-9', 'concept_archive_s33-9', 'claim_archive_s33-9', 'action', 'life_archive', '家里的坡道、扶手和浴室改造，可以向县级以上政府申请补贴', '33. 残疾之后怎么活', '《无障碍环境建设法》写了一条：县级以上政府应当支持、指导家庭无障碍设施改造，对符合条件的残疾人、老年人家庭应当给予适当补贴。这类项目一般由残联牵头，按年度名额做，所以要早点去登记。补多少、改哪几项由各地定。', '定 B 是因为法律只写了「应当给予适当补贴」，补多少、谁算符合条件全交给地方，没有全国统一的数字。先在当地残联官网查「困难重度残疾人家庭无障碍改造」。名额多数按年度分配，排队要早。小区加装电梯、楼道改造是另一套流程，走住建部门。公共场所的无障碍设施不达标，按第六十二条向主管部门投诉，它要给你答复。', NULL, NULL, NULL, '申请不花钱。改造本身多数有补贴，自己可能还要补一部分。要跑残联和街道。', '《无障碍环境建设法》第十九条：「县级以上人民政府应当支持、指导家庭无障碍设施改造。对符合条件的残疾人、老年人家庭应当给予适当补贴。」第十八条规定，对既有的不符合无障碍设施工程建设标准的居住建筑、居住区、公共建筑、公共场所、交通运输设施、城乡道路等，县级以上人民政府应当根据实际情况制定有针对性的无障碍设施改造计划并组织实施。第六十二条规定，任何组织和个人有权向政府有关主管部门提出加强和改进无障碍环境建设的意见和建议，对违反本法规定的行为进行投诉、举报；主管部门接到投诉举报「应当及时处理并予以答复」。第六十三条规定，对违反本法规定损害社会公共利益的行为，人民检察院可以提出检察建议或者提起公益诉讼（全国，2023 年 9 月 1 日起施行）', '定 B 是因为法律只写了「应当给予适当补贴」，补多少、谁算符合条件全交给地方，没有全国统一的数字。先在当地残联官网查「困难重度残疾人家庭无障碍改造」。名额多数按年度分配，排队要早。小区加装电梯、楼道改造是另一套流程，走住建部门。公共场所的无障碍设施不达标，按第六十二条向主管部门投诉，它要给你答复。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","B 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-10', 'concept_archive_s33-10', 'claim_archive_s33-10', 'action', 'life_archive', '找工作时主动说明自己持证，企业招你能抵掉一笔钱', '33. 残疾之后怎么活', '单位安排残疾人就业的比例不得低于在职职工总数的 1.5%，具体比例由省里定。达不到就要按差额人数交残疾人就业保障金，一个人头按本单位上年职工年平均工资算。所以招你不只是照顾，是实打实省钱。面试时把持证这件事说清楚，对方自己算得过来这笔账。', '对刚注册三年内、20 人以下的小微企业，这个理由不成立，别指望。保障金的减免政策这些年一直在调，具体以当年财政部的公告为准。另外，按比例就业要求的是真实用工。挂名领工资、让单位拿你去抵保障金，是骗取行为，你也会被牵进去。就业困难人员认定和社保补贴见第 7 节第 12 条（就业困难人员）。职业培训补贴见第 7 节第 13 条（职业培训补贴）。这条的受益人是你自己。', NULL, NULL, NULL, '不花钱。面试时多说一句话。难在开口。', '《残疾人就业条例》第八条：「用人单位安排残疾人就业的比例不得低于本单位在职职工总数的1.5%。具体比例由省、自治区、直辖市人民政府根据本地区的实际情况规定。」第九条：达不到所在地省级人民政府规定比例的，应当缴纳残疾人就业保障金。《残疾人就业保障金征收使用管理办法》第八条给了公式：「保障金年缴纳额=（上年用人单位在职职工人数×所在地省、自治区、直辖市人民政府规定的安排残疾人就业比例-上年用人单位实际安排的残疾人就业人数）×上年用人单位在职职工年平均工资」。第十六条：自工商登记注册之日起 3 年内，对安排残疾人就业未达到规定比例、在职职工总数 20 人以下（含 20 人）的小微企业，免征保障金。《残疾人保障法》第三十六条规定，国家对安排残疾人就业达到、超过规定比例或者集中安排残疾人就业的用人单位，依法给予税收优惠（全国，残疾人就业条例 2007 年 5 月 1 日起施行）', '对刚注册三年内、20 人以下的小微企业，这个理由不成立，别指望。保障金的减免政策这些年一直在调，具体以当年财政部的公告为准。另外，按比例就业要求的是真实用工。挂名领工资、让单位拿你去抵保障金，是骗取行为，你也会被牵进去。就业困难人员认定和社保补贴见第 7 节第 12 条（就业困难人员）。职业培训补贴见第 7 节第 13 条（职业培训补贴）。这条的受益人是你自己。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-11', 'concept_archive_s33-11', 'claim_archive_s33-11', 'action', 'life_archive', '残疾人的个人所得税可以减征，减多少打电话问省税务局', '33. 残疾之后怎么活', '个人所得税法写着，残疾人的所得可以减征个税。但是减多少、减多久，法律交给了省级政府定，所以各省不一样。有的省按年度定一个减免限额，有的按比例减。办法是打 12366 问当地税务局，或者在个人所得税 App 里找减免事项。', '收益量级定「小」，是因为法律本身没给数字，多数省份的减免额一年在几百到几千元这个量级。钱不算多，但办一次能长期用，值得跑。具体到你这个省减多少，只有当地税务局的公告算数，网上转的对照表常年过期。自己开小店的，行政事业性收费按《残疾人保障法》第三十六条免除，办执照时主动提。', NULL, NULL, NULL, '不花钱。申报时勾一项，或者交一次备案材料。', '《个人所得税法》第五条：「有下列情形之一的，可以减征个人所得税，具体幅度和期限，由省、自治区、直辖市人民政府规定，并报同级人民代表大会常务委员会备案：（一）残疾、孤老人员和烈属的所得；（二）因自然灾害遭受重大损失的。」《残疾人保障法》第三十六条另外规定，国家对从事个体经营的残疾人，依法给予税收优惠，并免除行政事业性收费（全国，个人所得税法 2019 年 1 月 1 日起施行）', '收益量级定「小」，是因为法律本身没给数字，多数省份的减免额一年在几百到几千元这个量级。钱不算多，但办一次能长期用，值得跑。具体到你这个省减多少，只有当地税务局的公告算数，网上转的对照表常年过期。自己开小店的，行政事业性收费按《残疾人保障法》第三十六条免除，办执照时主动提。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-12', 'concept_archive_s33-12', 'claim_archive_s33-12', 'action', 'life_archive', '导盲犬可以带进公共场所和公共交通，盲人免费坐市内公交', '33. 残疾之后怎么活', '法律写明，公共场所和公共交通要为带导盲犬、导听犬、辅助犬的残疾人提供便利。盲人凭有效证件免费坐市内公交、地铁和渡船，残疾人可以免费带随身必备的辅助器具。被拦下来时把这两条说出来，不行就投诉。', '法律写的是「提供便利」，没有配罚则，所以现场僵持时对方不一定立刻让步。手机里存一张法条截图，比背条号管用。当场解决不了就按第六十二条投诉，主管部门要答复。铁路和民航另有自己的规定，出行前先打客服确认。免费乘车的「有效证件」各地认的不完全一样，去当地残联问清楚认哪一种。', NULL, NULL, NULL, '不花钱。被拦下来时要开口引法条，可能要僵持一会儿。', '《无障碍环境建设法》第四十六条：「公共场所经营管理单位、交通运输设施和公共交通运输工具的运营单位应当为残疾人携带导盲犬、导听犬、辅助犬等服务犬提供便利。」第三十五条规定，政务服务便民热线和报警求助、消防应急、交通事故、医疗急救等紧急呼叫系统，应当逐步具备语音、大字、盲文、一键呼叫等无障碍功能。第六十二条规定，任何组织和个人有权对违反本法规定的行为投诉、举报，主管部门应当及时处理并予以答复。《残疾人保障法》第五十条：「盲人持有效证件免费乘坐市内公共汽车、电车、地铁、渡船等公共交通工具。盲人读物邮件免费寄递。」同条还规定，县级以上人民政府对残疾人搭乘公共交通工具应当给予便利和优惠，残疾人可以免费携带随身必备的辅助器具（全国，无障碍环境建设法 2023 年 9 月 1 日起施行）', '法律写的是「提供便利」，没有配罚则，所以现场僵持时对方不一定立刻让步。手机里存一张法条截图，比背条号管用。当场解决不了就按第六十二条投诉，主管部门要答复。铁路和民航另有自己的规定，出行前先打客服确认。免费乘车的「有效证件」各地认的不完全一样，去当地残联问清楚认哪一种。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-13', 'concept_archive_s33-13', 'claim_archive_s33-13', 'action', 'life_archive', '残疾人参加高考可以申请合理便利，用盲文卷的考试时间加一半', '33. 残疾之后怎么活', '残疾考生参加高考，可以申请盲文卷、大字卷、免外语听力、单独考场、带助听器和轮椅进场，考试时间也能延长。这些不会自动给，要按省里规定的时间交书面申请，附第二代以上的残疾人证。对结果不服，可以找省教育厅申请复核。', '申请时间由各省定，写在当年的高考报名办法里，错过就没有了。所以高三上学期就要去省教育考试院官网确认时间。第十八条还规定，研究生考试、成人高考这些国家教育考试，也可以参照申请。上学阶段学校不得拒收那一条见本节第 14 条（学校不得拒收）。这条的受益人是你自己或者你的孩子。', NULL, NULL, NULL, '不花钱。要在省里规定的时间内交一次书面申请，还要到现场确认。', '《残疾人参加普通高等学校招生全国统一考试管理规定》第五条列了十二项合理便利。包括为视力残疾考生提供现行盲文试卷、大字号试卷或者普通试卷；为听力残疾考生免除外语听力考试；允许视力残疾考生携带盲文笔、盲文手写板、无存储功能的盲文打字机、无存储功能的电子助视器、盲杖、光学放大镜等辅助器具；允许听力残疾考生携带助听器、人工耳蜗；允许行动不便的考生使用轮椅、助行器，有特殊需要的可以自带特殊桌椅。延长时间的幅度写在第五条第六项：「使用盲文试卷的视力残疾考生的考试时间，在该科目规定考试总时长的基础上延长50%；使用大字号试卷或普通试卷的视力残疾考生、因脑瘫或其他疾病引起的上肢无法正常书写或无上肢考生等书写特别困难考生的考试时间，在该科目规定考试总时长的基础上延长30%」。此外还有优先进入考点考场、单独标准化考场、配备引导辅助人员和手语翻译人员等。第七条规定申请程序：考生按省级教育考试机构规定的时间、地点、方式提出正式书面申请，并提供本人第二代及以上残疾人证；由专家组现场确认并综合评估，省级教育考试机构出具《告知书》。第八条规定，考生对《告知书》有异议，可以向省级教育行政部门提出书面复核申请。第九条规定，免除外语听力的，外语科成绩按「笔试成绩×外语科总分值/笔试部分总分值」计算。第十八条规定，残疾人参加其他国家教育考试需要合理便利的，可以参照本规定执行（全国，2017 年 4 月 7 日发布施行）', '申请时间由各省定，写在当年的高考报名办法里，错过就没有了。所以高三上学期就要去省教育考试院官网确认时间。第十八条还规定，研究生考试、成人高考这些国家教育考试，也可以参照申请。上学阶段学校不得拒收那一条见本节第 14 条（学校不得拒收）。这条的受益人是你自己或者你的孩子。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 时间","钱 0","时间 中","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-14', 'concept_archive_s33-14', 'claim_archive_s33-14', 'action', 'life_archive', '残疾孩子申请入学，学校不得拒收；到不了校的由教育局安排送教上门', '33. 残疾之后怎么活', '幼儿园和各类学校，对符合条件的残疾孩子申请入学不得拒收，普通职业学校也一样。孩子需要专人护理、到不了学校的，由县教育局安排送教上门或远程上课，照样有学籍。入学和转学由教育局请专家委员会评估后决定，不由学校自己说了算。', '学校口头说「我们这儿没条件」不算数。要它出书面答复，拿着书面答复去找县级教育局。评估是教育局委托专家委员会做的。第二十三条那句「学习要求可以有适度弹性」很有用，遇到学校拿成绩当理由劝退时可以引。孩子在校被欺凌怎么留证据、学校必须走哪道程序，见第 30 节第 3 条（校园欺凌）。高考的合理便利见本节第 13 条（合理便利）。这条的受益人是你的孩子。', NULL, NULL, NULL, '不花钱。要交一次申请，可能要经过一次评估。学校推脱时得往上找教育局。', '《残疾人教育条例》第七条：「学前教育机构、各级各类学校及其他教育机构应当依照本条例以及国家有关法律、法规的规定，实施残疾人教育；对符合法律、法规规定条件的残疾人申请入学，不得拒绝招收。」第二十九条：「普通职业学校不得拒绝招收符合国家规定的录取标准的残疾人入学，普通职业培训机构应当积极招收残疾人入学。」条例还规定，适龄残疾儿童、少年需要专人护理、不能到学校就读的，由县级人民政府教育行政部门统筹安排，通过提供送教上门或者远程教育等方式实施义务教育，并纳入学籍管理。第二十条规定，县级人民政府教育行政部门应当会同卫生行政部门、民政部门、残疾人联合会，建立由教育、心理、康复、社会工作等方面专家组成的残疾人教育专家委员会，由它评估身体状况、接受教育的能力和适应学校学习生活的能力并提出入学、转学建议；评估结果属于孩子的隐私，有关单位和工作人员负有保密义务。第二十三条规定，在普通学校随班就读的残疾学生，可以适用普通义务教育的课程设置方案、课程标准和教材，但是对其学习要求可以有适度弹性。第五十二条规定，残疾人参加国家教育考试需要必要支持条件和合理便利的，可以提出申请（全国，2017 年 5 月 1 日起施行）', '学校口头说「我们这儿没条件」不算数。要它出书面答复，拿着书面答复去找县级教育局。评估是教育局委托专家委员会做的。第二十三条那句「学习要求可以有适度弹性」很有用，遇到学校拿成绩当理由劝退时可以引。孩子在校被欺凌怎么留证据、学校必须走哪道程序，见第 30 节第 3 条（校园欺凌）。高考的合理便利见本节第 13 条（合理便利）。这条的受益人是你的孩子。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-15', 'concept_archive_s33-15', 'claim_archive_s33-15', 'action', 'life_archive', '右下肢或者双下肢没了也能考驾照，准驾车型叫 C5', '33. 残疾之后怎么活', '右下肢或双下肢没了、动不了，但能自己坐稳、上肢条件够的人，可以考残疾人专用的自动挡小车驾照，代号 C5。一只手掌缺失的也能申请。单眼视力障碍、听力障碍的人各有能考的车型。体检要去省里认定的专门医院做。', '门槛低得多的是残疾人机动轮椅车。《道路交通安全法》第一百一十九条把它列进非机动车，所以不用驾照；第五十八条规定，残疾人机动轮椅车在非机动车道内行驶时最高时速不得超过十五公里。C5 的车要装手动油门和刹车，改装要找有资质的厂家，改完去车管所变更登记。三个记分周期结束后一年内不提交身体条件证明，驾驶证会被注销。', NULL, NULL, NULL, '学费和普通驾照差不多，多数地方几千元。车要改装成手动操控。每三年查一次身体。', '《机动车驾驶证申领和使用规定》附件 1 把身体条件写得很细。第 8 目：「右下肢、双下肢缺失或者丧失运动功能但能够自主坐立，且上肢符合本项第5目规定的，可以申请残疾人专用小型自动挡载客汽车准驾车型的机动车驾驶证。一只手掌缺失，另一只手拇指健全，其他手指有两指健全，上肢和手指运动功能正常，且下肢符合本项第6目规定的，可以申请残疾人专用小型自动挡载客汽车准驾车型的机动车驾驶证」。第 6 目：单独左下肢缺失或者丧失运动功能、但右下肢正常的，可以申请小型自动挡汽车准驾车型。视力一项：「单眼视力障碍，优眼裸视力或者矫正视力达到对数视力表5.0以上，且水平视野达到150度的」，可以申请小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车准驾车型。听力一项：有听力障碍但佩戴助听设备能够辨别声源方向的，可以申请小型汽车、小型自动挡汽车准驾车型，驾驶时应当佩戴助听设备。第八十五条规定，办理残疾人专用小型自动挡载客汽车驾驶证业务时提交的身体条件证明，应当由经省级卫生健康行政部门认定的专门医疗机构出具。持这一准驾车型的人应当每三年进行一次身体检查，在记分周期结束后三十日内提交身体条件证明。第七十八条规定，驾驶时应当按规定在车身设置残疾人机动车专用标志（全国，公安部令第 172 号修正，2025 年 1 月 1 日起施行）', '门槛低得多的是残疾人机动轮椅车。《道路交通安全法》第一百一十九条把它列进非机动车，所以不用驾照；第五十八条规定，残疾人机动轮椅车在非机动车道内行驶时最高时速不得超过十五公里。C5 的车要装手动油门和刹车，改装要找有资质的厂家，改完去车管所变更登记。三个记分周期结束后一年内不提交身体条件证明，驾驶证会被注销。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 自由","钱 多","时间 多","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-16', 'concept_archive_s33-16', 'claim_archive_s33-16', 'action', 'life_archive', '康复在有康复医学科的正规机构做，强度听治疗师的，不是越猛越好', '33. 残疾之后怎么活', '把人接回家躺着等自然恢复，是最常见的错。中风后由多学科团队有组织地照护，一年后还活着、还能住在家里的人更多。但也别自己加码，中风后 24 小时内练得更早、更勤、更多，三个月后的结果反而更差。练多少、什么时候练，听康复科和治疗师的。', '争议：这两项证据都来自卒中，套到脊髓损伤、截肢、烧伤这些别的致残原因上属于往外推。AVERT 那一项说明的是「越早越猛」不成立，不是「早期活动没用」。试验里两组绝大多数人都在 24 小时内下了床，差的是频次和总量。挑机构时看它有没有康复医学科、有没有专职的康复治疗师和作业治疗师，别只看招牌上「康复」两个字。基层和三级医院之间怎么转、起付线怎么算，见第 24 节第 1 条（逐级转诊）。社区康复和辅助器具配置见本节第 7 条（去县级残联问全）。', NULL, NULL, NULL, '住院康复每天几百元，自费的那部分因地而异。时间按月算。每天都要练，很枯燥。', 'Cochrane 系统综述纳入 29 项试验、5902 名参与者，比较有组织的住院卒中单元照护和其他照护方式。随访到末次（中位 1 年）时，不良结局（死亡、残障或者需要机构照护）的比值比是 0.77（95% CI 0.69–0.87，可信范围），死亡的比值比是 0.76（95% CI 0.66–0.88），死亡或者依赖他人的比值比是 0.75（95% CI 0.66–0.85），证据质量中等。换算成绝对数，每 100 人接受卒中单元照护，多 2 人存活、多 6 人住在家里、多 6 人生活自理。另一方面，AVERT 试验在 5 个国家的 56 个急性卒中单元随机分配 2104 名患者，比较「常规照护」和「常规照护加超早期高强度活动」。三个月时结局良好（改良 Rankin 量表 0—2 分）的，超早期组 480 人（46%），常规组 525 人（50%），调整后比值比 0.73（95% CI 0.59–0.90，P=0.004）。死亡是 88 人比 72 人，没有做出差别（比值比 1.34，95% CI 0.93–1.93，P=0.113）', '争议：这两项证据都来自卒中，套到脊髓损伤、截肢、烧伤这些别的致残原因上属于往外推。AVERT 那一项说明的是「越早越猛」不成立，不是「早期活动没用」。试验里两组绝大多数人都在 24 小时内下了床，差的是频次和总量。挑机构时看它有没有康复医学科、有没有专职的康复治疗师和作业治疗师，别只看招牌上「康复」两个字。基层和三级医院之间怎么转、起付线怎么算，见第 24 节第 1 条（逐级转诊）。社区康复和辅助器具配置见本节第 7 条（去县级残联问全）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 死亡率","钱 多","时间 多","毅力 是","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-17', 'concept_archive_s33-17', 'claim_archive_s33-17', 'action', 'life_archive', '听力下降就去配助听器，配它的理由是听得见，不是防痴呆', '33. 残疾之后怎么活', '「戴助听器能防痴呆」这个说法目前没有立住。一项近千人的三年试验，总体上没有做出差别。只有在本来认知下降风险就偏高的那部分人里看到了差别。所以配助听器的理由是当下听得见、能和人说话、过马路能听见车，不是为了几十年以后的脑子。', '争议：网上常见的「助听器让认知下降少了近一半」来自这项试验里的一个亚组，不是它的主要结果，主要结果是两组没有差别。「配助听器」和「防痴呆」要分开看：前者该做，后者别当成理由。听力残疾考生高考可以免外语听力，见本节第 13 条（合理便利）。有听力障碍的人开车应当佩戴助听设备，见本节第 15 条（C5）。', NULL, NULL, NULL, '助听器几千到几万元，多数要自费。要验配，还要来回调试几次。', 'ACHIEVE 试验在美国 4 个社区做，纳入 977 名 70 到 84 岁、有未经治疗的听力损失、没有明显认知障碍的人。随机分成两组，一组接受听力干预（听力咨询和配助听器），一组接受健康教育对照，每 6 个月随访一次。主要终点是 3 年的整体认知评分变化。合并两个来源人群的主要分析里，两组没有显著差别：听力干预组 −0.200（95% CI −0.256 到 −0.144），对照组 −0.202（95% CI −0.258 到 −0.145），差值 0.002（95% CI −0.077 到 0.081），P=0.96。一项预设的敏感性分析显示，干预效果在两个来源人群之间存在差异（交互作用 P=0.010）。来自那项长期心血管健康观察研究的参与者年龄更大、认知下降的危险因素更多、基线认知分更低。研究者的结论是，听力干预可能在认知下降风险较高的人群里减少 3 年的认知变化，在风险较低的人群里则不能。试验没有报告归因于研究的严重不良事件', '争议：网上常见的「助听器让认知下降少了近一半」来自这项试验里的一个亚组，不是它的主要结果，主要结果是两组没有差别。「配助听器」和「防痴呆」要分开看：前者该做，后者别当成理由。听力残疾考生高考可以免外语听力，见本节第 13 条（合理便利）。有听力障碍的人开车应当佩戴助听设备，见本节第 15 条（C5）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 死亡率","钱 多","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-18', 'concept_archive_s33-18', 'claim_archive_s33-18', 'action', 'life_archive', '说一个成年人「管不了自己的事」，要向法院申请认定，家属说了不算', '33. 残疾之后怎么活', '一个成年人是不是「无民事行为能力」或者「限制民事行为能力」，只有法院能认定。家属、单位、居委会都不能自己说了算。要由利害关系人或者有关组织向法院申请。反过来，智力或者精神健康恢复了，也可以申请认定他恢复行为能力。这道程序既是限制，也是保护。', '申请走的是法院的特别程序，比普通民事案件快，但仍要几个月。要提交医院的诊断证明，法院多数还会委托司法鉴定，鉴定费通常几千元，由申请人先垫。不经过这道程序就替人签字、处分他的财产，事后可能被认定无效，房子卖了也可能要退回来。还要记住一点：限制民事行为能力不等于什么都不能做。和他的智力、精神状况相适应的事，以及纯得好处的事，他自己就能做，别一概代办。监护人怎么定见本节第 19 条（监护人）。', NULL, NULL, NULL, '向法院申请要交诉讼费，一般几十元到一百元。鉴定费另算，通常几千元，先由申请人垫。走完要几个月。', '《民法典》第二十一条：「不能辨认自己行为的成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。」第二十二条：「不能完全辨认自己行为的成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其智力、精神健康状况相适应的民事法律行为。」第二十四条：「不能辨认或者不能完全辨认自己行为的成年人，其利害关系人或者有关组织，可以向人民法院申请认定该成年人为无民事行为能力人或者限制民事行为能力人。」同条还规定，被认定之后，经本人、利害关系人或者有关组织申请，人民法院可以根据其智力、精神健康恢复的状况，认定其恢复为限制民事行为能力人或者完全民事行为能力人。有关组织包括：居民委员会、村民委员会、学校、医疗机构、妇女联合会、残疾人联合会、依法设立的老年人组织、民政部门等。第二十三条规定，无民事行为能力人、限制民事行为能力人的监护人是其法定代理人（全国，2021 年 1 月 1 日起施行）', '申请走的是法院的特别程序，比普通民事案件快，但仍要几个月。要提交医院的诊断证明，法院多数还会委托司法鉴定，鉴定费通常几千元，由申请人先垫。不经过这道程序就替人签字、处分他的财产，事后可能被认定无效，房子卖了也可能要退回来。还要记住一点：限制民事行为能力不等于什么都不能做。和他的智力、精神状况相适应的事，以及纯得好处的事，他自己就能做，别一概代办。监护人怎么定见本节第 19 条（监护人）。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 自由","钱 少","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-19', 'concept_archive_s33-19', 'claim_archive_s33-19', 'action', 'life_archive', '成年人的监护人按法定顺序定；被监护人伤了别人，由监护人赔', '33. 残疾之后怎么活', '成年人失去行为能力后，监护人按顺序来：配偶，父母和子女，其他近亲属，最后是愿意担任的其他人或组织。争起来了由居委会、村委会或民政部门指定，不服可以找法院。人还清醒时可以书面指定将来的监护人。被监护人伤了别人，由监护人赔。', '第三十三条那条就是意定监护。趁人清醒时用书面形式把人选定下来，能省掉后面一大半争议，具体怎么写见第 17 节第 1 条（意定监护）。赔偿那一段要当心：把人交给托养机构或者亲戚照看，责任仍在监护人身上，受托人只在自己有过错时承担相应责任。所以给被监护人买一份监护人责任保险是有意义的。《精神卫生法》第七十八条还规定，监护人遗弃患者或者不履行监护职责造成损害的，依法承担赔偿责任。', NULL, NULL, NULL, '不花钱。有争议时要到居委会、村委会、民政部门或者法院去解决。', '《民法典》第二十八条：无民事行为能力或者限制民事行为能力的成年人，由下列有监护能力的人按顺序担任监护人：「（一）配偶；（二）父母、子女；（三）其他近亲属；（四）其他愿意担任监护人的个人或者组织，但是须经被监护人住所地的居民委员会、村民委员会或者民政部门同意。」第三十一条：对监护人的确定有争议的，由被监护人住所地的居民委员会、村民委员会或者民政部门指定，对指定不服的可以向人民法院申请指定，也可以直接向人民法院申请。指定时「应当尊重被监护人的真实意愿，按照最有利于被监护人的原则」。指定之前权益处于无人保护状态的，由居民委员会、村民委员会、法律规定的有关组织或者民政部门担任临时监护人。第三十三条：「具有完全民事行为能力的成年人，可以与其近亲属、其他愿意担任监护人的个人或者组织事先协商，以书面形式确定自己的监护人」。第一千一百八十八条：「无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。」有财产的，从本人财产中支付赔偿费用，不足部分由监护人赔偿。第一千一百八十九条：监护人将监护职责委托给他人的，监护人仍应当承担侵权责任，受托人有过错的承担相应的责任（全国，2021 年 1 月 1 日起施行）', '第三十三条那条就是意定监护。趁人清醒时用书面形式把人选定下来，能省掉后面一大半争议，具体怎么写见第 17 节第 1 条（意定监护）。赔偿那一段要当心：把人交给托养机构或者亲戚照看，责任仍在监护人身上，受托人只在自己有过错时承担相应责任。所以给被监护人买一份监护人责任保险是有意义的。《精神卫生法》第七十八条还规定，监护人遗弃患者或者不履行监护职责造成损害的，依法承担赔偿责任。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 自由","钱 0","时间 中","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s33-20', 'concept_archive_s33-20', 'claim_archive_s33-20', 'action', 'life_archive', '因为残疾被拒招、不转正、少发钱，可以告，但先把过程成本算清', '33. 残疾之后怎么活', '法律禁止在招用、转正、晋级、评职称、报酬、社保上歧视残疾人。你可以向主管部门投诉，也可以去法院告。但打赢了官司，对方也不替你出律师费。所以先投诉，同时申请法律援助，再考虑打官司。', '过程成本必须先算。一审普通程序 6 个月起，可以延长；简易程序 3 个月。律师费不在《诉讼费用交纳办法》第六条列的诉讼费用里，第二十九条的「败诉方负担」不包括律师费。所以先走两条成本低的路：向人社部门或者残联投诉，由主管部门责令改正；同时申请法律援助，第四十二条对残疾人免予核查经济困难状况。取证是最难的一关。面试被拒时，对方很少留下书面理由，能录音、能留下聊天记录就留。已经入职的按劳动争议走仲裁，留证和时效见第 19 节第 8 条（离职前留证）。这条的受益人是你自己。', NULL, NULL, NULL, '律师费几千到几万元，自己出。一审普通程序 6 个月起，可以延长。证据要自己保存。', '《残疾人保障法》第三条：「禁止基于残疾的歧视。禁止侮辱、侵害残疾人。」第三十八条：「在职工的招用、转正、晋级、职称评定、劳动报酬、生活福利、休息休假、社会保险等方面，不得歧视残疾人。」同条还规定，残疾职工所在单位应当根据残疾职工的特点提供适当的劳动条件和劳动保护，并根据实际需要对劳动场所、劳动设备和生活设施进行改造。第六十四条：「违反本法规定，在职工的招用等方面歧视残疾人的，由有关主管部门责令改正；残疾人劳动者可以依法向人民法院提起诉讼。」《残疾人就业条例》第四条：「禁止在就业中歧视残疾人。」第十三条：用人单位不得在晋职、晋级、评定职称、报酬、社会保险、生活福利等方面歧视残疾职工。《法律援助法》第四十二条规定，申请人有材料证明属于「无固定生活来源的未成年人、老年人、残疾人等特定群体」的，免予核查经济困难状况。第四十五条规定，法律援助机构为老年人、残疾人提供法律援助服务的，应当根据实际情况提供无障碍设施设备和服务（全国）', '过程成本必须先算。一审普通程序 6 个月起，可以延长；简易程序 3 个月。律师费不在《诉讼费用交纳办法》第六条列的诉讼费用里，第二十九条的「败诉方负担」不包括律师费。所以先走两条成本低的路：向人社部门或者残联投诉，由主管部门责令改正；同时申请法律援助，第四十二条对残疾人免予核查经济困难状况。取证是最难的一关。面试被拒时，对方很少留下书面理由，能录音、能留下聊天记录就留。已经入职的按劳动争议走仲裁，留证和时效见第 19 节第 8 条（离职前留证）。这条的受益人是你自己。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"33. 残疾之后怎么活","A 级","性价比 一般","口径 金钱","钱 多","时间 多","毅力 是","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-1', 'concept_archive_s34-1', 'claim_archive_s34-1', 'action', 'life_archive', '同时吃两种感冒药或止痛药之前，先看成分表，对乙酰氨基酚只能占一种', '34. 家里的常备药别吃出事', '很多感冒药里都掺了对乙酰氨基酚，两盒一起吃就是吃了双份，过量会伤肝。在美国，它造成的急性肝衰竭病人里，近三成没等到换肝就死了。国内说明书建议一天最多吃 2 克，吃药期间也别喝酒。', '对乙酰氨基酚也叫扑热息痛。复方感冒药的通用名里带「氨酚」两个字的，比如氨酚伪麻、氨咖黄敏，就含这个成分。拿不准就把几盒药都拿给药店的药师看。定 B 是因为美国那组数字是病例登记，没有对照组，算不出看了成分表能少出多少事。收益定「大」是按后果定的：急性肝衰竭里有近三成直接死亡。', NULL, NULL, NULL, '不花钱。看一眼每盒药的成分表，一两分钟。', '美国 22 家医院用 6 年时间连续登记了 662 例急性肝衰竭。其中 275 例（42%）是对乙酰氨基酚造成的，吞下的剂量中位数是 24 克。这 275 人里，131 人（48%）是不小心吃多的，不是故意。不小心吃多的人里，38% 同时吃了两种以上含这个成分的药。这 275 人里，27% 没等到换肝就死了，8% 做了肝移植。国家药监局 2020 年要求非处方药说明书写明：过量使用会引起严重肝损伤，建议一日最大量不超过 2 克。说明书还要写明，尽量避免和含对乙酰氨基酚或其他解热镇痛药的药品合用。美国法规要求这类非处方药在警示第一条写明三种伤肝情形：超过一天最大量，和其他含对乙酰氨基酚的药同吃，用药期间每天喝 3 杯以上的酒。', '对乙酰氨基酚也叫扑热息痛。复方感冒药的通用名里带「氨酚」两个字的，比如氨酚伪麻、氨咖黄敏，就含这个成分。拿不准就把几盒药都拿给药店的药师看。定 B 是因为美国那组数字是病例登记，没有对照组，算不出看了成分表能少出多少事。收益定「大」是按后果定的：急性肝衰竭里有近三成直接死亡。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-2', 'concept_archive_s34-2', 'claim_archive_s34-2', 'action', 'life_archive', '孩子发烧不用阿司匹林、尼美舒利和安乃近，含安乃近的感冒药也不给未成年人吃', '34. 家里的常备药别吃出事', '孩子退烧，这三种药都别用。阿司匹林和瑞氏综合征有关，这种病伤脑伤肝，美国统计里约三成病孩死亡，警告发出后病例少了九成多。尼美舒利 12 岁以下禁用，安乃近 18 岁以下禁用。', '安乃近对成年人也不是首选药。说明书写明它可能引起粒细胞缺乏、再生障碍性贫血和过敏性休克，只在病情急重、又没有别的有效药时短期用。重感灵听名字像普通感冒药，里面就有安乃近。孩子该用什么退烧药、按体重吃多少，问儿科医生或药师。不满 3 个月的孩子发烧直接去医院，见第 20 节第 8 条（38 ℃ 就直接去医院）。定 B 是因为瑞氏综合征的数字来自监测报告，病例减少和警告发布是前后关系，不是对照试验。收益定「大」，是因为警告之后病例从每年 555 例降到 36 例以下。', NULL, NULL, NULL, '不花钱。买退烧药时看一眼通用名和成分表。', '瑞氏综合征会引起脑病和肝脏脂肪变性，通常出现在流感或水痘之后。美国 1981 到 1997 年的全国监测里，18 岁以下报告了 1207 例。82% 的病孩血里测得到水杨酸，这是阿司匹林这类药的成分。总病死率 31%。1980 年开始发布水杨酸类药的警告。那一年报告了 555 例，是高峰，1987 年起每年不超过 36 例。国家食药监局 2011 年规定，尼美舒利口服制剂禁止用于 12 岁以下儿童。国家药监局 2020 年规定安乃近片禁用于 18 岁以下青少年儿童。含安乃近的复方青蒿安乃近片、重感灵片和重感灵胶囊同样禁用于 18 岁以下。', '安乃近对成年人也不是首选药。说明书写明它可能引起粒细胞缺乏、再生障碍性贫血和过敏性休克，只在病情急重、又没有别的有效药时短期用。重感灵听名字像普通感冒药，里面就有安乃近。孩子该用什么退烧药、按体重吃多少，问儿科医生或药师。不满 3 个月的孩子发烧直接去医院，见第 20 节第 8 条（38 ℃ 就直接去医院）。定 B 是因为瑞氏综合征的数字来自监测报告，病例减少和警告发布是前后关系，不是对照试验。收益定「大」，是因为警告之后病例从每年 555 例降到 36 例以下。', '极高', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-3', 'concept_archive_s34-3', 'claim_archive_s34-3', 'action', 'life_archive', '60 岁以上、胃出过血、在吃抗凝药或激素的人，吃布洛芬这类止痛药之前先问医生', '34. 家里的常备药别吃出事', '布洛芬、萘普生、阿司匹林这类止痛药会伤胃。在大剂量的试验里，吃布洛芬的人胃出血、穿孔的风险是不吃的约 4 倍。年纪大、胃出过血、同时吃抗凝药或激素、每天喝酒的人，风险更高。', '论文结论讲的是大剂量用法。偶尔吃一两天、按说明书剂量吃的风险，这篇没有单独给数字。很多复方感冒药里也有这类成分，和止痛药一起吃就重复了，先看成分表。医生让你长期吃小剂量阿司匹林防血栓的，别自己停，也别自己再加一种止痛药。痛经怎么用这类药、什么时候该去妇科查，见第 3 节第 25 条（痛经就吃布洛芬这类止痛药）。', NULL, NULL, NULL, '不花钱。问一次医生或药师。', '这类药叫非甾体抗炎药，常见的有布洛芬、萘普生、双氯芬酸。一项荟萃分析汇总了 280 项这类药对安慰剂的随机试验，共 124513 人。和安慰剂比，上消化道穿孔、梗阻或出血的风险：布洛芬 RR 3.97（95% CI 2.22–7.10，约 4 倍），萘普生 4.22（2.71–6.56），双氯芬酸 1.89（1.16–3.09）。所有这类药都让心力衰竭的风险大约翻倍。美国法规要求这类非处方药写明胃出血警示。警示列出风险更高的六种人：60 岁以上，有过胃溃疡或出血，在吃抗凝药或激素，同时吃别的这类药，用药期间每天喝 3 杯以上的酒，吃得比说明书多或久。', '论文结论讲的是大剂量用法。偶尔吃一两天、按说明书剂量吃的风险，这篇没有单独给数字。很多复方感冒药里也有这类成分，和止痛药一起吃就重复了，先看成分表。医生让你长期吃小剂量阿司匹林防血栓的，别自己停，也别自己再加一种止痛药。痛经怎么用这类药、什么时候该去妇科查，见第 3 节第 25 条（痛经就吃布洛芬这类止痛药）。', '极高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","A 级","性价比 极高","口径 死亡率","钱 0","时间 少","毅力 否","收益 大"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-4', 'concept_archive_s34-4', 'claim_archive_s34-4', 'action', 'life_archive', '2 岁以下的孩子感冒，别自己喂复方感冒药和止咳药', '34. 家里的常备药别吃出事', '国家药监局要求 14 种儿童复方感冒药加上警示：不建议家长自己给 2 岁以下孩子用，要在医生或药师指导下用。在孩子身上做的试验里，止咳药、抗过敏药效果都不比安慰剂好。', '这 14 种里很多名字带「氨酚」，也含对乙酰氨基酚，再和退烧药一起吃就重复了，见本节第 1 条（对乙酰氨基酚）。那篇综述里有一项试验发现蜂蜜比安慰剂好，但不满 1 岁不能喂蜂蜜，见第 20 节第 6 条（蜂蜜）。定 B 是因为综述里每类药的试验都少，作者没有合并出数字。收益定「中」是判断：这类药对小孩没有证实的好处，风险主要是过量和成分重复。', NULL, NULL, NULL, '不花钱，还能省下买药的钱。', '国家药监局 2021 年第 57 号公告修订了 14 个品种的说明书，包括氨酚麻美口服溶液、小儿氨酚黄那敏颗粒、小儿氨酚烷胺颗粒等。新增警示语是「不建议家长或监护人自行给2岁以下婴幼儿使用本品，应在医师或药师的指导下使用」。注意事项加了「应严格按照药品说明书用法用量使用，避免用药过量」。还加了「应避免合并使用含有相同或相似活性成份的抗感冒药」。一篇 Cochrane 系统综述纳入 29 项随机对照试验，其中 10 项在儿童身上做。儿童试验里，这几类药都不比安慰剂好：止咳药，抗组胺药（抗过敏成分），抗组胺药加减充血剂（通鼻子的成分），止咳药加支气管扩张剂。21 项研究报告了不良反应，含抗组胺药和右美沙芬的制剂不良反应更多。', '这 14 种里很多名字带「氨酚」，也含对乙酰氨基酚，再和退烧药一起吃就重复了，见本节第 1 条（对乙酰氨基酚）。那篇综述里有一项试验发现蜂蜜比安慰剂好，但不满 1 岁不能喂蜂蜜，见第 20 节第 6 条（蜂蜜）。定 B 是因为综述里每类药的试验都少，作者没有合并出数字。收益定「中」是判断：这类药对小孩没有证实的好处，风险主要是过量和成分重复。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-5', 'concept_archive_s34-5', 'claim_archive_s34-5', 'action', 'life_archive', '怀孕 20 周以后，别自己吃布洛芬这类止痛药', '34. 家里的常备药别吃出事', '怀孕 20 周以后，羊水大部分是胎儿的肾做出来的。这时吃布洛芬这类药，可能伤到胎儿的肾、让羊水变少。美国收到的这类报告里，有新生儿死亡的病例。医生开的小剂量阿司匹林不在此列。', 'FDA 提醒，很多治感冒、流感、失眠的非处方药里也含这类成分，要看成分表。美国非处方药标签原来只警告怀孕最后 3 个月，这次把界线提前到了 20 周左右。小剂量阿司匹林防子痫前期，见第 27 节第 5 条（小剂量阿司匹林）。定 B 是因为数字来自不良事件报告，有多少人吃了药却没出事不知道。收益定「中」是判断：结局严重，但发生得少。', NULL, NULL, NULL, '不花钱。', '美国食品药品监督管理局（FDA）2020 年 10 月发布安全警示。怀孕约 20 周以后使用非甾体抗炎药，可能引起胎儿肾脏问题，导致羊水过少。警示同时管处方药和非处方药，包括阿司匹林、布洛芬、萘普生、双氯芬酸、塞来昔布。FDA 查了截至 2017 年 7 月的不良事件报告，找到 35 例羊水过少或新生儿肾功能不全，全是严重结局。其中 5 例新生儿死亡，都伴有新生儿肾衰竭。文献里，多数羊水过少在停药后 72 小时到 6 天内恢复。FDA 建议孕妇 20 周以后不要用这类药，除非医生明确这么建议。81 毫克的小剂量阿司匹林由医生开来治孕期特定问题的，不受这条限制。需要止痛退烧时，FDA 提到可以用对乙酰氨基酚等其他药，先问药师或医生。', 'FDA 提醒，很多治感冒、流感、失眠的非处方药里也含这类成分，要看成分表。美国非处方药标签原来只警告怀孕最后 3 个月，这次把界线提前到了 20 周左右。小剂量阿司匹林防子痫前期，见第 27 节第 5 条（小剂量阿司匹林）。定 B 是因为数字来自不良事件报告，有多少人吃了药却没出事不知道。收益定「中」是判断：结局严重，但发生得少。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-6', 'concept_archive_s34-6', 'claim_archive_s34-6', 'action', 'life_archive', '反酸烧心自己买奥美拉唑，最多吃 7 天；吞咽困难、呕血、黑便就直接去医院', '34. 家里的常备药别吃出事', '奥美拉唑肠溶片从 2022 年起不用处方就能买，但说明书写明自己吃不超过 7 天，两个月内别再吃。吞咽困难或疼痛、呕血、便血或黑便时不要自己吃，这些可能是严重情况的信号。这药还可能盖住胃癌的症状，耽误诊断。', '氯吡格雷是放过支架、得过心梗的人常吃的防血栓药。奥美拉唑会让它变弱，在吃的人先问医生。定 B 是因为这些是说明书的规定，没有研究算过照着做能少出多少事。收益定「中」是判断：它防的是把胃出血、胃癌拖晚了，但多数反酸烧心并不严重。', NULL, NULL, NULL, '不花钱。按说明书的天数吃。', '国家药监局 2022 年第 68 号公告把奥美拉唑肠溶片从处方药转成非处方药，同时发布说明书范本。范本写的适应症是「胃酸过多引起的烧心和反酸症状的短期缓解」。注意事项写明：使用不得超过 7 天，症状没缓解要咨询医师或药师。两个月以内不得再次服用，症状反复要立即就医。吞咽困难或疼痛、呕血、便血或黑便时请勿使用，这些可能是严重情况的征兆。出现明显消瘦、反复呕吐、吞咽困难、呕血或黑便这类报警症状时，要先排除恶性肿瘤，因为治疗可能掩盖症状、延误诊断。55 岁以上出现新的症状或症状有变化，要咨询医生。在吃氯吡格雷的人要避免同时吃奥美拉唑。', '氯吡格雷是放过支架、得过心梗的人常吃的防血栓药。奥美拉唑会让它变弱，在吃的人先问医生。定 B 是因为这些是说明书的规定，没有研究算过照着做能少出多少事。收益定「中」是判断：它防的是把胃出血、胃癌拖晚了，但多数反酸烧心并不严重。', '高', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-7', 'concept_archive_s34-7', 'claim_archive_s34-7', 'action', 'life_archive', '普通感冒别找医生要抗生素', '34. 家里的常备药别吃出事', '感冒吃抗生素，好得不比不吃快。成年人吃了，副作用的风险是不吃的两倍多。流脓鼻涕不到 10 天的，吃抗生素也没有确定的好处。', '这一版是 2025 年重新发布的，摘要写明文献检索截至 2013 年。抗生素在国内是处方药，药店要凭处方卖，家里剩的抗生素也别自己拿来吃。收益定「中」是判断：它防的是不良反应，不是死亡。', NULL, NULL, NULL, '不花钱，还能省下药钱。', '一篇 Cochrane 系统综述汇总了 6 项随机试验、1147 人。感冒吃抗生素和吃安慰剂比，没好或症状持续的比例没有明显差别（RR 0.83，95% CI 0.60–1.14，差别不显著）。不良反应的风险是安慰剂组的 1.8 倍（95% CI 1.01–3.21）。其中成人 2.62 倍（1.32–5.18），儿童没有增加（0.91，0.51–1.63）。流脓鼻涕不到 10 天的急性脓性鼻炎，吃抗生素也没有明确好处（RR 0.73，0.47–1.13）。不良反应却多了（RR 1.46，1.10–1.94，高约 46%）。作者结论是：这两种情况都不推荐常规用抗生素。', '这一版是 2025 年重新发布的，摘要写明文献检索截至 2013 年。抗生素在国内是处方药，药店要凭处方卖，家里剩的抗生素也别自己拿来吃。收益定「中」是判断：它防的是不良反应，不是死亡。', '高', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","A 级","性价比 高","口径 死亡率","钱 0","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-8', 'concept_archive_s34-8', 'claim_archive_s34-8', 'action', 'life_archive', '拉肚子先喝口服补液盐补水，5 岁以下的孩子不给止泻药', '34. 家里的常备药别吃出事', '拉肚子最要紧的是补水，不是止泻。按说明书兑水喝口服补液盐，别拿果汁饮料代替，太甜反而让人更缺水。5 岁以下的孩子不给洛哌丁胺这类止泻药，严重的会肠梗阻，可能致命。', '买的时候看说明书上的渗透压，选低渗配方。手册写明，孩子大便带血多半是细菌性痢疾，要去看医生用抗生素，不能只在家补水。收益定「中」是判断：手里的数字比的是两种补液盐，不是喝和不喝。', NULL, NULL, NULL, '一盒口服补液盐几块到十几块钱，家里备一盒。', '世界卫生组织的腹泻治疗手册写明，「止泻」药和止吐药对儿童急性或迁延性腹泻没有实际益处。它们不能预防脱水，也不能改善营养。有些有危险的、有时致命的副作用，绝不能给 5 岁以下儿童用。洛哌丁胺这类减慢肠蠕动的药，可能引起严重的麻痹性肠梗阻，可以致命，还可能拖长感染。手册还写明，糖太多的饮料会把身体里的水吸进肠子，造成高钠性脱水，比如软饮料和市售果汁饮料。世卫手册推荐的是低渗配方，总渗透压 245 mOsm/L。和旧配方比，它让计划外的静脉输液少了 33%。一篇 Cochrane 综述汇总 8 项试验，结果相近（OR 0.59，95% CI 0.45–0.79，少约四成）。', '买的时候看说明书上的渗透压，选低渗配方。手册写明，孩子大便带血多半是细菌性痢疾，要去看医生用抗生素，不能只在家补水。收益定「中」是判断：手里的数字比的是两种补液盐，不是喝和不喝。', '一般', 'A', 1, 'very_strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","A 级","性价比 一般","口径 死亡率","钱 少","时间 少","毅力 否","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-9', 'concept_archive_s34-9', 'claim_archive_s34-9', 'action', 'life_archive', '止痛药一个月别吃超过 15 天，复方止痛药别超过 10 天，不然头痛可能就是药吃出来的', '34. 家里的常备药别吃出事', '头痛老犯、就天天吃止痛药，可能越吃越痛。国际头痛分类把这叫药物过度使用性头痛。普通止痛药一个月吃 15 天以上，复方止痛药 10 天以上，连着超过 3 个月，就够得上。多数人停掉吃多的药以后会好转。', '药名里带「咖」字的止痛片，一般加了咖啡因，按复方算 10 天。一个月里头痛的天数越来越多，就去神经内科看，别只靠加药。定 B 是因为分类标准给的是诊断门槛，不是对照试验。收益定「中」是判断：它换回的是少头痛的日子，不涉及死亡。', NULL, NULL, NULL, '不花钱。要记吃药的天数，还要忍住不随手吃。', '国际头痛学会的《国际头痛疾病分类》第 3 版给了诊断标准。原本有头痛病的人，每月头痛 15 天以上，同时规律过量使用治头痛的药超过 3 个月。对乙酰氨基酚、阿司匹林、布洛芬这类非阿片止痛药，过量的门槛是每月 15 天及以上。复方止痛药的门槛是每月 10 天及以上。复方止痛药指两类以上有止痛作用的药合在一起，或者加了咖啡因这类辅助成分，比如对乙酰氨基酚加可待因。几种非阿片止痛药轮着吃，天数合起来算。分类说明写明，多个国家的流行病学证据显示，每月头痛 15 天以上的人里，超过一半属于这种头痛。多数病人停掉过量的药后会好转，预防头痛的治疗也更起作用。', '药名里带「咖」字的止痛片，一般加了咖啡因，按复方算 10 天。一个月里头痛的天数越来越多，就去神经内科看，别只靠加药。定 B 是因为分类标准给的是诊断门槛，不是对照试验。收益定「中」是判断：它换回的是少头痛的日子，不涉及死亡。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 中"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-10', 'concept_archive_s34-10', 'claim_archive_s34-10', 'action', 'life_archive', '过期药和用不上的剩药定期清出来，连包装投进有害垃圾桶，别留在家里', '34. 家里的常备药别吃出事', '小孩背着大人误吃的药，近一半是处方药片。误吃的处方药里，约三成是爷爷奶奶的。用不上的药清出来，就少一样能被孩子翻到的东西。清出来的药连包装投进有害垃圾桶，或者交给收旧药的药店。', '各地的垃圾分类目录不完全一样，以小区垃圾房贴的目录为准。上海把中药药渣归入湿垃圾，不算有害垃圾。留下来的药放在原盒里，别倒进分药盒或别的瓶子，放到孩子够不着的地方，见第 13 节第 20 条（误服）。家里剩的抗生素也别自己拿来吃，见本节第 7 条（抗生素）。美国在没有回收点时，让人把药混进咖啡渣、猫砂再封袋扔进普通垃圾，少数强效止痛药允许冲马桶。这是美国的做法，国内按当地分类投放。定 B 是因为美国那几组数字只是登记，没有研究算过清理药箱能少多少次误吃。收益定「小」：手里的数字是急诊次数，不是死亡，也算不出清理这个动作的效果。', NULL, NULL, NULL, '不花钱。每年翻一次药箱，十几分钟。', '美国急诊监测数据估计，2004 到 2013 年，不满 6 岁的孩子背着大人误吃药品，看了约 64 万次急诊（估计值 640161 次）。2013 年一年约 5.9 万次（59092 次）。2010 到 2013 年，最常见的是口服处方药片剂，占 45.9%。处方药里最常见的是阿片类止痛药（13.8%）和苯二氮䓬类安眠镇静药（12.7%）。美国 5 家中毒控制中心 2017 年问了打电话求助的家长。孩子误吃处方药的，30.7% 吃的是祖父母的药。一半以上（51.5%）的处方药，在孩子拿到之前已经被大人从原包装里取了出来。国内的《国家危险废物名录（2025 年版）》把家庭日常生活中产生的废药品及其包装物，列为生活垃圾中的危险废物。上海的分类投放指引把废药品归入有害垃圾，写明包括过期药物、药物胶囊、药片、药品内包装，「废弃药品宜连带包装一并投放」。上海还规定，药店收集的市民家庭过期废弃药品，由各区市场监管部门设临时中转点。美国 FDA 说，处理过期和用不上的药，最好的办法是交给回收点。', '各地的垃圾分类目录不完全一样，以小区垃圾房贴的目录为准。上海把中药药渣归入湿垃圾，不算有害垃圾。留下来的药放在原盒里，别倒进分药盒或别的瓶子，放到孩子够不着的地方，见第 13 节第 20 条（误服）。家里剩的抗生素也别自己拿来吃，见本节第 7 条（抗生素）。美国在没有回收点时，让人把药混进咖啡渣、猫砂再封袋扔进普通垃圾，少数强效止痛药允许冲马桶。这是美国的做法，国内按当地分类投放。定 B 是因为美国那几组数字只是登记，没有研究算过清理药箱能少多少次误吃。收益定「小」：手里的数字是急诊次数，不是死亡，也算不出清理这个动作的效果。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 否","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_archive_s34-11', 'concept_archive_s34-11', 'claim_archive_s34-11', 'action', 'life_archive', '用头孢、甲硝唑这类抗菌药期间和停药后 7 天内不喝酒，藿香正气水、止咳糖浆这类含酒精的药也不碰', '34. 家里的常备药别吃出事', '部分头孢、甲硝唑这类药碰上酒精，会让人脸红、心慌、胸闷、呕吐，重的血压往下掉。不光是白酒啤酒，藿香正气水、止咳糖浆这类含酒精的药也会引起。吃药期间到停药后 7 天都别碰。', '不是每一种头孢都会这样，但普通人分不清，吃哪种都照这条做最省事。医生开头孢或甲硝唑时，主动说一句最近几天喝没喝过酒。那篇科普建议用药前 3 天也别喝，同时承认这个间隔目前没有权威说法。一旦脸红心慌，马上停掉含酒精的东西。科普说轻的能自己缓过来，重的要送医院。吃对乙酰氨基酚期间也别喝酒，见本节第 1 条（对乙酰氨基酚）。定 B 是因为证据是病例整理和说明书，没有对照。收益定「小」：那 82 例都在几小时内缓过来，没有死亡，重度的只有 5 例。', NULL, NULL, NULL, '不花钱。一周多不喝酒，吃别的药前看一眼成分里有没有乙醇。', '这叫双硫仑样反应。福建省药监局 2023 年的安全用药科普说，部分头孢类药物服药前后饮酒，可能引发这种反应，「会严重损害健康甚至导致生命危险」。症状有面部潮红、出汗、心悸，甚至呼吸困难、血压下降、过敏性休克。科普按《中华人民共和国药典临床用药须知》列出的药，有头孢唑林、头孢曲松、头孢哌酮、甲硝唑、替硝唑、呋喃唑酮等。科普写明「用药后 7 天内禁止饮酒和食用含酒精的药物、食物等」，例子有酒心巧克力和藿香正气水。理由是被药抑制的那种酶，常要 4 到 5 天才能恢复。广州一家医院整理了 2 年里的 82 例病例。由头孢类引起的 57 例（69.51%），硝基咪唑类（甲硝唑、替硝唑这类）10 例（12.20%）。酒精来自酒类饮料的 40 例（48.78%），来自含乙醇药物的 31 例（37.80%）。口服的有藿香正气水、止咳糖浆、益母草流浸膏等。82 例里轻度 68 例、中度 9 例、重度 5 例，1 到 3 小时内缓解，没有死亡。美国甲硝唑说明书要求，用药期间和停药后至少 3 天不喝酒，也不用含丙二醇的产品。', '不是每一种头孢都会这样，但普通人分不清，吃哪种都照这条做最省事。医生开头孢或甲硝唑时，主动说一句最近几天喝没喝过酒。那篇科普建议用药前 3 天也别喝，同时承认这个间隔目前没有权威说法。一旦脸红心慌，马上停掉含酒精的东西。科普说轻的能自己缓过来，重的要送医院。吃对乙酰氨基酚期间也别喝酒，见本节第 1 条（对乙酰氨基酚）。定 B 是因为证据是病例整理和说明书，没有对照。收益定「小」：那 82 例都在几小时内缓过来，没有死亡，重度的只有 5 例。', '一般', 'B', 1, 'strong', 'low', 'action', 'published', '{"34. 家里的常备药别吃出事","B 级","性价比 一般","口径 死亡率","钱 0","时间 少","毅力 些","收益 小"}', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB001', 'concept_blindspot_LB001', 'claim_blindspot_LB001', 'blindspot', 'blindspot', '罐头为什么能放很久？', 'food · 生活盲区', '热处理 + 密封是商业罐藏长期保存的核心机制之一。', '长期保存可以通过控制微生物、温度、水分、酸度和再污染来实现，不只有防腐剂这一条路。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB002', 'concept_blindspot_LB002', 'claim_blindspot_LB002', 'blindspot', 'blindspot', '未开封罐头为什么通常不用放冰箱？', 'food · 生活盲区', '符合商业罐藏工艺的未开封罐头可在常温保存。', '保存稳定性来自处理和密封，而不是“冷藏之前先把它变安全”。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB003', 'concept_blindspot_LB003', 'claim_blindspot_LB003', 'blindspot', 'blindspot', '罐头开封后为什么要冷藏？', 'food · 生活盲区', '开封破坏了原来的密封保护，微生物就重新获得了进入和生长的机会。', '保护机制的一部分是“隔绝再污染”；开封就打破了这个条件。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB004', 'concept_blindspot_LB004', 'claim_blindspot_LB004', 'blindspot', 'blindspot', '“保质期长”不等于“加了很多防腐剂”', 'food · 生活盲区', '食品能久放，可能来自热处理、低水分、低温、酸度、密封等多种机制。', '不同微生物对温度、水分活度、酸碱度和氧气的耐受不同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB005', 'concept_blindspot_LB005', 'claim_blindspot_LB005', 'blindspot', 'blindspot', '食品包装上的“最佳食用期”不等于“当天过期就有毒”', 'food · 生活盲区', '日期标签可能涉及品质而不一定等同于瞬间变成不安全。', '风味、质地、营养品质和微生物安全不是完全同一个概念。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB006', 'concept_blindspot_LB006', 'claim_blindspot_LB006', 'blindspot', 'blindspot', '冰箱不会“杀死所有细菌”', 'food · 生活盲区', '冰箱主要是降低温度、减慢许多微生物的生长，而不是把食品灭菌。', '许多微生物在低温下仍可存活，有些还能生长。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB007', 'concept_blindspot_LB007', 'claim_blindspot_LB007', 'blindspot', 'blindspot', '冷冻不等于消毒', 'food · 生活盲区', '冷冻主要抑制生长，不能把所有病原微生物都可靠杀死。', '低温让微生物代谢和繁殖变慢，但许多微生物可在冷冻中存活。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB008', 'concept_blindspot_LB008', 'claim_blindspot_LB008', 'blindspot', 'blindspot', '冷冻烧（freezer burn）主要是品质问题', 'food · 生活盲区', '冷冻烧更多是水分升华和氧化造成的干燥、变色、风味下降。', '包装不严时食品表面水分会迁移到空气中，形成干燥区域。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB009', 'concept_blindspot_LB009', 'claim_blindspot_LB009', 'blindspot', 'blindspot', '剩菜真正重要的是时间和温度，不是“隔夜”两个字', 'food · 生活盲区', '食品安全风险和它放了多久、处于什么温度、是否快速冷却更相关。', '细菌在适宜温度下繁殖速度快，时间越长风险越可能上升。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB010', 'concept_blindspot_LB010', 'claim_blindspot_LB010', 'blindspot', 'blindspot', '剩菜不是越烫越安全，重新加热也不能修复所有问题', 'food · 生活盲区', '彻底加热能杀灭许多活菌，但不能把所有已经形成的风险物质或储存不当造成的问题“洗掉”。', '食品安全是多环节控制，不是最后一锅煮开就全部归零。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB011', 'concept_blindspot_LB011', 'claim_blindspot_LB011', 'blindspot', 'blindspot', '“看起来没坏”不能证明食品安全', 'food · 生活盲区', '有害微生物往往不会让食物立刻产生明显异味、颜色或口感变化。', '病原微生物和腐败微生物不是一回事。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB012', 'concept_blindspot_LB012', 'claim_blindspot_LB012', 'blindspot', 'blindspot', '生鸡肉通常不需要先冲洗', 'food · 生活盲区', '冲洗生禽肉可能把污染液滴带到水槽、台面和其他食物上。', '水不能可靠地杀死病原体，却会增加污染扩散机会。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB013', 'concept_blindspot_LB013', 'claim_blindspot_LB013', 'blindspot', 'blindspot', '洗菜和“消毒”不是一回事', 'food · 生活盲区', '流动水冲洗可以去掉部分表面污物，但不等于把所有病原体消灭。', '微生物可能附着在复杂表面或存在于缝隙中。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB014', 'concept_blindspot_LB014', 'claim_blindspot_LB014', 'blindspot', 'blindspot', '霉了的软面包不能靠“切掉一块”解决', 'food · 生活盲区', '高含水食品内部可能已经被肉眼看不到的霉菌丝或细菌污染。', '霉菌的可见部分只是表面，菌丝可能已经深入食品。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB015', 'concept_blindspot_LB015', 'claim_blindspot_LB015', 'blindspot', 'blindspot', '硬奶酪和软奶酪的“发霉处理”并不一样', 'food · 生活盲区', '部分硬奶酪表面的小块非特定霉斑可以按食品安全指导深切去除，但软奶酪通常应丢弃。', '硬质、低含水结构更不容易让霉菌深入，软湿食品则更容易被污染。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB016', 'concept_blindspot_LB016', 'claim_blindspot_LB016', 'blindspot', 'blindspot', '“天然”不是健康认证', 'food · 生活盲区', 'FDA 并没有把“natural”定义成一种全面的营养或健康等级。', '健康价值还要看糖、盐、脂肪、能量、污染和整体饮食结构。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB017', 'concept_blindspot_LB017', 'claim_blindspot_LB017', 'blindspot', 'blindspot', '“有机”也不等于“营养一定更高”', 'food · 生活盲区', '有机是生产与认证体系，不是“营养更高”的通用标签。', '生产方式和营养组成不是同一个维度。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB018', 'concept_blindspot_LB018', 'claim_blindspot_LB018', 'blindspot', 'blindspot', '食品标签上的“每份”不是建议你吃这么多', 'food · 生活盲区', 'Nutrition Facts 的 serving size 用于统一计算标签信息，不是在告诉你应该吃多少。', '营养标签需要一个标准计算单位，但消费者的实际摄入量可能不同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB019', 'concept_blindspot_LB019', 'claim_blindspot_LB019', 'blindspot', 'blindspot', '“无添加糖”不等于“里面没有糖”', 'food · 生活盲区', 'total sugars 与 added sugars 是不同概念。', '标签把天然糖和加工中添加的糖区分开，是为了帮助理解糖的来源。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB020', 'concept_blindspot_LB020', 'claim_blindspot_LB020', 'blindspot', 'blindspot', '“0 糖”不等于“整个饮料没有任何碳水或热量”', 'food · 生活盲区', '营养标签中的零值和具体法规定义有关，且不同地区阈值不同。', '食品标签是法规定义下的计量语言，不是“无限精确的化学分析”。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB021', 'concept_blindspot_LB021', 'claim_blindspot_LB021', 'blindspot', 'blindspot', '果汁和完整水果不是同一种食物', 'food · 生活盲区', '果汁通常少了完整水果中的纤维结构，也更容易一次喝下较多糖和能量。', '食物被榨成液体后，体积和饱腹感的关系会改变。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB022', 'concept_blindspot_LB022', 'claim_blindspot_LB022', 'blindspot', 'blindspot', '“清淡”不等于“低升糖”', 'food · 生活盲区', '口味清淡主要是油、盐、辣等感官维度；血糖反应受碳水类型、加工、纤维和食物结构影响。', '影响血糖的不只有“油盐”，还有碳水的种类、结构和消化速度。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB023', 'concept_blindspot_LB023', 'claim_blindspot_LB023', 'blindspot', 'blindspot', '粥的血糖反应不能只凭“清淡”判断', 'food · 生活盲区', '不同粥的原料、颗粒、加工和搭配不同，GI 可以差异很大。', '加工形式和食材组成会影响消化速度和血糖反应。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB024', 'concept_blindspot_LB024', 'claim_blindspot_LB024', 'blindspot', 'blindspot', '复合维生素不是“保险型健康升级包”', 'food · 生活盲区', '对没有特定缺乏的人，常规复合维生素并不是公认的通用长寿药。', '营养素缺乏与“多一点就更健康”是两套逻辑。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB025', 'concept_blindspot_LB025', 'claim_blindspot_LB025', 'blindspot', 'blindspot', '“排毒饮料”不是身体清除废物的必需品', 'food · 生活盲区', '肝脏、肾脏、肺等器官本身就在持续参与代谢和排泄。', '“detox”营销常把正常代谢过程重新包装成消费产品。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB026', 'concept_blindspot_LB026', 'claim_blindspot_LB026', 'blindspot', 'blindspot', '运动饮料不是日常喝水的默认升级版', 'food · 生活盲区', '多数普通日常活动并不需要额外的糖和电解质饮料。', '运动饮料的配方就是为了特定运动情境设计的。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB027', 'concept_blindspot_LB027', 'claim_blindspot_LB027', 'blindspot', 'blindspot', '“喝开水”主要解决的是饮水与部分微生物风险，不是获得神奇养生效果', 'food · 生活盲区', '煮沸能显著降低许多微生物风险，但不会让所有水质问题自动消失。', '热处理对微生物有效，但不同污染物的性质不同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB028', 'concept_blindspot_LB028', 'claim_blindspot_LB028', 'blindspot', 'blindspot', '“每天必须喝8杯水”不是普遍硬性指标', 'food · 生活盲区', '健康成年人水分需求受体型、饮食、气候、活动和疾病等影响。', '人体会通过口渴、肾脏和其他机制调节水分平衡。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB029', 'concept_blindspot_LB029', 'claim_blindspot_LB029', 'blindspot', 'blindspot', '咖啡和茶中的水也算进入总液体摄入', 'food · 生活盲区', '含咖啡因饮料仍能提供水分，虽然咖啡因可能影响睡眠等。', '饮水量与咖啡因效应是两个维度。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB030', 'concept_blindspot_LB030', 'claim_blindspot_LB030', 'blindspot', 'blindspot', '盐的“颜色、产地、矿物名头”不等于健康等级', 'food · 生活盲区', '盐的核心成分仍主要与钠摄入相关，颜色或产地不能替代总钠量判断。', '营销强调稀有来源，但健康效果需要看真正摄入了多少钠。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB031', 'concept_blindspot_LB031', 'claim_blindspot_LB031', 'blindspot', 'blindspot', '出汗多不等于减脂更多', 'health · 生活盲区', '汗水主要反映散热和体液丢失，不是脂肪“融化”的直接指标。', '脂肪减少需要长期能量平衡变化，汗量受温度、湿度、体能等多因素影响。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB032', 'concept_blindspot_LB032', 'claim_blindspot_LB032', 'blindspot', 'blindspot', '酸痛不是“练得有效”的唯一证明', 'health · 生活盲区', '延迟性肌肉酸痛可以出现在不熟悉或高负荷运动后，但没有酸痛也可能训练有效。', '酸痛更多反映组织应激与恢复过程，不是收益本身。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB033', 'concept_blindspot_LB033', 'claim_blindspot_LB033', 'blindspot', 'blindspot', '减脂不能靠只练某一块把那一块的脂肪“点掉”', 'health · 生活盲区', '局部训练会增强对应肌肉，但脂肪动员不是简单按训练部位精准分配。', '肌肉和脂肪是不同组织，训练刺激不能把脂肪精准切成区域清除。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB034', 'concept_blindspot_LB034', 'claim_blindspot_LB034', 'blindspot', 'blindspot', '发烧是症状，不是单独一种疾病', 'health · 生活盲区', '发烧是身体对感染、炎症等多种情况作出反应时可能出现的体温升高。', '发热是机体调节体温的结果，病因可能很多。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB035', 'concept_blindspot_LB035', 'claim_blindspot_LB035', 'blindspot', 'blindspot', '抗生素不是“消炎药万能版”', 'health · 生活盲区', '抗生素针对特定细菌感染，不治疗普通感冒和流感等病毒感染。', '细菌和病毒的生物学结构不同，抗菌药物靶点也不同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB036', 'concept_blindspot_LB036', 'claim_blindspot_LB036', 'blindspot', 'blindspot', '感冒流鼻涕变黄或绿，不自动等于“细菌感染”', 'health · 生活盲区', '鼻涕颜色可以随免疫细胞、黏液浓度和病程变化，并不能单凭颜色诊断细菌感染。', '症状颜色不是单独可靠的病原学检测。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB037', 'concept_blindspot_LB037', 'claim_blindspot_LB037', 'blindspot', 'blindspot', '维生素C不是普通感冒的万能预防药', 'health · 生活盲区', '对大多数人，规律补充维生素C并不能明显减少感冒发生率，可能只有小幅影响。', '普通感冒由很多病毒引起，不是简单的“缺维C”。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB038', 'concept_blindspot_LB038', 'claim_blindspot_LB038', 'blindspot', 'blindspot', '酒精可能让人更快困，却可能让后半夜睡得更差', 'health · 生活盲区', '酒精有镇静效应，但会使睡眠更碎片化、更浅。', '“更快睡着”和“睡得好”不是同一指标。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB039', 'concept_blindspot_LB039', 'claim_blindspot_LB039', 'blindspot', 'blindspot', '咖啡因的作用可能持续到你以为已经过了很久', 'health · 生活盲区', '足量咖啡因在睡前数小时仍可能影响入睡和睡眠时间。', '咖啡因的代谢不是“喝完几小时就清零”。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB040', 'concept_blindspot_LB040', 'claim_blindspot_LB040', 'blindspot', 'blindspot', '“睡够8小时”不是所有成年人完全相同的硬指标', 'health · 生活盲区', '睡眠需求存在个体差异，而且年龄也会影响需求。', '人体不是一台只接受一个固定睡眠时长的机器。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB041', 'concept_blindspot_LB041', 'claim_blindspot_LB041', 'blindspot', 'blindspot', '鼻炎和普通感冒不是一回事', 'health · 生活盲区', '过敏性鼻炎等可以造成鼻塞、流涕、打喷嚏，但并非都是感染。', '症状相似不代表病因相同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB042', 'concept_blindspot_LB042', 'claim_blindspot_LB042', 'blindspot', 'blindspot', '咳嗽本身是一个防御性反射', 'health · 生活盲区', '咳嗽可以帮助清除气道分泌物和异物。', '咳嗽反射能把分泌物、颗粒和刺激物从气道向外移动。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB043', 'concept_blindspot_LB043', 'claim_blindspot_LB043', 'blindspot', 'blindspot', '“天然”药物也可能有副作用', 'health · 生活盲区', '天然来源并不等于生物学上温和或没有相互作用。', '“天然”描述来源，不描述风险等级。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB044', 'concept_blindspot_LB044', 'claim_blindspot_LB044', 'blindspot', 'blindspot', '“出汗排毒”把正常生理功能说复杂了', 'health · 生活盲区', '汗液的主要作用是散热，人体代谢废物主要由肝、肾等系统处理。', '汗腺的主要生理任务是体温调节。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB045', 'concept_blindspot_LB045', 'claim_blindspot_LB045', 'blindspot', 'blindspot', '晒黑不是“健康小麦色”的代价可忽略版本', 'health · 生活盲区', '皮肤变黑是对紫外线暴露的一种反应，并不意味着皮肤得到了无害的“健康加分”。', '黑色素增加是皮肤防御反应之一，而不是免疫护盾。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB046', 'concept_blindspot_LB046', 'claim_blindspot_LB046', 'blindspot', 'blindspot', '防晒霜不是“涂一次就一天不管”', 'health · 生活盲区', '防晒效果受涂抹量、出汗、游泳和摩擦等影响。', '防晒剂会因为摩擦、汗水和时间而减少有效覆盖。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB047', 'concept_blindspot_LB047', 'claim_blindspot_LB047', 'blindspot', 'blindspot', '防晒霜不会让你完全隔绝紫外线', 'health · 生活盲区', '防晒产品降低一定范围的紫外线暴露，但不是隐身罩。', '不同产品和使用方式都会影响实际防护。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB048', 'concept_blindspot_LB048', 'claim_blindspot_LB048', 'blindspot', 'blindspot', '止汗剂和除臭剂不是同一种东西', 'health · 生活盲区', '除臭产品主要处理气味，止汗剂则通过特定机制减少汗液分泌。', '气味和汗液本身是两个问题：细菌分解汗液可能产生气味。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB049', 'concept_blindspot_LB049', 'claim_blindspot_LB049', 'blindspot', 'blindspot', '剃毛不会让毛囊突然生产“更粗的毛”', 'health · 生活盲区', '剃毛只是从皮肤表面切断毛干，不会把毛囊改造成更粗的毛囊。', '改变的是毛干形态和视觉，不是毛囊数量。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB050', 'concept_blindspot_LB050', 'claim_blindspot_LB050', 'blindspot', 'blindspot', '头发和指甲并不会在死亡后继续生长', 'health · 生活盲区', '死亡后组织代谢停止；皮肤脱水收缩会让毛发和指甲显得更长。', '皮肤失水后变紧，毛发和指甲暴露出的长度看起来增加。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB051', 'concept_blindspot_LB051', 'claim_blindspot_LB051', 'blindspot', 'blindspot', '人不是“只用了10%的大脑”', 'health · 生活盲区', '“10%大脑”是长期流传的都市传说，不符合现代神经科学。', '脑组织代谢成本高，长期维持大量“完全不用的”神经组织并不符合生理现实。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB052', 'concept_blindspot_LB052', 'claim_blindspot_LB052', 'blindspot', 'blindspot', '“左脑人/右脑人”不是可靠的人格分类', 'health · 生活盲区', '大脑两半球确实存在功能偏侧化，但复杂思维并不是一半脑只负责理性、另一半只负责艺术。', '功能专门化与“人格分成两类”是不同概念。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB053', 'concept_blindspot_LB053', 'claim_blindspot_LB053', 'blindspot', 'blindspot', '“冷”本身不是普通感冒的病原体', 'health · 生活盲区', '普通感冒通常由病毒感染造成。', '症状触发条件与真正病原体不是同一个层面。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB054', 'concept_blindspot_LB054', 'claim_blindspot_LB054', 'blindspot', 'blindspot', '体温高不一定是“体内有毒素”', 'health · 生活盲区', '发热有很多医学原因，包括感染、炎症、药物等。', '人体调节体温的机制与“排毒”概念不是同一套生理过程。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB055', 'concept_blindspot_LB055', 'claim_blindspot_LB055', 'blindspot', 'blindspot', '“吃药配牛奶”不是所有药都可以随便搭', 'health · 生活盲区', '部分药物会受食物、饮料或矿物质影响吸收。', '药物需要在特定化学环境中溶解、吸收并发挥作用。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB056', 'concept_blindspot_LB056', 'claim_blindspot_LB056', 'blindspot', 'blindspot', '药品不是“药效越强越好”', 'health · 生活盲区', '用药的目标是以合适剂量获得收益，同时把副作用控制在可接受范围。', '药物有治疗窗、代谢和毒副作用边界。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB057', 'concept_blindspot_LB057', 'claim_blindspot_LB057', 'blindspot', 'blindspot', '保健品和药物不是一个监管概念', 'health · 生活盲区', '保健食品/膳食补充剂与治疗疾病的药物在法规定位和证据要求上不同。', '“含有活性成分”不等于“临床有效治疗疾病”。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB058', 'concept_blindspot_LB058', 'claim_blindspot_LB058', 'blindspot', 'blindspot', '抗生素疗程不是自己觉得好多了就随意停', 'health · 生活盲区', '是否停药、换药取决于具体药物、感染类型和医生方案，不能用“感觉好多了”单独决定。', '抗菌治疗需要针对特定感染；自行短停、换药和重复使用都会增加不必要的风险。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB059', 'concept_blindspot_LB059', 'claim_blindspot_LB059', 'blindspot', 'blindspot', '睡前酒精和“助眠”不是一回事', 'health · 生活盲区', '酒精可能缩短入睡时间，但会让睡眠更碎、更浅。', '镇静作用和正常睡眠结构不同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB060', 'concept_blindspot_LB060', 'claim_blindspot_LB060', 'blindspot', 'blindspot', '短时间午睡不等于“偷懒”', 'health · 生活盲区', '适当的短暂午睡可以提高警觉性，但太长或太晚可能影响夜间睡眠。', '睡眠压力与昼夜节律共同影响睡眠。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB061', 'concept_blindspot_LB061', 'claim_blindspot_LB061', 'blindspot', 'blindspot', '清洁、消毒、灭菌不是三个同义词', 'home · 生活盲区', '清洁主要去污；消毒降低病原体；灭菌追求更彻底地消除微生物。', '表面有污垢时可能削弱某些消毒产品效果。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB062', 'concept_blindspot_LB062', 'claim_blindspot_LB062', 'blindspot', 'blindspot', '消毒剂不是“喷一下就立刻生效”', 'home · 生活盲区', '很多消毒产品需要保持表面湿润达到规定接触时间。', '杀灭微生物需要足够的化学作用时间。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB063', 'concept_blindspot_LB063', 'claim_blindspot_LB063', 'blindspot', 'blindspot', '漂白剂和其他清洁剂不要混用', 'home · 生活盲区', '不同化学品混合可能产生刺激性或有毒气体。', '化学反应可能生成挥发性危险产物。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB064', 'concept_blindspot_LB064', 'claim_blindspot_LB064', 'blindspot', 'blindspot', '肥皂并不是“必须杀死细菌”才算洗干净', 'home · 生活盲区', '肥皂和水通过乳化、包裹和冲洗把污物、微生物和化学物质从手上带走。', '肥皂分子能形成胶束，把油脂和颗粒包裹并随水冲走。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB065', 'concept_blindspot_LB065', 'claim_blindspot_LB065', 'blindspot', 'blindspot', '洗手的“20秒”重点不是神奇秒数，而是覆盖和充分摩擦', 'home · 生活盲区', '20秒是容易执行的公共卫生建议，但真正重要的是把手掌、手背、指缝、指甲周围等部位都洗到。', '短时间往往意味着遗漏区域。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB066', 'concept_blindspot_LB066', 'claim_blindspot_LB066', 'blindspot', 'blindspot', '空气净化器不能解决所有空气问题', 'home · 生活盲区', 'HEPA 类过滤器主要处理颗粒物，不等于能解决所有气体、异味、湿度和霉菌来源。', '过滤器的物理机制决定了它擅长抓颗粒，不一定擅长处理气体。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB067', 'concept_blindspot_LB067', 'claim_blindspot_LB067', 'blindspot', 'blindspot', 'HEPA 主要擅长拦截颗粒，不是“吸走一切化学气体”', 'home · 生活盲区', 'HEPA 是机械式颗粒过滤技术。', '滤网通过纤维结构拦截颗粒，对分子级气体并不是同一个机制。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB068', 'concept_blindspot_LB068', 'claim_blindspot_LB068', 'blindspot', 'blindspot', '臭氧空气净化器不是“越刺激鼻子越有效”', 'home · 生活盲区', '臭氧本身是肺部刺激物，EPA 不建议在有人占用的空间使用会主动产生臭氧的空气净化设备。', '臭氧本身具有反应性，可能刺激呼吸道并产生副产物。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB069', 'concept_blindspot_LB069', 'claim_blindspot_LB069', 'blindspot', 'blindspot', '除湿机不是“制冷机的缩水版”', 'home · 生活盲区', '除湿机通过冷凝等机制降低空气中的水分，通常同时向房间释放热量。', '除湿器把空气中的水蒸气凝结并收集，同时设备自身耗电会产生热。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB070', 'concept_blindspot_LB070', 'claim_blindspot_LB070', 'blindspot', 'blindspot', '电风扇通常不是在“制造冷空气”', 'home · 生活盲区', '风扇主要通过空气流动加快皮肤表面汗液和热量交换，让人觉得更凉。', '蒸发和对流加快了人体散热。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB071', 'concept_blindspot_LB071', 'claim_blindspot_LB071', 'blindspot', 'blindspot', '空调不是“凭空制造冷气”', 'home · 生活盲区', '家用空调通常通过制冷循环把室内热量搬到室外。', '制冷剂在不同压力下循环吸热、放热。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB072', 'concept_blindspot_LB072', 'claim_blindspot_LB072', 'blindspot', 'blindspot', '冰箱也不是“制造冷”', 'home · 生活盲区', '冰箱通过制冷循环把箱内热量搬出去。', '热力学过程把热从低温空间转移到高温环境。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB073', 'concept_blindspot_LB073', 'claim_blindspot_LB073', 'blindspot', 'blindspot', '冰箱背后为什么会热？因为热被排到那里', 'home · 生活盲区', '制冷系统吸走食物空间的热量，也需要把这些热量和压缩机产生的热排出去。', '能量不会凭空消失，制冷只是重新分配热量。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB074', 'concept_blindspot_LB074', 'claim_blindspot_LB074', 'blindspot', 'blindspot', '电磁炉不是“玻璃板自己发热煮锅”', 'home · 生活盲区', '电磁炉利用交变磁场在兼容锅具中产生感应电流并发热。', '电磁感应把电能以电流形式耦合到锅具。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB075', 'concept_blindspot_LB075', 'claim_blindspot_LB075', 'blindspot', 'blindspot', '微波炉不是“从里面把食物凭空煮熟”', 'home · 生活盲区', '微波炉通过电磁波与食物中的极性分子等相互作用产生加热。', '电磁场使分子运动和介电损耗转化为热。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB076', 'concept_blindspot_LB076', 'claim_blindspot_LB076', 'blindspot', 'blindspot', '微波炉不会让食物“变成放射性物质”', 'home · 生活盲区', '家用微波炉使用的是非电离辐射；正常使用不会把食物变成放射性物质。', '“辐射”是一个很大的物理分类，是否能电离物质取决于能量。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB077', 'concept_blindspot_LB077', 'claim_blindspot_LB077', 'blindspot', 'blindspot', '微波炉门上的金属网不是装饰', 'home · 生活盲区', '门上的金属网孔尺寸和电磁波波长关系决定其能抑制微波泄漏，同时允许可见光进入。', '导体表面对特定电磁波频段具有屏蔽作用。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB078', 'concept_blindspot_LB078', 'claim_blindspot_LB078', 'blindspot', 'blindspot', '电水壶会自动断电是因为温控检测到了沸腾相关的热状态', 'home · 生活盲区', '很多电水壶通过温控器和蒸汽/温度变化触发断电。', '温度达到设定区间后，开关机构状态改变。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB079', 'concept_blindspot_LB079', 'claim_blindspot_LB079', 'blindspot', 'blindspot', '烟雾报警器检测的不是“火焰”，而是烟粒子等特征', 'home · 生活盲区', '家用烟雾报警器常通过光电或离子化等方式检测火灾烟雾特征。', '不同传感器对烟粒子的物理性质进行检测。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB080', 'concept_blindspot_LB080', 'claim_blindspot_LB080', 'blindspot', 'blindspot', '一氧化碳报警器和烟雾报警器不是一回事', 'home · 生活盲区', '烟雾报警器主要针对烟雾，CO 报警器针对一氧化碳。', 'CO 是一种无色、无味的有毒气体，不一定伴随明显烟雾。
