INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB082', 'concept_blindspot_LB082', 'claim_blindspot_LB082', 'blindspot', 'blindspot', '燃气火焰和CO不是一回事', 'home · 生活盲区', '天然气泄漏与燃烧产生CO是两个不同风险；正常完全燃烧主要形成二氧化碳和水，而不完全燃烧可能产生CO。', '燃料的化学燃烧状态决定产物。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB083', 'concept_blindspot_LB083', 'claim_blindspot_LB083', 'blindspot', 'blindspot', '停电时发电机最危险的不是“没电”，而是CO和火灾风险', 'home · 生活盲区', '燃油发电机会产生大量CO，不能在室内、车库等封闭空间使用。', '发动机燃烧燃料会产生CO；半封闭空间仍可能快速积累。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB084', 'concept_blindspot_LB084', 'claim_blindspot_LB084', 'blindspot', 'blindspot', '电源插排不是“插孔越多，功率就越大”', 'home · 生活盲区', '插排只是把一个供电点分出多个接口，不会凭空增加电网可用功率。', '并联增加的是连接点，不是电源容量。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB085', 'concept_blindspot_LB085', 'claim_blindspot_LB085', 'blindspot', 'blindspot', '断路器跳闸不是“家里电坏了”，而是在保护线路', 'home · 生活盲区', '断路器在检测到过载或短路等异常电流条件时断开电路。', '电流过大时线路发热增加，保护装置会切断供电。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB086', 'concept_blindspot_LB086', 'claim_blindspot_LB086', 'blindspot', 'blindspot', '漏电保护和过载保护不是同一种保护', 'home · 生活盲区', 'RCD/GFCI 一类装置关注电流是否通过异常路径泄漏，过载保护则主要处理电流过大。', '电气安全是多层保护。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB087', 'concept_blindspot_LB087', 'claim_blindspot_LB087', 'blindspot', 'blindspot', 'LED灯省电的关键不是“更亮”，而是更高效地产生光', 'home · 生活盲区', 'LED 将更多输入电能转成可用光，通常比传统白炽灯更高效。', '白炽灯大量能量最终以热形式散失。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB088', 'concept_blindspot_LB088', 'claim_blindspot_LB088', 'blindspot', 'blindspot', '白炽灯很热，是因为大量能量最终变成了热', 'home · 生活盲区', '白炽灯依靠高温灯丝发光，大量能量以热形式散失。', '热辐射与可见光同时产生，但光只占能量的一部分。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB089', 'concept_blindspot_LB089', 'claim_blindspot_LB089', 'blindspot', 'blindspot', '加湿器不是越湿越好', 'home · 生活盲区', '湿度过高会促进霉菌等问题；不同环境应控制在适合的范围。', '过高湿度改变材料表面水分条件，为霉菌提供机会。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB090', 'concept_blindspot_LB090', 'claim_blindspot_LB090', 'blindspot', 'blindspot', '霉味解决不了，优先找水分来源', 'home · 生活盲区', '净化器或香氛可以掩盖气味，但不能消除导致霉菌生长的潮湿源。', '霉菌需要水分条件才能持续生长。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB091', 'concept_blindspot_LB091', 'claim_blindspot_LB091', 'blindspot', 'blindspot', 'Wi‑Fi不是互联网本身', 'technology · 生活盲区', 'Wi‑Fi 是设备接入局域网络的一种无线方式，互联网是更大的网络系统。', '设备、路由器、宽带链路和互联网服务是不同层次。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB092', 'concept_blindspot_LB092', 'claim_blindspot_LB092', 'blindspot', 'blindspot', '有信号不等于有互联网', 'technology · 生活盲区', '手机信号可能代表连接到移动网络，不代表当前数据业务一定可用。', '“无线电连接存在”与“应用层服务可用”是不同层级。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB093', 'concept_blindspot_LB093', 'claim_blindspot_LB093', 'blindspot', 'blindspot', 'GPS定位时，手机主要是“听”卫星，不是向卫星发送位置', 'technology · 生活盲区', '传统GPS定位的核心是接收卫星发来的时间和轨道信息，再计算位置。', '定位通过测量信号传播时间差等信息计算距离。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB094', 'concept_blindspot_LB094', 'claim_blindspot_LB094', 'blindspot', 'blindspot', 'GPS之所以能算位置，关键之一是时间测得非常准', 'technology · 生活盲区', '接收机通过多个卫星信号的传播时间差估计距离，从而求位置。', '电磁波传播速度已知，传播时间就能转换成距离信息。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB095', 'concept_blindspot_LB095', 'claim_blindspot_LB095', 'blindspot', 'blindspot', '二维码不是加密', 'technology · 生活盲区', 'QR code主要是一种把数据编码成图形的方式，不天然意味着数据被加密。', '编码解决“如何表示数据”，加密解决“如何让未授权者读不懂”。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB096', 'concept_blindspot_LB096', 'claim_blindspot_LB096', 'blindspot', 'blindspot', 'HTTPS说明传输链路加密，不等于网站一定可信', 'technology · 生活盲区', 'HTTPS能帮助保护浏览器与网站之间的传输内容，但骗子也可以拥有HTTPS网站。', '加密连接与网站是否诚实是两个问题。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB097', 'concept_blindspot_LB097', 'claim_blindspot_LB097', 'blindspot', 'blindspot', '无痕/隐身模式不是“匿名上网”', 'technology · 生活盲区', '隐私模式主要减少本机浏览记录、Cookie 等痕迹，不会让网站、网络运营者或你登录的服务看不见你。', '本地历史记录和网络可见性不是一回事。
