INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB100', 'concept_blindspot_LB100', 'claim_blindspot_LB100', 'blindspot', 'blindspot', '密码越复杂越重要，但“每个网站都不同”同样重要', 'technology · 生活盲区', '密码重复会造成“一处泄露、多处被撞库”。', '攻击者常利用已泄露的邮箱+密码组合去尝试其他网站。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB101', 'concept_blindspot_LB101', 'claim_blindspot_LB101', 'blindspot', 'blindspot', '多因素认证的第二步不是“多余步骤”', 'technology · 生活盲区', 'MFA 在密码泄露后仍可能提供额外防护。', '攻击者即使拿到密码，也未必拿得到第二因素。
