INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB103', 'concept_blindspot_LB103', 'claim_blindspot_LB103', 'blindspot', 'blindspot', '手机快充不是“电压越高越快”', 'technology · 生活盲区', '快充通常由充电器、手机和线材协商允许的电压、电流和功率。', '充电系统需要双方协商和保护。
