INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB108', 'concept_blindspot_LB108', 'claim_blindspot_LB108', 'blindspot', 'blindspot', '数码变焦和光学变焦不是一回事', 'technology · 生活盲区', '光学变焦通过镜头改变成像倍率，数码变焦主要是裁切/重采样。', '图像处理可以放大像素，但不能完全替代光学分辨率。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB109', 'concept_blindspot_LB109', 'claim_blindspot_LB109', 'blindspot', 'blindspot', '电子墨水屏和普通LCD不是同一种显示原理', 'technology · 生活盲区', '电子墨水通常利用带电微粒在电场作用下重新排列形成黑白图像，刷新方式与LCD不同。', '显示材料和成像机制不同。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB110', 'concept_blindspot_LB110', 'claim_blindspot_LB110', 'blindspot', 'blindspot', '电池“100%”不是固定不变的电量单位', 'technology · 生活盲区', '电池百分比是管理系统对剩余能量和状态的估算，不是直接测量出的“百分之一格”。', '电池电压与剩余可用容量并不是线性关系。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB111', 'concept_blindspot_LB111', 'claim_blindspot_LB111', 'blindspot', 'blindspot', '电动汽车减速时可以把部分动能变回电能', 'technology · 生活盲区', '再生制动通过电机反向工作，把部分车辆动能转换成电能储回电池。', '电机既能消耗电能产生运动，也能利用车轮带动发电。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB112', 'concept_blindspot_LB112', 'claim_blindspot_LB112', 'blindspot', 'blindspot', '热泵和空调在物理上是同一类技术', 'technology · 生活盲区', '热泵通过制冷循环搬运热量；切换工作方向可以实现制冷或供暖。', '热量可以从低温侧被搬到高温侧，关键是机械做功。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB113', 'concept_blindspot_LB113', 'claim_blindspot_LB113', 'blindspot', 'blindspot', '冰箱把热量搬出去时也在“制造热”', 'technology · 生活盲区', '压缩机耗电，系统不只排出冰箱内部吸收的热，还会把输入电能最终转成热。', '能量守恒要求热量与输入功最终被排出。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB114', 'concept_blindspot_LB114', 'claim_blindspot_LB114', 'blindspot', 'blindspot', '电梯不是靠钢丝绳单独“硬拉”整部电梯', 'technology · 生活盲区', '现代曳引电梯通过电机、曳引轮、钢丝绳与对重等系统平衡负载。', '平衡系统可以显著减少所需驱动力。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB115', 'concept_blindspot_LB115', 'claim_blindspot_LB115', 'blindspot', 'blindspot', '抽水马桶不是“把水直接冲进地下”', 'technology · 生活盲区', '冲厕时水流带动污物进入排水系统，存水弯等结构帮助隔绝下水道气体。', '液柱形成水封，同时利用虹吸和流体运动排走污物。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB116', 'concept_blindspot_LB116', 'claim_blindspot_LB116', 'blindspot', 'blindspot', '洗衣机不是“用水把衣服泡干净”那么简单', 'technology · 生活盲区', '洗衣机综合利用机械搅动、洗涤剂、温度和时间把污物从纤维上移除。', '污渍需要被润湿、乳化、分散，再随水带走。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB117', 'concept_blindspot_LB117', 'claim_blindspot_LB117', 'blindspot', 'blindspot', '洗碗机不是“把盘子泡一晚上”', 'technology · 生活盲区', '喷淋、高温、水压、洗涤剂和程序控制共同完成清洁。', '喷射水流提供机械能，洗涤剂降低油污与表面的结合。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB118', 'concept_blindspot_LB118', 'claim_blindspot_LB118', 'blindspot', 'blindspot', '吸尘器主要是制造压差并让空气带走颗粒', 'technology · 生活盲区', '吸尘器用风机制造气流，让空气携带灰尘进入过滤系统。', '空气从高压向低压运动形成流量，灰尘随气流进入集尘结构。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB119', 'concept_blindspot_LB119', 'claim_blindspot_LB119', 'blindspot', 'blindspot', '滚筒洗衣机不一定要装满才最省', 'technology · 生活盲区', '不同洗衣机的能耗和用水逻辑不同，半满洗并不是简单等于“浪费一半资源”。', '现代机器会根据程序和负载调整部分用水、时间或能耗。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB120', 'concept_blindspot_LB120', 'claim_blindspot_LB120', 'blindspot', 'blindspot', '路由器不是“有Wi‑Fi就一定能上网”的万能盒子', 'technology · 生活盲区', '路由器负责局域网络、地址分配和流量转发等；互联网连接还依赖上游线路和服务商。', '网络由多个层级组成：设备、局域网、路由、宽带接入、DNS、服务器。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB121', 'concept_blindspot_LB121', 'claim_blindspot_LB121', 'blindspot', 'blindspot', '免费试用不等于免费', 'consumer · 生活盲区', '很多试用会在到期后自动续费，如果不取消就开始收费。', '商业模式可能把“试用”设计成自动续费入口。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB122', 'concept_blindspot_LB122', 'claim_blindspot_LB122', 'blindspot', 'blindspot', '自动续费最容易被忽略的是“什么时候取消”', 'consumer · 生活盲区', '真正的成本可能不在第一次付款，而在用户忘记取消后的连续扣款。', '负选项订阅把“不操作”设计成继续付费。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB123', 'concept_blindspot_LB123', 'claim_blindspot_LB123', 'blindspot', 'blindspot', '网页上有小锁不等于卖家可信', 'consumer · 生活盲区', 'HTTPS保护浏览器到网站的加密连接，但诈骗网站也可以使用HTTPS。', '加密连接解决的是窃听风险的一部分，不是商家诚信。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB124', 'concept_blindspot_LB124', 'claim_blindspot_LB124', 'blindspot', 'blindspot', '五星评价不是“产品质量的科学测量”', 'consumer · 生活盲区', '评论可能被激励、刷量、操纵或选择性展示。', '评分平台的数据生成机制本身就可能有偏差。
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB125', 'concept_blindspot_LB125', 'claim_blindspot_LB125', 'blindspot', 'blindspot', '促销价不等于真实便宜', 'consumer · 生活盲区', '比较商品时应该看实际成交价、单位价格和总成本，而不是只看“原价划掉多少”。', '营销展示的是相对价格，消费者真正承担的是总支付。
