INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB127', 'concept_blindspot_LB127', 'claim_blindspot_LB127', 'blindspot', 'blindspot', '延长保修不是“免费延长原厂保障”那么简单', 'consumer · 生活盲区', '延保是额外合同，覆盖范围、免赔、人工、零件、期限都可能不同。', '合同可以对风险边界作不同定义。
