INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB129', 'concept_blindspot_LB129', 'claim_blindspot_LB129', 'blindspot', 'blindspot', '“需要输入银行卡才免费”是强烈的订阅警报', 'consumer · 生活盲区', '大量免费试用通过绑定支付方式实现自动续费。', '商家需要付款凭据才能在试用结束后自动收费。
