INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB133', 'concept_blindspot_LB133', 'claim_blindspot_LB133', 'blindspot', 'blindspot', '年化利率不是“每个月只收一次利息”', 'money · 生活盲区', '很多信用产品使用周期利率计算，APR是用于比较融资成本的重要指标。', '复利和费用会让简单乘法失真。
