INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_blindspot_LB142', 'concept_blindspot_LB142', 'claim_blindspot_LB142', 'blindspot', 'blindspot', '巡航控制不会自动替你承担驾驶责任', 'transport · 生活盲区', '普通定速巡航和各种驾驶辅助系统都有不同能力边界，驾驶员仍需监控道路。', '传感器和算法都存在设计范围和失效模式。
