INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0171', 'concept_b1000_NEWC0001', 'claim_b1000_NEWCL0001', 'blindspot', 'blindspot', '为什么棉织物容易吸汗，却不一定干得快？', '衣物与纺织 · 机制解读', '棉纤维亲水，能吸收水分；吸进去的水还需要蒸发，干燥速度也受织物厚度、织法、温度和气流影响。', '一般材料原理；具体性能受产品结构、配比和护理方式影响。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '棉纤维亲水，能吸收水分；吸进去的水还需要蒸发，干燥速度也受织物厚度、织法、温度和气流影响。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“为什么棉织物容易吸汗，却不一定干得快”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解面料性能、衣物护理和材质标签，减少只凭营销词或触感判断。', '一般材料原理；具体性能受产品结构、配比和护理方式影响。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'low', 'why', 'published', '{"生活盲区","衣物与纺织","衣物","纺织","材料科学","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
