INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0213', 'concept_b1000_NEWC0022', 'claim_b1000_NEWCL0043', 'blindspot', 'blindspot', '糖为什么会焦糖化？', '烹饪与食品科学 · 机制解读', '糖在足够高的温度下会发生分解和重组，形成颜色与焦糖风味；具体温度范围随糖种和条件而变。', '食品科学原理会随配方、温度、时间与设备而变化，不应把单一实验条件泛化到所有菜肴。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '糖在足够高的温度下会发生分解和重组，形成颜色与焦糖风味；具体温度范围随糖种和条件而变。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“糖为什么会焦糖化”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解烹饪中的物理、化学和食品安全机制，改善判断与操作。', '食品科学原理会随配方、温度、时间与设备而变化，不应把单一实验条件泛化到所有菜肴。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'low', 'why', 'published', '{"生活盲区","烹饪与食品科学","烹饪","食品科学","化学","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
