INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0291', 'concept_b1000_NEWC0061', 'claim_b1000_NEWCL0121', 'blindspot', 'blindspot', '化验单上的参考区间为什么不是“健康与生病的绝对分界线”？', '医疗检查与医疗体系 · 机制解读', '参考区间通常基于特定人群和统计方法建立，单个结果需要结合症状、病史、采样条件和其他检查解释。', '医疗流程、筛查建议和检查阈值可能因国家、地区、年龄和个体风险而不同。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '参考区间通常基于特定人群和统计方法建立，单个结果需要结合症状、病史、采样条件和其他检查解释。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“化验单上的参考区间为什么不是“健康与生病的绝对分界线””有助于把可观察现象、背后机制与适用条件分开判断。帮助理解检查、筛查和医疗流程，减少把单项结果或流程名称过度解读。', '医疗流程、筛查建议和检查阈值可能因国家、地区、年龄和个体风险而不同。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'medium', 'why', 'published', '{"生活盲区","医疗检查与医疗体系","医疗扫盲","检查","健康服务","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
