INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0371', 'concept_b1000_NEWC0101', 'claim_b1000_NEWCL0201', 'blindspot', 'blindspot', '水泥、混凝土和砂浆为什么不是同一种东西？', '居住与建筑材料 · 机制解读', '水泥是胶凝材料，混凝土通常由胶凝材料、骨料和水等组成，砂浆一般用于砌筑、抹面或粘结，骨料粒径和用途不同。', '建筑做法受气候、规范、结构设计和当地施工标准影响；涉及承重、燃气、电气或防水时请找合格专业人员。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '水泥是胶凝材料，混凝土通常由胶凝材料、骨料和水等组成，砂浆一般用于砌筑、抹面或粘结，骨料粒径和用途不同。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“水泥、混凝土和砂浆为什么不是同一种东西”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解居住环境、建筑材料和住宅舒适度，做更合理的维护与选购判断。', '建筑做法受气候、规范、结构设计和当地施工标准影响；涉及承重、燃气、电气或防水时请找合格专业人员。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'low', 'why', 'published', '{"生活盲区","居住与建筑材料","居住","建筑","材料原理","水系统","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
