INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0555', 'concept_b1000_NEWC0193', 'claim_b1000_NEWCL0385', 'blindspot', 'blindspot', '隐私政策为什么不是“用户完全放弃隐私”的同义词？', '法律与公民常识 · 机制解读', '隐私政策通常说明服务如何收集、使用、共享和保留数据，但权利与义务仍受法律和实际做法约束。', '法律规则因国家、地区和时间变化；本组用于理解概念，不可直接替代当地法律建议。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '隐私政策通常说明服务如何收集、使用、共享和保留数据，但权利与义务仍受法律和实际做法约束。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“隐私政策为什么不是“用户完全放弃隐私”的同义词”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解证据、权利和公共制度的基本概念；具体法律问题需核对所在地现行规则。', '法律规则因国家、地区和时间变化；本组用于理解概念，不可直接替代当地法律建议。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'medium', 'why', 'published', '{"生活盲区","法律与公民常识","法律扫盲","公民常识","制度","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
