INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0771', 'concept_b1000_NEWC0301', 'claim_b1000_NEWCL0601', 'blindspot', 'blindspot', '平均数和中位数为什么可能讲出不同的收入故事？', '统计与数据素养 · 机制解读', '平均数会受到极高或极低值影响；中位数表示排序后居中的位置，对极端值通常更稳健。', '统计示例为理解概念之用；具体结论应查看原始数据、定义、采样和研究设计。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '平均数会受到极高或极低值影响；中位数表示排序后居中的位置，对极端值通常更稳健。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“平均数和中位数为什么可能讲出不同的收入故事”有助于把可观察现象、背后机制与适用条件分开判断。帮助读懂数字、图表和研究结论，避免把相关性、精确度或平均值误读。', '统计示例为理解概念之用；具体结论应查看原始数据、定义、采样和研究设计。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'low', 'why', 'published', '{"生活盲区","统计与数据素养","统计","数据素养","研究方法","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
