INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0938', 'concept_b1000_NEWC0384', 'claim_b1000_NEWCL0768', 'blindspot', 'blindspot', '为什么植入微芯片后仍要登记联系方式？', '动物与宠物 · 机制解读', '芯片号码需关联到可查找的数据库与最新联系方式，才能帮助联系主人。', '动物行为需结合物种、身体状态和环境；涉及毒物、咬伤或急症时应联系兽医或当地专业机构。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '芯片号码需关联到可查找的数据库与最新联系方式，才能帮助联系主人。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“为什么植入微芯片后仍要登记联系方式”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解动物行为与照护原则，及早识别需要专业兽医评估的情况。', '动物行为需结合物种、身体状态和环境；涉及毒物、咬伤或急症时应联系兽医或当地专业机构。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'medium', 'how', 'published', '{"生活盲区","动物与宠物","动物","宠物","行为识读","工作原理"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0939', 'concept_b1000_NEWC0385', 'claim_b1000_NEWCL0769', 'blindspot', 'blindspot', '室内猫为什么也可能需要兽医预防保健？', '动物与宠物 · 机制解读', '室内环境能减少部分风险，但不能完全排除疾病、寄生虫、意外逃出或接触其他动物的可能。', '动物行为需结合物种、身体状态和环境；涉及毒物、咬伤或急症时应联系兽医或当地专业机构。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '室内环境能减少部分风险，但不能完全排除疾病、寄生虫、意外逃出或接触其他动物的可能。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“室内猫为什么也可能需要兽医预防保健”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解动物行为与照护原则，及早识别需要专业兽医评估的情况。', '动物行为需结合物种、身体状态和环境；涉及毒物、咬伤或急症时应联系兽医或当地专业机构。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'medium', 'why', 'published', '{"生活盲区","动物与宠物","动物","宠物","行为识读","猫","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
