INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB0962', 'concept_b1000_NEWC0396', 'claim_b1000_NEWCL0792', 'blindspot', 'blindspot', '为什么定期称重比只看外观更可靠？', '动物与宠物 · 机制解读', '毛量、体型和视觉角度会遮挡变化；持续或明显变化应咨询兽医。', '动物行为需结合物种、身体状态和环境；涉及毒物、咬伤或急症时应联系兽医或当地专业机构。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '毛量、体型和视觉角度会遮挡变化；持续或明显变化应咨询兽医。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“为什么定期称重比只看外观更可靠”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解动物行为与照护原则，及早识别需要专业兽医评估的情况。', '动物行为需结合物种、身体状态和环境；涉及毒物、咬伤或急症时应联系兽医或当地专业机构。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'medium', 'how', 'published', '{"生活盲区","动物与宠物","动物","宠物","行为识读","工作原理"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
