INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB1011', 'concept_b1000_NEWC0421', 'claim_b1000_NEWCL0841', 'blindspot', 'blindspot', '发酵和腐败为什么不是完全相同的概念？', '饮食文化与食品史 · 机制解读', '发酵是微生物或酶在特定条件下改变食材的过程；腐败指品质恶化或可能出现安全问题，两者不能只看有没有微生物判断。', '饮食习俗具有地域、阶层与时代差异；历史起源常是渐变与多源交流，不宜轻易归功于单一发明者。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '发酵是微生物或酶在特定条件下改变食材的过程；腐败指品质恶化或可能出现安全问题，两者不能只看有没有微生物判断。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“发酵和腐败为什么不是完全相同的概念”有助于把可观察现象、背后机制与适用条件分开判断。帮助拓宽饮食文化和食品技术史视野，避免把复杂传统简化为单一来源。', '饮食习俗具有地域、阶层与时代差异；历史起源常是渐变与多源交流，不宜轻易归功于单一发明者。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'low', 'why', 'published', '{"生活盲区","饮食文化与食品史","饮食文化","食品史","文化地理","发酵","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
