INSERT INTO cards (id, concept_id, primary_claim_id, type, module, title, subtitle, one_line, body, misconception, reality, why, cost, benefit, notes, ratio, grade, difficulty, evidence_level, risk_level, angle, status, tags, published_at, updated_at) VALUES ('card_b1000_LB1131', 'concept_b1000_NEWC0481', 'claim_b1000_NEWCL0961', 'blindspot', 'blindspot', '单位为什么需要标准定义？', '语言、符号与日常标准 · 机制解读', '统一的单位定义让不同实验室、工厂和国家能比较测量结果，减少因单位含义不同造成的误差。', '术语和符号在不同专业、国家或产品中可能有特殊定义；涉及标准时核对正式文件。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', NULL, NULL, '统一的单位定义让不同实验室、工厂和国家能比较测量结果，减少因单位含义不同造成的误差。', '阅读约30–60秒；这条是认知型内容，不要求用户执行特定动作，也不需要额外消费。若据此采取实际行动，应再核对产品说明、当地规则与个人情况。', '理解“单位为什么需要标准定义”有助于把可观察现象、背后机制与适用条件分开判断。帮助理解日常符号、单位和标准，减少跨地区沟通与测量误解。', '术语和符号在不同专业、国家或产品中可能有特殊定义；涉及标准时核对正式文件。 本卡用于生活扫盲、拓宽知识与纠正过度概括，不替代针对具体个案的专业意见。', '极高', 'A', 1, 'uncertain', 'low', 'why', 'published', '{"生活盲区","语言、符号与日常标准","语言","符号","测量标准","计量单位","机制解释"}', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z') ON CONFLICT (id) DO NOTHING;
